/* jdlgsd: SIDE-LINE DIALOGUE SCENES (DATA ONLY). Built by dev/build/jdlgsd_build.py from every dev/handover/content/dlg/*.md;
   schema dev/handover/reports/sideline-dialogue.md «## SCHEMA»; validator dev/test/dlgs_validate.py; engine jdlgs.js. Do not hand-edit. */
const DLGS_DATA=[
{"id":"j68:j68c-day-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong yến, ánh đèn lồng rọi lên mái tóc {A}, một cây trâm bạch ngọc sáng lạnh cài nghiêng bên tóc mai."},{"who":"A","text":"{Goi} nhìn gì mà kỹ vậy? Trâm này là của nhà {xung} mang theo từ lâu rồi, chẳng lẽ {goi} còn nghi ngờ."},{"who":"me","text":"Chân trâm có một vết khắc rất nhỏ, đúng tên cung {xung}. Mấy tháng trước {goi} mượn, {xung} vẫn nhớ rõ từng nét."},{"who":"A","text":"Chuyện đã lâu, {goi} nhớ nhầm cũng là lẽ thường. Trâm đẹp thì ai đeo cũng được, cần gì phải so đo."},{"who":"me","text":"Đẹp thì có, nhưng đó là vật {xung} quý. Trước mắt bao người, {xung} phải nghĩ cho khéo xem nên nói ra sao."}]}},
{"id":"j68:j68c-day-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa đổ bất chợt, ngói cung ròng ròng nước, {A} co ro đứng dưới mái hiên, tà áo mỏng ướt sẫm vai."},{"who":"A","text":"{Goi}, {xung} chỉ định đi ngang qua thôi, không ngờ trời trở mưa nhanh như vậy."},{"who":"me","text":"Trời lạnh thế này, {goi} đứng đó là run cả người rồi. Áo choàng gấm xanh còn treo sau bình phong gian ngoài."},{"who":"A","text":"{Xung} không dám làm phiền, chỉ sợ ướt thêm thì sáng mai lại ho cả ngày."},{"who":"me","text":"Mưa này chưa tạnh sớm đâu. Để {xung} nghĩ xem nên giúp {goi} thế nào cho vừa lòng cả hai."}]}},
{"id":"j68:j68c-day-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngưỡng cửa cung, {A} chặn ngang lối đi, mắt dán vào hộp phấn men lam trên tay {M}."},{"who":"A","text":"Hộp phấn ấy ở đâu ra vậy? Dấu ấn Nội vụ phủ dưới đáy hộp, {xung} nhìn là biết ngay vật ngự ban."},{"who":"me","text":"{Goi} tinh mắt thật. Một hộp phấn nhỏ thôi, cớ sao lại khiến {goi} đứng giữa đường mà hỏi?"},{"who":"A","text":"Nhỏ thì nhỏ, mà vì sao {goi} có, còn {xung} chẳng có? Trong cung này, ai được ban gì đều không phải chuyện nhỏ."},{"who":"me","text":"Lời ấy nặng quá. {Xung} hiểu nỗi lòng {goi}, nên trả lời thế nào cho phải đạo thì cần nghĩ một chút."}]}},
{"id":"j68:j68c-day-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi sương sớm còn vương trên lối đá, {A} rón rén sát lại bên ngươi, hạ giọng như sợ vách có tai."},{"who":"A","text":"{Goi} có nghe không? Sáng nay {xung} thấy cung nhân của {goi} bê thuốc ra cổng sau, bước đi rất vội."},{"who":"me","text":"Thuốc ư? Cổng sau vốn hẻo lánh, sao {goi} lại để ý đến thế?"},{"who":"A","text":"Thì tình cờ thấy thôi. Thuốc gì, bệnh ai, {xung} không dám đoán bừa, chỉ lo cho {goi} thôi."},{"who":"me","text":"Lo của {goi} {xung} xin nhận. Chuyện này có lớn có nhỏ, {xung} cần xem nên đáp lời nàng thế nào."}]}},
{"id":"j68:j68c-day-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quân cờ trên bàn đá chưa kịp nguội, {A} đỏ mặt gạt hai quân đen sang một bên, giọng lanh lảnh vang khắp sân."},{"who":"A","text":"Ván này {xung} lỡ tay thôi! Chơi lại một ván nữa đi, {M} làm chứng cho cả hai."},{"who":"me","text":"{Goi} vừa thua đã đòi lại, {xung} nhìn mà buồn cười. Quân cờ nào có lỗi gì."},{"who":"A","text":"Nước cờ ấy {xung} đi vội, chứ thật ra {xung} giỏi hơn thế nhiều. {Goi} không dám đấu lại sao?"},{"who":"me","text":"Dám chứ. Chỉ là chơi thế nào cho trọn tình lẫn lý, {xung} còn đang nghĩ."}]}},
{"id":"j68:j68c-day-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên giếng cổ, tiếng quát tháo vang dội cả lối đi, hai chiếc xô gỗ đổ nghiêng, nước loang ra mặt đá."},{"who":"A","text":"Cung nữ của {xung} múc nước trước, vậy mà {M} của {goi} lại đòi giành. Thế này còn ra thể thống gì!"},{"who":"me","text":"{Xung} nghe tiếng cãi từ xa, chưa rõ đầu đuôi. Chỉ một xô nước, sao lại ầm ĩ đến thế?"},{"who":"A","text":"Chuyện đâu phải chỉ vì xô nước, là vì thể diện của cung {xung}. {Goi} xử cho công bằng đi."},{"who":"me","text":"Công bằng thì phải nghe cả hai bên. {Xung} đang nghĩ xem nên mở lời thế nào cho họ khỏi hằn học thêm."}]}},
{"id":"j68:j68c-day-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp sơn đỏ vừa mở, mùi hoa quế ngọt dịu lan khắp gian ngoài, mặt bánh cháy sém một góc."},{"who":"A","text":"Đây là bánh hoa quế {xung} tự tay làm. Hơi cháy một chút, {goi} đừng chê nhé."},{"who":"me","text":"Tự tay {goi} làm ư? Hương quế thơm thế này, {xung} thật không ngờ {goi} còn khéo bếp núc."},{"who":"A","text":"{Xung} loay hoay từ sáng sớm, thất bại hai ba lần mới được mẻ này. Mong {goi} nếm thử cho {xung} yên lòng."},{"who":"me","text":"Mẻ bánh này đã chứa cả tấm lòng {goi}, {xung} nên đón nhận cho phải đạo."}]}},
{"id":"j68:j68c-day-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chim vẹt lông xanh đậu trên song cửa, cổ rướn lên, giọng the thé vang cả hiên cung."},{"who":"A","text":"Con vẹt của {xung} mới lạc sang đây phải không? Ôi, nó lại nói bậy gì rồi."},{"who":"me","text":"Nó vừa nhắc lại một lời bàn tán rất rõ ràng, nghe giống giọng {goi} lắm. Là nói về một người trong cung."},{"who":"A","text":"Chắc nó học lỏm ở đâu thôi. {Xung} nuôi nó từ nhỏ, đâu có dạy nó những lời như vậy."},{"who":"me","text":"Có thể thật. Chỉ là lồng son treo dưới mái cung {goi} vẫn đang trống. {Xung} cân nhắc xem nên làm gì với con chim này."}]}},
{"id":"j68:j68c-day-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tuyết phủ trắng sân cung, từng bông còn lả tả rơi, {A} xoa hai bàn tay đỏ ửng, mắt sáng như trẻ nhỏ."},{"who":"A","text":"{Goi} ơi, đắp người tuyết bên hiên với {xung} đi! Lâu lắm rồi {xung} chưa được chơi như thế này."},{"who":"me","text":"Giữa cung cấm mà nghe {goi} nói vậy, {xung} bỗng nhớ những mùa đông thuở bé."},{"who":"A","text":"Ở đây ai cũng giữ lễ, chỉ có tuyết là chẳng hỏi han ai. Một lát thôi cũng được."},{"who":"me","text":"Một lát thôi, nghe thật dễ chịu. Để {xung} nghĩ xem nên cùng nàng thế nào."}]}},
{"id":"j68:j68c-day-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió cuối chiều lùa qua rèm, {A} nắm chặt vạt áo, mãi mới ngẩng lên được nhìn ngươi."},{"who":"A","text":"{Goi}, người thân ở quê {xung} đang đau nặng, mà nguyệt bổng còn thiếu. {Xung} chưa dám mở lời, sợ {goi} khó xử."},{"who":"me","text":"Người thân đau nặng mà {goi} giấu đến giờ mới nói, chắc đã nghĩ ngợi nhiều đêm."},{"who":"A","text":"{Xung} chỉ cần một túi bạc nhỏ gửi về, còn lại sẽ tự xoay. Nói ra, mặt {xung} nóng bừng."},{"who":"me","text":"Lời khó nói nhất, {goi} đã nói được. {Xung} cân nhắc xem nên giúp thế nào cho phải lẽ."}]}},
{"id":"j68:j68c-day-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sắc mặt {A} tái nhợt, đôi môi run khẽ, bàn tay lạnh buốt níu lấy tay áo ngươi."},{"who":"A","text":"Đêm qua {xung} mơ thấy giếng cạn, trong giếng có tiếng trẻ khóc. {Xung} sợ lắm, cả đêm không dám chợp mắt."},{"who":"me","text":"Mộng mị thường chỉ là điều lòng người nghĩ nhiều mà thành. Sao {goi} lại tin đến mức sợ hãi vậy?"},{"who":"A","text":"Tiếng khóc ấy rất thật, như ngay bên tai. {Goi} bảo {xung} nên làm gì bây giờ?"},{"who":"me","text":"Nhìn {goi} sợ thế này, {xung} không thể gạt đi một câu. Để {xung} nghĩ cách nào cho nàng yên lòng."}]}},
{"id":"j68:j68c-day-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh nắng xiên qua bậc thềm, {A} chìa ra chiếc khăn lụa thêu hoa lê, ánh mắt dò xét lẫn tò mò."},{"who":"A","text":"Khăn này {xung} nhặt được ở lối đi sau điện, góc khăn thêu dấu hiệu cung {goi}. Sao khăn lại rơi đúng chỗ ấy vậy?"},{"who":"me","text":"Hoa lê này đúng là {xung} thêu. Khăn thất lạc đã lâu, {xung} còn tưởng không tìm lại được."},{"who":"A","text":"Lối sau điện vốn vắng người, rơi ở đó cũng lạ. {Xung} chỉ muốn hỏi cho rõ, không có ý gì khác."},{"who":"me","text":"Lạ thật. Nhưng lời nào nên nói, lời nào nên giữ, {xung} phải nghĩ trước đã."}]}},
{"id":"j68:j68c-day-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nơi bậc đá, đôi hài thêu chỉ vàng của {A} lấp lánh, nàng xoay một vòng, vạt váy xòe như hoa."},{"who":"A","text":"{Goi} thấy đôi hài này thế nào? Hoàng thượng vừa thưởng đấy, chỉ vàng thêu từng đường rất tinh xảo."},{"who":"me","text":"Chỉ vàng óng thế kia, hẳn thợ thêu đã mất nhiều công. Hoàng thượng thật có lòng với {goi}."},{"who":"A","text":"{Xung} cũng không ngờ. Nhưng mà, {goi} không có gì muốn nói sao?"},{"who":"me","text":"Ánh mắt {goi} đang đợi lời đáp của {xung}. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-day-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang vắng, ánh chiều tà hắt lên vách gạch, một bóng người co ro nơi góc cột, hai vai run khẽ."},{"who":"A","text":"{Goi}, đừng nhìn {xung} như vậy. {Xung} chỉ là, chỉ là thấy lòng nặng quá thôi."},{"who":"me","text":"Khăn trên tay {goi} ướt cả rồi. {Xung} đi ngang qua, không thể làm như chưa thấy."},{"who":"A","text":"Chuyện này nói ra cũng chẳng giải quyết được gì. {Xung} chỉ cần ngồi yên một lúc."},{"who":"me","text":"Nước mắt như thế, giấu trong lòng chắc đã lâu. {Xung} nên ở lại hay nên lui, để {xung} nghĩ."}]}},
{"id":"j68:j68c-day-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân gạch lạnh, {A} quỳ thẳng lưng, gò má ửng đỏ, tà váy bám bụi, nội giám đứng một bên canh chừng."},{"who":"A","text":"{Goi}, {xung} lỡ lời với nội giám nên bị phạt quỳ. Chẳng ngờ lại để {goi} thấy cảnh này."},{"who":"me","text":"Nhìn {goi} quỳ giữa nắng, {xung} cũng khó đi qua như không thấy. {M} đứng sau {xung}, im lặng."},{"who":"A","text":"{Xung} biết {goi} chẳng nợ gì {xung}, chỉ mong {goi} đừng nhìn {xung} bằng ánh mắt thương hại."},{"who":"me","text":"Không phải thương hại, mà là không nỡ. Xin để {xung} nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-day-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng nhạc nhẹ vừa dứt, {A} đứng ngoài hiên, tay vịn khung cửa, ánh mắt rụt rè dõi theo từng tà áo của ngươi."},{"who":"A","text":"{Goi}, điệu múa vừa rồi đẹp quá. {Xung} đứng xem từ nãy giờ, không kìm được mà muốn xin học vài động tác."},{"who":"me","text":"Điệu này {xung} mới luyện, chưa thật thuần. {Goi} học để làm gì vậy?"},{"who":"A","text":"Yến sắp tới, {xung} chưa có tiết mục nào. {Xung} sợ lại ngồi lặng giữa mọi người."},{"who":"me","text":"Sợ lặng lẽ giữa yến tiệc, {xung} hiểu. Nhưng nên dạy ra sao, {xung} còn phải cân nhắc."}]}},
{"id":"j68:j68c-day-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Canh khuya, ngọn đèn trong gian thờ vẫn chưa tắt, {A} mắt quầng thâm, khẽ nắm tay ngươi."},{"who":"A","text":"{Goi}, hôm qua {xung} thức khuya chép kinh, sáng nay sợ nhỡ miệng trước Thái hậu. Giúp {xung} đỡ một lời được không?"},{"who":"me","text":"Chép kinh đến khuya, hẳn {goi} đã mệt lắm rồi. Thái hậu hỏi, {goi} định đáp ra sao?"},{"who":"A","text":"{Xung} cũng chưa nghĩ ra. Chỉ sợ nhỡ lời, lại mang tội bất kính."},{"who":"me","text":"Một lời đỡ nhẹ nhàng, nhưng đỡ thế nào cho đúng thì {xung} cần nghĩ kỹ."}]}},
{"id":"j68:j68c-day-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sương còn đọng trên lá, góc vườn sau cung nở rộ những bông thược dược tía, {A} khom lưng với tay hái."},{"who":"A","text":"Ôi, {goi} tới rồi. {Xung} chỉ hái vài bông cắm bình thôi, hoa đẹp thế này để héo thì tiếc."},{"who":"me","text":"Thược dược tía ấy {xung} chăm từ đầu xuân, vậy mà {goi} hái đã vội, chưa hề hỏi một lời."},{"who":"A","text":"Chỉ là mấy bông hoa, {goi} đâu đến nỗi keo kiệt. {Xung} sẽ cắm thật đẹp cho {goi} ngắm."},{"who":"me","text":"Hoa là chuyện nhỏ, quy củ mới là chuyện lớn. Để {xung} nghĩ cách nói cho khéo."}]}},
{"id":"j68:j68c-day-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn cung, {A} quỳ thẳng, hai tay đặt lên gối, giọng khẽ nhưng rõ từng chữ."},{"who":"A","text":"Bẩm, có một cung khác mời {xung} sang hầu. {Xung} chưa dám nhận, nếu {goi} chưa gật đầu."},{"who":"me","text":"Ngươi theo ta bao lâu nay, ta không phải không biết. Cung nào đã ngỏ lời với ngươi?"},{"who":"A","text":"{Xung} không dám tự ý. Chỉ mong {goi} định đoạt, {xung} xin chịu theo."},{"who":"me","text":"Lòng ngươi thành thật, ta thấy cả. Để ta nghĩ cho kỹ rồi nói ngươi nghe."}]}},
{"id":"j68:j68c-day-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khóa nhỏ lách cách, {A} ghé sát, đặt vào tay ngươi chiếc hộp gỗ trầm, hương trầm phảng phất nơi kẽ tay."},{"who":"A","text":"Mai nội giám sẽ soát cung {xung}. Hộp này chỉ là kỷ vật của mẹ {xung}, nhờ {goi} giữ giùm một đêm."},{"who":"me","text":"Kỷ vật của mẹ {goi}, ắt phải rất quý. Nhưng đêm trước ngày soát cung, nhờ ai cũng nặng lời."},{"who":"A","text":"Chìa khóa {xung} vẫn đeo trên cổ. {Xung} chỉ còn tin được {goi} thôi."},{"who":"me","text":"Chữ tin ấy không nhẹ. {Xung} cần nghĩ xem nên đáp thế nào cho vẹn."}]}},
{"id":"j68:j68c-day-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa sổ nắng ngả vàng, khung thêu dang dở cánh hoa mai, {A} cầm kim mà ngón tay còn lúng túng."},{"who":"A","text":"{Goi}, cánh hoa mai này {xung} thêu mãi chưa xong. Chỉ trong giỏ của {goi} có màu nào hợp không?"},{"who":"me","text":"Cánh mai cần màu tơ hồng nhạt mới đẹp. Cuộn chỉ ấy {xung} cất ở bàn gần cửa sổ."},{"who":"A","text":"{Xung} vụng về lắm, mũi kim cứ lệch. {Goi} đừng cười {xung} nhé."},{"who":"me","text":"Không cười đâu. Thêu thùa nào cũng bắt đầu từ lúng túng, để {xung} nghĩ cách giúp nàng."}]}},
{"id":"j68:j68c-day-022","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gian ngoài vắng lặng, bình phong chạm hoa khẽ lay, thoáng bóng áo ai lấp ló sau cánh gỗ."},{"who":"M","text":"Bẩm, {xung} thấy bóng {A} đứng sau bình phong từ nãy. Hình như nàng đang nghe lời {goi} nói với người khác."},{"who":"me","text":"Nghe lỏm trong cung ta ư? Ngươi có chắc là nàng, chứ không phải bóng cây ngoài cửa?"},{"who":"M","text":"{Xung} nhìn rõ tà áo của nàng. {Xung} không dám nói sai, chỉ lo nàng nghe được điều không nên nghe."},{"who":"me","text":"Ngươi lo xa là phải. Để ta nghĩ xem nên đối với nàng ra sao."}]}},
{"id":"j68:j68c-day-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc diều giấy hình bướm rách một cánh, {A} chạy ào qua ngưỡng cửa, nước mắt lăn trên má, tay vẫn nắm chặt cuộn dây."},{"who":"A","text":"{Goi} ơi, anh chị cướp diều của con, rách mất rồi! Cuốn dây còn nằm dưới gốc cây lê kia."},{"who":"me","text":"Ngoan, đừng khóc. Con bướm giấy này con làm ra hay có người tặng con vậy?"},{"who":"A","text":"Con tự chọn giấy, còn xin {M} dán cánh. Con muốn nó bay cao nhất sân."},{"who":"me","text":"Lời con nói, {xung} nghe cả. Để {xung} nghĩ xem nên giúp con thế nào."}]}},
{"id":"j68:j68c-day-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, tiếng đàn tranh từ cung bên rót qua tường, từng nốt dịu dàng như nước chảy, người đi đường cũng dừng chân."},{"who":"A","text":"{Goi} cũng nghe rồi sao? Tiếng đàn của {xung} suốt buổi tối nay, hay là làm phiền {goi} nghỉ ngơi?"},{"who":"me","text":"Không hề. Người nghe quanh đây ngày một đông, ai cũng lặng đi vì khúc nhạc ấy."},{"who":"A","text":"{Xung} gảy chỉ để giải khuây, đâu có ý khoe. Người ta nghe cũng được, không nghe cũng chẳng sao."},{"who":"me","text":"Một tấm lòng gửi vào dây đàn như thế, {xung} không nỡ làm ngơ. Để {xung} nghĩ cách đáp lại."}]}},
{"id":"j68:j68c-day-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn ăn nhỏ buổi sớm lặng lẽ, chén cháo yến sứ men xanh còn bốc hơi mỏng, nhưng trông không phải chén thường ngày."},{"who":"A","text":"Chén cháo yến ấy đã bị đổi, {goi} chắc cũng nhận ra. Cung nhân bảo lúc đó chỉ có {xung} ghé qua gian bếp."},{"who":"me","text":"Phải, {xung} nghe rồi. {Goi} ghé bếp cung {xung} vào lúc sớm như vậy, hẳn có việc gì."},{"who":"A","text":"{Xung} chỉ đi ngang, thấy hơi cháo thơm nên vào xem thôi. {Goi} nghi ngờ gì chăng?"},{"who":"me","text":"{Xung} chưa nói chắc điều gì. Chén cháo này {xung} cần liệu sao cho đúng."}]}},
{"id":"j68:j68c-day-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chậu cảnh trúc vỡ dưới hiên, đất vãi tung tóe, {A} đứng sững, ánh mắt đảo nhanh quanh sân."},{"who":"A","text":"Ơ, {xung} chỉ vấp một chút thôi, ai ngờ chậu trúc lại đổ. {Goi} có thấy ai không?"},{"who":"me","text":"{Xung} thấy hết. Chậu trúc đặt cạnh chậu phù dung kia, cũng là chậu {xung} quý."},{"who":"A","text":"Đất hết cả rồi, chậu thì vỡ nát. {Xung} biết lỗi, chỉ mong {goi} đừng làm to chuyện."},{"who":"me","text":"Lỗi là lỗi, nhưng lòng {goi} cũng thật. {Xung} cần nghĩ xem nên xử ra sao cho phải."}]}},
{"id":"j68:j68c-day-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mực trên tờ hoa tiên còn chưa khô, bài thơ vịnh trăng nằm yên trong tay {A}, ánh mắt thoáng lo âu."},{"who":"A","text":"{Goi} đọc giúp {xung} bài thơ này. Câu cuối nghe buồn quá, {xung} phân vân nên giữ hay bỏ."},{"who":"me","text":"Trăng trong thơ {goi} lạnh mà sáng, đọc xong lòng {xung} cũng chùng xuống."},{"who":"A","text":"Làm thơ là để giãi bày, nhưng đưa ra cho người xem thì lại sợ họ hiểu tâm sự của {xung}."},{"who":"me","text":"Một câu thơ buồn không có tội. Nên khuyên {goi} thế nào, {xung} còn phải nghĩ."}]}},
{"id":"j68:j68c-day-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa phòng bật mở, ánh sáng sớm tràn vào, chiếc lược ngọc còn nằm yên trên mặt bàn, mái tóc ngươi còn xõa."},{"who":"A","text":"Ôi, {xung} xin lỗi, không biết {goi} chưa chải tóc. {Xung} đột ngột quá."},{"who":"me","text":"Không sao, {xung} cũng giật mình. Chỉ là mặt mộc thế này, {goi} đừng nhìn kỹ."},{"who":"A","text":"{Xung} nhìn thấy rồi, mà thật ra chẳng có gì đáng ngại. Hai người đứng sững thế này, buồn cười thật."},{"who":"me","text":"Thật là một buổi sáng khó lường. Để {xung} nghĩ xem nên đối đáp thế nào cho vui lòng cả hai."}]}},
{"id":"j68:j68c-day-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang dài lặng gió, {A} kéo chặt tay áo ngươi, vạt váy nàng còn lấm vết giày của ai."},{"who":"A","text":"{Goi} nhìn xem, {xung} bị {B} giẫm lên làn váy ngay giữa hành lang. Nàng cố ý, {goi} ở ngay đó, chắc thấy rõ."},{"who":"me","text":"Giữa lúc đông người, cả hành lang đều nghe tiếng {goi} kêu lên. Chuyện này {xung} có thấy."},{"who":"A","text":"Xin {goi} làm chứng cho {xung}. Nếu không, mọi người sẽ cho là {xung} đặt điều."},{"who":"me","text":"Lời làm chứng không nhẹ như tà áo. {Xung} cần nghĩ thật kỹ trước khi mở lời."}]}},
{"id":"j68:j68c-day-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh chiều rọi qua hàng cột son, {A} ghé sát tai ngươi, giọng nhỏ như gió thoảng qua rèm."},{"who":"A","text":"{Goi} có để ý không? Gần đây {B} được triệu thị tẩm nhiều lắm, chắc là có bí quyết gì."},{"who":"me","text":"Chuyện của người ta, {xung} sao dám đoán bừa. {Goi} nói với {xung} làm gì?"},{"who":"A","text":"Vì {xung} thấy {goi} đáng tin. Hay là {goi} tìm dịp hỏi thử, dò xem nàng nghĩ gì."},{"who":"me","text":"Lời dò xét nói ra dễ, làm khó. Để {xung} nghĩ xem nên đối xử với {B} thế nào."}]}},
{"id":"j68:j68c-day-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén trà vừa đặt xuống bàn, {A} cúi đầu, ngón tay xoắn chặt vạt áo, giọng lí nhí."},{"who":"A","text":"{Goi}, {xung} có điều muốn nói, nhưng sợ {goi} giận. Nếu {goi} cho phép, {xung} mới dám mở lời."},{"who":"me","text":"Ngươi theo ta lâu nay, ta chưa từng nặng lời với ngươi. Điều gì khiến ngươi sợ đến thế?"},{"who":"A","text":"{Xung} sợ nói ra rồi, {goi} sẽ không còn tin {xung}. Nhưng giấu mãi, lòng {xung} cũng không yên."},{"who":"me","text":"Lòng ngươi thành, ta thấy. Để ta nghĩ nên cho ngươi nói ra sao."}]}},
{"id":"j68:j68c-day-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên hiên nắng ấm, một bình sứ trắng nằm trong tay {A}, hương trà sen tuyết thoang thoảng theo gió."},{"who":"A","text":"{Goi} ơi, đây là trà mới hái đầu xuân, bình trà sen tuyết quý lắm. Mời {goi} cùng thưởng thức trong hiên nắng này."},{"who":"me","text":"Trà hái đầu xuân, hiếm lắm. {Goi} nhớ tới {xung} thật là có lòng."},{"who":"A","text":"Chỉ có người hợp ý mới đem ra uống chung. {Goi} đừng từ chối nhé."},{"who":"me","text":"Một lời mời ân cần như thế, {xung} sao nỡ qua loa. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-day-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần trưa, mùi thuốc thoảng nhẹ theo bước chân, {A} khoác túi vải đeo vai, dừng lại bên ngưỡng cung."},{"who":"A","text":"{Goi}, hôm nay {xung} tiện đường nên ghé thăm. Dạo này thân thể {goi} có điều gì cần dặn dò thêm chăng?"},{"who":"me","text":"{Goi} chu đáo quá. Mấy hôm nay {xung} vẫn ngủ chưa sâu, sáng dậy đôi khi còn nặng đầu."},{"who":"A","text":"Giấc ngủ là gốc của sức khỏe. Nếu {goi} bằng lòng, {xung} xin xem mạch một lượt cho yên tâm."},{"who":"me","text":"Một lượt bắt mạch thì tiện, nhưng nên làm thế nào cho phải thì {xung} còn nghĩ."}]}},
{"id":"j68:j68c-day-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư đóng dấu sáp mỏng run run trong tay {A}, nét chữ dang dở nhòe một đầu vì giọt nước."},{"who":"A","text":"{Goi}, đây là thư nhà {xung} viết dở. {Xung} nhớ nhà quá, mà phiên gửi thư xuất cung còn chưa tới."},{"who":"me","text":"Nét chữ thế này, ngươi viết trong đêm sao? Cầm lên mà mực còn run."},{"who":"A","text":"Dạ, mẹ {xung} yếu, mà quy củ thì không thể phá. {Xung} chỉ biết nhờ {goi} xem giúp."},{"who":"me","text":"Lòng nhớ nhà, ta hiểu. Để ta nghĩ xem nên giúp ngươi ra sao."}]}},
{"id":"j68:j68c-day-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chim sẻ đập cánh khắp gian phòng, lông nhỏ bay lả tả, {A} xô cửa bước vào, tay vịn khung cửa thở gấp."},{"who":"A","text":"Chim vào nhà, {goi} biết đó là điềm gì không? Dân gian vẫn bảo, hoặc là có khách, hoặc là có chuyện chẳng lành."},{"who":"me","text":"Chỉ là một con sẻ lạc thôi, nó sợ hơn chúng ta nhiều. Nhìn xem, nó run lên kìa."},{"who":"A","text":"{Xung} không tin cũng không dám không tin. Cung cấm nhiều chuyện lạ lắm."},{"who":"me","text":"Chuyện lạ thì đã nhiều. Còn con chim này, {xung} nghĩ nên xử ra sao."}]}},
{"id":"j68:j68c-day-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa cung vừa mở, {A} đã bước vào, mặt đỏ phừng, vạt áo còn rung theo từng hơi thở dồn."},{"who":"A","text":"Hoàng hậu nhắc nhở {xung} nơi điện, ngay trước mặt mọi người! Lại còn có kẻ cười thầm nữa chứ!"},{"who":"me","text":"{Goi} ngồi xuống uống ngụm nước đã. Giận như thế thì hại thân."},{"who":"A","text":"{Xung} chịu sao nổi! Nhắc thì nhắc, mà cớ gì lại kéo người khác ra chê trách {xung}?"},{"who":"me","text":"Lời đã nhiều mà chưa dứt. {Xung} đang nghĩ nên đáp nàng thế nào cho vừa."}]}},
{"id":"j68:j68c-day-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới gốc ngọc lan, một chiếc vòng tay bạc lấp lánh giữa lá khô, vết khắc nhỏ bên trong lộ ra dưới nắng."},{"who":"A","text":"Đó là vòng của {xung}! Bên trong có khắc nét chữ nhỏ của mẹ {xung}, mất từ lâu rồi."},{"who":"me","text":"Cung nhân vừa quét dọn nhặt được, {xung} cũng chưa biết là của ai. {Goi} nói thế thì nhìn lại vòng một chút."},{"who":"A","text":"Chữ khắc ấy không nhầm được đâu. {Xung} mất nó như mất đi một phần của mẹ."},{"who":"me","text":"Vật quý của người thân, {xung} hiểu. Nhưng nên xử trí thế nào cho đúng phép, để {xung} nghĩ."}]}},
{"id":"j68:j68c-day-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bậc thềm lát đá mát lạnh, {A} chắp tay, cúi người rất thấp, giọng ôn hòa như không có ý gì."},{"who":"A","text":"Bẩm, nhân dịp tết, các cung đã gửi quà biếu tổng quản rồi ạ. {Xung} chỉ nhắc nhẹ, kẻo cung {goi} thất lễ."},{"who":"me","text":"Ngươi nhắc khéo thật. Các cung đã biếu cả sao?"},{"who":"A","text":"Dạ, cung nào cũng đã tỏ lòng. Chỉ còn cung {goi}, {xung} thấy chưa có tin gì."},{"who":"me","text":"Lòng ngươi tử tế, ta hiểu. Để ta nghĩ xem nên đáp lễ thế nào cho phải."}]}},
{"id":"j68:j68c-day-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Má đỏ bừng, lưng áo ướt mồ hôi, {A} nằm nghiêng bên gối, hơi thở nóng nhè nhẹ phả ra."},{"who":"A","text":"{Goi} ơi, con thấy trong người hâm hấp, đầu hơi choáng. Con không muốn khóc đâu."},{"who":"me","text":"Con ngoan, để {xung} sờ trán nào. Trán nóng hơn thường ngày rồi."},{"who":"A","text":"Con nằm tựa vào {goi} một lát thôi cũng được. Con sợ phải uống thuốc đắng."},{"who":"me","text":"Con đừng sợ. Thuốc đắng hay không, để {xung} liệu cách cho con."}]}},
{"id":"j68:j68c-day-040","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong gian ngoài tĩnh lặng, {A} làm việc cả buổi chẳng nói một lời, bóng nàng khuất sau tà rèm."},{"who":"M","text":"Bẩm {goi}, {xung} nghe nói hôm nay là sinh thần của {A}. Nàng không dám nói với ai."},{"who":"me","text":"Cả buổi nàng im như vậy, thì ra là có chuyện trong lòng. Nàng ở cung ta đã bao lâu?"},{"who":"M","text":"Cũng đã lâu rồi ạ. {Xung} chỉ thấy tội, năm nào nàng cũng như thế."},{"who":"me","text":"Ngươi có lòng nhắc ta, ta ghi nhận. Để ta nghĩ xem nên làm thế nào cho nàng vui."}]}},
{"id":"j68:j68c-day-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trà đã nguội đi một nửa, {A} vẫn thong thả hỏi, ngón tay lơ đãng xoay quanh miệng chén."},{"who":"A","text":"Nghe nói {goi} xuất thân danh gia. Không biết lệnh tôn làm quan gì, họ hàng ai có tiếng trong triều?"},{"who":"me","text":"{Goi} hỏi kỹ thế, {xung} lại thấy lạ. Chuyện gia thế thường chẳng ai tự nhiên đem ra bàn."},{"who":"A","text":"Chỉ là tò mò thôi. Cùng ở một cung cấm, biết nhau nhiều hơn cũng chẳng hại gì."},{"who":"me","text":"Lời nhẹ mà ý sâu. Để {xung} nghĩ xem nên trả lời ra sao."}]}},
{"id":"j68:j68c-day-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Túi thơm lụa đào đung đưa nơi dây thắt nút đôi, hương hoa nhài quyện quế bay nồng khắp gian phòng."},{"who":"A","text":"{Goi} ngửi thử túi thơm {xung} tự phối đi. Nghe đồn mùi hơi nồng, {goi} nói thật lòng cho {xung} biết."},{"who":"me","text":"Hương hoa nhài thoang thoảng, nhưng quế lại hơi đậm. {Goi} phối thế này là có ý riêng sao?"},{"who":"A","text":"{Xung} thích quế, nên muốn giữ mùi ấm. Nhưng nếu nồng quá thì cũng không nên."},{"who":"me","text":"Một lời thật làm nàng vui hay buồn, {xung} còn đang nghĩ."}]}},
{"id":"j68:j68c-day-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều vàng rọi xuống lương đình quen thuộc, {A} ngồi nơi chiếc ghế đá ấy, nghe tiếng bước chân liền quay mặt đi."},{"who":"A","text":"Ồ, {goi} cũng đi dạo vườn sao? Lương đình này {xung} ngồi lâu rồi, {goi} thông cảm nhé."},{"who":"me","text":"Lương đình này {xung} đến mỗi chiều, chẳng ngờ hôm nay {goi} đến trước."},{"who":"A","text":"Chỗ ngồi vốn chẳng ai riêng cho ai. {Xung} chỉ thấy ngồi đây hợp lòng."},{"who":"me","text":"Chỗ ngồi là chuyện nhỏ, nhưng thế nào cho khéo thì {xung} cần nghĩ."}]}},
{"id":"j68:j68c-day-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư, mảnh vỡ bình men xanh nằm rải trên thảm, {A} đứng cạnh, mặt trắng bệch, tay run nắm vạt áo."},{"who":"A","text":"Bẩm, {xung} vấp phải thảm nên làm vỡ bình. {Xung} không cố ý, xin {goi} tha tội."},{"who":"me","text":"Bình men xanh Hàng Châu ấy ta quý, nhưng nhìn tay ngươi run thế, ta chưa vội giận."},{"who":"A","text":"{Xung} đã ngã thật, đầu gối còn đau. Mảnh vỡ vẫn nằm dưới chân án thư, chưa dám nhặt."},{"who":"me","text":"Ngươi nói có thật hay chưa, ta phải xem. Để ta nghĩ nên xử thế nào cho phải."}]}},
{"id":"j68:j68c-day-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau bình phong, hơi thở {A} thoảng bên tai, giọng nhỏ như gió luồn qua kẽ lá."},{"who":"A","text":"{Goi} có nghe tin không? Nghe đâu sắp có sắc phong mới. {Xung} muốn mời {goi} đứng cùng phe trước khi tin ấy lan ra."},{"who":"me","text":"Tin chưa chắc đã thật, mà phe cánh thì một khi đã chọn khó lòng quay đầu."},{"who":"A","text":"{Xung} hứa sẽ trả ơn. {Goi} cứ cân nhắc, nhưng đừng để muộn quá."},{"who":"me","text":"Lời hứa trả ơn nghe nhẹ mà nặng. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-day-046","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nội giám bưng hộp bánh đậu xanh, dấu son niêm phong cung Thái hậu còn tươi, chậm rãi bước vào sân."},{"who":"M","text":"{Goi}, nội giám cung Thái hậu vừa đến, truyền rằng sớm nay Thái hậu thấy {goi} hành lễ cẩn thận, nên tiện tay ban hộp bánh này."},{"who":"me","text":"Ân điển của Thái hậu, ta sao dám nhận nhẹ nhàng. Một hộp bánh nhỏ mà lòng người lớn quá."},{"who":"M","text":"Nội giám còn nhắn lời Thái hậu: lễ cẩn thận là phúc của cung đình, {goi} giữ lấy lòng ấy mà tiếp tục."},{"who":"me","text":"Lời dạy bảo ta xin ghi nhớ. Còn hộp bánh này, ta phải nghĩ nên xử trí ra sao."}]}},
{"id":"j68:j68c-day-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọn đèn cung hắt lên gương mặt {A}, nàng vẫn đứng hầu thẳng lưng, nhưng tay áo che miệng, ho nghẹn từng tiếng."},{"who":"A","text":"{Xung} không sao đâu ạ. {Goi} cứ dùng trà, {xung} hầu bên cạnh."},{"who":"me","text":"Nghe tiếng ho ấy, ta đâu thể làm như không nghe. Ngươi đứng đến tái cả mặt rồi."},{"who":"A","text":"{Xung} chỉ sợ làm lỡ việc của cung, nên không dám báo ốm."},{"who":"me","text":"Lỡ việc còn nhẹ hơn lỡ thân thể. Để ta nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-day-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bông mẫu đơn trắng đầu tiên hé nở bên bệ đá, cánh mỏng ánh sương, {A} đứng đó ngắm mãi không rời mắt."},{"who":"A","text":"Đẹp quá, {goi} ơi. Cánh hoa trắng như tuyết, nhụy vàng như ánh nắng. {Xung} chưa thấy mẫu đơn nào đẹp thế."},{"who":"me","text":"Chậu mẫu đơn này {xung} chăm từ năm ngoái, bông đầu mới nở. {Goi} khen, {xung} vui lòng lắm."},{"who":"A","text":"Giữa cung cấm có bông hoa như vậy, lòng người cũng dịu lại."},{"who":"me","text":"Hoa đẹp là chuyện chung, nhưng chia thế nào cho vừa thì {xung} phải nghĩ."}]}},
{"id":"j68:j68c-day-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giỏ cói đựng thuốc đung đưa nơi tay {A}, dấu Thái y viện in trên nắp, nàng nhìn quanh ngơ ngác như lạc vào mê cung."},{"who":"A","text":"{Goi} ơi, cho {xung} hỏi đường đến Thái y viện. {Xung} mới vào cung, đi mãi chẳng ra lối."},{"who":"me","text":"Cung cấm lắm lối, người mới vào ai cũng lạc. Giỏ thuốc trong tay ngươi là của ai?"},{"who":"A","text":"Của ai thì {xung} cũng không rõ. Vừa nãy có người nhờ cầm giùm rồi bảo mang tới Thái y viện."},{"who":"me","text":"Giỏ thuốc không phải của ngươi, mà lại có dấu Thái y viện. Ta nên giúp thế nào đây."}]}},
{"id":"j68:j68c-day-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mắt thâm quầng, ngón tay còn dính mực, {A} dựa vào khung cửa, hơi thở mỏi mệt như mới đi qua ba đêm dài."},{"who":"A","text":"{Goi}, {xung} bị phạt chép kinh ba hôm vì lỡ lời nơi điện. Mực của {xung} cạn mất rồi."},{"who":"me","text":"Ba hôm chép kinh, hẳn {goi} mệt lắm. Hộp mực trên giá thư phòng của {xung} cũng không nhiều."},{"who":"A","text":"{Xung} biết thỏi mực tùng khói quý, nên chỉ dám xin một ít. Nếu {goi} thấy khó thì {xung} đi."},{"who":"me","text":"Một chút mực nhỏ nhưng ý nghĩa không nhỏ. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-day-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh chiều hắt lên song cửa, {A} chống tay lên má, hờn dỗi nhìn ngươi như đợi ngươi mở lời trước."},{"who":"A","text":"Hôm qua {goi} hẹn đến thăm {xung}, {xung} chờ mãi mà chẳng thấy bóng người. Pha trà xong lại để nguội."},{"who":"me","text":"Nhìn nét mặt {goi} thế này, {xung} biết mình đã khiến {goi} buồn."},{"who":"A","text":"{Xung} không trách đâu, chỉ là hơi tủi. Lời hẹn nói ra, sao có thể để trôi như gió."},{"who":"me","text":"Lời hẹn thì phải trọn, {xung} hiểu. Để {xung} nghĩ xem nên bù đắp thế nào."}]}},
{"id":"j68:j68c-day-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, ngọn đèn lập lòe, {A} ngồi canh ở gian ngoài, mi mắt cứ chốc chốc lại sụp xuống."},{"who":"A","text":"{Xung} không buồn ngủ đâu ạ, {goi} cứ nghỉ. {Xung} sẽ canh đèn đến sáng."},{"who":"me","text":"Mắt ngươi díu lại cả rồi mà còn chối. Đêm nay ngươi canh đèn từ chạng vạng, ta thấy hết."},{"who":"A","text":"{Xung} chỉ sợ đèn tắt, {goi} sẽ gặp bất tiện. {Xung} cố gắng được."},{"who":"me","text":"Cố gắng thì ta ghi nhận. Còn nên làm thế nào cho vẹn, để ta nghĩ."}]}},
{"id":"j68:j68c-day-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khóm cúc vàng lặng gió, {A} nắm tay ngươi kéo đi, hơi thở còn gấp vì vui, nhưng nơi hoa chỉ còn một cánh bướm trắng."},{"who":"A","text":"Lạ thật, vừa nãy bướm đậu kín cả khóm cúc, đủ màu như thêu. Sao giờ chỉ còn một con?"},{"who":"me","text":"Có lẽ chúng đã bay đi cả rồi. Chỉ có con bướm trắng này còn nán lại."},{"who":"A","text":"{Xung} muốn {goi} thấy cảnh ấy lắm, hiếm có ngày đẹp như hôm nay. Nay chỉ còn tiếc nuối."},{"who":"me","text":"Tiếc cũng là một cách thương hoa. Còn con bướm trắng này, hãy xem {xung} nên làm gì."}]}},
{"id":"j68:j68c-day-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn tính gỗ lách cách dưới ngón tay {A}, cuốn sổ bìa xanh mở sẵn, hàng số cuối tháng kẻ chằng chịt mực đỏ."},{"who":"A","text":"Bẩm, {xung} đối sổ chi tiêu cung, thấy số bạc cuối tháng lệch với sổ của Nội vụ phủ. Chưa rõ lỗi tại ai."},{"who":"me","text":"Lệch bao nhiêu, tại khoản nào? Ngươi đã tính lại mấy lượt rồi?"},{"who":"A","text":"{Xung} tính ba lượt vẫn thế. Chỉ sợ lỗi ở sổ {xung}, mà cũng sợ lỗi ở nơi khác."},{"who":"me","text":"Một con số lệch cũng có thể là mầm họa. Ta cần cân nhắc xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-day-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dây ngọc dệt tên vẫn lòng thòng nơi cổ tay nhỏ, {A} cúi gằm, ngón chân cọ cọ xuống nền gạch."},{"who":"A","text":"{Goi} ơi, con làm mất ngọc bội khóa vàng {goi} cho rồi. Con mải chơi ở vườn, quên mất."},{"who":"me","text":"Con ngẩng đầu lên nhìn {xung}. Con có biết lúc nào thì rơi không?"},{"who":"A","text":"Con không biết ạ. Con sợ {goi} giận con. Dây ngọc chỉ còn lại đây thôi."},{"who":"me","text":"{Xung} không giận con đâu. {Xung} cần nghĩ xem nên làm gì cho con yên lòng."}]}},
{"id":"j68:j68c-day-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai mẹ con {A} bước qua ngưỡng cửa, đứa nhỏ ngoan ngoãn đứng bên, mắt lanh lợi đảo quanh gian phòng."},{"who":"A","text":"{Goi} xem, cháu nhà {xung} mới ba tuổi đã thuộc thơ rồi. Thầy còn khen là có thiên tư."},{"who":"me","text":"Bé ngoan thật, nhìn ánh mắt đã thấy thông minh. {Goi} dạy con khéo lắm."},{"who":"A","text":"Con nhà {goi} cũng chắc không kém. Hôm nào cho hai đứa gặp nhau, xem đứa nào thuộc nhiều hơn."},{"who":"me","text":"Lời nói vui mà ý chẳng nhẹ. {Xung} phải nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-day-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mắt thâm quầng, ngươi bước ra hiên đúng lúc tiếng đàn tiếng cười từ cung bên vẫn chưa dứt, đêm qua lại là một đêm thức trắng."},{"who":"A","text":"Ồ, {goi} dậy sớm thế sao? Đêm qua {xung} có chút tiệc nhỏ, chắc không làm phiền {goi}."},{"who":"me","text":"Đàn hát suốt đêm vọng sang tận gối {xung}, nghe rõ từng tiếng cười."},{"who":"A","text":"{Xung} đâu có biết tiếng vọng xa thế. Cung này vốn chẳng cách âm, đâu phải lỗi của {xung}."},{"who":"me","text":"Lỗi hay không, chỉ có {goi} tự hiểu. Còn {xung}, cần nghĩ nên nói thế nào cho khéo."}]}},
{"id":"j68:j68c-day-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mâm sơn đỏ bưng trên tay {A}, mẻ bánh nướng nhân đậu bốc hương thơm ngọt, xếp tròn như hoa."},{"who":"A","text":"{Goi} ơi, {xung} lỡ làm thừa cả mẻ bánh này. Mang sang hỏi {goi} có nhận giúp không, để khô thì tội."},{"who":"me","text":"Mẻ bánh còn ấm, nhìn đã thấy ngon. {Goi} nướng thế này mà gọi là thừa sao?"},{"who":"A","text":"Lỡ tay thật mà. Bánh đậu ngọt vừa, {goi} đừng chê nhé."},{"who":"me","text":"Tấm lòng của {goi} {xung} nhận. Còn nên dùng bánh này thế nào, để {xung} nghĩ."}]}},
{"id":"j68:j68c-day-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Rương mở, khăn lụa mẫu đơn không còn trong ngăn, nơi tay áo {A} lộ ra một góc lụa trông giống hệt."},{"who":"A","text":"Bẩm, {xung} đang kiểm rương cùng {goi}. Thật không hiểu sao khăn lụa lại thất lạc."},{"who":"me","text":"Khăn thêu mẫu đơn ấy ta quý. Ngươi nhìn lại tay áo xem, góc lụa đó của ai?"},{"who":"A","text":"{Xung} không biết ạ. {Xung} chỉ hầu hạ, chưa từng dám lấy đồ của {goi}."},{"who":"me","text":"Lời ngươi nghe thật mà tay áo thì mờ ám. Ta cần nghĩ nên xử ra sao."}]}},
{"id":"j68:j68c-day-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh mắt {A} lướt qua chiếc áo thưởng mới, giọng nhẹ như lụa nhưng sắc như kim."},{"who":"A","text":"Nghe nói {goi} vừa được thưởng, mà chẳng chia ai. Cũng phải thôi, gần đây có thấy {goi} sang thăm {xung} đâu."},{"who":"me","text":"Một lời trách nhẹ thế, {xung} nghe được. {Goi} đang nghĩ {xung} đã xa lạ sao?"},{"who":"A","text":"{Xung} không dám. Chỉ là cung này lạnh, có người nhớ tới thì ấm hơn một chút."},{"who":"me","text":"Nghe vậy {xung} cũng thấy day dứt. Để {xung} nghĩ cách đáp cho phải đạo."}]}},
{"id":"j68:j68c-day-061","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên sân cỏ xanh, con diều chim én bay vút lên, dây tơ quấn bên gốc liễu, {A} kéo tay áo ngươi, mắt tròn xoe."},{"who":"A","text":"{Goi} ơi, thả diều cùng con đi! Chim én này bay cao lắm, con muốn {goi} xem."},{"who":"me","text":"Con ngoan, hôm nay {xung} còn bận việc. Nhìn mắt con thế này, {xung} cũng khó cự."},{"who":"A","text":"Con chỉ cần một lát thôi. Nếu {goi} không đến, diều con bay một mình buồn lắm."},{"who":"me","text":"Một lát cũng là tấm lòng. Để {xung} nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-day-062","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói hạt sen sấy nằm trong lòng bàn tay {A}, giấy gói còn nguyên dấu ấn thương hiệu quen, mà người mang tới đã đi mất."},{"who":"A","text":"Bẩm, người lạ ngoài cổng đưa gói này rồi biến mất, không để lại tên. Giấy gói có dấu ấn quen, nhưng {xung} chưa dám mở."},{"who":"me","text":"Ngươi thận trọng là phải. Ai gửi mà không để lại tên, lại giống như người nhà."},{"who":"A","text":"{Xung} cũng nghĩ vậy. Hạt sen sấy thơm lừng, mà lòng {xung} cứ thấp thỏm."},{"who":"me","text":"Một gói quà không tên, ta không thể nhận nhẹ. Để ta nghĩ nên xử trí ra sao."}]}},
{"id":"j68:j68c-day-063","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa lối đi lát đá, tiếng gọi vọng đến từ xa, {A} vẫy tay, gọi tên một phi tần khác mà mắt lại nhìn ngay ngươi."},{"who":"A","text":"Ôi, nhìn bóng áo từ xa, {xung} tưởng là người khác. Hôm nay {goi} mặc giống hệt áo nàng ấy."},{"who":"me","text":"Màu áo ấy {xung} may từ đầu mùa, đâu ngờ lại trùng với người khác."},{"who":"A","text":"Thế mà {xung} gọi nhầm thật. {Goi} đừng giận, chỉ là nhìn kỹ thì ngay cả dáng đi cũng giống."},{"who":"me","text":"Chuyện nhỏ, {xung} chẳng giận. Chỉ là nên đáp lại thế nào cho thú vị, để {xung} nghĩ."}]}},
{"id":"j68:j68c-visit-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp trà long tĩnh đặt giữa bàn, thiếc sáng bóng với dấu cửa hiệu lừng danh, {A} mỉm cười khéo léo."},{"who":"A","text":"{Goi}, hộp trà này {xung} tìm mãi mới có, xin biếu {goi}. Tiện đây, {xung} có việc muốn nhờ."},{"who":"me","text":"Trà long tĩnh quý hiếm thế này, hẳn {goi} đã mất không ít công. Việc gì mà {goi} phải khéo léo như vậy?"},{"who":"A","text":"Chỉ là một lời nhắc với Hoàng thượng cho cung {xung}. {Goi} thân cận, nói một câu hơn {xung} nói mười câu."},{"who":"me","text":"Nhận lễ thì dễ, nhận lời thì nặng. {Xung} cần suy xét cho phải đạo."}]}},
{"id":"j68:j68c-visit-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khay gỗ phủ khăn che, hơi nóng của bát cháo gà hầm nhân sâm vẫn còn mơ hồ lan ra, {A} nhẹ nhàng bước vào."},{"who":"A","text":"{Xung} nghe tin {goi} thức khuya mệt nhọc, nên tự tay mang bát cháo đến. Nhớ giữ gìn thân thể đấy."},{"who":"me","text":"Giữa đêm lạnh mà {goi} còn mang cháo sang tận nơi, tấm lòng này {xung} không quên."},{"who":"A","text":"Cháo hầm từ chiều, nhân sâm còn ấm. {Goi} dùng thử khi còn nóng đi."},{"who":"me","text":"Một bát cháo mà nặng nghĩa như thế, {xung} biết đáp lại sao cho vẹn tình."}]}},
{"id":"j68:j68c-visit-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giọng nội giám ôn hòa, ánh mắt chậm rãi lướt quanh phòng, nhìn từng bộ đồ, từng chiếc rèm."},{"who":"A","text":"Hoàng thượng quan tâm, muốn biết dạo này {goi} có thiếu thứ gì không. {Xung} đến hỏi thăm theo ý chỉ."},{"who":"me","text":"Ơn Hoàng thượng nhớ đến, {xung} xin cảm tạ. Chỉ là nhìn ánh mắt {goi}, hình như còn có ý khác."},{"who":"A","text":"{Xung} chỉ phụng mệnh. Hoàng thượng vừa muốn biết, vừa muốn xem cung {goi} sống thế nào."},{"who":"me","text":"Một câu hỏi thăm mà hàm ý sâu. Để {xung} nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-visit-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi thuốc nồng nặc theo bước chân {A} lan vào phòng, nét mặt nàng nặng như đá, tay còn ghì chặt túi y cụ."},{"who":"A","text":"Bẩm {goi}, bệnh của người trong cung chuyển nặng. Phải quyết ngay có nên dời sang Thái y viện hay không."},{"who":"me","text":"Chuyển nặng đến thế rồi sao? Sáng nay còn tưởng đã đỡ hơn."},{"who":"A","text":"Bệnh này chậm trễ một khắc là thêm một khắc nguy. Dời đi thì có chỗ chữa, ở lại thì gần người thân."},{"who":"me","text":"Hai đường đều có lý, mà mạng người là chuyện lớn. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-visit-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp gỗ thơm khắc quốc ấn xứ xa đặt nơi bàn thấp, mùi hương trầm vùng xa lan khắp phòng, sứ thần cúi mình đứng chờ."},{"who":"A","text":"Nghe danh {goi} hiền hậu, lần trước {goi} đã giúp đỡ, nay {xung} dâng món lễ nhỏ này để tạ ơn."},{"who":"me","text":"Hương trầm xứ xa thật khác lạ. Nhưng việc lần trước {xung} làm, nào đáng được tạ ơn đến thế."},{"who":"A","text":"Ơn này nước {xung} ghi nhớ. Món lễ ấy chỉ là chút lòng thành, mong {goi} nhận cho."},{"who":"me","text":"Lễ của sứ thần nhận nhẹ thì dễ, mà liên quan thể diện hai nước. Để {xung} nghĩ cho chu đáo."}]}},
{"id":"j68:j68c-visit-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều xuống, bóng nắng nghiêng qua cửa sổ, {A} ngồi đối diện ngươi, chén trà trong tay đã nguội từ lúc nào."},{"who":"A","text":"{Goi}, dạo này {xung} thấy cô quạnh. Trong cung này, ngoài {goi} ra, {xung} không tìm được ai thật lòng."},{"who":"me","text":"Chuyện lòng như thế, {goi} đến nói với {xung}, tức là tin {xung}. {Xung} nghe đây."},{"who":"A","text":"Ai cũng cười nói mà chẳng ai chân thành. Có khi {xung} nghĩ mình là cái bóng của chính mình."},{"who":"me","text":"Lời như vậy nghe mà chạnh lòng. {Xung} nên làm gì để {goi} bớt cô quạnh, để {xung} nghĩ."}]}},
{"id":"j68:j68c-visit-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức tường treo họa nhạt màu, {A} đứng trước gương đồng, vuốt nhẹ khóe mắt rồi quay sang nhìn ngươi."},{"who":"A","text":"{Goi}, {goi} có quen họa sư nào vẽ khéo không? {Xung} muốn bức chân dung trông trẻ ra mười tuổi."},{"who":"me","text":"Trẻ ra mười tuổi, họa sư dù giỏi cũng khó lòng, trừ khi cầm bút bằng phép tiên."},{"who":"A","text":"Thế mới cần người khéo. Ai chẳng muốn để lại dung nhan đẹp nhất cho đời sau."},{"who":"me","text":"Muốn để lại dung nhan đẹp, {xung} hiểu. Còn chỉ cho {goi} thế nào, để {xung} nghĩ."}]}},
{"id":"j68:j68c-visit-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung mở ra, {A} bước vào, tay áo thoảng hương, nàng nắm chặt tay ngươi, mắt sáng rỡ như kể một chuyện kỳ."},{"who":"A","text":"{Goi} ơi, {xung} vừa gặp một thầy xem tướng ngoài cổng cung. Ông nói vận {goi} sắp có đổi thay, {goi} có muốn nghe không?"},{"who":"me","text":"Thầy xem tướng bên ngoài cung cấm, lời nói thường nửa thật nửa hư. Nhưng {goi} nói vậy, {xung} lại tò mò."},{"who":"A","text":"Ông ấy nhìn mặt {xung} rồi nhắc đến {goi} trước. {Xung} nghĩ có duyên."},{"who":"me","text":"Duyên hay nợ, nghe rồi mới biết. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-visit-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hũ sứ trắng nằm yên trong ngăn thuốc riêng, {A} ngập ngừng đứng bên ngưỡng cửa, quầng thâm hằn dưới mắt."},{"who":"A","text":"{Goi}, {xung} ngại hỏi Thái y viện, nên mạo muội xin {goi} ít thuốc an thần. Đêm nào {xung} cũng không ngủ được."},{"who":"me","text":"Không ngủ được thì cũng chẳng yên tâm. {Goi} có điều gì đè nặng trong lòng chăng?"},{"who":"A","text":"{Xung} cũng không rõ. Nhắm mắt lại là tiếng gió, tiếng bước chân, tưởng ai cũng đang nhìn mình."},{"who":"me","text":"Chuyện này thật khó nói ra. {Xung} cần nghĩ cách giúp mà không để nàng thấy tủi."}]}},
{"id":"j68:j68c-visit-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Rèm cửa khẽ lay, {A} cúi người thấp, tay ghì chặt phong thư kín dấu son đỏ lạ, giọng hạ xuống thật nhỏ."},{"who":"A","text":"Bẩm, có một nội giám cung khác tìm gặp {goi}, mang thư kín. Hắn nói chỉ trao tận tay, không để lại."},{"who":"me","text":"Phong thư dấu son lạ thế này, hắn có nói là của ai không?"},{"who":"A","text":"Hắn không nói, chỉ bảo {goi} xem thì tự rõ. {Xung} thấy mặt hắn không yên."},{"who":"me","text":"Thư kín không tên, nhận nhẹ thì dễ mà hối khó. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-visit-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cung nữ thở hổn hển chạy tới, trán còn lấm tấm mồ hôi, ánh mắt thấp thỏm nhìn quanh phòng."},{"who":"A","text":"Bẩm, chủ {xung} bị ngặt vì tiền thưởng chưa tới tay, sai {xung} sang vay ít bạc lẻ. Mong {goi} giúp cho."},{"who":"me","text":"Chủ ngươi vốn không phải người hay vay mượn, chắc là gấp lắm rồi."},{"who":"A","text":"Dạ, chủ {xung} nói chỉ cần qua vài hôm, thưởng tới sẽ trả. Chủ sợ mở miệng nên sai {xung} thay."},{"who":"me","text":"Một món bạc lẻ mà thể diện hai cung đều nặng. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-visit-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc nơ lụa đỏ quàng cổ mèo trắng tai đen, {A} bế nó áp vào ngực, giọng nhỏ như sợ làm nó thức giấc."},{"who":"A","text":"{Goi} ơi, ngày mai {xung} phải đi lễ chùa nội cung, không dám mang theo nó. Xin {goi} trông hộ vài hôm."},{"who":"me","text":"Mèo của {goi} cưng như con, mà lại đem gửi sang {xung} sao?"},{"who":"A","text":"Chỉ tin {goi} thôi. Nó hiền, chỉ thích cá và ngủ ngoài nắng."},{"who":"me","text":"Lời nhờ cậy này {xung} không thể từ chối vô cớ. Để {xung} nghĩ cho chu đáo."}]}},
{"id":"j68:j68c-visit-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói bánh quế hoa buộc dây đỏ run nhẹ trong hai tay {A}, nàng đứng rụt rè ngoài ngưỡng cửa, áo còn mới nếp gấp."},{"who":"A","text":"{Goi} ơi, {xung} mới vào cung, chưa biết lệ nào. Xin {goi} chỉ bảo cho, kẻo {xung} lỡ phạm điều gì."},{"who":"me","text":"Mới vào cung mà biết đến thăm hỏi trước, đã là biết lễ rồi. Gói bánh quế này nàng tự làm sao?"},{"who":"A","text":"Dạ, {xung} học theo mẹ, mong {goi} nhận cho thơm thảo. Ở đây mọi thứ lạ lẫm quá."},{"who":"me","text":"Người mới còn bỡ ngỡ, {xung} nhớ ngày đầu mình bước qua cổng cung. Để {xung} nghĩ cách giúp nàng."}]}},
{"id":"j68:j68c-visit-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khay trà bốc khói mỏng, {A} cười ngọt như mật, ánh mắt cứ chốc chốc lại dừng nơi chén trà trước mặt ngươi."},{"who":"A","text":"Dạo này {goi} hồng hào lắm, chắc dùng món gì bổ dưỡng. {Goi} kể {xung} nghe với, hôm nay đã dùng những gì?"},{"who":"me","text":"Chỉ là cơm canh thường ngày thôi. {Goi} hỏi từng món, làm {xung} ngại quá."},{"who":"A","text":"Chị em thân thiết mới hỏi thế. Còn chén trà ấy, {goi} dùng loại nào mà thơm đến vậy?"},{"who":"me","text":"Lời ngọt thì dễ nghe, mà ánh mắt kia {xung} chưa dám xem nhẹ. Nên đáp nàng thế nào, để {xung} nghĩ."}]}},
{"id":"j68:j68c-visit-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bóng chiều hắt qua bình phong, {A} ngồi nghiêng người, ngón tay vuốt nhẹ khăn lụa, giọng khẽ khàng như nhờ vả điều quý."},{"who":"A","text":"{Goi}, cháu {xung} đã đến tuổi. Nghe nói {goi} am hiểu mấy nhà công tử, xin {goi} xem hộ xem có ai hợp không."},{"who":"me","text":"Chuyện hôn sự là chuyện cả đời, {xung} sao dám nói bừa. Cháu {goi} là người thế nào?"},{"who":"A","text":"Cháu {xung} hiền hậu, nết na, chỉ tiếc nhà mình không có người quen biết rộng. {Xung} mới phải nhờ đến {goi}."},{"who":"me","text":"Chữ nhờ này nặng như duyên người. Để {xung} nghĩ cho thấu đáo."}]}},
{"id":"j68:j68c-visit-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ mở ra trên tay nội giám ghi danh, nét mực còn ướt, hắn cúi chào rồi ngước nhìn ngươi dò hỏi."},{"who":"A","text":"{Goi}, {xung} đang ghi danh phi tần để Hoàng thượng triệu thị tẩm. Gần đây thân thể {goi} thế nào, có tiện không?"},{"who":"me","text":"Hoàng thượng triệu thì {xung} biết phận. Nhưng {goi} hỏi riêng, hẳn là còn có ý nhắc."},{"who":"A","text":"{Xung} chỉ ghi theo sổ. Có phi tần sẵn sàng, có phi tần xin hoãn, {xung} chỉ biết ghi lại."},{"who":"me","text":"Một lời đáp ghi vào sổ, là một đường đi. {Xung} cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-visit-017","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nội giám cung Thái hậu cúi chào ngoài cổng, giọng đều đều như tiếng chuông xa, truyền xong lời thì đứng lặng chờ."},{"who":"M","text":"{Goi}, nội giám vừa truyền lời: Thái hậu muốn gặp {goi} ngay sau bữa trưa, dặn nên ăn mặc chỉnh tề, còn việc gì thì chưa nói."},{"who":"me","text":"Ngay sau bữa trưa sao? Triệu mà không nói việc, không biết Thái hậu đang vui hay đang giận."},{"who":"M","text":"Nội giám vẫn đứng chờ ngoài cổng đợi {goi} đáp lời. Xin {goi} đừng để chậm trễ."},{"who":"me","text":"Lòng người khó yên khi chưa rõ ý bề trên. Ta cần nghĩ nên chuẩn bị thế nào cho phải."}]}},
{"id":"j68:j68c-visit-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây đàn nhỏ ôm trong tay nhạc sư, bản phổ chép trên giấy tơ cuộn tròn, mồ hôi lấm tấm nơi trán vì hồi hộp."},{"who":"A","text":"Bẩm {goi}, {xung} mới soạn một khúc, chưa dám tấu ở điện. Xin {goi} nghe thử, nếu {goi} chưa gật đầu, {xung} không dám tấu."},{"who":"me","text":"Khúc mới soạn mà đã đem đến nghe trước, nhạc sư thật cẩn trọng. Bản phổ này tên gọi là gì?"},{"who":"A","text":"Là khúc tả một đêm trăng trên mặt nước. {Xung} soạn trong ba tháng, còn nhiều chỗ chưa vừa ý."},{"who":"me","text":"Một khúc nhạc cũng là một tấm lòng. Để {xung} nghĩ xem nên góp ý ra sao."}]}},
{"id":"j68:j68c-visit-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giấy lụa cuộn tròn dưới nách họa sư, hộp màu còn thoảng mùi thuốc vẽ, người nghiêng mình cung kính chờ đợi."},{"who":"A","text":"Cung đình cần chân dung các phi tần để treo ở thư các. {Xung} xin phép {goi} cho được vẽ một bức."},{"who":"me","text":"Chân dung treo ở thư các, người đời sau nhìn vào sẽ nhớ mình thế nào. Đó là chuyện không nhỏ."},{"who":"A","text":"{Xung} sẽ vẽ hết sức, nét bút đi từ tâm. Bức mới vẽ còn phơi ở xưởng họa, {goi} có thể xem trước."},{"who":"me","text":"Một bức tranh lưu lại cả dung nhan lẫn tâm tình. Để {xung} nghĩ cho chu đáo."}]}},
{"id":"j68:j68c-visit-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giỏ mây lót lá chuối đựng đầy trái cây quê, {A} đứng ngoài cửa, tà áo vải giản dị, chưa dám bước qua ngưỡng."},{"who":"A","text":"{Goi}, {xung} đã được thả ra khỏi cung, hôm nay mới dám quay lại thăm. Trái cây quê, không đáng gì, mong {goi} nhận cho."},{"who":"me","text":"Ngươi theo ta bao nhiêu năm, nay quay lại, ta mừng lắm. Vào đi, đứng ngoài làm gì."},{"who":"A","text":"{Xung} sợ làm phiền. Ngoài kia cuộc sống bình thường, nhưng {xung} cứ nhớ cung này."},{"who":"me","text":"Chữ nhớ ấy ta hiểu. Để ta nghĩ xem nên đối đãi với ngươi ra sao."}]}},
{"id":"j68:j68c-visit-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tà áo nhỏ đứng ngập ngừng nơi cửa, hai tay xoắn lấy nhau, {A} cúi gằm không dám nhìn thẳng."},{"who":"A","text":"{Goi}, con phân vân quá. Nên theo thầy học sách, hay theo ma ma học thêu thùa? Thầy dạy hay, nhưng con thích thêu hơn."},{"who":"me","text":"Con thích thêu hơn, vì sao vậy? Con ngẩng lên, nói thật với {xung}."},{"who":"A","text":"Vì thêu thì con làm ra được thứ đẹp, còn sách thì con chỉ đọc. Con sợ nói ra thầy buồn."},{"who":"me","text":"Con biết nghĩ cho người khác, {xung} vui lắm. Để {xung} nghĩ xem nên giúp con thế nào."}]}},
{"id":"j68:j68c-visit-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây tỳ bà gỗ tử đàn dựa nơi giá, bầu đàn khắc hoa văn riêng của cung ngươi ánh lên dưới nắng chiều, {A} bước vào nhìn nó không rời."},{"who":"A","text":"{Goi}, đàn của {xung} mới đứt dây. Xin {goi} cho mượn tỳ bà để tập khúc cho yến sắp tới."},{"who":"me","text":"Yến sắp tới mà đàn lại đứt, thật là không đúng lúc. Cây này {xung} quý lắm."},{"who":"A","text":"{Xung} biết nó quý, nên mới đến hỏi trước. {Xung} sẽ giữ gìn như của riêng."},{"who":"me","text":"Mượn đàn như mượn tiếng lòng. {Xung} cần nghĩ xem nên cho mượn thế nào."}]}},
{"id":"j68:j68c-visit-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh cửa vừa khép, then cài còn kêu khẽ, {A} thở ra như vừa chạy một quãng dài, mắt đảo nhìn bốn phía."},{"who":"A","text":"{Goi}, {xung} phải nói nhỏ. Vừa nãy {xung} nghe lỏm có người đang bàn cách làm khó {goi} nơi buổi yến tới."},{"who":"me","text":"Khóa cửa mới nói, chắc không phải chuyện nhỏ. {Goi} nghe ai bàn, bàn những gì?"},{"who":"A","text":"{Xung} chỉ nghe được nửa chừng, nhưng giọng rất quen. {Xung} sợ nói ra mà {goi} không tin."},{"who":"me","text":"Lời đã nói ra là lời nặng. Để {xung} nghĩ xem nên làm gì cho yên."}]}},
{"id":"j68:j68c-visit-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sương khuya còn đọng trên giàn hoa, {A} đứng ngoài hiên, mắt thỉnh thoảng liếc ra phía vườn tối."},{"who":"A","text":"Bẩm {goi}, mấy hôm nay {xung} thấy một bóng người lạ lảng vảng sau vườn cung. Hễ {xung} ngó ra là biến mất."},{"who":"me","text":"Bóng người lạ sau vườn cung ư? Ngươi có nhìn rõ hình dáng, hay chỉ thấy thoáng qua?"},{"who":"A","text":"Chỉ thấy thoáng thôi ạ. Nhưng {xung} nhớ là đêm nào cũng giờ ấy, như thể quen đường."},{"who":"me","text":"Quen đường tức là biết rõ cung ta. Ta cần nghĩ nên xử trí ra sao."}]}},
{"id":"j68:j68c-visit-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén trà bên bàn đã nguội, {A} vân vê khăn tay, mắt đỏ hoe như vừa mất ngủ mấy đêm."},{"who":"A","text":"{Goi}, {xung} giận {B} mấy hôm nay, mà không biết mở lời thế nào. Xin {goi} sang thưa với nàng một lời hòa giải."},{"who":"me","text":"Hai người giận nhau mấy hôm, hẳn trong lòng ai cũng nặng. {Goi} giận vì chuyện gì vậy?"},{"who":"A","text":"Chỉ vì một lời lỡ miệng, mà lời nào nói ra cũng thành gai. Giờ {xung} nhớ nàng, mà không dám nhìn mặt."},{"who":"me","text":"Một lời lỡ miệng mà kéo dài như vậy, thật đáng tiếc. Để {xung} nghĩ cho phải đạo."}]}},
{"id":"j68:j68c-visit-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bó hương buộc dây vàng thoảng mùi trầm, từ chùa nội cung mang về, {A} nâng hai tay như nâng báu vật."},{"who":"A","text":"{Goi}, đây là bó hương thượng phẩm cầu duyên. {Xung} xin {goi} cắm ở đầu giường vài hôm, linh nghiệm lắm."},{"who":"me","text":"Bó hương cầu duyên, mà lại đến tay {xung}. Chùa nội cung có nhiều người cầu mà sao {goi} chọn mang cho {xung}?"},{"who":"A","text":"Vì {xung} tin {goi} có phúc. Có phúc thì hương mới có chỗ đậu."},{"who":"me","text":"Lời nói khéo mà tấm lòng thật. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-visit-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tà áo cung nữ lấm bụi đường, {A} quỳ xuống thật chậm, tay ép sát nền gạch, giọng nghèn nghẹn."},{"who":"A","text":"Bẩm, {xung} hầu cung khác đã mấy năm, chủ cũ lạnh nhạt hết sức. Xin {goi} cho {xung} sang làm việc ở cung này."},{"who":"me","text":"Ngươi đã hầu mấy năm mà bỏ đi, chắc có nỗi khổ. Chủ cũ ngươi đối xử thế nào?"},{"who":"A","text":"{Xung} không dám nói xấu chủ cũ. Chỉ xin {goi} cho một chỗ nương thân, {xung} sẽ làm việc hết lòng."},{"who":"me","text":"Người xin chỗ nương thân, ta không thể làm ngơ. Nhưng nên quyết thế nào, để ta nghĩ."}]}},
{"id":"j68:j68c-visit-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi trà vừa bay, {A} ngồi bên cửa sổ, ánh mắt thả vào khoảng sân yên tĩnh, không hề nhắc việc cung."},{"who":"A","text":"Hôm nay {xung} chỉ muốn ngồi uống trà, nói chuyện thơ ca với {goi}. Việc cung, {xung} không muốn nhắc."},{"who":"me","text":"Chuyện thơ ca thì hợp với buổi chiều thế này. Bài nào {goi} thuộc, đọc cho {xung} nghe thử."},{"who":"A","text":"Có bài thơ nói về cánh chim bay về núi, {xung} nghĩ mãi không hết. Giữa cung cấm, chỉ ở đây {xung} thấy thở được."},{"who":"me","text":"Một người tìm chỗ thở, mà tìm đến cung {xung}. Để {xung} nghĩ xem nên cùng nàng ra sao."}]}},
{"id":"j68:j68c-visit-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tập sổ bổng lễ kẹp dưới nách, {A} đứng thẳng ngoài cửa, mồ hôi còn đọng nơi thái dương vì đi qua bao nhiêu cung."},{"who":"A","text":"Bẩm, {xung} từ Nội vụ phủ mang bổng lễ ngày tết đến cung {goi}. Xin {goi} ký nhận."},{"who":"me","text":"Lễ tết đã đến, năm cũ sắp hết rồi. Ngươi đi nhiều cung, mệt lắm phải không?"},{"who":"A","text":"Dạ, còn nhiều cung chưa tới. Nhưng việc là việc, {xung} không dám nề hà."},{"who":"me","text":"Thấy ngươi mệt mà vẫn giữ lễ, ta cũng ái ngại. Để ta nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-visit-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai bàn tay {A} áp nhẹ lên bụng, đôi mắt long lanh như hồ thu, bước chân nhẹ như gió vào xuân."},{"who":"A","text":"{Goi}, {xung} vừa biết tin vui. {Xung} muốn nói cho {goi} trước nhất, trước cả khi báo với Hoàng thượng."},{"who":"me","text":"Tin vui thế này mà đến nói với {xung} trước, {xung} cảm động lắm. Mừng cho {goi}."},{"who":"A","text":"Lòng {xung} vừa mừng vừa sợ. Con đường phía trước còn nhiều gió, {xung} chỉ biết nhờ {goi} cầm tay."},{"who":"me","text":"Vừa mừng vừa lo, ai làm mẹ cũng thế. {Xung} cần nghĩ xem nên đáp nàng thế nào."}]}},
{"id":"j68:j68c-visit-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con dấu quan huyện đỏ như son trên tờ giấy, {A} đặt nó trước mặt ngươi, mỉm cười nhẹ như chẳng có gì."},{"who":"A","text":"{Goi}, đây là tờ giấy chuyển nhượng một mảnh đất quê cho cháu {xung}. Xin {goi} ký làm chứng, chỉ là thủ tục nhỏ thôi."},{"who":"me","text":"Thủ tục nhỏ mà cần người làm chứng, hẳn có điều phải cẩn thận. Mảnh đất ấy ở đâu?"},{"who":"A","text":"Ở quê {xung}, đất nhà ông bà để lại. {Xung} muốn giao cho cháu trước khi quá muộn."},{"who":"me","text":"Chữ ký là chữ nặng, ký rồi không rút lại được. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-visit-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nửa đêm, tiếng gõ cửa dồn dập, {A} đứng ngoài hiên, tóc rối, mặt phờ phạc như vừa chạy khỏi cơn ác mộng."},{"who":"A","text":"{Goi}, cho {xung} vào. {Xung} không tiện về cung, vì nghe có người đang chờ {xung} ngoài ấy."},{"who":"me","text":"Nửa đêm gõ cửa, nhìn mặt {goi} thế này, chuyện chắc không nhỏ. Ai chờ {goi}?"},{"who":"A","text":"{Xung} không dám nói chắc. Chỉ nghe thấy tiếng bước chân, và {xung} sợ lắm."},{"who":"me","text":"Một người sợ đến mức không dám về cung, {xung} không thể làm ngơ. Để {xung} nghĩ cho phải."}]}},
{"id":"j68:j68c-visit-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chậu lan hồ điệp nở bông đầu, nhãn gỗ cắm trong chậu ghi tên giống, {A} bưng bằng hai tay như bưng cả một mùa xuân."},{"who":"A","text":"{Goi} ơi, lan này vừa nở bông đầu. {Xung} không nỡ tặng ai khác, vì trong cung chỉ có {goi} hiểu hoa."},{"who":"me","text":"Lan hồ điệp mà nở bông đầu thì khó nuôi lắm. {Goi} tặng {xung}, {xung} cảm kích vô cùng."},{"who":"A","text":"Chỉ cần {goi} đặt nó ở nơi có nắng dịu, tưới ít nước, lan sẽ biết tìm người hiểu mình."},{"who":"me","text":"Một chậu hoa chứa cả tấm lòng. Để {xung} nghĩ xem nên nhận thế nào cho trọn tình."}]}},
{"id":"j68:j68c-visit-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén sứ còn nguyên dấu niêm đặt trên khay, {A} khép cửa nhẹ nhàng, ánh mắt đảo quanh trước khi cất lời."},{"who":"A","text":"Bẩm {goi}, chén trà biếu mà {goi} gửi đi, {xung} đã nghiệm xong. Còn có điều muốn dặn riêng, xin {goi} cho người lui."},{"who":"me","text":"Nghiệm xong rồi sao? Nhìn ngươi dè dặt thế này, ta đoán kết quả không đơn giản."},{"who":"A","text":"{Xung} không dám nói bừa trước đông người. Điều này liên quan đến người đã gửi chén trà."},{"who":"me","text":"Ngươi đã nói đến mức ấy, ta không thể làm ngơ. Để ta nghĩ nên nghe thế nào cho an toàn."}]}},
{"id":"j68:j68c-visit-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vạt áo {A} thoảng hương nhài, nàng đứng trước cửa cung, nụ cười nhã nhặn như đã tính trước mọi lời."},{"who":"A","text":"{Goi} ơi, chiều nay sang cung {xung} dự tiệc trà nhỏ nhé. Chỉ có vài người thân cận thôi, không ồn ào."},{"who":"me","text":"Tiệc trà nhỏ giữa chiều muộn thì dễ chịu. Nhưng {goi} sao lại nhớ mời {xung} trước tiên?"},{"who":"A","text":"Vì {xung} muốn ngồi cùng người hợp ý. Trà mới hái, bánh còn nóng, chỉ thiếu {goi} thôi."},{"who":"me","text":"Lời mời khéo như thế, {xung} khó từ chối. Còn đi hay không, để {xung} nghĩ cho chín."}]}},
{"id":"j68:j68c-visit-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ dày bìa dấu Nội vụ phủ mở sẵn trên tay nội giám, những người đi cùng đứng xếp hàng ngoài sân."},{"who":"A","text":"Bẩm {goi}, theo lệ cuối năm, {xung} đến kiểm kê đồ dùng trong cung. Mong {goi} thứ lỗi vì đột ngột."},{"who":"me","text":"Lệ cuối năm thì {xung} biết. Đồ cung này không nhiều, nhưng mỗi món đều có chỗ cất."},{"who":"A","text":"Sổ ghi đủ từng món, {xung} chỉ đối chiếu. Xin {goi} chớ lo, {xung} sẽ cẩn thận."},{"who":"me","text":"Kiểm kê là việc công, nhưng tay ai chạm vào đồ cung cũng khiến lòng người xao động. Để {xung} nghĩ cách tiếp."}]}},
{"id":"j68:j68c-visit-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước hiên, {A} đứng đó, người gầy hẳn đi, quầng mắt sâu hoắm, giọng khẽ như thể sợ làm ồn chiều thu."},{"who":"A","text":"{Goi}, đã lâu không ai ngó tới {xung}. Hôm nay {xung} chỉ muốn ngồi nhờ chỗ {goi} một chút, cho đỡ trống vắng."},{"who":"me","text":"Ngồi nhờ cũng được, không phải ngại. Nhìn {goi} gầy thế này, {xung} xót lắm."},{"who":"A","text":"Người ta tránh {xung} như tránh gió độc. Chỉ {goi} không đóng cửa."},{"who":"me","text":"Cửa cung mở rộng, nhưng thị phi thì ai cũng sợ. Để {xung} nghĩ cách giữ cả tình lẫn thân."}]}},
{"id":"j68:j68c-visit-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp trâm ngọc bích đậy nắp, dấu Nội vụ phủ đỏ tươi, {A} cúi người dâng bằng hai tay, giọng mật ngọt."},{"who":"A","text":"Bẩm {goi}, đây là ân điển của Hoàng hậu, ban hộp trâm ngọc bích. Xin {goi} nhận cho trọn lễ."},{"who":"me","text":"Hoàng hậu chu đáo như thế, {xung} cảm kích. Nhưng {goi} nói ngọt quá, làm {xung} phải nghĩ nhiều."},{"who":"A","text":"{Xung} chỉ truyền lời. Ngọc quý, lòng Hoàng hậu càng quý, xin {goi} đừng nghi ngại."},{"who":"me","text":"Lễ ban của bề trên không thể từ chối bừa. Để {xung} nghĩ xem nên nhận thế nào cho an."}]}},
{"id":"j68:j68c-visit-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang nội cung chằng chịt lối rẽ, sứ thần đứng thở dốc, áo choàng xứ xa còn vương bụi đường, mắt tò mò nhìn quanh."},{"who":"A","text":"Cung nhân của {goi} vừa chỉ đường cho {xung}, may mà gặp. {Xung} đi lạc vòng quanh hành lang đã hồi lâu rồi."},{"who":"me","text":"Nội cung vốn lắm lối rẽ, người lạ lạc cũng là lẽ thường. Mời ngồi nghỉ một chút."},{"who":"A","text":"Cảm tạ {goi}. Cung đình quý quốc quả là rộng lớn, {xung} đi mãi chẳng thấy điểm cuối."},{"who":"me","text":"Khách từ xa mà gặp nhau, cũng là duyên. Để {xung} nghĩ cách tiếp cho phải lễ."}]}},
{"id":"j68:j68c-visit-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ giấy trắng nét chữ non nằm trong tay {A}, con bé đứng thẳng như cột, cái miệng nhỏ mím chặt vì hồi hộp."},{"who":"A","text":"{Goi} ơi, thầy khen chữ của con đẹp. Con viết suốt cả buổi, không lem một nét nào."},{"who":"me","text":"Cho {xung} xem nào. Nét chữ non mà đều, nhìn là biết con đã chăm."},{"who":"A","text":"Thầy bảo con chịu khó. Con muốn {goi} xem trước tiên, rồi mới cất vào hộp."},{"who":"me","text":"Con ngoan, đợi một chút. {Xung} nghĩ xem nên thưởng con thế nào cho xứng."}]}},
{"id":"j68:j68c-visit-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung vừa mở, {A} bước vào, mắt dán xuống nền gạch, không nhìn ngươi lấy một lần, giọng khô như lá thu."},{"who":"A","text":"{Xung} chỉ muốn nói một chuyện, nói xong sẽ đi ngay. Xin {goi} đừng ngắt lời."},{"who":"me","text":"Giữa chúng ta vốn có hiềm khích, mà {goi} vẫn đến tận cung {xung}. Chuyện ấy chắc không nhỏ."},{"who":"A","text":"Chuyện này liên quan đến cả hai, {xung} không còn cách nào khác. Việc cũ xin gác lại một bên."},{"who":"me","text":"Gác việc cũ lại, nghe việc mới, {xung} sẽ cân nhắc. Để {xung} nghĩ xem nên tiếp thế nào."}]}},
{"id":"j68:j68c-visit-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm thất tịch, trăng sáng như lụa, chén nước đặt trên bậc thềm lấp lánh dưới ánh đèn, {A} cầm cây kim bạc, mắt rạng rỡ."},{"who":"A","text":"{Goi} ơi, tối nay thất tịch, ra sân gieo kim cầu khéo tay cùng {xung} đi. Bóng kim chìm xuống chén nước, xem hình gì hiện ra."},{"who":"me","text":"Nghe nói bóng kim hình hoa thì khéo tay, hình cây búa thì vụng. {Goi} đã thử chưa?"},{"who":"A","text":"Chưa dám thử một mình. Có {goi} bên cạnh, {xung} mới thấy vui."},{"who":"me","text":"Đêm đẹp như vậy, bỏ qua cũng tiếc. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-visit-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gian ngoài vắng lặng, {A} khẽ nhìn quanh, ánh mắt dừng nơi {M} đang lau bàn rồi quay sang ngươi, giọng ngập ngừng."},{"who":"A","text":"{Goi}, cung {xung} đang ngặt người. {Xung} xin mượn cung nữ giỏi nhất của {goi} mấy hôm, hứa sẽ trả lại nguyên vẹn."},{"who":"me","text":"Cung nữ giỏi nhất của {xung} cũng là người {xung} dùng quen. Mượn mấy hôm là mấy hôm?"},{"who":"A","text":"Chỉ chừng ấy việc là xong. {Xung} không dám làm khó người của {goi}, sẽ đối đãi thật tử tế."},{"who":"me","text":"Mượn người cũng là mượn lòng. Để {xung} nghĩ xem nên đáp thế nào cho thỏa."}]}},
{"id":"j68:j68c-visit-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi thuốc dưỡng thoang thoảng theo túi vải, {A} vừa từ cung Thái hậu trở về, bước chân chậm mà ánh mắt tinh tường."},{"who":"A","text":"{Goi}, {xung} vừa từ cung Thái hậu về, ghé qua mang chút thuốc dưỡng. Tiện thể kể {goi} nghe tình hình Thái hậu dạo này."},{"who":"me","text":"{Goi} chu đáo quá. Thái hậu dạo này ra sao, có điều gì vui buồn không?"},{"who":"A","text":"Người vẫn khỏe, chỉ là gió xuân làm đầu hơi nặng. Người hay nhắc tới những ai đã hành lễ cẩn thận."},{"who":"me","text":"Một lời nhắc của Thái hậu mà lòng {xung} xao động. Để {xung} nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-visit-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân, tiếng lớn của {A} vang cả hành lang, vài cung nhân ngoái nhìn, ánh mắt tò mò lẫn e dè."},{"who":"A","text":"Cung nhân của {goi} còn nợ cung {xung} khoản bạc chưa trả. {Xung} đến đòi, mong {goi} phân xử cho."},{"who":"me","text":"Khoản bạc nào, bao giờ vay, ngươi nói rõ ta nghe. Đừng lớn tiếng giữa sân thế này."},{"who":"A","text":"Phải lớn tiếng thì mới có người nghe. Chủ {xung} đang chờ bạc để dùng."},{"who":"me","text":"Giữa sân đông người, nói sao cho khỏi mất thể diện cả hai bên, ta cần nghĩ."}]}},
{"id":"j68:j68c-visit-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Căn phòng nhỏ tối nhẹ, nhũ mẫu bế đứa trẻ trong tay, quầng mắt thâm sâu như chưa chợp mắt từ mấy đêm."},{"who":"A","text":"Bẩm {goi}, dạo này đứa nhỏ ăn ít, đêm hay giật mình. {Xung} nghĩ nên nghe lời {goi} để chăm cho đúng."},{"who":"me","text":"Đứa nhỏ ăn ít, hay giật mình, {goi} thấy từ khi nào?"},{"who":"A","text":"Chừng bốn năm hôm nay. {Xung} đã thử ru, thử hát, nhưng không hết."},{"who":"me","text":"Con trẻ giật mình khiến lòng người mẹ đau thắt. Để {xung} nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-visit-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp sơn mài dấu cung khác nằm trên tay {A}, nàng đứng sát cửa, mắt liếc ra ngoài như sợ ai rình."},{"who":"A","text":"Bẩm, có một người từ cung bên nhờ {xung} chuyển hộp thuốc cao thơm kèm lời nhắn. Nhưng người ấy lấm lét, {xung} không dám nhận thay."},{"who":"me","text":"Người ấy lấm lét thế nào? Ngươi nhớ mặt hay tên không?"},{"who":"A","text":"{Xung} nhớ dáng đi, và dấu trên hộp là của cung bên. Chỉ không biết lời nhắn là gì."},{"who":"me","text":"Ngươi thận trọng là phải. Hộp thuốc của người lạ, nhận hay không, ta cần nghĩ."}]}},
{"id":"j68:j68c-visit-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai bàn tay run run đan vào nhau, {A} đứng giữa gian phòng, thở một hơi dài như thể đã nuốt hết dũng khí."},{"who":"A","text":"{Goi} ơi, {xung} lần đầu được triệu, tay run mãi chẳng thôi. {Xung} không có mẹ bên cạnh dặn dò, nên đến xin {goi} chỉ giúp đôi điều."},{"who":"me","text":"Lần đầu ai cũng hồi hộp, {goi} không phải thấy xấu hổ. Nói cho {xung} nghe, {goi} sợ điều gì nhất?"},{"who":"A","text":"Sợ nói sai, sợ làm sai, sợ cả ánh mắt Hoàng thượng. {Xung} chẳng biết phải đứng thế nào."},{"who":"me","text":"Một người nhờ cậy lòng chân thành như vậy, {xung} không nỡ từ chối. Để {xung} nghĩ cách giúp nàng."}]}},
{"id":"j68:j68c-visit-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp y cụ đặt trên bàn, {A} ngồi ngay ngắn, giọng nhã nhặn như lời thăm hỏi quen thuộc của tiết trời."},{"who":"A","text":"{Xung} đến theo lệnh Hoàng thượng, khám định kỳ cho các phi tần. {Goi} dạo này ăn ngủ ra sao?"},{"who":"me","text":"Ăn cũng được, nhưng ngủ thì chập chờn. Có đêm tỉnh dậy, trong lòng nặng nề không rõ vì sao."},{"who":"A","text":"Giấc ngủ chập chờn thì thân thể cũng yếu theo. {Goi} cứ nói thật, {xung} mới bốc thuốc đúng bệnh."},{"who":"me","text":"Nói thật bao nhiêu, nói nhẹ bao nhiêu, {xung} cần cân nhắc."}]}},
{"id":"j68:j68c-visit-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một bó vải gấm đủ màu ôm trên tay {A}, dải vải còn nguyên dấu thợ dệt kinh thành, ánh mắt ngơ ngác nhìn quanh phòng lạ."},{"who":"A","text":"Cho hỏi, đây có phải cung mà {xung} cần tới không? Bó vải này xin {goi} xem giúp, mẫu nào hợp nhất."},{"who":"me","text":"Màu sắc đẹp lắm, nhưng {goi} có vẻ nhầm cung rồi. Cung này đâu có cần may áo."},{"who":"A","text":"Ôi, {xung} mới đến, đi mãi chẳng phân biệt được cung nào với cung nào. Thật xấu hổ quá."},{"who":"me","text":"Người mới nhầm cung cũng là chuyện thường. Để {xung} nghĩ xem nên giúp nàng thế nào."}]}},
{"id":"j68:j68c-visit-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thái hậu thân hành bước vào, không ai báo trước, ánh mắt quét một vòng qua bài trí cung, rèm, bình hoa, giá sách."},{"who":"A","text":"Dạo này con đọc sách gì? {Xung} thấy giá sách ở đây nhiều quyển lạ."},{"who":"me","text":"Dạ, thưa Thái hậu, {xung} đọc nhiều thứ, có sách cũ, có sách mới, mỗi quyển một ý riêng."},{"who":"A","text":"Mỗi quyển một ý. Thế thì quyển nào con thích nhất, nói {xung} nghe thử."},{"who":"me","text":"Câu hỏi của Thái hậu nhẹ mà ý sâu. {Xung} cần suy nghĩ cho kỹ trước khi thưa."}]}},
{"id":"j68:j68c-visit-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ hoa tiên trải trên án, nghiên mực đã mài sẵn, {A} đọc từng câu, ngập ngừng như sợ chữ chẳng đủ nói lòng."},{"who":"A","text":"{Goi}, {xung} không giỏi chữ, xin {goi} viết thư gửi mẹ {xung} giúp. {Xung} đọc, {goi} chép nhé."},{"who":"me","text":"Thư gửi mẹ là chuyện thiêng liêng, {xung} sẵn lòng. Mẹ nàng hẳn mong tin lắm."},{"who":"A","text":"Thưa mẹ, con ở đây bình an, mẹ chớ lo. Còn lại thì {goi} thêm bớt giúp {xung}."},{"who":"me","text":"Nội dung thư là tâm sự của nàng, viết sao cho đúng ý mà vẫn hay, để {xung} nghĩ."}]}},
{"id":"j68:j68c-visit-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nến chập chờn, {A} ghé sát tai ngươi, hơi thở nhẹ như làn khói, đôi mắt nhìn chăm chú."},{"who":"A","text":"{Goi}, cha {xung} vừa báo, trong triều có biến, một đại thần bị khiển trách. Nhà {goi} hình như có dây dưa."},{"who":"me","text":"Dây dưa thế nào? Cha {goi} nói gì cụ thể, {goi} nhớ được bao nhiêu?"},{"who":"A","text":"{Xung} chỉ nghe loáng thoáng. Nhưng {xung} thấy cần báo cho {goi} trước khi tin lan ra."},{"who":"me","text":"Một tin như vậy nặng hơn núi. {Xung} cần suy nghĩ nên đối đãi thế nào."}]}},
{"id":"j68:j68c-visit-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trà đã dọn, {A} ngồi xuống nhưng không chạm chén, ánh mắt giận dỗi hướng ra ngoài song cửa."},{"who":"A","text":"Gần đây {goi} hay đi lại với {B} mà ít ghé cung {xung}. {Goi} có phải coi {xung} nhẹ không?"},{"who":"me","text":"{Goi} nói thế, {xung} nghe mà nhói lòng. {Xung} không hề có ý đó."},{"who":"A","text":"Nói không có thì dễ, mà {xung} đếm từng ngày {goi} không sang. Thật tủi thân."},{"who":"me","text":"Tủi thân vì thương nhau, {xung} hiểu. Để {xung} nghĩ cách đáp cho phải lẽ."}]}},
{"id":"j68:j68c-visit-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp bánh đậu ngự thiện bọc giấy dấu cung Thái hậu, nội giám cúi người dâng lên, vẻ mặt cung kính."},{"who":"A","text":"Bẩm {goi}, Thái hậu nhớ {goi} sáng nay khi nhìn khay trà, bảo mang hộp bánh này sang cho tròn lễ."},{"who":"me","text":"Thái hậu nhớ đến {xung}, ân điển này nặng lắm. Hộp bánh thơm quá, mùi đậu xanh ấm cả phòng."},{"who":"A","text":"Người dặn {xung} không cần nói nhiều, chỉ cần chuyển đúng ý. {Goi} nhận lấy là được."},{"who":"me","text":"Ân điển của Thái hậu, nhận rồi còn phải đáp. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-visit-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa cung mở ra, {A} dẫn một ông lão phong trần bước vào, giọng tha thiết như giới thiệu bậc trưởng bối."},{"who":"A","text":"{Goi}, đây là bậc bề trên của {xung}, từ xa lên kinh. Mong {goi} tiếp đãi chu đáo, {xung} xin cảm tạ."},{"who":"me","text":"Khách từ xa tới là quý. Bậc trưởng bối đi đường vất vả, xin ngồi nghỉ."},{"who":"A","text":"Ông không quen chốn cung đình, có gì thất lễ, mong {goi} bỏ qua. {Xung} nhờ {goi} giúp đỡ."},{"who":"me","text":"Lời nhờ vả này nặng tình lẫn lễ. Để {xung} nghĩ xem nên tiếp thế nào cho phải."}]}},
{"id":"j68:j68c-visit-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khay mây bày ngổn ngang trâm lược khăn thêu, ánh chiều làm lược sừng chạm hoa lóng lánh, cung nhân quây quanh ngắm nghía."},{"who":"A","text":"Bẩm {goi}, người bán hàng rong vào cung theo lệ, {xung} dẫn đến đây. Hàng của ông ấy đủ loại, cung nhân ai cũng thích."},{"who":"me","text":"Lược sừng chạm hoa này tinh xảo thật. Người bán nói giá bao nhiêu?"},{"who":"A","text":"Ông ấy nói còn tùy người mua. Chủ cung mua thì cung nhân cũng đỡ ngại."},{"who":"me","text":"Một khay hàng hóa mà thành chuyện chung của cả cung. Để {xung} nghĩ xem nên mua thế nào."}]}},
{"id":"j68:j68c-visit-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa cung, {A} quỳ thật thấp, trán sát nền gạch, giọng nghẹn như đã khóc rất nhiều đêm."},{"who":"A","text":"Xin {goi} tha cho {M} một lần. {M} lỡ làm đổ trà trước Hoàng hậu, bị phạt nặng lắm rồi."},{"who":"me","text":"{M} làm đổ trà trước Hoàng hậu sao? Tội ấy không nhỏ, nhưng ngươi quỳ thế này, ta nhìn mà không đành."},{"who":"A","text":"{M} tuổi còn trẻ, tay chân vụng về, không có ý bất kính. {Xung} xin thay {M} chịu thêm cũng được."},{"who":"me","text":"Một lời xin tha dứt khoát đến thế, ta cần cân nhắc cho phải."}]}},
{"id":"j68:j68c-visit-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên mái ngói, tiếng gỗ gãy rôm rốp vang lên, bụi rơi lả tả, {A} đứng dưới sân ngửa cổ nhìn, mặt tái đi."},{"who":"A","text":"Bẩm {goi}, thợ do Nội vụ phủ cử đến, mới nửa buổi đã nghe tiếng gỗ gãy. {Xung} sợ mái hỏng thêm."},{"who":"me","text":"Mới nửa buổi mà làm gãy gỗ, {goi} có nhìn thấy họ làm thế nào không?"},{"who":"A","text":"{Xung} thấy họ dẫm lên rường cột như thể đất bằng, chẳng cẩn thận chút nào."},{"who":"me","text":"Mái cung hỏng thì mưa dột, người hại là {xung}. Để {xung} nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-visit-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khung tre dán giấy đỏ phồng lên như thân cá chép, {A} giơ chiếc lồng đèn lên cao, ánh mắt tự hào."},{"who":"A","text":"{Goi} xem, lồng đèn cá chép {xung} tự làm cho đêm rước đèn. {Goi} định treo đèn gì?"},{"who":"me","text":"Cá chép đỏ thế này, vảy từng chiếc đều tăm tắp. Khéo tay như {goi}, {xung} phải học."},{"who":"A","text":"Chỉ là {xung} rảnh rỗi thôi. Nhưng đêm rước đèn mà không có đèn thì buồn, {goi} nhỉ?"},{"who":"me","text":"Đêm rước đèn là đêm vui của cả cung. {Xung} cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-visit-061","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cung nữ chạy sang, thở hổn hển, đứng sát cạnh ngươi, giọng nhỏ như gió lùa dưới khe cửa."},{"who":"A","text":"Bẩm {goi}, chủ {xung} vừa giấu một chiếc hộp trong rương. {Xung} nghe tiếng như có người khóc bên trong."},{"who":"me","text":"Tiếng khóc trong hộp ư? {Goi} có nghe rõ, hay chỉ là gió xuyên qua khe rương?"},{"who":"A","text":"{Xung} nghe rõ lắm, như tiếng trẻ nhỏ. {Xung} sợ lắm nên chạy sang bẩm {goi}."},{"who":"me","text":"Chuyện lạ như vậy, nói ra hay giữ lại đều có hậu quả. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-visit-062","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tóc đã điểm sương, lưng còng xuống, {A} quỳ trước ngươi, đôi bàn tay chai sần run run đặt lên đầu gối."},{"who":"A","text":"Bẩm {goi}, {xung} hầu {goi} đã lâu, nay lưng đau chân yếu. {Xung} xin phép ra cung về quê dưỡng già."},{"who":"me","text":"Ngươi theo ta nhiều năm, đâu phải chỉ là người hầu. Ngươi về quê rồi, ta cũng nhớ."},{"who":"A","text":"{Xung} cũng không nỡ rời. Nhưng sức người có hạn, {xung} sợ làm chậm việc của {goi}."},{"who":"me","text":"Một lời xin ra cung chứa cả chặng đường dài. Để ta nghĩ cho vẹn nghĩa."}]}},
{"id":"j68:j68c-visit-063","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bó hoa dại còn đọng sương sớm, cánh nhỏ cánh to không đều, {A} ôm trong tay, mặt hơi đỏ khi nhìn ngươi."},{"who":"A","text":"{Goi}, {xung} tự hái bó hoa dại này, mà cắm thế nào cũng không đẹp. Xin {goi} chỉ cách cho."},{"who":"me","text":"Hoa dại mà hái đúng lúc sương, màu còn tươi nguyên. {Goi} có mắt chọn hoa đấy."},{"who":"A","text":"Nhưng cắm vào bình thì cứ xiêu vẹo. {Xung} chẳng biết sửa thế nào."},{"who":"me","text":"Cắm hoa cũng như đối nhân, cốt ở cái tình. Để {xung} nghĩ xem nên giúp thế nào."}]}},
{"id":"j68:j68c-visit-064","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa phòng khép hờ, {A} liếc nhanh quanh phòng, rồi bước sát lại, hạ giọng như thì thầm với bóng tường."},{"who":"A","text":"{Goi}, hôm qua có một thị vệ trẻ cầm thư lấm lét hỏi thăm cung {goi}. {Xung} đoán là thư ai đó nhờ."},{"who":"me","text":"Thị vệ cầm thư hỏi thăm cung {xung}? Hắn có nói tên ai gửi không?"},{"who":"A","text":"Hắn không nói, chỉ hỏi han vòng vo. {Xung} thấy lạ nên đến báo trước."},{"who":"me","text":"Lời báo của {goi} khiến lòng {xung} xao động. Để {xung} nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-serv-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọn nến sáp ong cháy dở được gói gọn trong khăn, in rõ hoa văn riêng của cung, {M} bắt gặp {A} đang giấu vào tay áo."},{"who":"A","text":"Bẩm {goi}, {xung} nhặt những đoạn nến cháy dở này định đem bán ở chợ đồ cũ ngoài cung, để thêm đồng tiền gửi về nhà."},{"who":"me","text":"Nến sáp ong còn in hoa văn cung này, mang ra chợ là ai cũng biết xuất xứ. Sao ngươi dám liều như vậy?"},{"who":"A","text":"{Xung} biết sai. Nhưng nhà {xung} chỉ trông vào bấy nhiêu, mẹ già lại ốm, {xung} không nỡ nhìn."},{"who":"me","text":"Lòng hiếu thảo của ngươi ta thấy cả. Còn việc này, ta phải liệu sao cho phải phép mà không phụ tình."}]}},
{"id":"j68:j68c-serv-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mép phong thư sờn nhàu dưới gối, nét mực loang nước mắt, mà {A} vẫn quét sân đều đều như chưa có gì xảy ra."},{"who":"A","text":"{Goi}, {xung} vẫn làm việc, {goi} đừng bận lòng. Thư nhà chỉ là chuyện riêng của {xung}."},{"who":"me","text":"{M} đã thấy phong thư báo tang dưới gối ngươi. Người đi rồi, mà ngươi còn đứng quét sân, lòng ngươi nặng thế nào ta hiểu."},{"who":"A","text":"{Xung} sợ khóc thì lỡ việc cung, nên cứ quét cho tay bận, lòng đỡ đau."},{"who":"me","text":"Nỗi đau như thế, giấu đi chẳng nhẹ bớt. Ta cần nghĩ nên giúp ngươi ra sao."}]}},
{"id":"j68:j68c-serv-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương hoa quế còn vương trên môi, vài vụn bánh dính nơi cằm, {A} đứng bên nửa đĩa bánh còn lại, mặt đỏ như gấc."},{"who":"A","text":"Bẩm {goi}, bánh hoa quế này định dâng khách, {xung} lỡ ăn mất nửa đĩa. {Xung} biết lỗi rồi."},{"who":"me","text":"Hôm nay khách đến, ta định đem đĩa bánh này tiếp. Nửa đĩa đã vào bụng ngươi, còn vụn bánh trên cằm kia."},{"who":"A","text":"{Xung} thèm quá, ngửi mùi quế thơm mà không cầm lòng được. Xin {goi} đừng đuổi {xung}."},{"who":"me","text":"Nhìn bộ dạng ngươi, ta vừa giận vừa buồn cười. Việc này ta nghĩ cách xử cho khéo."}]}},
{"id":"j68:j68c-serv-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nước thuốc sẫm màu hơn mọi lần, bát thuốc dưỡng sức còn nóng trên khay, {A} đứng cạnh, bàn tay nắm chặt vạt áo."},{"who":"A","text":"Bẩm {goi}, lúc {M} đi vắng, {xung} thấy có người lạ ghé phòng nấu thuốc. Nước thuốc hôm nay lại có mùi khác lạ."},{"who":"me","text":"Người lạ ghé phòng nấu thuốc, ngươi có nhìn rõ mặt không? Sao đến giờ mới nói?"},{"who":"A","text":"{Xung} sợ nói ra thì bị nghi, mà không nói thì {goi} sắp uống. {Xung} nghĩ mãi mới dám mở lời."},{"who":"me","text":"Ngươi nói ra là đúng. Bát thuốc này ta chưa vội uống, để ta nghĩ cho kỹ."}]}},
{"id":"j68:j68c-serv-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khăn lụa thêu sen nằm gọn trong tay {A}, đường thêu nhỏ tỉ mỉ, kim chỉ còn mới như vừa xong đêm qua."},{"who":"A","text":"Bẩm {goi}, khăn này có người thương {xung} nên đặt cho {xung}. Nhưng {xung} nghĩ chỉ {goi} mới xứng dùng."},{"who":"me","text":"Một bông sen nhỏ thêu khéo thế, ai nỡ nhường cho người khác? Tấm lòng ngươi, ta nhận."},{"who":"A","text":"Khăn đẹp thì phải đến tay người quý. {Xung} chỉ biết hầu hạ, không dám giữ của đẹp."},{"who":"me","text":"Món quà này nặng tình nhẹ vật. Ta cần nghĩ xem nên đáp lại ngươi thế nào."}]}},
{"id":"j68:j68c-serv-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắp hộp son ngọc trai khắc chữ nhỏ tên cung, {A} chỉ tay quả quyết, {B} đứng đó nước mắt lăn dài, môi mím không nói."},{"who":"A","text":"Bẩm {goi}, chính {B} lấy trộm hộp son này giấu đi. {Xung} đã dẫn {M} đến tận nơi, thấy tận mắt."},{"who":"me","text":"{B} cớ gì lại chỉ khóc mà không cãi? Ta lại nghe chỗ giấu rất gần giường ngươi."},{"who":"A","text":"Gần giường {xung} là sự tình cờ thôi ạ. {B} không cãi vì đã nhận tội rồi."},{"who":"me","text":"Nhận tội hay không dám cãi, khác nhau xa. Ta cần cân nhắc cho phải lẽ."}]}},
{"id":"j68:j68c-serv-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén lê hầm đường phèn bốc hơi ấm, mùi lê thơm lan khắp gian phòng, {A} bưng trên tay còn nóng hổi."},{"who":"A","text":"Bẩm {goi}, nghe {goi} ho mấy đêm nay, {xung} hầm riêng chén lê theo bài thuốc của bà nội. Mong {goi} dùng nóng."},{"who":"me","text":"Thái y đã kê thuốc rồi, mà chén lê này lại thơm ngọt lạ thường. Ngươi hầm lúc nào vậy?"},{"who":"A","text":"Từ chạng vạng, {xung} canh lửa nhỏ cho lê nhừ. Chỉ sợ {goi} không nuốt nổi thuốc đắng."},{"who":"me","text":"Một chén lê mà gói trọn tâm ý. Ta cần nghĩ xem nên đón nhận thế nào."}]}},
{"id":"j68:j68c-serv-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Áo choàng thêu trải trên án, ngón tay {B} còn dấu kim chích, đứng nép sau lưng {A} không dám ngẩng đầu."},{"who":"A","text":"Bẩm {goi}, chính {xung} thức đêm khâu xong tấm áo choàng này để dâng khách. {Xung} mong được {goi} ghi nhận."},{"who":"me","text":"Đường kim bên trong áo trái hẳn lối thêu của ngươi. Ta nhìn là biết ai thêu."},{"who":"A","text":"Chắc là {B} phụ giúp vài mũi thôi ạ. Phần lớn là công của {xung}."},{"who":"me","text":"Lời ngươi ta đã nghe. Nhưng ngón tay {B} kia đã nói giùm. Ta cần nghĩ nên xử ra sao."}]}},
{"id":"j68:j68c-serv-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc mũ hổ con đường chỉ đỏ đã bạc màu vì giặt nhiều, {A} ôm vào lòng, mắt dán mãi ra cổng cung phía nam."},{"who":"A","text":"Bẩm {goi}, mũ này con {xung} gửi lại khi {xung} vào cung. {Xung} chỉ nhìn một chút thôi, không dám lơ là việc."},{"who":"me","text":"Mấy hôm nay ngươi làm việc như người mất hồn. Mũ hổ nhỏ xíu thế, hẳn con ngươi còn bé lắm."},{"who":"A","text":"Dạ, mới chập chững biết đi. {Xung} nhớ nó, cứ nhìn ra cổng như thể nó sẽ chạy vào."},{"who":"me","text":"Nỗi nhớ con thì ai cũng hiểu. Ta nghĩ xem nên làm gì cho ngươi đỡ nhớ."}]}},
{"id":"j68:j68c-serv-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắm đất vừa vun dưới gốc cây, một hình nhân gỗ buộc chỉ đỏ lộ ra, {A} run đến mức chiếc xẻng tuột khỏi tay."},{"who":"A","text":"Bẩm {goi}, {xung} đào đất vun hoa thì chạm phải vật này. Hình nhân gỗ buộc chỉ đỏ, chôn ngay trước sân {goi}."},{"who":"me","text":"Hình nhân buộc chỉ đỏ ư? Ngươi có chạm vào nó không, hay chỉ nhìn thấy?"},{"who":"A","text":"{Xung} chỉ chạm một chút thôi ạ. Gỗ có mùi trầm, giống hương cung của {B}."},{"who":"me","text":"Vật này không thể xem nhẹ. Ta cần nghĩ kỹ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-serv-011","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Ngoài hành lang, tiếng cười khúc khích còn chưa dứt, {A} đỏ mặt chạy mất, để lại {B} đứng đó."},{"who":"B","text":"Bẩm {goi}, {A} nói mơ suốt đêm, gọi tên một thị vệ ở cổng đông. {Xung} đã kể cho cả dãy phòng nghe."},{"who":"me","text":"Ngươi kể cho cả dãy phòng, hay chỉ thuật lại chuyện tình cờ nghe thấy?"},{"who":"B","text":"{Xung} chỉ nói đùa thôi, ai ngờ {A} biết chuyện, đỏ mặt chạy đi mất rồi."},{"who":"me","text":"Chuyện vui mà thành chuyện riêng của người khác. Ta cần nghĩ nên xử thế nào."}]}},
{"id":"j68:j68c-serv-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi khói còn vương nơi gian kho cháy sém, hòm đựng thư nhà nắp có dấu cháy xém, {A} ôm chặt trong tay, bàn tay đỏ rát vì bỏng."},{"who":"A","text":"Bẩm {goi}, đêm qua lửa bếp lan sang kho, {xung} lo hòm thư nhà của {goi}, nên vác ra trước. Hòm có sao không ạ?"},{"who":"me","text":"Hòm vẫn còn nguyên, ngươi cầm nó mà tay đã bỏng đỏ thế kia. Sao không nói đau?"},{"who":"A","text":"Chỉ cần hòm còn là {xung} yên tâm. Thư nhà của {goi} là kỷ niệm quý."},{"who":"me","text":"Ngươi lo cho vật của ta hơn cả thân mình. Ta cần nghĩ xem nên đáp đền thế nào."}]}},
{"id":"j68:j68c-serv-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước gương đồng, tà áo lụa hồng đào xoay nhẹ, hương xông còn chưa tan, {A} đỏ mặt khi {M} bước vào."},{"who":"A","text":"Bẩm {goi}, {xung} lén mặc thử áo mới của {goi}. {Xung} biết là sai, nhưng áo đẹp quá, {xung} chưa nỡ cởi ra."},{"who":"me","text":"Áo hồng đào ấy ta mới may, cổ áo còn thơm hương xông. Nhìn ngươi mặc, quả thật hợp."},{"who":"A","text":"{Goi} đừng giận. {Xung} chỉ muốn biết cảm giác mặc áo đẹp một lần cho thỏa."},{"who":"me","text":"Một lần thỏa mộng cũng đáng thương. Việc này ta phải nghĩ cho vẹn đôi bề."}]}},
{"id":"j68:j68c-serv-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc vòng bạc chạm hoa văn cung bên nằm trong lòng bàn tay {A}, nàng đứng giữa hành lang, mắt liếc mãi về phía cửa phòng."},{"who":"A","text":"Bẩm {goi}, {B} sai người đem vòng bạc này biếu {xung}, lại mời {xung} ghé cung chơi ngày rảnh. {Xung} chưa dám nhận."},{"who":"me","text":"Hoa văn ấy là của cung {B}. Sao nàng ta bỗng nhiên tốt với ngươi đến vậy?"},{"who":"A","text":"{Xung} cũng nghĩ thế. Nên mới đứng giữa hành lang, chưa biết nên đi hay ở."},{"who":"me","text":"Quà biếu giữa các cung vốn không đơn giản. Ta cần nghĩ xem nên trả lời ra sao."}]}},
{"id":"j68:j68c-serv-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát mì trường thọ nghi ngút, sợi mì dài nguyên không đứt, hành thái mịn, {A} đứng sau rèm, nói khẽ như sợ phá vỡ yên tĩnh."},{"who":"A","text":"Bẩm {goi}, hôm nay là ngày {goi} vào cung. {Xung} nghĩ {goi} nhớ nhà, nên nấu bát mì này."},{"who":"me","text":"Ngày ta vào cung, đến chính ta còn quên. Ngươi nhớ giùm, thật khiến lòng ta ấm."},{"who":"A","text":"Mì dài, ý chúc {goi} sống lâu. {Xung} chỉ biết nấu món quê thôi, mong {goi} đừng chê."},{"who":"me","text":"Bát mì giản dị mà chan chứa lòng người. Ta nghĩ nên đáp lại ngươi thế nào."}]}},
{"id":"j68:j68c-serv-016","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bộ khay trà sứ men xanh còn nguyên dấu nung của cung, {A} ôm trong tay, đứng sau quản sự mà ngoái nhìn về phía ngươi."},{"who":"B","text":"Bẩm {goi}, Nội vụ phủ sai {xung} đến mượn {A} đi hầu tiệc một buổi. Nàng muốn mang theo bộ khay trà của cung."},{"who":"me","text":"Khay trà ấy mang dấu nung riêng của cung ta. Ngươi mượn người, sao lại mượn cả khay?"},{"who":"B","text":"Tiệc lớn cần khay đẹp, {xung} chỉ phụng mệnh. Nhưng {A} bảo phải hỏi {goi} trước."},{"who":"me","text":"{A} biết phải giữ lễ, ta thấy vui. Còn việc này, để ta nghĩ cho chu toàn."}]}},
{"id":"j68:j68c-serv-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuộn lụa thưởng còn dán phiếu Nội vụ phủ, {A} chạy khắp các phòng báo tin, cung nữ ùa ra chen chúc ngoài cửa."},{"who":"A","text":"Bẩm {goi}, cung {xung} được dâng thêm một cuộn lụa thưởng! {Xung} chạy khắp nơi báo, mừng quá chẳng biết giữ ý."},{"who":"me","text":"Nhìn nét mặt ngươi, ta cũng vui lây. Cuộn lụa ấy ban cho cả cung, không phải riêng ta."},{"who":"A","text":"Nghe tin, ai cũng muốn xem. {Xung} chỉ mong {goi} cho phép mọi người được ngắm một lần."},{"who":"me","text":"Niềm vui lan ra cả cung, thật quý. Ta cần nghĩ xem nên phân thế nào cho vừa lòng cả nhà."}]}},
{"id":"j68:j68c-serv-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói cơm nếp thắt lá chuối kiểu quê được nhấc cao trên tay {A}, {B} co ro nép góc, mắt đỏ hoe, không dám cãi."},{"who":"A","text":"Bẩm {goi}, {xung} bắt gặp {B} ăn cắp cơm của dãy phòng. Gói cơm nếp này chính là tang vật."},{"who":"me","text":"{B} chỉ đứng khóc mà không nói gì. Gói cơm nếp thắt kiểu quê, có thật là của dãy phòng không?"},{"who":"A","text":"{Xung} thấy nàng giấu trong ngực áo, còn chối thế nào được ạ?"},{"who":"me","text":"Một gói cơm nhỏ mà nước mắt lớn như vậy. Ta cần xét cho rõ đầu đuôi."}]}},
{"id":"j68:j68c-serv-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Túi ngải cứu đỏ treo đầy cửa phòng, buộc chỉ ngũ sắc, khói ba nén hương lan cả hành lang, mặt cung nữ ai nấy tái đi."},{"who":"A","text":"Bẩm {goi}, đêm qua {xung} nghe tiếng khóc trong giếng cổ ở góc sân. {Xung} treo ngải cứu, thắp hương, mong yên được lòng người."},{"who":"me","text":"Tiếng khóc trong giếng cổ ư? Ngươi có chắc là tiếng khóc, chứ không phải gió thổi qua thành giếng?"},{"who":"A","text":"{Xung} nghe rõ lắm. Cả cung đều sợ, đêm nào cũng không dám ngủ sâu."},{"who":"me","text":"Lòng người sợ thì lời đồn càng lớn. Ta cần nghĩ xem nên làm thế nào cho cả cung yên."}]}},
{"id":"j68:j68c-serv-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc đèn lồng cũ của cung, nét vẽ hoa mai đã phai, {A} lau từng góc một, bàn tay run run nhưng cẩn thận như xưa."},{"who":"A","text":"Bẩm {goi}, {xung} lau đèn này từ ngày đầu hầu cung. Mắt giờ kém, tay run, quản sự muốn thả {xung} về."},{"who":"me","text":"Ngươi chẳng nói gì, chỉ lặng lẽ lau đèn. Ta quen cái bóng ngươi bên đèn này đã bao năm."},{"who":"A","text":"{Xung} không dám xin xỏ. Chỉ mong {goi} nhớ đến một cung nữ già, từng thắp đèn cho cung này."},{"who":"me","text":"Chữ nhớ ấy nặng tình. Ta cần nghĩ nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-serv-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân gạch, bàn tay {A} chìa ra, đôi hoa tai vàng nhạt lấp lánh trong trí nhớ, {M} đứng sau đỏ mặt thay cho nàng."},{"who":"A","text":"Bẩm {goi}, {goi} từng hứa thưởng {xung} đôi hoa tai vàng nhạt. {Xung} xin nhắc lại, mong {goi} nhớ cho."},{"who":"me","text":"Lõi vàng thật, có khắc ký hiệu thợ, ta nhớ lời hứa ấy. Nhưng đòi ngay giữa sân thế này, ngươi thấy có hợp không?"},{"who":"A","text":"{Xung} biết là không phải lối. Nhưng {xung} chờ đã lâu, sợ {goi} quên."},{"who":"me","text":"Lời hứa phải giữ, nhưng cách đòi cũng cần có phép. Ta cần nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-serv-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khăn lau mồ hôi đường khâu vụng, cạnh vải xơ, nằm bên gối, {A} thức đến sáng, mắt đỏ quầng thâm."},{"who":"A","text":"{Goi} tỉnh rồi ạ? Đêm qua {goi} sốt li bì, {xung} thay khăn lạnh mãi đến sáng mới thấy hạ."},{"who":"me","text":"Khăn lau mồ hôi bên gối đường khâu vụng thế này, là ngươi tự khâu sao?"},{"who":"A","text":"Dạ, vì khăn của cung không đủ mềm. {Xung} sợ {goi} khó chịu nên khâu tạm."},{"who":"me","text":"Đêm dài thức canh, tay vụng mà tấm lòng không vụng. Ta cần nghĩ xem nên thưởng ngươi thế nào."}]}},
{"id":"j68:j68c-serv-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp trầm hương gỗ còn mùi lạ nằm trong tay {A}, nàng run run nhìn ra cửa, nơi bóng thị vệ vừa khuất sau cột."},{"who":"A","text":"Bẩm {goi}, thị vệ lảng vảng ngoài cửa cung đã mấy hôm. Vừa nãy hắn nhét hộp trầm hương này vào tay {xung} rồi biến mất."},{"who":"me","text":"Hộp có đường khắc không giống đồ cung. Hắn có nói gì với ngươi không?"},{"who":"A","text":"Hắn không nói, chỉ đặt vào tay rồi đi. {Xung} sợ lắm, không biết nên giữ hay trả."},{"who":"me","text":"Một món quà không lời mà nặng như tảng đá. Ta cần nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-serv-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh quạt tròn thêu, cán chạm tên cung, {A} cầm giả làm chủ nhân, giọng điệu nhái giống đến lạ khiến cả phòng im phăng phắc."},{"who":"A","text":"Làm việc thế này à? Sân chưa quét xong mà còn đứng nhìn nhau, định đợi nhắc đến bao giờ?"},{"who":"me","text":"Ngoài cửa, ta đứng nghe mà thấy giọng mình vang trong gian phòng. Nhái giống đến thế, mà ta chưa từng thấy."},{"who":"A","text":"Ôi, {goi}! {Xung} chỉ đùa cho vui, không dám có ý bất kính. Chiếc quạt này {xung} mượn làm đạo cụ."},{"who":"me","text":"Đùa vui hay bất kính, ranh giới mỏng lắm. Ta cần nghĩ xem nên bước vào thế nào."}]}},
{"id":"j68:j68c-serv-025","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Giữa sân gạch lạnh, {A} quỳ, không dám ngẩng đầu, mảnh bình hoa men lam vỡ nằm trong tay {B}, vết nứt nơi men khớp từng chỗ."},{"who":"B","text":"{Goi}, bình này do {A} làm vỡ. Giao nàng ta cho {xung} chịu tội, kẻo các cung lại bảo cung {goi} bao che."},{"who":"me","text":"Mảnh vỡ còn trong tay {goi}, vết nứt trên men khớp đúng chỗ. {Xung} thấy lạ."},{"who":"B","text":"Lạ thì có gì lạ? Nàng ta quỳ đó, còn nói được gì nữa. {Goi} đừng để một cung nữ hủy thể diện cả cung."},{"who":"me","text":"Một cung nữ quỳ giữa sân mà lòng {xung} nặng. {Xung} cần nghĩ cách xử cho phải đạo."}]}},
{"id":"j68:j68c-serv-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn vỡ lòng cũ gáy sách ố vàng, dấu ấn riêng của cung ngươi còn in nơi bìa, {A} giấu vội tay ra sau lưng khi thấy ngươi."},{"who":"A","text":"Bẩm {goi}, {xung} không dám trộm sách. {Xung} chỉ mượn cuốn vỡ lòng để luyện chữ, vạch lên cát mỗi đêm."},{"who":"me","text":"Ngươi muốn biết chữ à? Ta nhìn nét vạch trên cát, cũng không đến nỗi vụng."},{"who":"A","text":"Dạ, {xung} muốn đọc được thư nhà, khỏi phải nhờ người. Cũng muốn biết trong sách có gì."},{"who":"me","text":"Một cung nữ chịu khó học, đáng quý. Ta cần nghĩ xem nên giúp ngươi thế nào cho vẹn."}]}},
{"id":"j68:j68c-serv-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ hộ tịch cũ nét chữ lạ, dấu ấn quan lại đã bạc màu, {A} quỳ nơi sân, hai tay nâng giấy như nâng cả mạng sống."},{"who":"A","text":"Bẩm {goi}, có người đồn {xung} là con nhà tội thần, giấu thân phận vào cung. {Xung} xin trình tờ hộ tịch để chứng minh trong sạch."},{"who":"me","text":"Tờ giấy cũ thế này, dấu quan lại đã bạc, sao ta phân biệt thật giả?"},{"who":"A","text":"{Xung} chỉ có tờ này để tự chứng. Nếu có tội, {xung} xin chịu, nhưng thân phận {xung} không dối."},{"who":"me","text":"Ngươi nói thế, ta nghe. Việc này nặng, ta cần nghĩ kỹ."}]}},
{"id":"j68:j68c-serv-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm chiếu cói dày bị kéo căng giữa phòng, dấu Nội vụ phủ in nơi góc chiếu, {A} và {B} mỗi người nắm một đầu, mặt hầm hầm."},{"who":"A","text":"Bẩm {goi}, giường sát cửa sổ gió mát nhất. {Xung} ở cung này lâu hơn, nên phải được ở đó."},{"who":"me","text":"Tiếng ồn vọng cả sang phòng ta. Hai ngươi cùng ở một phòng, vì một chiếc giường mà kéo nhau thế này sao?"},{"who":"A","text":"{B} cũng nói nàng ở trước, có lý riêng. {Xung} không nhường, nàng cũng không nhường."},{"who":"me","text":"Một chỗ nằm mà thành chuyện chung. Ta cần nghĩ xem nên phân thế nào cho công bằng."}]}},
{"id":"j68:j68c-serv-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc túi hương thêu dở, chỉ xanh chồng lên nhau vì sửa đi sửa lại, {A} cười gượng, ngón tay đầy dấu kim châm."},{"who":"A","text":"Bẩm {goi}, {xung} thêu mãi chưa xong túi hương này. Đây là quà cho một người {xung} không dám tỏ lòng."},{"who":"me","text":"Thêu đến chồng cả chỉ, hẳn ngươi đặt nhiều tâm ý. Ngươi không dám nói với người ấy sao?"},{"who":"A","text":"{Xung} thân phận thấp, sợ nói ra làm khó người ta. Nên chỉ dám thêu, không dám đưa."},{"who":"me","text":"Một mối tình kín trong từng mũi kim. Ta cần nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-serv-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói mứt gừng quê gói bằng giấy viết chữ nhà, mùi thơm cay ấm lan cả hành lang, {A} giữ phần lớn nhất đem dâng ngươi."},{"who":"A","text":"Bẩm {goi}, người nhà {xung} gửi lên ít mứt gừng quê. {Xung} chia cho cả phòng, để phần lớn nhất dành cho {goi}."},{"who":"me","text":"Mứt gừng thơm thế, mùi quê nồng ấm. Giấy gói còn nét chữ nhà ngươi, ta nhìn cũng thấy gần gũi."},{"who":"A","text":"Mẹ {xung} tự làm, dặn gửi cho người trên. {Xung} muốn {goi} nếm thử một miếng."},{"who":"me","text":"Món quà quê chan chứa tình. Ta cần nghĩ xem nên đáp lại thế nào cho phải."}]}},
{"id":"j68:j68c-serv-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau bình phong gỗ, {A} nín thở nghe rõ từng lời, tay nắm chặt mảnh giấy nhàu nét chữ nghiêng mực tím đặc."},{"who":"A","text":"Bẩm {goi}, vừa nãy {xung} nghe {B} bàn chuyện với một người lạ. {Xung} nhặt được mảnh giấy này, không biết nên nói gì, cho ai biết."},{"who":"me","text":"Nét chữ nghiêng, mực tím đặc, ta chưa từng thấy trong cung. Ngươi nghe được những gì?"},{"who":"A","text":"Chỉ lọt vài lời, nhưng có nhắc tên cung {goi}. {Xung} sợ, nên đem đến ngay."},{"who":"me","text":"Một mảnh giấy nhàu mà nặng như đá. Ta cần nghĩ cho kỹ nên xử trí ra sao."}]}},
{"id":"j68:j68c-serv-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vành đồng thùng nước khắc dấu Nội vụ phủ phản chiếu ánh nắng, tiếng cằn nhằn của {A} vang dọc hành lang."},{"who":"A","text":"Bẩm {goi}, thùng nước đầy nặng quá, đường lại xa, mà còn bị quản sự la. {Xung} làm hết sức mà vẫn chẳng vừa lòng ai!"},{"who":"me","text":"Giọng ngươi vang cả hành lang rồi. Nghe đến đây ta cũng biết ngươi mệt thế nào."},{"who":"A","text":"{Xung} biết là không nên nói, chỉ là kìm lòng không nổi. {Goi} đừng giận."},{"who":"me","text":"Lời cằn nhằn nào cũng có chỗ đau. Ta cần nghĩ xem nên đáp ra sao cho ngươi dịu lại."}]}},
{"id":"j68:j68c-serv-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giỏ mây buộc chỉ đỏ lật nghiêng, con mèo con chui ra ngay trước chân ngươi, đuôi vắt cong, cả phòng im phăng phắc."},{"who":"A","text":"Bẩm {goi}, {xung} lén nuôi con mèo con này dưới gầm giường. Nó kêu lên giữa buổi hầu trà, {xung} biết lỗi rồi."},{"who":"me","text":"Con mèo nhỏ xíu như thế, ngươi giấu nó từ bao giờ? Nó còn ngước nhìn ta như chẳng có tội."},{"who":"A","text":"{Xung} nhặt nó ở góc tường hôm mưa. Thấy nó run rẩy, {xung} không nỡ để nó chết."},{"who":"me","text":"Lòng ngươi mềm hơn tà áo. Việc này ta nghĩ xem nên xử thế nào."}]}},
{"id":"j68:j68c-serv-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuộn thẻ tre buộc dây gai chữ tròn nhỏ được nhét nhanh vào tay áo ngươi, {A} ghé sát tai, hơi thở nhẹ như gió thoảng."},{"who":"A","text":"{Goi}, lát nữa người ta gọi {goi} lên hỏi chuyện. {Xung} nghĩ ra một kế, {goi} chỉ cần làm đúng như thẻ này."},{"who":"me","text":"Thẻ tre ghi lời sẵn thế này, ngươi viết từ bao giờ? Kế của ngươi là gì?"},{"who":"A","text":"{Xung} đã nghĩ suốt đêm. Chỉ cần {goi} nói đúng từng chữ, sẽ không ai bắt bẻ được."},{"who":"me","text":"Ngươi lo cho ta như vậy, ta cảm kích. Nhưng đi theo lời viết sẵn hay không, ta cần cân nhắc."}]}},
{"id":"j68:j68c-serv-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn dầu lay lắt giữa đêm khuya, con thỏ vải chắp vá nhiều, dấu chỉ trắng, nằm trong tay {A} đang kể chuyện cổ tích."},{"who":"A","text":"Bẩm {goi}, {goi} mất ngủ, {xung} kể chuyện cổ tích quê {xung} cho {goi} nghe nhé. Chuyện thỏ ngọc và trăng sáng."},{"who":"me","text":"Con thỏ vải trong tay ngươi cũ lắm rồi. Chắc là món cũ ngươi mang từ nhà?"},{"who":"A","text":"Dạ, mẹ khâu cho {xung} từ thuở nhỏ. Mỗi lần buồn, {xung} ôm nó, chuyện cổ tích sẽ tự tìm đến."},{"who":"me","text":"Một đêm khuya mà có người kể chuyện bên đèn, lòng ta ấm. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-serv-036","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Giấy điều chuyển còn thơm mùi mực, dấu ấn son đỏ của Nội vụ phủ chói như máu, ngoài sân {A} vẫn cười nói chưa hay biết gì."},{"who":"B","text":"Bẩm {goi}, Nội vụ phủ định chuyển {A} sang cung khác vì thiếu người. Giấy điều chuyển đã có dấu ấn. {Xung} đến báo để {goi} biết."},{"who":"me","text":"{A} vẫn đang cười nói ngoài sân, chưa biết chuyện. Ngươi nói thế, ta thấy khó nghĩ."},{"who":"B","text":"Quy củ là quy củ, {xung} chỉ truyền lời. Nhưng {goi} có quyền xin giữ nàng lại."},{"who":"me","text":"Tin này ta không thể làm ngơ. Cần nghĩ xem nên đáp thế nào cho phải."}]}},
{"id":"j68:j68c-serv-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát canh măng nước đục mặn khác lạ đặt trên bàn, {A} đứng cúi đầu, ánh mắt trốn tránh như sợ ai nhìn thấu."},{"who":"A","text":"Bẩm {goi}, canh măng của {B} hôm nay mặn thật, {xung} cũng đã nếm. Chắc bếp lỡ tay thôi ạ."},{"who":"me","text":"Ta cũng nếm rồi. Mặn đến chát cả lưỡi, không giống lỡ tay bình thường."},{"who":"A","text":"Chuyện nhỏ thôi ạ. {Xung} chỉ mong {goi} đừng truy hỏi làm gì."},{"who":"me","text":"Ngươi lảng đi nhanh quá. Ta cần nghĩ xem nên làm gì cho khéo."}]}},
{"id":"j68:j68c-serv-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc trâm đồng cũ đầu khắc chữ tên mẹ, {A} nằm trên giường bệnh, hơi thở yếu như lá rụng cuối mùa, tay run run đưa ra."},{"who":"A","text":"{Goi}, thái y nói {xung} khó qua mùa này. {Xung} chỉ còn cây trâm này của mẹ, xin {goi} giữ giùm."},{"who":"me","text":"Ngươi đừng nói gở. Ngươi còn trẻ, còn nhiều ngày phía trước."},{"who":"A","text":"{Xung} biết thân mình. Mẹ nằm dưới đất quê xa, trâm này là thứ duy nhất {xung} còn mang. Xin {goi} nhận."},{"who":"me","text":"Một món kỷ vật mà nặng cả đời người. Ta cần nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-serv-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tập thư nháp bìa lót vải xanh bị nắm chặt trong gói, {A} vừa đi vừa quay đầu, bước chân loạng choạng giữa hành lang."},{"who":"A","text":"Bẩm {goi}, {B} ép {xung} đem tập thư nháp của {goi} sang cung khác dò xét. {Xung} không dám cãi, nhưng cũng không muốn phản chủ."},{"who":"me","text":"Tập thư này là chữ ta viết tay, ngươi nắm chặt như nắm lửa. Ngươi đã mở ra xem chưa?"},{"who":"A","text":"{Xung} chưa mở. {Xung} chỉ đang đi thì {goi} gặp, nên không biết làm sao cho phải."},{"who":"me","text":"Ngươi thành thật như vậy, ta thấy lòng nhẹ hơn. Ta cần nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-serv-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Viên ngọc bích có vết tì nhỏ lấp lánh trong lòng bàn tay, {A} giữ chiếc nhẫn sạch bóng, đứng im đợi ngươi mở lời."},{"who":"A","text":"Bẩm {goi}, mấy hôm trước {goi} làm rơi chiếc nhẫn dưới hiên, {xung} nhặt được. {Xung} giữ gìn sạch sẽ, không dám nói."},{"who":"me","text":"Chiếc nhẫn ngọc bích này, ta tìm mãi không thấy. Vết tì nhỏ ấy ta nhận ra ngay."},{"who":"A","text":"{Xung} sợ nói ra bị nghi, nên chờ {goi} hỏi. Nhưng giữ đồ người khác, lòng {xung} không yên."},{"who":"me","text":"Ngươi thật thà đến thế, ta cảm động. Ta cần nghĩ nên đáp ra sao."}]}},
{"id":"j68:j68c-serv-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dải lụa đỏ tua dấu kho Nội vụ phủ bay như cánh bướm giữa sân, {A} múa theo nhịp tưởng tượng, rồi vấp chân ngã nhào vào đống lá."},{"who":"A","text":"Ôi, {goi}! {Xung} chỉ học lỏm điệu múa của vũ nữ cho vui, không ngờ vấp ngã giữa sân thế này."},{"who":"me","text":"Dải lụa này của kho Nội vụ phủ, ngươi lấy ở đâu ra? Nhìn ngươi múa, quả thật có dáng."},{"who":"A","text":"{Xung} mượn của người khác, hứa sẽ trả. {Goi} đừng báo quản sự."},{"who":"me","text":"Vừa buồn cười vừa đáng thương. Ta cần nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-serv-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tập sổ tay nét chữ nhỏ ghi ngày tháng nằm trong hai tay {A}, nàng quỳ run run, ánh mắt nghiêm nghị khác hẳn thường ngày."},{"who":"A","text":"Bẩm {goi}, {xung} từng hầu {B}. {B} đã hạ nhục {xung} nhiều lần, {xung} xin {goi} làm chủ cho {xung}."},{"who":"me","text":"Tập sổ này ngươi ghi từ bao giờ? Nét chữ nhỏ mà đều, ngày tháng rõ ràng."},{"who":"A","text":"Từng việc {xung} đều ghi lại. {Xung} không dám bịa, chỉ mong {goi} xem rồi tự phán đoán."},{"who":"me","text":"Chuyện chưa kiểm chứng, nhưng nét mặt ngươi không dối. Ta cần nghĩ kỹ."}]}},
{"id":"j68:j68c-serv-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắm cơm nguội gói lá in dấu bếp cung, {A} ngoái lại thấy ngươi, bàn tay run rẩy bên đứa trẻ tạp dịch gầy gò nép góc tường."},{"who":"A","text":"Bẩm {goi}, {xung} chỉ chia nắm cơm nguội thôi, không dám lấy gì khác. Đứa nhỏ đã đói từ sáng."},{"who":"me","text":"Cơm nguội của bếp cung, ngươi giấu dưới áo mang đi như thế, nếu quản sự thấy thì thế nào?"},{"who":"A","text":"{Xung} biết sai. Nhưng nhìn nó gầy quá, {xung} không đành lòng."},{"who":"me","text":"Lòng ngươi tốt, cách làm chưa phải. Ta cần nghĩ xem nên giải quyết thế nào."}]}},
{"id":"j68:j68c-serv-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm, tiếng đập cửa dồn dập, {A} mặt tái nhợt đứng ngoài, trong tay là mảnh áo rách in dấu kho Nội vụ phủ vấy máu."},{"who":"A","text":"Bẩm {goi}, cung bên có biến! {Xung} nhặt được mảnh áo rách này mang dấu máu. Xin {goi} đừng đến xem!"},{"who":"me","text":"Mảnh áo vấy máu giữa đêm khuya, ngươi nhặt ở đâu? Cung bên xảy ra chuyện gì?"},{"who":"A","text":"{Xung} không rõ. Chỉ thấy người chạy qua, tiếng la rồi im lặng. {Xung} sợ lắm."},{"who":"me","text":"Một mảnh áo mà báo cả một đêm dữ. Ta cần nghĩ xem nên làm gì cho an toàn."}]}},
{"id":"j68:j68c-serv-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sương sớm còn đọng trên cành mai nở sớm, nụ mới hé một hai bông, {A} cẩn thận cắm vào bình ngay cửa phòng, miệng lẩm nhẩm lời cầu may."},{"who":"A","text":"Bẩm {goi}, đầu xuân {xung} cắm cành mai này, cầu một năm bình an cho {goi}. {Xung} nghèo, chỉ có cành hoa dâng được."},{"who":"me","text":"Cành mai còn sương, nụ vừa nở một hai bông, nhìn là thấy xuân đến. Ngươi hái ở đâu vậy?"},{"who":"A","text":"Ở góc vườn sau, hoa nở sớm nhất. {Xung} dậy từ canh năm để hái."},{"who":"me","text":"Lòng người nghèo dâng cành hoa còn quý hơn vàng. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-serv-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói bánh đậu xanh giấy có dấu cung ngươi, {A} chống nạnh giữa sân, mặt hằm hằm, bên cạnh {B} lặng lẽ cầm phần mình, không nói."},{"who":"A","text":"Bẩm {goi}, thưởng gói bánh đậu xanh, sao phần của {B} to hơn của {xung}? {Xung} làm việc cực nhọc không kém!"},{"who":"me","text":"Giữa sân mà cãi nhau như thế, ngươi nói to cả cung nghe. Ngươi nghĩ ai bất công?"},{"who":"A","text":"{Xung} không dám trách {goi}, chỉ thấy phần chia không đều. {B} thì im lặng, chẳng nói gì."},{"who":"me","text":"Chia thế nào cho công bằng, cũng là chuyện khó. Ta cần nghĩ xem nên xử ra sao."}]}},
{"id":"j68:j68c-serv-047","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Nắp hộp khóa đồng in dấu Nội vụ phủ nằm yên trên án, {A} quỳ giữa sân nắng gắt, mồ hôi chảy ròng, không cãi nửa lời."},{"who":"B","text":"Bẩm {goi}, {xung} phạt {A} quỳ vì làm mất hộp khóa đồng. Nàng không cãi, nhưng cũng không nhận lỗi."},{"who":"me","text":"Hộp khóa đồng mất, nhưng ta biết người lấy không phải {A}. Nàng quỳ giữa nắng, nhìn mà xót."},{"who":"B","text":"Quy củ là quy củ, {xung} chỉ làm theo lệ. {Goi} nói thế, {xung} cũng khó xử."},{"who":"me","text":"Phạt oan một người thì lòng người nguội lạnh. Ta cần nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-serv-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm danh thiếp giấy dày kim tuyến nằm trên án, {A} đọc to rồi bỗng đứng khựng, cả phòng nín cười, mặt nàng đỏ như gấc."},{"who":"A","text":"Ôi, {goi}! {Xung} đọc nhầm, chữ quan lại khó nhìn quá. {Xung} xin lỗi trước mặt khách."},{"who":"me","text":"Đọc nhầm danh thiếp thành con ngỗng nhà quan, khách cũng nín cười. Nhìn ngươi đỏ mặt, ta cũng buồn cười."},{"who":"A","text":"{Xung} biết chữ không nhiều, chỉ cố gắng đọc cho trọn việc. Giờ thì làm hỏng cả buổi."},{"who":"me","text":"Lỗi nhỏ mà mất thể diện. Ta cần nghĩ xem nên đỡ lời cho ngươi thế nào."}]}},
{"id":"j68:j68c-serv-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc vòng hạt gỗ đục lỗ buộc chỉ xanh siết chặt trong lòng bàn tay {A}, ánh mắt nàng nhìn mãi vào khoảng không."},{"who":"A","text":"Bẩm {goi}, bạn {xung} cùng vào cung bị thanh trừ vì lỗi nhỏ. Vòng hạt gỗ này là món duy nhất nàng để lại."},{"who":"me","text":"Mấy hôm nay ngươi im lặng, ta thấy cả. Người bạn ấy, ngươi thương lắm phải không?"},{"who":"A","text":"Cùng vào cung một ngày, cùng chia nhau từng bát cơm. {Xung} không hiểu vì sao nàng lại phải ra đi."},{"who":"me","text":"Nỗi mất bạn không phải lời có thể an ủi hết. Ta cần nghĩ xem nên làm gì cho ngươi."}]}},
{"id":"j68:j68c-serv-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Suối cạn chảy rì rầm qua đá, đôi giày thêu đế còn bùn bị bỏ quên bên bờ, {A} vừa đặt ngươi xuống đất khô, tay run vì lạnh."},{"who":"A","text":"Bẩm {goi}, giày {goi} ướt sũng, {xung} cõng {goi} qua suối cho khỏi lạnh chân. {Goi} đừng bận lòng."},{"who":"me","text":"Tay ngươi lạnh run cả lên, mà vẫn cõng ta qua suối. Hoa văn chỉ vàng trên giày ta còn nằm bên bờ kia."},{"who":"A","text":"{Xung} lội lại lấy ngay được, chỉ cần {goi} nói một tiếng."},{"who":"me","text":"Công ơn ấy không nhỏ. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-serv-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau tường hoa, túi vải thô đường khâu mới được trao tay cho người lạ áo thường dân, {A} quay lại, chạm ngay ánh mắt ngươi."},{"who":"A","text":"{Goi}, {xung} không có ý gì xấu đâu. Chỉ là nhờ người quen mang túi vải này ra ngoài, tiện đường thôi ạ."},{"who":"me","text":"Người áo thường dân giữa cung cấm, sao ngươi quen được? Trong túi có gì?"},{"who":"A","text":"Chỉ là đồ nhà nhờ gửi về. {Xung} thề không dám mang việc cung ra ngoài."},{"who":"me","text":"Lời thề thì dễ, mà túi vải kia thì thật. Ta cần nghĩ xem nên xử trí ra sao."}]}},
{"id":"j68:j68c-serv-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bảng gỗ cũ mép tróc sơn dựng giữa sân, {A} cầm phấn khua khoắng, cả phòng cười rộ vì nàng viết sai mất một nét."},{"who":"A","text":"{Goi} ủ rũ mấy hôm, nên {xung} bày trò đố chữ cho vui. Ai đoán trúng thì có thưởng!"},{"who":"me","text":"Cả phòng cười rộ vì ngươi viết sai chữ. Nhìn bảng gỗ cũ kỹ mà thấy ấm lòng."},{"who":"A","text":"{Xung} chỉ muốn làm {goi} cười. Cười một chút, bao nhiêu phiền muộn cũng nhẹ đi."},{"who":"me","text":"Một trò vui nhỏ mà chứa tấm lòng lớn. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-serv-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát sứ trắng của bếp cung đã trống trơn nơi bàn nhỏ, {A} nằm trên giường nhắm nghiền mắt, hơi thở đều đều."},{"who":"A","text":"{Goi}, {xung} đau bụng nằm cả buổi, xin {goi} thứ lỗi. Hôm nay {xung} không làm việc được."},{"who":"me","text":"{M} thấy ngươi vừa ăn hết bát cháo gà nóng. Bát còn trống trơn nằm ngay đây."},{"who":"A","text":"{Xung} đau bụng thật mà. Cháo gà ăn cho đỡ đau thôi ạ."},{"who":"me","text":"Giả ngủ mà thở đều thế kia, ngươi tưởng ta không thấy. Ta cần nghĩ xem nên xử ra sao."}]}},
{"id":"j68:j68c-serv-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ấm trà bạc miệng có dấu cung ngươi bị giơ cao, {A} quỳ lạy, tay run, nước mắt lăn dài, còn {B} đứng đó dẫn người sẵn sàng trói."},{"who":"A","text":"{Goi}, {xung} thề không bỏ độc vào ấm trà! {Xung} hầu hạ bao năm, nỡ nào hại người."},{"who":"me","text":"{B} nói có bằng chứng, nhưng chỉ là mấy lời bẩm. Ngươi nói lại cho ta nghe, lúc pha trà ngươi ở đâu?"},{"who":"A","text":"{Xung} ở bếp cả buổi, có người chứng. Xin {goi} cho {xung} một cơ hội."},{"who":"me","text":"Mạng người không thể xử vội. Ta cần nghĩ xem nên cản hay đứng ngoài."}]}},
{"id":"j68:j68c-serv-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nồi canh xương hầm nước trong, hương thơm ngọt lan ra, {A} và {B} đứng hai bên, mắt trừng nhau như gà chọi."},{"who":"A","text":"{Goi}, hôm nay nấu canh xương, {xung} cược với {B} xem ai ngon hơn. Mong {goi} nếm giúp cho công bằng."},{"who":"me","text":"Hai bát canh bày ra, hương cũng giống nhau. Hai ngươi nhìn nhau đến mức muốn đốt lửa cả bếp."},{"who":"A","text":"{Xung} đã nấu hết lòng. Nếu thua, {xung} không dám than, chỉ mong {goi} nếm kỹ."},{"who":"me","text":"Nếm canh thì dễ, mà chọn người thì khó. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-serv-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Răng lược sứt, cán lược khắc chữ nhỏ của mẹ, {A} đã tìm khắp sân không thấy, mắt đỏ hoe mà tay vẫn cắm cúi quét."},{"who":"A","text":"Bẩm {goi}, {xung} làm mất chiếc lược gỗ mẹ để lại. {Xung} tìm khắp sân mà không thấy, không dám nhờ ai."},{"who":"me","text":"Ta thấy ngươi quét mãi một chỗ từ sáng, thì ra là đang tìm. Lược ấy có gì đặc biệt?"},{"who":"A","text":"Cán lược có khắc chữ nhỏ của mẹ {xung}. Mất nó như mất thêm một phần của mẹ."},{"who":"me","text":"Một chiếc lược mà nặng nghĩa cả đời. Ta cần nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-serv-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói quà thêu tay giấy gói đỏ thắt nơ, góc giấy thêu hoa, được giấu dưới gầm giường khi ngươi vô tình bước vào, {A} đứng cứng người."},{"who":"A","text":"Bẩm {goi}, {goi} đừng nhìn dưới gầm giường. Không có gì đâu, chỉ là... chỉ là mấy món lặt vặt thôi ạ."},{"who":"me","text":"Giấy đỏ thắt nơ, góc giấy thêu hoa, lặt vặt mà khéo vậy sao? Mai là ngày sinh của ta mà."},{"who":"A","text":"{Xung} và mấy cung nữ định bất ngờ, ai ngờ {goi} đã thấy. Xin {goi} giả vờ như chưa thấy nhé."},{"who":"me","text":"Một tấm lòng lén lút mà đáng yêu. Ta cần nghĩ xem nên đón nhận thế nào."}]}},
{"id":"j68:j68c-serv-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thẻ bài đầu phòng khắc chữ còn thơm mùi gỗ mới nằm giữa sảnh, vừa bị ném xuống đất, cả sảnh nín thở nhìn ngươi."},{"who":"A","text":"Bẩm {goi}, {xung} hầu lâu hơn {B}, cớ sao lại cất nhắc nàng? {Xung} không phục!"},{"who":"me","text":"Giữa sảnh, ném thẻ bài xuống đất như thế, ngươi định để cả cung nhìn ta thế nào?"},{"who":"A","text":"{Xung} biết là thất lễ. Nhưng {xung} cố gắng bao năm, tưởng đến lượt mình."},{"who":"me","text":"Công lao ngươi ta không quên. Nhưng chuyện này cần nghĩ kỹ, kẻo mất lòng người."}]}},
{"id":"j68:j68c-serv-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mép khăn thêu tên nàng, chiếc khăn tay cũ ấp trong ngực, {A} ngã quỵ giữa sân rồi bò dậy, nắm lấy tay ngươi."},{"who":"A","text":"{Goi}, người thân thất lạc của {xung} đã tìm ra rồi! {Xung} không biết phải làm gì, tay chân cứ run lên."},{"who":"me","text":"Đứng dậy đi, ngươi khóc đến lạc giọng rồi. Khăn trong ngực ngươi là của mẹ để lại, phải không?"},{"who":"A","text":"Dạ, {xung} giữ nó suốt bao năm. Giờ gặp người, {xung} sợ mình chỉ là mơ."},{"who":"me","text":"Một tin vui đến bất ngờ, ngươi nghĩ gì ta hiểu. Ta cần nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-serv-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bìa da xanh có dấu ngươi nằm yên trên án, {A} ghé sát tai, giọng thì thầm như gió luồn qua kẽ lá."},{"who":"A","text":"Bẩm {goi}, {B} đang gom sổ chi tiêu các phòng để tra vặt, mà có vẻ nhắm vào {goi}. Tốt nhất {goi} cất sổ riêng đi."},{"who":"me","text":"Sổ chi tiêu của cung ta, ngươi đã thấy chưa? Có chỗ nào sơ ý không?"},{"who":"A","text":"{Xung} không dám xem. Chỉ nghe người ta nói, {B} muốn tìm lỗi của cung {goi}."},{"who":"me","text":"Một lời báo thầm mà quý như vàng. Ta cần nghĩ xem nên làm thế nào cho yên."}]}},
{"id":"j68:j68c-emp-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi cúc khô thoảng nhẹ từ chiếc gối lụa, Hoàng thượng bước vào, tay day trán, bóng người đổ dài trên nền gạch."},{"who":"A","text":"Buổi nghị sự hôm nay kéo dài mãi, đầu trẫm nhức như búa bổ. Trẫm chỉ muốn ngồi yên một lát."},{"who":"me","text":"Gối lụa nhồi hoa cúc {xung} để sẵn, mùi cúc khô thơm dịu, {goi} dựa thử xem có đỡ chăng."},{"who":"A","text":"Hương này nhẹ mà dễ chịu. Ở đây trẫm không phải nghĩ đến tấu chương nữa."},{"who":"me","text":"{Goi} không nói gì thêm, chỉ nhắm mắt chờ. {Xung} nên làm sao cho {goi} nhẹ lòng, để {xung} nghĩ."}]}},
{"id":"j68:j68c-emp-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tập tấu chương giấy vàng đặt trên bàn, dấu ấn quan thần còn tươi, Hoàng thượng nhìn ngươi không chớp, không khí trầm hẳn xuống."},{"who":"A","text":"Có vị quan vừa dâng thư khen công của họ nhà {goi}. Trẫm đọc xong, muốn nghe {goi} nghĩ sao."},{"who":"me","text":"Thư khen công thì ai nghe cũng vui, nhưng {goi} nhìn {xung} như vậy, {xung} lại thấy nặng lòng."},{"who":"A","text":"Trẫm chỉ muốn biết {goi} phản ứng ra sao. Nói thật đi, đừng giữ lễ quá."},{"who":"me","text":"Lời khen từ ngoài triều có khi là gió thuận, có khi là bẫy ngầm. {Xung} cần suy nghĩ kỹ rồi mới đáp."}]}},
{"id":"j68:j68c-emp-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai bức tranh trải trên án thư, một nét hoa mai thanh nhã, một nét sơn thủy mực đậm hùng vĩ, Hoàng thượng đứng giữa, ánh mắt phân vân."},{"who":"A","text":"Trẫm có hai bức tranh, muốn treo trong thư phòng mà chưa chọn được. {Goi} nhìn giúp trẫm."},{"who":"me","text":"Hoa mai thanh nhã như hơi thở đầu xuân, sơn thủy hùng vĩ như khí phách người quân tử. Cả hai đều có cái hay."},{"who":"A","text":"Trẫm thích cả hai. Nhưng thư phòng chỉ có một bức tường trống."},{"who":"me","text":"Một bức tường, hai bức tranh, lựa thế nào cho hợp ý {goi}, để {xung} nghĩ."}]}},
{"id":"j68:j68c-emp-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bình hoa ngọc bích lớn trong điện miệng mẻ một góc, Hoàng thượng đứng trước nó, bắt chước dáng một vị quan già ngã nhào, cả phòng cười."},{"who":"A","text":"Rồi lão quan ngủ gật giữa triều, nghiêng người một cái, ngã nhào vào cái bình hoa lớn. Nghe này, rầm một tiếng!"},{"who":"me","text":"Cung nữ che miệng cười cả rồi. {Goi} diễn đến mức này, bình hoa kia còn phải tức cười theo."},{"who":"A","text":"Trẫm kể mãi, sao chỉ mình trẫm cười? {Goi} không thấy buồn cười sao?"},{"who":"me","text":"{Goi} đợi {xung} cười theo. Nên cười thế nào cho khéo, {xung} cần nghĩ."}]}},
{"id":"j68:j68c-emp-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm giỗ tiên đế, ngọn đèn leo lét, chuỗi hạt trầm sờn cũ trong tay Hoàng thượng thoảng mùi hương xưa."},{"who":"A","text":"Đêm nay trẫm không muốn ở một mình. Ngồi đây một lúc, đừng hỏi gì."},{"who":"me","text":"Chuỗi hạt trầm ấy là của tiên đế. Hạt đã sờn, mùi hương vẫn còn nguyên."},{"who":"A","text":"Phải, trẫm nhìn ngọn đèn mà tưởng như người còn ngồi đó. Trẫm chưa kịp nói với người nhiều điều."},{"who":"me","text":"{Goi} không nói thêm. {Xung} không nên quấy lòng {goi}, nhưng cũng không muốn ngồi lặng như tượng. Để {xung} nghĩ."}]}},
{"id":"j68:j68c-emp-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm màn thêu mới thay sáng nay còn thơm mùi vải lạ, Hoàng thượng cau mày nhìn một lượt, ngón tay chỉ vào chỗ trống."},{"who":"A","text":"Sao tấm màn hôm nay không thêu hoa cúc như thường lệ? Trẫm quen nhìn nó mỗi lần tới đây."},{"who":"me","text":"Màn cũ đã giặt, {xung} thay tấm mới. Chắc {goi} để ý nhiều hơn {xung} tưởng."},{"who":"A","text":"Trẫm là người kén, chỉ cần sai một chút là thấy lạ ngay. Nhưng trẫm nhớ rõ, hoa cúc ấy thêu rất đẹp."},{"who":"me","text":"Một chi tiết nhỏ mà {goi} nhớ đến thế. Để {xung} nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-emp-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa bất chợt đổ ào ào, Hoàng thượng cởi áo choàng long văn thêu rồng vàng khoác lên vai ngươi, nắm tay chạy vào hiên."},{"who":"A","text":"Mau vào đây, kẻo ướt hết. Áo này ấm, {goi} khoác vào đi."},{"who":"me","text":"Áo này thêu rồng vàng, cổ viền tía, là lễ phục của {goi}. Không ai dám chạm đến, {xung} sao dám khoác."},{"who":"A","text":"Trẫm khoác lên là của trẫm, chẳng ai dám nói gì. Ướt mưa thì bệnh, trẫm không muốn thế."},{"who":"me","text":"Một chiếc áo mà gánh cả lễ nghi lẫn tình ý. {Xung} cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức mật thư nét chữ nghiêng, ấn giả đặt trước mặt ngươi, Hoàng thượng không giận, chỉ nhìn rất lâu, im lặng nặng như đá."},{"who":"A","text":"{B} vừa dâng tin đồn nhà {goi} kết bè với quan lớn. Trẫm mang bức mật thư tố cáo này đến, hỏi thẳng {goi}."},{"who":"me","text":"{Goi} không nổi giận, chỉ nhìn {xung} lâu như vậy. {Xung} cảm thấy còn đáng sợ hơn là bị quở."},{"who":"A","text":"Trẫm muốn nghe {goi} nói, chứ không muốn tự mình nghĩ. Nét chữ nghiêng này, {goi} có nhận ra không?"},{"who":"me","text":"Lời đồn như nước đổ, thu về không dễ. {Xung} cần suy nghĩ cẩn thận từng chữ."}]}},
{"id":"j68:j68c-emp-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Túi hương nhồi hoa lài, đường thêu nhỏ, mùi lài dịu, nằm trong tay Hoàng thượng, ngài nâng lên ngắm hồi lâu."},{"who":"A","text":"Món này tinh xảo, đường kim mũi chỉ rất đều. Trẫm thắc mắc ai khéo tay đến thế."},{"who":"me","text":"{Goi} nhìn kỹ như vậy, {xung} không giấu được nụ cười. Đó là món {xung} làm mấy hôm trước."},{"who":"A","text":"Của {goi} ư? Trẫm không ngờ. Hương lài thơm dịu, rất hợp với trẫm lúc mệt."},{"who":"me","text":"Một món nhỏ mà {goi} để ý đến thế. Để {xung} nghĩ xem nên đáp lại ra sao."}]}},
{"id":"j68:j68c-emp-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm bản đồ biên giới trải rộng giữa bàn, nét mực xưa dấu ấn Binh bộ, Hoàng thượng đặt tay lên một chấm đồi, mắt nhìn ngươi."},{"who":"A","text":"Biên giới có nhiều đồn đồi, triều thần chia hai ý. Nên bãi binh hay tăng thêm, {goi} nghĩ sao?"},{"who":"me","text":"Chuyện quân quốc là việc nam nhân, {xung} chỉ là nữ nhi trong cung, sao dám bàn."},{"who":"A","text":"Trẫm hỏi thật lòng. Có khi người ngoài cuộc lại nhìn rõ hơn kẻ trong cuộc."},{"who":"me","text":"Lời nói của {xung} có thể bị người khác đồn là can dự triều chính. {Xung} cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-emp-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bột trắng bay đầy mặt, dính cả lên long bào, nắm bột nhào dở trong tay Hoàng thượng, cung nữ cố nín cười run vai."},{"who":"A","text":"Trẫm tự tay nhào bánh cho {goi} ăn. Xem nào, bột nở sao thế này?"},{"who":"me","text":"Bột bay cả lên mặt {goi} rồi. Long bào cũng dính trắng cả, {xung} chưa từng thấy {goi} như vậy."},{"who":"A","text":"Ai dám cười thì trẫm phạt. Nhưng bánh này chắc sẽ không thành rồi."},{"who":"me","text":"Nhìn {goi} lúng túng mà lòng {xung} ấm. Để {xung} nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-emp-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bình thuốc gia truyền nút sáp niêm phong của Thái y viện được nắm chặt trong tay, Hoàng thượng bước vào, nét mặt đầy lo lắng."},{"who":"A","text":"Trẫm vừa thăm hoàng tử ốm bên cung khác. Thái y bó tay, {goi} có biết phương thuốc nào hay không?"},{"who":"me","text":"Nghe {goi} nói mà lòng {xung} cũng nặng. Hoàng tử còn nhỏ, bệnh bao lâu rồi?"},{"who":"A","text":"Mấy hôm nay hay sốt, ăn uống ít. Trẫm lo lắm, nhưng không biết làm gì."},{"who":"me","text":"Một lời của {goi} nặng như núi. {Xung} cần nghĩ xem nên giúp thế nào."}]}},
{"id":"j68:j68c-emp-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Từ lễ tế về, chiếc trâm ngọc xanh nhạt chân bạc được đặt lên bàn, Hoàng thượng ngập ngừng, không nói là tặng."},{"who":"A","text":"Đi ngang quầy hàng, trẫm thấy món này hợp {goi}. Trẫm đặt ở đây, {goi} muốn lấy thì lấy."},{"who":"me","text":"Ngọc xanh nhạt, chân trâm bạc. {Goi} không nói tặng, chỉ đặt lên bàn như tình cờ."},{"who":"A","text":"Trẫm không quen nói những điều này. Cứ coi như trẫm tiện tay mang về."},{"who":"me","text":"Một món nhỏ mà tấm lòng không nhỏ. {Xung} cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấu chương mực đẫm nước trà loang trên án, một người hầu quỳ run, Hoàng thượng đứng giận dữ, chẳng nghe ai can."},{"who":"A","text":"Một giọt trà làm hỏng cả bản tấu chương quan trọng! Người đâu, đem phạt trượng!"},{"who":"me","text":"{Goi}, người ấy là người hầu của {xung}. {Xung} biết nàng sai, nhưng trượng là hình nặng."},{"who":"A","text":"{Goi} đừng can. Tấu chương này không thể chép lại ngay được."},{"who":"me","text":"Lòng {xung} thắt lại. Nên can hay không, can thế nào, {xung} phải nghĩ."}]}},
{"id":"j68:j68c-emp-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nắng lướt qua cửa sổ, sổ chi tiêu bìa lụa xanh chữ ngươi nằm ngay ngắn trên án, Hoàng thượng đi một vòng thấy mọi thứ đâu ra đấy."},{"who":"A","text":"Cung của {goi} gọn gàng ngăn nắp, sổ chi tiêu rõ ràng. Ai là người quán xuyến?"},{"who":"me","text":"Chuyện cung nhỏ, ai quản thì cũng chỉ là chăm chút từng ngày. {Goi} hỏi vậy, {xung} chưa biết nên đáp thế nào."},{"who":"A","text":"Trẫm hỏi thật. Người có công thì trẫm muốn biết."},{"who":"me","text":"Một lời khen nhẹ nhàng mà gửi gắm bao công lao. Để {xung} nghĩ cách đáp cho phải đạo."}]}},
{"id":"j68:j68c-emp-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư nhà nét chữ mẹ ngươi nhô ra khỏi tay áo, Hoàng thượng bắt gặp, giọng bình thản mà mắt không rời."},{"who":"A","text":"Thư gì mà {goi} giấu trong tay áo? Ai gửi?"},{"who":"me","text":"Thư của họ hàng, nét chữ mẹ {xung}. {Xung} giấu không phải vì sợ, chỉ là chuyện riêng."},{"who":"A","text":"Trẫm không ép. Nhưng trong cung này, thư từ ra vào đều có lệ."},{"who":"me","text":"Thư nhà là chuyện riêng, mà lệ cung lại là chuyện chung. {Xung} cần nghĩ nên đáp ra sao."}]}},
{"id":"j68:j68c-emp-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khuya khoắt, ngọn đèn nhỏ hắt bóng Hoàng thượng đứng ngoài hiên, tay xoa bụng, bát cháo hoa nguội đặt trên bàn."},{"who":"A","text":"Trẫm đói. {Goi} còn gì ăn không? Bếp lớn đã tắt lửa, trẫm không muốn đánh thức ai."},{"who":"me","text":"Bát cháo hoa nguội này {xung} để lại. Sứ trắng nhỏ, hơi đã nguội từ lâu."},{"who":"A","text":"Có còn hơn không. Trẫm chỉ cần món gì đó ấm bụng."},{"who":"me","text":"Giữa đêm {goi} ghé cung kiếm cái ăn, {xung} không nỡ để {goi} đói. Để {xung} nghĩ cách."}]}},
{"id":"j68:j68c-emp-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén trà nguội men ngà dấu cung ngươi đặt giữa bàn, Hoàng thượng ngồi im hồi lâu, trong lòng hẳn còn dư âm của trận cãi."},{"who":"A","text":"Trẫm vừa cãi với Hoàng hậu. Trẫm không muốn nói gì, chỉ muốn ngồi đây một lát."},{"who":"me","text":"Chén trà nguội rồi, {goi} chưa uống ngụm nào. {Goi} đến đây, {xung} hiểu là cần một chỗ trú."},{"who":"A","text":"Trẫm đúng sai chưa rõ. {Goi} nghĩ trẫm nên làm gì?"},{"who":"me","text":"Một câu hỏi khó mà không thể từ chối. Để {xung} nghĩ cho thấu đáo."}]}},
{"id":"j68:j68c-emp-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giàn hoa tử đằng buông rủ, cành tre đan dệt, Hoàng thượng đứng giữa vườn tối, mặt dính mạng nhện, cố giữ vẻ uy nghi."},{"who":"A","text":"Vườn cung của {goi} tối quá, trẫm đi nhầm vào giàn hoa. Không có gì đáng cười."},{"who":"me","text":"Mạng nhện còn vương trên mặt {goi}, mà {goi} vẫn nghiêm trang như đang thượng triều."},{"who":"A","text":"Trẫm phủi áo, đứng thẳng. Đừng nói với ai chuyện này."},{"who":"me","text":"Một lúc luống cuống của người trên, nhìn mà vừa thương vừa buồn cười. Để {xung} nghĩ cách đỡ cho {goi}."}]}},
{"id":"j68:j68c-emp-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khăn lụa nhạt góc thêu tên ngươi nằm yên trong tay Hoàng thượng, nhẹ như một kỷ niệm cũ."},{"who":"A","text":"{Goi} còn nhớ lần đầu gặp trẫm không? Khăn này {goi} đánh rơi hôm ấy, trẫm giữ từ đó đến nay."},{"who":"me","text":"Chiếc khăn lụa nhạt, góc thêu tên {xung}. Không ngờ {goi} vẫn giữ đến bây giờ."},{"who":"A","text":"Trẫm không nói gì, vì không biết nói thế nào. Mỗi lần nhìn nó, trẫm lại nhớ hôm ấy."},{"who":"me","text":"Một món nhỏ mà chan chứa nhiều năm. {Xung} cần nghĩ xem nên đáp lại ra sao."}]}},
{"id":"j68:j68c-emp-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bộ trâm cài ngọc loại tốt khắc dấu Nội vụ phủ lấp lánh trong trí nhớ, Hoàng thượng tình cờ nhắc đến, ánh mắt thăm dò."},{"who":"A","text":"{B} vừa nhận bộ trâm cài ngọc, nặng hơn phần thưởng của {goi}. Trẫm tình cờ nhắc, {goi} thấy sao?"},{"who":"me","text":"{Goi} nhắc vô tình như thế mà ánh mắt đang chờ. {Xung} không dám đáp bừa."},{"who":"A","text":"Trẫm không có ý gì cả. Chỉ muốn nghe {goi} nói thật lòng."},{"who":"me","text":"Một câu hỏi khéo mà dễ lộ lòng. Để {xung} nghĩ cách đáp cho phải."}]}},
{"id":"j68:j68c-emp-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cả xe hoa đào cành tươi giọt sương còn đọng, dấu ngự uyển in trên cành, cung nữ ùa ra ngắm không dứt."},{"who":"A","text":"Mùa này hoa đào nở đúng ý nhất, trẫm sai chuyển cả xe từ ngự uyển sang cung {goi}."},{"who":"me","text":"Cành còn giọt sương, màu hồng như má thiếu nữ. {Goi} nghĩ cho {xung} chu đáo đến thế."},{"who":"A","text":"Trẫm không nói nhiều, chỉ muốn {goi} thấy đẹp. Cung này lâu nay vắng sắc xuân."},{"who":"me","text":"Cả xe hoa là ơn nặng. {Xung} cần nghĩ xem nên nhận và chia thế nào cho phải."}]}},
{"id":"j68:j68c-emp-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây tỳ bà cũ dấu Giáo phường trên tay ngươi, nhạc sư đang cúi chào, Hoàng thượng bước vào đúng lúc, không khí bỗng đóng băng."},{"who":"A","text":"Trẫm không báo trước mà đến. Nhưng sao {goi} lại cầm tỳ bà, và có người lạ trong cung?"},{"who":"me","text":"Đây là nhạc sư trong cung, {xung} học đàn cho khuây. Cây tỳ bà ấy của Giáo phường cho mượn."},{"who":"A","text":"Trẫm không nghi ngờ gì, chỉ là bất ngờ. Phòng này lâu lắm không có tiếng đàn."},{"who":"me","text":"Một ánh nhìn mà làm cả phòng nín lặng. {Xung} cần nghĩ xem nên giải thích thế nào."}]}},
{"id":"j68:j68c-emp-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con dấu cung ngọc xanh khắc tên ngươi bị đặt gọn trong lòng bàn tay Hoàng thượng, giọng ngài trầm xuống như đêm đông."},{"who":"A","text":"Có kẻ tâu {goi} lạm quyền. Trẫm tạm thu con dấu này, chưa rõ thời hạn."},{"who":"me","text":"Lạm quyền là tội nặng, {xung} chưa hề có ý đó. {Goi} nói tạm thu, tức là chưa định tội."},{"who":"A","text":"Trẫm không muốn tin, nhưng cũng không thể bỏ qua. {Goi} hiểu cho."},{"who":"me","text":"Một con dấu mà là thể diện cả cung. Để {xung} nghĩ cho kỹ nên đối đáp thế nào."}]}},
{"id":"j68:j68c-emp-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây cổ cầm dây tơ khắc tên cung ngươi vừa bật lên một tiếng \"tách\", dây đứt đôi, cung nữ cắn môi nín cười."},{"who":"A","text":"Trẫm gảy theo lời {goi} dạy, mà dây đứt ngay. Ai nói trẫm gảy vụng, trẫm phạt!"},{"who":"me","text":"Dây tơ vốn mỏng, {goi} ấn mạnh một chút là đứt. Ngón tay {goi} đỏ cả lên rồi."},{"who":"A","text":"Trẫm đòi học, thì {goi} dạy cho kỹ. Đừng cười."},{"who":"me","text":"{Goi} làm ra vẻ nghiêm trang mà ánh mắt vẫn thích. Để {xung} nghĩ cách dạy cho phải."}]}},
{"id":"j68:j68c-emp-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chồng tấu chương giấy vàng chất cao bừa bộn trên án, mắt Hoàng thượng đầy tia máu, dáng ngồi thừ như tượng."},{"who":"A","text":"Hôm nay trẫm không có ai để than một câu. Ngồi nhìn chồng tấu chương này, muốn buông bút mà không được."},{"who":"me","text":"Tấu chương chất cao như núi, mắt {goi} đỏ cả. {Xung} đứng đây, nghe {goi} than."},{"who":"A","text":"Trẫm không cần lời khuyên. Chỉ cần có người ngồi nghe."},{"who":"me","text":"Có những lúc, chỉ cần ngồi bên cũng là một cách thương. Để {xung} nghĩ nên giúp thế nào."}]}},
{"id":"j68:j68c-emp-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tập thư cũ giấy ngả vàng nét chữ non nớt mở ra dưới ánh đèn, giọng Hoàng thượng nhỏ hơn thường lệ."},{"who":"A","text":"Đây là mấy lá thư thời trẫm còn nhỏ. {Goi} thấy tình cảm thuở nhỏ là gì?"},{"who":"me","text":"Giấy ngả vàng, nét chữ còn non, đọc mà thấy cả một thời xa. {Goi} giữ chúng bao nhiêu năm rồi?"},{"who":"A","text":"Từ lâu lắm. Trẫm không nói, vì không ai hỏi trẫm."},{"who":"me","text":"Một câu hỏi nhẹ mà mở ra cả quá khứ. {Xung} cần nghĩ nên đáp thế nào cho phải đạo."}]}},
{"id":"j68:j68c-emp-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, ánh bình minh hồng nhạt, chiếc áo choàng lông cáo trắng mép viền nhung được ngươi khoác nhẹ lên vai Hoàng thượng."},{"who":"A","text":"Trẫm sắp thượng triều. Hôm nay có chuyện lớn phải bàn, mà trẫm lại lo."},{"who":"me","text":"Lông cáo trắng ấm, {goi} khoác vào cho đỡ lạnh. Tay {goi} lạnh cả rồi."},{"who":"A","text":"{Goi} nắm lấy tay trẫm thế này, trẫm thấy yên lòng. Chốc nữa lại phải cầm bút phê nghị."},{"who":"me","text":"Trong khoảnh khắc ấy, {xung} muốn nói điều gì đó. Để {xung} nghĩ cho vẹn."}]}},
{"id":"j68:j68c-emp-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đĩa bánh hạt sen đường kính mịn in hoa văn cung bị đẩy ra, Hoàng thượng nhăn mặt, ngươi hồi hộp vì chính tay mình nêm."},{"who":"A","text":"Món hôm nay quá ngọt, khác hẳn thường ngày. Trẫm không dùng nổi."},{"who":"me","text":"Bánh này {xung} tự tay làm, nêm đường hơi tay. {Goi} chê, {xung} cũng thấy xấu hổ."},{"who":"A","text":"Trẫm không chê, chỉ nói thật. Hôm nay trẫm vừa dùng vị ngọt khác, nên miệng còn đọng."},{"who":"me","text":"Có thể do {goi}, có thể do {xung}. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách tuyển tú giấy đỏ chữ ngay ngắn đặt xuống bàn, Hoàng thượng nhìn ngươi, giọng nhẹ nhưng lời nặng."},{"who":"A","text":"Sắp tới có người mới nạp vào cung. Trẫm hỏi {goi}, nên ban cung nào cho nàng ấy?"},{"who":"me","text":"{Goi} hỏi {xung} chuyện này, hẳn là coi trọng. Nhưng một lời của {xung} có thể làm lòng người nứt vỡ."},{"who":"A","text":"Trẫm không ép. Chỉ muốn nghe ý {goi}."},{"who":"me","text":"Nói thế nào cho vừa lòng cả hai bên, {xung} cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-emp-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư gièm pha giấy thơm hương cung {B} nằm trên tay Hoàng thượng, ngài bước vào mà nét mặt đã khác thường."},{"who":"A","text":"Trẫm chưa hỏi gì. Nhưng nét mặt trẫm, {goi} chắc cũng thấy."},{"who":"me","text":"Giấy thơm hương lạ, chữ nghiêng nghiêng. {Goi} cầm bức thư ấy, chắc là chuyện lớn."},{"who":"A","text":"Có người nói {goi} qua lại với người ngoài. Trẫm không tin, nhưng cũng không thể làm ngơ."},{"who":"me","text":"Lời gièm pha nặng như đá đè. Để {xung} nghĩ cách đối đáp cho vẹn."}]}},
{"id":"j68:j68c-emp-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọn nến trắng sáp trắng dấu Nội vụ phủ đặt bên giường, Hoàng thượng nằm dài, bắt ngươi kể chuyện có ma mà lại sợ phải bịt tai."},{"who":"A","text":"Kể cho trẫm nghe một chuyện có ma, nhưng đừng có đoạn nào quá đáng sợ. Trẫm sẽ bịt tai khi tới đoạn hay."},{"who":"me","text":"{Goi} vừa đòi nghe vừa sợ, thật hiếm có. Nhìn ngọn nến trắng kia, {xung} cũng thấy rờn rợn."},{"who":"A","text":"Trẫm là Hoàng thượng, nhưng sợ ma vẫn là sợ ma. Đừng cười."},{"who":"me","text":"{Goi} tin {xung} mới thú nhận như vậy. Để {xung} nghĩ nên kể thế nào."}]}},
{"id":"j68:j68c-emp-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây trâm vàng khắc phượng ấn Ngự dụng giám lấp lánh trong hộp, Hoàng thượng đứng lúng túng như trẻ nhỏ, cả cung nín thở nhìn."},{"who":"A","text":"Hôm nay là sinh nhật {goi}. Trẫm tự tay chọn cây trâm này, không biết {goi} có thích không."},{"who":"me","text":"Phượng khắc tinh xảo, ấn Ngự dụng giám rõ ràng. {Goi} tự chọn, {xung} cảm động lắm."},{"who":"A","text":"Trẫm không giỏi lời hay ý đẹp, chỉ mong {goi} nhận."},{"who":"me","text":"Một món quà mà cả cung đang nhìn, {xung} cần nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-emp-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư của công chúa mép giấy nhàu, chữ run run, Hoàng thượng đặt trước mặt ngươi, vai rũ xuống như mang gánh nặng ngàn cân."},{"who":"A","text":"Trẫm mất ngủ mấy đêm vì phải gả công chúa đi xa. Lá thư này của nó, trẫm đọc mãi chưa dứt."},{"who":"me","text":"Chữ run, mép giấy nhàu, hẳn công chúa cũng đã khóc nhiều. {Goi} đặt thư trước mặt {xung}, là muốn nhờ gì?"},{"who":"A","text":"Trẫm chưa nói được. Chỉ mong {goi} giúp trẫm gạt bỏ ý nghĩ ấy."},{"who":"me","text":"Một người cha bên trong vị quân vương. Để {xung} nghĩ xem nên giúp thế nào."}]}},
{"id":"j68:j68c-emp-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lụa thêu áo đỏ thắm dấu thợ may cung được Hoàng thượng chỉ lên khi ngài đứng giữa cung ngươi, ánh mắt chê màu nhợt nhạt."},{"who":"A","text":"Hôm nay {goi} mặc màu nhợt nhạt quá, thay màu đỏ đi cho tươi tắn."},{"who":"me","text":"Hôm nay là ngày lễ Hoàng hậu, mặc đỏ có phần không nên. {Xung} chọn màu nhạt cũng là vì thế."},{"who":"A","text":"Trẫm không nhớ. Nhưng trẫm vẫn thích {goi} mặc đỏ."},{"who":"me","text":"Ý của {goi} và lễ của cung không trùng nhau. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắp lọ khắc chữ Ngự thiện phòng đặt giữa bàn, sắc mặt Hoàng thượng nặng như chì, cả phòng nín thở không ai dám nhúc nhích."},{"who":"A","text":"Thái y vừa phát hiện lọ nước hoa quả này có độc. Và nó từng đi qua cung {goi}."},{"who":"me","text":"Lọ ấy là của Ngự thiện phòng. {Xung} chỉ nhận như mọi lần, chưa từng động tay vào."},{"who":"A","text":"Trẫm không kết tội. Trẫm muốn nghe {goi} nói, vì trẫm không muốn tin điều đó."},{"who":"me","text":"Một lời oan có thể nhấn chìm cả cung. {Xung} cần nghĩ thật kỹ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhành hoa dại cánh héo một nửa, cuống còn dính bùn, Hoàng thượng ngập ngừng đưa ra, như thể chưa quen làm việc này."},{"who":"A","text":"Trẫm thấy bên đường có nhành hoa dại, thơm lắm, nên hái. Dẫu héo rồi, nhưng trẫm muốn {goi} có."},{"who":"me","text":"Nhành hoa dại cánh héo, cuống dính bùn. {Goi} cầm như cầm bảo vật, {xung} nhìn mà xúc động."},{"who":"A","text":"Trẫm không có gì quý tặng. Chỉ là nhành hoa này, trẫm nghĩ đến {goi}."},{"who":"me","text":"Một nhành hoa dại mà nặng hơn trăm ngọc quý. {Xung} cần nghĩ cách nhận cho trọn tình."}]}},
{"id":"j68:j68c-emp-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức tranh lụa nét vẽ đẹp kèm thơ mỉa nằm trên án, Hoàng thượng bất ngờ ghé qua sau nhiều ngày vắng bóng."},{"who":"A","text":"Mấy hôm nay trẫm bận, không ghé được. Có người nói với trẫm, trong cung có nhiều lời không hay."},{"who":"me","text":"{Goi} cũng nghe rồi. {B} mang bức tranh lụa sang châm chọc, {xung} đã biết từ lâu."},{"who":"A","text":"Trẫm không tin. Nhưng trẫm cũng muốn nghe từ chính miệng {goi}."},{"who":"me","text":"Một lần ghé bất ngờ, lòng {xung} lẫn lộn mừng và tủi. Để {xung} nghĩ nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn cờ ngọc trắng chưa tàn, Hoàng thượng thua ngươi ba ván liền, ngón tay lén xoay một quân giữa chừng."},{"who":"A","text":"Ván này trẫm chưa thua đâu. Trẫm đi nước khác, {goi} nhìn kỹ lại."},{"who":"me","text":"Quân ngọc trắng ấy vừa nãy nằm chỗ kia, giờ lại ở đây. {Xung} nhìn thấy cả rồi."},{"who":"A","text":"{Goi} nhìn thấy, trẫm cũng nhìn thấy {goi} nhìn thấy. Đừng nói ra."},{"who":"me","text":"Một Hoàng thượng chơi gian mà nín thở chờ phản ứng. Vừa buồn cười, vừa đáng yêu. Để {xung} nghĩ cách đáp."}]}},
{"id":"j68:j68c-emp-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáo trúc ngà cũ khắc tên ngươi nằm bên cạnh, Hoàng thượng ngồi tựa, giọng nhỏ như sợ làm vỡ đêm."},{"who":"A","text":"Đêm nay trẫm nhớ. {Goi} còn nhớ khúc hát ngày trước trẫm từng nghe qua cây sáo này không?"},{"who":"me","text":"Khúc hát ấy {xung} đã lâu không hát. Không ngờ {goi} vẫn nhớ."},{"who":"A","text":"Trẫm không nhớ lời, chỉ nhớ điệu. Nếu {goi} hát lại, trẫm sẽ nhận ra."},{"who":"me","text":"Một khúc hát cũ gọi cả một thời đã xa. Để {xung} nghĩ xem nên hát thế nào."}]}},
{"id":"j68:j68c-emp-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư gấp biên cương dấu ấn Binh bộ đặt trước mặt ngươi, Hoàng thượng thở nặng, quầng mệt hằn dưới mắt."},{"who":"A","text":"Mấy hôm nay bắc cương có tin xấu, trẫm thấy khó thở. Trẫm đến đây, cũng chỉ vì không biết đi đâu."},{"who":"me","text":"Nhìn {goi} mệt thế này, {xung} xót lắm. Tin ấy xấu đến mức nào?"},{"who":"A","text":"Chưa rõ hết. Trẫm không muốn nói với triều thần, vì họ sẽ đổ lỗi cho nhau."},{"who":"me","text":"Một người gánh cả giang sơn mà phải đến đây tìm chỗ thở. Để {xung} nghĩ cách giúp."}]}},
{"id":"j68:j68c-emp-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa phùn rắc ngoài hiên, đôi nến đỏ sáp đỏ dấu Nội vụ phủ cháy lặng lẽ, người hầu đã bị đuổi hết ra ngoài."},{"who":"A","text":"Đêm nay trẫm chỉ muốn ngồi yên cạnh {goi}, không bàn việc nước. Cứ thế thôi."},{"who":"me","text":"Mưa phùn, nến đỏ, người hầu đã lui. {Goi} ngồi đây, {xung} thấy khung cảnh yên bình hiếm có."},{"who":"A","text":"Trẫm hiếm khi được thế này. Đừng nghĩ gì, đừng lo gì."},{"who":"me","text":"Một đêm không việc nước, chỉ có hai người. {Xung} cần nghĩ xem nên cùng {goi} ra sao."}]}},
{"id":"j68:j68c-emp-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tách trà sứ hồng nét vẽ mẫu đơn dấu cung ngươi khựng lại giữa không trung, Hoàng thượng vừa lỡ miệng, cả cung im phăng phắc."},{"who":"A","text":"Ôi... trẫm... trẫm lỡ lời. {Goi} đừng để ý, chỉ là trẫm nhầm tên."},{"who":"me","text":"Tên ấy không phải tên {xung}. Trước mặt cả cung, {goi} lỡ lời như thế, ai nấy đều nghe thấy."},{"who":"A","text":"Trẫm không có ý gì, thật đấy. Trẫm mệt, đầu óc lẫn lộn."},{"who":"me","text":"Một lời nhầm, mà cả cung nhìn. Để {xung} nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-emp-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh ngọc hổ phù khắc dấu Binh bộ, đường cắt tinh xảo, được đặt vào lòng bàn tay ngươi, Hoàng thượng thì thầm sát tai."},{"who":"A","text":"Triều đình sắp có biến. Trẫm chỉ tin {goi}, mảnh hổ phù này xin {goi} giữ kín."},{"who":"me","text":"Hổ phù binh quyền, {xung} sao dám giữ? Một mảnh ngọc mà nặng cả sơn hà."},{"who":"A","text":"Trẫm đã chọn rồi. Ngoài {goi}, trẫm không tin ai khác."},{"who":"me","text":"Lòng tin lớn đến mức này, {xung} sợ chính mình gánh không nổi. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-emp-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây quạt giấy vẽ cá chép bị Hoàng thượng cầm như quạt mà vẫy, ngài hát lạc điệu, cung nữ ngoài hiên cười rúc rích."},{"who":"A","text":"À ơi, cái ru em này trẫm hát sao nhỉ? Nghe quen mà chẳng nhớ tiếng nào."},{"who":"me","text":"{Goi} hát lạc điệu cả rồi. Cung nữ ngoài hiên cười không nhịn được."},{"who":"A","text":"Cười thì cười, trẫm đòi học. {Goi} dạy trẫm đi."},{"who":"me","text":"Hoàng thượng cầm quạt vẫy như tướng cầm cờ, vừa đáng yêu vừa buồn cười. Để {xung} nghĩ cách dạy."}]}},
{"id":"j68:j68c-emp-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chuỗi tràng hạt gỗ trầm hạt thơm dấu Nội vụ phủ nằm bên một món lễ khác, Hoàng thượng đặt cả hai trước mặt ngươi, nét mặt bối rối."},{"who":"A","text":"Đại lễ sắp đến, trẫm phải chọn lễ dâng Thái hậu. Hai món này, trẫm sợ chọn sai."},{"who":"me","text":"Một chuỗi tràng hạt thơm, một món lễ ấm. {Goi} nhờ {xung} chọn, tức là rất tin."},{"who":"A","text":"Trẫm tin gu của {goi}. Nói đi, trẫm nghe."},{"who":"me","text":"Lựa lễ dâng Thái hậu, có chữ hiếu, có chữ khéo. Để {xung} nghĩ cho thấu."}]}},
{"id":"j68:j68c-emp-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc áo cũ vải thô của mẹ còn thoảng mùi nhà, ngươi ôm trước ngực, mắt đỏ hoe khi Hoàng thượng bước vào."},{"who":"A","text":"Vì sao {goi} khóc? Ai làm {goi} buồn, nói trẫm nghe."},{"who":"me","text":"Không ai làm {xung} buồn cả. Chiếc áo của mẹ, {xung} mang theo từ nhà, nhìn thấy nên nhớ."},{"who":"A","text":"Nhớ nhà ư? Trẫm không muốn {goi} giấu. Cung này cũng là nhà của {goi}."},{"who":"me","text":"Nỗi nhớ nhà thật khó nói. Sợ nói ra thành than thở. Để {xung} nghĩ cách đáp."}]}},
{"id":"j68:j68c-emp-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giỏ hoa lài tre đan được Hoàng thượng cầm làm bộ như đến từ đầu, vạt áo ngài còn dính phấn hoa của cung khác."},{"who":"A","text":"Trẫm đến thăm {goi}, mang theo giỏ hoa này. Trẫm đi thẳng đến đây từ đầu."},{"who":"me","text":"Giỏ hoa lài thơm thật. Nhưng vạt áo {goi} sao lại dính phấn hoa nơi khác?"},{"who":"A","text":"À... chắc trẫm đi ngang vườn. Trẫm không nhầm cung nào cả."},{"who":"me","text":"Hoàng thượng nói dối một cách vụng về, mà đáng yêu. Để {xung} nghĩ cách đáp lại."}]}},
{"id":"j68:j68c-emp-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc đèn lồng vẽ tay nét vẽ lạ dấu cung {B} bị đặt giữa sảnh, Hoàng thượng quở trách, cả sảnh nhìn ngươi chờ phản ứng."},{"who":"A","text":"Chiếc đèn lồng này hỏng, là lỗi của {goi}. Trước mặt cả cung, trẫm không thể bỏ qua."},{"who":"me","text":"Đèn này nét vẽ lạ, không phải của cung {xung}, dấu ấn lại là của cung {B}. {Xung} thấy lạ."},{"who":"A","text":"Trẫm chỉ nghe nói thế. {Goi} có điều gì muốn nói không?"},{"who":"me","text":"Một lời quở trước cả sảnh, đáp thế nào cho khéo, {xung} cần nghĩ."}]}},
{"id":"j68:j68c-emp-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát thuốc nóng sứ ngự dụng hơi bốc nghi ngút, Hoàng thượng thân chinh ngồi canh bên giường, thái y đứng ngoài không dám bước vào."},{"who":"A","text":"{Goi} bệnh mấy hôm rồi, trẫm đến thăm. Thuốc này trẫm tự mang, {goi} dùng đi."},{"who":"me","text":"Thuốc trong bát sứ ngự dụng, hơi còn nóng. {Goi} thân chinh đến, thái y cũng không dám vào."},{"who":"A","text":"Trẫm nói rồi, chỉ cần {goi} khỏi. Việc triều để sau."},{"who":"me","text":"Một lời mà nặng như núi, lại dịu như gió. Để {xung} nghĩ cách đáp."}]}},
{"id":"j68:j68c-emp-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản chiếu chỉ cấm cung giấy vàng ấn Hoàng hậu đặt nhẹ trên án, Hoàng thượng vô tình thốt lời, rồi lặng lẽ nhìn ngươi."},{"who":"A","text":"Chiếu chỉ cấm cung của Hoàng hậu khiến trẫm không vừa ý. {Goi} thấy thế nào?"},{"who":"me","text":"Một lời như vô tình mà ánh mắt lại chờ. {Xung} nghĩ đây có thể là phép thử."},{"who":"A","text":"Trẫm không có ý gì. Chỉ muốn nghe {goi} nói thật."},{"who":"me","text":"Nói thật hay nói khéo, đều có cái giá. Để {xung} nghĩ cho cẩn thận."}]}},
{"id":"j68:j68c-emp-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc vòng bạc trẻ sơ sinh khắc chữ phúc nằm trong tay Hoàng thượng, ngài ngồi lặng, vai khẽ rung."},{"who":"A","text":"Cung này vẫn chưa có ai để nối dõi. Trẫm nhìn chiếc vòng này mà lòng chua xót."},{"who":"me","text":"Vòng bạc nhỏ khắc chữ phúc, hẳn là món trẫm giữ từ lâu. {Goi} nhìn nó như nhìn một giấc mơ."},{"who":"A","text":"Trẫm không muốn nói với triều thần. Chỉ muốn nói với {goi}."},{"who":"me","text":"Nỗi lòng của bậc quân vương không ai dám nghe. Để {xung} nghĩ xem nên cùng {goi} ra sao."}]}},
{"id":"j68:j68c-emp-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc đồng hồ nước nhỏ bằng đồng thau dấu cống phẩm tí tách chảy, Hoàng thượng háo hức, mắt sáng như trẻ nhỏ."},{"who":"A","text":"Nhìn này! Đồng hồ nước vừa được tiến cống, chạy đúng giờ lắm. {Goi} đừng làm hỏng nó nhé."},{"who":"me","text":"Đồng thau sáng bóng, nước chảy từng giọt. {Goi} vui như được món đồ chơi mới vậy."},{"who":"A","text":"Trẫm vui thật. Cả ngày triều chính căng thẳng, có món này trẫm cũng đỡ."},{"who":"me","text":"Một món đồ lạ mà làm Hoàng thượng cười. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thanh đoản đao chuôi khắc dấu Tuần phòng dính máu nằm trong tay Hoàng thượng, đêm ghé cung, ngài chưa nói một lời."},{"who":"A","text":"Trẫm vừa thoát một vụ ám sát hụt. Trẫm không muốn về cung, chỉ muốn một nơi yên tĩnh."},{"who":"me","text":"Thanh đao còn dính máu, tay {goi} cũng run. Nơi này là chỗ yên tĩnh {goi} cần."},{"who":"A","text":"Trẫm không sợ chết. Trẫm sợ không biết ai là kẻ đứng sau."},{"who":"me","text":"Một đêm nguy hiểm mà {goi} tìm đến đây. {Xung} cần nghĩ nên làm gì cho an toàn."}]}},
{"id":"j68:j68c-emp-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nệm gấm ngự tọa thêu rồng còn dính lông mèo, con mèo của ngươi nằm gọn trong lòng Hoàng thượng, ngài hắt hơi liên hồi."},{"who":"A","text":"Hắt xì! Con mèo của {goi} nhảy vào lòng trẫm. Hắt xì! Trẫm dị ứng lông mèo, nhưng... đừng đuổi nó."},{"who":"me","text":"Mặt {goi} tái cả rồi, mà vẫn gượng cười. Con mèo này được cưng chiều quá nên không biết sợ ai."},{"who":"A","text":"Trẫm là Hoàng thượng, không thể sợ một con mèo. Hắt xì!"},{"who":"me","text":"Vừa thương vừa buồn cười. Để {xung} nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-emp-056","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp bánh an ủi giấy đỏ hoa văn Ngự thiện đặt trước cửa cung, nội giám cúi người dâng, cả cung nhìn ngươi người thương hại, kẻ hả hê."},{"who":"M","text":"{Goi}, nội giám truyền lời Hoàng thượng: đêm nay lễ trọng, Người không thể đến cung {goi}, gửi hộp bánh này để an ủi."},{"who":"me","text":"Hộp bánh có hoa văn Ngự thiện. Hoàng thượng đến cung khác, mà vẫn nhớ gửi quà sang đây."},{"who":"M","text":"Nội giám còn nói, Hoàng thượng tin {goi} sẽ hiểu, đêm lễ trọng có những việc không thể làm khác."},{"who":"me","text":"Nhìn ánh mắt cả cung, ta biết mình đang bị nhìn. Để ta nghĩ cách đáp."}]}},
{"id":"j68:j68c-emp-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm chăn lông cừu mềm dấu cung ngươi phủ lên vai Hoàng thượng, ngài ngả đầu bên án thư, hơi thở đều đều."},{"who":"A","text":"Trẫm... chỉ nghỉ một chút thôi, đọc xong tấu chương này..."},{"who":"me","text":"{Goi} ngủ gật giữa chồng tấu chương rồi. Hơi thở đều, vai thả lỏng, chắc kiệt sức lắm."},{"who":"A","text":"Ai... ai đó... trẫm không ngủ đâu."},{"who":"me","text":"Một người gánh thiên hạ mà ngủ gật như trẻ nhỏ. Để {xung} nghĩ cách giữ giấc ngủ cho {goi}."}]}},
{"id":"j68:j68c-emp-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọn đèn hoa đăng giấy hồng dấu Nội vụ phủ trôi nhẹ trên mặt hồ sen, trăng đầy, thuyền chỉ có hai người."},{"who":"A","text":"Đêm nay trăng đẹp, trẫm mời {goi} dạo thuyền hồ sen. Chỉ có hai ta thôi."},{"who":"me","text":"Mặt hồ phẳng lặng như gương, ngọn đèn hoa đăng soi một vệt hồng. {Goi} chọn đêm đẹp thế này."},{"who":"A","text":"Trẫm hiếm khi được thế này. Đừng nói gì cả, cứ ngắm trăng."},{"who":"me","text":"Một đêm thuyền nhẹ, trăng đầy. {Xung} cần nghĩ xem nên làm gì cho vẹn."}]}},
{"id":"j68:j68c-emp-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh lụa trắng chưa thêu, vẽ phác hoa văn mờ mờ, Hoàng thượng cầm lên hỏi, giọng nhẹ như trách mà như nhắc."},{"who":"A","text":"Ngày nào {goi} từng hứa thêu cho trẫm. Sao trẫm chưa thấy?"},{"who":"me","text":"Mảnh lụa trắng, hoa văn mới phác. {Xung} nhớ ra rồi, quả thật {xung} đã quên."},{"who":"A","text":"Trẫm không trách. Nhưng trẫm vẫn chờ."},{"who":"me","text":"Lời hứa nhỏ mà trong lòng người nhớ lâu. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-emp-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản nhạc phổ riêng giấy vàng chữ nhạc sư nằm trước mặt ngươi, Hoàng thượng không giận, chỉ mong ngươi nói thật."},{"who":"A","text":"Trẫm nghe đồn {goi} quá thân với nhạc sư. Bản nhạc phổ này là gì?"},{"who":"me","text":"Bản nhạc ấy do nhạc sư viết, giấy vàng, chữ ngay ngắn. {Goi} hỏi thế, {xung} biết có người đã đồn."},{"who":"A","text":"Trẫm không giận. Trẫm chỉ muốn {goi} nói thật, đừng giấu."},{"who":"me","text":"Một lời hỏi nhẹ mà ý nặng. Để {xung} nghĩ thật kỹ cách đáp."}]}},
{"id":"j68:j68c-sea-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió xuân thổi mạnh, chiếc diều giấy vướng trên cành đào trước cửa cung, đuôi diều phất phơ, giấy rách một góc."},{"who":"A","text":"{Goi} ơi, diều của {xung} mắc lên cành đào nhà {goi} mất rồi. Dây đứt, giấy cũng rách, {xung} xấu hổ quá."},{"who":"me","text":"Cành đào còn nở hoa, diều lại vướng đúng chỗ ấy, trông cũng như một bức tranh. Ngươi đừng ngượng."},{"who":"A","text":"{Xung} chỉ muốn thả diều cho vui, nào ngờ gió xuân đổi chiều đột ngột. Giờ không biết làm sao với nó."},{"who":"me","text":"Một con diều rách mà làm ngươi đỏ mặt. Để ta nghĩ xem nên gỡ nó xuống thế nào cho khỏi tổn thương thêm."}]}},
{"id":"j68:j68c-sea-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sương muối muộn phủ trắng góc hiên đông, chậu lan vân lá cuộn lại, héo rũ nửa ngọn, cung nhân đứng nhìn nhau chưa ai dám động tay."},{"who":"M","text":"Bẩm {goi}, đêm qua sương muối rơi muộn, chậu lan vân của {goi} héo mất nửa ngọn. Các chậu khác trong vườn cũng thế."},{"who":"me","text":"Lan vân ta chăm từ đầu xuân, lá cuộn lại như bị bỏng lạnh. Các chậu cung khác cũng héo cả sao?"},{"who":"M","text":"Dạ, cung nhân nhìn mà chưa ai dám động tay, sợ làm hỏng thêm."},{"who":"me","text":"Mất cả một mùa công chăm sóc trong một đêm. Ta cần nghĩ xem nên cứu thế nào cho phải."}]}},
{"id":"j68:j68c-sea-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bùn còn ướt trên chiếc tổ én mới dựng dưới mái hiên, một cặp én lượn quanh, kêu líu lo như đang khoe công."},{"who":"M","text":"Bẩm {goi}, cặp én vừa làm tổ dưới mái hiên cung {xung}. Cung nhân sợ phân chim làm bẩn bậc thềm nên xin dời tổ đi."},{"who":"me","text":"Én làm tổ nhà nào là điềm lành cho nhà ấy. Nhưng cung nhân sợ bẩn cũng có lý."},{"who":"M","text":"Dạ, bậc thềm mới lát xong, ai cũng tiếc. Nhưng nô tỳ thấy cặp én chăm chỉ lắm."},{"who":"me","text":"Một tổ én mà gánh cả ý trời lẫn chuyện sạch sẽ. Để ta nghĩ xem nên quyết ra sao."}]}},
{"id":"j68:j68c-sea-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa phùn kéo từ sáng, giá phơi hiên tây ướt sũng, {A} ôm chồng lụa thêu trước ngực, vai áo ướt đẫm, tấm lụa bên dưới đã loang màu."},{"who":"A","text":"Bẩm {goi}, {xung} phơi lụa mà không ngờ mưa kéo đến. {Xung} ôm vào nhưng tấm lụa thêu đã loang màu rồi."},{"who":"me","text":"Mép lụa loang như vết nước mắt. Ngươi dầm mưa đến ướt cả vai, còn lo lụa hơn lo thân mình."},{"who":"A","text":"Lụa thêu quý, {xung} xót lắm. Là lỗi của {xung}, không canh trời cho kỹ."},{"who":"me","text":"Mưa xuân khó đoán, không trách ngươi. Việc cứu tấm lụa này, để ta nghĩ."}]}},
{"id":"j68:j68c-sea-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đến tiết thanh minh, trời âm u như muốn mưa, {A} đứng lặng ngoài cửa, tay nắm gói giấy vàng mã và nén hương gói chặt trong khăn."},{"who":"A","text":"{Goi}, hôm nay là thanh minh. Quê {xung} xa, mộ cha mẹ mấy năm rồi chưa có ai thắp hương."},{"who":"me","text":"Gói giấy vàng và nén hương ngươi gói chặt thế, hẳn đã chuẩn bị từ lâu. Sao không nói sớm?"},{"who":"A","text":"{Xung} không dám. Việc cung nhiều, {xung} sợ mình xin ra ngoài là lỡ việc."},{"who":"me","text":"Lòng hiếu của ngươi, ta thấy rõ. Để ta nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-sea-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sấm đầu xuân rền vang, con mèo tam thể vòng chuông bạc lẻn qua tường, nằm vắt trên bậc thềm, mắt mở to hoảng hốt."},{"who":"A","text":"{Goi}, mèo của {xung} hoảng sợ tiếng sấm chạy mất, {xung} cho người đi tìm khắp nơi mà chẳng thấy."},{"who":"me","text":"Mèo tam thể vòng chuông bạc đang nằm trên bậc thềm cung {xung}, run như lá. Chắc nó sợ sấm lắm."},{"who":"A","text":"Giọng {xung} gắt, {goi} đừng chấp. {Xung} lo cho nó, như lo cho đứa con nhỏ."},{"who":"me","text":"Lo cho mèo như lo cho con, {xung} hiểu. Để {xung} nghĩ xem nên trả nó cho {goi} thế nào."}]}},
{"id":"j68:j68c-sea-007","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau cơn mưa xuân, rêu bờ đá ướt trơn, một con cá chép đỏ giãy giụa nơi bờ ao ngự uyển, cung nhân xúm quanh bàn tán."},{"who":"M","text":"Bẩm {goi}, nước ao dâng tràn, một con cá chép đỏ lên nằm trên rêu bờ đá. Người thì bảo nấu canh, kẻ lại bảo thả đi."},{"who":"me","text":"Cá chép đỏ vốn là điềm lành. Nó còn thở, thân còn ướt, chắc vừa lạc khỏi ao thôi."},{"who":"M","text":"Dạ, cung nhân đi ngang đều xúm lại nhìn. Nô tỳ chưa biết nên giữ hay thả."},{"who":"me","text":"Một con cá mà chia ý cả đám người. Để ta nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-sea-008","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa hè ập xuống đột ngột, chồng sách chép tay còn phơi nơi hiên đông, bìa nâu sẫm nước, chữ nhòe dần từng trang."},{"who":"M","text":"Bẩm {goi}, mưa ập xuống đúng lúc phơi sách. Cung nhân chạy ra ôm sách, mỗi người một ý, chẳng ai biết làm sao."},{"who":"me","text":"Sách chép tay nhòe chữ, tiếc cả công người chép. Hỏng bao nhiêu trang rồi?"},{"who":"M","text":"Dạ, nhiều trang đã ướt hẳn, mực loang. Nô tỳ sợ chậm thêm thì mất hết."},{"who":"me","text":"Từng trang sách là từng tâm huyết. Ta cần nghĩ cách cứu cho phải lẽ."}]}},
{"id":"j68:j68c-sea-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ve sầu rền khắp cành hòe trước cửa, {A} cầm sào dính nhựa lén rình quanh gốc, cả sân cung nhân nín thở nhìn theo."},{"who":"A","text":"{Goi} mất giấc trưa vì ve kêu, {xung} cầm sào ra bắt chúng. {Goi} đừng lo, {xung} nhẹ tay lắm."},{"who":"me","text":"Cả sân cung nhân ngó theo, ve thì còn kêu mà người đã lo thay. Sào dính ấy ngươi làm sao thế?"},{"who":"A","text":"{Xung} phết nhựa sáng nay. Chỉ cần ve đậu gần là dính ngay."},{"who":"me","text":"Một tấm lòng chu đáo mà ồn ào cả sân. Để ta nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-sea-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hầm băng của Nội vụ phủ chỉ phát từng cục nhỏ theo phẩm, cung nhân khiêng khay băng nhỏ, {A} sai người sang với giọng nhã nhặn."},{"who":"A","text":"{Goi}, hầm băng năm nay ít, {xung} sai người sang xin thêm phần băng của {goi}. {Xung} sợ nắng làm hỏng da."},{"who":"me","text":"Sổ phát băng ghi theo phẩm, cung nào cũng chỉ vừa đủ. {Goi} xin thêm, {xung} cũng khó xử."},{"who":"A","text":"Chỉ là chút băng thôi. Da {xung} vốn mỏng, hè đến là sạm, {goi} thương {xung}."},{"who":"me","text":"Một cục băng nhỏ mà thành chuyện lớn. Để {xung} nghĩ cách đáp thế nào."}]}},
{"id":"j68:j68c-sea-011","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm hè oi nồng không một hơi gió, lư hương ngải khói xám bay thẳng ngoài hiên, tiếng muỗi vo ve ngoài song."},{"who":"M","text":"Bẩm {goi}, trong phòng nóng quá, nô tỳ nghĩ nên kê giường tre ngoài hiên. Ngoài ấy có lư hương ngải xua muỗi."},{"who":"me","text":"Ngoài hiên mát thì mát, nhưng muỗi cũng nhiều. Khói ngải bay thẳng thế này, trời chắc không có gió."},{"who":"M","text":"Dạ, giường tre đã sẵn. Chỉ chờ {goi} quyết."},{"who":"me","text":"Một đêm hè oi nồng, ngủ trong hay ngủ ngoài, ta cần nghĩ xem nên chọn thế nào."}]}},
{"id":"j68:j68c-sea-012","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cành hòe lớn gãy ngang sau đêm giông, đè nát một góc mái hiên, bồn sứ trồng trúc vỡ làm đôi, cung nhân đứng nhìn chưa ai dám nhận việc dọn."},{"who":"M","text":"Bẩm {goi}, giông đêm qua đánh gãy cành hòe trước cổng, cành rơi đè mái hiên và vỡ cả bồn sứ trồng trúc."},{"who":"me","text":"Bồn sứ vỡ làm đôi, trúc nằm nghiêng. Ta nhìn mà tiếc cả cành hòe lẫn bồn sứ."},{"who":"M","text":"Cung nhân ai cũng đứng nhìn, chưa ai dám nhận dọn. Sợ nhỡ làm hỏng thêm."},{"who":"me","text":"Một đêm giông để lại cả một mớ ngổn ngang. Ta cần nghĩ xem nên bắt đầu từ đâu."}]}},
{"id":"j68:j68c-sea-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tối hè, lồng tre đầy đom đóm đặt trên bàn nhỏ, ánh sáng lập lòe khắp phòng, cung nhân kéo đến ồn ào ngoài ngưỡng cửa."},{"who":"A","text":"{Goi}, {xung} bắt đom đóm cả buổi chiều, bỏ vào lồng tre này. {Goi} xem, sáng như trăng nhỏ vậy."},{"who":"me","text":"Cả phòng lập lòe ánh sáng, đẹp như một giấc mơ. Mấy cung nhân kia ngoài cửa kéo đến xem rồi."},{"who":"A","text":"{Xung} chỉ muốn {goi} thấy một chút đẹp giữa mùa hè oi bức."},{"who":"me","text":"Một lồng ánh sáng nhỏ mà gói cả mùa hè. Để ta nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-sea-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắng hè gắt làm vại sành nơi góc sân nứt dọc thân, nước rỉ từng giọt xuống nền, {A} đứng cạnh, mặt đầy lo lắng."},{"who":"A","text":"Bẩm {goi}, vại sành đựng nước ở góc sân đã nứt dọc thân, nước rỉ ra từng giọt. Mùa này nước sạch quý như bạc."},{"who":"me","text":"Vết nứt chạy dọc thân vại, nhìn mà xót. Trong vại còn bao nhiêu nước?"},{"who":"A","text":"Còn nhiều ạ. Nếu không xử lý, chỉ vài ngày là cạn hết."},{"who":"me","text":"Một chiếc vại nứt mà gánh cả nguồn nước cả cung. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-sea-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thu cuốn chiếc khăn lụa thêu hạc bay qua tường, rơi vào sân cung {A}, {A} cầm lên ngắm, ánh mắt khó đoán."},{"who":"A","text":"{Goi}, chiếc khăn lụa thêu hạc trắng này là của {goi} sao? Gió cuốn nó rơi vào sân {xung}."},{"who":"me","text":"Góc thêu hạc trắng ở một đầu, đúng là khăn của {xung}. Không ngờ gió thu lại mang sang tận sân {goi}."},{"who":"A","text":"{Xung} chưa trả, cũng chưa nói gì, vì ngắm mãi đường thêu. Khéo lắm, {goi} thêu à?"},{"who":"me","text":"Một chiếc khăn bay qua tường mà cũng thành chuyện giữa hai cung. Để {xung} nghĩ cách đáp."}]}},
{"id":"j68:j68c-sea-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân ngự uyển, cúc ngọc bích cánh dài như tơ nở rộ, {A} bưng chậu hoa đi khoe khắp nơi, ánh mắt liếc về phía chậu của ngươi vừa hé nở."},{"who":"A","text":"{Goi} xem chậu cúc ngọc bích của {xung} này, cánh dài như tơ, đẹp không? Nghe nói chậu của {goi} chưa nở hết."},{"who":"me","text":"Chậu của {xung} vừa nở nửa chừng, còn phải đợi thêm vài ngày nữa. Hoa nào cũng có thời của nó."},{"who":"A","text":"{Xung} chỉ nói thật thôi. Hôm nay mọi người đều đến xem, tiếc là chậu {goi} chưa kịp khoe."},{"who":"me","text":"Lời khoe nhẹ mà ý sâu. Để {xung} nghĩ xem nên đáp ra sao cho khỏi mất lòng nàng."}]}},
{"id":"j68:j68c-sea-017","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cây hồng sau sân chín đỏ au, chim sâu đã mổ gần nửa, trên hiên sau giỏ hồng chín xếp ngay ngắn những quả đẹp nhất."},{"who":"M","text":"Bẩm {goi}, cây hồng sau sân chín rộ, nô tỳ hái được một giỏ, lựa ra những quả đẹp nhất, chờ {goi} phân phó."},{"who":"me","text":"Quả đỏ au thế này, chim sâu cũng đã chọn trước. Ngươi lựa kỹ lắm."},{"who":"M","text":"Dạ, phần chim mổ nô tỳ để lại cho chúng. Phần đẹp để dành cho {goi}."},{"who":"me","text":"Một giỏ hồng chín mà gửi cả mùa thu. Để ta nghĩ nên chia thế nào cho vừa lòng cả cung."}]}},
{"id":"j68:j68c-sea-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sương thu xuống sớm, {A} mặc áo mỏng đứng gác hiên đêm, vai co lại, hắt hơi từng cơn dưới ánh đèn lạnh."},{"who":"A","text":"Bẩm {goi}, {xung} không sao, chỉ hắt hơi chút thôi. {Goi} đừng bận lòng."},{"who":"me","text":"Áo mỏng giữa sương thu, ngươi còn nói không sao. Tủ áo bông của Nội vụ phủ còn ghi sổ chưa phát, ta biết."},{"who":"A","text":"Dạ, {xung} nghe nói áo bông ít, chỉ đủ cho vài người. {Xung} không dám xin."},{"who":"me","text":"Một cơn hắt hơi giữa đêm mà thấu cả nỗi thiếu thốn. Để ta nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-sea-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lá thu rụng đầy sân, chiếc trâm bạc khảm ngọc nằm giữa đống lá, dấu Nội vụ phủ khắc rõ, {A} đứng cách xa như sợ chạm vào."},{"who":"A","text":"Bẩm {goi}, {xung} quét sân gom lá thì thấy chiếc trâm bạc khảm ngọc này lẫn trong đống lá. {Xung} không dám cầm, chạy vào hỏi {goi}."},{"who":"me","text":"Trâm có khắc dấu Nội vụ phủ, hẳn là của một người trong cung làm rơi. Ngươi nhìn thấy ai quanh đây không?"},{"who":"A","text":"Không ạ. Sân vắng, chỉ có lá rụng. {Xung} sợ nhỡ đụng vào lại bị nghi."},{"who":"me","text":"Ngươi thật thà, ta thấy yên lòng. Còn trâm này, ta cần nghĩ nên xử trí ra sao."}]}},
{"id":"j68:j68c-sea-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau cơn mưa thu, giỏ nấm rừng còn ướt, chân nấm trắng đốm nâu, thái y đứng gần nhíu mày, {A} hớn hở dâng lên."},{"who":"A","text":"Bẩm {goi}, {xung} hái nấm ở bìa vườn sau cơn mưa, định nấu canh dâng {goi}. Nấm tươi lắm, thơm nữa."},{"who":"me","text":"Chân nấm trắng đốm nâu, ta chưa từng thấy loại này. Thái y đứng cạnh kia vừa nhíu mày đấy."},{"who":"A","text":"Dạ, {xung} hái chỗ gần gốc cây mục, thấy mọc nhiều nên mừng quá."},{"who":"me","text":"Tấm lòng dâng canh thì quý, nhưng nấm lạ có thể hại người. Ta cần nghĩ cho cẩn thận."}]}},
{"id":"j68:j68c-sea-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió bấc về, kho than sụt xuống thấy rõ, {A} đứng bên sọt than hồng, giọng nhỏ như sợ làm phiền."},{"who":"A","text":"Bẩm {goi}, kho than cung {xung} sụt xuống nhiều rồi. {Xung} muốn hỏi có nên xin thêm than ở Nội vụ phủ không."},{"who":"me","text":"Sổ ghi cấp than theo phẩm, ngươi cũng biết. Xin thêm cũng có lý, mà cũng dễ mang tiếng."},{"who":"A","text":"{Xung} sợ làm phiền {goi}, nhưng cung nhân gác đêm đã rét lắm."},{"who":"me","text":"Một sọt than mà chứa cả chuyện thể diện lẫn chuyện cái rét. Để ta nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-sea-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hồ ngự uyển đóng băng mỏng như lụa, {A} xỏ đôi giày trượt bằng sừng đế gỗ buộc dây da, mắt sáng rỡ, cung nhân quây quanh người cổ vũ kẻ can ngăn."},{"who":"A","text":"{Goi}, băng đã đóng rồi, {xung} muốn đem giày trượt ra thử. Mấy cung nhân cũng rủ {xung} cùng trượt."},{"who":"me","text":"Băng mỏng như lụa, ngươi không sợ nứt à? Có người ngăn, có người cổ vũ, ngươi nghe ai?"},{"who":"A","text":"{Xung} muốn nghe {goi}. Nếu {goi} bảo không, {xung} sẽ không trượt."},{"who":"me","text":"Ngươi biết chờ lời ta, ta thấy vui. Nhưng quyết thế nào, ta cần nghĩ."}]}},
{"id":"j68:j68c-sea-023","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió bấc thổi mạnh cả đêm, lò sưởi gian ngoài bập bùng, tàn lửa bay lên rèm, chậu than đồng quai nóng bỏng đã được nhấc khỏi lò."},{"who":"M","text":"Bẩm {goi}, lò sưởi gian ngoài bập bùng cả đêm, tàn lửa bay lên rèm. Nô tỳ vội nhấc chậu than khỏi lò, tay còn run."},{"who":"me","text":"Rèm còn nguyên không? Lửa lan đến đâu rồi?"},{"who":"M","text":"Dạ, chưa cháy ạ. Nhưng nếu gió còn mạnh thế này, nô tỳ sợ không giữ nổi."},{"who":"me","text":"Một đêm gió bấc mà lửa gần sát người. Ta cần nghĩ xem nên xử trí thế nào cho an."}]}},
{"id":"j68:j68c-sea-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần cuối năm, mâm mứt và bánh cúng bày trên bàn thờ nhỏ ở bếp cung, khói hương nhẹ bay, {A} dâng lên mà mày hơi nhíu."},{"who":"A","text":"Bẩm {goi}, năm nay {xung} xin phép đưa ông Táo như mọi năm. Nhưng kho bếp thiếu mật, phải bớt đi vài món."},{"who":"me","text":"Mâm cúng đã bày, mứt còn ít, bánh cũng ít hơn năm trước. Ta thấy được."},{"who":"A","text":"{Xung} không muốn làm sơ lễ, mà cũng không có thêm. {Xung} chờ {goi} quyết."},{"who":"me","text":"Một mâm cúng mà gửi cả mong ước cuối năm. Để ta nghĩ nên giữ lễ thế nào cho vẹn."}]}},
{"id":"j68:j68c-sea-025","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tuyết đè nặng giàn dây leo trước cửa, giàn nghiêng hẳn, chiếc đèn lồng lụa vẽ mai chao đảo như muốn rơi, cung nhân đứng nhìn chưa ai bước vào."},{"who":"M","text":"Bẩm {goi}, tuyết đêm qua đè nặng giàn dây leo, chiếc đèn lồng lụa vẽ mai treo trên đó chao đảo muốn rơi."},{"who":"me","text":"Đèn vẽ mai còn nguyên, lụa chưa hề rách. Nhưng giàn nghiêng như thế, chỉ cần một cơn gió là đổ."},{"who":"M","text":"Dạ, cung nhân đứng nhìn mà chưa ai dám bước vào, sợ giàn sập."},{"who":"me","text":"Một chiếc đèn mà gánh cả sự an toàn lẫn tiếc nuối. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-sea-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trời quang hiếm hoi giữa mùa đông, chồng chăn bông còn ẩm trên sân phơi, {A} khệ nệ ôm từng tấm ra nắng."},{"who":"A","text":"Bẩm {goi}, mấy hôm nay chăn ẩm lạnh người, nay trời quang, {xung} xin đem cả chồng chăn bông ra phơi. Nhưng sân chỉ đủ chỗ một nửa."},{"who":"me","text":"Chăn bông còn ẩm, ngươi ôm từng tấm thế này chắc mệt lắm. Còn nửa kia thì sao?"},{"who":"A","text":"Nửa kia phải đợi. Hôm nay nắng đẹp, mai có thể lại mưa."},{"who":"me","text":"Một mảnh sân hẹp mà chia người ấm người lạnh. Để ta nghĩ nên phơi chăn ai trước."}]}},
{"id":"j68:j68c-sea-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đường tuyết trơn ngay trước cổng cung, kiệu Hoàng thượng dừng lại vì cung nhân khiêng không vững, thái giám còn giữ bao tro bếp sẵn để rắc đường."},{"who":"A","text":"Đường này trơn quá, kiệu của trẫm phải dừng lại. {Goi} xem, có cách nào cho cung nhân khiêng cho vững không?"},{"who":"me","text":"Trước cổng cung {xung} có sẵn bao tro bếp, rắc lên là đường đỡ trơn. {Goi} ngồi đó thì có lạnh không?"},{"who":"A","text":"Trẫm không sao. Chỉ sợ cung nhân ngã, sẽ đau."},{"who":"me","text":"Một đoạn đường tuyết giữ chân cả kiệu rồng. Để {xung} nghĩ cách cho chu đáo."}]}},
{"id":"j68:j68c-sea-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sương dày đến mức không thấy bậc thềm, ánh đèn lồng giấy dầu mờ mờ trong sương, {A} lạc mất một đoạn, tiếng bước chân ai đó vọng xa xa."},{"who":"A","text":"{Goi} ơi! {Xung} đến đón {goi} từ vườn về mà lạc mất đường rồi! Sương dày quá, không thấy bậc thềm đâu cả."},{"who":"me","text":"Ta nghe tiếng ngươi gọi, nhưng không thấy bóng. Đèn của ngươi chỉ còn một đốm mờ."},{"who":"A","text":"{Xung} nghe cả tiếng bước chân ai đó xa xa. {Xung} không biết là ai."},{"who":"me","text":"Một đêm sương mà lạc cả người lẫn đèn. Để ta nghĩ cách tìm ngươi."}]}},
{"id":"j68:j68c-sea-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa dầm cả tuần, chồng áo lụa ẩm mốc, mép tay áo đã chuyển màu, {A} ôm đứng trước cửa, người trong cung nhìn sang nửa thương nửa cười."},{"who":"A","text":"Bẩm {goi}, mưa dầm cả tuần, {xung} không còn áo khô mà mặc. Chồng áo lụa này ẩm mốc hết rồi."},{"who":"me","text":"Mép tay áo đã đổi màu, mùi mốc nồng cả hiên. Ngươi mặc áo ẩm thế này sao được."},{"who":"A","text":"{Xung} xin lỗi, không biết giữ áo. Mưa dầm lâu quá, lụa nào cũng hỏng."},{"who":"me","text":"Mưa dầm khó trách ai. Ta cần nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-sea-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa ập xuống giữa buổi dạo vườn, chiếc dù giấy dầu nan tre bung một chiếc, {A} giương lên che cho ngươi mà chỉ vừa một người."},{"who":"A","text":"{Goi}, mau vào dưới dù đi, kẻo ướt. Dù này nan tre bung một chiếc, chỉ che vừa một người."},{"who":"me","text":"Quanh đây ai cũng chạy tránh dưới tàn cây. Ngươi chỉ lo che cho ta, vai ngươi đã ướt rồi."},{"who":"A","text":"{Xung} không sao, {goi} đừng ướt. Dù bé, nhưng {xung} giữ cho {goi}."},{"who":"me","text":"Một chiếc dù nhỏ mà chứa cả tấm lòng. Để ta nghĩ xem nên làm thế nào cho vẹn."}]}},
{"id":"j68:j68c-sea-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau mưa, giỏ măng tre còn dính đất nằm trước cửa cung, người của {A} cúi chào, kèm lời nhắn nhỏ nhẹ."},{"who":"A","text":"{Goi}, {xung} cho người đem giỏ măng vừa đào ở bụi tre sau cung. Nghe nói cung {goi} thiếu rau xanh, mong {goi} nhận cho."},{"who":"me","text":"Măng còn dính đất, chân măng tươi non. {Goi} lại để ý cả chuyện cung {xung} thiếu rau xanh."},{"who":"A","text":"Chỉ là chút quà quê, đừng ngại. {Xung} chỉ muốn chia sẻ."},{"who":"me","text":"Quà nhỏ mà ơn lớn. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-sea-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió xuân dịu, hộp bánh thuốc táo đỏ phủ lụa vàng trên nắp, cung nhân đứng quanh xì xào vì hộp thuốc nhìn lại giống bánh."},{"who":"A","text":"{Goi}, đây là bánh thuốc táo đỏ {xung} mới nấu, bổ cho mùa chuyển tiết. {Goi} dùng thử khi còn ấm nhé."},{"who":"me","text":"Hộp phủ lụa vàng, nhìn lại giống bánh thật. Cung nhân cũng xì xào cả rồi."},{"who":"A","text":"{Xung} làm theo bài thuốc của Thái y viện, không có gì đáng ngại. {Goi} cứ yên tâm."},{"who":"me","text":"Thuốc bổ mà trông như bánh, ăn vào là chuyện thân thể. Để {xung} nghĩ xem nên dùng thế nào."}]}},
{"id":"j68:j68c-sea-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngày hè oi bức, mâm mận chín ngâm giếng nước giếng còn đọng trên quả, đặt trước cửa cung, kèm lời hỏi thăm."},{"who":"A","text":"{Goi}, hôm nay oi quá, {xung} gửi sang một mâm mận ngâm giếng cho mát. Không biết cung {goi} hôm nay thế nào?"},{"who":"me","text":"Mận chín đỏ, nước giếng còn đọng trên quả, nhìn đã thấy mát. Cung {xung} đang thiếu mấy món giải khát, {goi} biết sao?"},{"who":"A","text":"{Xung} đoán thế. Hè năm nào cung nào cũng thiếu, nên gửi chút cho {goi}."},{"who":"me","text":"Một mâm mận mà thấu cả nỗi lòng chu đáo. Để {xung} nghĩ xem nên đáp lại ra sao."}]}},
{"id":"j68:j68c-sea-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Canh khuya gió thu lạnh, {A} đứng một mình ngoài hiên cung nàng, ngón tay lần chiếc vòng ngọc cũ ngả màu vàng nhạt trên cổ tay."},{"who":"A","text":"{Goi} cũng chưa ngủ sao? {Xung} đứng đây hóng gió một lát, đừng để ý."},{"who":"me","text":"Gió thu đêm nay buốt lắm, {goi} mặc mỏng thế này. Vòng ngọc ấy ngả vàng rồi, chắc đeo đã nhiều năm."},{"who":"A","text":"Vòng này là của một người, đeo mãi thành quen. Mỗi lần gió thu về, {xung} lại nhớ."},{"who":"me","text":"Nhớ một người trong đêm thu, {xung} hiểu nỗi ấy. Để {xung} nghĩ xem nên làm gì cho phải."}]}},
{"id":"j68:j68c-sea-035","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa lớn mấy ngày liền, nước mương ngự uyển dâng ngập sân sau, hòm gỗ đựng sổ sách bị nước đẩy trôi nghiêng ra phía cổng."},{"who":"M","text":"Bẩm {goi}, nước mương dâng ngập sân sau, hòm gỗ đựng sổ sách của kho đang trôi dần ra cổng. Cung nhân hoang mang, kẻ lo cứu đồ, người lo cứu mình."},{"who":"me","text":"Hòm sổ sách trôi nghiêng, nước đã ngập đến đâu rồi? Người có an toàn không?"},{"who":"M","text":"Dạ, nước chưa tới gối, nhưng nếu mưa thêm thì khó lường."},{"who":"me","text":"Người và đồ, cái nào cũng quý. Ta cần nghĩ xem nên làm gì trước."}]}},
{"id":"j68:j68c-sea-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm hội đèn, mặt ao ngự đông người chen chúc, hoa đăng giấy hồng bấc đã thắp sẵn nằm trong tay {A}, ánh mắt tha thiết."},{"who":"A","text":"Bẩm {goi}, {xung} xin phép thả hoa đăng này xuống ao ngự. Trong đó {xung} gói lời cầu cho người thân."},{"who":"me","text":"Hoa đăng giấy hồng, bấc đã thắp sẵn. Ao hôm nay đông người, chỗ trống chẳng còn bao nhiêu."},{"who":"A","text":"{Xung} chỉ cần một chỗ nhỏ thôi. Nếu {goi} cho phép, {xung} sẽ thả thật nhẹ."},{"who":"me","text":"Một ngọn đèn nhỏ mang cả lời cầu. Ta cần nghĩ xem nên giúp ngươi thế nào."}]}},
{"id":"j68:j68c-sea-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tuyết dày phủ kín sân, giày của vị thái y ướt sũng, hòm thuốc giấy vàng bọc kín nhưng vẫn run theo từng bước chân chậm chạp."},{"who":"A","text":"Bẩm {goi}, giữa tuyết dày, thần mang thang thuốc bổ mùa đông đến. Dặn {goi} dùng nóng, hiệu nghiệm hơn."},{"who":"me","text":"Giày của thái y ướt sũng thế này, tuyết rơi dày mà còn lặn lội đến, ta thật áy náy."},{"who":"A","text":"Việc của thầy thuốc, đâu quản đường dài. Chỉ mong {goi} giữ gìn thân thể."},{"who":"me","text":"Ông không thể quay về trong bộ dạng này. Ta cần nghĩ xem nên đối đãi thế nào."}]}},
{"id":"j68:j68c-sea-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân thả diều ngự uyển gió lộng, chiếc diều phượng giấy lụa đuôi dài sáu thước nằm trên tay {A}, nàng cười tươi như đã tính trước."},{"who":"A","text":"{Goi}, hôm nay gió đẹp, {xung} mới tập được cách thả cao hơn {goi}. Cùng thả cho vui, {goi} nhé?"},{"who":"me","text":"Cả sân đang nhìn, diều phượng đuôi dài như lụa. Lời thách ấy nghe nhẹ mà ý rõ ràng."},{"who":"A","text":"{Xung} chỉ muốn chơi thôi. Ai thả cao hơn, người ấy đãi trà."},{"who":"me","text":"Một trò chơi nhỏ mà cả sân đứng xem. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-sea-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho củi phủ đầy tuyết, bó củi khô cuối cùng nằm trong tay {A}, tiếng cãi nhau với mấy cung nhân vọng tới tận hiên ngươi."},{"who":"A","text":"Bẩm {goi}, củi trong kho chỉ còn bó này khô. {Xung} giữ để nhóm lửa nhỏ cho cung, mà họ cứ tranh."},{"who":"me","text":"Tiếng cãi nhau vọng cả sang hiên ta. Bó củi khô cuối kho, ai cũng muốn giữ cho mình."},{"who":"A","text":"{Xung} không có ý tranh. Chỉ là mùa đông lạnh, ai cũng cần lửa."},{"who":"me","text":"Một bó củi nhỏ mà chia lòng người. Ta cần nghĩ xem nên xử thế nào cho công bằng."}]}},
{"id":"j68:j68c-sea-040","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa đá đột ngột trút xuống, ngói lưu ly vỡ tan, mảnh rơi cách giá thêu gỗ trầm ngoài hiên chưa đầy nửa thước, cung nhân hoảng hốt tìm chỗ nấp."},{"who":"M","text":"Bẩm {goi}, mưa đá làm vỡ vài viên ngói lưu ly, mảnh rơi sát giá thêu của {goi}. Cung nhân chạy tìm chỗ nấp cả rồi."},{"who":"me","text":"Giá thêu gỗ trầm còn nguyên chứ? Mảnh ngói rơi gần như thế, người có ai bị thương không?"},{"who":"M","text":"Dạ, chưa ai bị thương. Chỉ sợ mưa đá còn tiếp, ngói vỡ thêm."},{"who":"me","text":"Mưa đá bất ngờ, mà lòng người cũng hoảng. Để ta nghĩ nên làm gì trước."}]}},
{"id":"j68:j68c-sea-041","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa vừa tạnh, một dải cầu vồng bắc ngang bầu trời cung điện, cung nhân kéo ra sân chỉ trỏ, tấm lụa căng trên khung còn ẩm hơi mưa."},{"who":"M","text":"Bẩm {goi}, mưa tạnh rồi, cầu vồng hiện ngang cung điện. Cung nhân kéo ra xem, có người xin {goi} phân định cách mừng điềm lành."},{"who":"me","text":"Cầu vồng sau mưa, điềm lành thật. Tấm lụa trên tay ngươi còn ẩm, ngươi cứ giữ cho khỏi nhàu."},{"who":"M","text":"Dạ, nô tỳ vẫn ôm lụa chưa kịp hong khô. Nhưng cả cung đang chờ lời {goi}."},{"who":"me","text":"Một dải cầu vồng mà cả cung nhìn lên. Ta cần nghĩ xem nên đón điềm lành thế nào."}]}},
{"id":"j68:j68c-sea-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hồ ngự uyển băng dày, ấm rượu gừng nóng hơi bốc trong gió buốt trên tay {A}, nàng nhìn ra phía đội thợ băng làm việc suốt đêm."},{"who":"A","text":"Bẩm {goi}, thợ băng làm việc suốt đêm ngoài hồ, trong đó có người thân của {xung}. {Xung} muốn mang ấm rượu gừng này ra cho họ."},{"who":"me","text":"Gió buốt thốc qua từng cánh cửa, rượu gừng nóng hổi thế này, họ chắc cần lắm. Người thân ngươi là ai trong đội?"},{"who":"A","text":"Dạ, là chú của {xung}. Hơn một năm rồi chưa gặp, hôm nay vô tình nhìn thấy."},{"who":"me","text":"Một ấm rượu gừng mà mang cả tình thân. Để ta nghĩ nên cho ngươi đi thế nào."}]}},
{"id":"j68:j68c-sea-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa nhẹ giữa chiều, vạt áo Hoàng thượng ướt lấm tấm, tay cầm cành mai đầu mùa vài nụ còn ướt, cung nhân hốt hoảng chưa kịp dọn bàn."},{"who":"A","text":"Trẫm đi ngang, thấy cành mai nở sớm bên đường nên hái mang tặng {goi}. Không kịp báo, {goi} đừng trách."},{"who":"me","text":"Cành mai còn ướt mưa, nụ chưa nở hết. {Goi} dầm mưa đến thế, {xung} xót lắm."},{"who":"A","text":"Trẫm không sao. Nhìn mai thấy nhớ {goi}, thế là đến."},{"who":"me","text":"Một cành mai đầu mùa mà thấm cả mưa lẫn tình. Để {xung} nghĩ xem nên đón thế nào."}]}},
{"id":"j68:j68c-sea-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùa oi nóng, hòm thuốc mở ra mùi ngải bốc nồng, bó ngải xông còn tươi, vị thái y đứng chờ lệnh, cung nhân nhìn nhau lo lắng."},{"who":"A","text":"Bẩm {goi}, trong cung có vài người sốt rét. Thần xin {goi} ra lệnh cho cung nhân dùng bó ngải này xông khắp cung."},{"who":"me","text":"Mùi ngải nồng, dễ làm người ho. Nhưng sốt rét lan ra thì còn nguy hơn."},{"who":"A","text":"Thần hiểu, nhưng ngải xông xua được khí độc. Mong {goi} cân nhắc."},{"who":"me","text":"Một bó ngải mà nặng cả sức khỏe cả cung. Ta cần nghĩ xem nên xử trí ra sao."}]}},
{"id":"j68:j68c-court-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư nhà niêm sáp xanh, con dấu nhà ngươi còn nguyên, {A} dâng bằng hai tay, hạ giọng như sợ vách có tai."},{"who":"A","text":"Bẩm {goi}, anh trai {goi} vừa thi hội xong. Bảng chưa yết, nhưng cả kinh đô đồn nhiều lắm. Thư nhà gửi qua cổng cung đây ạ."},{"who":"me","text":"Thi hội xong rồi, sao thư ngươi giữ chặt như vậy? Con dấu nhà ta còn nguyên, chưa ai mở."},{"who":"A","text":"Dạ, {xung} không dám. Chỉ mong {goi} đọc trước, rồi liệu lời."},{"who":"me","text":"Tin của anh ta, vui hay lo, lòng ta cũng không yên. Ta cần nghĩ nên làm thế nào."}]}},
{"id":"j68:j68c-court-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ phát gạo muối của Nội vụ phủ ghi theo phẩm vị trải trên bàn, {A} cúi chào, mặt nặng nề."},{"who":"A","text":"Bẩm {goi}, tiền triều vừa tăng thuế muối. Nội vụ phủ sẽ bớt phần gạo và muối của từng cung vào kỳ này."},{"who":"me","text":"Bớt cho mỗi cung, cung nào nhận ít sẽ rơi vào thế khó. Ngươi có biết cung ta nhận bao nhiêu?"},{"who":"A","text":"Theo sổ phát thì hơi ít, nhưng còn xem thông lệ. {Xung} chỉ đến báo trước để {goi} liệu."},{"who":"me","text":"Một khoản bớt nhỏ mà thể diện cả cung treo trong đó. Ta cần nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-court-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản sớ đàn hặc niêm giấy vàng nằm trên án Kính sự phòng, một dòng ghi tên cung ngươi đậm mực đen, cả phòng im phăng phắc."},{"who":"A","text":"Bẩm {goi}, một ngự sử vừa dâng sớ đàn hặc cha của một phi tần thân với {goi}. Tội danh chưa rõ, nhưng trong sớ đã ghi tên cung {goi} vào một dòng."},{"who":"me","text":"Một dòng tên cung ta trong sớ đàn hặc, ngươi nhìn thấy tận mắt? Kính sự phòng đang nhìn xem ta làm gì?"},{"who":"A","text":"Dạ, cả phòng đều nhìn. {Xung} đến báo để {goi} biết, chứ chưa ai kết tội."},{"who":"me","text":"Một dòng mực mà đủ làm lòng người khó yên. Ta cần nghĩ kỹ xem nên làm gì."}]}},
{"id":"j68:j68c-court-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp gấm bộ trâm ngọc phỉ thúy chưa tháo dây đặt cạnh, nội giám đọc chiếu, giọng đều đều như tiếng chuông xa."},{"who":"A","text":"Bẩm {goi}, có chiếu truyền: trong một kỳ này các cung hạn chế dùng ngọc quý, vì triều đình cắt giảm chi tiêu."},{"who":"me","text":"Hộp trâm phỉ thúy ta vừa sắm, còn chưa kịp tháo dây. Chiếu này đến thật không đúng lúc."},{"who":"A","text":"{Xung} chỉ truyền lời. Mong {goi} liệu sao cho hợp lễ."},{"who":"me","text":"Một bộ trâm mà chạm cả chuyện thể diện lẫn nghĩa vụ. Ta cần nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-court-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thị giám nâng súc gấm ngũ sắc cuộn chặt dấu nội phủ ở đầu, Hoàng thượng hứng khởi sau tin thắng trận, ánh mắt sáng rực."},{"who":"A","text":"Tin thắng trận vừa về, trẫm ban cho các cung mỗi nơi một súc gấm ngũ sắc. {Goi} thấy nên chia thế nào cho phải lẽ?"},{"who":"me","text":"Gấm ngũ sắc dấu nội phủ, cuộn chặt, đẹp lắm. {Goi} hỏi {xung} chia thế nào, tức là trọng ý {xung}."},{"who":"A","text":"Trẫm tin {goi} biết cân nhắc. Cung nào cũng có, nhưng ai cũng muốn phần hơn."},{"who":"me","text":"Một súc gấm mà gánh cả ơn vua lẫn lòng người. Để {xung} nghĩ cho thấu đáo."}]}},
{"id":"j68:j68c-court-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuộn giấy kinh nét mực mờ còn tươi nằm trên bàn, Thái hậu ngồi nghiêm trang, ánh mắt thâm trầm, cung nhân bồn chồn vì trời chưa mưa."},{"who":"A","text":"Trời chưa mưa, lòng người chưa yên. {Xung} giao con cuộn giấy kinh này, chép kinh cầu mưa trong ba buổi."},{"who":"me","text":"Dạ, Thái hậu. Nét mực còn tươi, giấy dày. {Xung} sẽ chép hết lòng."},{"who":"A","text":"Cầu mưa cho dân, cũng là tích đức cho cung. Con làm cho cẩn thận."},{"who":"me","text":"Lời dặn nhẹ mà nặng như núi. Để {xung} nghĩ cách chép cho thành tâm."}]}},
{"id":"j68:j68c-court-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp sơn son của Thái y viện mở ra, rễ nhân sâm núi già nằm lẻ loi, vị thái y đứng chờ, giọng khẽ."},{"who":"A","text":"Bẩm {goi}, nhân sâm núi từ vùng xa về chỉ còn ít, nhiều cung đang xin. {Goi} có tên trong danh sách, nhưng bề trên cũng vừa sai người xin."},{"who":"me","text":"Còn đúng một phần, mà hai nơi cùng xin. Rễ già thế này, quý hiếm lắm."},{"who":"A","text":"Thần chỉ biết trình lên cho {goi} quyết. Phần này không thể chia đôi dễ dàng."},{"who":"me","text":"Một củ sâm mà chia cả tình lẫn lễ. Ta cần nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-court-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mâm đồng đã chất vài món đồ quý các cung góp, chuỗi hạt trai hộp lụa cung ngươi đặt cạnh, nội giám đứng chờ, giọng trầm xuống."},{"who":"A","text":"Bẩm {goi}, đê sông vỡ, dân khu ngoại thành mất nhà. Các cung đều đã góp đồ quý, chỗ trống này đang chờ {goi}."},{"who":"me","text":"Mâm đã có mấy món, ngươi chỉ vào chỗ trống ấy, nghĩa là chờ ta bỏ thêm. Chuỗi hạt trai này hạt tròn đều, ta quý lắm."},{"who":"A","text":"{Xung} không ép, chỉ báo thôi. Mỗi người góp theo tâm."},{"who":"me","text":"Giúp dân là việc nghĩa, nhưng góp thế nào mới vẹn đôi bề, ta cần nghĩ."}]}},
{"id":"j68:j68c-court-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thêu chim trĩ mẫu chỉ ngũ sắc còn mới cầm trên tay, nội giám bước vào, giọng nhẹ mà ý sâu."},{"who":"A","text":"Bẩm {goi}, Nội vụ phủ vừa nhận một thợ thêu tay nghề cao, nhiều cung đã xin. Đây là bức thêu mẫu người ấy mang đến."},{"who":"me","text":"Chim trĩ thêu tinh xảo, chỉ ngũ sắc còn mới. Nhiều cung xin cả rồi sao? Ai nhận được thợ thì nở mày với bề trên?"},{"who":"A","text":"Đúng vậy ạ. {Xung} nghĩ {goi} cũng nên cân nhắc."},{"who":"me","text":"Một người thợ mà thành cuộc tranh thể diện. Để ta nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-court-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp trà búp đầu xuân niêm sáp đỏ trên tay nội giám, mùi trà thoang thoảng qua nắp thiếc, ánh mắt hắn ngầm dò xét."},{"who":"A","text":"Bẩm {goi}, trà này vừa từ vùng xa dâng về. Ai nếm trước thì được ghi nhớ. {Xung} đến, mời {goi} nếm trước."},{"who":"me","text":"Hộp niêm sáp đỏ, trà búp đầu xuân hiếm thật. Ai cũng muốn nếm trước, ngươi lại tìm ta đầu tiên."},{"who":"A","text":"Dạ, {xung} nghĩ {goi} xứng đáng. Nhưng cũng tùy {goi} quyết."},{"who":"me","text":"Một chén trà mà thành chuyện thứ bậc. Ta cần nghĩ xem nên nhận thế nào."}]}},
{"id":"j68:j68c-court-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thẻ bài ghi tên nét mực còn tươi nằm trên án Kính sự phòng, vị quan nghiêm nghị khép sổ, giọng trầm xuống."},{"who":"A","text":"Bẩm {goi}, thẻ bài đêm qua ghi nhầm. Tên {goi} nằm trong sổ ở đêm không thuộc về {goi}, và thẻ đã đưa lên tận trước mặt Hoàng thượng."},{"who":"me","text":"Ghi nhầm mà đưa lên tận trước mặt Hoàng thượng. Ngươi đến báo ta, tức là chuyện còn kịp liệu?"},{"who":"A","text":"Dạ. Chuyện này có thể thành lợi hay thành họa, tùy cách {goi} nhận."},{"who":"me","text":"Một chữ nhầm mà đổi cả vận. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-court-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc vòng bạc cũ mặt khắc tên cung ngươi nằm trên tay vị quan, một nội thị quỳ rạp, đầu cúi sát nền gạch."},{"who":"A","text":"Bẩm {goi}, thần bắt được nội thị này lấy chiếc vòng bạc của kho. Món ấy vốn từ cung {goi} ban ra, nên dẫn đến trước mặt {goi}."},{"who":"me","text":"Chiếc vòng này đúng là từ cung ta ban ra. Nội thị quỳ rạp, không dám ngẩng đầu, ngươi hỏi hắn chưa?"},{"who":"A","text":"Hắn nhận tội, nhưng chưa nói vì sao. Xin {goi} định đoạt."},{"who":"me","text":"Một chiếc vòng bạc cũ mà gánh cả mạng người. Ta cần nghĩ xem nên xử trí thế nào."}]}},
{"id":"j68:j68c-court-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói thuốc hạ sốt giấy bọc dấu đỏ Thái y viện nằm trong tay vị thái y, ông hạ giọng như sợ ai nghe."},{"who":"A","text":"Bẩm {goi}, một cung nhân của {goi} sốt cao, nhưng thuốc quý chỉ cấp theo phẩm. Gói thuốc hạ sốt duy nhất đã dành cho cung trên."},{"who":"me","text":"Gói thuốc duy nhất mà đã cấp đi rồi. Người của ta đang sốt cao, ngươi nói thế là thế nào?"},{"who":"A","text":"Thần có thể lấy bớt nếu {goi} gật đầu. Nhưng làm vậy là vượt lệ."},{"who":"me","text":"Một gói thuốc mà chia cả công bằng lẫn tình người. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-court-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đơn thuốc viết tay nét mực đen còn ướt trên án thái y, ông đưa bút, giọng nghiêm trang."},{"who":"A","text":"Bẩm {goi}, có kẻ đồn thần kê nhầm vị thuốc cho một phi tần vừa ốm. Xin {goi} làm chứng cho đơn thuốc này."},{"who":"me","text":"Đơn thuốc nét mực còn ướt, ông xin ta làm chứng. Ký tên chứng kiến, tức là ta ràng buộc với chuyện này."},{"who":"A","text":"Thần hiểu. Nhưng không có người chứng, lời đồn càng lan."},{"who":"me","text":"Một chữ ký mà nặng cả danh tiếng lẫn thân phận. Ta cần nghĩ kỹ."}]}},
{"id":"j68:j68c-court-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản tấu đề cử mực son còn đậm đặt xuống bàn ngự, Hoàng thượng nhìn ngươi, giọng nhẹ như hỏi chuyện thường."},{"who":"A","text":"Trẫm đang nghĩ nên thưởng một trọng thần thế nào cho hợp lòng người. {Goi} nghĩ sao?"},{"who":"me","text":"Việc triều chính, hậu cung không được can dự. {Xung} sao dám lạm bàn."},{"who":"A","text":"Trẫm biết quy củ. Nhưng trẫm đang hỏi {goi}, không phải hỏi triều thần."},{"who":"me","text":"Câu hỏi nhẹ mà ý nặng. Một lời có thể thành họa. {Xung} cần nghĩ kỹ."}]}},
{"id":"j68:j68c-court-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, nghiên mực đá đen đã cạn mực, đáy chỉ còn một vệt khô, Hoàng thượng vẫn cúi đầu phê tấu, ấm trà gừng trong tay ngươi còn nóng."},{"who":"A","text":"Đêm khuya rồi, {goi} còn đến đây. Trẫm còn nhiều tấu chương chưa phê."},{"who":"me","text":"Nghiên mực đã cạn rồi, trà gừng {xung} mang theo còn nóng. {Goi} đừng làm việc quá sức."},{"who":"A","text":"Trẫm biết. Nhưng nếu trẫm buông bút, ai gánh việc thiên hạ?"},{"who":"me","text":"Một người gánh cả giang sơn mà đêm khuya vẫn phê tấu. Để {xung} nghĩ xem nên giúp thế nào."}]}},
{"id":"j68:j68c-court-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bộ quạt múa lụa đỏ còn nếp gấp từ kho Nội vụ phủ trải trên bàn, Hoàng thượng đứng giữa gian, giọng hứng khởi."},{"who":"A","text":"Sứ giả xa sắp tới, trẫm dặn mỗi cung chuẩn bị một tiết mục. Cung {goi} nhận bộ quạt múa lụa đỏ này."},{"who":"me","text":"Quạt lụa đỏ còn nếp gấp, mới từ kho phát. Ai cũng đang đoán xem nên múa gì."},{"who":"A","text":"Trẫm tin {goi} sẽ chọn khéo. Đừng làm trẫm mất mặt trước sứ giả."},{"who":"me","text":"Một tiết mục mà thể diện cả cung treo trên đó. Để {xung} nghĩ cho chu đáo."}]}},
{"id":"j68:j68c-court-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách ba thầy đồ giấy vàng viết tay trải trên bàn Thái hậu, ba cái tên, ba bóng người đứng sau."},{"who":"A","text":"{Xung} cần chọn người dạy kinh cho các hoàng tử. Danh sách ba thầy đồ này, con xem nên chọn ai."},{"who":"me","text":"Dạ, Thái hậu. Mỗi cái tên đều có người đứng sau. {Xung} chọn sai sẽ gánh lấy."},{"who":"A","text":"{Xung} biết. Nhưng {xung} muốn nghe ý con, vì con ít bè phái."},{"who":"me","text":"Ba cái tên mà ba con đường. Để {xung} nghĩ cho thấu đáo."}]}},
{"id":"j68:j68c-court-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chuỗi hạt bồ đề cũ hạt bóng loáng vì lần lâu nằm trong tay Thái hậu, cung nhân xung quanh nhìn sang, có người đã thì thầm."},{"who":"A","text":"Con lại đây. Chuỗi hạt này đã theo {xung} nhiều năm. Hôm nay {xung} trao cho con."},{"who":"me","text":"Dạ, Thái hậu. Chuỗi hạt bồ đề cũ, bóng loáng vì lần lâu. {Xung} sao dám nhận."},{"who":"A","text":"{Xung} trao thì con nhận. Có gì mà sợ."},{"who":"me","text":"Một chuỗi hạt mà cả cung nhìn. Để {xung} nghĩ cách đáp cho phải đạo."}]}},
{"id":"j68:j68c-court-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ sách hiệu buôn bìa có dấu hiệu nhà ngươi nằm trong tay nội giám, hắn hạ giọng, mắt không rời cửa."},{"who":"A","text":"Bẩm {goi}, có người mách nhà mẹ {goi} mở hiệu buôn nhỏ, trái lệ quan gia. Sổ sách đã nằm trong tay người đàn hặc."},{"who":"me","text":"Sổ sách có dấu hiệu nhà ta, mà nằm trong tay người đàn hặc. Chưa ai nhắc đến ta, nhưng sớm muộn cũng có."},{"who":"A","text":"Dạ. {Xung} đến báo để {goi} liệu trước."},{"who":"me","text":"Một cuốn sổ mà đe cả gia tộc. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-court-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hòm hồi môn gỗ tử đàn mở nắp giữa gian, nội giám cầm sổ đếm từng món, mỗi món đều có thể bị ghi lại."},{"who":"A","text":"Bẩm {goi}, theo lệ, {xung} đến kiểm kê hồi môn các cung. Xin {goi} cho mở hòm."},{"who":"me","text":"Hòm tử đàn đã mở, ngươi đếm từng món. Món nào cũng bị ghi lại, bàn tán, đánh giá."},{"who":"A","text":"{Xung} chỉ làm theo lệ. Nhưng {goi} biết mà, trong cung lời nói đi nhanh hơn người."},{"who":"me","text":"Một chiếc hòm mà cả thể diện nhà mẹ ta nằm trong. Để ta nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-court-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Xâu chìa khóa kho nhỏ dây đỏ nằm trong tay người coi kho, nội giám đưa lệnh điều, giọng đều đều."},{"who":"A","text":"Bẩm {goi}, theo lệ Nội vụ phủ, người coi kho của cung {goi} sắp bị điều sang cung khác. Đây là lệnh điều."},{"who":"me","text":"Người ấy theo ta từ lâu, biết rõ mọi việc nhà. Lệnh điều ngươi đưa, ta không thể làm ngơ."},{"who":"A","text":"Lệnh đã ban, nhưng {goi} có thể xin. {Xung} chỉ truyền lời."},{"who":"me","text":"Một xâu chìa khóa mà gánh cả sự tin cậy bao năm. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-court-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bao lụa đỏ đựng bạc lẻ buộc dây đỏ kỹ trên tay nội giám, cung nhân đứng quanh lặng thinh, nhưng ai cũng đã nhẩm đếm."},{"who":"A","text":"Bẩm {goi}, {xung} đến phát bao thưởng Tết cho cung. Năm nay bao mỏng hơn mọi năm một ít, xin {goi} thứ lỗi."},{"who":"me","text":"Mỏng hơn một ít, ngươi nói nhẹ nhàng, mà cung nhân đã đếm cả rồi. Không ai nói, nhưng ai cũng nghe thấy."},{"who":"A","text":"Dạ, {xung} chỉ phát theo sổ. Nếu {goi} thấy thiếu, có thể hỏi lại."},{"who":"me","text":"Một bao thưởng mỏng mà đủ làm nguội cả tết. Ta cần nghĩ xem nên bù đắp thế nào."}]}},
{"id":"j68:j68c-court-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc hộp ngọc khắc hoa sen phủ rêu vừa được vớt lên từ đáy giếng, nội giám đến ngay, ánh mắt chưa rời nắp hộp."},{"who":"A","text":"Bẩm {goi}, thợ sửa giếng vớt lên chiếc hộp ngọc này, nằm đáy giếng không biết bao năm. Theo lệ, đồ cổ phải báo Nội vụ phủ."},{"who":"me","text":"Hộp ngọc khắc hoa sen, nắp còn dính rêu. Ngươi nói theo lệ, nhưng mắt ngươi nhìn hộp mãi không rời."},{"who":"A","text":"{Xung} chỉ tò mò thôi. Nhưng {goi} là chủ cung, {xung} xin nghe {goi}."},{"who":"me","text":"Một chiếc hộp ngọc từ đáy giếng, có thể là phúc, có thể là họa. Ta cần nghĩ kỹ."}]}},
{"id":"j68:j68c-court-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bọc thư báo tang nét chữ nghiêng vội, nhàu trong áo cung nhân bỏ trốn, quan Kính sự phòng đứng ngoài cửa cung chờ một lời."},{"who":"A","text":"Bẩm {goi}, thần bắt được một cung nhân bỏ trốn, trên người giấu bọc thư báo tang. Hóa ra nàng từng là người nhà {goi}."},{"who":"me","text":"Bọc thư báo tang, nét chữ nghiêng vội. Nàng cuống cuồng vì tin dữ từ quê mà chạy, ta hiểu."},{"who":"A","text":"Theo cung quy, bỏ trốn là trọng tội. Nhưng nàng từng là người của {goi}, nên thần dừng lại chờ lời {goi}."},{"who":"me","text":"Một người bỏ trốn vì tin buồn, một bộ luật đang nhìn. Ta cần nghĩ xem nên nói gì."}]}},
{"id":"j68:j68c-court-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lệnh khám cung giấy vàng trải trên bàn, quan Kính sự phòng đứng nghiêm trang, trong cung nhân đã có người lén cất đồ."},{"who":"A","text":"Bẩm {goi}, hộp châu bảo ở kho ngoại vừa mất, sổ ghi mà không thấy. Cung của {goi} nằm trong danh sách khám."},{"who":"me","text":"Hộp châu bảo mất ở kho ngoại, mà khám đến cung ta. Cung nhân đã bắt đầu lo lắng, có người lén cất đồ."},{"who":"A","text":"Thần chỉ làm theo lệnh. Mong {goi} hợp tác để việc xong sớm."},{"who":"me","text":"Một lệnh khám mà khuấy động cả cung. Ta cần nghĩ xem nên đón thế nào."}]}},
{"id":"j68:j68c-court-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp thuốc giấy gói kín đặt cạnh gối, thái y bắt mạch xong, hạ giọng, ánh mắt chần chừ giữa nghề và tình."},{"who":"A","text":"Bẩm {goi}, mạch của {goi} có chứng nhẹ, cần uống thang dưỡng khí một thời gian. Nhưng nếu ghi vào sổ Thái y viện, chuyện sẽ lan khắp cung."},{"who":"me","text":"Chứng nhẹ, ngươi nói thế, ta nghe cũng yên lòng. Nhưng sổ ghi vào thì cả cung biết, không ghi thì ta lo."},{"who":"A","text":"Thần chờ {goi} chọn. Thuốc không thể bỏ, nhưng cách dùng thì tùy."},{"who":"me","text":"Một thang thuốc mà thể diện và sức khỏe cùng nặng. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-court-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Viên ngọc bích nguyên khối màu xanh sâu như đáy hồ nằm trên tay Hoàng thượng, ngài mỉm cười, ánh mắt thăm dò."},{"who":"A","text":"Trẫm ban viên ngọc bích này cho {goi}. Nghĩ xem, nên dùng thế nào mới xứng với nó?"},{"who":"me","text":"Ngọc bích nguyên khối, xanh như đáy hồ. Các cung đã bàn tán chuyện ngọc ngự ban rồi, {goi} biết không?"},{"who":"A","text":"Trẫm biết. Nên mới hỏi {goi} trước, để {goi} tự quyết."},{"who":"me","text":"Một viên ngọc mà cả cung nhìn vào. Để {xung} nghĩ xem nên dùng sao cho xứng."}]}},
{"id":"j68:j68c-court-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản đồ đê điều mực son khoanh vài chỗ trải trên bàn ngự, Hoàng thượng ngồi lặng, không nói thêm lời nào, chỉ nhìn ngươi."},{"who":"A","text":"Trẫm vừa nhận tin đê sông có chỗ nứt, dân ven sông lo sợ lắm."},{"who":"me","text":"Mực son khoanh vài chỗ, nhìn mà lòng {xung} cũng nặng. {Goi} không nói thêm, nhưng ánh mắt như đang chờ."},{"who":"A","text":"Trẫm không cần lời khuyên chính sự. Trẫm chỉ muốn có người ngồi đây."},{"who":"me","text":"Một người gánh cả sơn hà mà tìm chỗ ngồi lặng. Để {xung} nghĩ nên đáp thế nào."}]}},
{"id":"j68:j68c-court-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lò ủ thuốc nhỏ cạnh giường nghi ngút khói thơm gừng, Thái hậu cảm lạnh hai hôm, giọng khàn mà vẫn mời ngươi vào."},{"who":"A","text":"Vào đây đi con. {Xung} cảm lạnh hai hôm rồi, giọng khàn cả. Nhiều người đã ghé thăm, người ngồi lâu, người chỉ chào rồi đi."},{"who":"me","text":"Dạ, Thái hậu. Khói gừng thơm cả phòng, người nằm đây mà còn lo chuyện người khác."},{"who":"A","text":"{Xung} quen rồi. Nhìn xem ai thật lòng, ai chỉ làm lễ."},{"who":"me","text":"Một lời mời vào mà như một phép thử. Để {xung} nghĩ xem nên hầu thế nào."}]}},
{"id":"j68:j68c-court-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khăn lụa cũ góc thêu hoa nhài của người quen ở lãnh cung nằm trong trí nhớ, nội giám hạ giọng như sợ gió nghe."},{"who":"A","text":"Bẩm {goi}, nghe đồn triều đình sắp đại xá, người ở lãnh cung có thể được thả. Một người {goi} từng quen biết nằm trong đó, vẫn giữ chiếc khăn lụa {goi} gửi năm xưa."},{"who":"me","text":"Chiếc khăn thêu hoa nhài, ta nhớ rồi. Nàng vẫn giữ sau bao năm ở lãnh cung."},{"who":"A","text":"Tin đồn chưa chắc chắn, nhưng {xung} thấy nên báo cho {goi}."},{"who":"me","text":"Một tin chưa chắc mà đủ khơi lại cả một thời. Ta cần nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-court-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bao gạo tẻ thượng hạng bao gai dấu đỏ xếp ngay ngắn trong kho Nội vụ phủ, nội giám báo tin, giọng cân nhắc từng chữ."},{"who":"A","text":"Bẩm {goi}, giá gạo tăng, khẩu phần cung nhân sẽ bớt một ít. Nhưng phần gạo cho phi tần vẫn giữ nguyên."},{"who":"me","text":"Khẩu phần cung nhân bớt mà phần phi tần giữ nguyên. Nghe cả cung đã bắt đầu thì thầm bất bình."},{"who":"A","text":"Dạ, {xung} chỉ nói đúng lệnh. {Goi} nghe rồi liệu."},{"who":"me","text":"Một bao gạo mà chia cả trên lẫn dưới. Ta cần nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-court-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ danh sách theo ngự giá mực son chia từng hàng nằm trên tay nội giám, kẻ hàng đầu đắc ý, kẻ hàng cuối đã xì xào xin đổi."},{"who":"A","text":"Bẩm {goi}, đây là danh sách người theo ngự giá đi tế Giao. {Goi} ở hàng giữa, sát cuối."},{"who":"me","text":"Hàng giữa sát cuối, ngươi nói thẳng thế. Kẻ hàng đầu đắc ý, kẻ hàng cuối đã xin đổi."},{"who":"A","text":"{Xung} chỉ đưa {goi} xem qua trước khi niêm yết. Có muốn đổi thì nói sớm."},{"who":"me","text":"Một chỗ đứng trong đoàn tế mà thể diện lẫn thứ bậc cùng nặng. Ta cần nghĩ kỹ."}]}},
{"id":"j68:j68c-court-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đất mới đảo dưới gốc hòe trước cung bên còn ẩm, quan Kính sự phòng ghé sát, mắt không rời cửa, giọng nhỏ như gió."},{"who":"A","text":"Bẩm {goi}, có cung nhân tố cáo một cung gần {goi} đã chôn hình nộm vải dưới gốc hòe. Người tố còn chưa thấy bằng chứng."},{"who":"me","text":"Hình nộm vải dưới gốc hòe cung bên. Ngươi đến hỏi ta có thấy gì khả nghi không."},{"who":"A","text":"Dạ. Nếu {goi} thấy điều gì, xin nói. Nếu không, {xung} cũng ghi vào sổ."},{"who":"me","text":"Một lời của ta có thể cứu một người hoặc hại một người. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-court-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quyển cổ thư chép tay bìa lụa mòn gáy được đặt ngoài danh sách thường, nội giám dâng bằng hai tay, nụ cười kín đáo."},{"who":"A","text":"Bẩm {goi}, Nội vụ phủ mở kho sách cổ cho các cung mượn một quyển trong kỳ. {Xung} nghe {goi} ham đọc, nên dâng quyển này."},{"who":"me","text":"Quyển cổ thư bìa lụa mòn gáy, chữ chép tay. Nhiều người muốn mượn mà ngươi đưa cho ta trước."},{"who":"A","text":"{Xung} chỉ nghĩ sách nên đến tay người biết đọc."},{"who":"me","text":"Một quyển sách mà đủ chạm cả lòng lẫn danh. Ta cần nghĩ xem nên nhận thế nào."}]}},
{"id":"j68:j68c-court-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói bánh quê gói lá chuối buộc dây gai, mùi nếp thơm thoảng qua kẽ lá, nội giám bẩm tin nhà mẹ xin vào cung."},{"who":"A","text":"Bẩm {goi}, nhà mẹ {goi} xin phép vào cung thăm. Dịp này chỉ cho một người, kèm theo gói bánh mẹ làm gửi {goi}."},{"who":"me","text":"Gói bánh quê buộc dây gai, mùi nếp thơm cả phòng. Chỉ cho một người vào, mà cả nhà đều nhớ ta."},{"who":"A","text":"Cả cung đều biết chỗ {goi} sắp có khách quý. {Xung} đến báo để {goi} chọn."},{"who":"me","text":"Một chỗ trong cổng cung mà bao nhiêu người mong. Ta cần nghĩ xem nên chọn ai."}]}},
{"id":"j68:j68c-court-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bột thuốc còn thơm hoa trong hòm thái y, thang thuốc dưỡng nhan chỉ đủ cho một người, ông đứng cúi đầu chờ chỉ định."},{"who":"A","text":"Bẩm {goi}, thần nhận lệnh bào chế thang thuốc dưỡng nhan, nhưng nguyên liệu quý đã hết, chỉ đủ cho một người. Xin {goi} chỉ định người dùng."},{"who":"me","text":"Thang thuốc chỉ đủ cho một người, mà vài cung đã hỏi. Ông xin ta chỉ định."},{"who":"A","text":"Thần không dám quyết. Lệ cung, ai dùng cũng phải có lý."},{"who":"me","text":"Một thang thuốc mà ai nhận cũng đều có người mất. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-court-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sơ đồ chỗ ngồi yến mực son chia từng dãy trải trên tay nội giám, chỗ ngươi nằm gần cửa gió, ngón tay chỉ vào ô nhỏ ấy."},{"who":"A","text":"Bẩm {goi}, đây là sơ đồ chỗ ngồi đại yến sắp tới. Chỗ của {goi} gần cửa gió, mong {goi} xem."},{"who":"me","text":"Cửa gió đêm yến lạnh lắm. Đổi chỗ thì phiền người khác, giữ nguyên thì chịu rét."},{"who":"A","text":"Dạ, {xung} chỉ đưa {goi} xem trước. Quyết thế nào, tùy {goi}."},{"who":"me","text":"Một chỗ ngồi mà phải cân cả thân thể lẫn thể diện. Ta cần nghĩ xem nên làm gì."}]}},
{"id":"j68:j68c-court-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp bánh ngọt lễ giấy lụa gói kín trên tay nội giám, ánh mắt hắn đầy ý nghĩa, người coi kho đứng cách một bước."},{"who":"A","text":"Bẩm {goi}, người coi kho muốn nhận một món lễ nhỏ, hứa sẽ phát đồ tốt cho cung {goi} cả năm. Việc không sai luật, nhưng cũng không đẹp."},{"who":"me","text":"Không sai luật mà cũng không đẹp, ngươi nói thật. Hộp bánh gói kín thế này, nhận hay không đều để lại dấu."},{"who":"A","text":"{Xung} chỉ truyền ý. Xin {goi} cân nhắc."},{"who":"me","text":"Một hộp bánh mà nặng cả liêm sỉ lẫn thực lợi. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-court-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ thuốc gia truyền bìa lụa sờn gáy nằm trong tay vị thái y già, ông xin về quê dưỡng bệnh, giọng nhẹ như gió thu."},{"who":"A","text":"Bẩm {goi}, thần đã già, xin về quê dưỡng bệnh. Cuốn sổ thuốc gia truyền này, thần định gửi lại cho một người kế nghiệp."},{"who":"me","text":"Sổ thuốc gia truyền bìa sờn gáy, ông giữ bao nhiêu năm rồi. Ông đến hỏi ý ta trước."},{"who":"A","text":"Vì thần nhớ {goi} từng dùng thuốc thần. Người từng tin thần, thần mới tin."},{"who":"me","text":"Một cuốn sổ mà gửi gắm cả đời nghề. Ta cần nghĩ xem nên đáp ra sao."}]}},
{"id":"j68:j68c-court-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp bánh hoa quế ngự ban lụa vàng phủ nắp trong tay thái giám đi ngang hiên, Hoàng thượng cười vui, giọng hạ thấp."},{"who":"A","text":"Trẫm thưởng riêng {goi} hộp bánh hoa quế này, đừng nói cho ai. Kẻo cung bên biết sẽ ầm lên."},{"who":"me","text":"Hộp bánh phủ lụa vàng, thái giám bưng ngang cả hiên rồi. Cung nhân đã thấy cả."},{"who":"A","text":"Trẫm vô ý quá. Nhưng đã ban thì cứ nhận."},{"who":"me","text":"Một hộp bánh mà thành chuyện cả cung. Để {xung} nghĩ cách đón nhận thế nào."}]}},
{"id":"j68:j68c-court-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Luống bạc hà và ngải cứu nhỏ ở góc vườn thuốc cạnh Thái y viện còn xanh mướt, vị thái y đứng cạnh, đeo gùi hái thuốc."},{"who":"A","text":"Bẩm {goi}, thần đi hái thuốc xa mấy hôm, xin {goi} coi giúp luống bạc hà và ngải cứu ở góc vườn. Việc nhẹ nhàng, nhưng nếu héo thì thần sẽ buồn."},{"who":"me","text":"Luống bạc hà xanh thế này, ông trồng từ bao giờ? Coi giúp thì ta nhận, nhưng chăm cho xanh mới khó."},{"who":"A","text":"Chỉ cần tưới đều là được. Thần tin {goi}."},{"who":"me","text":"Một luống thuốc nhỏ mà chứa cả lòng tin. Ta cần nghĩ xem nên chăm thế nào."}]}},
{"id":"j68:j68c-court-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư niêm sáp xám dấu sáp chưa rạn trên tay nội giám, hắn đứng im, mắt không rời phong bì."},{"who":"A","text":"Bẩm {goi}, có người quen cũ bên ngoài tường cung gửi bức thư này cho {goi}. Dấu sáp còn nguyên."},{"who":"me","text":"Thư từ ngoài tường cung, dấu sáp xám chưa rạn. Mở thì có thể rước chuyện, không mở thì tò mò khôn nguôi."},{"who":"A","text":"{Xung} chỉ chuyển thư, chưa đọc. Nhưng nghe đồn người gửi không phải người thường."},{"who":"me","text":"Một bức thư kín mà có thể đổi cả vận. Ta cần nghĩ thật kỹ."}]}},
{"id":"j68:j68c-kid-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh sứ men lam rải dưới gốc hoa trong vườn ngự uyển, {A} nấp trong góc phòng, hai tay ôm đầu gối, mắt đỏ hoe."},{"who":"A","text":"{Goi} ơi, con không cố ý đâu. Con đuổi bướm, bướm bay qua bình, bình rơi xuống đất vỡ tan."},{"who":"me","text":"Bình của cung bên, men lam đẹp như vậy. Người ta đã biết rồi, đang cho người sang hỏi."},{"who":"A","text":"Con sợ lắm. Con muốn trốn đi, đừng ai thấy con."},{"who":"me","text":"Con sợ là phải, nhưng trốn không giải quyết gì. Để {xung} nghĩ xem nên giúp con thế nào."}]}},
{"id":"j68:j68c-kid-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chú chim sẻ non lông chưa đủ nằm gọn trong lòng bàn tay nhỏ, {A} ôm sát vào ngực, chẳng chịu buông."},{"who":"A","text":"{Goi} ơi, con nhặt được chim rơi dưới mái hiên. Cho con nuôi nhé, con sẽ cho nó ăn mỗi ngày."},{"who":"me","text":"Chim non lông chưa đủ, mỏng manh lắm. Con có biết nuôi nó khó thế nào không?"},{"who":"A","text":"Con không biết, nhưng con sẽ học. Nó run quá, con không nỡ bỏ nó."},{"who":"me","text":"Lòng con mềm thật. Còn chú chim này, để {xung} nghĩ cách cho con."}]}},
{"id":"j68:j68c-kid-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giấy gói nhàu trên chiếc kẹo mạch nha trong tay nhỏ, {A} chạy về, thở hổn hển, mắt đầy thắc mắc."},{"who":"A","text":"{Goi} ơi, vì sao dì ở cung bên khóc? Con nghe cung nhân thì thầm chuyện xấu. Con mang kẹo sang cho dì được không?"},{"who":"me","text":"Con nghe cung nhân nói gì mà bảo là chuyện xấu? Dì khóc, con thương dì phải không?"},{"who":"A","text":"Con thương dì lắm. Dì hay cho con bánh, nên con muốn đem kẹo sang."},{"who":"me","text":"Lòng con tốt như vậy. Nhưng có những chuyện người lớn khó nói. Để {xung} nghĩ cách đáp con."}]}},
{"id":"j68:j68c-kid-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mực đỏ loang cả tay áo nhỏ, tờ giấy tuyên trắng nguệch ngoạc trên bàn viết, {A} giơ cao với vẻ trịnh trọng."},{"who":"A","text":"{Goi} xem, con viết bản tấu vua giao cho con đấy! Con viết đỏ để trông cho oai."},{"who":"me","text":"Mực đỏ loang cả tay áo rồi. Bản tấu của con nét nguệch ngoạc, mà con cầm đầy vẻ quan trọng."},{"who":"A","text":"Con làm việc lớn đó. Cha giao, con không dám lơ là."},{"who":"me","text":"Con ngây thơ mà đáng yêu. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-kid-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cái roi nhỏ trong tay {A} vung vẩy, yên ngựa da nhỏ nơi sân tập thị vệ còn dính bụi, trơn và cũ."},{"who":"A","text":"{Goi} ơi, cho con theo thị vệ ra sân tập cưỡi ngựa đi! Con muốn học như các anh."},{"who":"me","text":"Con muốn cưỡi ngựa, mắt long lanh vì cái roi nhỏ. Nhưng ngựa tập chưa chắc hiền, yên lại vừa cũ vừa trơn."},{"who":"A","text":"Con không sợ đâu. Con sẽ ngồi thật vững."},{"who":"me","text":"Con dũng cảm mà lòng {xung} lo. Để {xung} nghĩ cho kỹ."}]}},
{"id":"j68:j68c-kid-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con mèo hoang lông vàng bết bụi theo chân {A} từ vườn về tới tận bậc thềm, cung nhân nhăn mặt, {M} lặng lẽ liếc nhìn ngươi."},{"who":"A","text":"{Goi} ơi, mèo này theo con từ vườn về tận đây. Con nuôi nó nhé, nó đói lắm."},{"who":"me","text":"Lông bết bụi, xơ xác thế này. Cung nhân sợ bẩn thềm cả rồi, con nhìn họ kìa."},{"who":"A","text":"Con tắm cho nó, con dọn thềm sạch. Con hứa mà."},{"who":"me","text":"Con chân thành thế, {xung} khó nỡ từ chối. Nhưng nên quyết thế nào, để {xung} nghĩ."}]}},
{"id":"j68:j68c-kid-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây đàn nhỏ dây tơ căng sẵn trong tay, {A} đứng ở cửa, miệng bĩu ra, thầy đàn chờ ở đình ngoài, tiếng dây tơ chưa ngân đã tắt."},{"who":"A","text":"{Goi} ơi, tay con đau, con không muốn tập nữa. Thầy chờ ngoài kia, nhưng con không đi đâu."},{"who":"me","text":"Dây tơ căng, ngón tay nhỏ chắc đau lắm. Thầy chờ ngoài đình, nghe tiếng đàn chưa ngân đã tắt."},{"who":"A","text":"Con tập mãi mà chẳng hay lên. Con thấy chán."},{"who":"me","text":"Đứa nhỏ chán đàn cũng là chuyện thường. Để {xung} nghĩ cách dỗ con."}]}},
{"id":"j68:j68c-kid-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Áo gấm nhỏ thêu cá chép đỏ rực nằm trong tay, {A} níu chặt tà áo ngươi, mắt tha thiết như sợ bị bỏ lại."},{"who":"A","text":"{Goi} ơi, nghe nói tối nay có đại yến, cho con theo nhé. Con sẽ ngoan, con không quấy đâu."},{"who":"me","text":"Yến đông người, ồn ào, chưa chắc hợp với trẻ nhỏ. Con có mệt không, buồn ngủ không?"},{"who":"A","text":"Con không mệt. Con muốn ở cạnh {goi}. Áo mới này con mặc đẹp lắm đấy."},{"who":"me","text":"Con dựa vào {xung} thế này, {xung} cũng không yên nếu để con ở nhà. Để {xung} nghĩ cho vẹn."}]}},
{"id":"j68:j68c-kid-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm giông sấm vang, con thỏ vải cũ tai đã sờn ôm chặt trong tay, {A} ôm gối chạy sang giường ngươi, run lẩy bẩy."},{"who":"A","text":"{Goi} ơi, sấm to quá, con sợ lắm. Cho con ngủ cùng {goi} nhé."},{"who":"me","text":"Lại đây con. Con run như lá rồi. Thỏ vải của con cũng run theo phải không?"},{"who":"A","text":"Dạ, nó cũng sợ. Con dỗ mãi nó mà không nín."},{"who":"me","text":"Cả hai đứa đều sợ. {M} đứng ngoài cửa chưa dám vào. Để {xung} nghĩ cách dỗ con."}]}},
{"id":"j68:j68c-kid-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đống giấy rách, tập chép thơ nhỏ nét chữ nguệch ngoạc nằm vung vãi, {A} ngồi giữa, mắt đỏ, môi mím chặt."},{"who":"A","text":"Con không muốn học nữa! Cung nhân khen ai cũng học giỏi hơn con. Con ghét!"},{"who":"me","text":"Con xé hết tập chép dở rồi. Nét chữ còn nguệch ngoạc mà con đã xé, {xung} nhìn mà xót."},{"who":"A","text":"Con chép mãi mà chữ vẫn xấu. Con thua hết rồi."},{"who":"me","text":"Con giận vì sợ thua, {xung} hiểu. Để {xung} nghĩ cách nói với con."}]}},
{"id":"j68:j68c-kid-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Túi bạc lẻ nhỏ dây buộc cẩn thận trong tay {A}, một cung nhân mới mất mẹ đứng ngượng ngập, chưa dám nhận."},{"who":"A","text":"{Goi} ơi, chị này mới mất mẹ, chị buồn lắm. Con muốn tặng chị túi bạc nhỏ này, được không?"},{"who":"me","text":"Túi bạc lẻ buộc dây cẩn thận. Con nghĩ cho chị trước, lòng con tốt lắm."},{"who":"A","text":"Con thấy chị khóc một mình. Con không biết làm gì, chỉ có túi bạc này thôi."},{"who":"me","text":"Lòng nhân ái của con khiến {xung} xúc động. Để {xung} nghĩ cách giúp con."}]}},
{"id":"j68:j68c-kid-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bài chép thơ nộp thầy nét chữ lạ nằm trên án thầy đồ, {A} đứng cúi đầu, ngón tay xoắn vạt áo."},{"who":"A","text":"{Goi} ơi, con nhờ cung nhân chép giùm bài chữ trước kỳ học. Con nộp rồi, thầy chưa biết."},{"who":"me","text":"{M} đã thấy nét chữ khác. Con làm thế là không phải, con hiểu không?"},{"who":"A","text":"Con biết sai. Nhưng con sợ thầy phạt, con chép không kịp."},{"who":"me","text":"Con thành thật nhận, {xung} thấy yên lòng. Để {xung} nghĩ xem nên dạy con thế nào."}]}},
{"id":"j68:j68c-kid-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con diều giấy hình cá mắc trên cành cây cuối vườn, gió chiều đã lạnh, cổng vườn sắp đóng, bóng nhỏ của {A} biến mất sau hàng liễu."},{"who":"A","text":"{Goi} ơi, con đuổi diều rồi lạc đường. Trời tối, con sợ lắm, con không tìm thấy lối ra."},{"who":"me","text":"Gió chiều lạnh rồi, cổng vườn sắp đóng. Cung nhân tìm khắp nơi mà chưa thấy con."},{"who":"A","text":"Con nghe tiếng ai gọi mà không biết hướng nào. Con đứng yên chờ ạ."},{"who":"me","text":"Con ngoan, đứng yên đó. Để {xung} nghĩ cách đến với con thật nhanh."}]}},
{"id":"j68:j68c-kid-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ giấy hoa tiên mực còn ướt trong tay nhỏ, {A} chạy đến, mắt sáng rỡ, chữ chưa đều mà ý đã đầy tự hào."},{"who":"A","text":"{Goi} xem, con làm xong câu đối đầu tiên rồi! Con viết lên giấy hoa tiên này, mực còn chưa khô đâu."},{"who":"me","text":"Mực còn ướt, nét chữ chưa đều, mà ý thì ngây ngô đáng yêu. Con nghĩ ra từ bao giờ?"},{"who":"A","text":"Con nghĩ từ sáng, nghĩ mãi mới ra. Thầy bảo hay thì con muốn khoe cho {goi}."},{"who":"me","text":"Câu đối đầu tiên của con, đáng ghi nhớ. Để {xung} nghĩ xem nên đáp lại thế nào."}]}},
{"id":"j68:j68c-kid-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn lồng nhỏ giấy dầu run run trong tay trẻ, {A} ngồi thu mình bên giường, không chịu ngủ, mắt mở to nhìn ra phía giếng cũ."},{"who":"A","text":"{Goi} ơi, cung nhân kể ở giếng cũ có ma. Con sợ lắm, con không dám ngủ."},{"who":"me","text":"Chuyện ma ở giếng cũ chỉ là lời bịa của người ta. Nhưng con thì tin thật, nắm đèn chặt thế kia."},{"who":"A","text":"Con nghe rõ ràng mà. Tiếng khóc trong giếng, tóc xõa dài, mắt đỏ."},{"who":"me","text":"Nỗi sợ của trẻ không thể gạt đi một câu. Để {xung} nghĩ cách dỗ con."}]}},
{"id":"j68:j68c-kid-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa điện thỉnh an, chuỗi ngọc đeo cổ va leng keng theo từng cử động của {A}, vài ánh mắt đã quay sang, mồ hôi rịn sau gáy ngươi."},{"who":"A","text":"{Goi} ơi, con chán quá. Chuỗi ngọc của con kêu leng keng vui lắm, con lắc thêm nữa nhé."},{"who":"me","text":"Con khẽ thôi. Cả sảnh đang nghe tiếng ngọc va, các bề trên đang nhìn."},{"who":"A","text":"Con không cố ý. Chỉ là con nghịch một chút thôi."},{"who":"me","text":"Nghịch giữa điện thỉnh an không phải chuyện nhỏ. Để {xung} nghĩ cách nhắc con cho khéo."}]}},
{"id":"j68:j68c-kid-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cặp cá vàng vảy lấp lánh trong chậu nhỏ cung nhân bê tới, chum nước trong sân đã đầy rêu, nước đục, {A} reo lên không dứt."},{"who":"A","text":"{Goi} ơi, cho con nuôi cặp cá vàng này nhé! Con sẽ đặt tên, hát cho chúng nghe mỗi sáng."},{"who":"me","text":"Cá vàng vảy lấp lánh thế này đẹp thật. Nhưng chum trong sân đã đầy rêu, nước đục rồi."},{"who":"A","text":"Con sẽ thay nước mỗi ngày, con hứa. Con không để chúng chết đâu."},{"who":"me","text":"Lời hứa của trẻ chân thành nhưng dễ quên. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-kid-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén nước nóng run run trong tay nhỏ, nước trà hơi đặc, hơi tràn ra đĩa sứ, {A} đứng chờ, mặt đỏ ửng vì ngượng."},{"who":"A","text":"{Goi} ơi, con tự pha trà cho {goi} lần đầu. Con làm theo cung nhân, không biết có ngon không."},{"who":"me","text":"Đĩa sứ còn ướt nước trà, chén hơi tràn một chút. Nhưng tay con run thế mà vẫn bưng đến đây."},{"who":"A","text":"Con sợ làm đổ, nên cố gắng đi thật chậm. {Goi} thử một ngụm đi."},{"who":"me","text":"Chén trà đầu tiên của con, đáng quý hơn mọi chén khác. Để {xung} nghĩ cách đáp con."}]}},
{"id":"j68:j68c-kid-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Góc khăn thêu tên con còn thoang thoảng mùi sen, {A} đứng im, mặt tái đi, hai tay chắp trước ngực như chờ bị mắng."},{"who":"A","text":"{Goi} ơi, con làm mất khăn tay {goi} thêu cho con rồi. Con chơi ở hồ sen, khăn rơi xuống nước."},{"who":"me","text":"Khăn thêu tên con, {xung} mất cả mấy đêm thêu. Con nhìn {xung} mà mặt tái thế này."},{"who":"A","text":"Con xin lỗi. Con không cố ý, con chỉ mải chơi."},{"who":"me","text":"Con thành thật nhận lỗi, {xung} thấy yên lòng. Để {xung} nghĩ cách giúp con."}]}},
{"id":"j68:j68c-kid-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa rơi rả rích ngoài hiên, cuốn sách tranh cổ tích gáy sờn vì lật nhiều nằm trong tay nhỏ, {A} kéo tay ngươi mãi không buông."},{"who":"A","text":"{Goi} ơi, đọc lại câu chuyện này cho con nghe đi. Con đã thuộc lòng rồi, nhưng con vẫn muốn nghe."},{"who":"me","text":"Con thuộc lòng mà vẫn muốn nghe. Bàn việc của {xung} còn dở dang, mưa lại rả rích thế này."},{"who":"A","text":"Con thích nghe giọng {goi}. Mưa thế này, nghe chuyện là nhất."},{"who":"me","text":"Một đứa trẻ mê nghe giọng mẹ, từ chối sao đành. Để {xung} nghĩ xem nên làm thế nào."}]}},
{"id":"j68:j68c-kid-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp bánh ngoại gửi từ lâu, hộp gỗ nhỏ khép lỏng, {A} mân mê nắp hộp, hỏi bằng giọng nhỏ như gió."},{"who":"A","text":"{Goi} ơi, vì sao con của dì cung bên được nhà ngoại vào thăm, mà con thì không? Con nhớ ngoại."},{"who":"me","text":"Hộp bánh ngoại gửi con vẫn giữ từ lâu. Nhà ngoại ở xa, khó vào cung, con có biết không?"},{"who":"A","text":"Con biết, nhưng con vẫn nhớ. Con cũng muốn ngoại đến thăm như các bạn."},{"who":"me","text":"Nỗi nhớ của trẻ nhẹ mà thấm sâu. Để {xung} nghĩ xem nên đáp con ra sao."}]}},
{"id":"j68:j68c-kid-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mũi kiếm gỗ sơn đỏ vương vệt máu nhẹ, trong vườn một đứa trẻ khóc ré, {A} đứng đó mặt cắt không còn giọt máu."},{"who":"A","text":"{Goi} ơi, con không cố ý đâu. Con vung kiếm, mũi kiếm trúng tay bạn, bạn khóc to lắm."},{"who":"me","text":"Máu rịn nhẹ, cha mẹ đứa trẻ đã được báo. Con có biết chuyện nghiêm trọng thế nào không?"},{"who":"A","text":"Con biết. Con sợ lắm. Con muốn xin lỗi nhưng không dám."},{"who":"me","text":"Con biết sợ, biết nhận, là điều tốt. Để {xung} nghĩ xem nên đưa con đi thế nào."}]}},
{"id":"j68:j68c-kid-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con ngựa gỗ sơn son bị kéo chặt hai đầu, hai đứa trẻ đỏ mặt giữa sân, cung nhân hai bên đứng nhìn chờ xem phản ứng của ngươi."},{"who":"A","text":"{Goi} ơi, con ngựa gỗ này là của con! Bạn cứ đòi lấy, con không cho."},{"who":"me","text":"Hai đứa kéo chặt, mặt đỏ hết cả. Hai bên cung nhân đang nhìn, phi tần kia cũng đang chờ."},{"who":"A","text":"Con không nhường đâu, con chơi trước mà."},{"who":"me","text":"Chuyện của trẻ nhỏ mà thành chuyện của người lớn. Để {xung} nghĩ xem nên xử thế nào."}]}},
{"id":"j68:j68c-kid-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lọ kẹo mạch nha nắp dán sáp giấu dưới gối, {A} ôm má, nhăn nhó, Thái y viện đã sai người đến nhưng con nhất quyết không chịu uống thuốc."},{"who":"A","text":"{Goi} ơi, con đau răng. Con không uống thuốc đâu, đắng lắm."},{"who":"me","text":"Con giấu lọ kẹo dưới gối đúng không? Chính vì kẹo mà răng con đau."},{"who":"A","text":"Con chỉ ăn một chút thôi. Con không muốn bỏ kẹo."},{"who":"me","text":"Con vừa đau lại vừa sợ thuốc. Để {xung} nghĩ cách dỗ con cho khéo."}]}},
{"id":"j68:j68c-kid-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp bạc lẻ nắp mở trên án cung, {A} chia từng đồng nhỏ cho cung nhân như người lớn, vẻ mặt trang nghiêm đến buồn cười."},{"who":"A","text":"{Goi} xem, con phát bạc cho mọi người giống {goi} vậy. Ai cũng được một ít, không ai bị thiếu."},{"who":"me","text":"Con lấy bạc từ hộp trên án của {xung}. Cung nhân ngập ngừng, người nhận, người từ chối."},{"who":"A","text":"Con chỉ muốn mọi người vui. Con thấy {goi} làm vậy mỗi dịp lễ."},{"who":"me","text":"Con bắt chước người lớn mà chân thành. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-kid-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khay cát luyện chữ phẳng nhẵn trước sân, nét que tre nghiêng ngả trên cát, {A} đứng bên, mắt đầy chờ đợi."},{"who":"A","text":"{Goi} ra xem này! Con viết đầy một khay cát rồi. Nét còn nghiêng nhưng con nghĩ ý hay lắm."},{"who":"me","text":"Nét chữ nghiêng ngả mà ý thật hay. Con nghĩ ra từ đâu vậy?"},{"who":"A","text":"Con nghĩ khi ngắm mây. Mây trôi, con muốn viết ra mà không biết viết sao."},{"who":"me","text":"Chữ nghiêng mà ý thanh, khó có ở đứa nhỏ. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-kid-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắp hòm gỗ chứa chăn hé mở, tiếng khúc khích vẳng ra không ngớt, cung nhân tìm khắp nơi, {M} cũng đứng giữa phòng bối rối."},{"who":"A","text":"{Goi} ơi, đừng nói cho ai nhé. Con trốn trong hòm này nửa buổi rồi. Cung nhân tìm con mãi không thấy."},{"who":"me","text":"Con trốn trong hòm chăn nửa buổi rồi, cung nhân sốt ruột cả. Con nhìn khe nắp hở kia, ai cũng thấy."},{"who":"A","text":"Con thấy vui lắm. Con muốn xem họ có tìm ra không."},{"who":"me","text":"Một trò chơi nhỏ mà khuấy cả cung. Để {xung} nghĩ cách đối đáp."}]}},
{"id":"j68:j68c-kid-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc áo vải cũ may thuở bé gấu đã sờn nhưng còn thơm mùi nắng, {A} níu chặt không buông, cung nhân đứng chờ với bộ áo mới."},{"who":"A","text":"{Goi} ơi, con không muốn thay áo mới. Áo này là áo {goi} may cho con hồi còn bé."},{"who":"me","text":"Áo vải cũ gấu sờn, vậy mà con vẫn nhớ {xung} may. Bộ áo mới thêu đẹp, cung nhân chờ ngoài kia."},{"who":"A","text":"Con thích áo này hơn. Mặc nó, con thấy {goi} ở bên con."},{"who":"me","text":"Một chiếc áo cũ mà chứa cả tình mẹ con. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-kid-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con diều đôi hai màu giấy ghép trên tay nhỏ, {A} chạy về, má hồng, mắt sáng như vừa được tặng cả mùa xuân."},{"who":"A","text":"{Goi} ơi, hôm nay con chơi thả diều với con của {B}. Hai đứa con hợp nhau lắm, còn hẹn mai chơi tiếp."},{"who":"me","text":"Con diều đôi hai màu giấy ghép, hai đứa cùng làm. Con của {B} cũng vui như con sao?"},{"who":"A","text":"Dạ, bạn ấy nói chuyện rất hay. Con thích bạn lắm."},{"who":"me","text":"Con vô tư mà lòng người lớn có chỗ khó. Để {xung} nghĩ xem nên đáp con thế nào."}]}},
{"id":"j68:j68c-kid-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn tay nhỏ hằn vết thước sưng đỏ chìa ra trong ánh đèn, {A} cúi đầu, giọng rụt rè như sợ nói ra là có lỗi."},{"who":"A","text":"{Goi} ơi, thầy phạt đánh thước vào tay con, vì con viết sai một chữ. Tay con đau lắm."},{"who":"me","text":"Tay sưng đỏ thế này, {xung} nhìn mà xót. Thầy là người cả cung kính trọng, nói thẳng dễ rước họa."},{"who":"A","text":"Con không dám kể với ai, chỉ kể với {goi}. Con sợ thầy giận con nữa."},{"who":"me","text":"Con tin {xung} mới nói ra. Để {xung} nghĩ cách xử trí cho khéo."}]}},
{"id":"j68:j68c-kid-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ thư riêng viết dở giấy nhàu, nét chữ ngươi còn rõ trong tay nhỏ, tin vừa lan ra tận hành lang, {A} đứng giữa vòng người, ngây thơ chưa hiểu."},{"who":"A","text":"{Goi} ơi, con nghe {goi} nói chuyện với {M} ở gian trong, con kể lại với chị cung nhân kia. Con không biết là không được nói."},{"who":"me","text":"Câu nói đã lan ra tận hành lang, con còn giữ tờ thư riêng của {xung} trong tay."},{"who":"A","text":"Con thấy tờ thư trên bàn, con chỉ cầm xem thôi. Con xin lỗi."},{"who":"me","text":"Con ngây thơ chưa hiểu, nhưng việc đã lan. Để {xung} nghĩ cách thu xếp."}]}},
{"id":"j68:j68c-kid-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức tranh chim hạc đứng trước hồ, màu nước còn ướt, nét vụng nhưng cái đầu hạc nghiêng nghiêng trông thật có duyên, {A} cầm hí hửng."},{"who":"A","text":"{Goi} xem, con vẽ chim hạc đứng trước hồ, để tặng cha. Màu còn lem một chút, nhưng con thấy đẹp."},{"who":"me","text":"Cái đầu hạc nghiêng nghiêng thật duyên. Con vẽ cả buổi sáng đúng không?"},{"who":"A","text":"Con vẽ từ lúc nắng lên. Con muốn cha thấy con thật chăm."},{"who":"me","text":"Một bức tranh vụng mà đầy lòng thành. Để {xung} nghĩ xem nên giúp con thế nào."}]}},
{"id":"j68:j68c-kid-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp trâm cài nhỏ nắp mở hờ trên án, cung nhân mới tới đứng ngoài hiên, ánh mắt hơi lạ, {A} níu tay ngươi nài nỉ."},{"who":"A","text":"{Goi} ơi, cho con lấy cây trâm trong hộp, con muốn tặng chị cung nhân mới. Chị đã hứa chơi với con cả ngày."},{"who":"me","text":"Cây trâm nhỏ trong hộp của {xung}, con muốn tặng người ta quen chưa lâu. Ánh mắt người ấy, {xung} thấy hơi lạ."},{"who":"A","text":"Chị hiền lắm, còn kể chuyện cho con nghe. Con thích chị."},{"who":"me","text":"Con tin người dễ dàng, mà người lớn thì phải cân nhắc. Để {xung} nghĩ cách đáp con."}]}},
{"id":"j68:j68c-kid-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khăn lau mồ hôi ướt đẫm trong tay nhỏ, {A} tập quyền từ sáng sớm cùng thị vệ, mắt díp lại, người còn nóng hổi."},{"who":"A","text":"{Goi} ơi, con tập quyền xong rồi. Con mệt lắm, nhưng con không bỏ giữa chừng đâu."},{"who":"me","text":"Mồ hôi đầm đìa, khăn ướt đẫm cả rồi. Mắt con díp lại, vậy mà tay vẫn nắm chặt khăn."},{"who":"A","text":"Con muốn mạnh như thị vệ. Con muốn bảo vệ {goi}."},{"who":"me","text":"Lời con nói vừa thương vừa buồn cười. Để {xung} nghĩ xem nên đáp con thế nào."}]}},
{"id":"j68:j68c-kid-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gối nhỏ thêu sư tử căng phồng bông gòn trong tay, {A} đứng ở cửa, mũi đỏ ửng vì lạnh, {M} vừa nhóm thêm than."},{"who":"A","text":"{Goi} ơi, đêm nay lạnh quá, chăn giường con mỏng. Cho con ngủ chung với {goi} nhé."},{"who":"me","text":"Mũi con đỏ ửng cả rồi, ôm gối nhỏ chạy sang đây. {M} đã nhóm thêm than, nhưng con vẫn run."},{"who":"A","text":"Con đã đắp hết chăn mà vẫn lạnh. Con nhớ {goi} nữa."},{"who":"me","text":"Đêm đông con tìm hơi ấm của mẹ. Để {xung} nghĩ cách cho con ấm."}]}},
{"id":"j68:j68c-kid-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bài thơ chép dở mực nhòe một góc vì nước mắt trên án, {A} ngồi trước bàn, không ăn cơm, lo đến mức tay run."},{"who":"A","text":"{Goi} ơi, mai con phải đọc thơ trước cha, mà con quên mất mấy câu. Con lo lắm, con không ăn nổi."},{"who":"me","text":"Bài thơ chép dở, mực nhòe một góc vì nước mắt con. Con lo đến mức không ăn cơm, {xung} nhìn mà thương."},{"who":"A","text":"Con học mãi không thuộc. Nếu con quên trước mặt cha, cha sẽ buồn."},{"who":"me","text":"Con sợ làm cha buồn, đứa trẻ có lòng. Để {xung} nghĩ cách giúp con."}]}},
{"id":"j68:j68c-kid-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vòng ngọc xanh nhỏ mát lạnh giấu dưới giường, {A} ngồi sát tường, tay xoắn vạt áo, không dám nhìn ngươi."},{"who":"A","text":"{Goi} ơi, con nhặt được cái vòng ngọc này trong vườn. Con nghĩ là của một phi tần đánh rơi, nhưng con không dám trả."},{"who":"me","text":"Vòng ngọc xanh nhỏ, mát lạnh, con giấu dưới giường. Vì sao con không dám trả?"},{"who":"A","text":"Con sợ bị trách là nhặt đồ của người ta. Con không lấy, con chỉ nhặt thôi."},{"who":"me","text":"Con nhận thật thà, {xung} mừng. Để {xung} nghĩ cách cùng con xử trí."}]}},
{"id":"j68:j68c-kid-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh lụa hình bướm phất phơ trên mái cung bên, dây đứt, {A} đứng giữa sân khóc ré, cung nhân xì xào chưa ai dám sang xin."},{"who":"A","text":"{Goi} ơi, diều của con bay lên mái cung bên rồi! Gió lớn quá, dây đứt mất. Con muốn lấy lại!"},{"who":"me","text":"Diều lụa hình bướm mắc trên mái cung bên, cánh lụa phất phơ. Con khóc thế này cả sân đều nghe."},{"who":"A","text":"Đó là con diều con thích nhất. Con muốn có nó."},{"who":"me","text":"Một con diều mà cả hai cung đều biết. Để {xung} nghĩ cách xử cho phải."}]}},
{"id":"j68:j68c-kid-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con rối gỗ cha tặng lần trước sơn đã mòn ở tay, {A} ngẩng lên, giọng nhẹ như gió thoảng mà ánh mắt nặng như đá."},{"who":"A","text":"{Goi} ơi, vì sao cha ít khi ở chỗ mẹ? Cha tặng con rối gỗ này lâu lắm rồi, cha chưa đến thăm con nữa."},{"who":"me","text":"Con rối gỗ sơn đã mòn ở tay, con nắm bao lâu rồi. Câu hỏi của con nhẹ mà {xung} nghe nặng."},{"who":"A","text":"Con nhớ cha. Mà cha bận lắm phải không?"},{"who":"me","text":"Một đứa trẻ hỏi mà người lớn khó đáp. Để {xung} nghĩ cách nói với con."}]}},
{"id":"j68:j68c-kid-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phao bầu khô buộc dây gai nơi bờ hồ ngự uyển, mặt hồ êm nhưng sâu, {A} giơ phao lên đòi xuống nước, cung nhân cười đùa gần đó."},{"who":"A","text":"{Goi} ơi, cung nhân rủ nhau bơi ở hồ ngự uyển. Cho con xuống nước với, con có phao bầu khô này nè."},{"who":"me","text":"Mặt hồ êm nhưng sâu, tay chân con còn bé. Phao bầu khô buộc dây gai thế này, {xung} vẫn lo."},{"who":"A","text":"Con không sợ đâu. Con sẽ bám phao thật chặt."},{"who":"me","text":"Con gan dạ mà lòng {xung} không yên. Để {xung} nghĩ xem nên đáp thế nào."}]}},
{"id":"j68:j68c-kid-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hạt dẻ rang nóng gói giấy còn hơi ấm trong tay nhỏ, {A} chìa ra đổi lấy một câu chuyện, mắt long lanh."},{"who":"A","text":"{Goi} ơi, kể con nghe ngày bé {goi} từng chơi gì, từng sợ gì đi. Con đem hạt dẻ rang nóng này đổi nhé."},{"who":"me","text":"Hạt dẻ rang nóng, thơm cả tay con. Con đổi một câu chuyện lấy một gói hạt, {xung} thấy hời quá."},{"who":"A","text":"Con muốn biết {goi} hồi bé thế nào. Có sợ sấm như con không?"},{"who":"me","text":"Con muốn biết cả thuở nhỏ của {xung}. Để {xung} nghĩ nên kể phần nào cho trẻ."}]}},
{"id":"j68:j68c-kid-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mâm đồ chơi bày giữa sân, nén hương bằng que tre khói giả nhỏ xíu, {A} đứng đầu, cung nhân cúi lạy theo, trò đùa nghiêm trang như thật."},{"who":"A","text":"{Goi} ơi, con bày bàn hương, bắt mọi người cúi lạy. Mọi người cũng chịu chơi với con."},{"who":"me","text":"Nén hương que tre, khói giả nhỏ xíu. Cả sân cung nhân đang lạy con. Nếu người lạ nhìn thấy, dễ hiểu lầm."},{"who":"A","text":"Con chỉ chơi thôi mà. Con đóng vai bề trên, con thấy vui."},{"who":"me","text":"Trò đùa vui mà có thể gây hiểu lầm. Để {xung} nghĩ cách đáp con thế nào."}]}},
{"id":"j68:j68c-myst-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió sớm đưa {O} đong đưa dưới mái cổng, ngọn nến bên trong đã cạn, chỉ còn vệt sáp đọng lại như giọt lệ."},{"who":"M","text":"{Goi}, mở cổng sáng nay, nô tỳ đã thấy nó treo ở đó. Hỏi khắp lượt người gác mà chẳng ai nhận là của mình."},{"who":"me","text":"Treo ngay trước cửa cung ta, mà nến cháy cạn từ lúc nào cũng không ai hay. Người đặt nó là muốn soi đường cho ai, hay muốn ai nhìn thấy?"},{"who":"M","text":"Nô tỳ lật đáy đèn lên thì thấy dán một mảnh tem của Nội vụ phủ. Còn vì sao nến tắt giữa đêm, {xung} không dám đoán."},{"who":"me","text":"Vật vô chủ nằm trước cửa nhà mình, nghĩ lại thấy se lạnh. Ta phải liệu cách xử trí, kẻo chuyện nhỏ thành chuyện của cả cung."}]}},
{"id":"j68:j68c-myst-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh tủ vừa mở, mùi cay xộc lên lẫn trong lớp vải mới giặt, khiến người cầm áo phải quay mặt đi mà hắt hơi."},{"who":"A","text":"{Goi}, áo trong tủ có mùi lạ lắm. {Xung} lục ra mới thấy một gói {O} bọc giấy dầu, buộc dây đỏ, không phải đồ của cung mình."},{"who":"me","text":"Dây đỏ, giấy dầu, lại nằm giữa lớp áo ta vẫn mặc hằng ngày. Ngươi chắc từ sáng tới giờ không ai đụng vào tủ?"},{"who":"A","text":"Dạ, tủ khóa kín, chìa chỉ có {xung} và vài người thân tín giữ. Chính vì thế {xung} mới sợ, không biết nghĩ về ai."},{"who":"me","text":"Mùi cay còn vương trên tay áo ta đây. Gói ấy là ai bỏ, vì sao bỏ, ta chưa dám nghĩ, chỉ biết áo này không thể mặc như cũ được nữa."}]}},
{"id":"j68:j68c-myst-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều xuống, dãy phòng đông bỏ hoang phủ bụi và mạng nhện, cửa sổ hé ra một nửa như đang lắng nghe ai."},{"who":"A","text":"{Goi}, đêm qua {xung} nghe rõ tiếng {O} gảy từ dãy phòng phía đông, từng nốt rời rạc mà buồn lắm. {Xung} thề không nghe nhầm."},{"who":"me","text":"Dãy phòng ấy bỏ trống đã lâu, ai lại vào đó mà gảy đàn giữa đêm khuya? Sáng nay ngươi lén ra xem thì thấy gì?"},{"who":"A","text":"Chỉ thấy bụi dày, chẳng có dấu chân. Nhưng cây đàn cũ cất trong phòng nhạc khóa lại, thùng đàn nứt một đường mà dây thì còn mới."},{"who":"me","text":"Dây mới trên cây đàn nứt, nghe mà rợn người. Ngươi đừng sợ, ta cũng muốn biết tiếng đàn ấy từ đâu mà ra."}]}},
{"id":"j68:j68c-myst-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nắng xiên qua song cửa thư phòng, rơi trên án thư còn mở cuốn sổ chép thơ, góc gáy nhăn một nếp lạ."},{"who":"A","text":"{Goi}, lúc nãy {xung} thấy ống tay áo {B} dính vết mực đen còn mới, vừa bước ra khỏi thư phòng của {goi}. Chẳng biết {B} vào đó làm gì."},{"who":"me","text":"Cuốn {O} trên án, ta nhớ rõ mình không để như vậy. Mà {B} thì xưa nay chưa từng có việc gì cần ghé thư phòng này."},{"who":"A","text":"{Xung} chỉ kể điều mình thấy thôi, không dám khẳng định gì. Nhưng nếp gấp nơi gáy sổ, nhìn kỹ thì đúng là lạ thật."},{"who":"me","text":"Lời ngươi nghe nhẹ như gió, mà làm ta không yên. Một vết mực đen, một nếp gấp, chưa đủ để nói ai, nhưng đủ để ta phải xem lại."}]}},
{"id":"j68:j68c-myst-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng bàn tính lách cách dừng hẳn, tờ sổ chi tiêu bày giữa án, dấu mực son nội phủ còn đỏ nơi gáy sổ."},{"who":"A","text":"{Goi}, {xung} giữ sổ đã lâu, chưa bao giờ sai một đồng. Vậy mà tháng này {O} hụt mất vài lạng so với lời ghi."},{"who":"me","text":"Ngươi run cả giọng rồi. Sổ cất trong tráp ở buồng phụ, ngoài ngươi còn ai biết chỗ ấy không?"},{"who":"A","text":"{Xung} thề không biết thất thoát từ đâu. Chỉ nhớ hôm kia tráp mở ra thì khóa hơi lỏng, tưởng do dùng lâu nên không để tâm."},{"who":"me","text":"Khóa lỏng, bạc hụt, một người giữ sổ nước mắt chực trào. Ta chưa vội trách, nhưng sổ này phải có người nhìn cho rõ."}]}},
{"id":"j68:j68c-myst-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chùm chìa đồng nhỏ sáng loáng trong lòng bàn tay run run, đầu chìa chạm tráp mà không chịu khớp vào ổ."},{"who":"A","text":"{Goi}, kỳ lạ lắm. Khóa vẫn nguyên, vậy mà chùm chìa cầm trên tay không còn khớp ổ nữa, như đã bị thay bằng chiếc khác giống hệt."},{"who":"me","text":"Chùm chìa này ta đeo bên mình bao năm, chỉ cần nhìn quai đeo là nhận ra được. Quai đeo của chiếc này có vết xước không?"},{"who":"A","text":"Có ạ. Vết xước ấy đúng là của {goi}, nên mới nói chìa mình đã bị thay đi, mà trở lại trong tráp như chưa từng rời."},{"who":"me","text":"Chìa đi một vòng rồi lại về nơi cũ, kẻ giữ nó trong tay hẳn đã thong thả lắm. Ta phải biết người ấy là ai."}]}},
{"id":"j68:j68c-myst-007","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gạch hành lang phía tây còn ướt sương, từng hạt ngọc trắng lăn lóng lánh như một chuỗi đứt giữa đường."},{"who":"M","text":"{Goi}, sáng nay nô tỳ đi qua hành lang phía tây, nhặt được mấy hạt thuộc {O}. Chúng rải rác một đường, đi từ cung mình tới tận Cung Chính ti."},{"who":"me","text":"Chuỗi ngọc ấy ta cất kỹ lắm. Nhưng nghe ngươi nói, ta lại nhớ trong ngăn của ta còn một hạt, loại chỉ bạc xâu cũng giống."},{"who":"M","text":"Nô tỳ thấy rồi, chuỗi còn thiếu đúng một hạt nằm lại trong ngăn của {goi}. Như thể ai đó đã chọn đường để ngọc rơi ra."},{"who":"me","text":"Một đường ngọc rơi như người cố tình để lại dấu. Ta muốn biết nó dẫn tới đâu, và ai muốn ta đi theo."}]}},
{"id":"j68:j68c-myst-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách, bức tranh mai trắng treo đối diện ô cửa sổ, nắng chiếu lên khiến sắc hoa nhạt như phủ sương."},{"who":"A","text":"{Goi}, lão phu nhìn bức họa này mà cứ thấy lạ. Màu nhạt hơn, nét cọ cuối cùng cũng không phải của lão phu. Có người đã đổi nó bằng một bản sao."},{"who":"me","text":"Ông nói kỹ lại xem. Bức mai trắng ấy treo ở đây mấy tháng nay, sao hôm nay ông mới nhận ra?"},{"who":"A","text":"Vì hôm nay lão phu tới xem lại dấu triện nhỏ nơi góc dưới. Bản thật mà lão phu để lại, nghe đâu đang nằm trong kho của Nội vụ phủ."},{"who":"me","text":"Họa sư nhận ra nét cọ như người nhận ra tiếng con mình. Nếu đúng thế, bức tranh trước mặt ta là kẻ nào đã khéo tay đổi đi?"}]}},
{"id":"j68:j68c-myst-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau sân, miệng giếng bốc lên mùi tanh nồng, nước đục ngầu như bị khuấy từ đáy sâu."},{"who":"A","text":"{Goi}, nước giếng sau sân đục lắm. {Xung} múc một gáo thử thì cá trong {O} đã quay bụng trắng, chết ngay trước mắt."},{"who":"me","text":"Chậu sứ men lam ấy ta vẫn đặt ở bậu cửa, sao lại dọn tới gốc cây sau sân?"},{"who":"A","text":"Dạ, {xung} dọn ra gốc cây cho thoáng, ai ngờ nước giếng lại như vậy. Giếng ấy cả cung cùng dùng, {xung} sợ lắm."},{"who":"me","text":"Cá chết trước người, nước đục sau giếng, cả cung đang uống chung một dòng. Ta không được để nỗi sợ này lan ra mà chưa biết cội nguồn."}]}},
{"id":"j68:j68c-myst-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước thư phòng, một vệt bùn đỏ in sâu trên hiên đá, màu đất lạ giữa buổi sáng khô ráo không một giọt mưa."},{"who":"A","text":"{Goi}, hôm qua trời không mưa mà hiên lại có vệt bùn đỏ này. Dưới thềm còn bị bỏ quên {O}, mòn gót như đã đi nhiều năm."},{"who":"me","text":"Bùn đỏ chỉ có ở đất lạ, mà giày thì không phải loại nội phủ cấp. Ngươi chắc không ai trong cung mình làm rơi?"},{"who":"A","text":"Nô tỳ hỏi khắp rồi, chẳng ai nhận. Bây giờ chiếc giày được cất trong tủ ở Kính sự phòng, chờ người nhận về."},{"who":"me","text":"Một dấu chân nam nhân bước vào chỗ ta đọc sách. Dù không biết là ai, ta cũng phải biết hắn đã tới để làm gì."}]}},
{"id":"j68:j68c-myst-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh tủ sách mở ra, mùi giấy cũ phảng phất, nhưng giữa cuốn y thư có mép giấy trắng mới như vết rách vừa xảy ra."},{"who":"A","text":"{Goi}, cuốn {O} của {goi} bị xé mất mấy trang giữa rồi. Đêm qua cửa tủ không khóa, {xung} cũng không nghĩ tới việc kiểm."},{"who":"me","text":"Cuốn sách ấy gáy còn có chữ ta tự viết, ta nâng niu hơn cả trang sức. Ai lại nỡ xé đúng những trang quan trọng?"},{"who":"A","text":"{Xung} không rõ. Chỉ nhớ đêm qua có tiếng chân đi ngang hiên, mà trời tối, {xung} không dám ra xem."},{"who":"me","text":"Tiếng chân ngoài hiên, mép giấy còn trắng, ta thấy mình như người đọc một cuốn sách đã bị xé mất đoạn đáng đọc nhất. Phải tìm cách lấp đầy chỗ trống ấy."}]}},
{"id":"j68:j68c-myst-012","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sương sớm còn đọng trên vạt đất ngoài sân, cây mai nằm nghiêng giữa đám lá, rễ trắng phơi ra như bàn tay xòe."},{"who":"M","text":"{Goi}, nô tỳ dậy sớm đã thấy cây mai cổ bị nhổ bật gốc. Đất xung quanh còn lỗ cuốc nhỏ, chắc là do tay người chứ không phải gió."},{"who":"me","text":"Cây mai ấy ta chăm từng nhành, chậu men xanh còn khắc tên ta. Giờ trơ gốc giữa sân, lòng ta như bị ai nhổ theo."},{"who":"M","text":"{Xung} đã gom hết rễ, trồng tạm vào chậu mới trong vườn nhỏ. Cây còn sống, nhưng nhành mới e khó đâm lại."},{"who":"me","text":"Còn một chút sự sống là còn hy vọng. Nhưng kẻ cầm cuốc nhổ mai của ta, ta phải biết hắn là ai, và vì sao."}]}},
{"id":"j68:j68c-myst-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một tờ phiếu nhận vải đặt giữa án, dấu son đỏ in rõ ràng, nét chữ nhìn qua tưởng như do chính ngươi viết."},{"who":"A","text":"{Goi}, Nội vụ phủ gửi lại tờ phiếu này, bảo là {goi} đã nhận vải. Dấu {O} đóng lên giống hệt dấu cung mình, chữ ký lại rất giống tay {goi}."},{"who":"me","text":"Ta chưa từng nhận một tấc vải nào. Mà dấu thì đúng là dấu của ta, nét ký cũng đủ để ta ngờ chính mình."},{"who":"A","text":"{Xung} cũng thấy lạ. Con dấu ngọc thạch ấy vẫn được cất trong tráp khóa hai lớp, chìa chỉ có {goi} giữ."},{"who":"me","text":"Dấu thật vẫn nằm yên, vậy mà dấu giả lại đã đi khắp Nội vụ phủ. Kẻ làm được việc này tinh tường hơn ta tưởng."}]}},
{"id":"j68:j68c-myst-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nắng xuyên qua lọ sứ nhỏ, làm màu thuốc bên trong ngả xám như nước hồ lúc chiều muộn."},{"who":"A","text":"{Goi}, {xung} đưa {O} lên soi dưới nắng thì thấy màu đã đổi. Hôm qua còn nâu sậm, nay ngả xám, dù sáp niêm của Thái y viện vẫn còn nguyên."},{"who":"me","text":"Sáp niêm còn nguyên mà thuốc đã khác, nghĩa là có người mở ra mà biết cách đóng lại. Ngươi nhớ ai từng chạm vào lọ?"},{"who":"A","text":"Chỉ có {goi} và {xung}, còn lại là người của Thái y viện đã mang đến nghiệm. Nhưng {xung} không dám nói chắc."},{"who":"me","text":"Thuốc an thần mà bị đổi màu, nghĩ tới việc mình từng uống nó mỗi đêm, ta đã lạnh người. Lọ này phải được xử trí cho rõ."}]}},
{"id":"j68:j68c-myst-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc gương đồng nặng tay nằm trong ngăn trang sức, một đường nứt dài chạy giữa mặt gương, cắt đôi hình người soi vào."},{"who":"A","text":"{Goi}, gương đồng soi mặt của {goi} nứt đôi một đường dài, mà {xung} thề không ai chạm vào. Cung nhân bảo đó là điềm xấu."},{"who":"me","text":"Viền sen vẫn nguyên, bọc lụa cũng vẫn còn đó, mà mặt gương lại tách đôi. Ngươi cũng tin vào điềm gở này sao?"},{"who":"A","text":"{Xung} không biết tin hay không, chỉ thấy rờn rợn. Gương nặng thế mà tự nứt thì thật hiếm có."},{"who":"me","text":"Gương nứt thì lòng người cũng dễ nứt. Ta phải làm sao cho tin đồn này không kịp lan thành nỗi sợ trong cung."}]}},
{"id":"j68:j68c-myst-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư đặt trên án, giấy thơm mùi trầm, góc dưới có dấu triện nhỏ, đoạn cuối mực đen hơn phần đầu."},{"who":"A","text":"{Goi}, có một {O} gửi đến cung mình, nét chữ giống chữ {B} nhưng đoạn cuối mực đen hơn hẳn. Người đưa thư là một tiểu thái giám lạ mặt."},{"who":"me","text":"Thư xin hẹn, mùi trầm của cung {B}, dấu triện cũng đúng. Chỉ có mực là không chịu về chung một chỗ."},{"who":"A","text":"{Xung} cũng chỉ thấy thế. Tiểu thái giám đưa thư xong là đi mất, hỏi tên cũng không đáp."},{"who":"me","text":"Nếu {B} thật lòng hẹn ta thì hà cớ phải giấu mặt người đưa thư? Còn nếu không, thì ai đang mượn tay {B} mà gọi ta?"}]}},
{"id":"j68:j68c-myst-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Song cửa buồng hằn một dấu bàn tay in bằng nước ruộm, ngón xòe rộng, cao hơn đầu người một chút."},{"who":"A","text":"{Goi}, sáng nay {xung} thấy dấu bàn tay này in trên song cửa buồng. Trên bậu còn vương một {O}, chỉ óng ánh như vàng."},{"who":"me","text":"Dấu tay in cao hơn đầu người, thì người ấy tất phải cao lớn, hoặc trèo lên cao. Ngươi có thấy kẻ nào lạ ra vào?"},{"who":"A","text":"Chẳng thấy ai, thưa {goi}. Đầu cuộn chỉ có dấu của nội phủ, nên {xung} không dám tự ý cất, sợ làm mất dấu vết."},{"who":"me","text":"Một sợi chỉ vàng, một dấu tay nhuộm, ta chưa biết nó nói gì. Nhưng nó đã nói rằng đêm qua có người đứng ngay ngoài cửa ta."}]}},
{"id":"j68:j68c-myst-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên gối chiếu, một túi gấm nhỏ nằm im, chỉ thêu chữ ngoằn ngoèo, mùi lạ thoang thoảng làm đầu óc nặng trĩu."},{"who":"A","text":"{Goi}, {xung} nhặt được {O} dưới gối chiếu của {goi}. Mùi hương lạ lắm, ngửi một lát đã choáng váng, tay run không cầm nổi."},{"who":"me","text":"Chữ thêu không phải nét chỉ của cung ta, mà túi lại nằm đúng dưới gối ta. Ngươi có nhớ ai vào buồng không?"},{"who":"A","text":"Không ai ạ. {Xung} dọn giường mỗi sáng, hôm qua chưa thấy gì. Có người đặt vào từ lúc nào, {xung} thật không hay."},{"who":"me","text":"Vật lạ đặt dưới gối người đang ngủ, kẻ ấy dám tới gần ta đến thế. Ta không được để chuyện này trôi qua yên lặng."}]}},
{"id":"j68:j68c-myst-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hàng rào hoa hồng sau cung đón gió, một mảnh lụa mỏng vướng giữa gai nhọn, chỉ bạc lóe sáng trong nắng."},{"who":"A","text":"{Goi}, {xung} nhặt được từ hàng rào hoa hồng một mảnh {O} thêu chỉ bạc, đúng kiểu áo của phi tần. Nhưng chẳng ai nhận là áo mình rách."},{"who":"me","text":"Lụa mịn thế này, chỉ bạc thế này, ngươi nghĩ tới ai? Một phi tần mà rách áo giữa vườn hồng, lại không dám nhận, thật lạ."},{"who":"A","text":"Viền có dấu nội phủ, chắc cũng tra ra được. Có điều {xung} thấy cung nào cũng xì xào, mà không cung nào chịu nói trước."},{"who":"me","text":"Một mảnh áo rách không đáng nói, cái đáng nói là kẻ giữ im lặng về nó. Ta muốn biết ai đã đi qua hàng hoa hồng ấy."}]}},
{"id":"j68:j68c-myst-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên trước, sợi dây mảnh buông thõng, chuông gió bằng đồng nằm lăn bên giậu, khẽ chạm đất không phát ra tiếng."},{"who":"A","text":"{Goi}, sáng ra {xung} thấy {O} nằm bên giậu, dây đứt gọn như bị dao cắt. Đêm qua gió nhẹ lắm, không thể tự đứt được."},{"who":"me","text":"Chuông này khắc chữ phúc, ta treo từ ngày mới vào cung. Kẻ nào cắt dây là muốn tắt tiếng chuông, hay muốn tắt điều gì khác?"},{"who":"A","text":"{Xung} cũng nghĩ vậy. Tiếng chuông xưa nay báo có người tới gần hiên, mất chuông thì cũng mất luôn người canh."},{"who":"me","text":"Ngươi nói đúng, kẻ ấy đã biết chuông là tai mắt của ta. Ta cần xem vết cắt, và cần người canh đêm này."}]}},
{"id":"j68:j68c-myst-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn cờ trong thư phòng còn bày dở thế cờ hôm qua, ánh đèn hắt lên một quân ngọc trắng đứng lạc giữa hai làn đen."},{"who":"A","text":"{Goi}, bàn cờ hôm qua bày dở, hôm nay lại thêm một quân {O} mà {goi} không nhớ. {Xung} thề không đụng tới."},{"who":"me","text":"Quân cờ ngọc trơn, mài tròn đều, ta lại không có quân nào như thế. Ai đã vào thư phòng chỉ để đặt thêm một nước?"},{"who":"A","text":"{Xung} cũng không rõ. Đêm qua cửa đóng, sáng nay cửa vẫn đóng, mà quân cờ thì đã nằm giữa bàn."},{"who":"me","text":"Kẻ ấy chơi cờ với ta mà không cho ta thấy mặt. Nước cờ này đặt xuống, ta không biết nên đáp hay nên chờ."}]}},
{"id":"j68:j68c-myst-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng trà vắng tanh, chiếc mâm sơn đỏ còn đặt giữa bàn, vụn bánh trắng như tuyết lả tả rơi ra tận cuối hành lang."},{"who":"A","text":"{Goi}, mâm {O} thiếu mất một chiếc, vụn bánh rơi dài ra tới cuối hành lang. Nghe cứ như có kẻ đói lén vào ăn vụng."},{"who":"me","text":"Kẻ đói mà biết chọn đúng bánh hạt sen, lại nhẹ chân đến mức không ai nghe thấy. Ngươi cười gì thế?"},{"who":"A","text":"Nô tỳ cười vì vụn bánh rơi vãi thế kia, chẳng khác chim sẻ lạc vào bếp. Nhưng cũng lạ, chữ phúc dưới đáy mâm vẫn còn nguyên."},{"who":"me","text":"Một chiếc bánh nhỏ, một dấu vụn dài, nghe là chuyện vặt mà lại như có người đang chỉ đường cho ta đi theo."}]}},
{"id":"j68:j68c-myst-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cổng cung, ngọn nến cháy hừng hực như lửa nhỏ, sáp chảy xuống thành vệt đen trên chân đèn."},{"who":"A","text":"{Goi}, ngọn {O} thắp ngoài cổng cháy nhanh gấp đôi mọi hôm, sáp chảy xuống thành vệt đen. {Xung} ngờ có ai thêm thứ gì vào bấc."},{"who":"me","text":"Nến sáp ong tốt thế mà cháy nhanh bất thường. Bấc ngâm thứ gì mới sinh ra vệt đen ấy?"},{"who":"A","text":"{Xung} không dám đoán. Chỉ biết chân nến có dấu nội phủ, và mùi khói đêm qua hơi khét, không giống mùi sáp ong thường."},{"who":"me","text":"Khói khét, sáp đen, ngọn nến không chịu cháy như nến. Ta thấy trong bóng tối ấy có điều ai đó muốn giấu."}]}},
{"id":"j68:j68c-myst-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trăng non treo trên giếng cạn sau vườn, rêu xanh phủ miệng giếng, và một nắm vải thô nhàu nhĩ nằm co giữa rêu."},{"who":"A","text":"{Goi}, đêm qua {xung} nghe tiếng khóc vọng lên từ giếng cạn sau vườn. Cả đám cung nhân không ai dám ra gần."},{"who":"me","text":"Tiếng khóc từ giếng cạn, ai nghe cũng sợ. Nhưng ngươi có thấy thứ gì thật, hay chỉ nghe thấy?"},{"who":"A","text":"Có ạ. Gần giếng có một tấm áo choàng vải thô vứt dưới rêu, chỉ tay may ẩu như người vội. Sáng ra cung nhân đã dọn khỏi giếng."},{"who":"me","text":"Áo của người sống để lại bên giếng, thì tiếng khóc kia chưa chắc là ma. Ta muốn biết ai đã khóc, và vì sao khóc ở nơi ấy."}]}},
{"id":"j68:j68c-myst-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn trang điểm, hộp sứ vẽ hoa đào mở toang, bên trong trống trơn, chỉ còn một vệt đỏ in nơi đáy."},{"who":"A","text":"{Goi}, {O} đặt trên bàn trang điểm trống trơn rồi, chỉ còn vệt đỏ nơi đáy. Đêm qua {xung} nghe loáng thoáng tiếng mở hộp."},{"who":"me","text":"Son hết sạch mà nắp sứ vẫn nguyên, cứ như người lấy không muốn lưu dấu. Ngươi nghe tiếng mở hộp lúc nào?"},{"who":"A","text":"Lúc canh ba, thưa {goi}, khi đó {xung} đã ngái ngủ nên không dám chắc. Hộp này sau đó {xung} giữ trong ngăn kéo thu dọn."},{"who":"me","text":"Một vệt son đỏ, một tiếng mở hộp lúc canh ba. Nhỏ nhặt thế mà ta lại thấy khó ngủ."}]}},
{"id":"j68:j68c-myst-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cổng sau, một chiếc nón gỗ nằm nghiêng dưới gốc cây, đế nhẵn mòn, bã trà khô còn bám trong lòng nón."},{"who":"A","text":"{Goi}, trước cổng sau có {O} ai bỏ lại, đế nhẵn mòn mà vương bã trà. {Xung} nhìn vành thì giống nón thị vệ canh đêm."},{"who":"me","text":"Thị vệ canh đêm mà bỏ nón lại trước cổng cung ta, nghe vừa buồn cười vừa đáng ngại. Nón có dấu gì không?"},{"who":"A","text":"Có dấu của Kính sự phòng, mòn cả vành. Hiện nón đang được cất ở phòng trực của thị vệ, chờ người nhận."},{"who":"me","text":"Một chiếc nón gỗ bỏ quên, hay một người vội vàng chạy đi mà không kịp đội? Ta tò mò, nhưng cũng phải cẩn trọng khi hỏi."}]}},
{"id":"j68:j68c-myst-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư nhà từ ngoài cung nằm trên án, sáp niêm bị bóc rồi dán lại, nét dán ẩu như tay trẻ con làm."},{"who":"A","text":"{Goi}, phong {O} này đến lúc {xung} nhận thì còn nguyên sáp niêm. Vậy mà giờ mép giấy rách, chỗ dán thì ẩu."},{"who":"me","text":"Thư nhà cha mẹ gửi, ta nâng niu từng chữ. Ai lại nhẫn tâm bóc ra đọc trước ta?"},{"who":"A","text":"{Xung} chỉ biết cất thư trong hộp riêng của {goi}. Nếu có kẻ đọc, thì là sau khi thư rời tay {xung}."},{"who":"me","text":"Dòng chữ nhà đã bị mắt lạ nhìn qua, nghĩ tới thôi ta đã thấy nghẹn. Thư còn đủ hay đã mất, ta phải xem ngay."}]}},
{"id":"j68:j68c-myst-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa rả rích suốt đêm, đến sáng chiếc áo choàng lông cáo trắng còn treo trên móc cửa, vạt áo nặng trĩu bùn nâu."},{"who":"A","text":"{Goi}, đêm qua mưa cả đêm, mà {O} treo ở móc cửa lại ướt sũng, bùn bắn tận gối. Tối qua {xung} đã cất khô cẩn thận rồi."},{"who":"me","text":"Áo cất trong nhà mà lại dính bùn đường, nghĩa là có ai khoác nó đi ra ngoài trong mưa. Ngươi có nghe tiếng cửa mở không?"},{"who":"A","text":"Không ạ, nhưng nút ngọc nhỏ ở cổ áo lệch chỗ, như người lạ tay cài. Giờ áo được hong khô bên lò sưởi."},{"who":"me","text":"Lông cáo trắng vấy bùn, nút ngọc cài lệch, kẻ nào mượn áo của ta mà không để ta hay? Ta muốn đoán xem bùn ấy là bùn của nơi nào."}]}},
{"id":"j68:j68c-myst-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau cánh cửa buồng, một tấm giấy vàng cũ nằm cuộn lại, mực son nhòe lấm tấm như vệt máu khô."},{"who":"A","text":"{Goi}, {xung} bóc từ sau cánh cửa buồng ra một {O}, vẽ ngoằn ngoèo, chữ không ai đọc nổi. {Xung} nghĩ nên đem đốt cho xong."},{"who":"me","text":"Bùa dán sau cửa phòng ta, ai dán, dán để làm gì? Đốt đi thì tiện, nhưng chữ không ai đọc nổi mới càng đáng ngại."},{"who":"A","text":"Giấy cũ, mực son nhòe, nhìn là biết không phải mới vẽ. {Xung} cất vào hộp nhỏ rồi, chờ {goi} định đoạt."},{"who":"me","text":"Lá bùa nằm im trong hộp mà ta thấy nó nặng hơn mọi vật trong buồng. Đốt hay giữ, ta phải quyết cho xong."}]}},
{"id":"j68:j68c-myst-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau cung, chuồng gà vắng lặng, vài chiếc lông rụng nằm dọc hàng rào, dẫn thẳng về dãy nhà bếp khói lên nghi ngút."},{"who":"A","text":"{Goi}, chuồng gà sau cung mất dần mỗi đêm một con, lông rơi từ hàng rào tới tận nhà bếp. {Xung} đoán có kẻ lén bán trứng và {O} ngoài cổng."},{"who":"me","text":"Mỗi đêm một con, đều đặn như nhịp canh. Sổ trứng gà ta có chữ viết tay, ngươi giữ ở đâu?"},{"who":"A","text":"{Xung} cất trong ngăn bếp, thưa {goi}. Nhưng gáy sổ gần đây có nét chữ lạ, {xung} chưa dám nói với ai."},{"who":"me","text":"Gà mất, trứng ít, sổ lại có chữ không phải của ta. Chuyện nhỏ như hạt cát mà thành đống, ta nên dò từ đâu đây?"}]}},
{"id":"j68:j68c-myst-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, chậu đồng rửa mặt còn bốc hơi lạnh, mặt nước ngả vàng nhạt như men sứ cũ."},{"who":"A","text":"{Goi}, nước trong {O} rửa mặt sáng nay ngả vàng nhạt, sờ vào hơi nhớt. {Xung} thề đã đổ nước sạch từ đêm."},{"who":"me","text":"Chậu quai chạm hình chim mà nước lại đục thế này. Ngươi rửa chậu lúc nào, úp trên giá thế nào?"},{"who":"A","text":"{Xung} rửa sạch rồi úp lên giá, không ai chạm tới. Đến sáng ra thì nước đã thành ra thế, mà không ai nghe tiếng động."},{"who":"me","text":"Nước ngả vàng, sờ nhớt, thứ gì đã tan vào đó trong đêm? Ta chưa dám nếm, nhưng cũng không thể rửa mặt như chưa có gì."}]}},
{"id":"j68:j68c-myst-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chung trà sen trắng bốc khói mỏng trên án, vị chát gắt xông lên mũi, nghe không giống mùi hoa nhài quen thuộc."},{"who":"A","text":"{Goi}, chung trà hôm nay vị đắng gắt lạ. {Xung} vẫn pha {O} như mọi ngày, vậy mà hộp trà trong tủ lại nhẹ hơn thường."},{"who":"me","text":"Hộp thiếc nắp hoa mai này ta cất kỹ lắm. Nhẹ hơn thường, là có người đã lấy bớt, hay đã đổi thứ khác vào?"},{"who":"A","text":"{Xung} không dám đoán. Chỉ nhớ hôm qua tủ chưa khóa kỹ, bên cung ngoài có người ghé qua hỏi trà."},{"who":"me","text":"Một chung trà đắng, một hộp trà nhẹ, và một người ghé qua hỏi han. Ta uống trà mà lòng lại thấy chát hơn trà."}]}},
{"id":"j68:j68c-myst-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn dầu soi lên cặp xuyến bạc nằm trong hộp trang sức, mặt trong xỉn đi như chưa từng được đánh bóng."},{"who":"A","text":"{Goi}, cặp {O} đeo hôm qua nhẹ hơn lúc mang, lòng trong cũng xỉn. {Xung} nhìn kỹ thì ánh bạc không còn như xưa."},{"who":"me","text":"Xuyến khắc hoa văn sóng, ta đeo mỗi ngày mà không nhận ra. Ngươi nhìn thấy trước ta, ngươi tinh mắt thật."},{"who":"A","text":"Dạ, {xung} thấy nhẹ tay mới ngờ ngợ. Hiện xuyến vẫn nằm trong hộp trang sức, chưa ai động tới."},{"who":"me","text":"Bạc thật hay bạc pha, nhẹ đi vì thời gian hay vì tay người? Nhìn lòng xuyến xỉn, ta chợt thấy cái lạnh len vào cổ tay."}]}},
{"id":"j68:j68c-myst-034","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khe cửa buồng hé một tờ giấy gấp hình hoa sen, cánh giấy mỏng run trong gió, thoảng mùi trầm hương."},{"who":"M","text":"{Goi}, sáng ra nô tỳ thấy dưới khe cửa có {O} gấp hình hoa sen, chỉ một dòng chữ ngắn. {Xung} chưa dám mở rộng ra đọc kỹ."},{"who":"me","text":"Mực tàu xanh, giấy thơm mùi trầm, ta chưa từng thấy ai gấp thư kiểu này. Nét chữ như của người quen mà ta không nhớ ra."},{"who":"M","text":"{Xung} cũng nghĩ như thế, thưa {goi}. Nhìn qua tưởng của một người, nhìn lại thấy khác, như người cố viết lệch tay."},{"who":"me","text":"Một đóa sen giấy gửi vào cửa ta, người gửi biết ta là ai mà ta chẳng biết người. Dòng chữ ngắn kia ta phải đọc cho tới nơi."}]}},
{"id":"j68:j68c-myst-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọc bội xanh nằm trong lòng bàn tay, ánh sáng hắt qua mặt ngọc, hiện ra một vệt móng cào sâu như vết rạn."},{"who":"A","text":"{Goi}, mặt ngọc của {O} bị vết móng cào sâu một đường, mà hôm qua {xung} còn thấy nguyên vẹn. {Goi} có nhớ lúc nào bị không?"},{"who":"me","text":"Ngọc xanh quai lụa này ta đeo ngay hông, ngày nào cũng vuốt qua. Một vết cào sâu thế, sao ta không nhận ra?"},{"who":"A","text":"{Xung} cũng không rõ. Trong hộp gấm không có dấu mở, vậy chắc là bị cào khi {goi} đeo ngoài."},{"who":"me","text":"Ngọc quý mà để lại vết móng, người cào hẳn đã đứng sát bên ta. Ta không nhớ nổi ai, càng muốn tìm cho ra."}]}},
{"id":"j68:j68c-myst-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng nào cũng vậy, bình hoa gốm nhỏ nằm nghiêng trên bàn, miệng cắm hoa lài rũ xuống, và một nhúm lông vàng vương trên nền."},{"who":"A","text":"{Goi}, đêm nào cũng có mèo lạ nhảy lên bàn, kéo rơi {O}. Sáng nào {xung} cũng thấy lông vàng vương lại."},{"who":"me","text":"Bình men rạn ta đã nhờ ngươi dán sáp rồi mà vẫn bị đẩy ngã. Mèo ấy là mèo của cung nào, ngươi thấy chưa?"},{"who":"A","text":"Chưa ạ, chỉ thấy lông và vết chân nhỏ. Nó đến lúc nào cũng nhẹ như gió, nên {xung} chẳng rõ nó từ đâu tới."},{"who":"me","text":"Một chú mèo lạ nghịch bình hoa, nghe thì buồn cười. Nhưng ai nuôi nó, và vì sao nó cứ tìm đến bàn ta?"}]}},
{"id":"j68:j68c-myst-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong chén sứ men lam, thang thuốc đã nguội, một vệt bột trắng lắng ở đáy như cát mịn bị dòng nước bỏ quên."},{"who":"A","text":"{Goi}, {xung} nếm thử {O} thấy vị lạ, lại thấy một vệt bột trắng dưới đáy chén. Mùi thuốc nồng hơn thường."},{"who":"me","text":"Lần trước thái y từng dặn ta rằng nếu có vị lạ thì phải dừng ngay. Ngươi nếm bao nhiêu rồi, có thấy khó chịu không?"},{"who":"A","text":"{Xung} chỉ nếm đầu lưỡi, hơi tê. Phần còn lại đã đổ vào lọ nhỏ, giữ làm bằng chứng."},{"who":"me","text":"Ta nhớ lời thái y dặn, nhớ cả vị thuốc mình uống mỗi sáng. Nếu đây là bàn tay ai đó, thì ta phải biết tay ấy thuộc về ai."}]}},
{"id":"j68:j68c-myst-038","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ánh bình minh vừa rót qua mái hiên, một vòng cỏ gấu buộc dây gai đung đưa, hoa tươi trên đó lại đổi sang loài khác."},{"who":"M","text":"{Goi}, sáng nào cũng có {O} treo ở hiên cung mình, mỗi ngày đổi một loài hoa. {Xung} hỏi người gác, mà chẳng ai thấy ai treo."},{"who":"me","text":"Hôm nay là hoa lài, hôm qua là hoa cúc. Người ấy nhẹ tay như gió, không làm kinh động đến ai."},{"who":"M","text":"Nô tỳ thấy vui thì ít mà sợ thì nhiều, thưa {goi}. Vòng hoa đan bằng cỏ gấu cũng được thay mới mỗi ngày."},{"who":"me","text":"Một lòng tử tế hay một lời nhắn gửi, ta chưa biết. Ta thích đoán cho ra người ấy, nhưng cũng sợ đoán sai."}]}},
{"id":"j68:j68c-myst-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chân tường vườn vừa bị xới một lỗ nhỏ, đất ẩm còn mới, cỏ rạp một lối dài, cái xẻng nằm nghiêng bên cạnh."},{"who":"A","text":"{Goi}, bên lỗ đào ở chân tường vườn còn nằm nghiêng {O}. Đất mới còn ẩm, cỏ bị rạp một lối. Chắc có kẻ vừa đào xong trong đêm."},{"who":"me","text":"Cán gỗ sờn và dấu nội phủ này là xẻng của kho dụng cụ vườn. Kẻ đào định chôn thứ gì, hay định lấy thứ gì lên?"},{"who":"A","text":"{Xung} không dám bới lên. Chỉ biết cỏ rạp tới cửa phụ, như người chạy vội mà không kịp che dấu."},{"who":"me","text":"Một cái lỗ nhỏ, một lối cỏ rạp, một chiếc xẻng bỏ lại. Dưới lớp đất ẩm kia hẳn có lý do để người ta đào đêm."}]}},
{"id":"j68:j68c-myst-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân tiết, nồi cháo phát cho cung nhân loãng như nước sương, hạt gạo thưa thớt nổi chìm trong bát."},{"who":"A","text":"{Goi}, nồi cháo hôm nay nhẹ hẳn, hạt gạo thưa như sao buổi sớm. {Xung} nghe nói {O} đã bị rút bớt một nửa."},{"who":"me","text":"Gạo nếp còn dấu niêm Nội vụ phủ mà vẫn hao, ngươi nghe nói từ ai?"},{"who":"A","text":"Từ người coi kho, thưa {goi}. Bao đã được cân lại và niêm lại, nhưng không ai nhận là mình cân thiếu."},{"who":"me","text":"Cung nhân đói bụng nhìn bát cháo mà lòng nguội, ta là chủ không thể nhắm mắt cho qua. Gạo đã đi đâu, ta phải biết."}]}},
{"id":"j68:j68c-myst-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng chứa đồ nằm khuất sau dãy hành lang, vách tường còn vết tay gõ, bụi rơi lả tả theo từng nhịp."},{"who":"A","text":"{Goi}, {xung} thấy một người ăn mặc như thợ nội phủ gõ tường phòng chứa đồ của {goi}, mang theo {O} lạ. Hỏi tên thì hắn quay đi."},{"who":"me","text":"Thợ nội phủ đến sửa tường thì phải có lệnh, mà cung ta không hề báo. Hắn gõ vào chỗ nào?"},{"who":"A","text":"Gõ dọc theo chân tường phía trong. Thẻ bài của hắn mới tinh, chữ khắc lại lệch, sau đó được thu về phòng trực Kính sự phòng."},{"who":"me","text":"Thẻ gỗ mới khắc lệch, kẻ cầm nó biết ta không để ý. Hắn tìm gì trong tường nhà ta, và đã tìm thấy chưa?"}]}},
{"id":"j68:j68c-myst-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trăng, hoa ngọc lan rụng đầy gốc, một chiếc chén sứ nhỏ đặt ngay ngắn giữa cánh hoa trắng, hương lài thoảng nhẹ."},{"who":"A","text":"{Goi}, đêm nào trăng sáng {xung} cũng nghe tiếng hát khe khẽ trong vườn, hát bài ru của quê {xung}. Dưới gốc ngọc lan có {O} đặt ngay ngắn."},{"who":"me","text":"Người hát biết dọn chén cúng, lại biết hát bài ru xứ nhà ngươi. Ngươi đã nhìn thấy mặt chưa?"},{"who":"A","text":"Chưa ạ. Sáng ra chén đã được thu về Ngự thiện phòng, mép sứ mòn như chén cũ nhiều năm."},{"who":"me","text":"Tiếng hát nửa đêm, chén lài dưới gốc hoa, nghe như một lời nhớ nhà gửi vào gió. Ta không muốn dọa người ấy, nhưng cũng không thể để nó không rõ nguồn."}]}},
{"id":"j68:j68c-rumor-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa trưa, sau vườn lặng gió, miệng giếng cũ tối om như một con mắt không chịu nhắm."},{"who":"A","text":"{Goi}, {xung} nói nhỏ thôi. Đêm qua cung nữ của {B} lén thả một {O} xuống giếng sau vườn, mặt tái xanh như người vừa gặp ma."},{"who":"me","text":"Gói giấy dầu buộc dây ném xuống giếng giữa đêm, vậy mà ngươi lại biết rõ thế. Ngươi nhìn thấy tận mắt sao?"},{"who":"A","text":"Chỉ thấy bóng người thôi, thưa {goi}. Nhưng góc giấy dầu còn vướng lại ở thành giếng, sáng ra {xung} thấy rõ ràng."},{"who":"me","text":"Chẳng ai biết trong gói có gì, chỉ biết một người đã phải sợ đến tái mặt. Chuyện này lan ra thì {B} sẽ ra sao, ta không muốn nghĩ."}]}},
{"id":"j68:j68c-rumor-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi thuốc sắc loang khắp hành lang, nồng và đắng như chuyện vừa bị thì thầm sau bức vách."},{"who":"A","text":"{Goi}, thái giám phòng thuốc kể rằng thang {O} sắc cho cung {B} đã bị đổi vị ba hôm nay. {B} vẫn uống, sắc mặt mỗi ngày một vàng."},{"who":"me","text":"Đổi vị là đổi thứ gì, đổi vì bất cẩn hay vì ý đồ? Ngươi nghe được từ ai?"},{"who":"A","text":"Từ cung nữ hầu thuốc, thưa {goi}. Nàng bảo vị thuốc đắng gắt hơn thường, mà không ai dám nói thẳng với {B}."},{"who":"me","text":"Một chén thuốc đắng, một người cứ thế mà uống, ba ngày trôi qua trong im lặng. Ta nghĩ mà lạnh lòng, nhưng chưa biết nên nói với ai."}]}},
{"id":"j68:j68c-rumor-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn tắt dần sau dãy nhà hầu, tiếng cười rúc rích lan qua sân sau, nơi chuồng gà bị bịt kín bằng những mảnh vải trắng."},{"who":"A","text":"{Goi}, {xung} nghe chuyện này buồn cười lắm. {B} sợ gà trống gáy giữa canh khuya, nên sai người nhét vải bít cả chuồng gà ở sân sau."},{"who":"me","text":"Bịt chuồng gà để khỏi nghe gáy sao? Nghe vừa lạ vừa ngô nghê. Cả dãy nhà hầu cười như vậy, ngươi cũng cười theo à?"},{"who":"A","text":"Dạ, {xung} cười đến chảy nước mắt. Nhưng cười xong lại thấy tội, vì chẳng biết {B} sợ thật hay bị người ta thêu dệt."},{"who":"me","text":"Một lời đồn nhẹ như lông, nhưng lông cũng có ngày thành mũi tên. Ta nên cười theo, hay chặn tiếng cười này lại?"}]}},
{"id":"j68:j68c-rumor-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiên cung vắng người, rèm trúc rủ thấp, giọng người nói khẽ đến mức chỉ như hơi thở lướt qua tai."},{"who":"A","text":"{Goi}, {xung} chỉ dám nói riêng với {goi}. Nghe đồn Thái hậu chê {B} nhút nhát, không xứng tấn phong, còn hỏi dò {M} về {goi}."},{"who":"me","text":"Thái hậu hỏi dò về {xung}, qua tay cung nữ của chính {xung}? {Goi} nghe thế từ ai, có chứng cứ gì không?"},{"who":"A","text":"Không ai làm chứng cả, thưa {goi}. Nhưng lời lẽ nghe như thật, từng câu từng chữ đều có đầu có đuôi, nên {xung} mới sợ."},{"who":"me","text":"Một lời đồn không dấu vết, mà đã chạm cả tới Thái hậu, tới {B}, tới người bên {xung}. {Xung} phải chọn cách cầm nó cho khỏi đứt tay."}]}},
{"id":"j68:j68c-rumor-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang, ánh chiều rọi xiên lên vạt áo người đứng một mình, tay ôm một chiếc hà bao thêu hoa mận."},{"who":"A","text":"{Goi}, {xung} nghe đồn {B}, kẻ hầu ngoài sân, thường đứng cuối hành lang nhìn về phía cổng thị vệ, tay ôm {O} chưa đưa cho ai."},{"who":"me","text":"Hà bao thêu hoa mận, đường chỉ khéo thế, chắc là tay chính nàng thêu. Nàng định đưa cho ai?"},{"who":"A","text":"{Xung} cũng không rõ, chỉ nghe nói như vậy. Nàng vẫn giữ trong ống tay áo, thấy người đi qua là giấu vội."},{"who":"me","text":"Tuổi trẻ đứng ngóng cổng thị vệ, ta nghe mà lòng chợt mềm. Nhưng cung quy nghiêm, ta không biết nên khéo tay hay nên nghiêm mặt."}]}},
{"id":"j68:j68c-rumor-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong hành lang Nội vụ phủ, tiếng bàn tán rì rầm như ong về tổ, ánh bạc lấp lánh nơi cổ tay của người đi qua."},{"who":"A","text":"{Goi}, {xung} nghe nói {B} lấy cớ ngự ban mà kể khắp nơi chuyện được thưởng một {O}, trong khi người trong kho bảo chỉ là đồ thừa."},{"who":"me","text":"Ngự ban hay đồ thừa, hai lời chẳng khớp với nhau. {Goi} tin bên nào?"},{"who":"A","text":"{Xung} cũng không dám tin bên nào. Chỉ biết vòng ngọc nay vẫn đeo trên tay {B}, mặt trong còn có dấu ngự dụng, nhưng nghe rồi chẳng ai biết tin ai."},{"who":"me","text":"Một chiếc vòng ngọc làm cả cung nghi ngờ nhau. Muốn biết thật giả, {xung} phải biết dò từ đâu cho khéo."}]}},
{"id":"j68:j68c-rumor-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giọng thì thầm vọng qua tấm bình phong, tiếng nghe như gió lùa mà từng chữ nặng như chì."},{"who":"A","text":"{Goi}, có người mách rằng người trong cung {B} đã bán {O} mà Hoàng thượng ban, đổi lấy bạc. Nếu thật, đó là trọng tội."},{"who":"me","text":"Ban vật của Hoàng thượng mà đem bán, nghe đã khiếp. Nhưng nếu giả, kẻ mách lẻo kia cũng chẳng nhẹ tội. Ngươi nghe thấy từ ai?"},{"who":"A","text":"Từ người ngoài thành, thưa {goi}. Góc gấm có dấu nội ban nơi viền, lại đã nằm trong tay một chủ tiệm, ghi cả vào sổ Nội vụ phủ."},{"who":"me","text":"Nếu thật, đây là trọng tội; nếu giả, chính ta sẽ mang tiếng vu khống. Lời đã vào tai ta, ta không thể coi như chưa nghe."}]}},
{"id":"j68:j68c-rumor-008","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trên khay sơn son, hộp bánh hạt sen còn bốc hơi ấm, hương thơm dịu mà ai nhìn cũng thấy dè dặt."},{"who":"M","text":"{Goi}, đây là hộp bánh {B} sai tặng đến. Nhưng vài cung đang đồn bánh ấy có hạ bã thuốc, nghe mà nô tỳ run cả tay."},{"who":"me","text":"Thái giám đã thử rồi chứ? Nắp sơn son có dấu riêng của cung {B}, đúng là bánh nàng ấy gửi."},{"who":"M","text":"Dạ rồi, thưa {goi}. Thái giám thử lại nói bánh vẫn ngon lành, không có gì lạ, mà lời đồn thì vẫn cứ lan ra."},{"who":"me","text":"Bánh ngon mà lòng người không yên, nếm một miếng cũng thành chuyện. Ta nên ăn thế nào cho vẹn tình mà không mất lòng tin?"}]}},
{"id":"j68:j68c-rumor-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống hiên cung {B}, ngọn đèn lưu ly vẫn thắp, bấc cháy lặng lẽ tới tận canh ba."},{"who":"A","text":"{Goi}, lục cung đang đàm tiếu rằng {B} bị Hoàng thượng bỏ rơi, đêm đêm ngồi thắp {O} đợi thánh giá không tới."},{"who":"me","text":"Đợi một người không đến, chuyện ấy đáng thương mà cũng dễ thành trò cười. {Goi} đã cười chưa?"},{"who":"A","text":"Không dám ạ. Nhưng đôi ba người đã đem ra cười, nói rằng ngọn đèn kia đặt hiên cung {B} chẳng soi được ai."},{"who":"me","text":"Một ngọn đèn lưu ly cháy tới canh ba, ai thấy cũng thương, ai nghe cũng đồn. {Xung} không biết {B} có muốn ai thương mình hay không."}]}},
{"id":"j68:j68c-rumor-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mặt trời lên cao, tiếng người thì thào bên bờ tường như sương vẫn chưa tan sau giờ ngọ."},{"who":"A","text":"{Goi}, có người trong cung {B} biếu {O} cho thái giám Kính sự phòng, mong được lật thẻ sớm. Ai nghe cũng bĩu môi mà chẳng ai dám nói."},{"who":"me","text":"Biếu bạc vụn để mua thẻ lật, chuyện này vừa hèn vừa nguy. Túi gấm ấy thêu chữ gì?"},{"who":"A","text":"Có chữ thêu của cung {B} thưa {goi}. Nay túi đã vào tay một thái giám, cất trong ngăn bàn Kính sự phòng."},{"who":"me","text":"Một túi bạc vụn đủ làm cả cung nhìn nhau lạnh nhạt. Ta không muốn là người nói ra, cũng không muốn là người mắc kẹt."}]}},
{"id":"j68:j68c-rumor-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư Hoàng thượng, tờ hoa tiên viết thơ nằm ngay ngắn, mép giấy thấp thoáng dấu hoa mai chìm."},{"who":"A","text":"{Goi}, thái giám hầu thư phòng kể Hoàng thượng đã xem bài thơ trên {O} của {B}, khen có hơi thở mùa xuân."},{"who":"me","text":"Nghe vui đấy. Nhưng ngươi vừa nói chữ vừa ngập ngừng, còn điều gì chưa kể?"},{"who":"A","text":"Còn một lời đồn khác, thưa {goi}. Có người bảo ngài chê nét chữ yếu ớt. Hai tin đi ngược nhau như hai ngả sông."},{"who":"me","text":"Một bài thơ, hai lời đồn trái chiều. Cái nào thật, cái nào do người ghen mà thêm? Ta không nên vội tin bên nào."}]}},
{"id":"j68:j68c-rumor-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tủ áo cung ta khép kín, tà áo thêu hoa lan treo thẳng, đường chỉ bạc nơi mép áo ánh lên nhè nhẹ."},{"who":"A","text":"{Goi}, {xung} nghe nói {B} đã sai người chép trộm mẫu thêu {O} của {goi}, sắp mang ra dự yến đầu tháng."},{"who":"me","text":"Mẫu ấy {xung} thêu mấy đêm, chỉ bạc ở mép áo cũng do {xung} khâu để nhận ra. {Xung} chưa thấy mẫu của nàng, nhưng nghe tin đã nóng lòng."},{"who":"A","text":"{Xung} chỉ truyền lại lời đồn, chẳng dám nói chắc. Nhưng tà áo thật vẫn treo trong tủ cung {goi}, chưa ai đụng tới."},{"who":"me","text":"Áo còn trong tủ mà tin đã đi trước {xung}. Sợ thì sợ, nhưng {xung} cũng muốn xem nàng làm gì với mẫu của {xung}."}]}},
{"id":"j68:j68c-rumor-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau Nội vụ phủ, hố rác tỏa mùi ẩm, những mảnh sứ xanh vỡ vụn nằm lẫn trong đống lá mục."},{"who":"A","text":"{Goi}, {B} sắp bị đuổi khỏi cung vì làm vỡ {O}, mà thật ra là người khác làm. {Xung} nghe mà thương."},{"who":"me","text":"Người ngoài đổ lỗi cho kẻ yếu thế, chuyện ấy trong cung vốn không hiếm. Nhưng ngươi có biết ai đã làm vỡ không?"},{"who":"A","text":"Không biết, thưa {goi}. Chỉ nghe nói mảnh vỡ còn nằm sau giá gỗ trong kho, rồi bị quét vào hố rác sau Nội vụ phủ."},{"who":"me","text":"Mảnh vỡ nằm đâu thì lỗi nằm đó, nhưng người bị trách thì chưa chắc có tội. Ta muốn làm gì đó, mà chưa biết làm gì cho khỏi sai."}]}},
{"id":"j68:j68c-rumor-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung {B}, chú mèo ba màu cuộn mình bên bậu cửa, sợi dây vàng quanh cổ khẽ ngân tiếng chuông nhỏ."},{"who":"A","text":"{Goi}, {B} nuôi một con mèo lông ba màu mà Hoàng thượng cũng chưa thấy. Ai nấy xôn xao muốn xin giống, ngay cả {xung} cũng thấy tò mò."},{"who":"me","text":"Mèo ba màu hiếm có, ngươi lại thích. Nhưng sao tin này lại chạy khắp cung nhanh vậy?"},{"who":"A","text":"Vì có người nói ngài sắp ban {O} cho chủ nuôi mèo đẹp nhất. Dây có chuông nhỏ, nghe ngân trong trẻo lắm."},{"who":"me","text":"Một con mèo mà làm cả cung rộn lên, ai cũng muốn thành chủ của nó. Ta muốn xem con mèo ấy, cũng muốn biết ai đang ghen."}]}},
{"id":"j68:j68c-rumor-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đầu giường cung {B}, lọ thuốc ho bằng sứ nằm yên, nút lọ vẫn niêm sáp xanh của Thái y viện."},{"who":"A","text":"{Goi}, {xung} khẽ bảo, thái y tới cung {B} nhiều lần mà lần nào cũng ra về vui vẻ. Có người nghi nàng giả bệnh để khỏi dự yến."},{"who":"me","text":"Giả bệnh để tránh yến, là điều bất kính. Nhưng ngươi nói lọ {O} còn nguyên, sao không dùng?"},{"who":"A","text":"Nút lọ còn sáp niêm, như chưa ai mở. {Xung} đoán vậy, nhưng cũng sợ mình đoán sai, nên chỉ dám nói riêng với {goi}."},{"who":"me","text":"Lọ thuốc còn kín, thái y về vui, tin nghe vừa đủ để nghi mà chưa đủ để kết. Ta phải cẩn thận đừng thành người đầu tiên buộc tội."}]}},
{"id":"j68:j68c-rumor-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng Thái hậu, bức hoành thêu chữ thọ treo cao, từng sợi chỉ vàng lấp lánh trong ánh hương trầm."},{"who":"A","text":"{Goi}, {xung} giận lắm. {B} nói với Thái hậu rằng chính nàng thêu bức {O}, mà chính {xung} đã thức mấy đêm. Mắt {xung} đỏ cả lên."},{"who":"me","text":"Thêu thức mấy đêm mà công lại thành của người khác, ai nghe cũng uất. Chữ thọ ấy có điểm gì chỉ {goi} biết?"},{"who":"A","text":"Có kẽ chỉ rối ở nét cuối, thưa {goi}. Đó là chỗ tay {xung} run vì mệt, người khác không thể bắt chước."},{"who":"me","text":"Một nét chỉ rối cũng là dấu tay thật, nhưng trước mặt Thái hậu, lời ai nặng hơn thì chưa biết. {Xung} phải cân nhắc trước khi mở lời."}]}},
{"id":"j68:j68c-rumor-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong tủ hồ sơ Nội vụ phủ, sổ chia lương thực dịp tiết nằm dưới lớp bụi, chữ ký Tổng quản đậm nét nơi cuối trang."},{"who":"A","text":"{Goi}, thái giám bảo Tổng quản chia {O} cho các cung không đều, cung mình nhận ít hơn cung khác. Có người nói vì {goi} thất sủng."},{"who":"me","text":"Thất sủng hay ghi nhầm, mỗi lời một cách. Ngươi tin lời nào?"},{"who":"A","text":"{Xung} chỉ muốn nói rằng sổ có chữ ký của Tổng quản ở cuối trang. Nếu ghi nhầm thì xem lại sẽ rõ."},{"who":"me","text":"Phần ít đi thì chịu được, nhưng cái tiếng thất sủng thì khó nuốt. Ta không muốn gây chuyện, mà cũng không muốn chịu oan."}]}},
{"id":"j68:j68c-rumor-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, mâm cháo thuốc sơn đỏ nguội dần trên bàn ngoài cung {B}, dấu ngự thiện còn rõ nơi đáy mâm."},{"who":"A","text":"{Goi}, {xung} nghe nói con nhỏ của {B} chỉ sốt nhẹ, mà nàng thổi phồng lên để Hoàng thượng ghé thăm. Có thật không thì {xung} chẳng biết."},{"who":"me","text":"{Xung} cũng chỉ thấy mâm {O} đưa đến cung ấy lúc khuya, nguội ở bàn ngoài. Hài tử sốt, mẫu thân lo, lời nào {xung} cũng chưa nên tin hẳn."},{"who":"A","text":"{Xung} cũng chỉ thấy cháo thuốc có dấu ngự thiện, chưa biết ai đã sai đưa tới."},{"who":"me","text":"Đứa trẻ có thể đang bệnh thật, người mẹ có thể đang lo thật, và cả lời đồn cũng có thể thật. Việc này, {xung} phải bước cho nhẹ."}]}},
{"id":"j68:j68c-rumor-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, bóng người lướt qua cổng cung như vệt khói, vòng xuyến bạc trên cổ tay nàng khẽ chạm nhau thành tiếng leng keng."},{"who":"A","text":"{Goi}, {xung} khẽ báo, {B} bị người cung khác trả {O} để chép lại thời khóa {goi} ra vào. Không có chứng cứ, chỉ thấy {B} bỗng có đồ đẹp."},{"who":"me","text":"Xuyến bạc ấy mới đeo gần đây, ngươi chắc không? Hay chỉ vì nàng bỗng thêm của mà người ta sinh ngờ?"},{"who":"A","text":"Lòng xuyến có khắc chữ cung khác, thưa {goi}. {Xung} thấy tận mắt, nhưng không dám khẳng định gì."},{"who":"me","text":"Thời khóa của ta mà có người chép lại, thì mọi bước chân ta đều bị đếm. Ta cần biết chuyện này có thật hay không, và dùng nó ra sao."}]}},
{"id":"j68:j68c-rumor-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, giữa sân cung {B}, mấy cột sơn đỏ sáng lên, cung nhân đi qua đều ngoái đầu nhìn rồi cười khúc khích."},{"who":"A","text":"{Goi}, {xung} nghe nói {B} mơ thấy rồng quấn quanh cột cung, nên khắp nơi đồn nàng sắp thụ thai quý."},{"who":"me","text":"Rồng quấn cột, giấc mơ đẹp thế đủ làm cả cung rộn lên. Nhưng chính nàng nói sao?"},{"who":"A","text":"Nàng bảo chỉ vì ăn nhiều hạt dẻ nên ngủ không yên, thưa {goi}. Mà lời đồn thì cứ lớn như quả cầu tuyết."},{"who":"me","text":"Hạt dẻ làm nên giấc rồng, người nghe đồn lại thành lời chúc. Ta muốn biết nên cười, nên chúc hay nên nhẹ tay cải chính."}]}},
{"id":"j68:j68c-rumor-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau phòng chuyển, một ngăn kéo gỗ khép hờ, phong thư nhà nằm trong, mép giấy còn vệt mực của người cha."},{"who":"A","text":"{Goi}, {xung} nghe đồn thư nhà của {B} bị giữ lại ở phòng chuyển, và nàng ta lúc đêm khóc thầm. Có người nhận {O} ngầm đổi thư của nàng."},{"who":"me","text":"Thư nhà bị giữ, người thì khóc thầm. Ai ác tâm đến thế mà chặn cả tin cha mẹ?"},{"who":"A","text":"Chưa có ai biết, thưa {goi}. Chỉ nghe thư đã nằm trong ngăn kéo của một nội thị, vệt mực cha viết vẫn còn rõ trên phong bì."},{"who":"me","text":"Một phong thư nhà cũng thành vật mua bán. Ta không rõ thực hư, nhưng nghe tin này khiến lòng ta nhói."}]}},
{"id":"j68:j68c-rumor-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối buổi chiều, phòng nhạc còn vọng một khúc đàn dang dở, nốt cuối kéo dài mà chưa chịu dứt."},{"who":"A","text":"{Goi}, {xung} nghe nói {B} ngày nào cũng ở lại phòng nhạc muộn, học một khúc mà nhạc sư chưa từng dạy ai. Còn nhạc sư cứ nhìn nàng mãi."},{"who":"me","text":"Khúc đàn chưa ai được dạy, người thầy lại nhìn học trò mãi không rời. Ngươi nghe đến đây rồi, hay còn điều gì nữa?"},{"who":"A","text":"Hết rồi ạ, vì chuyện chưa có bằng chứng, {xung} chỉ truyền lại lời người ta. Nhưng nghe thế, {xung} sợ cho tiếng tăm của {B}."},{"who":"me","text":"Đàn là chuyện thanh, người nghe lại dễ biến thành chuyện đục. Ta muốn biết khúc ấy là khúc nào, và ai đang nghe."}]}},
{"id":"j68:j68c-rumor-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho Nội vụ phủ, những tấm lụa thượng hạng xếp chồng lên nhau, mép lụa lấp lánh dấu ngự dụng dưới ánh nến."},{"who":"A","text":"{Goi}, {xung} nghe nói {B} được ban nhiều tấm lụa, còn {goi} chỉ được vài tấm. Có người bảo do {goi} dạo này kém đức."},{"who":"me","text":"Kém đức, một lời đơn giản mà nặng như lụa ướt. Lụa của nàng ấy hiện nằm ở đâu?"},{"who":"A","text":"Đã cất trong rương của {B}, thưa {goi}. Chuyện chia nhiều ít có phần đúng, nhưng lời thêu dệt thì nghe quá khéo."},{"who":"me","text":"Đúng một nửa, thêu thêm một nửa, thành ra không biết giận ai. {Xung} giận cũng khó, mà bỏ qua cũng khó."}]}},
{"id":"j68:j68c-rumor-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước dãy kho giày, tiếng người xì xào chen chúc, những chiếc hộp gỗ mở tung, giày thêu mũi cong xếp thành hàng."},{"who":"A","text":"{Goi}, Tổng quản đang sai người kiểm kê từng đôi {O}, vì nghe nói có kẻ lẫn giày lên cả mâm yến. {Xung} cười không nhịn được."},{"who":"me","text":"Giày lẫn lên mâm yến, ta nghe cũng muốn bật cười. Nhưng Tổng quản mà phải cho kiểm, thì chắc cũng không đùa."},{"who":"A","text":"Cả dãy nhà hầu chen nhau nhìn, thưa {goi}. Giày đều có dấu nội phủ ở vỏ, xếp lại trong ngăn của kho Nội vụ phủ."},{"who":"me","text":"Một chuyện cười mà thành cả buổi kiểm kê. Ta nên đến xem, hay nên để người ta cười cho xong?"}]}},
{"id":"j68:j68c-rumor-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng thuốc sau cung {B}, khói thuốc quyện hương gừng, mùi hắc lạ thoảng qua cánh cửa vừa khép."},{"who":"A","text":"{Goi}, {xung} vội đến báo, có người định bỏ {O} vào chén an thai của {B} khi cung nữ pha thuốc. Nghe qua đáng sợ lắm, mà chưa rõ thực hư."},{"who":"me","text":"An thai là mạng của hai người. {Goi} nghe được từ đâu, và kẻ định hạ thủ là ai?"},{"who":"A","text":"{Xung} chỉ biết có mùi hắc trong bát thuốc. Còn người ấy thì đã cất vị thuốc vào tráp ở cung mình, không biết là ai."},{"who":"me","text":"Chén an thai mà có mùi lạ, mạng người đặt trên tay {xung} một lời nói. Nói sai hay nói chậm, {xung} đều không tha thứ cho mình."}]}},
{"id":"j68:j68c-rumor-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dãy nhà hầu im ắng, một tấm chiếu cũ trải trên sạp gỗ, dưới chiếu thấp thoáng một túi vải thêu hoa mận."},{"who":"A","text":"{Goi}, người ta đồn {B} lén đưa thuốc và bạc cho cung nhân bệnh ở dãy nhà hầu, không để ai hay. Lại có kẻ nói nàng làm vậy để mua lòng người."},{"who":"me","text":"Đưa thuốc lén, cho bạc lén, người đời có thể nói là thiện mà cũng có thể nói là mưu. Ngươi nghĩ sao?"},{"who":"A","text":"{Xung} thấy túi {O} ấy có thêu hoa mận của {B}, nay nằm dưới chiếu của một cung nhân bệnh, thưa {goi}."},{"who":"me","text":"Việc thiện làm trong im lặng lại bị soi ra giữa ánh sáng. Ta chưa biết nên học hay nên cẩn trọng với chuyện này."}]}},
{"id":"j68:j68c-rumor-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên giá sách cung {B}, một cuốn thơ mở dở, trang cuối hơi phồng lên như có thứ gì mỏng nằm kẹp giữa."},{"who":"A","text":"{Goi}, {xung} khẽ nói, có thư từ ngoài thành gửi vào cung {B}, mỗi lần lại kẹp {O} trong sách. Người ngoài viết vòng vo, không rõ nghĩa."},{"who":"me","text":"Thư kẹp trong sách, câu chữ vòng vo, chuyện này giống người sợ bị đọc hơn là người thật thà. Ngươi nhìn thấy thư chưa?"},{"who":"A","text":"Chưa ạ, chỉ biết thư mỏng gấp tư, {B} cất kỹ trong tráp khóa. Có lẽ không phải lần nào cũng đọc trước người khác."},{"who":"me","text":"Thư từ ngoài cung vào tận tay phi tần, nếu thật thì là chuyện lớn. Mà nếu không thật, ta lại thành người gieo ngờ vực."}]}},
{"id":"j68:j68c-rumor-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước thềm, cung nữ đứng cắn môi, mắt long lanh nước, khóe miệng run như cánh bướm sắp tan."},{"who":"A","text":"{Goi}, {xung} chỉ muốn nói một câu thôi. Cung nữ khác nhận phần thưởng đáng lẽ của {xung}, còn bảo {goi} thiên vị."},{"who":"me","text":"Ngươi nói vậy là có ý trách ta sao? Ta thiên vị bao giờ, hay chỉ là người ngoài nhìn thấy như thế?"},{"who":"A","text":"{Xung} không dám trách, chỉ thấy tủi. Công việc cũng làm đủ mà phần thưởng lại về tay người khác."},{"who":"me","text":"Nước mắt ấy không phải giả. Ta nên nghe cho hết, rồi tính cho công bằng, hay chỉ cần nói một lời cho yên?"}]}},
{"id":"j68:j68c-rumor-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng cung, cung nữ mới đứng nép dưới tán lê, chiếc trâm ngọc bích trên tóc xanh như một giọt sương không chịu tan."},{"who":"A","text":"{Goi}, {xung} nghe đồn {B} xin Hoàng hậu đổi một cung nữ sang hầu bên {goi}, nói là thương {goi} thiếu người."},{"who":"me","text":"Thương ta thiếu người, hay thương ta quá mức? Ngươi nói đến cung nữ mới ấy là ai?"},{"who":"A","text":"Là người đang đứng ngoài cổng đó, thưa {goi}. Hôm qua nàng còn đeo {O} mới tinh, có hoa văn riêng của cung {B}."},{"who":"me","text":"Một chiếc trâm xanh biếc nằm trên tóc người lạ, cũng đủ khiến ta thấy sợi dây vô hình chạy từ cung nàng sang cung ta. Nhận hay không, ta phải nghĩ cho kỹ."}]}},
{"id":"j68:j68c-rumor-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm sóc, dưới gốc ngọc lan tối đen, khói hương mong manh bốc lên như một sợi tơ mỏng, vấn vít quanh tấm bài vị nhỏ."},{"who":"A","text":"{Goi}, có người thấy {B} lén thắp hương dưới gốc ngọc lan vào đêm sóc, bên cạnh có {O}. Có kẻ cho là yểm bùa."},{"who":"me","text":"Yểm bùa là tội nặng, nhưng nếu chỉ là thắp hương cho cha mẹ đã khuất thì sao? Ngươi thấy bài vị ra sao?"},{"who":"A","text":"Gỗ đã bóng vì tay vuốt nhiều, thưa {goi}. {B} cất sâu trong hòm riêng. Có kẻ bảo chỉ là cúng cha mẹ."},{"who":"me","text":"Một nén hương dưới trăng, người thấy sợ, người thấy thương. Ta nên cho nàng thắp cho trọn đạo hiếu, hay giữ cung quy cho nghiêm?"}]}},
{"id":"j68:j68c-rumor-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng Thái hậu, chuỗi hạt gỗ trầm lăn qua cổ tay bà, mùi hương ấm lan ra tới ngoài hiên."},{"who":"A","text":"{Goi}, thiên hạ đồn {B} đem {O} cung phụng Thái hậu để lấy lòng. Còn {goi} thì chưa dâng gì."},{"who":"me","text":"{Goi} nói xong lại nhìn {xung} như chờ xem {xung} ra sao. Chuỗi hạt ấy là của {B}, hiện đang trên tay Thái hậu?"},{"who":"A","text":"Dạ, nhẵn tay, mùi trầm ấm, Thái hậu đeo suốt. Người trong cung nhìn thấy đều khen {B} chu đáo."},{"who":"me","text":"Lòng hiếu thảo của người ta thành thước đo cho {xung}. Nhưng {xung} không vội, chỉ muốn nghĩ xem nên đáp lễ ra sao cho đúng lòng mình."}]}},
{"id":"j68:j68c-rumor-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Góc hành lang tối, tiếng cười khẩy rơi xuống như mảnh sứ vỡ, khăn lụa bị nắm chặt đến nhàu nát trong tay người đứng nghe."},{"who":"A","text":"{Goi}, {xung} nói thật, nhà {B} chỉ là thương hộ, ngoài miệng nói đọc sách mà chưa thuộc thơ nào. Cười cho cái thói khoe chữ."},{"who":"me","text":"{Goi} nói thế trước mặt nàng sao? Nàng đang đứng ở góc hành lang kia, tay nắm chặt {O}."},{"who":"A","text":"Nàng nghe rồi ư? Cũng chẳng sao, lời thật vốn khó nghe. Khăn thêu cành mai, chữ ở góc, ai mà chẳng biết là của nàng."},{"who":"me","text":"Khăn lụa tơ tằm nhàu trong tay, mắt ngấn lệ mà vẫn đứng thẳng. {Xung} không thể bước qua như chưa thấy gì."}]}},
{"id":"j68:j68c-rumor-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Ngự thiện phòng, bộ chén sứ men ngọc xếp trong tủ gỗ, ánh men xanh nhạt phản chiếu lên mặt người đứng ngắm."},{"who":"A","text":"{Goi}, {xung} khoe chuyện vui. Nghe đồn Tổng quản sắp ban {O} cho cung nào dọn bếp gọn gàng nhất sau tết ông Táo. Ai nấy rục rịch cả."},{"who":"me","text":"Một bộ chén xinh thế mà cũng khiến cả cung xôn xao. Ngươi nghe đồn từ ai?"},{"who":"A","text":"Từ người hầu Ngự thiện phòng, thưa {goi}. Nghe nói Tổng quản sẽ giao chén cho cung thắng cuộc, nên ai cũng sắp đặt từ giờ."},{"who":"me","text":"Việc dọn bếp mà thành cuộc đua, trong cung đúng là chuyện gì cũng có người thi. Ta không rõ có nên bước vào cuộc ấy hay không."}]}},
{"id":"j68:j68c-rumor-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang Thái y viện thoảng hương thảo dược, một chiếc túi gấm thêu tên viện đặt trên tủ riêng, cánh cửa tủ hé một khe nhỏ."},{"who":"A","text":"{Goi}, {xung} nghe nói Thái y viện đồn có một vị chỉ chữa bệnh cho cung nào biếu {O}, còn các cung khác phải chờ lâu."},{"who":"me","text":"Ta nhớ lần trước thái y đến hơi muộn. Chuyện ấy, lúc đó ta tưởng do bận, nay nghe ngươi nói lại thấy chột dạ."},{"who":"A","text":"Túi gấm thêu tên Thái y viện ấy được cất trong tủ riêng của vị thái y. Chỉ nghe nói, {xung} chưa tận mắt thấy ai biếu."},{"who":"me","text":"Muộn một lần thì có thể là bận, muộn nhiều lần thì thành thói. Ta nên hỏi thẳng, hay nên chờ thêm một lần nữa?"}]}},
{"id":"j68:j68c-rumor-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng kho nhá nhem, hộp son đỏ nằm khuất sau ngăn gỗ, nắp hộp in dấu nội phủ mờ như nét son nhạt."},{"who":"A","text":"{Goi}, người ta đồn {B} đánh cắp {O} ở phòng kho, mà không ai thấy tận mắt. Một số cung nhân đã không muốn nói chuyện với nàng."},{"who":"me","text":"Chưa ai thấy mà đã không ai nói chuyện, lời đồn nặng hơn bằng chứng. Hộp son ấy giờ ở đâu?"},{"who":"A","text":"Đã tìm lại được sau ngăn gỗ trong kho, thưa {goi}. Nhưng người ta nghĩ sao thì vẫn nghĩ như thế."},{"who":"me","text":"Hộp tìm lại rồi mà tiếng xấu vẫn đeo người. Một lời đồn không dễ gỡ, và ta cũng không biết phải gỡ từ đâu."}]}},
{"id":"j68:j68c-rumor-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân sau rộn tiếng cười, giàn tre dựng cao nghiêng nghiêng, con diều giấy hình hạc phơi cánh dưới nắng."},{"who":"A","text":"{Goi}, mấy hoàng tự đang ngầm đặt cược xem ai thả {O} cao nhất. Cả đám cung nhân giúp nhau dựng giá tre."},{"who":"me","text":"Trẻ con chơi diều mà cả cung náo động. Con diều hình hạc kia là của ai, nét mực đen ở cánh nhìn lạ mắt?"},{"who":"A","text":"Là của {B}, thưa {goi}. Có người lo diều bay vướng cây trong Ngự hoa viên, nên {xung} hơi lo."},{"who":"me","text":"Hạc giấy sắp bay lên giữa trời xanh, ta nhìn mà muốn cười. Nhưng cười thì dễ, lo cho cành cây trong vườn mới khó."}]}},
{"id":"j68:j68c-rumor-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối buổi chiều, nơi hành lang hẹp, cung nữ ngồi lặng, chiếc nhẫn đồng nơi tay lấp lánh trong ánh nắng xiên."},{"who":"A","text":"{Goi}, {xung} thì thầm, cung nữ hầu thân cận của {goi}, {B}, sắp đến tuổi xuất cung, lại có người đợi ngoài cổng."},{"who":"me","text":"{B} theo ta bao lâu rồi, nay có người đợi. Ta nghe mà vừa mừng, vừa bâng khuâng."},{"who":"A","text":"Nàng ta thỉnh thoảng cầm {O} nhìn mãi không rời. Trong nhẫn khắc hai chữ nhỏ, hẳn là tên người ấy."},{"who":"me","text":"Nhẫn đồng nhỏ mà chứa cả đời người. Ta nên chúc phúc cho nàng, hay giữ nàng thêm một chút nữa cho lòng ta đỡ trống?"}]}},
{"id":"j68:j68c-rumor-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiên cung {B} đón nắng sớm, chậu sứ hạc trắng đặt giữa, mẫu đơn nở trắng như tuyết mới."},{"who":"A","text":"{Goi}, {xung} rỉ tai, {B} nhờ người trong Nội vụ phủ giữ lại {O} đáng lẽ chia cho cung khác. Hôm nay chậu ấy đặt giữa hiên cung {B}, hoa nở đúng ý Thái hậu."},{"who":"me","text":"Hoa đẹp mà đến sớm thì ai cũng ngờ. {Goi} nghe điều này từ ai?"},{"who":"A","text":"Từ người trong kho, thưa {goi}. Chậu sứ có hoa văn chim hạc, đặt ở hiên cung {B}, nhìn là biết."},{"who":"me","text":"Một chậu mẫu đơn trắng, đẹp đến mức người ta phải tìm cớ nghi ngờ. {Xung} nhìn hoa, mà lòng chẳng yên."}]}},
{"id":"j68:j68c-rumor-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong tráp của Nội vụ phủ, một bức thư không đề tên nằm im, nét chữ nghiêng gấp như người viết vội dưới ánh đèn mờ."},{"who":"A","text":"{Goi}, cung nhân nhặt được một {O} không ký tên, nói {B} lén nhận quà từ người ngoài cung. Lời lẽ rất khéo, như do kẻ nắm rõ cung {B} viết."},{"who":"me","text":"Thư nặc danh, mực tàu rẻ tiền, ai gửi thì giấu mặt, ai đọc thì ngờ vực. Thư nay ở đâu?"},{"who":"A","text":"Tổng quản đã cất trong tráp ở Nội vụ phủ, thưa {goi}. {Xung} nghĩ nên có người xem xét cho kỹ trước khi tin."},{"who":"me","text":"Một bức thư không tên đã đủ làm lòng người lung lay. Ta phải tính xem nên làm gì với nó, và với người đang bị nhắc tới."}]}},
{"id":"j68:j68c-rumor-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dãy phòng cũ sau cung vắng lặng, gió lùa qua cửa nứt, tiếng ho khan vọng ra từng đợt nặng nề."},{"who":"A","text":"{Goi}, {B} ho mãi nên bị chuyển ra dãy phòng cũ phía sau, không ai mang cháo tới. {Xung} thương quá."},{"who":"me","text":"Ho mà không ai mang cháo, ngươi nói đến đây mắt đã đỏ rồi. Ngươi còn nghe thêm gì nữa?"},{"who":"A","text":"Có kẻ thấy {O} của {B} bị đem đổi lấy ít tiền thuốc, nay nằm ở sạp bán đồ cũ ngoài cổng cung."},{"who":"me","text":"Cây lược hình sen nhỏ phải đem bán để mua thuốc, nghe mà xót. Ta phải làm gì đó, trước khi tiếng ho ấy tắt."}]}},
{"id":"j68:j68c-rumor-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong tủ cung ta, tà áo yến thêu mẫu đơn treo thẳng, vạt áo vừa được vá lại, đường chỉ cùng màu như chưa từng đứt."},{"who":"A","text":"{Goi}, cung nữ cung {B} lén cắt đứt một chỉ thêu trên {O} của người khác, làm áo yến bị lộ đường may. {Xung} thề thấy tận mắt."},{"who":"me","text":"Áo yến lộ đường may là mất cả mặt mũi. Mà tà áo ấy hiện treo trong tủ cung ta, sao ngươi nói như chuyện của ta vậy?"},{"who":"A","text":"Vì chính là áo của {goi}, đường may lộ ở nách. {M} đã vá lại rồi, nhưng chỉ cùng màu nên chẳng ai biết."},{"who":"me","text":"Chỉ vá cùng màu, áo nhìn như mới, mà ta thì chẳng thể coi như chưa từng đứt. Yến sắp tới, ta phải nghĩ nên mặc ra sao."}]}},
{"id":"j68:j68c-rumor-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lương đình sau vườn, hai chung trà đặt song song, hơi nóng bốc lên mơ hồ như làn khói của một buổi hẹn không ai biết."},{"who":"A","text":"{Goi}, người ta đồn {B} và một phi tần đối địch vẫn lén hẹn uống trà nơi lương đình sau vườn, nhắc chuyện cũ mà nước mắt lăn dài."},{"who":"me","text":"Hai người đối địch ngồi nhắc chuyện cũ mà khóc, ngươi tin chuyện ấy không?"},{"who":"A","text":"{Xung} nghe nói có người thấy hai người trao {O}. Bình có nắp hoa sen, sau được đem về cung {B} cất vào tủ."},{"who":"me","text":"Nếu chỉ là một cuộc trà nhỏ, ta không nên phá. Nhưng cung này sống nhờ lời đồn, và ta phải biết đứng ở đâu cho khéo."}]}},
{"id":"ky:kyc-ma-001","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong gian dệt của Nội vụ phủ, {W} căng một tấm lụa lên khung, thước trong tay, kéo gác bên cạnh, ánh sáng từ cửa sổ rọi xuống từng sợi tơ."},{"who":"W","text":"Lụa này đo sai nửa phân là cả bộ áo lễ phải bỏ đi. {Goi} đứng nhìn nãy giờ, hẳn là có điều muốn hỏi."},{"who":"me","text":"{Xung} chỉ thấy bà đo mà tay không run, lòng bỗng ngưỡng mộ. Một đường thước mà nặng như lời hứa vậy sao?"},{"who":"W","text":"Nặng chứ. Người mặc áo lễ chẳng bao giờ biết có bàn tay nào đã giữ cho nó vừa vặn. {Goi} có muốn biết bà đo thế nào không?"}]}},
{"id":"ky:kyc-ma-002","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Điện Thọ Ninh lặng lẽ khói hương, {W} xếp từng nén trên án thờ, lưng bà thẳng như cây nến."},{"who":"W","text":"Lễ dâng hương, nén nào đặt trước nén nào đặt sau, sai một nén là cả năm không yên. Đứng đó mà nhìn thì chẳng học được gì đâu."},{"who":"me","text":"Nghe bà nói, {xung} chợt thấy mình vụng về giữa chốn linh thiêng. Một nén hương mà cũng có thứ bậc của nó."},{"who":"W","text":"Cả cung này chuyện gì cũng có thứ bậc, hương chỉ là chỗ dễ thấy nhất thôi. Bà đang nghe đây, {goi} muốn học thế nào?"}]}},
{"id":"ky:kyc-ma-003","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên hiên điện Thọ Ninh, bức tượng Phật mới vẽ dở còn ướt màu, tay áo {W} dính đầy sắc đỏ chu sa."},{"who":"W","text":"Màu này phải pha từ sớm, để lâu là xỉn hết. {Goi} thứ lỗi, tay {xung} lấm lem thế này thật chẳng ra dáng."},{"who":"me","text":"Lấm lem mà {goi} vẫn giữ được sắc đỏ tươi đến vậy, {xung} lại thấy đáng quý hơn bất cứ bộ áo gấm nào."},{"who":"W","text":"Lời ấy làm {xung} ngượng. Chu sa thì đây, nước keo thì đó, {goi} muốn xem {xung} pha, hay muốn có riêng một bức?"}]}},
{"id":"ky:kyc-ma-004","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trăng treo trên mặt hồ, sau mái đình vọng ra tiếng sáo trầm, {W} ngồi một mình trên bậc đá."},{"who":"W","text":"Khúc này {xung} thổi cho người đã khuất. {Goi} nghe cũng được, không nghe cũng chẳng sao."},{"who":"me","text":"Tiếng sáo nghe như nước đọng dưới trăng. {Xung} không nỡ bước đi giữa chừng khi người đang nhớ ai."},{"who":"W","text":"Nhớ nhiều quá thì thành khúc nhạc. {Goi} muốn ngồi nghe hết, hay muốn {xung} dạy lại khúc này?"}]}},
{"id":"ky:kyc-ma-005","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Hành lang trước điện triệu kiến còn vắng, {W} từ xứ xa tới ôm một gói lá trà lạ, mùi lá xộc lên là lạ."},{"who":"W","text":"{Goi} ngửi thử đi. Xứ {xung} uống trà với muối. Đại Hy chê thế là dã man, nhưng {xung} chê Đại Hy uống trà nhạt là phí của trời."},{"who":"me","text":"Muối trong trà nghe lạ tai quá, mà {goi} nói cứ như thể lẽ ấy là đương nhiên. {Xung} tò mò thật."},{"who":"W","text":"Tò mò là cánh cửa tốt nhất giữa hai xứ. {Goi} muốn nghe chuyện xứ {xung}, hay đổi cho {xung} một gói trà Đại Hy?"}]}},
{"id":"ky:kyc-ma-006","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Kho thuốc Thái y viện nồng mùi đương quy, mấy vị thuốc phơi trên sàn tre, {W} nhấc một lát lên soi trước đèn."},{"who":"W","text":"Thuốc thật thuốc giả, nhìn vân là biết. {Goi} có muốn lão phu chỉ cho một lần không?"},{"who":"me","text":"Vân thuốc mảnh như sợi tóc, {xung} nhìn mãi chẳng thấy gì. Hóa ra có những thứ chỉ người từng trải mới nhìn ra."},{"who":"W","text":"Nhìn lâu rồi cũng ra. Còn nếu {goi} mệt trong người, lão phu bắt mạch giùm cũng được, ngay đây thôi."}]}},
{"id":"ky:kyc-ma-007","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ngoài cửa điện, {W} chắp tay trong tay áo, mắt nhìn xuống nền gạch mà tai lắng nghe cả trong lẫn ngoài."},{"who":"W","text":"Bốn mươi năm hầu cận, lão nô chỉ học được một điều: nghe tiếng chân ngài là biết hôm nay nên nói gì."},{"who":"me","text":"Chỉ một điều mà mất bốn mươi năm. {Xung} nghe mà thấy lạnh sống lưng, và cũng thấy thương ông."},{"who":"W","text":"Sống lâu trong cung thì lạnh là thường. {Goi} muốn nghe thêm, lão nô kể thêm vài điều cũng không sao."}]}},
{"id":"ky:kyc-ma-008","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ngoài sân Kính sự phòng, {W} ngồi mài cây roi gỗ như mài một món đồ thủ công, gương mặt chẳng chút hung hăng."},{"who":"W","text":"Người vào đây không ai muốn nghe lệ phạt, nhưng không nghe thì lại càng khổ. {Goi} ngồi xuống, lão nô nói vài câu thôi."},{"who":"me","text":"Nhìn ông mài roi chậm rãi mà {xung} chợt nghẹn. Ông cũng chẳng muốn việc này, đúng không?"},{"who":"W","text":"Việc không do mình chọn, chỉ làm cho tròn. {Goi} ngồi nghe, hay muốn hỏi chuyện gần đây xảy ra trong phòng này?"}]}},
{"id":"ky:kyc-ma-009","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Cửa sổ Nội vụ phủ đầy nắng, {W} giơ một chiếc trâm lên, nheo mắt xoay mãi dưới ánh sáng."},{"who":"W","text":"Ngọc thật thì ấm tay, ngọc giả thì lạnh. {Goi} thử sờ xem, lão nô không lừa đâu."},{"who":"me","text":"Ông nói như người dỗ trẻ con vậy. {Xung} cầm thử mà tim đập thình thịch, sợ mình đoán sai."},{"who":"W","text":"Đoán sai cũng chẳng mất gì, chỉ mất một nụ cười. {Goi} đoán xem thật hay giả, hay muốn lão nô bán lại chiếc trâm?"}]}},
{"id":"ky:kyc-ma-010","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa mấy luống rau dại trong sân lãnh cung, {W} ngồi nhổ cỏ, những ngón tay gầy guộc quen thuộc từng lá."},{"who":"W","text":"Bà chẳng hỏi {goi} đến làm gì. Cầm nắm lá khô này, sắc uống đỡ đau đầu. Không ai nhớ đến bà, nhưng cỏ cây thì không quên."},{"who":"me","text":"Nắm lá còn ấm hơi tay bà. {Xung} nghe câu cuối mà mắt cay, chẳng biết nên đáp thế nào cho phải."},{"who":"W","text":"Chẳng cần đáp. Có người ngồi đây là đủ. {Goi} muốn học nhận lá, hay chỉ muốn ngồi nói chuyện với bà?"}]}},
{"id":"ky:kyc-ma-011","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Dưới giàn thiên lý trong ngự hoa viên, {W} tách vỏ cây bằng con dao nhỏ, mắt không rời cành non."},{"who":"W","text":"Giống này {xung} ghép đã sáu năm mới ra được một nụ. Nhưng chờ cũng có cái hay của chờ."},{"who":"me","text":"Sáu năm chờ một nụ hoa, chắc lòng bà đã học được kiên nhẫn từ lâu. {Xung} thì nóng ruột quá."},{"who":"W","text":"Nóng ruột là chuyện của tuổi trẻ, rồi cũng qua. {Goi} muốn học cách ghép cành, hay cùng bà tưới chậu hoa kia?"}]}},
{"id":"ky:kyc-ma-012","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ngoài trời lạnh buốt, trong gian thêu Nội vụ phủ, {W} đặt một lò than nhỏ dưới chân mấy tú nữ."},{"who":"W","text":"Tay lạnh thì mũi kim run, mũi kim run thì đường chỉ xấu. {Goi} lại đây, đôi tay đỏ ửng thế kia sao cầm kim được."},{"who":"me","text":"Bà để ý cả đôi tay lạnh của {xung}. Lâu rồi mới có người nhìn kỹ {xung} như thế."},{"who":"W","text":"Nhìn kỹ là nghề của bà. {Goi} ngồi sưởi rồi học một đường chỉ, hay muốn bà chỉ cách giữ ấm tay trước?"}]}},
{"id":"ky:kyc-ma-013","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Mưa phùn kéo đến, {W} vội che tấm lụa bằng chiếc nón lá, bút lông vẫn còn cầm trên tay."},{"who":"W","text":"Cảnh mưa khó vẽ nhất, vì chẳng có đường nét nào. {Goi} đứng yên một lát, để {xung} ghi lại cái ý này."},{"who":"me","text":"Mưa mà cũng muốn ghi lại sao? {Xung} chỉ thấy ướt, {goi} lại thấy cả một bức tranh."},{"who":"W","text":"Ướt mà đẹp thì cũng là tranh. {Goi} đứng yên cho {xung} vẽ, hay muốn {xung} chỉ cách vẽ mưa?"}]}},
{"id":"ky:kyc-ma-014","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm đã khuya, Thái y viện chỉ còn một ngọn đèn nhỏ, {W} ngồi nghiền thuốc trong cối đá, tiếng chày đều đều."},{"who":"W","text":"Ai đêm nay cũng khó ngủ, {goi} không phải người đầu tiên đến đây đâu."},{"who":"me","text":"Mắt {xung} mở trừng trừng đến canh ba, trong lòng chuyện nọ nối chuyện kia. {Xung} nghe tiếng chày mà thấy dễ chịu hơn."},{"who":"W","text":"Tiếng chày cũng là một liều thuốc. {Goi} xin một liều an thần, hay ngồi lại nghe lão phu nói chuyện thuốc?"}]}},
{"id":"ky:kyc-ma-015","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên hồ Thọ Ninh, {W} gấp từng cánh giấy hồng thành hoa sen, đặt vào đĩa nhỏ cho lễ thả đăng."},{"who":"W","text":"Mười cánh phải đều nhau, lệch một cánh là đèn chìm. {Goi} lại đây gấp cho bà vài chiếc."},{"who":"me","text":"Giấy mỏng thế này mà gánh cả lời cầu nguyện. {Xung} sợ tay vụng làm hỏng mất ước nguyện của người khác."},{"who":"W","text":"Người ta thả đèn là để gửi lòng, đèn có đẹp hay không thì lòng vẫn đi. {Goi} gấp cùng bà, hay hỏi ý nghĩa từng cánh?"}]}},
{"id":"ky:kyc-ma-016","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Dưới gốc bạch quả lá vàng rơi, {W} ngồi hai tay đan trong tay áo, chẳng nói chẳng rằng, nhìn từ xa."},{"who":"W","text":"Người trong cung hay nói nhiều để che cái họ muốn giấu. Nói ít để người ta tự lộ ra. {Goi} thử xem."},{"who":"me","text":"Bà nhìn {xung} lâu như thế mà không hỏi gì, {xung} cứ tưởng đã bị nhìn thấu cả rồi."},{"who":"W","text":"Chưa thấu hết đâu. {Goi} muốn bà nói rõ hơn, hay ngồi yên chẳng nói, đợi bà tiếp lời?"}]}},
{"id":"ky:kyc-de-001","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sương còn đọng trên lá liễu, Hoàng thượng đứng một mình bên hồ, môi khẽ ngâm một câu thơ cũ."},{"who":"W","text":"{Goi} đến đúng lúc, trẫm vừa quên mất câu sau. Một câu thơ làm khó trẫm cả buổi sớm."},{"who":"me","text":"Nghe {goi} ngâm, {xung} thấy sương cũng như lắng lại. Câu ấy hình như {xung} từng đọc ở đâu, mà lòng chưa dám chắc."},{"who":"W","text":"Nói đi, trẫm chẳng trách sai. Nếu {goi} chẳng nhớ, trẫm ngâm lại từ đầu cho {goi} nghe cũng được."}]}},
{"id":"ky:kyc-de-002","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Chồng tấu chương trên án cao quá nửa người, ngọn nến sắp tàn, Hoàng thượng day trán, bút đỏ đặt xuống đã lâu."},{"who":"W","text":"Vào đây, trẫm không bảo ai đuổi {goi}. Mắt trẫm mỏi quá rồi, chữ cứ nhòe đi như nước loang."},{"who":"me","text":"Trông {goi} mệt thế này, lòng {xung} chợt chùng xuống. Cả giang sơn đè trên một đôi vai, mà chẳng ai dám bảo người nghỉ."},{"who":"W","text":"Chẳng ai dám, nên trẫm mới bảo {goi} vào. {Goi} định làm gì để trẫm đỡ nhọc?"}]}},
{"id":"ky:kyc-de-003","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đèn trong điện tàn quá nửa, Hoàng thượng đứng trước tấm bản đồ treo tường, ngón tay chạm vào một nơi xa xôi."},{"who":"W","text":"Một đạo quân đi xa ngàn dặm, người ở nhà ai biết họ đã ăn gì chưa."},{"who":"me","text":"Lời ấy nghe nhẹ mà đau. {Xung} đứng sau, chợt thấy bàn tay đặt trên bản đồ ấy cũng lo như tay một người cha."},{"who":"W","text":"Trẫm nói với bản đồ, chẳng nói với {goi}. Nhưng {goi} đã nghe thì thôi, đêm khuya thế này, {goi} định làm gì?"}]}},
{"id":"ky:kyc-de-004","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tuyết mỏng phủ trên cành mai, mấy nụ hồng hé ra như thở khói, Hoàng thượng đứng dưới cành, áo choàng khoác hờ."},{"who":"W","text":"Mai nở một mình giữa mùa lạnh. Khen cũng được, mà thương cũng được."},{"who":"me","text":"Hoa không biết mình bị ngắm, vẫn cứ nở cho trọn mùa. {Xung} thấy nó vừa đẹp vừa đáng thương."},{"who":"W","text":"{Goi} chọn khen hay chọn thương, trẫm đứng đây chờ nghe."}]}},
{"id":"ky:kyc-de-005","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Góc vườn hẻo lánh, một gốc đào đã trụi hết hoa, Hoàng thượng đứng trước nó lâu chẳng nhúc nhích."},{"who":"W","text":"Cây này do một người trồng, giờ người ấy chẳng còn."},{"who":"me","text":"{Xung} bước chậm lại, không dám thở mạnh. Đứng trước nỗi nhớ của người khác, mình chỉ biết lặng đi."},{"who":"W","text":"{Goi} đừng nói với ai là trẫm đứng ở đây. Giữ lời, hay kể cho trẫm nghe một chuyện cũ cho đỡ trống, tùy {goi}."}]}},
{"id":"ky:kyc-de-006","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Vạt áo Hoàng thượng còn vương mùi trầm khi ngài từ điện Thọ Ninh bước ra, thấy người đứng chờ ngoài hiên."},{"who":"W","text":"{Goi} cũng đến vấn an Thái hậu à? Hiên này lạnh, {goi} đứng đây bao lâu rồi?"},{"who":"me","text":"Thưa, {xung} đến sớm, muốn giữ cho tròn lễ. Gặp {goi} ở đây, lòng {xung} vừa mừng vừa e."},{"who":"W","text":"Lần sau trẫm đi cùng {goi} cho tiện. Hay {goi} thích đi một mình cho tự tại hơn?"}]}},
{"id":"ky:kyc-de-007","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Cầu đá lúc nắng lên, đàn cá chép quẫy nước tranh từng mẩu bánh vụn, Hoàng thượng ngồi xổm bên lan can, thoáng ngượng khi ngẩng lên."},{"who":"W","text":"Triều thần mà thấy trẫm thế này thì khỏi nói chuyện nghiêm túc được nữa. {Goi} cười gì đó?"},{"who":"me","text":"{Xung} đâu dám cười, chỉ thấy lần đầu {goi} giống một người thường, vui như trẻ nhỏ."},{"who":"W","text":"Vậy là {goi} đã thấy, không giấu được nữa. Ngồi xuống ném bánh cùng trẫm, hay đứng canh cho khỏi ai bắt gặp?"}]}},
{"id":"ky:kyc-de-008","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Thư phòng thơm mùi giấy cũ, giá sách cao đến tận xà ngang, Hoàng thượng đưa tay chỉ lên những gáy sách xếp san sát."},{"who":"W","text":"{Goi} chọn một cuốn mang về đọc, trẫm cho phép."},{"who":"me","text":"Sách nhiều thế này, {xung} chẳng biết nên nhìn gáy nào trước. {Goi} ban cho, mà chọn sai thì sợ phụ lòng người."},{"who":"W","text":"Chọn không có sai, chỉ có để lộ. Trẫm muốn xem tay {goi} sẽ dừng ở đâu."}]}},
{"id":"ky:kyc-de-009","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trên án chỉ có một bình rượu nhỏ và hai chiếc chén, một chiếc chưa ai đụng đến; Hoàng thượng không quay đầu khi nghe tiếng bước."},{"who":"W","text":"Trẫm không bảo {goi} vào, nhưng cũng không bảo {goi} lui. Ngồi đi. Đêm dài thế này, uống một mình thì rượu cũng đắng."},{"who":"me","text":"{Xung} nhìn chiếc chén còn trống mà lòng nghẹn. {Goi} chuẩn bị cho ai, hay chỉ để đó cho đỡ cô quạnh?"},{"who":"W","text":"Đừng hỏi. Ngồi xuống uống cùng trẫm, hay ép trẫm đổi sang chén trà, tùy {goi}."}]}},
{"id":"ky:kyc-de-010","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Gió thu thổi mạnh qua khóm cúc, Hoàng thượng đưa tay che miệng ho khan mấy tiếng rồi xua tay khi thấy người sắp tiến lại."},{"who":"W","text":"Không sao, chuyện nhỏ. Đừng làm ầm lên cho cung nhân phải chạy."},{"who":"me","text":"Tiếng ho ấy nghe không nhỏ chút nào. {Xung} sợ {goi} cứ gượng mãi, rồi gió thu sẽ thắng."},{"who":"W","text":"{Goi} lo thì cứ lo, nhưng đừng làm trẫm mất mặt trước cả vườn hoa."}]}},
{"id":"ky:kyc-th-001","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Cửa sổ Thọ Ninh nắng nghiêng, một cánh bướm đậu trên chậu lan, chuỗi hạt trong tay Thái hậu lần chậm rãi."},{"who":"W","text":"Ngày bé, {xung} cũng đuổi bướm như thế. Chạy mãi không kịp, chỉ được cái vạt áo rách."},{"who":"me","text":"Nghe Thái hậu kể, {xung} thấy người bỗng trẻ lại, chẳng còn là bậc chí tôn giữa điện."},{"who":"W","text":"Rồi còn {goi} thì sao? Hồi bé {goi} có đuổi bướm không, hay chỉ ngồi nhìn?"}]}},
{"id":"ky:kyc-th-002","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trên bàn trà của Thái hậu bày ba loại lá khác nhau, khói hương nhẹ lan trong điện; người nhấp thử một chén, rồi đặt xuống thật khẽ."},{"who":"W","text":"Ba loại trà này, loại nào là lá thượng hạng? {Goi} đoán xem."},{"who":"me","text":"Mùi hương nào cũng dịu, {xung} sợ đoán sai làm người mỉm cười buồn. Nhưng trà ngon phải thuận theo hương, chắc đoán bằng mũi cũng không sai."},{"who":"W","text":"Vậy thì cứ thử đi. Còn nếu muốn, {xung} chỉ cho cách đoán cũng được."}]}},
{"id":"ky:kyc-th-003","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bức họa cũ đã ố vàng, ngón tay Thái hậu vuốt nhẹ lên nét mặt người trong tranh."},{"who":"W","text":"Tranh còn đây, người đã đi xa. Cái gì ở lại thì thường là cái không đáng giữ."},{"who":"me","text":"{Xung} nghe mà không dám đáp. Lời ấy nói với tranh hay nói với {xung} cũng đều nặng như nhau."},{"who":"W","text":"{Goi} cứ đứng đó. {Xung} chỉ cần một người nghe, chẳng cần một người khuyên."}]}},
{"id":"ky:kyc-th-004","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đĩa bánh mới của Ngự thiện phòng còn bốc khói, phủ lớp đường mịn như tuyết; Thái hậu chưa vội ăn mà ra hiệu cho người lại gần."},{"who":"W","text":"{Xung} ăn thử món lạ thì nhờ {goi} ăn thử trước. Nếu {goi} vẫn khỏe mạnh thì {xung} mới an tâm."},{"who":"me","text":"Người cười mà ý ấy thật sâu, {xung} biết đây vừa là trêu vừa là thử. Một miếng bánh mà cũng nặng cả tấm lòng."},{"who":"W","text":"Ăn đi rồi nói thật cho {xung} nghe. Hay {goi} định khen cho {xung} vui?"}]}},
{"id":"ky:kyc-th-005","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Chén trà đặt xuống bàn thật khẽ, tiếng sứ chạm gỗ vang lên trong điện vắng."},{"who":"W","text":"Cung này ai cũng có gia tộc đứng sau, {goi} cũng vậy. Lấy gia tộc làm chỗ dựa, đừng để gia tộc làm gánh nặng."},{"who":"me","text":"Lời Thái hậu đều đều mà sắc như dao. {Xung} nghe ra cả điều dặn lẫn điều cảnh báo."},{"who":"W","text":"{Goi} đã hiểu chưa? Hay cần {xung} nói rõ hơn?"}]}},
{"id":"ky:kyc-th-006","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Mắt Thái hậu mờ đi nhiều, trang kinh đặt trước mặt đã gần chạm mũi; người đẩy kinh về phía người trước mặt."},{"who":"W","text":"Đọc giùm {xung} một đoạn. Giọng {goi} nghe dễ chịu."},{"who":"me","text":"Nghe người nói vậy, lòng {xung} ấm lên. Không ngờ một giọng đọc cũng có thể làm người nhẹ bớt nỗi buồn."},{"who":"W","text":"Đọc to từng chữ cho {xung} nghe, hay chép lại chữ lớn cho {xung} tự xem, tùy {goi}."}]}},
{"id":"ky:kyc-th-007","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tiết Thanh minh, phía sau điện Thọ Ninh, hương khói nhẹ như sương trên một mâm cúng nhỏ; {W} khẽ đốt thêm nén hương."},{"who":"W","text":"Những cung nữ mất đi chẳng ai nhớ tên, bà nhớ giùm vài người."},{"who":"me","text":"Nhìn mâm cúng giản dị mà {xung} xúc động. Giữa chốn cung son, vẫn còn một người nhớ những cái tên vô danh."},{"who":"W","text":"{Goi} có muốn khấn một câu không? Hay đứng sau bà cúi đầu im lặng cũng được."}]}},
{"id":"ky:kyc-th-008","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tết Đoan ngọ, mùi lá ngải xông lên nồng nồng, {W} bó từng nắm cùng xương bồ để treo lên cửa mỗi gian cung, rồi đưa cho người một bó nhỏ."},{"who":"W","text":"Treo ở cửa mình, trừ khí độc mùa nóng. Chẳng ai dặn {goi} điều này đâu, bà dặn thôi."},{"who":"me","text":"Chẳng ai dặn mà bà vẫn nhớ đến {xung}. Một bó lá nhỏ mà nặng nghĩa thế này."},{"who":"W","text":"Nhận rồi tự treo lên, hay muốn bà chỉ cách bó cho đẹp, thì lại đây."}]}},
{"id":"ky:kyc-th-009","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tết Trùng cửu, hàng cúc vàng nở rộ khắp ngự hoa viên, Hoàng thượng đang chỉ cho từng chậu, thấy người liền vẫy tay."},{"who":"W","text":"Chọn giùm trẫm một chậu cúc đưa lên Thọ Ninh dâng Thái hậu. Chậu nào đẹp nhất?"},{"who":"me","text":"Chậu nào cũng rực rỡ, mà dâng Thái hậu thì phải chọn đúng ý người. {Xung} đứng giữa vườn, lòng cứ phân vân."},{"who":"W","text":"Vàng rực hay trắng thanh, {goi} nhìn bằng mắt hay bằng lòng, trẫm đều muốn nghe."}]}},
{"id":"ky:kyc-th-010","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tiết Đông chí, bếp phụ Thọ Ninh bốc khói nghi ngút, {W} vo từng viên bột nếp trắng ngần rồi bưng ra một bát nóng."},{"who":"W","text":"Ngày ngắn nhất rồi, sau hôm nay ngày sẽ dài ra. Ăn đi cho ấm bụng."},{"who":"me","text":"Bát chè nóng hổi làm tay {xung} bớt lạnh. Nghe bà nói, {xung} thấy trong đêm dài cũng có một chút hy vọng."},{"who":"W","text":"Ở lại trò chuyện với bà cho đỡ vắng, hay muốn học vo bột cho tròn, bà dạy."}]}},
{"id":"ky:kyc-th-011","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm Giao thừa, pháo nổ rền xa xa, Hoàng thượng đưa cho người một phong bao đỏ rực trong xấp còn dày."},{"who":"W","text":"Năm mới, {goi} ước điều gì thì cứ nói thật. Trẫm không cười đâu."},{"who":"me","text":"Phong bao còn nóng hơi tay {goi}. {Xung} đứng giữa tiếng pháo mà thấy lòng mình bé nhỏ, lại có hai điều trong dạ."},{"who":"W","text":"Hai điều thì nói một điều trước. Ước cho trẫm, hay ước cho nhà {goi}?"}]}},
{"id":"ky:kyc-th-012","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Mồng một Tết, {W} mặc áo mới, đứng ở hành lang dúi cho mỗi cung nữ một chiếc bánh nhỏ gói lá; đến phần người, bà dừng lâu hơn."},{"who":"W","text":"Năm mới nói một lời tốt đẹp, cả năm theo lời đó mà đi."},{"who":"me","text":"Chiếc bánh còn ấm trong lòng bàn tay. {Xung} nghẹn lời, chẳng biết lời nào mới xứng với tấm lòng bà."},{"who":"W","text":"{Goi} chúc bà trước, hay muốn bà chúc cho {goi} một lời trước?"}]}},
{"id":"ky:kyc-th-013","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Hội Phượng náo nhiệt, tiếng vó ngựa vang xa, {W} đứng ven sân tập, mắt sáng như người trẻ."},{"who":"W","text":"Hồi trẻ lão nô cũng cưỡi ngựa bắn cung, nay chỉ còn đứng nhìn. {Goi} biết xem cung không?"},{"who":"me","text":"Nhìn ông dõi theo từng mũi tên, {xung} biết trong lòng ông vẫn còn tiếng vó ngựa ngày xưa."},{"who":"W","text":"Cái gì mất rồi mới thành chuyện kể. {Goi} muốn nghe chuyện thuở trẻ của lão nô, hay hỏi cách xem tay cung thủ?"}]}},
{"id":"ky:kyc-th-014","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm Thất tịch, bên hồ lung linh những chiếc đèn nhỏ trôi đi, {W} ngồi thả từng chiếc, mắt xa xăm."},{"who":"W","text":"Trước kia bà cũng thả đèn cầu duyên. {Goi} đứng đó làm gì, ngồi xuống đây."},{"who":"me","text":"Ánh đèn in trên gương mặt bà, nửa vui nửa buồn. {Xung} chợt tò mò duyên của bà ngày xưa ra sao."},{"who":"W","text":"Hỏi thì bà kể. Hoặc ngồi xuống thả đèn cùng bà, chẳng cần nói gì cũng được."}]}},
{"id":"ky:kyc-vat-001","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sương sớm còn đọng trên cỏ, dưới bụi trúc, một món đồ nằm lẫn trong lá khô, dây tua đã ướt đẫm; từ xa vọng lại tiếng người gọi nhau."},{"who":"me","text":"Vật này {xung} từng thấy {W} đeo bên người. Hóa ra nó rơi tận đây, lặng lẽ như một lời chưa ai nghe."},{"who":"W","text":"Tìm kỹ lại mấy lối quanh đây đi. Cả cung đã biết {xung} mất đồ, {xung} chẳng thể mất mặt thêm nữa."},{"who":"me","text":"Giọng nàng gấp mà run, như người đang sợ hơn cả đang tiếc. Cầm vật trong tay, {xung} thấy nó nặng hơn hình dáng của nó."}]}},
{"id":"ky:kyc-vat-002","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong sân lãnh cung cỏ mọc quá gối, gió lùa qua những mái ngói rêu, chân người vấp phải một vật cứng."},{"who":"me","text":"Gạt lá ra, là một món đồ phủ đầy bụi và mạng nhện. {Xung} nhận ra ngay vật {W} đã tìm mãi mà chẳng thấy."},{"who":"W","text":"Ai ở trong ấy? Nơi này bỏ hoang bao năm, đừng nói là {goi} cũng đi tìm thứ đã mất. {Xung} tìm mãi vẫn chưa thấy."},{"who":"me","text":"Nàng tìm cả những chốn người đời lảng tránh, vậy là tìm bằng cả tấm lòng. {Xung} đứng giữa hai ngả, tay còn cầm món đồ lạnh buốt."}]}},
{"id":"ky:kyc-vat-003","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Mưa vừa tạnh, bên mương nước có thứ gì lóe sáng giữa bùn, nước còn rỉ xuống từng giọt; đâu đó sau hàng cột có tiếng {W} nói."},{"who":"me","text":"Vớt lên, là món đồ bùn còn vương nơi viền. {W} từng nhắc đến nó với giọng rất lo, bởi người ta đồn nó mất là điềm chẳng lành."},{"who":"W","text":"Điềm gì thì điềm, {xung} chỉ cần nó về. Đừng để thiên hạ đồn thêm nữa."},{"who":"me","text":"Lời đồn đi nhanh hơn bước chân. Món đồ nằm trong tay {xung}, và {xung} biết mình chưa nói với ai."}]}},
{"id":"ky:kyc-vat-004","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Hơi thở dồn dập, cung nữ {W} chạy về từ sau bình phong, hai tay nâng một món đồ, mép áo còn ướt sương."},{"who":"W","text":"{Goi}, {xung} tìm thấy rồi! Nhưng viền vật này dính dấu bùn lạ, như có kẻ đã cầm qua rồi vội bỏ lại, {goi} xem này."},{"who":"me","text":"Ngươi chạy một mạch như thế, đừng lo, ta không trách. Nhưng dấu bùn ấy, ngươi thấy ở chỗ nào?"},{"who":"W","text":"Ngay sau bình phong, nơi chẳng ai hay qua lại, {goi}. {Xung} sợ nói ra lại thành chuyện, nhưng không nói thì lòng không yên."}]}},
{"id":"ky:kyc-vat-005","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên nắng xiên, tiểu thái giám bỗng kêu lên, chỉ vào xà ngang có vật gì sáng lấp lánh rồi trèo lên lấy xuống."},{"who":"W","text":"Hóa ra con quạ nào đã tha về làm ổ! Cả cái ổ lót toàn đồ sáng, không thiếu một thứ!"},{"who":"me","text":"Cả đám cười ồ lên, mà {xung} nhận ra ngay vật ấy: món {W} báo mất mấy hôm nay. Quạ lại là kẻ trộm khéo nhất cung."},{"who":"W","text":"Con quạ còn vô tội hơn nhiều người. Nó chỉ thích cái sáng, đâu biết đồ ấy đã làm cả cung xáo động."}]}},
{"id":"ky:kyc-vat-006","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong kho sau Nội vụ phủ, bụi lơ lửng trong tia nắng hẹp, {W} mở một chiếc hộp gỗ cũ bằng đôi tay quen việc."},{"who":"W","text":"Đây là di vật của một người đã khuất, chưa ai đến nhận. Tấm vải gói còn nguyên nếp gấp của bàn tay chủ cũ, {goi} xem."},{"who":"me","text":"Nếp gấp ấy như còn hơi ấm. {Xung} đứng lặng, chợt thấy một cuộc đời gói gọn trong chiếc hộp nhỏ."},{"who":"W","text":"Chủ cũ đi rồi, mà vật vẫn ở lại. {Goi} muốn chuộc về giữ làm kỷ niệm, hay dâng Thái hậu thay người khuất?"}]}},
{"id":"ky:kyc-vat-007","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Gió lùa qua cửa kho Nội vụ phủ, sổ chi mở trên bàn, mực còn ướt, {W} hạ giọng như sợ vách có tai."},{"who":"W","text":"Món này của người đã khuất, sắp bị bán ra ngoài cung để lấp sổ chi của kho. Nếu {goi} không muốn nó lọt vào tay người lạ thì phải nói ngay hôm nay."},{"who":"me","text":"Bán đồ của người chết để lấp một con số trên giấy sao? {Xung} nghe mà lạnh người."},{"who":"W","text":"Nô tài chỉ giữ kho, không dám cãi sổ. Chuộc ngay, hay nhờ Thái hậu giữ hộ, {goi} định liệu."}]}},
{"id":"ky:kyc-vat-008","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Chiếc hộp gỗ trong kho vừa mở, mùi trầm cũ thoảng lên, {W} khẽ khàng đẩy nó về phía người đến."},{"who":"W","text":"Người chủ cũ của món này khi còn sống từng khen {goi} ân cần với kẻ dưới. Giờ người đã đi, món này chưa ai thừa nhận."},{"who":"me","text":"Chỉ một lời khen thoảng qua mà người ấy còn nhớ. {Xung} chẳng ngờ mình từng được ai ghi nhớ lặng lẽ như vậy."},{"who":"W","text":"Có những ơn nhỏ nặng hơn lời tạ. {Goi} nhận lấy thắp nén hương, hay xin dâng Thái hậu làm phúc?"}]}},
{"id":"ky:kyc-vat-009","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sáng sớm, quầy hàng Nội vụ phủ còn phủ khăn, {W} khẽ gọi người lại gần, tay giữ chiếc hộp nhỏ."},{"who":"W","text":"Món quý tuần này chưa bày lên quầy. Nô tài để riêng cho {goi} ngắm trước, vì người ngoài chưa ai biết đến."},{"who":"me","text":"Ngươi giữ riêng cho ta sao? Món đồ quý đến thế mà chưa ai hay, ta vừa thấy mừng vừa thấy ngại."},{"who":"W","text":"Đồ quý phải gặp đúng người. {Goi} nhận về dùng cho mình, hay tiến lên Thái hậu trước, nô tài đều chờ lệnh."}]}},
{"id":"ky:kyc-vat-010","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Cánh cửa kho khép hờ, {W} đưa mắt nhìn quanh rồi mới mở hộp, mắt cứ liếc ra phía cửa."},{"who":"W","text":"Hôm qua đã có người hỏi mua, nhưng nô tài chưa gật đầu, chỉ đợi {goi} tới. Giá hôm nay là giá của hôm nay thôi."},{"who":"me","text":"{Goi} giữ lại cho {xung}, mà người kia hẳn không vui. {Xung} nghe ngoài hiên có tiếng chân đi qua."},{"who":"W","text":"Chính là sợ họ quay lại đấy. {Goi} mua ngay kẻo bị người khác lấy, hay mua rồi dâng lên Đức Thọ cung?"}]}},
{"id":"ky:kyc-vat-011","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Quầy kho bụi mờ, {W} vừa lau một món đồ vừa lầm bầm, giọng ngán ngẩm của người giữ hàng lâu ngày không bán nổi."},{"who":"W","text":"Món này đắt như bụng quan lớn, bày ra mấy hôm chẳng ai hỏi. Ôi {goi}, người vào đúng lúc quá, nô tài sắp héo cùng nó rồi."},{"who":"me","text":"Nhìn ông mừng như gặp cứu tinh, {xung} suýt bật cười. Món đồ ấy chẳng có lỗi gì, chỉ là quá đắt."},{"who":"W","text":"Đắt thì đắt, mà thứ tốt vẫn là thứ tốt. {Goi} mua giùm cho nô tài đỡ lo, hay mua rồi tiến Thái hậu lấy lòng bà?"}]}},
{"id":"ky:kyc-vat-012","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Hành lang buổi chiều lặng gió, một mảnh giấy gấp rơi khỏi tay áo thị nữ của {W}; xa xa có tiếng nàng giục người hầu đi nhanh."},{"who":"me","text":"{Xung} nhặt lên, thấy nét chữ nói về một việc nàng đang sắp đặt, đã bày đến nửa đường. Những dòng ấy chẳng phải lời của người vô sự."},{"who":"W","text":"Đi nhanh lên, chuyện nhỏ như thế đừng để ai để ý."},{"who":"me","text":"Nhỏ mà chứa cả toan tính. Tờ giấy trong tay {xung} nhẹ như lông, mà giữ hay trả đều là một quyết định."}]}},
{"id":"ky:kyc-vat-013","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm xuống, trăng lẩn sau mây, dưới gốc mai thái giám của {W} cúi xuống đào đất, chôn một gói nhỏ rồi vội vã bỏ đi."},{"who":"me","text":"{Xung} đứng im sau cột, chỉ thấy hắn chôn xuống mà không ngoảnh lại, như sợ chính gốc cây thấy."},{"who":"W","text":"Xong chưa? Mau lại đây. Đêm khuya, đừng để ai bắt gặp."},{"who":"me","text":"Gói ấy nằm đó, chờ đến khi có người bị liên lụy. Tim {xung} đập như trống, tay áo siết chặt."}]}},
{"id":"ky:kyc-vat-014","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa hành lang buổi trưa, {W} nhét một chiếc hộp gấm vào tay người, cười gượng, mắt không dám nhìn thẳng."},{"who":"W","text":"Giữ hộ {xung} chiếc hộp này, là bánh ngọt thôi, {xung} mua ngoài chợ. Lát nữa {xung} quay lại lấy."},{"who":"me","text":"Nắp hộp hé ra, {xung} thấy toàn thứ chẳng giống bánh: giấy, chỉ đỏ, cả một lọn tóc. Bánh gì mà kỳ lạ thế?"},{"who":"W","text":"Là đồ chơi cho trẻ con thôi, {goi} đừng mở thêm. Cứ giữ giùm {xung}, đừng hỏi nữa."}]}},
{"id":"ky:kyc-sv-001","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên bậc thềm trơn ẩm, {W} ôm chồng áo giặt cao quá đầu, chân vấp, cả chồng áo chực rơi xuống nước bẩn."},{"who":"me","text":"{Xung} kịp đưa tay đỡ lấy chồng áo, nặng hơn tưởng. Nàng này gầy đến mức chồng áo che khuất cả người."},{"who":"W","text":"{Goi} tha tội, nô tỳ vụng về quá, suýt làm hỏng việc. Nô tỳ... nô tỳ tạ ơn {goi}."},{"who":"me","text":"Tay nàng còn run, quỳ giữa bậc thềm ướt. Đứng dậy đi, {goi} cứ yên tâm, {xung} chỉ muốn hỏi vài chuyện."}]}},
{"id":"ky:kyc-sv-002","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trời mới hửng, phòng trà Ngự còn nghi ngút hơi nước, thái giám {W} nhìn quanh rồi lén đưa ra một chén trà nóng."},{"who":"W","text":"Trà thừa của Hoàng thượng đấy {goi}. Để lâu sẽ đổ đi, chẳng ai hay. Uống đi cho ấm bụng buổi sớm."},{"who":"me","text":"Chén trà nóng ấm cả bàn tay. {Xung} biết trà ấy chẳng thừa, hắn cố tình giữ lại cho {xung}."},{"who":"W","text":"Ơn nghĩa nhỏ thôi, {goi} đừng bận tâm. Nô tài chỉ thấy {goi} đi từ sớm, lòng thương."}]}},
{"id":"ky:kyc-sv-003","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sau cây cột sơn đỏ, {W} ngồi thu mình, tay nắm chặt góc áo, bức thư nhà nhàu nát nằm trên đầu gối."},{"who":"W","text":"Thư nhà báo mẹ nô tỳ đau nặng. Nhưng nô tỳ không dám xin phép chủ nhân nhà mình, sợ bị quở."},{"who":"me","text":"Nghe mà nghẹn. Người con xa mẹ giữa cung cấm, chỉ biết giấu nước mắt sau cây cột."},{"who":"W","text":"Nô tỳ xin lỗi đã để {goi} thấy. Xin {goi} đừng nói ai, nô tỳ sẽ chịu."}]}},
{"id":"ky:kyc-sv-004","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ở sân sau, một chiếc diều giấy mắc vào nhành cây cao, dây diều đung đưa trong gió; tiểu thái giám {W} đứng dưới, mặt tái xanh."},{"who":"W","text":"Chết rồi, chết rồi. Nếu quản sự thấy nô tài chơi diều trong giờ làm việc thì phen này bị phạt nặng."},{"who":"me","text":"Nhìn mặt hắn tái như tàu lá, {xung} suýt bật cười. Cái tuổi chỉ cần một chiếc diều là vui cả ngày."},{"who":"W","text":"Dây diều vướng cao quá, nô tài với không tới. {Goi} có thể giúp hay chỉ đi qua, nô tài đều không dám trách."}]}},
{"id":"ky:kyc-sv-005","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên hàng cột trong buổi chiều, {W} chặn ngay lối đi, cúi đầu thật thấp, giọng khẽ như hơi thở."},{"who":"W","text":"Gần đây chủ nhân nhà nô tỳ hay hỏi dò chuyện của {goi}. Nô tỳ thấy lạ, mà không dám nói với ai."},{"who":"me","text":"Có người đang âm thầm nhìn {xung} như nhìn một ván cờ. Hơi lạnh chạy dọc sống lưng."},{"who":"W","text":"Nô tỳ nói ra là để {goi} biết mà đề phòng. {Goi} muốn nghe kỹ từng chuyện, hay chỉ muốn nô tỳ giữ kín?"}]}},
{"id":"ky:kyc-sv-006","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa lối hoa, hoàng tử nhỏ {W} cầm cành hoa, ngước nhìn người rất lâu như đang so sánh điều gì."},{"who":"W","text":"Dì đẹp hơn mẫu phi của con."},{"who":"me","text":"Nhũ mẫu bên cạnh tái mặt, vội bịt miệng bé lại. {Xung} cúi xuống, nửa muốn cười, nửa không dám."},{"who":"W","text":"Con nói thật mà! Bà nhũ mẫu không cho con nói, nhưng con thấy là thấy."}]}},
{"id":"ky:kyc-sv-007","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong thư phòng nhỏ, hoàng tử {W} giơ tấm bảng gỗ ra, ngón tay lấm mực đen, đọc sai chữ thứ ba rồi quay sang cầu cứu."},{"who":"W","text":"Chữ này đọc thế nào ạ? Con đọc mãi mà thầy bảo sai, con không biết sai ở đâu."},{"who":"me","text":"Nhìn ngón tay bé nhem mực, lòng {xung} dịu lại. Ai cũng từng nhớ chữ chậm như thế, chỉ là quên mất rồi."},{"who":"W","text":"Dì chỉ cho con từng nét đi, hay kể chuyện cổ, con dễ nhớ hơn!"}]}},
{"id":"ky:kyc-sv-008","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa sân gạch, hoàng tự {W} ngã sấp, đầu gối rách chảy máu, nhũ mẫu còn đang chạy tới từ phía xa."},{"who":"W","text":"Bé nghiến răng, không khóc. Con không đau, con không đau mà."},{"who":"me","text":"Đôi mắt bé ráo hoảnh nhìn {xung}, mà môi cắn đến trắng bệch. Không khóc, không phải vì không đau."},{"who":"W","text":"Con sợ nhũ mẫu mắng, con sợ cả mẫu phi biết. Dì đừng nói nhé."}]}},
{"id":"ky:kyc-sv-009","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Gió hồ thổi lộng lên sân, nhũ mẫu đứng phía sau vừa muốn ngăn vừa không dám mở lời, bé {W} chạy tới ôm chân người."},{"who":"W","text":"Dì ơi, cõng con đi xem cá ngoài hồ! Cá to lắm, con thấy hôm qua mà."},{"who":"me","text":"Chiếc ôm quấn lấy chân {xung} chặt như thể sợ mất. {Xung} nhìn sang nhũ mẫu, bà chỉ biết cười gượng."},{"who":"W","text":"Cõng con đi một vòng thôi, hay dắt tay cũng được. Con ngoan, con không chạy nữa đâu!"}]}},
{"id":"ky:kyc-sv-010","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa sân chơi, hai đứa trẻ tranh một con châu chấu tre, khóc đến đỏ mặt, các nhũ mẫu đứng quanh mà chẳng ai dám phân xử."},{"who":"W","text":"Của con! Con thấy trước mà! Nó giật của con, con không cho!"},{"who":"me","text":"Tiếng khóc chồng lên nhau như hai cái chuông vỡ. Các nhũ mẫu nhìn {xung} bằng ánh mắt cầu cứu."},{"who":"W","text":"Dì phân xử đi, dì nói nó phải trả lại cho con!"}]}},
{"id":"ky:kyc-sv-011","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Dưới hiên mưa nhỏ giọt, bé {W} ôm con búp bê vải rách một bên tai, ngồi thu mình như một viên sỏi."},{"who":"W","text":"Mẫu phi ốm rồi. Họ không cho con vào thăm, bảo con ồn ào, làm phiền người."},{"who":"me","text":"{Xung} ngồi xuống, ngang tầm mắt bé. Búp bê rách tai mà bé vẫn ôm chặt như ôm cả nỗi nhớ."},{"who":"W","text":"Con chỉ muốn nhìn mẫu phi một lát thôi. Dì ở đây với con, hay nhờ nhũ mẫu dẫn con vào?"}]}},
{"id":"ky:kyc-sv-012","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tuyết phủ trắng vườn ngự, bé {W} cúi xuống nặn người tuyết, nhưng cái đầu cứ lăn khỏi thân, mũi đỏ ửng vì lạnh."},{"who":"W","text":"Nó cứ rơi hoài! Con ấn thật chặt rồi mà nó vẫn lăn. Dì xem, đầu nó ngốc quá!"},{"who":"me","text":"{Xung} bật cười, hơi thở thành khói trắng. Cái đầu tròn ấy cứ lăn như muốn bỏ trốn khỏi thân người tuyết."},{"who":"W","text":"Dì giúp con nặn đầu nhé, hay mang cho con lò sưởi nhỏ, tay con tê hết rồi."}]}},
{"id":"ky:kyc-sv-013","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đèn đã cạn nửa dầu, cung nữ {W} nhà ngươi vẫn cúi xuống chiếc áo đang khâu, đầu ngón tay chi chít vết kim châm."},{"who":"W","text":"Nô tỳ khâu nốt rồi mới nghỉ, {goi}. Áo mai cần mặc, nô tỳ không muốn lỡ việc."},{"who":"me","text":"Nàng không kêu một tiếng, chỉ cúi mặt thêm thấp. Nhìn đầu ngón tay ấy, ta thấy nghèn nghẹn."},{"who":"W","text":"Nô tỳ không dám làm {goi} lo. Xin {goi} cứ để nô tỳ làm."}]}},
{"id":"ky:kyc-sv-014","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa đêm, ngọn đèn bên án còn leo lét, cung nữ {W} nhà ngươi nhẹ nhàng bưng vào một chén canh sâm bốc khói."},{"who":"W","text":"Nô tỳ thấy đèn {goi} còn sáng, sợ {goi} quên ăn. Chẳng ai dặn, nô tỳ tự đun."},{"who":"me","text":"Chén canh nóng hổi, hơi sâm thoang thoảng. Lâu rồi mới có người nhớ đến cái bụng của ta, giữa đêm khuya thế này."},{"who":"W","text":"{Goi} uống đi cho ấm, nô tỳ đứng chờ. Việc gì thì đợi sáng mai hãy tính."}]}},
{"id":"ky:kyc-sv-015","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm xuống, gió luồn qua khe cửa, cung nữ {W} nhà ngươi bước vào thật khẽ, giọng hạ xuống như sợ vách có tai."},{"who":"W","text":"{Goi}, có người lạ ngồi lâu dưới cửa sổ. Nô tỳ đã thấy hai lần trong mấy hôm nay, mà không dám tự ý đuổi."},{"who":"me","text":"Hai lần trong mấy hôm, không phải ngẫu nhiên. Ai lại ngồi dưới cửa sổ của ta, để làm gì?"},{"who":"W","text":"Nô tỳ sợ làm to chuyện. {Goi} muốn hỏi kỹ từng việc nô tỳ thấy, hay cho nô tỳ đứng canh đêm nay?"}]}},
{"id":"ky:kyc-sv-016","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Nắng chiều xiên qua song cửa, {W} đang lau cửa sổ cung chủ nàng, thấy người đi qua liền cúi chào rất thấp."},{"who":"W","text":"{Goi} vạn phúc. Nô tỳ... nô tỳ vẫn nhớ hôm trước {goi} đã không bỏ mặc nô tỳ lúc bị quở."},{"who":"me","text":"{Xung} nhớ rõ nàng bị oan mà không dám cãi, đứng im như tượng. Một việc nhỏ ngày ấy, nàng vẫn giữ trong lòng."},{"who":"W","text":"Nô tỳ không có gì báo đáp, chỉ có mắt có tai. {Goi} có điều gì cần dặn, nô tỳ xin nghe."}]}},
{"id":"ky:kyc-sv-017","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa hành lang tối, ánh đèn lồng cuối dãy hiên đã tắt từ lúc nào, bóng người chặn ngang lối đi."},{"who":"W","text":"{Goi} đừng đi lối này."},{"who":"me","text":"Hắn không giải thích, chỉ liếc về phía cuối dãy hiên tối đen. {Xung} nghe gió luồn qua khe cửa, lạnh dọc sống lưng."},{"who":"W","text":"Nô tài không dám nói nhiều. {Goi} muốn hỏi, nô tài nói điều đã thấy, hoặc nghe lời nô tài mà đổi lối."}]}},
{"id":"ky:kyc-sv-018","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ở góc sân vắng, {W} đứng thì thầm tập câu chúc thọ, đọc mãi vẫn nhầm một chữ thành chữ khác nghe rất buồn cười."},{"who":"W","text":"Xin {goi} đừng cười. Nô tỳ tập cả buổi mà cứ nhầm chữ này, mai lại phải dâng lời chúc Thái hậu."},{"who":"me","text":"Mặt nàng đỏ như quả hồng chín. {Xung} nhịn cười, thấy nàng đáng thương và đáng yêu cùng một lúc."},{"who":"W","text":"{Goi} chỉ giúp nô tỳ ngắt câu cho đúng, hay dạy cách thưa lễ trước Thái hậu, nô tỳ đều xin ghi nhớ."}]}},
{"id":"ky:kyc-sv-019","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ở cổng cũ, mái ngói rêu phủ, {W} đã gác từ thuở tiên đế còn tại thế, tóc bạc, lưng còng, chỉ tay về góc tường nắng đọng."},{"who":"W","text":"Chỗ này nắng lên đầu tiên, mùa {S} nào cũng ấm nhất. Lão nô ngồi đây đã mấy chục năm rồi."},{"who":"me","text":"Nhìn góc tường ấy, {xung} thấy cả một đời người đọng lại trong một vệt nắng."},{"who":"W","text":"Cung này đổi chủ hết lượt này đến lượt khác, chỉ có nắng ở góc tường này là vẫn thế. {Goi} đứng đây một lát cho ấm."}]}},
{"id":"ky:kyc-sv-020","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Ngoài hiên gió lạnh luồn từng đợt, cung nữ mới {W} quỳ suốt buổi, môi tím tái, vai run bần bật mà không dám đứng dậy."},{"who":"W","text":"Nô tỳ... nô tỳ biết lỗi rồi, xin {goi} đừng để ý. Chủ nhân nhà nô tỳ phạt thì nô tỳ chịu."},{"who":"me","text":"Nghe giọng nàng run mà {xung} đứng khựng lại. Gió lạnh thế này mà quỳ suốt buổi, ai nhìn cũng không đành."},{"who":"W","text":"{Goi} đừng vì nô tỳ mà chuốc phiền. Nô tỳ quen rồi, quen rồi."}]}},
{"id":"ky:kyc-sv-021","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong kho Nội vụ phủ, những tấm vải thêu chồng như núi, {W} đếm đi đếm lại, trán đẫm mồ hôi dù trời mát."},{"who":"W","text":"Lại sai nữa rồi. Hôm nay là hạn nộp sổ mùa {S}, nếu số không khớp nô tỳ sẽ bị phạt."},{"who":"me","text":"Nhìn những ngón tay nàng run rẩy trên từng tấm vải, {xung} thấy thương. Con số không có lỗi, chỉ có người sợ hãi."},{"who":"W","text":"{Goi} ngồi tính giúp nô tỳ cho xong, hay chỉ nô tỳ mẹo đếm nhanh, nô tỳ đều biết ơn."}]}},
{"id":"ky:kyc-sv-022","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm Trung thu, ánh nến chập chờn trong chiếc đèn lồng cá chép, bé {W} đứng giữa lối vắng, môi mím chặt."},{"who":"W","text":"Con tìm nhũ mẫu mà không thấy. Con không khóc đâu, con lớn rồi."},{"who":"me","text":"Chiếc đèn lồng cá chép lắc lư trong tay bé, ánh nến run theo. {Xung} thấy cổ họng mình nghẹn."},{"who":"W","text":"Dì dắt con đi tìm nhũ mẫu nhé? Hay con ngồi đây chờ, nhũ mẫu sẽ tìm tới?"}]}},
{"id":"ky:kyc-sv-023","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm Nguyên tiêu, đèn hoa đăng nối nhau như sao sa, bé {W} kéo tay áo người, nhũ mẫu đứng sau che miệng cười."},{"who":"W","text":"Dì ơi, con đố dì nhé! Cái gì bay không có cánh, khóc không có mắt? Là mây, mây đó! Con trả lời luôn rồi!"},{"who":"me","text":"Bé tự đố tự đáp, mặt hí hửng như đã thắng cả thiên hạ. {Xung} bật cười, hứng thú không kém."},{"who":"W","text":"Dì đoán sai đi cho con thắng, hay dì đố lại con một câu khó hơn!"}]}},
{"id":"j68:gossipTea","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi trà còn bốc trên chén sứ, {A} ngồi sát bên hiên, giọng nhỏ đến mức như sợ cả gió cũng nghe lỏm."},{"who":"A","text":"Chuyện cung nọ cung kia {xung} kể cả buổi vẫn chưa hết. Nhưng {xung} muốn hỏi một câu: {Goi} nghĩ thế nào về Hoàng hậu?"},{"who":"me","text":"Hỏi thẳng như vậy, {xung} lại tự hỏi vì sao {goi} muốn nghe. Chén trà này đủ ấm để nói thật, nhưng chưa chắc đủ kín để nói hết."},{"who":"A","text":"Trong cung, lời nói bay nhanh hơn cánh chim. {Xung} chỉ muốn biết lòng {goi} đứng về phía nào."},{"who":"me","text":"Một chén trà, một buổi chiều, và một câu hỏi nặng như đá. {Xung} nên nghe, nên dò, hay khéo khép chuyện lại, cần cân nhắc cho kỹ."}]}},
{"id":"j68:giftArrive","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp quà còn thoảng mùi thơm, đặt ngay ngắn trên án, tấm thẻ nhỏ buộc dây đề tên {A} bằng nét chữ mềm."},{"who":"M","text":"Bẩm {goi}, người bên cung {A} vừa mang quà sang, nói là chút lòng thành, mong {goi} nhận cho."},{"who":"me","text":"Quà đến vừa lúc, lại đề tên rõ ràng. Món quà đẹp đến mấy, ta cũng muốn biết lòng người gửi trước đã."},{"who":"M","text":"Dạ, người mang quà niềm nở lắm. Nhận thì phải đáp lễ, không nhận lại sợ mất lòng {A}."},{"who":"me","text":"Nhận hay trả cũng là một lời đáp. Để ta nghĩ cách nào vừa giữ tình, vừa giữ mình."}]}},
{"id":"j68:lostItem","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Rương gỗ mở toang, hộp trang sức vẫn khóa chặt, nhưng một món đồ ngươi cất kỹ đã không còn trong đó."},{"who":"A","text":"{Goi}, sáng nay {xung} dọn buồng thì thấy rương vơi mất một món. Hộp trang sức còn nguyên khóa, {xung} tìm khắp nơi mà không ra."},{"who":"me","text":"Khóa không hỏng, rương không bị cạy, vậy mà đồ vẫn mất. Món ấy ta giữ làm kỷ niệm, mất đi lòng ta xót lắm."},{"who":"A","text":"{Xung} sợ {goi} nghi cung nhân. Người trong cung phần nhiều thật thà, {xung} không muốn họ chịu oan."},{"who":"me","text":"Ta chưa vội nghi ai. Tìm đồ là việc cần, giữ lòng người cũng là việc cần, ta phải liệu sao cho vẹn cả đôi đường."}]}},
{"id":"j68:sickServant","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dãy nhà hầu phía sau lặng đi trong bóng chiều, chỉ nghe tiếng thở nặng nhọc vọng ra từ một gian nhỏ."},{"who":"M","text":"Bẩm {goi}, {A} đau từ đêm qua, ai cũng ngại không dám lại gần. Người ấy vẫn cắn răng nói không sao."},{"who":"me","text":"Một người quen chịu khó như {A}, đến nỗi gục xuống mà còn bảo không sao, hẳn đã chịu đựng từ lâu."},{"who":"M","text":"Dạ, ai cũng thương mà cũng sợ. Nếu không có người đứng ra lo, {xung} e người ấy khó mà gượng nổi."},{"who":"me","text":"Việc này không thể để mặc. Chữa thế nào, lo cho người ấy đến đâu, ta phải quyết cho thấu tình thấu lý."}]}},
{"id":"j68:maidQuarrel","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng cãi vã vọng lên từ sân sau, hai bóng người đứng đối mặt, người đỏ mặt tía tai, người mắt đã rưng rưng."},{"who":"M","text":"Bẩm {goi}, {A} và {B} cãi nhau từ nãy, ai cũng nói mình phải. Cung nhân đứng xem đã đông, {xung} không dám can."},{"who":"me","text":"Hai người cùng hầu một cung mà để lời qua tiếng lại lan ra tận ngoài. Mỗi người nói thế nào, ngươi nghe được những gì?"},{"who":"M","text":"Dạ, {A} kêu bị oan, {B} kêu bị thiệt. Cả hai đều nhìn {xung}, chờ {goi} đứng ra phân xử."},{"who":"me","text":"Nghiêng về ai cũng là bỏ rơi một người. Ta phải tìm cách xử sao cho cả cung còn nể phép, mà hai đứa còn giữ được thể diện."}]}},
{"id":"j68:strayCat","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng mèo kêu khe khẽ quanh quẩn nơi hiên cung, chẳng ai biết nó từ đâu tới, cũng chẳng ai đuổi được nó đi."},{"who":"M","text":"Bẩm {goi}, có một con mèo lạ cứ lảng vảng trong cung, đuổi mãi không chịu đi. Cung nhân người thương, người sợ."},{"who":"me","text":"Nó lạc đường hay tự tìm đến, ta cũng không rõ. Một con vật nhỏ mà đủ khiến cả cung bàn tán."},{"who":"M","text":"Dạ, có người bảo mèo tìm nhà là điềm lành, có người lại thì thầm chuyện chẳng hay. {Xung} không biết tin bên nào."},{"who":"me","text":"Giữ nó lại, đưa nó đi xa hay dò xem chủ nó là ai, mỗi đường đều có lý. Để ta nghĩ cho kỹ."}]}},
{"id":"j68:brokenHeirloom","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh vỡ còn rải trên nền gạch, {A} quỳ giữa đó, hai tay run rẩy không dám chạm vào."},{"who":"A","text":"{Goi}, {xung} sơ ý làm hỏng vật quý của {goi}. {Xung} đáng tội, xin {goi} cứ trách phạt."},{"who":"me","text":"Vật ấy không chỉ đáng giá bạc vàng. Nó gắn với người đã trao cho ta, nên ta xót không phải vì món đồ, mà vì tình."},{"who":"A","text":"{Xung} biết. Nhìn {goi} lặng đi, lòng {xung} đau hơn bị đánh. Xin {goi} cho {xung} một cơ hội chuộc lỗi."},{"who":"me","text":"Ngươi sợ đến run cả người, ta nhìn cũng không nỡ. Phạt hay tha, ta phải nghĩ cho khỏi hối về sau."}]}},
{"id":"j68:spoiledFood","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phần được cấp cho cung hôm nay vừa mở ra đã khiến {A} nhíu mày, mùi ẩm chua bốc lên nghẹn cả mũi."},{"who":"A","text":"{Goi}, phần cấp lần này kém hẳn mọi khi, {xung} bất bình thay cho {goi}. Như thế là họ coi thường cả cung."},{"who":"me","text":"Ngươi nói cũng phải. Nhưng nếu ta làm lớn, người ta bảo ta hẹp lòng; mà nhịn mãi, họ càng được thể."},{"who":"A","text":"{Xung} chỉ sợ {goi} chịu thiệt. Muốn đòi lẽ công bằng thì khó, còn nhịn thì nuốt không trôi."},{"who":"me","text":"Đòi, bù hay nhịn, mỗi đường một cái giá. Ta phải xem đường nào hợp thế của mình hơn."}]}},
{"id":"j68:leakRoof","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió mưa đêm qua để lại dấu vết khắp cung: nước loang trên nền, giấy tranh nhòe mực, mùi ẩm len vào từng góc nhà."},{"who":"M","text":"Bẩm {goi}, thiên tai đêm qua làm cung {xung} hư hại không ít. {Xung} đã cho dọn tạm, nhưng chỗ hỏng phải sửa mới yên."},{"who":"me","text":"Cung này là nơi ta nương thân, để nó dột nát thì lòng cũng không yên. Hư hại nặng nhẹ thế nào, ngươi đã xem hết chưa?"},{"who":"M","text":"Dạ, chỗ nào cũng tốn công. Xin Nội vụ phủ thì lâu, thuê thợ thì tốn, cung nhân nói tự che chắn cũng được."},{"who":"me","text":"Mỗi cách đều có nhanh chậm, đắt rẻ riêng. Để ta nghĩ cách nào vừa lòng cung nhân, vừa giữ được thể diện."}]}},
{"id":"j68:letterHome","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Phong thư nhàu nhẹ vì đi đường xa, nét chữ quen thuộc của người nhà hiện trên tờ giấy ngả vàng."},{"who":"M","text":"Bẩm {goi}, thư nhà vừa vào đến cung. {Xung} xin đọc: «Con ở nơi cung cấm, cha mẹ nhớ nhiều, trong nhà có đôi việc, con đừng lo.»"},{"who":"me","text":"«Đừng lo.» Người nhà càng dặn đừng lo, ta càng không yên. Nét chữ ấy, ngươi có thấy run không?"},{"who":"M","text":"Dạ, nét chữ nghiêng ngả, như người viết vừa nghĩ vừa dừng. {Xung} đoán trong nhà có điều khó nói."},{"who":"me","text":"Nhà ở xa, cung cấm lại cách mấy lớp tường. Gửi bạc, gửi thư hay cầu xin ân điển, ta phải chọn cách nào để lòng nhà được yên."}]}},
{"id":"j68:eunuchSqueeze","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khay bổng lộc đặt xuống nhẹ hơn mọi tháng, người đưa đứng đó, ánh mắt trượt qua tay áo người nhận như chờ đợi điều gì."},{"who":"A","text":"Bẩm {goi}, phần tháng này chỉ được thế thôi. Nhưng ở đây xưa nay có lệ, người biết điều thì việc gì cũng thuận."},{"who":"me","text":"Lệ ấy ta chưa từng thấy trong sổ sách. Ngươi nói lệ, ta nghe ra là một lời gợi ý ngầm."},{"who":"A","text":"{Goi} sáng suốt quá. {Xung} chỉ nhắc để {goi} đỡ mất lòng người, cũng đỡ thiệt phần mình."},{"who":"me","text":"Đưa bạc cho êm, mắng thẳng hay ghi lại để tâu lên người đứng đầu, đường nào cũng để lại dấu vết. Ta phải nghĩ xem đường nào đáng đi."}]}},
{"id":"j68:embroidery","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chỉ ngũ sắc trải giữa khung thêu, những mũi kim nhỏ vừa lướt qua tấm lụa đã hiện lên nét hoa sống động."},{"who":"A","text":"{Goi}, mũi thêu của {xung} dạo này khá hơn rồi. Nhưng {xung} vẫn muốn xem {goi} định thêu theo mẫu nào."},{"who":"me","text":"Mũi kim của {goi} đều và mịn, {xung} nhìn mà nể. {Xung} cũng đang nghĩ nên làm thế nào cho xứng với việc này."},{"who":"A","text":"Cùng một việc, mỗi người một cách, đẹp xấu nhìn là biết. {Xung} chỉ sợ mình thua {goi} mà thôi."},{"who":"me","text":"Lời {goi} nói khiêm nhường mà ý thì sâu. Thêu một mình, mượn tay thợ hay cùng nhau, {xung} phải chọn cho đúng."}]}},
{"id":"j68:flowerBloom","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nụ hoa mở dần trong ánh sáng dịu, cánh mỏng run nhẹ như đang thở, cả sân cung như ngưng lại để nhìn."},{"who":"M","text":"Bẩm {goi}, hoa trong cung vừa nở, cung nhân bảo là điềm lành. Ai đi ngang cũng dừng lại ngắm."},{"who":"me","text":"Hoa nở đúng lúc, đẹp như báo trước một chuyện vui. Nhưng hoa đẹp mấy cũng chỉ có một thời."},{"who":"M","text":"Dạ, {xung} nghĩ hoa nở đẹp nhất khi có người thưởng. Không biết {goi} muốn mời ai đến xem?"},{"who":"me","text":"Một đóa hoa cũng là một cơ duyên. Dâng ai, mời ai hay giữ riêng cho cung, ta phải nghĩ cho chu đáo."}]}},
{"id":"j68:servGamble","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} quỳ giữa nền gạch lạnh, đầu cúi thấp, hai bàn tay nắm chặt vạt áo như muốn giấu đi điều gì."},{"who":"A","text":"{Goi}, {xung} có tội, vì túng tiền mà làm điều không nên. Xin {goi} cho {xung} nói hết trước khi xử."},{"who":"me","text":"Ngươi quỳ đến thế, ta biết chuyện không nhỏ. Cứ nói thật, vì sao một người biết giữ phép như ngươi lại sa chân?"},{"who":"A","text":"{Xung} khổ vì tiền, lại nghe lời người xúi giục, đến lúc tỉnh ra thì đã muộn. {Xung} xin nhận mọi hình phạt."},{"who":"me","text":"Thương thì thương, phép cung vẫn là phép cung. Trả nợ răn đe, phạt theo lệ hay tra cho ra gốc, ta phải cân nhắc."}]}},
{"id":"j68:proudVisit","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kiệu hoa dừng trước cửa cung, rèm gấm khẽ lay, bước chân {A} nhẹ mà dõng dạc, như đang đi trong sân nhà mình."},{"who":"A","text":"{Goi}, nghe nói cung của {goi} dạo này yên ắng lắm. Cung của {xung} thì ngày nào cũng có chuyện, thật khó mà ngồi yên."},{"who":"me","text":"Yên ắng cũng là một cái phúc. Khách đến thăm là nể mặt {xung}, xin mời {goi} vào dùng chén trà."},{"who":"A","text":"Trà thì nơi nào cũng có. {Xung} đến là để xem {goi} sống ra sao, có cần {xung} chỉ vẽ điều gì không."},{"who":"me","text":"Lời {goi} mềm như lụa mà vướng như gai. Nhún nhường, đáp lại sắc sảo hay lui vào trong, {xung} phải chọn một đường."}]}},
{"id":"j68:kindVisit","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương thơm nhè nhẹ lan trong cung, {A} bước vào, vạt áo thanh nhã, trên tay mang theo chút lòng thành."},{"who":"A","text":"{Goi}, nghe nói dạo này {goi} có vẻ mệt. {Xung} mang chút đồ sang, mong {goi} đừng ngại."},{"who":"me","text":"{Goi} nhớ đến {xung}, lòng {xung} ấm lắm. Mời ngồi đây, đừng đứng mãi."},{"who":"A","text":"{Xung} muốn nán lại một chút, vì trong lòng có điều muốn nhờ mà chưa biết mở lời thế nào."},{"who":"me","text":"Điều gì khiến {goi} ngập ngừng đến vậy? {Xung} sẵn lòng nghe, và giúp được đến đâu {xung} sẽ giúp."}]}},
{"id":"j68:slyVisit","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} cười rất ngọt, nhưng ánh mắt cứ lướt khắp gian phòng, dừng lại ở từng góc nhỏ như đang đếm."},{"who":"A","text":"{Goi} sống thật chu đáo, mọi thứ đều ngăn nắp. {Xung} muốn biết thêm {goi} sinh hoạt ra sao, để tiện sang thăm."},{"who":"me","text":"Hỏi tỉ mỉ thế, {xung} lấy làm lạ. Những lần trước {goi} đến, {xung} đâu thấy {goi} để tâm đến chuyện nhà {xung}."},{"who":"A","text":"Gần nhau thì phải hiểu nhau chứ. {Xung} chỉ có lòng tốt, {goi} chớ nghĩ nhiều."},{"who":"me","text":"Lòng tốt mà phải dò từng giờ giấc, nghe mà lạnh gáy. Tiếp có người canh chừng, dò ngược ý nàng hay lạnh nhạt tiễn khách, {xung} cần một nước đi khéo."}]}},
{"id":"j68:thMama","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ma ma thân tín của Thái hậu bước vào, lưng thẳng, tay chắp trước bụng, ánh mắt chậm rãi lướt qua từng thứ trong cung."},{"who":"M","text":"{Goi}, ma ma bên Đức Thọ cung đã tới, nói phụng ý Thái hậu sang thăm, xem {goi} dạo này sống ra sao."},{"who":"me","text":"Ơn Thái hậu nhớ đến, ta cảm kích khôn xiết. Mời ma ma vào, dâng chén trà ngon nhất trong cung."},{"who":"M","text":"Nô tỳ nghe ma ma nhắn: Thái hậu lúc nào cũng muốn biết cung nào yên, cung nào có chuyện. Vài lời thật lòng có khi quý hơn quà."},{"who":"me","text":"Ma ma là tai mắt của Thái hậu, một lời của ta cũng sẽ đến tai Người. Biếu chút lòng thành, kể thật hay giữ lễ ít lời, ta phải liệu cho khéo."}]}},
{"id":"j68:docCheck","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đầu ngón tay thái y đặt nhẹ lên cổ tay, ánh mắt trầm tư, gian phòng im đến nỗi nghe rõ tiếng thở."},{"who":"A","text":"{Goi} cứ yên tâm, mạch tượng có chỗ cần lưu ý. {Xung} sẽ kê vài vị thuốc bồi bổ, uống đều thì đỡ."},{"who":"me","text":"Nghe {goi} nói, {xung} đỡ lo phần nào. Có điều thân thể này vẫn cần {goi} chỉ giúp, uống thế nào, kiêng gì?"},{"who":"A","text":"Lòng nặng thì thuốc thấm chậm. {Goi} cứ nghỉ ngơi, đừng nghĩ ngợi nhiều."},{"who":"me","text":"Thuốc bổ, chuyện các cung hay lời cảm ơn mà từ chối, thái y biết nhiều hơn {xung}. {Xung} phải cân nhắc xem nên nhận đến đâu."}]}},
{"id":"j68:painter","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuộn giấy trải ra trên án, mực đen mới mài còn thoảng mùi trầm, bút lông treo sẵn bên nghiên."},{"who":"A","text":"{Goi}, {xung} phụng mệnh đến vẽ trong cung. Nét bút cần ánh sáng và lòng yên tĩnh, xin {goi} cho {xung} chút thời gian."},{"who":"me","text":"Tay nghề của {goi} {xung} nghe danh đã lâu. Vẽ gì, vẽ thế nào để người xem hiểu đúng ý {xung}, {xung} cần bàn với {goi}."},{"who":"A","text":"Nét bút nói thật hay nói đẹp là tùy người ngồi trước giấy. {Xung} chỉ vẽ theo điều {goi} muốn."},{"who":"me","text":"Bỏ bạc cho nét thêm đẹp, ngồi cho vẽ đúng thật hay học lỏm vài nét, mỗi lối đều có cái hay riêng. {Xung} cần chọn."}]}},
{"id":"j68:musician","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dây đàn khẽ rung khi ngón tay chạm đến, một âm thanh trong vắt tan vào không khí trong cung."},{"who":"A","text":"{Goi}, {xung} mang đàn sang vì có việc liên quan đến nhạc. Xin {goi} cho phép {xung} gảy vài âm trước."},{"who":"me","text":"Tiếng đàn của {goi} thanh lắm, khiến {xung} tạm quên mọi sự bận lòng. Xin cứ gảy tiếp."},{"who":"A","text":"Nhạc hợp lòng thì nhớ lâu, nhạc gượng ép thì chóng tàn. {Xung} mong khúc này đem lại chút vui cho {goi}."},{"who":"me","text":"Học thêm một khúc, nhờ phổ nhạc hay mời về sớm, {xung} đều có lý để chọn. Để {xung} nghe thêm rồi mới quyết."}]}},
{"id":"j68:newGirlAdvice","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một bóng áo nhạt rụt rè đứng ngoài ngưỡng cửa, hai tay xoắn vào nhau, mắt đỏ hoe như vừa lau vội."},{"who":"A","text":"{Goi}, {xung} mới vào cung, nhiều điều chưa biết. Nghe nói {goi} hiền hậu, nên {xung} mạo muội đến xin chỉ bảo."},{"who":"me","text":"Vào đi, đừng sợ. Người mới nào cũng từng bỡ ngỡ, {xung} cũng không khác."},{"who":"A","text":"{Xung} sợ sai lễ nghi, lại sợ bị người ta bắt nạt. Có {goi} chỉ cho, {xung} đỡ lo biết bao."},{"who":"me","text":"Lời xin ấy làm {xung} mềm lòng. Chỉ bảo tận tình, nhận về bên mình hay khuyên vài câu, {xung} phải nghĩ xem nên giúp đến đâu."}]}},
{"id":"j68:eunRequest","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} quỳ ngoài thềm đã lâu, trán áp sát nền gạch, giọng nghẹn lại như sợ nói ra là mất cả can đảm."},{"who":"A","text":"{Goi}, {xung} hầu {goi} bấy lâu chưa từng xin điều gì. Hôm nay vì việc nhà, {xung} đành mạo muội cầu xin."},{"who":"me","text":"Ngươi quỳ đến thế, ta biết là việc trọng. Cứ đứng dậy, nói rõ ràng, ta nghe."},{"who":"A","text":"Việc này liên quan đến người thân của {xung}, một mình {xung} không làm nổi. Xin {goi} thương mà giúp."},{"who":"me","text":"Giúp được hay không còn tùy việc khó dễ. Giúp thẳng, giúp để giữ thêm lòng người hay từ chối, ta phải nghĩ cho kỹ."}]}},
{"id":"j68:empDish","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hương thơm từ bếp nhỏ bay ra, nồi niêu còn nóng, người của Càn Thanh cung đứng chờ ngoài hiên, dáng vẻ cung kính."},{"who":"M","text":"Bẩm {goi}, Hoàng thượng có lời truyền xuống về một món ăn, muốn {goi} lo liệu. Người đang chờ hồi âm."},{"who":"me","text":"Hoàng thượng nhớ đến chuyện bếp núc của ta, đó là phúc, cũng là một phép thử. Món ngài muốn là món thế nào?"},{"who":"M","text":"Dạ, người truyền lời nói ngài muốn thứ hợp ý ngài, còn lại cứ nói thật. {Xung} không dám đoán thêm."},{"who":"me","text":"Tự tay vào bếp thì tốn công, thuê người thì ngài chẳng thấy lòng ta, nói thật thì sợ phật ý. Ta phải chọn một lối cho trọn."}]}},
{"id":"j68:empPoem","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tờ giấy hoa tiên còn thơm mùi mực, nét chữ phóng khoáng của Hoàng thượng chạy dài, chừa lại một khoảng trống chờ người đáp."},{"who":"M","text":"Bẩm {goi}, Hoàng thượng gửi sang mấy dòng chữ, chờ {goi} hồi đáp. Người dặn trước lúc lên đèn phải có lời."},{"who":"me","text":"Một bài thơ để ngỏ như vậy, là ngài muốn thử tài hay muốn nghe tiếng lòng ta? Mực của ngài còn chưa khô."},{"who":"M","text":"Dạ, {xung} đoán là cả hai. Ngài ít khi tự gửi chữ, hẳn là coi trọng {goi} lắm."},{"who":"me","text":"Góp ý thẳng thắn, khen cho vừa lòng hay nhờ người chấp bút, mỗi đường một thế. Ta phải chọn cho khéo."}]}},
{"id":"j68:empSulk","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn hắt lên gương mặt Hoàng thượng, đôi mày chau lại, chén trà đặt bên tay nguội dần mà không ai dám động."},{"who":"A","text":"{Xung} không muốn nói nhiều. Chỉ là hôm nay mọi chuyện đều không thuận, nên {xung} mới đến đây."},{"who":"me","text":"{Goi} cứ ngồi, ở đây không ai làm phiền. Muốn nói thì {xung} nghe, không muốn nói thì {xung} ngồi cùng."},{"who":"A","text":"{Goi} thấy {xung} có nặng lời quá không? Trong triều ai cũng chờ một câu của {xung}, mà lòng {xung} lại chẳng yên."},{"who":"me","text":"Một người gánh cả thiên hạ cũng cần một khoảng lặng. {Xung} nên lặng lẽ pha trà, khuyên giải hay kể chuyện nhẹ cho khuây, cần cân nhắc."}]}},
{"id":"j68:empChess","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quân cờ đen trắng nằm ngổn ngang trên bàn gỗ, ánh đèn lay nhẹ, Hoàng thượng chống cằm nhìn thế cờ, chờ một nước đi."},{"who":"A","text":"Ván này {xung} muốn đánh với {goi}, đừng nhường. Nhường mãi, {xung} chẳng còn biết mình thắng thật hay thua thật."},{"who":"me","text":"Lời dặn ấy khó mà nghe theo. Đánh hết sức thì sợ phật ý, nhường thì sợ {goi} nhận ra."},{"who":"A","text":"{Xung} nhìn nước cờ là biết lòng người. {Goi} cứ đánh theo ý mình."},{"who":"me","text":"Nước cờ cũng như lòng, giấu được lâu mới thành. {Xung} nên đánh hết sức, khéo để thua sát nút hay xin hôm khác, cần nghĩ cho kỹ."}]}},
{"id":"j68:empAsksAbout","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng đặt chén xuống, giọng nhẹ như hỏi chuyện thời tiết, nhưng ánh mắt dừng trên gương mặt người đối diện rất lâu."},{"who":"A","text":"{Goi} thấy {B} là người thế nào? Cứ nói, {xung} chỉ muốn nghe lời thật."},{"who":"me","text":"{B} có điều hay, có điều khó nói. Lời của {xung} rơi vào tai {goi} là có sức nặng, nên {xung} không dám nói bừa."},{"who":"A","text":"{Xung} biết {goi} cẩn trọng. Nhưng chính vì thế, {xung} mới hỏi {goi} mà không hỏi người khác."},{"who":"me","text":"Nói tốt cho {B}, nói thật không thêm bớt, hay khéo thêm một câu cho nặng, mỗi cách đều là một lời {xung} phải chịu. {Xung} phải cân nhắc."}]}},
{"id":"j68:empGiftOdd","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Món ban của Hoàng thượng vừa đặt giữa sảnh, cung nhân tụ lại nhìn, ánh mắt người tò mò lẫn kẻ đoán già đoán non."},{"who":"M","text":"Bẩm {goi}, Hoàng thượng vừa ban xuống một món quà. Cả cung bàn tán xôn xao, ai cũng chờ xem {goi} đón nhận ra sao."},{"who":"me","text":"Ân điển của ngài là phúc, nhưng phúc quá rõ cũng thành cái gai trong mắt người khác. Món này có ý gì, ngươi nghĩ sao?"},{"who":"M","text":"Dạ, {xung} chỉ thấy Hoàng thượng nghĩ đến {goi}. Còn người ngoài nhìn vào, e sẽ nghĩ khác."},{"who":"me","text":"Tạ ơn rồi khoe khắp nơi, cất kín hay dâng lại Thái hậu cho yên lòng, mỗi lối đều có lợi có hại. Ta phải nghĩ cho chín."}]}},
{"id":"j68:empIncognito","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm buông xuống, đèn cung lập lòe, Hoàng thượng đứng bên cửa sổ, tay nắm vạt áo thường, như người sắp trốn khỏi khuôn phép."},{"who":"A","text":"Đêm nay {xung} muốn ra ngoài, không ai biết, chỉ có {goi} đi cùng. Đừng hỏi lý do, đi rồi sẽ rõ."},{"who":"me","text":"{Goi} nói nhẹ nhàng mà ý định không nhỏ. Rời cung trong đêm, không báo ai, lòng {xung} vừa rộn ràng vừa sợ."},{"who":"A","text":"{Xung} cũng sợ, nhưng thà đi một lần cho nhẹ lòng. Có {goi} bên cạnh, {xung} yên tâm hơn."},{"who":"me","text":"Theo {goi} là tin {goi}, can {goi} là lo cho {goi}. {Xung} cần nghĩ xem nên theo, nên can, hay theo mà ngầm báo cho người hộ vệ."}]}},
{"id":"j68:empSleepRead","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh sáng trong cung dịu dần, tiếng người nói chuyện thưa dần, Hoàng thượng tựa lưng, mi mắt nặng trĩu như sắp thiếp đi."},{"who":"A","text":"Hôm nay {xung} mệt lắm. Chỉ muốn ngồi đây một lúc, không nghĩ chuyện triều chính."},{"who":"me","text":"Cứ nghỉ đi, ở đây không ai làm phiền. {Xung} ở bên canh."},{"who":"A","text":"Cung của {goi} lúc nào cũng yên ổn, khiến {xung} nhớ thuở còn nhỏ, chưa phải gánh gì."},{"who":"me","text":"Người đã ngủ say. {Xung} nhìn mà thấy thương. Để người ngủ, đánh thức đúng giờ thượng triều hay nhân lúc người vui mà xin ân điển, {xung} phải nghĩ cho phải đạo."}]}},
{"id":"j68:heatStroke","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nắng gắt đổ xuống mái ngói, không khí oi nồng đặc quánh, tiếng ve rền rĩ làm cả cung uể oải."},{"who":"M","text":"Bẩm {goi}, trời nóng quá, người trong cung ai cũng mệt lả. {Xung} thấy sắc mặt {goi} cũng không được tươi."},{"who":"me","text":"Nóng thế này, ngồi yên cũng ướt áo. Ngươi nghĩ xem còn cách nào để cả cung đỡ khổ?"},{"who":"M","text":"Dạ, có thể xin đá lạnh từ hầm băng, hoặc ra hồ hóng gió, hoặc ở yên trong cung chờ trời dịu."},{"who":"me","text":"Đi đâu, xin gì hay ở yên, mỗi cách đều có giá riêng. Ta phải chọn cách hợp với thân mình và cung nhân."}]}},
{"id":"j68:snowDay","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tuyết phủ trắng mái ngói và bậc thềm, hơi lạnh len qua khe cửa, lò than đỏ rực mà vẫn không đủ ấm."},{"who":"M","text":"Bẩm {goi}, tuyết rơi suốt đêm, cả cung lạnh cóng. {Xung} đã cho đốt thêm than nhưng cung nhân vẫn co ro."},{"who":"me","text":"Tuyết đẹp mà người lạnh thì khổ. Ta muốn lo cho họ trước, rồi mới nghĩ đến chuyện thưởng ngoạn."},{"who":"M","text":"Dạ, {goi} thương cung nhân thật. Còn lễ thỉnh an sáng nay, đường trơn thế này, không biết {goi} định đi hay thôi."},{"who":"me","text":"Phát áo ấm, làm thơ vịnh tuyết hay vẫn lội tuyết mà đi, việc nào cũng đáng làm. Ta cần chọn việc nào trước."}]}},
{"id":"j68:autumnMoon","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trăng thu treo cao, gió heo may mang hơi lạnh và mùi hoa cúc thoảng sang từ phía cung của {A}."},{"who":"M","text":"Bẩm {goi}, bên cung {A} gửi lời đến, mời {goi} chung vui đêm thu này. Nàng nói cảnh đẹp mà thiếu người thì uổng."},{"who":"me","text":"Trăng đẹp thế này, ngồi một mình thì lòng buồn. Nhưng lời mời của {A} có ý gì, ngươi đoán thử?"},{"who":"M","text":"Dạ, {xung} đoán nàng thật lòng muốn thân cận. Cũng có thể nàng muốn nhân dịp này nhìn thấu lòng {goi}."},{"who":"me","text":"Nhận lời cho vui, mượn dịp dò lòng nàng hay ở nhà đọc sách, cả ba đều có lý. Ta cần quyết cho phải."}]}},
{"id":"j68:springAllergy","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khăn lụa chặn nơi mũi vẫn không ngăn được tiếng hắt hơi, mắt đỏ hoe, xuân đẹp mà người lại khó chịu."},{"who":"M","text":"Bẩm {goi}, xuân về hoa nở mà người trong cung lại khó chịu thế này. {Xung} nhìn mà lo."},{"who":"me","text":"Phấn hoa với sương gió mùa này thật hành người. Sắp có việc cần ra mặt, ta không muốn lộ vẻ tiều tụy."},{"who":"M","text":"Dạ, thái y {A} ở viện vẫn sẵn lòng chữa. Hoặc {goi} tự pha trà thanh nhiệt cũng được."},{"who":"me","text":"Mời thái y, tự pha trà hay gắng chịu, ta phải xem thân mình chịu được đến đâu mà liệu."}]}},
{"id":"j68:stormNight","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sấm rền vọng khắp các điện, chớp xé ngang bầu trời, cành cây quất vào cửa sổ như tiếng gõ của kẻ lạ."},{"who":"M","text":"Bẩm {goi}, giông tố dữ dội quá, cả cung xôn xao. Có người bảo Hoàng thượng nghe tiếng sấm là không yên."},{"who":"me","text":"Một đêm bão thế này, không chỉ cung ta sợ. Ngươi có nghe tin gì thêm không, ai bị thương chưa?"},{"who":"M","text":"Dạ, {xung} nghe có chuyện hư hại, có người bị đè. Lòng {xung} cũng bất an."},{"who":"me","text":"Hầu Hoàng thượng giữa đêm, cầu an cho cung hay cứu người ngay, việc nào cũng trọng. Ta phải chọn việc đáng làm trước."}]}},
{"id":"j68:famineDonate","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tờ cáo thị mới dán còn ướt hồ, dân ngoài cổng thành kéo về mỗi lúc một đông, tin dữ lan nhanh hơn tiếng chuông."},{"who":"M","text":"Bẩm {goi}, tin từ ngoài kinh truyền về: dân đói rất nhiều. Trong cung có lời kêu gọi các cung giảm chi, góp sức cứu đói."},{"who":"me","text":"Dân đói thì cung cũng không thể yên lòng ngồi hưởng. Nhưng quyên góp bao nhiêu mới phải đạo?"},{"who":"M","text":"Dạ, quyên ít sợ mang tiếng keo kiệt, quyên nhiều thì cung {xung} cũng phải chịu thiếu. {Xung} không dám bàn."},{"who":"me","text":"Góp nhiều, giữ chay giảm chi hay góp chút cho phải lễ, mỗi đường đều là một tấm lòng. Ta nghĩ kỹ rồi sẽ nói."}]}},
{"id":"j68:borderNews","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tin từ biên ải đến lúc nửa đêm, đèn trong điện Dưỡng Tâm vẫn sáng, bóng người in lên cửa sổ không rời."},{"who":"M","text":"Bẩm {goi}, tin từ biên ải vừa truyền vào cung. Nghe nói Hoàng thượng thức suốt đêm vì chuyện ấy."},{"who":"me","text":"Biên ải xa xôi, mà bóng ngài in trên cửa sổ điện Dưỡng Tâm suốt đêm nay. Lòng ta cũng không yên."},{"who":"M","text":"Dạ, cung nhân ai cũng lo. {Goi} có muốn làm gì cho Hoàng thượng và quân sĩ không?"},{"who":"me","text":"Thêu cờ may áo, mang canh khuya hầu ngài hay đứng ngoài việc triều, mỗi đường đều có lợi có hại. Ta phải cân nhắc."}]}},
{"id":"j68:clanFather","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} bước vào, vạt áo vẫn chỉnh tề, nhưng đôi tay cứ vuốt đi vuốt lại một góc khăn như người không yên."},{"who":"A","text":"{Goi}, chuyện trong triều có liên quan đến cha {xung}. {Xung} lo lắm, nên đến hỏi {goi} một lời."},{"who":"me","text":"Chuyện gia tộc mà {goi} đến tận đây, {xung} nghe ra là việc trọng. Cứ nói đi."},{"who":"A","text":"Cha {xung} ở triều có lúc lên lúc xuống. {Xung} không có ai để nhờ, chỉ còn biết dựa vào {goi}."},{"who":"me","text":"{Xung} thương lòng {goi}, nhưng chuyện triều chính là nước sâu. Hứa giúp, an ủi hay mách lại nhà đối đầu, {xung} phải liệu cho thận trọng."}]}},
{"id":"j68:kidSick","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng khóc yếu ớt vọng ra từ buồng trong, tấm khăn ướt còn đặt trên trán đứa trẻ, nhũ mẫu đứng bên mà tay chân luống cuống."},{"who":"M","text":"Bẩm {goi}, {A} không khỏe từ chiều. Nhũ mẫu lo lắm, vừa sai người đi báo."},{"who":"me","text":"Con ta bệnh mà ta chưa hay, lòng ta xót vô cùng. Đã ai xem kỹ chưa, nặng nhẹ thế nào?"},{"who":"M","text":"Dạ, chưa xem rõ. Thái y {B} sẵn lòng đến ngay, hay {goi} muốn tự mình thức canh cũng được."},{"who":"me","text":"Mời thái y ngay, tự mình chăm con hay giao nhũ mẫu lo, trong lòng ta chỉ muốn con khỏe. Ta phải chọn đường nào tốt nhất cho con."}]}},
{"id":"j68:kidFight","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng ồn vọng ra từ thư phòng, sách vở ngổn ngang, hai đứa trẻ đứng đối mặt, đứa nào cũng đỏ mặt, chưa chịu nhường nhau."},{"who":"M","text":"Bẩm {goi}, {A} vừa xích mích với con của {B}, chuyện đã đến tai cung nhân khắp nơi."},{"who":"me","text":"Trẻ con va chạm cũng là thường. Có điều con của {B} là người nhà {B}, ta xử không khéo thì thành chuyện lớn."},{"who":"M","text":"Dạ, {A} vẫn bướng, chưa chịu cúi đầu. {Xung} không biết {B} đã hay tin hay chưa."},{"who":"me","text":"Dẫn con sang xin lỗi, bênh con đòi lẽ phải hay nghiêm khắc dạy lễ, mỗi đường đều thấm vào lòng con. Ta cần cân nhắc."}]}},
{"id":"j68:kidGift","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đôi chân nhỏ chạy dồn dập ngoài hành lang, một bóng áo nhỏ ập vào cửa, hai tay giấu sau lưng, mắt sáng như sao."},{"who":"A","text":"{Goi}, con có chuyện muốn khoe. Con muốn {goi} là người biết đầu tiên."},{"who":"me","text":"Con chạy mệt không? Cứ nói từ từ, ta nghe đây, không ai giành mất đâu."},{"who":"A","text":"Con làm, con học, con mong được {goi} khen. Nếu {goi} bằng lòng, con còn muốn xin thêm một điều."},{"who":"me","text":"Con làm mẹ vui lòng thế này, ta chẳng muốn rời con. Dành cả buổi bên con, nhờ thầy dạy thêm hay dẫn con đến hầu phụ hoàng, ta phải nghĩ xem điều nào tốt nhất."}]}},
{"id":"j68:bribedServ","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} đứng sát vách, giọng hạ thấp đến mức chỉ nghe được hơi thở, như muốn trao một bí mật nóng bỏng."},{"who":"A","text":"{Goi}, người bên {B} đã tìm {xung}. {Xung} không dám giấu, nên đến báo ngay."},{"who":"me","text":"Ngươi dám đến nói thẳng, ta ghi nhận. Người của {B} muốn gì ở ngươi?"},{"who":"A","text":"Họ muốn {xung} làm tai mắt trong cung này, hứa cho nhiều lợi lộc. {Xung} nghe mà sợ, không dám từ chối ngay."},{"who":"me","text":"Thành thật là đức hiếm. Thưởng ngươi, dùng ngươi để đối phó ngược lại hay đuổi cho yên, ta phải liệu thật kỹ."}]}},
{"id":"j68:servRomance","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} đứng cúi mặt, má đỏ đến tận mang tai, môi mấp máy mà chẳng nói thành lời, hai tay siết chặt một góc khăn."},{"who":"A","text":"{Goi}, {xung} biết mình phạm điều không nên. Nhưng lòng {xung} có người, {xung} không muốn dối {goi}."},{"who":"me","text":"Ngươi dám nói thật, ta thấy cũng đáng nể. Lòng người một khi đã động thì khó giấu, nhưng phép cung nghiêm lắm."},{"who":"A","text":"{Xung} chỉ mong đến ngày mãn hạn được ra khỏi cung. Xin {goi} đừng bắt {xung} dứt lòng."},{"who":"me","text":"Che giấu thì có lỗi với phép cung, răn dạy thì lạnh lòng người, hứa xin ân điển thì còn xa. Ta phải nghĩ cho thấu."}]}},
{"id":"j68:servLeave","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} quỳ nơi bậc thềm, mắt đỏ hoe, tay nắm một góc áo, giọng run run vì nén khóc."},{"who":"A","text":"{Goi}, nhà {xung} có chuyện gấp. {Xung} chỉ xin được về một chuyến, chỉ sợ không kịp."},{"who":"me","text":"Ngươi hầu ta bấy lâu, chưa từng xin điều gì. Việc nhà ngươi nặng thế nào, nói ta nghe."},{"who":"A","text":"Người thân của {xung} đang gặp họa. {Xung} không còn cách nào khác, chỉ biết cầu xin {goi}."},{"who":"me","text":"Lòng ngươi ta thấy rõ. Cho về kèm bạc, xin Nội vụ phủ cho phép hay không cho, ta phải cân nhắc cả phép cung lẫn tình người."}]}},
{"id":"j68:newServSus","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bóng người thoắt qua cửa sau khi đêm đã khuya, tiếng chân rất khẽ, khẽ đến mức như cố ý không để ai nghe."},{"who":"M","text":"Bẩm {goi}, {xung} thấy {A} có điều khác lạ. Cung nhân cũng đã bàn tán, chỉ chưa ai dám nói thẳng."},{"who":"me","text":"{A} mới vào cung chưa lâu, chưa rõ tính nết. Ngươi thấy cụ thể điều gì, nói rõ cho ta."},{"who":"M","text":"Dạ, {xung} chỉ thấy dáng vẻ không như người mới đến. Nhưng {xung} không có bằng chứng, không dám khẳng định."},{"who":"me","text":"Không bằng chứng mà nghi thì dễ oan người. Theo dõi, hỏi thẳng hay đổi việc, ta phải chọn đường ít tổn thương nhất."}]}},
{"id":"j68:rumorPreg","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lời xì xào theo gió luồn qua từng hành lang, cung nhân thì thầm mà mắt thì liếc về phía cung của {A}."},{"who":"M","text":"Bẩm {goi}, trong cung đang đồn một chuyện về {A}: người ta bảo nàng đã có tin vui, nhưng đang giấu."},{"who":"me","text":"Lời đồn chưa biết thật giả đã lan nhanh hơn lửa. Nếu thật, đây là chuyện của cả cung."},{"who":"M","text":"Dạ, {xung} không dám tin hết, cũng không dám bỏ qua, vì nếu thật thì {A} sẽ có thế mạnh."},{"who":"me","text":"Cho người dò cho rõ, sang chúc mừng thăm dò hay mặc kệ lời đồn, mỗi đường đều thử lòng người. Ta phải chọn cho khéo."}]}},
{"id":"j68:rumorSpy","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Vài tiếng thì thầm lọt qua khe cửa dãy nhà hầu, ngừng bặt ngay khi có bước chân lại gần."},{"who":"M","text":"Bẩm {goi}, có kẻ rỉ tai rằng {A} đem chuyện trong cung ra ngoài. {Xung} nghe mà không biết nên tin hay không."},{"who":"me","text":"{A} hầu ta bấy lâu chưa lộ điều gì khác thường. Nhưng nghi một lần thì dễ nghi mãi."},{"who":"M","text":"Dạ, {xung} cũng thấy khó tin. Nhưng lời đồn đã ra, nếu không xử thì cung nhân sẽ cho là {goi} dung túng."},{"who":"me","text":"Thử lòng bằng một tin giả, tin tưởng mà thưởng cho yên lòng hay đuổi đi cho yên, mỗi đường đều có giá. Ta phải nghĩ kỹ."}]}},
{"id":"j68:rumorEvidence","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một cuốn sổ, một mẩu giấy hay chỉ là một ánh mắt đắc ý, lời đồn không rõ hình dạng nhưng ai nghe cũng thấy sức nặng của nó."},{"who":"M","text":"Bẩm {goi}, trong cung đang đồn {A} nắm trong tay thứ gì đó có thể làm hại {goi}. {Xung} nghe mà lạnh cả người."},{"who":"me","text":"Lời đồn chưa có hình dạng mà đã khiến người ta đứng ngồi không yên. Ngươi nghe từ ai?"},{"who":"M","text":"Dạ, từ cung nữ các cung truyền lại. Không ai thấy tận mắt, nhưng ai cũng nhắc đến tên {A}."},{"who":"me","text":"Mua tin từ người bên nàng, sang làm lành hay bỏ ngoài tai, mỗi cách đều là một canh bạc. Ta cần chọn thật kỹ."}]}},
{"id":"j68:rumorEmpLove","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tin đồn trượt qua hành lang, qua cửa các cung, đổi đi đôi chút theo mỗi cái miệng truyền đi."},{"who":"M","text":"Bẩm {goi}, trong cung đang đồn về số phận của {A}. Người nói vui, người nói buồn, chưa ai biết thật giả."},{"who":"me","text":"Chuyện ân sủng của {A} lúc lên lúc xuống, ta đã quen nghe. Nhưng lần này lời đồn có vẻ nặng hơn mọi lần."},{"who":"M","text":"Dạ, cung nhân bảo tin ấy bắt nguồn từ Kính sự phòng. Hỏi nơi ấy thì rõ nhất."},{"who":"me","text":"Hỏi Kính sự phòng, sang thân thiết với nàng hay thêm lời vào chuyện đồn, mỗi đường đều có người vui kẻ buồn. Ta phải nghĩ xem nên đi đường nào."}]}},
{"id":"j68:hairpinThief","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tráp nhỏ khép lại như chưa từng bị động đến, nhưng bên trong đã trống một chỗ, ánh nến soi vào chỉ thấy lớp lụa lót nhăn nhẹ."},{"who":"M","text":"Bẩm {goi}, món đồ trong tráp đã mất. Quanh lúc ấy chỉ có {A}, {B} và {C} ra vào buồng trong."},{"who":"me","text":"Ba người, ba lời giải thích, mà chỉ một người nói thật. Ta không muốn nghi oan ai, cũng không muốn bỏ qua kẻ có lỗi."},{"who":"M","text":"Dạ, {xung} đã hỏi sơ qua, ai cũng kêu oan. {Xung} cũng không biết nên tin ai."},{"who":"me","text":"Tự tra từng manh mối, nhờ Cung Chính ti hay cho kẻ lấy một đêm tự trả lại, ta phải chọn cách vừa tìm ra sự thật vừa giữ tình người."}]}},
{"id":"j68:poisonedFish","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mặt nước trong chậu vẫn lặng, nhưng sinh vật trong đó đã nằm yên không còn động đậy, khiến người nhìn lạnh sống lưng."},{"who":"A","text":"{Goi}, {xung} sáng nay phát hiện vật nuôi trong cung chết bất thường. {Xung} sợ lắm, nên chạy đến báo ngay."},{"who":"me","text":"Chết trong một đêm mà không dấu hiệu bệnh. Ngươi có thấy ai lạ ra vào, có cho ăn thứ gì mới không?"},{"who":"A","text":"{Xung} nhớ không có gì khác. Nhưng đêm qua có tiếng động nhỏ, {xung} cũng không dám chắc."},{"who":"me","text":"Việc nhỏ mà bóng dáng nặng nề. Mời thái y nghiệm độc, hỏi ngươi kỹ hơn hay thay hết đồ ăn nước uống, ta phải chọn trước."}]}},
{"id":"j68:nightSteps","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya gió rít qua mái hiên, trong tĩnh mịch có thứ gì khẽ khàng lướt qua rồi lại im bặt như chưa từng có."},{"who":"A","text":"{Goi}, đêm qua {xung} nghe tiếng động lạ quanh cung, sáng ra lại thấy dấu vết. {Xung} sợ lắm."},{"who":"me","text":"Có người rình quanh cung ta mà ta ngủ say không biết. Ngươi thấy gì rõ nhất?"},{"who":"A","text":"{Xung} chỉ thấy dấu vết để lại, chứ không thấy bóng người. Cung nhân khác cũng bắt đầu bàn tán."},{"who":"me","text":"Thức đêm rình bắt, thuê thêm người gác hay bảo ngươi im lặng cho yên, mỗi lối đều có điều đáng lo. Ta phải nghĩ xem nên dùng kế nào."}]}},
{"id":"j68:silkAllot","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Những xấp lụa mới xếp trên khay đỏ, sắc màu rực rỡ, ánh mắt người nhìn không giấu được sự so sánh."},{"who":"A","text":"{Goi}, lụa mới của Nội vụ phủ chia đến hai cung {xung}, mà xem ra không đủ cho cả hai bên vừa lòng."},{"who":"me","text":"Lụa đến tay ai cũng do thời vận, chứ {xung} không cố ý tranh. Sao {goi} lại nghĩ đến chuyện ấy?"},{"who":"A","text":"Chỉ vì cùng là phi tần, ai cũng muốn được xứng đáng. {Xung} mong {goi} hiểu cho."},{"who":"me","text":"{Xung} hiểu, nên không muốn vì mấy xấp lụa mà sinh lòng ngại nhau. Nhường, giữ hay bỏ bạc may thêm cho cả hai, {xung} cần nghĩ."}]}},
{"id":"j68:templeRite","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khói hương lượn lờ trong Phật đường, tiếng mõ vọng đều, ngọn đèn dầu cháy nhỏ bên bậc đá như những chấm lửa khẩn cầu."},{"who":"M","text":"Bẩm {goi}, Đức Thọ cung có phật sự cần người góp sức, nghe nói Thái hậu rất để tâm. Cung nào chu đáo sẽ được ghi nhận."},{"who":"me","text":"Việc phật sự là việc lớn, tâm thành thì có phước. Ta nên đến, hay chỉ cúng chút để tỏ lòng?"},{"who":"M","text":"Dạ, theo hầu trọn buổi thì mệt, cúng nhiều thì tốn. Nhưng thiếu mặt thì sợ Thái hậu phật ý."},{"who":"me","text":"Một nén hương cũng là tấm lòng, nhưng người ta nhìn tấm lòng ấy thế nào còn tùy. Theo hầu, cúng hậu hay cáo bận, ta phải cân nhắc."}]}},
{"id":"j68:fortuneNun","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc áo tu màu xám lướt qua cổng cung, thoảng mùi hương trầm, bóng người ấy khiến cung nhân ngoái lại nhìn."},{"who":"M","text":"Bẩm {goi}, trong cung vừa có người đến xem số xem tướng. Cung nhân đổ xô đi hỏi, {xung} cũng tò mò."},{"who":"me","text":"Số mệnh người sống trong cung này đã khó đoán, nghe thêm lời tiên tri chẳng biết là phúc hay thêm lo."},{"who":"M","text":"Dạ, có kẻ tin, có kẻ không, nhưng ai cũng sợ bỏ lỡ điều tốt. {Xung} nghĩ {goi} nên có chủ ý."},{"who":"me","text":"Xem một quẻ, treo bùa cho người yên lòng hay can ngăn chuyện mê tín, mỗi đường đều có lý. Ta phải xem đường nào hợp."}]}},
{"id":"j68:hhSummons","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chuông chiều Khôn Ninh cung vừa điểm, trên án sổ sách dày chồng chất, ánh mắt Hoàng hậu bình thản mà không ai dám ngẩng lên."},{"who":"A","text":"{Goi}, {xung} cho gọi {goi} đến vì có việc cần người đáng tin. Ở lục cung này, không phải ai {xung} cũng giao việc được."},{"who":"me","text":"Được {goi} tin cậy, {xung} vinh hạnh vô cùng. Việc ấy cụ thể thế nào, xin cho {xung} biết."},{"who":"A","text":"Việc không nhỏ mà cũng không khó, chỉ cần {goi} cẩn thận và để tâm. {Xung} tin {goi} làm được."},{"who":"me","text":"Lời của {goi} nặng như núi. Tận tâm giúp, nhân tiện xem xét hay cáo bệnh từ chối, {xung} phải cân nhắc cho kỹ."}]}},
{"id":"j68:allyOffer","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đình nghỉ vắng, gió lay rèm trúc, {A} liếc quanh một vòng rồi mới hạ giọng, như sợ ngay cả cột đình cũng biết nghe."},{"who":"A","text":"{Goi}, {B} ngày càng lấn lướt, ai cũng thấy. {Xung} nghĩ hai ta nên liên thủ, {goi} thấy thế nào?"},{"who":"me","text":"Một lời đề nghị lớn. Vì sao {goi} lại chọn {xung} mà không chọn người khác?"},{"who":"A","text":"Vì {xung} thấy {goi} sáng suốt, không ham tranh nhưng cũng không chịu thiệt. Hai ta hợp lại, {B} khó mà ngang ngược."},{"who":"me","text":"Bắt tay với {goi} là đứng chung một thuyền, báo cho {B} là đổi phe, từ chối là đứng ngoài. {Xung} cần nghĩ kỹ thuyền nào đáng bước lên."}]}},
{"id":"j68:borrowDress","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"{A} đứng ngoài cửa, ngập ngừng như người đến xin một điều mà chính mình cũng thấy ngượng."},{"who":"A","text":"{Goi}, {xung} có việc muốn nhờ. Thứ {xung} cần bỗng dưng thiếu đúng lúc, không biết {goi} có thể cho mượn không?"},{"who":"me","text":"Cùng ở trong cung, mượn qua mượn lại cũng thường. Nhưng điều {goi} nhờ {xung} muốn biết dùng vào việc gì."},{"who":"A","text":"{Xung} hứa giữ gìn cẩn thận, dùng xong sẽ trả ngay. {Xung} xin ghi ơn {goi}."},{"who":"me","text":"Một lời mượn là một chút niềm tin trao đi. Cho mượn vui vẻ, đòi đáp lễ hay khéo từ chối, {xung} phải cân nhắc."}]}},
{"id":"j68:doubtVisit","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng chân dồn dập ngoài sân, rèm cửa bị vén mạnh, {A} bước vào, sắc mặt tái mà đôi mắt sáng như lửa."},{"who":"A","text":"{Goi}, {xung} đến hỏi cho rõ một chuyện. Có người nói {goi} đứng sau lưng {xung} gây chuyện, có đúng không?"},{"who":"me","text":"Lời oan ấy từ đâu ra? {Xung} ngồi trong cung này, chưa từng làm điều gì sau lưng ai."},{"who":"A","text":"Chứng cứ {xung} chưa có, nhưng lòng {xung} đã nghi. Nếu {goi} thật lòng, xin cho {xung} một lời giải thích."},{"who":"me","text":"Lòng nghi đã nặng thì lời giải thích cũng khó nhẹ. Thề thốt minh oan, mời {goi} khám xét hay mặc kệ, {xung} phải chọn một đường."}]}},
{"id":"j68:empWager","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng cười của Hoàng thượng vang lên giữa vườn hoa, gió làm bay vạt áo, ánh mắt ngài sáng lên với niềm vui hiếm hoi."},{"who":"A","text":"{Goi}, {xung} bày một cuộc vui nho nhỏ, {goi} có muốn thử không? Ai thắng, {xung} sẽ ban thưởng."},{"who":"me","text":"Cuộc vui của {goi} lúc nào cũng khiến {xung} vừa vui vừa lo. Thắng thì sao, thua thì sao?"},{"who":"A","text":"Thắng thì có thưởng, thua thì cũng chỉ một tiếng cười. Cuộc đời đã đủ nặng, hôm nay cứ nhẹ đi một lần."},{"who":"me","text":"Cược lớn cho {goi} vui, cược nhỏ giữ chừng mực hay đứng xem mà khen, mỗi đường đều có chỗ hay. {Xung} cần chọn cho khéo."}]}},
{"id":"j68:empDream","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn hắt lên gương mặt trầm tư của Hoàng thượng, giấc mơ đêm qua dường như còn vương trong đáy mắt."},{"who":"A","text":"Đêm qua {xung} mơ một giấc kỳ lạ. Sáng ra nghĩ mãi không thôi, nên muốn kể {goi} nghe."},{"who":"me","text":"Cứ kể, {xung} nghe. Giấc mơ lớn đến đâu cũng chỉ là bóng của lòng người."},{"who":"A","text":"Có người bảo là điềm lành, có người bảo điềm xấu. {Xung} muốn biết {goi} thấy thế nào."},{"who":"me","text":"Một giấc mơ mà hỏi trúng lòng người. Giải theo hướng lành, khuyên {goi} chớ tin hay xin lập đàn cầu an, {xung} phải chọn lời cho hợp."}]}},
{"id":"j68:empOldFlame","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gian phòng chìm trong yên lặng, chỉ còn tiếng nến nổ lách tách, Hoàng thượng nhìn về nơi xa như đang gọi một cái tên."},{"who":"A","text":"Hôm nay {xung} bỗng nhớ về một người đã xa. Có những điều chưa nói với ai, chỉ nói được với {goi}."},{"who":"me","text":"Người ấy hẳn đã để lại nhiều thương nhớ. {Goi} muốn nói, {xung} xin nghe."},{"who":"A","text":"{Xung} cứ thấy đâu đây có bóng dáng người ấy. Hay chỉ là {xung} đa cảm?"},{"who":"me","text":"Một câu hỏi đặt giữa ký ức và hiện tại, khó đáp biết bao. Lắng nghe an ủi, cố giống người cũ hay lảng sang chuyện khác, {xung} phải nghĩ kỹ."}]}},
{"id":"j68:kidTutor","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng đọc sách từ thư phòng vọng sang lúc cao lúc thấp, giữa các giọng quen có một giọng nhỏ cứ ngắt quãng."},{"who":"M","text":"Bẩm {goi}, thầy dạy ở thư phòng vừa gửi lời, nói về việc học của {A}. Thầy muốn {goi} biết trước khi chuyện đến tai nơi khác."},{"who":"me","text":"Con ta học hành thế nào, thầy nói thẳng đi. Ta không muốn nghe lời quanh co."},{"who":"M","text":"Dạ, thầy bảo {A} có lúc thông minh hơn người, có lúc lơ đễnh. Cần có người nhắc nhở đúng cách."},{"who":"me","text":"Tự kèm con, biếu thầy nhờ dạy kỹ hay nghiêm khắc răn dạy, mỗi cách đều ảnh hưởng đến tâm tính con. Ta phải chọn lối hợp với con ta."}]}},
{"id":"j68:kidLie","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"{B} quỳ trước cửa, vai run lên từng đợt, đôi mắt sưng đỏ mà vẫn cố gượng nhìn thẳng vào người trong cung."},{"who":"B","text":"{Goi}, {xung} xin thề không làm điều ấy. Ai cũng bảo là lỗi của {xung}, {xung} không biết kêu ai."},{"who":"me","text":"Ngươi nói là bị oan, mà người nói ngược lại lại là {A}, con ta. Chuyện này ta không thể đoán bừa."},{"who":"B","text":"{Xung} không dám trách {A}, chỉ mong {goi} phân xử cho công bằng."},{"who":"me","text":"Con còn nhỏ nên dễ nói sai, người hầu thì dễ chịu oan. Tra cho rõ, bênh con hay dạy con tự nhận lỗi, ta phải cân nhắc kỹ."}]}},
{"id":"j68:servHero","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dấu vết của một đêm không yên còn vương trong cung, {A} đứng đó, tóc rối, áo lấm lem, vẫn cố đứng thẳng lưng."},{"who":"A","text":"{Goi}, {xung} làm việc vì bổn phận, không dám nhận công. Chỉ mong cung yên ổn là {xung} mãn nguyện."},{"who":"me","text":"Ngươi làm việc lớn mà nói nhẹ như không. Ta nghe cung nhân kể, đêm qua nếu không có ngươi thì chuyện đã khác."},{"who":"A","text":"{Xung} chỉ may mắn phát hiện kịp. Ai ở đó cũng sẽ làm như vậy."},{"who":"me","text":"Không phải ai cũng làm được. Thưởng hậu, nhắc lên làm người thân cận hay tra xem có kẻ gây ra, ta phải nghĩ cho trọn."}]}},
{"id":"j68:rumorTH","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng thì thầm lan từ Đức Thọ cung qua từng dãy hành lang, càng đi xa càng thêm lời mới."},{"who":"M","text":"Bẩm {goi}, trong cung đang đồn chuyện Thái hậu nhắc đến {goi}. Người nói tốt, người nói xấu, {xung} không biết tin ai."},{"who":"me","text":"Lời đồn về Thái hậu nặng hơn lời đồn thường. Ngươi nghe từ miệng ai?"},{"who":"M","text":"Dạ, từ các cung nữ qua lại. Không ai chắc, nhưng ai cũng nói như đã chắc."},{"who":"me","text":"Hỏi ma ma thân tín, sang thỉnh an ngay hay bỏ ngoài tai, mỗi đường đều có lợi có hại. Ta phải chọn một đường."}]}},
{"id":"j68:rumorFavor","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lời đồn về chuyện ân sủng bay khắp lục cung, mỗi cung nhân kể lại một kiểu, nghe lúc mừng lúc lo."},{"who":"M","text":"Bẩm {goi}, cung nhân đang đồn về chuyện Hoàng thượng và {goi}. Người nói vui, người nói buồn."},{"who":"me","text":"Lòng vua khó đoán, lời đồn lại càng khó đoán. Ngươi có biết kẻ nào tung tin không?"},{"who":"M","text":"Dạ, {xung} chỉ thấy ai cũng nhắc mà không ai biết gốc từ đâu."},{"who":"me","text":"Mua tin từ Kính sự phòng, làm như không nghe hay tìm kẻ tung tin, mỗi cách đều phải trả giá. Ta cần cân nhắc."}]}},
{"id":"j68:lotusSeason","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương sen thoang thoảng lan từ hồ vào tận hiên cung, {A} bước vào, trên tay còn vương chút sương mát."},{"who":"A","text":"{Goi}, sen đang độ đẹp nhất. {Xung} nghĩ ra một trò vui, mong {goi} cùng tham gia."},{"who":"me","text":"Cảnh đẹp mà có người cùng ngắm thì vui gấp đôi. Trò của {goi} là gì?"},{"who":"A","text":"Chỉ cần {goi} gật đầu là {xung} lo liệu hết. Đi một chuyến, nhìn hoa, làm một chút việc nhỏ rồi về."},{"who":"me","text":"Nghe thì nhẹ nhàng, nhưng nước hồ sâu mà lòng người còn sâu hơn. Đi cùng, cùng làm hay từ chối khéo, {xung} phải nghĩ kỹ."}]}},
{"id":"j68:droughtPrayer","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mặt đất nứt như lòng bàn tay người già, bầu trời trắng đục không một gợn mây, ngay cả tiếng chim cũng thưa đi."},{"who":"M","text":"Bẩm {goi}, hạn hán kéo dài, Hoàng thượng lo lắng. Trong cung có lệnh tiết kiệm, ai cũng phải chịu thiếu."},{"who":"me","text":"Trời không mưa thì dân đói, vua lo thì cung cũng không yên. Ta có thể làm gì để giúp?"},{"who":"M","text":"Dạ, {xung} nghĩ chép kinh cầu đảo cũng là lòng thành. Hoặc {goi} chia bớt phần của mình cho người hầu."},{"who":"me","text":"Chép kinh, bớt phần mình hay tìm cách riêng, mỗi cách đều có giá. Ta phải chọn cách hợp đạo lý nhất."}]}},
{"id":"j68:officialWife","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc kiệu nhỏ dừng ngoài cổng cung, một vị phu nhân y phục chỉnh tề bước xuống, theo sau là mấy gói quà bọc lụa."},{"who":"M","text":"Bẩm {goi}, có một vị phu nhân trong triều đến cung, xin gặp {goi}. Vị ấy mang theo lễ vật, nói có việc nhờ cậy."},{"who":"me","text":"Người ngoài triều vào cung nhờ vả, ắt là việc không nhỏ. Vị phu nhân ấy nói rõ việc gì chưa?"},{"who":"M","text":"Dạ, vị ấy chỉ nói cần {goi} giúp một lời, còn chi tiết xin được thưa trực tiếp."},{"who":"me","text":"Giúp hay không giúp, nhận quà hay không nhận, mỗi lựa chọn đều ảnh hưởng đến danh tiếng ta. Ta phải cân nhắc cho kỹ."}]}},
{"id":"j68:envoyGift","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp gấm mở ra dưới ánh sáng, vật lạ từ phương xa nằm giữa lớp lụa, khiến ai nhìn cũng phải chớp mắt một lần."},{"who":"M","text":"Bẩm {goi}, Hoàng thượng ban xuống vật quý từ sứ thần. Cả lục cung đều có phần, nhưng phần của cung {xung} đến sớm nhất."},{"who":"me","text":"Ân điển đến sớm, người khác nhìn vào sẽ nghĩ nhiều. Ngươi có nghe cung nhân bàn gì không?"},{"who":"M","text":"Dạ, có người mừng, có người ghen. {Xung} chỉ thấy vật này không phải thứ tầm thường."},{"who":"me","text":"Tạ ơn rồi chia cho người hầu, thử tài trước sứ thần hay xin giữ làm của riêng, ta phải chọn cách vừa lòng mình vừa lòng người."}]}},
{"id":"j68:q6coldRice","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc bát sứt mẻ đặt trên bậc cửa lãnh cung, cháo loãng đã nguội, mùi ẩm mốc lẫn trong hơi sương sớm."},{"who":"M","text":"Bẩm {goi}, phần được cấp cho lãnh cung hôm nay lại thiếu. Việc ấy do người của {A} lo."},{"who":"me","text":"Lãnh cung vốn đã đạm bạc, bớt thêm nữa thì ta với ngươi lấy gì qua ngày?"},{"who":"M","text":"Dạ, {xung} sẵn lòng chịu đói, nhưng {goi} sức yếu, {xung} không đành."},{"who":"me","text":"Dúi bạc cho họ, chia phần ít ỏi cho mọi người hay nhịn mà chép kinh, ta phải chọn cách nào giữ được lòng người lẫn thân mình."}]}},
{"id":"j68:q6coldMate","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lạnh luồn qua khe cửa lãnh cung, bóng người đứng ngoài hiên run rẩy trong tấm áo mỏng, tay áp vào song gỗ."},{"who":"A","text":"{Goi}, {xung} làm phiền {goi} một chút. Đêm nay lạnh quá, {xung} không chịu nổi, nên mạo muội gõ cửa."},{"who":"me","text":"Cùng ở nơi lạnh lẽo, {xung} hiểu nỗi khổ ấy. Vào đây đi, {goi} đừng đứng ngoài gió."},{"who":"A","text":"{Xung} cảm kích lắm. Ở nơi này, chỉ có người cùng cảnh mới thông cảm cho nhau."},{"who":"me","text":"Nghe tiếng {goi} khẽ run, {xung} cũng nặng lòng. Chia chăn ngồi cùng, nghe chuyện cũ dò tin hay đóng cửa giữ sức, {xung} phải nghĩ xem nên làm gì."}]}},
{"id":"j68:q6coldTake","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chỗ để đồ ngoài hiên trống trơn, chỉ còn vệt ẩm trên nền gạch và một đôi dấu chân nhỏ in trên bụi."},{"who":"M","text":"Bẩm {goi}, thứ để ngoài hiên đã không còn. {Xung} hỏi quanh, có người thấy {A} đi ngang đó."},{"who":"me","text":"Một thứ nhỏ nhoi thôi, nhưng ở nơi này, mất đi là mất cả phần sống qua ngày."},{"who":"M","text":"Dạ, {xung} nghĩ {A} cũng khổ, chỉ là lấy mà không nói trước. Không biết {goi} định xử trí thế nào?"},{"who":"me","text":"Đòi lại thì thêm oán, lấy bù thì thêm tội, bỏ qua thì thương người cùng cảnh. Ta phải chọn một đường để lòng không hổ thẹn."}]}},
{"id":"j68:q6coldGloat","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tà áo gấm quét qua ngưỡng cửa lãnh cung, hương phấn thơm nồng lấn át mùi ẩm mốc, nụ cười nơi khóe môi vừa ngọt vừa lạnh."},{"who":"A","text":"{Goi}, ăn ngủ ở đây có quen không? {Xung} vẫn thường nhớ đến {goi}, không biết {goi} có nhớ {xung} không."},{"who":"me","text":"{Goi} đến tận nơi này chỉ để hỏi một câu như thế. Hẳn là nhớ {xung} lắm."},{"who":"A","text":"Tất nhiên rồi. Người cũ sa cơ, ai chẳng muốn đến xem một lần cho đỡ nhớ."},{"who":"me","text":"Lời nói mềm mà nhọn như kim. Nhẫn nhục dụ {goi} lỡ lời, mắng trả cho hả giận hay quỳ xin nương tay, {xung} phải chọn một lối giữ được mình."}]}},
{"id":"j68:q6coldLetter","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh giấy gấp nhỏ nằm trong lòng bàn tay run run, giấu kỹ sau tay áo như một mầm hy vọng."},{"who":"A","text":"{Goi}, {xung} có cách đưa tin ra ngoài, tuy liều nhưng có thể thử. {Goi} có muốn viết thư không?"},{"who":"me","text":"Ngươi dám liều vì ta, ta cảm động lắm. Nhưng nếu bị bắt thì sao?"},{"who":"A","text":"{Xung} đã nghĩ kỹ. Ở nơi này, ngồi yên cũng là chết dần, chi bằng thử một lần."},{"who":"me","text":"Lòng trung của ngươi ta ghi nhận. Nhờ đưa thư, giữ ngươi lại không cho liều hay thưởng chút bạc cuối cùng, ta phải cân nhắc kỹ."}]}},
{"id":"j68:q6coldWinter","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tuyết dày phủ kín mái ngói lãnh cung, gió bấc lùa qua khe cửa, tiếng ho khô khan vọng sang từ gian phòng bên."},{"who":"M","text":"Bẩm {goi}, {A} ở phòng bên bệnh nặng rồi. Cả dãy lãnh cung ai cũng nghe tiếng ho mà không ai dám lại gần."},{"who":"me","text":"Trời rét thế này, người yếu sao chống nổi. Ta với {A} cùng ở một nơi rét buốt, nghe tiếng ho lòng cũng không nỡ."},{"who":"M","text":"Dạ, {xung} cũng thấy tội. Nhưng áo bông của {goi} cũng chẳng dày hơn bao nhiêu."},{"who":"me","text":"Cởi áo đắp cho người, xin lính gác ít than hay lo thân mình trước, mỗi đường đều là một tấm lòng. Ta phải chọn đường nào mình không hối."}]}},
{"id":"j68:q6visitCold","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bức tường lãnh cung xám lạnh nằm im cuối con đường vắng, sau lớp gạch ấy có người đang nhắc đến một cái tên."},{"who":"M","text":"Bẩm {goi}, có tin từ lãnh cung về {A}. Nàng muốn gặp {goi} một lần, hoặc ít nhất có người nhắc đến."},{"who":"me","text":"{A} là người ta đưa vào đó, nghe tin nàng, ta không thể thờ ơ."},{"who":"M","text":"Dạ, {xung} nghĩ {goi} nên đi xem. Nhưng cũng cần liệu trước, vì người ta đang nhìn."},{"who":"me","text":"Đến xem nàng, gửi áo ấm không lộ mặt hay dò xem nàng còn giữ gì, mỗi lối đều có tính toán riêng. Ta phải chọn cho khéo."}]}},
{"id":"j68:q6srvCredit","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lời khen vang trong sân như một chiếc áo đẹp, khoác lên vai người không phải kẻ đã cắt may nó."},{"who":"A","text":"{Goi}, {xung} biết {goi} nghĩ gì. Nhưng việc đã đến thế, nói ra chỉ thêm rối, {goi} cũng nên giữ hòa khí."},{"who":"me","text":"Việc {xung} làm, công người khác nhận. {Xung} đâu phải đá mà không thấy chua xót."},{"who":"A","text":"{Xung} biết, nhưng chốn này công lao thường về người biết nói. Mong {goi} thông cảm."},{"who":"me","text":"Nhịn cho yên, tâu thật với {B} hay nhận luôn phần việc để khỏi sinh sự, mỗi đường đều có giá riêng. {Xung} phải chọn cho khéo."}]}},
{"id":"j68:q6srvMood","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đèn trong phòng chập chờn như tâm trạng người ngồi bên án, chén trà trên bàn nguội từ lâu mà chưa ai dám động tay."},{"who":"A","text":"{Xung} không biết vì sao trong lòng cứ bực bội mãi. {Goi} lại gần đây, đừng đứng ngoài đó."},{"who":"me","text":"Dạ, {xung} xin hầu. Xin {goi} cứ nói, {xung} nghe."},{"who":"A","text":"Nói ra cũng chẳng ai giúp được. Chỉ là {xung} muốn có người ở bên, đừng bỏ đi."},{"who":"me","text":"{Xung} sẽ ở lại. Thức hầu đến sáng, nhờ bếp lo việc riêng hay dỗ khéo vài câu rồi lui, {xung} phải chọn cách vừa sức mình."}]}},
{"id":"j68:q6srvQuan","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thùng nước nặng đặt giữa sân, tiếng cười nhạt của quản sự vang lên khô khốc, kẻ không có lệ phải đi con đường xa nhất."},{"who":"A","text":"{Goi} mới vào, chưa biết lệ chỗ này. Ai biết điều thì việc nhẹ, ai không thì gánh nặng, đừng trách {xung}."},{"who":"me","text":"{Goi}, {xung} làm việc thật lòng, không dám trái lệ. Chỉ là bạc của {xung} chẳng được bao nhiêu."},{"who":"A","text":"Lệ là lệ, {xung} chỉ làm theo. {Goi} nghĩ kỹ rồi hẵng nói."},{"who":"me","text":"Lệ ấy nghe mà nặng lòng. Đút bạc cho yên, làm cật lực chẳng kêu hay tố lên chủ nhân, {xung} phải chọn một đường."}]}},
{"id":"j68:q6srvPass","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng bước chân đều đặn vang trên hành lang, màu áo vàng thoáng hiện ở đầu dãy, cung nhân ai cũng cúi đầu im bặt."},{"who":"A","text":"{Goi} đứng đó làm gì? Ngẩng lên, nói cho {xung} nghe {goi} là người cung nào."},{"who":"me","text":"Dạ, {xung} hầu ở nơi này, không dám làm phiền thánh giá. Xin {goi} thứ tội."},{"who":"A","text":"Không phải tội. Chỉ là {xung} thấy {goi} lạ mặt, nên hỏi một câu."},{"who":"me","text":"Một câu hỏi của bậc chí tôn có thể đổi cả đời người. Cúi đầu đúng phép, đáp khéo một câu hay lánh đi, {xung} phải chọn trong một hơi thở."}]}},
{"id":"j68:q6hhLate","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi thỉnh an sớm ở Khôn Ninh cung, ai nấy đều yên vị, chỉ riêng {A} khiến cả điện phải để tâm."},{"who":"A","text":"{Goi}, {xung} đến muộn, mong {goi} thứ lỗi. Việc riêng làm {xung} chậm chân, thật không phải."},{"who":"me","text":"Lục cung đều đủ mặt, riêng {goi} khiến mọi người chờ. {Xung} nghe đây, {goi} có lý do gì?"},{"who":"A","text":"{Xung} có điều khó nói, không tiện giải thích giữa chốn đông người."},{"who":"me","text":"Lý do khó nói thì nghe riêng cũng được. Phạt trước lục cung, khoan dung nhắc nhẹ hay gặp riêng hỏi rõ, {xung} cần cân nhắc."}]}},
{"id":"j68:q6hhLedger","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ dày đặt trên án, nét chữ chi chít, mỗi con số như một cái bẫy nhỏ hay một lời thật chờ người đọc."},{"who":"A","text":"Bẩm {goi}, sổ lục cung đã đưa lên, xin {goi} xem qua. Có chỗ chưa khớp, {xung} xin được giải thích."},{"who":"me","text":"Sổ sách không nói dối, nhưng người chép sổ thì có thể. Chỗ nào chưa khớp, ngươi nói rõ."},{"who":"A","text":"Dạ, theo {xung} thì do chép nhầm. {Xung} xin {goi} xét cho."},{"who":"me","text":"Chép nhầm hay cố ý, ta cần xem cho tường tận. Tự tra từng trang, giao cho ngươi lo hay xử cách khác, ta phải chọn đường chính đáng."}]}},
{"id":"j68:q6hhJudge","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng cãi vã chưa dứt đã vọng đến sảnh chính, hai người đứng hai bên, mỗi người một ánh mắt, đều chờ người phân xử."},{"who":"A","text":"{Goi}, {B} và {xung} có chuyện không thể tự giải quyết. Xin {goi} xử cho công bằng."},{"who":"me","text":"Hai người cùng đến, tức là cùng muốn có lẽ phải. {Xung} nghe, {goi} nói trước."},{"who":"A","text":"Chuyện này {B} có lỗi, {xung} chỉ muốn lẽ phải được rõ. Xin {goi} đừng thiên vị."},{"who":"me","text":"Lời một phía chưa đủ. Xử theo lý tra cho rõ, nghiêng về một bên hay hòa giải mỗi người một bước, {xung} phải chọn đường công tâm nhất."}]}},
{"id":"j68:q6hhRite","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nghi trượng đã sắp ngay ngắn dọc hành lang, mùi hương trầm lan trong gió, lễ lớn sắp đến mà việc còn dồn đống."},{"who":"M","text":"Bẩm {goi}, lễ lớn sắp đến, Thái hậu và các cung đều chờ xem {goi} lo liệu. Việc nhiều, người lo chưa đủ."},{"who":"me","text":"Lễ là mặt mũi của cả hậu cung, không thể để sơ suất. Ngươi nghĩ ta nên làm thế nào?"},{"who":"M","text":"Dạ, {xung} nghĩ {goi} tự lo thì chu đáo nhưng mệt. Hoặc nhờ {B} phụ giúp cũng được."},{"who":"me","text":"Tự lo trọn lễ, giao phần việc cho {B} hay bỏ bạc làm thật lớn, mỗi đường đều có giá. Ta phải chọn cách xứng với lễ này."}]}},
{"id":"j68:q6hhAccused","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng chuông Đức Thọ cung vọng sang trong buổi chiều lặng, báo hiệu một cuộc đối chất không thể từ chối."},{"who":"M","text":"Bẩm {goi}, Thái hậu cho gọi {goi} sang Đức Thọ cung. Nghe nói có người đã tâu lên chuyện của {goi}."},{"who":"me","text":"Người tâu lên là {A}, đúng không? Thái hậu đã nghe những gì?"},{"who":"M","text":"Dạ, {xung} chỉ biết {A} đã quỳ ở Đức Thọ cung từ sáng. Còn lời tâu cụ thể thì chưa rõ."},{"who":"me","text":"Đối chất trước Thái hậu, nhận lỗi hay chối đều có hậu quả. Nhận lỗi, một mực chối hay bù đắp cho {A}, ta phải nghĩ trước khi bước vào."}]}},
{"id":"j68:q6hhNew","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tân nhân quỳ thành hàng trước điện, áo mới còn thơm hương, ánh mắt vừa rụt rè vừa tò mò lướt qua chốn cung cấm."},{"who":"A","text":"{Goi}, {xung} mới vào cung, nhiều điều còn chưa biết. Mong {goi} chỉ bảo cho."},{"who":"me","text":"Người mới vào ai cũng bỡ ngỡ. {Goi} cứ yên tâm, có {xung} ở đây."},{"who":"A","text":"{Xung} sợ làm sai điều gì, lại sợ không có chỗ nương. Được {goi} che chở, {xung} yên lòng hơn."},{"who":"me","text":"Lời xin ấy thật lòng, {xung} nghe mà thương. Tự dạy lễ nghi, ban lễ kéo về phía mình hay thử tài trước lục cung, {xung} phải chọn cách thích hợp."}]}},
{"id":"j68:q6hhSick","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hương thuốc quấn trong gió, cửa sổ cung người bệnh khép hờ, tiếng ho khẽ vọng ra rồi chìm xuống."},{"who":"M","text":"Bẩm {goi}, {A} bệnh đã mấy hôm. Cung bên ấy báo tình hình chưa khá, theo lệ thì {goi} nên hỏi han."},{"who":"me","text":"Người đang đau yếu, lục cung nhìn vào cũng là nhìn ta. Thái y {B} đã xem chưa?"},{"who":"M","text":"Dạ, đã sai người đến nhưng chưa rõ kết quả. {Goi} muốn tự mình đến hay sai người thay?"},{"who":"me","text":"Tự sang thăm, sai thái y đem thuốc quý hay chỉ sai người hỏi han, mỗi cách đều là một tấm lòng. Ta phải chọn cách vừa tình vừa lễ."}]}},
{"id":"j70:j70c-poison-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới hiên chiều muộn, cung nữ cúi đầu bước vội, ống tay áo còn vương mùi men nồng của hoa cúc."},{"who":"M","text":"{Goi}, nô tỳ có điều không dám giấu. Ngoài cửa cung có kẻ đặt mua một vò rượu hoa cúc ở quán phố Nam, niêm kín rồi cất riêng trong gian kho nhỏ."},{"who":"me","text":"Rượu hoa cúc vốn là món quý dịp lễ, sao lại phải cất riêng cho kín như vậy? Ta nghe mà thấy lạnh sống lưng."},{"who":"M","text":"Còn nữa, có người sai dò xem {goi} hay uống loại rượu nào trong tiệc. Nô tỳ nghĩ vò ấy là dành cho {goi}."},{"who":"me","text":"Vậy là có kẻ đã tính sẵn chén rượu của ta từ lâu. Ngươi dẫn ta tới gian kho ấy, ta phải tận mắt nhìn vò rượu đó."}]}},
{"id":"j70:j70c-poison-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ánh đèn dầu hắt lên đôi đũa bạc sáng như sương, cung nữ nắm chặt vạt áo, giọng nhỏ như hơi thở."},{"who":"M","text":"{Goi}, nô tỳ thấy một cung nữ lạ giấu thứ gì dài dài trong ống tay áo. Nghe nói có người thuê thợ bạc phố Tây đúc một đôi đũa giống hệt đôi của {goi}."},{"who":"me","text":"Đôi đũa bạc vốn để thử độc, nay lại có kẻ muốn đúc thêm một đôi giống hệt. Lòng ta vừa tức vừa sợ."},{"who":"M","text":"Nếu đũa giả thay đũa thật, bạc kia có nhúng vào độc cũng chẳng đổi sắc. {Xung} sợ {goi} ăn mà không hay biết."},{"who":"me","text":"Thế thì đôi đũa ấy chính là dấu vết. Ngươi nói rõ nàng cung nữ lạ kia ở đâu, ta muốn tìm ra tay áo giấu nó."}]}},
{"id":"j70:j70c-poison-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hơi sâm bốc lên từ chung sứ trắng, thơm ngọt nhưng cung nữ lại nhíu mày như ngửi thấy điều chẳng lành."},{"who":"M","text":"{Goi}, tối qua nô tỳ thấy có người hỏi thái y cách hầm sâm cho kẻ ốm yếu, rồi bưng một chung sâm lạ sang cung bệnh."},{"who":"me","text":"Một chung sâm hầm sứ trắng từ Ngự thiện phòng, nghe thì đáng ơn nghĩa, sao ngươi lại lo lắng?"},{"who":"M","text":"Vì chung sâm ấy nô tỳ không thấy ai chịu nhận là của mình. Bã sâm còn lại đang nằm ở Thái y viện, chỉ chờ người xem."},{"who":"me","text":"Sâm vốn để bồi bổ, nếu bị pha lạ thì thành điều đáng sợ. Ngươi đem bã sâm kia ra, ta muốn nghe thái y nói lời thật."}]}},
{"id":"j70:j70c-poison-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới gốc ngọc lan lúc nhá nhem, hương hoa thoảng qua mà cung nữ chỉ nhìn chằm chằm vào bàn tay mình."},{"who":"M","text":"{Goi}, nô tỳ thấy một cung nữ bên cung kia gặp người lạ dưới gốc ngọc lan, rồi hôm sau tóc nàng cài thêm một chiếc trâm bạc mới."},{"who":"me","text":"Một cung nữ nghèo bỗng có trâm bạc, ắt phải có người trả công. Ta nghĩ đến nước rửa tay thường ngày mà rùng mình."},{"who":"M","text":"Bình đồng đựng nước rửa tay lấy từ kho cung kia, nay còn nằm trong phòng nàng. Nô tỳ không dám tự ý chạm vào."},{"who":"me","text":"Nàng ấy chỉ là kẻ bị sai bảo, ta không nỡ trách. Ngươi nói thật xem, nàng có sợ hãi hay đã quen tay làm việc ấy?"}]}},
{"id":"j70:j70c-poison-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Phố Đông rộn ràng sắp hội đèn, nhưng trong tiệm nến lại có một gói giấy đỏ được cất riêng, kín như bí mật."},{"who":"M","text":"{Goi}, thợ làm nến phố Đông kể rằng gần đây nhận một đơn nến thơm rất lạ, gói riêng bằng giấy đỏ để đem tặng."},{"who":"me","text":"Nến thơm đem tặng đêm hội đèn vốn là lễ nghĩa thường tình. Cớ sao ngươi nghe xong lại lo lắng đến thế?"},{"who":"M","text":"Vì món quà ấy lẻ loi quá, nô tỳ nghe nói có cây nến còn chưa đốt đã được đem đến Thái y viện giữ lại."},{"who":"me","text":"Nếu ánh nến cũng thành lưỡi dao, thì đêm hội đèn sẽ chẳng còn là đêm vui. Ngươi đứng đó, kể ta nghe cho hết."}]}},
{"id":"j70:j70c-poison2-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong gian phòng khóa kín, lá thơm phơi cạnh khung cửa, mùi hắc nhè nhẹ lẫn vào hương hoa thêu."},{"who":"M","text":"{Goi}, tiệm may phố Tây vừa may một chiếc gối nhồi lá thơm, thêu hoa rất công phu, lá nhồi lại được sấy riêng trong phòng khóa kín."},{"who":"me","text":"Chiếc gối đẹp như thế, ai nhìn cũng khen. Nhưng ngươi kể bằng giọng nghiêm trọng, ta biết còn điều khác."},{"who":"M","text":"Gối an thần vốn đặt đầu giường, người ngủ hít lá cả đêm mà chẳng hay. Nô tỳ thấy chuyện này không thể xem thường."},{"who":"me","text":"Ngủ say giữa mùi hương lạ thì thật đáng sợ. Ngươi nói tiếp, chiếc gối ấy hiện đang ở đâu?"}]}},
{"id":"j70:j70c-poison2-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trên bàn thư phòng, thỏi mực dở còn ướt, mùi hắc bốc lên khi cung nữ nghiêng đầu nhìn nghiên."},{"who":"M","text":"{Goi}, nô tỳ thấy kẻ kia mua thỏi mực lạ ở hiệu phố Bắc, mài ra mùi hắc. Giấy bút còn bị nhúng nước lạ rồi hong khô trong phòng kín."},{"who":"me","text":"Ta ngày ngày cầm bút chép kinh, nếu mực giấy có độc thì mỗi nét chữ đều là vết thương. Ngươi thấy tận mắt chứ?"},{"who":"M","text":"Nô tỳ thấy thỏi mực còn dở nằm trong thư phòng của người ấy, thấy cả giấy bút đem hong. Nô tỳ không dám nói bừa."},{"who":"me","text":"Cầm bút mà cũng phải đề phòng, ta nghĩ mà thấy chua xót. Dẫn ta xem đống giấy bút ấy ngay."}]}},
{"id":"j70:j70c-poison2-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp thuốc ngậm nằm yên trong tủ gỗ ở Thái y viện, dấu ấn đỏ còn rõ nhưng nắp đã khác màu."},{"who":"M","text":"{Goi}, có người xin thái y bài thuốc ngậm trị ho rồi thêm một vị khác. Hộp vẫn in dấu Thái y viện, nhưng nắp đã được thay mới."},{"who":"me","text":"Thuốc trị ho, ta uống mỗi khi lạnh gió. Dấu in vẫn còn mà nắp đã đổi, thế thì ta biết phân biệt thế nào?"},{"who":"M","text":"Nô tỳ để ý thấy nắp đổi nên không dám đụng. Hộp ấy đã được thu lại, đang nằm trong tủ thuốc Thái y viện."},{"who":"me","text":"Một lớp dấu giả đủ khiến người ta yên tâm, thật đáng sợ. Ngươi đi cùng ta, ta muốn xem hộp thuốc ấy."}]}},
{"id":"j70:j70c-poison2-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cửa hậu hé mở đón gió đêm, cung nữ nép sát tường, tay giữ túi lá thơm xộc mùi thuốc."},{"who":"M","text":"{Goi}, nô tỳ thấy cung nữ hầu tắm của người kia gặp riêng kẻ lạ ở cửa hậu, và nàng ta hay xách thêm một túi lá lạ vào phòng tắm."},{"who":"me","text":"Nước tắm thảo dược vốn để dưỡng người, nếu bị tẩm độc thì thật thành họa. Ta không ngờ đến chuyện ấy."},{"who":"M","text":"Túi lá mua từ chợ thuốc ngoài thành, hiện vẫn còn trong tay cung nữ kia. Nô tỳ nhìn thấy nên mới dám tâu."},{"who":"me","text":"Ngươi làm ta bất an thật. Nói cho ta nghe, nàng cung nữ ấy trông thế nào, có vẻ sợ hãi hay vô tâm?"}]}},
{"id":"j70:j70c-poison2-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp giày kín thơm mùi vải mới, ánh sáng xuyên qua cửa sổ chiếu lên những cánh sen thêu đỏ thắm."},{"who":"M","text":"{Goi}, tiệm thêu phố Nam đang làm một đôi giày hoa sen thật đẹp. Hộp giày kín ấy được chuyền qua nhiều tay rồi mới đem tặng."},{"who":"me","text":"Một đôi giày đẹp thế, ta thấy tên của mình trong ấy rồi. Nhưng sao ngươi lại không vui chút nào?"},{"who":"M","text":"Vì nô tỳ nghĩ, nếu người tặng thật lòng thì đâu phải chuyền nhiều tay như thế. Đôi giày ấy ai cũng chạm mà chẳng ai nhận."},{"who":"me","text":"Hoa sen thêu tươi thế, mà nay ta lại sợ nó. Ngươi tả kỹ cho ta nghe đôi giày ấy đang ở đâu."}]}},
{"id":"j70:j70c-musk-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gói giấy dầu bóng lên trong tay cung nữ, mùi bột ngai ngái như rễ cỏ ẩm sau mưa."},{"who":"M","text":"{Goi}, nô tỳ thấy có người giã ý dĩ và ngưu tất thành bột mịn như bột gạo, gói giấy dầu rồi giấu dưới nệm."},{"who":"me","text":"Ý dĩ, ngưu tất đều là vị thuốc quen, sao lại bị giấu như vật cấm? Ta thấy rợn người."},{"who":"M","text":"Nô tỳ không hiểu thuốc, nhưng chợ thuốc ngoài thành bán loại này, và gói bột đã bị thu giữ, cất ở Thái y viện."},{"who":"me","text":"Một gói bột giấu dưới nệm có thể làm hỏng cả phúc phần của ta. Ngươi đem thái y đến, ta muốn biết rõ."}]}},
{"id":"j70:j70c-musk-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm khuya, hiên cung lạnh như nước giếng, tiếng gió lùa qua cổng nghe như người nấc từng hồi."},{"who":"M","text":"{Goi}, đêm nào quanh hiên cung cũng vọng tiếng khóc than, có đêm nô tỳ thấy bóng áo trắng thoáng hiện bên giếng cổ sau cung."},{"who":"me","text":"Ta tưởng chỉ là gió, nay nghe ngươi nói mới biết đó là tiếng người. Ta có sợ, nhưng cũng thấy giận."},{"who":"M","text":"Bộ áo tang trắng ở kho đồ tang Nội vụ phủ vẫn vắt ở xó kho, ai cũng thấy được. Nô tỳ nghĩ có kẻ mượn áo ấy dọa người."},{"who":"me","text":"Giả ma để dọa ta thì cũng là kẻ nhát gan. Ngươi cùng ta ra hiên đêm nay, ta muốn tận mắt nhìn bóng trắng ấy."}]}},
{"id":"j70:j70c-musk-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau vườn, ánh trăng soi vào chậu đồng, hơi nước còn ấm mà mùi lạ phảng phất không giống mùi ngải cứu."},{"who":"M","text":"{Goi}, cung nữ hầu của người kia dạo này hay pha thêm vị lạ vào nước ngâm chân. Nô tỳ gặp nàng riêng ở sau vườn nên mới biết."},{"who":"me","text":"Nước ngâm chân lẽ ra để ta thư giãn, nay lại thành điều đáng ngờ. Ngươi nói tiếp xem."},{"who":"M","text":"Chậu đồng vẫn nằm trong phòng giặt giũ của nàng ấy, chưa ai dọn đi. Nô tỳ sợ nếu chậm sẽ mất dấu."},{"who":"me","text":"Một chậu nước nhỏ mà chứa cả mưu tính, ta nghĩ tới mà lạnh lòng. Dẫn ta đến phòng nàng ấy ngay."}]}},
{"id":"j70:j70c-musk-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáp đỏ lấp lánh dưới ánh nến, cung nữ nâng hộp nhỏ bằng hai tay như nâng một món nợ chưa trả."},{"who":"M","text":"{Goi}, có người đặt tiệm thuốc phố Bắc làm một lô viên hoàn giống hệt viên của Thái y viện, rồi bọc sáp đỏ rất cẩn thận."},{"who":"me","text":"Viên hoàn an thai là thứ ta uống mỗi ngày để giữ phúc phần. Giống hệt của Thái y viện, vậy ta biết đâu là thật?"},{"who":"M","text":"Hộp còn niêm, hiện được giữ ở Thái y viện. Nô tỳ chỉ sợ khi chưa ai kịp nhìn kỹ, viên giả đã vào tay {goi}."},{"who":"me","text":"Ngươi nói đúng, bảo vệ con trước rồi mới tính chuyện trách ai. Cùng ta đến Thái y viện xem cái hộp ấy."}]}},
{"id":"j70:j70c-musk-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều tà, chén trà sơn tra nghi ngút bốc hơi, vị chua nhẹ đọng nơi đầu lưỡi mà lòng người lại nặng trĩu."},{"who":"M","text":"{Goi}, buổi chiều nào cũng có người mang trà sơn tra sang, bảo là cho ngon miệng. Nô tỳ để ý thấy kẻ ấy còn mua sơn tra khô cả giỏ."},{"who":"me","text":"Ngon miệng, nghe thật ân cần. Ta uống hoài mà chưa từng nghĩ có điều bất thường."},{"who":"M","text":"Giỏ sơn tra khô ấy nằm trong kho nhỏ của họ, ở Nội vụ phủ. Nô tỳ không dám nói mình biết chắc, chỉ thấy lạ quá."},{"who":"me","text":"Ân cần quá mức lại hóa đáng ngờ. Ngươi nhớ kỹ giờ nào trà đến, ta muốn xem thái y nói sao."}]}},
{"id":"j70:j70c-catswap-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giỏ mây ọp ẹp đặt cạnh cửa nhà thuê, tiếng khóc non nớt lọt qua kẽ ván vào buổi sáng sương."},{"who":"M","text":"{Goi}, nô tỳ nghe nói ngoài thành có người nuôi lén một hài nhi sơ sinh ở nhà thuê, sáng nào cũng có người gánh sữa dê đi về phía ấy."},{"who":"me","text":"Một đứa trẻ nuôi lén ngoài thành, lại là sơ sinh... Ta nghe mà thấy lạnh gáy, không biết nên giận hay thương."},{"who":"M","text":"Giỏ mây đựng hài nhi, chợ ngoại thành ai cũng bán. Nô tỳ thấy người gánh sữa dê đi đi về về, đều đặn như người đưa thư."},{"who":"me","text":"Gánh sữa mỗi sáng là dấu vết rõ nhất. Ngươi nhớ hướng người ấy đi, ta sẽ nghĩ cách lần theo."}]}},
{"id":"j70:j70c-catswap-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cửa phòng sinh đóng im ỉm, chiếc chìa đồng treo ở ngăn kéo lạnh lẽo, cung nữ đứng nép sát vách như sợ hơi thở của chính mình."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng cung nữ giữ cửa phòng sinh. Dạo này nàng ăn mặc tươm tất lạ thường, y phục mới cả áo trong."},{"who":"me","text":"Kẻ giữ cửa phòng sinh bỗng sung túc, hẳn là có người trả công. Ta chỉ sợ ngày sinh đã bị tính trước."},{"who":"M","text":"Chìa dự phòng của cung {xung} nằm trong ngăn kéo của nàng. Nô tỳ không dám lục khi chưa có lệnh {goi}."},{"who":"me","text":"Ngươi làm đúng, đừng đánh động. Nàng chỉ là người bị mua chuộc, ta muốn gọi nàng ra mà hỏi cho rõ."}]}},
{"id":"j70:j70c-catswap-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đèn dầu trong phòng sinh leo lét, ánh sáng hắt lên vách vàng như nước trà nguội, cung nữ nhìn bình dầu mà thở dài."},{"who":"M","text":"{Goi}, có người hỏi thợ đèn hiệu phố Tây về loại dầu cháy nhanh rồi tắt. Dầu thắp trong phòng sinh được thay lần cuối trước kỳ sinh."},{"who":"me","text":"Dầu cháy nhanh rồi tắt, phòng sinh sẽ tối giữa lúc cần sáng nhất. Ta nghĩ đến mà tay lạnh ngắt."},{"who":"M","text":"Bình dầu đèn kém còn dở, đang giữ ở Nội vụ phủ. Nô tỳ nhìn thấy nên mới dám đem chuyện này đến bẩm."},{"who":"me","text":"Tối lúc nguy cấp thì ai mà nhìn rõ mặt ai. Ngươi theo ta ra Nội vụ phủ xem bình dầu ấy."}]}},
{"id":"j70:j70c-catswap-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc tay nải khâu kín nằm lặng im trên bậc cửa cung, gió lướt qua mà không làm nó động đậy."},{"who":"M","text":"{Goi}, có một ni cô ở chùa nhỏ ngoại thành thường được mời vào cung. Mỗi lần đến, nàng đều mang theo chiếc tay nải khâu kín."},{"who":"me","text":"Ni cô vào cung tụng kinh cầu phúc thì có gì lạ. Nhưng sao ngươi lại nhắc tay nải khâu kín?"},{"who":"M","text":"Vì nô tỳ chưa từng thấy ai mở nó ra. Tay nải ấy hiện được niêm lại, giữ ở Nội vụ phủ."},{"who":"me","text":"Một túi khâu kín giữa lúc ta gần ngày sinh, ta thấy bất an khó tả. Ngươi kể tiếp, nàng thường đi cửa nào?"}]}},
{"id":"j70:j70c-catswap-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong góc bếp phụ, chung canh sứ xanh đã nguội ngắt, hơi nước đọng thành giọt nhỏ bên thành chung."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đưa chung canh ấm cho bà đỡ trước giờ vào phòng sinh. Đến cung rồi, bà ngủ gà ngủ gật mãi."},{"who":"me","text":"Bà đỡ cầm mạng sống của hai mẹ con, vậy mà lại ngủ gật. Ta nghe mà vừa sợ vừa thương bà."},{"who":"M","text":"Chung canh sứ xanh từ Ngự thiện phòng, còn dở trong bếp phụ. Nô tỳ giữ lại chưa ai đụng đến."},{"who":"me","text":"Ngươi giữ đúng việc, đừng để ai dọn đi. Ta muốn nhờ thái y xem chung canh đó."}]}},
{"id":"j70:j70c-kpoison-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sắc đỏ của bộ thú gỗ chói mắt dưới nắng, nhưng cung nữ chỉ ngửi thấy mùi hắc lẫn trong lớp sơn mới khô."},{"who":"M","text":"{Goi}, có người đặt thợ mộc phố Tây làm bộ thú gỗ sơn màu rực rỡ, nô tỳ ngửi thấy sơn đỏ pha bột lạ, mùi hắc lắm."},{"who":"me","text":"Con ta rất thích thú gỗ, ôm cả khi ngủ. Nghĩ đến chuyện nó đưa lên miệng cắn, ta rụng rời."},{"who":"M","text":"Bộ đồ chơi đã bị niêm, giữ ở Nội vụ phủ. Nô tỳ thấy tận mắt, nên mới không dám giấu {goi} một khắc nào."},{"who":"me","text":"May mà ngươi tinh ý. Hãy dẫn ta đến xem thú gỗ ấy, ta muốn biết vì sao kẻ đó dám ra tay với trẻ thơ."}]}},
{"id":"j70:j70c-kpoison-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trại dê ngoại thành mờ sương, tiếng chuông đeo cổ dê leng keng, một chiếc xe sữa lặng lẽ lăn về phía cung."},{"who":"M","text":"{Goi}, nô tỳ nghe nói có người sai nuôi một đàn dê ở trại ngoại thành, sữa dê ấy lại được đưa vào cung theo một lối riêng."},{"who":"me","text":"Sữa dê là thứ con ta uống mỗi sáng. Lối riêng, nghe đã thấy không phải chuyện bình thường."},{"who":"M","text":"Có cả bình sữa còn dở, đã giao Thái y viện giữ. Nô tỳ chỉ biết sữa không đến theo lối của Ngự thiện phòng."},{"who":"me","text":"Chỗ nào có người lén lút thì chỗ ấy có điều gian. Ngươi cùng ta tính xem phải chặn xe sữa ấy thế nào."}]}},
{"id":"j70:j70c-kpoison-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lọ thuốc nhỏ bóng loáng nằm trong tủ Thái y viện, nút gỗ mới còn nguyên vân sáng như vừa tiện xong."},{"who":"M","text":"{Goi}, nô tỳ hỏi thái y thuốc bôi trị mẩn ngứa cho trẻ nhỏ thì thấy có kẻ cũng hỏi. Lọ thuốc bôi sau đó bỗng đổi nút gỗ mới."},{"who":"me","text":"Một chiếc nút gỗ thay đi, ta mới nhớ lọ thuốc cũ sạm màu. Ta thật không để ý tới điều này."},{"who":"M","text":"Lọ ấy đã bị thu hồi, giữ ở Thái y viện. Nô tỳ nghĩ có người muốn mượn thuốc của thái y để ra tay."},{"who":"me","text":"Thuốc trị bệnh mà lại thành thuốc hại, ta đau lòng nhiều hơn là giận. Ngươi dẫn ta đến nơi lọ thuốc ấy."}]}},
{"id":"j70:j70c-kpoison-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới hiên lễ đầy tháng, bộ vòng bạc nhỏ xinh lấp lánh nằm yên trong hộp gấm, không ai ngờ nó từng chìm trong thuốc đen."},{"who":"M","text":"{Goi}, có người đặt thợ bạc phố Đông khắc một bộ vòng chân nhỏ dịp lễ. Nô tỳ nghe nói bộ vòng được ngâm cả đêm trong chậu thuốc đen."},{"who":"me","text":"Vòng bạc tặng trẻ thơ vốn là lễ nghĩa quý giá. Nghĩ đến chuyện kẻ nào đó dám tẩm độc vào, tim ta thắt lại."},{"who":"M","text":"Bộ vòng ấy đã bị thu giữ, cất ở Thái y viện. Nô tỳ thấy rõ thợ bạc cũng không biết mình đã giao hàng cho ai."},{"who":"me","text":"Một món quà đầy tháng mà đầy tâm kế. Ngươi cùng ta tới Thái y viện, ta muốn tự tay nhìn bộ vòng."}]}},
{"id":"j70:j70c-kpoison-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Quả dại đỏ tươi bày lẫn trong rổ trái cây, đẹp như viên ngọc, nhưng cung nữ cầm lên mà tay run run."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hái quả dại màu đỏ tươi ở góc vườn hậu, rửa sạch rồi bày lẫn với trái cây dâng ngự."},{"who":"me","text":"Quả đỏ tươi đẹp mắt như vậy, con ta nhìn thấy ắt sẽ đòi nhặt. Ta không dám nghĩ tiếp."},{"who":"M","text":"Rổ quả ấy nô tỳ đã thu, cất ở Thái y viện. Chỉ sợ người ta còn bày thêm một rổ khác lúc không ai để ý."},{"who":"me","text":"Chuyện trẻ nhỏ thì không thể chậm một canh giờ. Ngươi nói cho ta nghe, góc vườn hậu ấy thế nào?"}]}},
{"id":"j70:j70c-pond-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bến hồ sương còn đọng trên ván, một chiếc thuyền nan cũ dập dềnh nhẹ, sáp trét đáy mờ như vết sẹo."},{"who":"M","text":"{Goi}, có người đem thả chiếc thuyền nan cũ ở bến hồ. Nô tỳ nhìn kỹ thấy đáy thuyền bị khoét một lỗ nhỏ rồi trét sáp lại."},{"who":"me","text":"Thuyền nan trên hồ, con ta ắt thích lắm. Ngươi nói một lỗ nhỏ trét sáp, ta nghe mà lạnh cả ngực."},{"who":"M","text":"Thuyền ấy đã được kéo lên bờ, giữ ở Nội vụ phủ. Nô tỳ nghe nói nó từ bến sửa thuyền ngoài thành."},{"who":"me","text":"Một lỗ nhỏ có thể thành chuyện lớn. Ngươi đừng giấu gì nữa, nói hết những gì mắt ngươi đã thấy."}]}},
{"id":"j70:j70c-pond-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sân hồ chiều nắng nhạt, lông trắng của chú chó con thoắt ẩn thoắt hiện giữa đám trẻ cười đùa."},{"who":"M","text":"{Goi}, nô tỳ thấy có người nuôi một chú chó con lông trắng rất hiếu động, rồi thả lẫn vào đám trẻ đi chơi quanh hồ."},{"who":"me","text":"Chó con chạy nhảy, trẻ con đuổi theo. Nhìn thì vui mắt, nhưng nghĩ đến mép hồ ta lại thấy sợ."},{"who":"M","text":"Chó ấy từ chợ chó ngoại thành, nay đã được trả về người nuôi. Nô tỳ biết người thả chính là kẻ lạ mặt, không phải người trong cung."},{"who":"me","text":"Vậy chó chỉ là mồi nhử. Ngươi dẫn ta đến chỗ người nuôi chó ngoại thành, ta muốn hỏi nó từ đâu ra."}]}},
{"id":"j70:j70c-pond-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tủ giày của hoàng tự mở hé, đôi giày cũ biến mất để lại chỗ trống như một chiếc răng mất."},{"who":"M","text":"{Goi}, tiệm giày phố Tây vừa may một đôi giày đế nhẵn thín giống đôi cũ của hoàng tự, rồi đôi giày cũ biến khỏi tủ lúc không ai để ý."},{"who":"me","text":"Đế giày nhẵn thì trượt chân là chuyện sớm muộn, nhất là ở bờ nước ướt. Ta nghe đến đó mà đau lòng."},{"who":"M","text":"Đôi giày cũ nô tỳ tìm được giấu ở kho Nội vụ phủ. Nô tỳ nghĩ kẻ đó đã tính từng bước chân của hoàng tự."},{"who":"me","text":"Lòng người sâu như đáy hồ. Ngươi cùng ta lục lại tủ giày, ta muốn biết còn đôi nào bị đổi nữa không."}]}},
{"id":"j70:j70c-pond-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên bờ ao, chiếc vợt tre cắm nghiêng, bóng tre in dài trên mặt nước, trẻ nhỏ cười ríu rít chờ buổi chiều."},{"who":"M","text":"{Goi}, đám trẻ con thị vệ gần đây được cho kẹo ngọt, lại dặn rủ hoàng tự ra bờ ao. Mỗi buổi chiều chúng tụ tập bên hồ."},{"who":"me","text":"Kẹo ngọt dỗ trẻ, kẻ lớn dùng trẻ để dỗ trẻ. Ta nghe mà chua xót."},{"who":"M","text":"Chiếc vợt tre bắt cá cắm bên bờ ao, ai đi qua cũng thấy, nhưng không ai biết là từ sạp đồ tre chợ Đông."},{"who":"me","text":"Đám trẻ không có tội, chỉ là quân cờ. Ngươi gọi chúng ra cho ta, ta muốn hỏi ai đưa kẹo."}]}},
{"id":"j70:j70c-pond-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm hoa đăng, mặt hồ rực như một bầu trời ngược, những cánh sen giấy nối nhau trôi, lũ trẻ chen nhau ra mép nước."},{"who":"M","text":"{Goi}, có người đặt hàng chục chiếc đèn hoa đăng cánh sen thả xuống hồ. Đèn thả dày khiến lũ trẻ chen nhau ra mép nước."},{"who":"me","text":"Hoa đăng đẹp thế, trẻ nào mà chẳng muốn chạm. Ta bỗng thấy ánh đèn đáng sợ hơn cả đêm tối."},{"who":"M","text":"Có chiếc đèn trôi dạt vào bờ, nô tỳ nhặt về Nội vụ phủ. Xưởng đèn phố Đông bảo chỉ bán theo đơn đặt."},{"who":"me","text":"Hội đẹp mà mưu cũng đẹp. Ngươi nói cho ta nghe, đêm ấy bờ hồ có những ai."}]}},
{"id":"j70:j70c-pushp-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Canh khuya, bậc đá ven hồ ngời lên như men sứ dưới trăng, dù bầu trời suốt ngày không một giọt mưa."},{"who":"M","text":"{Goi}, nô tỳ thấy có người xách bình dầu mè đi qua hành lang ven hồ lúc canh khuya. Sáng ra, bậc đá bỗng bóng loáng dù trời không mưa."},{"who":"me","text":"Bậc đá ướt trơn vì dầu, ai bước xuống cũng ngã. Ta quen đi dạo ven hồ mỗi sáng, sao ngươi chỉ nói bây giờ?"},{"who":"M","text":"Nô tỳ nhặt được bình dầu bỏ sau bụi trúc, mang về Nội vụ phủ giữ. Dầu ấy là của bếp phụ Ngự thiện phòng."},{"who":"me","text":"Dầu của bếp lại bôi ra bậc đá, kẻ đó tính kỹ thật. Ngươi dẫn ta xem bậc đá ấy để ta nghĩ cách."}]}},
{"id":"j70:j70c-pushp-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa hồ sen, cây cầu gỗ nhỏ lặng lẽ nằm, ván lót phơi nắng, dây buộc mòn xơ như tóc người già."},{"who":"M","text":"{Goi}, đêm qua nô tỳ thấy có bóng người lén ra cây cầu gỗ bắc qua hồ sen, sáng ra dây buộc ván đã bị cưa gần đứt."},{"who":"me","text":"Cầu gỗ ấy ta vẫn đi qua hằng ngày, chưa bao giờ nghĩ nó có thể là bẫy. Nghĩ đến mà tim ta đập loạn."},{"who":"M","text":"Chiếc cưa nhỏ nô tỳ nhặt được dưới gốc liễu, đã mang về Nội vụ phủ. Nghe nói cưa ấy từ xưởng mộc ngoài thành."},{"who":"me","text":"Vết cưa không biết nói, nhưng chiếc cưa thì có chủ. Ngươi theo ta xem cây cầu ấy, ta muốn tận mắt nhìn."}]}},
{"id":"j70:j70c-pushp-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió vườn thổi hương hoa qua lối nhỏ, nhưng cung nữ chỉ nghe thấy tiếng thở khò khè như của một con thú đói."},{"who":"M","text":"{Goi}, nô tỳ nghe người ta kể có kẻ nuôi một con chó săn bị bỏ đói nhiều ngày, rồi cho nó đánh hơi chiếc khăn của {goi}."},{"who":"me","text":"Khăn của ta bị đem ra làm mồi dẫn chó, đúng là lòng dạ thâm độc. Ta nghe mà lạnh người."},{"who":"M","text":"Con chó săn gầy rạc từ nhà thợ săn ngoại thành, nay đã được dắt trả về. Nô tỳ nhìn thấy nó đi qua cổng cung."},{"who":"me","text":"Chó thì vô tội, kẻ dắt nó mới đáng nói. Ngươi nói thật cho ta nghe, người dắt chó trông thế nào?"}]}},
{"id":"j70:j70c-pushp-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau hòn non bộ, ánh đèn lồng giấy đỏ lay nhẹ, rọi lên vòng ngọc mới trên cổ tay một cung nữ trẻ."},{"who":"M","text":"{Goi}, cung nữ cầm đèn đêm của {goi} được hẹn ra chỗ khuất sau hòn non bộ, nô tỳ thấy nàng hay khoe chiếc vòng ngọc mới."},{"who":"me","text":"Nàng ấy cầm đèn dẫn đường cho ta mỗi đêm, nếu nàng dẫn sai lối thì ta biết tin ai? Ta thấy buồn hơn là giận."},{"who":"M","text":"Chiếc đèn lồng giấy đỏ vẫn treo ở phòng nàng, lấy từ kho đèn của cung {xung}. Nô tỳ chưa dám nói với ai khác."},{"who":"me","text":"Ngươi đã làm đúng, đừng để lộ tiếng. Ta muốn xem rốt cuộc nàng cầm đèn ấy dẫn ta đi đâu."}]}},
{"id":"j70:j70c-pushp-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mặt hồ sen lấp lánh vảy vàng, đàn cá chép quẫy nhẹ, người người nghiêng đầu nhìn mà quên cả bờ nước trơn."},{"who":"M","text":"{Goi}, trong hồ sen vừa thả mấy con cá chép vàng quý hiếm, tin cá lạ được rỉ tai khắp các cung. Ai cũng muốn ra xem."},{"who":"me","text":"Cá quý trong hồ cung, ai chẳng muốn ngắm. Ta cũng từng nghĩ đến chuyện ra bờ hồ buổi chiều."},{"who":"M","text":"Đàn cá ấy từ ao cá phố Nam, vẫn được nuôi trong hồ sen. Nô tỳ nghe người ta rỉ tai nhau, chứ không biết ai là người khởi đầu."},{"who":"me","text":"Tin đồn lan nhanh như gió, ắt có người mong ta ra bờ hồ. Ngươi nói tiếp, đông khách vào lúc nào?"}]}},
{"id":"j70:j70c-kframe-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm đã khuya, ngọn đèn xa chiếu lên miệng hố nhỏ dưới gốc cây cạnh điện Thái hậu, một mảnh vải lấp ló như lưỡi đỏ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đào hố nhỏ dưới gốc cây cạnh điện Thái hậu lúc canh khuya. Miệng hố còn vương mảnh vải áo của hoàng tự."},{"who":"me","text":"Áo của con ta lại bị vứt ở nơi ấy, chạm đến điện Thái hậu. Ta nghe mà ngực nghẹn lại."},{"who":"M","text":"Mảnh vải ấy lấy từ tủ áo của cung {xung}, nô tỳ nhặt về Nội vụ phủ làm tang vật. Nô tỳ không biết kẻ đó trộm bằng cách nào."},{"who":"me","text":"Có người muốn đem áo con ta đặt dưới gốc cây để vu cho ta. Ngươi theo ta đến xem miệng hố ấy."}]}},
{"id":"j70:j70c-kframe-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một chiếc la bàn gỗ quay chậm trong tay thầy địa lý, kim run run rồi chỉ về một cung, ông ta lắc đầu thở dài."},{"who":"M","text":"{Goi}, có người mời thầy địa lý ngoại thành vào cung xem hướng, ông ta chỉ về cung của {goi} rồi lắc đầu, chẳng nói thêm lời nào."},{"who":"me","text":"Chỉ lắc đầu, ai nhìn cũng tưởng cung ta có điềm dữ. Ta thấy tức nhưng cũng thấy sợ."},{"who":"M","text":"La bàn gỗ của ông ta nằm trong nhà, bị thu làm chứng, mua ở phố thầy bói ngoài thành. Nô tỳ thấy rõ điều ấy."},{"who":"me","text":"Lời không nói ra mà thành tiếng đồn, mới khó chống đỡ. Ngươi nói cho ta nghe, ông ta lắc đầu trước những ai."}]}},
{"id":"j70:j70c-kframe-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió sớm lay tấm vải đỏ trong giỏ rác, dưới lớp vải lộ ra mảnh lông nâu nhỏ xíu, vương một vệt máu khô."},{"who":"M","text":"{Goi}, nô tỳ thấy có kẻ bắt chim sẻ trong lồng, đóng đinh nhỏ vào cánh, rồi để xác bọc vải đỏ trong giỏ rác trước cửa."},{"who":"me","text":"Một con chim nhỏ bị hành hạ để dọa người, ta nghe mà thương nó, cũng sợ kẻ nhẫn tâm ấy."},{"who":"M","text":"Xác chim bọc vải đỏ ấy từ chợ chim ngoài thành, nô tỳ đã nhặt khỏi giỏ rác, cất ở Nội vụ phủ. Chưa ai khác nhìn thấy."},{"who":"me","text":"Nếu ai thấy trước ta, người ta sẽ nói là điềm gở của cung này. Ngươi kể kỹ giờ nào giỏ rác đặt ở đó."}]}},
{"id":"j70:j70c-kframe-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khói trầm bảng lảng trên đàn lễ cầu an, mâm lễ nặng hơn thường lệ, tiếng chuông ngân dài như hỏi han người chưa kịp đáp."},{"who":"M","text":"{Goi}, trong lễ cầu an có bà đồng được mời nói chuyện riêng sau điện. Sau đó nô tỳ thấy bà đồng nhận một mâm lễ nặng hơn thường lệ."},{"who":"me","text":"Bà đồng nói điều gì sau điện mà phải tặng nặng như thế? Ta nghĩ lời thần linh đang bị người mượn miệng."},{"who":"M","text":"Mâm lễ ngoài điện đã được thu về Nội vụ phủ. Nô tỳ nghe lời bà ấy chuyền ra ngoài như gió lùa, đều nhắm vào cung {goi}."},{"who":"me","text":"Thần linh giận hay người giận, cũng phải tra cho ra. Ngươi cùng ta tính xem nên hỏi bà đồng ấy thế nào."}]}},
{"id":"j70:j70c-kframe-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tấm vải đen che kín một vật nhỏ nằm im, nhưng góc vải hở lộ ra thớ gỗ đào sáng nhạt như da người."},{"who":"M","text":"{Goi}, nô tỳ nghe nói có kẻ thuê thợ khắc nhỏ ngoài phố khắc một tấm bài vị gỗ đào, bọc kín trong khăn đen, và khắc tên hoàng tự lên đó."},{"who":"me","text":"Bài vị đề tên con ta khi còn sống, trời ơi, ai nghĩ ra được thứ ác độc này? Ta đau lòng đến không thốt nên lời."},{"who":"M","text":"Tấm bài vị ấy đã được tìm ra, cất ở Nội vụ phủ. Nô tỳ biết nó từ xưởng khắc phố Nam."},{"who":"me","text":"Chỉ một mảnh gỗ mà muốn đổ cả tai họa lên đầu ta. Ngươi cho ta xem nó, ta cần nhớ kỹ từng nét khắc."}]}},
{"id":"j70:j70c-frame-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới gốc hòe, đất mới xới còn ẩm, hơi lạnh đêm lẫn mùi gỗ đào, cung nữ cúi gập người thì thầm."},{"who":"M","text":"{Goi}, thợ khắc phố Tây ngoài cung vừa đẽo một hình nhân gỗ nhỏ, viết ngày sinh của {goi} lên lưng. Đêm khuya có bóng người cúi đào đất dưới gốc hòe."},{"who":"me","text":"Hình nhân ghi ngày sinh của ta, chôn dưới gốc hòe, đúng là cách vu người xưa nay. Ta nghĩ mà tay run."},{"who":"M","text":"Hình nhân gỗ đào ấy đào lên rồi, hiện cất ở Kính sự phòng làm chứng. Nô tỳ chỉ nhìn thấy, không dám nói với ai khác."},{"who":"me","text":"Có chứng cứ trong tay, ta mới yên một phần. Ngươi nhắc lại xem, bóng người cúi đào cao thấp thế nào?"}]}},
{"id":"j70:j70c-frame-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tờ giấy vàng gấp nhỏ lộ ra từ tay áo một cung nữ, nét chu sa đỏ như vệt máu mới khô."},{"who":"M","text":"{Goi}, có một đạo cô lạ ra vào cung của {xung}, ở lại rất lâu. Đạo cô đi rồi, tay áo cung nữ lại có tờ giấy vàng gấp nhỏ."},{"who":"me","text":"Đạo cô lạ ra vào, giấy vàng chu sa, nghe đã thấy mùi bùa chú. Ta lo không phải vì bùa, mà vì kẻ vẽ bùa."},{"who":"M","text":"Lá bùa ấy từ đạo quán ngoài thành, hiện nằm trong hồ sơ Kính sự phòng. Nô tỳ ghi nhớ gương mặt đạo cô lúc nàng rời đi."},{"who":"me","text":"Bùa mà giấu dưới gối thì thật là hại người ta không hay biết. Ngươi nói xem, đạo cô ấy từng ngồi ở đâu?"}]}},
{"id":"j70:j70c-frame-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau miếu hoang trong vườn, tro hương còn ấm, khói mỏng cuộn lên như hơi thở của người vừa bỏ đi."},{"who":"M","text":"{Goi}, người dạo vườn thấy tro hương còn ấm sau miếu hoang, khói chưa tan. Họ dựng một bài vị gỗ ghi tên {goi} ở đó."},{"who":"me","text":"Tên ta khắc lên bài vị giữa miếu hoang, ta nghe mà thấy cả người lạnh toát. Là ai mà độc địa vậy?"},{"who":"M","text":"Bài vị ấy làm ở xưởng đồ thờ ngoài cung, nay nằm ở Kính sự phòng. Nô tỳ không thấy ai nhận là đã đặt."},{"who":"me","text":"Vậy là còn kẻ muốn chờ ta sợ mà tự nhận lỗi. Ngươi dẫn ta ra miếu hoang xem tro hương ấy."}]}},
{"id":"j70:j70c-frame-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Am nhỏ ngoài thành tối đen, thẻ tre treo lủng lẳng lách cách trong gió, như đếm từng nhịp tim người nghe."},{"who":"M","text":"{Goi}, có kẻ mời thầy cúng vào cung xem phong thủy, ở lại một đêm. Thầy đi rồi, lời sấm nhắc tên {goi} lan khắp các cung."},{"who":"me","text":"Lời sấm nhắc tên ta, lan khắp các cung, không sai một nhà. Ta biết, thứ gieo vào lòng người là nỗi sợ."},{"who":"M","text":"Thẻ tre ghi lời sấm vẫn ở chỗ thầy cúng, ngoài am nhỏ. Nô tỳ nghe nói chữ trên thẻ không phải chữ của ông ấy."},{"who":"me","text":"Chữ không phải của ông ta, tức là có người đứng sau. Ngươi cùng ta nghĩ cách hỏi cho ra."}]}},
{"id":"j70:j70c-frame-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong đêm tĩnh, chiếc gối thêu mới còn thơm mùi vải, cạnh gối lấp ló ánh bạc mảnh như sợi tóc."},{"who":"M","text":"{Goi}, cung nữ bên cung của {goi} được dúi cho một cây kim bạc dài. Giữa đêm, có chiếc gối thêu mới chuyển vào phòng."},{"who":"me","text":"Kim bạc giấu trong gối thêu, nếu không phát hiện thì thành tội danh nặng nề. Ta nghe mà sợ lạnh."},{"who":"M","text":"Chiếc gối ấy từ tiệm thêu ngoài cung, nằm trong phòng làm tang vật. Nô tỳ chưa dám chạm vào, sợ dính dấu tay."},{"who":"me","text":"Ngươi đã khéo giữ lại. Gọi cung nữ ấy ra cho ta, ta muốn xem nàng nhận kim bạc từ ai."}]}},
{"id":"j70:j70c-plant-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nắp hộp sơn đỏ bóng loáng, nhưng dây buộc lại khác màu với dây cũ, cung nữ nhìn mà thấy lòng chùng xuống."},{"who":"M","text":"{Goi}, có người gói ghém một vật lạ vào hộp lễ vật {goi} sắp dâng. Nô tỳ thấy hộp bị đổi nắp khác, dây buộc cũng khác."},{"who":"me","text":"Hộp dâng lễ mà bị đổi nắp, dây cũng khác, bên trong chắc chẳng chỉ có lễ vật. Ta nghĩ mà bất an."},{"who":"M","text":"Hộp nắp sơn đỏ ấy hiện nằm ở Nội vụ phủ, chờ tra xét. Nô tỳ không dám tự mở, sợ mang tiếng."},{"who":"me","text":"Mở hộp ra trước hay để người khác mở, đều là nước cờ. Ngươi đi cùng ta xem, ta cần nhìn tận mắt trước."}]}},
{"id":"j70:j70c-plant-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hội đèn đêm ấy, kho Nội vụ phủ sáng mờ, thái giám canh kho mồ hôi nhễ nhại bên chiếc hộp rỗng."},{"who":"M","text":"{Goi}, một viên ngọc bội trong kho biến mất, thái giám canh kho toát mồ hôi. Nô tỳ thấy kẻ lạ lảng vảng quanh cung {goi} lúc hội đèn."},{"who":"me","text":"Ngọc bội mất, kẻ lạ lảng vảng quanh cung ta. Nghe đến đó, ta đã đoán có người định đưa nó vào rương ta."},{"who":"M","text":"Ngọc bội của Hoàng thượng nay đã thu về Nội vụ phủ. Nô tỳ nghĩ chuyện chưa kết thúc, vì kẻ lấy chưa lộ mặt."},{"who":"me","text":"Ngọc của Hoàng thượng mà để vào tay ta thì khó mà biện bạch. Ngươi nhớ lại kẻ lạ ấy trông ra sao."}]}},
{"id":"j70:j70c-plant-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bọc bột lạ nằm lặng trên bàn, mùi nhè nhẹ như hương cỏ úa, chiếc khóa mới của hòm thuốc lóe sáng bên cạnh."},{"who":"M","text":"{Goi}, có kẻ mua lén một bọc bột lạ ở hiệu thuốc phố Đông. Nô tỳ thấy hòm thuốc của {goi} đổi khóa, chìa nằm trong tay kẻ khác."},{"who":"me","text":"Hòm thuốc là chỗ ta cất thuốc quý, nay chìa không còn trong tay ta. Nghĩ đến, ta chợt thấy rợn."},{"who":"M","text":"Bọc bột lạ ấy nô tỳ đã đem nghiệm ở Thái y viện, họ bảo chưa thể kết luận. Nô tỳ chỉ biết nó không phải của cung {xung}."},{"who":"me","text":"Một bọc bột lạ cũng đủ viết nên tội danh. Ngươi nói rõ xem, ai đã đổi khóa hòm thuốc?"}]}},
{"id":"j70:j70c-plant-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiệm may ngoài phố tối om, cây kim còn cắm dở trên mảnh áo, thợ may nhìn tay mình mà run rẩy."},{"who":"M","text":"{Goi}, có người đặt may một chiếc áo, dặn thợ khâu thêm một vật vào lớp lót. Thợ may nhận bạc xong, tay run khi cuộn vải."},{"who":"me","text":"Một vật khâu trong lớp lót, tức là người ta muốn giấu thứ gì trên người ta. Ta nghe mà lạnh lòng."},{"who":"M","text":"Chiếc áo lót khâu bùa nay giữ ở Kính sự phòng làm chứng. Nô tỳ nghe thợ may thì thào, chứ chưa ai tra hỏi thẳng."},{"who":"me","text":"Thợ may sợ nên run, nghĩa là hắn biết điều gì. Ngươi cùng ta nghĩ cách hỏi hắn cho khéo."}]}},
{"id":"j70:j70c-plant-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chồng khăn giặt thơm mùi nắng, trong nếp gấp lấp ló một túi thơm thêu hoa sen, đẹp quá nên khiến người nghi ngờ."},{"who":"M","text":"{Goi}, nô tỳ thấy có kẻ gặp riêng cung nữ bên giặt đồ, đưa một túi thơm nhỏ. Túi thơm lạ lẫn trong chồng khăn đem sang cung {goi}."},{"who":"me","text":"Túi thơm hoa sen thêu khéo thế, ai nhìn cũng khen. Nhưng lẫn trong khăn giặt, thì hẳn là có ý đồ."},{"who":"M","text":"Túi thơm ấy từ tiệm thêu phố Bắc, hiện nằm trong rương của {goi}. Nô tỳ chưa dám động đến."},{"who":"me","text":"Ta cũng không muốn động đến, kẻo dính tay. Gọi cung nữ giặt đồ ra, ta muốn hỏi nàng nhận túi từ ai."}]}},
{"id":"j70:j70c-bribe-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Miếu thổ địa nhỏ bên đường, nhang tàn rơi xuống đất vụn, cung nữ nhớ rõ cái dáng kẻ hầu đi vào lúc sớm và trở về lúc xế."},{"who":"M","text":"{Goi}, có một kẻ hầu cung khác xin ra ngoài đốt hương ở miếu nhỏ. Trở về, tay áo nàng nặng hơn lúc đi."},{"who":"me","text":"Đốt hương một mình, về lại nặng tay áo, nghĩ thôi cũng thấy lạ. Ta không dám đoán, ngươi cứ nói."},{"who":"M","text":"Túi bạc vụn gói vải xanh, nô tỳ thấy trong rương nàng, đồng bạc từ một tiền trang ngoài cung."},{"who":"me","text":"Bạc ấy không phải bạc nàng kiếm được. Ngươi nhớ kỹ giờ nàng đi và giờ nàng về, ta cần biết."}]}},
{"id":"j70:j70c-bribe-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới ngọn đèn tiền trang phố Bắc, tờ văn tự bị xé đôi, mảnh giấy bay lên rồi rơi xuống như tuyết tàn."},{"who":"M","text":"{Goi}, có người cho một kẻ hầu vay bạc rất dễ, không hỏi ngày trả. Sau đó, văn tự vay bị xé bỏ ngay trước mặt kẻ hầu."},{"who":"me","text":"Cho vay mà không đòi, xé luôn văn tự, ân huệ đến lạ thường. Ta nghĩ nợ tình khó trả hơn nợ bạc."},{"who":"M","text":"Văn tự ấy bản gốc còn ở tiền trang phố Bắc. Nô tỳ nghe họ nói nhỏ, kẻ hầu kia từ đó chẳng dám ngẩng mặt."},{"who":"me","text":"Nợ đã xóa thì biết lấy gì mà đòi, ngoài lòng trung thành. Ngươi nói tiếp xem, kẻ hầu ấy là ai?"}]}},
{"id":"j70:j70c-bribe-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mùi thuốc bổ thơm lan ngoài ngõ nghèo, thang thuốc quý đặt trên bậc cửa, người mẹ già nằm trong nhà nghe tiếng chân khách."},{"who":"M","text":"{Goi}, một kẻ hầu cung khác có mẹ già bệnh nặng, có người hỏi thăm rồi mang thang thuốc quý đến tận nhà nàng."},{"who":"me","text":"Một thang thuốc quý đủ cứu một người già, ơn nghĩa này nặng hơn cả bạc. Ta thương người, mà cũng lo cho ta."},{"who":"M","text":"Đơn thuốc ghi trong sổ Thái y viện, nô tỳ nhìn thấy dấu đó. Nó là thang thuốc bổ, mua rất tốn kém."},{"who":"me","text":"Ơn nghĩa như vậy ràng buộc hơn cả bạc vàng. Ngươi đừng nóng, nói rõ cho ta nghe nàng là ai."}]}},
{"id":"j70:j70c-bribe-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Góc tường cổng cung tối bóng người, chiếc ủng da của thị vệ phồng lên một chỗ lạ, lụa mịn thoáng ló ra."},{"who":"M","text":"{Goi}, nô tỳ thấy thị vệ gác cổng nhận gói lễ nhỏ rồi cất vào ủng. Sau đó, kẻ hầu cung khác được thị vệ gọi ra góc tường."},{"who":"me","text":"Gói lễ trong ủng, người hầu bị gọi ra nơi khuất, nghe như kẻ qua tay kẻ để chuyển lời. Ta thấy bất an."},{"who":"M","text":"Gói lễ lụa ấy sau nằm trong rương kẻ hầu, nô tỳ đoán nó từ kho riêng của người ra tay."},{"who":"me","text":"Một cánh cổng, hai người trao tay, mà đã thành đường dây. Ngươi nói thật, người gác cổng ấy là ai?"}]}},
{"id":"j70:j70c-block-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khay thẻ bài ở Kính sự phòng sáng ánh ngà, một chỗ trống lõm như ô răng bị nhổ, thái giám cúi lục từng ngăn."},{"who":"M","text":"{Goi}, thẻ bài của {goi} bỗng không còn trên khay lật thẻ. Thái giám khay thẻ lục khắp ngăn mà chẳng thấy."},{"who":"me","text":"Thẻ bài mất đúng buổi ta cần được lật. Ta không giận vì chiếc thẻ, mà giận kẻ muốn ta lỡ buổi hầu."},{"who":"M","text":"Về sau thẻ bài ngà được tìm ra ở ngăn kẹt Kính sự phòng. Nô tỳ thấy rõ ràng, thẻ không tự rơi vào đó."},{"who":"me","text":"Thẻ không có chân, ắt có người đã cầm tay. Ngươi theo ta xem chỗ ngăn kẹt, ta muốn biết ai ra vào."}]}},
{"id":"j70:j70c-block-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Thư phòng Thái hậu nhàn nhạt mùi trầm, tờ tâu xin tụng kinh trải ngay ngắn, dấu ấn thái giám chùa còn mới như vừa đóng."},{"who":"M","text":"{Goi}, có người nhỏ giọng tâu xin cho {goi} vào chùa nhỏ trong cung tụng kinh. Tờ tâu ấy có dấu ấn của thái giám chùa."},{"who":"me","text":"Xin cho ta đi tụng kinh, nghe như lòng thành, mà thực ra là muốn giữ chân ta khỏi chốn khác. Ta hiểu rồi."},{"who":"M","text":"Tờ tâu nay lưu ở Kính sự phòng. Nô tỳ nghĩ nét mực ấy không phải do thái giám chùa tự viết."},{"who":"me","text":"Ai xin, ai viết, ai đóng dấu, ba việc ba người. Ngươi nhớ lại cho kỹ rồi nói cùng ta."}]}},
{"id":"j70:j70c-block-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khâm thiên giám đèn sáng trắng đêm, tờ ghi ngày giờ kỵ nằm giữa bàn, đầu bút đỏ rung nhẹ như chưa quyết."},{"who":"M","text":"{Goi}, có người mời thầy tướng vào cung xem ngày giờ cho nhiều cung, nhưng riêng với {goi}, thầy tâu ngày ấy phạm kỵ."},{"who":"me","text":"Cung nào cũng được ngày lành, riêng ta là ngày kỵ. Ta nghe mà thấy trớ trêu hơn là sợ."},{"who":"M","text":"Tờ ghi ngày giờ kỵ còn lưu ở Khâm thiên giám. Nô tỳ nhớ rõ, thầy tâu xong thì liếc về phía một cung nữ."},{"who":"me","text":"Ngày kỵ hay không kỵ, ta chưa biết, nhưng ai dặn thầy tâu thì ta phải biết. Ngươi nói về cung nữ ấy."}]}},
{"id":"j70:j70c-block-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm sâu, đèn trong phòng chủ cháy đến tàn, cung nữ lau bàn thật khẽ như sợ làm động chuyện gì chưa kịp nói ra."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng cung nữ bên cung {goi}, dặn nói khéo lúc hầu hạ. Hôm nay nàng cứ khuyên {goi} nghỉ sớm, bảo trông mệt mỏi."},{"who":"me","text":"Khuyên ta nghỉ sớm, lời nghe êm tai, nhưng vì sao đêm nay lại cứ khuyên? Ta thấy có ý nằm sau lời ấy."},{"who":"M","text":"Nô tỳ không dám nói là nàng có tội, chỉ thấy tối nay nàng nhắc lời ấy đến lần thứ ba."},{"who":"me","text":"Nhắc ba lần thì chẳng phải vô tình nữa rồi. Ngươi thử nghĩ xem, ai đã dặn nàng?"}]}},
{"id":"j70:j70c-rumor-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sân sau thái giám ríu rít tiếng trẻ, câu hát ngộ nghĩnh đưa qua đưa lại, nghe thì vui mà lời nghe lại như dao."},{"who":"M","text":"{Goi}, đám trẻ con thái giám hát một câu đồng dao lạ ở sân sau, vần nghe ngộ nghĩnh nhưng nhắc đúng tên {goi}."},{"who":"me","text":"Đồng dao nhắc tên ta, ta nghe mà chẳng cười được. Trẻ nhỏ hát vô tư, người dạy mới đáng nói."},{"who":"M","text":"Tờ chép lời đồng dao do một thư lại ở Nội vụ phủ viết, hiện nằm ở Kính sự phòng. Nô tỳ nghe lỏm được vần ấy ngoài vườn."},{"who":"me","text":"Từ tờ chép mà truyền thành tiếng hát, kẻ đó khéo thật. Ngươi hát lại cho ta nghe đúng từng chữ."}]}},
{"id":"j70:j70c-rumor-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giỏ hoa lan tươi mát đặt nơi hiên, hương thoang thoảng, bà bán hoa nhỏ giọng kể như đang tặng thêm một đóa."},{"who":"M","text":"{Goi}, một bà bán hoa quen mặt được gọi vào cung biếu hoa. Bà ấy kể chuyện riêng của {goi} cho cung nữ nghe."},{"who":"me","text":"Bà bán hoa mà biết chuyện riêng của ta, hẳn có ai thì thầm cho bà ấy. Ta nghe thấy mất vui."},{"who":"M","text":"Giỏ hoa lan từ vườn hoa ngoài phố, nay còn ở cung của người ra tay. Nô tỳ đứng gần, nghe rõ từng câu."},{"who":"me","text":"Hoa thì thơm, lời thì độc. Ngươi nhớ bà ấy kể những điều gì, để ta biết ai đã mớm lời."}]}},
{"id":"j70:j70c-rumor-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hòm thư gần cung Thái hậu lặng lẽ giữa canh ba, ba bức thư không đề tên nằm sát nhau như ba chiếc lá cùng cành."},{"who":"M","text":"{Goi}, có người thuê một nho sinh nghèo viết ba bức thư không đề tên, bỏ vào hòm thư gần cung Thái hậu lúc canh ba."},{"who":"me","text":"Ba bức thư gửi đến Thái hậu, nhắm đúng ta, nghĩ đến đã thấy nặng lòng. Không tên người viết, ai biết đường mà chối?"},{"who":"M","text":"Bức thư không đề tên nay nằm trong tay ma ma Thái hậu. Nô tỳ biết nho sinh ấy ở ngoài thành, nghèo đến nỗi nhận bạc là viết."},{"who":"me","text":"Nét chữ nghèo không giấu được nét chữ thuê. Ngươi nói về nho sinh ấy, ta muốn biết tìm hắn thế nào."}]}},
{"id":"j70:j70c-rumor-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sân khấu trong cung đèn sáng lung linh, mặt nạ vai hề lấp ló sau màn, tiếng cười khúc khích vang lên ngay khi vai ấy bước ra."},{"who":"M","text":"{Goi}, gánh hát trong cung bỗng đổi vở, có một vai giống hệt {goi}. Cung nữ cười khúc khích mỗi khi vai ấy bước ra sân khấu."},{"who":"me","text":"Một vai hề giống hệt ta, cười trên sân khấu giữa vườn cung. Ta thấy nhục mà không thể làm ầm."},{"who":"M","text":"Mặt nạ vai hề cất ở hậu trường, nô tỳ đã thấy tận mắt. Còn người viết vở thì nô tỳ chưa biết."},{"who":"me","text":"Người cười thì dễ, người viết mới đáng nói. Ngươi nhớ mấy cung nữ cười, ta cần biết họ thuộc cung nào."}]}},
{"id":"j70:j70c-accuse-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sổ chi lương dày cộm nằm trên giá ở Nội vụ phủ, một trang bị lật lên rồi lại gập xuống, thư lại giữ cuốn sổ cúi mặt."},{"who":"M","text":"{Goi}, có người xin xem sổ chi lương của cung {goi} ở Nội vụ phủ, rồi chép lại từng khoản vào sổ riêng."},{"who":"me","text":"Chép từng khoản vào sổ riêng, ý ắt không phải để học cách ghi sổ. Ta thấy kẻ ấy đang tìm kẽ hở nơi ta."},{"who":"M","text":"Sổ chi lương vẫn còn lưu ở Nội vụ phủ, nô tỳ đã hỏi. Thư lại nói người ấy xin xem không có giấy phép."},{"who":"me","text":"Xin xem không giấy phép, mà thư lại vẫn cho, vậy cũng là có người đứng sau. Ngươi cùng ta nghĩ xem hỏi thế nào."}]}},
{"id":"j70:j70c-accuse-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bờ hồ sau cung buổi chiều lặng, một góc khăn lụa còn vương vệt mực đen loang như bóng mây, nằm trên bàn của người lạ."},{"who":"M","text":"{Goi}, chiếc khăn rơi của {goi} đã có người nhặt, nhờ thợ nhuộm xem vết lạ. Thợ nhuộm bảo khăn từng nhúng vào thứ mực lạ."},{"who":"me","text":"Khăn ta rơi bên hồ, nay thành vật trong tay kẻ khác. Mực lạ lên khăn lụa của ta, ta nghĩ đến thôi cũng thấy ấm ức."},{"who":"M","text":"Chiếc khăn có vết mực nay giữ ở cung của người tố, làm tang vật. Nô tỳ nghe nói họ định dùng nó để vu cho {goi}."},{"who":"me","text":"Khăn của ta mà thành chứng cứ chống lại ta, thật là trò khéo. Ngươi nói cho ta biết, ai nhặt khăn."}]}},
{"id":"j70:j70c-accuse-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Phòng canh cổng chong đèn dầu, cuốn sổ ghi ra vào xòe trang, một dòng chữ mới còn ướt, thái giám đứng chờ bên cạnh."},{"who":"M","text":"{Goi}, thái giám canh cổng ghi thêm giờ ra vào của {goi} vào sổ, ghi xong thì đứng chờ ai đó tới lấy bản chép."},{"who":"me","text":"Giờ ra vào của ta, có người thêm vào sổ. Ta thấy như bị theo dấu giữa ban ngày."},{"who":"M","text":"Sổ ghi ra vào cổng cung vẫn lưu ở phòng canh cổng. Nô tỳ không biết người tới lấy bản chép là ai."},{"who":"me","text":"Một bản chép trao tay mà thành mưu kế. Ngươi nói rõ giờ nào thái giám ấy ghi, ta sẽ đối với giờ ta đi."}]}},
{"id":"j70:j70c-accuse-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài hiên, cung nữ lạ đứng im như tượng, tay nắm chặt vạt áo, mắt cứ ngó vào hộp thư mà chẳng chịu quay đi."},{"who":"M","text":"{Goi}, một lá thư không đề tên được gửi đến cung {goi} qua tay cung nữ lạ. Nàng ấy đứng chờ ngoài hiên, nhất định không chịu về."},{"who":"me","text":"Thư không tên mà người đưa không chịu đi, rõ là đợi hồi âm. Ta đọc thư ấy mà lòng thấy nặng."},{"who":"M","text":"Lá thư mồi giờ nằm trong hộp thư, nô tỳ nghe nói từ bàn viết của người đang muốn tố cáo {goi}."},{"who":"me","text":"Thư mồi là để ta mắc câu, nếu ta trả lời. Ngươi nói tiếp, cung nữ lạ ấy đứng chờ từ lúc nào?"}]}},
{"id":"j70:j70c-ksab-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Thư phòng hoàng tự đêm khuya, một đốm đèn nhỏ chớp tắt giữa giá sách, bộ Tứ thư chép tay thiếu mất mấy cuốn."},{"who":"M","text":"{Goi}, sách của hoàng tự bỗng thiếu mất mấy cuốn ở thư phòng. Đêm đến, nô tỳ thấy có người lẻn vào, cầm đèn nhỏ."},{"who":"me","text":"Mấy cuốn Tứ thư chép tay của con ta, đứa trẻ ấy đã thức đêm chép cẩn thận. Ta thương nó hơn là giận."},{"who":"M","text":"Nô tỳ nghe nói sách đã bị giấu trong rương ở cung người ra tay. Người cầm đèn nhỏ ấy thì nô tỳ chưa thấy mặt."},{"who":"me","text":"Giấu sách, chặn đường học của con ta, nhỏ nhặt mà độc ác. Ngươi cùng ta tính xem canh thư phòng thế nào."}]}},
{"id":"j70:j70c-ksab-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ấm trà an thần bốc hơi nhè nhẹ, mùi thảo mộc đặc hơn thường lệ, trên bàn sách hoàng tự gục đầu ngủ quên bên trang chữ."},{"who":"M","text":"{Goi}, ấm trà an thần mấy hôm nay nấu đặc hơn thường lệ, đêm xem sách hoàng tự ngáp luôn, mắt díu lại."},{"who":"me","text":"Con ta ngày thường thức khuya học bài không biết mệt, sao nay buồn ngủ đến thế? Ta xót cho nó."},{"who":"M","text":"Gói lá an thần ấy nô tỳ thấy ở Thái y viện, rồi lại thấy ở cung người ra tay. Nô tỳ không hiểu vì sao có hai nơi."},{"who":"me","text":"Một chén trà hóa thành sợi dây trói tâm trí con trẻ. Ngươi đừng vội, cho ta nghe kỹ từ khi nào ấm trà thay đổi."}]}},
{"id":"j70:j70c-ksab-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp bánh hạt sen đặt trên bàn học, nắp mở hé, hương ngọt dịu mà chỗ ngồi cạnh hoàng tự lại trống như vừa bị bỏ rơi."},{"who":"M","text":"{Goi}, con của một cung khác thường mang bánh sang cho hoàng tự. Mấy hôm sau, người đồng môn ấy bỗng lảng tránh hoàng tự."},{"who":"me","text":"Trẻ con chơi với nhau, hôm trước còn mang bánh, hôm sau đã tránh mặt. Ta thấy như có bàn tay nào đẩy."},{"who":"M","text":"Hộp bánh hạt sen nay nằm ở chỗ đồng môn, nô tỳ biết bánh làm ở bếp riêng của người ra tay."},{"who":"me","text":"Tình bạn con trẻ bị đem ra làm quân cờ, ta thấy chua xót. Ngươi nói xem, đồng môn ấy lảng tránh vào lúc nào."}]}},
{"id":"j70:j70c-ksab-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cửa thư phòng khép hờ, bóng một thái giám lạ in dài trên nền gạch, tờ chép bài giảng nằm trong tay áo rộng."},{"who":"M","text":"{Goi}, có thái giám lạ đứng sát cửa thư phòng nghe suốt buổi giảng, hôm sau lại nhắc từng câu hoàng tự đọc sai."},{"who":"me","text":"Lỗi nhỏ của trẻ thơ mà có người ghi nhớ từng câu, như bắt lỗi để đem ra làm chuyện. Ta không chịu nổi."},{"who":"M","text":"Tờ chép bài giảng nằm trong tay thái giám ấy, nô tỳ thấy tận mắt. Chữ trên tờ ấy không phải chữ của thầy giảng."},{"who":"me","text":"Chữ không phải của thầy, là của kẻ nghe lén. Ngươi nói cho ta biết mặt người ấy."}]}},
{"id":"j70:j70c-joint-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước cửa cung vắng người, bóng vài kẻ hầu lần lượt đi qua, mỗi người mang một việc nhỏ, chẳng ai nhìn ai."},{"who":"M","text":"{Goi}, mỗi người trong phe nhận một việc nhỏ, không ai làm trọn. Họ còn thay phiên nhau canh cửa cung {goi}."},{"who":"me","text":"Mỗi người một việc nhỏ, chẳng ai làm trọn thì chẳng ai chịu tội trọn. Cách làm này thật khôn ngoan, và thật đáng sợ."},{"who":"M","text":"Nô tỳ để ý đã mấy hôm, thấy người canh cửa đổi mặt mỗi buổi. Nô tỳ không nghe rõ họ nói gì với nhau."},{"who":"me","text":"Đổi mặt mỗi buổi, vậy thì khó nhận ra ai là người cầm đầu. Ngươi nhớ từng gương mặt, kể cho ta nghe."}]}},
{"id":"j70:j70c-joint-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tượng Phật trong am nhỏ nhìn xuống bằng mắt từ bi, khói hương lượn lờ, tiếng thề thì thầm vang vọng giữa không gian lặng."},{"who":"M","text":"{Goi}, người trong phe rủ nhau đến am nhỏ trong cung thắp hương. Nô tỳ nghe một lời thề được đọc vang trước tượng Phật."},{"who":"me","text":"Thề trước Phật mà để hại người, thật là tội. Ta nghe mà thấy lòng chùng xuống."},{"who":"M","text":"Bài văn thề có bản sao nằm ở người cầm đầu phe. Nô tỳ không biết trong bài ghi những ai."},{"who":"me","text":"Một lời thề làm họ buộc vào nhau hơn bạc vàng. Ngươi nói thật cho ta, có kẻ nào trong họ ngập ngừng không?"}]}},
{"id":"j70:j70c-joint-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cổng cung xế bóng, một ma ma lặng lẽ rời cửa, túi vải nhỏ nặng trĩu bên hông, bước chân đều như đã quen đường."},{"who":"M","text":"{Goi}, mỗi người trong phe trích ít bạc đưa cho một ma ma. Ma ma ấy ra ngoài cung một chuyến rồi trở về."},{"who":"me","text":"Mỗi người góp một ít bạc, giao cho một người ra ngoài cung. Ta nghĩ họ muốn thuê người ngoài làm việc."},{"who":"M","text":"Túi bạc góp chung vốn từ rương người cầm đầu phe, nay đã chuyển cho người ngoài cung. Nô tỳ thấy ma ma về mà tay không."},{"who":"me","text":"Về tay không, vậy là bạc đã tới nơi cần tới. Ngươi nhớ kỹ ma ma ấy đi cửa nào, về cửa nào."}]}},
{"id":"j70:j70c-joint-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khung thêu bỏ dở cạnh cửa sổ, chỉ màu rũ xuống như tóc mưa, tiếng thì thầm kéo dài mãi trong cung chiều muộn."},{"who":"M","text":"{Goi}, người trong phe rủ nhau đến một cung thêu khăn ban chiều. Khung thêu bỏ đó, tiếng thì thầm kéo dài cả buổi."},{"who":"me","text":"Thêu khăn mà không thêu, ngồi cả buổi chỉ để nói thầm. Ta tức cười mà cũng tức giận."},{"who":"M","text":"Bức thêu chung treo ở cung của người cầm đầu phe, nô tỳ đi ngang thấy kim còn cắm dở, chưa ai đụng."},{"who":"me","text":"Tấm thêu thì đẹp, chuyện bàn thì xấu. Ngươi nói xem, họ họp vào những buổi nào?"}]}},
{"id":"j70:j70c-huydung-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp phấn men xanh mở trên bàn phấn, bột trắng mịn như tuyết, một mùi chua nhẹ phảng phất mà chủ nhân chưa kịp để ý."},{"who":"M","text":"{Goi}, có người mua loại phấn rẻ tiền vị chua gắt ở chợ ngoài, rồi hộp phấn của {goi} bị đổi sang một hộp giống y hệt."},{"who":"me","text":"Hộp phấn giống y hệt, ta nhìn cũng không phân biệt được. Nếu thoa lên mặt, ta sẽ ra sao?"},{"who":"M","text":"Hộp phấn men xanh ấy mua từ tiệm phấn phố Nam, nay còn ở bàn phấn của {goi}. Nô tỳ vẫn chưa dám động tay."},{"who":"me","text":"Làm hư dung nhan ta là làm hỏng cả đường lên. Ngươi giữ nguyên hộp, ta sẽ cho người nghiệm."}]}},
{"id":"j70:j70c-huydung-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tấm lụa trắng phơi trong gió, phơi trộm ở góc khuất, mùi nước lạ thoang thoảng lẫn vào hương nắng."},{"who":"M","text":"{Goi}, có người ngâm một tấm lụa trong thứ nước lạ suốt đêm, rồi phơi trộm ở chỗ không ai biết. Về sau tấm lụa ấy may thành khăn."},{"who":"me","text":"Khăn lụa tẩm nước gây ngứa, ai dùng cũng ngứa suốt ngày. Ta chợt nhớ sáng nay tay ta cũng hơi ngứa."},{"who":"M","text":"Tấm lụa tẩm nước ngứa từ tiệm thuốc nhuộm ngoài cung, nay may thành khăn, còn ở cung của {goi}."},{"who":"me","text":"Ngươi cất khăn riêng, đừng để ai chạm. Ta muốn biết ai phơi lụa ấy trong đêm."}]}},
{"id":"j70:j70c-huydung-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đĩa món cay nóng bốc khói ngay trước chỗ ngồi, hơi ớt bốc lên nồng đến cay khóe mắt, trên bàn tiệc không ai hay."},{"who":"M","text":"{Goi}, bếp được dặn thêm ớt và rượu mạnh vào món dâng riêng cho {goi}. Đĩa riêng ấy đặt ngay trước chỗ {goi} ngồi."},{"who":"me","text":"Món dâng riêng cho ta, mà thêm ớt với rượu mạnh. Nếu ta ăn, mặt đỏ, miệng nóng, ai nhìn cũng thấy."},{"who":"M","text":"Đĩa món cay nóng ấy từ Ngự thiện phòng, nay đã trả về chỗ cũ. Nô tỳ thấy bếp đưa ra, nhưng chưa biết ai dặn."},{"who":"me","text":"Làm ta mất thể diện trước mặt mọi người, thật là ác. Ngươi nhớ ai ngồi gần ta, ta muốn biết."}]}},
{"id":"j70:j70c-huydung-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hộp lược nằm bên gương đồng, cung nữ chải đầu nhìn rất lâu, bàn tay còn giữ ít bạc vừa được nhét vào."},{"who":"M","text":"{Goi}, có người gặp riêng cung nữ chải đầu của {goi}, nhét bạc vào tay. Nàng ấy nhìn trộm hộp lược của chủ rất lâu."},{"who":"me","text":"Người chải tóc cho ta mỗi sáng, lại nhìn trộm hộp lược. Ta thấy buồn hơn là giận."},{"who":"M","text":"Chiếc lược gỗ tẩm thuốc mua từ tiệm thuốc ngoài cung, nay nằm ở bàn phấn của {goi}. Nô tỳ không dám chạm."},{"who":"me","text":"Lược mà tẩm thuốc, chạm vào tóc sẽ thế nào? Gọi nàng chải đầu ra cho ta, ta muốn nghe nàng nói."}]}},
{"id":"j71:fc-newyear-c01","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Hiên sau cung Thái hậu, mảnh lụa đỏ vừa thêu xong còn căng trên khung, một góc loang vệt nước trà sậm màu chưa kịp khô."},{"who":"B","text":"Ôi chao, {goi} xem, tay {xung} vụng quá! Chén trà vừa nghiêng đã đổ trúng mảnh lụa, {xung} lau mãi mà vệt vẫn còn."},{"who":"me","text":"Vệt trà còn ướt thế này, chứng tỏ mới đổ ngay trước giờ nộp. {Xung} thức mấy đêm mới thêu xong, nhìn mà xót."},{"who":"B","text":"Xin {goi} đừng giận, {xung} đâu cố ý. Ai ngờ cái khay lại trơn đến vậy, {xung} chỉ muốn giúp một tay."},{"who":"me","text":"Giúp tay, hay vấp chân, một mình {xung} hiểu. Lụa này còn phơi được, nhưng lòng người thì không."}]}},
{"id":"j71:fc-newyear-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Pháo nổ giòn ở cổng Thần Vũ, khói thuốc còn vương trên mái ngói, mùi mứt gừng cay ngọt theo gió thoảng vào sân."},{"who":"M","text":"{Goi}, vừa rồi pháo nổ làm một cung nhân giật mình, hất cả khay mứt gừng lên vạt áo nô tỳ, nhem nhuốc hết cả."},{"who":"me","text":"Ta nghe tiếng pháo mà tưởng trời sập. Áo ngươi mới may đón Tết, thế này thì tiếc thật."},{"who":"M","text":"Nàng ấy sợ đến run, cứ xin lỗi mãi. Nô tỳ thì không giận, chỉ ngại để người ta nhìn thấy dáng vẻ này."},{"who":"me","text":"Một khay mứt đổ giữa ngày xuân, chẳng tội tình gì mà ai cũng ngượng. Ta bước ra xem, rồi liệu lời cho êm."}]}},
{"id":"j71:fc-newyear-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau hiên cuối dãy phòng, tiếng chiêng trống đón xuân vọng lại, còn một bóng áo nhỏ ngồi co ro bên cột gỗ."},{"who":"M","text":"{Goi}, nô tỳ vừa thấy một cung nữ nhỏ ngồi sau hiên lau nước mắt. Nàng ấy không được về thăm mẹ ngày Tết."},{"who":"me","text":"Mẹ già ở xa, thiên hạ đoàn viên mà nàng lẻ bóng. Nghe mà thấy nghẹn, ta cũng từng xa nhà như thế."},{"who":"M","text":"Nàng giấu mặt vào tay áo, sợ ma ma trông thấy lại bị trách. Nô tỳ chẳng biết khuyên nhủ thế nào."},{"who":"me","text":"Nước mắt ngày xuân khó dỗ nhất. Dẫn ta đến sau hiên, ta sẽ ngồi xuống nghe nàng nói."}]}},
{"id":"j71:fc-newyear-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gần giờ cược, bên sân đua, tiếng người bàn tán rì rầm lẫn trong mùi hương trầm và tiếng pháo lẻ."},{"who":"M","text":"{Goi}, nô tỳ nghe rõ: {B} thì thầm với một người quen bên đội thị vệ rằng tay nào sẽ ngã nhẹ ở khúc quanh."},{"who":"me","text":"Thì thầm giữa chốn đông người, hẳn không phải lời vô cớ. Còn gì nữa?"},{"who":"M","text":"Rồi nàng ấy rủ cả {goi} đặt theo, cười rất tươi, như thể đang chia cho {goi} một món lộc đầu năm."},{"who":"me","text":"Lộc đầu năm mà đến từ miệng kẻ hay tính toán, ta thấy lạnh gáy. Đặt hay không đặt, ta còn phải hỏi lòng."}]}},
{"id":"j71:fc-nguyentieu-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đèn lụa hình hoa sen vừa treo lên xà, cánh hoa đung đưa, nút buộc dưới cuống lỏng lẻo như sắp tuột."},{"who":"M","text":"{Goi}, nô tỳ thấy mối buộc nơ đã bị cởi, thay bằng nút lỏng. Đèn nghiêng sắp rơi, mà lúc trước rõ ràng buộc rất chặt."},{"who":"me","text":"Ta tự tay thắt cái nơ ấy, đời nào lại lỏng như vậy. Có người đã động vào đèn của ta."},{"who":"M","text":"Nô tỳ trông thấy người của {B} đi quanh đây từ sớm. Nô tỳ không dám chắc, chỉ biết mối buộc này không phải tay mình."},{"who":"me","text":"Bằng chứng treo lơ lửng ngay trên đầu, mà người đi qua chưa ai ngước lên. Nói ra hay lặng lẽ buộc lại, ta chưa quyết."}]}},
{"id":"j71:fc-nguyentieu-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió nổi từ phía hồ, quét qua sân, từng ngọn đèn rụng tắt như sao rụng, chỉ còn một đốm lửa nhỏ run run."},{"who":"M","text":"{Goi}, gió thổi tắt hết hàng đèn trong sân rồi. Nô tỳ chỉ kịp che lấy ngọn đèn nhỏ cuối cùng này."},{"who":"me","text":"Cả sân tối đen mà tay ngươi còn che một đốm sáng. Nhìn thấy, lòng ta cũng ấm lại."},{"who":"M","text":"Tay nô tỳ run lắm, sợ nó tắt mất. Nhưng bỏ nó thì nô tỳ lại không nỡ."},{"who":"me","text":"Đêm rằm sao nỡ để tối. Che cùng ngươi một ngọn, hay thắp lại cả hàng, tay ta đã sẵn sàng."}]}},
{"id":"j71:fc-nguyentieu-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Cạnh dãy đèn đố treo thẻ chữ, người qua lại đông, tiếng cười lẫn tiếng rao đoán chữ rộn cả một góc sân."},{"who":"B","text":"{Goi}, {xung} vừa đặt cược xong thì đã thấy hối. Nghe nói có tin quan trọng, {xung} muốn đổi đoán với {goi}."},{"who":"me","text":"Mới đặt đã đổi, trông vội vã quá. Tin quan trọng gì mà khiến nàng đổi ý nhanh vậy?"},{"who":"B","text":"Đã là tin quan trọng thì sao nói ở chỗ này được. {Goi} chịu đổi, {xung} sẽ không quên ơn."},{"who":"me","text":"Người chưa đưa tin mà đã đòi ơn, {xung} nghe không yên. Nhưng bỏ qua thì lại sợ lỡ việc."}]}},
{"id":"j71:fc-nguyentieu-c04","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Ngoài hiên đèn giấy, gió thốc xé một bên tán đèn mai, nét vẽ hoa mai trên giấy vẫn còn mảnh mai rõ nét."},{"who":"B","text":"Đèn của {xung} bị gió xé rách rồi, {goi} nhìn xem. Nét vẽ vẫn đẹp, vậy mà giấy đã rách một bên."},{"who":"me","text":"{Xung} thấy nét hoa mai vẫn nguyên, thật tiếc. Mắt nàng đỏ hoe, chắc thức mấy đêm liền?"},{"who":"B","text":"Phải. {Xung} thức mấy đêm để vẽ cho xong, chỉ mong đến giờ chấm không bị chê. Giờ thì sắp đến giờ rồi."},{"who":"me","text":"Đèn rách mà nét mai vẫn nguyên, {xung} đứng trước nó mà không nỡ quay đi. Chia sẻ chút phần mình, hay lo phần mình trước?"}]}},
{"id":"j71:fc-thanhminh-c01","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Dưới giàn hoa, những cuộn chỉ màu xếp thành hàng, riêng cuộn chỉ cuối cùng của nàng nằm trong tay áo, ánh lên màu thiên thanh."},{"who":"B","text":"{Goi} ơi, cho {xung} mượn cuộn chỉ cuối của {goi} một chút thôi. Chỉ chốc lát là {xung} trả."},{"who":"me","text":"Cuộn cuối cùng {xung} có, cho mượn rồi lấy gì thêu tiếp? Nàng nói chốc lát, nhưng {xung} chưa thấy ai trả lại đúng hẹn."},{"who":"B","text":"{Goi} cứ đa nghi. Việc nhỏ thôi mà, chị em với nhau, cớ gì phải giữ khư khư."},{"who":"me","text":"Tình nghĩa thì {xung} quý, nhưng kim chỉ cũng là sức lực của {xung}. {Xung} đang nghĩ nên đáp nàng thế nào."}]}},
{"id":"j71:fc-thanhminh-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mâm bánh thanh đoàn xếp ngay ngắn trước bàn cúng, lá ngải xanh biếc, mùi bánh thơm tỏa trong làn khói hương."},{"who":"M","text":"{Goi}, nô tỳ nếm thử một cái, nhân bánh mặn lạ lắm. Dưới đáy khay còn dính vết muối chưa kịp lau."},{"who":"me","text":"Bánh dâng cúng tổ tiên mà vị mặn như vậy, thật là bất kính. Ai đã đụng vào mâm của ta?"},{"who":"M","text":"Nô tỳ ngờ là người của {B}, đêm qua có kẻ lui tới nhà bếp cung mình. Nhưng nô tỳ không có bằng chứng ngoài vết muối này."},{"who":"me","text":"Giờ cúng đã gần, bánh đã hỏng, trong bếp chỉ còn dấu muối làm chứng. Bây giờ ta phải ra tay."}]}},
{"id":"j71:fc-thanhminh-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước bàn cúng, khói hương quấn quanh những tấm bài vị, một bà lão áo vải đứng lặng, ngón tay mân mê vạt áo cũ."},{"who":"M","text":"{Goi}, có một cung nhân già ngỏ ý nhờ {goi} đọc giúp tên người bà thương đã khuất, vì bà không biết chữ."},{"who":"me","text":"Người đã khuất mà tên chỉ có thể đọc qua miệng kẻ khác. Nghe vậy, lòng ta chùng xuống."},{"who":"M","text":"Bà đứng đó từ sáng, chẳng dám cất lời với ai. Nô tỳ thấy bà run, như sợ làm phiền."},{"who":"me","text":"Giữa ngày tảo mộ, tên người thương cũng cần được gọi ra. Ta đang nghĩ nên giúp bà thế nào cho trọn lễ."}]}},
{"id":"j71:fc-thanhminh-c04","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Diều giấy vừa lượn lên, dải đuôi lụa phấp phới, người đứng quanh sân đua đã vây thành một vòng."},{"who":"B","text":"Khoan đã! Lúc nãy {goi} đặt lệch, {xung} thấy rõ. Giờ diều đã bay, {goi} phải trả thêm bạc cho đúng lệ."},{"who":"me","text":"{Xung} nhớ rõ mình đặt đúng chỗ. Nàng nói lớn như vậy, là muốn mọi người cùng nghe chứ gì?"},{"who":"B","text":"Đã là lệ thì nói trước mặt đông người càng tốt. {Goi} đừng làm khó {xung}, chỉ thêm chút bạc thôi."},{"who":"me","text":"Mặt {xung} nóng bừng dưới bao ánh mắt. Trả hay cãi, một lời thốt ra cũng đã là câu trả lời."}]}},
{"id":"j71:fc-doanngo-c01","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bàn vẽ ngũ độc trải lụa trắng, con rết đã hoàn thành, bột mực còn tươi nơi đầu bút, ngoài sân thoảng mùi ngải cứu."},{"who":"B","text":"Ối, tay áo {xung} lỡ quệt vào tranh của {goi}! Vệt mực dài thế này, trông cứ như một con rắn bò ngang."},{"who":"me","text":"Vệt mực quệt ngang qua con rết đã vẽ xong. Nàng đi ngang bàn mà tay áo lại vừa vặn chạm đúng chỗ ấy."},{"who":"B","text":"Đường chật mà. {Goi} đừng trách, tranh khéo như vậy, sửa chút là lại đẹp."},{"who":"me","text":"Công {xung} vẽ cả buổi, giờ vệt mực này nằm đó mà nàng nói nhẹ nhàng. {Xung} đang nghĩ nên đáp sao."}]}},
{"id":"j71:fc-doanngo-c02","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Thuyền rồng cập bờ sát nút, nước hồ còn vỗ lên mạn thuyền, tiếng trống dồn dập vẫn chưa dứt."},{"who":"B","text":"{Goi} nhìn xem, thuyền {goi} chọn cập bờ sát nút, như vậy là phạm quy! {Xung} đòi cả cung đặt lại."},{"who":"me","text":"Thuyền {xung} cập bờ có người chứng kiến cả. Nàng kêu lớn như vậy là sợ thua, hay vì chuyện khác?"},{"who":"B","text":"Quy củ là quy củ. {Goi} cứ để mọi người phân xử cho công bằng, kẻo ngày sau lại có điều tiếng."},{"who":"me","text":"Trước mặt cả cung, thể diện và lý lẽ đều đang chờ {xung} đáp. Hòa khí hay lẽ thẳng, {xung} chọn trong một hơi thở."}]}},
{"id":"j71:fc-doanngo-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên treo túi thơm ngũ sắc, mùi ngải và xương bồ thoảng nhẹ, một bàn tay nhỏ níu chặt tay áo."},{"who":"M","text":"{Goi}, một hoàng tự nhỏ ốm nhẹ vì nóng, bám lấy tay áo {goi} hỏi liệu túi thuốc có đuổi được bệnh không."},{"who":"me","text":"Đôi mắt trẻ thơ ngước lên, vừa sợ vừa tin. Ta chưa biết trả lời thế nào cho đừng làm bé thất vọng."},{"who":"M","text":"Bé nóng, má đỏ hây, nhưng vẫn cố cười. Nô tỳ nhìn mà thương."},{"who":"me","text":"Lời dịu dàng có khi hơn cả thang thuốc. Ngồi xuống ngang tầm mắt bé, ta sẽ biết nói gì trước."}]}},
{"id":"j71:fc-doanngo-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bình rượu hùng hoàng vừa mở nắp, mùi lạ xộc lên, người đứng quanh lần lượt nhăn mặt rồi lùi lại."},{"who":"M","text":"{Goi}, bình rượu của {goi} bị đổi rồi. Nắp bình có chỉ đỏ khác loại của cung mình, nô tỳ nhìn mới biết."},{"who":"me","text":"Chỉ đỏ ấy ta không dùng. Rượu ta ủ cả tháng, giờ vị đã nặng mùi, ai uống cũng nhăn mặt."},{"who":"M","text":"Nô tỳ nghe nói {B} nhờ người đổi bình, nhưng chưa có ai nhìn thấy tận mắt cả."},{"who":"me","text":"Ta giận thì có giận, nhưng giữa ngày hội, giận cho đúng cách mới là điều khó. Phải liệu thế nào đây."}]}},
{"id":"j71:fc-phoenix-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bãi ngựa buổi sớm đẫm sương, con ngựa thuần phì hơi trắng, dây yên da trâu rủ xuống còn mỏng như sợi tóc."},{"who":"M","text":"{Goi}, nô tỳ vừa kiểm lại dây yên, đường dây bị cắt gần hết, chỉ còn một sợi mỏng. Vết cắt mới, nhẵn lắm."},{"who":"me","text":"Nhẵn như thể có lưỡi dao sắc đi qua. Lúc ta dắt ngựa ra, dây vẫn còn nguyên."},{"who":"M","text":"Nô tỳ thấy {B} đứng gần đó, xoa tay mà mặt thản nhiên như chẳng có chuyện gì."},{"who":"me","text":"Một sợi dây mỏng, một người điềm nhiên. Ngồi lên lưng ngựa mà lòng không yên, ta phải tính kỹ bước đầu."}]}},
{"id":"j71:fc-phoenix-c02","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bên rào xạ trường, mũi tên cắm trên bia còn rung, tiếng bàn tán thấp thoáng sau tấm rèm gấm."},{"who":"B","text":"{Goi}, {xung} mới nghe một tin: có tay thiện xạ đau cổ tay, e rằng không giương nổi cung. Nên {xung} rủ {goi} đặt ngược."},{"who":"me","text":"Lời đồn bay nhanh hơn mũi tên. Nàng nghe từ miệng ai mà dám chắc như vậy?"},{"who":"B","text":"Nghe từ người rất gần nàng ấy, {goi} cứ tin. Đặt ngược lần này, cả hai ta cùng có lợi."},{"who":"me","text":"Nàng cười tươi đến mức {xung} chẳng đọc ra lòng nàng. Giữa tin thật và lời bẫy, {xung} phải chọn một bên."}]}},
{"id":"j71:fc-phoenix-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Nắng sớm hắt lên mái cung, chiếc mũ giáp lăn lóc trên nền đá, vang một tiếng khô khan giữa bãi hội."},{"who":"M","text":"{Goi}, một thị vệ trẻ trượt tay làm rơi mũ giáp ngay trước cung mình. Cậu ấy đứng đơ ra, nhìn quanh như sợ bị phạt."},{"who":"me","text":"Mới ngày đầu hội mà đã lỡ tay, mặt cậu ấy hẳn đỏ như gấc. Ta nhớ lần đầu mình lỡ lời trước mặt người trên."},{"who":"M","text":"Quan thị vệ trưởng đứng khá xa, chưa nhìn tới. Nhưng sớm muộn gì cũng biết."},{"who":"me","text":"Một chiếc mũ rơi, một người ngượng, mà quan thị vệ trưởng chưa nhìn tới. Ta bước tới, hoặc giả như không thấy."}]}},
{"id":"j71:fc-phoenix-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngọn cờ thêu phượng căng trên cột, một góc vải rách bay phần phật trong gió, sợi chỉ đỏ lòa xòa như vết máu."},{"who":"M","text":"{Goi}, gió thổi rách cờ rồi. Nhưng nô tỳ thấy chỉ đỏ vương ngay mép rách, đúng loại chỉ ngón tay của {B} còn dính."},{"who":"me","text":"Gió có thể xé vải, nhưng không thể để lại chỉ đỏ trên tay một người. Nàng ấy còn đứng đó cười."},{"who":"M","text":"Nàng nhìn {goi} mà mỉm cười, như đang chờ xem {goi} làm gì tiếp."},{"who":"me","text":"Nét thêu phượng vẫn nguyên, chỉ rách một góc. Đưa sợi chỉ đỏ ra ánh sáng, hay âm thầm vá lại, cả hai đều là một nước cờ."}]}},
{"id":"j71:fc-thattich-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lư hương hoa bách hợp mở nắp, khói mỏng bay lên tan trong gió, hương thơm lạ không còn như ta đã chọn."},{"who":"M","text":"{Goi}, bột trong lư là loại rẻ, khác hẳn bột {goi} đã bỏ vào. Nô tỳ ngửi kỹ, chỉ còn mùi khói."},{"who":"me","text":"Ta chọn từng nhánh trầm, từng cánh hoa khô. Giờ mở nắp ra chỉ còn khói nhạt, ai đã làm chuyện này?"},{"who":"M","text":"{B} vừa xoa tay vừa an ủi {goi}, lời lẽ rất dịu. Nô tỳ nghe mà lạnh cả lưng."},{"who":"me","text":"Lời an ủi quá ngọt lại càng khiến ta ngờ. Lư vẫn còn đây, ta phải đối phó sao cho đúng cách."}]}},
{"id":"j71:fc-thattich-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới cành mai treo đầy dải lụa ngũ sắc, một cung nữ trẻ đứng ngập ngừng, tay nắm chặt sợi chỉ đỏ nhỏ."},{"who":"M","text":"{Goi}, có một cung nữ trẻ xin {goi} buộc giúp sợi chỉ đỏ vào cành mai, để cầu một mối duyên lành."},{"who":"me","text":"Mặt nàng ửng đỏ chắc không phải vì nắng. Chuyện lòng con gái, người ngoài cũng ngại nghe."},{"who":"M","text":"Nô tỳ nghĩ nàng ấy tin lắm, tin rằng người nào buộc thì lời nguyện mới thiêng."},{"who":"me","text":"Một sợi chỉ nhỏ gửi gắm cả niềm hy vọng. Nhận lấy nó, ta phải nói sao cho nàng không buồn."}]}},
{"id":"j71:fc-thattich-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Quanh bàn cờ bày giữa sân, quân đen quân trắng xếp ngay hàng, tiếng bàn luận đột ngột lặng đi khi một giọng nói vang lên."},{"who":"B","text":"Nước cờ của {goi} hay lắm, hay đến lạ. Nghe nói {goi} có sách riêng, học mấy nước này, đúng chứ?"},{"who":"me","text":"Mấy người xung quanh quay lại nhìn {xung}. Lời nàng nhẹ như gió mà đẩy {xung} ra giữa vòng người."},{"who":"B","text":"{Xung} chỉ nói thật. {Goi} đừng giận, người tài thường bị người khác nghi ngờ."},{"who":"me","text":"Nghe như khen mà là đẩy {xung} vào thế khó. {Xung} phải đáp thế nào để mọi người thấy rõ."}]}},
{"id":"j71:fc-thattich-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc kim bạc nằm trên nền sân, gãy làm đôi, đầu kim còn dính sợi chỉ ngũ sắc, lấp lánh dưới nắng chiều."},{"who":"M","text":"{Goi}, nô tỳ đáng chết. Lúc mang kim ra bàn lễ, nô tỳ hụt chân, kim bạc khất xảo gãy làm đôi rồi."},{"who":"me","text":"Ngươi đứng dậy đi, mặt tái hết rồi. Chiếc kim ấy là lễ vật cầu khéo tay, cũng là tấm lòng của ta."},{"who":"M","text":"Đầu kim còn dính chỉ ngũ sắc, nô tỳ cầm mà tay run. Nô tỳ sợ ngày lễ thành ngày xui."},{"who":"me","text":"Kim gãy thì gãy, người còn đây. Đỡ ngươi dậy trước, rồi ta tính chuyện cái kim."}]}},
{"id":"j71:fc-vulan-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Cuộn cờ phướn vàng trải trên bàn chờ nộp, nước ngải lấm tấm ở mép lụa, mùi thảo mộc còn nồng."},{"who":"M","text":"{Goi}, nô tỳ mở cuộn cờ ra thì thấy mép lụa lấm tấm vết nước ngải, may mà nét thêu còn nguyên."},{"who":"me","text":"Nước ngải tưới ướt cả mép lụa, như ai cố ý để lại dấu. Sao lại đúng vào lúc sắp nộp?"},{"who":"M","text":"{B} đứng gần đó, xin lỗi vội vàng lắm, chưa kịp hỏi đã nhận lỗi trước."},{"who":"me","text":"Lời xin lỗi đến trước câu hỏi, nghe mà ngờ ngợ. Giờ ta còn phải giữ cho kịp giờ nộp."}]}},
{"id":"j71:fc-vulan-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài cổng cung nắng gay gắt, hơi nồi cháo thoang thoảng bay ra, một bà lão ôm đứa cháu nhỏ lặng người trong bóng cổng."},{"who":"M","text":"{Goi}, ngoài cổng có bà lão ôm cháu nhỏ đứng đợi cháo từ sáng. Môi bà nứt nẻ mà bà chưa dám xin."},{"who":"me","text":"Đứa bé gục đầu vào vai bà, mắt nhắm nghiền. Giữa tiết Vu lan, người ta còn đói thế này, ta nghe mà cay mắt."},{"who":"M","text":"Bà cứ đứng im, chắc sợ người trong cung xua đuổi. Nô tỳ nhìn mà không đành."},{"who":"me","text":"Cháo phát có hạn mà lòng người thì rộng. Ta ra cổng một chuyến, xem bà đứng bóng nào."}]}},
{"id":"j71:fc-vulan-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bên bàn phúc, giấy hồng trải sẵn, bút son còn ướt, mọi người chụm đầu quanh bảng ghi tên người góp bạc."},{"who":"B","text":"{Goi} nghe này, {xung} đề nghị cả cung cùng góp bạc làm phúc. Nhưng bảng ghi tên thì phải để tên {xung} ở trên cùng."},{"who":"me","text":"Làm phúc mà đã lo xếp chỗ tên, {xung} nghe thấy nặng nề. Phúc chẳng phải đo bằng chữ trên bảng."},{"who":"B","text":"Thể diện là thể diện. {Goi} theo hay không, {xung} cũng đã nói rõ."},{"who":"me","text":"Lòng {xung} muốn làm điều thiện, nhưng không muốn bị lợi dụng. Phải liệu cách góp cho ổn."}]}},
{"id":"j71:fc-vulan-c04","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Giữa sân lộng gió, đèn hoa đăng giấy sen cháy xém bên mép, ánh lửa liếm vào cánh hoa như muốn nuốt trọn."},{"who":"B","text":"{Goi}... đèn của {xung} rơi rồi, lửa lan vào giấy sen. {Xung} không biết phải làm sao, tay run quá."},{"who":"me","text":"Nàng đứng sững như tượng, mắt nhìn đèn mà không nhấc nổi chân. Một cánh sen cháy xém, khung vẫn còn nguyên."},{"who":"B","text":"Đèn này {xung} làm cho người đã khuất. Nếu hỏng, {xung} không biết nói gì với người."},{"who":"me","text":"Giấy sen cháy, tình người đâu có cháy. {Xung} nên giúp nàng bằng cách nào cho kịp?"}]}},
{"id":"j71:fc-xa-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lối ra sân hội đọng bùn nhão, mùi đất ẩm lẫn hương hoa khô, tiếng cười vang lên từ phía dãy hành lang."},{"who":"M","text":"{Goi}, hài thêu của nô tỳ dính chặt xuống bùn rồi. Nô tỳ nhảy lò cò, mặt đỏ bừng, mà chân không nhấc lên được."},{"who":"me","text":"Ngươi kể mà ta suýt bật cười. Giữa hội lớn, đôi hài thêu đẹp lại vùi xuống bùn."},{"who":"M","text":"Mọi người nhìn cả, nô tỳ ngượng quá. Nhưng đi cũng không được, ở lại cũng không xong."},{"who":"me","text":"Chuyện nhỏ mà bẽ mặt lớn. Ta ra lối bùn, xem kéo ngươi lên, hay cười cùng ngươi một trận."}]}},
{"id":"j71:fc-xa-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió lạnh lùa qua hành lang, chén trà gừng bốc khói, hơi ấm lan trên đầu ngón tay một bà ma ma già."},{"who":"M","text":"{Goi}, bà ma ma già đã lặng lẽ đưa chén trà gừng nóng cho {goi} lúc nãy, chẳng nói lời nào. Bà đứng chờ ngoài hiên."},{"who":"me","text":"Trà gừng ấm tay mà ấm cả lòng. Ta nghĩ giữa gió lạnh, chẳng ai nhớ đến người già lặng lẽ như vậy."},{"who":"M","text":"Nô tỳ thấy bà run, mà tay vẫn che chén trà cho khỏi nguội."},{"who":"me","text":"Một chén trà nhỏ, một tấm lòng thầm lặng. Đáp tạ bà thế nào cho đủ nghĩa, ta tự có cách."}]}},
{"id":"j71:fc-xa-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Tà áo gấm thêu chỉ bạc xoay một vòng giữa sân hội, ánh bạc nơi cổ áo lấp lánh chói mắt đám đông."},{"who":"B","text":"{Goi} xem này, áo {xung} mới may cho ngày hội, mẫu thêu cung nào cũng khen. {Goi} có ưng không?"},{"who":"me","text":"Nàng xoay một vòng trước mặt {xung}, để mọi người cùng nhìn, rồi hỏi {xung} ưng hay không."},{"who":"B","text":"Chỉ bạc ở cổ áo, {goi} nhìn kỹ đi. Nói thật, đừng nể."},{"who":"me","text":"Hỏi thì nhẹ mà ý thì nặng. Khen cho thật lòng, hay đáp bằng một nụ cười, {xung} chỉ có một hơi để chọn."}]}},
{"id":"j71:fc-xa-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đám đông chen chúc quanh sân hội, tiếng nói cười ngợp trời, bờ vai ai chạm vào vai ai cũng có thể là vô tình."},{"who":"M","text":"{Goi}, vừa nãy khi đám đông chen vào xem, {B} huých vai {goi} một cái rất mạnh, rồi giả vờ như bị người khác đẩy."},{"who":"me","text":"Ta thấy đau mà tưởng là đám đông. Hóa ra có người tính toán cả nhịp chen."},{"who":"M","text":"Nô tỳ thấy rõ, nàng cố ý. Nhưng người xung quanh không ai để ý cả."},{"who":"me","text":"Một cái huých mà ý sâu như giếng. Đáp lại một cái, hay lùi nửa bước, ta nghe tim mình đập nhanh."}]}},
{"id":"j71:fc-xa-c05","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài rìa đám đông xem hội, tiếng trống vẫn rộn, riêng một góc tường im lặng, nơi bóng tóc bạc đứng dưới nắng xế."},{"who":"M","text":"{Goi}, có một bà cung nhân tóc bạc đứng ngoài đám đông, mắt xa xăm, tay cứ vân vê chiếc khăn cũ."},{"who":"me","text":"Chiếc khăn đã bạc màu mà bà giữ chặt như báu vật. Chắc là kỷ vật mang từ quê nhà."},{"who":"M","text":"Nô tỳ nghe bà lẩm bẩm tên một làng nhỏ. Bà không ra gần, cũng không dám hỏi ai."},{"who":"me","text":"Giữa hội vui vẫn có người nhớ nhà đến rưng rưng. Để xem ta đến với bà bằng cách nào cho nhẹ nhàng."}]}},
{"id":"j71:fc-xa-c06","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bóng áo nhỏ xíu lao qua hành lang rải lá, đôi giày hổ thêu chạy loạng choạng, theo sau là tiếng gọi hốt hoảng của nhũ mẫu."},{"who":"M","text":"{Goi}, một hoàng tự bé xíu vừa chạy khỏi tay nhũ mẫu, nắm lấy tay áo nô tỳ rồi ngẩng nhìn {goi}, mắt đẫm lệ."},{"who":"me","text":"Bé nhìn ta chằm chằm, má còn ướt. Chắc bé hoảng vì lạc giữa chốn đông người."},{"who":"M","text":"Bé không nói gì, chỉ giữ chặt tay áo nô tỳ. Nô tỳ chẳng dám rút ra."},{"who":"me","text":"Một bàn tay nhỏ níu lấy, mà lòng ta cũng mềm đi. Giờ nên dỗ bé trước, hay đưa bé về trước, ta còn phân vân."}]}},
{"id":"j71:fc-xa-c07","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa sân hội đông người, mấy tà áo chụm đầu vào nhau, tiếng xì xào lan như gió qua rặng trúc."},{"who":"M","text":"{Goi}, nô tỳ nghe nói khắp nơi rằng {goi} bỏ bạc mua lòng cung nhân để được khen. Lời ấy do {B} rỉ tai."},{"who":"me","text":"Bỏ bạc mua lòng người, nghe sao mà cay nghiệt. Ta đối đãi thật lòng, không ngờ lại bị bẻ thành toan tính."},{"who":"M","text":"Tiếng xì xào lan nhanh lắm, nhiều người đã nhìn {goi} bằng ánh mắt khác."},{"who":"me","text":"Lời đã ra khỏi miệng như tên rời cung. Giờ ta phải đối diện tiếng xì xào ấy, trước khi nó thành thật."}]}},
{"id":"j71:fc-xa-c08","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trên bàn tiệc, đĩa bánh còn nguyên hoa văn, bỗng một bóng vằn nhảy vút qua, bụi cây rung rinh, tiếng cười bật ra khắp sân."},{"who":"M","text":"{Goi}, con mèo vằn của Thái hậu nhảy lên bàn, tha đi miếng bánh đẹp nhất của một cung rồi chạy tuốt vào bụi cây!"},{"who":"me","text":"Cả sân cười vang. Nghĩ đến gương mặt người làm bánh, ta vừa buồn cười vừa thương."},{"who":"M","text":"Con mèo thì thản nhiên, miếng bánh thì nằm trong bụi. Mọi người còn đang bàn nên làm sao."},{"who":"me","text":"Mèo của Thái hậu, ai dám trách. Ta nhìn bụi cây rung rinh mà chẳng biết nên đuổi hay nên cười."}]}},
{"id":"j71:fc-xa-c09","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Chiếc ghế gần cửa sổ vẫn còn hơi ấm, tách trà bên cạnh chưa kịp nguội, đã có một tà áo khác ngồi xuống thế chỗ."},{"who":"B","text":"Ôi, {goi} đi lấy trà đấy ư? {Xung} thấy chỗ này thoáng quá, ngồi xuống lúc nào không hay."},{"who":"me","text":"Chiếc ghế {xung} ngồi từ đầu buổi, chiếc khăn {xung} đặt vẫn còn đó. Nàng ngồi vào mà thản nhiên như chưa từng có ai."},{"who":"B","text":"Chỗ nào chẳng là chỗ, {goi} nhỉ? Nhìn {goi} bưng trà, {xung} cũng ngại đứng dậy."},{"who":"me","text":"Nàng nói chuyện nhẹ như gió mà ngồi vững như đá. Tách trà trong tay {xung} còn nóng, chỗ ngồi thì đã mất."}]}},
{"id":"j71:fc-xa-c10","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa sân hội, Thái hậu ngồi trên ghế cao, tràng hạt chầm chậm lăn qua kẽ tay, mọi ánh mắt dồn về phía ấy."},{"who":"M","text":"{Goi}, vừa rồi Thái hậu bất ngờ hỏi {goi} một việc nhỏ trong cung nội. Người nhìn {goi} rất lâu, chờ nghe {goi} nói thật hay nói khéo."},{"who":"me","text":"Giữa đông người mà hỏi riêng một mình ta. Nghe thì nhẹ, nhưng ta biết người muốn thử lòng."},{"who":"M","text":"Nô tỳ đứng gần, thấy mấy phi tần cũng nghiêng tai nghe."},{"who":"me","text":"Lời nói thật dễ mất lòng, lời nói khéo dễ mất tin. Ta phải chọn cách đáp trước khi mọi người sốt ruột."}]}},
{"id":"j71:fc-xa-c11","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Hoàng hôn tắt dần sau mái điện, bóng người thưa, một tà áo lặng lẽ bước tới gần, giọng thấp như sợ tường có tai."},{"who":"B","text":"{Goi}, hôm nay {xung} muốn thử một điều rất lớn. Nếu {xung} thất bại, {goi} sẽ đứng về bên nào?"},{"who":"me","text":"Điều lớn mà không nói rõ, lại hỏi {xung} đứng về đâu. Nghe mà lạnh sống lưng."},{"who":"B","text":"Chỉ hỏi vậy thôi, {goi} cứ nghĩ cho kỹ. {Xung} cần biết lòng {goi} trước khi liều thân."},{"who":"me","text":"Một lời hứa nặng hơn ngàn lượng bạc. {Xung} chưa vội đáp, để {xung} hỏi nàng muốn thử điều gì đã."}]}},
{"id":"j71:fc-xa-c12","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Kho Nội vụ phủ bụi phủ mờ, hộp gỗ mở ra thơm mùi long não, chiếc khăn lụa phai vàng nằm trong lớp giấy mỏng."},{"who":"M","text":"{Goi}, cung nhân dọn kho tìm ra chiếc khăn thêu cũ. Chỉ vàng nơi góc khăn đã sờn, vẫn đọc được tên một phi tần đã khuất."},{"who":"me","text":"Một cái tên thêu bằng chỉ vàng, giờ chỉ còn dấu vết. Người đã đi, khăn còn ở lại."},{"who":"M","text":"Họ hỏi nô tỳ nên để lại kho hay đem cúng, mà nô tỳ không dám quyết thay."},{"who":"me","text":"Đồ của người đã khuất, ta cầm trên tay thấy nặng. Phải nghĩ cho khéo, để người yên lòng và người sống cũng yên."}]}},
{"id":"j71:fc-trungthu-c01","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Án chờ chấm bày kín bài dự thi, hoa văn rực rỡ, riêng bài của nàng nằm ngay trước ghế Thái hậu, đường kim chỉ còn nguyên nếp."},{"who":"B","text":"Ôi, vạt áo {xung} lỡ quệt qua bài của {goi} rồi. Thật vô ý quá, {goi} đừng giận nhé."},{"who":"me","text":"Vạt áo nàng quệt đúng bài {xung}, đúng lúc người ta bày xong. Đường kim chỉ riêng của cung {xung} cũng bị kéo lệch rồi."},{"who":"B","text":"Đông người chen chúc mà. Chắc không sao đâu, {goi} xem lại là biết."},{"who":"me","text":"Bài {xung} vẫn đang nằm đó, trước mặt Thái hậu. Phải xử trí cho đúng, ngay bây giờ."}]}},
{"id":"j71:fc-trungthu-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hội trăng lung linh ánh đèn, trên tay cô cung nữ là chiếc đèn thỏ bằng giấy dầu, nét vẽ vụng về mà đáng yêu."},{"who":"M","text":"{Goi}, nô tỳ tự làm chiếc đèn này, mong {goi} nhận lấy. Để {goi} đi đêm khỏi vấp chân."},{"who":"me","text":"Chiếc đèn thỏ mắt tròn xoe, nét vẽ ngây thơ. Ta nhìn mà bất giác mỉm cười."},{"who":"M","text":"Nô tỳ vẽ hỏng mấy lần mới ra thế này. Nô tỳ chỉ sợ {goi} chê."},{"who":"me","text":"Chê sao được, đèn nhỏ mà tấm lòng lớn. Ta đang nghĩ nên đền đáp ngươi ra sao."}]}},
{"id":"j71:fc-trungthu-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Kết quả vừa báo xong, sân đình còn rộn tiếng bàn tán, mấy tờ giấy chép nằm lặng trên án như đang chờ bị lật."},{"who":"B","text":"Kết quả vừa báo mà {xung} nghe nói bài của {goi} chép lại một cuốn sách cổ. Ai tra sẽ rõ ngay thôi."},{"who":"me","text":"Nàng nói to giữa sân, để cả nơi này nghe. Lời buộc tội mà không đưa ra bằng chứng, chỉ bảo người ta đi tra."},{"who":"B","text":"{Goi} đừng giận. {Xung} chỉ nói điều {xung} nghe, nếu sai thì cứ để sách làm chứng."},{"who":"me","text":"Mọi ánh mắt đã đổ dồn về {xung}. {Xung} cần một lời đáp đứng được trước Thái hậu."}]}},
{"id":"j71:fc-trungthu-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mây dày kéo kín mặt trăng đúng lúc cả sân đang ngẩng chờ, ánh đèn lồng bỗng trở nên le lói và cô quạnh."},{"who":"M","text":"{Goi}, nô tỳ có người thân ở quê, đêm rằm này không được về. Mây che trăng, nô tỳ càng thấy nhớ."},{"who":"me","text":"Trăng khuất sau mây, người cũng khuất sau xa cách. Ta hiểu nỗi lòng ngươi."},{"who":"M","text":"Nô tỳ không dám làm mất vui, chỉ là khóe mắt cứ cay."},{"who":"me","text":"Đêm rằm sao nỡ để ngươi một mình giấu lệ. Ngồi xuống đây cạnh ta, trăng còn đang chờ."}]}},
{"id":"j71:fc-vantho-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khay dâng điện Càn Thanh phủ lụa vàng, trên nắp hộp lễ vật còn in dấu niêm của cung ta, nhưng hộp mở ra đã khác."},{"who":"M","text":"{Goi}, hộp lễ vật bị đổi rồi. Dấu niêm của cung mình vẫn còn trên nắp, mà bên trong là món rẻ hơn."},{"who":"me","text":"Dấu niêm còn nguyên, hộp thì đã khác. Tay ai khéo đến thế mà dám đổi lễ vật ngay lúc sắp dâng?"},{"who":"M","text":"Nô tỳ thấy {B} vừa đi ngang qua khay ấy. Nô tỳ chỉ thấy vậy, không dám nói thêm."},{"who":"me","text":"Sắp đến giờ dâng, không còn thời gian kêu oan. Ta phải chọn một cách, nhanh mà đúng."}]}},
{"id":"j71:fc-vantho-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong yến tiệc đèn rực, bát đĩa sáng loáng, bên cuối bàn một tiếng hắt hơi nổ ra liên tiếp khiến cả mâm cười ồ."},{"who":"M","text":"{Goi}, một cung nhân già hắt hơi liên hồi, ai nấy cười rộ lên. Nô tỳ khẽ hỏi, có nên đưa khăn tay cho bà không?"},{"who":"me","text":"Hắt hơi mà dồn dập như vậy, tội nghiệp bà. Mọi người cười, ta lại thấy bà đỏ mặt."},{"who":"M","text":"Bà cố nhịn mà không nhịn được. Nô tỳ nhìn mà vừa buồn cười vừa ái ngại."},{"who":"me","text":"Một chiếc khăn tay, một lời pha trò, hay tìm thái y, có cách nào cũng khiến bà đỡ ngượng. Để ta xem."}]}},
{"id":"j71:fc-vantho-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Sau điện Thọ Khang, dãy hành lang vắng, mùi mực và giấy kinh còn vương trên vạt áo của ai đó vừa kéo ta đứng lại."},{"who":"B","text":"{Goi}, {xung} nhờ {goi} một việc nhỏ. Xin {goi} thưa giúp rằng {xung} đã thức thâu đêm chép kinh chúc thọ."},{"who":"me","text":"Thức thâu đêm chép kinh, đêm ấy {xung} ngồi dưới đèn mà mắt cay xè. Nàng nhờ {xung} thưa thay, chính {xung} là người đã chép."},{"who":"B","text":"Chỉ một lời thôi, {goi}. Sau này {xung} nhất định đền đáp."},{"who":"me","text":"Lời nàng khẽ mà nặng, như đặt cả công sức của {xung} lên cán cân. {Xung} mở lời trước hay chờ nàng nói hết?"}]}},
{"id":"j71:fc-vantho-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng đàn tiếng sáo trong yến bỗng chênh đi một nhịp, mọi chén rượu khựng lại, cô nhạc công trẻ cúi gằm mặt, môi tái nhợt."},{"who":"M","text":"{Goi}, nhạc phường đệm cho yến vừa lạc nhịp, cô nhạc công trẻ tái mặt. Ánh mắt nàng cầu cứu về phía bàn của {goi}."},{"who":"me","text":"Một nhịp lạc thôi mà nàng sợ như trời sập. Giữa yến tiệc, ai cũng nhìn xuống nàng."},{"who":"M","text":"Quan nhạc chưa kịp nhìn tới. Nếu lỡ thêm, nàng ấy khó mà giữ được chỗ."},{"who":"me","text":"Ánh mắt cầu cứu ấy ta không nỡ lờ đi. Hãy xem ta có thể giúp nàng bằng cách nào, trước khi nhịp sau tới."}]}},
{"id":"j71:fc-trungcuu-c01","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Đình núi ngợp sắc vàng, bình cúc dự thi đứng giữa bàn, nhành cúc vàng nhất vươn cao như đang cười thách thức mọi người."},{"who":"B","text":"{Goi} xem bình cúc của {xung} đi, đẹp chưa? Nhành vàng ở giữa này nở rực nhất vườn."},{"who":"me","text":"Nhành cúc ấy {xung} nhận ra ngay. Gốc nó nằm ở sân cung {xung}, vết ngắt còn mới, vừa khuất bóng sương sớm."},{"who":"B","text":"{Goi} nhìn nhầm rồi. Cúc vàng nào chẳng giống cúc vàng, nhất là khi đã cắm vào bình đẹp."},{"who":"me","text":"Nàng nói nhẹ nhàng mà không dám nhìn thẳng. Gốc cúc ở sân cung {xung} còn đó để làm chứng."}]}},
{"id":"j71:fc-trungcuu-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió thu cuốn lá vàng bay tung trên đình núi, mọi người đang nín thở theo dõi nghi thức, thì một dải lụa mỏng lướt qua đầu."},{"who":"M","text":"{Goi}, gió bốc lên thổi bay chiếc khăn lụa của {goi}, giờ nó đang vắt vẻo trên cành cây thấp, đúng lúc ai nấy nín thở."},{"who":"me","text":"Chiếc khăn bay đi như con bướm mất chủ. Ta suýt bật cười, nhưng cả đình đang nhìn."},{"who":"M","text":"Nô tỳ nhìn cành ấy cũng không cao lắm. Nhưng trông cũng thật là buồn cười."},{"who":"me","text":"Một chiếc khăn lụa mà cả đình đều ngoảnh nhìn. Ta bước tới gốc cây, xem tay ai với tới."}]}},
{"id":"j71:fc-trungcuu-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bình rượu cúc đặt trên án trước Từ Ninh cung, nút sáp còn nguyên dấu cung nàng, mùi hơi chua thoang thoảng bay ra."},{"who":"B","text":"{Goi}, rượu này mùi chua lạ quá, {xung} nghe nói uống vào dễ sinh bệnh. Có nên dâng Thái hậu không?"},{"who":"me","text":"Rượu {xung} tự ủ, nút sáp đóng dấu cung {xung}, sao lại chua? Nàng nói lớn như thế, ai nghe cũng hoang mang."},{"who":"B","text":"{Xung} chỉ lo cho Thái hậu thôi. Rượu mà hại long thể thì ai chịu trách nhiệm?"},{"who":"me","text":"Lời nàng như mật mà ý như dao. Giữa mọi người, {xung} cần có cách đáp cho rượu của mình được rõ ràng."}]}},
{"id":"j71:fc-trungcuu-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lưng núi lộng gió, sương còn đọng trên lá thù du, một bóng áo cũ ngồi lặng lẽ cạnh phiến đá rêu."},{"who":"M","text":"{Goi}, bà cung nhân già ngồi bên đá kia, tay vân vê túi thù du cũ. Nô tỳ nhận ra, chính bà từng chải đầu cho {goi} buổi đầu vào cung."},{"who":"me","text":"Là bà ấy sao. Hôm ấy ta còn lạ lẫm, mái tóc rối, chính bàn tay bà vuốt cho gọn."},{"who":"M","text":"Bà không nhìn thấy {goi}, chỉ ngồi ngắm núi, mắt có vẻ buồn."},{"who":"me","text":"Đoàn người còn đi tiếp, mà lòng ta nặng chút ân xưa. Ta đứng đây, chân chưa quyết rẽ lối nào."}]}},
{"id":"j71:fc-thanhtho-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước ghế Thái hậu, hai hộp lễ đặt cạnh nhau, một hộp gấm rực rỡ được xoay mặt ra, hộp kia chỉ được nhìn lướt qua."},{"who":"M","text":"{Goi}, Thái hậu nhận lễ của {B} xong thì khen hết lời. Lúc nhìn sang lễ của {goi}, người chỉ gật đầu hờ hững."},{"who":"me","text":"Hờ hững một cái gật đầu, mà ta nghe như bị cân lên cân xuống. Lễ ta chọn từng thứ, đâu có thua kém."},{"who":"M","text":"Nô tỳ đứng gần, thấy {B} liếc sang cười rất khẽ."},{"who":"me","text":"Trước mặt Thái hậu, một lời đáp khéo có thể xoay chuyển cả buổi. Phải nghĩ cho thật kỹ."}]}},
{"id":"j71:fc-thanhtho-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước Phật đường khói trầm lững lờ, một bà ma ma bên Thái hậu đứng chờ, tay chắp lại, bên cạnh là cô cung nữ mới ngơ ngác."},{"who":"M","text":"{Goi}, ma ma bên Thái hậu thì thầm nhờ {goi} dẫn một cung nữ mới vào Phật đường, vì nô tỳ biết đường nhất."},{"who":"me","text":"Một cô bé lạ chỗ lạ người, ta hiểu cảm giác ấy. Bà ma ma nhờ ta, chắc cũng có ý riêng."},{"who":"M","text":"Nàng ấy nép sau lưng nô tỳ, tay nắm chặt khăn, không dám ngước nhìn ai."},{"who":"me","text":"Dẫn đường chỉ là việc nhỏ, nhưng cũng là dịp để ta tỏ rõ lòng. Phải xem cách nào hợp nhất."}]}},
{"id":"j71:fc-thanhtho-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Rạng sáng, trong rương cuộn lụa đỏ thẫm, một khoảng lớn bị cắt mất, nơi mép lụa vẫn còn dấu dệt của Cục Thêu."},{"who":"M","text":"{Goi}, cuộn lụa dùng cho bài dự thi thiếu một mảnh lớn. Dấu dệt của Cục Thêu nơi mép lụa vẫn còn nguyên."},{"who":"me","text":"Một mảnh lớn biến mất giữa đêm, còn đang là việc gấp. Ai đã đụng vào rương của ta?"},{"who":"M","text":"Rồi nô tỳ nghe tin {B} vừa mới sai người mang tới Phật đường một mảnh y hệt."},{"who":"me","text":"Y hệt đến thế, đâu phải trùng hợp. Rương còn mở, ma ma chưa tới, ta phải ra tay ngay."}]}},
{"id":"j71:fc-thanhtho-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chính điện lặng như tờ, ngọn nến chập chờn trước tượng Phật, Thái hậu kéo ta lại gần, bàn tay gầy mà ấm."},{"who":"M","text":"{Goi}, Thái hậu hỏi {goi} năm nay muốn gì nhất. Người hỏi chậm rãi, ai cũng nghiêng tai nghe."},{"who":"me","text":"Một câu hỏi nhẹ như hơi thở, nhưng cả điện đang nín thở chờ. Ta không biết nên nói điều thật trong lòng, hay điều vừa lòng người."},{"who":"M","text":"Nô tỳ thấy Thái hậu nhìn {goi} rất lâu, như đang nhìn lại một người xưa."},{"who":"me","text":"Lời đáp này sẽ in vào lòng người. Ta cần chọn lời, thật thà mà không thiếu khéo."}]}},
{"id":"j71:fc-dongchi-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng sớm giá buốt, hơi thở đọng thành khói trước noãn các, giỏ than bạc sương nằm góc phòng chỉ còn một nửa."},{"who":"M","text":"{Goi}, than sưởi trong cung mình đã ít đi quá nửa. Dấu niêm Nội vụ phủ vẫn còn trên giỏ, mà một nửa than đã bị mang đi."},{"who":"me","text":"Giữa mùa đông, mất than là mất ấm. Ngón tay ta đã lạnh tê đây."},{"who":"M","text":"Có người thấy tay áo {B} dính bụi than. Nô tỳ không dám chắc điều gì."},{"who":"me","text":"Tay áo dính bụi than chưa phải là bằng chứng, nhưng cũng đủ để ta ngờ. Phải xử trí thế nào cho khỏi sai."}]}},
{"id":"j71:fc-dongchi-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tuyết rơi trắng sân, mái ngói phủ một lớp bạc, nơi cổng cung một bóng thị vệ đứng thẳng mà người run lên từng đợt."},{"who":"M","text":"{Goi}, thị vệ gác cổng cung mình run bần bật, tay tím tái. Nô tỳ không dám tự ý, đành đến chờ lệnh."},{"who":"me","text":"Tuyết rơi suốt buổi mà ông đứng suốt buổi. Lòng ta chợt thấy nhói."},{"who":"M","text":"Ông không dám kêu, chỉ giậm chân cho ấm. Nô tỳ nhìn mà không đành."},{"who":"me","text":"Một chút ấm áp giữa ngày đông có thể nhớ cả đời. Ta bước ra hiên, xem trong tay mình có gì."}]}},
{"id":"j71:fc-dongchi-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài cửa cung, trên bậc thềm lạnh, một chiếc áo bông thêu hoa mai đặt ngay ngắn, tuyết nhẹ phủ vai áo."},{"who":"M","text":"{Goi}, có chiếc áo bông thêu hoa mai đặt trước cửa cung mình, không ai nhận. Nơi cổ áo có một dấu thêu rất lạ."},{"who":"me","text":"Hoa mai thêu tinh tế, mà không đề tên, không kèm lời nhắn. Dấu lạ ở cổ áo như muốn kể chuyện gì."},{"who":"M","text":"Nô tỳ đã hỏi quanh, các cung đều lắc đầu. Áo còn ấm hơi sương, chắc mới đặt không lâu."},{"who":"me","text":"Áo này là lòng người hay lời nhắn, ta chưa rõ. Cầm trên tay mà thấy ấm lạ."}]}},
{"id":"j71:fc-dongchi-c04","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Hiên chờ phiên thi ngập hơi lạnh, chiếc lò sưởi tay bằng đồng chạm hoa mai vẫn ấm, nằm trong tay áo của người đang vội vã."},{"who":"B","text":"{Goi}, làm ơn canh giúp {xung} chiếc lò sưởi tay này nhé. {Xung} có việc gấp, đi một lát rồi quay lại ngay."},{"who":"me","text":"Một lát là bao lâu, {xung} không biết. Lò còn nóng, mà phiên thi của {xung} cũng sắp tới."},{"who":"B","text":"Chỉ một lát thôi, {goi} đừng lo. Lò này quý lắm, mất thì {xung} chịu không nổi."},{"who":"me","text":"Nàng đi nhanh như gió, để lại cái lò ấm trong tay {xung}. Nghĩ mà vừa buồn cười vừa bực, phải xử trí sao đây."}]}},
{"id":"j71:fc-lapbat-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước Phật đường, hơi cháo bốc nghi ngút trong nồi lớn, các cung nhân xếp hàng dài, tiếng muôi chạm thành nồi vang đều."},{"who":"M","text":"{Goi}, lúc phát cháo, {B} tới trước, múc đầy hai bát cho người của nàng. Phần của cung nhân mình chỉ còn đáy nồi."},{"who":"me","text":"Hai bát đầy cho người của nàng, đáy nồi cho người của ta. Giữa chốn từ bi mà cũng có chuyện này."},{"who":"M","text":"Họ đứng nhìn bát cháo mỏng, không ai dám than. Nô tỳ thấy mà xót."},{"who":"me","text":"Cháo thì ít, nhưng lòng người mới là điều nặng. Phải liệu thế nào cho họ khỏi tủi."}]}},
{"id":"j71:fc-lapbat-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bếp Phật đường khói bốc mù mịt, mùi khét nồng lẫn mùi gạo đậu, cung nhân các nơi lấp ló nhìn qua cửa."},{"who":"M","text":"{Goi}, nô tỳ canh nồi cháo của {goi} mà để khê một góc, mùi khét bay cả ra hành lang. Cung nhân các nơi đều nhìn sang."},{"who":"me","text":"Mùi khét lan nhanh hơn lời xin lỗi. Ta nghe cả hành lang đang xì xào về cháo cung ta."},{"who":"M","text":"Nô tỳ biết mình có lỗi. Nô tỳ thật không biết ăn nói sao."},{"who":"me","text":"Cháo khê thì khê, người vẫn còn. Ngươi đừng sợ, ta ra bếp xem nồi cháo đã."}]}},
{"id":"j71:fc-lapbat-c03","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Bên bếp Phật đường, nắp nồi cháo còn in dấu đồng cung nàng, một cô cung nữ lạ mặt đứng chắn trước, ánh mắt khẽ lấm lét."},{"who":"B","text":"{Goi}, cung nữ của {xung} sang xin nếm nồi cháo của {goi} trước giờ chấm, nói là Thái hậu dặn như vậy."},{"who":"me","text":"Thái hậu dặn mà {xung} chưa nghe lệnh nào. Dấu đồng trên nắp nồi vẫn nguyên, sao lại có chuyện này?"},{"who":"B","text":"Chắc truyền lời sai thứ tự thôi. {Goi} cho nếm một thìa, chẳng mất gì."},{"who":"me","text":"Một thìa nhỏ mà có thể thay đổi cả nồi cháo. Phải biết nên cho, hay không cho."}]}},
{"id":"j71:fc-lapbat-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên Phật đường, gió se se lùa qua, một chú tiểu áo nâu đứng ngượng nghịu, hai tay ôm cái bát gỗ trống."},{"who":"M","text":"{Goi}, chú tiểu bên Phật đường ngượng ngùng xin {goi} chút gạo đậu để nấu cháo cho các cụ già trong am ngoài cung."},{"who":"me","text":"Chú còn nhỏ mà đã nghĩ cho người già. Cái bát gỗ trống kia nhìn mà thương."},{"who":"M","text":"Chú nói am ngoài cung đang thiếu, các cụ chỉ trông vào lòng người. Chú đỏ mặt, không dám nhìn thẳng."},{"who":"me","text":"Xin gạo vì người khác, không vì mình, ta quý lắm. Mở kho ra, ta xem còn bao nhiêu để chia."}]}},
{"id":"j71:fc-giaothua-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gió lùa dọc hành lang, ngọn đèn thủ tuế chớp một cái rồi tắt phụt, chỉ còn sợi khói mảnh quấn lên mái ngói."},{"who":"M","text":"{Goi}, đèn thủ tuế của cung mình vừa bị gió thổi tắt. {B} đứng ngay phía đầu gió, tay còn khép áo."},{"who":"me","text":"Đèn thủ tuế tắt đúng đêm giao thừa, điềm gở ai cũng sợ. Ta nhớ rõ dấu cung ta khắc dưới đế đèn."},{"who":"M","text":"Nô tỳ không thấy nàng chạm vào đèn. Nhưng gió thổi từ phía nàng đứng thì rõ lắm."},{"who":"me","text":"Ngọn đèn thủ tuế cần thắp lại ngay, mà tay ai đứng đầu gió cũng cần được nhìn rõ. Ta cúi xuống nhặt đèn."}]}},
{"id":"j71:fc-giaothua-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm cuối năm, pháo hoa lập lòe phía xa, nơi hành lang một bóng áo quỳ xuống nền đá lạnh, tiếng khẩn cầu run rẩy."},{"who":"M","text":"{Goi}, nô tỳ xin phép ra khỏi cung nửa buổi để thăm mẹ già đêm giao thừa. Nô tỳ biết thông lệ không cho cung nhân ra ngoài đêm nay."},{"who":"me","text":"Đêm đoàn viên mà ngươi quỳ ở đây xin đi. Mẹ ngươi già rồi, chắc đang ngồi bên bếp lửa chờ."},{"who":"M","text":"Nô tỳ nguyện chịu mọi tội, chỉ cần được thấy mẹ một lát."},{"who":"me","text":"Một bên là luật cung, một bên là chữ hiếu. Ta nghe mà thấy lòng nặng trĩu."}]}},
{"id":"j71:fc-giaothua-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa sân đèn lồng đỏ, những chiếc túi chúc năm mới thêu chữ vàng được trao tay hết người này đến người khác."},{"who":"M","text":"{Goi}, vừa rồi lúc phát túi chúc, có người đọc nhầm chữ trên túi thành lời trêu ghẹo. Cả sân cười rộ lên."},{"who":"me","text":"Đọc nhầm một nét chữ mà thành chuyện trêu. Ta nghe mà suýt cười, nhưng ngại cho người đọc."},{"who":"M","text":"Nàng đỏ mặt cúi xuống, còn mọi người thì chưa dứt cười."},{"who":"me","text":"Ngày đầu năm, một tiếng cười có thể ấm lòng mà cũng có thể làm tủi. Để ta xem cách nào hợp nhất."}]}},
{"id":"j71:fc-giaothua-c04","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Sau giờ Tý, tiếng chiêng ngân xa, chiếc hộp nhỏ in dấu ngự tứ còn ấm hơi tay trong lòng bàn tay nàng."},{"who":"B","text":"{Goi} vừa được Hoàng thượng ban vật nhỏ, phải không? {Xung} thấy hết rồi. Chắc {goi} đã ngầm xin ngài từ trước."},{"who":"me","text":"Dấu ngự tứ còn nguyên trên hộp, mà nàng đã nói to như thế. Mọi người đang nhìn {xung}."},{"who":"B","text":"{Xung} chỉ nói điều ai cũng nghĩ. Ân sủng đâu tự nhiên mà có, {goi} nhỉ?"},{"who":"me","text":"Một lời đồn bắt đầu từ một câu nói nhẹ. {Xung} phải đáp sao cho không tự tổn thương mình."}]}},
{"id":"j71:fc-xb-c01","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm hội kéo dài, đèn lồng đã dịu, sương xuống phủ trên mái ngói, hơi lạnh thấm dần vào tay áo."},{"who":"M","text":"{Goi}, sương xuống lạnh lắm rồi. Nô tỳ mang chiếc khăn choàng dày đến cho {goi}, xin hỏi {goi} nên ở lại hay về."},{"who":"me","text":"Chiếc khăn còn ấm hơi tay ngươi. Hội đã tàn dần mà ta vẫn còn muốn ngắm."},{"who":"M","text":"Nô tỳ nghĩ tiết trời sắp lạnh hơn. {Goi} giữ gìn long thể quan trọng hơn."},{"who":"me","text":"Giữa nỗi lưu luyến và cái rét, hội vẫn chưa tàn. Ta cầm khăn trong tay, chưa nỡ choàng."}]}},
{"id":"j71:fc-xb-c02","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa sân hội, tiếng nói cười rộn rã, riêng một góc có bóng áo mới tinh đứng nép bên cột, đôi tay xoắn vào nhau."},{"who":"M","text":"{Goi}, có một cung nhân lạ mặt rụt rè hỏi {goi}, xin được đứng cạnh vì nàng mới vào cung, chưa quen ai."},{"who":"me","text":"Mới vào cung, chốn lạ người lạ, ta nhớ cảm giác ấy. Đôi tay xoắn lại như muốn nấp vào đâu đó."},{"who":"M","text":"Nàng nói xong thì cúi đầu, không dám nhìn lên."},{"who":"me","text":"Một chỗ đứng nhỏ mà là cả chỗ dựa với nàng. Ta nhìn nàng, nhìn đám đông, rồi mới mở lời."}]}},
{"id":"j71:fc-xb-c03","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng tù và của thái giám vang lên, hơi rượu nhẹ còn vương trên đầu lưỡi, hai gò má ửng hồng như cánh đào."},{"who":"M","text":"{Goi}, khi thái giám thổi tù và, {goi} mới nhận ra lúc nãy đã lỡ nói với nô tỳ vài câu thật lòng."},{"who":"me","text":"Mấy chén rượu nhẹ mà lời lại nhẹ hơn chén. Ta nói gì, ngươi nhớ không?"},{"who":"M","text":"Nô tỳ nghe cả. Nhưng nô tỳ là người giữ miệng, {goi} đừng lo."},{"who":"me","text":"Rượu làm lòng hở, lời hở thì khó vá. Ta nhìn ngươi, hỏi sao cho khéo."}]}},
{"id":"j71:fc-xb-c04","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiếc hộp gấm nhỏ nằm trên bàn, không đề tên, nắp có dấu niêm lạ, thái giám đưa tới đã lẩn vào đám đông."},{"who":"M","text":"{Goi}, một thái giám lạ vừa đặt chiếc hộp này lên bàn {goi}, không nói ai gửi, rồi quay đi ngay."},{"who":"me","text":"Hộp gấm không tên, dấu niêm lạ. Nửa muốn mở nửa muốn ngại."},{"who":"M","text":"Nô tỳ nhìn dấu niêm mãi mà không nhận ra là của cung nào."},{"who":"me","text":"Quà không rõ người, mở ra là phúc hay họa. Chiếc hộp nằm đó, nhìn ta trân trân."}]}},
{"id":"j71:fc-xb-c05","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Khay bánh kẹo bày giữa bàn, sắc đỏ sắc vàng trông bắt mắt, mùi mật đường thơm lan trong gió nhẹ."},{"who":"B","text":"Mời {goi} và mọi người dùng bánh kẹo của cung {xung}. {Goi} đừng khách sáo, {xung} không cần ai đáp lễ đâu."},{"who":"me","text":"Nói không cần đáp lễ, mà nàng liếc về phía khay của {xung}. Mắt nàng nói nhiều hơn miệng."},{"who":"B","text":"Bánh này {xung} tự tay làm, {goi} nếm thử xem. Nhà ai cũng ngon, nhưng cũng nên so cho biết."},{"who":"me","text":"Bánh ngọt mà lời chua, {xung} nghe được cả ý trong đó. Phải đáp sao cho vừa lễ."}]}},
{"id":"j71:fc-xb-c06","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Giữa sân đông người, hương rượu hòa trong hương hoa, một nụ cười quen quen nở trên môi người vừa tiến tới."},{"who":"B","text":"{Goi}, lâu lắm mới gặp. {Xung} vui lắm, hôm nay hội đông thế này, mong {goi} nâng chén cùng {xung}."},{"who":"me","text":"Nụ cười ấy {xung} nhận ra. Năm xưa trên hành lang, chính bàn tay này đã đẩy {xung} ngã."},{"who":"B","text":"{Goi} sao im lặng thế? Hay là rượu làm {goi} quên mất chuyện cũ rồi?"},{"who":"me","text":"Nàng nhắc chuyện cũ như chuyện chơi. Nhìn nụ cười ấy, từng chữ {xung} thốt ra đều phải nặng."}]}},
{"id":"j71:fc-xb-c07","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới chân bàn tiệc, một đứa trẻ nhỏ nép vào vạt váy, mắt đỏ hoe, tay ôm chặt chiếc trống nhỏ sơn đỏ đã bong mép."},{"who":"M","text":"{Goi}, một đứa nhỏ con cung nhân chạy lạc tới chân {goi}, khóc thút thít, tay nắm chặt chiếc trống nhỏ."},{"who":"me","text":"Chiếc trống nhỏ sơn đỏ bong ở mép, chắc là đồ chơi thân thiết nhất của bé. Nhìn bé ôm mà thương."},{"who":"M","text":"Bé không nói tên, cũng không nói mẹ ở đâu, chỉ nức nở mãi."},{"who":"me","text":"Ta muốn dỗ cho bé nín, mà cũng muốn tìm nhanh mẹ bé. Phải xem làm cách nào."}]}},
{"id":"j71:fc-xb-c08","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Dưới bóng hoa, tiếng đàn thấp thoáng, tờ giấy hoa tiên với mấy dòng thơ vừa viết xong còn thơm mùi mực mới."},{"who":"B","text":"{Goi} này, bài thơ {goi} viết hay quá, cho {xung} mượn một lát để ghi nhớ. {Xung} chỉ muốn học thôi."},{"who":"me","text":"Mượn để ghi nhớ, chắc là để đọc lên như của mình. {Xung} thấy rõ ý trong mắt nàng."},{"who":"B","text":"Chỉ là mượn thôi mà, {goi}. Chị em với nhau, có gì mà phải giữ."},{"who":"me","text":"Chữ của {xung} nằm trong tay nàng thì sẽ thành chữ của ai, {xung} còn phải tính. Nên đáp thế nào đây."}]}},
{"id":"j71:fc-xb-c09","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa bụi phủ kín sân hội, đèn lồng nhòe như những đóa hoa ướt, tiếng nhạc cũng nhỏ đi trong màn nước."},{"who":"M","text":"{Goi}, mưa bụi phủ kín sân hội, đèn lồng nhòe dần. Nô tỳ đứng cạnh {goi}, chỉ còn biết thở dài nhìn về phía cổng cung."},{"who":"me","text":"Ngươi thở dài làm ta cũng nghe nặng lòng. Trông về cổng cung, là nhớ nhà, hay nhớ ai?"},{"who":"M","text":"Nô tỳ không dám nói rõ. Chỉ là mưa làm người ta dễ nghĩ ngợi."},{"who":"me","text":"Mưa bụi thấm cả vào lòng. Hỏi ngươi, hay để ngươi tự mở lời, ta quay sang nhìn nàng."}]}},
{"id":"j71:fc-xb-c10","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên bàn hội, tiếng khen vang lên liên tiếp, bao khuôn mặt tươi như hoa xuân, nhưng nụ cười nào cũng hơi gượng."},{"who":"M","text":"{Goi}, cung nhân các nơi xúm lại khen {goi} tới tấp. Ai cũng cười tươi, mà nô tỳ thấy họ đang cố giấu một chuyện gì."},{"who":"me","text":"Khen nhiều quá thành lạ. Ánh mắt họ liếc nhau, lời khen nghe như bình phong che sau lưng."},{"who":"M","text":"Nô tỳ nghe loáng thoáng họ thì thầm, nhưng không rõ chuyện gì."},{"who":"me","text":"Giữa tiếng khen ngợi mà lòng ta bất an. Hỏi thẳng một câu, nụ cười nào sẽ tắt trước?"}]}},
{"id":"j71:fc-xb-c11","dlg":{"L":"B","R":"me","lines":[{"who":"nar","text":"Sắp tàn hội, đèn dầu dịu xuống, trên tay áo người vừa đến còn thoang thoảng hương hoa lài cung nàng."},{"who":"B","text":"{Goi}, sau hội xin mời {goi} sang cung {xung} dùng trà. {Xung} đã dặn người pha loại ngon nhất."},{"who":"me","text":"Lời mời tha thiết thế, nhưng {xung} vừa nhận một lời mời khác, cũng từ một phi tần khác. {Xung} chỉ có thể đến một nơi."},{"who":"B","text":"{Goi} còn do dự sao? Nghe nói bên kia cũng mời. Nhưng {xung} mong {goi} đừng để lời mời của {xung} đến muộn."},{"who":"me","text":"Nàng đã biết cả chuyện kia mà vẫn mỉm cười. Hai lời mời, một đôi chân, {xung} phải đáp ngay lúc này."}]}},
{"id":"j71:fc-xb-c12","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên gốc hòe cuối sân, một lão thái giám áo xanh cũ đứng khom lưng, mảnh giấy thư run run trên đôi tay chai sạn."},{"who":"M","text":"{Goi}, một thái giám già nhờ {goi} viết hộ dòng chữ chúc gửi người thân, vì ông không biết chữ. Tay ông run, giấy thư cũng run."},{"who":"me","text":"Mảnh giấy thư mang cả nét mực run lẫn dấu tay lão. Người nhà ông ở xa, chắc ông mong lắm."},{"who":"M","text":"Ông sẽ gửi qua tay thị vệ cổng cung. Nô tỳ nghĩ ông đã đợi mãi mới dám mở lời."},{"who":"me","text":"Mấy dòng chữ nhỏ mà gửi cả lòng ông, ta phải chọn cách giúp ông cho chu đáo."}]}},
{"id":"j70:poison:tyv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều muộn, ánh nắng xiên qua cửa Thái y viện, cung nữ trở về với vạt áo còn vương mùi dược liệu hăng hắc."},{"who":"M","text":"{Goi}, nô tỳ vừa thấy có người vào Thái y viện hỏi mua thạch tín, nói là để trừ chuột. Nô tỳ nghe mà lạnh cả sống lưng."},{"who":"me","text":"Thạch tín để trừ chuột thì cung nào cũng có thể mua. Nhưng người đứng ra hỏi lại cố nói nhỏ, ấy là điều đáng ngờ."},{"who":"M","text":"Lại thêm, nô tỳ thấy có người lén cất một gói bột trắng dưới đáy hộp phấn. Nhìn bề ngoài không ai nghĩ đó là độc."},{"who":"me","text":"Gói bột dưới đáy hộp phấn, thứ ấy ai cũng dễ dùng mà khó đề phòng. Ta phải liệu cách cho người nếm thử trước mọi món, hoặc nhờ thái y đánh tráo gói ấy."}]}},
{"id":"j70:poison:bep","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Canh ba, bếp nhỏ phía sau cung vắng lặng, chỉ có cung nữ run run thuật lại điều mình thấy bên bậc cửa Ngự thiện phòng."},{"who":"M","text":"{Goi}, nô tỳ thấy có người ở Ngự thiện phòng lén nhận bạc lúc canh ba. Nhận xong còn nhìn quanh mấy lượt."},{"who":"me","text":"Nhận bạc lúc canh ba, nhìn quanh như sợ ai thấy. Bạc ấy không phải tiền công, ta đoán vậy."},{"who":"M","text":"Sau đó có người hỏi kỹ giờ nấu điểm tâm cho các cung. Hỏi rất tỉ mỉ, cứ như đã định sẵn việc gì."},{"who":"me","text":"Hỏi giờ nấu điểm tâm là hỏi giờ có thể xuống tay. Ta chỉ dùng bếp nhỏ trong cung mình, hoặc bỏ bạc mua lại tên đầu bếp kia để hắn khai."}]}},
{"id":"j70:poison:tsv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới góc tường sau cung, bóng cây che kín lối đi, cung nữ nép mình sau hòn non bộ, đến giờ tay vẫn chưa hết run."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hẹn gặp một cung nữ của cung bên cạnh ở góc tường sau. Họ nói rất khẽ."},{"who":"me","text":"Gặp nhau ở góc tường khuất mà nói khẽ như thế, chắc là không muốn ai nghe thấy. Rồi sao nữa?"},{"who":"M","text":"Rồi người ấy dúi cho cung nữ kia một túi bạc nặng. Cung nữ cầm lấy, không nói gì, chỉ gật đầu."},{"who":"me","text":"Một túi bạc nặng, một cái gật đầu. Ta phải đổi người dâng trà, khóa chặt tủ trà, và gọi riêng nàng ấy ra cho nàng một đường lui."}]}},
{"id":"j70:poison2:tra","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong gian trà thơm ngát, cung nữ nâng hộp trà mới tới, đôi mày nhíu lại như vừa nhớ ra điều gì khiến lòng không yên."},{"who":"M","text":"{Goi}, nô tỳ thấy có người sai mua loại trà quý ngoài cung, đóng hộp rất cầu kỳ, như để đem tặng ai."},{"who":"me","text":"Trà quý đóng hộp cầu kỳ, nhìn thì là một món quà tử tế. Nhưng ta biết quà càng đẹp càng phải đề phòng."},{"who":"M","text":"Đêm qua nô tỳ còn nghe có người đóng cửa sao trà, mùi lạ bay ra ngoài hiên, chẳng giống mùi trà thường."},{"who":"me","text":"Mùi lạ lẫn trong khói trà thì không phải tình ý. Mọi món quà gửi đến ta đều phải thử trước, và ta sẽ nhờ người đổi hộp trà trước khi nó tới tay."}]}},
{"id":"j70:poison2:son","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài chợ, tiếng rao lẫn tiếng bước chân tấp nập, cung nữ ôm giỏ trở về, mặt tái đi khi nhắc lại điều mình nghe."},{"who":"M","text":"{Goi}, nô tỳ nghe có người hỏi mua chu sa và thủy ngân ở chợ ngoài. Người bán còn ngạc nhiên vì họ hỏi quá nhiều."},{"who":"me","text":"Chu sa và thủy ngân đều là thứ độc, ai cần đến chúng mà lại hỏi nhiều thế. Ngươi còn nghe thêm gì?"},{"who":"M","text":"Nô tỳ nghe nói có người sai thợ làm một hộp son mới, khắc hoa rất đẹp. Hộp son ấy rồi sẽ đưa đi đâu thì nô tỳ không biết."},{"who":"me","text":"Hộp son khắc hoa đẹp nhưng bên trong là gì thì không ai thấy. Ta chỉ dùng son phấn của Nội vụ phủ, và chặn mọi hộp son lạ ở đó."}]}},
{"id":"j70:poison2:huong","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Khói trầm lượn nhẹ trong gian phòng, cung nữ quỳ bên lò hương, đôi mắt nhìn chằm chằm vào làn khói xanh mảnh."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua một loại hương lạ ở Thái y viện, nói là trị mất ngủ. Ai ngửi cũng thấy dễ chịu."},{"who":"me","text":"Hương trị mất ngủ nghe rất nhẹ nhàng, nhưng mùi hương ấy lẫn vào gì thì khó đoán. Ngươi nghĩ sao?"},{"who":"M","text":"Nô tỳ nghe có người hỏi thăm cung nữ coi lò hương trong cung. Hỏi rất kỹ ai đốt, đốt lúc nào."},{"who":"me","text":"Hỏi người coi lò hương là hỏi chỗ có thể bỏ thuốc. Ta sẽ mở cửa cho thoáng, đổi lò hương, và đem mẫu hương đến Thái y viện nghiệm."}]}},
{"id":"j70:musk:xh","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chợ ngoài cung đông người, mùi hương liệu quyện lẫn nhau, cung nữ đi lẫn trong đám đông, chợt dừng chân nhìn một quầy hàng."},{"who":"M","text":"{Goi}, nô tỳ thấy có người lén mua xạ hương ở chợ ngoài cung, trả tiền xong là đi vội, không nhìn lại."},{"who":"me","text":"Xạ hương là thứ hại thai, thuốc nào cũng kiêng. Mua lén mà đi vội thế, chẳng giống người dùng hương thơm."},{"who":"M","text":"Sau đó nô tỳ lại thấy có người may một túi thơm rất khéo, nói là để tặng. Mũi chỉ rất đều, thêu rất kỹ."},{"who":"me","text":"Túi thơm khéo mấy cũng không dám nhận. Ta sẽ không nhận đồ tặng của ai mà không rõ lai lịch, và chặn người đưa xạ hương ở cửa cung."}]}},
{"id":"j70:musk:ty","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong Thái y viện, tiếng cối giã thuốc đều đều, cung nữ đứng đợi ngoài hành lang, ánh mắt dõi theo một bóng áo thái y vừa đi qua."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mời một vị thái y sang cung trò chuyện rất lâu, đóng cửa kín, không cho ai vào."},{"who":"me","text":"Trò chuyện lâu mà đóng cửa kín, lời nói hẳn không dành cho tai người ngoài. Thái y ấy có gì khác lạ không?"},{"who":"M","text":"Có, {goi}. Mấy hôm sau vị thái y ấy bỗng có thêm bạc gửi về quê, mà nhà ông vốn chẳng dư dả gì."},{"who":"me","text":"Bạc gửi về quê của một thái y chưa chắc là bạc sạch. Ta chỉ uống thuốc do thái y tâm phúc sắc, và giữ lại bã thuốc để làm chứng."}]}},
{"id":"j70:musk:hh","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên cửa bếp, hơi nóng bốc lên cùng mùi canh bổ, cung nữ đứng nép, mắt nhìn quanh như sợ ai nghe thấy."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hỏi mua hồng hoa ở tiệm thuốc, nói là để nhuộm vải. Nhưng người ấy chẳng có việc nhuộm vải nào."},{"who":"me","text":"Hồng hoa nhuộm vải cũng được, mà hại thai cũng được, tùy tay người dùng. Còn điều gì khác?"},{"who":"M","text":"Nô tỳ thấy người ấy dò xem bếp nào nấu canh bổ cho người trong cung. Dò từng bếp một, chẳng sót bếp nào."},{"who":"me","text":"Dò bếp nấu canh bổ thì mục đích đã rõ. Mọi bát canh đều phải qua tay ma ma thử, và ta sẽ bắt quả tang kẻ mang hồng hoa vào bếp."}]}},
{"id":"j70:musk:tsv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới hiên sắc thuốc, bếp lò đỏ than, cung nữ đứng bên người sắc thuốc, giọng khẽ như sợ làm vỡ một điều gì."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng cung nữ sắc thuốc an thai. Gặp chớp nhoáng rồi tản ra, như chưa hề nói gì."},{"who":"me","text":"Người sắc thuốc an thai mà bị gặp riêng, nghe đã thấy bất an. Nàng ta dạo này ra sao?"},{"who":"M","text":"Nàng ấy hay giật mình, tay có vết bỏng lạ, lại tránh nhìn nô tỳ. Nô tỳ hỏi mãi nàng cũng chỉ lắc đầu."},{"who":"me","text":"Vết bỏng lạ, đôi mắt tránh né, nàng đang giấu một điều nặng. Ta tự tay coi ấm thuốc, rồi gọi nàng ra hỏi chuyện cho thật dịu dàng."}]}},
{"id":"j70:catswap:bd","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Gần ngày sinh, cung đã sắp sẵn khăn tã, cung nữ lặng lẽ bước vào, trên tay còn dính hơi lạnh của gió sân."},{"who":"M","text":"{Goi}, nô tỳ thấy có một bà đỡ lạ ra vào cung. Không ai gọi bà ta tới, mà bà ta vẫn đi lại rất thong thả."},{"who":"me","text":"Một bà đỡ lạ ra vào mà không ai mời, ấy là chuyện không nhỏ. Bà ấy trông thế nào?"},{"who":"M","text":"Bà ta được may áo mới, đeo vòng bạc, trong khi nhà vốn nghèo. Nô tỳ thấy lạ mà không dám hỏi."},{"who":"me","text":"Áo mới, vòng bạc, tiền từ đâu mà có? Ta sẽ chọn bà đỡ do Thái hậu ban, và đổi bà đỡ ngay trước kỳ sinh."}]}},
{"id":"j70:catswap:nv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong Nội vụ phủ, sổ sách xếp ngay ngắn trên án, cung nữ đứng đợi ngoài cửa, tai nghe rõ từng tiếng thì thầm bên trong."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đút lót quản sự Nội vụ phủ, hỏi việc cắt cử bà đỡ. Người ấy cười rất niềm nở."},{"who":"me","text":"Đút lót quản sự để hỏi việc bà đỡ, chuyện này không phải chuyện thường. Họ còn hỏi gì nữa?"},{"who":"M","text":"Họ dò cả ngày dự sinh. Hỏi rất khéo, như chỉ tò mò, nhưng quản sự lại ghi hẳn vào sổ."},{"who":"me","text":"Dò ngày dự sinh rồi cắt cử bà đỡ, cả hai chuyện dính vào nhau thì ta phải đề phòng. Ta sẽ xin Hoàng thượng tự chỉ định bà đỡ, và tố với Nội vụ phủ."}]}},
{"id":"j70:catswap:dọa","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài cung, ngõ nhỏ chiều tàn, cung nữ trở về với đôi giày lấm bùn, sắc mặt không còn hồng hào như mọi ngày."},{"who":"M","text":"{Goi}, nô tỳ thấy có người ra ngoài cung tìm nhà một bà đỡ, hỏi han kỹ càng, ra vẻ không có ý tốt."},{"who":"me","text":"Tìm tận nhà bà đỡ mà hỏi, ý đã không còn là chuyện thăm hỏi. Bà ấy thế nào rồi?"},{"who":"M","text":"Bà đỡ ấy sau đó mặt cắt không còn hột máu, đi đâu cũng như người mất hồn. Nô tỳ gọi mà bà cũng không đáp."},{"who":"me","text":"Một người sợ đến mất hồn thì ai bảo gì cũng nghe. Ta sẽ cho bà đỡ ở hẳn trong cung, và che chở gia quyến bà để bà dám nói thật."}]}},
{"id":"j70:kpoison:vu","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên cửa sau cung, ánh chiều đổ dài trên bậc đá, cung nữ nhìn theo bóng người vừa khuất sau khúc quanh hành lang."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hẹn gặp vú nuôi của hoàng tự ở cửa sau. Họ nói chuyện rất lâu mà nhìn quanh luôn luôn."},{"who":"me","text":"Hẹn gặp vú nuôi của con ta ở cửa sau, không phải chuyện thăm hỏi bình thường. Còn gì nữa?"},{"who":"M","text":"Về sau vú nuôi ấy được cho một đôi hoa tai vàng. Nàng đeo giấu trong tay áo, không dám để ai thấy."},{"who":"me","text":"Đôi hoa tai vàng là giá của một lòng tin. Ta sẽ đổi vú nuôi, tự mình trông con, hoặc gọi nàng ra hứa che chở nếu nàng chịu khai."}]}},
{"id":"j70:kpoison:keo","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiệm bánh ngoài cung thơm mùi hạt sen, cung nữ đứng nhìn qua cửa kính, nhớ lại điều mình vừa nghe được."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đặt một hộp bánh hạt sen rất đẹp ngoài chợ, dặn kỹ phải gói thật khéo, như để tặng người."},{"who":"me","text":"Một hộp bánh gói khéo, bánh hạt sen là món trẻ con ưa. Họ còn dò hỏi điều gì không?"},{"who":"M","text":"Có, người ấy hỏi hoàng tự thích ăn món gì, hỏi rất tự nhiên mà người bán bánh còn nhớ lâu."},{"who":"me","text":"Hỏi trẻ con thích ăn gì rồi gói bánh thật đẹp, chuyện ấy không lành. Ta không cho con ăn đồ ai mang đến, và chặn hộp bánh đem đi nghiệm."}]}},
{"id":"j70:kpoison:chao","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mờ sáng, Thái y viện còn vắng người, cung nữ đi ngang cửa thuốc, bước chân chợt khựng lại vì một câu hỏi lạ."},{"who":"M","text":"{Goi}, nô tỳ nghe có người vào Thái y viện hỏi mua thạch tín, nói là để trừ chuột. Ông thái y còn dặn dò kỹ."},{"who":"me","text":"Lại thạch tín. Thứ ấy trừ chuột được mà hại người cũng được. Chuyện này không phải một mình thạch tín."},{"who":"M","text":"Đúng vậy, {goi}. Cũng có người ở Ngự thiện phòng hỏi giờ dâng cháo cho các hoàng tự. Hai chuyện cách nhau mà đều nhắm vào bữa ăn của trẻ."},{"who":"me","text":"Bữa cháo của con ta mà cũng có người nhòm ngó. Ta sẽ tự nấu cháo trong cung mình, cắt đường bếp và bắt kẻ mua thuốc."}]}},
{"id":"j70:pond:lo","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ven hồ sen lộng gió, bậc đá còn ướt, cung nữ đứng nhìn mặt nước phẳng lặng mà lòng không yên."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hay dẫn người ra hồ sen dò lối, còn hỏi giờ các hoàng tự đi chơi. Hỏi lúc nào cũng thật ra vẻ vô tình."},{"who":"me","text":"Hỏi giờ con ta đi chơi, mà lại dò cả lối đi ra hồ. Ngươi thấy họ làm gì thêm?"},{"who":"M","text":"Họ sai người nhổ bớt lan can gỗ bên hồ. Nô tỳ nhìn lại thì lan can thưa hẳn đi, trẻ con chạy qua dễ ngã."},{"who":"me","text":"Lan can bị nhổ bớt, bờ hồ thành cái bẫy. Ta không cho con ra hồ khi không có người lớn, và báo Nội vụ phủ sửa lan can, canh hồ."}]}},
{"id":"j70:pond:hoi","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngày hội sắp tới, trong vườn đã giăng đèn lồng, cung nữ lặng nhìn từng dãy đèn mà lòng thấy một nỗi bất an mơ hồ."},{"who":"M","text":"{Goi}, nô tỳ nghe có người hỏi kỹ lịch lễ hội và chỗ các hoàng tự đứng xem. Họ hỏi rất cặn kẽ, như đã tính trước từng bước."},{"who":"me","text":"Hỏi lịch hội, hỏi chỗ trẻ con đứng xem. Trong ngày hội đông người, nhìn kỹ mới thấy chỗ sơ hở. Còn gì nữa?"},{"who":"M","text":"Có người lạ trà trộn vào đám thị vệ, mặt không quen, nô tỳ hỏi tên mà họ nói khác nhau."},{"who":"me","text":"Người lạ lẫn trong thị vệ ngày hội đông, ấy là điều đáng sợ. Ta sẽ giữ con sát bên, và nhờ thị vệ tâm phúc canh chừng."}]}},
{"id":"j70:pond:dieu","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều xuống trên hồ sen, gió thổi mặt nước gợn từng vòng, cung nữ đứng bên bờ nhìn lên bầu trời có một cánh diều lạ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua một con diều hình phượng rất đẹp. Nô tỳ nhìn mà ngỡ như để dành cho một đứa trẻ nào."},{"who":"me","text":"Diều hình phượng đẹp như thế, trẻ con nào cũng muốn cầm. Họ thả ở đâu?"},{"who":"M","text":"Thả gần hồ, mấy chiều liền. Hôm nào cũng có vài đứa trẻ nhìn theo, lại gần dần bờ nước."},{"who":"me","text":"Dùng diều để dụ con trẻ đến gần hồ, toan tính ấy thật nham hiểm. Ta dặn con không đi theo người lạ, và bắt kẻ thả diều hỏi chuyện."}]}},
{"id":"j70:pushp:gio","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau cơn mưa, bậc đá trơn ướt, rêu xanh bám đầy mép đá bên hồ sen, cung nữ cúi nhìn mà lòng thấy rờn rợn."},{"who":"M","text":"{Goi}, nô tỳ thấy có người dò giờ người ta đi qua bậc đá trơn sau mưa. Người ấy đứng lặng, đếm từng người qua lại."},{"who":"me","text":"Bậc đá trơn, giờ người qua lại, người nào dò mấy thứ ấy hẳn không vì thơ thẩn. Còn gì nữa?"},{"who":"M","text":"Họ còn đứng lâu bên hồ sen mỗi chiều. Nô tỳ nhìn thì họ không ngắm hoa, chỉ nhìn bậc đá."},{"who":"me","text":"Nhìn bậc đá mà không ngắm hoa, ý đã lộ rồi. Ta không dạo vườn một mình lúc chiều tối, và báo Nội vụ phủ rắc cát bậc đá, canh hồ."}]}},
{"id":"j70:pushp:den","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm hội đèn sắp đến, hành lang treo kín lồng đèn, cung nữ nhìn dãy đèn mà nhớ lại mấy câu hỏi lạ nghe được hôm qua."},{"who":"M","text":"{Goi}, nô tỳ nghe có người hỏi đường đi của các cung trong đêm hội. Họ hỏi rất kỹ, hỏi cả lối đi vòng sau hồ."},{"who":"me","text":"Hỏi lối đi của các cung, hỏi cả đường vòng sau hồ. Trong đêm hội, người ta ít để ý chân mình. Còn gì?"},{"who":"M","text":"Có người sai tắt bớt đèn bên hồ, nói là để tiết kiệm dầu, nhưng bờ hồ tối hẳn đi, lối đi mờ như bóng ma."},{"who":"me","text":"Tắt bớt đèn bên bờ hồ giữa đêm hội, ấy là sắp đặt có chủ ý. Ta đi hội có thị vệ đi kèm, và nhờ thị vệ thắp đèn suốt bờ hồ."}]}},
{"id":"j70:pushp:tsv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trên đường về cung, cung nữ ôm chặt khăn tay, thỉnh thoảng nhìn lại phía sau như sợ có ai theo."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng cung nữ hầu {goi} đi dạo. Gặp ngoài cổng, nói chuyện rất nhỏ rồi vội đi."},{"who":"me","text":"Gặp riêng cung nữ hầu ta, ngoài cổng, nói nhỏ thế. Ngươi có biết họ nói gì không?"},{"who":"M","text":"Nô tỳ không nghe rõ, chỉ thấy nàng ấy dạo này hay rủ chủ ra hồ sen ngắm trăng, mà trước kia nàng chưa từng thích."},{"who":"me","text":"Người hầu bỗng thích ngắm trăng bên hồ, ấy không phải vô cớ. Ta không theo lời rủ ra hồ lúc vắng, và gọi nàng ra hỏi chuyện."}]}},
{"id":"j70:kframe:bup","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ, ánh đèn khuya chưa tắt, cung nữ đứng dưới hiên, nghe tiếng kim chỉ lách cách vọng ra từ bên kia tường."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua vải vàng và kim bạc, đêm đêm đóng cửa may vá. Ánh đèn sáng đến gần sáng."},{"who":"me","text":"Vải vàng, kim bạc, đóng cửa may đêm. Thứ ấy không phải đồ may áo. Còn gì lạ không?"},{"who":"M","text":"Có người hỏi ngày sinh tháng đẻ của hoàng tự. Hỏi rất khéo mà nô tỳ thấy lạ, vì chẳng ai cần biết thứ ấy."},{"who":"me","text":"Ngày sinh tháng đẻ của con ta mà lọt vào tay kẻ có ý xấu, ta không thể yên. Ta sẽ cho người soát phòng con mỗi tối, thấy hình nhân nào thì đốt ngay."}]}},
{"id":"j70:kframe:thay","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên thư phòng của hoàng tự, giấy bút còn bày ngổn ngang, cung nữ nhìn quanh rồi hạ giọng như sợ vách có tai."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mời thầy dạy của hoàng tự đến uống rượu. Uống rất lâu, cười nói rất vui."},{"who":"me","text":"Mời thầy dạy uống rượu, vui vẻ như vậy, chắc không chỉ vì tình riêng. Rồi sao nữa?"},{"who":"M","text":"Thầy dạy ấy sau đó bỗng hay hỏi chuyện chữ viết của hoàng tự, hỏi cả cách cầm bút, cách gạch nét."},{"who":"me","text":"Thầy dạy quan tâm đến chữ viết của con ta đến thế, ta phải đề phòng. Ta sẽ đổi thầy dạy, hoặc nói chuyện riêng để cho ông đường lui."}]}},
{"id":"j70:kframe:chu","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau buổi học, trong thư phòng của hoàng tự, mấy tờ giấy nháp bị vứt trong giỏ, cung nữ nhìn giỏ giấy mà thấy lạ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người thu gom giấy viết bỏ của hoàng tự. Thu từng tờ một, kể cả tờ đã vo viên."},{"who":"me","text":"Giấy nháp của con ta, thu từng tờ, kể cả tờ đã vo viên. Chữ của con ta có gì đáng giữ đến vậy?"},{"who":"M","text":"Rồi nô tỳ nghe nói có người thuê một người khéo tay nhại chữ. Người ấy tập viết rất nhiều tờ, nét chữ giống đến lạ."},{"who":"me","text":"Giả chữ con ta, rồi viết điều gì không ai biết. Ta đốt hết giấy nháp của con, và tìm người nhại chữ, bắt hắn khai."}]}},
{"id":"j70:frame:bup","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm xuống, vườn hoa tối đen, cung nữ nép sau chậu lan, nhìn qua kẽ lá thấy một bóng người lảng vảng."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua vải vàng và kim bạc, đóng cửa may vá ban đêm. Lại có người đêm đêm lảng vảng quanh vườn một cung khác."},{"who":"me","text":"Vải vàng may đêm, rồi lảng vảng quanh vườn người khác. Hai chuyện gộp lại thì không lành."},{"who":"M","text":"Nô tỳ thấy đất dưới gốc cây ở đó mới xới, nhưng ai cũng nói không biết. Có lẽ có thứ gì đang bị giấu."},{"who":"me","text":"Đất mới xới dưới gốc cây, mà không ai nhận. Ta cho người đào xới, lục soát vườn, và đào búp bê lên trước để giữ làm tang chứng."}]}},
{"id":"j70:frame:tsv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa buổi chiều, hành lang cung vắng bóng người, cung nữ đứng đợi ở góc rẽ, thấy một bóng áo đang đứng nói chuyện khẽ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng một cung nữ bên cung kia. Nói chuyện khẽ, rồi cung nữ ấy lẳng lặng đi vào trong."},{"who":"me","text":"Gặp riêng cung nữ của cung khác, rồi nàng ấy đi vào trong. Nàng ấy làm gì ở đó?"},{"who":"M","text":"Nàng ấy hay vào phòng chủ lúc không ai gọi. Nô tỳ nhìn mà thấy lạ, vì từ trước nàng vốn rất giữ phép."},{"who":"me","text":"Cung nữ tự ý vào phòng chủ lúc không ai gọi, ấy là chuyện lớn. Ta khóa phòng ngủ, tự giữ chìa, và gọi nàng ấy ra tra hỏi."}]}},
{"id":"j70:frame:thu","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn hiên, mấy cuộn giấy chất trên bàn, cung nữ đứng nhìn mà trong lòng thấy một nỗi lo mơ hồ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người thu gom thư từ, giấy viết của một cung nhân. Thu từng lá một, gấp lại cẩn thận."},{"who":"me","text":"Thu thư từ giấy viết của người khác, mục đích hẳn không tốt. Còn gì nữa?"},{"who":"M","text":"Có người thuê một kẻ nhại chữ ở ngoài cung. Kẻ ấy nhận bạc rồi ngồi viết cả đêm, nét chữ giống đến mức nô tỳ cũng phải nhìn lâu."},{"who":"me","text":"Nhại chữ để viết thư tư thông với ngoại thần, ấy là mưu hại đến tận gốc. Ta đốt hết giấy viết thừa, và tìm kẻ nhại chữ, bắt hắn khai."}]}},
{"id":"j70:plant:lv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa trưa, cung vắng bóng người, chỉ còn tiếng gió lùa qua cửa, cung nữ đứng nhìn con đường phía bên kia cổng."},{"who":"M","text":"{Goi}, nô tỳ thấy có người lảng vảng quanh cung người khác lúc vắng người. Họ đi lại mấy lần mà không vào."},{"who":"me","text":"Lảng vảng lúc vắng người mà không vào, hẳn đang chờ lúc không ai trông. Rồi sao?"},{"who":"M","text":"Họ còn hỏi giờ cung nữ bên ấy đi lĩnh lương. Hỏi như chuyện phiếm, nhưng nô tỳ nghe thấy rất rõ."},{"who":"me","text":"Biết giờ cung nữ đi lĩnh lương là biết giờ cung vắng. Ta luôn để người trông cung, và lục rương trước để vứt đồ lạ đi."}]}},
{"id":"j70:plant:tsv","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều muộn, trong hành lang tối dần, cung nữ nhìn một bóng áo lẳng lặng đi ngang, tay áo phồng lên một cục."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp riêng một cung nữ bên cung kia. Cung nữ ấy sau đó giấu một bọc nhỏ trong tay áo."},{"who":"me","text":"Một bọc nhỏ trong tay áo, nhận từ người lạ. Bọc ấy sẽ đi đâu, ngươi có đoán được không?"},{"who":"M","text":"Nô tỳ đoán là đi vào một cái rương. Nhưng không dám chắc, vì nàng đi nhanh quá, chớp mắt đã mất bóng."},{"who":"me","text":"Một cái bọc không rõ lai lịch sẽ vào rương của ai đó. Ta tự giữ chìa khóa rương, và gọi cung nữ ấy ra hỏi chuyện."}]}},
{"id":"j70:bribe:bac","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới ánh trăng mờ, sân cung vắng, cung nữ đi ngang một dãy hiên tối, chợt nghe tiếng bạc khẽ chạm nhau."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đem bạc đổi thành ngân phiếu nhỏ. Rồi hẹn gặp kẻ hầu cung khác lúc canh ba."},{"who":"me","text":"Đổi bạc thành ngân phiếu nhỏ để dễ giấu, rồi hẹn lúc canh ba, người ấy rõ ràng muốn mua lòng người. Ngươi còn thấy gì?"},{"who":"M","text":"Kẻ hầu đó sau cuộc hẹn trở về mà vẻ mặt cứ đăm chiêu, đi đứng như người mất hồn."},{"who":"me","text":"Một lòng người có thể bị đổi bằng ngân phiếu. Ta tăng lương kẻ hầu, giữ lòng họ, và hỏi xem ai đã bị dụ."}]}},
{"id":"j70:bribe:doa","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài cổng cung, bóng chiều đổ dài, cung nữ ngồi bên kẻ hầu cũ, nghe nàng kể bằng giọng nhỏ như sợ ai nghe."},{"who":"M","text":"{Goi}, nô tỳ thấy có người ra ngoài cung dò nhà của kẻ hầu. Họ hỏi han hàng xóm rất tỉ mỉ."},{"who":"me","text":"Dò nhà kẻ hầu, hỏi han hàng xóm. Chẳng ai làm việc ấy chỉ vì tò mò. Kẻ hầu ấy dạo này ra sao?"},{"who":"M","text":"Nàng thất thần, nói chuyện không ra đầu đuôi, tay hay run. Nô tỳ hỏi mà nàng chỉ lắc đầu."},{"who":"me","text":"Một người bị dọa đến thất thần thì dễ bị người lợi dụng. Ta hỏi han gia cảnh kẻ hầu, và che chở gia quyến họ."}]}},
{"id":"j70:bribe:hua","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong Nội vụ phủ, tiếng bút sột soạt, cung nữ đứng đợi ngoài cửa nghe tiếng chuyện trò trong phòng vọng ra."},{"who":"M","text":"{Goi}, nô tỳ nghe có người nhờ quản sự Nội vụ phủ giữ chỗ trống. Họ nói là để dành cho người thân."},{"who":"me","text":"Giữ chỗ trống ở Nội vụ phủ, ấy là quyền của người có thế. Rồi có ai được hứa gì không?"},{"who":"M","text":"Có một kẻ hầu bên cung kia hay khoe sắp được đổi chỗ tốt. Nàng cười suốt ngày, mà không ai biết do đâu."},{"who":"me","text":"Một lời hứa đổi chỗ tốt đủ mua một người. Ta hứa cho kẻ hầu một tương lai tốt hơn, và hỏi thẳng Nội vụ phủ."}]}},
{"id":"j70:block:ksp","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm khuya, cạnh Kính sự phòng đèn vẫn sáng, cung nữ đi ngang qua, nhìn thấy hai bóng người đứng dưới mái hiên."},{"who":"M","text":"{Goi}, nô tỳ thấy có người gặp thái giám Kính sự phòng ban đêm. Họ nói chuyện rất nhỏ, tay đưa qua đưa lại."},{"who":"me","text":"Gặp thái giám Kính sự phòng ban đêm, tay đưa qua đưa lại, ý đã quá rõ. Thái giám ấy sau đó thế nào?"},{"who":"M","text":"Ông ta có thêm một chiếc nhẫn ngọc, đeo hẳn lên ngón tay, dù trước nay chưa từng có."},{"who":"me","text":"Chiếc nhẫn ngọc mới là giá của một tấm thẻ. Ta biếu Kính sự phòng trước, hoặc đến đó nói chuyện thẳng."}]}},
{"id":"j70:block:tq","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong sân Tổng quản, lễ vật hậu bày thành hàng, cung nữ lẩn qua đám người, tai nghe tiếng bàn tán thì thầm."},{"who":"M","text":"{Goi}, nô tỳ thấy có người đem lễ vật hậu sang chỗ Tổng quản. Hộp lễ nặng trĩu, phải hai người khiêng."},{"who":"me","text":"Lễ vật hậu như vậy, Tổng quản không thể không nhận. Về sau Tổng quản có gì khác không?"},{"who":"M","text":"Tổng quản bỗng lạnh nhạt mỗi khi nhắc tên {goi}. Nô tỳ nghe mà lòng hơi chùng xuống."},{"who":"me","text":"Lễ vật hậu đổi lấy sự lạnh nhạt của Tổng quản, thật khéo. Ta biếu Tổng quản một phần lễ, hoặc nhờ người nói khéo với ông."}]}},
{"id":"j70:block:benh","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong Thái y viện, hơi thuốc nhè nhẹ, cung nữ đứng trước án thuốc, nghe câu chuyện thì thầm ngoài hành lang."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hỏi Thái y viện về bệnh truyền nhiễm. Hỏi rất kỹ, ghi cả triệu chứng."},{"who":"me","text":"Hỏi bệnh truyền nhiễm, ghi triệu chứng, người ấy muốn biết điều gì? Còn gì nữa không?"},{"who":"M","text":"Rồi có người đồn nhỏ rằng {goi} ho suốt đêm. Tin ấy truyền từ cung này sang cung khác, chớp mắt đã khắp nơi."},{"who":"me","text":"Một tin bệnh đồn ra thì thẻ bài cũng bị rút. Ta mời thái y viết giấy khỏe mạnh, hoặc mời thái y bắt mạch công khai."}]}},
{"id":"j70:rumor:mama","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Buổi tối, ma ma già ngồi quanh bàn trà, tiếng trò chuyện rì rầm kéo dài, cung nữ nép ngoài cửa nghe lỏm."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mời các ma ma già uống trà, kể chuyện thâu đêm. Trà rót mãi, chuyện kể mãi."},{"who":"me","text":"Mời ma ma uống trà kể chuyện thâu đêm, hẳn có bạc đi kèm. Họ kể gì?"},{"who":"M","text":"Nô tỳ nghe một ma ma thì thầm tên {goi}. Giọng bà ta vừa như tiếc nuối, vừa như thích thú."},{"who":"me","text":"Một lời thì thầm từ ma ma già đi xa hơn trăm lời đồn. Ta giữ cho kẻ hầu kín miệng, và gặp các ma ma cho bạc gấp đôi để họ im."}]}},
{"id":"j70:rumor:tho","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng sớm, sương còn đọng trên cổng cung, cung nữ ôm giấy mực đi qua, chợt thấy một tờ giấy lạ dán bên tường."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua giấy và mực loại rẻ, không ai nhận là của mình. Họ mua nhiều hơn cần dùng."},{"who":"me","text":"Giấy mực rẻ mà mua nhiều như thế, chắc không phải để viết thư nhà. Ngươi còn thấy gì nữa?"},{"who":"M","text":"Đêm qua có người đi qua các cổng mà không mang đèn, nô tỳ thấy bóng nhưng không rõ mặt."},{"who":"me","text":"Đi qua các cổng trong đêm mà không đèn, ấy là kẻ dán thơ. Ta cho người gỡ thơ ngay khi thấy, và rình bắt kẻ dán."}]}},
{"id":"j70:rumor:tg","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong sân cung, bóng thái giám đi lại tấp nập, cung nữ đứng bên cột, nhìn qua những khuôn mặt quen thuộc."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hay trò chuyện với thái giám các cung. Cười nói rất vui, ai cũng ngỡ chuyện phiếm."},{"who":"me","text":"Hay trò chuyện với thái giám các cung, ấy là cách truyền tin nhanh nhất. Rồi sao?"},{"who":"M","text":"Thái giám bên ấy bỗng biết nhiều chuyện riêng của {goi}, biết đến cả những điều nô tỳ chưa từng nói với ai."},{"who":"me","text":"Chuyện riêng của ta đã lọt vào miệng thái giám các cung. Ta ít để kẻ lạ ra vào cung, và gọi thái giám ấy ra hỏi."}]}},
{"id":"j70:accuse:do","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước cửa cung, bóng cây in dài trên nền đá, cung nữ nhìn quanh rồi nói khẽ như sợ gió nghe thấy."},{"who":"M","text":"{Goi}, nô tỳ thấy có người cho kẻ rình rập trước cửa cung. Kẻ ấy đứng lâu, mắt nhìn chằm chằm vào cổng."},{"who":"me","text":"Cho người rình rập trước cửa cung, như ghi lại từng người ra vào. Họ còn làm gì nữa?"},{"who":"M","text":"Họ hỏi han cung nữ trong cung về giờ giấc của chủ. Hỏi rất tự nhiên, nhưng nô tỳ thấy lạ."},{"who":"me","text":"Giờ giấc của ta mà bị người ghi chép, thì lời ăn tiếng nói của ta cũng phải cẩn trọng. Ta bắt kẻ rình, đuổi đi."}]}},
{"id":"j70:accuse:chung","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài phố, một quán nước nhỏ chiều tàn, cung nữ ngồi cạnh một kẻ hầu cũ, nghe nàng kể bằng giọng nhỏ."},{"who":"M","text":"{Goi}, nô tỳ nghe có người tìm một kẻ hầu cũ bị đuổi khỏi cung này. Họ tìm rất lâu, hỏi khắp phố."},{"who":"me","text":"Tìm một kẻ hầu cũ bị đuổi, người ấy có lý do rồi. Tìm được rồi thì sao?"},{"who":"M","text":"Kẻ hầu cũ ấy được cho ăn ở tử tế, áo mới, nhà tốt. Người ta thấy nàng cười, mà trước kia nàng vốn chẳng cười."},{"who":"me","text":"Một kẻ hầu cũ đang được nuôi cho tử tế, chắc là để nói điều gì đó. Ta tìm kẻ hầu cũ trước, cho bạc, và đối xử tử tế với nàng."}]}},
{"id":"j70:accuse:so","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn hiên, một cuốn sổ nhỏ bị khép vội, cung nữ nhìn thoáng thấy, bước chân chợt khựng lại."},{"who":"M","text":"{Goi}, nô tỳ thấy có người ghi chép từng việc {goi} làm. Ghi rất kỹ, cả những việc nhỏ như ăn gì, đi đâu."},{"who":"me","text":"Ghi chép từng việc nhỏ của ta, như đang gom lỗi. Còn gì khác?"},{"who":"M","text":"Họ còn đếm số đồ trang sức {goi} đeo mỗi ngày. Đếm bằng mắt, ghi bằng bút, như người kiểm kê."},{"who":"me","text":"Kẻ chờ sơ hở sẽ nhìn từng món đồ ta đeo. Ta không mặc đồ quá phẩm, giữ lễ, và xin gặp nói chuyện thẳng để gỡ mối."}]}},
{"id":"j70:ksab:thay","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong thư phòng của hoàng tự, bàn học trống trải, cung nữ đứng cạnh án sách, thấy ghế thầy dạy bỏ không."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mời thầy dạy của hoàng tự uống rượu. Mời mấy bận, lần nào cũng ân cần."},{"who":"me","text":"Mời thầy dạy uống rượu mấy bận như vậy, chắc có điều muốn nhờ. Rồi sao nữa?"},{"who":"M","text":"Thầy dạy ấy dạo này hay cho hoàng tự nghỉ học. Nay nghỉ ngày này, mai nghỉ ngày khác, sách để phủ bụi."},{"who":"me","text":"Thầy dạy hay cho nghỉ là việc lạ. Ta tự kèm con học, hoặc đổi thầy dạy cho yên lòng."}]}},
{"id":"j70:ksab:choi","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều trên vườn hoa, tiếng cười trẻ con vang xa, cung nữ đứng nhìn từ xa, thấy một bóng lạ đang ngồi chơi với hoàng tự."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua dế và diều tặng hoàng tự. Quà đẹp, trẻ con nào cũng thích."},{"who":"me","text":"Mua dế mua diều tặng con ta, quà ấy hợp tuổi trẻ con. Nhưng tặng để làm gì?"},{"who":"M","text":"Người lạ ấy hay rủ hoàng tự ra vườn chơi. Chơi đến quên cả giờ học, nô tỳ gọi mà cũng chẳng chịu về."},{"who":"me","text":"Rủ con ta ham chơi để bỏ bê sách vở, mưu ấy thật độc. Ta giữ con ở thư phòng, và bắt kẻ dụ con, đuổi đi."}]}},
{"id":"j70:ksab:tin","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau buổi học, thầy dạy bước ra khỏi thư phòng, cung nữ đứng ngoài hành lang nghe thấy tiếng thì thầm bàn tán."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hỏi han thầy dạy về bài vở của hoàng tự. Hỏi rất kỹ, từng bài một."},{"who":"me","text":"Hỏi han thầy dạy về bài vở của con ta, ấy là điều thường. Nhưng ngươi có nghe thêm gì không?"},{"who":"M","text":"Có người đồn nhỏ rằng hoàng tự học mãi không thuộc. Lời đồn nhẹ như gió, nhưng người nghe thì đông."},{"who":"me","text":"Tin con ta đần độn mà lan ra thì khó gỡ. Ta cho con trả bài trước mặt mọi người, và mời thầy dạy nói rõ trước Hoàng thượng."}]}},
{"id":"j70:joint:hop","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm khuya, nhiều cỗ kiệu nhỏ qua lại ngoài cổng, cung nữ đứng sau cột, đếm từng bóng người đi vào một cung."},{"who":"M","text":"{Goi}, nô tỳ thấy người trong một phe họp kín ở cung chủ phe ban đêm. Người các cung trong phe qua lại dày đặc."},{"who":"me","text":"Họp kín ban đêm, người qua lại dày đặc, ắt là có việc lớn. Họ họp tới lúc nào?"},{"who":"M","text":"Tới tận canh tư, đèn trong cung ấy vẫn sáng. Khi ra về ai cũng cúi đầu, như sợ người khác nhận ra."},{"who":"me","text":"Cả một phe họp kín thì không phải chuyện nhỏ. Ta tìm người làm chứng cho mình, và chia rẽ phe ấy bằng quà."}]}},
{"id":"j70:joint:chu","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều buồn, cung nữ ngồi bên người hầu quen biết, nghe chuyện của các cung khác mà lòng thấy một nỗi bất an."},{"who":"M","text":"{Goi}, nô tỳ nghe người trong một phe lần lượt hỏi chuyện kẻ hầu của {goi}. Hỏi từng người một, rất kiên nhẫn."},{"who":"me","text":"Hỏi từng kẻ hầu của ta, như đang gom lời khai. Còn gì nữa?"},{"who":"M","text":"Có một ma ma trong phe ấy ghi chép giờ giấc của {goi}. Nét chữ nắn nót, từng dòng rõ ràng."},{"who":"me","text":"Cả một phe cùng gom tội của ta, từng người từng việc. Ta giữ mình, không để sơ hở, và gặp riêng kẻ yếu nhất trong phe."}]}},
{"id":"j70:huydung:phan","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trước bàn trang điểm, hộp phấn mới còn bọc giấy gấm, cung nữ đứng nhìn mà nhớ lại điều nghe được ngoài chợ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người hỏi mua thủy ngân và lưu huỳnh ở chợ ngoài cung. Mua nhiều, trả tiền ngay."},{"who":"me","text":"Thủy ngân và lưu huỳnh, thứ ấy không dùng để thoa mặt. Ngươi còn thấy gì nữa?"},{"who":"M","text":"Có người sai đổi hộp phấn mới, nói là quà Nội vụ phủ. Hộp rất đẹp, nhưng nô tỳ chưa thấy dấu ấn của Nội vụ phủ."},{"who":"me","text":"Một hộp phấn mang danh Nội vụ phủ mà không có dấu ấn thì không thể tin. Ta thử son phấn trên tay kẻ hầu trước, và chặn hộp ở cửa cung đem đi nghiệm."}]}},
{"id":"j70:huydung:canh","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong yến tiệc, đèn lồng sáng rực, cung nữ đứng cạnh cửa nhà bếp, nhìn từng khay canh nóng bưng đi qua."},{"who":"M","text":"{Goi}, nô tỳ thấy có người dò xem ai dâng canh cho {goi} trong yến tiệc. Dò rất kỹ, nhìn từng khay một."},{"who":"me","text":"Dò xem ai dâng canh cho ta, rồi sao? Còn gì khác không?"},{"who":"M","text":"Cung nữ bên ấy tập bưng khay nóng nhiều lần. Nô tỳ nhìn mà thấy lạ, vì tập quá nhiều cho một việc nhỏ."},{"who":"me","text":"Tập bưng khay nóng nhiều lần để lỡ tay đúng lúc, mưu ấy thật hiểm độc. Ta không để ai lạ đứng gần lúc dâng canh, và gọi cung nữ bưng khay ra hỏi."}]}},
{"id":"j70:huydung:meo","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong góc vườn, mấy con mèo hoang nằm dài dưới nắng, cung nữ đứng nhìn mà lòng thấy một nỗi bất an mơ hồ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người nuôi mấy con mèo hoang trong góc vườn. Cho ăn rất đều, mèo quen hơi người."},{"who":"me","text":"Nuôi mèo hoang trong vườn, nghe như việc thiện. Nhưng ngươi còn thấy gì khác?"},{"who":"M","text":"Có người bôi mật ong lên áo cũ rồi bỏ ở lối đi. Ong bay đến đen kịt, mèo cũng lẩn quẩn quanh đó."},{"who":"me","text":"Mèo dữ, ong độc, một lối đi bị biến thành bẫy. Ta không ra vườn khi có mèo lạ, cho người đuổi ong, và sai thái giám bắt mèo, phá tổ ong."}]}},
{"id":"j70:huydung:son","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài chợ, một tiệm son phấn nhỏ treo biển bạc màu, cung nữ đứng nhìn qua cửa kính một hộp son lạ."},{"who":"M","text":"{Goi}, nô tỳ thấy có người mua loại son rẻ bị mốc ở chợ. Mua nhiều hộp một lúc, nói là để dùng riêng."},{"who":"me","text":"Mua son rẻ bị mốc nhiều như thế, người ấy không dùng riêng được. Rồi họ làm gì?"},{"who":"M","text":"Họ gói hộp son thật đẹp, đề tên một người khác để đem tặng. Nô tỳ nhìn hộp rất đẹp mà bên trong thì chẳng ai biết."},{"who":"me","text":"Một hộp son đẹp, đề tên người khác, mà bên trong đã mốc. Ta không dùng son phấn người khác tặng, và nghiệm hộp son trước khi dùng."}]}},
{"id":"j72:j72c-craft-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng muộn, mặt hồ sen sau Ngự hoa viên lặng như gương, chỉ có bèo trôi dạt về phía bờ đá."},{"who":"A","text":"{Goi} thứ lỗi, {xung} đường đột tìm đến. Sáng nay hóng gió bên hồ, {xung} sơ ý để cây trâm ngọc mẫu thân để lại rơi xuống nước."},{"who":"me","text":"Trâm ấy hẳn là vật quý, nên {goi} mới hớt hải thế này. Rơi ở chỗ nào, {goi} còn nhớ không?"},{"who":"A","text":"Chỗ nước cạn bên bờ đá. Giữa chốn thâm cung, {xung} chỉ còn chút hơi ấm của nhà gửi trong cây trâm ấy, lại sợ người ta cười kẻ vụng về."},{"who":"me","text":"Nước cạn thì trâm chưa trôi xa được. {Goi} đừng lo, để {xung} tính cách vớt cho."}]}},
{"id":"j72:j72c-craft-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thêu, chiếc quạt lụa ngự ban mở ra, nơi mép quạt có một vệt mối ăn nhỏ xíu."},{"who":"A","text":"{Goi} xem này, quạt Hoàng thượng ban cho {xung}, vậy mà mối cắn thủng mất một góc. Nhìn mà tim {xung} thắt lại."},{"who":"me","text":"Vật ngự ban hư tổn không phải chuyện nhỏ. Sao {goi} không báo lên cho người trên biết?"},{"who":"A","text":"Báo lên thì thành tội bất kính, {xung} biết ăn nói sao. Nghe nói {goi} khéo tay, xin vá giúp, nhất định đừng để ai hay."},{"who":"me","text":"Đã vậy thì {xung} xem vệt mối ăn trước, rồi chọn chỉ cho thật hợp màu, vá xong nhìn không ra dấu."}]}},
{"id":"j72:j72c-craft-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuộn họa trải dở trên án, nghiên mực bên cạnh đã khô thành một vệt xám."},{"who":"A","text":"Bức họa dâng Thái hậu sắp đến hạn, mà thỏi mực cuối của {xung} đã mài hết. Thứ mực thơm ấy, {xung} tìm khắp nơi không có."},{"who":"me","text":"Họa sư dùng mực nào thì nét bút mới vừa ý?"},{"who":"A","text":"Phải là mực tùng khói thơm, nét mới ngả màu cổ kính. Loại ấy chỉ nằm trong ngăn mực quý ở kho thư phòng Nội vụ phủ, {xung} thân phận thấp, không vào được."},{"who":"me","text":"Nội vụ phủ {xung} còn có đường nói chuyện. {Goi} cứ yên tâm vẽ, mực để {xung} lo."}]}},
{"id":"j72:j72c-craft-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng nhạc, bên giá đàn tranh, cây sáo ngọc nằm trên khăn gấm với một vết nứt dài chạy dọc thân."},{"who":"A","text":"Cây sáo ngọc này theo {xung} hai mươi năm, đêm qua tự nứt dọc thân, nghe tiếng \"rắc\" mà lòng {xung} như đứt ra."},{"who":"me","text":"Hai mươi năm gắn bó thì chẳng khác một người bạn cũ. {Goi} muốn {xung} giúp thế nào?"},{"who":"A","text":"Nghe nói trong cung có ông thợ ngọc khéo ở Nội vụ phủ. {Xung} chỉ mong còn nghe lại được một điệu cổ từ cây sáo ấy."},{"who":"me","text":"Để {xung} tìm ông thợ ấy. Keo sơn và dây tơ cần có thời gian se lại, nhưng sáo ngọc rồi sẽ cất tiếng được."}]}},
{"id":"j72:j72c-craft-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi nước nóng còn vương trong gian bếp, cánh tay đỏ rộp của người cung nữ giấu vội sau tay áo."},{"who":"A","text":"{Goi}, hôm qua {xung} bưng nước nóng bị bỏng cả cánh tay. Thuốc cao ở phòng {xung} lại hết sạch."},{"who":"me","text":"Đưa tay ta xem. Bỏng thế này mà chịu đựng suốt một đêm sao?"},{"who":"A","text":"{Xung} không dám xin công khai, sợ bị trách vụng về. {Goi} có thể xin giúp ít cao mỡ trộn nghệ ở Thái y viện không?"},{"who":"me","text":"Ngăn thuốc dự trữ ở Thái y viện vẫn còn loại cao ấy. Ngươi ngồi yên, ta đi xin rồi tự tay bôi cho."}]}},
{"id":"j72:j72c-craft-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thêu, khung gỗ căng sẵn tấm lụa trắng, chỉ còn chờ bàn tay đặt kim xuống."},{"who":"A","text":"Mẫu thân, con hứa tặng bạn một chiếc khăn thêu hoa lê mà bận chơi nên quên khuấy. Mai đã đến hạn rồi."},{"who":"me","text":"Hứa với người thì phải giữ lời. Con quên suốt mấy hôm rồi sao?"},{"who":"A","text":"Con không dám nói dối. Nhưng khung thêu ở cung mẫu thân căng sẵn lụa trắng, con biết mà. Mẫu thân thêu hộ con nhé?"},{"who":"me","text":"Lần này mẫu thân giúp con. Nhưng từ nay đã hứa thì chớ để quên nữa, nghe chưa?"}]}},
{"id":"j72:j72c-craft-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân trồng lan trước cung {B}, chậu lan vân lá đã đốm vàng, bên dưới thấp thoáng những vết sâu đục."},{"who":"A","text":"{Goi}, chậu lan quý của chủ {xung} bị sâu đục lá. Chủ {xung} sĩ diện, không chịu nhờ ai, {xung} đành lén tìm {goi}."},{"who":"me","text":"{B} biết chuyện này chưa? Lá đốm vàng thế kia, để lâu e héo cả cây."},{"who":"A","text":"Chủ {xung} biết, nhưng thà để lan héo còn hơn mở miệng nhờ người. {Xung} xin {goi} giữ kín, đừng để chủ {xung} mất mặt."},{"who":"me","text":"Ta hiểu rồi. Ta sẽ chữa lặng lẽ, để {B} tưởng lan tự khỏe lại."}]}},
{"id":"j72:j72c-craft-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió đông luồn qua khe cửa lãnh cung, bên rương cũ trong gian phụ, tấm áo lông cáo sờn tận vai."},{"who":"A","text":"Đông này lạnh lắm. Áo choàng lông cáo của {xung} sờn đến tận vai, mà trong lãnh cung chẳng ai đoái hoài."},{"who":"me","text":"Áo ấy là vật cũ từ ngày {goi} còn ở bên ngoài, đúng không?"},{"who":"A","text":"Phải, ngày trước nào nghĩ có lúc co ro bên rương cũ thế này. {Goi} còn qua lại được, giúp {xung} tìm người vá, {xung} không dám đòi hỏi gì hơn."},{"who":"me","text":"{Xung} mang áo đi. Lông cáo cùng màu hẳn còn ở Tân Giả khố, vá xong {xung} đem trả, {goi} cứ giữ ấm đã."}]}},
{"id":"j72:j72c-craft-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa đêm vừa tạnh, mấy cung nhân gác cửa đứng ho khan, vạt áo còn ướt sẫm."},{"who":"A","text":"{Goi}, đêm qua mấy chị em gác cửa dầm mưa, ho khan cả buổi. {Xung} muốn nấu chút canh gừng cho các chị em."},{"who":"me","text":"Dầm mưa cả đêm mà không ai nghỉ được, thương thật. {Goi} cần gì cứ nói."},{"who":"A","text":"Xin cho {xung} mượn bếp nhỏ sau cung. Gừng già, táo đỏ {xung} sẽ tự lo, chỉ sợ làm phiền {goi}."},{"who":"me","text":"Bếp nhỏ cứ dùng, củi khô xếp sẵn ở góc. Canh nóng uống lúc này là hợp nhất."}]}},
{"id":"j72:j72c-craft-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mai đầu cành vừa hé, trong bếp nhỏ bột nếp trắng và đường phèn bày sẵn bên khuôn hoa."},{"who":"A","text":"Mai nở rồi, yến thưởng mai sắp tới mà cung {xung} chưa có món nào ra hồn. {Goi} khéo tay, giúp {xung} làm bánh hoa mai nhé?"},{"who":"me","text":"Bánh hoa mai cần cánh mai thơm mới nên vị. Ở Ngự hoa viên hẳn còn nhiều cành mới nở."},{"who":"A","text":"Phải, {xung} muốn món bánh thơm mùi mai, nhìn thấy đã thấy xuân. Yến tiệc ấy, {xung} không muốn thua cung nào về sự tinh tế."},{"who":"me","text":"Vậy {xung} hái cánh mai, nhào bột ép khuôn, bày cho thật đẹp. Hương thơm ấy sẽ làm cả yến tiệc nhớ tới cung của {goi}."}]}},
{"id":"j72:j72c-craft-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án ở phòng nhạc, tờ nhạc cổ ố vàng, những dòng chữ nhòe đi vì nước mưa dột."},{"who":"A","text":"Bản nhạc cổ {xung} chép năm ngoái bị mưa dột làm nhòe gần hết. Giấy mốc ở mép, chữ chỉ còn sót lại vài nét."},{"who":"me","text":"Khúc ấy {goi} có nhớ được bao nhiêu? Chữ nào còn rõ, cứ chỉ cho {xung}."},{"who":"A","text":"{Xung} nhớ được điệu, nhưng quên mất nhịp cuối. Nghe nói {goi} thuộc nhiều khúc cổ, xin chép giúp một đoạn."},{"who":"me","text":"{Xung} ngồi cạnh {goi}, cùng đối chiếu những nét còn rõ. Khúc nhạc ấy sẽ không mất đi."}]}},
{"id":"j72:j72c-craft-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng mõ vừa dứt, trên sàn Phật đường ở Đức Thọ cung, hạt trầm lăn lóc dưới giá kinh."},{"who":"A","text":"{Goi} đến đúng lúc. Chuỗi tràng hạt ai gia đeo mấy chục năm, đứt dây giữa giờ tụng kinh, hạt lăn khắp Phật đường."},{"who":"me","text":"Hạt gỗ trầm không lăn xa được, {goi} đừng lo. {Xung} xin nhặt giúp từng hạt một."},{"who":"A","text":"Có hạt lăn dưới giá kinh, ai gia già rồi, cúi người không nổi. Mất một hạt, ai gia thấy như thiếu một lời kinh."},{"who":"me","text":"{Xung} nhặt đủ rồi sẽ tìm dây tơ vàng thật chắc ở Tân Giả khố, xâu lại cho {goi}."}]}},
{"id":"j72:j72c-craft-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở Tân Giả khố, chậu thuốc nhuộm chàm ngả màu xanh sẫm, tấm lụa hồ vừa nhuộm lệch đang phơi trên sào."},{"who":"A","text":"{Xung} cần một tấm lụa thiên thanh đúng màu may áo mừng đại lễ. Thợ nhuộm làm hai lần mà cả hai đều lệch sắc."},{"who":"me","text":"Màu thiên thanh khó ở chỗ chỉ lệch một chút đã thành xanh bạc hoặc xanh đục. Họ nhuộm ở đâu?"},{"who":"A","text":"Ở Tân Giả khố, bên chậu chàm. {Xung} không cần nghe lý do, chỉ cần đúng màu. {Goi} có cách nào chăng?"},{"who":"me","text":"Để {xung} học cách pha chàm và phèn trước, thử một mảnh lụa nhỏ rồi mới chốt màu cho tấm lớn."}]}},
{"id":"j72:j72c-craft-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, đèn cung còn sáng, Hoàng thượng ngồi thừ trên giường, mắt thâm quầng vì mất ngủ."},{"who":"A","text":"Trẫm mấy đêm trằn trọc, nhắm mắt mà chẳng ngủ được. Thuốc thái y dâng, uống vào chỉ thêm đắng miệng."},{"who":"me","text":"Long thể là quan trọng nhất. Xin hỏi, {goi} muốn {xung} làm điều gì?"},{"who":"A","text":"Nghe nói {goi} biết làm gối thơm. Làm cho trẫm một chiếc, đừng để ai nói là thuốc, trẫm chỉ muốn ngủ yên một giấc."},{"who":"me","text":"Thái y viện có cúc khô, hoa nhài. {Xung} sẽ may cho {goi} chiếc gối thơm êm, nằm xuống là dễ chìm vào giấc."}]}},
{"id":"j72:j72c-craft-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thêu, khung gỗ trắc đặt dựa tường, một bên chân vênh lên sau mùa mưa dầm."},{"who":"A","text":"Khung thêu của {xung} bị cong sau mùa mưa, kim luồn không thẳng được. Đổi khung mới thì tiếc, vì nó theo {xung} từ ngày nhập cung."},{"who":"me","text":"Gỗ trắc quý, bỏ đi thật uổng. Chân khung vênh bên nào, {goi} chỉ cho {xung} xem."},{"who":"A","text":"Bên trái, vênh khá nhiều. {Goi} có cách nào nắn lại không, hay phải chịu mua khung khác?"},{"who":"me","text":"Dùng hơi nước hơ mép gỗ rồi cố định cho thẳng, nắn từ từ thì gỗ không gãy. {Xung} thử cho {goi} xem."}]}},
{"id":"j72:j72c-craft-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở vườn sau cung, tre vót sẵn xếp bên mấy xấp giấy dó, gió thổi bay cả góc giấy."},{"who":"A","text":"Con trai {xung} đòi con diều hình phượng như của nhà người ta, mà thợ làm mãi chưa xong. {Xung} nhìn nó ngóng mà xót."},{"who":"me","text":"Trẻ con thích thả diều thì đâu cần phải đợi thợ. Tre và giấy dó đã sẵn cả rồi mà."},{"who":"A","text":"Phải, nhưng {xung} vụng, vẽ cánh phượng thế nào cũng xấu. {Goi} giúp {xung} làm một con thật đẹp được không?"},{"who":"me","text":"Được, {xung} vót khung dán giấy, rồi vẽ lông phượng lên cánh. Làm xong, đưa nó ra thả thử cho cháu mừng."}]}},
{"id":"j72:j72c-craft-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho nhỏ của nội viện, bên kệ gốm, chiếc bình sứ men xanh nằm nghiêng, miệng sứt mất một mảnh."},{"who":"A","text":"Thần xin thứ lỗi vì đường đột. Bình sứ men xanh nhà thần dâng vào cung, lúc dọn dẹp bị sứt miệng."},{"who":"me","text":"Sứt miệng là chuyện nhỏ, sao đại nhân lại lo đến vậy?"},{"who":"A","text":"Vật dâng vào cung mà hư hại thì sợ bị quy tội bất kính. Mong {goi} chỉ cho một cách kín đáo, đừng để chuyện đến tai người trên."},{"who":"me","text":"Nội vụ phủ có thợ sứ khéo tay. Để {xung} nhờ ông ấy phối men xanh cho đúng sắc rồi trét kín miệng bình."}]}},
{"id":"j72:j72c-craft-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùa mưa, hiên sau cung nồng mùi ẩm mốc, chăn gối treo trên xà không khô nổi."},{"who":"A","text":"{Goi}, mùa mưa chăn gối trong phòng ẩm mốc cả rồi. {Xung} muốn làm túi ngải cứu để xua ẩm, nhưng không biết phơi thế nào."},{"who":"me","text":"Ngải cứu phải hái đúng lúc, phơi cho khô mà không mất mùi. Ngươi hái chưa?"},{"who":"A","text":"Chưa ạ, {xung} sợ hái sai, phơi hỏng thì tiếc. Có {goi} chỉ cho, {xung} mới dám làm."},{"who":"me","text":"Để ta chỉ ngươi hái và phơi lên giàn tre trước đã. Túi ngải ấy treo đầu giường sẽ dịu hẳn cái ẩm."}]}},
{"id":"j72:j72c-craft-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lồng son treo trên cành phong sau Ngự hoa viên mở toang, nắng sớm rọi vào chiếc lồng trống."},{"who":"A","text":"Chú sơn ca {xung} nuôi ba năm sổ lồng bay mất sáng nay. Nó thuộc giọng {xung} lắm, mà giờ chẳng biết bay đi đâu."},{"who":"me","text":"Sơn ca nhớ chủ, chắc chưa bay xa. {Goi} có nghe thấy tiếng nó quanh đây không?"},{"who":"A","text":"Hình như tiếng hót vọng từ phía Ngự hoa viên. Ba năm nay mỗi sáng đều có nó hát, giờ thiếu tiếng nó, cung {xung} trống trải hẳn."},{"who":"me","text":"{Xung} rắc hạt sẵn để dụ nó đậu xuống. Đi theo tiếng chim rồi, {xung} sẽ đưa nó về cho {goi}."}]}},
{"id":"j72:j72c-craft-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối giường, mấy chiếc rương mây mở tung, hộp châm cài và khăn lụa chất lộn vào nhau."},{"who":"A","text":"Hộp phấn thơm {xung} cất trong rương nào cũng không thấy. Hôm qua cung nữ dọn rương, xếp lộn tùm lum."},{"who":"me","text":"Mỗi rương một thứ lộn xộn thế này, tìm cho ra cũng mất công. Lần cuối {goi} thấy hộp phấn là lúc nào?"},{"who":"A","text":"Hình như nằm dưới hộp châm cài, trong rương mây cuối giường. {Goi} giúp {xung} nhớ lại, rồi cùng cung nữ lục từng rương với."},{"who":"me","text":"{Xung} ghi lại những rương đã mở để khỏi lục lặp. Hộp phấn thơm chắc đang nằm đâu đó dưới đống châm cài."}]}},
{"id":"j72:j72c-craft-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa dầm không dứt, góc phòng giã thuốc ở Thái y viện bốc mùi bạc hà, cối đá còn ẩm."},{"who":"A","text":"Thần xin thất lễ, mưa dầm nhiều ngày, cung nhân ho nhiều mà thuốc ho thần giã chưa kịp."},{"who":"me","text":"Tiếng ho vọng khắp nơi mà ta đi ngang cũng nghe thấy. Thái y cần giã những vị nào?"},{"who":"A","text":"Bạc hà, cam thảo và vỏ quýt, giã cho thật mịn rồi chia từng gói. Nếu {goi} rảnh tay, xin giúp thần một ít."},{"who":"me","text":"Ta không nề việc nhỏ. Giã xong ta chia gói đều tay để người nào ho nặng thì được phần nhiều hơn."}]}},
{"id":"j72:j72c-craft-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thư nhà gửi vào cung đêm qua mở vội, nét chữ của cha run run ở dòng cuối."},{"who":"A","text":"Con gái, cha mẹ vẫn khỏe, chỉ là bà ngoại con đau chân đã lâu, đêm đêm trở mình không yên."},{"who":"me","text":"Bà đau thế nào, sao thư nhà không nói sớm?"},{"who":"A","text":"Bà không cho báo, sợ con lo. Nghe nói trong cung có vị thuốc quý trị đau chân, con có cách xin được chăng?"},{"who":"me","text":"Ngăn thuốc dự trữ ở Thái y viện có hộp gỗ niêm kín. Con sẽ khéo xin, rồi nhờ người tin cậy mang ra ngoài cho bà."}]}},
{"id":"j72:j72c-craft-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng đàn, cây đàn tranh đặt giữa bàn, dây thứ bảy đứt buông thõng, cuộn lại như sợi tóc."},{"who":"A","text":"Dây đàn tranh của {xung} đứt đúng lúc cần dùng, mà tơ mới thì chưa có. {Goi} biết cách nối thì làm giúp, đừng để {xung} mất mặt."},{"who":"me","text":"Đàn đứt dây giữa buổi là chuyện khó xử. Dây thứ mấy đứt, {goi} cho {xung} xem."},{"who":"A","text":"Dây thứ bảy, âm trầm nhất. Không có nó, cả khúc đàn thành rời rạc."},{"who":"me","text":"Tân Giả khố có tơ tằm cùng cỡ. {Xung} se tơ, kéo căng dây mới rồi chỉnh âm cho {goi} nghe thử."}]}},
{"id":"j72:j72c-craft-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thêu cung Hoàng hậu, lụa đỏ cắt sẵn xếp thành chồng, chữ phúc phác bằng phấn còn dở."},{"who":"A","text":"Khăn tay lễ tặng mệnh phụ cần thêu chữ phúc cho tròn, mà thợ thêu bận việc khác. {Goi} nhận thêu hộ {xung} mấy chiếc."},{"who":"me","text":"Chữ phúc thêu sao cho tròn đầy là phép khó, không thể làm cẩu thả. Bao nhiêu chiếc, hạn là khi nào?"},{"who":"A","text":"Hạn gấp, nhưng {xung} tin tay {goi}. Mệnh phụ nhận khăn sẽ nhớ tấm lòng của {xung}, đừng để họ thấy nét thêu méo."},{"who":"me","text":"{Xung} thêu từng nét cho tròn, xong sẽ đem giao tận tay, để {goi} khỏi phải lo."}]}},
{"id":"j72:j72c-craft-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Phật đường ở Đức Thọ cung, tờ giấy ẩm mốc ở góc, nét mực loang như khói lẫn vào kinh."},{"who":"A","text":"Sổ công đức ai gia ghi ở chùa bị nhòe vì dột mưa. {Goi} chép lại giúp ai gia, ai gia chỉ tin tay {goi}."},{"who":"me","text":"Công đức ghi một lần không thể sai, {xung} xin cẩn thận. Tờ nào nhòe nặng nhất ạ?"},{"who":"A","text":"Tờ ở góc, mấy dòng cuối gần như mất hết. Ai gia nhớ được, nhưng mắt đã mờ, không tự chép nổi."},{"who":"me","text":"{Xung} hong khô từng tờ, đợi mực khô mới đọc lại nét còn rõ, rồi chép lại đúng như ai gia nhớ."}]}},
{"id":"j72:j72c-craft-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần bếp, trong phòng tạp vụ, khúc gỗ lê đã bào nhẵn nằm cạnh mấy lưỡi đục mòn."},{"who":"A","text":"{Goi}, nô tài có đứa cháu sắp lấy vợ, muốn tặng bức tượng gỗ khắc chim yến. Nô tài khắc xấu quá, xin {goi} chỉ cách."},{"who":"me","text":"Chim yến là đôi lứa gắn bó, tặng cháu trai thì ý nghĩa lắm. Ngươi mới khắc được đến đâu?"},{"who":"A","text":"Mới bào khúc gỗ lê, chưa phác được hình. {Xung} sợ khắc hỏng, mất cả lòng cháu ngày vui."},{"who":"me","text":"Ta chỉ ngươi phác hình trên gỗ trước, dùng đục theo nét. Tượng xấu hay đẹp cũng là cái tình của ngươi gửi vào."}]}},
{"id":"j72:j72c-craft-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau buổi trà chiều, bên trong ngăn nhỏ ở rương mây cung {B}, thấp thoáng ánh bạc."},{"who":"A","text":"Vòng tay bạc mẫu thân {xung} để lại biến mất sau buổi trà chiều. {Xung} nghi {B} giấu, nhưng không có bằng chứng."},{"who":"me","text":"Nghi ngờ mà không có bằng chứng thì không nên nói ra. Vòng ấy đối với {goi} là thứ gì?"},{"who":"A","text":"Là vật cuối cùng mẫu thân để lại. {Goi} giúp {xung} tìm, đừng để {xung} thành kẻ vu oan."},{"who":"me","text":"{Xung} sẽ dò hỏi cung nữ của {B} về buổi trà chiều, lại tìm cớ tới nhìn rương mây. Cẩn thận từng bước để đừng làm tổn tình cảm hai cung."}]}},
{"id":"j72:j72c-craft-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau Thái y viện, trong vườn nhỏ sương còn đọng, luống hoàng kỳ xanh um dưới nắng mai."},{"who":"A","text":"Thần cần mấy vị thảo dược mọc ở vườn nhỏ sau Thái y viện, mà tay thần đau không hái nổi."},{"who":"me","text":"Thái y đau tay mà vẫn lo cho bệnh nhân, thật đáng nể. Thần cần những vị nào?"},{"who":"A","text":"Hoàng kỳ và ngải diệp, hoàng kỳ ở luống góc vườn. Xin {goi} giúp thần một chuyến."},{"who":"me","text":"{Xung} đi hái ngay, rồi mang về phơi đúng cách để thuốc không mất vị."}]}},
{"id":"j72:j72c-craft-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bếp nhỏ sau cung phảng phất mùi đậu xanh, bột nếp trắng đọng trên mặt thớt."},{"who":"A","text":"{Goi}, đứa em trong cung nữ sắp tròn tuổi mà chẳng ai nhớ. {Xung} muốn làm cho nó một chiếc bánh nhỏ, nhưng không có bột."},{"who":"me","text":"Ngày sinh mà không ai nhớ thì tủi thân lắm. Đứa nhỏ ấy là người thế nào mà ngươi thương đến vậy?"},{"who":"A","text":"Nó lặng lẽ làm việc, chẳng đòi hỏi gì. {Xung} chỉ muốn một chiếc bánh đào nhỏ, để nó biết có người nghĩ đến nó."},{"who":"me","text":"Ta cho ngươi xin bột nếp và đậu xanh ở bếp lớn, hấp bánh tạo hình đào nhỏ. Tặng nó thật nhẹ nhàng, đừng làm nó ngại."}]}},
{"id":"j72:j72c-craft-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách sứ quán, hòm gỗ đỏ mở sẵn, mấy gói lụa đặt bên danh sách dài chưa gạch xong."},{"who":"A","text":"Mai {xung} phải lên đường về nước, lễ vật tặng quan cung còn chưa gói. {Goi} rộng lòng, giúp {xung} chọn và gói cho hợp lễ."},{"who":"me","text":"Mỗi vị quan cung một sở thích riêng. Danh sách người nhận {goi} đã đưa chưa?"},{"who":"A","text":"Đây rồi, nhưng {xung} sợ gói nhầm, phạm lễ. Xứ này lễ nghi nhiều điều tế nhị."},{"who":"me","text":"{Xung} xem danh sách, chọn món hợp từng người, rồi gói lụa đề tên cẩn thận. {Goi} lên đường yên tâm."}]}},
{"id":"j72:j72c-craft-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong giỏ khâu ở cung {A}, vải trắng và chỉ mềm xếp ngay ngắn, chưa chiếc áo nhỏ nào hoàn thành."},{"who":"A","text":"{Goi}, {xung} sắp sinh mà áo tã chưa đủ. Mẫu thân xa, {xung} chỉ dám nhờ {goi}. Khâu giúp {xung} vài chiếc nhé?"},{"who":"me","text":"Sắp làm mẹ, {goi} nhất định hồi hộp lắm. {Xung} khâu giúp, nhưng {goi} cho {xung} biết cỡ nhỏ thế nào."},{"who":"A","text":"{Xung} cũng chưa hình dung nổi, chỉ biết phải thật mềm, đừng để cộm da con. Nhờ {goi} cả."},{"who":"me","text":"{Xung} cắt lụa mỏng theo cỡ nhỏ, khâu nối thật mềm, rồi thêu điểm hoa nhỏ cho áo thêm duyên."}]}},
{"id":"j72:j72c-craft-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên ngăn trên cùng của kho giấy Nội vụ phủ, xếp ngay ngắn những tập giấy dó thô vàng."},{"who":"A","text":"Bức họa {xung} định vẽ cần giấy dó mịn, mà kho nội phủ chỉ phát giấy thô. Xin {goi} chiếu cố, mua giùm vài tờ."},{"who":"me","text":"Giấy thô khó giữ được nét mực tinh. Họa sư cần bao nhiêu tờ?"},{"who":"A","text":"Chỉ vài tờ thôi, nhưng phải mịn, ngả trắng ngà. Tay thái giám coi kho có thể cho, nếu {goi} nói khéo."},{"who":"me","text":"Ta sẽ hỏi mua qua thái giám coi kho, trả công cho phải đạo, để ngươi vẽ trọn nét mà không thiệt."}]}},
{"id":"j72:j72c-craft-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thay đồ cung {B}, chiếc áo yến tiệc treo trên giá, nơi nách áo toạc một đường dài."},{"who":"A","text":"{Goi}, áo tiệc của chủ {xung} rách ở nách khi thử, mà chủ sắp phải dự yến. {Xung} sợ bị mắng, lén tìm {goi}."},{"who":"me","text":"Rách thế kia mà chủ ngươi chưa biết sao? Yến tiệc thì chẳng còn bao lâu nữa."},{"who":"A","text":"Dạ chưa, chủ {xung} vốn kiêu, thấy rách ắt giận lây tới người hầu. Xin {goi} may lại giúp, đừng nói cho ai."},{"who":"me","text":"Đưa áo đây, ta may ở bàn thêu của ta, chọn chỉ cùng màu cho đường may khuất. Chủ ngươi sẽ không thấy gì cả."}]}},
{"id":"j72:j72c-craft-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lò nung nhỏ gần Phật đường hãy còn ấm, đất sét ẩm nằm trên bàn, thơm mùi đất sau mưa."},{"who":"A","text":"Con gái thần mới nhập cung, nhà thần muốn có một tượng đất nhỏ tặng nó giữ bình an. Nghe nói {goi} khéo tay nên thần mạo muội nhờ."},{"who":"me","text":"Tượng cầu bình an thì phải nặn bằng cả tấm lòng. Con gái đại nhân nhập cung đã lâu chưa?"},{"who":"A","text":"Mới ít ngày. Nó còn bỡ ngỡ, thần ở xa không che chở được. Chỉ mong có một pho tượng nhỏ làm bạn bên gối nó."},{"who":"me","text":"Ta nặn một pho nhỏ, nung nhẹ trong lò nhỏ cạnh Phật đường, rồi sẽ trao cho cô bé giữ làm lòng yên."}]}},
{"id":"j72:j72c-craft-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua kẽ nứt gian phía đông lãnh cung, vách tường ẩm loang từng mảng xám."},{"who":"A","text":"Phòng {xung} ở lãnh cung dột nước mấy đêm rồi, không ai thèm sửa. {Goi} rộng lòng, nghĩ giúp {xung} cách trát lại bức tường."},{"who":"me","text":"Mấy đêm nằm nghe nước nhỏ giọt thì làm sao ngủ được. Chỗ tường nứt nhìn thấy nơi nào, {goi} chỉ cho {xung}."},{"who":"A","text":"Bức vách phía đông, vết nứt chạy dọc từ mái xuống. {Xung} đã quen với khổ, nhưng chẳng muốn thêm bệnh vì ẩm."},{"who":"me","text":"{Xung} xin vôi vữa ở chỗ coi kho Nội vụ phủ, mang vào đây tự tay trát lại. {Goi} chớ lo, tường sẽ khô ráo."}]}},
{"id":"j72:j72c-craft-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên giá chỉ ở phòng thêu, ba màu chỉ đã xe sẵn rủ xuống như ba dải khói."},{"who":"A","text":"{Goi}, dây lưng cũ đã sờn, {xung} muốn bện một sợi mới nhưng chưa từng bện dây lụa. Xin {goi} chỉ dạy."},{"who":"me","text":"Dây lưng tuy nhỏ mà nhìn là biết tay người. Ngươi chuẩn bị chỉ ba màu thế này là đúng cách rồi."},{"who":"A","text":"Dạ, {xung} chưa biết chọn màu nào cho hợp. Muốn sợi dây thật bền, và cũng muốn nó đẹp mắt."},{"who":"me","text":"Ta chỉ cách bện ba sợi thành một, rồi cùng chọn màu theo sắc áo. Bện xong nhìn là thấy công của ngươi."}]}},
{"id":"j72:j72c-craft-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư cung {A}, hai mảnh giấy rách đặt cạnh nhau, nét mực đứt giữa chừng như một câu chưa nói hết."},{"who":"A","text":"Thư riêng {xung} nhận được bị ai đó xé đôi. {Xung} không muốn ai biết, đành nhờ {goi}."},{"who":"me","text":"Xé thư người khác là việc không nên làm. {Goi} có biết ai xé không?"},{"who":"A","text":"Không rõ, nhưng nét chữ trong thư là của người thân. {Xung} muốn đọc cho trọn ý, nối lại cho nguyên vẹn."},{"who":"me","text":"{Xung} ghép hai nửa, đọc từng dòng, rồi dán lại bằng hồ nếp và chép thêm một bản mới. Chuyện này giữ kín trong hai ta."}]}},
{"id":"j72:j72c-craft-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong vườn tre nhỏ sau cung, mấy ống tre chặt sẵn nằm dưới ánh nắng, còn thơm mùi nhựa mới."},{"who":"A","text":"Mẫu thân, con muốn đi câu cá ở hồ sen mà chưa có hộp đựng mồi. Mẫu thân làm cho con cái hộp tre nhỏ được không?"},{"who":"me","text":"Con muốn bắt cá, sao không nhờ thái giám trông nom? Hồ sen sâu, con phải cẩn thận."},{"who":"A","text":"Con muốn có hộp mẫu thân tự tay làm, con mang theo sẽ thấy như có mẫu thân bên cạnh."},{"who":"me","text":"Lời ấy khiến mẫu thân mềm lòng. Ta khoét ống tre, đục lỗ thông hơi, làm nắp cho kín, con đi câu nhớ về sớm."}]}},
{"id":"j72:j72c-craft-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc hộp nữ trang của Hoàng hậu mở ra, chuỗi trân châu nằm trên gấm đỏ thiếu mất một hạt."},{"who":"A","text":"Chuỗi trân châu {xung} đeo dự đại lễ bị sút chỉ, thợ đưa lại bảo thiếu một hạt. {Xung} ngờ có kẻ trộm."},{"who":"me","text":"Hoàng hậu vội nghi ngờ thì dễ oan người. Hạt ngọc có thể lăn xuống khe sàn."},{"who":"A","text":"{Goi} nói cũng phải. Vậy hãy xem lại hộp nữ trang và khe sàn, rồi hỏi cung nhân dọn phòng cuối buổi. {Xung} cần một hạt trân châu, không cần một vụ oan."},{"who":"me","text":"{Xung} sẽ tìm cho kỹ, nếu hạt ngọc nằm đâu đó thì chẳng ai phải mang tiếng."}]}},
{"id":"j72:j72c-craft-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giỏ trà nhỏ ở cung {A} bày lá trà và hoa nhài tươi, mùi thơm ngan ngát cả gian phòng."},{"who":"A","text":"Thái hậu thích trà hoa nhài, mà cung {xung} nghèo, chẳng có gì quý để dâng. {Goi} giúp {xung} ướp một gói trà nhỏ thôi."},{"who":"me","text":"Quà không cần đắt, chỉ cần ý tứ. Hoa nhài tươi này hái từ sáng sớm đúng không?"},{"who":"A","text":"Đúng, {xung} hái lúc sương còn đọng. Chỉ mong gói trà ấy làm Thái hậu nhớ tấm lòng của {xung}."},{"who":"me","text":"Ướp lá trà với hoa nhài qua một đêm, hương sẽ thấm đều. {Xung} gói lại thật xinh để {goi} dâng lên."}]}},
{"id":"j72:j72c-craft-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thủ công cung {A}, giấy dó và hồ nếp bày bên khuôn mặt nạ còn dở, chỉ thiếu đôi mắt."},{"who":"A","text":"Tiệc hoa đăng sắp tới, {xung} muốn đeo mặt nạ cáo trắng mà thợ làm chưa kịp. {Goi} giúp {xung} dán một cái nhé, đừng nói ai."},{"who":"me","text":"Mặt nạ cáo trắng nghe đã thấy tinh nghịch. {Goi} định hóa trang để đi đâu giữa tiệc?"},{"who":"A","text":"Chỉ là muốn một đêm thoát khỏi vai {xung} ngày thường, thong dong giữa đèn hoa. Đừng cười {xung}."},{"who":"me","text":"{Xung} không cười đâu. {Xung} dán giấy dó thành khuôn, vẽ đôi mắt cáo cho thật tinh anh, rồi trang trí cho {goi}."}]}},
{"id":"j72:j72c-craft-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Góc bếp phụ trong Đức Thọ cung, lọ sành bịt vải đặt trên giá, hơi quế thoảng đâu đây."},{"who":"A","text":"Ai gia thích giấm hoa quế mà năm nay thợ ủ hỏng. {Goi} biết cách thì ủ cho ai gia một vò nhỏ."},{"who":"me","text":"Giấm hoa quế phải hái đúng lúc, mới giữ được hương. {Xung} nghĩ Ngự hoa viên còn quế đọng sương."},{"who":"A","text":"Đúng thế, ai gia thèm cái vị ấy từ mấy năm trước. Mất công đợi cũng không sao, ai gia chờ được."},{"who":"me","text":"{Xung} hái hoa lúc còn sương, ủ cho hoa lên men qua nhiều tuần. Vò giấm hoàn thành rồi sẽ dâng lên bà."}]}},
{"id":"j72:j72c-craft-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng tạp vụ ở Nội vụ phủ, hòm giấy tờ bị cạy hở nắp, khóa đồng gãy nằm trên sàn."},{"who":"A","text":"{Goi}, hòm giấy tờ nô tài giữ bị ai cạy khóa đêm qua. Nô tài sợ bị quở, xin {goi} chỉ chỗ thay khóa."},{"who":"me","text":"Cạy khóa là việc có người cố ý. Trong hòm có thứ gì quan trọng, ngươi kiểm lại chưa?"},{"who":"A","text":"Dạ, nô tài xem sơ thì chưa mất, nhưng chưa dám chắc. Xin {goi} chớ nói cho ai trước khi nô tài thay khóa."},{"who":"me","text":"Ta mượn khóa đồng cũ ở Nội vụ phủ lắp lại, rồi cùng ngươi khám lại từng tờ giấy xem còn đủ không."}]}},
{"id":"j72:j72c-craft-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn nhỏ trong phòng {A}, bình sứ men ngọc trống không, một chùm cúc trắng đặt bên cạnh."},{"who":"A","text":"Hôm nay là ngày giỗ người thân của {xung}, {xung} muốn có bình hoa cúc trắng trong phòng. {Goi} giúp {xung} cắm cho trang nhã."},{"who":"me","text":"Ngày giỗ thì hoa nên đơn sơ mà thanh khiết. {Goi} nhớ người thân nào nhất?"},{"who":"A","text":"Mẫu thân. Mỗi năm đến ngày này, {xung} chỉ có hoa cúc để nói thay lời. Nhờ {goi} giúp {xung} cắm cho vừa lòng."},{"who":"me","text":"{Xung} ra vườn hái cúc trắng và lá thủy trúc, tỉa cành, cắm theo thế nghiêng. Hoa sẽ thay {goi} nhớ về người."}]}},
{"id":"j72:j72c-craft-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nơi góc giá giày phòng kẻ hầu, đôi giày vải ướt sũng còn nhỏ nước, đế bong ra một nửa."},{"who":"A","text":"{Goi}, đế giày của {xung} bong keo, trời mưa ướt cả chân. {Xung} không có đôi nào khác, xin {goi} chỉ cách dán lại."},{"who":"me","text":"Mưa ướt chân mà cứ đi tiếp thì dễ bệnh. Đôi giày này ngươi mang bao lâu rồi?"},{"who":"A","text":"Hơn hai mùa mưa, nhưng chưa từng bong thế này. {Xung} không dám xin giày mới, sợ làm phiền người trên."},{"who":"me","text":"Ta chỉ ngươi trộn keo nếp, dán lại đế vải, rồi hong khô cho chắc. Đôi giày cũ này sẽ còn đi được lâu."}]}},
{"id":"j72:j72c-craft-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho đồ nhạc Nội vụ phủ, hòm da thuộc xếp cạnh chiếc trống thủng, mặt trống rách tả tơi."},{"who":"A","text":"Mặt trống phòng nhạc thủng sau mùa hội, mà da trâu Nội vụ phủ chưa phát. {Goi} có đường nào tìm da và thợ căng trống chăng?"},{"who":"me","text":"Mặt trống hỏng thì cả đội nhạc chơi đâu ra tiếng. Da thuộc có sẵn trong kho không?"},{"who":"A","text":"Có một hòm da thuộc, nhưng cần người xin phép. Còn thợ căng trống, phòng nhạc chưa quen ai."},{"who":"me","text":"Ta xin da trâu thuộc ở kho đồ nhạc, mời thợ trống căng da đóng đinh, rồi thử tiếng cho đúng nhịp."}]}},
{"id":"j72:j72c-craft-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng giặt nhỏ cung {B}, chiếc khăn gấm treo trên sào, vệt mực loang thành một đám đen ở góc."},{"who":"A","text":"{Goi}, {xung} làm đổ mực lên khăn gấm của chủ, sợ bị phạt. Có cách nào tẩy mực kín đáo chăng?"},{"who":"me","text":"Mực đã khô thì khó tẩy, nhưng nước vo gạo và vỏ bưởi vẫn có thể làm nhạt. Ngươi cho ta xem khăn."},{"who":"A","text":"Đây ạ. Chủ {xung} nổi tiếng thù dai, nếu biết, {xung} e chẳng yên thân."},{"who":"me","text":"Ta sẽ giặt kỹ bằng nước vo gạo và vỏ bưởi, rồi trả khăn lặng lẽ. Chủ ngươi sẽ không hay biết gì."}]}},
{"id":"j72:j72c-craft-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thuốc Thái y viện, vò rượu hà thủ ô bịt giấy đặt giữa bàn, màu hổ phách dậy mùi dịu."},{"who":"A","text":"Rượu thuốc ngâm hà thủ ô của thần đã chín nhưng chưa lọc, mà thần bận đủ việc. {Goi} có tay lọc rượu, xin giúp thần."},{"who":"me","text":"Rượu thuốc để lâu không lọc thì đục mất vị. Thái y cần lọc mấy lần?"},{"who":"A","text":"Qua vải mịn nhiều lần, rồi đong vào chai sứ và dán nhãn. Việc không khó, chỉ cần kiên nhẫn."},{"who":"me","text":"Ta lọc rượu qua vải mịn cho thật trong, rồi đong vào chai sứ, dán nhãn. Thái y cứ yên tâm lo việc khác."}]}},
{"id":"j72:j72c-craft-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giá len và khung dệt ở cung {A} chất đầy cuộn len nhạt màu, như màu sữa đầu đông."},{"who":"A","text":"{Goi}, mùa đông đến, con {xung} hay đạp chăn, thức dậy mũi lạnh buốt. {Goi} giúp {xung} dệt tấm chăn nhỏ ấm hơn nhé?"},{"who":"me","text":"Trẻ nhỏ ngủ ngoan mới lớn nhanh. Len nhạt thế này hợp lắm, {goi} muốn sắc nào?"},{"who":"A","text":"Sắc nhạt như sữa, để con trông dịu dàng. {Xung} nhìn con ngủ mà cứ lo cho nó lạnh."},{"who":"me","text":"{Xung} xe len, nhuộm sắc nhạt, dệt từng hàng rồi viền mép thật êm. Chăn xong sẽ mang qua cho {goi}."}]}},
{"id":"j72:j72c-craft-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn án của quan nội viện, con dấu gỗ nằm trên tờ giấy trắng, vết nứt chạy dọc cán như sợi tóc."},{"who":"A","text":"Con dấu gỗ của thần nứt dọc thân, nếu thay mới thì phải báo bộ. Xin {goi} chỉ cách dán lại cho kín."},{"who":"me","text":"Con dấu quan nội viện liên quan đến giấy tờ trọng đại. Nứt thế này đã ảnh hưởng nét đóng chưa?"},{"who":"A","text":"Chưa, nhưng thần sợ nứt thêm. Báo bộ thì mất nhiều ngày, lại mang tiếng cẩu thả."},{"who":"me","text":"Ta nhờ thợ mộc cung nhân dán và buộc dây cho chắc, giữ kín chuyện này để đại nhân yên tâm làm việc."}]}},
{"id":"j72:j72c-craft-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong bếp thuốc nhỏ cạnh phòng {A}, ấm đất đen đặt trên lò nguội, cạnh bát thuốc còn đầy."},{"who":"A","text":"{Goi}, {xung} nằm bệnh mấy hôm nay mà thuốc cung nữ sắc không đúng lửa. {Goi} giúp {xung} canh một đêm được không?"},{"who":"me","text":"Thuốc sắc sai lửa thì không công hiệu. {Goi} nằm nghỉ cho khỏe, {xung} sẽ lo."},{"who":"A","text":"{Xung} không muốn phiền {goi}. Nhưng đêm dài một mình, ngửi mùi thuốc mà lòng cứ buồn."},{"who":"me","text":"{Xung} mang ấm thuốc ra bếp nhỏ, nhóm lửa liu riu, canh qua đêm. {Goi} ngủ đi, sáng ra thuốc sẽ vừa uống."}]}},
{"id":"j72:j72c-craft-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn họa sư, chén bột son đặt cạnh nghiên mực, sắc đỏ đã ngả sang màu gạch cũ."},{"who":"A","text":"Bức tranh mừng thọ cần màu son đỏ tươi, mà bột son {xung} pha mãi ra màu gạch. {Goi} có mắt tinh, xin chỉ giúp."},{"who":"me","text":"Son đỏ muốn tươi phải pha đúng độ. {Goi} pha bằng gì?"},{"who":"A","text":"Bột son với keo da trâu và chút phèn, mà không hiểu sao vẫn xỉn. Bức tranh ấy là lễ mừng thọ nên {xung} không dám sai."},{"who":"me","text":"Để {xung} xem rồi chọn sắc. Có thể do keo hơi nhiều, {xung} thử pha lại cho đỏ tươi như ý."}]}},
{"id":"j72:j72c-craft-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thợ Nội vụ phủ, mẫu gỗ đã khắc nằm bên hộp trang sức khảm xà cừ lấp lánh."},{"who":"A","text":"Hộp trang sức của {B} đẹp quá, {xung} muốn có cái giống hệt mà không muốn ai biết. {Goi} giúp {xung} làm một cái nhé."},{"who":"me","text":"Muốn có cái giống hệt thì cũng là yêu cái đẹp. Sao {goi} không hỏi thẳng {B}?"},{"who":"A","text":"{Xung} ngại, sợ {B} nghĩ {xung} bắt chước. Chỉ mong lặng lẽ có một hộp, để thỉnh thoảng ngắm cho vui."},{"who":"me","text":"{Xung} xem kỹ nét khảm của hộp {B} để nhớ, rồi nhờ thợ Nội vụ phủ làm theo mẫu vẽ. Chuyện này giữ kín cho {goi}."}]}},
{"id":"j72:j72c-craft-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thủ công cung Hoàng hậu, giấy đỏ và vàng xếp thành chồng, kéo cắt đặt cạnh mẫu hoa sen."},{"who":"A","text":"Yến tiệc sắp tới, {xung} muốn mấy chậu hoa giấy cắt tay để trang hoàng bàn. {Goi} cắt giúp {xung} một ít."},{"who":"me","text":"Hoa giấy cắt tay có hồn hơn hoa mua sẵn. Hoàng hậu thích dáng hoa nào?"},{"who":"A","text":"Hoa sen, vì nó hợp với yến thanh nhã. {Xung} không cần nhiều, chỉ cần cánh nào cũng tinh xảo."},{"who":"me","text":"{Xung} gấp giấy nhiều lớp rồi cắt theo mẫu hoa sen. Xong sẽ bày thành chậu để bàn tiệc thêm sắc."}]}},
{"id":"j72:j72c-craft-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Góc phòng lãnh cung lạnh lẽo, khung dệt nhỏ phủ bụi bên cửa sổ, ánh chiều hắt qua song."},{"who":"A","text":"Con {xung} bị đưa đi xa, {xung} chẳng được gặp. {Xung} muốn dệt chiếc khăn quàng gửi nó mà trong này không có len. {Goi} giúp {xung} một lần."},{"who":"me","text":"Một chiếc khăn gửi đi cũng đủ thay lời mẹ. Len ngoài kia, {xung} sẽ lén mang vào cho {goi}."},{"who":"A","text":"{Xung} dệt chậm, nhưng từng hàng đều thương nó. Chỉ mong nó biết mẹ chưa quên."},{"who":"me","text":"{Xung} ngồi cạnh dệt cùng {goi} từng hàng. Khăn xong, {xung} sẽ tìm cách gửi đi cho tử tế."}]}},
{"id":"j72:j72c-craft-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên hiên sau Đức Thọ cung, mẹt tre trống đặt ngoài nắng, hương hồng thoang thoảng gió."},{"who":"A","text":"Hoa hồng trong vườn nở rộ, ai gia muốn phơi ít cánh ướp trà. {Goi} giúp ai gia hái và phơi."},{"who":"me","text":"Hồng nở rộ thì cánh còn thơm nhất. {Xung} nghĩ nên hái lúc sương còn đọng, cánh mới không dập."},{"who":"A","text":"{Goi} hiểu ý ai gia. Ai gia thích cánh hồng đỏ, phơi khô ướp trà mà uống vào buổi chiều."},{"who":"me","text":"{Xung} hái hoa hồng đỏ khi sương còn đọng, rồi phơi trên mẹt tre ở hiên sau cho khô đều."}]}},
{"id":"j72:j72c-craft-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn vẽ trong phòng ngươi, giấy dó trải sẵn, mực nhạt còn đọng trong nghiên."},{"who":"A","text":"{Goi}, bà nội quan trong cung sắp tròn tuổi, {xung} muốn vẽ bức tranh tặng bà mà vẽ chẳng giống. Xin {goi} dạy."},{"who":"me","text":"Bà nội quan là người ngươi quý mến lắm đúng không? Vẽ người chỉ cần giống thần thái, không cần quá tinh."},{"who":"A","text":"Bà từng chăm sóc {xung} lúc mới vào cung. {Xung} chỉ muốn tranh có đôi mắt hiền của bà."},{"who":"me","text":"Ta chỉ ngươi phác người bằng nét mực đơn giản, rồi tô màu lụa, đề thơ ở góc. Tranh mừng thọ không cần giống, chỉ cần có tình."}]}},
{"id":"j72:j72c-craft-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng khách sứ quán, bàn viết trải giấy trắng, bên cạnh bản quốc thư vấy mực như vệt mây đen."},{"who":"A","text":"Bản quốc thư của {xung} bị vấy mực, phải chép lại trước giờ yết kiến. {Xung} tin nét chữ của {goi}, xin giúp."},{"who":"me","text":"Quốc thư là việc hệ trọng, sai một nét cũng thành thất lễ. Bản cũ {goi} còn đọc được chứ?"},{"who":"A","text":"Còn, chỉ vệt mực che mất vài chữ, nhưng {xung} thuộc nội dung. Giờ yết kiến chẳng còn xa nữa."},{"who":"me","text":"{Xung} đọc kỹ từng chữ trong bản cũ, rồi chép lại bằng nét chân phương. Xong thì niêm cẩn thận cho {goi} mang đi."}]}},
{"id":"j72:j72c-craft-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong bồn cúc ở Ngự hoa viên, lá khô phủ dày che mất ánh bạc của chiếc nhẫn ngọc đánh rơi."},{"who":"A","text":"{Goi}, {xung} làm rơi nhẫn của chủ khi tỉa hoa trong vườn, sợ bị phạt. {Goi} giúp {xung} tìm lại đi."},{"who":"me","text":"Rơi ở bồn nào, ngươi còn nhớ không? Chủ ngươi biết chưa?"},{"who":"A","text":"Bồn hoa cúc, hình như rơi xuống dưới lá khô. Chủ {xung} chưa biết, nhưng nhẫn ngọc ấy chủ rất quý."},{"who":"me","text":"Ngươi đừng khóc. Ta nhẹ tay bới lá khô trong bồn cúc, tìm được rồi thì trả cho chủ ngươi thật khéo."}]}},
{"id":"j72:j72c-craft-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên giá sách phòng đọc cung {A}, cuốn sách cổ gáy sờn xơ, trang giấy ố vàng rời ra từng tờ."},{"who":"A","text":"Cuốn sách cổ của {xung} rời trang cả, {xung} sợ mất chữ. {Goi} khéo tay, giúp {xung} đóng lại gáy nhé."},{"who":"me","text":"Sách cổ là vật giữ được lâu nhất. Các trang còn thứ tự không?"},{"who":"A","text":"Còn mục lục cũ để đối chiếu, nhưng {xung} không dám động tay, sợ hỏng thêm."},{"who":"me","text":"{Xung} sắp lại trang theo mục lục, khâu gáy bằng chỉ gai và dán bìa. Sách cổ rồi sẽ nằm gọn trên giá như xưa."}]}},
{"id":"j72:j72c-craft-061","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong hộp thêu cung ngươi, cây kéo cắt chỉ tay cầm đồng sờn, lưỡi cùn không còn cắt được chỉ mảnh."},{"who":"A","text":"{Goi}, kéo cắt chỉ của {xung} cùn quá, cắt gì cũng xơ. {Xung} không biết mài, xin {goi} chỉ."},{"who":"me","text":"Kéo cùn thì cắt chỉ xơ, thêu đẹp mấy cũng hỏng. Ngươi dùng kéo này bao lâu rồi?"},{"who":"A","text":"Dạ, hơn hai năm, từ ngày mới vào. Nó là cây kéo duy nhất {xung} có."},{"who":"me","text":"Ta chỉ ngươi mài kéo trên đá mịn với chút dầu, rồi thử cắt một sợi chỉ cho biết lưỡi đã sắc chưa."}]}},
{"id":"j72:j72c-craft-062","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thay đồ cung {A}, ống tay áo lụa trắng vương một vệt hồng nhạt của sơn móng."},{"who":"A","text":"Móng tay {xung} sơn mới mà lem ra ống tay áo lụa trắng. {Goi} có cách nào giấu giúp {xung} trước khi vào yến không?"},{"who":"me","text":"Lụa trắng thì vết hồng lộ rõ lắm. Để {xung} xem, may ra tẩy được bằng bông thấm rượu."},{"who":"A","text":"{Xung} sợ người ta nhìn thấy mà cười. Yến tiệc ấy có mặt các cung, {xung} không muốn bị chê."},{"who":"me","text":"{Xung} dùng bông gòn thấm rượu tẩy nhẹ vệt sơn, nếu còn dấu thì tìm cách che khéo. {Goi} yên tâm bước vào yến."}]}},
{"id":"j72:j72c-craft-063","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn án quan nội viện, gỗ lê đã cắt thành tấm xếp ngay ngắn, bên cạnh mấy bức thư còn nằm lộn xộn."},{"who":"A","text":"Thư từ của thần thất lạc hoài, thần muốn có hộp gỗ nhỏ có khóa. {Goi} khéo tay, xin chỉ cách đóng."},{"who":"me","text":"Thư thất lạc thì giấy tờ quan trọng cũng dễ mất theo. Đại nhân cần hộp cỡ nào?"},{"who":"A","text":"Vừa khổ giấy là được, có khóa đồng nhỏ. Không cần đẹp, chỉ cần chắc."},{"who":"me","text":"Ta cắt gỗ lê vừa khổ giấy, ráp mộng, lắp khóa đồng rồi trang trí nhẹ. Từ nay thư của đại nhân sẽ có chỗ yên."}]}},
{"id":"j72:j72c-social-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi chiều trong cung lặng gió, lời chê hôm qua vẫn còn lơ lửng đâu đây như mùi trà nguội."},{"who":"A","text":"{Goi}, hôm qua {xung} lỡ miệng chê lụa của {B} ngay trước mặt mọi người. Giờ {B} giận ra mặt, {xung} nhìn mà đứng ngồi không yên."},{"who":"me","text":"Nói ra rồi thì khó thu lại. {Goi} thật lòng chê, hay chỉ buột miệng?"},{"who":"A","text":"Chỉ là buột miệng. {Xung} vốn thẳng tính, nhưng không muốn vì một câu mà mất một người bạn trong cung."},{"who":"me","text":"Hiếm ai chịu nhận mình lỡ lời như {goi}. Để {xung} tìm lúc {B} thong thả mà nói đỡ một câu."}]}},
{"id":"j72:j72c-social-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa phòng ma ma coi cung nhân, người cung nữ đứng tần ngần, tay vặn vạt áo đến nhàu."},{"who":"A","text":"{Goi}, mẹ {xung} ốm nặng, {xung} muốn xin ma ma cho nghỉ ba hôm. {Xung} sợ ma ma không cho, xin {goi} nói giúp."},{"who":"me","text":"Mẹ bệnh nặng thì chữ hiếu đáng trọng hơn việc cung. Ngươi nhận thư báo từ lúc nào?"},{"who":"A","text":"Mới hôm qua, thư nói mẹ chẳng còn ngồi dậy nổi. {Xung} muốn về nhìn mẹ một lần, dẫu chỉ ba hôm."},{"who":"me","text":"Ta hiểu. Ta sẽ tìm ma ma lúc bà rảnh, thưa chuyện cho khéo để bà thương tình mà cho ngươi về."}]}},
{"id":"j72:j72c-social-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư của {A}, mấy tấm thiệp đỏ đã viết sẵn tên từng cung, mực còn thơm."},{"who":"A","text":"{Goi}, cô muội mới vào cung còn lạ nước lạ cái. {Goi} dẫn nàng đi chào các cung giúp {xung}, {xung} đau chân không đi được."},{"who":"me","text":"Mới vào cung mà đã phải đi hết các cung, nàng chắc hồi hộp lắm. Lễ nghi từng cung có khác nhau không?"},{"who":"A","text":"Khác nhiều, người trọng lễ, người ưa thân tình. {Xung} đã viết thiệp sẵn, chỉ thiếu người dẫn đường tử tế."},{"who":"me","text":"{Xung} đưa nàng qua từng cung, giải thích lễ nghi từng người để nàng khỏi bỡ ngỡ."}]}},
{"id":"j72:j72c-social-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư cung Hoàng hậu, giấy đỏ viết tay còn ướt mực, bên cạnh bàn cờ xếp sẵn quân trắng đen."},{"who":"A","text":"{Xung} muốn mở buổi đấu cờ cho cả cung bớt buồn tẻ. {Goi} đi mời từng người giúp {xung}, nhớ nói cho khéo."},{"who":"me","text":"Đấu cờ vừa nhã vừa giải khuây. Hoàng hậu muốn mời những cung nào?"},{"who":"A","text":"Mời từng người, không bỏ sót ai. {Xung} không muốn ai bảo {xung} thiên vị, cũng không muốn ai ngại không dám đến."},{"who":"me","text":"{Xung} sẽ đưa thiệp đến từng cung, lựa lời mời sao cho ai nhận được cũng thấy mình được trọng."}]}},
{"id":"j72:j72c-social-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sứ quán, rương lớn mở nắp trống rỗng, đợi người xếp những món đặc sản mang về xứ."},{"who":"A","text":"Sắp về nước, {xung} muốn mua ít đặc sản trong cung làm quà. Nhờ {goi} dẫn đường, tránh chỗ sai lễ."},{"who":"me","text":"Về nước mang theo chút hương vị nơi này là ý hay. Sứ thần muốn tặng những ai?"},{"who":"A","text":"Người thân, bạn cũ và mấy vị quan lớn. {Xung} sợ chọn món không hợp lễ nghi, mang tiếng thất kính với cung đình."},{"who":"me","text":"Ta dẫn sứ thần qua khu chợ cung, chọn đặc sản hợp từng người, còn trả giá thì cứ để ta lo."}]}},
{"id":"j72:j72c-social-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng họa sư, cuộn tranh buộc lụa vàng đặt giữa bàn, mực vừa khô, chưa ai được thấy."},{"who":"A","text":"{Xung} muốn dâng tranh cho Hoàng hậu mà không có đường vào. Nhờ {goi} nói đỡ, {xung} sẽ đền ơn."},{"who":"me","text":"Tranh vẽ xong rồi mà không đến được tay người xem thì uổng công. Họa sư vẽ gì trong cuộn này?"},{"who":"A","text":"Một bức vẽ cho Hoàng hậu, chỉ hy vọng nàng liếc nhìn một lần. Họa sư thân phận thấp, chẳng ai chịu tiến cử."},{"who":"me","text":"Ta dò ý Hoàng hậu qua nữ quan trước, rồi tìm lúc người thư thả mà tiến cử. Bức tranh sẽ đến được nơi đáng đến."}]}},
{"id":"j72:j72c-social-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần Tết, trên bàn lễ của quan nội viện, hộp gỗ đỏ buộc lụa chờ người đưa vào cung."},{"who":"A","text":"Tết sắp đến, {xung} muốn gửi lời chúc {goi} và dâng chút lễ mọn, xin {goi} nhận cho."},{"who":"me","text":"Tấm lòng của đại nhân thật chu đáo. Trong hộp này là những gì?"},{"who":"A","text":"Một hộp bánh Tết, đơn sơ thôi, nhưng {xung} tự chọn từng chiếc. {Xung} chỉ mong {goi} nhận được chút ấm áp đầu năm."},{"who":"me","text":"Ta nhận hộp lễ cùng lời chúc của đại nhân, sẽ lo cho trọn lễ đầu năm."}]}},
{"id":"j72:j72c-social-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, người con cúi đầu đứng trước án, hai tay siết chặt vạt áo."},{"who":"A","text":"Mẫu thân, con lỡ làm hỏng việc phụ hoàng giao, sợ người quở trách. Nghĩ đến thôi là con run."},{"who":"me","text":"Việc gì mà con sợ thế? Kể đầu đuôi cho mẫu thân nghe."},{"who":"A","text":"Con làm chưa tới nơi. Mẫu thân nói đỡ cho con một lời, con hứa sẽ sửa."},{"who":"me","text":"Mẫu thân sẽ hỏi rõ trước, rồi chọn lúc Hoàng thượng thư thái mà thưa. Nói đỡ không phải chối lỗi, chỉ là xin người cho con cơ hội sửa."}]}},
{"id":"j72:j72c-social-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư niêm sáp đỏ nằm trong lòng bàn tay, nét chữ ngoài bì là của cha mẹ nàng."},{"who":"A","text":"Con gái, cha mẹ nhờ gửi thư cho một cô nương cùng quê cũng ở trong cung, nó là bạn thuở nhỏ của nhà {xung}. Con giúp cha mẹ nhé."},{"who":"me","text":"Bạn thuở nhỏ của nhà ta ư? Con chưa nghe nhắc, tên nàng là gì ạ?"},{"who":"A","text":"Chuyện cũ lắm, con còn nhỏ nên không nhớ. Hai nhà đã lâu không tin tức, cha mẹ chỉ muốn nàng biết nhà vẫn nhớ."},{"who":"me","text":"Con sẽ tìm nàng giữa cung, trao tận tay lá thư, rồi viết thư nhà báo cha mẹ yên lòng."}]}},
{"id":"j72:j72c-social-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đèn trong thư phòng dịu lại, Hoàng thượng đặt bút, ánh mắt xa xăm như nghĩ về một người."},{"who":"A","text":"Trẫm có lời muốn nhờ {goi} chuyển cho Hoàng hậu, nhưng đừng để nàng biết là lời trẫm."},{"who":"me","text":"Hoàng thượng muốn Hoàng hậu hiểu điều gì mà lại phải giấu?"},{"who":"A","text":"Trẫm ngại lời mình nặng, nàng nghe sẽ thêm phiền lòng. Qua miệng {goi}, nàng sẽ dễ nghe hơn."},{"who":"me","text":"{Xung} đã hiểu. {Xung} sẽ tìm dịp gặp Hoàng hậu một mình, nói thật khéo, để người nghe lời mà không biết mình nghe ai."}]}},
{"id":"j72:j72c-social-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, hộp gỗ trầm buộc lụa đặt trên án, hương nhẹ như khói lặng."},{"who":"A","text":"Hôm nay là thọ nhật của một bà lão trong cung. Ai gia không đi được, {goi} thay ai gia đến chúc."},{"who":"me","text":"Bà lão ấy chắc đã phục vụ lâu năm nên Thái hậu mới nhớ ngày thọ."},{"who":"A","text":"Bà ở trong cung từ thuở ai gia mới vào, chưa từng đòi hỏi gì. Một lời chúc ấm áp có khi quý hơn lễ vật."},{"who":"me","text":"{Xung} xin mang hộp quà đến phòng bà, thay Thái hậu trao tận tay và chúc bà thọ cùng tháng ngày."}]}},
{"id":"j72:j72c-social-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng chợ cung nườm nượp tiếng người, nơi cửa soát, người nô tài đứng chờ với tờ giấy trong tay."},{"who":"A","text":"{Goi}, nô tài muốn xin vào chợ cung mua đồ cho chủ, mà phải có người bảo lãnh. Xin {goi} giúp một chữ."},{"who":"me","text":"Bảo lãnh là đứng ra chịu trách nhiệm. Ngươi mua gì cho chủ, ta cần biết rõ."},{"who":"A","text":"Chỉ vài thứ thường dùng, nô tài xin thề không mua gì khác. Chủ nô tài không có người bảo lãnh nào khác."},{"who":"me","text":"Ta hỏi quan coi chợ cung điều kiện bảo lãnh, viết giấy đóng dấu cung. Giữ lời nhé, ngươi."}]}},
{"id":"j72:j72c-social-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm dài, trong phòng kẻ hầu, người cung nữ ngồi bên đèn, nhắc đến bạn cũ mà mắt đỏ hoe."},{"who":"A","text":"{Goi}, {xung} có người bạn cũ từng cùng vào cung, giờ nàng ở cung khác. {Xung} nhớ nàng lắm, xin {goi} giúp {xung} gặp."},{"who":"me","text":"Cùng vào cung một ngày rồi bị chia mỗi người một ngả, thật buồn. Ngươi biết nàng ở cung nào chưa?"},{"who":"A","text":"Chưa rõ, chỉ nghe loáng thoáng. Cung nữ khác cung không dễ gặp, trừ khi ma ma bên ấy cho phép."},{"who":"me","text":"Ta dò hỏi xem nàng ở cung nào, rồi xin ma ma cung ấy cho hai người gặp. Đừng buồn nữa, ta sẽ sắp xếp."}]}},
{"id":"j72:j72c-social-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lạnh thổi qua khe cửa lãnh cung, bóng người ngồi bên song cửa mờ như sương."},{"who":"A","text":"{Xung} ở đây đã lâu, không dám xin gì. Chỉ mong {goi} chuyển lời thăm đến một người cũ, hỏi xem nàng còn nhớ {xung} chăng."},{"who":"me","text":"Người cũ ấy là ai, hiện đang ở cung nào?"},{"who":"A","text":"{Xung} không chắc nàng ở đâu giữa cung. Chỉ nhớ ngày xưa chúng ta thân nhau như tỷ muội. Đừng nói {xung} khổ, chỉ nói {xung} nhớ."},{"who":"me","text":"{Xung} sẽ tìm nàng, nói khéo cho nàng biết {goi} vẫn nhớ. {Xung} mang cả câu hỏi của {goi} đến tận tai nàng."}]}},
{"id":"j72:j72c-social-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư của {A}, thiệp mời uống trà viết chữ nhỏ, ngay ngắn nhưng chưa gửi đi."},{"who":"A","text":"{Goi}, chủ {xung} muốn mời {B} sang uống trà mà ngại mở lời trước. {Xung} đến nhờ {goi} mời hộ."},{"who":"me","text":"Muốn mời mà ngại thì ra là có tâm. Chủ ngươi vì sao muốn mời {B}?"},{"who":"A","text":"Chủ {xung} muốn kết thân, nhưng sợ {B} từ chối thì mất mặt. Nhờ {goi} mời khéo, thành hay không cũng không mất danh."},{"who":"me","text":"Ta chuyển thiệp đến cung {B} lúc nàng nhàn rỗi, nói sao cho nàng thấy được thành ý chứ không phải ép buộc."}]}},
{"id":"j72:j72c-social-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng nghỉ cung {A}, chiếc gối đôi thêu hoa lan đặt giữa giường, gió trưa lay màn nhẹ."},{"who":"A","text":"{Goi}, {B} một mình ở cung xa, {xung} muốn mời nàng sang nghỉ trưa chung mà sợ nàng ngại. {Goi} nói giúp {xung} nhé."},{"who":"me","text":"Nghỉ trưa chung là ý thân tình. Sao {goi} nghĩ đến {B}?"},{"who":"A","text":"Nàng hay lặng lẽ một mình, {xung} thấy thương. Gối đôi thêu lan này {xung} làm cho cả hai, mong nàng nhận."},{"who":"me","text":"{Xung} dò ý {B} bằng chuyện trò thường ngày, rồi mời nàng sang sau buổi trưa. Giữ thân mật là điều quan trọng nhất."}]}},
{"id":"j72:j72c-social-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sảnh cung, sứ thần đứng thẳng như tượng, hai tay không biết đặt nơi nào cho phải phép."},{"who":"A","text":"{Xung} mới đến, chưa rành lễ cung đình. Xin {goi} chỉ cho vài điều kẻo sai."},{"who":"me","text":"Lễ cung đình tuy nhiều nhưng chỉ cần nhớ vài điều gốc. Sứ thần muốn bắt đầu từ lễ nào?"},{"who":"A","text":"Từ lễ cúi chào. {Xung} sợ mình cúi quá sâu hay quá nông thì thành thất lễ, mang tiếng cho cả nước."},{"who":"me","text":"Ta chỉ từng động tác cúi chào cho đúng, sứ thần làm thử một lần, ta sẽ nhắc nhở nhẹ nhàng."}]}},
{"id":"j72:j72c-social-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chuyện bàn tán lan khắp các cung, ai nhắc đến {B} cũng khẽ nhíu mày."},{"who":"A","text":"{B} dạo này kiêu căng quá, mọi người bàn tán. {Goi} nói khéo để nàng biết, đừng để {xung} phải ra mặt."},{"who":"me","text":"Lời đồn hay lời thật, {goi} có chắc không? {Xung} không muốn vì một lời mà làm tổn thương nàng."},{"who":"A","text":"{Xung} thấy tận mắt rồi. Nhưng nàng kiêu ngạo, nói thẳng nàng sẽ giận. {Goi} khéo léo hơn {xung} nhiều."},{"who":"me","text":"{Xung} sẽ tìm dịp trò chuyện riêng với {B}, nhẹ nhàng nhắc chuyện lời đồn, chỉ để nàng tự biết mà sửa."}]}},
{"id":"j72:j72c-social-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thuốc, mấy bát thuốc nguội bỏ dở nằm trên khay, mùi đắng còn đọng."},{"who":"A","text":"Thần dặn cung nhân uống thuốc mà họ cứ bỏ dở. Xin {goi} lên tiếng, họ nghe {goi} hơn nghe thần."},{"who":"me","text":"Bệnh chưa khỏi mà thuốc đã bỏ thì lấy gì mà lành. Họ bỏ vì đắng, hay vì không tin?"},{"who":"A","text":"Cả hai. Thuốc đắng, lại thêm lời thần dặn họ thấy khô khan. Nếu {goi} nói, họ sẽ nghe."},{"who":"me","text":"Ta gọi họ đến, nói chuyện nhỏ nhẹ, để họ hiểu uống thuốc là thương mình chứ không phải chịu phạt."}]}},
{"id":"j72:j72c-social-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư của {A}, tấm thiệp mời kín không đề tên đặt úp mặt, như giấu một lời chưa nói."},{"who":"A","text":"{Xung} và {B} có chuyện cũ chưa nói rõ. {Xung} không muốn gặp công khai. {Goi} dàn xếp cho {xung} gặp nàng kín đáo một lần."},{"who":"me","text":"Chuyện cũ chưa nói rõ thì dễ thành oán. {Goi} muốn nói gì với {B}?"},{"who":"A","text":"{Xung} chưa biết, chỉ biết nếu cứ để mãi thì càng sâu. Nóng nảy mấy ngày, {xung} mệt rồi."},{"who":"me","text":"{Xung} thăm dò tâm trạng {B} trước, chọn nơi kín, rồi dẫn hai bên đến giờ hẹn không để ai thấy."}]}},
{"id":"j72:j72c-social-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, bên thềm Đức Thọ cung, sương chưa tan, cô gái mới vào cung đứng ngơ ngác bên cạnh cha."},{"who":"A","text":"Con gái thần mới vào cung, chưa rành lễ thỉnh an. Nhờ {goi} dẫn nàng đến Đức Thọ cung lần đầu."},{"who":"me","text":"Lần đầu thỉnh an hẳn khiến nàng bối rối. Đại nhân có dặn nàng điều gì không?"},{"who":"A","text":"Thần dặn nàng nhớ lễ nhưng chưa dặn kỹ. Thần chỉ mong nàng biết điều, không phạm húy."},{"who":"me","text":"Ta cùng nàng đến Đức Thọ cung, dặn nàng từng điều nên nói nên im, nàng sẽ yên lòng."}]}},
{"id":"j72:j72c-social-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng cuối ngày, người con ngồi bên mẫu thân, giọng nhỏ như sợ ai nghe."},{"who":"A","text":"Mẫu thân, con nghe nhiều lời đồn quá. Mẫu thân dặn con làm sao để tránh rắc rối nhé."},{"who":"me","text":"Lời đồn trong cung đa phần thật giả lẫn lộn. Con nghe được điều gì mà lo vậy?"},{"who":"A","text":"Chuyện các cung tranh nhau, con sợ vô tình bị kéo vào. Con muốn sống yên mà không biết có được không."},{"who":"me","text":"Mẫu thân dặn con ba điều: nói ít, nghe nhiều, đừng chọn phe. Con ngồi lại đây, ta nói kỹ từng chuyện."}]}},
{"id":"j72:j72c-social-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, tin vui của {B} vẫn chỉ là thì thầm lấp lửng giữa các cung."},{"who":"A","text":"{Goi}, {xung} nghe {B} có tin vui mà nàng giấu kín. {Goi} khéo hỏi dò giúp {xung}, nhưng đừng để nàng biết là {xung} nhờ."},{"who":"me","text":"Sao {goi} không hỏi thẳng nàng? Bạn bè nên chân thành với nhau."},{"who":"A","text":"{B} kín đáo, hỏi thẳng nàng sẽ càng khép. {Xung} chỉ muốn mừng cho nàng mà không làm nàng khó xử."},{"who":"me","text":"{Xung} bắt chuyện như tình cờ, hỏi dò từng bước theo ý nàng. Nếu nàng chưa muốn nói, {xung} sẽ không ép."}]}},
{"id":"j72:j72c-social-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Yến tiệc của Hoàng hậu đã gần kề, trong sân cung nhân tấp nập mà chưa ai nhận được việc hầu trà."},{"who":"A","text":"Yến tiệc sắp tới cần người hầu trà tử tế. {Goi} nhìn giúp {xung} chọn ai cho khéo."},{"who":"me","text":"Hầu trà tuy nhỏ nhưng nhìn biết ngay nết người. Hoàng hậu muốn chọn người thế nào?"},{"who":"A","text":"Nhanh tay mà không vụng, khéo nói mà không nhiều lời. {Xung} không muốn bàn yến bị một ly trà làm hỏng hứng."},{"who":"me","text":"{Xung} xem cung nhân từng cung, chọn người nhẹ nhàng và biết ý, để yến tiệc trọn vẹn."}]}},
{"id":"j72:j72c-social-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang cung bên, hai bóng người lướt qua nhau, chẳng ai chào ai."},{"who":"A","text":"{Goi}, {xung} và cung nữ cung bên có chút hiểu lầm vì một câu nói. {Xung} không biết nói sao, mong {goi} giúp."},{"who":"me","text":"Câu nói thế nào mà thành hiểu lầm? Ngươi kể ta nghe từ đầu."},{"who":"A","text":"Hôm đó {xung} chỉ buột miệng, nàng nghe lại thành ra {xung} chê nàng. Từ đó nàng không nhìn mặt {xung}."},{"who":"me","text":"Ta nghe ngươi kể đầu đuôi, rồi gặp cung nữ bên ấy nghe nàng nói. Hiểu lầm giải ra thì tình xưa còn đó."}]}},
{"id":"j72:j72c-social-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cửa sổ lãnh cung, một vệt nắng rọi xuống sân, nhưng người ở trong đã bao ngày không bước ra."},{"who":"A","text":"{Xung} bị nhốt trong phòng cả mùa, chỉ muốn ra sân một lát hóng nắng. {Goi} nói giúp {xung} với quản sự lãnh cung."},{"who":"me","text":"Người chỉ muốn hóng nắng, đâu phải chuyện lớn. Quản sự có cấm hẳn không?"},{"who":"A","text":"Cấm, {xung} không biết vì sao. Đã lâu {xung} không thấy trời, chỉ muốn ngồi một chút dưới nắng."},{"who":"me","text":"{Xung} đến gặp quản sự lãnh cung xin cho {goi} ra sân. Nắng không phải của riêng ai, {xung} sẽ thưa thật khéo."}]}},
{"id":"j72:j72c-social-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư của {A}, hộp gấm nhỏ đặt cạnh tờ lời chúc chưa dán, như món quà còn dang dở."},{"who":"A","text":"Hôm nay là sinh nhật {B}, mà {xung} lỡ quên chuẩn bị quà. {Goi} thay {xung} chuyển lời chúc nhé."},{"who":"me","text":"Quên ngày sinh nhật của bạn thì ai cũng áy náy. Trong hộp gấm này là gì?"},{"who":"A","text":"Món quà nhỏ {xung} chuẩn bị gấp, không đáng giá nhưng thật lòng. {Xung} sợ {B} nghĩ {xung} đã quên nàng."},{"who":"me","text":"{Xung} mang quà và lời chúc đến cung {B}, nói thật rằng {goi} nhớ nàng, chỉ chậm một chút thôi."}]}},
{"id":"j72:j72c-social-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối ngày, trong phòng kẻ hầu, đồ đạc chất thành đống, chưa kịp dọn gọn trước ngày soát."},{"who":"A","text":"{Goi}, ma ma sắp kiểm tra phòng nô tài mà nô tài chưa dọn kịp. Xin {goi} nói khéo hoãn một buổi."},{"who":"me","text":"Soát phòng là lệ cung, hoãn không dễ. Vì sao ngươi chưa dọn kịp?"},{"who":"A","text":"Nô tài bận việc cả ngày, chỉ còn đêm là dọn. Xin cho một buổi, nô tài hứa sẽ sạch sẽ."},{"who":"me","text":"Ta tìm ma ma, nói chuyện thân mật rồi xin hoãn một buổi, chỉ vì ngươi lần đầu thôi đấy."}]}},
{"id":"j72:j72c-social-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân trước cung trống vắng, chỉ có bóng gió thổi qua, nhạc cụ nằm im trong hòm."},{"who":"A","text":"{Xung} muốn mở buổi diễn nhạc ngoài sân trước, nhưng không có lệnh Hoàng hậu. Nhờ {goi} nói giúp."},{"who":"me","text":"Diễn nhạc ngoài sân là hay, nhưng không có lệnh thì sao dám? Nhạc sư định diễn khúc nào?"},{"who":"A","text":"Một bản hợp tấu mừng xuân. {Xung} đã luyện nhiều ngày cùng các nhạc công, chỉ chờ phép."},{"who":"me","text":"Ta thăm dò ý Hoàng hậu, rồi dâng chương trình biểu diễn lên người. Bản nhạc hay, hẳn người sẽ cho phép."}]}},
{"id":"j72:j72c-social-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng trang điểm cung {B}, mảnh chén ngọc vỡ nằm dưới kệ, lấp lánh như sương."},{"who":"A","text":"{Goi}, {xung} lỡ làm vỡ chén ngọc của chủ, chủ nổi giận định phạt nặng. {Goi} nói giúp {xung} một lời."},{"who":"me","text":"Chén ngọc vỡ là chuyện lớn, nhưng nặng phạt thì ngươi chịu nổi sao? Chủ ngươi thù dai, ta biết."},{"who":"A","text":"{Xung} biết lỗi rồi. Chỉ xin {goi} thưa giúp, kẻo chủ {xung} không nghe lời ai khác."},{"who":"me","text":"Ta gặp {B}, nói nhỏ nhẹ xin tha. Mảnh chén ta sẽ đưa thợ Nội vụ phủ xem có dán lại được không."}]}},
{"id":"j72:j72c-social-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, giỏ mây đựng bánh đặt cạnh cửa, hơi ấm còn vương dưới nắp."},{"who":"A","text":"Ai gia nhớ mấy cung nhân già làm việc lâu năm, giờ ở phòng nhỏ phía tây. {Goi} thay ai gia đến thăm."},{"who":"me","text":"Cung nhân già ở phòng nhỏ phía tây hẳn chưa ai ghé thăm. Thái hậu nhớ họ đến vậy sao?"},{"who":"A","text":"Họ đã theo ai gia từ lúc còn trẻ. Nay già yếu, ai gia không đi được, chỉ mong có người đến hỏi han."},{"who":"me","text":"{Xung} xin mang giỏ quà này đến phòng họ, thay Thái hậu thăm hỏi từng người."}]}},
{"id":"j72:j72c-social-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài sảnh Hoàng hậu, quan lại đứng chờ dưới hiên, tay cầm tờ thưa viết sẵn."},{"who":"A","text":"Thần muốn xin Hoàng hậu một buổi gặp mà không có đường vào. Nhờ {goi} chuyển lời."},{"who":"me","text":"Hoàng hậu bận nhiều việc, gặp không dễ. Đại nhân cần gặp để thưa chuyện gì?"},{"who":"A","text":"Việc quan trọng, chỉ có thể nói trực tiếp. Thần đã chuẩn bị lời thưa, chỉ chờ cơ hội."},{"who":"me","text":"Ta nói với nữ quan Hoàng hậu về yêu cầu, rồi giúp đại nhân chuẩn bị lời thưa chu đáo trước khi gặp."}]}},
{"id":"j72:j72c-social-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng đọc của {A}, giá sách xếp ngay ngắn, một chiếc ghế trống đặt cạnh ghế chủ nhân."},{"who":"A","text":"{Goi}, {B} cũng thích đọc sách như {xung}. {Goi} giới thiệu cho {xung} làm quen với nàng nhé."},{"who":"me","text":"Hai người thích sách thì dễ thân. {Goi} biết {B} thích sách nào không?"},{"who":"A","text":"Chưa rõ, nhưng thấy nàng cầm sách đi trong vườn, {xung} đã muốn bắt chuyện mà ngại."},{"who":"me","text":"{Xung} mời {B} sang phòng đọc của {goi}, giới thiệu hai người. Sách sẽ nói thay lời mở đầu."}]}},
{"id":"j72:j72c-social-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, người con ngồi ngay ngắn mà mắt cứ liếc ra cửa, như đợi tin từ xa."},{"who":"A","text":"Mẫu thân, con nghe nói có người dò hỏi về con. Mẫu thân hỏi giúp con xem là ai."},{"who":"me","text":"Con nghe được từ đâu? Chuyện hôn sự đâu phải điều nên đoán mò."},{"who":"A","text":"Con nghe cung nhân thì thầm, nhưng chẳng ai dám nói rõ. Con không muốn bị gả mà không biết người ấy là ai."},{"who":"me","text":"Mẫu thân sẽ hỏi cung nhân quen biết ngoài cung, dò thái độ đôi bên, rồi báo lại cho con. Con cứ yên tâm."}]}},
{"id":"j72:j72c-social-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sớm mai, trong sân cung, hai chiếc khăn lễ đã gấp sẵn, hương trầm còn trong hộp chưa thắp."},{"who":"A","text":"{Goi}, mai chị em {xung} đi lễ chùa cầu bình an mà {xung} chưa có người cùng đi. {Goi} đi chung với {xung} nhé."},{"who":"me","text":"Đi lễ chùa cầu bình an là điều hay. {Goi} muốn cầu điều gì?"},{"who":"A","text":"Cầu cho người thân bình an, cho cung {xung} yên ổn. Một mình {xung} đến chùa thấy lòng trống lắm."},{"who":"me","text":"Vậy {xung} cùng đi, sang chùa dâng hương. Hai người cùng khấn thì lòng thêm vững."}]}},
{"id":"j72:j72c-social-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thư nhà viết vội, mực loang nơi dòng báo tin, tay người đọc run run."},{"who":"A","text":"Con gái, nhà {xung} có chuyện không may. Con báo cho cô cô trong cung biết nhẹ nhàng, đừng để nàng sốc."},{"who":"me","text":"Chuyện gì xảy ra vậy ạ? Cô cô thương gia đình mình, con biết nói sao cho nàng đỡ đau?"},{"who":"A","text":"Người ấy vừa mất, cha mẹ cũng đau lòng. Cô cô con từ xa nghe tin sẽ không chịu nổi, con ở bên nàng một lúc."},{"who":"me","text":"Con tìm cô cô, chọn lời nhẹ nhàng báo tin, rồi ở bên nàng lúc nàng khóc. Con sẽ không để cô cô một mình."}]}},
{"id":"j72:j72c-social-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng cung nhân, tấm khăn che bệnh còn dựng đứng, mấy người ngồi im lặng như tránh người lạ."},{"who":"A","text":"Cung nhân ở đây ngại gặp thái y vì sợ tốn bạc. Xin {goi} giới thiệu giúp thần."},{"who":"me","text":"Họ sợ tốn bạc, hay sợ người trên biết họ ốm? Cung nhân nghèo thường giấu bệnh."},{"who":"A","text":"Cả hai. Thần chỉ muốn chữa bệnh, không nhận gì ngoài phận sự. Nhưng họ không tin thần."},{"who":"me","text":"Ta đưa thái y đến phòng họ, giới thiệu thật rõ ràng. Họ tin ta thì sẽ tin người."}]}},
{"id":"j72:j72c-social-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa các cung, lời đồn về {B} đi nhanh hơn tiếng bước chân, nghe như gió lùa qua hành lang."},{"who":"A","text":"Có người bảo {B} nói xấu {xung} sau lưng. {Goi} khéo dò giúp {xung} xem có thật không."},{"who":"me","text":"Lời đồn chưa chắc là thật. {Goi} nghe ai nói vậy, và bao giờ?"},{"who":"A","text":"Mấy hôm trước, có người thì thầm. {Xung} không muốn hiểu lầm {B}, mà cũng không muốn bị lừa."},{"who":"me","text":"{Xung} trò chuyện với cung nữ thân cận của {B}, hỏi dò bằng cách thân mật. Hễ biết thật hay giả, {xung} sẽ báo lại."}]}},
{"id":"j72:j72c-social-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối ngày, người cung nữ đứng bên tấm lịch cũ treo tường, ngón tay đặt trên một ngày chưa dám đánh dấu."},{"who":"A","text":"{Goi}, {xung} muốn xin phép về nhà thăm mẹ, nhưng muốn chọn ngày lành. Xin {goi} chỉ giúp."},{"who":"me","text":"Về thăm mẹ thì ngày nào cũng là ngày tốt. Vì sao ngươi muốn chọn ngày lành?"},{"who":"A","text":"Mẹ {xung} hay lo, thấy ngày lành bà mới yên lòng. {Xung} muốn bà thấy con về trong niềm vui."},{"who":"me","text":"Ta xem lịch ngày tốt cùng ngươi, chọn ngày thích hợp rồi xin phép cho đúng lễ."}]}},
{"id":"j72:j72c-social-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, Hoàng thượng đặt bút xuống, giọng trầm xuống như người nhớ một điều đã lâu chưa làm."},{"who":"A","text":"Trẫm bận chính sự, không đến thỉnh an Thái hậu nhiều. {Goi} khéo nói để Thái hậu biết lòng trẫm."},{"who":"me","text":"Thái hậu hẳn trông ngóng Hoàng thượng lắm. {Xung} nói sao cho Thái hậu thấy được lòng người mà không thành trách móc?"},{"who":"A","text":"Chỉ cần nói trẫm vẫn nhớ, vẫn nghĩ đến người mỗi ngày. Trẫm không biết tự nói sao cho đủ ý."},{"who":"me","text":"{Xung} sẽ thăm Thái hậu lúc người rảnh, kể thật tế nhị chuyện Hoàng thượng luôn nhớ đến người."}]}},
{"id":"j72:j72c-social-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng người bệnh, màn buông nhẹ, bát thuốc đã nguội đặt bên gối."},{"who":"A","text":"{Goi}, {xung} nằm mãi một chỗ buồn lắm. {Goi} đến đọc thơ cho {xung} nghe nhé."},{"who":"me","text":"Nằm bệnh một mình, nghe thơ cũng bớt trống trải. {Goi} thích thơ nào?"},{"who":"A","text":"Thơ nhẹ nhàng, nói chuyện hoa, chuyện gió. {Xung} không muốn nghe điều gì nặng nề."},{"who":"me","text":"{Xung} đến ngồi bên giường, đọc từng bài cho {goi} nghe. Nghe thơ rồi, bệnh cũng dễ chịu hơn."}]}},
{"id":"j72:j72c-social-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư cung Hoàng hậu, tấm thiệp đỏ viết sẵn, mực đỏ như son dưới ánh đèn."},{"who":"A","text":"Lễ mừng Thái hậu sắp tới, {goi} đi mời mấy phu nhân nhà quan vào dự cho đủ nghi thức."},{"who":"me","text":"Mời đủ nghi thức thì các phu nhân phải được trọng. Hoàng hậu muốn mời những phủ nào?"},{"who":"A","text":"Những phủ có công với triều, theo danh sách trong thiệp. Đừng để ai thấy mình bị bỏ sót."},{"who":"me","text":"{Xung} gửi thiệp qua nữ quan và thái giám các phủ, lời mời phải đủ lễ và đủ ấm áp."}]}},
{"id":"j72:j72c-social-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tối đến, tiếng nhạc yến vọng từ xa, người ngồi trong phòng vẫn chưa dám bước ra."},{"who":"A","text":"{Goi}, yến tiệc tối nay {xung} sợ ngồi một mình lạc lõng. {Goi} đi cùng {xung} nhé, giúp {xung} bắt chuyện với mọi người."},{"who":"me","text":"Yến tiệc đông người mà vẫn thấy lẻ loi, {xung} hiểu. {Goi} sợ điều gì nhất?"},{"who":"A","text":"Sợ không có ai nói chuyện, sợ người ta nhìn rồi bàn tán. {Xung} chỉ muốn có {goi} bên cạnh."},{"who":"me","text":"{Xung} cùng {goi} bước vào yến, giúp {goi} bắt chuyện với từng người. Có {xung} bên cạnh thì không ai dám xem thường."}]}},
{"id":"j72:j72c-social-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng họa sư, tranh phác dựng dọc tường, giấy dó trống chờ mấy nét đầu tiên của học trò."},{"who":"A","text":"{Xung} muốn nhận mấy học trò trong cung dạy vẽ. {Goi} giới thiệu giúp, {xung} sẽ không nhận bạc."},{"who":"me","text":"Dạy vẽ mà không nhận bạc là lòng hiếm có. Họa sư muốn dạy những người thế nào?"},{"who":"A","text":"Ai có lòng muốn học, không cần giỏi. Cung nhân sống đơn điệu, một nét vẽ đôi khi làm họ vui."},{"who":"me","text":"Ta dò xem cung nhân nào muốn học vẽ, dẫn họa sư gặp họ rồi cùng chọn học trò."}]}},
{"id":"j72:j72c-social-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trời hửng muộn, người ngồi bên cửa sổ nhìn mãi về phía cung Hoàng hậu, rồi lại thở dài."},{"who":"A","text":"{Xung} có chuyện riêng, không đi thỉnh an Hoàng hậu một kỳ được. {Goi} khéo xin hộ {xung}, đừng để Hoàng hậu nghi."},{"who":"me","text":"Chuyện riêng của {goi} lớn đến mức phải miễn thỉnh an sao? Hoàng hậu hay xét kỹ, nói dối khó lọt mắt người."},{"who":"A","text":"{Xung} không nói dối, chỉ là chưa tiện nói. {Goi} khéo léo nên {xung} mới nhờ."},{"who":"me","text":"{Xung} thăm dò tâm trạng Hoàng hậu, chọn lúc người thư thái rồi dâng lời xin cùng một món quà nhỏ."}]}},
{"id":"j72:j72c-social-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách, khay trà đặt sẵn trên bàn, hơi nước mỏng bốc lên từ ấm sứ trắng."},{"who":"A","text":"{Goi}, hôm nay có khách quý đến cung. {Xung} sợ pha trà không đúng cách, mong {goi} chỉ."},{"who":"me","text":"Khách quý thì trà phải đúng phép. Ngươi pha thử trước ta xem."},{"who":"A","text":"Dạ, {xung} tráng ấm rồi rót nước, nhưng chưa biết phải rót ba lần. {Xung} sợ làm khách phật ý."},{"who":"me","text":"Ta chỉ ngươi tráng ấm, rót trà ba lần cho đều vị. Pha trà cũng như đãi khách, quan trọng nhất là lòng thành."}]}},
{"id":"j72:j72c-social-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân cung, bảng phân ca trực dán cạnh cửa, một cái tên đã bị gạch rồi viết lại."},{"who":"A","text":"{Goi}, {xung} muốn đổi ca trực mà chủ không cho. {Xung} nhờ {goi} nói giúp."},{"who":"me","text":"Chủ ngươi không cho vì lẽ gì? Ta cần biết nguyên do trước khi nói."},{"who":"A","text":"Chủ {xung} bảo ca ấy quan trọng, đổi sẽ lỡ việc. Nhưng {xung} có lý do riêng, không tiện nói."},{"who":"me","text":"Ta gặp chủ ngươi hỏi nguyên do, rồi đề xuất cách đổi ca sao cho việc cung không bị ảnh hưởng."}]}},
{"id":"j72:j72c-social-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài hiên Đức Thọ cung, quan lại đứng chờ, tay ôm hộp thuốc bổ buộc lụa."},{"who":"A","text":"Thần nghe Thái hậu trong người không khỏe, muốn gửi lời thăm hỏi mà không có đường. Nhờ {goi} chuyển."},{"who":"me","text":"Lòng thành của đại nhân đáng quý. Người muốn thưa với Thái hậu những gì?"},{"who":"A","text":"Chỉ mong Thái hậu mạnh khỏe. Thần không dám đòi gì, chỉ muốn Thái hậu biết thần luôn nhớ."},{"who":"me","text":"Ta đến Đức Thọ cung, dâng lời của đại nhân cho Thái hậu bằng giọng thật thành kính."}]}},
{"id":"j72:j72c-social-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối ngày, nô tài đứng gác bên cổng, chân sưng đỏ, vạt áo bám đầy bụi."},{"who":"A","text":"{Goi}, nô tài đứng gác cả ngày chân sưng, xin {goi} nói với người coi chỗ cho nô tài một chỗ ngồi."},{"who":"me","text":"Đứng cả ngày thì ai chịu nổi. Chân ngươi sưng thế này, thái y đã xem chưa?"},{"who":"A","text":"Dạ chưa, nô tài sợ xin nghỉ bị phạt. Chỉ mong có chỗ ngồi giây lát, để chân bớt đau."},{"who":"me","text":"Ta gặp người coi chỗ gác, nói giúp ngươi một chỗ ngồi. Làm việc cũng cần có chỗ để thở."}]}},
{"id":"j72:j72c-social-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thư nhà gửi tới giữa buổi chiều, nét chữ của mẹ nàng nhỏ và run, hỏi han từng dòng."},{"who":"A","text":"Con gái, mẹ muốn biết con ở cung có tốt không. Con báo lại cho mẹ, nhớ nói đủ."},{"who":"me","text":"Con vẫn khỏe, mẹ đừng lo. Mẹ nhận thư của con lần cuối khi nào?"},{"who":"A","text":"Lâu rồi, mẹ nhớ con lắm. Con viết thật đầy đủ, mẹ muốn đọc từng chuyện nhỏ."},{"who":"me","text":"Con sẽ tìm sứ giả đi qua phủ nhà, chọn lời bình yên, tránh làm mẹ lo, rồi viết thư thật dài."}]}},
{"id":"j72:j72c-social-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi chiều trước yến, nữ quan phân chỗ ngồi đang chép tên từng người lên tấm bảng gỗ."},{"who":"A","text":"Yến tối nay {xung} sợ ngồi cạnh {B} lại sinh chuyện. {Goi} nói giúp {xung} xếp chỗ ngồi khéo nhé."},{"who":"me","text":"Hai người đã có chuyện gì sao? Hay chỉ sợ bất hòa vô cớ?"},{"who":"A","text":"Chưa có gì, nhưng {xung} biết tính {B} nóng. Ngồi gần nhau, chỉ cần một lời là thành chuyện."},{"who":"me","text":"{Xung} gặp nữ quan phân chỗ ngồi, đề xuất lại vị trí cho {goi} yên lòng. Chuyện này {xung} xin giữ kín."}]}},
{"id":"j72:j72c-social-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, tiếng gió lùa qua cửa sổ, tĩnh lặng đến mức nghe được nhịp thở của người."},{"who":"A","text":"Ai gia muốn nghe mấy bài hát quê của cung nhân. {Goi} gọi họ đến cho ai gia vui."},{"who":"me","text":"Hát quê là điệu dân dã nhưng chất chứa tình. Thái hậu muốn nghe những khúc nào?"},{"who":"A","text":"Khúc nào cũng được, miễn là hồn nhiên. Ai gia ở cung lâu, nhớ tiếng hát thuở còn trẻ."},{"who":"me","text":"{Xung} xin tìm vài cung nhân hát hay trong cung, mời đến cho Thái hậu thưởng thức."}]}},
{"id":"j72:j72c-social-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thư của {A}, tấm thiệp xin lỗi viết tay còn vệt nước mắt, giấy nhăn ở một góc."},{"who":"A","text":"Mẫu thân, con lỡ lời làm bạn giận. Con không dám đến xin lỗi, mẫu thân nhắn giúp con."},{"who":"me","text":"Lỡ lời thì con nên tự xin lỗi, bạn mới hiểu lòng con. Vì sao con không dám?"},{"who":"A","text":"Con sợ bạn không tha thứ, mà thiệp này con viết đi viết lại mấy lần. Mẫu thân giúp con trao nó."},{"who":"me","text":"Mẫu thân sẽ tìm bạn con lúc nàng vui, trao thiệp và nói thật nhẹ nhàng. Con nên nhớ, xin lỗi cũng là một sự can đảm."}]}},
{"id":"j72:j72c-social-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho Thái y viện, các hộc dược liệu trống nhiều, nhãn vẫn còn dán mà bên trong chẳng còn gì."},{"who":"A","text":"Thái y viện thiếu bạc mua dược liệu. Nhờ {goi} nói giúp với Nội vụ phủ."},{"who":"me","text":"Dược liệu thiếu thì cung nhân bệnh cũng khó chữa. Thái y cần bao nhiêu?"},{"who":"A","text":"Thần đã ghi từng vị, cần bao nhiêu thần ghi rõ. Thần chỉ mong Nội vụ phủ cấp đủ."},{"who":"me","text":"Ta gặp quan Nội vụ phủ trình bày, nói rõ vì sao cần. Dược liệu là mạng người."}]}},
{"id":"j72:j72c-social-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư gấp nhỏ giấu trong tay áo, góc giấy đã mòn vì được vuốt đi vuốt lại."},{"who":"A","text":"{Xung} không dám xin gì, chỉ mong {goi} gửi hộ lá thư này đến người thân của {xung} trong cung."},{"who":"me","text":"Thư này viết đã lâu chưa? Người thân của {goi} có biết {goi} còn nhớ nàng không?"},{"who":"A","text":"Viết rất lâu, nhưng chưa có ai dám mang đi. Ở đây chẳng ai dám nhận thư của {xung}."},{"who":"me","text":"{Xung} mang thư ra khỏi lãnh cung thật khéo, rồi trao tận tay người thân của {goi}."}]}},
{"id":"j72:j72c-social-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng đầu tuần, mấy cung nhân mới đứng nép bên hiên, áo còn mới mà dáng đã mỏi vì lạ chỗ."},{"who":"A","text":"Cung nhân mới vào thường quên nề nếp. {Goi} dặn giúp {xung} vài điều."},{"who":"me","text":"Nề nếp trong cung không ít điều, nên dặn từng điều một. {Goi} muốn nhắc điều nào trước?"},{"who":"A","text":"Điều gốc là kính trên nhường dưới, nói năng giữ lễ. Còn lại sẽ học dần theo năm tháng."},{"who":"me","text":"{Xung} gọi cung nhân mới đến chỗ yên tĩnh, dặn thật dịu dàng, để họ nhớ là vì quý chứ không phải vì sợ."}]}},
{"id":"j72:j72c-social-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước giờ trà chiều, quan coi bàn trà đang xếp thẻ tên lên từng chiếc bàn thấp."},{"who":"A","text":"{Goi}, trà chiều nay {xung} ngồi chung với {B} thật chán. {Goi} giúp {xung} đổi bàn nhé, đừng để ai phật ý."},{"who":"me","text":"Sao {goi} thấy chán? {B} có làm gì {goi} không?"},{"who":"A","text":"Không, chỉ là hai người không hợp chuyện. {Xung} muốn yên ổn, mà cũng không muốn làm {B} buồn."},{"who":"me","text":"{Xung} tìm quan coi trà chiều xin đổi bàn, rồi giải thích lý do cho {B} nghe thật khéo. Đừng lo."}]}},
{"id":"j72:j72c-social-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng {A}, hộp gấm nhỏ đặt trên bàn, bên trong là vải mới và mấy thỏi bạc gói khéo."},{"who":"A","text":"{Goi}, {B} đang túng bạc mà nàng lại sĩ diện. {Goi} giúp {xung} gửi chút quà kín đáo, đừng nói của ai."},{"who":"me","text":"Giúp mà không để người biết, lòng ấy đáng quý. {Goi} nhận ra {B} túng từ lúc nào?"},{"who":"A","text":"Từ mấy hôm nay, thấy nàng mặc áo cũ mà vẫn cười nói như thường. {Xung} nhìn mà thương."},{"who":"me","text":"{Xung} mang gói quà đến cung {B} lúc trời chạng vạng, để nàng nhận mà không phải ngượng."}]}},
{"id":"j72:j72c-social-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sứ quán, sứ thần ngồi trước bàn trà đã nguội, tay mân mê chiếc quạt xếp."},{"who":"A","text":"{Xung} lỡ lời trước mặt một quan cung hôm qua, chưa dám đến xin lỗi. Nhờ {goi} nói đỡ."},{"who":"me","text":"Lỡ lời thế nào, sứ thần kể lại ta nghe. Quan cung ấy là người rộng lượng hay hay chấp nhặt?"},{"who":"A","text":"{Xung} chưa rõ, chỉ biết mình nói sai. Ở xứ lạ, một lời cũng có thể thành mối thù."},{"who":"me","text":"Ta gặp quan cung dò thái độ, rồi truyền lời xin lỗi của sứ thần cho đúng ý."}]}},
{"id":"j72:j72c-social-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong hộp nhỏ ở phòng {A}, chiếc khăn thêu đôi nhạn cuộn lại, màu chỉ đã phai theo năm tháng."},{"who":"A","text":"{Goi}, {xung} và {B} từng thân mà xa nhau vì hiểu lầm cũ. {Goi} giúp {xung} dựng lại tình chị em nhé."},{"who":"me","text":"Hiểu lầm cũ nhưng tình chưa mất. Khăn thêu đôi nhạn này là của hai người?"},{"who":"A","text":"Phải, ngày trước hai người thêu chung. {Xung} giữ nó bao năm, chưa nỡ vứt."},{"who":"me","text":"{Xung} tìm hiểu nguyên nhân hai người xa nhau, dẫn {goi} đến cung {B}, mời hai người ngồi bên trà mà nói. Khăn ấy sẽ nối lại tình xưa."}]}},
{"id":"j72:j72c-social-061","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang cung bên, một bóng áo quen thấp thoáng, người nhìn theo rồi lại cúi mặt."},{"who":"A","text":"{Goi}, {xung} gặp lại một chị cùng làng ở cung bên mà chưa dám chào. {Goi} dẫn {xung} qua chào một tiếng."},{"who":"me","text":"Cùng làng thì thân tình, sao lại ngại?"},{"who":"A","text":"Nàng giờ có vị thế hơn, {xung} sợ nàng không nhận ra. Nhưng bỏ qua thì thấy tiếc."},{"who":"me","text":"Ta dẫn ngươi sang cung bên chào. Chị em cùng làng, chắc chắn nàng sẽ mừng."}]}},
{"id":"j72:j72c-social-062","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sớm tinh sương, vườn hoa phủ đầy sương, những nụ mới chớm hé giữa lá xanh."},{"who":"A","text":"{Goi}, {xung} muốn đi dạo vườn hoa với {B} mà ngại mở lời. {Goi} rủ nàng giúp {xung} nhé."},{"who":"me","text":"Đi dạo buổi sớm là thú vui thanh tịnh. {Goi} ngại vì lẽ gì?"},{"who":"A","text":"{Xung} sợ {B} từ chối, mà cũng không muốn nàng nghĩ {xung} có ý gì."},{"who":"me","text":"{Xung} rủ {B} đi dạo vườn hoa buổi sớm, nói thật tự nhiên để nàng thấy ngại cũng thành dễ chịu."}]}},
{"id":"j72:j72c-social-063","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn tiếp khách ở Đức Thọ cung, hộp trà biếu khắc hoa mai nằm chờ dưới ánh đèn."},{"who":"A","text":"Một phu nhân ngoài cung đến thăm mà ai gia mệt, {goi} thay ai gia tiếp nàng giúp."},{"who":"me","text":"Thái hậu mệt thì cứ nghỉ ngơi. Phu nhân ấy muốn gì, Thái hậu có biết chưa?"},{"who":"A","text":"Nàng hay nhờ vả điều lớn, ai gia không muốn nhận mà cũng không muốn làm nàng mất lòng."},{"who":"me","text":"{Xung} tiếp phu nhân ở phòng khách nhỏ, khéo từ chối chuyện lớn mà giữ được lòng nàng."}]}},
{"id":"j72:j72c-social-064","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối ngày dài, ma ma ngồi bên bàn ghi sổ, ngón tay thoăn thoắt mà chưa từng ngẩng lên."},{"who":"A","text":"{Goi}, {xung} làm việc bao lâu mà ma ma chưa từng nhắc đến. {Xung} không dám xin, chỉ mong {goi} khéo nhắc."},{"who":"me","text":"Làm lâu mà không ai thấy thì tủi thân lắm. Ngươi chưa từng nghe ma ma khen điều gì sao?"},{"who":"A","text":"Chưa từng, nhưng {xung} không đòi gì hơn. Chỉ mong ma ma biết là {xung} vẫn cố gắng."},{"who":"me","text":"Ta tìm ma ma lúc bà dễ chịu, nói khéo công lao của ngươi. Việc đúng thì ai cũng nên được ghi nhận."}]}},
{"id":"j72:j72c-court-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, ngự thư phòng thoang thoảng mùi giấy mới, Hoàng thượng đặt bút xuống, nhìn nét chữ nhạt như sương."},{"who":"A","text":"Mực trong ngự thư phòng dạo này nhạt quá, chữ trẫm viết lên giấy cứ như sương phủ. {Goi} có mắt tinh, chọn giúp trẫm một thỏi mực tốt."},{"who":"me","text":"Bẩm Hoàng thượng, mực tùng yên nên thử ở kho Nội vụ phủ, nơi còn giữ vết khói thơm trên đầu thỏi và sổ ghi rõ ràng."},{"who":"A","text":"Trẫm thích mực đậm, nhưng trên tường lại treo tranh thủy mặc nhạt. Đậm hợp chữ, nhạt hợp tranh, trẫm cũng khó nghĩ."},{"who":"me","text":"Việc nhỏ, {goi} cứ để {xung} sang kho thử từng thỏi rồi tâu lại."}]}},
{"id":"j72:j72c-court-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trà cống của sứ thần xứ xa được dâng vào ngự trà phòng, hộp còn nguyên tem niêm Nội vụ phủ."},{"who":"A","text":"Sứ thần xứ xa dâng trà, trẫm chưa dám uống. {Goi} nếm trước giúp trẫm, đừng nể nang."},{"who":"me","text":"Tem niêm còn nguyên, sổ cống phẩm cũng ghi đủ hộp. Để {xung} pha một chén thử xem sao."},{"who":"A","text":"Trà ấy ra sao, nói thật cho trẫm nghe. Trẫm cần một lời thẳng, không cần lời khéo."},{"who":"me","text":"Đầu lưỡi hơi đắng, nhưng hậu vị lại ngọt dịu. {Xung} đang nghĩ nên tâu thế nào cho vừa lòng {goi} và vừa với sự thật."}]}},
{"id":"j72:j72c-court-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm bão hôm trước, sổ ghi của quan Khởi cư bị nước thấm, mực loang thành từng vệt."},{"who":"A","text":"Đêm bão ấy sổ ghi của quan Khởi cư ướt hết, chữ mờ không đọc nổi. {Goi} ở cạnh trẫm đêm đó, chép lại giúp trẫm những gì còn nhớ."},{"who":"me","text":"Dạ, {xung} nhớ được nhiều chuyện. Quyển sổ ướt đang phơi ở Nội vụ phủ, chờ mực khô sẽ đối chiếu lời người trực đêm."},{"who":"A","text":"Cứ chép đúng như đã thấy. Trẫm chỉ cần sổ cho đủ, không cần thêm bớt."},{"who":"me","text":"Chỉ là có đôi điều trong đêm ấy, {xung} còn phân vân có nên ghi vào sổ hay không."}]}},
{"id":"j72:j72c-court-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng đứng lặng bên án thư, ánh mắt dừng lại ở chỗ trống nơi cuộn họa từng nằm."},{"who":"A","text":"Trẫm có một cuộn họa nhỏ vẽ mùa xuân ở vườn cũ, đã ba hôm không thấy đâu. {Goi} lanh lợi, tìm giúp trẫm, đừng làm ồn cung."},{"who":"me","text":"Họa ấy hẳn có dấu ấn riêng của {goi} ở góc tranh, nhờ đó mà dễ nhận ra. Thái giám ngự thư phòng sẽ là người đầu tiên {xung} hỏi."},{"who":"A","text":"Đó là bức họa trẫm giữ nhiều năm, nhìn nó trẫm nhớ mùa xuân còn chưa có gánh nặng."},{"who":"me","text":"Xin {goi} yên lòng, đã là vật có thật thì tất có nơi để tìm. {Xung} sẽ lần theo từng hòm {goi} từng cho đem sang vườn ngự."}]}},
{"id":"j72:j72c-court-005","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấu chương trải trên án thư, nét chữ thảo cuộn tròn như dây leo quấn nhau."},{"who":"A","text":"Có quan viết tấu bằng lối chữ thảo, trẫm nhìn như rồng bay phượng múa mà chẳng hiểu gì. {Goi} đọc thử xem lão muốn xin điều gì."},{"who":"me","text":"Nét bút quấn nhau thế này, phải đoán từng nét rồi đối chiếu chữ quen. Cuối bản có ký tên, từ đó có thể dò ngược lên."},{"who":"A","text":"Đọc cho kỹ, tấu chương không phải chuyện đùa."},{"who":"me","text":"Có một câu đọc được theo hai nghĩa khác nhau. {Xung} cần cân nhắc xem lão ấy xin điều gì mới đúng ý."}]}},
{"id":"j72:j72c-court-006","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng ngồi tựa ghế, sắc mặt nhợt nhạt sau mấy ngày triều chính nặng nề."},{"who":"A","text":"Trẫm ăn không ngon, thái y bảo ăn cháo loãng. Ngự thiện phòng nấu thì nhạt như nước. {Goi} nấu cho trẫm bát cháo {goi} vẫn nấu cho mình."},{"who":"me","text":"Chỉ là bát cháo gạo tẻ nấu ở bếp nhỏ cung {xung}, e không xứng với bàn ngự thiện của {goi}."},{"who":"A","text":"Xứng hay không, trẫm tự biết. Trẫm đang bực chuyện trong triều, chỉ muốn có thứ gì ấm bụng."},{"who":"me","text":"Vậy {goi} đợi một lát, {xung} canh lửa cho cháo nhừ rồi mang đến bằng bát sứ men trắng."}]}},
{"id":"j72:j72c-court-007","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ba ngày đều được ghi là ngày lành, nhưng bản tâu của Khâm thiên giám đặt trên án lại khiến ngài nhíu mày."},{"who":"A","text":"Quan Khâm thiên giám tâu cả ba ngày đều tốt, mà ngày nào trẫm cũng có việc. {Goi} xem giúp trẫm chọn ngày nào ít người than phiền nhất."},{"who":"me","text":"Cuộc săn thu là việc lớn, ngày nào cũng có người tiếc. {Xung} sẽ hỏi người quen ở Khâm thiên giám về tuần trăng trước đã."},{"who":"A","text":"Cứ hỏi cho kỹ. Trẫm không cần ngày hoàn hảo, chỉ cần ngày ít phiền lòng nhất."},{"who":"me","text":"Xin {goi} chờ {xung} một lát, rồi {xung} tâu rõ từng điều được mất."}]}},
{"id":"j72:j72c-court-008","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản danh sách quan văn võ trải kín án thư, mấy chỗ ngồi bị gạch đi gạch lại."},{"who":"A","text":"Yến tiệc sắp tới, quan văn không muốn ngồi cạnh quan võ, quan võ chê quan văn nói nhiều. {Goi} khéo tay, sắp chỗ giúp trẫm cho yên bề."},{"who":"me","text":"Muốn sắp chỗ cho êm, trước hết phải biết lòng từng bên. {Xung} sẽ dò ý qua người quen ở Lễ bộ."},{"who":"A","text":"Hai vị quan đầu triều vốn không nhìn mặt nhau, ngồi gần thì sinh chuyện, ngồi xa lại thành điều tiếng."},{"who":"me","text":"{Goi}, sơ đồ chỗ ngồi sẽ vẽ tay rồi gửi qua Lễ bộ, {goi} xem trước rồi hãy quyết."}]}},
{"id":"j72:j72c-court-009","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sinh nhật Thái hậu đang đến gần, trong kho Nội vụ phủ gấm vóc cuộn từng hộp xếp kín."},{"who":"A","text":"Sinh nhật mẫu hậu sắp đến, trẫm muốn dâng một cuộn gấm do chính tay {goi} chọn. Trẫm tin mắt nàng hơn mắt thợ dệt."},{"who":"me","text":"Hoàng thượng quá khen. Gấm ấy phải xem tận mắt từng cuộn ở kho Nội vụ phủ, rồi mới chờ thợ đóng hộp, thêu chữ chúc thọ."},{"who":"A","text":"Mẫu hậu ưa màu trầm, mà trẫm lại thích sắc tươi. Chọn sao cho hợp lòng bà, chẳng phụ lòng trẫm."},{"who":"me","text":"Một cuộn gấm chỉ vàng vừa trầm vừa sáng, có lẽ sẽ vẹn cả đôi đường. {Xung} xin đi xem trước."}]}},
{"id":"j72:j72c-court-010","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng đặt lên bàn một chiếc hộp sơn son, bên trong kẹp tấm thiệp ngài đích thân viết."},{"who":"A","text":"Quan Thượng thư cũ đã lui về nghỉ bệnh, trẫm không ra cung được. {Goi} thay trẫm mang chút quà, hỏi thăm lão."},{"who":"me","text":"Hộp sơn son kèm thiệp tay {goi}, lão nhìn là biết ý {goi}. {Xung} sẽ mang đến tận phủ."},{"who":"A","text":"Lão già ấy từng giúp trẫm nhiều việc. Nếu lão nói điều gì khó nói, {goi} nghe cho kỹ."},{"who":"me","text":"Dạ, nghe thì {xung} nghe, nhưng điều gì nên tâu hay không, {xung} sẽ tự cân nhắc."}]}},
{"id":"j72:j72c-court-011","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản nháp chiếu chỉ giấy vàng, mép đóng ấn nhỏ, niêm sáp còn mới."},{"who":"A","text":"Trẫm mới thảo xong một đạo chiếu mà chưa muốn ai biết. {Goi} giữ giúp trẫm đến ngày ban bố, đừng cho kẻ nào dòm ngó."},{"who":"me","text":"Giao việc trọng như vậy, {xung} sợ không xứng. Nhưng đã nhận, {xung} sẽ cất ở chỗ chỉ riêng mình biết."},{"who":"A","text":"Giữ kín đến hết mấy tuần, kẻ nào dò hỏi cũng đừng hé một lời."},{"who":"me","text":"Dạ, dù là quan lớn đến tận cửa cung, {xung} cũng một mực không để lộ."}]}},
{"id":"j72:j72c-court-012","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đội thị vệ mới lập đứng nghiêm trước cổng, mà trên cột cờ chưa có lấy một lá hiệu."},{"who":"A","text":"Đội thị vệ mới lập chưa có cờ hiệu. Võ quan đòi hình hổ, văn quan bảo hình hạc. {Goi} vẽ thử một lá để trẫm khỏi nghe cãi nhau."},{"who":"me","text":"Cờ hiệu thay mặt cả đội, phải vừa uy vừa nhã. {Xung} xin vẽ mẫu ở thư phòng, rồi nhờ thợ thêu ướm thử."},{"who":"A","text":"Hổ hay hạc, trẫm không ép, chỉ cần hai phía đều chịu."},{"who":"me","text":"Có khi không hổ cũng không hạc, mà là một hình đủ cho cả hai bên nhìn vào đều thấy mình."}]}},
{"id":"j72:j72c-court-013","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng dạo bước qua vườn ngự, dừng lại bên đình, nhìn mảng đất trống không một cánh hoa."},{"who":"A","text":"Vườn ngự năm nay vắng hoa, trẫm đi qua thấy buồn. {Goi} chọn giúp loại hoa nào hợp để trồng thêm."},{"who":"me","text":"Chỗ trống bên đình này đón nắng sớm, phải chọn hoa hợp đất rồi mới nói đến đẹp."},{"who":"A","text":"Trẫm muốn mùa sau nhìn vườn là thấy lòng nhẹ đi."},{"who":"me","text":"Ba loại hoa, ba vẻ riêng. {Xung} xin xem kỹ đất trước, rồi tâu {goi} chọn loại nào."}]}},
{"id":"j72:j72c-court-014","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm từ Đức Thọ cung thoảng sang, bữa chay hôm nay Hoàng thượng định dùng cùng Thái hậu."},{"who":"A","text":"Mẫu hậu ăn chay đã quen, trẫm ăn cùng một bữa cho tròn đạo hiếu. {Goi} nghĩ cho ngự thiện phòng vài món."},{"who":"me","text":"Bữa chay phải vừa miệng Thái hậu, lại không làm {goi} thấy nhạt. {Xung} xin hỏi người nấu chay ở Đức Thọ cung trước."},{"who":"A","text":"Trẫm không kén, chỉ mong mẫu hậu ăn ngon miệng."},{"who":"me","text":"Hoàng thượng hiếu thảo, bữa chay ấy tất sẽ ấm lòng cả hai người."}]}},
{"id":"j72:j72c-court-015","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở xưởng Nội vụ phủ, ba khúc gỗ nằm cạnh nhau, vân gỗ lấp lánh dưới nắng."},{"who":"A","text":"Ai gia muốn khắc một pho tượng nhỏ để thờ trong phòng riêng. Thợ đưa đến ba khúc gỗ, ai gia nhìn mà không chọn nổi. {Goi} giúp ai gia."},{"who":"me","text":"Khúc thơm thì nứt, khúc cứng thì thô, khúc mịn lại nhỏ. Mỗi khúc một vẻ, {xung} phải xem kỹ vân gỗ rồi mới dám nói."},{"who":"A","text":"Pho tượng ấy theo ai gia đến cuối đời, phải có duyên với người mới được."},{"who":"me","text":"Thái hậu cứ để {xung} xem từng khúc, nhãn của thợ mộc Nội vụ phủ cũng sẽ giúp {xung} biết gỗ nào đáng tin."}]}},
{"id":"j72:j72c-court-016","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm đã khuya, Thái hậu ngồi dựa gối, bàn chân đặt lên chiếc ghế nhỏ lót lụa."},{"who":"A","text":"Chân ai gia tối nào cũng nhức, thuốc của thái y dùng không thấm. {Goi} nghe nói biết nhiều bài thuốc dân gian, thử pha cho ai gia."},{"who":"me","text":"Thuốc dân gian hợp hay không còn tùy người. {Xung} xin hỏi thái y trước xem vị nào không xung khắc, rồi mới pha."},{"who":"A","text":"Ai gia già rồi, chỉ mong ngủ được một giấc yên."},{"who":"me","text":"Xin Thái hậu cứ yên tâm, lọ thuốc có gừng ấm, xoa vào sẽ nóng chân dịu cơn nhức."}]}},
{"id":"j72:j72c-court-017","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, tiếng đọc kinh của lão cung nữ run run, lệch từng chữ."},{"who":"A","text":"Cung nữ hầu ai gia đã lão, mắt kém, đọc kinh sai chữ hoài. {Goi} giúp ai gia sửa cho nó, đừng để nó xấu hổ."},{"who":"me","text":"Người già sợ nhất bị sửa trước mặt người khác. {Xung} sẽ ngồi đọc cùng bà ấy, chữ nào sai thì khẽ nhắc."},{"who":"A","text":"Nó theo ai gia mấy chục năm, ai gia không nỡ để nó khổ tâm."},{"who":"me","text":"Có lẽ bà ấy sẽ không nhận mình đọc sai, nhưng {xung} sẽ tìm cách để bà ấy tự thấy mà sửa."}]}},
{"id":"j72:j72c-court-018","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con đường từ Đức Thọ cung đến phật đường rợp bóng cây, lá rụng phủ kín lối."},{"who":"A","text":"Ai gia đánh rơi chiếc vòng ngọc nhỏ ở đâu đó trên đường đến phật đường. Người hầu tìm hoài không ra. {Goi} thử tìm giúp ai gia."},{"who":"me","text":"Vòng ấy có dấu gì riêng để {xung} nhận ra khi thấy?"},{"who":"A","text":"Ngọc xanh, có một vết sứt nhỏ gần khóa, sổ trang sức của Đức Thọ cung đều có ghi."},{"who":"me","text":"Vậy {xung} sẽ đi lại con đường ấy, hỏi cả cung nữ quét dọn gần đó. Nếu ai nhặt được, hẳn họ còn nhớ."}]}},
{"id":"j72:j72c-court-019","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thái hậu ngồi lặng bên cửa sổ, tay cầm cây bút mà không hạ xuống giấy."},{"who":"A","text":"Một vị cố nhân của ai gia vừa mất. Ai gia viết không nổi một câu. {Goi} chữ đẹp, viết giúp ai gia bài văn tế ngắn."},{"who":"me","text":"Thái hậu kể cho {xung} nghe về người ấy trước đã, để lời trong văn tế là lời của người, không phải của {xung}."},{"who":"A","text":"Người ấy hiền lành, chịu thiệt nhiều năm. Ai gia chỉ nhớ có một câu, mà ngại nói thành lời."},{"who":"me","text":"Câu nào Thái hậu ngại nói, {xung} sẽ viết sao cho vừa thương vừa không đau lòng."}]}},
{"id":"j72:j72c-court-020","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng kinh đều đều vọng ra từ phật đường, khay trà chờ sẵn bên cạnh."},{"who":"A","text":"Ai gia đang tụng kinh buổi chiều, hay khát. {Goi} chọn cho ai gia một loại trà không làm tỉnh ngủ cũng không làm lạc tâm."},{"who":"me","text":"Trà nhẹ quá thì vô vị, đậm quá thì động tâm. Ba loại trà ở trà phòng, {xung} xin thử từng chén rồi chọn."},{"who":"A","text":"Chọn cho kỹ, giọng tụng của ai gia nghe theo hơi trà đấy."},{"who":"me","text":"Dạ, {xung} sẽ chọn loại có hơi hương thanh, uống xong thấy lòng lặng lại."}]}},
{"id":"j72:j72c-court-021","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn Đức Thọ cung, sổ quà đáp lễ mở ra, từng dòng mực đỏ viền ngoài."},{"who":"A","text":"Các phu nhân trong triều gửi quà mừng, ai gia phải đáp lễ cho đều tay, không thiếu không thừa. {Goi} xem sổ quà giúp ai gia."},{"who":"me","text":"Dạ, {xung} đọc từng dòng, có chỗ nào chưa rõ sẽ nhờ nữ quan mang sổ cũ đối chiếu."},{"who":"A","text":"Có một phu nhân tặng nhiều, mà nhà lại không giàu. Đáp lễ nhẹ thì thất lễ, nặng lại làm người ta ngại."},{"who":"me","text":"Thái hậu nhân hậu, {xung} xin cân nhắc để món quà đáp vừa lòng, không ai thấy mình bị coi nhẹ."}]}},
{"id":"j72:j72c-court-022","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm ở Đức Thọ cung dài, đèn chỉ còn một ngọn, bóng Thái hậu đổ dài trên bức bình phong."},{"who":"A","text":"Đêm nay ai gia không ngủ được. Cung nữ nghe chuyện xưa của ai gia đã chán. {Goi} ở lại nghe ai gia kể, ai gia chỉ cần người nghe."},{"who":"me","text":"Thái hậu cứ kể, {xung} xin ngồi lại đến sáng."},{"who":"A","text":"Chuyện này ai gia chưa kể ai, nói ra rồi, không biết nên giấu hay nên nói tiếp. {Goi} nghĩ sao?"},{"who":"me","text":"Tâm sự đã chôn lâu, nói ra nhẹ lòng nhưng cũng có thể động đến người khác. {Xung} xin nói điều {xung} thật lòng nghĩ."}]}},
{"id":"j72:j72c-court-023","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp hương gỗ trầm đặt trên khay lụa, đáy khắc một hàng chữ nhỏ đã mờ."},{"who":"A","text":"Hộp hương này là quà thành hôn ai gia giữ hơn nửa đời. {Goi} giữ giúp ai gia vài hôm, ai gia đang dọn cung."},{"who":"me","text":"Vật quý như vậy, {xung} xin cất ở nơi khô ráo và kín đáo, không để ai đụng đến."},{"who":"A","text":"Nếu có người hỏi mượn xem thử, cứ nói là ai gia dặn không cho."},{"who":"me","text":"Dạ, {xung} nhớ rồi. Hộp hương ấy đến ngày Thái hậu cần, {xung} sẽ trao lại nguyên vẹn."}]}},
{"id":"j72:j72c-court-024","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, Thái hậu tựa gối nghe một cung nữ đọc truyện, giọng đều đều như tiếng chuông nhỏ."},{"who":"A","text":"Ai gia muốn nghe truyện buổi tối mà cung nữ đọc nhát gừng quá. {Goi} tìm giúp ai gia người đọc có giọng ấm."},{"who":"me","text":"{Xung} sẽ hỏi trong số cung nhân xem ai đọc có hồn. Có người đọc hay nhưng nhút nhát, người khác giọng ấm lại hay quên chữ."},{"who":"A","text":"Ai gia không cần hoàn hảo, chỉ cần nghe xong thấy lòng dịu lại."},{"who":"me","text":"Vậy {xung} sẽ chọn người có giọng ấm, rồi nhờ người còn lại đứng sau nhắc chữ."}]}},
{"id":"j72:j72c-court-025","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài chuồng ngựa, sợi dây cương mới còn vắt trên cọc, con ngựa chiến nằm im đã lạnh."},{"who":"A","text":"Con ngựa quý của lão phu chết vì mã phu lơ là, Hoàng thượng đã nghe tiếng. Lão phu không muốn mã phu bị đánh. {Goi} tâu giúp một lời."},{"who":"me","text":"Lão đại nhân nhân hậu. Nhưng nếu mã phu thật sự có lỗi, {xung} khó tâu thay."},{"who":"A","text":"Ngay cả lão cũng chưa rõ đêm đó ra sao. Sổ Thái bộc tự có ghi, {goi} hỏi người coi chuồng sẽ biết."},{"who":"me","text":"Vậy để {xung} hỏi cho rõ đầu đuôi, rồi mới biết nên tâu thế nào."}]}},
{"id":"j72:j72c-court-026","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhà quan bên sông, mảnh đất ven nước bị chiếm mất nửa, mà sổ địa bạ nằm cả ở Hộ bộ."},{"who":"A","text":"Mảnh đất bên sông nhà lão phu bị người ta chiếm nửa phần, Hộ bộ giữ sổ địa bạ không chịu trả lời. {Goi} thường qua lại, hỏi dò giúp lão."},{"who":"me","text":"Sổ địa bạ ghi tên chủ đất bằng mực tàu, có dấu đỏ Hộ bộ. {Xung} sẽ nhờ người quen hỏi dò."},{"who":"A","text":"Nghe nói một chức nhỏ ở đó muốn lời lót tay. Lão thanh liêm, không có gì ngoài đất ấy."},{"who":"me","text":"Lão đại nhân yên tâm, việc chính đáng không nhất thiết phải qua đường tối. {Xung} sẽ tìm đường chính."}]}},
{"id":"j72:j72c-court-027","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sảnh nhà quan treo lụa đỏ, chỗ giữa còn để trống một khoảng chờ bức hoành phi."},{"who":"A","text":"Nhà lão phu làm lễ mừng thọ, khách đều là người có tiếng. Lão phu muốn nhờ {goi} nghĩ giúp một câu chúc không sáo mà không phạm húy."},{"who":"me","text":"Câu chúc hay phải vừa lòng người nghe lại không phạm điều kiêng. {Xung} xin nghĩ vài câu, viết thử trên giấy."},{"who":"A","text":"Chữ vàng nền đỏ, treo giữa sảnh. Lão chỉ sợ câu quá lạ thì khách không hiểu, quá quen lại nhạt."},{"who":"me","text":"Một câu hay nhưng lạ, một câu quen nhưng ấm. {Xung} sẽ chọn câu nào đọc lên mà ai cũng thấy lòng nở."}]}},
{"id":"j72:j72c-court-028","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phủ quan, tờ giấy chia gia sản nằm giữa hai chiếc ghế quay lưng vào nhau."},{"who":"A","text":"Hai đứa con trai lão phu cãi nhau chuyện chia tài sản, một đứa đã mách tới tai Hoàng thượng. Lão phu nhờ {goi} khéo miệng, nói giúp cho êm."},{"who":"me","text":"Việc nhà mà ra đến tai ngự, e cần gỡ khéo mới khỏi mất tình huynh đệ."},{"who":"A","text":"Nghe bảo cả hai đều nói bên kia sai. Lão không còn nhiều năm, chỉ mong tờ giấy này có đủ chữ ký trước khi lão nhắm mắt."},{"who":"me","text":"{Xung} sẽ nói riêng với từng người một trước, rồi mới nói đến chuyện chung."}]}},
{"id":"j72:j72c-court-029","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùa thi gần đến, nhà quan còn vương khói hương tang, chiếc áo cũ của chàng sĩ tử đã sờn cổ."},{"who":"A","text":"Con trai lão phu sắp vào trường thi, áo cũ rách mà nhà mới có tang. {Goi} tay khéo, may giúp nó một chiếc áo xanh."},{"who":"me","text":"Vải bông xanh, đường chỉ đều, thêu một chữ nhỏ ở cổ cho chàng nhớ mà giữ lòng. {Xung} xin lấy số đo trước."},{"who":"A","text":"Lão không dám nhờ nhiều, chỉ mong áo kịp ngày thi. Cổ áo kiểu nào cũng được, miễn là kín đáo."},{"who":"me","text":"Cổ áo mỗi kiểu một ý, {xung} sẽ chọn kiểu hợp với chàng và hợp cả với tang trong nhà."}]}},
{"id":"j72:j72c-court-030","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lá thư niêm sáp còn ấm hơi tay người, dấu nhẫn riêng ép giữa chỗ khóa."},{"who":"A","text":"Lá thư này lão phu không dám giao cho gia nhân. {Goi} tiện đường ra phủ, trao tận tay quan phủ giúp lão phu."},{"who":"me","text":"Thư niêm sáp có dấu nhẫn riêng, {xung} nhận là chỉ trao tận tay, không để ai chạm vào."},{"who":"A","text":"Nếu giữa đường có kẻ lạ hỏi thư gửi ai, đừng hé một lời. Giấy mỏng, dễ bị mở lắm."},{"who":"me","text":"Lão đại nhân yên tâm, {xung} đi đường chính, giữ thư cẩn thận."}]}},
{"id":"j72:j72c-court-031","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhà quan vừa có cháu đích tôn, tiếng trẻ khóc vọng ra từ nội đường, cả nhà tranh nhau đặt tên."},{"who":"A","text":"Nhà lão phu vừa có cháu đích tôn, mà người nhà mỗi người một ý đặt tên. {Goi} có chữ, nghĩ giúp lão một cái tên vừa đẹp vừa không trùng húy."},{"who":"me","text":"Tên đặt cho trẻ là điều theo suốt đời. {Xung} xin tra sách ở thư phòng, chọn chữ nào vừa nghĩa vừa vần."},{"who":"A","text":"Cả họ chỉ chịu khi tên có vần hay. Lão cũng không muốn trái ý con cháu."},{"who":"me","text":"Nếu vần êm tai mà nghĩa lại sâu, {xung} tin cả nhà sẽ đồng lòng."}]}},
{"id":"j72:j72c-court-032","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bảng kê bạc lương trải trước mặt lão quan, con dấu Nội vụ phủ đóng lệch, hai khoản trừ lặp lại."},{"who":"A","text":"Bạc lương của nhà lão phu mấy tháng bị trừ vì một chuyện hiểu lầm. Lão phu thanh liêm, không có gì ngoài lương. {Goi} nói giúp một lời với Nội vụ phủ."},{"who":"me","text":"Dấu đóng lệch, hai khoản trừ lặp, rõ ràng là sai sót. {Xung} sẽ đến hỏi người giữ sổ."},{"who":"A","text":"Nghe bảo họ đòi người bảo lãnh. Lão già này nào có ai để nhờ."},{"who":"me","text":"Đã là lẽ phải thì không cần cầu xin. {Xung} sẽ tìm người đứng ra bảo lãnh cho lão."}]}},
{"id":"j72:j72c-court-033","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhà quan nhỏ, bếp quen món dân dã, thế mà sắp phải đón vị khách quý nhất triều."},{"who":"A","text":"Nhà lão phu mời Hoàng thượng đến dự tiệc nhà nhỏ, mà bếp nhà chỉ quen món dân dã. {Goi} giúp lão nghĩ vài món hợp cả hai bên."},{"who":"me","text":"Món dân dã mà nấu tinh, có khi lại hợp lòng {goi} hơn món cầu kỳ. {Xung} sẽ hỏi quan thiện về các món {goi} thường dùng."},{"who":"A","text":"Lão chỉ sợ ngài thấy nhà lão keo kiệt, mà khoe quá lại thành phô trương."},{"who":"me","text":"Một món ấm, một món lạ miệng, thêm một món thể hiện tấm lòng nhà quan. {Xung} sẽ lo."}]}},
{"id":"j72:j72c-court-034","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lão quan nằm trên giường bệnh, tay run run nắm cây bút, ba người chứng đã ngồi quanh."},{"who":"A","text":"Lão phu bệnh lâu, muốn viết di chúc trước mặt người ngoài tin cậy. {Goi} đến làm chứng cho lão."},{"who":"me","text":"Việc hệ trọng như vậy, {xung} xin đến phủ nghe lão đọc ý nguyện, rồi mới ký tên làm chứng."},{"who":"A","text":"Lão muốn để phần lớn cho một người con, người kia thì ít hơn. Lão nghĩ kỹ rồi, nhưng vẫn thấy nặng lòng."},{"who":"me","text":"Chứng thì {xung} chứng, nhưng {xung} chỉ chứng cho những gì lão tự nguyện nói, không chứng cho điều lão còn ngần ngại."}]}},
{"id":"j72:j72c-court-035","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng Hàn lâm, sách cũ xếp kín giá, bìa lụa sờn mà mùi giấy vẫn thơm."},{"who":"A","text":"Lão phu nuôi một đứa học trò nghèo, nó sắp xuống tỉnh thi. {Goi} chọn giúp một cuốn sách hợp để lão tặng."},{"who":"me","text":"Một cuốn dễ đọc, một cuốn sâu sắc, một cuốn nhỏ gọn mang theo. {Xung} xin xem từng cuốn ở thư phòng Hàn lâm."},{"who":"A","text":"Nó đi đường xa, hành trang ít, nhưng lão muốn nó mang theo một cuốn đáng đọc."},{"who":"me","text":"Cuốn nào có ghi chú tay của người xưa ở lề sẽ quý hơn nhiều, {xung} sẽ tìm cuốn ấy."}]}},
{"id":"j72:j72c-court-036","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở sảnh sứ quán, hòm quà đáp lễ xếp thành hàng, mà hòm nào cũng nặng đến hai người mới khiêng nổi."},{"who":"A","text":"Sứ đoàn sắp về nước, Hoàng thượng ban quà đáp lễ, nhưng người coi kho chọn toàn món nặng trĩu. {Goi} giúp chúng thần chọn món vừa hợp vừa nhẹ."},{"who":"me","text":"Sứ thần cứ yên tâm, {xung} sẽ xem sổ quà ở Lễ bộ trước, mỗi món đều có ghi rõ."},{"who":"A","text":"Có món rất đẹp mà nặng, có món nhẹ mà thường thường. Chúng thần không biết nên tiếc bên nào."},{"who":"me","text":"Quà đáp lễ quý ở tấm lòng. {Xung} sẽ chọn món nhẹ mà người nhận nhìn là nhớ mãi."}]}},
{"id":"j72:j72c-court-037","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở ngự hoa viên, sứ thần nhìn quanh một vòng, rồi hạ giọng thật thấp."},{"who":"A","text":"Có lời thần không dám nói trước triều, chỉ dám nhờ {goi} thưa riêng với Hoàng thượng khi ngài rảnh. Xin {goi} giữ kín nguồn tin."},{"who":"me","text":"Lời ấy không giấy bút, chỉ có tai nghe và lòng nhớ. Xin sứ thần nói rõ từng chữ, kẻo {xung} truyền sai."},{"who":"A","text":"Nghe qua thì như hăm dọa, nhưng thật ra là lời cầu hòa. Chỉ sợ ngài hiểu lầm."},{"who":"me","text":"{Xung} sẽ chờ lúc Hoàng thượng thanh nhàn mà thưa, đúng như lòng sứ thần."}]}},
{"id":"j72:j72c-court-038","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sảnh đợi vắng người, chỉ có đoàn sứ thần đứng nép gần nhau, vạt áo xứ lạ còn bám bụi đường xa."},{"who":"A","text":"Chúng thần ở xa tới, lễ cung đình chưa thuộc, sợ thất lễ trước Thái hậu. {Goi} chỉ giúp vài điều tối kỵ."},{"who":"me","text":"Lễ cung có nhiều điều nhỏ mà trọng. {Xung} xin nói cho sứ thần biết điều gì nên làm, điều gì nên tránh."},{"who":"A","text":"Có vài lễ nghi nếu nói thẳng chúng thần sợ xấu hổ. Xin {goi} khéo lời cho."},{"who":"me","text":"Sứ thần cứ yên tâm, {xung} sẽ chỉ bằng cách nói nhẹ nhàng nhất."}]}},
{"id":"j72:j72c-court-039","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong đình giữa vườn, khung gỗ căng giấy lụa đã dựng sẵn, nét mực nhạt chờ bóng người."},{"who":"A","text":"Tại hạ đang vẽ bức Xuân Cung theo ý Hoàng thượng, còn thiếu một người ngồi trong đình để phác bóng dáng. {Goi} có phong thái, xin giúp tại hạ nửa buổi."},{"who":"me","text":"Họa sư cần {xung} ngồi thế nào cho đúng?"},{"who":"A","text":"Ngồi yên là được, nhưng phải ngồi lâu. Tay tê chân mỏi, xin {goi} cố chịu một chút."},{"who":"me","text":"Vì bức Xuân Cung {goi} ấy để tâm, {xung} nguyện ngồi cho tới khi họa sư phác xong."}]}},
{"id":"j72:j72c-court-040","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc quạt trúc còn trắng xương, bên cạnh là hai mảnh giấy tô thử, một hồng nhạt và một xanh nhạt."},{"who":"A","text":"Tại hạ sắp vẽ quạt dâng Thái hậu mà nghĩ mãi không ra màu nền. {Goi} nhìn hộ xem hồng hay xanh hợp bà hơn."},{"who":"me","text":"Hồng nhạt thơm dịu, xanh nhạt mát mắt. Họa sư cho {xung} xem hai mẫu dưới nắng thì mới phân được."},{"who":"A","text":"Quạt này dâng làm quà thọ, màu phải vừa trang nhã vừa gần gũi."},{"who":"me","text":"Để {xung} nghĩ tới tính tình Thái hậu rồi mới chọn, họa sư đừng vội vẽ."}]}},
{"id":"j72:j72c-court-041","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhạc phường yên ắng, chỉ còn tiếng dây đàn rung nhẹ và tờ phổ gạch xóa vài chỗ."},{"who":"A","text":"Tại hạ vừa phổ một khúc dâng ngày yến Trung thu, nhưng tay đàn mỏi, tai nghe quen rồi. {Goi} nghe thử một hồi, nói tại hạ nghe chỗ nào lạ."},{"who":"me","text":"Nhạc sư cứ gảy đi, {xung} xin nghe trọn cả khúc rồi mới nói."},{"who":"A","text":"Đoạn đầu nghe buồn, đoạn sau lại vui. Tiệc Trung thu vốn cần vui, mà tại hạ không nỡ bỏ đoạn buồn."},{"who":"me","text":"Buồn một chút rồi vui lên cũng là cách làm cho niềm vui thêm đằm. {Xung} sẽ nói rõ chỗ nào nên giữ."}]}},
{"id":"j72:j72c-court-042","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhạc phường căng thẳng từ hôm xảy ra chuyện sai nhịp, người gảy đàn quay mặt đi mỗi khi gặp người thổi sáo."},{"who":"A","text":"Tên thổi sáo nói tại hạ gảy sai nhịp trước cả đội. Tại hạ không muốn nhìn mặt hắn. {Goi} khéo ăn khéo nói, xin xoa dịu giúp tại hạ."},{"who":"me","text":"Việc giữa nghề với nghề mà ra trước mặt cả đội, ắt nhạc sư mất mặt. {Xung} sẽ gặp riêng người thổi sáo trước."},{"who":"A","text":"Hắn bảo chỉ là góp ý. Tại hạ không tin lời hắn."},{"who":"me","text":"Nhạc sư đừng vội giận, có khi một khúc gảy chung sẽ nói hộ lòng cả hai người."}]}},
{"id":"j72:j72c-court-043","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ở Thái y viện, thái y đóng cửa lại thật kỹ rồi mới ngồi xuống."},{"who":"A","text":"Thần vừa chẩn ra một chứng bệnh mà người bệnh chưa muốn ai biết. Thần không dám nói với ai khác. {Goi} biết giữ kín, xin nghe thần thổ lộ."},{"who":"me","text":"Chuyện thầy thuốc giấu mà đem nói với {xung}, hẳn là rất nặng lòng. Thái y cứ nói, {xung} chỉ nghe."},{"who":"A","text":"Tờ phương thuốc này chữ thảo, chỉ thần đọc được. Thần phân vân có nên báo cho người bệnh hay không."},{"who":"me","text":"Xin để {xung} nghĩ thêm. Điều nên nói cũng cần nói lúc, nói cách nào cho người ấy không đổ gục."}]}},
{"id":"j72:j72c-court-044","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho thuốc ở Thái y viện còn thiếu một ngăn, thái y vừa đứng trước đó vừa thở dài."},{"who":"A","text":"Kho thuốc thiếu một vị quý, thần nghe nói trong vườn ngự mọc dại. {Goi} đi dạo, nhìn giúp thần."},{"who":"me","text":"Vị thuốc ấy trông ra sao để {xung} nhận ra?"},{"who":"A","text":"Lá xanh bóng, mùi hăng, mọc dưới gốc cây trong vườn ngự. Có hai bụi, một bụi gần lối đi, một bụi sâu trong bụi rậm."},{"who":"me","text":"Vậy {xung} sẽ theo lời thái y tả, tìm cho kỹ, tránh hái nhầm lá khác."}]}},
{"id":"j72:j72c-court-045","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hậu đặt sổ chi tiêu cuối tháng lên bàn, bìa xanh dấu đỏ, vài trang mực khác màu."},{"who":"A","text":"Sổ chi tiêu cuối tháng của cung cấm có mấy khoản {xung} đọc không hiểu. {Goi} tinh tường, đọc lại giúp {xung}."},{"who":"me","text":"{Xung} xin ngồi đối chiếu từng khoản với sổ cũ, chờ Nội vụ phủ mang thêm chứng từ nữa."},{"who":"A","text":"Có khoản nhìn như của một phi tần quyền thế. {Xung} không muốn nói ra khi chưa rõ."},{"who":"me","text":"Dạ, {xung} sẽ chỉ nói điều có chứng, không dám đoán bừa."}]}},
{"id":"j72:j72c-court-046","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vườn ngự vào mùa hoa, Hoàng hậu đi giữa luống hoa, dừng lại hồi lâu trước mỗi bông."},{"who":"A","text":"{Xung} sắp mở yến cho các phi tần, hoa cài đầu mỗi người phải khác nhau mà không đua đòi. {Goi} chọn giúp {xung} mẫu."},{"who":"me","text":"Hoa đẹp có hạn, ai cũng muốn bông đẹp nhất. {Xung} sẽ xem từng loại ở vườn ngự rồi chọn."},{"who":"A","text":"{Xung} không muốn có ai dỗi vì hoa. Chọn cho khéo, đừng để thành chuyện lớn."},{"who":"me","text":"Mỗi người một hoa hợp sắc mặt của mình, thì tự nhiên chẳng ai thấy mình bị bỏ sót."}]}},
{"id":"j72:j72c-court-047","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung Hoàng hậu, giấy hồng điều trải ra, ấn son còn đặt bên cạnh chưa đóng."},{"who":"A","text":"Mẫu thân {xung} bệnh, {xung} không ra cung được, thư gửi về chữ run run. {Goi} chép lời {xung} vào thư, đừng sai ý."},{"who":"me","text":"{Xung} xin nghe Hoàng hậu nói hết lời muốn gửi, rồi mới chép thành thư."},{"who":"A","text":"{Xung} muốn giấu chuyện mình đang lo, mà vẫn muốn mẹ hiểu lòng con."},{"who":"me","text":"Dạ, {xung} sẽ chép sao cho thư vừa nhẹ lòng bà cụ vừa không mất tình mẫu tử."}]}},
{"id":"j72:j72c-court-048","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước mặt Hoàng hậu, hai cung nữ quỳ hai phía, giữa họ là chiếc trâm đồng đã mòn."},{"who":"A","text":"Hai cung nữ của {xung} tranh nhau một chiếc trâm, mỗi người nói trâm là của riêng nàng. {Goi} nghe cả hai, xử giúp {xung} cho công bằng."},{"who":"me","text":"Trâm có khắc chữ nhỏ ở mặt trong, {xung} xin xem trước. Rồi hỏi riêng từng người, không để người này nghe lời người kia."},{"who":"A","text":"{Xung} ngờ cả hai đều nói thật một phần. Chỉ sợ xử oan người này mà lòng người kia vẫn không yên."},{"who":"me","text":"Xin Hoàng hậu yên tâm, {xung} sẽ xử theo chứng cứ chứ không theo thiên vị."}]}},
{"id":"j72:j72c-court-049","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quyển sách thuốc cổ nằm giữa bàn Thái y viện, gáy bong, nhiều trang chữ phai loang."},{"who":"A","text":"Quyển sách thuốc cổ của Thái y viện gáy bong, chữ phai. {Goi} chữ đẹp, chép lại giúp thần vài chương."},{"who":"me","text":"Chương nào phai nhiều nhất, thái y cho {xung} chép trước."},{"who":"A","text":"Có một chương mất hẳn chữ ở vị thuốc, thần không dám đoán bừa. {Goi} chép đến đó thì dừng lại hỏi thần."},{"who":"me","text":"Dạ, chữ nào không rõ {xung} không dám chép liều."}]}},
{"id":"j72:j72c-court-050","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn Thái y viện, chén sứ nhỏ đựng nước thuốc đậm đen, mùi hắc nồng lên."},{"who":"A","text":"Thần pha ra bài thuốc mới nhưng đắng quá, cung nữ nào cũng không chịu uống. {Goi} nếm thử, nói thần nghe nên thêm vị gì cho dịu."},{"who":"me","text":"Để {xung} nếm một ngụm. Quả là đắng gắt, nhưng hậu vị không xấu."},{"who":"A","text":"Thêm mật cho dịu, hay thêm cam thảo, hoặc hoa cúc, thần còn lưỡng lự."},{"who":"me","text":"Mật dịu nhưng ngọt gắt, cam thảo ấm mà hợp hơn. {Xung} xin thử từng thứ rồi tâu thái y."}]}},
{"id":"j72:j72c-court-051","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang bên cung vắng người, tổng quản thái giám nhìn quanh rồi mới dám hạ giọng."},{"who":"A","text":"{Goi}, nô tài có việc ngại mở lời. Mấy thái giám nhỏ trong cung ngày nào cũng lén uống rượu. {Goi} nhắc khéo giúp nô tài, nô tài nói thì họ không nghe."},{"who":"me","text":"Rượu là chuyện cấm trong cung, lỡ bị phát hiện thì chẳng ai giữ nổi. {Xung} sẽ gặp họ ở hành lang."},{"who":"A","text":"Họ bảo chỉ uống chút giải sầu. Nô tài không nỡ phạt, mà cũng không dám buông."},{"who":"me","text":"{Goi} cứ yên tâm, {xung} sẽ nói sao cho họ hiểu mà không thấy mình bị răn."}]}},
{"id":"j72:j72c-court-052","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, tổng quản thái giám đứng nép sau cột hành lang, giọng nghẹn lại."},{"who":"A","text":"{Goi}, nô tài có người đệ trong cung vừa mất mẹ ở quê. Nô tài không dám lên tiếng với quản sự. {Goi} nhân từ, xin cho nó nghỉ vài hôm."},{"who":"me","text":"Mất mẹ là nỗi đau lớn nhất, sao có thể không cho về chịu tang? Ta sẽ gặp quản sự của hắn."},{"who":"A","text":"Quản sự bảo cung đang thiếu người, e khó gật đầu. Nô tài chỉ mong {goi} nói một lời."},{"who":"me","text":"Ngươi đừng lo, ta sẽ nói sao cho quản sự thấy việc ấy là đạo hiếu, không phải đòi hỏi."}]}},
{"id":"j72:j72c-court-053","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho lúa vơi, ngoài cổng thành người đói đứng xếp hàng dài từ sáng sớm."},{"who":"A","text":"Kho lúa cạn mà dân đói, lão phu chỉ có sức già, quyên được ít. {Goi} nói với các phi tần cùng góp một phần, lão cảm kích."},{"who":"me","text":"Chẩn tế là việc thiện, {xung} xin nói với các phi tần. Mỗi người góp một ít cũng thành nhiều."},{"who":"A","text":"Bao lúa buộc dây đỏ, sổ kho ghi tên người quyên. Mỗi người góp ít nhiều khác nhau, lão không dám đòi hỏi."},{"who":"me","text":"Lão đại nhân yên tâm, tấm lòng không đo bằng ít nhiều, {xung} sẽ khéo nói cho ai cũng thấy mình có phần."}]}},
{"id":"j72:j72c-court-054","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Biên ải lạnh giá, đoàn lương thảo sắp lên đường, trên xe còn chỗ trống cho những túi nhỏ."},{"who":"A","text":"Biên ải lạnh, binh sĩ ốm đau mà thuốc thiếu. {Goi} cùng các phi tần may túi thuốc nhỏ, lão phu gửi theo đoàn lương thảo."},{"who":"me","text":"Vải bông xanh, chỉ đen, nhồi cỏ thuốc khô. {Xung} sẽ cùng cung nữ cắt vải, may từng túi."},{"who":"A","text":"Có hai cách đóng gói, một cách nhanh, một cách kỹ. Đoàn đi gấp, lão sợ không kịp."},{"who":"me","text":"Lão đại nhân đừng lo, túi nào đến tay binh sĩ cũng phải đủ thuốc, {xung} sẽ cân nhắc cách nào hợp hơn."}]}},
{"id":"j72:j72c-court-055","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tết cận kề, cổng cung treo lụa đỏ mà đôi câu đối cũ vẫn dán nguyên từ năm ngoái."},{"who":"A","text":"Tết đến, câu đối cổng cung năm nào cũng giống năm nào. {Goi} nghĩ cho trẫm một đôi mới, vừa ý vừa không phạm húy."},{"who":"me","text":"Một vế nói thịnh vượng, một vế nói bình an. {Xung} xin nghĩ ở thư phòng, viết thử trên giấy đỏ."},{"who":"A","text":"Trẫm muốn câu đối mới nhưng không lạ lẫm, đọc lên cả cung đều thấy ấm."},{"who":"me","text":"{Goi}, vế đối cần chỉnh cho đối nhau từng chữ, {xung} sẽ cẩn thận."}]}},
{"id":"j72:j72c-court-056","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hôm dọn tủ ở Đức Thọ cung, Thái hậu lục hết ngăn này đến ngăn khác mà chiếc khăn vẫn không thấy."},{"who":"A","text":"Ai gia có chiếc khăn thêu hoa sen, đã cũ nhưng ai gia quý. Hôm dọn tủ không thấy. {Goi} tìm giúp ai gia, đừng nói với người hầu."},{"who":"me","text":"Khăn ấy có dấu gì để {xung} nhận ra?"},{"who":"A","text":"Chỉ thêu bạc màu, góc có chữ cái đầu tên ai gia. Đừng làm ồn, kẻo người ta cười ai gia già còn tiếc đồ cũ."},{"who":"me","text":"Thái hậu yên tâm, {xung} chỉ lặng lẽ tìm trong tủ và rương ở Đức Thọ cung."}]}},
{"id":"j72:j72c-court-057","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng thượng triều về, áo chưa kịp thay đã cho bày bàn cờ ngay trong thư phòng."},{"who":"A","text":"Hôm nay thượng triều nghe than phiền suốt buổi. {Goi} đánh với trẫm một cuộc cờ, nhưng đừng nhường, trẫm ghét kẻ nhường."},{"who":"me","text":"Đã lệnh không nhường thì {xung} xin đánh hết sức."},{"who":"A","text":"Phải thế. Trẫm cần một cuộc cờ thật, không cần lời nịnh."},{"who":"me","text":"Thế cờ đang nghiêng về {xung}, mà {goi} lại có vẻ rất muốn thắng. {Xung} đang nghĩ nên đi nước nào."}]}},
{"id":"j72:j72c-court-058","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng thượng đứng bên cửa sổ, tay cầm một tấm thiệp trắng chưa viết chữ nào."},{"who":"A","text":"Có một người xưa, giờ ở xa, hôm nay sinh nhật. Trẫm không tiện ra mặt. {Goi} chọn một món nhỏ gửi thay trẫm, đừng ghi tên."},{"who":"me","text":"Gói quà không tên, không dấu ấn, chỉ buộc nơ xanh trên lụa trắng. {Xung} nhận lời."},{"who":"A","text":"Món quà có ý nghĩa quá thì dễ bị đoán ra, mà lắt léo quá thì người nhận lại ngờ."},{"who":"me","text":"{Goi}, {xung} sẽ chọn ở Nội vụ phủ một món nhỏ, giản dị mà ấm."}]}},
{"id":"j72:j72c-court-059","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho lúa cạn, trên án thư ngự thư phòng bản chiếu nháp mực còn ướt, vài chữ bị gạch đi viết lại."},{"who":"A","text":"Kho lúa cạn, trẫm muốn cắt bớt yến tiệc trong cung mà không để người ta nói trẫm keo kiệt. {Goi} giúp trẫm soạn lời chiếu cho khéo."},{"who":"me","text":"Lời chiếu phải nói rõ vì dân mà bớt, không phải vì {goi} tiếc của. {Xung} xin soạn ở thư phòng."},{"who":"A","text":"Giọng chiếu nên nghiêm hay nên mềm, trẫm còn phân vân."},{"who":"me","text":"Có thể nghiêm trong lý lẽ, mềm trong tình ý. {Xung} xin viết thử hai bản để {goi} chọn."}]}},
{"id":"j72:j72c-court-060","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ thiếp dạm hỏi giấy đỏ buộc chỉ nằm trên bàn, chữ đã viết xong mà vẫn chưa gửi."},{"who":"A","text":"Nhà lão phu muốn dạm hỏi con gái nhà {B}, mà nghe nói họ chưa thuận. {Goi} quen hai bên, dò giúp lão phu một câu."},{"who":"me","text":"Chuyện hôn sự là chuyện hai nhà, {xung} xin nhờ người quen nhà kia dò ý trước, không dám hỏi thẳng."},{"who":"A","text":"Nghe nói nhà kia chưa thuận vì lý do riêng, lão cũng không rõ là vì đâu."},{"who":"me","text":"Lão đại nhân đừng vội, hiểu ra lý do rồi hãy gửi thiếp thì sẽ êm hơn."}]}},
{"id":"j72:j72c-court-061","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc hộp gỗ nhỏ chia nhiều ngăn, mỗi ngăn một vị thuốc khô, nhãn do thái y viết tay."},{"who":"A","text":"Mẹ lão phu tuổi cao, thái y nói cần thuốc bổ mà lão phu không rành. {Goi} chọn giúp lão phu vài vị lành."},{"who":"me","text":"Người già dùng thuốc phải nhẹ nhàng. {Xung} xin hỏi Thái y viện những vị hợp với người cao tuổi."},{"who":"A","text":"Một vị bổ khí, một vị bổ huyết, một vị an thần. Lão sợ chọn sai thì hại bà cụ."},{"who":"me","text":"Lão đại nhân yên tâm, {xung} sẽ chọn vị lành nhất, hợp với thể trạng bà cụ."}]}},
{"id":"j72:j72c-court-062","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày lên chùa, Thái hậu đưa tay chạm vào chiếc lá xanh thẫm, nụ lan đã sắp nở."},{"who":"A","text":"Ai gia sắp đến chùa ba hôm, chậu lan này kén chăm, cung nữ nào chăm cũng héo. {Goi} chăm hộ ai gia, đừng để nó chết."},{"who":"me","text":"Lan kén nước, kén gió. {Xung} xin mang về cung, đặt chỗ mát, tưới đều từng ngày."},{"who":"A","text":"Thợ vườn có ghi tên giống, {goi} cứ theo đó mà chăm. Ai gia chỉ muốn lúc về còn thấy hoa nở."},{"who":"me","text":"Thái hậu yên tâm, {xung} xin giữ lan như giữ lòng mình."}]}},
{"id":"j72:j72c-court-063","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm tĩnh, trong hành lang cung Hoàng hậu thoang thoảng tiếng quân bài va vào nhau khe khẽ."},{"who":"A","text":"{Xung} nghe cung nữ trong cung tụ tập đánh bài ban đêm. {Xung} không muốn truy mạnh tay. {Goi} nhắc khéo, đừng để thành chuyện lớn."},{"who":"me","text":"Cung nữ đầu nhóm là người biết nói khéo, {xung} xin gặp riêng nàng ở hành lang vắng."},{"who":"A","text":"Phải khéo, đừng để các nàng sợ mà cũng đừng để các nàng nhờn."},{"who":"me","text":"Dạ, {xung} sẽ nói sao cho họ hiểu mà tự thôi."}]}},
{"id":"j72:j72c-fam-001","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều xuống, {M} bưng vào một phong thư có nét chữ quen, giấy còn thoảng mùi nhà cũ."},{"who":"M","text":"{Goi}, thư mẫu thân gửi từ quê vào. Người dặn phải trao tận tay."},{"who":"me","text":"Mẫu thân viết gì, ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ già vụng tay, mấy cô hàng xóm đòi xem mẫu thêu trong cung. Con vẽ một mẫu gửi về, để mẹ nở mày nở mặt với họ.»"},{"who":"me","text":"Ta vẽ một mẫu hoa sen nhà ta vẫn thêu, nét mảnh thôi. Nhưng đừng cầu kỳ quá, mẹ không thêu nổi."},{"who":"M","text":"Dạ, {goi} cứ vẽ ở thư phòng, nô tỳ sẽ đưa mẫu ra khỏi cung giúp."}]}},
{"id":"j72:j72c-fam-002","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} lặng lẽ bước vào, tay cầm phong thư có nét chữ vững của huynh trưởng."},{"who":"M","text":"{Goi}, thư huynh trưởng bên nhà vừa tới, người gửi qua đường dịch trạm."},{"who":"me","text":"Huynh ấy ít khi viết thư. Có chuyện gì sao?"},{"who":"M","text":"Ngài viết: «Huynh sắp dạy cháu nhỏ mà trong nhà không có thầy giỏi. Ở cung có biết ai tử tế thì tiến cử một người cho huynh.»"},{"who":"me","text":"Hàn lâm viện có nhiều người quen. Có người giỏi mà nghiêm khắc, có người hiền mà dạy chậm. Ta phải nghĩ kỹ hợp với cháu nhỏ nhà ta."}]}},
{"id":"j72:j72c-fam-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Buổi chiều lặng, {M} mang đến một phong thư viết bằng nét chữ non nớt của người em gái."},{"who":"M","text":"{Goi}, thư em gái bên nhà gửi vào. Cô ấy sắp thành thân rồi."},{"who":"me","text":"Muội ấy đã đến tuổi gả sao? Ngươi đọc ta nghe."},{"who":"M","text":"Cô ấy viết: «Muội sắp thành thân, tủ chưa có món trang sức đẹp nào. Gửi cho muội một cây trâm, để muội đỡ tủi.»"},{"who":"me","text":"Trâm tốt nhất ta cũng quý, trâm kém lại sợ mất mặt nhà. Ngươi mở rương trang sức của ta, để ta chọn."}]}},
{"id":"j72:j72c-fam-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tin nhà đến vào lúc trời chạng vạng, {M} đứng bên cửa, nét mặt lo lắng."},{"who":"M","text":"{Goi}, thư phụ thân vừa đến. Nô tỳ thấy nét chữ run, không giống mọi lần."},{"who":"me","text":"Đọc đi, ta nghe."},{"who":"M","text":"Người viết: «Con gái, bệnh cũ của cha lại tái, thuốc thầy lang quê không còn hợp. Con xin thái y một phương thuốc gửi về.»"},{"who":"me","text":"Thư cha chỉ nói qua loa, thái y còn cần biết triệu chứng chi tiết. Ta sẽ vào Thái y viện, xin thuốc rồi gói thật cẩn thận."}]}},
{"id":"j72:j72c-fam-005","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư giấy đỏ bước vào, khóe môi hơi cong vì tin vui nhà ngoại."},{"who":"M","text":"{Goi}, thư dì bên nhà vừa tới. Nghe nói nhà sắp có hỷ sự."},{"who":"me","text":"Dì gả con gái sao? Ngươi đọc ta nghe."},{"who":"M","text":"Dì viết: «Cháu gái, dì sắp gả con cho nhà tử tế. Dì nghĩ cháu ở cung biết món quà nào không phạm lệ. Cháu chọn giúp dì một món.»"},{"who":"me","text":"Một món thực dụng, một món có ý nghĩa, một món lộng lẫy. Ta phải sang Nội vụ phủ xem rồi mới chọn được."}]}},
{"id":"j72:j72c-fam-006","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Thư bà ngoại gửi tới qua tay một người quen, giấy mỏng, nét chữ đã yếu."},{"who":"M","text":"{Goi}, thư bà ngoại bên nhà. Nô tỳ xem nét chữ mà lòng chùng xuống."},{"who":"me","text":"Bà tuổi cao rồi. Ngươi đọc cho ta nghe, chậm thôi."},{"who":"M","text":"Bà viết: «Cháu ơi, bà tuổi cao rồi, e không gặp lại cháu được nữa. Cháu gửi cho bà một bức chân dung nhỏ, để bà nhìn cho đỡ nhớ.»"},{"who":"me","text":"Ta sẽ nhờ họa sư vẽ một bức nhỏ, nhưng phải chờ mực khô, đóng khung cho cẩn thận. Chỉ sợ họa sư vẽ khác người thật, bà không nhận ra."}]}},
{"id":"j72:j72c-fam-007","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} khẽ khàng bước vào, tay ôm một phong thư cũ nhàu, nét chữ run run của người đã ngoài tuổi."},{"who":"M","text":"{Goi}, thư vú nuôi từ quê gửi vào. Nô tỳ nghe nói bà đã ốm lâu."},{"who":"me","text":"Vú nuôi của ta... Ngươi đọc đi."},{"who":"M","text":"Bà viết: «Tiểu thư của vú, vú muốn vào cung thăm con một lần trước khi nhắm mắt. Con xin phép trong cung giúp vú.»"},{"who":"me","text":"Phải xin ở Cung Chính ti, nghe nói họ chỉ cho vào một ngày. Ta sẽ đi xin ngay."}]}},
{"id":"j72:j72c-fam-008","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} bước vào, trên tay là phong thư của biểu huynh, nét chữ gấp gáp như người đã chờ lâu."},{"who":"M","text":"{Goi}, thư biểu huynh bên ngoại gửi vào. Ông ấy viết dài hơn mọi lần."},{"who":"me","text":"Huynh ấy từ lâu đã không có việc. Ngươi đọc đi."},{"who":"M","text":"Ngài viết: «Huynh đã ba năm không có việc. Ở cung, nghe nói Nội vụ phủ đang thiếu người ghi sổ. Nói giúp huynh một tiếng.»"},{"who":"me","text":"Ta đã biết huynh ấy làm việc không đều. Nhưng tình nghĩa cũng không nỡ bỏ, để ta hỏi xem Nội vụ phủ còn thiếu chỗ nào."}]}},
{"id":"j72:j72c-fam-009","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cười mỉm bước vào, trên tay là phong thư giấy bản nét chữ nguệch ngoạc của trẻ con."},{"who":"M","text":"{Goi}, thư tiểu đệ bên nhà gửi vào, chữ còn xiêu vẹo nhưng ý rất rõ."},{"who":"me","text":"Thằng bé lại đòi gì? Ngươi đọc ta nghe."},{"who":"M","text":"Cậu bé viết: «Hôm trước tỷ gửi về con vịt gỗ, đệ thích lắm, nhưng bị thằng bé hàng xóm lấy mất. Gửi đệ con khác, đệ giấu kỹ.»"},{"who":"me","text":"Ta sẽ ra chợ cung chọn một con thật chắc, đừng quá dễ vỡ. Thằng bé mà giấu kỹ thì phải là món bền."}]}},
{"id":"j72:j72c-fam-010","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài trời mưa dầm, {M} cầm phong thư ướt một góc bước vào, mặt mày thoáng buồn."},{"who":"M","text":"{Goi}, thư phụ thân vừa đến. Nô tỳ sợ trong thư có chuyện không lành."},{"who":"me","text":"Đọc ta nghe, chậm rãi thôi."},{"who":"M","text":"Người viết: «Con gái, mùa mưa năm nay mái nhà dột nặng, cha già không đủ bạc sửa. Con gửi giúp cha một ít, cha sẽ hoàn lại khi mùa màng khá.»"},{"who":"me","text":"Bạc của ta cũng không dư, nhưng cha thật sự cần. Ngươi mở rương riêng của ta ra, để ta đếm."}]}},
{"id":"j72:j72c-fam-011","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} khẽ khép cửa sau lưng rồi mới đặt phong thư xuống trước mặt."},{"who":"M","text":"{Goi}, thư của chú bên nhà. Trong thư có kèm một tấm bản đồ ruộng."},{"who":"me","text":"Chú ấy ít khi viết thư. Đọc cho ta."},{"who":"M","text":"Ông viết: «Cháu, chú đang có tranh chấp ruộng với một nhà giàu, quan huyện nghiêng về họ. Cháu có thế trong cung, nhắn một lời cho quan trên.»"},{"who":"me","text":"Nhà kia có thế, mà chú cũng chưa hẳn đúng hoàn toàn. Để ta nhờ người quen ở Hộ bộ xem bản đồ trước, rồi hẵng tính."}]}},
{"id":"j72:j72c-fam-012","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} đứng bên cửa sổ, tay cầm phong thư nhẹ mà dường như nặng trĩu."},{"who":"M","text":"{Goi}, thư cô bên nhà gửi vào. Nô tỳ đọc thoáng qua, thấy đó là chuyện riêng của cô."},{"who":"me","text":"Cô lấy chồng đã mấy năm, có chuyện gì sao? Đọc đi."},{"who":"M","text":"Cô viết: «Cháu gái, cô lấy chồng đã nhiều năm mà chồng lạnh nhạt. Cháu sống trong cung nhiều chuyện, có cách gì khuyên cô không?»"},{"who":"me","text":"Lời khuyên nói sai thì có thể làm cô giận, mà nói đúng cũng chưa chắc cô vui. Để ta suy nghĩ rồi mới viết thư trả lời."}]}},
{"id":"j72:j72c-fam-013","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} mang đến một phong thư thơm mùi đất ẩm, trên giấy còn dính chút cánh hoa khô."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà từ vườn quê gửi vào."},{"who":"me","text":"Cha lại mê trồng hoa rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, vườn nhà trồng thử hoa quý trong cung mà không nảy. Con xin giúp cha ít hạt giống ở vườn ngự.»"},{"who":"me","text":"Hạt quý không được mang ra khỏi cung, thợ vườn chắc sẽ do dự. Nhưng ta sẽ tìm cách hỏi khéo."}]}},
{"id":"j72:j72c-fam-014","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} bước vào với nụ cười hiếm hoi, trên tay là gói giấy dầu buộc dây gai cùng một phong thư."},{"who":"M","text":"{Goi}, thư mẫu thân vừa tới, kèm theo một gói thuốc quê. Hình như bà đã nghe tin vui."},{"who":"me","text":"Tin ấy đã lan đến tận nhà rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ nghe tin con có hỷ, vui không ngủ được. Mẹ gửi vài bài thuốc dân gian, con xem thái y có đồng ý không.»"},{"who":"me","text":"Thuốc ấy phải để thái y xem trước. Nếu một vị không hợp, ta sẽ nói sao cho mẹ không buồn."}]}},
{"id":"j72:j72c-fam-015","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư gấp tư, nét chữ mềm mại của một người phụ nữ đã lớn tuổi."},{"who":"M","text":"{Goi}, thư tẩu tử bên bên nhà gửi vào. Người nhờ chuyện một người thân trong cung."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Chị viết: «Tiểu cô, tẩu có người thân đang làm thợ thêu trong cung, từ lâu không có tin. Muội hỏi thăm giúp tẩu.»"},{"who":"me","text":"Để ta hỏi trong số cung nhân xem thợ thêu ấy ở đâu. Nghe nói có người đã chuyển sang cung khác, ta phải tìm kỹ."}]}},
{"id":"j72:j72c-fam-016","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} bước vào, đặt phong thư lên bàn rồi lùi lại một bước, như biết đây là chuyện hôn sự."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà vừa tới, chỉ nói về tiểu đệ."},{"who":"me","text":"Đệ ấy đến tuổi lấy vợ rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, đệ đệ con đã đến tuổi lấy vợ. Cha muốn biết có nhà nào trong cung có con gái hiền, môn đăng hộ đối. Con dò giúp cha.»"},{"who":"me","text":"Có nhà giàu mà kiêu, có nhà nghèo mà hiền. Ta chỉ dám dò qua người quen, tuyệt không để tin truyền ra ngoài."}]}},
{"id":"j72:j72c-fam-017","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều thu, {M} mang đến phong thư của mẫu thân, giấy còn thoảng mùi trà ngâm."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào. Bà nhắc đến sinh nhật phụ thân."},{"who":"me","text":"Ngày ấy ta chưa quên. Ngươi đọc đi."},{"who":"M","text":"Bà viết: «Con gái, sinh nhật cha sắp đến, ông hay giận dỗi mà thương con nhất. Con viết một lá thư chúc, mẹ đọc cho ông nghe.»"},{"who":"me","text":"Viết gần gũi hay lễ nghĩa, ta còn phân vân. Ta sẽ ngồi ở thư phòng viết cho cha một lá thư từ lòng mình."}]}},
{"id":"j72:j72c-fam-018","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư giấy cũ, nét chữ khô cứng của một người từng quen cha nhà ta."},{"who":"M","text":"{Goi}, thư của một vị bác, nói là cố nhân của phụ thân. Nô tỳ chưa từng thấy tên ấy."},{"who":"me","text":"Đọc ta nghe."},{"who":"M","text":"Bác ấy viết: «Cháu, bác là cố nhân của cha cháu, nghe nói cháu ở cung. Bác muốn biết quan Hộ bộ năm nay có đổi người không. Bác thấy cháu tin được.»"},{"who":"me","text":"Đây là chuyện quan trọng, người ta không dễ nói. Ta sẽ hỏi người quen ở Hộ bộ thật nhẹ nhàng."}]}},
{"id":"j72:j72c-fam-019","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư lên, tiếng ho khan của ông cụ dường như còn vang trong từng nét chữ."},{"who":"M","text":"{Goi}, thư ông bên nhà gửi vào. Ông vẫn còn ho."},{"who":"me","text":"Ông ho dai như vậy sao? Ngươi đọc cho ta."},{"who":"M","text":"Ông viết: «Cháu ơi, ông ho mãi, thuốc lá thầy lang cho không bớt. Cháu xin thái y một cách khác, ông tin cháu hơn mọi thầy.»"},{"who":"me","text":"Thái y cần nghe ông kể rõ triệu chứng. Ta sẽ viết thư hỏi ông, rồi mới đến Thái y viện xin thuốc."}]}},
{"id":"j72:j72c-fam-020","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Phong thư niêm sáp dày, dấu nhẫn của phụ thân còn in nguyên, {M} cầm bằng cả hai tay."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, trong thư có kèm một lá thư khác niêm kín. Người dặn gì đó rất nặng."},{"who":"me","text":"Đọc đi."},{"who":"M","text":"Người viết: «Con gái, cha có lá thư quan trọng muốn con giữ ở cung, nhà cha không còn chỗ kín. Đừng mở, đừng nói ai, đến khi cha viết thư nhắc.»"},{"who":"me","text":"Lá thư ấy ta sẽ cất ở nơi chỉ ta biết. Ngươi cũng đừng nhắc với ai."}]}},
{"id":"j72:j72c-fam-021","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} nâng phong thư lên, mùi giấy vàng đã ngả màu nhang khói."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào, nhắc đến ngày giỗ ông nội."},{"who":"me","text":"Gần đến ngày giỗ rồi sao? Đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, ngày giỗ ông nội sắp đến, mẹ muốn nhờ con chép kinh gửi về. Chữ con đẹp, ông nội sẽ vui.»"},{"who":"me","text":"Ta sẽ chép ở thư phòng. Chỉ sợ có một đoạn kinh rối, dễ chép sai, phải để ta chép thật cẩn thận."}]}},
{"id":"j72:j72c-fam-022","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư từ phía dượng nhà ta, mực còn nhòe đôi chữ vì tay người viết run."},{"who":"M","text":"{Goi}, thư dượng bên nhà gửi vào. Dượng sắp lo hôn sự cho con gái."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Dượng viết: «Cháu ở cung biết nơi bán lụa tốt giá phải chăng. Dượng sắp may áo cưới cho con, nhờ cháu hỏi giúp.»"},{"who":"me","text":"Có chủ hàng giá tốt mà hay lừa, có chủ hàng giá cao mà thật. Ta sẽ hỏi người mua sắm của cung xem nên chọn nhà nào."}]}},
{"id":"j72:j72c-fam-023","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} đặt phong thư xuống bàn, nét mặt như đã đoán trước chuyện không dễ nói."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, nói về chuyện hôn sự của tiểu muội."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, có nhà giàu muốn dạm hỏi em gái con. Cha muốn con xem trong cung có ai biết nhà ấy, nhận xét giúp cha.»"},{"who":"me","text":"Nghe nói nhà ấy giàu mà tiếng không tốt. Ta sẽ hỏi người quen cho kỹ, rồi mới viết thư khuyên cha."}]}},
{"id":"j72:j72c-fam-024","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Phong thư của người chị đến vào buổi chiều tĩnh, {M} mang vào bằng tay nhẹ như sợ làm nát giấy."},{"who":"M","text":"{Goi}, thư chị gái bên nhà gửi vào. Người nhắc một vật cũ."},{"who":"me","text":"Đọc đi."},{"who":"M","text":"Chị viết: «Tỷ nhớ chiếc khăn hồi nhỏ mẹ may cho hai chị em, muội còn giữ không? Gửi tỷ một góc, tỷ muốn nhìn lại.»"},{"who":"me","text":"Chiếc khăn hồng nhạt, hai chữ cái thêu ở góc. Ta phải lục rương cũ, chỉ sợ gửi đi rồi thất lạc."}]}},
{"id":"j72:j72c-fam-025","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư từ phụ thân, vẻ mặt bình lặng như người đã quen những chuyện thế này."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà gửi vào, nhắc đến một người hầu cũ."},{"who":"me","text":"Đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, người hầu cũ của bên nhà tuổi cao không còn sức làm. Cha không nỡ đuổi, con xin ít bạc nuôi ông ấy thêm.»"},{"who":"me","text":"Ông ấy phục vụ nhà ta ba đời, ta không thể làm ngơ. Mở rương riêng cho ta, dù bạc ít cũng phải gửi."}]}},
{"id":"j72:j72c-fam-026","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} mang vào phong thư của phụ thân, kèm một mảnh giấy ghi tên người đã góp."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà gửi vào. Trong thư nói về mộ tổ."},{"who":"me","text":"Mộ tổ có chuyện gì sao? Đọc đi."},{"who":"M","text":"Người viết: «Con gái, mộ tổ bên nhà bị mưa lở, họ hàng bàn góp tiền sửa. Con góp một phần, để tổ tiên biết con còn nhớ họ.»"},{"who":"me","text":"Họ hàng người góp ít người góp nhiều, ta cũng phải góp cho vừa lòng cha. Ngươi giúp ta gom bạc."}]}},
{"id":"j72:j72c-fam-027","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của bác, giấy còn thơm mùi gỗ mới vì ông vừa dựng nhà."},{"who":"M","text":"{Goi}, thư bác bên nhà gửi vào. Bác nói bác vừa dựng nhà mới."},{"who":"me","text":"Nhà mới thì phải có câu đối. Ngươi đọc ta nghe."},{"who":"M","text":"Bác viết: «Cháu, bác vừa dựng nhà mới, chưa có câu đối trước cửa. Cháu chữ đẹp, viết giúp bác một đôi.»"},{"who":"me","text":"Một vế nói về nhà, một vế nói về người ở. Ta sẽ ngồi ở thư phòng nghĩ cho thật chỉnh."}]}},
{"id":"j72:j72c-fam-028","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư có dính vài vệt màu nhuộm còn chưa phai, lạ mắt giữa bàn giấy trắng."},{"who":"M","text":"{Goi}, thư dì bên nhà gửi vào. Dì mới mở một lò nhuộm nhỏ."},{"who":"me","text":"Dì ấy chăm chỉ thật. Ngươi đọc ta nghe."},{"who":"M","text":"Dì viết: «Cháu, dì nghe nói trong cung có cách pha màu nhuộm vải bền không phai. Dì mở lò nhuộm nhỏ, cháu chỉ dì với.»"},{"who":"me","text":"Cách pha màu là bí quyết riêng, thợ nhuộm chưa chắc chịu nói. Nhưng ta sẽ hỏi thử ở Nội vụ phủ."}]}},
{"id":"j72:j72c-fam-029","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} đặt phong thư xuống, giọng khẽ hạ xuống như sợ ai nghe thấy."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà. Bà dặn đừng đồn với ai trong cung."},{"who":"me","text":"Bà dặn như vậy, ắt có điều giấu. Đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ vẫn khỏe, đừng lo. Chỉ dạo này hay mệt, thầy lang bảo uống thuốc bổ. Con đừng đồn với ai trong cung.»"},{"who":"me","text":"Mẹ sợ làm phiền ta nên không chịu nhận thuốc. Ta sẽ xin thái y gói thuốc bổ, rồi viết thư dỗ mẹ nhận."}]}},
{"id":"j72:j72c-fam-030","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tờ giấy bản nhẹ như cánh chim, {M} cầm bằng hai ngón tay mà vẫn thấy ấm."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào. Bà nhắc chuyện chim sẻ ngoài hiên."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, hôm nay mẹ thấy chim sẻ làm tổ ở hiên, nhớ lúc con còn bé hay đứng xem. Con vẽ chim sẻ gửi mẹ, mẹ treo chỗ cũ.»"},{"who":"me","text":"Chim đứng, chim bay hay chim hót, ta còn nghĩ chưa ra. Ta sẽ vẽ ở thư phòng, một góc có tổ chim."}]}},
{"id":"j72:j72c-fam-031","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} mang vào phong thư thơm mùi bột gạo, như có hơi bếp từ phương xa."},{"who":"M","text":"{Goi}, thư chị gái bên nhà gửi vào. Người nhắc chuyện bánh cung."},{"who":"me","text":"Người lại nghe tin bánh rồi. Ngươi đọc ta nghe."},{"who":"M","text":"Chị viết: «Tỷ nghe nói trong cung có chiếc bánh gạo nhân hoa, ngon lắm. Muội chép công thức gửi tỷ, tỷ mở quán nhỏ bán.»"},{"who":"me","text":"Công thức ấy là bí truyền của ngự thiện phòng. Ta phải hỏi cung nữ nấu bánh thật khéo, không dám để lộ."}]}},
{"id":"j72:j72c-fam-032","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư lên rồi đặt xuống, nét mặt như đang cân nhắc điều gì."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, nói về chuyện họ tộc."},{"who":"me","text":"Họ hàng bàn việc gì? Ngươi đọc đi."},{"who":"M","text":"Người viết: «Con gái, họ hàng bàn việc chọn người nối dõi cho bên nhà. Cha muốn con nhắn một lời với bậc trên, để đừng chọn người không hợp.»"},{"who":"me","text":"Chuyện nối dõi là việc lớn, lại có người họ hàng muốn chen chân. Ta phải dò ý quan phụ trách việc họ tộc cho kỹ."}]}},
{"id":"j72:j72c-fam-033","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Ngoài cửa, một nô tỳ trong cung đứng lặng, hai tay nắm chặt phong thư gửi từ quê, mắt đỏ hoe."},{"who":"M","text":"{Goi}, có người hầu trong cung xin được gặp. Mẹ nàng ốm nặng ở quê, thư gửi đến mà nàng chưa dám xin nghỉ."},{"who":"me","text":"Ngươi gọi nàng vào. Nàng muốn gì?"},{"who":"M","text":"Nàng xin {goi} cho về vài ngày. Nhưng cung đang thiếu người, nô tỳ cũng không dám hứa thay."},{"who":"me","text":"Ta phải đến Cung Chính ti xin phép cho nàng, rồi xoay sở người thay."}]}},
{"id":"j72:j72c-fam-034","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều lặng, một nô tỳ trong cung đứng cúi đầu trước cửa, vạt áo vân vê mãi không thôi."},{"who":"M","text":"{Goi}, nô tỳ trong cung có chuyện không dám nói. Có người ngoài cung đến hỏi cưới nàng."},{"who":"me","text":"Đây là chuyện vui, sao nàng lại ngập ngừng?"},{"who":"M","text":"Nàng chưa dám nhận lời khi chưa được {goi} cho phép. Nhà trai nghèo nhưng hiền, nàng rất muốn."},{"who":"me","text":"Ta sẽ hỏi nhà trai qua người quen, nghe cho kỹ rồi mới trả lời nàng."}]}},
{"id":"j72:j72c-fam-035","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tối muộn, một nô tỳ trong cung đứng trước cửa phòng, tay ôm túi vải nhỏ còn lép kẹp."},{"who":"M","text":"{Goi}, có người hầu xin ứng trước một tháng lương. Nhà nàng ở quê đang thiếu bạc."},{"who":"me","text":"Nàng ấy hay xin ứng, lần này có thật không?"},{"who":"M","text":"Nô tỳ thấy nàng khóc, hình như lần này là thật. Nàng hứa tháng sau sẽ làm thêm bù lại."},{"who":"me","text":"Ta phải xem lại sổ bạc của cung rồi mới quyết."}]}},
{"id":"j72:j72c-fam-036","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một nô tỳ trong cung quỳ ngoài hành lang, mắt đỏ, trong tay còn nắm một mảnh sứ trắng viền xanh."},{"who":"M","text":"{Goi}, người hầu này có người đệ làm việc ở cung khác, lỡ làm vỡ chén nên bị phạt. Nàng xin {goi} nói giúp một lời."},{"who":"me","text":"Mảnh chén ấy ghi trong sổ cung kia sao? Ngươi mang nàng vào để ta hỏi rõ."},{"who":"M","text":"Nàng sợ đệ nàng bị đánh. Quản sự bên kia bảo phải có người bảo lãnh mới tha."},{"who":"me","text":"Để ta sang cung ấy gặp quản sự, nói một lời cho đệ nàng."}]}},
{"id":"j72:j72c-fam-037","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một nô tỳ trong cung đứng trước cửa phòng, tay ôm lá thư nhàu nát chữ nguệch ngoạc."},{"who":"M","text":"{Goi}, người hầu này nhận được thư nhà mà không biết đọc. Nàng xin {goi} đọc giúp, rồi viết thư trả lời."},{"who":"me","text":"Ngươi bảo nàng vào phòng riêng, ta đọc cho nàng nghe."},{"who":"M","text":"Nô tỳ thấy nét chữ có dấu tay người nhà, e trong thư có tin nàng chưa biết."},{"who":"me","text":"Nếu có tin buồn, ta sẽ nói thật nhẹ nhàng."}]}},
{"id":"j72:j72c-fam-038","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mùa lễ gần kề, một nô tỳ trong cung đứng trước cửa bếp nhỏ, ngón tay xoắn vào nhau."},{"who":"M","text":"{Goi}, người hầu này sắp về làng, muốn mang chút quà cho mấy đứa nhỏ. Nàng xin ban cho một ít bánh trái."},{"who":"me","text":"Nàng có lòng như vậy, ta cũng không nỡ từ chối. Ngươi dẫn nàng ra bếp cung xem bánh."},{"who":"M","text":"Bánh đẹp thì đắt, bánh rẻ lại sợ hỏng trên đường. Nàng không dám chọn."},{"who":"me","text":"Để ta tự chọn, chọn bánh vừa bền vừa thơm."}]}},
{"id":"j72:j72c-fam-039","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một nô tỳ trong cung đến trước cửa phòng, bàn tay nắm chặt một lá bùa giấy vàng gấp tam giác."},{"who":"M","text":"{Goi}, người hầu này có lá bùa mẹ cho từ nhỏ, mang vào cung bị cấm. Nàng xin {goi} giữ giúp, khi nào ra cung thì trả."},{"who":"me","text":"Một lá bùa nhỏ mà nặng lòng như vậy. Đưa đây, ta cất ở chỗ kín trong phòng."},{"who":"M","text":"Nghe nói Cung Chính ti sắp soát đồ các cung, {goi} phải cẩn thận."},{"who":"me","text":"Ta biết. Ta sẽ không để lá bùa bị thu."}]}},
{"id":"j72:j72c-fam-040","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Một nô tỳ trong cung đứng nghiêng đầu, một tay ôm má, nét mặt nhăn lại vì đau."},{"who":"M","text":"{Goi}, người hầu này đau răng mấy hôm, ăn không được, làm việc chậm. Nàng xin thuốc ở Thái y viện."},{"who":"me","text":"Đau như vậy mà vẫn làm việc sao? Để ta xin thuốc cho nàng."},{"who":"M","text":"Thái y có thể bảo thuốc chỉ hết đau, muốn khỏi hẳn phải nhổ răng. Nàng sợ lắm."},{"who":"me","text":"Cứ để ta xin thuốc trước, rồi tính tiếp."}]}},
{"id":"j72:j72c-fam-041","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm buông, một nô tỳ trong cung đứng ngoài cửa phòng, khe khẽ liếc nhìn bóng tối cuối hành lang."},{"who":"M","text":"{Goi}, người hầu này nghe kể cung có chuyện lạ ban đêm, nàng sợ. Nàng xin ngủ gần cửa phòng để canh."},{"who":"me","text":"Nàng có lòng như vậy, ta cảm kích. Ngươi chỉ chỗ cho ta xem."},{"who":"M","text":"Có chỗ ngủ gần cửa nhưng lạnh, có chỗ ấm nhưng xa. Nàng không dám chọn."},{"who":"me","text":"Ta sẽ xem rồi tự quyết, đừng để nàng chịu lạnh."}]}},
{"id":"j72:j72c-fam-042","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} nâng một bản tâu niêm kín, dấu ấn riêng của con trưởng còn in rõ nơi mép."},{"who":"M","text":"{Goi}, con trưởng của {goi} gửi bản tâu vào. Cậu bé nhờ nô tỳ trao tận tay."},{"who":"me","text":"Con ta lớn rồi, không biết muốn nói gì. Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần đã lớn, muốn ra ngoài tầm sư học đạo vài tháng. Xin mẫu phi nói giúp với phụ hoàng.»"},{"who":"me","text":"Hoàng thượng muốn con ở gần, mà con lại muốn đi xa. Ta phải chọn đúng thời khắc để thưa với ngài."}]}},
{"id":"j72:j72c-fam-043","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} khép nép bước vào, trên tay là phong thư thơm mùi hương mới của con gái sắp xuất giá."},{"who":"M","text":"{Goi}, thư của công chúa gửi vào. Nàng sắp thành thân."},{"who":"me","text":"Con gái ta đã đến ngày ấy rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Nàng viết: «Mẫu phi, sắp đến ngày thành thân, nữ nhi muốn mẫu phi chọn giúp cây trâm cài ngày ấy, để mẫu phi theo con suốt đời.»"},{"who":"me","text":"Ta sẽ đến Nội vụ phủ chọn. Một cây quý hiếm mà con sợ làm mất, một cây giản dị hợp lễ, ta sẽ chọn cho vừa lòng con."}]}},
{"id":"j72:j72c-fam-044","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm bản tâu nhỏ, nét chữ non nớt nhưng hăm hở của cậu con trai."},{"who":"M","text":"{Goi}, thư của hoàng tử gửi vào. Cậu bé nhờ nô tỳ đọc."},{"who":"me","text":"Con ta lại muốn gì? Đọc đi."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần muốn tập cưỡi ngựa như các hoàng tử khác. Xin mẫu phi nói giúp, cho nhi thần một con ngựa non.»"},{"who":"me","text":"Thái bộc tự chắc chỉ có một con ngựa non, chưa tập được ngay. Ta sẽ đến hỏi."}]}},
{"id":"j72:j72c-fam-045","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm tờ thư nhỏ, đầu giấy còn nhòe một vệt mực vì người viết vội."},{"who":"M","text":"{Goi}, thư của hoàng tử gửi vào, nhắc đến chuyện sách."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần đọc xong mấy cuốn trong thư phòng, muốn mượn thêm bộ sách cổ ở kho Hàn lâm. Xin mẫu phi xin giúp.»"},{"who":"me","text":"Con ta ham đọc, ta mừng. Hàn lâm viện có thể chỉ cho mượn một phần, ta cũng sẽ xin cho được chừng nào hay chừng ấy."}]}},
{"id":"j72:j72c-fam-046","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} đứng lặng trước cửa, vẻ mặt lo lắng khi đưa lên một bản thư của cậu con trai."},{"who":"M","text":"{Goi}, thư của hoàng tử gửi vào, giọng văn trầm hơn mọi lần."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần có người đồng môn bị oan, nhi thần muốn mẫu phi giúp giải oan, nhưng không biết có nên không.»"},{"who":"me","text":"Việc này có thể kéo ta vào chuyện rắc rối. Ta phải nghe con kể kỹ rồi mới quyết định."}]}},
{"id":"j72:j72c-fam-047","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng ho khẽ vọng từ hành lang đưa theo {M}, tay cầm thư của hoàng tử."},{"who":"M","text":"{Goi}, thư của hoàng tử gửi vào. Cậu bé vẫn còn ho."},{"who":"me","text":"Con ta ho dai như vậy sao? Ngươi đọc đi."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần ho dai, uống thuốc mãi không dứt. Xin mẫu phi xin thái y một bài mới, nhi thần tin thái y hơn thầy lang ngoài.»"},{"who":"me","text":"Thái y cần theo dõi nhiều ngày mới biết bệnh. Ta sẽ đến Thái y viện nhờ xem bệnh cho con."}]}},
{"id":"j72:j72c-fam-048","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm bản thư của hoàng tử, vành tai khẽ nóng lên vì chuyện vui sắp đến."},{"who":"M","text":"{Goi}, hoàng tử được mời dự yến nhà đại thần, cậu viết thư hỏi ý {goi}."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Mẫu phi, nhi thần được mời dự yến nhà đại thần, không biết nên mặc gì, nói gì. Mẫu phi chỉ giúp.»"},{"who":"me","text":"Con ta muốn nổi bật, nhưng nổi bật quá có thể gặp họa. Ta sẽ dặn con từng điều về lễ nghi."}]}},
{"id":"j72:j72c-fam-049","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} mang vào lá thư của hoàng tử, nét chữ còn ngập ngừng như người ngượng ngùng xin xỏ."},{"who":"M","text":"{Goi}, sắp đến lễ thầy, hoàng tử chưa có quà. Cậu xin {goi} ít bạc mua một món nhỏ."},{"who":"me","text":"Ngươi đọc thư ta nghe."},{"who":"M","text":"Cậu viết: «Mẫu phi, sắp đến lễ thầy, nhi thần chưa có quà. Xin mẫu phi cho nhi thần ít bạc mua một món nhỏ.»"},{"who":"me","text":"Một món rẻ mà ý nghĩa, hay một món đắt mà thể diện? Ta sẽ cùng con chọn."}]}},
{"id":"j72:j72c-fam-050","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} khẽ bước vào, đôi tay nâng phong thư giấy hồng điều như nâng một vật quý."},{"who":"M","text":"{Goi}, thư nhà vừa tới cho {goi}. Niêm sáp còn mới, nét chữ là chữ quen."},{"who":"me","text":"Ngươi cứ đứng đó, ta đọc xong sẽ nói."},{"who":"M","text":"Nô tỳ nghe nói thư kể nhiều chuyện, chỉ một chuyện cần trả lời gấp."},{"who":"me","text":"Để ta đọc trong phòng riêng, rồi viết hồi âm ngay."}]}},
{"id":"j72:j72c-fam-051","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Hôm nay đoàn thư của cung sắp lên đường, {M} đứng bên bàn, tay ôm một gói vải nhỏ."},{"who":"M","text":"{Goi}, nô tỳ xin gửi chút quà về quê mẹ, mong {goi} thương cho gửi cùng đoàn thư."},{"who":"me","text":"Ngươi có lòng hiếu, ta không từ chối. Gói gì đây?"},{"who":"M","text":"Một gói vải nhỏ, buộc dây thô, ngoài có tên mẹ nô tỳ."},{"who":"me","text":"Để ta xem, có muốn thêm món gì của ta cùng gửi không, hay chỉ gửi quà của ngươi."}]}},
{"id":"j72:j72c-fam-052","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} đứng lặng, mắt đỏ, tay siết chặt vạt áo."},{"who":"M","text":"{Goi}, nhà nô tỳ vừa có tang, cha nô tỳ mất, nô tỳ không về được."},{"who":"me","text":"Ngươi nói gì? Phụ thân ngươi mất rồi sao?"},{"who":"M","text":"Dạ, nô tỳ xin {goi} viết giúp thư thăm gia đình nô tỳ, nô tỳ không dám tự viết."},{"who":"me","text":"Ta sẽ ngồi viết cùng ngươi, thư nên có lời ấm mà không quá nặng."}]}},
{"id":"j72:j72c-fam-053","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của phụ thân, giấy hồng điều, chữ vững mà giọng thư trầm nặng."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà gửi vào. Người nhắc đến một nhà cố nhân."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, bên nhà với nhà người cố nhân của cha giận nhau vì chuyện nhỏ. Con có quen con gái nhà ấy trong cung, nói giúp cha vài lời.»"},{"who":"me","text":"Nàng ấy cũng muốn làm hòa, nhưng sợ phụ thân nàng. Ta sẽ gặp nàng trong cung, nói thật nhẹ nhàng."}]}},
{"id":"j72:j72c-fam-054","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của mẫu thân, bên cạnh là gói lụa hồng buộc dây tím."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào, kèm theo gói quà tạ ơn."},{"who":"me","text":"Quà cho ai? Ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ nghe nói con thân với một vị phi tần tử tế. Mẹ gửi chút quà nhỏ, con chuyển giúp mẹ, tỏ lòng cảm ơn nàng chăm sóc con.»"},{"who":"me","text":"Nàng ấy có thể từ chối vì sợ người đàm tiếu. Ta sẽ mang đến tận cung nàng, nói thật khéo."}]}},
{"id":"j72:j72c-fam-055","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} bước vào, tay cầm bản nháp giấy thô, mực nhòe, vài chỗ gạch đi chằng chịt."},{"who":"M","text":"{Goi}, thư tiểu đệ bên nhà gửi vào. Cậu bé có chuyện vừa ngượng vừa mừng."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Đệ có cô nương muốn hỏi, mà đệ viết thư vụng lắm. Ở cung văn hay, xin chỉ đệ vài câu.»"},{"who":"me","text":"Ta sẽ đọc bản nháp rồi sửa từng câu. Câu nào hoa mỹ quá thì gọt bớt, câu nào thật thà quá thì thêm chút ý."}]}},
{"id":"j72:j72c-fam-056","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} ôm phong thư và nhìn quanh một lượt, như sợ có ai nghe lỏm lời trong thư."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, nặng hơn mọi lần."},{"who":"me","text":"Đọc đi, ta nghe."},{"who":"M","text":"Người viết: «Con gái, bên nhà sắp mất đất, cha muốn con giữ giúp vật gia bảo duy nhất, khỏi lọt vào tay chủ nợ.»"},{"who":"me","text":"Chiếc hộp gia bảo ấy ta sẽ cất ở nơi kín nhất cung. Nếu chủ nợ cử người đến hỏi, ngươi không được nhắc một lời."}]}},
{"id":"j72:j72c-fam-057","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} mang vào phong thư của phụ thân, kèm một bản văn khế cũ, giấy dày ba dấu tay."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, nhắc đến mảnh vườn cũ."},{"who":"me","text":"Mảnh vườn đã cầm cố năm nào, ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, mảnh vườn bên nhà từng cầm cố, năm nay cha muốn chuộc lại. Con gửi giúp cha một khoản, cha ghi sổ trả dần.»"},{"who":"me","text":"Bạc trong rương ta e chưa đủ chuộc cả. Ta sẽ gom thêm từ người quen, rồi tính."}]}},
{"id":"j72:j72c-fam-058","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của phụ thân, nét chữ bình thản nhưng ý trong thư lại nặng lời hứa."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà, nhắc đến một cô gái hàng xóm."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, con hàng xóm bên nhà muốn vào cung làm cung nữ. Con tiến cử giúp, cha hứa với bà con rồi.»"},{"who":"me","text":"Cô ấy ta chưa gặp, không biết tính nết. Nhưng ta sẽ hỏi Cung Chính ti xem còn thiếu cung nữ không."}]}},
{"id":"j72:j72c-fam-059","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} nâng phong thư của mẫu thân, mùi tro bếp quê nhà thoảng ra từ giấy."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào, nhắc chuyện xây bếp."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ muốn xây thêm gian bếp nhỏ mà không biết ngày nào tốt. Con hỏi thầy Khâm thiên giám giúp mẹ.»"},{"who":"me","text":"Ta sẽ hỏi người quen ở Khâm thiên giám. Thầy cho hai ngày, một hợp một kỵ, ta phải nghe cho kỹ."}]}},
{"id":"j72:j72c-fam-060","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của cô, giấy vàng cuộn nhỏ, như một lời nhắc về nguồn cội."},{"who":"M","text":"{Goi}, thư cô bên nhà gửi vào. Sắp đến ngày họp họ rồi."},{"who":"me","text":"Cô muốn ta viết gì?"},{"who":"M","text":"Cô viết: «Cháu, sắp đến ngày họp họ, cô muốn cháu viết vài dòng gửi về, để họ hàng biết cháu vẫn nhớ nguồn cội.»"},{"who":"me","text":"Một đoạn nhắc chuyện cũ, một đoạn nhắc chuyện mới. Ta sẽ viết ở thư phòng, chữ phải thật ngay ngắn."}]}},
{"id":"j72:j72c-fam-061","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của thầy cũ, nét chữ run nhưng vẫn đĩnh đạc như thuở còn dạy học."},{"who":"M","text":"{Goi}, thư thầy bên nhà gửi vào. Nô tỳ nghe nói thầy đã già lắm."},{"who":"me","text":"Thầy dạy chữ cho ta từ thuở nhỏ. Ngươi đọc đi."},{"who":"M","text":"Thầy viết: «Con, thầy già rồi, không còn dạy được. Thầy nhớ con ngày nhỏ ngồi dưới gốc cây đọc sách. Con có thể giúp thầy chút bạc dưỡng già không.»"},{"who":"me","text":"Thầy tự trọng, e không nhận thẳng. Ta sẽ chuẩn bị túi bạc từ rương riêng, gửi sao cho thầy không thấy mình bị thương hại."}]}},
{"id":"j72:j72c-fam-062","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} bước vào với nụ cười khẽ, tay cầm phong thư của phụ thân, giấy vàng nét chữ trang trọng."},{"who":"M","text":"{Goi}, thư phụ thân bên nhà gửi vào. Người nghe tin vui rồi."},{"who":"me","text":"Cha đã biết rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, nghe tin con có hỷ, cha muốn tự đặt tên cho cháu. Cha nghĩ vài cái, con chọn một cái hợp ý.»"},{"who":"me","text":"Một tên mạnh mẽ, một tên hiền hòa, một tên cổ kính. Ta sẽ đọc từng cái rồi chọn."}]}},
{"id":"j72:j72c-fam-063","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của tiểu đệ, giấy bản nhàu nhĩ vì bị cầm nhiều lần trước khi gửi."},{"who":"M","text":"{Goi}, thư tiểu đệ bên nhà gửi vào. Cậu bé ở nhà buồn lắm."},{"who":"me","text":"Cậu bé muốn gì? Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Đệ ở nhà buồn lắm, tỷ kể đệ nghe một chuyện vui trong cung đi, đệ đọc cho cả xóm nghe.»"},{"who":"me","text":"Chuyện cung không nên nói bừa. Ta sẽ kể một chuyện vô hại, vẽ thêm vài hình nhỏ cho cậu vui."}]}},
{"id":"j72:j72c-fam-064","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm phong thư của cậu, giấy nhã, nét chữ khẩn khoản nhưng giữ lễ."},{"who":"M","text":"{Goi}, thư cậu bên nhà gửi vào. Cậu nhờ một việc rất khó mở lời."},{"who":"me","text":"Ngươi đọc ta nghe."},{"who":"M","text":"Cậu viết: «Cháu, cậu có người quen bị phạt vì lỗi nhỏ, cậu muốn nhờ cháu xin Hoàng thượng giảm nhẹ. Cậu biết cháu ngại ngần.»"},{"who":"me","text":"Người ấy có lỗi thật, dù nhỏ. Ta sẽ dò ý Hoàng thượng qua người thân tín trước, không dám thưa vội."}]}},
{"id":"j72:j72c-fam-065","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} nâng phong thư của người chị lên, trong lòng giấy còn kẹp một cánh hoa khô."},{"who":"M","text":"{Goi}, thư chị gái bên nhà gửi vào. Người sắp cưới."},{"who":"me","text":"Người sắp cưới rồi sao? Ngươi đọc ta nghe."},{"who":"M","text":"Chị viết: «Tỷ sắp cưới, muốn có hoa trong cung để cài. Muội xin giúp tỷ vài bông, tỷ nhớ ơn.»"},{"who":"me","text":"Hoa nở rộ thì dễ héo, hoa nụ thì bền mà chưa đẹp. Ta sẽ xin thợ vườn ngự những bông đẹp nhất."}]}},
{"id":"j72:j72c-fam-066","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} cầm một gói lá khô nhỏ, bên ngoài có tên hoa trà, cùng phong thư của mẫu thân."},{"who":"M","text":"{Goi}, thư mẫu thân bên nhà gửi vào, kèm một gói trà ngủ."},{"who":"me","text":"Mẹ lo ta mất ngủ sao? Ngươi đọc ta nghe."},{"who":"M","text":"Bà viết: «Con gái, mẹ nghe người ta nói trong cung hay thức đêm, mẹ lo con mất ngủ. Mẹ gửi ít trà ngủ, con thử.»"},{"who":"me","text":"Vị trà lạ, ta chưa rõ hợp hay không. Ngươi pha thử cho ta một chén."}]}},
{"id":"j72:th_thuoc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Thái y viện, lò thuốc nghi ngút khói, bàn thuốc bày dở dang một đơn còn thiếu vị."},{"who":"A","text":"Thái hậu mắc bệnh đã mấy hôm, mà phương thuốc của thần còn thiếu một vị quý. Trong vườn ngự có trồng, nhưng khó tìm lắm."},{"who":"me","text":"Vị thuốc ấy hẳn quan trọng với phượng thể, nên thái y mới lo đến vậy. Thái y có biết nó mọc ở chỗ nào không?"},{"who":"A","text":"Có trồng ở vườn ngự, nhưng lá giống cỏ dại, không có mắt tinh thì dễ lẫn. Thần phải giữ lò, không rời đi được."},{"who":"me","text":"Thái y yên tâm giữ lò. {Xung} ra vườn tìm, hoặc nhờ người ngoài cung mua về, rồi mang sang Thái y viện."}]}},
{"id":"j72:th_thuoc2","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, lò thuốc cháy liu riu trong gian phòng kín, bóng người in trên vách mờ như sương."},{"who":"A","text":"Thái hậu vẫn chưa khỏi hẳn. Thuốc phải canh lửa ba đêm, không để ai lạ đến gần. Thần tin {goi}."},{"who":"me","text":"Ba đêm canh lửa không ngủ, lại không cho người lạ lại gần. Thái y sợ điều gì sao?"},{"who":"A","text":"Thuốc của Thái hậu mà lọt vào tay kẻ xấu thì thần có chết cũng không đền nổi. Cho nên thần chỉ dám nhờ người thật tin cậy."},{"who":"me","text":"Thái y đã tin {xung}, {xung} xin canh đủ ba đêm. Lửa vừa, thuốc kỹ, sáng ra bệnh sẽ nhẹ đi."}]}},
{"id":"j72:th_kinh_om","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, đèn khuya vẫn sáng, trên bàn nhỏ chén thuốc đã nguội mà người bệnh chưa chợp mắt."},{"who":"A","text":"Ai gia mắc bệnh đã mấy hôm, đêm nằm không yên. {Goi} chép cho ai gia một quyển kinh Dược Sư."},{"who":"me","text":"Kinh Dược Sư cầu cho người bệnh được an, {xung} xin chép bằng cả tấm lòng. Thái hậu còn đau chỗ nào không?"},{"who":"A","text":"Đau thì chịu được, chỉ là đêm dài nằm một mình, lòng chẳng yên. Có tiếng kinh, ai gia thấy bớt lẻ loi."},{"who":"me","text":"{Xung} chép xong sẽ dâng sang và ngồi hầu Thái hậu, đọc cho Thái hậu nghe từng trang."}]}},
{"id":"j72:hh_hau_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gian ngoài Đức Thọ cung, Hoàng hậu tựa vào cột, mắt thâm quầng sau mấy đêm liền không ngủ."},{"who":"A","text":"Thái hậu ốm, {xung} hầu mấy đêm liền đã kiệt sức. {Goi} chia phiên với {xung} nhé."},{"who":"me","text":"Hoàng hậu thức đêm bao lâu rồi? Người phải giữ gìn phượng thể, kẻo Thái hậu lại thêm lo."},{"who":"A","text":"Phận con dâu, thấy mẫu hậu bệnh làm sao ngủ được. Nhưng sức người có hạn, {xung} sợ đến lúc ngã xuống mất."},{"who":"me","text":"{Xung} xin nhận phiên đêm. Hoàng hậu cứ nghỉ ngơi, đã có {xung} ở đây."}]}},
{"id":"j72:emp_om","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên giường rồng, chén thuốc đen còn nguyên, hơi đắng bốc lên làm người bệnh nhăn mặt."},{"who":"A","text":"Hoàng thượng mắc bệnh mà không chịu uống thuốc của thần. {Goi} được ngài thương, xin hầu ngài uống thuốc."},{"who":"me","text":"Hoàng thượng chê thuốc đắng, hay lòng đang có điều phiền muộn? Thái y có thấy gì khác không?"},{"who":"A","text":"Thần e cả hai. Thuốc đắng thì sắc lại cho dễ uống, nhưng phiền muộn thì chỉ người thân cận mới giải được."},{"who":"me","text":"{Xung} sẽ sắc lại thuốc cho dịu vị, rồi tự mang đến, nói với Hoàng thượng vài câu cho nhẹ lòng."}]}},
{"id":"j72:emp_kinh_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phật đường Đức Thọ cung lặng lẽ, khói trầm quấn quanh mấy quyển kinh trải sẵn trên án."},{"who":"A","text":"Hoàng thượng ốm, ai gia lòng như lửa đốt. Các phi tần đều phải chép kinh cầu an, {goi} cũng vậy."},{"who":"me","text":"Chép kinh cầu an cho Hoàng thượng là bổn phận, {xung} xin vâng. Thái hậu muốn chép bộ kinh nào?"},{"who":"A","text":"Cứ chọn bộ nào {goi} thuộc, miễn là chữ ngay ngắn, lòng thành. Chép xong dâng về ai gia, ai gia tự mang đặt trước tượng."},{"who":"me","text":"{Xung} sẽ chép từng chữ thật cẩn trọng, dâng sang Đức Thọ cung để Thái hậu tự tay thắp hương."}]}},
{"id":"j72:rv_thuoc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung {A}, hơi thuốc không còn, người bệnh nằm nghiêng nhìn ra cửa, mắt đầy chờ đợi."},{"who":"A","text":"{Goi}, {xung} nằm bệnh mấy hôm, người của {xung} xin thuốc mãi không được. {Goi} xin giúp {xung} ở Thái y viện nhé."},{"who":"me","text":"Sao lại không xin được? Thái y viện thường cấp thuốc cho người bệnh mà."},{"who":"A","text":"Chắc vì {xung} không còn mấy thế lực. Người hầu của {xung} chạy mấy lượt, lần nào cũng bị đuổi về."},{"who":"me","text":"Để {xung} đi xin. Thuốc có rồi, {xung} sẽ tự mang sang cung {goi}."}]}},
{"id":"j72:rv_tham_om","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cung của {B} im ắng lạ thường, rèm buông kín, chỉ nghe tiếng ho khẽ vọng ra."},{"who":"A","text":"{B} đang bệnh, mà chẳng ai đến thăm. {Goi} đi cùng {xung} nhé, mang ít thuốc bổ."},{"who":"me","text":"Chẳng ai đến thăm ư? Bệnh nặng mà lại lẻ loi, thật tội. {Goi} thân với {B} lắm sao?"},{"who":"A","text":"Không thân, nhưng thấy người ta nằm một mình, {xung} không đành lòng. Một chén thuốc cũng đủ làm lòng nàng ấm lại."},{"who":"me","text":"{Xung} chuẩn bị thuốc bổ, rồi cùng {goi} sang thăm {B}."}]}},
{"id":"j72:th_tham","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, Thái hậu tựa ghế bên khung cửa, tay vê tràng hạt, ánh mắt nhìn về phía cung xa."},{"who":"A","text":"{B} đang bệnh. Ai gia mỏi chân, không sang được, {goi} thay ai gia mang thuốc sang."},{"who":"me","text":"Thái hậu còn nhớ đến {B} lúc nàng nằm bệnh, nàng nhất định cảm kích lắm."},{"who":"A","text":"Cung này người đông nhưng ai nấy lo thân. Một người bệnh mà không ai hỏi han thì ai gia thấy chạnh lòng."},{"who":"me","text":"{Xung} xin thuốc ở Thái y viện, mang sang thăm {B}, thay Thái hậu nói lời hỏi han."}]}},
{"id":"j72:hh_om","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung Hoàng hậu, rèm thêu rủ xuống, bên giường là chén thuốc đã bị rót đổ một nửa."},{"who":"A","text":"{Xung} mắc bệnh, người hầu lại vụng về. {Goi} có lòng thì sang hầu thuốc giúp {xung}."},{"who":"me","text":"Người hầu vụng thì chén thuốc đổ cũng không lạ. Hoàng hậu bệnh thế nào rồi?"},{"who":"A","text":"Đỡ chút, nhưng nằm lâu thấy nặng nề. Chỉ cần một người cẩn thận, dịu dàng bên cạnh là {xung} yên tâm."},{"who":"me","text":"{Xung} xin hầu thuốc, từng muỗng từng muỗng cho Hoàng hậu dễ uống."}]}},
{"id":"j72:doc_docman","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thuốc, thái y đóng chặt cửa, nói thật khẽ như sợ vách có tai."},{"who":"A","text":"Thần bắt mạch {B}, thấy mạch có dấu trúng độc lâu ngày. Thần thân phận thấp, không dám nói với nàng. {Goi} nhắc giúp."},{"who":"me","text":"Trúng độc lâu ngày ư? Thái y có chắc không? Nói oan thì hậu quả thật khó lường."},{"who":"A","text":"Mạch không dối, thần chỉ không biết độc từ đâu. Nếu nói ra, e kẻ ra tay sẽ tìm đến thần trước."},{"who":"me","text":"{Xung} hiểu rồi. {Xung} sẽ báo kín cho {B}, không để lộ nguồn tin, cũng không nhắc đến thái y."}]}},
{"id":"j72:lc_thuoc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài tường Trường Môn viện, rêu xanh phủ kín cổng sắt, gió thổi qua nghe lạnh như tiếng thở dài."},{"who":"A","text":"{B} ở Trường Môn viện mắc bệnh, không ai được mang thuốc vào. Thần không vào được. {Goi} nhân từ…"},{"who":"me","text":"Lãnh cung cấm người ra vào, thái y nói vậy là muốn {xung} liều lĩnh mang thuốc vào sao?"},{"who":"A","text":"Thần chỉ không đành lòng. Một người bệnh bị bỏ mặc thì chẳng khác nào chờ chết. Thuốc thần đã phối sẵn."},{"who":"me","text":"Việc này nếu lộ thì họa không nhỏ, nhưng {xung} không thể làm ngơ. Thái y đưa thuốc cho {xung}, {xung} sẽ tìm cách vào."}]}},
{"id":"j72:thuoc_cam","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung {A} khóa chặt, người bên trong bị cấm túc đã lâu, sắc mặt xanh xao nhìn ra qua khe cửa."},{"who":"A","text":"{Xung} bị cấm túc mấy tháng, người suy kiệt. {Goi} thương {xung}, nhờ người lén mang ít thuốc bổ."},{"who":"me","text":"Cấm túc đã khổ, lại suy kiệt thế này. Cung nữ của {goi} không ai lo cho {goi} sao?"},{"who":"A","text":"Họ cũng bị canh giữ nghiêm. Chỉ mong {goi} nhớ tình xưa, mà đừng để bị bắt."},{"who":"me","text":"{Xung} xin thuốc ở Thái y viện, rồi tìm đường lẻn vào. Lưu ý giữ kín, kẻo cả hai cùng mắc tội."}]}},
{"id":"j72:huong_doc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng thuốc Thái y viện, những nén hương mới phối còn thơm nồng, khói mỏng cuộn nhẹ trong ánh sáng sớm."},{"who":"A","text":"Thần thấy {goi} sắc mặt mệt mỏi. Thần vừa phối được phương hương an thần, {goi} dùng thử rồi kể thần nghe."},{"who":"me","text":"Thái y chu đáo thật. {Xung} đúng là mấy đêm nay ngủ chẳng sâu giấc."},{"who":"A","text":"Hương này nhẹ, không làm nặng đầu. Dùng một tuần rồi thần mới biết công hiệu hay không, nên cần {goi} nói thật."},{"who":"me","text":"{Xung} dùng thử đủ một tuần rồi sẽ kể cho thái y nghe, ngủ ngon hay không, mộng nhẹ hay nặng."}]}},
{"id":"j72:rv_con_om","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung {A}, đứa trẻ nằm co trong chăn, thân hình gầy guộc, đôi mắt nhìn mẹ không chớp."},{"who":"A","text":"Con của {xung} yếu ớt mãi không khá. {Xung} sợ thái y trong cung bị người ta mua chuộc. {Goi} mời giúp {xung} người tin được."},{"who":"me","text":"{Goi} nghi có người dùng thuốc hại đứa trẻ sao? Nói ra cẩn thận, chuyện này không nhỏ."},{"who":"A","text":"{Xung} không dám nói chắc, chỉ thấy thuốc cứ dùng mà con không khá. Một người mẹ thì không dám liều."},{"who":"me","text":"{Xung} biết một thái y chính trực. Để {xung} mời người ấy, rồi cùng sang cung {goi} xem bệnh cho đứa nhỏ."}]}},
{"id":"j72:thu_ab","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lá thư làm lành nằm trong tay áo, gấp vuông vắn, nét chữ đắn đo từng dòng."},{"who":"A","text":"{Xung} với {B} giận nhau đã lâu. {Xung} viết lá thư này mà không dám đưa. {Goi} mang giúp {xung} được không?"},{"who":"me","text":"Giận nhau vì chuyện gì mà lâu đến thế? {Goi} viết thư tức là lòng còn mong làm lành."},{"who":"A","text":"Chuyện nhỏ thôi, nhưng ai cũng giữ thể diện, càng để lâu càng khó mở lời. {Xung} nhớ nàng nhiều hơn là giận."},{"who":"me","text":"{Xung} mang thư sang cung {B}, đợi nàng đọc rồi sẽ nghe ý nàng thế nào."}]}},
{"id":"j72:hoa_giai","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, khói trầm lượn lờ, Thái hậu khẽ thở dài bên chén trà đã nguội."},{"who":"A","text":"Hoàng hậu với {B} cứ gặp là gai mắt nhau. Hậu cung không yên thì ai gia cũng không yên. {Goi} khéo miệng, thử khuyên xem."},{"who":"me","text":"Hai bên mỗi người một tính, khuyên không khéo càng thêm xung đột. Thái hậu muốn {xung} bắt đầu từ ai?"},{"who":"A","text":"Từ {B}, nó trẻ, dễ nghe. Hoàng hậu thì ai gia sẽ tự nói. Hai người ấy bất hòa, cung này khó mà yên."},{"who":"me","text":"{Xung} sẽ gặp {B}, khuyên nhẹ nhàng, cho nàng thấy hòa khí quý hơn một câu thắng thua."}]}},
{"id":"j72:hh_kieu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung Hoàng hậu, chén trà đặt xuống mạnh tay, tiếng sứ chạm nhẹ mà nghe nặng nề."},{"who":"A","text":"{B} hễ gặp {xung} là nói lời khó nghe. {Xung} không muốn phạt nặng, {goi} sang khuyên nàng tự đến nhận lỗi."},{"who":"me","text":"Hoàng hậu nhân từ không muốn phạt nặng. Nhưng {B} kiêu, nàng chịu nghe không?"},{"who":"A","text":"Nếu nàng chịu nhận lỗi, {xung} sẽ bỏ qua. Nếu không, {xung} cũng đành phải nghiêm."},{"who":"me","text":"{Xung} sẽ gặp {B}, nghe nàng còn ấm ức gì, rồi khuyên nàng một cách thấu tình đạt lý."}]}},
{"id":"j72:rv_di_cung","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thiệp mời uống trà gửi đến chiều nay, chữ viết nắn nót, nhưng lòng người nhận không yên."},{"who":"A","text":"{B} ghét {xung} ra mặt, giờ lại cho gọi {xung} sang uống trà. {Xung} sợ lắm. {Goi} đi cùng {xung} được không?"},{"who":"me","text":"Người ghét lại mời trà, ắt có điều phải đề phòng. {Goi} nghĩ nàng ta muốn gì?"},{"who":"A","text":"{Xung} không đoán được. Chỉ biết nếu đi một mình, {xung} sợ bị ép nhận điều gì đó."},{"who":"me","text":"{Xung} đi cùng {goi}, ngồi cạnh {goi} suốt buổi trà. Có {xung} ở đó, {B} sẽ phải chừng mực."}]}},
{"id":"j72:bo_chung","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau buổi trà chiều, trong góc hành lang vắng, hai bóng người đứng thật gần mà nói rất khẽ."},{"who":"A","text":"{B} nắm được chút sơ hở của {xung}, cứ đem ra dọa. {Goi} có mặt mũi, nói với nàng giúp {xung}."},{"who":"me","text":"Sơ hở thế nào mà khiến {goi} sợ đến vậy? Nói ra {xung} mới biết cách tính."},{"who":"A","text":"Chuyện không lớn nhưng nếu lộ ra thì rất khó coi. {B} cứ nhắc mãi, {xung} ăn không ngon ngủ không yên."},{"who":"me","text":"{Xung} sẽ nói chuyện với {B}, nghe nàng ra điều kiện gì rồi mới tính."}]}},
{"id":"j72:loi_thoi","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân cung buổi sáng, hoa còn đọng sương, người mới vào cung đứng lẻ loi bên bàn trà trống."},{"who":"A","text":"{Xung} vào cung chưa có ai thân. {Xung} nghe {B} cũng hiền lành. {Goi} mời giúp một buổi trà ba người được không?"},{"who":"me","text":"Mới vào cung mà đã muốn kết thân, thật dễ thương. {Goi} nghe {B} hiền từ ai?"},{"who":"A","text":"Từ vài lời thiên hạ. {Xung} không dám đến nhà người ta mà mời trước, sợ bị cười."},{"who":"me","text":"{Xung} mời {B}, rồi bày trà và cùng nhau chuyện trò. Ba người ngồi chung, tình sẽ gần hơn."}]}},
{"id":"j72:don_ta","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió từ hành lang thổi vào cung Hoàng hậu, tấm rèm khẽ lay như lời đồn chưa dứt."},{"who":"A","text":"Có người thưa với {xung} rằng {B} oán {xung}. {Goi} hỏi dò xem thật hay giả."},{"who":"me","text":"Lời thưa ấy có bằng chứng gì không? Nếu chỉ là lời đồn, nàng ấy sẽ oan."},{"who":"A","text":"Chưa có bằng chứng, chỉ là người ta nói. Vì thế {xung} cần người khéo hỏi, mà không làm {B} hoảng."},{"who":"me","text":"{Xung} sẽ trò chuyện với {B}, nghe thật lòng nàng rồi báo lại. Thật hay giả, {xung} cũng báo đúng như thấy."}]}},
{"id":"j72:off_hoa","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng quyền thần, hai tấm sớ cũ xếp chồng lên nhau, cả hai đều là lời tố cáo qua lại."},{"who":"A","text":"Nhà lão phu với nhà đối đầu đấu đá mãi, triều đình rối ren. {Goi} ở trong cung, gửi lời khuyên giải giúp."},{"who":"me","text":"Hai nhà đối đầu lâu năm, nay lão đại nhân muốn hòa giải. Lòng ấy đáng quý, nhưng bên kia có chịu nghe không?"},{"who":"A","text":"Lão phu không chắc. Nhưng đấu mãi thì cả hai cùng thiệt, triều đình chẳng ai được lợi."},{"who":"me","text":"{Xung} viết thư khuyên giải hai nhà, rồi đợi hồi âm. Khi nào có tin, {xung} sẽ báo."}]}},
{"id":"j72:mat_tram","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn trang điểm cung {A}, hộp nhỏ để mở, chỗ đặt đôi hoa tai ngọc nay trống rỗng."},{"who":"A","text":"Đôi hoa tai ngọc mẫu thân {xung} để lại biến mất mấy hôm nay. {Xung} không dám làm to chuyện. {Goi} tinh ý, giúp {xung} tìm."},{"who":"me","text":"Đôi hoa tai ấy đối với {goi} là thứ gì? Ngày thường {goi} cất nó ở đâu?"},{"who":"A","text":"Trong hộp nhỏ ở bàn trang điểm. Chỉ người trong cung {xung} mới vào được, nên {xung} sợ nghi oan ai."},{"who":"me","text":"Để {xung} hỏi chuyện người hầu cung {goi} trước, nhẹ nhàng thôi, khỏi làm tổn thương ai."}]}},
{"id":"j72:mat_tram2","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng gọi từ cung Hoàng hậu truyền xuống, người nhận lời gọi tay run run, sắc mặt tái đi."},{"who":"A","text":"Chuyện mất đồ đến tai Hoàng hậu, người cho gọi {xung} hỏi. {Goi} là người biết rõ nhất, đi cùng {xung} được không?"},{"who":"me","text":"Hoàng hậu gọi hỏi tức là chuyện đã thành lớn. {Goi} có điều gì cần nói riêng với {xung} trước không?"},{"who":"A","text":"{Xung} chỉ sợ nói không rõ, bị hiểu lầm. Có {goi} bên cạnh làm chứng, {xung} mới dám thưa."},{"who":"me","text":"{Xung} đi cùng {goi}, nói đúng những gì {xung} biết. Sự thật thì không cần lời hoa mỹ."}]}},
{"id":"j72:tai_mat","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm yên, trong phòng nhỏ cung ngươi, cung nữ khép cửa thật khẽ rồi kề sát bên đèn."},{"who":"A","text":"{Goi}, có người đang nắm chuyện riêng của cung mình. Chắc có kẻ làm tai mắt cho ai đó. Để {xung} cùng {goi} dò xét."},{"who":"me","text":"Chuyện riêng bị lộ ra ngoài, ngươi nghi ai chưa?"},{"who":"A","text":"{Xung} chưa dám nghi ai. Nhưng việc nào nói trong cung này, chẳng bao lâu đã nghe ở cung khác, nên chắc chắn có kẻ lọt."},{"who":"me","text":"Ngươi nói đúng. Ta không vội kết tội, chỉ lặng lẽ dò xét kẻ hầu trong cung, xem ai có chuyện bất thường."}]}},
{"id":"j72:bac_mat","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới chiếc gối cũ, chỗ giấu túi bạc nay trống không, nếp vải còn hằn dấu vật từng nằm đó."},{"who":"A","text":"Số bạc dành dụm cả năm của {xung} để dưới gối, giờ mất sạch. {Goi} làm chủ cho {xung}."},{"who":"me","text":"Bạc dành dụm cả năm lại mất, ngươi chắc đã khóc mấy đêm. Ngươi giấu ở đó ai biết?"},{"who":"A","text":"Chỉ vài người trong phòng. {Xung} không dám nghi ai, nhưng bạc mất rồi, lòng đau lắm."},{"who":"me","text":"Ta sẽ làm chủ cho ngươi. Ta hỏi từng người trong cung, tra cho ra manh mối."}]}},
{"id":"j72:hang_lau","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho phụ của cung, mấy cuộn lụa nằm kín sau tấm vải thô, đường chỉ lạ lẫm không giống hàng cung."},{"who":"A","text":"Nô tài tham chút lời, mang ít lụa lậu vào bán. Xin {goi} cho cất tạm trong kho cung mấy hôm."},{"who":"me","text":"Lụa lậu mà đem vào cung là phạm cấm. Ngươi không sợ liên lụy cả ta sao?"},{"who":"A","text":"Nô tài biết lỗi, chỉ một lần thôi. Bán xong nô tài xin chia chút lời tạ ơn {goi}."},{"who":"me","text":"Nói thế là muốn kéo ta vào chuyện này. Ta suy nghĩ đã, ngươi đừng hứa hẹn gì vội."}]}},
{"id":"j72:chuoc_sv","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước hiệu cầm đồ, chiếc vòng cũ còn nằm sau quầy gỗ, sắc bạc ngả màu theo năm tháng."},{"who":"A","text":"Nô tài túng quá, lỡ đem cầm chiếc vòng mẹ để lại, giờ hiệu cầm đồ sắp bán mất. {Goi} cho nô tài vay ít bạc chuộc về."},{"who":"me","text":"Vòng của mẫu thân mà đem cầm, hẳn ngươi bí lắm mới làm vậy. Ngươi cần bao nhiêu?"},{"who":"A","text":"Đủ để chuộc vòng ra, nô tài sẽ làm việc trả dần. Mất vòng ấy rồi, nô tài không còn gì của mẹ."},{"who":"me","text":"Ta cho ngươi vay, cầm vòng ra rồi ta gửi trả tận tay. Từ nay đừng đem vật của mẹ đi cầm nữa."}]}},
{"id":"j72:doi_thuoc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho thuốc Thái y viện, hộc đựng nhân sâm nằm trống hơn nửa, lớp bụi nhạt còn in dấu tay lấy."},{"who":"A","text":"Nhân sâm trong kho hụt hẳn mấy cân. Thần không dám báo khi chưa rõ. {Goi} tra giúp thần."},{"who":"me","text":"Nhân sâm quý, ai cũng thèm. Kho này có những ai ra vào, thái y có nhớ không?"},{"who":"A","text":"Chỉ vài người, nhưng chìa khóa cũng có lúc rời tay thần. Thần không dám nghi ai, chỉ mong có một cuộc tra kín đáo."},{"who":"me","text":"Để {xung} tra cho rõ ngọn ngành, nhưng nhẹ nhàng, tránh để thái y và người kho mang tiếng oan."}]}},
{"id":"j72:dem_chung","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giờ Tý, ánh trăng rọi lên hòn non bộ ở vườn ngự, bóng cây rung rinh như có ai nấp sau tảng đá."},{"who":"A","text":"{Goi}, {xung} hầu chủ đã chán cảnh bị hành hạ. Chủ {xung} làm nhiều chuyện sau lưng {goi}. Giờ Tý, ở hòn non bộ vườn ngự, {xung} trao vật chứng."},{"who":"me","text":"Vật chứng gì? Ngươi biết phản chủ là đại tội, nếu bị phát hiện thì chẳng yên thân."},{"who":"A","text":"{Xung} biết, nhưng lòng không thể chịu nổi nữa. {Xung} chỉ xin {goi} đến một mình, đừng để ai theo."},{"who":"me","text":"Ta sẽ đến đúng giờ Tý, chỉ một mình. Nhưng ngươi nhớ, chuyện này không được để ai biết."}]}},
{"id":"j72:rsv_tin","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên vắng, người cung nữ cúi đầu, tay nắm vạt áo vá chằng vá đụp."},{"who":"A","text":"{Xung} hầu chủ mà chẳng được đối đãi tử tế. {Xung} kể {goi} nghe chuyện bên ấy, chỉ xin {goi} nói với Tổng quản cho {xung} được thưởng Tết như người khác."},{"who":"me","text":"Thưởng Tết ai cũng có, riêng ngươi bị thiếu, chắc ngươi tủi lắm. Chuyện bên ấy thế nào?"},{"who":"A","text":"{Xung} sẽ kể hết. Chỉ xin {goi} nể tình mà giúp {xung} một lần, đừng để {xung} thiệt thòi mãi."},{"who":"me","text":"Ngươi kể ta nghe, ta sẽ nói với Tổng quản ở Kính sự phòng. Ngươi giúp ta một việc, ta giúp ngươi một việc."}]}},
{"id":"j72:tra_emp","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya trong ngự thư phòng, đèn dầu chập chờn, Hoàng thượng dụi mắt bên chồng tấu chưa phê xong."},{"who":"A","text":"Trẫm mất ngủ mấy đêm. Hôm trước {goi} nói ở quê nàng sao trà cách khác, ngủ ngon lắm. Sao cho trẫm một ít."},{"who":"me","text":"Trà sao theo lối quê {xung} lá thơm dịu, uống buổi tối an thần. Hoàng thượng muốn dùng thử sao?"},{"who":"A","text":"Trẫm đã uống đủ loại thuốc mà không khá. Một chén trà quê có khi lại hiệu nghiệm."},{"who":"me","text":"{Xung} xin sao trà thật kỹ, từng mẻ nhỏ, để Hoàng thượng uống được ngon giấc."}]}},
{"id":"j72:emp_co","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, bàn cờ ngọc bày giữa án, quân đen quân trắng sáng lên dưới ánh đèn."},{"who":"A","text":"Việc triều làm trẫm bực bội. {Goi} mang bàn cờ đến, đánh với trẫm một ván."},{"who":"me","text":"Bàn cờ có thể làm lòng người nhẹ đi. Hoàng thượng muốn {xung} đánh thật hay đánh để giải khuây?"},{"who":"A","text":"Đánh thật, trẫm không thích người nhường. Thắng thua gì cũng được, chỉ cần có người đối diện."},{"who":"me","text":"{Xung} xin đánh hết sức. Thua thì {xung} cũng thấy vui, vì ván cờ này làm Hoàng thượng bớt phiền."}]}},
{"id":"j72:so_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm trong ngự thư phòng, một tập tấu chương đóng dấu khẩn đặt riêng trên khay lụa."},{"who":"A","text":"Bản tấu này trẫm muốn mẫu hậu xem. {Goi} mang sang Đức Thọ cung, đừng để ai khác cầm."},{"who":"me","text":"Tấu chương khẩn mà Hoàng thượng giao tận tay {xung}, {xung} xin giữ thật kín."},{"who":"A","text":"Việc triều đình đang cần Thái hậu xem. Trẫm tin {goi}, nên mới không giao người khác."},{"who":"me","text":"{Xung} xin mang tận tay Thái hậu, không qua tay ai. Hoàng thượng yên tâm."}]}},
{"id":"j72:tho_te","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm trong ngự thư phòng, giấy vàng đã trải, nghiên mực mới mài vẫn còn thơm."},{"who":"A","text":"Lễ tế trời đầu năm trẫm muốn có bài văn tế mới. {Goi} thơ hay, viết cho trẫm một bài."},{"who":"me","text":"Lễ tế trời trọng đại, văn tế không thể sai một chữ. Hoàng thượng muốn giọng văn trang nghiêm hay thanh nhã?"},{"who":"A","text":"Trang nghiêm mà không nặng nề, cầu cho dân an quốc thái. Trẫm chán những bài khuôn sáo mọi năm."},{"who":"me","text":"{Xung} xin làm một bài, lời thành khẩn, câu chữ chọn lọc. Làm xong sẽ dâng Hoàng thượng đọc trước."}]}},
{"id":"j72:an_xa","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cửa sổ ngự thư phòng, mưa nhẹ rơi, Hoàng thượng đứng nhìn sổ tên người bị phạt trải trên án."},{"who":"A","text":"Mẫu hậu ốm lâu. Trẫm muốn ân xá một số cung nhân bị phạt để cầu phúc. {Goi} hiểu chuyện hậu cung, soạn giúp trẫm."},{"who":"me","text":"Ân xá để cầu phúc cho Thái hậu là việc nhân đức. Hoàng thượng muốn xá những ai?"},{"who":"A","text":"Những ai tội nhẹ, hoặc bị phạt oan. {Goi} xét kỹ, đừng để kẻ đáng phạt thoát tội."},{"who":"me","text":"{Xung} xin xét từng người, soạn danh sách rồi dâng Hoàng thượng định đoạt."}]}},
{"id":"j72:qua_tet","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm, trên bàn đặt chồng danh mục lễ vật, mấy hộp ngọc đã mở mà chưa hộp nào vừa ý."},{"who":"A","text":"Tết đến, năm nào trẫm cũng dâng mẫu hậu ngọc, người xem mãi cũng chán. {Goi} chọn giúp trẫm món gì người thích."},{"who":"me","text":"Thái hậu thích điều gì, Hoàng thượng đã biết chưa? Có khi người thích những thứ giản dị."},{"who":"A","text":"Trẫm bận chính sự, chưa từng hỏi kỹ. {Goi} gần gũi với người, chọn thứ gì cho đúng ý."},{"who":"me","text":"{Xung} sẽ tìm hiểu ý Thái hậu, rồi chọn món quà hợp lòng người. Tết này có lẽ là cái Tết người nhớ lâu."}]}},
{"id":"j72:bien_tin","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách quyền thần, tấm bản đồ biên ải trải rộng, quân cờ đỏ chấm dày ở một góc."},{"who":"A","text":"Biên cương bất ổn, lão phu ở xa không biết ý Hoàng thượng thế nào. {Goi} hầu cận, dò giúp một lời."},{"who":"me","text":"Ý Hoàng thượng về biên ải là việc trọng đại. Lão đại nhân muốn biết điều gì cụ thể?"},{"who":"A","text":"Người nghiêng về hòa hay chiến. Lão phu cần biết để định liệu việc nhà, việc quân."},{"who":"me","text":"{Xung} sẽ tìm dịp nghe ngóng, chọn lúc Hoàng thượng thư thái mà hỏi dò, rồi báo lại cho đại nhân."}]}},
{"id":"j72:kho_lua","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới trời xám, ngoài kho lúa chỉ còn vài bao rỗng nghiêng ngả, dân mấy trấn xếp hàng dài trước cổng."},{"who":"A","text":"Kho lúa còn ít, dân mấy trấn đói. Sớ xin điều lúa của lão phu chưa được phê. {Goi} nhân lúc ngài vui, thưa giúp."},{"who":"me","text":"Dân đói là việc cấp bách, sao sớ chưa được phê? Có ai chặn lại không?"},{"who":"A","text":"Lão phu không rõ, chỉ biết sớ nằm mãi trên án. Mỗi ngày chậm là thêm người chết đói."},{"who":"me","text":"{Xung} sẽ chọn lúc Hoàng thượng thư thái, thưa chuyện kho lúa. Lòng người lúc vui dễ mềm."}]}},
{"id":"j72:ao_bien","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió bấc rít qua mái ngói, nơi biên ải xa tít tắp, quân sĩ còn mặc áo mỏng chờ áo bông gửi tới."},{"who":"A","text":"Gió bấc đã về biên ải mà áo bông chưa tới. {Goi} có thể cùng các phi tần góp may, rồi tâu lên Hoàng thượng."},{"who":"me","text":"Quân sĩ chịu rét nơi biên cương, lòng người trong cung sao yên được. Lão đại nhân muốn bao nhiêu áo?"},{"who":"A","text":"Càng nhiều càng tốt, mỗi chiếc là một mạng người được ấm. Lão phu chỉ lo chậm trễ thì không kịp."},{"who":"me","text":"{Xung} sẽ rủ các phi tần, chia nhau cắt may. Áo xong sẽ tâu lên Hoàng thượng để chuyển ra biên."}]}},
{"id":"j72:su_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm muộn trong phòng sứ quán, ánh đèn rọi lên bức thư niêm kín, sáp đỏ còn nguyên dấu ấn."},{"who":"A","text":"Biên cương căng thẳng, quốc thư cầu hòa bị quan Lễ bộ giữ lại. Thần có bức thư riêng, xin {goi} chuyển tận tay Hoàng thượng."},{"who":"me","text":"Thư không qua Lễ bộ mà giao thẳng ngự tiền, sứ thần có biết điều này nguy hiểm đến đâu không?"},{"who":"A","text":"Thần biết, nhưng nếu không tới được tay Hoàng thượng, chiến sự có thể nổ ra. Thần chỉ còn cách này."},{"who":"me","text":"Việc này liên quan đến cả hai nước, {xung} xin nhận. {Xung} sẽ chọn lúc Hoàng thượng thư thái mà dâng thư."}]}},
{"id":"j72:so_hl","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách nhà quyền thần, tờ sớ cuộn tròn nằm giữa bàn, góc giấy nhàu vì bị giữ lâu."},{"who":"A","text":"Nhà lão phu thế suy, sớ tấu bị kẻ khác chặn ở Thông chính ty. {Goi} có thể đưa nó đến tay Hoàng thượng."},{"who":"me","text":"Sớ bị chặn ở Thông chính ty tức là có người không muốn Hoàng thượng đọc. Trong sớ là chuyện gì?"},{"who":"A","text":"Lời tâu về việc nhà, nhưng cũng liên quan đến chuyện triều. Lão phu già rồi, không muốn đấu đá, chỉ cần sớ đến tay người."},{"who":"me","text":"{Xung} sẽ tìm cách đặt sớ lên án thư Hoàng thượng. Lão đại nhân yên tâm chờ tin."}]}},
{"id":"j72:so_khen","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng quyền thần, tờ phú viết dở nằm giữa hai cây bút lông, nét mực vừa khô."},{"who":"A","text":"Biên cương yên ổn, nhà lão phu muốn dâng bài phú mừng. {Goi} văn hay, nhuận sắc giúp."},{"who":"me","text":"Bài phú mừng biên ải yên ổn tức là mừng cho cả triều. Lão đại nhân muốn lời lẽ thế nào?"},{"who":"A","text":"Trang trọng mà không sáo, khen quân mà không nịnh. Lão phu già, nét bút không còn mượt như xưa."},{"who":"me","text":"{Xung} xin nhuận sắc từng câu, giữ lấy cái hồn của lão đại nhân, chỉ gọt đi những chỗ chưa trơn."}]}},
{"id":"j72:tham_o","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng quyền thần, hai sổ sách đặt cạnh nhau, một sổ của nhà mình, một sổ chưa biết của nhà ai."},{"who":"A","text":"Nhà của {B} đối đầu với nhà lão phu đã lâu. {Goi} ở trong cung, dò giúp lão phu xem sổ sách nhà ấy có sạch không."},{"who":"me","text":"Dò sổ sách nhà người khác là việc nhạy cảm, nếu không sạch thì thành án, mà nếu sạch thì thành thù."},{"who":"A","text":"Lão phu chỉ muốn biết, không định làm gì ngay. Biết để phòng, không phải để hại."},{"who":"me","text":"{Xung} sẽ dò qua đường khác, tuyệt không để {B} biết. Nhưng nếu thật có chuyện, {xung} sẽ báo đúng sự thật."}]}},
{"id":"j72:off_bac","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng khách quyền thần, hộp lễ mọn đặt ngay ngắn trên bàn, buộc lụa đỏ, tuyệt không phô trương."},{"who":"A","text":"Thấy {goi} chi tiêu chật vật, lão phu có chút lễ mọn. Con trai lão phu thi đỗ mà chưa được bổ dụng. {Goi} nhắc giúp một câu."},{"who":"me","text":"Lễ mọn mà đổi lấy một lời nhắc, lão đại nhân tính thật kỹ. Con trai đại nhân đỗ khoa nào?"},{"who":"A","text":"Đỗ đàng hoàng, chỉ thiếu người dẫn đường. Lão phu không dám nhờ vả lớn, chỉ một câu nhắc tên là đủ."},{"who":"me","text":"Nhận lễ tức là nợ một ân và xen vào việc triều chính. {Xung} phải nghĩ kỹ rồi mới trả lời."}]}},
{"id":"j72:off_con","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung ngươi, buổi chiều lặng gió, thiệp gửi từ phủ quan vừa đến, nét chữ thấm đẫm lo lắng của người cha."},{"who":"A","text":"Con gái lão phu phẩm vị thấp, vào cung còn non dại. Mong {goi} chỉ bảo, che chở cho nó."},{"who":"me","text":"Con gái lão đại nhân mới vào cung, lòng còn bỡ ngỡ. {B} là người thế nào, đại nhân có dặn dò gì không?"},{"who":"A","text":"Nó hiền, ít nói, lại thật thà. Lão phu chỉ sợ nó bị người ta bắt nạt, mà lão phu thì chẳng thể bước vào cung."},{"who":"me","text":"{Xung} sẽ sang thăm {B}, rồi mời nàng sang cung chơi, chỉ nàng những điều cần biết để tự vệ."}]}},
{"id":"j72:ak_bien","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng hoàng tự, bộ binh thư bản hiếm được dâng lên bằng cả hai tay, bìa lụa còn mới."},{"who":"A","text":"Biên cương nguy, con muốn ra trận rèn luyện mà phụ hoàng chưa cho. Con biếu {goi} bộ binh thư bản hiếm, xin {goi} nói giúp con."},{"who":"me","text":"Ra biên ải là chuyện nguy hiểm, không phải trò rèn luyện. Con nghĩ kỹ chưa?"},{"who":"A","text":"Con nghĩ rất kỹ. Con không muốn mãi ở trong cung đọc sách, con muốn biết thế nào là cầm quân."},{"who":"me","text":"Chí con đáng nể. Bộ sách này {xung} giữ, còn lời nói đỡ thì {xung} xin cân nhắc, vì phụ hoàng con có lý do của người."}]}},
{"id":"j72:gioi_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Đức Thọ cung, người vào cung đã lâu đứng chờ ở bậc thềm, mấy lần định bước rồi lại thôi."},{"who":"A","text":"{Xung} vào cung đã lâu mà Thái hậu chưa nhìn {xung} lấy một lần. {Goi} được Thái hậu thương, dắt {xung} đi cùng được không?"},{"who":"me","text":"Mấy lần {goi} định sang mà vẫn chưa dám, đúng không? Thái hậu rộng lượng, không khó đến thế."},{"who":"A","text":"{Xung} sợ lỡ lời, sợ làm người phật ý. Có {goi} đi cùng, {xung} mới can đảm."},{"who":"me","text":"{Xung} dắt {goi} sang Đức Thọ cung, thưa với Thái hậu cho trọn lễ. Cứ giữ lòng thành, Thái hậu sẽ nhớ."}]}},
{"id":"j72:hh_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung Hoàng hậu, chén trà dâng Thái hậu đã châm nhưng chưa ai mang sang, hơi nóng mỏng bay lên rồi tan."},{"who":"A","text":"Thái hậu dạo này lạnh nhạt với {xung}. {Xung} có lời muốn thưa mà không tiện tự đi. {Goi} chuyển lời giúp, lựa lúc Thái hậu vui."},{"who":"me","text":"Hoàng hậu muốn thưa điều gì với Thái hậu, {xung} xin nghe trước để chuyển cho đúng."},{"who":"A","text":"Chỉ là lời hiếu kính, mong người đừng giận. Nhưng {xung} sợ nói không khéo lại thành thêm giận."},{"who":"me","text":"{Xung} sẽ chọn lúc Thái hậu vui mà thưa, giữ nguyên lòng của Hoàng hậu, không thêm không bớt."}]}},
{"id":"j72:th_nhac_hh","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, tiếng lá trúc xào xạc ngoài cửa, Thái hậu hạ giọng như sợ vách có tai."},{"who":"A","text":"Ai gia biết một người hầu bên Hoàng hậu làm tai mắt cho kẻ khác. {Goi} khéo léo nhắc nàng, đừng để nàng biết ai gia bảo."},{"who":"me","text":"Thái hậu biết người hầu ấy là ai không? Nếu nhắc sai người thì thành oan."},{"who":"A","text":"Ai gia biết, nhưng không muốn nói ra. Hoàng hậu thông minh, chỉ cần một lời gợi ý là nàng sẽ tự nhìn ra."},{"who":"me","text":"{Xung} sẽ nhắc Hoàng hậu thật khéo, như một lời quan tâm bình thường, tuyệt không nhắc đến Thái hậu."}]}},
{"id":"j72:th_tram","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên khay lụa ở Đức Thọ cung, cây trâm phượng lấp lánh dưới nắng, đuôi phượng khảm ngọc mềm mại."},{"who":"A","text":"Cây trâm phượng này ai gia ban cho {goi}. {Goi} hay sang Càn Ninh cung, để ý xem Hoàng hậu dạo này thế nào, rồi kể ai gia nghe."},{"who":"me","text":"Trâm của Thái hậu ban, {xung} xin nhận. Nhưng để ý Hoàng hậu là việc nhạy cảm, Thái hậu muốn biết điều gì?"},{"who":"A","text":"Chỉ là tâm trạng của nàng, ai đến thăm, nàng nói gì. Ai gia già, không muốn nghe tai mắt người khác."},{"who":"me","text":"Thái hậu đã tin, {xung} xin làm đôi mắt của người. {Xung} nhớ ơn trâm phượng này."}]}},
{"id":"j72:tin_doi","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc yên tĩnh của hành lang cung, người cung phi nói khẽ như đổi một bí mật lấy một bí mật."},{"who":"A","text":"{Xung} cho {goi} biết một tin trong cung. Đổi lại, {goi} nói đỡ {xung} vài câu trước Thái hậu nhé, người chẳng ưa {xung}."},{"who":"me","text":"Tin gì mà {goi} dám đổi lấy lời nói đỡ? Phải đáng giá thì {xung} mới nhận."},{"who":"A","text":"Tin liên quan đến an nguy của {goi}, không nhỏ đâu. Đổi lại chỉ cần một lời với Thái hậu, {xung} không đòi gì hơn."},{"who":"me","text":"Nghe thì có lý. {Xung} sẽ nói đỡ trước Thái hậu, nhưng {goi} cũng phải giữ lời."}]}},
{"id":"j72:quat_rv","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn họa, cây quạt tròn trắng muốt mới căng, chưa một nét bút nào, như chờ người đặt hồn lên."},{"who":"A","text":"Hoàng thượng lâu rồi chẳng nhìn đến {xung}. {Xung} vụng tay, {goi} vẽ giúp {xung} cây quạt dâng ngài được không?"},{"who":"me","text":"Hoàng thượng chưa nhìn đến, chắc {goi} buồn lắm. Quạt dâng người, {goi} muốn vẽ gì?"},{"who":"A","text":"Một cành mai, hay vài nét trúc, miễn là có chút tình ý. {Xung} muốn ngài nhận ra lòng {xung}."},{"who":"me","text":"{Xung} vẽ cho {goi}, rồi cùng nghĩ xem đề tên ai trên quạt, vì chữ đề cũng là tình ý."}]}},
{"id":"j72:ksp_xem","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn mờ ở Kính sự phòng, sổ thị tẩm nằm trên án, mực đen khô đọng thành từng hàng người được gọi tên."},{"who":"A","text":"{Xung} muốn biết vì sao Hoàng thượng lật thẻ người khác mà không lật thẻ {xung}. {Goi} quen người Kính sự phòng, xem giúp {xung}."},{"who":"me","text":"Xem sổ thị tẩm là chuyện phạm lễ. {Goi} không sợ nếu bị phát giác sẽ liên lụy sao?"},{"who":"A","text":"{Xung} biết, nhưng không biết chỗ sai ở đâu thì làm sao sửa? Một lần thôi, {xung} xin hứa."},{"who":"me","text":"{Xung} không hứa chắc, chỉ nói sẽ tìm cách khéo. Lẻn xem là hiểm, nhưng {xung} hiểu {goi} đang nghĩ gì."}]}},
{"id":"j72:tu_nu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sảnh cung Hoàng hậu, mấy phi tần mới đứng thành hàng, bước đi còn lúng túng chưa thuộc nhịp."},{"who":"A","text":"Mấy nàng còn vụng lễ nghi. {Xung} giao {goi} chỉ bảo."},{"who":"me","text":"Lễ nghi trong cung nhiều điều, {xung} xin dạy từng điều một, từ cách cúi chào đến cách thưa chuyện."},{"who":"A","text":"Tốt, dạy cho tử tế rồi đưa các nàng sang ra mắt. {Xung} không muốn ai nói cung này thiếu quy củ."},{"who":"me","text":"{Xung} sẽ dạy cẩn thận, rồi đưa các nàng sang ra mắt Hoàng hậu cho đúng lễ."}]}},
{"id":"j72:vay_bac","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa chiều, trong cung ngươi, chiếc túi nhỏ đặt trên bàn, chưa ai chạm đến mà nặng như lời ngại ngùng."},{"who":"A","text":"{Xung} thấy {goi} dạo này túng. {Xung} có ít bạc, {goi} cầm tạm chỗ bạc này mà xoay xở, khi nào có thì trả."},{"who":"me","text":"Nàng chu đáo như vậy, {xung} thật cảm kích. Nhưng nhận bạc là nợ ân, {goi} có nghĩ vậy không?"},{"who":"A","text":"Nếu {goi} thấy phải trả thì cứ trả. {Xung} chỉ không muốn nhìn người khác chật vật mà đứng yên."},{"who":"me","text":"Vậy {xung} xin nhận, và hẹn trả trước hạn, kèm một lời cảm tạ cho thật xứng."}]}},
{"id":"j72:rv_ngheo","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung {A}, mấy cái hộp trống nằm kề nhau, ví bạc mỏng như tờ giấy."},{"who":"A","text":"{Xung} còn ít bạc, lương tháng chưa phát mà phải lo lót người hầu. {Goi} cho {xung} vay ít bạc được không?"},{"who":"me","text":"Lương chưa phát mà lo lót đủ thứ, chắc {goi} đang khó xử. {Goi} cần bao nhiêu?"},{"who":"A","text":"Chỉ đủ qua mấy hôm, đến kỳ lương {xung} sẽ trả. {Xung} chỉ ngại nói ra, sợ mất mặt."},{"who":"me","text":"Cho vay không khó, {xung} chỉ mong {goi} đừng ngại. Có việc gì khó khăn cứ nói thẳng."}]}},
{"id":"j72:rv_tho","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nắng len qua cửa sổ cung {A}, trên bàn thơ nháp chất một chồng, câu cuối còn bỏ trống."},{"who":"A","text":"Yến thưởng hoa sắp tới, {xung} vụng văn, nghĩ mãi không ra câu kết. {Goi} giúp {xung}."},{"who":"me","text":"Câu kết khó nhất, vì nó phải gói được ý cả bài. Bài thơ ấy {goi} định ca ngợi điều gì?"},{"who":"A","text":"Hoa nở và lòng người, nhưng cứ viết ra là sáo. {Xung} muốn một câu khiến người nghe thấy bồi hồi."},{"who":"me","text":"{Xung} ngồi cùng {goi} ở cung nghĩ thơ. Hai người nghĩ, có khi câu hay sẽ tự đến."}]}},
{"id":"j72:rv_huong","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn hương ở cung {A}, mấy gói hương thảo nằm bên lò nhỏ đã nguội, mùi trầm thoảng bay."},{"who":"A","text":"Mấy đêm nay {xung} trằn trọc không ngủ được, người cứ rã rời. {Goi} khéo điều hương, phối giúp {xung} một túi."},{"who":"me","text":"Mất ngủ lâu ngày thì sắc diện cũng kém đi. {Goi} thích hương nào?"},{"who":"A","text":"Hương dịu, đừng quá nồng. {Xung} sợ mùi nặng lại thêm nhức đầu."},{"who":"me","text":"{Xung} phối túi hương an thần theo ý {goi}, xong sẽ mang sang cung {goi}, để {goi} ngủ một giấc cho trọn."}]}},
{"id":"j72:canh_thai","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm sâu, trong cung {A}, người mang thai ngồi dậy giữa chăn, tay đặt lên bụng, mắt lo lắng nhìn ra cửa sổ."},{"who":"A","text":"{Xung} mang thai, đêm nào cũng nằm mơ thấy chuyện chẳng lành. {Goi} có người tin cẩn, để mắt giúp {xung}."},{"who":"me","text":"Mơ thấy chuyện chẳng lành có khi chỉ là lo nghĩ nhiều. Nhưng cẩn thận thì không thừa."},{"who":"A","text":"{Xung} không dám tin ai ngoài {goi}. Cái thai này là tất cả những gì {xung} có."},{"who":"me","text":"{Xung} sẽ sai người tin cẩn canh quanh cung {goi} hai tuần, có gì lạ sẽ báo ngay."}]}},
{"id":"j72:giu_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung {A}, chiếc hộp thư nhỏ đặt dưới đáy tủ, nắp khép kín dưới lớp áo gấp."},{"who":"A","text":"Có người đang nắm sơ hở của {xung}, {xung} sợ bị lục soát. Trong hộp chỉ là thư nhà, nhưng người ta bới móc chữ nghĩa. {Goi} giữ hộ {xung} ít lâu."},{"who":"me","text":"Chỉ là thư nhà mà phải giấu thế này, hẳn {goi} đang bị theo dõi. Ai nắm sơ hở của {goi}?"},{"who":"A","text":"{Xung} chưa biết chắc. Chỉ biết chữ nghĩa trong thư, nếu bị hiểu sai, có thể thành tội."},{"who":"me","text":"{Xung} cất giữ hộp thư cẩn thận, khi nào {goi} yên ổn thì trả lại nguyên vẹn."}]}},
{"id":"j72:lc_ao","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lạnh lùa qua song cửa Trường Môn viện, tấm áo mỏng người ở trong đang co ro bên lò than đã tắt."},{"who":"A","text":"Gió lạnh lùa qua song cửa Trường Môn viện. Nếu còn chút tình xưa, xin gửi cho {xung} tấm áo bông."},{"who":"me","text":"Tình xưa thì {xung} vẫn nhớ. {Goi} chịu lạnh bao lâu rồi, sao không báo ai?"},{"who":"A","text":"Báo cho ai? Ở đây chẳng còn ai nghe {xung}. Một tấm áo bông thôi là đủ, {xung} không dám xin gì khác."},{"who":"me","text":"{Xung} chuẩn bị áo bông, rồi tìm cách mang vào. {Goi} cố chịu thêm vài hôm."}]}},
{"id":"j72:lc_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng tối của Trường Môn viện, lá thư viết bằng mực đã nhạt, nét chữ nghiêng vì tay run."},{"who":"A","text":"{Xung} bị đày vào đây, không ai nghe {xung} nói. Nếu còn thương {xung}, chuyển giúp bức thư này đến tay Hoàng thượng."},{"who":"me","text":"Thư kêu oan gửi thẳng lên Hoàng thượng, nếu bị bắt gặp thì tội rất nặng. {Goi} có chắc mình bị oan không?"},{"who":"A","text":"{Xung} chắc. {Xung} chỉ cần một lần được nói, không cầu được tha, chỉ cầu được nghe."},{"who":"me","text":"{Xung} sẽ tìm cách đưa thư đến tay Hoàng thượng. Chuyện này giữ kín, đừng nói với ai."}]}},
{"id":"j72:ak_me","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa cung của mẫu thân, đứa trẻ đứng ngoài hiên nhìn vào, đã mấy hôm không được bước vào."},{"who":"A","text":"Con lỡ lời làm mẫu thân giận, mấy hôm nay không cho con vào thỉnh an. {Goi} nói giúp con một lời."},{"who":"me","text":"Lỡ lời thế nào mà mẫu thân con giận đến vậy? Con kể thật cho {xung} nghe."},{"who":"A","text":"Con nói điều không nên nói. Con biết lỗi rồi, nhưng không dám tự xin. Con nhớ mẫu thân lắm."},{"who":"me","text":"Con biết lỗi là điều đáng quý. {Xung} sẽ nói giúp, chọn lúc mẫu thân con nguôi giận."}]}},
{"id":"j72:mama_nghi","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng ma ma già, tấm áo cũ giặt mòn vải, đôi tay chai sạn run run đặt trên đầu gối."},{"who":"A","text":"{Goi}, {xung} hầu hạ trong cung đã mấy chục năm, chân tay rã rời. {Goi} xin giúp {xung} về Tây uyển dưỡng già."},{"who":"me","text":"Mấy chục năm hầu hạ, bà xứng đáng được nghỉ ngơi. Bà có muốn về hẳn không?"},{"who":"A","text":"Muốn, nhưng chưa dám xin. Người như {xung} ở trong cung lâu rồi chẳng ai nhớ đến, chỉ mong còn được mấy năm yên tĩnh."},{"who":"me","text":"{Xung} sẽ hỏi Kính sự phòng, xin cho bà về Tây uyển dưỡng già. Bà cứ yên tâm."}]}},
{"id":"j72:maid_vay","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn nhỏ, người cung nữ đặt túi bạc dành dụm xuống bàn, tay vẫn còn do dự."},{"who":"A","text":"{Goi} đang túng, {xung} có dành dụm được ít bạc. {Goi} cứ cầm, khi nào có lương thì trả {xung}."},{"who":"me","text":"Bạc dành dụm của ngươi là mồ hôi nước mắt cả năm, sao ta nhận được?"},{"who":"A","text":"Không sao đâu, {xung} theo {goi} bấy lâu, chỉ muốn {goi} qua cơn khó. Trả lúc nào cũng được."},{"who":"me","text":"Ta nhận, nhưng sẽ trả trước hạn. Ngươi có lòng như vậy, ta nhớ mãi."}]}},
{"id":"j72:sv_luong","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối tháng, tiếng bạc phát lương vang trong sân cung, người hầu lặng lẽ xếp hàng chờ lĩnh phần mình."},{"who":"A","text":"{Xung} hầu {goi} chăm chỉ mà lương chẳng đủ gửi về nhà. {Goi} thương thì thưởng thêm chút ít."},{"who":"me","text":"Ngươi gửi về nhà bao nhiêu mà không đủ? Nhà ngươi có chuyện gì không?"},{"who":"A","text":"Cha mẹ già, em nhỏ, chỉ trông vào lương của {xung}. Một chút bạc thưởng thôi là đủ cho họ qua mùa."},{"who":"me","text":"Ngươi chăm chỉ, ta thấy hết. Ta sẽ thưởng thêm, ngươi giữ lấy mà lo cho nhà."}]}},
{"id":"j72:dt_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc túi thơm thêu hoa nhỏ nằm trong lòng bàn tay người cung nữ, từng mũi chỉ còn thơm mùi trầm."},{"who":"A","text":"{Goi}, {B} hầu ở cung khác, chúng nô tỳ thương nhau đã lâu. {Xung} thêu túi thơm này mà không dám tự mang sang. {Goi} giúp {xung}."},{"who":"me","text":"Hai ngươi thương nhau trong cung, chuyện này không nhỏ. {Goi} tin {xung} sao?"},{"who":"A","text":"{Xung} tin {goi}. Chỉ cần {goi} trao tận tay {B}, rồi nghe nàng nói gì, {xung} chỉ mong thế."},{"who":"me","text":"{Xung} sẽ trao túi thơm cho {B} thật kín đáo, rồi mang lời nàng về cho {goi}."}]}},
{"id":"j72:dt_hen","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa sau cung tĩnh lặng, hoàng hôn buông nhẹ, người cung nữ đứng nép sau cánh cửa gỗ, mắt đỏ hoe."},{"who":"A","text":"Người thương của {xung} sắp bị điều đi xa. {Xung} chỉ xin một khắc ở cửa sau cung để từ biệt… {Goi} thương {xung}."},{"who":"me","text":"Chỉ một khắc thôi sao? Hai người thương nhau lâu chưa mà phải chia tay vội vàng?"},{"who":"A","text":"Đã lâu, nhưng chưa từng nói lời từ biệt. {Xung} chỉ muốn được nhìn mặt người ta một lần cuối."},{"who":"me","text":"Một khắc thì {xung} xin cho. Cửa sau cung {xung} giữ, {goi} cứ đi, đừng để ai thấy."}]}},
{"id":"j72:dt_che","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ban đêm trong phòng nhỏ, người cung nữ ngồi cuộn người bên cột giường, giọng nói chỉ còn là hơi thở."},{"who":"A","text":"Có người đang dò chuyện riêng của cung mình, {xung} sợ chuyện của {xung} bị lôi ra làm cớ hại {goi}. {Goi} dạy {xung} phải làm sao."},{"who":"me","text":"Chuyện riêng của ngươi, ngươi cứ nói thật, ta mới biết cách che chắn."},{"who":"A","text":"Chuyện tình của {xung} với một người, chưa ai biết ngoài {goi}. {Xung} sợ liên lụy cả cung."},{"who":"me","text":"Ngươi đừng sợ. Ta sẽ lặng lẽ che chuyện này, cũng dò xem ai đang theo dõi cung ta."}]}},
{"id":"j72:xc_mai","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân nhỏ, tà áo cung nữ khẽ rung trong gió, nàng lén liếc về phía thị vệ đứng gác ngoài cổng."},{"who":"A","text":"{Xung} sắp đến tuổi xuất cung mà chưa có ai. {Xung} thầm để ý {B}. {Goi} dò ý giúp {xung}."},{"who":"me","text":"{Goi} để ý {B} từ bao giờ? Chàng ấy biết {goi} chưa?"},{"who":"A","text":"Chưa, {xung} chỉ dám nhìn từ xa. Hễ {B} đi ngang là lòng {xung} thót lại."},{"who":"me","text":"{Xung} sẽ dò ý {B} thật khéo, không làm {goi} mất mặt. Nếu chàng cũng có ý, {xung} mới nói tiếp."}]}},
{"id":"j72:xc_uoc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa buổi chiều, người cung nữ đứng trước cửa phòng, tay siết chặt mảnh khăn thêu nhỏ như một lời hứa."},{"who":"A","text":"Người ấy muốn đợi {xung} đến ngày xuất cung rồi cưới. {Goi} xin Tổng quản ghi tên cho hai người được không ạ?"},{"who":"me","text":"Hẹn ước đến ngày xuất cung, {goi} và chàng ấy có chắc chắn không?"},{"who":"A","text":"Chắc ạ. Chàng ấy đã nói sẽ đợi, dù mấy năm cũng đợi. {Xung} chỉ cần có tên trong sổ để lòng yên."},{"who":"me","text":"{Xung} xin Tổng quản ghi tên hai người ở Kính sự phòng, để lời hẹn này có chỗ nương tựa."}]}},
{"id":"j72:xc_hoimon","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn nhỏ, người cung nữ mở chiếc rương gỗ cũ, bên trong chỉ có vài bộ áo vá."},{"who":"A","text":"Năm sau {xung} xuất cung về với người thương. {Xung} nghèo, chẳng có gì làm của hồi môn."},{"who":"me","text":"Ngươi sắp có người đón, thật đáng mừng. Nhưng không có của hồi môn thì lòng cũng chạnh."},{"who":"A","text":"{Xung} không dám xin, chỉ buồn lòng. Về nhà chồng tay trắng, {xung} sợ mẹ chồng chê."},{"who":"me","text":"Ngươi hầu ta chăm chỉ, ta góp cho ngươi chút hồi môn, để ngày về nhà chồng khỏi tủi."}]}},
{"id":"j72:dong_tam","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm Thất tịch, sao Ngưu Lang Chức Nữ lấp lánh trên mái ngói, trong phòng một sợi chỉ đỏ vừa mới được tìm thấy."},{"who":"A","text":"Đêm Thất tịch, {xung} muốn thắt nút đồng tâm gửi người thương mà thiếu chỉ đỏ. {Goi} cho {xung} xin ít."},{"who":"me","text":"Nút đồng tâm đêm Thất tịch thì phải do chính tay người thắt. Ngươi thắt được chưa?"},{"who":"A","text":"Chưa từng thắt bao giờ, chỉ biết nhìn người ta. {Xung} sợ thắt xấu quá lại thành điềm không hay."},{"who":"me","text":"Ta mua chỉ đỏ cho ngươi, rồi ngồi thắt cùng ngươi. Nút đồng tâm có xấu cũng là tình thật."}]}},
{"id":"j72:giau_cn","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nửa đêm, tiếng gõ cửa khẽ vang lên ngoài cửa cung, người cung nữ đứng đó, tay áo vén lên lộ vết thương cũ."},{"who":"A","text":"{Goi}, cứu {xung}! Chủ cũ hễ giận là đánh, lưng {xung} chưa lành vết cũ. Cho {xung} trốn tạm vài hôm."},{"who":"me","text":"Vết thương này nặng quá. Ngươi vào đây trước đã, kẻo bị người ngoài thấy."},{"who":"A","text":"{Xung} biết trốn là tội, nhưng ở lại thì không sống nổi. {Xung} chỉ xin vài hôm, rồi đi đâu cũng được."},{"who":"me","text":"Ta giấu ngươi trong cung, rồi tính xem nên đưa ngươi đi đâu cho yên ổn."}]}},
{"id":"j72:th_thanhminh","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thanh minh sắp tới, Phật đường Đức Thọ cung thơm mùi mực mới, trên án giấy trắng trải sẵn."},{"who":"A","text":"Thanh minh sắp tới, ai gia muốn một bộ kinh Kim Cang chép tay đặt trước lăng tiên đế. Nét chữ phải ngay ngắn, lòng phải thành."},{"who":"me","text":"Kinh Kim Cang chép cho lăng tiên đế, {xung} xin chép từng chữ trong tĩnh tâm. Thái hậu muốn dùng mực nào?"},{"who":"A","text":"Mực vàng, như người xưa vẫn dùng. Ai gia già rồi, chỉ muốn tiên đế thấy lòng ai gia còn nhớ."},{"who":"me","text":"{Xung} chép bằng mực vàng, đợi mực khô rồi đóng bìa, sau đó dâng sang Đức Thọ cung."}]}},
{"id":"j72:th_kinh2","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn thờ ở Đức Thọ cung, bộ kinh chép tay trước đó vẫn nằm yên, bìa lụa còn thơm mùi trầm."},{"who":"A","text":"Bộ kinh lần trước ai gia cho đặt trên bàn thờ. Chùa Hộ Quốc xin một bộ nữa, ai gia nghĩ đến {goi}."},{"who":"me","text":"Bộ kinh ấy Thái hậu vẫn còn giữ, {xung} vừa mừng vừa thẹn. Chùa Hộ Quốc cần chép quyển nào?"},{"who":"A","text":"Cả quyển thượng và quyển hạ. Chép chậm không sao, chỉ cần cẩn thận từng chữ."},{"who":"me","text":"{Xung} xin chép đủ hai quyển, rồi mang dâng lên Thái hậu để người đưa sang chùa."}]}},
{"id":"j72:th_mai","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đầu năm, mai trong vườn ngự nở rộ từng nhành, bình sứ rỗng đặt cạnh cửa sổ Đức Thọ cung."},{"who":"A","text":"Năm nào ai gia cũng cắm một bình mai đầu năm. Năm nay mắt kém rồi, {goi} chọn cành giúp ai gia."},{"who":"me","text":"Mai đầu năm là điềm lành. Thái hậu thích cành thưa hay cành dày?"},{"who":"A","text":"Cành thưa, nụ nhiều, để còn thấy hoa nở dần trong mấy ngày Tết. Ai gia thích cái dáng gầy mà ngạo nghễ của nó."},{"who":"me","text":"{Xung} ra vườn ngự chọn cành, cắm xong sẽ dâng bình sang cho Thái hậu ngắm."}]}},
{"id":"j72:th_trungcuu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiết Trùng cửu, hoa cúc vàng nở đầy trong vườn ngự, hương thoang thoảng theo gió vào tận Đức Thọ cung."},{"who":"A","text":"Tết Trùng cửu, ai gia thèm chén rượu hoa cúc như hồi còn ở nhà. {Goi} ủ giúp ai gia một vò."},{"who":"me","text":"Rượu hoa cúc ủ phải đợi ngấm mới thơm. Thái hậu còn nhớ hương rượu thuở ở nhà không?"},{"who":"A","text":"Nhớ chứ. Mẫu thân ai gia ủ mỗi năm, hương cúc quyện với nếp. Nhớ nhà đến mức nghe thấy mùi là rơi nước mắt."},{"who":"me","text":"{Xung} ra vườn hái cúc, ủ rượu, đợi ngấm rồi dâng. Mong chén rượu ấy đưa Thái hậu về lại mùa thu cũ."}]}},
{"id":"j72:hh_trungthu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh trăng Trung thu treo trên mái cung Hoàng hậu, đèn lồng bày dở, danh sách khách mời còn mở chưa gấp."},{"who":"A","text":"Yến Trung thu năm nay Hoàng thượng muốn làm lớn. {Xung} bận, nhờ {goi} lo phần bày biện và thực đơn."},{"who":"me","text":"Yến lớn thì phần bày biện rất quan trọng. Hoàng hậu muốn yến có không khí thế nào?"},{"who":"A","text":"Ấm cúng mà không bê bối, đủ lễ mà không nặng nề. Còn bạc cho yến, {xung} sợ không đủ, {goi} tính giúp."},{"who":"me","text":"{Xung} lên thực đơn, sắp chỗ ngồi, tính bạc cho vừa. Xong sẽ trình Hoàng hậu xem."}]}},
{"id":"j72:hh_trungcuu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung Hoàng hậu, khung bình phong trăm hoa dựng giữa phòng, chỗ khung giữa còn trống nguyên lụa trắng."},{"who":"A","text":"Trùng cửu là tết người già. {Xung} muốn dâng Thái hậu một bức bình phong trăm hoa, nhờ {goi} thêu khung giữa."},{"who":"me","text":"Bình phong trăm hoa cho Thái hậu chúc thọ, thật là ý đẹp. Khung giữa là chỗ quan trọng nhất."},{"who":"A","text":"Phải, nên mới giao {goi}, người khác {xung} không yên tâm. Chỉ sợ chỉ vàng không đủ."},{"who":"me","text":"{Xung} thêu khung giữa cho đẹp, thiếu chỉ vàng thì sẽ tìm. Xong sẽ mang bình phong sang Càn Ninh cung."}]}},
{"id":"j72:hh_doanngo","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đoan ngọ nắng gắt, trên bàn cung Hoàng hậu, từng gói lụa ngũ sắc cắt sẵn chồng lên nhau, kim chỉ vương vãi."},{"who":"A","text":"Đoan ngọ phải đeo túi ngũ sắc trừ tà cho trẻ nhỏ. Các hoàng tử, công chúa đông, {xung} khâu không xuể."},{"who":"me","text":"Các hoàng tử, công chúa nhiều thật, mỗi người một túi thì không ít. Hoàng hậu muốn {xung} khâu giúp bao nhiêu?"},{"who":"A","text":"Càng nhiều càng tốt. Mỗi túi là một lời cầu bình an cho các cháu."},{"who":"me","text":"{Xung} sẽ khâu túi ngũ sắc cẩn thận, rồi mang sang Càn Ninh cung để Hoàng hậu tự tay trao cho các cháu."}]}},
{"id":"j72:th_aodong","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trời trở rét, mấy ma ma già trong Đức Thọ cung co ro bên hiên, vạt áo mỏng bay theo gió."},{"who":"A","text":"Trời trở rét, mấy ma ma già trong Đức Thọ cung áo mỏng. Ai gia muốn các phi tần góp tay may áo bông."},{"who":"me","text":"Các ma ma theo Thái hậu bao năm, nay chịu rét thì thật tội. {Xung} xin cắt may một phần."},{"who":"A","text":"Ai gia không đòi nhiều, mỗi người một chiếc cũng đủ. Việc thiện nhỏ nhưng ấm lòng người."},{"who":"me","text":"{Xung} sẽ cắt may áo bông cẩn thận, rồi mang sang Đức Thọ cung trao cho các ma ma."}]}},
{"id":"j72:akf_den","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước Tết Nguyên tiêu, trong thư phòng hoàng nữ, khung đèn lồng trần tre nằm bên hộp giấy màu."},{"who":"A","text":"Tết Nguyên tiêu con muốn treo đèn lồng cho phụ hoàng ngắm. {Goi} giúp con chọn dáng đèn, chọn màu cho đẹp."},{"who":"me","text":"Đèn dâng phụ hoàng thì phải có ý nghĩa. Con muốn dáng đèn thế nào?"},{"who":"A","text":"Con muốn đèn hình hoa sen, màu hồng nhạt. Phụ hoàng ít khi cười, con muốn thấy người cười."},{"who":"me","text":"Ý con rất hay. {Xung} giúp con chọn dáng, chọn màu, rồi cùng con dán đèn cho thật xinh."}]}},
{"id":"j72:tv_mua","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau Hội Phượng, sân luyện võ còn lấm tấm vết máu khô, mấy thị vệ băng bó tạm bằng vải thô."},{"who":"A","text":"Hội Phượng thi cưỡi ngựa bắn cung, đội thần bị thương mấy người, thuốc ở Thái y viện phải có phi tần xin mới cấp. {Goi} thương giúp."},{"who":"me","text":"Thị vệ bị thương mà thuốc cấp khó khăn thế sao? Họ bị thương nặng không?"},{"who":"A","text":"Có người nặng, không có thuốc thì sợ nhiễm. Bọn thần không dám làm phiền phi tần, nhưng chẳng còn đường nào khác."},{"who":"me","text":"{Xung} đến Thái y viện xin thuốc cho các thị vệ. Vết thương không nên để lâu."}]}},
{"id":"j72:maid_tet","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cận Tết, trong phòng kẻ hầu, nhà nhà đã gói quà gửi ra cung, chỉ riêng gói của nàng vẫn nằm trên giường."},{"who":"A","text":"{Goi}, Tết sắp đến, {xung} muốn gửi ít quà về cho mẹ mà không có đường ra. {Goi} cho {xung} gửi theo người của cung mình."},{"who":"me","text":"Ngươi nhớ mẹ nhiều, ta hiểu. Quà gì mà ngươi gói kỹ thế?"},{"who":"A","text":"Chỉ là chút bánh và tấm vải {xung} dành dụm. Mẹ {xung} ở xa, năm nào cũng chờ."},{"who":"me","text":"Cho người ngoài cung gửi quà hợp lệ. Ngươi giao gói quà cho ta, ta nhờ người của cung gửi ra đúng dịp Tết."}]}},
{"id":"j72:kho_tet","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm, trong kho lụa của Nội vụ phủ, sổ sách trải đầy bàn, tờ nào cũng dày đặc những con số chồng nhau."},{"who":"A","text":"Cuối năm Nội vụ phủ soát kho, sổ sách rối như canh hẹ. {Goi} tính toán giỏi, xem giúp nô tài."},{"who":"me","text":"Sổ rối thì phải đối chiếu từng khoản. Kho lụa cuối năm thường hay thiếu hụt, {goi} có ghi chép gì không?"},{"who":"A","text":"Có chứ, nhưng sổ ghi một đằng kho nhập một nẻo. Nô tài sợ bị quy lỗi, mà không hiểu sai ở đâu."},{"who":"me","text":"Để {xung} đối chiếu sổ kho từng khoản, rồi chỉ {goi} chỗ sai. Rối mấy cũng có đường gỡ."}]}},
{"id":"j72:su_tet","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Đức Thọ cung, sứ thần đứng ngay ngắn, hai tay ôm hộp lễ buộc lụa đỏ, mắt nhìn ngưỡng cửa cao."},{"who":"A","text":"Quốc vương nước thần gửi lễ Tết dâng Thái hậu. Thần không rõ lễ nghi trong cung, xin {goi} dẫn đường."},{"who":"me","text":"Lễ Tết dâng Thái hậu thì phải đúng phép. Sứ thần nên nhớ ba điều: cúi chào, dâng bằng hai tay, thưa chậm."},{"who":"A","text":"Thần xin ghi nhớ. Thần sợ làm sai thì tổn quốc thể, nên mong {goi} nhắc từng bước."},{"who":"me","text":"{Xung} dẫn sứ thần vào, đứng cạnh nhắc khẽ. Lễ ấy sẽ trọn vẹn."}]}},
{"id":"j72:akf_xuan","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa vườn ngự, nhành đào mới nở, tay áo hoàng nữ đang múa dở bỗng khựng lại giữa nhịp."},{"who":"A","text":"Yến xuân năm nay con được múa trước phụ hoàng, mà điệu Nghê thường con tập mãi không xong. {Goi} chỉ giúp con."},{"who":"me","text":"Điệu Nghê thường khó ở chỗ phải nhẹ như mây. Con tập ở đoạn nào hay vấp?"},{"who":"A","text":"Đoạn xoay tay áo và bước chân. Con xoay thì tay áo rối, mà bước thì mất nhịp."},{"who":"me","text":"{Xung} chỉ con cách xoay tay áo mềm hơn, rồi cùng con ra vườn ngự tập cho quen không gian."}]}},
{"id":"j72:tho_hs","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng họa sư, bức sơn thủy trải trên bàn, mây núi sương mù đã đủ, chỉ thiếu một góc trống."},{"who":"A","text":"Bức sơn thủy này vẽ xong mà còn trống một góc. Cả cung khen thơ {goi}, xin đề giúp mấy câu."},{"who":"me","text":"Tranh sơn thủy đề thơ cần ý hợp với cảnh. Họa sư muốn thơ mang ý gì?"},{"who":"A","text":"Ý núi sông mà thanh thản, nhàn hạ mà không buồn. Bức này dâng Hoàng thượng, nên thơ phải trang nhã."},{"who":"me","text":"{Xung} nghĩ thơ, đề vào góc trống, rồi trao tranh lại cho họa sư."}]}},
{"id":"j72:dan_ns","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn nhạc, bản phổ cổ ố vàng, những khuyết rách khiến nhiều đoạn nhạc hóa thành khoảng trống đau lòng."},{"who":"A","text":"Thần tìm được bản phổ Quảng Lăng tán, rách mất mấy đoạn. {Goi} tinh thông cầm nghệ, xin cùng thần dò lại."},{"who":"me","text":"Quảng Lăng tán là khúc đã thất truyền, nay có người tìm lại, thật quý. Nhạc sư nhớ được đoạn nào?"},{"who":"A","text":"Chỉ nhớ lờ mờ, còn phải dò từng nốt. Nhưng thần tin rằng khúc ấy vẫn nằm đâu đó trong ngón đàn người xưa."},{"who":"me","text":"{Xung} cùng nhạc sư dò lại cung đàn, rồi đàn thử cho nhạc sư nghe. Khúc cổ ấy sẽ không mất."}]}},
{"id":"j72:ns_doi","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng nhạc, tiếng dây đàn còn rung nhẹ sau một nốt cuối, như hơi thở chưa tan."},{"who":"A","text":"Thần xin chỉ {goi} ngón vê dây của Quảng Lăng tán. Mai này {goi} nhắc tên thần với Hoàng thượng."},{"who":"me","text":"Một ngón đàn đổi lấy một lời nhắc tên, nhạc sư tính thật khéo. Ngón vê ấy khó đến đâu?"},{"who":"A","text":"Khó nhất là chỗ vê rền mà không đục tiếng. Học được ngón này, tiếng đàn của {goi} sẽ khác hẳn."},{"who":"me","text":"Nếu đổi như vậy thì {xung} nhận. {Xung} sẽ nhớ ơn nhạc sư, và sẽ nhắc tên người với Hoàng thượng."}]}},
{"id":"j72:hs_hoa","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng họa sư, nửa bức Bách điểu triều phụng trải trên án, chim đã đủ mà hoa lá còn bỏ trống."},{"who":"A","text":"Bức Bách điểu triều phụng dâng Thái hậu, thần vẽ không kịp. Nghe nói {goi} cũng cầm cọ, xin vẽ giúp phần hoa lá."},{"who":"me","text":"Bách điểu triều phụng là bức lớn, họa sư lại cần phần hoa lá làm nền. Thần muốn lá thế nào?"},{"who":"A","text":"Xanh dịu, hoa hồng nhạt, để chim phượng nổi bật. Thần không muốn hoa lá tranh phần với chim."},{"who":"me","text":"{Xung} xin vẽ phần hoa lá, rồi ghép tranh cùng họa sư để thành một bức liền mạch."}]}},
{"id":"j72:dich_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng sứ đoàn đóng cửa, bức quốc thư nằm giữa bàn, mực xa lạ ngoằn ngoèo như chữ của một cõi khác."},{"who":"A","text":"Thông ngôn của sứ đoàn ngã bệnh, quốc thư phải dâng trong tuần. Nghe nói {goi} thông chữ nghĩa…"},{"who":"me","text":"Chữ nghĩa nước ngoài không phải ai cũng thông. Quốc thư thì phải dịch cho chính xác từng câu."},{"who":"A","text":"Phải, một chữ sai là thành thất lễ. Thần chỉ còn tuần này, nên cầu xin sự giúp đỡ."},{"who":"me","text":"{Xung} sẽ dịch cẩn thận từng đoạn, rồi đưa sứ thần xem lại. Chuyện bang giao không thể sai sót."}]}},
{"id":"j72:ak_sach","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng hoàng tử, trên bàn chỉ có mấy cuốn sách nhập môn, trang giấy đã mòn góc vì lật nhiều."},{"who":"A","text":"Thầy chê con học kém. Con muốn đọc bộ Thủy kinh chú bản cổ, chỉ thư phòng hoàng gia còn giữ. {Goi} xin chép giúp con."},{"who":"me","text":"Thầy chê vì thấy con chưa chăm, hay vì thầy muốn con cố hơn? Con hiểu ý thầy chưa?"},{"who":"A","text":"Con hiểu, con muốn học thật, nên mới cần bộ sách cổ. Con chép tay chậm, mong {goi} giúp một phần."},{"who":"me","text":"Con có chí học thì {xung} giúp. {Xung} sẽ vào thư phòng hoàng gia chép sách, mang về cho con đọc."}]}},
{"id":"j72:ak_co","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa vườn ngự, bàn cờ đá bày dưới tán trúc, hoàng tự ngồi đã lâu mà chưa có ai đối diện."},{"who":"A","text":"Con học cờ được ít nước mới, trong cung không ai đánh lại. {Goi} đánh với con một ván."},{"who":"me","text":"Học được nước mới mà không có người đánh thì thật tiếc. Con muốn đánh thật hay đánh vui?"},{"who":"A","text":"Đánh thật ạ, con muốn biết nước mới của con có dùng được không."},{"who":"me","text":"Vậy ta đánh. Nhớ rằng thua không đáng xấu hổ, thua mới biết chỗ sai của mình."}]}},
{"id":"j72:le_hoa","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, Thái hậu hạ chén trà xuống, ánh mắt nhìn sang phía hoàng nữ sắp xuất giá."},{"who":"A","text":"{B} đã hứa gả. Ai gia muốn {goi} dạy con bé lễ nghi nhà chồng, kẻo người ta cười hoàng gia."},{"who":"me","text":"Lễ nghi nhà chồng nhiều điều tế nhị. Thái hậu muốn {xung} dạy những phần nào?"},{"who":"A","text":"Cách thờ cúng, cách chào hỏi, cách nói năng với mẹ chồng. Con bé còn bướng, ai gia sợ nó mang tiếng."},{"who":"me","text":"{Xung} sẽ dạy {B} từng điều một, cẩn thận mà nhẹ nhàng, để nàng ra khỏi cung với lòng vững vàng."}]}},
{"id":"j72:fam_suy","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều xuống, {M} bưng vào phong thư nét chữ cứng cáp quen thuộc của người cha, giấy còn nặng mùi nhà cũ."},{"who":"M","text":"{Goi}, thư lão gia vừa tới, người gửi qua đường dịch trạm, dặn phải giao tận tay."},{"who":"me","text":"Cha ít khi viết thư vào dịp này. Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con gái, nhà {xung} dạo này thế suy, kẻ đối đầu chèn ép. Con ở gần Hoàng thượng, nói giúp cha một lời.»"},{"who":"me","text":"Cha chưa từng mở miệng nhờ vả. Chắc chuyện đã đến lúc nặng, ta phải tìm lúc Hoàng thượng thư thái mà thưa."}]}},
{"id":"j72:fam_tt","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"{M} khẽ khàng đặt phong thư lên án, mực ngoài phong bì còn mới như vừa viết hôm qua."},{"who":"M","text":"{Goi}, thư lão gia gửi vào, người dặn không được để ai biết."},{"who":"me","text":"Cha dặn không để ai biết thì chuyện chắc lớn. Ngươi đọc."},{"who":"M","text":"Người viết: «Con gái, Thái tử chưa lập, triều đình bàn tán đã lâu. Con ở gần Hoàng thượng, dò xem ý ngài nghiêng về ai.»"},{"who":"me","text":"Dò ý lập Thái tử là việc nhạy cảm bậc nhất. Ta sẽ viết thư trả lời cha, nói rõ những gì ta thấy và cả những gì ta không dám nói."}]}},
{"id":"j72:fam_dtq","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm xuống, {M} cầm phong thư còn dính bụi đường, nét chữ nghiêng nghiêng như gấp gáp từ nơi xa."},{"who":"M","text":"{Goi}, thư lão gia từ biên ải gửi về, giấy còn hơi sương."},{"who":"me","text":"Biên ải nguy, cha viết thư ắt có điều khẩn. Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Biên ải nguy, quân ở Nhạn Môn quan thiếu lương. Sớ của cha bị Hộ bộ ỉm đi. Con thưa với Hoàng thượng giúp cha.»"},{"who":"me","text":"Quân thiếu lương là việc không thể chậm. Ta sẽ chọn lúc thích hợp mà thưa với Hoàng thượng."}]}},
{"id":"j72:fam_muoi","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng ra, {M} đưa vào phong thư dán sáp đỏ, bì thư thoang thoảng mùi biển mặn."},{"who":"M","text":"{Goi}, thư nhà từ trấn xa gửi vào, người dặn phải thật kín."},{"who":"me","text":"Nhà ta ít khi nhờ vả. Ngươi đọc xem."},{"who":"M","text":"Thư viết: «Con gái, trấn Lâm An mới mở đường muối. Nhà {xung} muốn xin phép buôn muối ở đó. Con nhờ người đưa lời đến Hộ bộ.»"},{"who":"me","text":"Buôn muối là việc nhà nước, xin phép phải qua nhiều cửa. Ta sẽ nhờ người ở Kính sự phòng chuyển lời cho đúng chỗ."}]}},
{"id":"j72:fam_nc","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sảnh nhỏ của sứ quán, sứ thần nước Cao Ly cúi đầu dâng phong thư phụ vương gửi, sáp đỏ in dấu vương ấn."},{"who":"A","text":"Công chúa, phụ vương người gửi thư. Năm nay Cao Ly mất mùa, xin người tâu với Hoàng đế giảm bớt cống phẩm."},{"who":"me","text":"Phụ vương nói mất mùa thế nào, sứ thần cho ta biết rõ. Dân ta đói đến mức nào?"},{"who":"A","text":"Đói nhiều vùng, nhưng cống phẩm vẫn phải nộp đủ. Phụ vương lo nếu không giảm thì dân sẽ khổ thêm."},{"who":"me","text":"Ta hiểu rồi. Ta sẽ chọn lúc Hoàng đế thư thái mà thưa, cố gắng khuyên người giảm cống phẩm cho quê nhà."}]}},
{"id":"j72:fam_bd","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng sứ giả, chiếc áo lông còn vương tuyết, sứ giả cung kính dâng phong thư phụ hãn gửi từ xa."},{"who":"A","text":"Công chúa, phụ hãn người gửi thư. Mùa đông này tuyết lớn, dân thiếu muối, thiếu trà. Xin người tâu với Hoàng đế cho mở chợ biên, đổi ngựa lấy muối, trà."},{"who":"me","text":"Chợ biên mở thì dân hai bên đều lợi. Ta sẽ nghĩ cách tâu sao cho Hoàng đế thấy được điều đó."},{"who":"A","text":"Phụ hãn nói nếu mở chợ, ngựa tốt sẽ đưa sang đổi. Đôi bên cùng có ích, không ai thiệt."},{"who":"me","text":"Ta ghi nhớ. Một lời của ta cũng đủ làm Hoàng đế cân nhắc, ta sẽ chọn lúc thích hợp mà thưa."}]}},
{"id":"j72:fam_pf","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng khách sứ quán thoang thoảng mùi gió biển, sứ thần Phù Tang quỳ gối trao bức thư phụ hoàng gửi theo thuyền buôn Tân La."},{"who":"A","text":"Công chúa, phụ hoàng người gửi thư theo thuyền buôn Tân La. Xin người tâu với Hoàng đế cho thuyền Phù Tang năm sau được vào bến Minh Châu."},{"who":"me","text":"Thuyền vượt biển phải qua bãi cạn nhiều hiểm trở. Phụ hoàng đã tính đường đi thế nào?"},{"who":"A","text":"Sẽ có người Đại Hy dẫn đường qua bãi cạn. Sứ đoàn ra khơi khi gió mùa đổi, nếu Hoàng đế cho phép sớm thì kịp chuẩn bị."},{"who":"me","text":"Ta sẽ tâu với Hoàng đế, mong người cho thuyền Phù Tang vào bến Minh Châu. Sứ thần cứ yên tâm."}]}},
{"id":"j72:fam_cn","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc hành lang cung nhỏ, người cung nữ cũ đứng nép bóng cột, giọng mềm như sợ ai nghe thấy."},{"who":"A","text":"{Goi} còn nhớ {xung} không? Ngày trước hai ta cùng bưng trà ở Càn Thanh cung. Giờ {xung} hầu chủ khác, bị mắng suốt, xin {goi} nể tình cũ nói Tổng quản thưởng chút ít."},{"who":"me","text":"Ta nhớ ngươi, hồi ấy ngươi luôn cười, tay lại khéo. Bây giờ ngươi khổ lắm sao?"},{"who":"A","text":"Khổ, nhưng không dám nói với ai. Gặp lại {goi}, {xung} như gặp được người nhà."},{"who":"me","text":"Ta nói với Tổng quản ở Kính sự phòng, xin thưởng cho ngươi. Tình đồng liêu cũ, ta không quên."}]}},
{"id":"j72:fam_ch","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, Thái hậu đặt tràng hạt xuống, nhìn người cháu mà giọng bỗng hạ thấp như một người cô."},{"who":"A","text":"{B} là con nhà thế giao với họ nhà ai gia. Nó hiền quá, bị người ta bắt nạt. Con là cháu ai gia, để mắt giúp nó."},{"who":"me","text":"Cô đã dặn thì cháu xin nghe. {B} bị bắt nạt như thế nào, cô có biết không?"},{"who":"A","text":"Chỉ biết người ta hay bỏ mặc nó. Cô không muốn nó bị đối xử bất công mà không ai nói."},{"who":"me","text":"Cháu sẽ sang thăm {B}, rồi mời nàng sang chơi, dạy nàng cách phòng thân giữa cung."}]}},
{"id":"j72:fam_thd","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều tà, {M} mang vào phong thư giấy thô, nét chữ của người cha quen thuộc mà run nhè nhẹ."},{"who":"M","text":"{Goi}, thư lão gia vừa tới, nói chuyện trường làng."},{"who":"me","text":"Trường làng ta thì nhỏ, sao cha viết dài vậy? Ngươi đọc ta nghe."},{"who":"M","text":"Người viết: «Con ơi, trường làng {xung} thiếu sách đã lâu. Cha nghe nói trong cung có kho sách thừa. Con xin giúp cha mấy bộ.»"},{"who":"me","text":"Con nít làng ta thiếu sách thì thật đáng thương. Ta sẽ tìm cách xin sách thừa gửi về."}]}},
{"id":"j72:fam_td","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm khuya, {M} đứng ngoài cửa, tay cầm phong thư dán vội, mùi mực còn mới."},{"who":"M","text":"{Goi}, thư nhà báo tin, nói chuyện lão bộc ngày trước của nhà."},{"who":"me","text":"Lão bộc nào? Ta nhớ ông ấy từng bế ta lúc nhỏ. Ngươi đọc."},{"who":"M","text":"Thư viết: «Tiểu thư, lão bộc ngày trước của nhà {xung} nay già yếu ở Giang Nam, không còn ai thân thích. Tiểu thư còn nhớ ông thì gửi chút bạc.»"},{"who":"me","text":"Ta nhớ ông ấy chứ. Ta gom bạc gửi ra, rồi đợi tin hồi âm xem ông còn sống khỏe không."}]}},
{"id":"j72:fam_tien","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Buổi sáng, {M} mang vào phong thư mỏng kèm chiếc túi gấm nhỏ, ngoài buộc dây đỏ."},{"who":"M","text":"{Goi}, nhà gửi vào một phong thư kèm túi gấm, nói phải qua tay thái giám mới vào được cung."},{"who":"me","text":"Mẹ cha vẫn lo ta túng thiếu. Ngươi đọc thư xem."},{"who":"M","text":"Thư viết: «Nghe nói con trong cung túng thiếu. Nhà gửi vào ít bạc, nhưng phải nhờ thái giám Kính sự phòng lo lót mới qua được cửa cung.»"},{"who":"me","text":"Phải lo lót mới nhận được bạc nhà gửi, nghĩ mà chua xót. Ta sẽ nhờ người ở Kính sự phòng giúp."}]}},
{"id":"j7:doll","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Canh ba, gió lay ngọn đèn trong tẩm cung. Cung nữ ôm cuộn vải ướt đất đứng ngoài bình phong, run đến không giữ nổi tay."},{"who":"M","text":"{Goi}, dưới gốc quế trong sân, nô tỳ vừa bới ra một hình nhân vải, trên ngực thêu ngày sinh của Hoàng thượng."},{"who":"me","text":"Ngày sinh của Hoàng thượng thêu trên hình nhân, lại chôn ngay sân nhà ta. Kẻ ấy không chỉ muốn hại ta, mà muốn ta mang tội với trời."},{"who":"M","text":"Người của Cung Chính ti đã vào đến ngõ, đèn lồng sáng cả một đoạn đường. Chỉ chốc nữa là tới cửa cung."},{"who":"me","text":"Chỉ còn chốc lát. Ta phải quyết ngay: đốt nó đi mà lần theo dấu chân kẻ chôn, hay tự mình đem trình lên trước khi họ gõ cửa."}]}},
{"id":"j7:poisongift","dlg":{"L":"v","R":"me","lines":[{"who":"nar","text":"Giữa sân cung vắng, hộp điểm tâm đề tên người gửi còn mở nắp, mấy miếng bánh vương trên nền gạch lạnh."},{"who":"v","text":"{Goi}, hộp bánh này mang tên {goi} gửi sang cung {xung}. Cung nữ của {xung} nếm thử một miếng đã thổ huyết ngay trước mặt mọi người."},{"who":"me","text":"Hộp bánh ấy {xung} không hề gửi, tên {xung} bị người mượn dùng. Cung nữ của {goi} đang nằm thế nào, còn cứu được không?"},{"who":"v","text":"Thái y còn đang cứu. Cả hậu cung đều nói là tay {goi}, mà lòng {xung} chẳng biết tin ai."},{"who":"me","text":"{Xung} không trách người nghi, chỉ xin đừng vội kết tội. {Xung} phải tìm cách rửa oan, kẻo kẻ làm điều ác lại đứng ngoài thêm một lần."}]}},
{"id":"j7:guardrumour","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều muộn, nắng tắt sau mái ngói, ngoài hiên có tiếng cung nhân bàn tán khẽ rồi im bặt khi cung nữ bước tới."},{"who":"M","text":"{Goi}, lời đồn đã lan khắp các cung: đêm đêm có thị vệ lẻn vào tẩm cung của {goi}. Nô tỳ nghe mà tay chân lạnh ngắt."},{"who":"me","text":"Thị vệ lẻn vào cung ta, mà người nói lại chẳng thấy bóng người nào. Hoàng thượng đã hai tuần không lật thẻ của ta, ta hiểu vì sao."},{"who":"M","text":"Hoàng thượng chưa hề nói một lời, nhưng chính vì thế nô tỳ càng sợ. Lời đồn còn đó, người trong cung đã tránh mặt {goi}."},{"who":"me","text":"Im lặng của Hoàng thượng đáng sợ hơn mọi lời đồn. Ta phải tính đường: để người tra rõ, hay dập tắt tiếng đồn trước khi nó thành thật."}]}},
{"id":"j7:ghost","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm thu gió thốc qua hành lang, giếng sau cung sâu hun hút, nước tối như mực không soi nổi một vì sao."},{"who":"M","text":"{Goi}, cung nhân thì thầm rằng đêm qua có bóng áo trắng khóc bên giếng sau cung. Ba cung nữ đã quỳ xin đổi đi nơi khác."},{"who":"me","text":"Bóng áo trắng khóc bên giếng, nghe đã rợn người. Người trong cung đang sợ, mà nỗi sợ ấy lây nhanh hơn bệnh dịch."},{"who":"M","text":"Nô tỳ không dám nói thật hay giả. Chỉ biết đêm nào cũng có người nghe thấy tiếng khóc, vọng tới tận phòng ngủ của đám cung nữ."},{"who":"me","text":"Ta phải giữ cho cung yên. Mời người làm lễ trừ tà, hay đích thân xem kẻ nào đêm đêm khóc bên giếng, còn phải tính cho kỹ."}]}},
{"id":"j7:pact","dlg":{"L":"v","R":"me","lines":[{"who":"nar","text":"Chiều đầu thu, đình Thiên Thu vắng người, lá rụng đầy bậc đá, một bóng người đứng chờ bên lan can nhìn mặt hồ lặng."},{"who":"v","text":"{Goi}, hôm nay {xung} mạo muội hẹn {goi} ra đây. Hoàng hậu đè đầu cả hậu cung đã lâu, hai ta chung một thuyền, được chăng?"},{"who":"me","text":"Một lời hẹn riêng ở đình vắng, mà nói thẳng thế, hẳn đã nghĩ lâu rồi. {Goi} muốn cùng {xung} làm gì?"},{"who":"v","text":"Chỉ cầu hai ta cùng gánh, chứ không dám một mình đối đầu. Việc này nếu thành, ai nấy đều có phần."},{"who":"me","text":"Hoàng hậu quyền thế thế nào ai cũng rõ. Kết minh hay mật báo, hay khéo từ chối, {xung} phải cân nhắc kẻo mất cả chì lẫn chài."}]}},
{"id":"j7:eunuch","dlg":{"L":"sv","R":"me","lines":[{"who":"nar","text":"Trước thềm cung, một bóng người quỳ thẳng, trán gần chạm đá lạnh, tay áo còn ướt sương sớm."},{"who":"sv","text":"{Goi}, {xung} hầu ở một cung khác, hôm nay mạo muội quỳ ngoài thềm. {Xung} nguyện làm tai mắt cho {goi}."},{"who":"me","text":"Ngươi hầu ở cung khác mà dám đến tận đây, hẳn đã nghĩ kỹ. Vì sao ngươi lại chọn ta?"},{"who":"sv","text":"Ở bên đó, {xung} nhìn nhiều thứ không nên nhìn. Nếu {goi} cho phép, những gì {xung} thấy được, {goi} sẽ biết."},{"who":"me","text":"Lòng người khó lường, kẻ tình nguyện đến cửa càng đáng nghĩ. Nhận ngay, thử trước, hay đuổi đi, ta phải liệu cho thật khéo."}]}},
{"id":"j7:empnight","dlg":{"L":"emp","R":"me","lines":[{"who":"nar","text":"Đêm khuya, không đèn lồng, không tiếng thái giám báo trước, chỉ có bóng áo vàng in lên rèm cửa cung."},{"who":"emp","text":"Trẫm không ngủ được. Đi đến đâu cũng nghe tiếng chân mình, rốt cuộc lại đến cung của {goi}."},{"who":"me","text":"Hoàng thượng đến mà không báo, {xung} chưa kịp trang điểm đã ra nghênh đón. {Goi} có điều gì nặng lòng?"},{"who":"emp","text":"Việc triều chưa dứt, hậu cung cũng chẳng yên. Trẫm chỉ muốn có một nơi yên tĩnh để ngồi."},{"who":"me","text":"Đêm {goi} không ngủ được, {xung} có thể thắp đèn hầu rượu, đàn hát cho khuây, hoặc xin {goi} giữ gìn long thể."}]}},
{"id":"j7:minister","dlg":{"L":"emp","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, ánh nến soi trên bản tấu mở dở, nét son phê chưa khô, mùi mực mới thoảng trong gian phòng lặng."},{"who":"emp","text":"Thượng thư Hộ bộ xin tăng thuế muối, nói là để đủ quân lương. {Goi} nghĩ sao?"},{"who":"me","text":"Thuế muối đánh vào dân nghèo nhiều nhất, nhà nào cũng phải dùng. {Goi} đã hỏi, {xung} thật không biết mở lời thế nào."},{"who":"emp","text":"Trẫm hỏi vì trẫm cần nghe một lời khác với đám đại thần. Cứ nói thật."},{"who":"me","text":"Hậu cung vốn không bàn chính sự, nhưng {goi} đã hỏi. Can thẳng, từ chối khéo, hay nói đỡ cho vị quan ấy, {xung} phải chọn kỹ."}]}},
{"id":"j7:jealousprince","dlg":{"L":"emp","R":"me","lines":[{"who":"nar","text":"Sau buổi giảng kinh, sân điện còn đông triều thần, tiếng xì xào vây quanh một bóng áo nhỏ đứng giữa."},{"who":"emp","text":"Triều thần vây quanh {kid} như vây quanh một vị trữ quân. Trẫm đứng ở xa, nhìn mà thấy không vui."},{"who":"me","text":"{kid} còn nhỏ, chỉ biết đọc sách cho tròn lời thầy dạy. {Goi} đừng nặng lòng, thằng bé đâu hiểu những chuyện ấy."},{"who":"emp","text":"Con không hiểu, nhưng người vây quanh con thì hiểu rất rõ. Việc này, {goi} định xử trí ra sao?"},{"who":"me","text":"Cầm con ở nhà, để con kết giao, hay xin cho con đi biên ải, mỗi đường một nỗi lo. {Xung} phải chọn sao cho {goi} yên lòng."}]}},
{"id":"j7:flood","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Mưa dầm mấy ngày chưa dứt, trên bàn đặt tờ chiếu của Hoàng hậu còn ướt mép, nét chữ đỏ bóng lên dưới đèn."},{"who":"M","text":"{Goi}, tin vừa về: Hoàng Hà vỡ đê, ba châu chìm trong nước. Hoàng hậu đã truyền các cung quyên góp cứu tế."},{"who":"me","text":"Ba châu chìm dưới nước, dân tản cư không biết bao nhiêu. Thân ta ở trong cung êm ấm, nghĩ đến mà thấy áy náy."},{"who":"M","text":"Các cung đều đang bàn xem nên dâng bao nhiêu. Người dâng nhiều thì được tiếng, người dâng ít thì sợ bị chê."},{"who":"me","text":"Tiếng tốt không phải điều ta nghĩ trước, nhưng ta cũng không thể đứng ngoài. Dâng nhiều hay dâng ít, lo cho cung nhân ra sao, ta phải tính."}]}},
{"id":"j7:newgirl","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng nay hành lang các cung rộn tiếng chân, rèm cửa kéo lên, người người nghển cổ nhìn ra phía cổng chính."},{"who":"M","text":"{Goi}, con gái Thượng thư Lễ bộ vừa được tuyển vào cung. Người ta nói dung mạo khuynh thành, hôm nay nàng đi bái kiến các cung."},{"who":"me","text":"Một người mới vào cung, dung mạo hơn người, lại đi từng cung bái kiến. Hậu cung từ nay sẽ không còn yên như trước."},{"who":"M","text":"Cung nào cũng đang chuẩn bị, kẻ thì tặng quà, kẻ thì chuẩn bị lời đón. Nô tỳ nghĩ {goi} cũng nên có chủ ý."},{"who":"me","text":"Nàng sắp tới cung ta rồi. Ta nên dịu dàng kết thân, hay giữ vẻ lạnh nhạt, hay dằn mặt ngay buổi đầu, phải xem lòng nàng trước đã."}]}},
{"id":"j7:princefever","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng nhạc từ Thái Hòa điện vẫn vọng sang, nhưng trong tẩm cung đèn đã tắt gần hết, chỉ còn tiếng ho khẽ và tiếng chân người chạy gấp."},{"who":"M","text":"{Goi}, {kid} sốt cao, co giật không dừng. Nô tỳ gọi mãi mà con không mở mắt!"},{"who":"me","text":"Đêm yến tiệc, lại đúng lúc con ta bệnh nặng thế này. Ta không thể ngồi yên được."},{"who":"M","text":"Thái y viện mới có người trực, đã sai đi gọi rồi. Nhưng yến còn chưa tan, Hoàng thượng đang chờ {goi} bên ấy."},{"who":"me","text":"Bỏ yến, thức bên con, hay mời thái y rồi vẫn dự yến, hay tự mình bốc thuốc, ta phải chọn nhanh, vì con ta không chờ được."}]}},
{"id":"j7:foreignwed","dlg":{"L":"emp","R":"me","lines":[{"who":"nar","text":"Giữa điện, hàng ngựa quý của Bắc Địch đứng im dưới bậc thềm, bờm đen bóng, yên cương thêu chỉ vàng."},{"who":"emp","text":"Sứ thần Bắc Địch dâng ngựa quý, cầu hôn {kid}. Triều thần đều nói: một nàng công chúa đổi mười năm yên biên ải."},{"who":"me","text":"{kid} mới ngần ấy tuổi, mà đã phải rời mẹ đi tận phương bắc. Hoàng thượng cũng nghĩ như triều thần sao?"},{"who":"emp","text":"Trẫm là vua một nước, trước hết phải nghĩ cho non sông. Nhưng trẫm cũng là cha, nên mới gọi {goi} đến hỏi."},{"who":"me","text":"Thuận theo đại cục, quỳ xin giữ con, hay tiến cử một tông nữ đi thay, {xung} đều phải trả giá. {Xung} xin nghĩ kỹ trước khi nói."}]}},
{"id":"j7:maidhostage","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm thanh vắng, cung nữ quỳ sụp giữa gian phòng, mặt úp xuống nền gạch, vai run từng đợt."},{"who":"M","text":"{Goi}, nô tỳ có tội với người. Người của {v} giữ cha mẹ nô tỳ, ép nô tỳ lấy trộm thư từ của {goi} mang sang."},{"who":"me","text":"Cha mẹ ngươi nằm trong tay người ta, ngươi sợ mà không dám nói. Ngươi đã nói ra, ta không giận, chỉ thương cho ngươi."},{"who":"M","text":"Nô tỳ chưa lấy được lá thư nào, nhưng họ hẹn đêm mai không thấy thư thì cha mẹ nô tỳ sẽ khó giữ mạng."},{"who":"me","text":"Chuộc người bằng bạc, bày kế phản gián, hay bỏ mặc, mỗi đường một giá. Ta phải cứu được cha mẹ ngươi mà không để {v} nắm thêm điều gì của ta."}]}},
{"id":"j7:doctorblack","dlg":{"L":"doc","R":"me","lines":[{"who":"nar","text":"Trong gian ấm khuất sau Thái y viện, ánh đèn dầu chập chờn, tay thái y cầm tờ phương thuốc run lên theo nhịp thở."},{"who":"doc","text":"{Goi}, có kẻ biết thần từng kê nhầm thuốc cho tiên phi năm xưa. Hắn đòi năm chục lượng mỗi tháng, không thì sẽ tâu lên."},{"who":"me","text":"Một sai lầm cũ, mà nay thành dây trói cổ ông. Ông giấu ta lâu nay, hôm nay mới nói, hẳn đã đến lúc chịu hết nổi."},{"who":"doc","text":"Thần không dám giấu {goi} nữa. Nếu thần bị lôi ra, thì những phương thuốc thần kê cho cung {goi} cũng không ai tin."},{"who":"me","text":"Ông đã tin ta mà nói, ta không bỏ ông. Trả bạc thay ông, diệt kẻ tống tiền, hay để ông tự lo, ta phải chọn đường ít hại nhất."}]}},
{"id":"j7:comet","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đêm khuya, cả hậu cung ngẩng nhìn trời tây, một vệt sáng dài quét ngang như nhát kiếm bạc rạch qua nền đen."},{"who":"M","text":"{Goi}, Khâm Thiên giám vừa tâu lên điềm sao chổi. Cung nhân bàn tán khắp nơi, người nói điềm ấy đổ về cung này, người nói đổ về cung khác."},{"who":"me","text":"Sao chổi quét ngang là điềm chẳng lành. Người ta nói điềm ấy đổ cho ai, người ấy khó sống yên trong hậu cung."},{"who":"M","text":"Nô tỳ nghe nói Hoàng thượng đang giận. Có người đã quỳ ngoài điện cả đêm để xin dập lời tâu."},{"who":"me","text":"Điềm trời mà thành lời đồn thì sức mạnh còn hơn lưỡi kiếm. Ta phải xem nên nói đỡ, im lặng, hay cầu đảo để giữ lấy mình."}]}},
{"id":"j7:phoenix","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau buổi lễ ở chùa Bảo Hoa, khói hương còn vương trên áo cung nữ, ánh mắt nàng sáng lên một cách khác thường."},{"who":"M","text":"{Goi}, thầy tướng ở chùa Bảo Hoa phán rằng trong hậu cung có một người mệnh phượng hoàng. Ông ấy chỉ thẳng vào cung của {goi}."},{"who":"me","text":"Mệnh phượng hoàng, lại chỉ thẳng vào cung ta. Lời ấy mà truyền ra, người vui ít, kẻ ghen nhiều."},{"who":"M","text":"Cung nhân nghe được đã truyền nhau rồi. Nô tỳ sợ chưa đến tối, cả hậu cung đều biết."},{"who":"me","text":"Lời phán thật hay giả, lòng người cũng đã động. Khiêm nhường chối từ, để lời lan xa, hay bịt miệng thầy tướng, ta phải chọn cẩn thận."}]}},
{"id":"j7:doanngo","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng Đoan ngọ, trên mái hiên các cung treo ngải cứu xanh ngắt, mùi thơm hăng nồng bay khắp hành lang."},{"who":"M","text":"{Goi}, hôm nay thuyền rồng đua trên Thái Dịch trì, các cung đều gói bánh ú, treo ngải cứu rồi. Cung {xung} cũng nên chuẩn bị."},{"who":"me","text":"Tết Đoan ngọ, trên hồ trống thúc thuyền đua, người người hớn hở. Ta chỉ mong các con khỏe mạnh qua mùa nóng."},{"who":"M","text":"Thái hậu cũng thích bánh ú nhân đậu, nếu {goi} gói dâng người, chắc người vui. Nô tỳ còn nghe có người đặt cược thuyền rồng."},{"who":"me","text":"Gói bánh dâng Thái hậu, đeo túi ngải cho các con, hay thử vận may cược thuyền rồng, ba việc đều hay, ta chỉ có một buổi để chọn."}]}},
{"id":"j7:trungcuu","dlg":{"L":"emp","R":"me","lines":[{"who":"nar","text":"Tiết Trùng cửu, trên Cảnh Sơn gió lộng, hoa cúc nở vàng khắp triền núi, rượu thù du còn ấm trong bình ngọc."},{"who":"emp","text":"Hôm nay trẫm lên Cảnh Sơn ngắm cúc, uống rượu thù du. {Goi} có muốn đi cùng trẫm một đoạn không?"},{"who":"me","text":"Hoa cúc nở rực cả triền núi, rượu thù du thơm ấm. Được đi cùng {goi}, {xung} đã thấy vui rồi."},{"who":"emp","text":"Núi cao gió lớn, nhìn xa ngàn dặm mà lòng chẳng thảnh thơi. Có hoa có rượu, thiếu một bài thơ."},{"who":"me","text":"Một bài thơ Trùng cửu, {xung} xin thử. Nếu thấy chưa hay, xin cho {xung} đi dâng rượu chúc thọ Thái hậu thay vậy."}]}},
{"id":"j7:vulan","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Rằm tháng bảy, trên kênh Kim Thủy hàng trăm ngọn hoa đăng trôi lặng lẽ, ánh nến lung linh phản chiếu trên mặt nước đen."},{"who":"M","text":"{Goi}, tối nay lễ Vu Lan, cung nhân đều ra kênh thả đèn, khấn vái người đã khuất. Nô tỳ cũng đã chuẩn bị cho {goi} mấy ngọn."},{"who":"me","text":"Hoa đăng trôi trên nước, mỗi ngọn một lời nguyện. Ta cũng có người cần cầu siêu, có người chưa kịp tiễn."},{"who":"M","text":"Trong cung năm xưa cũng có những phi tần chết oan, không ai dám khấn tên họ. {Goi} có muốn cúng riêng cho họ không?"},{"who":"me","text":"Khấn cho người thân, cho những người chết oan, hay mượn lễ dò hỏi cung nhân, ta chỉ có một đêm mà cõi lòng nhiều nỗi."}]}},
{"id":"j7:dongchi","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Đông chí, tuyết phủ trắng mái ngói lưu ly, hơi thở ra thành khói, trong sân chỉ còn tiếng chổi quét khe khẽ."},{"who":"M","text":"{Goi}, hôm nay Hoàng thượng ra đàn Nam Giao tế trời. Các cung nếu được ban chỉ thì có thể theo hầu lễ."},{"who":"me","text":"Tuyết rơi dày thế, đứng hầu lễ tế ngoài trời, ta e thân thể không chịu nổi. Nhưng bỏ lễ thì lại thành thiếu thành ý."},{"who":"M","text":"Cung nhân đã nấu sẵn nồi chè nóng, nếu {goi} muốn thì chia cho cả cung ấm bụng. Hoặc nghỉ lại trong cung cho ấm."},{"who":"me","text":"Theo hầu lễ tế, nấu chè mừng cả cung, hay ở lại giữ ấm, ta nghĩ thương người trong cung trước, rồi mới nghĩ đến thể diện."}]}},
{"id":"j7:thbirthday","dlg":{"L":"th","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, lễ vật của các cung xếp đầy hai bên án, hộp gấm chồng lên hộp gấm, mùi trầm thoảng trong điện."},{"who":"th","text":"Hôm nay là Thánh thọ của ai gia. Các cung đua nhau dâng lễ, ai gia nhìn mà thấy lòng không yên."},{"who":"me","text":"Lễ vật đầy điện, nhưng điều {xung} muốn dâng không nằm trong hộp gấm. {Xung} chỉ mong Thái hậu thọ khang."},{"who":"th","text":"Ai gia từng thấy nhiều người dâng ngọc quý, ít ai dâng cái tâm. {Goi} định dâng gì cho ai gia?"},{"who":"me","text":"Ngọc Như Ý, trăm chữ Thọ tự tay thêu, hay lễ mọn cho phải phép, {xung} xin tính cho vừa sức mà vẫn chân thành."}]}},
{"id":"j7:caning","dlg":{"L":"v","R":"me","lines":[{"who":"nar","text":"Trước Càn Ninh cung, trâm cài bị giật rơi trên nền đá, tóc xõa xuống vai, tiếng trượng đập nặng nề giữa sân im phăng phắc."},{"who":"v","text":"{Goi}... xin {goi} nhìn {xung} một lần. {Xung} không có tội bất kính, chưa từng nói câu nào như thế."},{"who":"me","text":"Hoàng hậu bắt cả hậu cung đứng xem, ý muốn dằn mặt chúng ta. {Xung} nghe thấy lời cầu xin ấy, nhưng nơi này {xung} không tiện lên tiếng."},{"who":"v","text":"Hai mươi trượng thế này, {xung} không chịu nổi. Nếu có ai chịu nói một lời, {xung} nhớ ơn suốt đời."},{"who":"me","text":"Quỳ xin tha, đứng yên như không thấy, hay thêm một lời buộc tội, mỗi đường một giá. Phải chọn ngay khi trượng này còn chưa dứt."}]}},
{"id":"j7:condemnedmaid","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều tàn, bóng người bị lôi qua cổng cung kéo dài trên nền gạch, tiếng khóc lẫn tiếng gào vang vọng cả hành lang."},{"who":"M","text":"{Goi}, một cung nữ ở cung khác bị khép tội trộm, sắp bị đánh chết. Lúc bị lôi qua cổng, nàng ta gào tên {goi}."},{"who":"me","text":"Nàng ta gào tên ta, mà ta chưa từng quen nàng. Có lẽ nàng chỉ còn biết ôm lấy cái tên cuối cùng nàng nghe nói đến."},{"who":"M","text":"Nô tỳ nghe nói tang vật chưa rõ ràng, nhưng người của Cung Chính ti đã quyết án. Ai can thiệp cũng chịu tiếng."},{"who":"me","text":"Quỳ xin tha, lén gửi bạc về nhà nàng, hay không can dự, đều có cái giá của nó. Ta không muốn nhìn thêm một mạng người chết oan."}]}},
{"id":"j7:coldvisit","dlg":{"L":"f","R":"me","lines":[{"who":"nar","text":"Gió lùa qua song cửa mục nát của lãnh cung, cỏ dại mọc đầy hiên, mùi ẩm mốc quyện với hơi lạnh thấm vào tận áo."},{"who":"f","text":"{Goi}... {Goi} đến thăm {xung} ư? {Xung} gầy rộc thế này rồi, còn biết nhà ai nhớ đến."},{"who":"me","text":"Nghe tin {goi} ở nơi này, {xung} không thể làm ngơ. Thấy {goi} gầy yếu như vậy, lòng {xung} không yên."},{"who":"f","text":"{Xung} biết những chuyện họ muốn chôn. Nếu {goi} chịu giúp {xung} một lần, {xung} sẽ nói hết."},{"who":"me","text":"Mang chăn ấm thuốc men, xin ân xá cho {goi}, hay quay lưng đi, {xung} phải chọn cẩn thận, vì chuyện chôn dưới đất này không nhẹ."}]}},
{"id":"j7:taster","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giữa bữa cơm, bát canh ngự ban còn bốc khói trên bàn, bên cạnh chiếc thìa bạc, một tiểu thái giám đang nằm co quắp dưới đất."},{"who":"M","text":"{Goi}, tiểu thái giám nếm canh ngự ban cho {goi} vừa ôm bụng ngã gục, môi tím tái, mặt trắng như giấy."},{"who":"me","text":"Bát canh ấy là ngự ban, người nếm thay ta đã ngã. Nếu hôm nay không có người nếm, kẻ nằm dưới đất kia chính là ta."},{"who":"M","text":"Nô tỳ đã đóng cửa cung, không cho ai ra vào. Nhưng canh từ Ngự thiện phòng đưa tới, phải truy mới rõ."},{"who":"me","text":"Truy đến cùng Ngự thiện phòng, đổi người nấu mà giấu chuyện, hay khóc kể với Hoàng thượng, mỗi đường một hậu quả. Ta phải bình tĩnh mà chọn."}]}},
{"id":"j7:letterhome","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Giỏ trái cây vừa đưa vào cung, dưới lớp quả tươi có một góc giấy gấp nhỏ, mép đã mòn vì nằm lâu trong lòng bàn tay người."},{"who":"M","text":"{Goi}, nô tỳ tìm thấy thư nhà giấu dưới đáy giỏ. Người thương yêu {goi} nhất trong nhà đã lâm bệnh nặng, chỉ mong gặp {goi} lần cuối."},{"who":"me","text":"Người ấy một đời thương ta, nay nằm bệnh mà chỉ muốn nhìn ta một lần. Ta ở sâu trong cung này, về làm sao được."},{"who":"M","text":"Hoàng thượng chưa chắc đã chuẩn cho về. Nếu không về được, ít nhất {goi} cũng nên gửi bạc, gửi thư hỏi han."},{"who":"me","text":"Gửi bạc chữa bệnh, viết thư hỏi han, hay xin ân chuẩn về thăm, đường nào ta cũng phải đi, chỉ mong người còn kịp chờ thư ta."}]}},
{"id":"j7:fire","dlg":{"L":"v","R":"me","lines":[{"who":"nar","text":"Nửa đêm, Đông lục cung bốc cháy, lửa liếm lên mái ngói, khói đen cuộn lên che khuất cả vầng trăng, tiếng chiêng vang dồn dập."},{"who":"v","text":"{Goi}! Lửa đã lan tới cung {xung} rồi! Trong kia còn người chưa kịp ra, gọi mãi mà không ai đáp!"},{"who":"me","text":"{Goi} đừng hoảng, đứng yên đây, đừng chạy vào nữa. {Xung} đã sai người xách nước tới ngay."},{"who":"v","text":"Tiếng trẻ khóc trong ấy là tiếng nào, {xung} không phân biệt nổi. {Goi} cứu người trước, {xung} xin nhớ ơn này."},{"who":"me","text":"Lao vào cứu người thì thân {xung} gặp nguy, chỉ huy dập lửa thì chậm mất người, ngầm tra kẻ phóng hỏa thì sợ lỡ việc. {Xung} phải quyết ngay."}]}},
{"id":"j7:rvframe","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sau hòn non bộ rêu phủ, hai người nép sát vào bóng đá, nghe lẫn trong tiếng nước rỉ có tiếng thì thầm từ bên kia."},{"who":"M","text":"{Goi}, nô tỳ nghe rõ rồi. {a} đang bàn với một thái giám, giấu đồ ngự dụng vào cung của {b} để vu cho tội trộm."},{"who":"me","text":"Đồ ngự dụng giấu vào cung người khác, kẻ bị vu có trăm miệng cũng khó phân. Ta nghe tận tai, nhưng chưa có gì làm chứng."},{"who":"M","text":"Họ định ra tay trong mấy ngày tới. Nếu {goi} báo cho {b}, kịp thì cứu được nàng."},{"who":"me","text":"Báo cho {b}, giúp {a} một tay, hay ghi nhớ lấy làm chứng cứ, ta sẽ phải chọn theo điều mình muốn giữ lâu về sau."}]}},
{"id":"j7:rvquarrel","dlg":{"L":"a","R":"b","watch":true,"lines":[{"who":"nar","text":"Giữa Ngự hoa viên, chậu mẫu đơn đỏ thắm Hoàng thượng ban còn nguyên cánh, hai bóng người đứng đối nhau bên bờ đá, tay áo run lên."},{"who":"a","text":"Chậu mẫu đơn này Hoàng thượng ban cho {xung}. {Goi} mang đi thì phải hỏi một tiếng trước chứ."},{"who":"b","text":"Hoàng thượng ban cho cả hai cung, {goi} nhìn cho kỹ. Hoa nở trong vườn, ai thấy trước thì giữ."},{"who":"a","text":"Vườn của hoàng gia chứ đâu phải nhà riêng của {goi}. Cậy có sủng ái mà hỗn xược, {xung} nhớ lời hôm nay."},{"who":"b","text":"Nhớ thì nhớ, {xung} không sợ. Chậu hoa này {xung} đã giữ, đừng hòng cướp lại."}]}},
{"id":"j7:rvmusk","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ, túi thơm gấm thêu còn nguyên dây tua, mùi hương lan nhè nhẹ thoảng ra, mà sắc mặt cung nữ thì trắng bệch."},{"who":"M","text":"{Goi}, nô tỳ nghe nói {a} đã trộn xạ hương vào túi thơm tặng {b}. Người ta mong nàng không bao giờ có con."},{"who":"me","text":"Xạ hương trong túi thơm, thứ thuốc hại người từ trong âm thầm. Nếu ta nói ra, ta phải có bằng chứng mới được."},{"who":"M","text":"Nô tỳ đã dò hỏi, người trong cung {a} còn mang vẻ lúng túng. Túi thơm chưa tới tay {b}, vẫn còn kịp."},{"who":"me","text":"Cảnh báo {b}, tố lên Hoàng thượng, hay làm ngơ, đường nào cũng đụng đến thiện cảm của hậu cung. Ta phải xem điều gì nặng hơn."}]}},
{"id":"j7:rvbribe","dlg":{"L":"ksp","R":"me","lines":[{"who":"nar","text":"Sau Kính sự phòng, dưới ánh đèn mờ, mấy xấp thẻ bài xếp ngay ngắn, mùi giấy cũ lẫn mùi trầm đốt dở."},{"who":"ksp","text":"{Goi}, {xung} nói thẳng với {goi} một chuyện. {a} đã đút lót để giấu thẻ bài của {b} đi. {Goi} có muốn chen một chân không?"},{"who":"me","text":"Giấu thẻ bài của người khác để mình được lật, việc ấy trong cung vốn hay xảy ra. Ngươi tìm đến ta, hẳn có tính toán."},{"who":"ksp","text":"{Xung} chỉ truyền lời, không dám có tính toán. Nếu {goi} góp bạc, tuần này và tuần sau thẻ của {goi} sẽ được dâng lên trước."},{"who":"me","text":"Góp bạc giấu cả thẻ của {b}, mách cho {b} biết, hay không dính vào, ta phải chọn điều khiến lòng ta yên."}]}},
{"id":"j7:rcpMama","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều êm, một bà ma ma tóc bạc đang đứng chờ ngoài thềm, hai tay cầm một xấp giấy cũ, hơi cúi đầu chào."},{"who":"M","text":"{Goi}, có một ma ma già ở một cục trong cung sang thỉnh an. Bà nói thuở trẻ từng hầu một vị chủ cung rất giỏi một nghề, còn nhớ cả phổ."},{"who":"me","text":"Một ma ma già còn nhớ phổ xưa của một người tài, thật hiếm có. Bà ấy mong điều gì khi đến tìm ta?"},{"who":"M","text":"Bà nói nếu {goi} muốn, bà sẽ chép lại cho. Chỉ là nghề xưa thì tay già ít người dám tin, mà bạc thì bà cũng cần."},{"who":"me","text":"Biếu bà ít bạc để chép phổ, hay phụ bà một buổi bếp núc để học tận tay, mỗi đường một cái giá. Ta thấy nghề xưa đáng giữ."}]}},
{"id":"ky:ma_phe","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Gió lùa qua bức tường đổ của Trường Môn viện, mang theo một mùi hương lạ, thoảng như hoa cũ phơi khô trong nắng đã tàn."},{"who":"W","text":"Năm xưa cả Lục cung đều xin {xung} một túi hương. Nay ngồi đây trộn nốt mấy vị cũ, thấy {goi} đến, lòng cũng vui."},{"who":"me","text":"Hương ấy thơm thật, mà nay chỉ còn bà ngồi một mình bên khung cửa mục. {Xung} đứng đây lâu mà chưa dám làm phiền."},{"who":"W","text":"Nghề điều hương mà không có người học thì mai một. {Goi} có muốn học không, hay chỉ ngồi nghe chuyện cũ?"},{"who":"me","text":"Điều hương là nghề, chuyện cũ là tình. {Xung} ngồi lại, học nghề hay nghe chuyện, đều là cách giữ lấy điều bà muốn trao."}]}},
{"id":"ky:ma_giao","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trên bàn gỗ cũ có một cuốn sổ tay ố vàng, mép gáy bạc màu, trang giấy chằng chịt lối thêu, lối vẽ, lối nấu viết bằng nét chữ già."},{"who":"W","text":"Cuốn sổ này {xung} gom góp mấy chục năm dạy tú nữ. Mỗi lối trong đây đều có người học rồi, có người bỏ, có người mang theo suốt đời."},{"who":"me","text":"Mấy chục năm tâm huyết gói trong một cuốn sổ. Nhìn bà gập sổ lại, {xung} hiểu đây là thứ không dễ trao cho ai."},{"who":"W","text":"{Xung} nhìn {goi} đã lâu. {Goi} là người biết giữ điều học được, nên hôm nay {xung} mới mở sổ ra."},{"who":"me","text":"Xin ma ma cho chép một lối, hay chỉ dạy tận tay, {xung} cũng xin giữ gìn cho xứng với lòng tin của bà."}]}},
{"id":"ky:ma_nhac","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trăng lên sau hòn non bộ, mặt hồ gợn bạc, có tiếng đàn ai gảy rất khẽ, mỗi nốt tan vào đêm như giọt nước rơi vào đáy giếng."},{"who":"W","text":"Thần không biết có người nghe. Xin {goi} thứ lỗi, đã vội đứng dậy hành lễ."},{"who":"me","text":"Tiếng đàn hay như thế, đêm nay chỉ có người một mình nghe. {Xung} đứng nghe đến quên cả lối về."},{"who":"W","text":"Khúc này cả cung chẳng còn ai đàn được nữa. Thần giữ nó như giữ một nén hương cuối cùng."},{"who":"me","text":"Nén hương cuối cùng không nên để tắt. {Xung} ngồi lại học đàn, hay xin Hoàng thượng cho người vào cung dạy, đều muốn giữ khúc này sống tiếp."}]}},
{"id":"ky:ma_hoa","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên hàng liễu rủ, giá vẽ vừa dựng xong, giấy lụa căng phẳng, nghiên mực còn ướt, một cây bút treo lơ lửng giữa chừng."},{"who":"W","text":"Thần đang vẽ cảnh liễu, ngẩng lên thì thấy {goi} đứng đó. Bút vừa dừng, vì chưa từng thấy ai đứng yên được như vậy."},{"who":"me","text":"Người trong cung nhiều lắm, vì sao họa sư lại dừng bút trước mặt {xung}? {Xung} chỉ đứng ngắm liễu thôi."},{"who":"W","text":"Người trong cung vẽ đã nhiều, nhưng hiếm ai đứng yên đến mức khiến cảnh vật cũng im theo. Thần muốn giữ lại khoảnh khắc ấy."},{"who":"me","text":"Nhờ họa sư nói tốt trước Hoàng thượng, hay xin học cách đặt bút, {xung} đều mang ơn lời khen này, và phải chọn cho khéo."}]}},
{"id":"ky:ma_ty","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm khuya Thái y viện chỉ còn một ngọn đèn, trên án mấy cuốn y thư cũ mở dở, hơi thuốc nhè nhẹ lẫn trong mùi giấy ẩm."},{"who":"W","text":"Thấy {goi} đến muộn thế này, mời {goi} ngồi, để lão phu bắt mạch cho. Bệnh cũ trong người {goi} không nhẹ."},{"who":"me","text":"Bệnh cũ cứ âm ỉ mà {xung} không dám nói ra. Thái y nhìn ra được, đủ biết ông chưa từng lơ là."},{"who":"W","text":"Lão phu có một phương thuốc gia truyền, dùng được mà chưa từng trao ai. {Goi} xem hợp thì lão phu chữa dứt cho."},{"who":"me","text":"Xin thái y chữa dứt bệnh cũ, hay xin học phương thuốc ấy để tự giữ mình, {xung} đều phải nghĩ cho thật kỹ."}]}},
{"id":"ky:ma_co","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, Hoàng thượng chưa về, bàn cờ vẫn dở ván, quân trắng quân đen đứng im như hai đạo quân giằng co từ rất lâu."},{"who":"W","text":"Ván cờ này đánh từ đời tiên đế, chưa ai giải được. {Goi} nhìn quân trắng này xem, có thể thử một nước không?"},{"who":"me","text":"Ván cờ từ đời trước, đến nay vẫn còn dở dang. Quân trắng bị vây, mà vây không chặt, hẳn có người cố ý giữ lại."},{"who":"W","text":"Giữ lại là để chờ một người hiểu cờ. {Goi} đánh hết ván, hay nhường một nước, lão cũng đều cảm tạ."},{"who":"me","text":"Đánh hết ván cờ là cho ván cờ một kết cục. Nhường một nước là cho người một thể diện. {Xung} sẽ chọn theo lòng mình lúc này."}]}},
{"id":"ky:ma_lao","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên hiên Phật đường, nắng chiều rọi vào mấy quân cờ đã mòn góc, mùi trầm đượm trên áo người ngồi cạnh bàn cờ."},{"who":"W","text":"Ngồi đây. {Xung} hầu từ tiên triều, đã thấy hậu cung này đổi bao nhiêu chủ. Hôm nay muốn kể {goi} nghe cung này ngày trước."},{"who":"me","text":"Một người đã hầu từ tiên triều, hiểu hết những điều chúng ta chưa kịp hiểu. {Xung} xin ngồi nghe."},{"who":"W","text":"Ván cờ này {xung} bày đã nhiều năm, mà chưa tìm được người đánh cùng. Hôm nay có {goi}, cũng là duyên."},{"who":"me","text":"Xin bà chỉ giáo nước cờ, hay hầu bà nói chuyện cũ, {xung} đều biết đây là dịp hiếm có, không nên bỏ lỡ."}]}},
{"id":"ky:vat_lac","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Bên lối đi, giữa lớp cỏ ướt sương, có vật gì lấp lánh khiến người đi qua phải cúi xuống nhặt lên."},{"who":"W","text":"{Goi}... món đồ này chính là món {xung} báo mất hôm trước! Thì ra {goi} đã tìm thấy."},{"who":"me","text":"Nó nằm trong cỏ ngay bên lối, ai đi qua cũng có thể thấy. {Xung} nhặt lên, nhận ra ngay là của {goi}."},{"who":"W","text":"{Xung} tìm mãi không thấy, đã nghĩ là mất hẳn. {Goi} chịu mang đến tận nơi, {xung} thật cảm kích."},{"who":"me","text":"Một món đồ thuộc về người khác, giữ lại cũng chẳng yên lòng. Mang trả tận tay hay giữ lại, {xung} đã biết mình phải làm gì."}]}},
{"id":"ky:vat_minh","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sáng sớm, gió thổi lá khô quét ngang hiên, cung nữ chạy vội từ ngoài vào, hơi thở dồn dập, hai tay run run nâng một món đồ."},{"who":"M","text":"{Goi}, nô tỳ vừa tìm thấy món đồ của {goi} dưới gốc cây bên lối. Gần đó còn vương một dấu vết của kẻ đã lấy."},{"who":"me","text":"Món đồ ta tưởng mất hẳn lại nằm ngay bên lối. Kẻ lấy nó vội vàng bỏ lại, hẳn đã bị ai đó làm kinh động."},{"who":"M","text":"Dấu vết ấy nô tỳ không dám động vào, sợ làm mất manh mối. {Goi} xem rồi mới quyết có truy hay không."},{"who":"me","text":"Có lại món đồ thì đã yên lòng, nhưng kẻ lấy vẫn còn trong cung. Ta phải xem dấu vết ấy chỉ về ai trước khi nó bị gió xóa."}]}},
{"id":"ky:vat_cu","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Kho sau Nội vụ phủ tối và lạnh, một chiếc hộp gỗ cũ đặt trên giá, mở nắp ra có mùi trầm ngả vàng của vật đã nằm lâu."},{"who":"W","text":"{Xung} lén đưa {goi} vào đây, mong {goi} đừng nói ra. Trong hộp là di vật của người đã khuất, chờ ngày đem bán ra ngoài."},{"who":"me","text":"Di vật của một người đã khuất mà đem bán, nghe đã xót lòng. Người ấy có thân nhân nào còn nhớ không?"},{"who":"W","text":"Không còn ai nhận. Quy củ của Nội vụ phủ là hết hạn thì bán. {Xung} thấy tiếc, nên mới nghĩ đến {goi}."},{"who":"me","text":"Chuộc lại cho mình, hay dâng Thái hậu thay người đã khuất, {xung} đều cảm thấy trọng trách này không nhẹ. {Xung} xin nghĩ một lát."}]}},
{"id":"ky:vat_thu","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa bụi hoa, một con vật nhỏ lẫn trong lá, lông ướt sương, vừa bị bế lên đã thôi kêu mà rúc vào tay áo người ôm nó."},{"who":"W","text":"Nó chạy lạc từ sáng, {xung} tìm khắp nơi mà chẳng thấy. {Goi} đã mang nó về, {xung} chẳng biết nói sao."},{"who":"me","text":"Nó chạy lẫn vào bụi hoa, run lên như đã sợ lắm. {Xung} chỉ tình cờ thấy, đưa về cho đúng chủ thôi."},{"who":"W","text":"Với người khác thì chỉ là một con vật, với {xung} thì là bầu bạn. Ơn này {xung} xin nhớ."},{"who":"me","text":"Một việc nhỏ mà được nhớ ơn, {xung} lấy làm vui. Cũng nhờ nó mà hai người mới có dịp ngồi lại nói chuyện."}]}},
{"id":"ky:vat_chung","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Bên tường, trong chậu lan rêu xanh phủ kín, một mảnh thư gấp nhỏ nằm ép giữa hai lá, mép giấy đã ngả màu vì sương."},{"who":"M","text":"{Goi}, nô tỳ vừa nhặt được mảnh thư này trong chậu lan. Nét chữ giống nét chữ của {W}, nói về một việc nàng ta đang sắp đặt."},{"who":"me","text":"Thư viết dở mà nằm trong chậu hoa, hẳn chủ nhân chưa kịp mang đi. Nét chữ ấy, ta nhận ra được."},{"who":"M","text":"Nếu giữ làm chứng cứ thì có thể dùng khi cần. Nếu trả lại, nàng ta sẽ không biết ai đã nhìn thấy."},{"who":"me","text":"Giữ lấy là thêm một mối thù, trả lại là thêm một món nợ. Ta phải chọn cách nào để mình yên ổn hơn."}]}},
{"id":"ky:vat_ngu","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sáng sớm trong kho Nội vụ phủ, tấm lụa phủ trên giá hé ra, lộ một góc ánh men lạnh, chưa kịp đem bày."},{"who":"W","text":"Món quý tuần này còn chưa bày ra, {xung} để dành cho {goi} xem trước. Chỉ mong {goi} nhận lấy lòng thành."},{"who":"me","text":"Một món quý chưa bày mà đã dành cho {xung}, hẳn là {goi} tin {xung} trọng. Cho {xung} xem kỹ rồi hãy nói."},{"who":"W","text":"{Goi} cứ xem tận mắt. Có món quý này, ai cầm cũng thấy xứng đáng, nhưng {xung} thấy chỉ có {goi} hợp nhất."},{"who":"me","text":"Nhận về dùng thì tiện cho {xung}, tiến lên Thái hậu thì là tấm lòng. Món đồ này nên về đâu, {xung} phải nghĩ thêm."}]}},
{"id":"ky:de_mua","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Mưa đổ xuống bất chợt, nước tuôn từ mái đình thành tấm rèm bạc, gió lùa ướt vạt áo, bốn bề chỉ còn tiếng mưa rơi."},{"who":"W","text":"Mưa lớn thế này, {goi} đứng ngoài đình làm gì? Trẫm đang trú ở đây một mình, lại gần đây."},{"who":"me","text":"Mưa đến quá nhanh, {xung} không kịp tránh. Không ngờ gặp Hoàng thượng ở đây."},{"who":"W","text":"Trẫm cũng không ngờ. Áo mỏng thế này sẽ lạnh, khoác lấy áo choàng của trẫm đi."},{"who":"me","text":"{Xung} nhận lấy áo choàng này, lòng ấm lên giữa cơn mưa lạnh. Theo {goi} về điện, hay xin {goi} giữ long thể, {xung} phải nghĩ thật kỹ."}]}},
{"id":"ky:de_but","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, tấu chương đã xếp gọn, ánh nến vàng soi lên tờ giấy trải rộng, nghiên mực vừa mài còn thơm."},{"who":"W","text":"Trẫm phê xong tấu chương, hôm nay còn hứng, muốn viết vài chữ. {Goi} lại gần đây."},{"who":"me","text":"Giấy trải rộng, mực thơm, tay Hoàng thượng đang cầm bút. {Xung} bước tới mà chưa biết nên đứng hay quỳ."},{"who":"W","text":"Cứ đứng đó. Trẫm viết một chữ, xem {goi} nhìn ra điều gì trong nét bút."},{"who":"me","text":"Một nét chữ của đế vương chứa cả ý tứ. {Xung} xin {goi} chỉ cho một nét, hay mài mực hầu bút, đều xin theo ý {goi}."}]}},
{"id":"ky:de_den","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đèn hoa đăng thắp kín mặt hồ, mỗi ngọn một vệt vàng đổ dài trên nước, bóng người trên bờ in lẫn bóng đèn."},{"who":"W","text":"Đêm nay đèn sáng cả hồ, lòng trẫm cũng nhẹ. Trẫm cho {goi} một điều ước, {goi} cứ nói."},{"who":"me","text":"Điều ước bên hồ đèn, lại do đích thân Hoàng thượng ban. {Xung} không biết nên ước điều gì cho vẹn."},{"who":"W","text":"Trẫm nói rồi thì giữ lời. Muốn gì cứ mở lời, đừng sợ."},{"who":"me","text":"Xin ân điển cho gia tộc, hay xin {goi} ở lại đêm nay, đều là điều {xung} mong. Chỉ một điều ước, {xung} phải chọn cho đáng."}]}},
{"id":"ky:de_su","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Giữa hành lang rộng, một vị sứ thần mặc phục sức nước ngoài đi ngang, bước chân chậm lại khi thấy người đứng bên cột đá."},{"who":"W","text":"Xin hỏi {goi} một câu về lễ nghi Đại Hy. Lòng thần tò mò, muốn biết người trong cung hiểu lễ đến đâu."},{"who":"me","text":"Sứ thần từ xa đến, hỏi về lễ nghi nước {xung}. Không rõ hỏi để học, hay để thử người trong cung."},{"who":"W","text":"Thần chỉ muốn nghe lời thật từ người hiểu lễ. Xin {goi} chỉ giáo."},{"who":"me","text":"Đáp khiêm cung thì giữ phép, đối lại một câu thơ thì lộ tài. {Xung} đại diện cả cung, không thể nói bừa một lời."}]}},
{"id":"ky:th_kinh","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sớm tinh mơ trong Phật đường, khói trầm bay lờ mờ, chỉ có Thái hậu quỳ trước tượng, tay tự lật từng trang kinh đã mòn."},{"who":"W","text":"Ma ma hầu kinh hôm nay ốm, ai gia tự lật trang kinh. Mắt đã mỏi, chữ nhòe đi, đọc chẳng được trọn câu."},{"who":"me","text":"Một mình quỳ trước Phật từ sớm, tự lật từng trang. {Xung} xin Thái hậu thương lấy mắt mình."},{"who":"W","text":"Có người hầu kinh bên cạnh, ai gia mới thấy bớt lẻ loi. {Goi} muốn ở lại không?"},{"who":"me","text":"Ở lại chép kinh cùng người, hay xin người dạy lễ nghi, {xung} đều xin một lòng hầu hạ Thái hậu."}]}},
{"id":"ky:th_tham","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Chiều tối, chiếc bánh trung thu bày trên đĩa sứ còn nóng hơi, vỏ nứt đôi, từ trong ló ra một mẩu giấy gấp nhỏ."},{"who":"M","text":"{Goi}, nô tỳ bẻ bánh thì thấy mẩu giấy này. Không có tên người gửi, chỉ viết rằng có một mưu đang nhắm vào {goi}."},{"who":"me","text":"Mẩu giấy không tên, nét chữ vội vã. Người báo tin hẳn không muốn bị ai biết, mà vẫn không nỡ để ta mắc bẫy."},{"who":"M","text":"Nô tỳ đã hỏi người dâng bánh, ai cũng nói không biết. Mẩu giấy không rõ ai gài vào."},{"who":"me","text":"Một lời cảnh báo không tên vẫn đáng để tâm. Ta phải đề phòng, và lặng lẽ xem ai là người đã gài mẩu giấy này."}]}},
{"id":"ky:th_chi","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Tết Đoan ngọ, hiên nhà treo đầy ngải cứu, mùi lá thơm hăng, trên bàn bày rễ xương bồ phơi khô cùng mấy túi vải nhỏ."},{"who":"W","text":"Ngồi xuống đây, nghe {xung} dặn. Lá ngải treo cửa, rễ xương bồ ngâm rượu, mùa hạ dịch bệnh dễ vào nhà, phải giữ kỹ."},{"who":"me","text":"Bà dặn từng vị lá, từng rễ, như dặn người nhà. {Xung} nghe, thấy trong lòng ấm lại."},{"who":"W","text":"{Xung} không có con cháu bên cạnh, thấy {goi} thì nhớ người nhà. Dặn xong, {xung} cũng yên lòng."},{"who":"me","text":"{Xung} xin ghi nhớ từng lời. Mùa hạ này, không chỉ {xung}, cả cung cũng sẽ được yên nhờ lời bà dặn."}]}},
{"id":"ky:th_sao","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm Thất tịch, Ngân Hà vắt ngang trời, mặt hồ in cả dải sao, bên bờ có hai bóng người đứng cách nhau mấy bước."},{"who":"W","text":"Đêm nay ai cũng có người cùng ngắm sao, chỉ {xung} là một mình. Không ngờ {goi} cũng đến đây."},{"who":"me","text":"Hai người cùng ngẩng nhìn Ngân Hà, cùng không nói gì. Đêm Thất tịch này, cả hai đều lẻ bóng."},{"who":"W","text":"Thất tịch là đêm của người có đôi. Người không có đôi thì gặp được một tri kỷ cũng là phúc."},{"who":"me","text":"Kết làm tri kỷ, hay cùng đối thơ dưới sao, {xung} đều thấy hợp. Ngân Hà đêm nay hình như cũng muốn làm chứng cho chúng ta."}]}},
{"id":"ky:sv_den","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Một chiếc đèn lồng đứt dây rơi xuống, vỡ tan trên nền đá, nến văng ra thành mấy vệt lửa nhỏ, người vừa bị kéo vào bên hiên còn run rẩy."},{"who":"W","text":"{Goi}... nếu không có {goi} kéo kịp, {xung} đã chết dưới đèn rồi. {Xung} quỳ tạ ơn cứu mạng."},{"who":"me","text":"Ngươi đứng dậy đi, đừng quỳ. Ta chỉ tiện tay kéo ngươi, không có gì phải tạ."},{"who":"W","text":"Với {goi} là tiện tay, với {xung} là cả một mạng. {Xung} không biết lấy gì trả."},{"who":"me","text":"Một mạng người không thể coi nhẹ. Ta nên giữ nàng làm tai mắt, hay đưa nàng về tận cung chủ, phải nghĩ cho thấu."}]}},
{"id":"ky:sv_tuyet","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Đêm tuyết, cổng cung im lìm, lò than nhỏ bên chòi gác tỏa hơi đỏ, trên bếp một nồi nước gừng sôi lục bục."},{"who":"W","text":"Trời lạnh thế này, {goi} đứng ngoài thì chịu sao nổi. Vào đây ngồi bên lò than của {xung}, uống bát nước gừng cho ấm."},{"who":"me","text":"Ngươi gác cổng suốt đêm mà còn nhường chỗ cho ta. Lò than nhỏ thế, ngươi tự sưởi chưa đủ."},{"who":"W","text":"{Xung} đã quen với lạnh rồi. {Goi} là chủ nhân, lỡ nhiễm hàn thì {xung} không gánh nổi."},{"who":"me","text":"Bát nước gừng nóng trong đêm tuyết, ta nhận lấy tấm lòng này. Lúc nào ngươi cần, ta cũng nhớ."}]}},
{"id":"ky:sv_co","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Trong sân sau, từng hàng chậu nước đặt ngay ngắn, người đứng bên hiên nhìn chằm chằm vào đôi tay đang vắt khăn của người làm."},{"who":"W","text":"{Xung} đứng nhìn {goi} làm việc hồi lâu. Tay chân nhanh nhẹn, biết giữ quy củ. {Goi} muốn gì?"},{"who":"me","text":"Được cô cô nhìn đến, {xung} vừa mừng vừa lo. {Xung} chỉ mong được học thêm, làm cho đúng, đừng để ai phải phiền."},{"who":"W","text":"Biết lo là biết giữ mình. Người trẻ như {goi}, ở đây không phải ai cũng được chỉ bảo."},{"who":"me","text":"Xin cô cô dạy quy củ, hay xin về hầu Đức Thọ cung, {xung} đều xin theo lời cô cô chỉ lối."}]}},
{"id":"ky:sv_tre","dlg":{"L":"W","R":"me","lines":[{"who":"nar","text":"Sau hòn non bộ, đứa trẻ co ro trong bóng đá, tay vẫn nắm chặt một cánh bướm giấy, nước mắt chảy dài trên má."},{"who":"W","text":"Bướm bay mất rồi, nhũ mẫu cũng đi đâu mất rồi... Con sợ lắm."},{"who":"me","text":"Đừng khóc, đừng khóc. Ta ở đây rồi, ta đưa con về với mẫu thân của con."},{"who":"W","text":"Con đuổi theo bướm mà lạc đường. Về rồi mẫu thân có mắng con không?"},{"who":"me","text":"Không đâu, người chỉ lo cho con thôi. Ta dắt con về tận tay, con nắm chặt tay ta, đừng buông."}]}},
{"id":"j7:j7-001","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Nắng sớm hắt vào hành lang trước Tân Giả khố, chiếc trâm vàng vừa từ Nội vụ phủ trả về lóe lên một vệt sáng quá đỗi mới."},{"who":"maid","text":"{Goi}, {xung} vừa thấy trâm vàng của {target} được thợ kim hoàn đưa trả. Sáng loáng như cũ, nhưng cầm lên thì đuôi trâm nhẹ tênh."},{"who":"me","text":"Nhẹ tênh ư? Vàng thật đâu nhẹ thế. Nàng vốn thật thà, mất mát gì cũng chỉ biết nuốt vào lòng."},{"who":"maid","text":"Ánh vàng ở đuôi đã phai, lộ màu đồng, bong một vệt. Mà người đến chỗ thợ kim hoàn trước nàng, chính là {plotter}."},{"who":"me","text":"Một vệt đồng dưới lớp vàng mỏng... Ta phải liệu cách nào cho khéo, để nàng khỏi bị thiệt mà ta cũng không thành kẻ lắm chuyện."}]}},
{"id":"j7:j7-002","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng thêu phía tây im ắng, đôi gối mẫu đơn nằm vắt trên tay ghế, chỉ rút từ mép đã bung ra như cánh hoa gặp gió."},{"who":"target","text":"Nửa tháng ngồi thêu, từng cánh mẫu đơn đều là tâm huyết dâng Thái hậu. Vừa ôm vào lòng, hoa đã tuột ra từng mảng thế này."},{"who":"plotter","text":"Ôi chao, sao lại ra nông nỗi ấy? Chắc {goi} khâu vội nên chỉ không chắc, đừng đổ oan cho ai."},{"who":"target","text":"Mép gối bị rút chỉ có chủ ý. Trên tay vịn còn vương một mũi kim lạ, ngay chỗ {goi} vẫn thường ngồi."},{"who":"plotter","text":"Tay vịn ghế ai ngồi chẳng được. {Goi} nói câu ấy, {xung} nghe mà lạnh cả lòng."}]}},
{"id":"j7:j7-003","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Chiều êm, trà vừa rót, khay bánh đậu xanh xanh mướt bày giữa nhã thất mà người nào cắn một miếng cũng nhăn mặt."},{"who":"tool","text":"{Goi}, {xung} bưng khay mà hai tay run mãi. Bánh trông ngon thế, ai ngờ ngọt đã hóa mặn, như bị trộn muối vào."},{"who":"me","text":"Một khay bánh đẹp thế mà thành trò cười trước mặt khách. Ta nên giận hay nên cười đây?"},{"who":"tool","text":"Muối mịn còn vương nơi viền khay, và trên tay áo {plotter} cũng có một ít. Nàng cười vờ vĩnh, còn {xung} chẳng dám nói thêm."},{"who":"me","text":"Chút muối thôi mà đủ nói rất nhiều. Ngươi đừng sợ, ta đang nghĩ nên đáp lại thế nào cho vừa."}]}},
{"id":"j7:j7-004","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phật đường sau điện lặng như tờ, khói hương cuộn quanh bàn thờ, nơi nửa cuộn kinh chép tay đã loang mực đen."},{"who":"target","text":"Ba tháng chép từng chữ, chỉ còn chờ Thái hậu đến lễ, vậy mà mực bắn thành vệt dài trên nửa cuộn kinh. Ai nỡ làm thế?"},{"who":"plotter","text":"Bình mực của {xung} đặt ngay sau bàn, {goi} muốn nói là {xung} ư? Thật oan uổng, {xung} đến đây chỉ để lễ."},{"who":"target","text":"Nắp bình ấy vẫn còn ấm. Mực để một đêm thì đã nguội rồi."},{"who":"plotter","text":"Ấm hay nguội, ai biết được. {Goi} đang giận quá nên nhìn đâu cũng ra kẻ gian."}]}},
{"id":"j7:j7-005","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng đàn trước Dực điện còn mùi dầu thơm của đêm qua, cây tỳ bà vừa nâng lên đã để lòng thòng một sợi dây đứt."},{"who":"target","text":"Đêm qua dây còn căng nguyên vẹn, sáng nay đã đứt đôi. Chiều nay tấu trước Hoàng thượng, {xung} biết làm sao?"},{"who":"plotter","text":"Dây đàn mỏng manh, đứt lúc nào chẳng được. {Xung} chỉ đến sớm để tập đàn thôi."},{"who":"target","text":"Vết cắt phẳng lì, không phải do căng quá. Mạt đàn còn vương trên áo {goi} kia."},{"who":"plotter","text":"Mạt đàn ư? Có lẽ {xung} chạm vào đàn của {goi} lúc nào không hay."}]}},
{"id":"j7:j7-006","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Hành lang gần Phật đường bóng người thưa, một phong thư trắng vừa rơi khỏi tay áo, và có bàn tay nhặt rất nhanh."},{"who":"target","text":"Khoan đã! Phong thư ấy rơi khỏi tay áo ta, nhưng ta chưa từng viết một chữ nào trong đó."},{"who":"tool","text":"Nô tài chỉ thấy rơi nên nhặt lên, định đem trả lại {goi}. Vài câu tình ý trong thư, nô tài chẳng dám đọc kỹ."},{"who":"target","text":"Nét chữ bắt chước rất khéo, nhưng mực còn tươi, góc giấy dính cả vết hồ. Ai viết thay ta mà dám gán vào tay ta?"},{"who":"tool","text":"Nô tài thật không biết gì, xin {goi} tha cho kẻ bé mọn này."}]}},
{"id":"j7:j7-007","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng ghi chép của cung nồng mùi mực, cuốn sổ chi tiêu mở ngay trang có chữ ba lạng bị sửa thành ba mươi."},{"who":"target","text":"Con số trong sổ chi tiêu của cung {xung} bị sửa. Mực sửa còn mới hơn mực các hàng bên."},{"who":"plotter","text":"Chuyện sổ sách mà {goi} nghi cho ai? Người trực sổ sáng nay tuy là kẻ hầu quen của {xung}, nhưng đâu phải thiên hạ."},{"who":"target","text":"Một con số thôi mà đổi từ ba lạng thành ba mươi, tội danh nặng nhẹ khác hẳn. {Goi} nghĩ {xung} không nhìn ra sao?"},{"who":"plotter","text":"{Goi} cứ nhìn đi, sổ này vẫn còn đó cho người ta đối chiếu."}]}},
{"id":"j7:j7-008","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hiên sau điện nắng xiên, lồng chim đung đưa, mà con vẹt lông xanh vừa buông ra một câu khiến kiệu Hoàng hậu khựng lại."},{"who":"target","text":"Trời ơi, nó gọi cả Hoàng hậu bằng giọng ấy ngay lúc kiệu đi qua! {Xung} chưa từng dạy nó câu nào như vậy."},{"who":"plotter","text":"Chim học theo người, ai nuôi nấy chịu. Chẳng lẽ {goi} còn muốn đổ cho {xung}?"},{"who":"target","text":"Trong máng có hạt kê lạ, lồng bị dời sang hướng khác. Hôm qua {goi} ngồi bên nó rất lâu, tay còn cầm hạt kê."},{"who":"plotter","text":"Chỉ là ngắm chim chơi thôi mà. Vẹt của {goi} lắm lời, sao lại trách người đến thăm."}]}},
{"id":"j7:j7-009","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Sân trồng lan trước cung còn đọng sương, chậu lan quý nghiêng hẳn sang một bên, hai nhánh gãy nằm trên nền bùn."},{"who":"target","text":"Ba năm {xung} chăm chút, định dâng Thái hậu dịp lễ. Hai nhánh bị bẻ ngang, nhựa còn tươi nguyên."},{"who":"plotter","text":"Ôi, đáng thương quá. {Xung} đi qua nghe tin liền chạy đến, nào ngờ đã ra nông nỗi này."},{"who":"target","text":"Bùn dưới chân chậu còn dấu một chiếc hài thêu, vết mới in rõ từng mũi chỉ."},{"who":"plotter","text":"Hài thêu thì cung nào chẳng có, {goi} đừng nhìn {xung} bằng mắt ấy."}]}},
{"id":"j7:j7-010","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Vườn nhỏ sau cung, lá trúc xôn xao, và từ bụi trúc ló ra một con mèo tam thể cổ buộc dải lụa lạ, bụng tròn căng."},{"who":"target","text":"Cả đêm {xung} tìm khắp cung chẳng thấy, sáng ra nó từ viện của {goi} bước ra. Ôi tiểu bảo bối của {xung}."},{"who":"plotter","text":"Nó chạy lạc sang viện của {xung} từ đêm qua. {Xung} thấy tội nên cho ăn, lại buộc dải lụa cho đẹp, chớ có ý gì khác."},{"who":"target","text":"Dải lụa ấy {xung} chưa thấy bao giờ, mà bụng nó lại căng tròn thế. {Goi} nuôi nó tử tế đến vậy sao?"},{"who":"plotter","text":"Lòng người cũng có lúc mềm vì một con vật nhỏ. {Goi} cứ ôm nó về đi."}]}},
{"id":"j7:j7-011","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Gió sớm lùa qua phòng thay y phục sau điện, chiếc áo ngự ban treo ngay ngắn mà ở tay áo có một lỗ thủng cháy xém."},{"who":"maid","text":"{Goi}, áo ngự ban {target} định mặc buổi đại lễ chiều nay đã có lỗ thủng ở tay áo, quanh miệng lỗ cháy xém, hương than còn vương."},{"who":"me","text":"Cháy xém, hương than còn vương... Một chiếc áo đại lễ bỗng thành tai họa của người khác."},{"who":"maid","text":"Sáng nay trong phòng chỉ có {plotter} và nô tỳ. Nô tỳ xin thề không làm, chỉ sợ người ta hiểu lầm."},{"who":"me","text":"Ta tin ngươi, nhưng điều đáng sợ là người khác chưa chắc tin. Việc này phải xử sao đây?"}]}},
{"id":"j7:j7-012","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trước bàn thờ Phật đường sau điện Thái hậu, chuỗi tràng hạt gỗ trầm lặng lẽ treo, nơi khuyết một hạt trông như vết răng cắn."},{"who":"target","text":"Chuỗi hạt gỗ trầm Thái hậu ban cho cung {xung} thiếu mất một hạt, sợi xâu bị cắt gọn. Hạt ấy lại nằm trong hộp phấn của {goi}."},{"who":"plotter","text":"Hộp phấn của {xung} ai muốn bỏ gì vào chẳng được? Sáng nay {tool} dọn Phật đường đã đi qua, hỏi hắn xem."},{"who":"target","text":"Đồ Thái hậu ban, thiếu một hạt cũng là tội bất kính. Sợi dây ấy bị cắt có chủ ý đấy."},{"who":"plotter","text":"Ai chủ ý, ai vô tình, chẳng lẽ chỉ nhờ một cái nhìn của {goi}."}]}},
{"id":"j7:j7-013","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Kho lụa của Nội vụ phủ phảng phất hương long não, sổ cống đặt trên án, nơi một dòng ghi tấm lụa thiên thanh đã đi đâu mất."},{"who":"target","text":"Sổ cống thiếu một tấm lụa thiên thanh, mà lại ghi đã phát cho cung {xung}. {Xung} chưa từng nhận."},{"who":"plotter","text":"Chuyện phát lụa nhiều nơi nhiều tay, có khi nhầm lẫn thôi. Người ký nhận tuy là kẻ hầu thân của {xung}, đâu có nghĩa gì."},{"who":"target","text":"Chữ ký nhận ấy có lẫn một nét lạ, không giống người của cung {xung}. Vậy tấm lụa nằm ở đâu?"},{"who":"plotter","text":"Nét lạ hay nét quen, để Nội vụ phủ đối chiếu rồi tự khắc rõ."}]}},
{"id":"j7:j7-014","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Buổi chầu sắp bắt đầu, trước gương phòng thoa phấn, nửa mặt nàng đã ửng lên những mảng đỏ rát."},{"who":"target","text":"Hộp phấn mới vừa thoa lên đã ngứa rát, mặt nổi từng mảng. Phấn có lẫn mùi cỏ lạ, lại đúng lúc sắp vào chầu."},{"who":"plotter","text":"Ôi, {goi} dùng phấn gì mà ra nông nỗi này? Để {xung} xem giúp, phấn ấy có lẽ hỏng rồi."},{"who":"target","text":"Cỏ ngứa lẫn trong phấn là bột cỏ khô, không phải hỏng. {Goi} đứng bên bàn gương từ nãy, cười rất duyên."},{"who":"plotter","text":"Chúng ta chị em, {goi} nói thế là làm thương lòng {xung}."}]}},
{"id":"j7:j7-015","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Hương trầm trong điện chính bỗng chuyển cay xè, cả hàng phi tần quay mặt đi hắt hơi, khăn lụa che nửa mặt."},{"who":"tool","text":"{Goi}, lò hương hôm nay bị đổi sang bột cay, nô tài rửa tay mà vẫn cay cả mắt. Hoàng hậu vừa ngồi xuống đã hắt hơi mấy lượt."},{"who":"me","text":"Ta nín cười đến đau cả bụng, nhưng đây là buổi yết kiến, ngươi biết sợ chưa?"},{"who":"tool","text":"Gói bột còn dư vẫn nằm trong tay áo nô tài. Còn ai đưa gói ấy, nô tài chưa dám khai."},{"who":"me","text":"Chưa dám khai thì cứ giữ cho kỹ. Trước khi người ta tra đến ngươi, ta muốn nghe cho rõ đầu đuôi."}]}},
{"id":"j7:j7-016","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trong nhã thất ngắm hoa, quạt lụa mở ra dưới ánh đèn, chữ đề thơ mực đen còn rõ từng nét uốn."},{"who":"target","text":"Câu chúc thọ {xung} đề lên quạt dâng Thái hậu đã bị sửa thành lời mỉa. Một chữ thôi mà đủ lấy mạng người."},{"who":"plotter","text":"Kinh khủng quá. Nét chữ sửa kia nhìn qua cũng giống chữ của {goi} lắm, ai mà phân biệt nổi."},{"who":"target","text":"Chỉ khác ở nét hất cuối, mực lại đậm hơn hẳn. Người thuộc nét hất ấy cũng chỉ có vài ai."},{"who":"plotter","text":"Vài ai thì cũng đâu phải riêng {xung}. {Goi} nói câu ấy ra, e rằng người nghe sẽ hiểu khác đi."}]}},
{"id":"j7:j7-017","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Đình ngắm trăng trải bạc, tiếng ngâm thơ vừa dứt, người nghe vỗ tay khen rộn cả mặt hồ."},{"who":"target","text":"Bài vịnh trăng ấy {xung} thức mấy đêm mới viết xong. Sao tiếng ngâm kia lại là của {goi}?"},{"who":"plotter","text":"Trăng ai cũng ngắm được, lời thơ ai cũng có thể nghĩ ra. {Goi} đừng vội cho đó là của riêng mình."},{"who":"target","text":"Tờ hoa tiên gốc vẫn nằm trong ngăn tủ của {xung}, mực thấm mép, góc còn nếp gấp. Chữ nào cũng của {xung}."},{"who":"plotter","text":"Một tờ giấy thì nói lên được gì? Đêm nay trăng sáng, {goi} hãy để người ta vui chút đi."}]}},
{"id":"j7:j7-018","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Giữa hành lang hai cung, người người xúm lại, ngọc bội từ tay áo {target} rơi ra, xanh như một giọt nước hồ."},{"who":"maid","text":"{Goi}, ngọc bội Hoàng thượng ban cho {plotter} mất đã một canh giờ, giờ lại nằm trong tay áo {target}. Nàng ấy thề chưa từng thấy."},{"who":"me","text":"Ngọc còn ấm, dây thắt cũng mới. Một kẻ trộm có chịu giữ đồ ngự ban trong tay áo mình không?"},{"who":"maid","text":"Nô tỳ để ý, lúc người ta lục tay áo {target}, {plotter} khẽ cười một thoáng rất nhanh."},{"who":"me","text":"Nụ cười một thoáng ấy ngươi nhớ kỹ lắm. Ta chỉ sợ mình biết quá nhiều mà chưa biết nên nói gì."}]}},
{"id":"j7:j7-019","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Cửa kho nhỏ sau cung mở hé, sợi dây buộc chìa lủng lẳng trên đinh, nút thắt lạ hơn mọi hôm."},{"who":"target","text":"Chìa kho sáng mượn, chiều mới trả, đếm lại thiếu hai hộp trà quý và một cuộn chỉ vàng. {maid} chỉ nhận đã đưa chìa cho người của {goi}."},{"who":"plotter","text":"Người của {xung} mượn chìa để lấy đồ sao? Chìa trả lại, kho lại nguyên, sao {goi} chỉ nhìn một phía."},{"who":"target","text":"Chìa tuy trả về nhưng dây buộc đã đổi nút thắt. {Xung} thắt kiểu nào {xung} nhớ rất rõ."},{"who":"plotter","text":"Nút thắt thì nói lên gì? {Goi} có chứng cứ thì hãy đem ra, đừng ngờ vực suông."}]}},
{"id":"j7:j7-020","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Gió đêm thổi tung vạt áo ngoài cổng nách cung Đông, then cổng vừa cài xong dưới ánh đèn lồng chao đảo; {plotter} thoáng đi qua rồi khuất bóng."},{"who":"target","text":"Ta đi thăm bà cô về, thẻ ra cổng vẫn còn trong tay áo đây. Sao cổng đã đóng sớm hơn giờ lệ?"},{"who":"tool","text":"Có lệnh dặn đóng sớm, nô tài chỉ biết làm theo, xin {goi} đừng làm khó."},{"who":"target","text":"Lệnh dặn nét chữ lạ, dấu đóng sớm ghi trên bản canh. Ai dặn ngươi, nói thật đi."},{"who":"tool","text":"Nô tài không dám nói, chỉ xin {goi} đứng lùi ra khỏi gió, kẻo cảm lạnh."}]}},
{"id":"j7:j7-021","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Suối nước nóng bốc hơi nghi ngút, trên giá ngoài đình chỉ còn một chiếc khăn lụa lạ nằm trơ trọi."},{"who":"target","text":"Bộ xiêm áo thay của {xung} đâu? Vừa bước ra đã chỉ còn chiếc khăn lụa này."},{"who":"plotter","text":"Hi hi, ai bảo {goi} tắm lâu quá, xiêm áo chán đợi nên bỏ đi rồi."},{"who":"target","text":"Khăn thêu hoa này là của {goi}, tiếng cười sau bình phong cũng là của {goi}. Mau đưa áo {xung}!"},{"who":"plotter","text":"Ái chà, {goi} giận trông còn đẹp hơn lúc cười. Thôi được, đi lấy đây."}]}},
{"id":"j7:j7-022","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Bến hồ sen sương đêm phủ trắng, ngọn hoa đăng vừa rời bờ đã trôi xa, chỉ còn mảnh giấy ướt mắc trên bậc đá."},{"who":"target","text":"Hoa đăng khắc tên cha mẹ {xung}, {xung} chuẩn bị cả tháng để thả đêm nay. Dây đứt, đèn trôi mất rồi."},{"who":"plotter","text":"{Xung} cũng vừa tới thôi... tay {xung} ướt vì chạm nước hồ, {goi} đừng nghĩ gì khác."},{"who":"target","text":"Dây đứt phẳng như bị cắt, còn tay áo {goi} ướt cả một mảng. {Xung} chỉ muốn thả cho cha mẹ một ngọn đèn."},{"who":"plotter","text":"{Goi} đừng khóc nữa. Nước hồ lạnh lắm, ngọn đèn kia hẳn đã đến nơi cần đến."}]}},
{"id":"j7:j7-023","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Ở ngự thiện phòng, giỏ vải tiến cống đặt giữa bàn đá, vỏ sẫm màu, hương chua lan khắp gian."},{"who":"target","text":"Chia cho cung ta mà đến tay chỉ còn quả sẫm vỏ, thịt nhũn, tem niêm lại bị bóc. Quả tươi đi đâu hết rồi?"},{"who":"tool","text":"Nô tài chỉ giữ giỏ, còn việc chọn quả thì... {Goi} cứ hỏi người nhận trước đi."},{"who":"target","text":"Người nhận trước là {plotter}. Nghe nói đã chọn hết quả tươi cho mình. Ngươi nhìn thấy chứ?"},{"who":"tool","text":"Nô tài chỉ biết nhún vai, nói ra e mất cả bát cơm."}]}},
{"id":"j7:j7-024","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trong thư phòng của cung, cuộn tranh vừa mở, nét núi sông lạc lõng như bàn tay trẻ con vụng về."},{"who":"target","text":"Một mùa {xung} vẽ bức sơn thủy dâng Hoàng thượng, mở ra lại là bản sao vụng thế này. Ấn nhìn gần giống, giấy lại mới hơn."},{"who":"plotter","text":"Giấy mới hay cũ, ai dám khẳng định? Có lẽ {goi} đã mang nhầm bản tập."},{"who":"target","text":"Hôm qua {maid} thấy người của {goi} đến mượn mực. Ngoài việc ấy ra, ai còn ra vào thư phòng này?"},{"who":"plotter","text":"Mượn một chút mực mà thành kẻ trộm tranh, {goi} thật khéo nghĩ."}]}},
{"id":"j7:j7-025","dlg":{"L":"plotter","R":"target","watch":true,"lines":[{"who":"nar","text":"Chiều lộng gió, sân cung lạnh lốm đốm cỏ, nơi một sợi dây diều vắt lủng lẳng trên cành táo."},{"who":"plotter","text":"Hu hu, con diều hạc của {xung} đứt dây rơi vào đây, mà {goi} giữ lại để rình mò nhà {xung} ư?"},{"who":"target","text":"Giữ diều của {goi} làm gì? {Xung} mới tới đây, diều còn chưa thấy mặt."},{"who":"plotter","text":"Vậy sao dây còn vắt trên cây táo đây? Nhà cung lạnh chẳng ai dám bén mảng."},{"who":"target","text":"Dây có vết cắt phẳng lì. Diều đứt chứ chẳng phải rơi, {goi} xem kỹ đi."}]}},
{"id":"j7:j7-026","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Cổng sau cung lặng gió, chiếc bọc đồ cũ mở toang trên đất, vòng bạc lấp lánh bên đôi hài sờn."},{"who":"target","text":"Nó bán đồ để lo thuốc cho mẹ, chiếc vòng bạc này nó giữ bao năm nay. Xin {goi} tha cho nó một lần."},{"who":"plotter","text":"Vòng bạc có dấu cung, đem bán ngoài cung là phạm lệ. {Xung} chỉ làm theo phép, tâu lên Cung Chính ti."},{"who":"target","text":"Một đôi hài cũ, một chiếc vòng, cả gia sản nó chỉ có thế. Phép nghiêm cũng nên có tình."},{"who":"plotter","text":"Tình thì ai cũng có, nhưng phép là phép. {Goi} đừng bắt {xung} lựa chọn."}]}},
{"id":"j7:j7-027","dlg":{"L":"tool","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Nửa đêm gian bếp nhỏ sau cung vang lên một tiếng nổ giòn, nắp vò bay vọt, mùi rượu mơ thơm ngào ngạt cả hành lang."},{"who":"tool","text":"Là rượu của {goi} nhờ ủ, nắp vò niêm bằng dải lụa của {goi} đây. Nô tài chỉ làm theo thôi."},{"who":"plotter","text":"{Goi} nói bậy! Dải lụa ấy ai mà chẳng lấy được, đừng vu oan cho {xung}."},{"who":"tool","text":"Nô tài đâu dám vu cho {goi}. Ma ma đang cho tra, xin {goi} nói đỡ cho nô tài một lời."},{"who":"plotter","text":"Rượu mơ thơm thế ai không nhớ? Nhưng rượu ấy chẳng phải của {xung}."}]}},
{"id":"j7:j7-028","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trong chùa của cung, khói trầm lặng lẽ cuộn bên giỏ quẻ, tờ quẻ vừa mở ra đen như mực giữa lòng tay."},{"who":"target","text":"{Xung} rút quẻ rõ ràng là thượng cát, vậy mà mở ra lại là đại hung. Chữ in giống, giấy lại mới hơn các tờ khác."},{"who":"plotter","text":"Quẻ nào mà chẳng do trời định. {Goi} đừng đem lời oán trách cho người ngoài."},{"who":"target","text":"Người trông giỏ quẻ nói {goi} đến xin xem quẻ trước {xung}. Mực tờ này chưa khô hẳn đâu."},{"who":"plotter","text":"Xem quẻ trước cũng là phạm lệ sao? {Goi} thật hay ngờ vực."}]}},
{"id":"j7:j7-029","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng chuẩn bị yến rộn tiếng giày, trên giá chỉ còn chiếc hài thêu cánh bướm lẻ loi, bên cạnh vết bùn mới."},{"who":"target","text":"Chiếc hài bên trái của {xung} mất ngay trước giờ yến, đường thêu cánh bướm giờ chỉ còn một nửa."},{"who":"plotter","text":"Hài mất thì tìm, sao lại nhìn {xung}. Trong phòng đâu chỉ có {xung} và vài cung nữ."},{"who":"target","text":"Ống tay áo {goi} hôm nay sao lại phồng lên thế? Còn vết bùn mới này nữa."},{"who":"plotter","text":"Tay áo phồng vì mang khăn tay, {goi} đừng nghi oan người ta."}]}},
{"id":"j7:j7-030","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hành lang trước phòng Thái hậu tĩnh lặng, vòng ngọc vừa chạm đất đã nứt làm đôi, tiếng khẽ mà nghe nhói tim."},{"who":"target","text":"Vòng ngọc Thái hậu ban cho {xung} nứt ngay khi {xung} cúi chào. Vết nứt thẳng như bị dao khắc ngầm."},{"who":"plotter","text":"Ngọc quý cũng có lúc nứt, {goi} đừng lo. {Xung} chỉ vừa đỡ tay {goi}, nào ngờ ngọc đã vỡ."},{"who":"target","text":"Người đỡ tay {xung} lúc ấy là {goi}, nụ cười lại chậm hơn lời hỏi han. Bụi ngọc còn vương trên tay áo."},{"who":"plotter","text":"Ngọc vỡ thì bụi vương, đâu có gì lạ. {Goi} nghĩ nhiều quá rồi."}]}},
{"id":"j7:j7-031","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trong phòng ghi sổ của Kính sự phòng, đèn dầu hắt lên trang sổ thị tẩm, nơi một dòng chữ nhạt màu nằm lọt giữa hàng mực đậm."},{"who":"target","text":"Ngày của cung {xung} trong sổ đã bị đổi sang tên {goi}, mực sửa nhạt hơn mực cũ. Ai đã động đến sổ?"},{"who":"plotter","text":"{Xung} đâu có lui tới nơi này. Sổ ấy có người coi giữ, {goi} hỏi {xung} làm gì."},{"who":"target","text":"{tool} bối rối nói đêm ấy sổ nằm ngoài tủ khóa một khắc. Chỉ một khắc đã đủ để sửa một dòng."},{"who":"plotter","text":"Một khắc ngắn ngủi mà {goi} dám buộc tội, nghe mà chua xót."}]}},
{"id":"j7:j7-032","dlg":{"L":"tool","R":"target","watch":true,"lines":[{"who":"nar","text":"Gian ngự thiện phòng hơi nước mờ mịt, bát yến sào vừa dọn ra đã tanh nồng, sợi yến ngắn vụn nổi lềnh bềnh trên nước."},{"who":"tool","text":"Nô tài xin lỗi {goi} muôn vàn. Yến thượng hạng của cung {goi} không biết đã đổi đi đâu, chỉ còn loại rẻ này."},{"who":"target","text":"Yến ấy ta dùng vì chống ho, bát này mùi tanh, sợi ngắn lại vụn thế. Đổi ở đâu, ai đổi?"},{"who":"tool","text":"Người nhận đồ ở bếp là kẻ hầu của {plotter}. Nô tài chỉ dám nói đến đó thôi."},{"who":"target","text":"Chỉ đến đó thôi cũng đủ rồi. Ngươi đừng sợ, ta không trách người giữ bát."}]}},
{"id":"j7:j7-033","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Sáng ra, màn the còn vương mùi hương gắt, chăn gối mới xông thơm mà đặt đầu xuống đã nhức đến choáng váng."},{"who":"maid","text":"{Goi}, thầy thuốc vừa ngửi ra hạt thuốc lạ trộn trong túi thơm của bộ chăn gối. Túi ấy hôm qua chính nô tỳ mang đến."},{"who":"me","text":"Hôm qua ngươi bảo ai đưa?"},{"who":"maid","text":"Nô tỳ nói do cung {plotter} gửi tặng. Nô tỳ sợ mình đã vô tình đem họa đến cho {goi}."},{"who":"me","text":"Ngươi không có lỗi. Mùi gắt thế này, ta không muốn nằm thêm một đêm. Nhưng đáp lễ người tặng sao cho khéo?"}]}},
{"id":"j7:j7-034","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng lật thẻ bài lặng như tờ, khay thẻ chỉ còn một khoảng trống lõm giữa hàng thẻ ngọc, hộp thẻ lệch sang một bên."},{"who":"target","text":"Thẻ ghi tên {xung} biến khỏi khay ngay trước giờ Hoàng thượng chọn. Khay vẫn còn nguyên thẻ của {goi}."},{"who":"plotter","text":"Hoàng thượng chọn hay không là do ý trời. Thẻ mất thì tìm, chứ có gì {goi} phải hoảng."},{"who":"target","text":"{tool} nói chỉ rời khay một khắc để bưng trà. Chỉ một khắc, hộp thẻ đã dịch sang bên."},{"who":"plotter","text":"Hôm nay {goi} nói nhiều quá, {xung} nghe mà thấy bất an."}]}},
{"id":"j7:j7-035","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Cây bút lông quý nằm trên án, ngòi cắt gọn như bị dao rạch, ánh mực khô lặng lẽ nơi nghiên của người ngồi cạnh."},{"who":"target","text":"Bút này là quà của cha {xung}, vậy mà ngòi bị cắt đi một nửa ngay trước buổi viết thơ dâng. Nửa còn lại nằm cạnh nghiên mực của {goi}."},{"who":"plotter","text":"Nửa ngòi ấy lăn qua đó lúc nào {xung} đâu hay. {Goi} đừng vội gán cho người ta."},{"who":"target","text":"Dưới bàn còn vương một sợi lông lạ. Vết cắt gọn như thế, chẳng ai vô tình mà làm."},{"who":"plotter","text":"Chỉ là cây bút thôi mà, {goi} làm như mất cả mạng."}]}},
{"id":"j7:j7-036","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Mảnh men lam vương trên nền sảnh khách, sáng rực như một vệt trời, chiếc bình vỡ làm đôi giữa tiếng xì xào."},{"who":"plotter","text":"Bình hoa men lam trong sảnh của {goi} vỡ rồi, trên mảnh sứ lại có dấu tay của cung nữ nhà {goi}. {Xung} nghĩ vụng về thế thì phải phạt."},{"who":"me","text":"Dấu tay trên mảnh sứ thì dễ thấy. Nhưng {xung} lại nhìn mảnh vỡ nằm lệch hướng cửa, như thể bị hất từ phía bàn của {goi}."},{"who":"plotter","text":"{Goi} đang nói gì vậy? {Xung} chỉ muốn nhắc {goi} giữ nề nếp trong cung."},{"who":"me","text":"Nề nếp thì {xung} giữ. Nhưng phạt người trước khi hiểu ra đầu đuôi lại là lỗi của {xung}."}]}},
{"id":"j7:j7-037","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng đàn trong cung lặng lẽ, mặt cây đàn tranh có vết nứt nhỏ như sợi tóc, mạt gỗ mịn vương trên khay trà đặt bên cạnh."},{"who":"target","text":"Cho {goi} mượn một đêm, trả về đã nứt mặt đàn. Đàn tranh ấy {xung} nâng niu từ lâu."},{"who":"plotter","text":"Đàn nứt từ trước rồi, {xung} đâu dám làm hỏng. {Xung} còn nhờ người chứng kiến, nói dối làm gì."},{"who":"target","text":"Vết nứt còn mới, gỗ còn trắng. Mạt gỗ vương ở chính khay trà {goi} mượn đây."},{"who":"plotter","text":"Khay trà đặt cạnh đàn thì bám bụi gỗ cũng lạ gì. {Goi} nghĩ sao thì nghĩ."}]}},
{"id":"j7:j7-038","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Sáng sớm trên tường hành lang cung Tây có tờ giấy mới dán, hồ ướt còn nhỏ từng giọt xuống nền gạch xám."},{"who":"target","text":"Tờ giấy này bêu riếu {xung}, chữ xiêu vẹo như viết bằng tay trái. Hồ còn ướt, vừa dán chưa lâu."},{"who":"plotter","text":"Ai mà ác thế, bêu riếu {goi} giữa chốn công cộng. Để {xung} sai người gỡ xuống ngay."},{"who":"target","text":"Người dán chắc còn gần đây. Ai đi ngang, chẳng ai không đọc nhẩm."},{"who":"plotter","text":"Đọc nhẩm thì lòng cũng đã nhớ. {Goi} cứ để {xung} lo, đừng đứng đây cho người ta nhìn."}]}},
{"id":"j7:j7-039","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng đọc sách im ắng sau buổi soát, trên nền gạch nằm một cuốn thoại bản bìa còn mới, giấy vàng chưa một nếp gấp."},{"who":"target","text":"Cuốn sách cấm ấy rơi ra từ tay áo {xung}, mà {xung} chưa từng thấy nó. Mới tinh, chưa một vết gấp."},{"who":"plotter","text":"Sách cấm trong người, {goi} còn dám nói chưa thấy. Ma ma đã tận mắt trông rồi."},{"who":"target","text":"Giấy vàng và nét in này giống hệt bộ sách ở phòng {goi}. {Xung} đỏ mặt vì oan, không phải vì thẹn."},{"who":"plotter","text":"Bộ sách giống nhau thiếu gì. {Goi} đừng kéo người vô tội vào."}]}},
{"id":"j7:j7-040","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phòng ấn của cung thoang thoảng mùi son đỏ, tờ thỉnh nguyện xin than sưởi mang dấu ngọc nhỏ, mực in nhạt lệch một chút."},{"who":"target","text":"Tờ thỉnh nguyện xin thêm than sưởi mang dấu ấn của {xung}, mà {xung} chưa hề ký. Con dấu in lệch, nét khắc phụ cũng mờ."},{"who":"plotter","text":"Con dấu nằm trong phòng ấn, ai có phép ra vào cũng đóng được. Sao lại nghi người của {xung}?"},{"who":"target","text":"Con dấu ấy để cạnh bàn kẻ hầu thân tín của {goi}. Than sưởi là việc sống còn của cả cung {xung}."},{"who":"plotter","text":"Cung {goi} thiếu than sưởi thì thật đáng thương, nhưng lời buộc tội kia thì quá nặng."}]}},
{"id":"j7:j7-041","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Kho than của Nội vụ phủ xám xịt, sọt than phát cho cung ta nhẹ bẫng khi nhấc lên, lớp rơm lót cao hơn lớp than."},{"who":"target","text":"Sổ ghi đủ số, mà sọt than vừa nhấc lên đã nhẹ một nửa. Lót rơm cao thế này, than nằm mỏng dính."},{"who":"tool","text":"Nô tài chỉ coi kho, xin {goi} đừng giận. Than xuất đúng số trong sổ."},{"who":"target","text":"Hôm qua {plotter} có ghé thăm kho. Ngươi nói ta nghe, ngoài nàng ra còn ai?"},{"who":"tool","text":"Mùa đông lạnh lắm, nô tài chỉ xin giữ lại bát cơm."}]}},
{"id":"j7:j7-042","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên ngự thiện phòng, hộp cơm mở ra chỉ có cơm khô và đĩa rau nhạt, niêm bếp đóng sai cả ngày."},{"who":"tool","text":"{Goi}, nô tài khổ lắm... ba bữa liền cung {target} chỉ nhận cơm khô rau nhạt, món mặn đều bị cắt."},{"who":"me","text":"Ba bữa liền, ai nỡ lòng làm vậy với một người? Mắt ngươi rưng rưng vì sao?"},{"who":"tool","text":"Người cắt là nô tài, nhưng bị ép bởi lời dặn của {plotter}. Hộp cơm nhẹ, niêm bếp lại đóng sai ngày."},{"who":"me","text":"Nỗi sợ của ngươi ta hiểu rồi. Ta cần nghĩ xem nên giúp {target} bằng cách nào mà không hại ngươi."}]}},
{"id":"j7:j7-043","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Trong phòng trà của cung, hũ mật ong rừng chỉ còn một lớp mỏng, một dòng kiến bò rỉ rả từ miệng hũ ra tận cửa."},{"who":"target","text":"Hũ mật dành pha trà dâng Thái hậu bị múc gần cạn rồi. Kiến bò từ miệng hũ ra tận hành lang cung {goi}."},{"who":"plotter","text":"Kiến thì bò khắp nơi, {goi} nhìn kiến mà trách người à? Thật là buồn cười."},{"who":"target","text":"Kiến bò theo vệt mật nhỏ từng giọt dọc đường, như cố ý để chỉ đường cho {xung}."},{"who":"plotter","text":"Ai chỉ đường cho ai, chỉ có kiến là rõ. {Goi} cứ theo chúng mà tìm đi."}]}},
{"id":"j7:j7-044","dlg":{"L":"plotter","R":"target","watch":true,"lines":[{"who":"nar","text":"Đêm khuya hành lang sau cung, gió lay lá trúc, bát cơm nửa vơi nằm cạnh gốc cây với vài sợi lông mèo lấp lánh dưới trăng."},{"who":"plotter","text":"Khuya thế này mà {goi} ra đây một mình, tay còn giấu bát gì? Người ta đang bàn tán về {goi} đấy."},{"who":"target","text":"{Xung} chỉ ra hóng gió thôi, {goi} hãy trở về nghỉ đi."},{"who":"plotter","text":"Hóng gió mà mang cơm theo? {Xung} sẽ không nói với ai đâu, nếu {goi} chịu nói cho {xung} nghe."},{"who":"target","text":"Có những chuyện nhỏ, nói ra rồi lại thành chuyện lớn. Xin {goi} cứ để nó là của riêng {xung}."}]}},
{"id":"j7:j7-045","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hành lang gần Phật đường sương lạnh, tiếng chuông xa vọng lại khi lời đồn về giấc mộng lệch mũ lan khắp cung."},{"who":"target","text":"{Xung} nằm mộng thấy Hoàng thượng đội mũ lệch, chưa kể cho ai nghe. Sao lời đồn lại bắt đầu từ chính chỗ này?"},{"who":"plotter","text":"Giấc mộng lệch mũ ấy {xung} cũng nghe người ta bàn. {Goi} nghĩ lời đồn ra từ miệng {xung} sao?"},{"who":"target","text":"Hành lang Phật đường chỉ có {goi} và {xung} qua lại. Giấc mộng ấy {xung} chỉ nói một mình trong bóng tối."},{"who":"plotter","text":"Bóng tối cũng có tai. {Goi} cẩn thận lời nói, kẻo thành điềm chẳng lành."}]}},
{"id":"j7:j7-046","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Hành lang cung Đông vắng người, tiếng thì thầm lướt qua như gió luồn dưới mái ngói, đến tai nô tỳ trước cả tiếng chuông canh."},{"who":"maid","text":"{Goi}, nô tỳ nghe được lời đồn cung {target} có tin vui, mà nàng còn chưa thị tẩm tháng này. Người rỉ tai đầu tiên là {plotter}."},{"who":"me","text":"Chưa thị tẩm mà đã có tin vui? Lời đồn như thế chỉ để đẩy nàng vào mắt Hoàng hậu."},{"who":"maid","text":"Nô tỳ nghe từ khi chưa ai hay, trong lòng bất an lắm. Tin ấy giờ lan cả cung rồi."},{"who":"me","text":"Một lời đồn nhẹ như khói mà đủ làm bỏng tay người ta. Ta phải tính xem nên chặn hay nên tránh."}]}},
{"id":"j7:j7-047","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Hành lang cung Tây đầy tiếng bước chân vội, tấm thẻ tên nhỏ trong tay người này nom như vừa dính mực chưa khô."},{"who":"plotter","text":"{Xung} đã xin Nội vụ phủ điều {maid} sang cung mình rồi. Tay thêu khéo như thế, ở cung {goi} cũng uổng."},{"who":"me","text":"{maid} theo {xung} nhiều năm, đâu phải món đồ cho mượn. Thẻ tên trong sổ cung nhân lại bị sửa sang cung khác."},{"who":"plotter","text":"Sổ cung nhân sửa hay không, {xung} nào hay. {Goi} đừng nghi oan."},{"who":"me","text":"Chữ sửa mới hơn chữ cũ, dấu niêm cũng lệch. {Xung} đang nghĩ nên làm gì để giữ người của {xung}."}]}},
{"id":"j7:j7-048","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Đình hóng mát gió nhẹ, chiếc vòng bạc nằm trên khay giữa hai dải lụa niêm, và {maid} vừa chạy vừa thở dốc đến."},{"who":"maid","text":"{Goi}, nô tỳ nghe chuyện lạ lắm! {plotter} và {target} cược chiếc vòng bạc xem tối nay Hoàng thượng ghé cung nào."},{"who":"me","text":"Cược chơi cho vui mà ngươi chạy đến thở không ra hơi. Chuyện gì khiến ngươi gấp thế?"},{"who":"maid","text":"{plotter} đã nhờ người báo tin trước, định thắng chắc. Vòng ấy còn đặt trên khay, dải lụa niêm của hai bên vẫn nguyên."},{"who":"me","text":"Hóa ra thắng thua đã định trước khi ván chơi bắt đầu. Ta vừa muốn cười, vừa thấy thương cho người sắp bị lừa."}]}},
{"id":"j7:j7-049","dlg":{"L":"plotter","R":"target","watch":true,"lines":[{"who":"nar","text":"Phòng thêu ngoài sân tràn nắng, tấm khăn thêu mở ra giữa hai bàn tay, hai con vịt béo tròn ngơ ngác nhìn ra."},{"who":"plotter","text":"Ha ha, đôi uyên ương của {goi} thành hai chú vịt béo ục ịch rồi! Chỉ khác mỗi cái cổ thôi."},{"who":"target","text":"Chỉ thêm cái cổ vịt mà thành ra thế này. Sợi chỉ đỏ trên tay {goi} lạ lắm, chẳng phải chỉ của {xung}."},{"who":"plotter","text":"Ôi, cười đến nấc rồi. Vịt hay uyên ương, Hoàng thượng nhìn cũng thấy dễ thương như nhau."},{"who":"target","text":"Tặng Hoàng thượng mà thành ra vịt, {goi} đền {xung} khăn khác đi."}]}},
{"id":"j7:j7-050","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Con đường hẹp giữa hai cung tối đen như mực, chiếc đèn lồng vừa tắt còn nghi ngút làn khói mỏng, và vạt áo ướt sũng chậu cảnh."},{"who":"target","text":"Đèn dẫn đường bỗng tắt giữa đêm, ta lỡ chân sa vào chậu cảnh, ướt cả vạt áo. Bấc đèn vẫn còn ấm."},{"who":"tool","text":"Nô tài vừa thấy bóng người chạy khuất, vạt váy giống áo của {plotter}, nhưng đêm tối nên nô tài không dám chắc."},{"who":"target","text":"Bấc còn ấm, khói còn mới, hẳn chưa chạy xa. Ngươi thấy rõ đến đâu thì nói đến đó."},{"who":"tool","text":"Nô tài chỉ thấy vạt váy thoáng qua, xin {goi} thương mà lượng thứ."}]}},
{"id":"j7:j7-051","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Mái hiên cung Tây lặng gió, chiếc chuông gió vẫn khẽ rung, một sợi dây mảnh kéo thẳng ra cây liễu bên cung ai đó."},{"who":"target","text":"Chuông gió trước hiên cung {xung} kêu leng keng suốt đêm khi chẳng có gió. Sáng nay mắt {xung} thâm quầng."},{"who":"plotter","text":"Chuông kêu cũng là điềm lành, {goi} ngủ không được mà đổ cho {xung} sao?"},{"who":"target","text":"Sợi dây buộc chuông nối ra cây liễu bên cung {goi}. Gió nào lại thổi từ xa như thế?"},{"who":"plotter","text":"Cây liễu ở đó từ bao giờ, dây ai buộc ai biết. {Goi} thức đêm nên lẫn rồi."}]}},
{"id":"j7:j7-052","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Ở tiền sảnh cung, chiếc áo choàng lông trải trên án, từng mảng lông bết lại như cánh chim ướt, vệt dầu lan nơi vạt áo."},{"who":"target","text":"Áo choàng lông {xung} cho {goi} mượn đi chùa, trả về vết dầu lan khắp vạt, lông bết từng mảng. Đồ ấy {xung} quý lắm."},{"who":"plotter","text":"Trả nguyên vẹn là {xung} biết, ai làm bẩn thì {xung} không hay. Đường đi chùa xa, ai biết ai chạm vào."},{"who":"target","text":"{maid} thấy vệt dầu từ lúc {goi} khoác áo lên xe. Sao nay lại không nhớ?"},{"who":"plotter","text":"Một vệt dầu thì có gì quan trọng, {goi} làm như mất cả gia sản."}]}},
{"id":"j7:j7-053","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hiên sau điện nắng chiều dịu xuống, nửa chiếc vòng ngọc nằm trong lòng bàn tay, mép sứt còn sắc như một nỗi nhớ."},{"who":"target","text":"Đôi vòng ngọc Hoàng thượng ban chung, nay {xung} chỉ còn nửa chiếc. Nửa kia {goi} nhặt được mà không chịu trả."},{"who":"plotter","text":"Nhặt được là của nhặt, {xung} giữ cho tới khi có người đến nhận chủ."},{"who":"target","text":"Vết sứt ở hai nửa khớp nhau, như hai nửa của một nỗi niềm. Xin {goi} trả lại cho {xung}."},{"who":"plotter","text":"Ngọc đã vỡ, có ghép lại cũng chẳng còn nguyên. {Goi} giữ nửa ấy làm gì?"}]}},
{"id":"j7:j7-054","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hành lang giữa hai cung gió thốc tà áo, lời mời trà vừa truyền qua ba miệng đã khiến Hoàng hậu nhíu mày không vui."},{"who":"target","text":"Lời mời trà {xung} nhờ nhắn đến Hoàng hậu bị biến thành câu lấc cấc. {maid} truyền lại ngay, mà lời đầu qua miệng {goi}."},{"who":"plotter","text":"Lời nói gió bay, qua mấy miệng thì tránh sao khỏi sai lệch. {Xung} chỉ là truyền lời giùm thôi."},{"who":"target","text":"Người ta nghe được, Hoàng hậu cũng nghe được. Sai một chữ mà cung {xung} mang tiếng vô lễ."},{"who":"plotter","text":"Nếu {goi} sợ thế, hãy tự đến trình bày với Hoàng hậu, đừng trách lời truyền."}]}},
{"id":"j7:j7-055","dlg":{"L":"tool","R":"target","watch":true,"lines":[{"who":"nar","text":"Cổng cung trước giờ chầu mặt trời lên cao, kiệu đón vắng bóng đến khi nàng đã đi bộ dưới nắng, mồ hôi thấm vạt áo."},{"who":"tool","text":"Kiệu đón {goi} bị đổi giờ, nô tài tội lỗi muôn phần. Bản lịch kiệu có chữ sửa, nô tài thấy mà không dám nói."},{"who":"target","text":"Đến muộn nửa khắc, ta phải đi bộ dưới nắng, áo ướt mồ hôi. Ai dặn dời giờ?"},{"who":"tool","text":"Người ấy mang thẻ của cung {plotter}. Nô tài thú nhận, xin {goi} đừng nói ra là nô tài khai."},{"who":"target","text":"Ngươi cứ yên tâm, lời ngươi nói ta chưa vội đem ra."}]}},
{"id":"j7:j7-056","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Đình tấu nhạc tiếng đàn còn vương, chiếc sáo ngọc cha để lại nằm trên khăn tay, miệng thổi sứt một góc nhỏ."},{"who":"target","text":"Sáo ngọc này cha {xung} để lại. {Xung} đưa lên môi, chưa thành tiếng đã thấy sứt một góc, ngọc vụn vương trên khăn tay."},{"who":"plotter","text":"Hôm qua {xung} có mượn xem, nhưng trả lại nguyên vẹn. Ngọc dễ vỡ, {goi} đừng đổ oan."},{"who":"target","text":"Vết sứt thẳng như bị gõ vào cạnh bàn đá. Nó là chút còn lại của cha, {xung} không còn gì khác."},{"who":"plotter","text":"Nếu {xung} sơ ý thì xin lỗi, nhưng ngọc sứt lúc nào ai chứng kiến."}]}},
{"id":"j7:j7-057","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Vườn mai cuối đông phủ tuyết, nơi ngưỡng cửa một cành mai nằm lặng lẽ, tuyết còn bám đầu cành, kèm tờ giấy mực xanh nhỏ."},{"who":"target","text":"Cành mai và mảnh giấy ghi chữ xin lỗi, chữ run run. Không rõ ai đặt trước cửa {xung} trong đêm tuyết."},{"who":"plotter","text":"Chắc ai đó nghĩ mình có lỗi mà chưa dám đến nói. {Goi} cứ nhận lấy, đừng giận nữa."},{"who":"target","text":"Hôm trước {xung} có giận một người, mà người ấy cũng giận lại {xung}. Mực xanh... trông quen lắm."},{"who":"plotter","text":"Quen mà chưa cần gọi tên. Cành mai thơm lắm, {goi} hãy cắm vào bình nhé."}]}},
{"id":"j7:j7-058","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Kho thuốc của cung dậy mùi sâm ngai ngái, củ nhân sâm ban sau cơn ốm nằm trên khay với đầu rễ nhẵn thín, vết cắt còn tươi."},{"who":"target","text":"Củ sâm Thái hậu ban cho {xung} sau trận ốm bị cắt mất một nửa, đầu rễ nhẵn thín. Vết còn tươi."},{"who":"plotter","text":"{Goi} nói như thể {xung} lấy. Sâm quý ai cũng muốn, nhưng {xung} nào dám."},{"who":"target","text":"{maid} nói chỉ {goi} từng cầm đến hộp thuốc. Mùi sâm còn tỏa ra từ chính hộp của {goi}."},{"who":"plotter","text":"Mùi sâm thì thuốc nào chẳng có. {Goi} hãy cẩn thận lời nói."}]}},
{"id":"j7:j7-059","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Cầu gỗ bên hồ sen lún nghiêng dưới chân, một thân người bấu chặt lan can, nơi sợi chỉ vải mắc vào mép gỗ."},{"who":"target","text":"Tấm gỗ lát cầu bị tháo lỏng ốc, {xung} suýt rơi xuống hồ sen. Ốc còn nằm cạnh cầu đây."},{"who":"plotter","text":"Ôi chao, {goi} bám lan can nom như mèo ướt vậy, suýt nữa thì cười rồi."},{"who":"target","text":"Lan can còn vương sợi chỉ vải giống hệt áo {goi} mặc hôm nay."},{"who":"plotter","text":"Sợi chỉ dài ngắn đều giống nhau cả. {Goi} lo lên bờ thay áo đi."}]}},
{"id":"j7:j7-060","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Phòng pha trà của Thái hậu thoảng hơi lạnh, ấm trà dâng buổi sớm đặt trên khay đã nguội ngắt như đêm hôm qua."},{"who":"tool","text":"{Goi}, nô tài lén kể: nước nóng phải đi qua bếp, nhưng bị kẻ hầu của {plotter} chặn lại, xô đến đổ mất nửa ấm."},{"who":"me","text":"Một ấm trà nguội dâng Thái hậu cũng đủ thành tội. Ngươi bị xô như thế có đau không?"},{"who":"tool","text":"Nô tài chỉ sợ bị trách tội. Vết nước đổ ngoài cửa bếp vẫn còn đó, ai muốn xem thì xem."},{"who":"me","text":"Ta nghe ngươi rồi. Ta đang nghĩ nên giúp {target} thế nào để trà nóng đến tay Thái hậu mà không hại ai."}]}},
{"id":"j7:j7-061","dlg":{"L":"tool","R":"target","watch":true,"lines":[{"who":"nar","text":"Cổng Nội vụ phủ lặng người, hộp quà mừng buộc dải lụa niêm còn nguyên, chờ chờ nơi bậc đá như người đợi tin."},{"who":"tool","text":"Hộp quà mừng của {goi} gửi cho biểu muội bị giữ lại, lý do «chưa duyệt». Nhưng hộp của {plotter} cùng buổi đã qua cổng."},{"who":"target","text":"Quà mừng cưới thì không thể trễ giờ. Ai dặn giữ hộp của ta?"},{"who":"tool","text":"Người dặn mang lệnh bằng miệng, không có dấu. Nô tài chỉ dám khai đến đây."},{"who":"target","text":"Lệnh miệng không dấu, dải lụa niêm còn nguyên. Ta thương cho cả hộp quà lẫn người nhận."}]}},
{"id":"j7:j7-062","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Hiên treo lồng trống không, cửa lồng mở toang đón gió đêm, chiếc khăn thơm vắt hờ lên lan can như quên ai đó."},{"who":"target","text":"Họa mi {xung} nuôi ba năm đã bị thả khỏi lồng giữa đêm. Cửa lồng mở toang, chim bay biệt tăm."},{"who":"plotter","text":"Chim vốn muốn bay, {goi} đừng đau lòng. Biết đâu nó vừa thoát được chiếc lồng."},{"who":"target","text":"Khăn thơm vắt trên lan can này là khăn của {goi}. Còn chiếc lông lạ rơi dưới hiên..."},{"who":"plotter","text":"Khăn của {xung} lạc đâu cũng có thể. {Goi} đừng khóc nữa."}]}},
{"id":"j7:j7-063","dlg":{"L":"plotter","R":"target","watch":true,"lines":[{"who":"nar","text":"Phòng đọc chung rộn tiếng cười, và giữa phòng một giọng ngâm cao vút đọc lên những câu thơ viết trong đêm buồn."},{"who":"plotter","text":"«Đêm nay ngồi nhớ ai mà lệ rơi thành chữ...» Ha ha, thơ của {goi} đây, nghe mà ngọt cả tai."},{"who":"target","text":"Đó là thơ riêng của {xung}. Sổ thơ vừa quay về hộc, mép giấy quăn vì cầm vội, bìa còn dấu tay mực."},{"who":"plotter","text":"Thơ hay thì cho mọi người cùng nghe, {goi} giận làm gì."},{"who":"target","text":"Những câu ấy {xung} viết lúc buồn nhất, không phải để làm trò vui cho thiên hạ."}]}},
{"id":"j7:j7-064","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Nhã thất sau điện sáng dịu, bức bình phong giấy dán thoáng một lỗ nhỏ rách mép, mảnh giấy vụn rơi trên nền gỗ."},{"who":"target","text":"Bình phong của ta rách một lỗ vừa đủ để nhòm. Hôm qua ta nói với ma ma những gì, chắc có kẻ nghe hết."},{"who":"tool","text":"Nô tài bắt gặp vạt áo {plotter} thấp thoáng sau bình phong, nhưng không dám khẳng định, chỉ thoáng qua thôi."},{"who":"target","text":"Mép giấy mới rách, mảnh vụn còn dưới đất. Ngươi nhớ kỹ vạt áo ấy màu gì?"},{"who":"tool","text":"Màu giống áo {plotter} thường mặc, xin {goi} đừng làm to chuyện kẻo nô tài khó sống."}]}},
{"id":"j7:j7-065","dlg":{"L":"target","R":"plotter","watch":true,"lines":[{"who":"nar","text":"Phật đường trong cung ngày vọng, khói hương nghi ngút trên mâm lễ chay, dưới lá chuối ló ra một miếng thịt khô."},{"who":"target","text":"Mâm lễ chay dâng ngày vọng mà lẫn một miếng thịt khô dưới lá chuối. Đây là tội bất kính nơi Phật đường."},{"who":"plotter","text":"Ôi, đáng sợ quá. Lẫn món mặn lên bàn thờ thì thật là phạm. {Goi} hãy xem lại ai sắp mâm."},{"who":"target","text":"{maid} sắp mâm sáng nay, nàng thề chưa từng bỏ thịt vào. Dầu mỡ còn dính ở mép mâm."},{"who":"plotter","text":"Người đến sau thì {xung} cũng chỉ vừa tới lạy Phật. {Goi} đừng nhìn {xung} như thế."}]}},
{"id":"j7:j7-066","dlg":{"L":"target","R":"tool","watch":true,"lines":[{"who":"nar","text":"Cửa nách phía bắc khuất dưới bóng cây, chiếc then gỗ cũ vừa đổi, nơi chìa đúc lại lẫn vài hạt ngọc vụn dưới đá."},{"who":"target","text":"Người ta nói ta từng đi cửa nách này, nên nghi ta mua chìa lẻn ra ngoài giờ. Sự thật thế nào, ngươi biết?"},{"who":"tool","text":"Nô tài bắt gặp cung nữ của {plotter} mang chìa ấy, trả bằng ngọc vụn. Nô tài nói thật."},{"who":"target","text":"Chìa đúc lại, ngọc vụn dùng làm tiền. Ngươi thấy tận mắt chứ?"},{"who":"tool","text":"Tận mắt, nhưng nô tài chỉ là kẻ hèn, xin {goi} cẩn thận cho nô tài."}]}},
{"id":"j7:j7-067","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Phòng bệnh trong cung vắng người, chỉ có tiếng ho khan nghe rất giả trên chiếc giường đã trải gối cao, trên bàn một tờ toa thuốc."},{"who":"plotter","text":"Khụ khụ... {Xung} nhiễm gió nên xin nghỉ buổi lễ. {Goi} đến thăm, lòng {xung} cảm kích lắm."},{"who":"me","text":"Nhìn {goi} sắc mặt hồng hào thế kia, {xung} lại tưởng gió đã đổi chiều từ lâu rồi."},{"who":"plotter","text":"Toa thuốc ở đây thầy thuốc xem rồi, nói là hơi lạ. Có lẽ chữ viết quá nhanh nên khó đọc."},{"who":"me","text":"{maid} nói sáng nay thấy {goi} nhởn nhơ ăn bánh trong vườn. {Xung} vừa muốn cười, vừa muốn hỏi chữ sửa ngày trong toa ấy."}]}},
{"id":"j7:j7-068","dlg":{"L":"tool","R":"target","watch":true,"lines":[{"who":"nar","text":"Phòng sau của Nội vụ phủ nặng mùi sổ cũ, tờ giấy mượn bạc nhăn nhúm trong tay, nét lăn tay mờ và con số đã bị sửa."},{"who":"tool","text":"Cung nữ của {goi} mượn bạc cứu bệnh người nhà, giờ phải trả gấp ba. Giấy nợ còn đây, nét lăn tay mờ."},{"who":"target","text":"Nó vay để cứu mạng người, sao có thể đòi gấp ba? Con số trên giấy rõ ràng bị sửa."},{"who":"tool","text":"Nô tài làm theo lệnh, {goi} đừng làm khó. Có người muốn cung {goi} mang tiếng kẻ hầu mắc nợ."},{"who":"target","text":"Có người ngầm xúi ngươi, ta hiểu. Cô bé ấy khổ rồi, ta không muốn nó khổ thêm."}]}},
{"id":"j7:j7-069","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Phòng chuẩn bị yến rộn ràng tiếng vải lụa, trên giá chỉ còn một chiếc hài thêu bên phải, cánh bướm thêu dở dang vắng một nửa."},{"who":"maid","text":"{Goi}, chiếc hài thêu bên trái của {goi} biến mất ngay trước giờ yến. Chỉ còn chiếc bên phải lẻ loi trên giá."},{"who":"me","text":"Hài mất ngay trước giờ yến, đúng lúc ta không thể đi chân không. Ai đã ở trong phòng?"},{"who":"maid","text":"Chỉ có {plotter} và vài cung nữ. Ống tay áo {plotter} hơi phồng, trên giá còn vết bùn mới."},{"who":"me","text":"Cánh bướm thêu thiếu một nửa, ta tiếc cho từng mũi chỉ. Giờ yến gần kề, ta phải quyết sao đây?"}]}},
{"id":"j7:j7-070","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Ngự thiện phòng sớm tinh mơ, hơi nước bốc lên từ bát yến loãng, mùi tanh thoảng qua trước cả khi nô tài kịp mở nắp."},{"who":"tool","text":"Nô tài xin lỗi {goi} rối rít. Bát yến sáng nay loãng, mùi tanh, đúng loại yến rẻ. Yến thượng hạng của cung {goi} đã đổi đi đâu rồi."},{"who":"me","text":"Sợi yến ngắn lại vụn, ta uống một ngụm đã biết. Ngươi biết ai đổi, đúng không?"},{"who":"tool","text":"Người nhận đồ ở bếp là kẻ hầu của {plotter}. Nô tài chỉ dám nói thế."},{"who":"me","text":"Chừng ấy là đủ để ta suy nghĩ. Cám ơn ngươi đã dám nói."}]}},
{"id":"j7:j7-071","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Sáng lặng sau đêm khó ngủ, màn trướng còn mùi hương nồng khiến đầu óc nặng trĩu như đeo đá."},{"who":"maid","text":"{Goi}, thầy thuốc ngửi ra hạt thuốc lạ trộn trong túi thơm xông chăn gối. Nô tỳ sợ lắm, chính nô tỳ mang túi ấy đến hôm qua."},{"who":"me","text":"Ai đưa túi ấy cho ngươi?"},{"who":"maid","text":"Nô tỳ nói người đưa nói do cung {plotter} gửi tặng. Mùi hương gắt, hạt thuốc lẫn trong túi vẫn còn."},{"who":"me","text":"Một món quà thơm mà ẩn hạt lạ. Ta đang nghĩ nên hỏi lại người gửi hay lặng lẽ giữ hạt này."}]}},
{"id":"j7:j7-072","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Phòng lật thẻ bài tĩnh mịch, trên khay chỉ có chỗ trống như một ô răng rụng, hộp thẻ đã bị dịch sang một bên."},{"who":"tool","text":"{Goi}, thẻ bài ghi tên {goi} biến khỏi khay trước giờ Hoàng thượng chọn. Khay vẫn còn nguyên thẻ của {plotter}."},{"who":"me","text":"Một tấm thẻ biến mất thì cả một đêm của ta cũng mất. Ngươi ở đâu khi ấy?"},{"who":"tool","text":"Nô tài chỉ rời khay một khắc để bưng trà. Về đến nơi thì hộp thẻ đã lệch sang bên."},{"who":"me","text":"Một khắc thôi mà đủ để đổi cả vận ta. Ta sẽ tính cách nào đây?"}]}},
{"id":"j7:j7-073","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Thư phòng chung phảng phất mùi mực mới mài, cây bút lông cha tặng nằm giữa án, ngòi cắt gọn như chưa từng có ngòi nào."},{"who":"plotter","text":"Trời, cây bút quý của {goi} sao lại ra nông nỗi này? Ngòi cắt mất một nửa, mà buổi viết thơ dâng thì sắp đến."},{"who":"me","text":"Nửa ngòi còn lại nằm cạnh nghiên mực của {goi}, trùng hợp thật. Cây bút ấy là quà của cha {xung}."},{"who":"plotter","text":"Ai biết nó lăn đến đâu. {Goi} nhìn kỹ dưới bàn đi, lông lạ rơi cả ra đấy."},{"who":"me","text":"{Xung} nhìn thấy cả hai thứ, sợi lông lạ lẫn nửa ngòi. {Xung} chưa biết nên nói gì với {goi}."}]}},
{"id":"j7:j7-074","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Hành lang cung Tây còn ẩm hơi sương, tờ giấy dán trên tường nhem nhuốc nét chữ nghiêng như viết bằng tay không thuận."},{"who":"maid","text":"{Goi}, sáng nay trên tường có tờ giấy dán bêu riếu {goi}. Ai đi qua cũng đọc nhẩm, nô tỳ nghe mà xót."},{"who":"me","text":"Hồ còn ướt, vết hồ nhỏ giọt xuống nền... người dán chưa đi xa. Chữ viết nghiêng lệch như bằng tay trái."},{"who":"maid","text":"Nô tỳ muốn gỡ ngay mà sợ làm hỏng chứng cứ. {Goi} định sao?"},{"who":"me","text":"Lời nặc danh nặng như đá. Ta nên gỡ nó đi hay giữ nó lại làm chứng, còn đang nghĩ."}]}},
{"id":"j7:j7-075","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Phòng đọc sách trong cung hãy còn dở dang buổi soát, cuốn thoại bản mới tinh nằm trên nền, giấy vàng chưa nếp gấp."},{"who":"plotter","text":"{Goi} thật đáng thương, bị lục tay áo trước mặt mọi người. Cuốn thoại bản cấm ấy từ đâu mà ra nhỉ?"},{"who":"me","text":"{Xung} chưa từng thấy nó. Mới tinh, chưa một vết gấp, giấy vàng và nét in giống hệt bộ sách của {goi}."},{"who":"plotter","text":"Bộ sách ấy nhiều cung có, {goi} nói thế khác nào buộc {xung} vào chuyện này."},{"who":"me","text":"{Xung} chưa buộc ai cả. {Xung} chỉ muốn tìm ra người đã bỏ nó vào tay áo {xung}."}]}},
{"id":"j7:j7-076","dlg":{"L":"maid","R":"me","lines":[{"who":"nar","text":"Phòng ấn của cung im lìm, con dấu ngọc nhỏ nằm đỏ au dưới ánh nến, dấu in trên tờ thỉnh nguyện lệch đi nửa phân."},{"who":"maid","text":"{Goi}, tờ xin thêm than sưởi gửi lên Nội vụ phủ mang dấu ấn của {goi}, mà {goi} chưa hề ký. Nét khắc phụ cũng chưa rõ."},{"who":"me","text":"Con dấu ngọc chỉ để ở phòng ấn. Ai đã động đến nó, in lệch cả nửa phân?"},{"who":"maid","text":"Con dấu ấy để cạnh bàn kẻ hầu thân tín của {plotter}. Nô tỳ thấy chuyện này bất ổn."},{"who":"me","text":"Chuyện xin than thì nhỏ, nhưng dấu ấn của ta thì lớn. Ta phải xử cho khéo mới được."}]}},
{"id":"j7:j7-077","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Kho than của Nội vụ phủ lạnh và đen, sọt than lót rơm cao quá miệng, lớp than ngay dưới chỉ mỏng như tờ giấy."},{"who":"tool","text":"{Goi}, than sưởi phát về cung {goi} nhẹ hẳn một nửa, sổ vẫn ghi đủ số. Sọt lót rơm để che, nô tài là người coi kho nên không dám giấu."},{"who":"me","text":"Mùa đông tới gần, than nhẹ một nửa nghĩa là rét thêm một nửa. Hôm qua ai đã tới thăm kho?"},{"who":"tool","text":"{plotter} có ghé qua. Nô tài chỉ biết thế, xin {goi} giữ lời cho nô tài."},{"who":"me","text":"Ta sẽ giữ lời. Nhưng sọt than này nhẹ thế, lòng ta cũng lạnh theo."}]}},
{"id":"j7:j7-078","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Hộp cơm khẩu phần mở ra, hơi lạnh bốc lên từ cơm khô và đĩa rau nhạt, niêm bếp đóng sai ngày như một dấu tay vội."},{"who":"tool","text":"{Goi}, ba bữa liền chỉ có cơm khô và rau nhạt, món mặn đều bị cắt. Người cắt là nô tài, nhưng nô tài bị ép bởi lời dặn của {plotter}."},{"who":"me","text":"Ngươi nói thật với ta, ta cũng không giận ngươi. Hộp cơm nhẹ thế này, ta nhìn đã biết."},{"who":"tool","text":"Niêm bếp đóng sai ngày, nô tài không dám sửa, sợ liên lụy."},{"who":"me","text":"Nỗi sợ của ngươi ta hiểu. Còn việc cung này bị đói bụng, ta phải lo cho trọn."}]}},
{"id":"j7:j7-079","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Con đường hẹp giữa hai cung tối đen, chậu cảnh lăn nghiêng, tay áo ướt vẫn nhỏ nước còn bấc đèn thì ấm hơi người."},{"who":"tool","text":"{Goi} ngã vào chậu cảnh đêm qua, nô tài sợ chết khiếp. Nô tài thấy bóng người chạy khuất, vạt váy giống áo của {plotter}."},{"who":"me","text":"Đèn bị thổi tắt giữa đêm, bấc còn ấm, khói còn mới. Ta không ngã vì chân yếu, chỉ vì không thấy đường."},{"who":"tool","text":"Nô tài không dám khẳng định, chỉ thấy vạt váy thoáng qua. Xin {goi} tha tội nếu nô tài nhìn lầm."},{"who":"me","text":"Vạt váy thoáng qua đủ để ta nhớ. Giờ ta chỉ tính xem nên làm gì cho đúng."}]}},
{"id":"j7:j7-080","dlg":{"L":"plotter","R":"me","lines":[{"who":"nar","text":"Phòng đọc chung rộn tiếng cười như chim sẻ, một giọng ngâm cao vút đọc những câu thơ buồn viết trong đêm."},{"who":"plotter","text":"«Đêm nay lạnh hơn lòng người...» Ha ha, thơ của {goi} thật hay. Hay cho cả phòng nghe."},{"who":"me","text":"Sổ thơ đã quay về hộc, mép giấy quăn vì cầm vội, bìa còn dấu tay mực. {Goi} lấy nó khi nào?"},{"who":"plotter","text":"{Xung} chỉ đọc cho vui thôi. {Goi} giận làm gì, thơ hay mà."},{"who":"me","text":"Những câu ấy {xung} viết trong lúc buồn nhất. {Xung} không giận vì thơ, mà giận vì lòng người."}]}},
{"id":"j7:j7-081","dlg":{"L":"tool","R":"me","lines":[{"who":"nar","text":"Nhã thất sau điện lặng lẽ, bức bình phong giấy có một lỗ nhỏ rách mép, mảnh giấy vụn vương dưới chân tựa một nhành cỏ úa."},{"who":"tool","text":"{Goi}, nô tài bắt gặp vạt áo {plotter} thấp thoáng sau bình phong. Lỗ nhỏ này vừa đủ để nhòm."},{"who":"me","text":"Hôm qua ta nói với ma ma những lời riêng tư, kẻ nghe lỏm đã nghe hết. Mảnh giấy còn dưới đất kia là chứng."},{"who":"tool","text":"Nô tài chỉ thấy vạt áo, không thấy mặt. Xin {goi} tha cho nô tài."},{"who":"me","text":"Chỉ vạt áo thôi cũng đủ để ta ngẫm. Ta nghĩ tiếp xem phải làm gì."}]}},
{"id":"wc:wc-tang-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Linh đường nghi ngút khói hương, chuông tang chưa dứt; dưới khăn trắng của {A}, một vệt xanh ngọc cứ chớp lên mỗi lần nàng cúi lạy."},{"who":"A","text":"{Goi} đừng nhìn {xung} như vậy. Chiếc trâm ngọc bích này {xung} chỉ muốn đeo thêm một buổi, để tiễn người cho trọn."},{"who":"me","text":"Ánh ngọc ấy ai trong cung cũng nhận ra, mà ma ma coi tang đã liếc sang mấy bận. {Xung} lo cho {goi}."},{"who":"A","text":"{Xung} biết là trái lệ, nhưng tháo xuống lúc này, lòng {xung} lại như tiễn người thêm một lần nữa. Xong lễ, {xung} sẽ cất vào hộp riêng."},{"who":"me","text":"Chuông tang vẫn ngân, ngọc vẫn lấp lánh dưới khăn trắng. Ma ma kia đang chờ xem ai dám nhắc nàng trước."}]}},
{"id":"wc:wc-tang-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chính điện trắng xóa khăn tang, lệnh quỳ theo phẩm vừa truyền xuống khiến tiếng thì thầm lan như gió luồn dưới rèm."},{"who":"A","text":"{Goi}, xin {goi} nói giúp một câu. {Xung} hầu hạ Thái hậu lâu nhất trong cung, hàng quỳ đầu bên linh cữu phải là chỗ của {xung}."},{"who":"me","text":"Ma ma xếp chỗ đứng ngay đó, mặt bà lúng túng. {Goi} cũng nên nghĩ đến phẩm trật mà lệnh đã định."},{"who":"A","text":"Phẩm trật ư? Người thương {xung} bao năm, {xung} chỉ muốn là người đứng gần người nhất, dù chỉ một buổi tang này."},{"who":"me","text":"Hàng quỳ đầu chỉ có một chỗ mà hai lòng cùng muốn. Lời {xung} nói lúc này sẽ định ai đứng gần linh cữu hơn."}]}},
{"id":"wc:wc-tang-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Canh khuya bên linh cữu Thái tử, nến cháy lụi vào bóng tối; một cung nữ gục đầu bên quan tài, tay vẫn siết chiếc quạt ngà."},{"who":"A","text":"{Goi}, xin đừng trách {xung}. Đây là quạt ngự bút của Thái tử, nét chữ trên mặt quạt vẫn còn, {xung} không nỡ buông tay."},{"who":"me","text":"Ba đêm quỳ canh, người đã kiệt sức. Ma ma còn quát nàng đứng dậy quỳ tiếp, ta nghe mà xót."},{"who":"A","text":"Nô tỳ hầu điện hạ từ thuở ấy, quạt này là thứ cuối cùng điện hạ từng cầm. Quỳ thêm một canh nữa nô tỳ cũng chịu được."},{"who":"me","text":"Nghe ngươi nói, lòng ta mềm hẳn đi. Ngươi đang cần một chén trà, một lời, hay một người quỳ thay?"}]}},
{"id":"wc:wc-tang-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Sương sớm còn ướt hiên, dải lụa đỏ trước cung bên vẫn phấp phới giữa một dãy cung phủ trắng."},{"who":"M","text":"{Goi}, nguy rồi! Dải lụa đỏ treo hiên còn chưa gỡ, ma ma Nội vụ phủ đang đi dọc dãy cung, chẳng mấy chốc sẽ tới nơi."},{"who":"me","text":"Lụa ấy chính Nội vụ phủ cấp cho đợt lễ trước, ta nào ngờ lệnh cấm sắc đỏ ban xuống gấp thế."},{"who":"M","text":"{Xung} thấy cung bên của {A} cũng còn treo một dải đèn lồng đỏ. Chỉ sợ ma ma thấy hết một lượt."},{"who":"me","text":"Dải lụa đỏ đã sắp chạm tầm mắt ma ma. Chỉ còn vài bước hiên để tính cho kịp."}]}},
{"id":"wc:wc-away-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà tắt dần trên hiên, {A} ôm con ngồi bên khung thêu, mùi ngải thơm quyện với sợi chỉ vàng đang vắt trên đầu ngón tay."},{"who":"A","text":"{Goi} xem, {xung} thêu dở túi thơm bình an này, đường long phụng cũng sắp xong rồi. Quân báo vừa về, {xung} muốn gửi theo trạm."},{"who":"me","text":"Túi thơm ngải ấy chắc mang được hơi ấm nhà đến biên ải. Nàng nhớ người đi xa lắm phải không?"},{"who":"A","text":"{Xung} ngượng khi nói ra, nhưng trong lòng toàn là những lời chưa viết. {Goi} có chữ nào muốn gửi kèm không?"},{"who":"me","text":"Kim còn cắm dở, trạm thư sắp đi. Một dòng gửi kèm, hay một mũi chỉ giúp nàng, {xung} chưa nghĩ ra."}]}},
{"id":"wc:wc-away-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cung điện thưa vắng như chiếc lồng vừa mở cửa, chỉ có tiếng {A} chạy dọc hành lang, tay ôm bao đựng tên chưa thêu xong."},{"who":"A","text":"{Goi}, {goi} ơi! Hoàng thượng đã lên đường đi săn, mà bao đựng tên của {xung} còn dở một đường rồng ở mép. Chỉ vàng cũng sắp hết!"},{"who":"me","text":"Nàng được chọn theo hầu, vinh dự lớn đấy, sao lại cuống như chạy giặc thế này?"},{"who":"A","text":"Vinh dự thì có, nhưng nếu rồng chưa thêu xong mà đem ra, {xung} chỉ muốn độn thổ. Cả dãy cung {xung} nhờ hết cả rồi."},{"who":"me","text":"Bao đựng tên nằm trên tay nàng, rồng mới thêu được nửa thân. Đến lượt {xung} đưa tay hay quay đi."}]}},
{"id":"wc:wc-away-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Điện phụ bày mâm chay thanh đạm, khói hương lan đều theo gió ngoài hiên khi Hoàng thượng đã rời cung đi tế trời."},{"who":"A","text":"{Goi} đến vừa lúc. Thái hậu truyền cả hậu cung ăn chay, {xung} bày mâm đạm bạc, muốn mời mọi người cùng trai giới."},{"who":"me","text":"Trong điện phụ yên ắng thế này, tiếng chuông cũng nghe như xa tận trời. Nàng chuẩn bị chu đáo thật."},{"who":"A","text":"Hoàng thượng đi tế trời, hậu cung mà không thanh tịnh thì sao đành lòng. Nhưng cung nhỏ không đủ đồ chay, {xung} cũng đang lo."},{"who":"me","text":"Nàng mời bằng cả tấm lòng, {xung} nghe mà thấy mình mắc nợ một bữa cơm chay."}]}},
{"id":"wc:wc-away-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vườn sau đêm vắng chủ, rượu mơ thơm lên từ chum niêm chữ tiệm rượu ngoài cổng thành, ba chiếc chén đã rót đầy."},{"who":"A","text":"{Goi} đến rồi! Hoàng thượng đi xa, trong cung vắng vẻ, {xung} mở chút tiệc nhỏ cho vui. Rượu mơ của tiệm ngoài cổng thành đấy."},{"who":"me","text":"{A} gan thật, mời cả {goi} lẫn {B} giữa lúc vắng chủ. Nếu ma ma biết thì sao?"},{"who":"A","text":"Ngài vắng thì ai biết! Một chén thôi, nhấp môi cho ấm bụng, đâu có ai nỡ mách."},{"who":"me","text":"Chén rượu mơ đã rót, lá cây xào xạc như đang nghe lén. Nhấp một chén hay quay về, {xung} phải quyết ngay đây."}]}},
{"id":"wc:wc-tuyen-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang dài hun hút, bóng chiều đổ xuống từng ô cửa chạm; một tú nữ mới đứng giữa lối đi, ôm chặt tay nải vải thô như ôm chiếc phao."},{"who":"A","text":"{Goi} xin lỗi, {xung} lạc đường rồi. Cung nữ dẫn đường nói đợi ở đây mà mãi chẳng thấy bóng ai."},{"who":"me","text":"Môi nàng mím chặt như sắp khóc. Ở mép tay nải còn thêu tên nàng, chắc là nhà vừa tiễn nàng vào cung."},{"who":"A","text":"Dạ phải, tay nải này là thứ duy nhất {xung} mang theo từ nhà. Nơi này rộng quá, {xung} sợ đi sai một bước là thất lễ."},{"who":"me","text":"Tay nải thô ôm chặt trước ngực, tên nàng thêu ở mép. Một lời của {xung} lúc này, nàng sẽ nhớ rất lâu."}]}},
{"id":"wc:wc-tuyen-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nội vụ phủ vừa báo tin tú nữ mới sẽ về dãy cung cũ; giữa sân, ma ma bị chặn lại, tay cầm sổ chia phòng run run."},{"who":"A","text":"Ma ma, gian hướng nam ấm nhất dãy, {xung} đã ở từ trước, không thể chia ra cho ai khác! {Goi} nói giúp {xung} một câu đi."},{"who":"me","text":"Ma ma nhìn quanh tìm người đỡ lời, mà {A} thì giữ chặt không buông. Chia phòng lúc này khó cho cả hai bên."},{"who":"A","text":"{Xung} không đòi nhiều, chỉ cần một gian cho riêng mình. Mùa đông gió đông bắc thổi buốt, nhường là {xung} lạnh."},{"who":"me","text":"Gian phòng hướng nam, ma ma đang nhìn, nàng đang nhìn. Cả hai đều chờ {xung} nói trước."}]}},
{"id":"wc:wc-tuyen-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa phòng, bàn trà bánh bày la liệt, mấy cung cao phẩm xúm quanh; tiếng cười lan ra tận hành lang như chuông gió."},{"who":"A","text":"{Goi} lại đây! Tú nữ mới sắp vào cung, chúng ta đặt cuộc xem ai được thị tẩm đầu, thua thì bao một đĩa bánh."},{"who":"me","text":"Tin tuyển tú làm cả cung xôn xao thế này sao? Nàng cũng nhanh trí lắm, lấy bánh làm tiền cược."},{"who":"A","text":"Cuộc vui nhỏ thôi, ai nỡ coi là thật. {Goi} đặt đĩa nào, hay chỉ ngồi nghe cho vui?"},{"who":"me","text":"Đĩa bánh còn nóng trên bàn, ánh mắt các cung đều nhìn sang. Một câu đáp lúc này nhẹ như tơ mà dễ vướng."}]}},
{"id":"wc:wc-hoa-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi khói còn khét trong gió sau cơn giông, giữa sân {A} đứng lặng, áo xống ám đen, ôm duy nhất một chiếc hòm gấm."},{"who":"A","text":"{Goi}, mái cung {xung} bắt lửa đêm qua, cái gì cũng cháy, chỉ còn chiếc hòm đựng y phục này. Nắp hòm còn dấu ấn Nội vụ phủ."},{"who":"me","text":"Khói bay sang tận hiên nhà {xung}. Nhìn nàng chẳng còn gì ngoài chiếc hòm ấy, {xung} thấy chạnh lòng."},{"who":"A","text":"Cung nhân của {xung} đang chạy đi mượn chăn đệm. Đêm nay trời lại trở lạnh, {xung} chưa biết ngủ ở đâu."},{"who":"me","text":"Giữa sân khói ám, nàng chỉ cần đêm nay có mái che. Phần còn lại, {xung} sẽ tính sau."}]}},
{"id":"wc:wc-hoa-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân, một cung nữ bị trói bên chân đèn đồng vết cháy xém, mặt xanh như tàu lá; {A} quỳ sụp xuống bên nàng."},{"who":"A","text":"{Goi}, xin thương nàng! Nội vụ phủ tra ra ngọn đèn đổ, nhưng nàng thật không cố ý. Nô tỳ xin dập đầu."},{"who":"me","text":"Chân đèn móp lõm, vết cháy còn rõ. {A}, ngươi nắm tay nàng sao chặt thế?"},{"who":"A","text":"Nô tỳ và nàng cùng nhau vào cung, nàng nhát gan, nô tỳ biết rõ. Nếu nàng bị phạt nặng thì nô tỳ cũng chẳng yên."},{"who":"me","text":"Chân đèn đồng móp lõm nằm ngay giữa sân, người bị trói đang ngước nhìn. Tội và tình đều cần một lời phân xử."}]}},
{"id":"wc:wc-hoa-003","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Tiếng gõ cửa lách cách vọng từ cung bên, ma ma Nội vụ phủ đi dọc hiên, đếm từng thùng gỗ niêm dấu quan trên thành."},{"who":"M","text":"{Goi}, ma ma Nội vụ phủ đang kê số thùng nước trước hiên từng cung. Cung nào thiếu thì chờ nhận thêm."},{"who":"me","text":"Sau cơn giông, ai cũng sợ lửa. Thùng nước trước hiên cung ta, đủ chưa?"},{"who":"M","text":"{Xung} đã kiểm, thiếu một chiếc. Nhưng cung bên cạnh lại dư, đang đứng nhìn ma ma với vẻ lo lắng."},{"who":"me","text":"Ma ma đã tới cung bên, tiếng đếm thùng nghe rành rọt. Còn thiếu một chiếc, mà cung ta thì cần một lời giải thích."}]}},
{"id":"wc:wc-hoa-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, mấy cung nhỏ chụm đầu thì thầm, tiếng nói nhỏ như muỗi mà ánh mắt thì sáng rực vì thích chuyện."},{"who":"A","text":"{Goi} biết không, sét đánh cung kia là do họ thất đức, trời không dung. Ai nghe {xung} nói cũng đều gật đầu cả."},{"who":"me","text":"Lời đồn chạy khắp dãy cung sau cơn giông rồi. Nhưng cung kia vừa mất mái, nàng nói vậy không sợ người ta nghe sao?"},{"who":"A","text":"{Xung} chỉ thuật lại điều người ta bàn tán. Ai muốn tin cứ tin, {goi} thì nghĩ sao?"},{"who":"me","text":"Cả đám cung nhỏ vẫn gật đầu theo nàng, chỉ còn đợi xem {xung} gật hay lắc."}]}},
{"id":"wc:wc-tuyen-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân phơi nắng, một tú nữ quỳ thẳng lưng chịu phạt vì lạy sai thứ tự, ma ma dạy lễ đứng bên, thước còn nằm trong tay."},{"who":"A","text":"{Goi} ơi, {xung} lạy sai có một bước mà bị phạt quỳ cả buổi. Chân {xung} tê hết rồi, mà ma ma nào chịu tha."},{"who":"me","text":"{Xung} thấy {M} khẽ đặt xuống chiếc gối thêu hoa lan của cung {xung} cho nàng kê, mà ma ma dạy lễ vẫn đang nhìn."},{"who":"A","text":"Gối ấy êm lắm, nhưng {xung} sợ ma ma thấy thì còn bị phạt nặng hơn. Quy củ ba tháng, ai dám coi thường."},{"who":"me","text":"Chiếc gối hoa lan vẫn nằm trong tay {M}. Đặt xuống hay mang đi, chỉ cần một cái gật của {xung}."}]}},
{"id":"wc:wc-dis-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hạn hán nứt đất ngoài thành, trong cung gió nóng hầm hập, mà từ bếp riêng của {A} vẫn bay ra mùi thịt thơm đến tận hiên."},{"who":"A","text":"{Goi} cũng nghe tin hạn hán rồi chứ? Hoàng thượng giảm thiện, nhưng bếp nhà {xung} vẫn nấu bốn món. Cơ thể yếu, {xung} không ăn nổi cháo loãng."},{"who":"me","text":"Cung nữ các cung đi ngang đều liếc nhìn. Mùi thơm kia, trong buổi này nghe như tiếng chuông báo."},{"who":"A","text":"{Xung} biết người ta nói gì sau lưng. Nhưng ăn ít một bữa có cứu được dân nào đâu, {goi} nói xem?"},{"who":"me","text":"Mùi thơm bay ra từ bếp riêng, tiếng thở dài lan theo hành lang. Nàng chờ {xung} nói, mà ai cũng đang nghe."}]}},
{"id":"wc:wc-dis-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiên sau hắt hiu gió đêm, một cung nữ ngồi co ro, tay siết chặt phong thư nhàu, góc cuối còn in dấu tay lý trưởng."},{"who":"A","text":"{Goi}, thư quê vừa tới, nói nước lũ tràn đồng, nhà nô tỳ phải chạy nạn. Dấu tay lý trưởng ở cuối thư, nô tỳ nhận ra."},{"who":"me","text":"Ngươi ngồi đây từ lúc nào mà mắt đã sưng đỏ thế? Thư viết thế nào, nói ta nghe."},{"who":"A","text":"Cha mẹ nô tỳ mất cả mùa gặt, lương thực cũng hết. Nô tỳ chỉ muốn hỏi, có cách nào gửi về chút lương cho nhà không?"},{"who":"me","text":"Phong thư nhàu trên tay ngươi còn ẩm hơi sương. Giúp ngươi, hay chỉ ngồi nghe, ta chưa quyết."}]}},
{"id":"wc:wc-dis-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng trẻ khóc nấc vang lên trong gian phòng tối, ngự thiện phòng mới cắt phần ăn; trong tay ngươi còn nằm hộp hạt dẻ niêm dấu thái giám."},{"who":"A","text":"{Goi}, con {xung} khóc đòi bánh mà trong tay {xung} chẳng có gì. Cả cung đều bị cắt phần, {xung} chỉ biết ôm nó chặt hơn."},{"who":"me","text":"Đứa nhỏ gầy quá, tiếng khóc như thể xé ruột. {Xung} còn chút hạt dẻ để dành, nhưng cũng chẳng nhiều."},{"who":"A","text":"Hạt dẻ ấy là phần của {goi}, {xung} không dám xin. Chỉ là nhìn con đói, lòng {xung} như bị dao cứa."},{"who":"me","text":"Đứa trẻ thì không biết chuyện kho lúa. Nó chỉ biết đói, và hộp hạt dẻ này đang nằm trong tay {xung}."}]}},
{"id":"wc:wc-dis-004","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Giữa sảnh, tiếng đàn vừa gảy đã bị tiếng cãi át đi; {A} và {B} đứng đối mặt, các phi tần khác ngồi im phăng phắc."},{"who":"A","text":"Hoàng thượng đã giảm thiện, cả cung bàn chuyện bớt chi dùng, vậy cứ bắt đầu từ phần ăn của {goi} đi."},{"who":"B","text":"{Goi} nói hay thật. Phần ăn của {goi} ngày nào cũng đầy mâm, {xung} bớt trước làm gì?"},{"who":"A","text":"{Goi} đừng chối, ai chẳng thấy mâm của {goi} thơm đến đâu. Tiếng đàn kia còn chẳng thèm át được lời {goi} nói."},{"who":"B","text":"Đã vậy, hôm nay trước mặt các cung, hai ta cùng thưa cho rõ, xem ai phải bớt trước."}]}},
{"id":"wc:wc-dich-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gian phòng ngoài lạnh lẽo, mùi ngải cứu nồng đến cay mắt; một cung nữ ho khan trong bóng tối, tay giữ khăn thấm thuốc."},{"who":"A","text":"{Goi}, đừng lại gần quá. Ma ma bảo nô tỳ ho suốt đêm, phải tách ra gian ngoài, chờ thái y đến xem."},{"who":"me","text":"Ta thấy khăn thấm thuốc trên tay ngươi nồng mùi ngải cứu. Ngươi ho từ lúc nào?"},{"who":"A","text":"Từ hôm qua, ban đầu chỉ rát cổ, giờ ho không dứt. Nô tỳ sợ mình mang dịch cho cả cung, sợ lắm."},{"who":"me","text":"Khăn thấm thuốc nồng mùi ngải trên tay nàng, gian ngoài chỉ cách một cánh cửa. Cánh cửa ấy mở hay đóng, ta còn phải tính."}]}},
{"id":"wc:wc-dich-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hàng người xếp dài trước án Thái y viện, khói ngải cứu bay mờ mặt; thái y đứng cau mày nhìn nắm túi thơm còn lại."},{"who":"A","text":"Mỗi cung hai túi mới đủ, {goi} ạ. {Xung} đã nhận một túi ngải cứu ngoài cửa, còn xin thêm hai túi cho cung {xung}. Dây túi niêm dấu Thái y viện, {goi} thấy chưa?"},{"who":"me","text":"Thái y cau mày kia, thuốc không còn nhiều. Nếu nàng lấy thêm thì cung khác e thiếu."},{"who":"A","text":"Cung {xung} đông người, thiếu túi là lo. {Goi} đứng đây, chắc cũng đang nhận phần của mình?"},{"who":"me","text":"Hai túi thơm cuối cùng nằm trên án, thái y còn cau mày. Nàng đang đưa tay ra, mắt nhìn {xung}."}]}},
{"id":"wc:wc-dich-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa vườn thu vắng, người người lùi ra như nước rẽ; {A} ngã quỵ trên lối sỏi, trong tay ngươi bát thuốc vẫn còn bốc khói."},{"who":"A","text":"{Goi}... đừng ai lại gần... {Xung} chóng mặt quá... Thuốc sắc từ Thái y viện, {goi} cầm đó mà."},{"who":"me","text":"Sắc mặt nàng tái như giấy. Mọi người lùi cả, chỉ có chén thuốc nóng này còn lại bên {xung}."},{"who":"A","text":"Nếu là dịch thì {goi} đừng ở gần. {Xung} không muốn liên lụy ai, nhưng sợ lắm."},{"who":"me","text":"Nàng ngã giữa vườn, chén thuốc nóng trong tay {xung}, mọi người lùi xa. Chân {xung} sắp bước đi rồi, về phía nào đây?"}]}},
{"id":"wc:wc-dich-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Góc sân Thái y viện nắng chiều nhạt, một thái y trẻ phát thuốc thí cho hàng cung nữ dài dằng dặc, tay áo xắn cao."},{"who":"A","text":"{Goi} đến đúng lúc. Dịch lan, các cung nhỏ thiếu thuốc, Thái y viện cho thí thuốc. {Xung} một mình phát, tay không xuể."},{"who":"me","text":"Hàng người xếp dài thế này, {goi} làm từ sáng à? Trông mệt lắm."},{"who":"A","text":"Từ sáng đến giờ, nước chưa kịp uống. Thuốc thì còn, người thì đông, {xung} chỉ sợ phát chậm lại có người ngã."},{"who":"me","text":"Hàng người vẫn dài, thuốc còn đủ cho họ. Chỉ thiếu một đôi tay, hoặc một lời của {xung}."}]}},
{"id":"wc:wc-su-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng cười rộ lên giữa yến, sứ thần giơ cây đàn dây lạ, thân đàn khắc hoa văn mà chưa ai trong cung từng thấy."},{"who":"A","text":"{Goi} xem này, đàn dây ngoại quốc sao lại có nhiều dây thế? {Xung} hỏi sứ thần xem nó kêu thế nào, ông ta ra hiệu thổi nữa!"},{"who":"me","text":"Nàng nghiêng đầu nhìn đàn như trẻ con thấy chuông. Tờ dâng lễ nói gì về nó?"},{"who":"A","text":"Tờ dâng lễ ghi tên lạ hoắc, {xung} đọc chẳng hiểu. Mà cả yến cười vì sứ thần thổi vào dây, kêu như mèo kêu."},{"who":"me","text":"Cười một trận rồi thì cây đàn vẫn đó. Có ai dám thử một tiếng cho yên cả yến không?"}]}},
{"id":"wc:wc-su-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Rèm châu rủ thấp trước hàng phi tần, hạt ngọc va khẽ leng keng mỗi khi {A} nghiêng người tìm khe nhòm ra điện."},{"who":"A","text":"{Goi} ơi, sứ thần mặc áo gì mà đỏ rực thế? {Xung} nhòm không thấy, rèm cứ che mãi."},{"who":"me","text":"Nàng nhích nữa là rèm đung đưa mất. Nhìn kìa, thái giám đã liếc sang rồi."},{"who":"A","text":"Chỉ nhòm một chút thôi, ai bắt lỗi được? Hậu phi chỉ được dự yến sau rèm, buồn chết đi được."},{"who":"me","text":"Rèm châu vẫn đung đưa, thái giám vẫn nhìn sang. Một cái khẽ kéo tay áo hay một cái thưa lên, đều làm được."}]}},
{"id":"wc:wc-su-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lụa lạ của sứ thần óng lên dưới ánh nến, {A} vuốt nửa tấm trước mặt cả điện, trong khi trong tay áo ngươi chỉ có chiếc khăn lụa nhỏ."},{"who":"A","text":"{Goi} xem lụa này, Hoàng thượng ban nửa tấm cho {xung}. Còn {goi} được chiếc khăn lụa nhỏ, thêu hoa văn nước sứ thần, cũng đẹp lắm."},{"who":"me","text":"Lụa đẹp, nàng chúc mừng cũng phải. Khăn nhỏ này mép thêu hoa lạ, {xung} nhìn cũng thích."},{"who":"A","text":"Ai bảo ban thưởng theo ý Hoàng thượng chứ. {Goi} đừng buồn, lụa lớn lụa nhỏ cũng là ân điển cả."},{"who":"me","text":"Lụa óng lên dưới ánh nến, khăn nhỏ nằm trong tay {xung}. {Xung} muốn đáp nàng bằng nụ cười hay bằng một câu nhẹ mà sắc?"}]}},
{"id":"wc:wc-su-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nắng sớm hắt vào nhạc phòng, nhạc sư của cung đứng trước cây đàn lạ của sứ đoàn, tờ dâng lễ nằm cạnh, tóc còn dính sương."},{"who":"A","text":"{Goi}, lão phu ngồi mày mò từ sáng sớm mà chưa gảy ra được một điệu. Tờ dâng lễ ghi tên nhạc cụ, nhưng không dạy cách chơi."},{"who":"me","text":"Đàn lạ của sứ đoàn, ta cũng chưa thấy ai chơi. Ông đã thử dây nào chưa?"},{"who":"A","text":"Thử rồi, dây kêu nhưng điệu không thành. {Goi} đã từng thấy ai chơi loại đàn này chưa?"},{"who":"me","text":"Tờ dâng lễ ghi tên mà không ghi cách gảy. Ông đang chờ một người cùng bắt đầu, dù chỉ một dây."}]}},
{"id":"wc:wc-tho-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương bột nếp thơm cả hiên, trên mâm son bóng loáng một quả đào bánh tròn vo, chóp còn chấm một điểm son đỏ."},{"who":"A","text":"{Goi} nếm thử miếng bột nặn này đi. Bánh đào thọ phải chọn quả thật tròn, chấm son cho khéo, dâng lên mới có phúc."},{"who":"me","text":"Quả đào nặn bằng bột nếp mà tròn trịa thế này, nàng khéo tay thật. Ngày đại thọ gần kề, các cung ai cũng bận."},{"who":"A","text":"{Xung} thức hai đêm để nặn, mong Thái hậu nhìn thấy sẽ vui. Còn {goi}, chắc cũng đã nghĩ lễ vật rồi chứ?"},{"who":"me","text":"Quả đào bột nếp chấm son trông thật tròn trịa. {Xung} chưa biết nên đưa tay nặn cùng, hay tự dâng lễ riêng."}]}},
{"id":"wc:wc-tho-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi khét lan khắp dãy cung, giữa sân bếp {A} ngồi bệt xuống đất, trước mặt mẻ bánh thọ đen thui nằm trên khay."},{"who":"A","text":"Xong rồi, {goi} ơi... bánh dâng thọ của {xung} cháy mất rồi. Đại thọ Thái hậu sắp đến mà cung nhỏ thế này biết lấy gì dâng?"},{"who":"me","text":"Nhìn khay bánh cháy xém, {xung} suýt bật cười, mà thấy mắt nàng đỏ hoe nên phải nín."},{"who":"A","text":"{Goi} đừng cười {xung}. Lò cung {xung} cũ, lửa lại không đều, nướng đến lần thứ ba vẫn hỏng."},{"who":"me","text":"Mùi khét nhạt dần, nàng vẫn ngồi bệt đó. Nàng cần một cái lò, hay chỉ cần một người ngồi xuống bên cạnh?"}]}},
{"id":"wc:wc-tho-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Trước mặt cả triều, hai chiếc bình thọ men lam đặt cạnh nhau, giống nhau như đúc, men xanh nổi tiếng của lò gốm Nội vụ phủ."},{"who":"A","text":"Đại thọ Hoàng thượng, ai cũng muốn dâng lễ lớn. Nhưng bình men lam này {xung} đã chuẩn bị từ đầu năm, sao {goi} lại có một chiếc y hệt?"},{"who":"B","text":"{Goi} cho là chỉ riêng {goi} biết lò Nội vụ phủ chăng? Lễ thọ ai dâng trước, ai dâng sau, trời tự biết."},{"who":"A","text":"Giống nhau thế này, trước mặt cả triều, người ta sẽ cười cả hai ta. {Goi} nhường một chút thì có sao?"},{"who":"B","text":"Nhường để thiên hạ nói {xung} sợ {goi} à? Cứ để cả triều chọn xem bình nào đẹp hơn."}]}},
{"id":"wc:wc-tho-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân trước điện nắng đẹp, một đứa nhỏ đứng thẳng lưng tập bài chúc thọ, bàn tay bé xíu cứ nắm chặt gấu áo."},{"who":"A","text":"{Goi} đến đúng lúc. Con {xung} thuộc bài chúc thọ lắm rồi, nhưng cứ nhìn {goi} là lại quên lời, nghe cứ như sợ."},{"who":"me","text":"Đứa trẻ này ngoan quá. Nó quên lời vì sợ hay vì mong đợi, nàng đã hỏi nó chưa?"},{"who":"A","text":"{Xung} lo lắm. Đại thọ Thái hậu mà đọc sai một câu, cả cung nhìn con {xung} thì mất mặt biết bao."},{"who":"me","text":"Đứa nhỏ đang ngước mắt chờ, mẹ nó nắm chặt tay áo. Bài chúc ngắn hay dài, giờ đây đều nằm ở {xung}."}]}},
{"id":"wc:wc-sao-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên giếng trời, sương đêm lạnh lẽo, chén sứ trắng đặt trên bàn thờ nhỏ, nước hoa quế thơm lên dưới ánh đèn."},{"who":"A","text":"Khâm Thiên giám tâu có điềm lạ, Hoàng thượng ăn chay, cả cung đều cầu đảo. {Xung} dâng chén nước hoa quế này để cầu bình an."},{"who":"me","text":"Chén sứ trắng có dấu đỏ của Thái miếu, nàng giữ gìn cẩn thận. Ai đi ngang cũng cúi đầu cả."},{"who":"A","text":"{Xung} chỉ biết lấy hương quế làm lễ. {Goi} cũng sợ điềm lạ trên trời phải không?"},{"who":"me","text":"Chén của nàng đã dâng lên. Còn {xung}, lòng thành sẽ gửi theo cách nào?"}]}},
{"id":"wc:wc-sao-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang vang tiếng khóc thút thít, cung nữ túm tụm thành từng nhóm, ở giữa, một cung nữ vừa chạy vừa kể, tay múa loạn."},{"who":"A","text":"{Goi}, nô tỳ nghe nói sao lạ đêm qua báo điềm chẳng lành cho cung của {goi}! Nô tỳ sợ lắm, phải nói cho mọi người biết!"},{"who":"me","text":"Ngươi chạy khắp dãy kể thế, mấy cung nữ kia khóc cả lên rồi. Ngươi nghe ai nói?"},{"who":"A","text":"Nô tỳ nghe lỏm bên Khâm Thiên giám, hình như sao đổi hướng, chẳng lành lắm. Nô tỳ cũng muốn báo để {goi} lo liệu."},{"who":"me","text":"Tiếng khóc lan từ hiên này sang hiên khác. Một lời quát hay một lời dỗ, cả cung đều sẽ nhớ."}]}},
{"id":"wc:wc-sao-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc điện phụ, một ống quẻ tre lắc lên lách cách, chữ khắc của ngôi chùa ngoài thành đã sờn, chung quanh toàn người ngồi nín thở."},{"who":"A","text":"{Goi} tới rồi à? {Xung} biết xem điềm, giải quẻ cho từng cung. Quẻ này chỉ tính giá một lượng bạc, thật rẻ so với chuyện sống còn."},{"who":"me","text":"Điềm lạ trên trời làm cung nào cũng nóng ruột. Quẻ của nàng, rốt cuộc là lành hay dữ?"},{"who":"A","text":"Nói trước thì mất linh. {Goi} trả công rồi {xung} giải, đảm bảo không ai biết."},{"who":"me","text":"Ống quẻ lắc lên nghe như mưa rơi. Quẻ của nàng giá một lượng bạc, mà bạc thì {xung} có thừa."}]}},
{"id":"wc:wc-sao-004","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió đêm lạnh thổi tắt vài ngọn nến, cả cung quỳ dưới trời tụng kinh, giữa hàng người bỗng có một bóng đổ gục xuống."},{"who":"A","text":"{Goi}... {Xung} chóng mặt quá, không đứng được nữa... Quỳ từ chiều đến giờ, đầu gối như đóng băng."},{"who":"me","text":"Người nàng run bần bật, mọi người vẫn chăm chú tụng kinh, chẳng ai nhìn sang."},{"who":"A","text":"Đừng dừng lại vì {xung}, lỡ lòng thành bị gián đoạn thì chẳng hay. {Xung} chỉ cần chút hơi ấm thôi."},{"who":"me","text":"Gió thổi lạnh thêm, kinh vẫn tụng, người vẫn run. Một tấm áo, một cái đỡ tay, hay một tiếng gọi thái y."}]}},
{"id":"wc:wc-xa-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cổng thành, gió thổi tung tà áo cũ, một cung nữ ôm tay nải sờn đứng quay lại, tên nàng thêu ở góc còn rõ."},{"who":"A","text":"{Goi}, chiếu đại xá ban xuống, nô tỳ được xuất cung rồi. Nô tỳ vào cung từ thuở nhỏ, hôm nay đi mà chân cứ nặng."},{"who":"me","text":"Cả đời {goi} ở trong cung, giờ ra ngoài kia, {goi} định về đâu?"},{"who":"A","text":"Nô tỳ cũng chưa rõ. Tay nải này là thứ nô tỳ giữ lâu nhất, tên nô tỳ thêu ở góc, để khỏi lẫn với người khác."},{"who":"me","text":"Cổng thành đã mở sau lưng nàng. Lời cuối của {xung}, nàng sẽ mang theo suốt quãng đường về."}]}},
{"id":"wc:wc-xa-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung vừa mở, một bóng gầy đứng lại trước cửa cung ngươi, khăn thêu chim hạc dở dang trong tay, đường chỉ chưa kịp khâu nốt."},{"who":"A","text":"{Goi}... {Xung} vừa được tha, đi ngang cung {goi}, tự nhiên chân không muốn bước. {Goi} đừng cười {xung}."},{"who":"me","text":"Nàng gầy đi nhiều quá. Khăn thêu chim hạc này vẫn chưa xong sao?"},{"who":"A","text":"Ngày bị cấm túc, {xung} chỉ có khăn này làm bạn. Thêu dở một góc, chẳng có tâm trí nào để thêu nốt."},{"who":"me","text":"Nàng đứng trước cửa cung {xung} như người gõ cửa mà không dám. Mở ra thì chỉ một câu thôi."}]}},
{"id":"wc:wc-xa-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Giữa sân vắng, nắng chiếu xuống hai bóng người đối diện; một người vừa được tha khỏi oan khuất, người kia từng đứng ra tố cáo nàng."},{"who":"A","text":"{Goi} cũng ở đây? Chiếu đại xá vừa ban, {xung} mới thấy ánh mặt trời, mà lại gặp đúng người đã tố cáo {xung}."},{"who":"B","text":"{Goi} đừng nhìn {xung} bằng ánh mắt ấy. Chuyện cũ, {xung} cũng chỉ nói điều mình thấy."},{"who":"A","text":"Điều {goi} thấy làm {xung} mất bao nhiêu ngày trong cấm cung, {goi} có biết không?"},{"who":"B","text":"Biết hay không thì giờ đây, giữa sân này, cả hai ta đều đang bị người ta nhìn."}]}},
{"id":"wc:wc-day-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa yến đầy tháng, tiếng cười rộn rã quanh chiếc nôi gấm, trên tay áo {A} thấp thoáng ánh bạc của khóa trường mệnh khắc tên đứa trẻ."},{"who":"A","text":"{Goi} lại gần nhìn con {xung} đi. Khóa bạc trường mệnh này thợ bạc phố Đông làm, khắc tên nó rõ ràng, ai nhìn cũng thấy."},{"who":"me","text":"Đứa bé ngủ ngoan thật. Quanh nôi ai cũng liếc xem người khác dâng quà gì, mà nàng thì chỉ nhìn con."},{"who":"A","text":"{Xung} chẳng cần quà lớn, chỉ mong mọi người có lòng. Nhưng {goi} biết đấy, ai mà chẳng so bì."},{"who":"me","text":"Đầy tháng thì có lễ, mà món quà của {xung} cũng đang bị người nhìn. Phải chọn món nào nói đúng lòng mình."}]}},
{"id":"wc:wc-day-002","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Mâm quà đầy án, ánh nến nhảy trên giấy gói lụa; {A} vừa mở hộp ra thì sắc mặt đổi, còn {B} ngồi cạnh khẽ mím môi cười."},{"who":"A","text":"Quà của {B} nhẹ thế này sao? {Xung} còn tưởng một món hậu hĩnh lắm. Yến đầy tháng công chúa mà dâng thế này, thật chẳng ra gì."},{"who":"B","text":"{Goi} nói nhẹ nhàng thôi. Lễ nhẹ ý nặng, {goi} chưa nghe câu ấy bao giờ sao?"},{"who":"A","text":"Ý nặng thì chẳng thấy, chỉ thấy hộp nhẹ. Cả điện đang nhìn kia, {goi} định nói sao?"},{"who":"B","text":"{Xung} không cần nói. Ai thấy được thì tự biết, còn lại chỉ là lời đàm tiếu."}]}},
{"id":"wc:wc-day-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc yến vắng người, một bóng đứng lặng tay nắm chặt chiếc yếm thêu hổ con đã cũ, mắt dán vào chiếc nôi gấm giữa điện."},{"who":"A","text":"{Goi}, {xung} không dám đến gần. Từ khi mất đứa con, {xung} chưa dám ôm trẻ nhỏ, nhìn chiếc nôi kia mà chân như đứng chôn."},{"who":"me","text":"Yếm thêu hổ con này, ai cũng từng thấy nàng thêu khi còn mang thai. Nàng vẫn giữ nó bên mình sao?"},{"who":"A","text":"Đứa con mất rồi, nhưng bàn tay {xung} thêu từng mũi vẫn còn nhớ. {Xung} chẳng nỡ cất đi."},{"who":"me","text":"Yếm hổ nhỏ vẫn nắm chặt trong tay nàng, chiếc nôi vẫn ở đó. Một cái nắm tay, hay một bước chân đưa nàng ra khỏi góc này?"}]}},
{"id":"wc:wc-xa-004","dlg":{"L":"M","R":"me","lines":[{"who":"nar","text":"Lãnh cung mở cửa dọn dẹp, bụi bay mù mịt trong nắng; ma ma cũ nơi ấy vừa đi ngang cổng, ôm bọc áo xếp gọn, miệng cười mà mắt thở dài."},{"who":"M","text":"{Goi}, ma ma cũ ở lãnh cung vừa nhờ nô tỳ nhắn lời tới {A}. Bà bảo quần áo nàng bỏ lại vẫn còn đó, chẳng ai dám đụng."},{"who":"me","text":"Quần áo bỏ lại ở lãnh cung, tới giờ mới nhớ ra sao? Ma ma nói thế, chắc có cả trách lẫn thương."},{"who":"M","text":"Dạ, bà nửa trách nửa than. Bà nói nàng đi vội quá, bỏ cả áo mùa đông, còn lãnh cung thì lạnh thật."},{"who":"me","text":"Bọc áo cũ nằm đó, chẳng ai dám đụng. Nhận lời nhắn là nhận cả chuyện cũ của {A} đấy."}]}},
{"id":"wc:wc-lap-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trống chiêng rền suốt buổi sáng, giữa điện cao {A} ngự trên ghế, ngón tay vân vê thanh ngọc như ý, ấn Nội vụ phủ khắc ở chuôi sáng lên."},{"who":"A","text":"{Goi} đến rồi à? Chiếu lập Thái tử vừa ban, hậu cung đều tới bái. Ngọc như ý này Hoàng thượng ngự ban, ai nhìn cũng phải cúi."},{"who":"me","text":"Tiếng trống còn vang trong tai mà lòng người đã chia ra từng phe. {Xung} thấy ai nấy cúi rạp, mắt thì đếm xem ai bái trước."},{"who":"A","text":"{Goi} tinh ý lắm. Bái trước hay bái sau, hôm nay đều thành chuyện. Lễ nặng nhẹ thế nào, chẳng ai quên đâu."},{"who":"me","text":"Lễ bái hôm nay không chỉ là cúi đầu, mà là chọn đứng ở đâu trong hàng. {Xung} đã đến lượt."}]}},
{"id":"wc:wc-lap-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhạc lễ sắc lập còn vương trong gió, mà trong gian phòng nhỏ, {A} ngồi lặng, vuốt từng đường rồng trên chiếc áo gấm của con."},{"who":"A","text":"Cả cung bàn tán đến nao lòng, {goi} biết không? Con {xung} là con trai, mà ngôi Thái tử đã không đến lượt nó."},{"who":"me","text":"Chiếc áo gấm thêu rồng con này, nàng bảo thợ Dệt cục làm cho con. Đường thêu còn mới nguyên."},{"who":"A","text":"Thợ thêu còn nhớ ngày {xung} dặn từng mũi chỉ. Nay nhìn áo mà nghe nhạc ngoài kia, {xung} chỉ thấy lòng trống."},{"who":"me","text":"Áo gấm rồng con còn nằm trên đầu gối nàng, nhạc ngoài kia chưa dứt. Mở lời hay giữ im, đều là một cách thương nàng."}]}},
{"id":"wc:wc-lap-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Trước điện sắc lập vừa lễ xong, hai bản tấu riêng lần lượt đặt lên án, chưởng sự đứng giữa nhìn quanh như tìm chỗ nương."},{"who":"A","text":"Dịp vui sắc lập Thái tử, {xung} xin ân điển cho cung nhỏ, đâu phải chuyện quá đáng. {Goi} dâng tấu sau {xung}, cớ gì phải gấp?"},{"who":"B","text":"{Goi} nói nghe thật nhẹ nhàng. Bản tấu của {xung} dâng từ sớm, chưởng sự chưa kịp đọc thì {goi} đã chen vào."},{"who":"A","text":"Chen hay không, chưởng sự tự biết. Hôm nay cả triều nhộn nhịp, chẳng ai rảnh phân đúng sai."},{"who":"B","text":"Đã vậy, để người trong điện phân xử. Chưởng sự kia đang tìm một người đỡ lời kìa."}]}},
{"id":"wc:wc-hau-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phượng nghi cung sực nức hương trầm, trên án son bày bộ trâm phượng ngự ban, ấn Nội vụ phủ trên hộp sáng lên giữa mặt người đang chờ bái."},{"who":"A","text":"{Goi} tới rồi. Từ ngày sắc phong, các cung đều đến yết kiến. Bộ trâm phượng này Hoàng thượng ban, cả cung thấy lúc trao."},{"who":"me","text":"Nghe tiếng lễ vừa dứt mà đã thấy gương mặt ai cũng cố tươi. Nàng ngồi cao thế này, mắt nhìn từng người một."},{"who":"A","text":"Nhìn kỹ để biết ai thật lòng, ai chỉ làm cho có. {Goi} định bái bằng lễ gì?"},{"who":"me","text":"Tân Hoàng hậu ngồi trên cao, mắt nhìn xuống từng người. Đến lượt {xung}, lễ phải nói được điều gì."}]}},
{"id":"wc:wc-hau-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau tin Hoàng hậu cũ bị phế, hiên nào cũng lặng như tờ; {A} nắm chặt chuỗi ngọc khắc chữ riêng của hậu cũ, đứng đợi dưới mái."},{"who":"A","text":"{Goi}, cả cung đều nhìn xem {goi} đứng về phía nào. {Xung} thân với hậu cũ, giờ cầm chuỗi ngọc bà tặng đi tìm {B} thương lượng."},{"who":"me","text":"Chuỗi ngọc có chữ riêng của hậu cũ, nhiều người từng thấy. Mang nó theo, nàng không sợ người ta đoán sao?"},{"who":"A","text":"Sợ, nhưng bỏ nó đi thì {xung} thành kẻ vong ơn. {Goi} giúp {xung} một lời, hay chỉ đứng nhìn?"},{"who":"me","text":"Chuỗi ngọc ấy là thứ của hậu cũ, mà cả hiên đang nín thở đợi xem {xung} đứng bên nào."}]}},
{"id":"wc:wc-hau-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Điện đón hậu mới chật kín người, tiếng áo lụa sột soạt như mưa nhỏ, giữa hàng phi tần hai bóng người đang đẩy nhau từng bước."},{"who":"A","text":"{Goi} lùi ra một chút đi, chỗ gần tân hậu phải là của {xung}. Váy {goi} cứ vướng vào chân {xung} thế này."},{"who":"B","text":"{Goi} nói hay quá. Chân ai vướng chân ai, cả điện đang nhìn kìa. {Xung} đứng đây trước, sao phải lùi?"},{"who":"A","text":"Đứng trước hay sau, tân hậu tự biết. Đừng đẩy nữa, váy {xung} rách mất!"},{"who":"B","text":"Rách thì để {goi} đền, đừng đổ cho {xung}. Này, mọi người đang nín cười kìa."}]}},
{"id":"wc:wc-thb-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đức Thọ cung đèn leo lét, mùi thuốc bốc thơm đắng; {A} bưng thang thuốc sắc nóng hổi, bàn tay run nhè nhẹ trước giường bệnh."},{"who":"A","text":"{Goi} đến vừa lúc, thang thuốc này sắc xong chưa nguội, có đơn thái y kèm theo. {Xung} muốn tự tay hầu Thái hậu."},{"who":"me","text":"Tay nàng run, mà bát thuốc nóng thế. Thái hậu nằm liệt giường, ai cũng nhìn xem ai thay phiên hầu."},{"who":"A","text":"Cung nhân đều đang nhìn xem {goi} có đứng ra không. {Xung} chẳng ép, chỉ muốn nói thật lòng."},{"who":"me","text":"Đêm dài, thuốc nóng, bàn tay nàng run. Nếu {xung} bước ra thì phiên hầu này sẽ khác."}]}},
{"id":"wc:wc-thb-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang Đức Thọ cung im lặng như nước, mấy cung nữ đứng thẳng không dám thở mạnh, trong khi một giọng nói đều đều vang lên giữa họ."},{"who":"A","text":"{Xung} thức mấy đêm hầu Thái hậu, mắt đỏ hoe mà chưa dám ngả lưng. {Goi} nghe thấy chưa, phải thế mới gọi là tận tâm."},{"who":"me","text":"Nghe nàng nói, cung nữ cũng im thin thít. Nàng liếc xem {xung} đáp thế nào à?"},{"who":"A","text":"Ai cũng muốn được ghi công hầu hạ, {xung} không giấu. {Goi} cũng thức mà, phải không?"},{"who":"me","text":"Cung nữ vẫn im thin thít, ánh mắt nàng vẫn dò. Khen một câu cho nàng vừa lòng, hay đáp sao cho thật?"}]}},
{"id":"wc:wc-thb-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bậc thềm Đức Thọ cung phủ sương, một cung nữ trẻ gục đầu bên bát canh sâm đã nguội, tên người nhận ghi rõ trên phiếu của Thái y viện."},{"who":"A","text":"{Goi}... nô tỳ xin lỗi, nô tỳ ngủ gật. Bát canh sâm này thái y đưa cho nô tỳ, ghi rõ tên nô tỳ, mà nô tỳ chưa kịp dùng."},{"who":"me","text":"Ngươi chẳng ngủ đã mấy đêm rồi phải không? Canh nguội cả, mà ngươi vẫn ôm trong tay."},{"who":"A","text":"Đức Thọ cung thiếu người, nô tỳ không dám bỏ. Nhưng mắt nô tỳ cứ sụp xuống, tay chân không còn nghe lời."},{"who":"me","text":"Canh sâm đã nguội mà nàng chưa kịp uống. Một lời của ta có thể là phép nghỉ, cũng có thể là một lệnh nặng hơn."}]}},
{"id":"wc:wc-thi-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau bình phong họa núi sông, {A} nhón chân ngó ra cổng cung, nơi đoàn sĩ tử áo xanh đi qua như dòng nước."},{"who":"A","text":"{Goi} đến đây xem! Khoa thi Đình khai mạc, {xung} đoán người áo xanh kia sẽ đỗ trạng nguyên, tướng mạo thế kia mà."},{"who":"me","text":"Nàng lẩm bẩm đoán tướng từ nãy, ai thấy cũng bật cười. Trạng nguyên mà đoán qua gương mặt sao?"},{"who":"A","text":"Sao không? {Xung} đặt cược một đĩa bánh, ai đoán trúng thì ăn. {Goi} dám theo không?"},{"who":"me","text":"Tiếng cười sau bình phong nghe giòn tan. {Xung} sẽ theo trò vui này, hay khép nó lại cho nàng?"}]}},
{"id":"wc:wc-thi-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bảng vàng vừa dán, tin vọng cả kinh thành; trong phòng nhỏ, {A} mở thư nhà, bài văn sách chép tay rơi ra, chữ ký còn đậm mực."},{"who":"A","text":"{Goi}, thư nhà gửi vào có kèm bài văn sách này, chữ ký và dấu của cha {xung}. Cha muốn nhờ người đưa tới Hàn lâm viện."},{"who":"me","text":"{Xung} từng xem bài này, nét chữ cha nàng chắc tay. Nhưng việc đưa văn vào Hàn lâm viện, nàng định nhờ ai?"},{"who":"A","text":"{Xung} chỉ biết nhìn {goi}. Hậu cung xa Hàn lâm viện, nhưng lòng {xung} thì không yên."},{"who":"me","text":"Bài văn sách nằm trên tay nàng nặng hơn giấy mực. Giúp hay không giúp, đều để lại dấu."}]}},
{"id":"wc:wc-thi-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mấy cung cao vị ngồi quanh bàn trà sau khoa thi Đình, tiếng cười nhỏ mà ý lại sắc như lưỡi cắt."},{"who":"A","text":"{Goi}, cháu {xung} đỗ bảng nhãn đấy, tin vừa về đến cung, mừng chưa nói hết. Cả họ đang chuẩn bị tiệc mừng."},{"who":"me","text":"Bảng nhãn là vinh dự lớn của nhà nàng. {Xung} thấy mừng lây."},{"who":"A","text":"{B} cười mỉm kia, nhà {B} cũng có người ngồi Hàn lâm. Cả hai đều khoe, giờ chỉ còn nhà {goi}."},{"who":"me","text":"Hai ánh mắt đang chờ, trà trên bàn đã nguội. Lời đáp của {xung} sẽ định nhà {xung} đứng ở đâu trong tiệc này."}]}},
{"id":"wc:wc-vuong-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cung môn mở rộng đón sứ phiên vương, hộp lễ bày giữa sảnh, ngọc bội lạ mắt hiện lên giữa tơ gấm, ấn phiên vương rõ trên mặt."},{"who":"A","text":"{Goi} xem này, phiên vương gửi quà vào hậu cung, có chiếc ngọc bội này, quan lễ tân đã ghi sổ. Nhận hay từ, {xung} chưa quyết."},{"who":"me","text":"Ngọc bội mang ấn phiên vương, mọi người xúm lại xem mà chẳng ai dám động vào. Quà này nặng ý hơn nặng giá."},{"who":"A","text":"Nhận thì sợ mang tiếng kết giao, từ thì sợ mất lòng phiên vương. {Goi} nói giúp {xung} một ý."},{"who":"me","text":"Ngọc bội này gửi vào hậu cung chẳng phải chuyện nhỏ. Nhận hay từ, hỏi hay báo, mỗi đường một hậu quả."}]}},
{"id":"wc:wc-vuong-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng sáo vang đến chiều muộn trong gia yến, quạt lụa che nửa gương mặt {A}, đôi mắt lại cứ trượt về phía phiên vương."},{"who":"A","text":"{Goi} có thấy phiên vương cười không? Người có tướng mạo oai phong, chẳng giống phiên vương nào {xung} từng nghe kể."},{"who":"me","text":"Cung nhân nhìn nhau lắc đầu cả rồi, nàng còn che quạt mà nhìn mãi. Gia yến đông người, nàng giữ ý chút."},{"who":"A","text":"{Xung} chỉ nhìn một chút thôi. Có gì sai đâu, người ngồi đó mà."},{"who":"me","text":"Tiếng sáo còn vang, quạt vẫn che nửa mặt nàng. Một cái chạm khẽ vào tay áo, hay một cái liếc mắt làm ngơ."}]}},
{"id":"wc:wc-vuong-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thu lùa vào hiên, tiếng chuông bạc nhỏ leng keng khi {A} nâng chiếc chuông khắc ấn phiên vương, nội giám đã ghi sổ ngay lúc trao."},{"who":"A","text":"{Goi} xem, phiên vương ghé thăm hoàng nữ, tặng một chiếc chuông bạc nhỏ xinh. {Xung} nhận mà vừa vui vừa sợ."},{"who":"me","text":"Chuông bạc khắc ấn phiên vương, nội giám đã ghi sổ. Nàng nhận đúng phép rồi, sao còn sợ?"},{"who":"A","text":"Sợ người ta hiểu lầm, sợ lễ mừng cháu thành điều tiếng. Mà chuông này, đứa nhỏ thích lắm."},{"who":"me","text":"Tiếng chuông bạc còn leng keng trên tay nàng, nội giám vừa ghi sổ xong. Lời đầu tiên của {xung} sẽ là lời cuối cùng nàng nhớ."}]}},
{"id":"wc:wc-ret-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tuyết dày phủ trắng mái ngói, trong cung lạnh, chiếc lò đồng khắc dấu Nội vụ phủ chỉ còn vài hòn than đỏ yếu ớt."},{"who":"A","text":"{Goi} đến thăm {xung} giữa trời giá thế này sao? {Xung} ôm lò than cuối cùng, ngồi sát vào mà vẫn run."},{"who":"me","text":"Môi nàng tím tái mà vẫn cố cười. Lò đồng này ai đến cung nàng cũng thấy, than còn có bao nhiêu?"},{"who":"A","text":"Còn nửa lò, đủ qua đêm nay nếu {xung} không ngủ. Mà ngày mai thì chưa biết, than Nội vụ phủ chưa phát."},{"who":"me","text":"Lò đồng còn vài hòn than đỏ, tuyết ngoài kia chưa ngừng. Chia hay giữ, đêm nay sẽ trả lời."}]}},
{"id":"wc:wc-ret-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân cung trắng tuyết, một cung nữ quét tuyết từ sớm, đôi bao tay vải bông vá chằng chịt, các ngón sưng đỏ lên vì cước."},{"who":"A","text":"{Goi}, nô tỳ xin lỗi. Quản sự quát nô tỳ nhanh lên, nô tỳ quét mãi mà tuyết cứ rơi mãi. Bao tay này nô tỳ vá đã nhiều lần."},{"who":"me","text":"Tay ngươi sưng đỏ thế kia, ai nhìn cũng thấy bao tay ấy, các cung nữ khác đều từng nhìn thấy ngươi đeo."},{"who":"A","text":"Đại hàn kéo dài, việc nặng cứ dồn xuống kẻ dưới. Nô tỳ không dám than, chỉ sợ làm chậm việc."},{"who":"me","text":"Đôi tay sưng đỏ của nàng, ta nhìn mà không yên. Quản sự thì đang đứng ngay đó."}]}},
{"id":"wc:wc-ret-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho áo bông mở ra, hơi vải mới và mùi long não tỏa ngát; {A} ôm một chiếc áo dày trên tay, mắt đảo quanh sân tìm người chịu nhận cùng."},{"who":"A","text":"{Goi} tới thật đúng lúc. Đại hàn kéo dài, hậu cung mở kho áo bông cho kẻ dưới. {Xung} đang tìm người cùng góp tay phân phát."},{"who":"me","text":"Nghe nói lệnh mở kho vừa xuống, mà nàng đã xếp áo thành chồng. Nàng có lòng nhân hậu thật."},{"who":"A","text":"Một mình {xung} lo không hết. Cả hậu cung ai cũng chờ xem {goi} có góp tay không."},{"who":"me","text":"Áo bông ai cũng muốn thấy người khác góp trước. {Xung} sẽ là người ra tay, hay người đứng nhìn?"}]}},
{"id":"wc:wc-trung-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Châu chấu bay đen đồng ngoài thành, trong cung rương mở hé, một hũ gạo nếp niêm dấu Ngự thiện phòng lấp ló dưới lớp áo."},{"who":"A","text":"{Goi}! Sao lại vào không gõ cửa? Hũ gạo nếp này... {Xung} chỉ muốn giữ phòng thân. Hồ sơ Ngự thiện phòng ghi rõ cả."},{"who":"me","text":"Kho lúa thiếu, lệnh cắt bớt bữa đã ban xuống. Nàng nhận lệnh mà vẫn giấu hũ gạo, {xung} vô tình thấy rồi."},{"who":"A","text":"Nàng đừng nhìn {xung} như vậy. Lệnh nào cũng cắt phần người, ai mà chẳng lo cho mình."},{"who":"me","text":"Hũ gạo nếp nằm trong rương nàng, mà mặt nàng thì đã đỏ bừng. {Xung} có thể giữ kín, cũng có thể nói ra."}]}},
{"id":"wc:wc-trung-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống sau hàng hiên cung nữ, một bóng nhỏ gói vội nửa bát cháo vào chiếc khăn thêu tên nàng, tay giấu sau lưng khi nghe bước chân."},{"who":"A","text":"{Goi}... nô tỳ xin {goi} đừng nói ai. Nô tỳ chỉ muốn mang ít cháo ra cổng cung cho thân đệ nhỏ."},{"who":"me","text":"Châu chấu hại mùa, mỗi buổi chỉ còn nửa bát cháo mà ngươi gói đi hết sao? Khăn này thêu tên ngươi, ai cũng nhận ra."},{"who":"A","text":"Nô tỳ nhịn được, đệ nô tỳ không nhịn nổi. Nô tỳ cầu xin {goi} chỉ lần này thôi."},{"who":"me","text":"Khăn bọc cháo run run trong tay nàng. Bước chân quản sự đang tới gần, ta phải quyết thật nhanh."}]}},
{"id":"wc:wc-trung-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Sân phát lương vắng bóng quan, một hũ gạo chia phiên đặt giữa hai cung nhỏ, tiếng cãi nhau vang lên át cả tiếng chim."},{"who":"A","text":"Gạo cung nhỏ đã chậm lại còn chia thế này, {xung} thiếu hơn {goi} nhiều, {goi} đừng chối!"},{"who":"B","text":"{Goi} nói hay thật. Thiếu thì ai chẳng thiếu, châu chấu hoành hành thế này, cung nào cũng đói."},{"who":"A","text":"Đói thì chia theo phiên cho đúng, cớ gì {goi} lại lấy phần nhiều hơn?"},{"who":"B","text":"Tiếng cãi to thế kia, chắc cả cung đã nghe rồi. Cứ thế mãi, ai kéo ra giữa cũng khó xử."}]}},
{"id":"wc:wc-vuco-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thị vệ lật tung rương gỗ giữa sân, đáy rương hiện ra hình nhân gỗ đào, kim đâm xuyên ngực, chỉ đỏ của Dệt cục buộc chặt."},{"who":"A","text":"{Goi}, {xung} không biết gì hết! Hình nhân này không phải của {xung}, thật sự không biết ai bỏ vào đáy rương."},{"who":"me","text":"Biên bản soát ghi rõ kim đâm cùng chỉ Dệt cục. Nàng khóc như thế, mọi người đều đang nhìn {xung}, chờ lời chứng."},{"who":"A","text":"Đêm đó {xung} chưa rời cung nửa bước, {goi} có nhìn thấy không? Xin {goi} nói một lời."},{"who":"me","text":"Hình nhân gỗ đào nằm đó, ai nhìn cũng sợ. Điều {xung} đã thấy đêm ấy, hôm nay phải nói ra thế nào?"}]}},
{"id":"wc:wc-vuco-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Điện Thận hình ti tối ánh đèn, một cung nữ quỳ giữa nền gạch lạnh, trước mặt lá bùa vải đỏ thêu chỉ tên cung tìm thấy trong khay giặt."},{"who":"A","text":"{Goi}, nô tỳ thật không biết lá bùa ấy! Nô tỳ chỉ giặt đồ, bùa này không phải nô tỳ làm."},{"who":"me","text":"Chỉ thêu tên cung trên bùa, mà khay giặt thì ai cũng chạm tay vào được. Ngươi nhìn ta làm gì?"},{"who":"A","text":"Nô tỳ chẳng còn ai để nhìn, chỉ mong {goi} nói một câu. Nô tỳ ở cạnh {goi} cả buổi hôm ấy mà."},{"who":"me","text":"Lá bùa đỏ nằm trên nền gạch, hơi lạnh bốc lên đến tận mắt ngươi. Một lời của ta, nặng hơn cả tấm bùa."}]}},
{"id":"wc:wc-vuco-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đèn dầu leo lét trong phòng đóng kín, tráp trang sức bị lục nằm trên đầu gối {A}, biên bản soát cung và dấu niêm vẫn còn nguyên."},{"who":"A","text":"{Goi}, thị vệ vừa trả lại tráp này. Biên bản soát cung còn kèm dấu niêm. Tay {xung} cứ run mãi, chẳng ngăn được."},{"who":"me","text":"Cửa đóng chặt thế này, cả cung cũng nặng nề. Nàng ngồi dưới đèn mà trông như muốn tan vào bóng."},{"who":"A","text":"{Xung} chỉ hỏi một câu thôi... có ai trách {xung} không? Có ai nghĩ {xung} làm điều ấy không?"},{"who":"me","text":"Nàng chỉ hỏi một câu nhỏ, mà nhỏ đến nỗi {xung} không dám trả lời qua loa."}]}},
{"id":"wc:wc-cam-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trống canh thúc liên hồi, các cổng cung khép kín như một vòng tay lạnh; {A} đứng sát cửa, bức thư niêm dấu Nội vụ phủ run trong tay."},{"who":"A","text":"{Goi}, người ngoài cổng không cho {xung} ra, lính canh cũng không cho thư vào. {Xung} sai người xin mà bị chặn lại."},{"who":"me","text":"Thư niêm kín, dấu Nội vụ phủ rõ ràng. Lính canh đã nhìn thấy, nàng muốn gửi gì cho người nhà?"},{"who":"A","text":"Thư báo tin bình an cho nhà. Giới nghiêm thế này, người nhà chắc đang đứng ngồi không yên."},{"who":"me","text":"Thư nhà nàng cầm run run, cổng cung thì đóng im ỉm. Một lá thư mà ngăn cả một đêm giới nghiêm."}]}},
{"id":"wc:wc-cam-002","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Điện lớn trải chiếu san sát, đèn nhỏ chớp tắt trong lệnh giới nghiêm; tiếng cãi vặt giữa hai tấm chiếu vang đến tận mái."},{"who":"A","text":"Chiếu của {goi} hôi quá, mùi hăng như ướp mắm. {Xung} không nằm cạnh được, chuyển đi chỗ khác đi!"},{"who":"B","text":"Còn {goi} thì ngáy ầm cả điện, tiếng như sấm. Hôm qua {xung} không ngủ nổi vì {goi}."},{"who":"A","text":"Ngáy là chuyện trời sinh, chiếu hôi là chuyện tay làm. Ai đúng ai sai, cả điện đang nghe."},{"who":"B","text":"Cả điện đang cười kia kìa, rồi đồng loạt nhìn sang người ngồi giữa, chờ có người phân xử."}]}},
{"id":"wc:wc-cam-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung phủ bóng đêm, lính canh chắn ngang lối với giọng điệu hách dịch; {A} đứng nép, thẻ bài ra vào khắc tên cung nàng lủng lẳng trong tay."},{"who":"A","text":"{Goi}, lính canh đòi quà mới cho {xung} lấy đồ ăn vào cung. Thẻ bài của {xung} khắc tên cung, họ đã xem rồi mà vẫn không tha."},{"who":"me","text":"Nàng đứng đó mắt ngân ngấn nước. Giới nghiêm kéo dài, lính canh bắt đầu hạch sách cung nhỏ à?"},{"who":"A","text":"Họ biết cung nhỏ không dám kêu. {Xung} có nhịn được cũng không đủ bạc, mà đồ ăn lại thiếu."},{"who":"me","text":"Thẻ bài nàng đưa lên, lính canh vẫn không buông. Nên chọn trả bạc, báo quan, dạy nàng, hay khuyên nàng nhịn?"}]}},
{"id":"wc:wc-trom-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm kiểm kê xong, ngự khố hụt một chiếc bình men xanh, ấn Nội vụ phủ dưới đáy bình thành đầu mối cho cả cung xôn xao."},{"who":"A","text":"{Goi}, người ta cứ nhìn {xung} vì {xung} vừa được ban nhiều đồ lạ. {Xung} không lấy bình ấy, thật không lấy!"},{"who":"me","text":"Sổ ngự khố ghi rõ bình ấy, ấn dưới đáy ai cũng biết. Nàng khóc thế, {B} đứng cạnh sao cứ lặng im?"},{"who":"A","text":"{B} lặng im, {xung} cũng không hiểu vì sao. Nội vụ phủ tìm khắp nơi mà không thấy, {xung} sợ hóa thành kẻ trộm."},{"who":"me","text":"Bình men xanh vẫn mất, {B} vẫn lặng thinh. Chỉ một lời của {xung} cũng đủ làm cán cân nghiêng."}]}},
{"id":"wc:wc-trom-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quản sự quát vang giữa sân thượng viện, một cung nữ nhỏ đứng giữa vòng người, chiếc thìa bạc khắc tên Ngự thiện phòng nằm trên bàn tay run rẩy."},{"who":"A","text":"{Goi}... thìa này nô tỳ thật không lấy! Nô tỳ không biết vì sao nó nằm trong rương của nô tỳ."},{"who":"me","text":"Sổ ghi rõ thìa bạc ấy khắc tên Ngự thiện phòng, bị tìm thấy trong rương ngươi. Ngươi nhìn quanh làm gì?"},{"who":"A","text":"Nô tỳ chỉ mong có người đứng ra. Cả cung đều đang bị thẩm vấn, nô tỳ nhỏ nhất nên bị quát nhiều nhất."},{"who":"me","text":"Chiếc thìa bạc ghi rõ tên Ngự thiện phòng, mà người nhận tội lại là một đứa trẻ. Ta phải nghe nàng nói hết đã."}]}},
{"id":"wc:wc-trom-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Điện lặng như tờ khi khay ngọc ngự ban bị nhắc đến, tên khay có trong sổ, ghi nợ chưa trả, giữa hàng phi tần ánh mắt chạm nhau như lưỡi dao."},{"who":"A","text":"Khay ngọc mất, án trộm ngự khố vẫn chưa tìm ra. {Xung} nói thẳng, món ấy có liên can tới cung của {goi}."},{"who":"B","text":"{Goi} đừng vu cho {xung}! Cung {xung} sạch sẽ, {goi} lấy gì làm chứng mà nói thế trước mọi người?"},{"who":"A","text":"Chứng cứ thì để Nội vụ phủ tìm. {Xung} chỉ hỏi, vì sao khay đó ghi nợ mà chưa thấy trả?"},{"who":"B","text":"Hỏi cũng phải có chừng mực. Cả điện đang chờ xem ai đúng, ai sai."}]}},
{"id":"wc:wc-phong-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bảng phóng cung nhân dán trước điện, mực còn ướt; một cung nữ lần đầu thấy tên mình trên đó, ôm chiếc khăn thêu hoa lan cũ đứng trước ngươi."},{"who":"A","text":"{Goi}, nô tỳ nhận lệnh xuất cung rồi. Nô tỳ ở đây nửa đời người, chưa từng ra ngoài. Mừng thì mừng, mà tủi cũng tủi."},{"who":"me","text":"Chiếc khăn thêu hoa lan ngươi cầm, chính là khăn ngươi thêu cho ta lúc mới vào cung. Ngươi vẫn giữ sao?"},{"who":"A","text":"Nô tỳ giữ để nhớ. Hôm nay ra ngoài, nô tỳ cũng không biết lấy gì dựa."},{"who":"me","text":"Khăn hoa lan còn thơm mùi xà phòng cũ, cổng cung đang chờ nàng. Giữ nàng hay tiễn nàng, đến lúc nói."}]}},
{"id":"wc:wc-phong-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài vườn mấy cung nữ reo thầm khi lệnh phóng cung ban xuống; trong phòng, {A} ngồi lặng, tráp chỉ thêu mở nắp, tên cung nữ thân cận thêu trên mặt."},{"who":"A","text":"{Goi}, cung nữ thân cận của {xung} được ra cung rồi. {Xung} mừng cho nàng, mà nghĩ đến ngày vắng nàng, lòng lại nặng."},{"who":"me","text":"Tráp chỉ thêu có tên nàng ấy trên nắp, ai cũng từng nhìn thấy. Nàng nhờ {xung} xem hộ điều gì?"},{"who":"A","text":"{Xung} muốn tặng nàng chút gì mang theo, mà chẳng biết chọn gì cho vừa lòng. {Goi} xem hộ {xung}."},{"who":"me","text":"Nàng vừa mừng vừa tủi, tráp chỉ thêu còn mở nắp. Một món quà tiễn, {xung} nên chọn thế nào cho phải tình?"}]}},
{"id":"wc:wc-phong-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin phóng cung chạy khắp hiên như gió luồn, cung nữ nơi nào cũng thấp thỏm; giữa sân hai phi tần chạm mặt, mắt cùng nhìn về phía ngươi."},{"who":"A","text":"{Goi}, nghe nói cung nữ của {goi} sắp được phóng ra, mà {B} lại hiểu là {goi} đã xin trước. {Xung} nói rõ ngay đây."},{"who":"me","text":"Chuyện chưa rõ thì lời đã bay khắp cung. {Xung} đâu có xin trước."},{"who":"A","text":"Hai nàng nhìn {goi} dò hỏi, tiếng bàn tán cứ lớn lên mãi. {Xung} chỉ muốn {goi} nói một câu cho yên."},{"who":"me","text":"Lời đồn đã lớn hơn lời giải thích, hai ánh mắt còn dò. Nói một lần cho rõ, hay cười cho nhẹ, giờ là lúc chọn."}]}},
{"id":"wc:wc-hon-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hồi môn đã lên xe, hộp nữ trang khắc tên công chúa trên nắp, dấu Nội vụ phủ ghi sổ ngày xuất giá, giữa sân nghe tiếng khóc nức nở."},{"who":"A","text":"{Goi}, con gái {xung} sắp xuất giá rồi. Hộp nữ trang này {xung} ôm từng đêm, chỉ sợ đưa ra rồi không còn gì giữ bên người."},{"who":"me","text":"Cả cung đang rộn ràng, mà nàng khóc giữa sân thế này. Hồi môn đủ rồi, nàng còn lo điều gì?"},{"who":"A","text":"Lo con xa nhà, lo nó không có ai che chở. {Goi} làm ơn nói với công chúa một lời cuối giúp {xung}."},{"who":"me","text":"Người mẹ đứng giữa sân khóc, nhờ {xung} nói lời cuối. Lời ấy nên nhẹ như gió hay nặng như quà?"}]}},
{"id":"wc:wc-hon-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng cung mở rộng, kiệu hoa dừng chờ, hàng nội giám đứng chắn như bức tường đỏ; một chiếc túi thơm hoa lài được dúi vội vào tay ngươi."},{"who":"A","text":"{Goi}, túi thơm hoa lài này {xung} thêu chữ chúc, nhờ {goi} đưa cho công chúa trước khi kiệu đi. Xin {goi} nhanh lên!"},{"who":"me","text":"Hàng nội giám đứng chắn kín, ai cũng lúng túng. Kiệu sắp đi, mà túi thơm thì nhỏ xíu."},{"who":"A","text":"{Xung} chỉ muốn công chúa nhận được, ngửi hương hoa lài mà nhớ nhà. {Goi} làm giúp {xung} chuyện này."},{"who":"me","text":"Kiệu sắp đi mà hàng nội giám vẫn chắn. Túi thơm hoa lài nhỏ xíu, mà không thể đến muộn."}]}},
{"id":"wc:wc-hon-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Xe hồi môn xếp dài trước cổng cung, gấm lụa phủ kín; {A} đứng cạnh con gái nhỏ, chép miệng nhìn từng rương một."},{"who":"A","text":"{Goi} xem hồi môn này, chưa bằng người khác. Công chúa nhà {xung} sau này mà thiệt thòi thì {xung} biết làm sao?"},{"who":"me","text":"Cả cung kéo đến xem, mà nàng lại lo xa. Con nàng còn nhỏ, ngày xuất giá còn lâu."},{"who":"A","text":"Còn nhỏ, nhưng người ta nói đến đâu cũng so. {Goi} cũng thấy hồi môn thế này chưa đủ phải không?"},{"who":"me","text":"Rương hồi môn xếp dài, ánh mắt nàng còn dò. Gật đầu, khen, hứa hay giả điếc, đều mở ra một con đường."}]}},
{"id":"wc:wc-ngoai-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa điện, một bóng đang quỳ giữa nắng, váy phủ bụi hiên; ngoài hiên {B} đứng lặng, mắt dò sắc mặt của ngươi."},{"who":"A","text":"{Goi}, nhà mẹ đẻ {xung} bị tra, xin {goi} giúp {xung} vào gặp Hoàng thượng. {Xung} quỳ từ sáng đến giờ."},{"who":"me","text":"Án ngoại thích đã nhao nhao khắp hậu cung. {B} đang nhìn xem {xung} đứng phía nào, nàng có thấy không?"},{"who":"A","text":"Thấy. Nhưng nhà {xung} bị tra, {xung} chẳng còn cách nào khác. {Goi} có nghe không?"},{"who":"me","text":"Cửa điện còn đóng, người quỳ giữa nắng chưa đứng dậy. Đứng cạnh hay đứng xa, {B} đang nhìn."}]}},
{"id":"wc:wc-ngoai-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thị vệ lục rương giữa phòng, bức thư nhà niêm dấu nhà mẹ đẻ rơi ra, nét chữ gửi cha rõ ràng trên mặt giấy, mọi người đều cúi đầu."},{"who":"A","text":"{Goi}, thư này {xung} viết gửi cha, chỉ hỏi thăm sức khỏe cha mẹ thôi. {Xung} không biết trong thư có gì khác."},{"who":"me","text":"Thư mang dấu niêm nhà nàng, thị vệ đã ghi vào biên bản. Nàng nói chỉ hỏi thăm, ai tin được?"},{"who":"A","text":"Không ai dám nhìn {xung}, cả cung cúi đầu. {Goi} cũng đang nghĩ {xung} có tội phải không?"},{"who":"me","text":"Thư nhà rơi ra giữa phòng, mà ai nhìn cũng cúi đầu. {Xung} sẽ là người ngẩng lên đầu tiên."}]}},
{"id":"wc:wc-ngoai-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, đèn dầu hắt bóng người ngồi thẫn thờ, tay nghịch chiếc khăn cũ của mẹ, tiếng gió ngoài cửa như tiếng người khóc."},{"who":"A","text":"{Goi} ngồi với {xung} một lát đi. Cả cung không ai ngủ được, án ngoại thích còn dở, nhà {xung} đang bị tra."},{"who":"me","text":"Nàng không nói gì, chỉ cầm khăn cũ của mẹ trong tay. Khăn ấy hẳn là thứ nàng quý nhất."},{"who":"A","text":"{Xung} chỉ muốn có ai bên cạnh. Một mình nghĩ đến nhà, {xung} sợ lắm."},{"who":"me","text":"Đêm khuya, giữa tiếng gió, nàng chỉ cần một người ngồi gần. {Xung} nên ở lại hay chỉ hỏi thăm một câu?"}]}},
{"id":"wc:wc-phat-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm quện quanh điện nhỏ, tràng hạt trầm hương có dấu chùa Hộ quốc đặt trên bàn thờ giữa tiếng kinh khẽ vọng."},{"who":"A","text":"{Goi} tới đúng lúc, lễ Phật đản nhỏ thôi nhưng khói hương nghi ngút. {Xung} dâng tràng hạt này, miệng khẽ đọc kinh."},{"who":"me","text":"Tràng hạt trầm hương mang dấu chùa Hộ quốc, nhiều người từng thấy nàng đeo. Nay dâng lên bàn thờ, hẳn lòng nàng thành lắm."},{"who":"A","text":"{Goi} định dâng gì? Nhiều người hỏi {xung} mà {xung} chưa kịp hỏi lại."},{"who":"me","text":"Tràng hạt trầm hương ấy đã nói lên lòng thành của nàng. Còn của {xung}, nên lấy món gì?"}]}},
{"id":"wc:wc-phat-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đại trai đàn mở giữa lúc tai ương, tiếng tụng rền suốt đêm; một bài vị gỗ nhỏ đặt trước bàn thờ, tên người thân mới khắc còn thơm mùi gỗ."},{"who":"A","text":"{Goi} đến rồi, xin {goi} cùng quỳ với {xung}. Bài vị này {xung} mang từ nhà vào, cầu cho người thân mất vì thiên tai."},{"who":"me","text":"Bài vị nhỏ thế này, nhưng khắc từng nét tên người. Nàng mang nó vào cung chắc đã cất giữ rất lâu."},{"who":"A","text":"Đêm nào {xung} cũng đặt trước giường, nay mang ra trước trai đàn để người nhận phần phước."},{"who":"me","text":"Nàng quỳ đó, bài vị nhỏ trong tay. Quỳ cùng hay giúp bằng cách khác, đều là cách thương người."}]}},
{"id":"wc:wc-phat-003","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Chùa nhỏ đông người xin hương lộc, tiếng cười dội vào chánh điện; hai phi tần cùng đưa tay giữ bát cháo lộc cuối cùng, nhà sư ghi sổ nhìn ra."},{"who":"A","text":"Bát cháo lộc cuối cùng này, {xung} thấy trước, {goi} buông tay ra đi!"},{"who":"B","text":"{Goi} thấy trước ư? Bát có dấu chùa Hộ quốc, sư thầy ghi sổ phát rõ ràng, {xung} đến trước {goi} một bước."},{"who":"A","text":"Một bước, hai bước, giằng thế này cháo đổ hết bây giờ, cả hàng đang cười kia."},{"who":"B","text":"Nhà sư ngoài kia cũng đang nhìn vào. Cười thì cười, bát này {xung} không buông."}]}},
{"id":"wc:wc-benh-001","dlg":{"L":"A","R":"B","watch":true,"lines":[{"who":"nar","text":"Long thể bất an, cả điện lặng đi trong ánh đèn; thái y vừa bước ra, mặt nặng như chì, hai phi tần đứng đối mặt nhau trước ngưỡng cửa."},{"who":"A","text":"Đêm nay đến phiên {xung} túc trực, {goi} đừng tranh. Long thể bất an, {xung} muốn ở cạnh người."},{"who":"B","text":"{Goi} nói nghe thật lòng. Nhưng {xung} cũng thức mấy đêm rồi, phiên canh đêm nay phải về tay {xung}."},{"who":"A","text":"Thái y bước ra mặt nặng thế kia, ai ở đó cũng phải lo. Tranh nhau lúc này mà người nghe thấy thì sao?"},{"who":"B","text":"Ai cũng nhìn nhau dè dặt cả. Việc này phải có người phân xử cho yên."}]}},
{"id":"wc:wc-benh-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng chuông sớm nghẹn lại như lòng người; trong Phật đường vắng, {A} cầm tờ sớ cầu phúc, dấu Lễ bộ còn ướt mực nơi cuối trang."},{"who":"A","text":"{Goi}, {xung} định mang sớ này tới Phật đường cầu cho Hoàng thượng, mà sợ lòng mình không thành. {Goi} dạy {xung} cầu thế nào đi."},{"who":"me","text":"Tờ sớ có dấu Lễ bộ, ai cũng thấy nàng viết. Nét chữ nàng run, nhưng lòng nàng thật."},{"who":"A","text":"Lòng thành mà không đủ lời, {xung} sợ trời Phật chẳng nghe. {Xung} chỉ muốn Hoàng thượng bình an."},{"who":"me","text":"Tờ sớ nàng cầm run run. Nên cùng nàng đọc kinh, giúp nàng viết lại, hay chỉ ngồi nghe nàng sợ."}]}},
{"id":"wc:wc-benh-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thái y viện đầy người chờ tin, mùi thuốc nóng phảng phất; {A} xách thang thuốc đến tận tay, phương kê của thái y còn kẹp trong tay y đồng."},{"who":"A","text":"{Goi} xem, thang thuốc này {xung} thức suốt đêm sắc, đích thân mang tới thái y viện. Y đồng đã ghi sổ nhận rồi."},{"who":"me","text":"Phương kê của thái y, y đồng ghi sổ nhận. Nàng làm vậy cũng chu đáo, mà nói to thế này, người nghe cũng đông."},{"who":"A","text":"{Xung} muốn mọi người biết lòng {xung} dành cho Hoàng thượng. {Goi} nhìn có phục không?"},{"who":"me","text":"Nàng khoe tận tâm, mà thái y cũng đang nhìn. Khen thật, nhắc khéo hay lặng nhìn, đều có giá."}]}},
{"id":"wc:wc-tinh-001","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng bên mở rộng dịp tỉnh thân, tiếng kiệu lăn trên đá xanh; một bà lão bước vào cung, tay ôm gói trà quê, nhãn đề tên quê nàng."},{"who":"A","text":"{Goi}, mẹ {xung} vừa vào cung. Gói trà quê này nội giám đã xem qua, cho vào cung. Bà muốn chào {goi}."},{"who":"me","text":"Gói trà quê có nhãn nơi nàng sinh ra, bà ôm chặt thế kia. Mắt bà ngấn lệ nhìn {xung} làm {xung} cũng xúc động."},{"who":"A","text":"Mẹ {xung} lần đầu vào cung, sợ phép tắc lắm. Nhìn bà, {xung} chỉ muốn bà yên lòng."},{"who":"me","text":"Bà ngước nhìn {xung} bằng ánh mắt của người lần đầu vào cung. Một lời chào của {xung}, bà sẽ nhớ mãi."}]}},
{"id":"wc:wc-tinh-002","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiên vắng giữa ngày hội ngộ, tiếng cười người nhà vọng từ cung khác, riêng một bóng ngồi lặng ôm bức thư cũ nhàu theo năm tháng."},{"who":"A","text":"{Goi} đi ngang à? {Xung} chỉ ngồi đây cho khuây. Các cung đều đón người nhà, còn {xung} có bức thư của mẹ để đọc."},{"who":"me","text":"Thư có chữ mẹ nàng, cung nữ cung nàng từng nhìn thấy. Nàng còn giữ lại được, cũng là phúc."},{"who":"A","text":"Đọc đi đọc lại, chữ đã nhòe, nhưng {xung} thuộc từng dòng. Nhìn người ta đón mẹ cha, {xung} chỉ biết cười cho qua."},{"who":"me","text":"Nàng gượng cười để che nỗi tủi. {Xung} chỉ cần dừng chân, hay phải làm hơn một cái gật đầu."}]}},
{"id":"wc:wc-tinh-003","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vườn thu sáng nắng, ngón nhẫn ngọc trên tay ông lão lóe lên mỗi bước chân; {A} dẫn cha đi chậm, mắt liếc sang hiên {B} đang đứng."},{"who":"A","text":"{Goi} xem cha {xung} này, nhẫn ngọc có ấn thợ kim hoàn kinh thành, bao người từng ngắm. Dịp tỉnh thân, phải để cha nở mày nở mặt."},{"who":"me","text":"Nhẫn lấp lánh thật, ai đi ngang cũng ngoái nhìn. {B} cười gượng kia, chắc đang chờ xem {xung} khen ai."},{"who":"A","text":"{B} muốn kéo {goi} làm chứng nhà mình cũng không kém. {Goi} đứng giữa hai bên, nói thế nào cũng có người phật lòng."},{"who":"me","text":"Hai nhà khoe nhau, {xung} đứng giữa. Lời nào nhẹ nhất mà vẫn thật nhất, {xung} phải tìm."}]}},
{"id":"nr:tt_co_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới giàn hoa cuối thu, một mảnh giấy xin nhờ cậy của môn sinh phủ Tể tướng bị vò nhàu trong tay nàng, nét chữ viết rất khéo."},{"who":"A","text":"Trong đám môn sinh của phụ thân {xung}, có một người cứ nài {xung} nói giúp. {Xung} không biết hắn thật lòng hay là tai mắt của cha."},{"who":"me","text":"Cha {goi} muốn nghe ngóng con gái cũng là lẽ thường. Điều {goi} sợ nhất là hắn mang tin gì về phủ?"},{"who":"A","text":"{Xung} chỉ muốn biết gốc gác hắn trước. Người trong cung hỏi thì phủ Tể tướng hay ngay, nên phải nhờ người ngoài cung."},{"who":"me","text":"Hỏi cho kín mà không để lộ dấu tay, việc ấy chỉ có hai đường. {Xung} đang cân xem đường nào nhẹ mà chắc."}]}},
{"id":"nr:tt_co_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trà trong chén đã nguội, người trước mặt cứ xoay mãi tờ danh sách môn sinh của phủ Tể tướng, đầu ngón tay trắng bệch."},{"who":"A","text":"{B} sai người làm thân với đám môn sinh của phụ thân {xung}. {Xung} muốn biết nàng ta đã mua chuộc được những ai."},{"who":"me","text":"Môn sinh của cha {goi} mà lại ngả về nhà người khác, {goi} nghi chuyện ấy đã bao lâu rồi?"},{"who":"A","text":"Từ ngày cha {xung} ngã bệnh một trận. Từ đấy, mấy người hay đến thăm bỗng thưa dần, mà {B} thì ngày càng đông khách."},{"who":"me","text":"Muốn biết hết nàng ta đã gom được những ai, phải có kẻ dò cho khéo. {Xung} sẽ tính xem nên sai ai."}]}},
{"id":"nr:tt_co_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một phong thư nhà đã bóc dấu niêm nằm giữa hai người, chữ ký của người nhận khiến nàng không dám nhìn lâu."},{"who":"A","text":"Có kẻ trong cung {xung} chép thư nhà đưa ra ngoài, mà người nhận lại là {B}. Cung nữ nào trong cung {xung} làm việc ấy?"},{"who":"me","text":"Thư nhà là chuyện kín nhất của một người. Ai trong cung {goi} có cớ hay lui tới cung {B}?"},{"who":"A","text":"Nhiều đến mức {xung} không dám đoán. Ai cũng có cớ đi lấy chỉ thêu, mượn kim, xin hoa."},{"who":"me","text":"Vậy phải dò cho ra từng bước chân. {Xung} đang nghĩ nên sai người canh, hay tự đi gặp cho đỡ đứt mối."}]}},
{"id":"nr:tt_co_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn buông trên hành lang, một cung nữ quỳ ngoài cửa điện, hai vai run lên dưới tấm áo thô."},{"who":"A","text":"Cung nữ thân tín của {xung} bị nghi là kẻ chép thư, mà {xung} tin nàng ấy vô tội. Có người sắp đem nàng ấy đi tra."},{"who":"me","text":"Người ta đã định tội thì lời cầu xin cũng khó nghe. {Goi} muốn nàng ấy trốn khỏi ánh mắt người nào?"},{"who":"A","text":"Khỏi những kẻ chỉ cần một người gánh tội là vừa. Nàng ấy theo {xung} từ thuở còn ở nhà, {xung} không nỡ để nàng chịu oan."},{"who":"me","text":"Cho nàng nương thân ít hôm thì được, chỉ là nương ở đâu mới kín. {Xung} đang nghĩ hai nơi có thể giấu."}]}},
{"id":"nr:tt_co_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước điện, một tờ sớ đàn hặc chép lại nửa trang được giữ trong tay áo, bên cạnh là bức thư hỏi chuyện mùa màng."},{"who":"A","text":"Ngự sử đem thư nhà của {xung} ra làm chứng phụ thân kết bè, mà thư ấy chỉ hỏi chuyện mùa màng. {Goi} thường được gần Hoàng thượng."},{"who":"me","text":"Một lá thư vô tội bị đọc thành kết bè, thật khó chịu. {Goi} muốn Hoàng thượng nghe điều gì từ {xung}?"},{"who":"A","text":"Rằng {xung} chưa từng đem chuyện bên gối ra ngoài. Chỉ một câu ấy từ người thân cận, Hoàng thượng sẽ nghĩ lại."},{"who":"me","text":"Lời nói ra thì nhẹ mà nặng như đá. {Xung} sẽ nghĩ xem tự mình thưa, hay nhờ người quanh ngự thư phòng nhắc khéo."}]}},
{"id":"nr:tt_co_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm, tờ sớ đàn hặc được chép lại vội, mực còn ẩm, đặt cạnh ngọn nến sắp lụi."},{"who":"A","text":"Tờ sớ đàn hặc sắp đem ra triều hội. {Xung} cần phụ thân biết trước những lá thư nào đã lọt ra ngoài, để cha kịp nói cho khớp."},{"who":"me","text":"Nói không khớp thì chính lời mình thành chứng cứ. Cha {goi} đã biết triều hội gần kề chưa?"},{"who":"A","text":"Chưa. Cung cấm bị canh kỹ, tin vào phủ Tể tướng phải đi thật khéo, mà chỉ còn rất ít thời gian."},{"who":"me","text":"Tin này phải ra khỏi cung trước canh tư. {Xung} đang nghĩ nên nhờ tay nào gửi đi."}]}},
{"id":"nr:tt_co_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên bậc thềm điện, người ấy đứng chờ từ lâu, hai tay siết lấy khăn lụa đã ướt mồ hôi."},{"who":"A","text":"Hoàng thượng đang thử {xung}: lời ngài nói bên gối có lọt về phủ cha hay không. Có kẻ đã thưa sai lên ngài một chuyện."},{"who":"me","text":"Kẻ ấy thưa sai chuyện gì mà {goi} lo đến thế?"},{"who":"A","text":"Một buổi {xung} ngồi cùng {goi} suốt từ sáng đến chiều. Nếu ngài hỏi, xin {goi} nói thật rằng hôm ấy {xung} có mặt bên cạnh."},{"who":"me","text":"Một lời làm chứng nhỏ mà đổi được lòng Hoàng thượng. {Xung} sẽ nghĩ nên thưa thẳng hay nhờ người hầu cận nói hộ."}]}},
{"id":"nr:tt_co_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua rèm, cuốn một mảnh giấy ghi chép lời thưa tội rơi xuống chân hai người."},{"who":"A","text":"Kẻ thưa với Hoàng thượng rằng {xung} để lọt lời bên gối là người của {B}. {Xung} cần biết nàng ta lấy tin từ đâu."},{"who":"me","text":"Lời bên gối ai nghe được mà đồn ra? {Goi} có nghi ai trong cung mình không?"},{"who":"A","text":"Không ai thân đến thế. Tin ấy nhất định đi qua một đường khác, chưa biết là đường nào."},{"who":"me","text":"Muốn lần ra đường dây ấy thì phải có người nghe ngóng. {Xung} đang cân xem sai người hay tự dò lời."}]}},
{"id":"nr:tt_co_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên có tiếng chim se sẻ, nàng đưa ra một phong thư dán kín, mép giấy đã mềm vì cầm lâu."},{"who":"A","text":"{Xung} muốn có một người ở ngoài triều không qua tay phụ thân. Có một vị quan trẻ ở Hàn lâm viện, chỉ cần đưa được đến tay hắn một lá thư."},{"who":"me","text":"Thư gửi một người xa lạ, trong thư {goi} viết điều gì?"},{"who":"A","text":"Chỉ vài dòng thăm hỏi, nhưng đủ để hắn biết {xung} muốn làm quen mà không qua cha."},{"who":"me","text":"Thư nhỏ mà người nhận lại quan trọng. {Xung} sẽ tính xem gửi đường nào mới không lọt vào mắt phủ Tể tướng."}]}},
{"id":"nr:tt_co_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần trưa, một tờ danh sách các thái giám giữ ấn vừa được gỡ khỏi kẹp sách, nét mực còn mới."},{"who":"A","text":"Có một thái giám giữ ấn muốn theo {xung}, nhưng hắn cần được Hoàng thượng biết mặt. {Goi} hầu ngự thì tiện nhắc tên hắn một lần."},{"who":"me","text":"Hắn muốn theo {goi} vì điều gì, {goi} đã hỏi chưa?"},{"who":"A","text":"Hắn nói chán cảnh làm chân sai vặt, muốn thành người có chỗ đứng. {Xung} thấy hắn cẩn trọng, có thể dùng được."},{"who":"me","text":"Một cái tên đặt trước mặt Hoàng thượng, nặng hơn nghìn lời. {Xung} đang nghĩ nên tự nhắc hay nhờ người thay."}]}},
{"id":"nr:tt_co_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày triều hội, đèn trong điện còn sáng, một tờ giấy ghi chuyện chia quyền Tể tướng nằm trên án."},{"who":"A","text":"Triều hội sắp quyết chuyện chia quyền Tể tướng. Phụ thân {xung} sẽ không lui, Hoàng thượng cũng sẽ không nhường."},{"who":"me","text":"Hai bên đều không chịu nhường thì chỉ có thể vỡ. {Goi} muốn xin điều gì cho phủ Tể tướng?"},{"who":"A","text":"Một đường lui có thể diện. Nếu {goi} được hầu trước buổi triều ấy, xin khuyên Hoàng thượng cho cha {xung} bước xuống mà không mất mặt."},{"who":"me","text":"Một lời khuyên đúng lúc có thể cứu cả một nhà. Để {xung} suy xét xem nên tự mình thưa hay nhờ người bên Hoàng thượng."}]}},
{"id":"nr:tt_co_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước buổi triều, một lá thư niêm kỹ được nắm chặt trong lòng bàn tay run run."},{"who":"A","text":"Phụ thân phải biết trước buổi triều hội rằng Hoàng thượng đã quyết. Lá thư này phải ra khỏi cung trước buổi triều ấy."},{"who":"me","text":"Cổng cung đêm nay canh gác rất chặt. Trong thư {goi} dặn cha điều gì?"},{"who":"A","text":"Dặn cha đừng cãi thêm một lời, đừng để người ta bắt được thóp. Nếu ông biết trước, ông sẽ còn đường xoay xở."},{"who":"me","text":"Đã gấp thế thì không thể chậm một canh giờ. {Xung} đang cân xem nên nhờ ai đưa thư ra."}]}},
{"id":"nr:tt_oan_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa buổi chiều, người ấy đặt xuống bàn một trang sổ sách giả, nét bút nghiêng nghiêng như cố che giấu điều gì."},{"who":"A","text":"Kẻ viết sổ giả hại phụ thân {xung} vẫn chưa bị bắt, mà người nhà {B} lại hay qua lại với hắn. {Goi} giúp {xung} xem nàng ta có nhúng tay không."},{"who":"me","text":"Hai nhà qua lại thì chưa chắc đã cùng một mưu. {Goi} nghi nàng ta vì điều gì cụ thể?"},{"who":"A","text":"Vì sau mỗi lần hắn ra vào, cung nàng ta lại thêm một món lễ hậu. Nhà họ chưa từng rộng tay như thế."},{"who":"me","text":"Có thể dò bằng mắt người ngoài, cũng có thể dò bằng chính lời nàng ta. {Xung} sẽ chọn đường nào ít lộ hơn."}]}},
{"id":"nr:tt_oan_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một mẫu chữ giấu trong tay áo được trải ra dưới ánh nến, từng nét móc nét sổ run run như người còn sợ."},{"who":"A","text":"{Xung} giữ được một mẫu chữ của kẻ viết sổ giả. Chỉ cần đưa nó đến tay một thư thủ ngoài cung so nét."},{"who":"me","text":"Mẫu chữ ấy {goi} lấy được từ đâu mà dám chắc là của hắn?"},{"who":"A","text":"Từ một tờ biên nhận cũ mà hắn quên lấy lại. Người ngoài chỉ cần nhìn nét là biết thật hay giả."},{"who":"me","text":"Một mẫu chữ nhỏ mà giữ được cả mạng người. {Xung} sẽ lo cho nó ra khỏi cung an toàn."}]}},
{"id":"nr:tt_oan_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài hiên mưa lất phất, trong điện chỉ còn tiếng giấy sột soạt, một lời nhắn đã chép sẵn chờ được gửi đi."},{"who":"A","text":"Có kẻ đang muốn đút bạc bịt miệng người giữ kho ngân khố, trước khi {xung} kịp gặp hắn. {Xung} cần một lời nhắn đến tay hắn."},{"who":"me","text":"Một người giữ kho dễ bị mua chuộc, cũng dễ sợ hãi. {Goi} muốn nhắn hắn điều gì?"},{"who":"A","text":"Rằng nhà {xung} sẽ giữ mạng hắn. Hắn chỉ cần biết còn có người đứng sau, hắn sẽ không dám nhận bạc của kẻ khác."},{"who":"me","text":"Lời hứa giữ mạng phải đến tay đúng lúc. {Xung} đang nghĩ nên nhờ ai đưa thì không bị chặn."}]}},
{"id":"nr:tt_oan_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang, ánh đèn lồng chao nghiêng, người ấy bước vào điện với đôi mắt đỏ hoe."},{"who":"A","text":"Vợ con người giữ kho ngân khố đang bị kẻ lạ đến hỏi han. Hắn sợ, sắp chối hết mọi lời."},{"who":"me","text":"Hắn mà chối thì cả án oan này khó gỡ. {Goi} muốn lo cho mẹ con họ thế nào?"},{"who":"A","text":"Một chỗ yên, không ai tìm thấy. Mẹ con họ an ổn thì hắn mới dám nói thật."},{"who":"me","text":"Việc lo cho người ta một chỗ nương mà kín thì cần cẩn thận. {Xung} đang nghĩ hai nơi có thể giấu họ."}]}},
{"id":"nr:tt_oan_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một cuốn sổ ghi đường bạc mở dở trên án, mấy hàng số đã được khoanh tròn bằng mực đỏ."},{"who":"A","text":"Lần theo đường bạc, {xung} thấy nhà {B} hưởng lợi nhiều nhất khi phụ thân {xung} mắc oan. Nàng ta biết {xung} đã thấy."},{"who":"me","text":"Biết bị theo dõi thì nàng ta sẽ ra tay trước. {Goi} đoán nàng ta định làm gì?"},{"who":"A","text":"{Xung} không đoán được, nên mới nhờ {goi}. Hoặc nàng ta xóa dấu, hoặc quay sang đổ ngược lên nhà {xung}."},{"who":"me","text":"Muốn biết nàng ta đi nước nào trước, phải có mắt trong cung hoặc nghe từ miệng nàng. {Xung} sẽ chọn."}]}},
{"id":"nr:tt_oan_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió sớm thổi tờ sớ năm ấy bay mép, trên đó có những cái tên đứng cạnh nhau, ngay hàng thẳng lối."},{"who":"A","text":"Có nhà được lợi từ cái oan của cha {xung}, mà Trung cung chưa hay. {Goi} nói được với Hoàng hậu, xin nhắc người xem lại sổ bổng lộc."},{"who":"me","text":"Muốn nhắc Hoàng hậu thì phải nhắc khéo, không thì thành vu cáo. {Goi} muốn người để ý chỗ nào?"},{"who":"A","text":"Các nhà đứng tên tờ sớ năm ấy. Chỉ cần so bổng lộc trước và sau là thấy ngay."},{"who":"me","text":"Một lời nhắc khéo sẽ đi xa hơn trăm lời tố cáo. {Xung} đang nghĩ nên mở lời thế nào."}]}},
{"id":"nr:tt_oan_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nàng ôm trong lòng một bọc áo bông dày, ngoài buộc dây vải thô, bên trên đặt một phong thư."},{"who":"A","text":"Phụ thân {xung} đã bị giải vào ngục Hình bộ. Ngục lạnh, cha lại già. {Xung} chỉ xin gửi được vào một bọc áo bông và một lá thư."},{"who":"me","text":"Cai ngục không cho thân quyến vào. {Goi} chỉ muốn cha nhận được hai thứ ấy thôi sao?"},{"who":"A","text":"Chỉ cần ông biết con gái không bỏ ông, và mùa đông này không phải chịu rét một mình."},{"who":"me","text":"Một bọc áo, một lá thư nhỏ mà nặng nghĩa. {Xung} sẽ tìm đường nào đến được tay ông."}]}},
{"id":"nr:tt_oan_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin từ ngục Hình bộ vừa đến, tờ giấy báo bệnh còn hằn nếp gấp, mùi ẩm lạnh bám theo."},{"who":"A","text":"Tin từ ngục báo phụ thân {xung} sốt đã mấy ngày. {Xung} không thể tự xin thái y cho một người mang án."},{"who":"me","text":"Người mang án thì thái y nào dám ghi sổ. {Goi} cần thuốc gì cho ông?"},{"who":"A","text":"Một thang hạ sốt, kín đáo, không ai hay. {Goi} quen thái y, xin giúp {xung} một thang thuốc."},{"who":"me","text":"Thuốc này phải vào đến ngục mà không ai biết. Để {xung} suy xét xem lo thế nào cho chu toàn."}]}},
{"id":"nr:tt_oan_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một xấp chứng cứ được gói vải xanh, mép vải buộc chặt bằng sợi tơ."},{"who":"A","text":"Phi tần không được bước vào công đường. Chứng cứ của {xung} phải đến tay một vị quan Đại Lý tự qua người khác."},{"who":"me","text":"Quan Đại Lý tự có chịu nhận chứng cứ từ tay lạ không? {Goi} đã nghĩ người đưa phải là ai?"},{"who":"A","text":"Một người đáng tin, không để lộ gốc gác. {Goi} có người như thế, xin giúp {xung} lần này."},{"who":"me","text":"Chứng cứ mà đến sai tay thì mất cả vụ án. {Xung} sẽ cân nhắc người đưa."}]}},
{"id":"nr:tt_oan_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió đêm thổi lật trang tấu, tiếng tam ty đang xét án vọng lại từ phía xa."},{"who":"A","text":"Tam ty đang xét án phụ thân {xung}. {Xung} chỉ xin Hoàng thượng đừng phán trước khi đọc hết lời khai."},{"who":"me","text":"Lời khai nhiều như núi, Hoàng thượng có kiên nhẫn đọc hết không?"},{"who":"A","text":"Nếu có người nhắc, ngài sẽ đọc. {Goi} được gần ngài, nói hộ {xung} một câu."},{"who":"me","text":"Một câu nhắc đúng chỗ có thể đổi cả án. {Xung} sẽ cân nhắc xem nói trực tiếp hay nhờ người bên cạnh."}]}},
{"id":"nr:tt_oan_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm cuối trước ngày phán án, trên án thư còn mở cuốn sổ ngân khố của phủ Tể tướng, từng dòng ngay ngắn."},{"who":"A","text":"Hoàng thượng sắp phán án phụ thân {xung}. {Xung} không dám xin tha, chỉ xin {goi} nhắc ngài những năm cha {xung} giữ sổ ngân khố không sai một lượng."},{"who":"me","text":"Công lao cũ có đủ che được cái oan hôm nay không? {Goi} nghĩ Hoàng thượng còn nhớ chuyện ấy không?"},{"who":"A","text":"Nếu ngài nhớ thì lòng ngài đã mềm. Chỉ sợ ngài quên, vì năm tháng đã xa."},{"who":"me","text":"Vậy phải nhắc cho đúng lúc, đúng người. {Xung} đang nghĩ nên mở lời thế nào."}]}},
{"id":"nr:tt_oan_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước án phán, khói trầm trong điện cuộn thành vòng, người ấy cúi đầu thật thấp trước mặt nàng."},{"who":"A","text":"Thái hậu đã thấy phủ Tể tướng làm việc từ thời tiên đế. Một lời của người trước ngày phán án nặng hơn trăm tờ sớ."},{"who":"me","text":"Thái hậu ít khi can dự việc triều đình. {Goi} muốn nhắc người điều gì?"},{"who":"A","text":"Chuyện cũ thời tiên đế, khi cha {xung} đứng bên ngài. {Goi} thường hầu Thái hậu, xin nhắc người."},{"who":"me","text":"Chuyện xưa nhắc đúng lúc thường đổi lòng người. {Xung} phải cân nhắc kỹ xem nên đến hầu Thái hậu thế nào."}]}},
{"id":"nr:tt_tranh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng thoảng mùi mực cũ, người ấy lật đi lật lại một tờ danh thiếp của huynh trưởng, ngón tay dừng lại ở cái tên cuối."},{"who":"A","text":"Huynh trưởng {xung} đứng sau {B} không phải vô cớ. Có một món nợ, hay một mối hôn sự buộc huynh vào nhà nàng ta."},{"who":"me","text":"Huynh trưởng {goi} xưa nay không phải người dễ bị ép. Điều gì khiến {goi} chắc là có chuyện giấu kín?"},{"who":"A","text":"Huynh từng nói muốn giữ phủ này cho vững, rồi đột nhiên lại nghiêng về phía nàng ta. Giữa hai chuyện ấy phải có một sợi dây."},{"who":"me","text":"Sợi dây ấy dò từ ngoài hay hỏi từ trong, mỗi đường một nguy. {Xung} đang cân xem nên đi hướng nào."}]}},
{"id":"nr:tt_tranh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh nến chập chờn trên tờ giấy mới trải, mới viết được hai chữ gọi huynh, nét bút dừng lại như còn do dự."},{"who":"A","text":"{Xung} muốn viết cho huynh trưởng một lá thư riêng, không qua tay phụ thân, cũng không qua tay chị dâu. Xin {goi} giúp {xung} đưa ra."},{"who":"me","text":"Thư riêng giữa anh em mà phải lén lút thế này, {goi} chắc cũng đau lòng. Trong thư {goi} muốn nói gì với huynh?"},{"who":"A","text":"Rằng {xung} chưa từng muốn tranh giành, chỉ muốn nhà đừng vỡ. Nhưng lời ấy qua tay người khác sẽ thành lời khác."},{"who":"me","text":"Thư tay phải đến đúng tay người nhận. {Xung} sẽ lo cho nó khỏi lạc."}]}},
{"id":"nr:tt_tranh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một sợi dây đeo chìa khóa kho phủ được đặt lên bàn, người ấy kể mà không dám ngẩng lên."},{"who":"A","text":"Quản gia phủ cha đang chọn phe giữa {xung} và huynh trưởng. Một lá thư của {xung} đến tay lão trước khi lão ngả hẳn sẽ giữ được lão."},{"who":"me","text":"Lão quản gia ấy trung với ai nhiều năm nay?"},{"who":"A","text":"Trung với phủ, nhưng phủ giờ có hai chủ. Lão là người đứng giữa, chỉ cần một lời đúng lúc là lão ngả về {xung}."},{"who":"me","text":"Lời gửi lão mà bị bắt gặp thì hỏng hết. Việc ấy, {xung} sẽ tính xem nên gửi theo đường nào kín nhất."}]}},
{"id":"nr:tt_tranh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa tạt vào hiên, một bà lão tóc bạc ngồi co ro ngoài cổng điện, vai gánh một tay nải nhỏ."},{"who":"A","text":"Ma ma vú nuôi của {xung} vừa bị huynh trưởng đuổi khỏi phủ vì đứng về phía {xung}. Bà già rồi, không chốn nương thân."},{"who":"me","text":"Người đã nuôi {goi} từ tấm bé mà phải đi lang thang, thật không đành. {Goi} muốn bà ở đâu?"},{"who":"A","text":"Đâu cũng được, miễn là yên. Xin {goi} che chở bà ít lâu, đến khi nhà yên lại."},{"who":"me","text":"Có chỗ nương rồi thì bà sẽ bớt khổ. {Xung} đang tính hai nơi có thể đón bà."}]}},
{"id":"nr:tt_tranh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn là đĩa điểm tâm còn nguyên sau bữa tiệc, mấy chiếc bánh nhỏ đã nứt vỏ, mùi bột ngọt thoảng lên."},{"who":"A","text":"Sau bữa tiệc, món điểm tâm từ phủ cha {xung} bị đồn là có độc, ai cũng nhìn về nhà {xung}."},{"who":"me","text":"Lời đồn đã lan ra khắp cung. {Goi} nhờ thái y xem điều gì trước?"},{"who":"A","text":"Xem có độc thật không, và độc từ đâu. {Xung} cần một thái y kín miệng, không để lộ chuyện ra ngoài."},{"who":"me","text":"Phần điểm tâm còn lại là bằng chứng duy nhất. {Xung} sẽ nghĩ nên nhờ ai nghiệm cho kín."}]}},
{"id":"nr:tt_tranh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ngọn đèn dầu, người ấy đẩy một đĩa điểm tâm đến trước mặt nàng, bàn tay không còn giữ nổi thăng bằng."},{"who":"A","text":"{Xung} không hạ độc {B}. Kẻ bày ra chuyện này đang ở gần nàng ta. {Goi} giúp {xung} xem ai đã đưa món điểm tâm đến bàn nàng."},{"who":"me","text":"Món ăn qua nhiều tay trước khi đến bàn. {Goi} có nhớ ai đã chạm vào đĩa ấy không?"},{"who":"A","text":"Nhà bếp, người bưng, người dọn. Chỉ cần tìm ra một bàn tay lạ giữa những bàn tay quen."},{"who":"me","text":"Muốn tìm ra thì phải hỏi từng người, hoặc sai người âm thầm tra. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:tt_tranh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thu thổi bay chiếc khăn đang lau nước mắt, người ấy vội nắm lại trong tay."},{"who":"A","text":"Phụ thân {xung} ngã bệnh nặng, mà thầy thuốc trong phủ là người của huynh trưởng. {Xung} muốn một thái y trong cung ra xem mạch cho cha."},{"who":"me","text":"Sao {goi} không tin thầy thuốc trong phủ?"},{"who":"A","text":"Vì thuốc cha uống đã đổi mấy lần mà bệnh chẳng khá. {Xung} chỉ muốn có người ngoài xem giúp, không ai ghi sổ."},{"who":"me","text":"Chữa bệnh cho một nhà quyền thế mà phải kín như đi trộm. {Xung} sẽ nghĩ hai cách để thái y ra phủ."}]}},
{"id":"nr:tt_tranh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên ngoài trời chưa sáng hẳn, một bức thư chưa niêm được đặt cạnh tấm bài ngà của gia ấn."},{"who":"A","text":"Cha bệnh, gia ấn chưa trao cho ai, huynh trưởng ngồi bên giường. {Xung} cần một lời nhắn đến tai cha trước khi quá muộn."},{"who":"me","text":"Cha {goi} còn tỉnh để nghe không?"},{"who":"A","text":"Lúc tỉnh lúc mê. Nhưng cha vẫn nhận ra giọng con gái, chỉ cần lời ấy đến đúng lúc cha tỉnh."},{"who":"me","text":"Trong phòng bệnh lúc này ai cũng canh chừng ai. {Xung} sẽ tính nên nhờ người nào đưa lời vào."}]}},
{"id":"nr:tt_tranh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, tờ chiếu về gia ấn nhà họ được chép lại hai bản, nét mực còn chưa khô, mép giấy hơi quăn."},{"who":"A","text":"Chuyện gia ấn nhà {xung} đã lọt ra triều. Hoàng thượng chỉ cần nói một câu là phủ cha nghiêng về một bên."},{"who":"me","text":"Một câu của Hoàng thượng đủ định cả nhà. {Goi} muốn người biết điều gì?"},{"who":"A","text":"Huynh trưởng {xung} đứng sau ai. Xin {goi} khéo cho Hoàng thượng biết, đừng để thành chuyện tố cáo."},{"who":"me","text":"Nhắc khéo mà không lộ vẻ chỉ điểm thì phải rất cẩn thận. {Xung} đang nghĩ nên tự nhắc hay nhờ người."}]}},
{"id":"nr:tt_tranh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm Đức Thọ cung còn vương trên ống tay áo người ấy, bên trong ống tay áo là một mảnh giấy ghi chuyện gia ấn."},{"who":"A","text":"Thái hậu là người giữ lễ tông tộc. Nếu người nói gia ấn phải trao theo ý cha, huynh trưởng {xung} không dám cãi."},{"who":"me","text":"Huynh trưởng {goi} không dám cãi lễ, nhưng dám cãi cha sao?"},{"who":"A","text":"Cãi cha thì được, nhưng cãi Thái hậu thì cả họ cùng chịu. {Goi} hầu Thái hậu, xin thưa giúp một lời."},{"who":"me","text":"Lời thưa với Thái hậu phải đúng lễ. Để {xung} suy xét xem nên thưa tay không hay có lễ kèm."}]}},
{"id":"nr:tt_tranh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thiệp mời gia yến cuối năm in chữ vàng nằm trên bàn, tên chị dâu đứng ngay cạnh tên {B}."},{"who":"A","text":"Gia yến cuối năm, huynh trưởng, chị dâu và {B} ngồi chung một mâm với {xung}. {Xung} cần biết trước {B} đã hẹn gì với chị dâu."},{"who":"me","text":"Cả một mâm cơm mà thành bàn cờ. {Goi} nghi họ sẽ làm gì giữa bữa?"},{"who":"A","text":"Đến bữa họ sẽ ép {xung} một điều trước mặt cả nhà. Nếu biết trước, {xung} còn kịp liệu."},{"who":"me","text":"Dò từ phía đám người hầu yến hay từ chính chị dâu {goi}, mỗi đường một cái giá. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:tt_tranh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên bàn gia yến, một tờ sơ đồ chỗ ngồi vẽ nguệch ngoạc, chiếc ghế gần phụ thân bị gạch chéo."},{"who":"A","text":"Hoàng hậu xếp chỗ ngồi gia yến. Chỉ cần {xung} ngồi cạnh phụ thân, không ngồi dưới huynh trưởng, cả phủ sẽ hiểu."},{"who":"me","text":"Chỗ ngồi nhỏ mà ý nghĩa lớn. {Goi} muốn nói gì với cả nhà qua chỗ ấy?"},{"who":"A","text":"Rằng cha vẫn coi {xung} là con đích, không phải kẻ đứng sau. {Goi} nói được với Hoàng hậu, xin cho {xung} một chỗ ngồi."},{"who":"me","text":"Xin chỗ ngồi mà thành xin lẽ phải. {Xung} phải cân nhắc kỹ xem nên xin trực tiếp hay qua tay người lo việc xếp chỗ."}]}},
{"id":"nr:tt_mat_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới giàn thiên lý, nàng đặt nhẹ chén trà xuống, hỏi về điều mà từ lâu chưa dám nói thành lời."},{"who":"A","text":"Giữa {xung} và Hoàng hậu có một điều phụ thân {xung} đã hứa, mà {xung} chưa từng được đọc. {Goi} thường hầu Trung cung."},{"who":"me","text":"Lời hứa của bậc cha mẹ, con cái phải gánh. {Goi} muốn biết điều gì về lời hứa ấy?"},{"who":"A","text":"Xem Hoàng hậu còn giữ lời hứa ấy không. Nếu người đã quên, {xung} sẽ không biết mình đang đứng ở đâu."},{"who":"me","text":"Dò ý Hoàng hậu cần khéo hơn cả dò ý Hoàng thượng. {Xung} sẽ cân nhắc đường đi."}]}},
{"id":"nr:tt_mat_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một lá thư gửi phụ thân đã viết hai lần rồi xé hai lần, mảnh giấy vụn rơi quanh chân bàn."},{"who":"A","text":"Bản mật ước nằm trong thư phòng phụ thân {xung}. {Xung} chỉ xin cha chép cho một bản. Lá thư hỏi không thể qua tay Kính sự phòng."},{"who":"me","text":"Thư qua Kính sự phòng thì ai cũng đọc được. {Goi} sợ ai đọc nhất?"},{"who":"A","text":"Sợ người của Trung cung. Mật ước mà lộ ra thì cả nhà {xung} cùng gánh."},{"who":"me","text":"Thư hỏi chuyện này phải đến tay cha {goi} nguyên vẹn. {Xung} sẽ nghĩ xem nhờ ai mang ra."}]}},
{"id":"nr:tt_mat_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ chỉ sắc phong mới vẫn còn gói trong lụa vàng, người ấy nhìn nó mà không có vẻ vui."},{"who":"A","text":"Theo mật ước, {xung} chỉ được đứng dưới Trung cung một bậc. Nay {xung} đã được thăng quá bậc ấy, Hoàng hậu coi đó là món nợ phải đòi."},{"who":"me","text":"Được thăng mà thành mắc nợ, thật trớ trêu. {Goi} muốn xin gì ở Hoàng hậu?"},{"who":"A","text":"Một kỳ hạn, đừng đòi ngay. Xin {goi} thưa với người, cho {xung} thời gian liệu."},{"who":"me","text":"Xin thời gian cũng là một cách nhận nợ. Việc ấy, {xung} sẽ tính xem nên thưa thế nào cho vừa."}]}},
{"id":"nr:tt_mat_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa sổ, lá thư chúc mừng thăng bậc chất đống trên án, nhưng người ấy không đọc lá nào."},{"who":"A","text":"Nếu Hoàng thượng nói một câu rằng {xung} được lên bậc là ý ngài, Trung cung sẽ không đòi được. {Goi} được gần thánh giá."},{"who":"me","text":"Một câu của Hoàng thượng đủ đổi nợ thành ân. Sao {goi} không tự xin?"},{"who":"A","text":"{Xung} không dám. Lời xin từ người trong cuộc dễ thành lời cầu lợi, mà lời nhắc từ người ngoài thì tự nhiên hơn."},{"who":"me","text":"Vậy phải nhắc cho khéo, nói như vô tình. {Xung} sẽ cân xem nhắc thế nào."}]}},
{"id":"nr:tt_mat_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một khay lá dâu xanh mơn mởn đặt giữa điện, người ấy nhìn khay lá như nhìn một lời thử thách."},{"who":"A","text":"Hoàng hậu giao {xung} lo lễ Thân tằm. Làm kém là phụ lòng, làm hơn là lấn Trung cung."},{"who":"me","text":"Giữa hai bờ ấy khó mà đứng cho vững. {Goi} muốn Hoàng hậu hiểu điều gì?"},{"who":"A","text":"Rằng {xung} chỉ dám làm theo lệ cũ, không hơn không kém. Xin {goi} thưa giúp một lời với người."},{"who":"me","text":"Thưa sao cho Hoàng hậu thấy lòng thành mà không thấy toan tính. {Xung} sẽ nghĩ cách."}]}},
{"id":"nr:tt_mat_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên vườn dâu, mấy cành bị bẻ gãy nằm rải rác, lá còn xanh chưa kịp héo."},{"who":"A","text":"Có kẻ muốn lễ Thân tằm của {xung} hỏng giữa chừng: {B} đã cho người hỏi chuyện vườn dâu. {Goi} giúp {xung} dò xem nàng ta định làm gì."},{"who":"me","text":"Vườn dâu mà có kẻ rình thì có thể sẽ có người phá. {Goi} đoán nàng ta ra tay vào lúc nào?"},{"who":"A","text":"Có lẽ đêm trước lễ, khi vườn vắng người. Chỉ cần vài cành bị chặt là lễ không thành."},{"who":"me","text":"Canh vườn hay dò lời người trong vườn, đều phải khéo. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:tt_mat_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một cuộn giấy mật ước mới chưa niêm được đặt trên án, dấu ấn mờ như vừa đóng xong."},{"who":"A","text":"{B} muốn cùng Hoàng hậu viết một mật ước mới và gạt nhà {xung} ra. {Xung} cần biết nàng ta đã đem gì đến Khôn Ninh cung."},{"who":"me","text":"Mật ước mới thì mật ước cũ sẽ ra sao? {Goi} có lo bị bỏ rơi không?"},{"who":"A","text":"Lo chứ. Nhà {xung} đã giữ lời bao năm, nếu bị gạt ra mà không hay biết thì thật nhục."},{"who":"me","text":"Muốn biết nàng ta dâng gì thì phải dò từ người hoặc từ chính nàng. {Xung} sẽ chọn đường nào ít lộ."}]}},
{"id":"nr:tt_mat_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khói trầm bay chậm trong điện, người ấy ngồi thẳng lưng, giọng nói nhỏ như sợ có người nghe."},{"who":"A","text":"Hoàng hậu đang nghe lời một nhà khác. {Xung} chỉ xin người nhớ rằng nhà {xung} chưa từng thất hứa."},{"who":"me","text":"Người đã nghe lời ngọt thì khó nghe lời thật. {Goi} muốn Hoàng hậu nhớ đến việc gì?"},{"who":"A","text":"Những lần nhà {xung} đứng ra gánh việc giúp người. {Goi} có lời với Trung cung, xin nhắc người một câu."},{"who":"me","text":"Nhắc người cũ không thể quên là việc phải làm đúng lúc. {Xung} sẽ nghĩ nên thưa thế nào."}]}},
{"id":"nr:tt_mat_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày thọ yến, chiếc hộp thọ lễ chưa mở nằm giữa điện, bên cạnh là một lá thư gửi phủ."},{"who":"A","text":"Ở thọ yến, {xung}, phụ thân và Hoàng hậu sẽ có một khắc ngồi riêng, ai cũng sẽ giấu đi một nửa sự thật."},{"who":"me","text":"Ba người ngồi cùng mà ba bụng khác nhau. {Goi} muốn cha biết trước điều gì?"},{"who":"A","text":"Rằng {xung} sẽ nói ra điều gì, giữ lại điều gì. Lá thư này phải đến tay cha trước thọ yến."},{"who":"me","text":"Thư đến muộn thì cha {goi} sẽ đỡ lời sai. {Xung} sẽ lo cho thư đến kịp."}]}},
{"id":"nr:tt_mat_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ra khỏi Khôn Ninh cung, nàng còn nắm một nhành hoa người ta tặng, cánh hoa đã nhàu đi vì cầm lâu."},{"who":"A","text":"Trước khi ngồi riêng với Trung cung, {xung} cần biết Hoàng hậu đang giận hay đang sợ. {Goi} vừa thỉnh an người."},{"who":"me","text":"Giận và sợ khác nhau lắm. Sắc mặt người hôm nay ra sao?"},{"who":"A","text":"Người cười, nhưng ngón tay cứ xoay chiếc nhẫn. {Xung} không đoán nổi, xin {goi} cho biết một lời."},{"who":"me","text":"Một dấu hiệu nhỏ cũng đáng giá. Để {xung} tìm cách hỏi cho không lộ ý."}]}},
{"id":"nr:tt_mat_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn là bản mật ước đã sờn mép giấy, một góc đã cháy xém vì từng bị đưa lại gần ngọn nến."},{"who":"A","text":"Ngôi Trung cung đang lung lay. Mật ước trong tay {xung} có thể cứu Hoàng hậu, cũng có thể chôn người. {Xung} chưa quyết."},{"who":"me","text":"Giữ hay đốt, mỗi đường một hậu quả. {Goi} muốn hỏi Hoàng hậu điều gì?"},{"who":"A","text":"Rằng người muốn {xung} giữ hay đốt. {Goi} gặp được Hoàng hậu, xin hỏi giúp một lời."},{"who":"me","text":"Câu hỏi ấy một khi hỏi ra không rút lại được. Để {xung} suy xét xem nên hỏi trực tiếp hay hỏi qua người thân tín."}]}},
{"id":"nr:tt_mat_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm nay trong điện tối, chỉ còn một đốm lửa nhỏ từ ngọn nến soi lên cuộn mật ước giấu trong tay áo."},{"who":"A","text":"Nếu mật ước đến tay Hoàng thượng, ngôi Trung cung sẽ đổ. {Xung} không muốn thế. Xin {goi} khuyên Hoàng thượng đừng tra chuyện cũ nữa."},{"who":"me","text":"Muốn Hoàng thượng thôi tra thì phải có lý do đủ mạnh. {Goi} nghĩ nên nói gì?"},{"who":"A","text":"Rằng chuyện cũ nhắc lại chỉ làm lòng người tan. Một lời khuyên nhẹ nhàng là đủ."},{"who":"me","text":"Khuyên một vị quân vương dừng tay không dễ. Để {xung} suy xét xem khuyên thế nào."}]}},
{"id":"nr:dtq_bien_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tuyết đầu mùa phủ trắng mái điện, trên án là tờ biên báo từ Nhạn Môn, nét chữ vội vã như người viết dưới trời lạnh."},{"who":"A","text":"Hộ bộ nói kho đã cạn, mà tuyết tan là giặc trở lại Nhạn Môn. Lương phải đi trước kỳ khóa sổ mùa xuân."},{"who":"me","text":"Kho cạn thật hay chỉ là cớ? {Goi} có biết quân ở ải còn lương được bao lâu?"},{"who":"A","text":"Chưa đến hết xuân. Phụ thân {xung} đã viết ba tờ xin lương mà chưa tờ nào được duyệt."},{"who":"me","text":"Một lời đặt đúng chỗ có thể mở được kho lương. {Xung} phải cân nhắc kỹ xem nên nhắc Hoàng thượng thế nào."}]}},
{"id":"nr:dtq_bien_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, một tờ sổ lương gập làm tư bị đặt cạnh ngọn nến, góc giấy đã ám khói."},{"who":"A","text":"Phụ thân {xung} cần biết Hộ bộ giữ lương vì kho cạn thật, hay vì có người dặn. Một vị quan Hộ bộ là chỗ quen cũ, xin {goi} hỏi giúp."},{"who":"me","text":"Hỏi đến Hộ bộ thì dễ động đến người cầm quyền. {Goi} nghi có người dặn giữ lương sao?"},{"who":"A","text":"Nghi. Kho năm ngoái còn đầy, năm nay lại báo cạn, mà lính ngoài ải chưa từng nhận đủ."},{"who":"me","text":"Muốn biết sự thật thì phải hỏi khéo, không để lộ ý. {Xung} sẽ tìm người hỏi hộ."}]}},
{"id":"nr:dtq_bien_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió bắc thổi hiên lạnh, người ấy đặt xuống một bức thư từ trại về, dấu niêm đã bị bóc và dán lại."},{"who":"A","text":"Trong trại của phụ thân {xung} có kẻ bán tin cho giặc, và kẻ ấy có người đỡ trong kinh. Thư từ trại về có ghé qua tay người nhà {B}."},{"who":"me","text":"Thư bị bóc thì phải có kẻ đã đọc. {Goi} nghi người ấy trong kinh hay ngoài trại?"},{"who":"A","text":"Trong kinh. Chỉ có trong kinh mới biết thư nào quan trọng để mà chặn."},{"who":"me","text":"Lần theo dấu thư hay dò lời {B}, mỗi đường một nguy. {Xung} đang cân nhắc."}]}},
{"id":"nr:dtq_bien_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn khuya, một lá thư riêng của huynh trưởng vừa đến, giấy nhàu và dính bụi đường, từng chữ viết ngắn gọn."},{"who":"A","text":"Huynh trưởng gửi thư riêng báo trong trại có kẻ bán tin. {Xung} phải hồi âm cho huynh mà không để thư lọt vào tay ai trong trại."},{"who":"me","text":"Huynh {goi} tin cậy {goi} đến mức báo chuyện cơ mật. Trong thư hồi âm {goi} viết gì?"},{"who":"A","text":"Dặn huynh để ý một người, đừng đả động. Nếu thư sai đường, huynh có thể mất mạng."},{"who":"me","text":"Thư ấy phải đi bằng đường không ai ngờ. {Xung} sẽ tính xem gửi theo đường nào."}]}},
{"id":"nr:dtq_bien_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản đồ ải bắc trải trên án, một quân cờ nhỏ đặt ở Nhạn Môn, quân cờ khác nằm xa tít ở kinh thành."},{"who":"A","text":"Phụ thân {xung} xin năm vạn viện binh, Binh bộ lại muốn viện binh đi dưới cờ một công tử nhà quyền quý chưa từng ra ải."},{"who":"me","text":"Công tử chưa từng ra ải mà cầm quân thì quân khó phục. {Goi} muốn Hoàng thượng hiểu điều gì?"},{"who":"A","text":"Tướng không quen ải, quân không quen tướng. Xin {goi} nhắc Hoàng thượng đúng chỗ ấy."},{"who":"me","text":"Một lời nhắc về tướng nào hợp với ải bắc có thể cứu cả đạo quân. {Xung} sẽ cân nhắc."}]}},
{"id":"nr:dtq_bien_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một thiệp mời yến tiệc còn thơm mùi trầm được người ấy ép chặt dưới bàn tay, mép thiệp đã hằn dấu ngón."},{"who":"A","text":"Binh bộ đổi tướng viện binh sau một bữa tiệc ở phủ nhà {B}. {Xung} cần biết bữa ấy ai ngồi, ai hứa gì."},{"who":"me","text":"Một bữa tiệc mà đổi cả tướng, ắt có người hứa hẹn điều gì. {Goi} đoán ai là kẻ cầm trịch?"},{"who":"A","text":"Có thể là chính chủ nhà, cũng có thể là một vị khách {xung} chưa biết mặt."},{"who":"me","text":"Muốn biết ai ngồi ai nói thì hỏi từ hạ nhân hay từ phu nhân, mỗi bên một lối. {Xung} sẽ chọn."}]}},
{"id":"nr:dtq_bien_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ hặc tội mất thành Ứng Châu nằm mở trên án, một góc giấy đã bị vò nhàu bởi bàn tay đã đọc đi đọc lại."},{"who":"A","text":"Ngự sử đổ tội mất thành Ứng Châu cho phụ thân {xung}. Nhưng cửa thành mở từ bên trong, và kẻ giữ cửa là người nhà {B} tiến cử."},{"who":"me","text":"Cửa thành mở từ trong thì ắt có nội gián. {Goi} nghĩ kẻ ấy có biết mình bị theo dõi không?"},{"who":"A","text":"{Xung} không rõ. Chỉ biết nếu tìm ra lai lịch hắn, cha {xung} sẽ có thêm đường gỡ tội."},{"who":"me","text":"Việc này dò thế nào cũng phải đụng đến nhà {B}. {Xung} sẽ cân nhắc xem nên đi đường nào."}]}},
{"id":"nr:dtq_bien_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, mấy bức sớ hặc chồng cao như núi nhỏ, người ấy đứng bên cạnh mà như đứng dưới đáy vực."},{"who":"A","text":"Thành mất, sớ hặc dồn về phụ thân {xung}. {Xung} chỉ xin Hoàng thượng đợi người từ Ứng Châu về rồi hãy xử."},{"who":"me","text":"Người từ Ứng Châu về có thể nói lên sự thật. {Goi} biết khi nào họ đến không?"},{"who":"A","text":"Chưa rõ, có thể chỉ vài ngày nữa. Chỉ sợ trong vài ngày ấy ngự án đã phán xong."},{"who":"me","text":"Xin hoãn một phiên xử cần khéo léo hơn xin tha. {Xung} sẽ liệu cách nói."}]}},
{"id":"nr:dtq_bien_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên kia cửa sổ, tuyết rơi rất nhẹ, người ấy đứng nhìn về phía bắc mà không nói gì một lúc lâu."},{"who":"A","text":"Hoàng thượng muốn ngự giá thân chinh. Phụ thân {xung} sợ nhất điều ấy: giữ ải đã khó, giữ thánh giá còn khó hơn."},{"who":"me","text":"Can một vị quân vương đang hăng chí thật khó. {Goi} muốn lời can ấy nghe thế nào?"},{"who":"A","text":"Nhẹ như lời quan tâm, không như lời cản. Xin {goi} can một lời mà không làm Hoàng thượng giận."},{"who":"me","text":"Can bằng lời hay mượn một vật để nói thay, đều có cái hay riêng. {Xung} sẽ cân nhắc."}]}},
{"id":"nr:dtq_bien_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương nhang Đức Thọ cung vẫn còn vương nơi tay áo người ấy, trên tay cầm một tờ ghi chuyện ải bắc."},{"who":"A","text":"Chỉ Thái hậu mới giữ được Hoàng thượng ở kinh. {Goi} thường hầu Đức Thọ cung, xin thưa với người nỗi lo của ải bắc."},{"who":"me","text":"Thái hậu có chịu nghe chuyện binh đao không? {Goi} muốn người hiểu nỗi lo nào?"},{"who":"A","text":"Nỗi lo mất một người con, mất một vị vua giữa chốn biên cương. Lời ấy chỉ người làm mẹ mới thấu."},{"who":"me","text":"Phải thưa cho khéo để người nghe ra tình chứ không nghe ra tâu việc triều. {Xung} sẽ nghĩ cách."}]}},
{"id":"nr:dtq_bien_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước trận quyết chiến, một phong thư dán kín được đặt giữa hai bàn tay, run đến mức dây niêm lỏng ra."},{"who":"A","text":"Trận quyết chiến sắp nổ ra. {Xung} có một lá thư cho phụ thân và huynh trưởng, có lẽ là lá cuối. Nó phải theo trạm khẩn ra ải."},{"who":"me","text":"Lá thư cuối thì từng chữ đều nặng. Trong thư {goi} dặn họ điều gì?"},{"who":"A","text":"Rằng cả nhà vẫn đợi họ về. Không gì khác, chỉ cần họ biết điều ấy trước khi ra trận."},{"who":"me","text":"Thư này phải đến trước ngày ra quân. {Xung} sẽ lo xem gửi bằng đường nào nhanh nhất."}]}},
{"id":"nr:dtq_bien_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió mùa đông thổi qua điện, người ấy nhìn tờ lịch ghi ngày quyết chiến, đôi mắt thẫm đi."},{"who":"A","text":"Ngày quyết chiến, Hoàng thượng sẽ đợi tin ở điện. {Xung} chỉ xin lập đàn tế cầu thắng, để ba quân biết kinh thành không quên họ."},{"who":"me","text":"Một lễ cầu thắng làm ba quân thêm vững. {Goi} muốn xin việc ấy với Hoàng thượng thế nào?"},{"who":"A","text":"Xin {goi} thưa giúp. Lời xin ấy từ người ngoài cuộc sẽ nhẹ nhàng hơn lời từ nhà tướng."},{"who":"me","text":"Một lời thưa, một nén hương, đều là tấm lòng. Việc ấy, {xung} sẽ tính xem nên giúp bằng cách nào."}]}},
{"id":"nr:dtq_vu_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa án thư là hai bức thư đặt cạnh nhau, một thật một giả, từng nét móc giống nhau đến lạ."},{"who":"A","text":"Bức thư giả bắt chước nét chữ phụ thân {xung} đến từng nét móc. {Xung} có một mẫu chữ thật, cần một thư thủ Hàn lâm viện so giúp."},{"who":"me","text":"Giống đến thế thì người so cũng phải là bậc tinh mắt. {Goi} đã có ai trong lòng chưa?"},{"who":"A","text":"Chưa. Chỉ biết người ấy phải kín miệng và không dính đến phe nào trong triều."},{"who":"me","text":"Một thư thủ đáng tin sẽ gỡ được cả án. {Xung} sẽ nghĩ nên tìm người ở đâu."}]}},
{"id":"nr:dtq_vu_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc điện, một danh sách tên người từng chép thư cho phủ tướng quân đã gạch xóa gần hết, chỉ còn một cái tên."},{"who":"A","text":"Người viết được chữ giả như thế không nhiều. Một kẻ từng chép thư cho phụ thân {xung}, nay lại hay ra vào nhà {B}."},{"who":"me","text":"Một người cũ ra vào nhà người khác thì khó nói là vô tình. {Goi} đã thấy hắn bao nhiêu lần?"},{"who":"A","text":"Nhiều lần, mà lần nào hắn cũng đi lối cửa sau. {Xung} muốn biết hắn mang gì vào, mang gì ra."},{"who":"me","text":"Theo bước hắn hay hỏi thẳng {B}, đều cần khéo tay. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:dtq_vu_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn xuống chậm, ngoài cửa điện có bà ma ma giặt áo tay còn ướt, đang cúi đầu rất thấp."},{"who":"A","text":"Người lính trạm mang bức thư giả vào kinh đang trốn, cả hai bên đều tìm hắn. Mẹ hắn là một ma ma giặt áo trong cung."},{"who":"me","text":"Mẹ ở trong cung mà con trốn ngoài kia, hắn thế nào cũng sẽ tìm về. {Goi} muốn che cho bà ra sao?"},{"who":"A","text":"Cho bà một chỗ an thân, đừng để người ta hỏi dồn. Hắn thấy mẹ an toàn thì sẽ tự tìm đến."},{"who":"me","text":"Che cho mẹ để gọi con về, là kế dựa vào tình. {Xung} sẽ nghĩ xem đưa bà đi đâu."}]}},
{"id":"nr:dtq_vu_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới tán cây, một người hầu của {B} thoáng đi qua rồi biến mất sau bức tường, để lại vài dấu chân trên nền đất ẩm."},{"who":"A","text":"Người của {B} cũng đang tìm người lính trạm. Ai tìm thấy trước thì giữ được lời khai."},{"who":"me","text":"Lời khai của hắn nặng như vàng. {Goi} đã biết người của {B} đi đến đâu rồi chưa?"},{"who":"A","text":"Chưa. Chỉ biết họ ra khỏi cung mỗi sáng sớm và về lúc chiều muộn."},{"who":"me","text":"Phải biết họ đến đâu trước khi họ đến nơi. {Xung} đang cân nhắc cách theo dấu."}]}},
{"id":"nr:dtq_vu_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cổng phủ tướng quân có lính canh đứng sát nhau, trên tay người ấy là một mảnh giấy dặn dò đã gấp nhỏ."},{"who":"A","text":"Phủ nhà {xung} bị canh ngày đêm, không ai ra vào được. Phụ thân sắp về kinh đối chất, {xung} phải gửi cho mẫu thân một lời dặn trước khi cha về."},{"who":"me","text":"Mẫu thân {goi} đang ở trong phủ bị canh. Lời dặn ấy là điều gì?"},{"who":"A","text":"Dặn mẫu thân đừng hoảng, đừng nhận bất cứ ai lạ mặt. Cha về là có người chờ sẵn."},{"who":"me","text":"Lời dặn phải lọt qua hàng rào lính canh. Để {xung} tìm cách mang vào."}]}},
{"id":"nr:dtq_vu_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng chuông canh vọng từ xa, người ấy đứng giữa điện, tay giữ một tờ chỉ dụ chưa được chép hết."},{"who":"A","text":"Phụ thân {xung} về kinh đối chất mà phủ bị canh như phủ tội thần. {Xung} chỉ xin Hoàng thượng cho cha được về nhà trước khi ra công đường."},{"who":"me","text":"Một ngày ở nhà trước phiên xử cũng đủ để người bình tâm. {Goi} muốn Hoàng thượng hiểu điều gì?"},{"who":"A","text":"Rằng cha {xung} là người có công, không phải tù nhân. Lệnh canh quá nặng sẽ làm lạnh lòng người."},{"who":"me","text":"Xin nới lệnh mà không mang giọng trách ai. Để {xung} suy xét xem nên thưa thế nào."}]}},
{"id":"nr:dtq_vu_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn lồng nơi cửa hông hoàng thành, một tờ sổ thẻ bài vừa được lật qua, chữ viết còn chưa ráo."},{"who":"A","text":"Thư giả qua cửa hông hoàng thành trong tay một thái giám có thẻ bài cung {B}. {Xung} cần biết tên hắn trước khi hắn biến mất."},{"who":"me","text":"Thẻ bài là dấu vết rõ nhất. {Goi} nghĩ hắn còn ở trong cung không?"},{"who":"A","text":"Còn, nhưng không lâu. Kẻ làm việc đó chắc chắn sẽ tìm cách ra khỏi cung hoặc bị diệt khẩu."},{"who":"me","text":"Tra thẻ bài hay hỏi đám thái giám cung nàng ta, đều cần nhanh. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:dtq_vu_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang vắng, một tiểu thái giám đứng nép sau cột, hai tay ôm chặt tay áo như muốn giấu mình đi."},{"who":"A","text":"Một tiểu thái giám đã thấy kẻ cầm thẻ bài đêm ấy. Nó sợ bị diệt khẩu. Xin {goi} cho nó làm việc vặt trong cung ít hôm."},{"who":"me","text":"Nó đã thấy mặt kẻ ấy sao? Nó nói với {goi} những gì?"},{"who":"A","text":"Chỉ nói thấy một bóng người mặc áo thái giám, tay cầm thẻ bài. Nó không dám nói thêm."},{"who":"me","text":"Một đứa trẻ sợ hãi mà giữ chìa khóa của cả vụ án. Để {xung} suy xét xem nên giấu nó ở đâu."}]}},
{"id":"nr:dtq_vu_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước phiên đối chất, một tờ khai của người lính trạm được gói trong lụa mỏng, chữ ký đã khô."},{"who":"A","text":"{Xung} có tờ khai của người lính trạm. Phải có một người ngoài cung đem nó nộp Đại Lý tự trước phiên đối chất."},{"who":"me","text":"Nộp trễ một ngày thì tờ khai mất giá trị. {Goi} có ai trong lòng chưa?"},{"who":"A","text":"Chưa. Người ấy phải tin được và không bị người ta nhận mặt."},{"who":"me","text":"Chọn sai người thì cả tờ khai bị chặn. {Xung} phải cân nhắc kỹ xem nên nhờ ai."}]}},
{"id":"nr:dtq_vu_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mặt trời chiều chiếu vào điện, trên án có tờ lịch phiên đối chất, ngày đã được khoanh tròn."},{"who":"A","text":"Phiên đối chất mà Hoàng thượng ngự xem thì không ai dám bẻ cong. Xin {goi} mời Hoàng thượng đến nghe một buổi."},{"who":"me","text":"Hoàng thượng bận trăm việc, sao lại ngự xem một phiên đối chất?"},{"who":"A","text":"Nếu {goi} nói đó là việc liên quan đến lòng trung của một nhà tướng, người sẽ chịu đến."},{"who":"me","text":"Một lời mời đúng lúc có thể đổi cả kết cục. {Xung} sẽ cân nhắc xem mời cách nào."}]}},
{"id":"nr:dtq_vu_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên thỏi mực đen đặt trên khay, bức thư giả nằm mở, nét mực bóng một vệt lạ."},{"who":"A","text":"Thỏi mực viết bức thư giả là loại mực chỉ cung {B} được cấp. {Xung} cần một mẩu mực từ cung nàng ta để so."},{"who":"me","text":"Mực cung cấp thì có dấu riêng. {Goi} có chắc đó là mực của {B} không?"},{"who":"A","text":"Chắc đến tám chín phần. Chỉ cần so mẩu mực là thấy ngay."},{"who":"me","text":"Lấy được mẩu mực mà không lộ ý đồ là việc khéo tay. {Xung} sẽ liệu cách."}]}},
{"id":"nr:dtq_vu_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dấu ấn đóng trên thư giả được người ấy áp sát vào đèn, từng đường khắc nhỏ hiện rõ trên giấy."},{"who":"A","text":"Khuôn ấn đóng trên thư giả được khắc ở một tiệm ngoài kinh. {Xung} cần người đến tiệm ấy hỏi ai đã đặt."},{"who":"me","text":"Tiệm khắc ấn nào cũng giữ kín khách hàng. {Goi} đã biết tiệm nào chưa?"},{"who":"A","text":"Biết tiệm, chưa biết người. Chủ tiệm là người cẩn thận, không nói với kẻ lạ."},{"who":"me","text":"Muốn hỏi được phải có cách khiến lão tin. {Xung} sẽ nghĩ nhờ ai đến hỏi."}]}},
{"id":"nr:dtq_binh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nửa tấm hổ phù bằng đồng nằm trong hộp gấm, mặt đồng sáng loáng dưới nắng, nửa còn lại ở nơi xa tận doanh Bắc."},{"who":"A","text":"Hổ phù còn một nửa ở doanh Bắc. Hoàng thượng cho hạn, mà phụ thân {xung} sợ giao gấp thì quân sinh loạn."},{"who":"me","text":"Giao gấp thì lòng quân dễ động. {Goi} muốn xin nới thêm bao lâu?"},{"who":"A","text":"Một tháng. Chỉ cần một tháng để cha {xung} dặn dò từng tướng, quân mới yên."},{"who":"me","text":"Xin nới hạn mà giữ được nghĩa quân thần là việc khó. {Xung} sẽ nghĩ xem nên thưa thế nào."}]}},
{"id":"nr:dtq_binh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn là bức thư mới viết dở, mực còn loang ở dòng đầu, bên cạnh là mảnh khăn lau nước mắt."},{"who":"A","text":"{Xung} phải khuyên phụ thân giao hổ phù đúng hạn. Lời khuyên ấy cha chỉ nghe từ chính {xung}. Một lá thư phải đến doanh Bắc."},{"who":"me","text":"Khuyên cha giao quyền là điều đau lòng. {Goi} viết sao cho cha hiểu?"},{"who":"A","text":"Rằng giữ binh quyền một ngày là thêm một ngày nghi kỵ. Cha buông thì cả nhà mới yên."},{"who":"me","text":"Lá thư ấy phải đến tay cha trước hạn. {Xung} sẽ tính nhờ ai mang ra bắc."}]}},
{"id":"nr:dtq_binh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một tờ huyết thư của chư tướng được trải ra, từng dấu tay đỏ sẫm xếp thành hàng dài trên giấy."},{"who":"A","text":"Chư tướng doanh Bắc dâng huyết thư xin giữ phụ thân {xung}. Người ngoài đọc là trung, Hoàng thượng có thể đọc là phản."},{"who":"me","text":"Lòng trung đọc sai một nét thành phản. {Goi} muốn Hoàng thượng hiểu thế nào?"},{"who":"A","text":"Rằng đó là lời của lính già nhớ chủ, không phải lời của kẻ kết bè."},{"who":"me","text":"Giải thích một tờ huyết thư mà không thành thêm tội. {Xung} sẽ nghĩ cách thưa."}]}},
{"id":"nr:dtq_binh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một bản nháp sớ đáp lại huyết thư nằm giữa án, nét chữ ngay ngắn và đã sửa nhiều chỗ."},{"who":"A","text":"Phụ thân phải dâng một tờ sớ đáp lại huyết thư, bảo chư tướng tuân chỉ. Bản nháp {xung} đã viết, cần đến tay cha trước khi sớ ông lên triều."},{"who":"me","text":"Sớ này nói giúp cha {goi} điều gì với chư tướng?"},{"who":"A","text":"Rằng lòng trung phải thể hiện bằng việc tuân lệnh. Lời ấy từ cha thì họ nghe, từ người khác họ không nghe."},{"who":"me","text":"Bản nháp phải đến tay cha còn nguyên vẹn. Việc ấy, {xung} sẽ tính xem nên nhờ ai mang đi."}]}},
{"id":"nr:dtq_binh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thiệp ngự yến viền vàng được đặt trên án, ngoài bìa in dòng chữ mời đại tướng quân cùng các lão tướng."},{"who":"A","text":"Ngự yến mời phụ thân {xung} và các lão tướng sẽ thu binh quyền bằng một chén rượu, mà {xung} không có mặt."},{"who":"me","text":"Một chén rượu mà đổi cả binh quyền. {Goi} muốn Hoàng thượng nói gì với cha?"},{"who":"A","text":"Một lời ấm trước khi nâng chén. Nếu {goi} được hầu trước ngày yến, xin nhắc Hoàng thượng chuyện ấy."},{"who":"me","text":"Lời ấm đặt đúng lúc làm chén rượu bớt đắng. Để {xung} suy xét xem nên làm thế nào."}]}},
{"id":"nr:dtq_binh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm trước ngày yến, một mảnh giấy nhỏ bằng bàn tay được người ấy viết rồi xé, rồi lại viết."},{"who":"A","text":"Trước ngự yến, phụ thân {xung} cần biết chén rượu ấy là ân hay là giữ. Chỉ cần nhờ người đưa đến tay ông một mảnh giấy, vỏn vẹn bốn chữ."},{"who":"me","text":"Bốn chữ mà quyết định cả cách cha {goi} nâng chén. {Goi} định viết gì?"},{"who":"A","text":"Chữ đủ để cha hiểu mà người khác nhìn vào không hiểu. Ông sẽ biết nên uống hay nên tạ."},{"who":"me","text":"Mảnh giấy ấy phải đến tay cha trước giờ yến. {Xung} sẽ nghĩ nhờ ai chuyển."}]}},
{"id":"nr:dtq_binh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thổi lật tờ sớ hặc có nhắc đến quân riêng ở quê, mép giấy xô vào chén trà vừa rót."},{"who":"A","text":"{B} gièm rằng phụ thân {xung} vẫn nuôi quân riêng ở quê. {Xung} cần biết ai đã đưa chuyện ấy cho nàng ta."},{"who":"me","text":"Chuyện ở quê nhà mà vào đến kinh, ắt có người chuyển. {Goi} nghĩ ai biết?"},{"who":"A","text":"Chỉ vài người thân quen cũ mới biết đường về quê. Một trong số họ đã đổi lòng."},{"who":"me","text":"Dò theo đường tin hay nghe từ chính miệng {B}, mỗi đường một nguy. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:dtq_binh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm trong Khôn Ninh cung vẫn còn thơm trên áo người ấy, trên tay là chiếc khăn chưa kịp xếp."},{"who":"A","text":"Lời gièm về quân riêng đã đến Trung cung. Hoàng hậu chỉ cần gạt đi như chuyện bàn tán vặt là lời ấy tắt."},{"who":"me","text":"Một lời gạt đi của Hoàng hậu nặng hơn trăm lời giải thích. {Goi} muốn người nói thế nào?"},{"who":"A","text":"Chỉ cần người nói đó là chuyện đàn bà rảnh rỗi đồn thổi. {Goi} được Trung cung tin, xin mở lời."},{"who":"me","text":"Nhờ Hoàng hậu gạt lời gièm là việc tế nhị. Để {xung} tìm cách mở lời."}]}},
{"id":"nr:dtq_binh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai bức thư, một của ngự thư phòng, một của phủ đại tướng quân, nằm song song trên án, hai bên không ai chịu nhìn nhau."},{"who":"A","text":"Hoàng thượng và phụ thân {xung} không còn nói thẳng với nhau, chỉ nói qua {xung}. {Xung} sợ mang sai một chữ."},{"who":"me","text":"Làm sứ giả giữa vua và cha, nặng nề lắm. {Goi} muốn biết điều gì?"},{"who":"A","text":"Ý thật của Hoàng thượng với cha {xung}. {Goi} hầu bên người, xin nghe giúp."},{"who":"me","text":"Nghe lời vua phải nghe cả điều vua không nói. {Xung} sẽ nghĩ nên hỏi thế nào."}]}},
{"id":"nr:dtq_binh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn đặt lời đáp của đại tướng quân chép trong một tờ giấy dày, mép giấy hằn nét chữ nặng tay."},{"who":"A","text":"Lời nhắn của Hoàng thượng {xung} đã mang đi nguyên vẹn. Lời đáp của phụ thân thì nặng quá. {Xung} cần hỏi lại cha trước khi trình lên."},{"who":"me","text":"Lời đáp nặng thì cha {goi} đang giận chăng?"},{"who":"A","text":"Không hẳn giận, mà là cay đắng. Nếu trình nguyên văn, Hoàng thượng sẽ nghe thành lời trách."},{"who":"me","text":"Phải hỏi lại cha để lời đáp mềm hơn mà không đổi ý. {Xung} sẽ lo."}]}},
{"id":"nr:dtq_binh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ấn soái bằng ngọc nằm trong hộp gỗ đàn hương, ngày giao ấn được viết bằng mực đỏ trên tờ lịch."},{"who":"A","text":"Ngày phụ thân {xung} giao ấn soái, lính cũ sẽ đổ về cổng thành. Nếu Hoàng thượng ban một đạo dụ khen công họ, sẽ không ai hô sai."},{"who":"me","text":"Một đám lính cũ đông như thế, chỉ cần một tiếng hô là loạn. {Goi} muốn dụ khen nói gì?"},{"who":"A","text":"Nhắc công họ giữ biên ải, để họ thấy mình được trọng, không phải bị bỏ rơi."},{"who":"me","text":"Một đạo dụ hay một bữa khao đều là cách giữ lòng người. Để {xung} suy xét xem nên xin thế nào."}]}},
{"id":"nr:dtq_binh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn khuya, một mảnh giấy dặn dò nhỏ gấp bốn góc được đặt cạnh thanh gươm treo tường."},{"who":"A","text":"Huynh trưởng {xung} sẽ đứng ở cổng thành ngày giao ấn. {Xung} cần dặn huynh: dù ai hô gì cũng không được rút gươm."},{"who":"me","text":"Huynh {goi} nóng tính, gặp cảnh ấy rất dễ bốc đồng. {Goi} lo nhất điều gì?"},{"who":"A","text":"Lo huynh nghe lính hô mà quên mình đang đứng ở đâu. Chỉ một nhát gươm là cả nhà mang tội."},{"who":"me","text":"Lời dặn ấy phải đến tay huynh trước hôm đó. {Xung} sẽ tính nhờ ai đưa ra."}]}},
{"id":"nr:dtq_huynh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dòng sông Hắc Thủy chỉ còn một lớp băng mỏng trên bản đồ, người ấy đặt ngón tay trên đó mà tay run."},{"who":"A","text":"Giặc đòi tiền chuộc người nhà {xung}, mà sông Hắc Thủy sắp đóng băng. {Xung} không xin bạc, chỉ xin một người đáng tin mang lời hẹn."},{"who":"me","text":"Lời hẹn ấy đến chỗ thương lái biên ải. {Goi} định nhắn điều gì?"},{"who":"A","text":"Rằng nhà {xung} sẽ chuộc người bằng cách khác, xin họ giữ người sống đến khi tìm ra đường."},{"who":"me","text":"Một lời hẹn nhắn qua tay thương lái là một canh bạc sống chết. {Xung} sẽ nghĩ nhờ người nào."}]}},
{"id":"nr:dtq_huynh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa tuyết rơi trên mái điện, người ấy đặt xuống một tờ biên báo về hòa nghị, mép giấy ướt một góc."},{"who":"A","text":"Nếu Hoàng thượng chịu đem chuyện chuộc người vào lời nghị với giặc, nhà {xung} không cần đến bạc. Xin {goi} nhắc Hoàng thượng trước khi sông đóng băng."},{"who":"me","text":"Đem chuyện nhà một người vào lời nghị của cả nước, {goi} có sợ bị người ta chê không?"},{"who":"A","text":"Sợ chứ, nhưng người ở đất giặc không chờ được. Mỗi ngày qua là mỗi ngày nguy."},{"who":"me","text":"Nhắc Hoàng thượng đúng lúc có thể đổi một đời người. {Xung} phải cân nhắc kỹ xem nên nhắc thế nào."}]}},
{"id":"nr:dtq_huynh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén trà của sứ giặc còn đặt dở bên bàn, hơi nóng đã tan, nhưng cái nhìn của người ấy vẫn nhìn vào đó mãi."},{"who":"A","text":"Sứ giặc muốn nói chuyện riêng với {xung}. {Xung} sợ đó là bẫy của kẻ khác, mà {B} lại vừa mời sứ ấy uống trà."},{"who":"me","text":"Sứ giặc đi lại giữa hai nhà thì không thể không nghi. {Goi} đã biết hai người nói gì chưa?"},{"who":"A","text":"Chưa, chỉ biết trà vừa dứt là sứ liền xin gặp {xung}. Có thể là trùng hợp, cũng có thể là sắp đặt."},{"who":"me","text":"Dò xem hai người nói gì mới biết lời mời ấy thật hay giả. {Xung} sẽ chọn đường."}]}},
{"id":"nr:dtq_huynh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn dầu, người ấy mở ra một tờ giấy chép lại dấu ấn, nét khắc nghiêng nghiêng khó nhìn."},{"who":"A","text":"Sứ giặc giữ một tờ giấy có ấn của huynh trưởng {xung}. {Xung} không gặp hắn được. Phải có một người ngoài cung xem tận mắt ấn ấy thật hay giả."},{"who":"me","text":"Ấn thật hay giả quyết định cả việc thương nghị. {Goi} đã biết người nào xem được chưa?"},{"who":"A","text":"Chưa. Người ấy phải quen dấu ấn nhà tướng, mà không được ai biết chuyện."},{"who":"me","text":"Nhờ người xem giúp mà không làm lộ việc. {Xung} sẽ cân nhắc xem nên nhờ ai."}]}},
{"id":"nr:dtq_huynh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng tranh cãi ngoài điện vọng vào, người ấy bước vào trong tay áo giấu một tờ ghi lời phe đánh."},{"who":"A","text":"Phe đánh nói đưa chuyện người nhà {xung} vào hòa ước là nhục quốc thể. Một lời đến tai Hoàng thượng đúng lúc có thể đổi được người."},{"who":"me","text":"Thể diện quốc gia hay mạng một người, bên nào nặng hơn? {Goi} muốn nói thế nào với Hoàng thượng?"},{"who":"A","text":"Rằng cứu một người con của nước cũng là giữ thể diện. Lời ấy phải do người ngoài cuộc nói."},{"who":"me","text":"Một lời của {goi} hay của một lão thần, đều có sức riêng. Việc ấy, {xung} sẽ tính xem nên chọn đường nào."}]}},
{"id":"nr:dtq_huynh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khói trầm Đức Thọ cung phảng phất, người ấy ngồi đối diện nàng, tay xoắn lại với nhau không yên."},{"who":"A","text":"Thái hậu là mẹ, người hiểu nỗi chờ của một nhà có con nơi đất giặc. Xin {goi} thưa với người trước buổi triều nghị."},{"who":"me","text":"Một người mẹ nghe chuyện của một người mẹ khác, lòng sẽ mềm. {Goi} muốn Thái hậu biết điều gì?"},{"who":"A","text":"Rằng nhà {xung} đã chờ bao đêm, không dám ngủ. Thái hậu hiểu, người sẽ nói với Hoàng thượng."},{"who":"me","text":"Thưa với Thái hậu bằng lễ hay chỉ bằng lời, đều phải thành tâm. {Xung} sẽ liệu cách."}]}},
{"id":"nr:dtq_huynh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm, một ngọn nến nhỏ chập chờn soi tờ bản đồ ải, đường cứu người được vạch bằng một nét mực mảnh."},{"who":"A","text":"Còn một đường: cứu người qua ải trong đêm. Có một thị vệ nợ huynh trưởng {xung} một mạng. {Xung} cần đưa đến tay hắn một lời hẹn."},{"who":"me","text":"Nợ một mạng thì hắn có chịu trả không? {Goi} tin hắn đến đâu?"},{"who":"A","text":"Tin được một nửa, nhưng chỉ còn đường này. Lời hẹn phải đến tay hắn mà không ai trong cung biết."},{"who":"me","text":"Một lời hẹn giữa đêm tối là một canh bạc. {Xung} sẽ nghĩ nên nhờ ai đưa."}]}},
{"id":"nr:dtq_huynh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, người ấy ngồi bên một chiếc tay nải đã gói sẵn, như kẻ chuẩn bị cho một chuyến đi không biết có về."},{"who":"A","text":"Đêm cứu người, gia quyến người dẫn đường phải có chỗ nương trong kinh để giặc không bắt làm tin. Xin {goi} lo giúp {xung}."},{"who":"me","text":"Người dẫn đường đã dám liều mạng thì nhà họ cũng đáng được che chở. {Goi} muốn họ ở nơi nào?"},{"who":"A","text":"Nơi kín đáo, không ai biết, đừng gần cung quá. Giặc có tai mắt khắp nơi."},{"who":"me","text":"Lo chỗ cho người của kẻ dẫn đường, là giữ lời hứa từ trước. Để {xung} suy xét xem nên giấu họ ở đâu."}]}},
{"id":"nr:dtq_huynh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ hàng thư mang ấn của huynh trưởng nằm trên án, từng nét chữ run run như viết dưới lưỡi dao."},{"who":"A","text":"Tờ thư xin hàng mang ấn huynh trưởng {xung} đã đến triều. Huynh bị giặc kề đao ép ký, để chúng không chém trăm người lính."},{"who":"me","text":"Một lá thư đổi lấy trăm mạng người. {Goi} muốn Hoàng thượng biết điều gì mà tờ giấy không nói?"},{"who":"A","text":"Rằng huynh ký không phải vì hèn, mà vì thương lính. Triều đình chỉ đọc chữ, không đọc lòng."},{"who":"me","text":"Kể lại sự thật cho người nghe hiểu mà không thành biện hộ. {Xung} sẽ nghĩ cách."}]}},
{"id":"nr:dtq_huynh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh chiều tà, người ấy mở ra một danh sách trăm cái tên, nhiều tên đã bị gạch vì không còn tìm thấy."},{"who":"A","text":"Trăm người được cứu hôm ấy, có người đã về quê. Nếu một người trong họ viết được tờ khai, huynh trưởng {xung} có cứ. {Xung} cần người tìm họ."},{"who":"me","text":"Trăm người rải rác khắp nơi, tìm một người đủ lòng viết khai không dễ. {Goi} nhớ tên ai chưa?"},{"who":"A","text":"Nhớ vài người, quê quán còn ghi lại. Chỉ cần một người chịu nói, những người khác sẽ theo."},{"who":"me","text":"Tìm được một nhân chứng thì cả án đổi chiều. {Xung} sẽ nghĩ nhờ ai tìm."}]}},
{"id":"nr:dtq_huynh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phiên xét sắp mở, trên án là tờ khai của một thân binh, chữ viết nguệch ngoạc mà từng nét đều thật lòng."},{"who":"A","text":"Quan xét nhìn sắc mặt Hoàng thượng mà xử. Nếu Hoàng thượng hỏi một câu về trăm người được cứu, án huynh trưởng {xung} sẽ khác."},{"who":"me","text":"Một câu hỏi của Hoàng thượng có thể đổi sắc mặt cả công đường. {Goi} muốn Hoàng thượng hỏi gì?"},{"who":"A","text":"Hỏi rằng trăm người ấy bây giờ ở đâu, nhờ ai mà sống. Chỉ vậy thôi, quan xét sẽ tự hiểu."},{"who":"me","text":"Nhắc một câu hỏi mà không có vẻ chỉ dẫn. Để {xung} tìm cách."}]}},
{"id":"nr:dtq_huynh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đại Lý tự đã dán cáo thị, người ấy đứng trước đó rất lâu, đôi mắt đỏ không rõ vì gió hay vì khóc."},{"who":"A","text":"Kẻ tố huynh trưởng {xung} trước Đại Lý tự là người được nhà {B} tiến cử. {Xung} cần biết hắn đã được hứa gì."},{"who":"me","text":"Người tố được tiến cử thì phía sau ắt có hứa hẹn. {Goi} nghĩ hắn nhận được gì?"},{"who":"A","text":"Có thể là chức vụ, cũng có thể là bạc. Chỉ cần biết hắn được hứa gì là biết ai chỉ đạo."},{"who":"me","text":"Dò người tố hay dò nhà {B}, mỗi đường một nguy. {Xung} sẽ chọn."}]}},
{"id":"nr:muoi_tuoc_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa buổi chiều, một cuốn sổ chép các lần nhà buôn góp bạc cứu tế được khép lại bằng tay run, bìa vải còn thơm mùi trầm."},{"who":"A","text":"Nhà {xung} có bạc, mà chưa đại thần nào dám ký tên bảo lãnh cho một nhà buôn xin tước. Một lời của Thái hậu là đủ để có người dám đứng ra."},{"who":"me","text":"Một nhà buôn xin tước, người đời chê nhiều hơn khen. {Goi} muốn Thái hậu nhớ đến điều gì của nhà mình?"},{"who":"A","text":"Những mùa cứu tế nhà {xung} đã góp bạc không đòi tên. Thái hậu là người trọng việc thiện, chỉ cần nhắc một câu."},{"who":"me","text":"Lời nhắc ấy nhẹ mà nặng, phải thưa cho khéo. {Xung} phải cân nhắc kỹ xem nên thưa bằng lời hay bằng lễ."}]}},
{"id":"nr:muoi_tuoc_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một lá thư gửi vị Thượng thư đã cáo lão được viết bằng nét chữ ngay ngắn, từng câu đều đắn đo."},{"who":"A","text":"Có một lão Thượng thư cáo lão từng nhận ơn nhà {xung}. Lão chỉ cần một lá thư nhắc là chịu đứng bảo. Thư ấy {xung} không thể tự gửi."},{"who":"me","text":"Một vị quan đã về hưu mà còn nhớ ơn cũ, ấy là phúc cho nhà {goi}. Trong thư {goi} nhắc điều gì?"},{"who":"A","text":"Nhắc ơn xưa và xin một lời bảo lãnh. Không xin gì hơn, chỉ cần lão chịu ký tên."},{"who":"me","text":"Lá thư này phải đến tận cửa lão. {Xung} sẽ lo xem nhờ ai mang."}]}},
{"id":"nr:muoi_tuoc_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ngọn đèn khuya, người ấy kể nhỏ như sợ tường có tai, tay vân vê một mảnh giấy gấp đôi."},{"who":"A","text":"Có người đang ghi sổ từng món lễ nhà {xung} đưa vào cung. Sổ ấy nằm trong tay một thái giám thân với {B}."},{"who":"me","text":"Ghi sổ từng món là để dành làm chứng. {Goi} sợ họ sẽ viết thành lời gì?"},{"who":"A","text":"Sợ họ ghi lễ thành hối lộ. Chỉ cần đổi một chữ là cả nhà {xung} mang tội."},{"who":"me","text":"Muốn biết sổ ghi những gì thì phải đến gần người giữ sổ. {Xung} sẽ chọn đường."}]}},
{"id":"nr:muoi_tuoc_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp lễ phẩm đặt giữa điện còn nguyên dây lụa đỏ, người ấy nhìn hộp mà do dự như nhìn một con dao hai lưỡi."},{"who":"A","text":"Lễ và hối lộ chỉ cách nhau một tờ giấy. Nếu Hoàng hậu nói những món nhà {xung} dâng là lễ đúng phép, không ai dám ghi khác."},{"who":"me","text":"Một lời của Hoàng hậu định rõ ranh giới ấy. {Goi} muốn xin người nói điều gì?"},{"who":"A","text":"Rằng nhà {xung} dâng lễ theo lệ, đúng thời đúng mức. Xin {goi} thưa giúp một lời."},{"who":"me","text":"Thưa với Trung cung phải giữ cho đúng mực, không thể có chút cầu lợi. {Xung} sẽ cân nhắc."}]}},
{"id":"nr:muoi_tuoc_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần đến Trung thu, một chiếc lồng đèn chưa dán giấy nằm trên án, người ấy nhìn vào khung tre mà thở dài."},{"who":"A","text":"{B} đã chuẩn bị một màn ở yến Trung thu để cả cung nhớ {xung} là con nhà buôn muối. {Xung} cần biết trước nàng ta định làm gì."},{"who":"me","text":"Người ta dùng xuất thân để chọc ghẹo trước mặt mọi người là điều khó chịu. {Goi} đoán nàng ta bày gì?"},{"who":"A","text":"Có thể là một bài thơ, một vở trò, hay một câu đố mà đáp án là {xung}. Không biết trước thì khó tránh."},{"who":"me","text":"Biết trước thì có thể đỡ. {Xung} sẽ chọn dò từ ngoài hay hỏi trong."}]}},
{"id":"nr:muoi_tuoc_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, bài thơ nàng viết cho yến Trung thu được chép lại ba lần, mực còn sáng trên mép giấy."},{"who":"A","text":"Có người bày sẵn một màn ở yến Trung thu để chê xuất thân của {xung}. Nếu Hoàng thượng hỏi đến bài thơ của {xung} trước, màn ấy sẽ không diễn được."},{"who":"me","text":"Thơ hay có thể che miệng người nhiều lời. {Goi} có tự tin vào bài ấy không?"},{"who":"A","text":"Tự tin, vì đó là bài {xung} viết bằng cả tâm tư. Chỉ cần Hoàng thượng nghe trước, người khác không dám chê."},{"who":"me","text":"Xin thứ tự dâng thơ là việc tế nhị. Việc ấy, {xung} sẽ tính xem nên nhắc ai."}]}},
{"id":"nr:muoi_tuoc_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản đồ con đê cũ trải trên án, đường nét mực đỏ chạy dọc theo bờ sông vẽ vội bằng tay."},{"who":"A","text":"Phụ thân {xung} muốn bỏ bạc đắp đê ở quê, nhưng bạc phải qua tay quan huyện. {Xung} cần một người ngoài cung để mắt xem bạc có đến chân đê không."},{"who":"me","text":"Bạc qua tay quan huyện thì khó tránh hao hụt. {Goi} sợ nhất điều gì?"},{"who":"A","text":"Sợ bạc bị ăn bớt, đê không xong mà tiếng xấu vẫn về nhà {xung}. Phải có người nhìn tận mắt."},{"who":"me","text":"Một con đê mà đủ bạc đủ công thì mới thành ơn dân. {Xung} sẽ nghĩ nhờ người nào đi xem."}]}},
{"id":"nr:muoi_tuoc_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ báo công trình con đê vừa đến, đất bùn còn dính ở mép giấy, mùi nước sông vẫn chưa tan."},{"who":"A","text":"Con đê nhà {xung} bỏ bạc đắp sắp xong. Nếu Hoàng thượng sai một vị quan đến nghiệm thu, công ấy là công thật."},{"who":"me","text":"Công thật phải có người ngoài chứng nhận. {Goi} muốn Hoàng thượng biết vào lúc nào?"},{"who":"A","text":"Lúc người vui, khi bàn chuyện dân sinh. Xin {goi} thưa chuyện nghiệm thu lúc ấy."},{"who":"me","text":"Một lời nói đúng khắc giờ có sức nặng. {Xung} sẽ liệu cách thưa."}]}},
{"id":"nr:muoi_tuoc_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ của Ngự sử được chép lại và truyền đi khắp các cung, mép giấy đã nhàu vì tay người đọc."},{"who":"A","text":"Ngự sử tố nhà {xung} mua quan bán tước. Xin {goi} thưa với Hoàng thượng rằng bạc nhà {xung} đã đắp đê, chẩn đói, không mua ai cả."},{"who":"me","text":"Lời tố nặng như núi, chỉ có sự thật mới gỡ được. {Goi} có chứng cớ gì không?"},{"who":"A","text":"Có sổ đắp đê, sổ chẩn đói, và người dân chứng kiến. Chỉ cần Hoàng thượng chịu nghe."},{"who":"me","text":"Thưa với Hoàng thượng, hay nhờ người làm chứng, mỗi cách một vẻ. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:muoi_tuoc_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa phùn ngoài hiên, trên bàn là tờ sớ tố nhà buôn muối, mực đen còn bóng dưới ánh nến."},{"who":"A","text":"Ngự sử dâng sớ tố nhà {xung} sau một lần đến phủ nhà {B}. {Xung} muốn biết tờ sớ ấy được viết ở đâu, ai mài mực."},{"who":"me","text":"Một vị Ngự sử đến phủ người khác rồi dâng sớ tố nhà mình, quả không phải tình cờ. {Goi} nghĩ sao?"},{"who":"A","text":"Nghĩ rằng {B} có mặt trong chuyện này, nhưng chưa có chứng cớ. Nếu biết nơi viết sớ, sẽ biết ai đứng sau."},{"who":"me","text":"Dò theo bước chân của Ngự sử hay dò miệng {B}, mỗi đường một nguy. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:muoi_tuoc_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hôm trước triều nghị, hương trầm Đức Thọ cung quyện trên áo người ấy, trên tay là danh sách các quan sẽ bàn việc tước."},{"who":"A","text":"Triều nghị lần cuối về tước của nhà {xung}. Thái hậu có lời thì triều thần sẽ theo. Xin {goi} hầu người hôm trước, nói giúp nhà {xung} một câu."},{"who":"me","text":"Chỉ một lời của Thái hậu mà đổi được cả triều nghị. {Goi} muốn người biết điều gì?"},{"who":"A","text":"Rằng nhà {xung} là nhà buôn lương thiện, đã góp bạc đắp đê chẩn đói, xứng được phong tước."},{"who":"me","text":"Nói thế nào cho vừa lòng Thái hậu, {xung} sẽ cân nhắc kỹ. Một lời nói hay một bức thêu cũng là cách thưa."}]}},
{"id":"nr:muoi_tuoc_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếu phong tước đã được nhà vua nhúng bút mà chưa viết, giấy vàng nằm chờ bên nghiên mực đã mài."},{"who":"A","text":"Chiếu phong tước nằm trên ngự án. Hoàng thượng chỉ còn chờ một lời: nhà buôn muối có xứng không. Xin {goi} nói lời ấy, đừng để {xung} phải tự nói."},{"who":"me","text":"Tự mình nói thì thành tự khen. {Goi} muốn lời ấy nghe ra sao?"},{"who":"A","text":"Nghe như người ngoài đã thấy, chứ không như kẻ trong nhà xin xỏ. Như vậy mới thật."},{"who":"me","text":"Chuyện đã đến nước này, một lời đúng chỗ có thể định cả chiếu. {Xung} sẽ nghĩ cách thưa."}]}},
{"id":"nr:muoi_lau_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa đêm gõ vào mái hiên, trên án là một mảnh sổ hải trình chép vội, nước biển còn thấm vào mép giấy."},{"who":"A","text":"Sổ hải trình thuyền muối nhà {xung} còn nằm ở Diêm vận ty, cuối năm sẽ bị đốt. {Xung} cần người chép được một bản trước kỳ ấy."},{"who":"me","text":"Sổ ấy là chứng cứ duy nhất cho các chuyến muối của nhà {goi}. Có ai trong Diêm vận ty chịu giúp không?"},{"who":"A","text":"Chưa biết. Người giữ sổ là người của Diêm vận sứ, không dễ lung lạc."},{"who":"me","text":"Một cuốn sổ sắp thành tro, phải chép gấp. {Xung} sẽ nghĩ nên nhờ ai."}]}},
{"id":"nr:muoi_lau_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mấy trang sổ thuyền bị xé để lại mép giấy lởm chởm, người ấy lấy ngón tay vuốt đi vuốt lại chỗ rách."},{"who":"A","text":"Có người đã xé mấy trang sổ thuyền nhà {xung}. Kẻ ấy về kinh đã ghé phủ nhà {B}. {Goi} giúp {xung} dò nàng ta biết đến đâu."},{"who":"me","text":"Xé những trang nào, {goi} có biết không?"},{"who":"A","text":"Những trang ghi chuyến muối đi Giang Khẩu. Kẻ xé biết rõ điều cần giấu."},{"who":"me","text":"Dò theo kẻ ấy hay hỏi thẳng {B} chuyện muối Giang Khẩu, đều phải khéo. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:muoi_lau_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa điện, bức thư của Diêm vận sứ gửi cho nhà vợ cũ của mình nằm mở một nửa, người ấy nhìn mà không chạm vào."},{"who":"A","text":"Nhà buôn muối hãm hại nhà {xung} là thông gia của {B}. {Xung} cần biết nàng ta đã hứa gì với Diêm vận sứ."},{"who":"me","text":"Thông gia giúp nhau là lẽ thường, nhưng hãm hại người khác thì khác. {Goi} nghi nàng ta đã nhúng tay?"},{"who":"A","text":"Nghi. Một lời hứa của {B} có thể là lý do Diêm vận sứ liều mình bắt tay với kẻ xấu."},{"who":"me","text":"Dò thư qua lại hay sang tận cung hỏi, mỗi đường một nguy. {Xung} đang cân nhắc."}]}},
{"id":"nr:muoi_lau_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn lệ cung quy treo trên tường Khôn Ninh cung rung nhẹ trong gió, người ấy đứng dưới đó mà thở khẽ."},{"who":"A","text":"Hậu cung có lệ: phi tần không được kéo nhà ngoại vào việc buôn. Có người đã phạm lệ ấy để hãm nhà {xung}. Xin {goi} thưa với Hoàng hậu một câu."},{"who":"me","text":"Lệ cung quy là quyền của Hoàng hậu. {Goi} muốn nhắc người như thế nào?"},{"who":"A","text":"Nhắc rằng lệ cấm ấy còn đó, và có kẻ đã lờ nó đi. Chỉ cần Trung cung để ý thì kẻ ấy sẽ phải dè chừng."},{"who":"me","text":"Nhắc khéo mà không chỉ mặt ai là cách đáng giá nhất. Để {xung} suy xét xem nên thưa thế nào."}]}},
{"id":"nr:muoi_lau_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai tờ diêm dẫn giống hệt nhau đặt song song trên án, chỉ khác nhau một vệt ấn đỏ rất mờ."},{"who":"A","text":"Chính Diêm vận ty đã cấp hai tờ diêm dẫn, tức giấy phép chở muối, cho cùng một chuyến muối. {Xung} giữ được một tờ, cần người đem nó đến tay Tuần diêm Ngự sử."},{"who":"me","text":"Hai tờ giấy cho một chuyến muối, ắt có kẻ gian. Tuần diêm Ngự sử có biết chuyện chưa?"},{"who":"A","text":"Chưa. Vị ấy là quan coi việc muối ngay chính, chỉ cần thấy tờ giấy là hiểu."},{"who":"me","text":"Tờ diêm dẫn ấy phải đến tay vị quan đó mà không bị chặn đường. {Xung} sẽ lo."}]}},
{"id":"nr:muoi_lau_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mấy bao muối nhỏ còn nguyên dấu niêm của Nội vụ phủ, đặt cạnh một sổ giao nhận chữ viết rất cẩu thả."},{"who":"A","text":"Thái giám ở Nội vụ phủ mua muối dư của Diêm vận ty, và hắn là người {B} hay sai. {Goi} giúp {xung} xem muối ấy chạy về đâu."},{"who":"me","text":"Muối dư mà vào cung thì ắt có đường dây. {Goi} nghi ai ở sau?"},{"who":"A","text":"Nghi {B}, nhưng chỉ cần biết muối đi đâu là biết ai hưởng lợi. {Xung} muốn có chứng cớ trước."},{"who":"me","text":"Lần theo đường muối hay hỏi thẳng tên thái giám, đều phải khéo. {Xung} sẽ chọn."}]}},
{"id":"nr:muoi_lau_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùa đông gió buốt, người ấy ôm bọc thuốc thảo dược đã gói sẵn, tay vẫn run lẩy bẩy dù đã mặc áo dày."},{"who":"A","text":"Mùa đông ngục Giang Khẩu ẩm lạnh, chân phụ thân {xung} đã sưng không đi được. {Goi} quen thái y, xin một phương thuốc mà người ngoài cung sắc được."},{"who":"me","text":"Chân sưng vì lạnh ẩm trong ngục, nếu để lâu sẽ thành tàn phế. {Goi} cần thuốc gì?"},{"who":"A","text":"Thuốc tan sưng, giảm đau, giữ được đôi chân. Thái y chỉ cần viết phương, người ngoài sẽ làm."},{"who":"me","text":"Thuốc phải đến tay cha {goi} trước khi chân hỏng hẳn. Để {xung} tìm cách lo thuốc."}]}},
{"id":"nr:muoi_lau_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn, một tờ biên lai thuế muối cũ vàng ố được trải ra, dấu ấn đỏ vẫn còn rõ."},{"who":"A","text":"Cha {xung} bị giam vì tội nợ thuế muối, mà thuế nhà {xung} đã nộp đủ. Biên lai còn giữ ở hiệu buôn. {Xung} cần người mang nó đến quan Giang Khẩu."},{"who":"me","text":"Có biên lai thì án nợ thuế tan ngay. Sao hiệu buôn chưa mang đến?"},{"who":"A","text":"Vì người ở hiệu sợ bị liên lụy, không dám ra mặt. Phải có người từ ngoài mang đi thay."},{"who":"me","text":"Biên lai mà đến tay quan thì cha {goi} được tha. {Xung} sẽ lo cho nó đến đúng nơi."}]}},
{"id":"nr:muoi_lau_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn buông trên Hoán y cục, một cung nữ trẻ đứng thất thần bên chậu giặt, nước vẫn chảy mà tay đã ngừng."},{"who":"A","text":"Lão lái thuyền thấy hết đêm giấu muối, lão đang trốn. Con gái lão là cung nữ ở Hoán y cục, người của Diêm vận sứ đã hỏi đến nàng."},{"who":"me","text":"Cha trốn mà con bị hỏi, thật tội nghiệp. {Goi} muốn che cho nàng thế nào?"},{"who":"A","text":"Cho nàng một chỗ nương, đừng để người của Diêm vận sứ gặp được. Xin {goi} cho nàng nương ít hôm."},{"who":"me","text":"Giữ nàng an toàn cũng là giữ lời khai của cha nàng. {Xung} phải cân nhắc kỹ xem nên đặt nàng ở đâu."}]}},
{"id":"nr:muoi_lau_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới giàn hoa, một bức thư báo tin được người ấy gấp làm tư, mép giấy đã bị xé một góc."},{"who":"A","text":"Người của Diêm vận sứ cũng đang tìm lão lái thuyền, và họ được người trong cung {B} báo tin. {Goi} giúp {xung} xem họ đã biết những gì."},{"who":"me","text":"Tin từ cung ra ngoài mà chính xác như vậy, ắt có người chuyên truyền. {Goi} nghi ai?"},{"who":"A","text":"Một cung nữ hay ra ngoài vào buổi chiều, nhưng {xung} chưa dám chắc."},{"who":"me","text":"Dò đường tin hay dò miệng cung nữ hầu {B}, mỗi đường một nguy. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:muoi_lau_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phiên xử Giang Khẩu sắp mở, một cuốn sổ muối đóng bìa xanh nằm trên án, bìa đã sờn bởi bao lần lật mở."},{"who":"A","text":"Đại Lý tự xử án Giang Khẩu, mà Diêm vận sứ có người ở Hộ bộ đứng sau. {Xung} chỉ xin Hoàng thượng truyền một lời: án muối xử theo sổ, không theo người."},{"who":"me","text":"Lời ấy nghe đơn giản mà động đến cả đường dây đứng sau. {Goi} có sợ gì không?"},{"who":"A","text":"Sợ chứ, nhưng nếu không nói, sổ sách sẽ thành giấy lộn. {Xung} chỉ xin một câu."},{"who":"me","text":"Một câu của Hoàng thượng đủ khiến cả Đại Lý tự phải theo sổ. {Xung} sẽ liệu cách thưa."}]}},
{"id":"nr:muoi_lau_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ba chiếc hộp gỗ nhỏ, mỗi chiếc giữ một phần chứng cứ, được xếp thành hàng trên bàn, chỉ thiếu một người đem chúng về một chỗ."},{"who":"A","text":"Chứng cứ nhà {xung} gom được còn nằm rải ở ba nơi. Trước phiên xử, chúng phải về chung một chỗ: tay người coi án."},{"who":"me","text":"Ba nơi, ba người giữ, mà thời gian còn rất ít. {Goi} tin được mấy người trong đó?"},{"who":"A","text":"Cả ba đều nhận lời, nhưng không ai chịu đi chung với ai. Phải có người đi thay mỗi nơi."},{"who":"me","text":"Gom chứng cứ về một mối là việc cần nhanh và kín. Việc ấy, {xung} sẽ tính xem nên giao ai."}]}},
{"id":"nr:muoi_doi_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió nam thổi qua hiên, trên án là sổ ruộng mới mua, những dòng chữ ghi giá rẻ đến mức khiến lòng người chùng xuống."},{"who":"A","text":"Phụ thân {xung} đang gom ruộng rẻ của dân đói. Lãi lớn, mà triều đình sớm muộn sẽ hỏi. {Xung} cần một lá thư khuyên cha dừng tay."},{"who":"me","text":"Cha {goi} nhìn thấy lãi mà quên tiếng oán. {Goi} định khuyên ông bằng lẽ nào?"},{"who":"A","text":"Bằng lẽ năm đói mà lấy ruộng của dân thì dù lời đến đâu cũng mất lòng người. Cha nghe con gái thì có thể dừng."},{"who":"me","text":"Lá thư ấy phải đến tay cha {goi} thật nhanh, trước khi thêm một mẫu ruộng bị mua. {Xung} sẽ lo."}]}},
{"id":"nr:muoi_doi_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một tờ chiếu cấm mua ruộng đã được phác thảo bằng nét chữ nhỏ, chỉ còn thiếu dấu ngự ấn."},{"who":"A","text":"Nếu Hoàng thượng ra lệnh cấm mua ruộng dân trong năm đói, phụ thân {xung} buộc phải dừng mà không ai trách ông. Xin {goi} thưa với Hoàng thượng."},{"who":"me","text":"Lệnh cấm vừa giúp dân vừa cứu cha {goi} khỏi tiếng xấu. {Goi} nghĩ Hoàng thượng có chịu ban không?"},{"who":"A","text":"Chịu, nếu có người nhắc đúng lúc. Năm đói mà dân mất ruộng thì loạn là chuyện sớm muộn."},{"who":"me","text":"Một đạo lệnh đổi cả vận một nhà. {Xung} sẽ nghĩ nên thưa thế nào."}]}},
{"id":"nr:muoi_doi_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cửa thành tiếng dân đói ồn ào vọng vào, người ấy đứng ở cửa sổ lầu nhìn xuống mà mắt đỏ hoe."},{"who":"A","text":"Dân đói kéo lên kinh, triều cần người để đổ lỗi, và nhà {xung} là cái tên dễ gọi nhất. Xin {goi} nhắc Hoàng thượng rằng nhà {xung} đã mở kho phát cháo."},{"who":"me","text":"Làm việc thiện mà vẫn bị đổ lỗi, thật bất công. {Goi} muốn Hoàng thượng biết điều gì cụ thể?"},{"who":"A","text":"Rằng nồi cháo nhà {xung} nấu đã nuôi mấy ngàn người, không có nhà buôn nào làm được như vậy."},{"who":"me","text":"Muốn Hoàng thượng nhớ đến thì có thể thưa hoặc góp thêm nồi cháo. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:muoi_doi_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên, một cung nữ Giang Nam quỳ gối ướt đẫm vì mưa, trước mặt là sàn đá lạnh, khăn trên tay đã nhăn nhúm."},{"who":"A","text":"Một cung nữ của {xung} quê Giang Nam có cha mẹ trong đám dân đói ngoài cửa thành. Nàng ấy xin ra gặp, bị phạt quỳ. Xin {goi} che chở nàng ấy ít hôm."},{"who":"me","text":"Phạt quỳ vì xin gặp cha mẹ trong cơn đói, thật khắc nghiệt. {Goi} muốn nàng ấy ở đâu?"},{"who":"A","text":"Đâu cũng được, miễn đừng bị phạt thêm. Nàng ấy sợ lắm, ngày nào cũng khóc."},{"who":"me","text":"Cho nàng ấy một chỗ nương, hoặc lo chỗ cho cha mẹ nàng, đều là việc thiện. {Xung} sẽ nghĩ."}]}},
{"id":"nr:muoi_doi_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn khuya, một bản ghi lời đồn về kho thóc ở bến Giang Khẩu được truyền tay nhau, nét chữ không giống nhau."},{"who":"A","text":"Cả kinh đồn nhà {xung} giấu kho thóc ở bến Giang Khẩu, và {B} là người kể chuyện ấy hay nhất. {Goi} giúp {xung} xem nàng ta nghe từ đâu."},{"who":"me","text":"Kể hay như thế thì chắc chắn có nguồn. {Goi} đã nghe nàng ta kể lần nào chưa?"},{"who":"A","text":"Nghe một lần. Nàng ta kể rất rõ số bao, số thuyền, như đã tận mắt thấy."},{"who":"me","text":"Muốn tìm nguồn thì lần ngược từ người kể đầu, hoặc ngồi nghe nàng kể để bắt lỗi. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:muoi_doi_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi thỉnh an vừa tan, chiếc khăn lụa của người ấy còn ướt mồ hôi vì những lời xì xào quanh mình."},{"who":"A","text":"Lời đồn tích trữ đã thành chuyện bàn ở buổi thỉnh an. Hoàng hậu chỉ cần cấm bàn chuyện ngoài cung là đủ. Một lời của {goi} ở Trung cung sẽ dập được nó."},{"who":"me","text":"Một lời cấm từ Trung cung sẽ làm im cả buổi thỉnh an. {Goi} muốn Hoàng hậu nói thế nào?"},{"who":"A","text":"Rằng chuyện ngoài cung không nên bàn ở trong cung. Không cần nhắc đến nhà {xung}."},{"who":"me","text":"Dập lời đồn mà không làm nó rộ thêm là việc khó. Để {xung} suy xét xem nên thưa thế nào."}]}},
{"id":"nr:muoi_doi_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên bàn sổ chẩn, người ấy giữ một tờ ghi phần thóc nhà mình góp, góc giấy bị lệch như sắp bị bỏ quên."},{"who":"A","text":"Gạo chẩn phát ra mang tên ai, Hoàng thượng chưa định. {Xung} không xin tên nhà {xung}, chỉ xin đừng để phần góp của nhà {xung} bị ghi là của kẻ khác."},{"who":"me","text":"Phần góp bị ghi nhầm tên thì công thành của người. {Goi} sợ ai sẽ nhận công?"},{"who":"A","text":"Sợ những nhà chỉ góp ít mà đứng tên to. Công của nhà {xung} sẽ bị chìm."},{"who":"me","text":"Xin ghi cho đúng là xin điều chính đáng. {Xung} sẽ nghĩ xem thưa thế nào."}]}},
{"id":"nr:muoi_doi_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi trầm Đức Thọ cung phảng phất trên tay áo, người ấy cầm một cuốn sổ thóc góp mỏng, mép giấy hơi quăn."},{"who":"A","text":"Thái hậu muốn gạo chẩn mang tên người. Nhà {xung} góp thóc, chỉ xin được đứng sau tên Thái hậu mà đi phát. {Goi} hầu người, xin thưa giúp."},{"who":"me","text":"Đứng sau tên Thái hậu là cách giữ nhà mình khỏi tiếng thị phi. {Goi} nghĩ Thái hậu có nhận không?"},{"who":"A","text":"Nhận, vì người trọng người biết khiêm nhường. Chỉ cần có người thưa giúp."},{"who":"me","text":"Thưa với Thái hậu, hay dâng một cuốn sổ thóc, đều chứa lòng thành. {Xung} sẽ chọn."}]}},
{"id":"nr:muoi_doi_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một cuốn sổ nhập thóc chẩn của huyện được mở ra, con số ghi nhập còn lớn gấp đôi số thật phát đi."},{"who":"A","text":"Thóc chẩn về đến huyện vơi một nửa. Tri huyện ăn bớt là người nhà ngoại của {B}. {Goi} giúp {xung} dò xem nàng ta có biết không."},{"who":"me","text":"Ăn bớt thóc chẩn là tội nặng, người nhà ngoại của {B} mà dám làm thì {B} khó nói không biết. {Goi} nghĩ sao?"},{"who":"A","text":"Nghĩ rằng nàng ta biết, chỉ là chưa có chứng cớ. Một lời lỡ miệng của nàng là đủ."},{"who":"me","text":"Dò thư từ giữa {B} và huyện ấy, hay tự nghe nàng nói chuyện, đều cần khéo. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:muoi_doi_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai cuốn sổ phát thóc đặt cạnh nhau trên án, một cuốn gáy mới, một cuốn cũ nát và có vết cháy."},{"who":"A","text":"Sổ phát thóc ở huyện có hai bản, bản thật nằm trong tay một thư lại già. {Xung} cần người đến lấy trước khi bản ấy cháy."},{"who":"me","text":"Bản thật mà cháy thì không còn gì chứng minh. {Goi} biết thư lại già ấy ở đâu không?"},{"who":"A","text":"Biết, ở cuối huyện. Lão là người ngay thẳng, nhưng lão đang sợ bị diệt khẩu."},{"who":"me","text":"Cuốn sổ ấy phải rời khỏi tay lão trước khi quá muộn. {Xung} phải cân nhắc kỹ xem nên nhờ ai đi lấy."}]}},
{"id":"nr:muoi_doi_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trời hạn đầu mùa, nền sân điện nứt từng đường nhỏ, người ấy nhìn đất khô mà lòng nóng như lửa."},{"who":"A","text":"Năm nay trời lại hạn đầu mùa. Nhà {xung} muốn mở kho sớm, nhưng sợ bị nói là mua lòng dân. Nếu Hoàng thượng cho phép trước, không ai nói được."},{"who":"me","text":"Mở kho sớm là cứu được nhiều người, nhưng mang tiếng mua lòng. {Goi} muốn xin điều gì?"},{"who":"A","text":"Một chỉ cho phép, để việc mở kho là theo lệnh. Xin {goi} thưa trước khi kho nhà khác mở."},{"who":"me","text":"Một lời xin cấp chỉ trước người khác phải nhanh và khéo. Việc ấy, {xung} sẽ tính xem nên thưa thế nào."}]}},
{"id":"nr:muoi_doi_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, bức thư gửi phụ thân mới viết dở, mực loang ở câu hỏi vì sao cha còn đợi."},{"who":"A","text":"Phụ thân {xung} còn đợi giá lên. {Xung} phải viết cho cha: mở kho ngay, kẻo cả Giang Nam nhớ nhà {xung} bằng oán."},{"who":"me","text":"Cha {goi} vì lợi mà quên oán dân. {Goi} định nói gì để ông nghe?"},{"who":"A","text":"Rằng bạc có thể kiếm lại, nhưng lòng dân mất thì không lấy lại được. Chỉ lời con mới làm cha lay."},{"who":"me","text":"Thư này phải đến tay cha thật nhanh. {Xung} sẽ lo cách gửi."}]}},
{"id":"nr:muoi_no_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một tờ giấy nợ trống chỗ điểm chỉ được trải ra, vết mực đỏ đã khô lại thành một vệt xám nhạt."},{"who":"A","text":"Bản sao giấy nợ có điểm chỉ của {B} đã biến mất cùng lão quản sổ. Ai cầm nó là cầm cả nàng ta lẫn {xung}. {Goi} giúp {xung} xem nàng ta đã tìm được lão chưa."},{"who":"me","text":"Một tờ giấy nợ lạc vào tay người khác thì ai cũng bị tổn. {Goi} có biết lão quản sổ đi đâu không?"},{"who":"A","text":"Không. Lão biến mất từ đêm hôm kia, chỉ để lại cái bàn trống và ngọn đèn chưa tắt."},{"who":"me","text":"Muốn biết {B} đã tìm tới đâu thì phải theo dấu người của nàng, hoặc hỏi khéo chính nàng. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:muoi_no_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài hiên trời nhá nhem, trên án là danh sách người từng giữ sổ cho nhà buôn muối, một cái tên bị gạch bằng mực đỏ."},{"who":"A","text":"Lão quản sổ bị phụ thân {xung} đuổi, nay ở trọ ngoài kinh. {Xung} muốn mua lại bản sao trước người khác. Lời hẹn phải đến được tay lão."},{"who":"me","text":"Người bị đuổi thì lòng đầy oán, khó mà tin lời hẹn. {Goi} định hứa gì với lão?"},{"who":"A","text":"Một khoản bạc đủ để lão sống yên và một lời xin lỗi thay cha. Lão là người biết điều, chỉ cần có người nói đúng chỗ."},{"who":"me","text":"Lời hẹn ấy phải đến lão trước người khác. {Xung} sẽ nghĩ nhờ ai đưa đi."}]}},
{"id":"nr:muoi_no_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một cuốn sổ thu chi của hiệu buôn nằm mở bên cạnh bàn tính gẩy dở, mấy hạt tính lệch ra khỏi hàng."},{"who":"A","text":"Hiệu buôn nhà {xung} cần bạc, còn {B} vẫn thiếu một khoản lãi. Trước khi đòi, {xung} cần biết nàng ta còn trả được hay đã cạn."},{"who":"me","text":"Đòi nợ người đã cạn thì chỉ thêm oán mà không thêm bạc. {Goi} nghĩ nàng ta còn bao nhiêu?"},{"who":"A","text":"Không rõ. Cung nàng ta vẫn ăn mặc rất sang, nhưng {xung} nghe nói đồ trang sức đã bán dần."},{"who":"me","text":"Dò của cải trong cung hay hỏi khéo chuyện chi tiêu, mỗi cách một vẻ. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:muoi_no_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khói trầm trong điện cuộn lên một sợi mảnh, người ấy ngồi ngay ngắn mà bàn tay giữ khăn đã siết đến trắng bệch."},{"who":"A","text":"Phi tần vay nợ là phạm lệ. Nếu chuyện khoản lãi còn thiếu đến Trung cung trước khi {xung} quyết, cả hai bên đều mất mặt."},{"who":"me","text":"Chuyện mà đến tai Hoàng hậu trước thì không còn đường lui. {Goi} muốn biết điều gì?"},{"who":"A","text":"Xem Hoàng hậu đã nghe tin chưa, và nghe từ ai. {Goi} hầu Trung cung, xin dò giúp {xung}."},{"who":"me","text":"Dò ý Hoàng hậu là việc tế nhị. {Xung} sẽ nghĩ nên hỏi người hay hỏi ma ma thân cận."}]}},
{"id":"nr:muoi_no_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới giàn hoa, bức thư vô danh nhắc chuyện cũ được người ấy cầm bằng hai ngón tay, như cầm một thứ bẩn."},{"who":"A","text":"Có một người thứ ba biết chuyện {B} từng vay nợ nhà {xung}. Người ấy không cần bạc, chỉ muốn nắm thóp để kéo cả hai nhà cùng ngã."},{"who":"me","text":"Người không cần bạc thì thứ họ cần còn đáng sợ hơn. {Goi} đoán là ai?"},{"who":"A","text":"Không đoán nổi. Chỉ biết người đó hay hỏi những chuyện mà ít ai biết. {Goi} giúp {xung} tìm ra."},{"who":"me","text":"Nhờ người dò hay tự mình để ý buổi thỉnh an, mỗi đường một nguy. {Xung} sẽ chọn."}]}},
{"id":"nr:muoi_no_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn xuống chậm, ngoài cửa điện có một cung nữ đứng im, ngón tay vặn chặt vạt áo đã nhăn nhúm."},{"who":"A","text":"Cung nữ từng mang giấy nợ qua lại cho {xung} đang bị một người thứ ba ép khai. Xin {goi} giữ nàng ấy ở chỗ người thứ ba không với tới."},{"who":"me","text":"Nàng ấy biết nhiều chuyện, bị ép khai cũng dễ. {Goi} muốn nàng ấy ở đâu?"},{"who":"A","text":"Ở đâu cũng được, miễn là không ai tìm thấy. Nàng ấy chỉ cần vài ngày để yên."},{"who":"me","text":"Cho nàng ấy một chỗ nương, hay gửi nàng về quê cho kín, đều là cách giữ. {Xung} sẽ nghĩ."}]}},
{"id":"nr:muoi_no_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên có một tiểu thái giám vừa qua rồi mất dạng, để lại mùi dầu thơm và một tờ biên nhận bỏ quên."},{"who":"A","text":"{B} lén vay một thái giám cho vay nặng lãi ở Nội vụ phủ. Chỉ {xung} biết. {Xung} cần biết nàng ta đã cầm cố những gì."},{"who":"me","text":"Vay nặng lãi mà phải cầm cố thì sớm muộn cũng lộ. {Goi} nghĩ nàng ta cầm những món gì?"},{"who":"A","text":"Hẳn là những thứ quý, vì thái giám ấy không nhận đồ rẻ. Biết được món cầm là biết nàng đã cạn đến đâu."},{"who":"me","text":"Dò sổ cầm đồ hay hỏi thẳng tên thái giám, đều cần khéo. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:muoi_no_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa điện, một xấp biên nhận vay mượn của nhiều cung được xếp lại với nhau, dấu tay đỏ chi chít khắp trang."},{"who":"A","text":"Thái giám cho vay nặng lãi ở Nội vụ phủ đang bóp cổ nhiều cung. Nếu Trung cung tra hắn, những món nợ ấy tự tan mà không ai phải mất mặt."},{"who":"me","text":"Tra một người mà cứu được nhiều cung, nghe thật hợp lý. Sao {goi} không tự thưa?"},{"who":"A","text":"Chuyện này {goi} nói thì nhẹ, {xung} nói thì nặng. Nói ra từ miệng chủ nợ thì thành tư lợi."},{"who":"me","text":"Một lời thưa khéo hay một cuốn sổ kèm theo, đều là cách. Để {xung} suy xét xem nên giúp thế nào."}]}},
{"id":"nr:muoi_no_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ vay mượn trong cung được Hoàng hậu cho tra, hai cái tên đứng cạnh nhau bằng nét chữ như nhau."},{"who":"A","text":"Hoàng hậu cho tra việc vay mượn trong cung. Tên nhà {xung} nằm cạnh tên {B} trong sổ, mà nhà {xung} là bên cho vay, không phải kẻ đi vay."},{"who":"me","text":"Hai cái tên đứng cạnh nhau dễ bị đọc nhầm. {Goi} muốn Hoàng hậu hiểu thế nào?"},{"who":"A","text":"Rằng nhà {xung} chỉ cho vay theo lệ, có giấy tờ rõ ràng. Xin {goi} thưa rõ với Hoàng hậu."},{"who":"me","text":"Thưa cho rõ ràng mà không gây thêm hiểu lầm là việc khó. {Xung} sẽ nghĩ cách."}]}},
{"id":"nr:muoi_no_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió đêm lùa qua rèm, cuốn một mảnh giấy ghi chuyện vay nợ bay ra khỏi tay người ấy rồi mới vội vàng nhặt lại."},{"who":"A","text":"Chuyện vay nợ trong hậu cung sắp đến tai Hoàng thượng. {Xung} chỉ xin Hoàng thượng nghe từ miệng người ngay trước khi nghe từ kẻ gièm. Xin {goi} thưa trước một lời."},{"who":"me","text":"Nghe từ kẻ gièm trước thì khó nghe lẽ phải sau. {Goi} muốn nói gì trước?"},{"who":"A","text":"Rằng nhà {xung} chỉ cho vay theo lệ, và đã có sổ rõ ràng. Chỉ cần Hoàng thượng biết trước điều đó."},{"who":"me","text":"Thưa trước một lời đúng chỗ sẽ khác nhiều. {Xung} phải cân nhắc kỹ xem nên mở lời thế nào."}]}},
{"id":"nr:muoi_no_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin về chuyện nợ đã lan khắp các cung, một bản chép sổ nhà buôn muối nằm mở trên án, góc giấy lật lên."},{"who":"A","text":"Chuyện nợ đã đến tai Hoàng thượng. {Xung} sợ Hoàng thượng lấy cớ ấy mà siết cả các nhà buôn muối."},{"who":"me","text":"Một việc nợ riêng mà thành cớ siết cả nghề, thật đáng sợ. {Goi} muốn Hoàng thượng hiểu điều gì?"},{"who":"A","text":"Rằng nhà {xung} chỉ đòi đúng phần, không ép ai đến đường cùng. Nhà buôn muối còn nhiều người lương thiện."},{"who":"me","text":"Nói thế nào cho Hoàng thượng thấy cái lý mà không thấy cái cớ. Để {xung} suy xét xem nên thưa hay nhờ người."}]}},
{"id":"nr:muoi_no_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương nhang Đức Thọ cung thoảng nhẹ trong điện, người ấy cầm một chuỗi tràng hạt, hạt nào cũng bị vuốt đến bóng."},{"who":"A","text":"Thái hậu nhân từ với người biết lỗi. Nếu {B} được dẫn đến Đức Thọ cung nhận tội trước, Hoàng thượng sẽ nương tay. {Goi} hầu Thái hậu, xin mở lời."},{"who":"me","text":"Nhờ Thái hậu cho {B} một đường lui là việc nhân từ, mà cũng là việc khó. {Goi} nghĩ nàng ta chịu nhận tội không?"},{"who":"A","text":"Nếu biết đường ấy còn mở, nàng sẽ chịu. Chỉ sợ nàng không biết, hoặc không dám tin."},{"who":"me","text":"Mở lời với Thái hậu thay cho kẻ có tội cần thành tâm. Việc ấy, {xung} sẽ tính xem nên thưa thế nào."}]}},
{"id":"nr:cn_chu_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi thỉnh an vừa tan, người ấy đứng lại sau cùng, chén trà trong tay còn nguyên vì không uống nổi."},{"who":"A","text":"Có người không để cả cung quên {xung} từng quỳ rót trà cho chủ cũ. Buổi thỉnh an nào cũng có người đem chuyện ấy ra châm chọc."},{"who":"me","text":"Bị nhắc mãi chuyện xuất thân giữa đông người, {goi} chắc khó chịu lắm. Việc ấy đã bao lâu rồi?"},{"who":"A","text":"Từ ngày {xung} được thăng. Mỗi lần một câu, câu nào cũng nhẹ như đùa mà nặng như dao."},{"who":"me","text":"Xin Hoàng hậu dẹp là việc đáng làm, chỉ là phải khéo. {Xung} sẽ nghĩ nên thưa hay nên dâng lễ."}]}},
{"id":"nr:cn_chu_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới giàn hoa, chiếc chén trà nhỏ bằng sứ trắng đặt trên bàn, người ấy nhìn nó mà ánh mắt xa xăm."},{"who":"A","text":"Mỗi lần {B} nhắc chuyện chén trà năm xưa, đều có một người nhắc trước nàng ta. {Goi} giúp {xung} xem là ai."},{"who":"me","text":"Người nhắc trước ắt là kẻ xúi giục phía sau. {Goi} nghĩ là ai?"},{"who":"A","text":"Không rõ. Chỉ biết người ấy luôn ngồi ở góc xa, không bao giờ lên tiếng, mà ai cũng nghe theo."},{"who":"me","text":"Muốn tìm ra kẻ xúi thì phải để ý nàng ấy nói chuyện với ai. Để {xung} tìm cách."}]}},
{"id":"nr:cn_chu_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, một cung nữ áo xám đứng đợi trong im lặng, tay giữ chặt tay nải nhỏ như thể sắp phải đi xa."},{"who":"A","text":"Ba người từng cùng {xung} hầu chủ cũ vẫn còn trong cung. Một người xin {xung} che chở, mà cung {xung} đã bị để mắt."},{"who":"me","text":"Nàng ấy xin che chở là vì sợ điều gì?"},{"who":"A","text":"Sợ bị Nội vụ phủ xếp lại người hầu, đẩy sang nơi nguy hiểm. Xin {goi} cho nàng nương ít hôm."},{"who":"me","text":"Cho nàng nương nhờ cũng là mang thêm nguy. {Xung} sẽ cân nhắc nên đón nàng hay lo chỗ khác."}]}},
{"id":"nr:cn_chu_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, ba cái tên được viết lên giấy, bên cạnh mỗi tên là một dấu chấm hỏi nhỏ."},{"who":"A","text":"Trong ba người cũ, một người đã thành tai mắt của {B}. {Xung} không phân được ai. {Goi} giúp {xung} tìm ra kẻ hai lòng ấy."},{"who":"me","text":"Ba người cùng hầu một chủ, cùng chịu một cảnh. Sao {goi} lại nghi một người đổi lòng?"},{"who":"A","text":"Vì có tin của {xung} đã lọt sang cung {B}, mà chỉ ba người ấy biết."},{"who":"me","text":"Muốn tìm ra thì phải theo dõi bước đi của họ, hoặc nói chuyện với từng người. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:cn_chu_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén lễ chúc thọ bằng ngọc đặt trên khay vàng, rượu trong chén phản chiếu ánh đèn lấp lánh, nhưng người ấy không dám nhìn lâu."},{"who":"A","text":"Ở yến mừng thọ, {xung} dâng chén lễ chúc, mà có người thấy kẻ lo trà rượu dặn riêng Ngự thiện phòng. {Xung} cần một thái y kín miệng nghiệm chén rượu trước."},{"who":"me","text":"Dặn riêng Ngự thiện phòng trước yến thọ thì không phải việc nhỏ. {Goi} sợ điều gì nhất?"},{"who":"A","text":"Sợ chén rượu có độc, hoặc có thứ gì làm {xung} thất thố trước mặt mọi người."},{"who":"me","text":"Nghiệm rượu trước khi dâng là cẩn thận đúng lúc. Để {xung} suy xét xem nên nhờ thái y hay tự lo thuốc giải."}]}},
{"id":"nr:cn_chu_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hôm trước yến thọ, thực đơn Ngự thiện phòng chép trên giấy hồng nằm trên án, một món bị khoanh tròn bằng bút đỏ."},{"who":"A","text":"Hôm trước yến mừng thọ, {B} dặn riêng Ngự thiện phòng một việc. {Xung} cần biết đó là việc gì."},{"who":"me","text":"Dặn riêng thì ắt không muốn ai biết. {Goi} nghi nàng ta dặn điều gì?"},{"who":"A","text":"Có thể là đổi món, có thể là thêm thứ gì vào chén của {xung}. {Xung} không dám đoán, chỉ biết phải biết trước."},{"who":"me","text":"Hỏi đầu bếp Ngự thiện phòng hay tự ghé mượn cớ, đều cần khéo. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:cn_chu_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ chiếu thăng phẩm nằm trên ngự án chưa đóng dấu, giấy vàng bóng lên dưới ánh nến, người ấy nhìn mà thấy lạnh người."},{"who":"A","text":"Hoàng thượng hỏi phẩm của {xung} đã nên ngang chủ cũ chưa. Ngồi ngang chủ cũ là vinh, mà cũng thành cái đích cho người ta nhắm vào."},{"who":"me","text":"Được thăng mà phải sợ là điều nghịch lý. {Goi} muốn Hoàng thượng hiểu điều gì?"},{"who":"A","text":"Rằng {xung} xin đợi thêm một mùa, để vững chân rồi mới ngồi cao. Xin {goi} thưa với Hoàng thượng."},{"who":"me","text":"Xin hoãn việc thăng phẩm mà không phụ ơn Hoàng thượng là việc khó. {Xung} sẽ liệu cách thưa."}]}},
{"id":"nr:cn_chu_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản sơ đồ chỗ ngồi buổi thỉnh an được vẽ lại, hai cái tên đứng cạnh nhau bị gạch rồi chép lại ở hai đầu."},{"who":"A","text":"Nếu {xung} ngồi ngang {B}, Hoàng hậu phải xếp lại chỗ ngồi thỉnh an. Chỉ cần người xếp {xung} ngồi xa nàng ta một chút, sẽ bớt được một phen sóng gió."},{"who":"me","text":"Ngồi cạnh người từng là chủ thì {goi} khó thở. Nàng ta có nói gì với {goi} không?"},{"who":"A","text":"Không nói, nhưng mỗi lần ngồi gần, cả buổi thỉnh an đều lặng như tờ. Lời này chỉ {goi} nói được."},{"who":"me","text":"Một lời xin chỗ ngồi mà đổi được bầu không khí cả buổi. {Xung} phải cân nhắc kỹ xem nên thưa thế nào."}]}},
{"id":"nr:cn_chu_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, một bà cung nữ già tóc bạc ngồi bên tay nải cũ, mắt nhìn ra bậc thềm mà không đợi ai."},{"who":"A","text":"Bà cung nữ già từng dạy {xung} việc hầu hạ năm xưa nay bị Nội vụ phủ khất gạo, không ai đoái hoài. {Xung} không tiện ra mặt."},{"who":"me","text":"Người dạy mình từ thuở đầu mà phải chịu cảnh ấy, {goi} chắc xót lắm. Bà còn đủ sức làm việc không?"},{"who":"A","text":"Còn một chút, nhưng đã già lắm rồi. Chỉ cần có miếng cơm, bà không đòi hỏi gì."},{"who":"me","text":"Đón bà về nuôi hay gửi gạo sang, đều là cách báo ơn. {Xung} sẽ nghĩ cách nào hợp hơn."}]}},
{"id":"nr:cn_chu_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ sách cung {B} nằm mở trên bàn Nội vụ phủ, mấy dòng bị khoanh bằng mực đỏ, ghi đầy lỗi sai."},{"who":"A","text":"Nội vụ phủ bắt lỗi sổ sách cung {B}. Cả cung chờ xem {xung} trả thù, mà {xung} không muốn. Xin {goi} thưa với Hoàng hậu cho nàng ta một kỳ hạn sửa sổ."},{"who":"me","text":"Người từng ức hiếp mình mà {goi} vẫn muốn giúp, thật hiếm có. Vì sao {goi} làm vậy?"},{"who":"A","text":"Vì trả thù lúc này là thua. Cả cung đang nhìn, {xung} phải cho họ thấy mình không nhỏ nhen."},{"who":"me","text":"Xin kỳ hạn cho người từng là địch là việc cần cẩn thận. Để {xung} tìm cách thưa."}]}},
{"id":"nr:cn_chu_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thiệp hẹn của {B} viết nét chữ nhã nhặn, nhưng mực như còn vương mùi trà nguội năm xưa."},{"who":"A","text":"{B} hẹn {xung} một đêm đến gian trà nhỏ sau cung nàng ta, nơi {xung} từng quỳ suốt đêm. {Xung} cần biết đêm ấy chỉ có hai người thật, hay có kẻ nấp sau bình phong."},{"who":"me","text":"Hẹn đúng chỗ cũ thì là mời hay là thách? {Goi} đoán nàng ta muốn gì?"},{"who":"A","text":"Có thể muốn nói lời hòa giải, cũng có thể muốn dựng một cái bẫy. {Xung} không dám đi nếu chưa rõ."},{"who":"me","text":"Canh quanh gian trà hay hỏi người hầu trà, mỗi đường một nguy. {Xung} sẽ chọn."}]}},
{"id":"nr:cn_chu_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần đêm hẹn, một cung nữ thân tín đứng ngoài cửa điện, hai bàn tay đan chặt vào nhau, mắt không rời cánh cửa."},{"who":"A","text":"Đêm hẹn ở gian trà nhỏ năm xưa, cung nữ thân tín của {xung} không được theo. Nàng ấy sợ có chuyện. Xin {goi} cho nàng ấy chờ ở cung {goi} đêm ấy."},{"who":"me","text":"Có người chờ sẵn thì có gì còn kịp chạy đi báo. {Goi} lo nhất điều gì?"},{"who":"A","text":"Lo đêm ấy {xung} đi mà không ai biết đã xảy ra chuyện gì, đến sáng mới hay thì muộn."},{"who":"me","text":"Cho nàng ấy chờ ở cung mình, hay nhờ người gác cổng để nàng chờ gần đó, đều được. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_tinh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn khuya, một phong thư cũ ngả vàng được lật từ đáy hộp ra, nét bút thời thiếu nữ còn run run."},{"who":"A","text":"Những bức thư năm xưa của {xung} còn trôi nổi, và người của {B} cũng đang tìm. {Goi} giúp {xung} xem họ đã tìm đến đâu."},{"who":"me","text":"Thư tình cũ lọt ra ngoài thì nặng nhẹ khó lường. Trong thư ấy có điều gì {goi} sợ nhất?"},{"who":"A","text":"Có tên một người, và những lời không nên viết ra. Một khi người khác đọc, {xung} khó giữ được mình."},{"who":"me","text":"Muốn biết họ tìm tới đâu thì phải theo dấu hoặc hỏi dò. {Xung} sẽ chọn đường kín hơn."}]}},
{"id":"nr:cn_tinh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa nhẹ ngoài hiên, trên án là tờ giấy ghi địa chỉ một nhà đồng hương, nét mực còn mới."},{"who":"A","text":"Một bức thư cũ của {xung} nằm ở nhà một người đồng hương ngoài cung. {Xung} cần lấy lại trước khi có người khác đến."},{"who":"me","text":"Người đồng hương ấy có biết trong thư viết gì không?"},{"who":"A","text":"Có lẽ không, bà ấy chỉ giữ hộ. Nhưng nếu có người khác đến hỏi, bà ấy sẽ đưa ngay."},{"who":"me","text":"Phải lấy thư về trước người khác một bước. {Xung} sẽ nghĩ nhờ ai đến lấy."}]}},
{"id":"nr:cn_tinh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, một tiểu thái giám vừa qua rồi đi mất, để lại nơi bậc cửa một mảnh giấy ghi giá, hàng chữ viết nguệch ngoạc."},{"who":"A","text":"Thái giám của {B} đã ra giá cho bức thư của {xung}, ai trả cao thì bán. {Xung} cần biết nàng ta muốn đổi lấy gì thật."},{"who":"me","text":"Ra giá công khai thế này thì không chỉ là chuyện bạc. {Goi} đoán nàng ta muốn điều gì?"},{"who":"A","text":"Có thể muốn {xung} im lặng một việc, có thể muốn {xung} rời khỏi một chỗ. Không biết thì không dám trả giá."},{"who":"me","text":"Dò ý thái giám hay nói bóng gió với chính nàng, mỗi đường một nguy. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:cn_tinh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gần canh hai, một cung nữ co ro ngoài bậc thềm, vạt áo ướt vì sương, tay nắm chặt một chiếc khăn cũ."},{"who":"A","text":"Cung nữ từng chuyển thư cho {xung} năm xưa đang bị người ta gọi đến hỏi. Xin {goi} cho nàng ấy nương ít hôm, đừng để nàng ấy bị ép khai."},{"who":"me","text":"Nàng ấy biết rõ từng bức thư đi đâu về đâu. {Goi} sợ nàng khai ra điều gì?"},{"who":"A","text":"Sợ nàng nói hết, vì nàng yếu lòng, không chịu nổi hỏi dồn."},{"who":"me","text":"Gọi nàng sang cung mình hay đưa nàng ra ngoài ít ngày, đều là cách giữ miệng. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_tinh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa án, tờ lệnh điều thị vệ ra biên ải đã đóng ấn đỏ, từng chữ đều đúng phép, chỉ có một nếp gấp rất khẽ ở góc."},{"who":"A","text":"Lệnh điều người thị vệ ấy ra biên ải là đúng phép, mà có người đã nói một lời. {Xung} nghe nói là người nhà {B}. {Goi} giúp {xung} tìm cho ra."},{"who":"me","text":"Một lệnh đúng phép mà có người đứng sau thì khó thấy dấu vết. {Goi} nghe ai nói vậy?"},{"who":"A","text":"Một thái giám quen. Hắn chỉ nói thoáng qua, nhưng tên {B} thì hắn nhắc rất rõ."},{"who":"me","text":"Dò chuyện ở Binh bộ hay hỏi thẳng {B} xem nàng có biết lệnh điều không, mỗi đường một nguy. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:cn_tinh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày lên đường, một lời nhắn ngắn không ký tên được viết rồi đốt, rồi lại viết, trên tay áo người ấy vết mực còn đen."},{"who":"A","text":"Người thị vệ ấy sắp lên đường ra biên ải. {Xung} chỉ muốn hắn biết: lệnh điều không phải từ {xung}. Một lời nhắn, không có chữ ký."},{"who":"me","text":"Lời nhắn không ký tên thì hắn có tin không? {Goi} định viết gì?"},{"who":"A","text":"Chỉ vài chữ, đủ để hắn hiểu {xung} không hề muốn điều này. Hắn biết nét chữ của {xung}."},{"who":"me","text":"Lời nhắn ấy phải đến tay hắn trước ngày ra quân. {Xung} sẽ nghĩ nhờ ai chuyển."}]}},
{"id":"nr:cn_tinh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Khôn Ninh cung, tiếng xì xào từ các cung nữ lan nhanh như gió, người ấy đứng đó mà đôi chân như chôn xuống đất."},{"who":"A","text":"Lời đồn {xung} tư tình với thị vệ vừa dừng ở cửa Trung cung. Hoàng hậu chưa tin, cũng chưa bỏ qua."},{"who":"me","text":"Chưa tin nghĩa là còn cơ hội minh oan. {Goi} muốn Hoàng hậu biết điều gì?"},{"who":"A","text":"Rằng lời đồn không có gốc, kẻ tung tin đã nhận bạc. Xin {goi} thưa giúp {xung} một lời."},{"who":"me","text":"Thưa với Hoàng hậu bằng lời hay nhờ ma ma thân cận thưa lại, đều cần khéo. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:cn_tinh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một túi bạc nhỏ còn gói trong khăn gấm được tìm thấy trong tay áo một tiểu thái giám, bị dấu dưới chiếc gối."},{"who":"A","text":"Kẻ tung lời đồn tư tình là một tiểu thái giám, mà hắn nhận bạc của {B}. {Goi} giúp {xung} bắt được dấu bạc ấy."},{"who":"me","text":"Có bạc ắt có dấu, chỉ cần lần theo sẽ thấy. {Goi} biết hắn nhận bạc từ ai?"},{"who":"A","text":"Từ người của {B}, nhưng chưa có chứng cớ. Nếu bắt được bạc trong tay hắn là đủ."},{"who":"me","text":"Lần theo bạc hay hỏi thẳng hắn khi hắn qua cung, mỗi đường một nguy. {Xung} sẽ chọn."}]}},
{"id":"nr:cn_tinh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ ra vào cung của Kính sự phòng đặt giữa bàn, bìa đen bóng, từng dòng đều ngay ngắn và lạnh lẽo."},{"who":"A","text":"Kính sự phòng mở sổ ra vào cung {xung}. Chỉ một dòng sai là đủ chết. Người chép sổ là kẻ từng nhận ơn {B}. {Goi} giúp {xung} xem hắn đã chép gì."},{"who":"me","text":"Sổ Kính sự phòng mà sai một dòng thì cả đời mang tội. {Goi} nghi hắn đã chép sai điều gì?"},{"who":"A","text":"Chuyện ai ra vào và vào giờ nào. Chỉ cần sai giờ là thành người có tội."},{"who":"me","text":"Dò sổ Kính sự phòng là việc cần rất khéo. Việc ấy, {xung} sẽ tính xem nên dò từ ngoài hay hỏi người trong."}]}},
{"id":"nr:cn_tinh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một dòng chữ trong sổ Kính sự phòng bị gạch mờ rồi viết lại đè lên, mực mới sáng hơn mực cũ."},{"who":"A","text":"Sổ Kính sự phòng ghi đêm ấy {xung} được triệu, mà có kẻ muốn sửa thành đêm khác. Xin {goi} nhắc Hoàng thượng đêm ấy Hoàng thượng đã ở đâu."},{"who":"me","text":"Một đêm đổi thành đêm khác thì cả chứng cứ đổi theo. {Goi} chắc Hoàng thượng còn nhớ chứ?"},{"who":"A","text":"Nhớ, nhưng cần có người nhắc đúng lúc. Hoàng thượng bận trăm việc, chuyện nhỏ dễ quên."},{"who":"me","text":"Nhắc Hoàng thượng đêm ấy hoặc nhờ Tổng quản giữ sổ cho đúng, mỗi cách một vẻ. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_tinh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài hiên, mưa phùn rơi lất phất, người ấy ôm một tấm áo bông đã gói sẵn, tay bấu chặt vào góc vải."},{"who":"A","text":"Người thị vệ ấy về kinh đối chất. Mẹ già của hắn ở ngoài kinh không ai trông. {Xung} muốn hắn biết bà đã có người lo, để hắn khỏi bị ai dọa."},{"who":"me","text":"Kẻ nào dùng mẹ già làm điều đe dọa là kẻ hèn. {Goi} muốn lo cho bà thế nào?"},{"who":"A","text":"Một chỗ ở yên, đủ ăn đủ ấm. Xin {goi} lo giúp {xung} một chỗ cho bà."},{"who":"me","text":"Tự lo hay bỏ bạc thuê người chăm, đều là cách báo ơn. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_tinh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phiên đối chất sắp mở, trên án là danh sách những người sẽ có mặt, tên người thị vệ ấy nằm ở dòng đầu."},{"who":"A","text":"Ngày thị vệ ấy đối chất, Hoàng thượng sẽ nhìn {xung}. Nếu Hoàng thượng không ngồi đó, hắn sẽ dám nói thật hơn. Xin {goi} giữ Hoàng thượng lại buổi ấy."},{"who":"me","text":"Người ngồi trên cao mà nhìn xuống thì ai cũng sợ. {Goi} muốn Hoàng thượng ở đâu buổi ấy?"},{"who":"A","text":"Ở đâu cũng được, miễn đừng có mặt. Hắn nói thật thì mới cứu được cả hai."},{"who":"me","text":"Mời Hoàng thượng ở lại cung mình hay nhờ thái giám xếp việc cho Hoàng thượng bận, đều là cách. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_ban_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn xuống cung đình, một người chị em cũ co ro ngoài hành lang, hai tay còn đỏ vì nước giặt."},{"who":"A","text":"Người chị em từ thuở giặt áo của {xung} biết quá nhiều chuyện cái giếng. Có kẻ muốn nàng ấy câm lặng. Xin {goi} cho nàng ấy một chỗ trốn đến khi yên."},{"who":"me","text":"Nàng ấy đã thấy những gì ở cái giếng mà người ta muốn bịt miệng?"},{"who":"A","text":"Thấy người xuống giếng, thấy kẻ ra tay. Chỉ nàng ấy mới là chứng nhân còn sống."},{"who":"me","text":"Giấu người chứng nhân là giữ lấy công lý. {Xung} sẽ nghĩ nên đón nàng hay gửi nàng đi."}]}},
{"id":"nr:cn_ban_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi sáng sương mờ, Hoán y cục tĩnh lặng, một tấm thẻ bài lạ rơi xuống nền gạch ướt mà chưa ai nhặt."},{"who":"A","text":"Kẻ muốn chị em cũ của {xung} câm lặng đã cho người đến Hoán y cục hỏi chuyện. Người ấy mang thẻ cung {B}. {Goi} giúp {xung} xem thẻ ấy có phải đồ thật."},{"who":"me","text":"Thẻ bài có thể làm giả, cũng có thể bị đánh cắp. {Goi} nghi sao?"},{"who":"A","text":"Nghi là giả, vì {B} không dại đến mức để người của mình mang thẻ đi khắp nơi."},{"who":"me","text":"Dò thẻ bài hay đến tận Hoán y cục hỏi, mỗi đường một nguy. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:cn_ban_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn mờ, người chị em cũ ngồi co trong góc phòng, ánh mắt như con thú nhỏ sợ tiếng động."},{"who":"A","text":"Chị em cũ của {xung} thấy cả đôi hài kẻ đổ thuốc, nay hai cung cùng sợ nàng ấy. {Xung} giữ nàng ấy không nổi nữa. Xin {goi} giữ giúp ít hôm."},{"who":"me","text":"Hai cung cùng sợ nàng thì không nơi nào còn yên. {Goi} muốn nàng ở đâu?"},{"who":"A","text":"Nơi nào không ai nghĩ đến. Nàng ấy đã sợ đến mức không dám ăn."},{"who":"me","text":"Giữ nàng trong cung mình hay lo cho nàng việc ngoài cung, đều là cách che. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_ban_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một đôi hài thêu hoa sen nhỏ được đặt trên khăn gấm, mũi hài còn dính bùn đêm hôm ấy."},{"who":"A","text":"Đôi hài chị em cũ của {xung} thấy đêm ấy là hài thêu kiểu cung {B}. {Xung} cần biết đêm ấy ai trong cung nàng ta mang đôi hài ấy."},{"who":"me","text":"Hài thêu thì mỗi cung một kiểu, dễ nhận ra. {Goi} nghi hài ấy là thật hay cố ý để lại?"},{"who":"A","text":"Nghi là cố ý. Kẻ đi hài ấy không thể không biết để lại dấu thế nào."},{"who":"me","text":"Dò đôi hài trong cung {B} hay khen kiểu hài mà hỏi khéo, đều cần tinh ý. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:cn_ban_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây trâm vàng được tìm thấy dưới lớp chăn thô trong phòng Hoán y cục, đầu trâm còn dính một sợi chỉ lạ."},{"who":"A","text":"Cây trâm vàng được tìm thấy trong chăn chị em cũ của {xung}. Ai đặt nó vào? Người hầu của {B} hôm ấy có ghé Hoán y cục. {Goi} giúp {xung} lần ra bàn tay ấy."},{"who":"me","text":"Một cây trâm trong chăn người nghèo, ắt có kẻ đặt vào. {Goi} đoán là lúc nào?"},{"who":"A","text":"Buổi chiều, khi người trong phòng đi giặt. Chỉ có vài người ghé qua lúc ấy."},{"who":"me","text":"Dò ai ghé Hoán y cục hay hỏi thẳng người hầu {B}, đều cần khéo. {Xung} sẽ định đường đi cho kín."}]}},
{"id":"nr:cn_ban_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ án trộm trâm đã đóng dấu từ sớm, mép giấy còn thơm mùi mực mới, người ấy cầm nó mà tay run lên."},{"who":"A","text":"Án trộm trâm của chị em cũ {xung} xử vội, chưa ai hỏi thợ bạc. Nếu Hoàng hậu cho xét lại một lần, người làm ra cây trâm sẽ nói ai đã mua nó."},{"who":"me","text":"Một án xử vội thì còn nhiều chỗ hở. {Goi} muốn Hoàng hậu xét lại điều gì?"},{"who":"A","text":"Chỉ cần hỏi thợ bạc. Cây trâm quý như thế, thợ làm ra không thể không nhớ người mua."},{"who":"me","text":"Mở lời thay một người không ai nghe là việc đáng làm. Để {xung} suy xét xem nên thưa thế nào."}]}},
{"id":"nr:cn_ban_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm, tiếng ho khan vọng lại từ căn phòng sau Hoán y cục, chiếc khăn lau miệng của người bệnh đỏ thẫm."},{"who":"A","text":"Chị em cũ của {xung} ho ra máu, Thái y viện không chữa cho tội nô. {Xung} cần một thái y chịu xem lén một lần."},{"who":"me","text":"Tội nô mà ho ra máu, nếu để lâu e không qua khỏi. {Goi} biết thái y nào chịu giúp không?"},{"who":"A","text":"Có một vị tâm thiện, nhưng không dám làm công khai. Chỉ cần có người nhờ đúng cách."},{"who":"me","text":"Xem lén một lần, hay tự sắc thuốc mang sang, đều có cái khó. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_ban_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Toa thuốc của thái y đặt trên bàn, nét chữ gọn gàng, dòng cuối ghi một vị thuốc quý không phải nơi nào cũng có."},{"who":"A","text":"Thái y nói không có sâm trăm năm thì chị em cũ của {xung} không qua nổi. Sâm ấy chỉ Ngự dược phòng có. {Goi} quen người ở đó, xin một nhánh."},{"who":"me","text":"Sâm trăm năm là vật báu, Ngự dược phòng giữ rất chặt. {Goi} có hy vọng không?"},{"who":"A","text":"Có, nếu {goi} chịu mở lời. Một nhánh nhỏ cũng đủ để nàng ấy qua cơn nguy."},{"who":"me","text":"Xin một nhánh sâm vì một mạng người. {Xung} sẽ cân nhắc xem nên nhờ người hay tự lo."}]}},
{"id":"nr:cn_ban_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió luồn qua khe cửa, người chị em cũ ngồi bên bàn, một tờ khai chưa ký đặt trước mặt, ngón tay không dám chạm vào bút."},{"who":"A","text":"Chị em cũ của {xung} muốn khai hết. Trước khi lời khai đến tay ai, nàng ấy phải ở chỗ không ai bịt miệng được. Xin {goi} giữ nàng ấy giúp {xung}."},{"who":"me","text":"Lời khai ấy nặng bao nhiêu người. {Goi} tin nàng ấy đủ gan đến ngày khai không?"},{"who":"A","text":"Đủ, nếu không bị ai đe dọa. Nàng ấy chỉ sợ trước ngày khai bị kẻ khác bắt đi."},{"who":"me","text":"Giữ nàng ở cung mình hay lo một chỗ kín ngoài kia, đều được. {Xung} phải cân nhắc kỹ xem nên giấu nàng ở đâu."}]}},
{"id":"nr:cn_ban_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản khai viết xong còn thơm mùi mực, từng dòng là từng bí mật của cả một đêm ở cái giếng."},{"who":"A","text":"Lời khai của chị em cũ {xung} đã viết xong. {Xung} muốn gửi một bản ra ngoài cung, phòng khi bản trong cung bị đốt."},{"who":"me","text":"Giữ hai bản thì mất một bản cũng không mất hết. {Goi} muốn gửi bản ấy cho ai giữ?"},{"who":"A","text":"Người nào đáng tin, không sợ bị người khác dò hỏi. Bản ấy là mạng của nàng ấy."},{"who":"me","text":"Bản khai phải ra khỏi cung an toàn. {Xung} sẽ liệu cách gửi."}]}},
{"id":"nr:cn_ban_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày phiên xét lại, khói trầm Khôn Ninh cung thoảng trên tay áo người ấy, chỉ còn vài canh giờ nữa là đến buổi."},{"who":"A","text":"Trung cung mở phiên xét lại án chị em cũ của {xung}. {Xung} xuất thân kẻ hầu, nói ra không ai nghe. Xin {goi} đứng cạnh {xung} một lời trước Hoàng hậu."},{"who":"me","text":"Một lời của người có phẩm vị đứng bên có thể thay đổi cả phiên xét. {Goi} muốn {xung} nói gì?"},{"who":"A","text":"Chỉ cần nói rằng {xung} đã xem xét kỹ và tin chị em cũ vô tội. Một câu thôi cũng đủ."},{"who":"me","text":"Đứng ra nói một lời hay dâng lễ xin xét công bằng, đều có cái giá của nó. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_ban_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách nhân chứng của phiên xét lại được dán trên bảng, tên một người đã bị người khác gạch nhẹ bằng mực nhạt."},{"who":"A","text":"Phiên xét lại án sắp mở, mà người của {B} đã đến gặp nhân chứng trước. {Goi} giúp {xung} xem họ đã nói gì với người ấy."},{"who":"me","text":"Gặp nhân chứng trước phiên xét thì thường không phải để thăm hỏi. {Goi} đoán họ đã nói gì?"},{"who":"A","text":"Có thể dọa, có thể dụ. Nhân chứng ấy sống một mình, không ai bảo vệ."},{"who":"me","text":"Hỏi nhân chứng sau khi người của {B} đi, hay tự gặp, đều phải nhanh. {Xung} sẽ chọn."}]}},
{"id":"nr:cn_than_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa phùn rơi bên thềm, người ấy ngồi bên một chiếc ghế thấp, tay nắm chặt tấm khăn trắng để tang lão ma ma."},{"who":"A","text":"Lão ma ma nuôi {xung} đã mất, để lại một bọc vải ở nhà cháu bà ngoài kinh. {Xung} cần người mang bọc ấy vào mà không ai mở."},{"who":"me","text":"Bà đã nuôi {goi} từ thuở nhỏ, bọc vải ấy hẳn giữ điều gì quan trọng. {Goi} có biết bên trong là gì không?"},{"who":"A","text":"Không rõ. Chỉ biết lúc lâm chung bà dặn: nếu {xung} muốn biết thân thế, phải đọc những gì trong đó."},{"who":"me","text":"Một lời trăn trối đáng nghe, nhất là khi chứa nguồn cội. {Xung} sẽ nghĩ nhờ ai mang bọc ấy vào cung."}]}},
{"id":"nr:cn_than_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bọc vải di vật của lão ma ma nằm trên án, dây buộc còn nguyên, nhưng một góc vải đã có vết ngón tay lạ."},{"who":"A","text":"Bọc di vật của lão ma ma chưa ai mở mà đã có người hỏi đến. Người hỏi là cung nữ của {B}. {Goi} giúp {xung} xem vì sao nàng ta quan tâm."},{"who":"me","text":"Một bọc vải của bà già đã mất mà có người hỏi, thật lạ. {Goi} có nói với ai về bọc ấy không?"},{"who":"A","text":"Không, chỉ vài người thân biết. Có người đã nói ra, hoặc có người đã nghe lén."},{"who":"me","text":"Dò xem cung nữ ấy hỏi cho ai, hay hỏi thẳng {B}, mỗi đường một nguy. Để {xung} quyết lấy một đường."}]}},
{"id":"nr:cn_than_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, bản án cũ của phụ thân ruột được lấy từ đáy rương ra, giấy đã ngả vàng, mực đã nhạt gần hết."},{"who":"A","text":"Người hặc phụ thân ruột của {xung} năm xưa là ông nội {B}. {Xung} cần biết nàng ta có biết chuyện ấy hay không."},{"who":"me","text":"Hai nhà có nợ cũ từ đời trước mà đến nay vẫn cùng ở một cung. {Goi} đoán nàng ta biết đến đâu?"},{"who":"A","text":"Nếu nàng ta biết, mọi lời nàng nói với {xung} từ trước tới giờ đều có ý khác. Nếu không biết, nàng cũng vô tình."},{"who":"me","text":"Dò xem nàng có giữ giấy tờ cũ không, hay thử nhắc chuyện xưa để xem nàng đáp thế nào. Đường nào, {xung} xin tự cân nhắc."}]}},
{"id":"nr:cn_than_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn là tờ giấy ghi tên vị Thượng thư đương nhiệm, bên cạnh một dòng chữ nhỏ: con trai lão Thái phó."},{"who":"A","text":"Con trai lão Thái phó vẫn ngồi ghế Thượng thư. {Xung} muốn đọc tờ sớ hặc năm xưa ở Hàn lâm viện. Phải có người ngoài cung chép giúp."},{"who":"me","text":"Tờ sớ cũ cất trong Hàn lâm viện, không dễ cho người ngoài xem. {Goi} muốn biết điều gì trong đó?"},{"who":"A","text":"Ai ký tên hặc, ai viết, và vì lý do gì. Từng chữ ấy là một phần thân thế của {xung}."},{"who":"me","text":"Chép được tờ sớ ấy là tìm được một mảnh sự thật. {Xung} sẽ nghĩ nhờ ai chép giúp."}]}},
{"id":"nr:cn_than_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi hương chùa còn vương trên tay áo người ấy, trên bàn là tờ giấy ghi tên một ngôi chùa nhỏ ngoài kinh."},{"who":"A","text":"Lão quản gia họ Thẩm đang trốn ở một ngôi chùa ngoài kinh, ốm nặng. Lão giữ nửa trang sổ. {Xung} cần một thái y ra chùa xem lão."},{"who":"me","text":"Lão là người giữ chứng cứ cuối cùng. {Goi} biết lão ốm đến mức nào không?"},{"who":"A","text":"Nghe nói ho nhiều, sốt nhiều ngày. Chỉ sợ lão không qua được mùa đông này."},{"who":"me","text":"Cứu lão là giữ lấy một mảnh sự thật. Việc ấy, {xung} sẽ tính xem nên mời thái y hay tự bốc thuốc."}]}},
{"id":"nr:cn_than_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh nến, mảnh giấy ghi đường đến ngôi chùa được vẽ vội bằng mấy nét than, góc giấy còn dính nước mưa."},{"who":"A","text":"Nhà {B} cũng đang tìm lão quản gia họ Thẩm. {Xung} cần một lời nhắn đến chùa trước họ: lão phải dời đi ngay."},{"who":"me","text":"Họ tìm lão bằng cách nào mà {goi} biết được?"},{"who":"A","text":"Một người nhà họ đã hỏi thăm khắp các chùa ngoài kinh. Chỉ vài ngày nữa là tới ngôi chùa ấy."},{"who":"me","text":"Lời nhắn phải đến chùa trước họ một bước. {Xung} sẽ nghĩ nên nhờ ai đưa đi."}]}},
{"id":"nr:cn_than_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ hặc không nêu tên được truyền đi khắp cung, người ấy cầm nó mà tay run, vì ai đọc cũng biết đang nhắm vào ai."},{"who":"A","text":"Tờ sớ hặc phi tần lật án tiên đế không nêu tên, mà ai cũng biết là {xung}. Xin {goi} thưa rằng {xung} chỉ muốn biết cha ruột, không dám đụng án tiên đế."},{"who":"me","text":"Tìm cha là chuyện tình thân, nhưng án tiên đế là chuyện quốc pháp. {Goi} muốn Hoàng thượng nghe lời ấy thế nào?"},{"who":"A","text":"Như lời của người con gái muốn biết gốc mình, không phải lời của kẻ muốn lật án. Chỉ cần Hoàng thượng hiểu điều đó."},{"who":"me","text":"Thưa nỗi lòng ấy hay nhờ một lão thần giảng hòa với Ngự sử, mỗi đường một vẻ. {Xung} sẽ nghĩ."}]}},
{"id":"nr:cn_than_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm Đức Thọ cung nhè nhẹ trong điện, người ấy ngồi thật ngay, nhìn tờ sớ hặc trong tay mà thở dài."},{"who":"A","text":"Án ấy xử thời tiên đế, Thái hậu còn nhớ. Nếu người nói một lời rằng tìm cha không phải tội, tờ sớ kia sẽ nhẹ đi. Xin {goi} thưa trước khi sớ đến triều."},{"who":"me","text":"Thái hậu còn nhớ án ấy, lại còn thương người mất cha. {Goi} muốn người biết điều gì?"},{"who":"A","text":"Rằng {xung} chỉ muốn thắp một nén hương cho cha ruột, không có ý gì khác."},{"who":"me","text":"Lời nhờ ấy phải thưa cho đúng chỗ. Để {xung} suy xét xem nên hầu Thái hậu hay dâng lễ cúng tiên đế."}]}},
{"id":"nr:cn_than_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ cung mở trang ghi tên người ấy, hàng xuất thân còn chép nét chữ cũ, chưa ai sửa."},{"who":"A","text":"Họ Thẩm đã nhận lại {xung}, mà sổ cung vẫn ghi xuất thân cũ. Chỉ một chữ của Hoàng thượng là sổ được sửa. Xin {goi} nhắc Hoàng thượng."},{"who":"me","text":"Sổ cung ghi xuất thân cũ thì mỗi lần đọc là mỗi lần nhắc chuyện xưa. {Goi} có hay bị nhắc không?"},{"who":"A","text":"Có. Mỗi lần tấn phong hay ban thưởng, sổ lại được mang ra, và cái xuất thân cũ lại hiện ra trước mắt mọi người."},{"who":"me","text":"Xin sửa sổ cho đúng gốc là việc chính đáng. {Xung} phải cân nhắc kỹ xem nên thưa Hoàng thượng hay nhờ Tông nhân phủ."}]}},
{"id":"nr:cn_than_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói di vật của mẹ đặt cạnh lá thư viết dở, giữa hai thứ là một chiếc khăn thêu nhỏ cũ kỹ, đường chỉ đã bạc màu."},{"who":"A","text":"Tên {xung} chưa vào tông phả họ Thẩm, trưởng họ ở quê còn đắn đo. {Xung} cần gửi về một lá thư cùng di vật của mẹ để ông tin."},{"who":"me","text":"Trưởng họ đắn đo vì chưa có bằng chứng. Di vật của mẹ {goi} có nói được điều gì với ông không?"},{"who":"A","text":"Có chiếc khăn thêu họ Thẩm, chỉ người trong họ mới nhận ra kiểu thêu. Ông sẽ nhìn là biết."},{"who":"me","text":"Thư và di vật ấy phải đến tận tay trưởng họ. {Xung} sẽ nghĩ nhờ ai mang về quê."}]}},
{"id":"nr:cn_than_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ trình minh oan đã được đặt lên ngự án, trang cuối còn kẹp nửa trang sổ ngả vàng, mép giấy bị cháy xém một góc."},{"who":"A","text":"Tờ trình minh oan cho phụ thân ruột của {xung} đã lên ngự án. Trang cuối là nửa trang sổ lão quản gia giữ. Xin {goi} nhắc Hoàng thượng đọc đến trang ấy."},{"who":"me","text":"Hoàng thượng mà đọc đến trang cuối thì án oan có thể được lật. {Goi} lo Hoàng thượng không đọc hết sao?"},{"who":"A","text":"Lo. Tờ trình dài, nếu không có người nhắc, Hoàng thượng chỉ đọc nửa đầu rồi phán."},{"who":"me","text":"Một lời nhắc đúng lúc có thể đổi cả một án oan. Việc ấy, {xung} sẽ tính xem nên nhắc thế nào."}]}},
{"id":"nr:cn_than_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi trầm Đức Thọ cung thoảng trong điện, người ấy ngồi thẳng lưng, tay đặt lên tờ trình minh oan đã gấp làm tư."},{"who":"A","text":"Thái hậu là người đã thấy triều đình đời tiên đế. Chỉ cần người hỏi Hoàng thượng đã đọc tờ trình chưa, cũng đủ. Việc ấy chỉ cần {goi} mở lời ở Đức Thọ cung."},{"who":"me","text":"Một câu hỏi của Thái hậu đủ để Hoàng thượng đọc đến nơi đến chốn. {Goi} muốn người hỏi thế nào?"},{"who":"A","text":"Hỏi nhẹ thôi, như chuyện thường ngày. Nhưng Hoàng thượng nghe là hiểu."},{"who":"me","text":"Hầu Thái hậu hay dâng kinh chép tay cầu siêu cho người oan, mỗi cách một vẻ. {Xung} sẽ nghĩ."}]}},
{"id":"j72:nr_emp","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên chiều, người ấy đợi bên bậc cửa từ lâu, tay giữ một phong thư gấp lại mà chưa dám đưa."},{"who":"A","text":"Việc của {xung} đã đến tai Hoàng thượng rồi. {Goi} được gần thánh giá, xin nói giúp {xung} một lời."},{"who":"me","text":"Hoàng thượng đã nghe được những gì, {goi} có biết không?"},{"who":"A","text":"Chỉ nghe một nửa, mà nửa ấy lại do người khác kể. {Xung} chỉ mong người nghe thêm một lời của chính mình."},{"who":"me","text":"Nói giúp một người trước mặt Hoàng thượng không phải việc nhỏ. {Xung} sẽ nghĩ nên giúp bằng đường nào."}]}},
{"id":"j72:nr_th","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi trầm từ Đức Thọ cung còn vương trên tay áo người ấy, chiếc khăn lụa đã bị vò nhàu từ lúc nào."},{"who":"A","text":"Thái hậu đang nghe lời gièm về {xung}. {Goi} thường đến Đức Thọ cung, xin đỡ lời cho {xung}."},{"who":"me","text":"Lời gièm ấy đã đến tai Thái hậu từ lúc nào, {goi} có biết không?"},{"who":"A","text":"Mới vài hôm. Nhưng Thái hậu là người hiền, nghe nhiều lần thì sẽ tin. {Xung} sợ không kịp."},{"who":"me","text":"Đỡ lời trước Thái hậu cần khéo hơn nói với ai. Để {xung} suy xét xem nên đi bằng lời hay bằng lễ."}]}},
{"id":"j72:nr_hh","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua hành lang Khôn Ninh cung, người ấy đứng ngoài cửa điện lâu rồi, ngón tay xoắn chặt vạt khăn."},{"who":"A","text":"Trung cung đang để mắt đến {xung}. {Goi} nói được với Hoàng hậu, xin nói giúp một câu."},{"who":"me","text":"Hoàng hậu để mắt đến {goi} vì chuyện gì, {goi} có đoán ra không?"},{"who":"A","text":"Có lẽ vì mấy lời xì xào ở buổi thỉnh an. {Xung} chưa làm gì sai, chỉ sợ có người đã thêm thắt."},{"who":"me","text":"Một câu nói đúng lúc với Trung cung có thể dẹp yên nhiều lời. {Xung} phải cân nhắc kỹ xem nên thưa thế nào."}]}},
{"id":"j72:nr_thu","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, một lá thư đã dán kín được đặt lên bàn, góc phong bì còn ẩm vì tay cầm lâu."},{"who":"A","text":"{Xung} có một lá thư phải đến tay người nhà, không được qua tay Kính sự phòng. {Goi} giúp {xung}."},{"who":"me","text":"Thư qua Kính sự phòng thì ai cũng đọc được. Trong thư {goi} viết điều gì mà sợ như vậy?"},{"who":"A","text":"Chỉ là chuyện nhà, nhưng người trong cung đọc được thì thêm bớt thành chuyện khác."},{"who":"me","text":"Thư này phải ra khỏi cung bằng đường khác. {Xung} sẽ nghĩ cách đưa."}]}},
{"id":"j72:nr_do","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn xuống nhẹ trên hành lang, người ấy ngồi bên cửa sổ, mắt nhìn về phía cung của {B} mà không chớp."},{"who":"A","text":"{Xung} cần biết {B} đang tính gì. {Goi} có tai mắt, giúp {xung} dò một chuyện."},{"who":"me","text":"Nàng ta đã làm gì khiến {goi} lo như vậy?"},{"who":"A","text":"Chưa làm gì rõ ràng, nhưng mấy hôm nay cung nàng ta ra vào tấp nập, mà chẳng ai nói vì sao."},{"who":"me","text":"Dò xem một người đang tính gì cần cẩn thận hơn dò xem họ đã làm gì. Việc ấy, {xung} sẽ tính xem nên dò bằng cách nào."}]}},
{"id":"j72:nr_y","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa chiều muộn, người ấy ngồi bên án, tay ôm một chiếc khăn lụa ướt mồ hôi, sắc mặt nhợt nhạt."},{"who":"A","text":"Bệnh này không thể để Thái y viện ghi sổ. {Goi} quen thái y, xin mời người đến xem kín cho {xung}."},{"who":"me","text":"Bệnh không dám để ai biết, hẳn {goi} đã giấu lâu rồi. Bệnh đã nặng đến đâu?"},{"who":"A","text":"Khi nhẹ khi nặng, nhưng {xung} sợ một khi có tên trong sổ thì khó giữ được yên."},{"who":"me","text":"Mời thái y xem kín là việc cần người đáng tin. {Xung} sẽ nghĩ nên lo thế nào."}]}},
{"id":"j72:nr_che","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa tạt ngoài hiên, người ấy đứng ngoài cửa điện, tóc ướt, tay nắm chặt tay nải như kẻ sắp đi xa."},{"who":"A","text":"{Xung} đang gặp nạn, không còn chỗ nương. {Goi} che chở cho {xung} ít hôm."},{"who":"me","text":"Nạn từ đâu đến mà {goi} không còn chỗ nương?"},{"who":"A","text":"Từ một lời đồn mà ai cũng tin. Không ai dám cho {xung} ở nhờ, sợ bị liên lụy."},{"who":"me","text":"Cho người ta một chỗ nương lúc hoạn nạn là việc đáng làm. {Xung} sẽ nghĩ xem lo thế nào cho ổn."}]}},
{"id":"j72:nr_bac","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn, người ấy ngồi bên bàn, một túi gấm đã xẹp được đặt trước mặt, bên cạnh là tờ giấy ghi con số bị gạch đi viết lại."},{"who":"A","text":"{Xung} đang cần bạc gấp, việc nhà không thể nói ra. {Goi} giúp {xung} lần này, {xung} không quên."},{"who":"me","text":"Việc gấp đến mức phải mở lời với người ngoài, ắt là khó nói. {Goi} cần đến bao giờ?"},{"who":"A","text":"Càng sớm càng tốt. {Xung} không muốn hỏi ai khác, vì lời đồn đi nhanh hơn bạc."},{"who":"me","text":"Giúp người lúc ngặt là kết được một mối ân tình. Để {xung} suy xét xem nên giúp thế nào."}]}},
{"id":"nr:nc_gian_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, trong tiểu viện còn vương mùi trầm cố hương, nàng giấu một phong thư trong tay áo, ngón tay siết chặt mép giấy."},{"who":"A","text":"Ở Hội Đồng quán có một lái buôn cố hương đang đợi tin của {xung}. Thư mà đi qua Kính sự phòng thì ai cũng đọc được chữ nước {xung}."},{"who":"me","text":"Thư nhà vốn là chuyện riêng, vậy mà phải e dè như thể làm điều có lỗi. {Xung} hiểu nỗi lòng ấy."},{"who":"A","text":"{Goi} chỉ cần cho một người kín miệng mang thư ra đến cửa quán, không cần hỏi trong thư viết gì."},{"who":"me","text":"Đường ra phố có hai ngả, {xung} sẽ chọn ngả nào ít người để mắt nhất rồi mới gật đầu."}]}},
{"id":"nr:nc_gian_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phong thư khen ngợi từ cố quốc đặt trên án, con dấu sáp còn nguyên mà nàng cứ nhìn mãi, mày khẽ chau."},{"who":"A","text":"Thư khen từ cố quốc vừa tới, mà {B} đã biết trước cả {xung}. Đường thư ấy hẳn có người nhìn trộm."},{"who":"me","text":"Một lời khen mà đến nơi sau kẻ khác, thật chẳng giống lời khen. {Goi} còn nhớ hôm nào thư tới không?"},{"who":"A","text":"{Xung} chỉ muốn biết người của {B} ra vào Hội Đồng quán những hôm nào. Biết rồi, {xung} sẽ liệu cách."},{"who":"me","text":"Việc này không thể hỏi thẳng. {Xung} sẽ tìm cách dò cho kín, để {B} không hay mình bị dõi lại."}]}},
{"id":"nr:nc_gian_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thu thổi qua cổng Chính Dương, đoàn xe buôn xếp hàng dài, riêng một chiếc rương gỗ bị niêm lại, dây buộc còn đỏ."},{"who":"A","text":"Lão lái buôn bị giữ ở cửa Chính Dương vì thiếu một tấm lộ dẫn của bộ Lễ. Rương ấy bị khám đến đáy thì {xung} không còn đường lui."},{"who":"me","text":"Chỉ một tờ giấy mà giữ chân cả đoàn buôn. Trong rương ấy có gì mà {goi} lo đến vậy?"},{"who":"A","text":"Có nhiều thứ không thể để người lạ nhìn thấy. {Goi} có cách nào xin cho kịp một tờ giấy ấy, trước khi đoàn buôn phải quay đầu?"},{"who":"me","text":"Tờ lộ dẫn phải đến đúng tay. {Xung} sẽ cân xem nên nhờ người trong cung hay người nhà, ai đi thì ít bị hỏi han hơn."}]}},
{"id":"nr:nc_gian_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên cửa Chính Dương, chiếc rương sơn son nằm lẻ loi, nắp còn dán tờ niêm của quan coi cổng."},{"who":"A","text":"Rương hàng ở cửa Chính Dương không chỉ có thư, còn có món quà {xung} dâng Hoàng thượng dịp Vạn thọ."},{"who":"me","text":"Quà mừng Vạn thọ mà nằm ngoài cổng thành thì thật uổng công người chuẩn bị. {Goi} muốn tâu sao?"},{"who":"A","text":"Hoàng thượng chỉ cần biết món quà đang bị giữ, một chữ của người là rương qua cửa. {Goi} nhắc giúp {xung} được không?"},{"who":"me","text":"Một lời nhắc đúng lúc là đủ. {Xung} sẽ tìm dịp thích hợp, hoặc nhờ người gần Hoàng thượng chuyển lời, để việc nhẹ nhàng."}]}},
{"id":"nr:nc_gian_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm đã khuya, ngoài tường cung vẫn có bóng áo giáp đứng bất động dưới ánh đèn lồng đỏ."},{"who":"A","text":"Thị vệ đứng ngoài cung {xung} đã ba đêm. Hoàng thượng chưa hỏi, nhưng người đang chờ một kẻ khác nói trước."},{"who":"me","text":"Ba đêm có người canh cửa, hẳn {goi} ngủ chẳng yên. Hoàng thượng chưa lên tiếng, ấy là còn chừa cho {goi} một lối."},{"who":"A","text":"Lúc {goi} hầu Hoàng thượng, xin nói giúp rằng {xung} chưa từng làm điều gì sau lưng người."},{"who":"me","text":"Lòng thẳng thì lời cũng phải thẳng. {Xung} sẽ chọn lúc và người nói sao cho Hoàng thượng nghe vào tai."}]}},
{"id":"nr:nc_gian_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ cuối cung, một nàng cung nữ cúi đầu tỉ mỉ xếp lại khăn lụa, ngón tay run khẽ."},{"who":"A","text":"Thị vệ đứng ngoài cửa, mà trong cung {xung} còn một cung nữ cố hương biết chữ nước nhà. Người ta sẽ hỏi nàng ấy trước tiên."},{"who":"me","text":"Nàng ấy chỉ là một cung nữ, nhưng ai cũng biết nàng ấy từng cùng {goi} từ quê hương sang đây."},{"who":"A","text":"{Goi} cho nàng ấy sang hầu cung của {goi} ít hôm, được không? Dưới mái nhà khác, lời tra hỏi cũng chùng lại."},{"who":"me","text":"Nàng ấy run tay xếp khăn, {xung} nhìn mà xót. Đón về cũng cần một cớ thật êm, kẻo chính {xung} lại gợi thêm nghi ngờ."}]}},
{"id":"nr:nc_gian_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa sổ khép hờ, trên án chồng thư nhà chưa gửi, mực còn ẩm, ngoài hiên có bóng người đứng quá lâu."},{"who":"A","text":"Từ khi biên ải có chuyện, người của {B} đếm từng lá thư {xung} viết. {Xung} cần biết ai đang canh cửa sổ của {xung}."},{"who":"me","text":"Chỉ thư nhà thôi cũng bị đếm, thật là nặng nề. {Goi} định gửi tin thật hay tin giả về cố quốc?"},{"who":"A","text":"Chuyện ấy {xung} chưa dám nghĩ. Trước hết phải biết kẻ nào rình, sau mới biết nên viết gì."},{"who":"me","text":"Phải biết mắt nhìn từ đâu rồi mới dám đặt bút. {Xung} sẽ dò cho {goi}, nhẹ tay và kín tiếng."}]}},
{"id":"nr:nc_gian_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng thơm mùi giấy cũ, tấm bản đồ hành quân vẫn còn nằm nửa cuộn trên án của Hoàng thượng."},{"who":"A","text":"Hoàng thượng tin {xung}, nên kể cả đường hành quân. {Xung} không muốn biết thêm một chữ nào nữa."},{"who":"me","text":"Được tin cậy mà thành nỗi sợ, thật là một gánh nặng. Biết nhiều thì dễ bị nghi, mà không biết thì lại thấy mình bị gạt ra ngoài."},{"who":"A","text":"{Goi} khéo khuyên Hoàng thượng đừng bàn việc quân ở cung {xung}. Như thế {xung} khỏi phải chọn giữa hai bờ."},{"who":"me","text":"Khuyên sao cho Hoàng thượng không nghĩ {goi} đang nghi người. {Xung} sẽ tìm cách nói cho mềm."}]}},
{"id":"nr:nc_gian_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa lạnh phủ kín nhà lao Đại Lý tự, trên bậc đá có một chiếc áo cũ xếp gọn, dường như vừa có người định mang vào."},{"who":"A","text":"Lão ấy nằm trong ngục Đại Lý tự, chờ phiên thẩm vấn. {Xung} chỉ cần lão nghe được một câu: cứ giữ im lặng, nhà lão sẽ có người lo."},{"who":"me","text":"Một câu nhắn đến người trong ngục, tưởng nhẹ mà nặng như đá. Cửa ngục kín thế, ai đi được?"},{"who":"A","text":"Vì thế {xung} mới cậy đến {goi}. Nhà {goi} có ai ra vào được cửa ngục không?"},{"who":"me","text":"Có người ra vào được, nhưng phải chọn ai đi cho khỏi để lại dấu. {Xung} sẽ lo liệu."}]}},
{"id":"nr:nc_gian_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngục tối, ngọn đèn dầu leo lét, từ xó đá vọng ra tiếng ho khô khốc kéo dài của một người già."},{"who":"A","text":"Lão ấy mắc bệnh suyễn, vào ngục mà không có thuốc thì khó qua khỏi. Chết trong ngục, người ta sẽ nói {xung} giết người diệt khẩu."},{"who":"me","text":"Một mạng người, lại vướng cả danh tiếng của {goi}. Thật là lưỡng nan."},{"who":"A","text":"Nếu {goi} quen một vị thái y, xin cho lão một thang thuốc. {Xung} chỉ cần lão sống đến hôm thẩm vấn."},{"who":"me","text":"Thuốc phải đến tay lão mà không ai hỏi vì sao. {Xung} sẽ tính đường mời người, hoặc tự tay lo."}]}},
{"id":"nr:nc_gian_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án trong ngự thư phòng, thư từ bị xếp thành từng chồng, giấy ố vàng còn nguyên dấu mực của những năm cũ."},{"who":"A","text":"Hoàng thượng đã cho bày hết thư từ lên án, rồi gọi {xung} đến một mình. {Xung} không xin {goi} che tội."},{"who":"me","text":"Thư đã bày ra thì lời không còn đứng một chỗ. {Goi} muốn xin điều gì đây?"},{"who":"A","text":"{Xung} chỉ xin, trước giờ ấy, có người nhắc Hoàng thượng nhớ những năm {xung} đã ở bên người."},{"who":"me","text":"Những năm tháng ấy là thật, và chính {goi} cũng không nên quên. {Xung} sẽ tìm lúc nhắc cho khéo."}]}},
{"id":"nr:nc_gian_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đèn Khôn Ninh cung vừa thắp, một nữ quan áo xanh đứng chắp tay ngoài điện, mắt nhìn về phía cung của nàng."},{"who":"A","text":"Hoàng thượng gọi {xung} đến một mình, mà Trung cung đã sai người đứng chờ ngoài điện. Hoàng hậu cũng hỏi tội thì {xung} không còn chỗ đứng."},{"who":"me","text":"Hai nơi cùng gọi một lúc, thật là khó đỡ. Nhưng Hoàng hậu cũng biết trên Hoàng thượng còn có phép tắc."},{"who":"A","text":"{Goi} thưa với Hoàng hậu, xin bà đợi Hoàng thượng xét xong. Chỉ thế thôi, {xung} không dám xin hơn."},{"who":"me","text":"Nữ quan áo xanh đứng chờ ngoài điện không chớp mắt, {xung} thấy rồi. Lời xin khoan thai ấy, ai nói thì Hoàng hậu mới nghe lọt?"}]}},
{"id":"nr:nc_su_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sảnh bộ Lễ, thước đo lễ nghi nằm trên án, sứ thần cố quốc đứng thẳng, áo bào xanh phủ bụi đường."},{"who":"A","text":"Bộ Lễ bắt sứ đoàn cố quốc quỳ ba lần, khấu chín lần, mà huynh trưởng của {xung} nhất quyết không chịu cúi."},{"who":"me","text":"Một chiếc lưng thẳng cũng là danh dự của cả một nước. Nhưng lễ nghi của kinh thành cũng không thể bỏ."},{"who":"A","text":"Chuyện lễ nghi, chỉ Thái hậu nói một lời là xong. {Goi} có thể thưa giúp {xung} để hai bên đều giữ được thể diện không?"},{"who":"me","text":"Huynh trưởng giữ lưng thẳng, bộ Lễ giữ phép tắc, chỉ Thái hậu mềm được cả hai. Đến cửa bà thế nào để không giống kẻ xin xỏ?"}]}},
{"id":"nr:nc_su_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Ngự thư phòng, chiếc bình trà vẫn bốc khói, bên cạnh là tập tấu của bộ Lễ chưa mở."},{"who":"A","text":"Huynh trưởng của {xung} không chịu khấu đầu chín lần, Hoàng thượng chưa hay. Nếu nghe từ miệng bộ Lễ, người sẽ giận."},{"who":"me","text":"Tin xấu nghe từ người khác bao giờ cũng nặng hơn tin nghe từ người nhà."},{"who":"A","text":"{Goi} kể trước cho người, nói rằng ở cố quốc chỉ quỳ ba lần là đủ lễ. Biết đâu người sẽ hiểu."},{"who":"me","text":"Một nước có một cách tỏ lòng kính. {Xung} sẽ lo nói cho Hoàng thượng nghe, tự mình hay qua người khác."}]}},
{"id":"nr:nc_su_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh nến, bức gấm Bách thọ trải ra trên bàn, một góc loang đen như vết mây đè lên đàn hạc trắng."},{"who":"A","text":"Bức gấm Bách thọ mẫu thân {xung} dệt suốt ba năm bị loang mực một góc, mà lễ Vạn thọ đã gần."},{"who":"me","text":"Ba năm dệt bằng cả tấm lòng, giờ lại bị một vết mực. Thật xót."},{"who":"A","text":"Thợ của cung {xung} không ai thêu được chỉ cố hương. Nếu bên {goi} có người tay khéo, xin cho {xung} mượn mấy hôm."},{"who":"me","text":"Tay khéo thì có, chỉ cần chọn ai đi cho đúng. {Xung} sẽ tìm người mà thêu cho vừa nét cố hương."}]}},
{"id":"nr:nc_su_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khăn trắng thấm mực được đặt lên khay bạc, vệt đen tỏa ra mùi phèn chua nhàn nhạt."},{"who":"A","text":"Mực đổ lên bức gấm không phải mực thường, ngửi có mùi phèn. {Xung} nghĩ có người cố ý."},{"who":"me","text":"Mực thường không có mùi ấy. Nếu đúng như vậy thì không phải chuyện sơ ý nữa."},{"who":"A","text":"{Goi} nhờ một vị thái y biết thuốc nhuộm xem giúp, để biết còn tẩy được hay không."},{"who":"me","text":"Phèn trộn trong mực, ấy không phải tay vụng làm ra. Trước khi chuyện lộ, {xung} cần một người nhìn vết màu mà dám nói thật. Người ấy là ai?"}]}},
{"id":"nr:nc_su_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài vườn Thượng Lâm, hoa quế rụng đầy lối, vài tên cấm quân đứng canh bên chiếc yên ngựa bỏ lại."},{"who":"A","text":"Huynh trưởng của {xung} say rượu, phi ngựa vào vườn Thượng Lâm, nay bị cấm quân giữ. Chuyện của một sứ thần là chuyện của hai nước."},{"who":"me","text":"Một chén rượu mà thành chuyện bang giao. Hoàng thượng đã biết chưa?"},{"who":"A","text":"Nếu có dịp hầu giá, xin {goi} nói giúp để huynh ấy chỉ bị phạt, đừng bị giải về nước trong nhục."},{"who":"me","text":"Một chén rượu say mà kéo theo thể diện hai nước. {Xung} chỉ ngại lời đến tai Hoàng thượng không đúng người, đúng lúc."}]}},
{"id":"nr:nc_su_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phía sau cổng doanh cấm quân, ngọn đuốc cháy lép bép, người gác nắm chặt cán thương, không cho ai vào."},{"who":"A","text":"Huynh trưởng của {xung} đang bị giữ ở chỗ cấm quân, chưa ai cho gặp. {Xung} cần huynh ấy nghe một lời: đừng nói gì thêm, cứ nhận lỗi say rượu."},{"who":"me","text":"Nhận lỗi say rượu thì còn có đường lui, nói thêm thì dễ thành tội lớn. Lời ấy đáng đến tay huynh ấy."},{"who":"A","text":"{Goi} có người ra vào được chỗ ấy không?"},{"who":"me","text":"Cấm quân không phải nơi ai cũng vào được, nhưng cũng có đường. {Xung} sẽ chọn người nào ít bị hỏi."}]}},
{"id":"nr:nc_su_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ xếp ghế đại yến trải trên bàn, dòng tên sứ cố quốc có vết gạch mờ và nét chữ mới chèn thêm."},{"who":"A","text":"Đại yến các nước, ghế của sứ cố quốc đặt ở hàng nào là một câu nói của hai triều. {Xung} nghe phong thanh người của {B} đã đổi chỗ trong sổ xếp ghế."},{"who":"me","text":"Một chiếc ghế cũng nói lên thứ bậc. Nếu bị đổi lén thì cả nước mất mặt."},{"who":"A","text":"{Goi} giúp {xung} hỏi xem ai đã cầm bút. Chỉ cần biết tên, {xung} sẽ tự liệu."},{"who":"me","text":"Việc này phải dò từ người lo yến. {Xung} sẽ chọn người để hỏi, sao cho không kinh động đến ai."}]}},
{"id":"nr:nc_su_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Khôn Ninh cung, chén ngọc đáp lễ đặt trên khay mạ vàng, bên cạnh là tờ giấy soạn lời chúc dở."},{"who":"A","text":"Hậu cung không dự đại yến, nhưng Trung cung được ban chén rượu đáp lễ sứ các nước. {Xung} chỉ xin Hoàng hậu nhắc đến cố quốc một câu."},{"who":"me","text":"Một câu thôi cũng đủ cho sứ thần nghe thấy mình được tôn trọng."},{"who":"A","text":"{Goi} thưa giúp {xung} được không? Chỉ một câu, không hơn."},{"who":"me","text":"Một câu nhắc cố quốc, nghe nhỏ mà nặng. Đặt nó vào chỗ nào để Hoàng hậu thuận tai, {xung} còn phải cân nhắc."}]}},
{"id":"nr:nc_su_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án bộ Hộ, bản điều ước chợ biên còn trống chữ ký, bên cạnh là bao muối mẫu trắng như tuyết."},{"who":"A","text":"Điều ước chợ biên phải ký trước tiết Sương giáng, mà bộ Hộ còn chần chừ vì giá muối."},{"who":"me","text":"Giá muối nằm trên bàn người mà quyết định cả một hiệp ước. Thật khó."},{"who":"A","text":"Nếu nhà {goi} có người ở triều, {xung} chỉ xin một lời nhắn đến đúng tay, để sứ đoàn khỏi phải về tay không."},{"who":"me","text":"Lời nhắn đúng người, đúng lúc là đủ. {Xung} sẽ lo, hoặc nhờ người trong cung, hoặc nhờ người nhà."}]}},
{"id":"nr:nc_su_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chợ muối kinh thành nhộn nhịp, mấy cửa hiệu cùng một biển hiệu treo cao, giá muối ghi trên bảng gỗ cứ nhích lên từng buổi."},{"who":"A","text":"Có kẻ đang thổi giá muối lên trong lúc hai bên bàn điều ước, mà người nhà {B} buôn muối ở kinh."},{"who":"me","text":"Thổi giá lên đúng lúc ấy thì chẳng phải trùng hợp. Nhưng không có bằng chứng thì không nói được."},{"who":"A","text":"{Goi} giúp {xung} xem họ đã gặp những quan nào của bộ Hộ. Biết rồi, {xung} mới biết nên làm gì."},{"who":"me","text":"Muốn biết thì phải có mắt ngoài chợ và tai trong cung. {Xung} sẽ chọn đường dò cho kín."}]}},
{"id":"nr:nc_su_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước quán sứ, xe ngựa đã thắng yên, bên cạnh là rương hành lý chồng lên nhau, bóng người lặng lẽ lướt qua cổng thành."},{"who":"A","text":"Ở cửa thành có người tâu xe sứ đoàn mang theo thứ không được phép mang. Huynh trưởng của {xung} chưa biết."},{"who":"me","text":"Xe sắp lăn bánh rồi, mà huynh ấy còn chẳng hay. Hẳn {goi} đang nóng ruột lắm."},{"who":"A","text":"{Xung} cần một lá thư đến tay huynh ấy trước khi xe đi, để huynh ấy bỏ lại thứ ấy."},{"who":"me","text":"Thư phải đến kịp, và đến kín. {Xung} sẽ chọn người đi sao cho không ai kịp ngăn."}]}},
{"id":"nr:nc_su_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong điện, chiếc hộp quà đáp lễ vừa ban còn đặt trên án, mùi sơn son mới phảng phất."},{"who":"A","text":"Hoàng thượng đã ban quà đáp lễ, giờ có người tâu xe sứ mang đồ cấm. Nếu người cho khám xe trước mặt dân, cả hai triều mất mặt."},{"who":"me","text":"Khám thì phải khám, nhưng khám ở đâu, trước mắt ai, mới là điều đáng bàn."},{"who":"A","text":"{Goi} xin Hoàng thượng cho khám kín trong quán sứ, như thế thể diện hai bên đều giữ được."},{"who":"me","text":"Khám giữa phố thì mất mặt, khám kín thì còn đường lui. {Xung} đang tìm người mở lời để Hoàng thượng dễ gật đầu."}]}},
{"id":"nr:nc_tuc_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng Nguyên đán, bộ lễ phục thêu phẩm cấp trải trên giường, bên cạnh là cây trâm bạc cố hương đã xỉn màu."},{"who":"A","text":"Lễ Nguyên đán, Nội vụ phủ bắt mọi người mặc lễ phục theo phẩm. {Xung} không dám trái lệ."},{"who":"me","text":"Lệ cung vốn nghiêm. Vậy {goi} muốn xin điều gì?"},{"who":"A","text":"{Xung} chỉ xin được cài một cây trâm cố hương trên tóc. {Goi} thưa với Hoàng hậu giúp {xung} một câu được không?"},{"who":"me","text":"Cây trâm xỉn màu kia, {xung} thấy {goi} vuốt mãi không rời. Xin một câu cho khéo, kẻo bị bảo là cãi lệ."}]}},
{"id":"nr:nc_tuc_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đáy tủ gỗ, rương áo cố hương nằm lặng lẽ, hương trầm cũ thoảng ra khi nắp hé mở."},{"who":"A","text":"Rương áo cố hương của {xung} nằm dưới đáy tủ, mà có người trong cung muốn đốt nó để tỏ lòng với Đại Hy."},{"who":"me","text":"Đốt áo cũ để tỏ lòng trung thì thật là cách làm lạnh lòng người."},{"who":"A","text":"{Xung} không nỡ. {Goi} giữ giùm rương áo ấy qua ngày Nguyên đán, được không?"},{"who":"me","text":"Giữ một rương áo không khó, chỉ cần chọn chỗ cất cho kín đáo. {Xung} sẽ lo liệu."}]}},
{"id":"nr:nc_tuc_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát canh sứ trắng còn nguyên trên khay, mặt canh trong veo, hơi nóng đã tan từ lâu."},{"who":"A","text":"Bát canh ở cung {xung} sạch như nước giếng, vậy mà cả cung đồn {xung} bỏ bùa. Thận hình ty chỉ cho một hạn ngắn."},{"who":"me","text":"Lời đồn đi nhanh hơn sự thật. {Goi} cần ai làm chứng?"},{"who":"A","text":"{Xung} cần một vị thái y chịu nghiệm lại bát canh ấy và nói thật điều tận mắt thấy."},{"who":"me","text":"Bát canh nguội ngắt mà tiếng đồn thì nóng hổi. Hạn của Thận hình ty ngắn lắm, phải tìm cho ra người dám nói thật."}]}},
{"id":"nr:nc_tuc_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong bếp nhỏ của cung, người hầu mới đứng sát bếp lò, tay lau mãi chiếc muôi đồng sáng loáng."},{"who":"A","text":"{B} ăn bát canh ở cung {xung} rồi nôn sốt, mà người hầu bếp hôm ấy lại do Nội vụ phủ mới đưa đến."},{"who":"me","text":"Người mới tới đúng ngày xảy chuyện, thật khó tin là trùng hợp."},{"who":"A","text":"{Goi} giúp {xung} biết người hầu bếp ấy trước kia ở cung {B} hay không. Chỉ cần thế."},{"who":"me","text":"Gốc gác một người không khó tra, chỉ là phải khéo. {Xung} sẽ dò theo hai ngả."}]}},
{"id":"nr:nc_tuc_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều hôm, bài vị tổ tiên đặt trên bàn nhỏ trong gian phòng sau, khói hương mong manh uốn quanh."},{"who":"A","text":"Lệnh soát cung sắp ban, mà trong cung {xung} có bài vị của tổ tiên. Người ta gọi đó là bàn thờ thần lạ."},{"who":"me","text":"Với {goi}, đó là tổ tiên, với người ngoài lại thành thần lạ. Quả là oan."},{"who":"A","text":"{Xung} không nỡ đốt. {Goi} cất giùm {xung} vài hôm, đến khi chuyện lắng xuống."},{"who":"me","text":"Khói hương còn mỏng mà lệnh soát cung sắp xuống. Bài vị tổ tiên nên nằm nơi nào cho kín đáo, {xung} phải chọn ngay."}]}},
{"id":"nr:nc_tuc_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm vừa xuống, ngọn đèn trong tẩm điện Hoàng thượng vẫn sáng, cung nữ bưng chén trà nguội lặng lẽ lui ra."},{"who":"A","text":"Hoàng thượng mất ngủ, người ta đổ cho bàn thờ của tổ tiên {xung}. {Xung} chỉ xin người nghe một lời trước khi lệnh soát cung ban xuống."},{"who":"me","text":"Một giấc ngủ không yên mà bị đổ cho người đã khuất. Thật oan cho cả hai phía."},{"who":"A","text":"{Goi} xin người ghé cung {xung} uống một chén trà. Chỉ một chén thôi."},{"who":"me","text":"Chén trà nguội ngoài tẩm điện, {xung} biết người đã trằn trọc cả đêm. Mời sao cho người đến mà không nghe như xin tội?"}]}},
{"id":"nr:nc_tuc_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ chép tay bị truyền qua nhiều cung, mép giấy đã quăn, chữ viết sắc như lưỡi dao."},{"who":"A","text":"Có tờ sớ ngoài triều nói người ngoại tộc không nên ở ngôi cao. Tên {xung} chưa nêu ra, nhưng ai cũng biết là ai."},{"who":"me","text":"Không nêu tên mà ai cũng biết, ấy là cách đâm khéo nhất."},{"who":"A","text":"{Xung} cần biết trong triều có những ai đứng sau tờ sớ ấy. {Goi} giúp {xung} một lần."},{"who":"me","text":"Biết tên rồi mới biết ai là bạn, ai là thù. {Xung} sẽ dò, hoặc nhờ người trong cung, hoặc nhờ người ngoài triều."}]}},
{"id":"nr:nc_tuc_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Từ Ninh cung, tiếng mõ đều đều vọng lại, Thái hậu ngồi bên cửa sổ nhìn đàn trẻ nhỏ chơi ngoài sân."},{"who":"A","text":"Tờ sớ nói người ngoại tộc không được tự nuôi hoàng tự. Thái hậu xưa nay thương trẻ nhỏ, một lời của bà nặng hơn trăm tờ sớ."},{"who":"me","text":"Thái hậu thương trẻ thì lòng bà dễ mềm. Chỉ cần chạm đúng chỗ."},{"who":"A","text":"{Goi} vào hầu, thưa giúp {xung} một câu. {Xung} không dám xin gì hơn."},{"who":"me","text":"Thái hậu nghe tiếng trẻ cười ngoài sân mà mềm lòng. Phải tìm đúng lúc, đúng cách để lời của {goi} chạm tới bà."}]}},
{"id":"nr:nc_tuc_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong tiểu điện, tượng Phật đản đặt trên bệ sen, bên cạnh là danh sách nghi thức dài mà nàng đọc mãi chưa hết."},{"who":"A","text":"Lễ Phật đản năm nay giao cho {xung} lo, mà {xung} chưa từng đứng một lễ nào theo phép nơi này."},{"who":"me","text":"Lễ lớn thế mà phép nơi đây còn lạ. {Goi} cần người chỉ dạy?"},{"who":"A","text":"Thái hậu có một vị ma ma thuộc lễ hơn ai hết. {Goi} xin giúp cho {xung} được theo học mấy buổi."},{"who":"me","text":"Học lễ thì phải cúi đầu xin người thạo. {Xung} đang tìm đường đến với bà ma ma sao cho vừa phép, vừa không phiền Thái hậu."}]}},
{"id":"nr:nc_tuc_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái chùa trong cung, hai hàng cung nữ lặng lẽ tập tụng, giọng cố hương ngân lên lạc lõng giữa nhịp mõ."},{"who":"A","text":"Lễ Phật đản cần hai người biết tụng kinh theo giọng Đại Hy. Người của {xung} chỉ biết giọng cố hương."},{"who":"me","text":"Kinh tụng sai giọng, lễ cũng mất trang nghiêm. Hẳn {goi} lo lắm."},{"who":"A","text":"{Goi} cho {xung} mượn hai cung nữ biết kinh đến hết ngày lễ, được không?"},{"who":"me","text":"Hai người tụng cho đúng giọng là đủ. {Xung} sẽ chọn người ngay trong cung hoặc nhờ người ngoài."}]}},
{"id":"nr:nc_tuc_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân nhà thế gia, rèm lụa buông xuống, người hầu đưa tới chiếc hộp gấm có đóng triện nhà họ."},{"who":"A","text":"Có một nhà thế gia muốn nhận {xung} làm nghĩa nữ. Ân ấy lớn, mà thứ gì lớn cũng có giá."},{"who":"me","text":"Ơn lớn đến bất ngờ thường kéo theo món nợ chưa nói ra."},{"who":"A","text":"Trước khi {xung} gật đầu, {goi} giúp {xung} biết nhà ấy muốn gì ở {xung}, và {B} có nhúng tay không."},{"who":"me","text":"Biết rồi mới dám nhận hay từ. {Xung} sẽ dò theo hai đường để khỏi bỏ sót."}]}},
{"id":"nr:nc_tuc_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư gửi mẫu thân còn nằm dang dở trên án, mực mới đã khô ở dòng đầu, dòng cuối bỏ trống."},{"who":"A","text":"Nhà thế gia ấy muốn nhận {xung} làm nghĩa nữ, mà mẫu thân {xung} ở cố quốc chưa hay. {Xung} không muốn bà nghe tin từ miệng người khác."},{"who":"me","text":"Tin về con gái nên đến từ chính con gái. {Goi} nghĩ rất phải."},{"who":"A","text":"{Goi} giúp {xung} gửi một lá thư về trước."},{"who":"me","text":"Dòng cuối thư còn bỏ trống, ấy là chỗ để một người mẹ yên lòng. Lá thư đi đường nào thì bà nhận được nguyên vẹn?"}]}},
{"id":"nr:nc_vuong_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, hộp ấn sách phong còn đóng kín, bên cạnh là tập tấu của phe thua chưa ráo mực."},{"who":"A","text":"Ngôi ở cố quốc đã có người ngồi, chỉ còn thiếu ấn sách phong. Phe thua đang xin Đại Hy đừng phong."},{"who":"me","text":"Một chiếc ấn mà quyết định cả cục diện một nước."},{"who":"A","text":"Một lời đến tai Hoàng thượng đúng lúc, cố quốc của {xung} yên được mười năm. {Goi} giúp {xung} nhắc ngài."},{"who":"me","text":"Chiếc ấn nằm yên trong hộp mà cả một nước đang chờ. Nhắc sao cho Hoàng thượng thấy là việc nước, chứ không phải lời nhờ riêng?"}]}},
{"id":"nr:nc_vuong_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quốc thư của tân vương nằm trên giá gỗ bộ Lễ, dải lụa vàng buộc chặt, lớp bụi mỏng phủ lên con dấu."},{"who":"A","text":"Quốc thư của tân vương đang nằm ở bộ Lễ. {Xung} cần biết vị quan nào đang giữ nó lại, và ông ta muốn gì để chịu đem lên ngự án."},{"who":"me","text":"Một tờ quốc thư mà bị giữ, ắt có người muốn đổi chác."},{"who":"A","text":"{Goi} có người quen ở bộ Lễ không?"},{"who":"me","text":"Có người quen thì dễ hỏi hơn. {Xung} sẽ chọn người thích hợp, nhờ trong cung hay nhờ người nhà."}]}},
{"id":"nr:nc_vuong_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài hiên, gió bấc thổi lật tấm bản đồ treo tường, hai trấn biên ở góc tây bắc bị gạch một nét son."},{"who":"A","text":"Binh bộ muốn nhân lúc cố quốc còn yếu mà đòi hai trấn biên, bộ Lễ muốn giữ hòa."},{"who":"me","text":"Một bên đòi đất, một bên giữ hòa, hai phía kéo cả triều đình."},{"who":"A","text":"Nếu nhà {goi} có người nói được trong triều, xin giúp {xung}. {Xung} chỉ xin một lời nhắn đến tay vị quan đứng về phía hòa."},{"who":"me","text":"Một lời nhắn nhẹ mà cần đúng đường. {Xung} sẽ chọn người đi, trong cung hay ngoài cung."}]}},
{"id":"nr:nc_vuong_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản đồ biên giới trải trên án, đầu ngón tay nàng dừng lại ở nơi có ba nét: ruộng, mỏ và con đường buôn."},{"who":"A","text":"Nhà {B} đứng sau Binh bộ đòi hai trấn biên. {Xung} cần biết họ được lợi gì từ hai trấn ấy, đất, mỏ hay đường buôn."},{"who":"me","text":"Đòi đất không vì nước, mà vì lợi nhà, thì phải bóc cho rõ."},{"who":"A","text":"{Goi} giúp {xung} dò một lần."},{"who":"me","text":"Muốn biết thì phải có người dò ngoài cung và tai nghe trong cung. {Xung} sẽ chọn đường kín nhất."}]}},
{"id":"nr:nc_vuong_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, gói thuốc lá khô xếp ngay ngắn bên lá thư đã niêm, mùi quế phảng phất."},{"who":"A","text":"Mẫu thân {xung} kẹt trong một tòa thành cũ, lương cạn, thuốc hết. Đường đèo chỉ còn đi được đến khi tuyết xuống."},{"who":"me","text":"Đường đèo sắp bị tuyết chặn, thời gian chẳng còn bao nhiêu."},{"who":"A","text":"{Xung} có bạc, chỉ thiếu một người mang được thuốc và thư ra khỏi cung."},{"who":"me","text":"Tuyết xuống là đóng đèo, chỉ còn ít ngày. {Xung} phải tìm cho ra người đủ gan mang thuốc và thư ra khỏi cung."}]}},
{"id":"nr:nc_vuong_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Ngự hoa viên, lá vàng rơi đầy trên bậc đá, bóng một người cung nữ đứng đợi cạnh lối đi quen của Hoàng thượng."},{"who":"A","text":"Mẫu thân {xung} kẹt trong thành, chỉ một đội quân nhỏ của Đại Hy là mở được đường. {Xung} không dám xin việc quân."},{"who":"me","text":"Việc quân là việc triều đình, hậu cung không được nhúng tay."},{"who":"A","text":"{Goi} chỉ cần kể với Hoàng thượng rằng trong thành ấy có một bà lão là thân mẫu của phi tần của người."},{"who":"me","text":"Một bà lão trong thành cũ, cũng là mẹ của một phi tần. Kể chuyện ấy ở đâu cho Hoàng thượng nghe mà không giống kể khổ?"}]}},
{"id":"nr:nc_vuong_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn ngự thư phòng, bản đồ núi non trải rộng, chỗ cố quốc bị che khuất bởi tập tấu chồng chất."},{"who":"A","text":"Hoàng thượng còn đắn đo chuyện xuất binh, và người chờ một người hiểu cố quốc nhất trong cung. {Xung} không dám tự xin vào chầu."},{"who":"me","text":"Xin vào chầu thì nghe như tranh công. Mà không nói thì cơ hội cũng mất."},{"who":"A","text":"{Goi} chỉ cần nói với người rằng có người biết đường núi bên ấy."},{"who":"me","text":"Tiến cử người biết đường núi, chứ không tiến cử mình. Lời ấy phải rơi vào tai Hoàng thượng lúc người đang mở bản đồ."}]}},
{"id":"nr:nc_vuong_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Từ Ninh cung, khói trầm bay chậm, Thái hậu lần tràng hạt, nghe tin biên ải như nghe một chuyện đã cũ."},{"who":"A","text":"Hoàng thượng còn đắn đo xuất binh, mà Thái hậu không muốn tốn quân vì nước khác."},{"who":"me","text":"Bà có lý của bà, mà {goi} cũng có nỗi niềm của {goi}."},{"who":"A","text":"{Xung} không xin bà đổi ý, chỉ xin bà đừng cản trước khi Hoàng thượng nghe đủ lời. {Goi} thưa giúp {xung}."},{"who":"me","text":"Thái hậu lần tràng hạt như chẳng nghe, nhưng bà vẫn nghe. Đến với bà dáng vẻ nào để bà chịu nghe hết lời?"}]}},
{"id":"nr:nc_vuong_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin bại trận bay về kinh, trong điện Khôn Ninh, nữ quan cầm tờ lệnh vừa ra, mặt nghiêm như sương."},{"who":"A","text":"Một cánh quân bị phục ở hẻm núi, và cả triều muốn đổ lỗi cho người cố quốc trong cung. Trung cung đã sai người đến hỏi."},{"who":"me","text":"Một cánh quân thua mà cả cung bị nghi. Chuyện này thật oan."},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp {xung}: một phi tần ở hậu cung không thể vẽ đường cho giặc."},{"who":"me","text":"Cả triều đang chờ có người gánh tội hẻm núi. Trung cung đã hỏi, nên lời thưa đầu tiên phải đến đúng tay Hoàng hậu."}]}},
{"id":"nr:nc_vuong_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án Binh bộ, tờ danh sách người dẫn đường bị lật nhàu, mép giấy còn dấu vân tay lấm mực."},{"who":"A","text":"Cánh quân bị phục ở hẻm núi, mà người dẫn đường lại là người Binh bộ chọn."},{"who":"me","text":"Người dẫn đường là người của Binh bộ, vậy sao lỗi lại đổ lên người cố quốc?"},{"who":"A","text":"{Xung} cần một bản danh sách người dẫn đường hôm ấy, để biết lỗi không ở người cố quốc."},{"who":"me","text":"Tờ danh sách nhàu nát ấy giữ cả sự thật. Chép được nó mà không ai hay, lỗi mới trả về đúng chỗ."}]}},
{"id":"nr:nc_vuong_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, hai tập tấu ngược chiều nằm cạnh nhau: một chia đôi cố quốc, một dẹp hẳn phe kia."},{"who":"A","text":"Hoàng thượng nói lần này người nghe {xung}, và chỉ nghe một lần. Trước khi nói, {xung} cần biết các quan đang nghiêng về đâu."},{"who":"me","text":"Chia đôi hay dẹp hẳn, hai đường dẫn tới hai kết cục khác nhau."},{"who":"A","text":"Nghe nói {B} cũng đang dò chuyện này. {Goi} có tai mắt ở tiền triều không?"},{"who":"me","text":"Tai mắt thì có, chỉ là phải khéo dùng. {Xung} sẽ dò theo hai ngả."}]}},
{"id":"nr:nc_vuong_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước buổi nói chuyện, nàng ngồi đọc đi đọc lại bản thảo lời tâu, hàng mực khô còn thơm."},{"who":"A","text":"Hoàng thượng nói chỉ nghe {xung} một lần. {Xung} sợ một lần ấy không đủ."},{"who":"me","text":"Một lần nói mà quyết định cả tương lai một nước, thật quá nặng."},{"who":"A","text":"{Goi} có thể xin Hoàng thượng cho {xung} nói ở Ngự thư phòng, có các đại thần cùng nghe, để lời {xung} không thành lời bên gối không?"},{"who":"me","text":"Một lần được nói mà bản thảo nào cũng thấy thiếu. {Goi} muốn nói ở nơi nào thì lòng thấy vững hơn?"}]}},
{"id":"nr:td_an_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhà kho Nội các nằm sâu sau hành lang đá, cánh cửa sắt khóa kín, chỉ có một ngọn đèn lồng chao nhẹ trong gió."},{"who":"A","text":"Bản sớ gốc vu cha {xung} năm ấy vẫn nằm trong kho Nội các, ấn Binh bộ trên đó là ấn giả."},{"who":"me","text":"Ấn giả mà nằm trong kho chính thức, hẳn có người lo giữ cho nó sống đến nay."},{"who":"A","text":"{Xung} cần biết thái giám nào đang giữ chìa khóa kho, và hắn có ăn bạc của {B} không."},{"who":"me","text":"Một chiếc chìa khóa mở ra cả vụ án. {Xung} sẽ dò hai đường, sao cho không ai biết có người hỏi."}]}},
{"id":"nr:td_an_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, quyển án lệ cũ trên giá nhuốm màu giấy ố, một trang đánh dấu bằng dải lụa vàng."},{"who":"A","text":"Bản sớ gốc có son phê của tiên đế. Chỉ Hoàng thượng mới mở được kho Nội các mà không ai dám hỏi."},{"who":"me","text":"Hoàng thượng mở kho thì không ai dám cản. Nhưng người phải tự muốn mở."},{"who":"A","text":"{Goi} khéo nhắc người một chuyện xưa có dấu ấn giả, để người tự muốn xem."},{"who":"me","text":"Muốn Hoàng thượng tự mở kho, phải để người tự thấy tò mò. Hạt giống ấy gieo vào lúc nào thì nảy?"}]}},
{"id":"nr:td_an_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sảnh Hình bộ, ngọn nến lụi dần bên chiếc bàn trống, trên giá chỉ còn một chồng hồ sơ phủ bụi."},{"who":"A","text":"Thư lại già ở Hình bộ ba tháng nữa phải đi biên viễn. Ông là người cuối cùng còn nhớ án nhà {xung}."},{"who":"me","text":"Người cuối cùng còn nhớ là người cuối cùng còn chứng. Mất ông thì mất cả một đoạn sự thật."},{"who":"A","text":"{Xung} cần một người ra ngoài chép lời ông, trước khi ông lên đường."},{"who":"me","text":"Phải đi gấp, và đi kín. {Xung} sẽ chọn người đi cho đúng, nhờ trong cung hay người nhà."}]}},
{"id":"nr:td_an_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng sau của một ngôi nhà nhỏ, người quản gia già đứng nép dưới mái hiên, tay ôm bọc đồ cũ."},{"who":"A","text":"Lão quản gia cũ của nhà {xung} đã về kinh, mà không có chỗ ở an toàn. Nhà kia đang tìm lão."},{"who":"me","text":"Lão là người nhà cũ, biết rõ bao chuyện. Tìm được lão cũng là tìm được một nhân chứng."},{"who":"A","text":"{Goi} cho lão ở tạm trong nhà người thân của {goi} ít hôm, được không?"},{"who":"me","text":"Lão quản gia ôm bọc đồ đứng dưới mái hiên, nhà kia đang tìm. Đêm nay lão ngả lưng ở đâu thì yên?"}]}},
{"id":"nr:td_an_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa cung hé mở, gió lùa vào làm đèn chao nghiêng, trên hành lang có tiếng bước chân lướt nhẹ rồi tắt."},{"who":"A","text":"Nhà kẻ thù đã biết {xung} đang gom chứng cứ. Họ không ra tay ngoài sáng, mà qua {B} và qua những người còn nợ ơn họ."},{"who":"me","text":"Họ không đánh trực diện mà đánh qua tay người khác. Thật khó phòng."},{"who":"A","text":"{Goi} giúp {xung} biết ai trong cung đang nhận lệnh của họ."},{"who":"me","text":"Biết ai là tai mắt thì mới biết nên tin ai. {Xung} sẽ dò theo hai ngả."}]}},
{"id":"nr:td_an_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Khôn Ninh cung, ngọn đèn hạc cao vừa thắp, nữ quan đặt chiếc khay rỗng xuống như chờ một lời tố cáo."},{"who":"A","text":"Nhà kẻ thù đã cài người vào cung, sắp vu cho {xung} tội trộm đồ. Trung cung sẽ phải xử."},{"who":"me","text":"Còn chưa xử mà đã có lời tố. Phải chặn từ trước."},{"who":"A","text":"{Goi} thưa trước với Hoàng hậu, để bà nghe {xung} trước khi nghe kẻ tố."},{"who":"me","text":"Chiếc khay rỗng đặt giữa điện như đang đợi lời tố. {Xung} phải đến trước kẻ kia, với dáng vẻ nào để Hoàng hậu tin?"}]}},
{"id":"nr:td_an_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, cuốn án cũ vừa được cung nữ dọn khỏi giá, vết mực trên bìa đã phai thành màu nâu."},{"who":"A","text":"Hoàng thượng có hỏi nhỏ {xung} một câu về án cũ, rồi im. {Xung} không đoán được ý người."},{"who":"me","text":"Hỏi nhỏ rồi im, ấy là còn đang cân nhắc."},{"who":"A","text":"Lúc {goi} hầu người, xin dò giúp người có muốn nghe chuyện ấy nữa không, trước khi sổ cũ bị đốt theo lệ."},{"who":"me","text":"Hoàng thượng hỏi nhỏ rồi im, ấy là còn lưỡng lự. Sổ cũ sắp đốt, dò ý người bằng cách nào cho khỏi lộ?"}]}},
{"id":"nr:td_an_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân sau Binh bộ, đống sổ cũ chất trên xe chờ đốt, một trang bìa bay lật trong gió."},{"who":"A","text":"Sổ xuất ấn của Binh bộ năm ấy sắp bị đốt theo lệ. {Xung} cần một người ngoài cung chép lại trang có ấn giả trước ngày đốt."},{"who":"me","text":"Trang giấy ấy là chứng cứ sống. Cháy rồi thì không còn gì."},{"who":"A","text":"{Goi} giúp {xung} tìm người ấy."},{"who":"me","text":"Phải có người tin cậy ngoài cung. {Xung} sẽ nghĩ nhờ ai thì ít bị để ý nhất."}]}},
{"id":"nr:td_an_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ xin xét lại án nằm gọn trong hộp sơn mài, đợi một lời gật đầu đủ mềm của người trên cao."},{"who":"A","text":"Tờ sớ xin xét lại án đã soạn xong. Án do tiên đế phê, xin xét lại là chạm đến chữ hiếu."},{"who":"me","text":"Chữ hiếu nặng hơn mọi tờ sớ. Phải xin sao cho không chạm vào chỗ đau."},{"who":"A","text":"Nếu Thái hậu không phật lòng, Hoàng thượng sẽ dễ gật đầu. {Goi} hầu Thái hậu, xin dọn đường giúp {xung}."},{"who":"me","text":"Chữ hiếu là chỗ đau của cả triều. Phải để Thái hậu tự thấy oan chứ không thấy mình bị ép, còn đường đến với bà thì {xung} phải chọn."}]}},
{"id":"nr:td_an_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, lịch ngày tốt mở sẵn, vài ngày bị khoanh bằng son, vài ngày gạch chéo vì kỵ lễ tiên đế."},{"who":"A","text":"Tờ sớ đã soạn, chỉ còn chọn ngày. Gần lễ của tiên đế thì chạm chữ hiếu, gặp dịp vui thì như phá cuộc vui."},{"who":"me","text":"Chọn ngày cũng là chọn lòng người. Ngày nào Hoàng thượng vui thì lời mới dễ lọt tai."},{"who":"A","text":"Có khi {goi} đoán ý Hoàng thượng được hơn {xung}. Xin dò giúp xem người vui vào ngày nào."},{"who":"me","text":"Ngày tốt thì lịch đã ghi, ngày lòng người rộng mở thì không sách nào chép. Nên hỏi ai trước?"}]}},
{"id":"nr:td_an_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ba nha môn xử án vừa họp, trước cổng công đường lính canh đứng chắn, phi tần không được bước qua bậc đá."},{"who":"A","text":"Ba nha môn xử án đã ngồi xét, mà phi tần không được ra công đường. Mọi lời của {xung} chỉ đến được tay các quan qua giấy."},{"who":"me","text":"Chỉ qua giấy thì phải có người đưa. Đưa đến tay ai là điều quan trọng."},{"who":"A","text":"{Xung} cần một người đưa tờ khai này đến tay vị Ngự sử còn ngay thẳng."},{"who":"me","text":"Vị Ngự sử ấy {xung} cũng đã nghe danh. Nhờ ai đưa cho kín là điều {xung} sẽ nghĩ."}]}},
{"id":"nr:td_an_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng phủ quan xét án mở hé, một chiếc kiệu nhỏ vừa rời đi, rèm lụa che kín, không rõ người ngồi bên trong."},{"who":"A","text":"Ba nha môn xử án đã ngồi xét, mà {B} lại sai người gặp riêng một vị quan xét án. {Xung} cần biết họ đã nói gì với nhau."},{"who":"me","text":"Gặp riêng trước phiên xét thì chẳng phải việc nhỏ."},{"who":"A","text":"{Goi} giúp {xung} một lần."},{"who":"me","text":"Phải có người dò từ phía ngoài, và có tai nghe từ phía trong. {Xung} sẽ chọn hướng nào kín hơn."}]}},
{"id":"nr:td_ke_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiệu cầm đồ cửa Tây im lìm dưới mưa, cuốn sổ cũ nằm trên quầy gỗ, một góc đã mục."},{"who":"A","text":"Năm ấy kẻ vu cha {xung} không có đủ bạc để mua thợ giả ấn. Bạc ấy đi qua một hiệu cầm đồ ở cửa Tây."},{"who":"me","text":"Dấu chân của đồng bạc còn lại trong sổ hiệu."},{"who":"A","text":"{Xung} cần biết người đến lấy bạc có dính đến nhà {B} không, trước khi sổ của hiệu bị đốt."},{"who":"me","text":"Mưa dội trước hiệu cầm đồ, mà cuốn sổ mục kia là thứ cuối cùng còn giữ dấu bạc. Ai đến đó được mà không bị nhìn?"}]}},
{"id":"nr:td_ke_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con đường quê dẫn về làng cũ, lão thủ sổ ngồi trước hiên, vẫn giữ thói quen nhìn trời đoán giờ."},{"who":"A","text":"Năm ấy bạc đi qua một hiệu cầm đồ, mà người giữ sổ hiệu ấy nay đã về quê."},{"who":"me","text":"Người giữ sổ còn nhớ, thì chuyện năm ấy chưa mất hẳn."},{"who":"A","text":"{Xung} cần một người tìm đến làng ông, hỏi xem ông còn nhớ khách nào đến lấy bạc."},{"who":"me","text":"Lão thủ sổ đoán giờ bằng trời, nhớ khách bằng lòng. Người tìm đến làng ông phải biết nghe hơn biết hỏi. Ai hợp việc ấy?"}]}},
{"id":"nr:td_ke_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngục tối, mâm cơm thuốc để nguyên trước song sắt, người nằm trong ấy chẳng động đũa."},{"who":"A","text":"Kẻ cầm dao năm xưa đang nằm trong ngục, và có người muốn hắn chết trước khi khai. {Xung} hận hắn, nhưng {xung} cần hắn sống."},{"who":"me","text":"Hận mà vẫn cần giữ mạng kẻ thù, thật là nghịch lý. Nhưng đó mới là người biết nhìn xa."},{"who":"A","text":"{Goi} có quen vị thái y nào chịu vào xem cơm thuốc của hắn không?"},{"who":"me","text":"Mâm cơm thuốc chẳng ai động đũa, mà đáng ngờ nhất lại chính bát ấy. Hắn phải sống để khai, {xung} cần ngay một người tin được."}]}},
{"id":"nr:td_ke_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ lệnh xử án vừa niêm yết, nét son còn tươi, ngoài cổng Hình bộ có người đứng đọc rồi lặng lẽ bỏ đi."},{"who":"A","text":"Kẻ cầm dao năm xưa sắp bị xử gấp, như có người muốn hắn câm mãi."},{"who":"me","text":"Xử gấp thì miệng hắn đóng lại vĩnh viễn."},{"who":"A","text":"{Xung} chỉ xin Hoàng thượng hoãn ngày xử mười hôm. Nếu có dịp hầu giá, xin {goi} nói giúp."},{"who":"me","text":"Mười ngày thôi, cũng đủ để lòng người đổi thay. {Xung} sẽ nghĩ xin trực tiếp hay nhờ quan Hình bộ."}]}},
{"id":"nr:td_ke_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ, cô cung nữ trẻ cúi mặt thu dọn chăn gối, tay run rẩy vì lạnh hay vì sợ chẳng rõ."},{"who":"A","text":"Trong cung {xung} đã có người bị mua, {xung} không biết còn tin được ai. Chỉ có Tiểu Hà là theo {xung} từ nhà."},{"who":"me","text":"Giữa bao ánh mắt dò xét, có một người theo từ ngày cũ là quý hơn vàng."},{"who":"A","text":"{Goi} cho Tiểu Hà sang ở nhờ ít hôm, đến khi {xung} biết ai là tai mắt."},{"who":"me","text":"Tiểu Hà run vì lạnh hay vì sợ, chưa ai biết. Nàng ở lại thì {goi} yên lòng, còn nàng thì yên được không?"}]}},
{"id":"nr:td_ke_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng cung, tên thị vệ mới đứng nghiêm, giọng nói còn pha tiếng quê mà ai cũng nhận ra."},{"who":"A","text":"Thị vệ canh cửa cung {xung} mới đổi người, mà người mới lại là đồng hương của {B}."},{"who":"me","text":"Đổi người đúng lúc ấy thì khó mà là ngẫu nhiên."},{"who":"A","text":"{Goi} giúp {xung} biết ai đã ký lệnh đổi thị vệ ấy."},{"who":"me","text":"Giọng quê của người mới ai cũng nghe ra, thế cũng là một dấu. Dấu ấy dẫn về tay ai ký lệnh, {xung} phải lần cho ra."}]}},
{"id":"nr:td_ke_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, lá thư viết cho vị phu nhân ngoài kinh vẫn chưa niêm, đầu bút còn ẩm mực, dòng chữ lạnh như sương."},{"who":"A","text":"Một người như hắn không chỉ hại nhà {xung}. Có một phu nhân ngoài kinh cũng mang thù với hắn."},{"who":"me","text":"Kẻ thù chung thì dễ thành đồng minh. Nhưng cũng phải cẩn thận."},{"who":"A","text":"{Xung} muốn gửi một lá thư cho bà, mà không để ai trong cung biết hai nhà đã nói chuyện."},{"who":"me","text":"Kẻ thù chung là sợi chỉ nối hai nhà, mà sợi chỉ nào cũng có thể bị cắt. Thư này giao cho tay nào mới giữ được kín?"}]}},
{"id":"nr:td_ke_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng hẻo lánh, người hầu cũ ngồi lặng im bên chiếc bọc vải, mắt nhìn ra cửa sổ như thể đang chờ một lệnh đuổi."},{"who":"A","text":"Phu nhân họ Trịnh muốn gửi vào cung một người hầu cũ biết chuyện, mà không thể để người ấy ở cung {xung}."},{"who":"me","text":"Người biết chuyện thì quý, nhưng cũng nguy. Ai cũng sẽ để ý tới nàng."},{"who":"A","text":"{Goi} nhận người ấy làm cung nữ ít lâu, được không?"},{"who":"me","text":"Người hầu cũ ngồi bên bọc vải như chờ lệnh đuổi. Nhận nàng là nhận cả mối, và mối ấy nên giữ ở đâu, {xung} chưa rõ."}]}},
{"id":"nr:td_ke_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Ngự hoa viên, mặt hồ lặng như gương, chiếc lương đình vắng người, như một chiếc bẫy chờ khách."},{"who":"A","text":"Cái bẫy đã giăng, chỉ cần Hoàng thượng có mặt đúng lúc kẻ đứng sau ra tay. {Xung} không có cách giữ chân người."},{"who":"me","text":"Hoàng thượng không phải người cứ nghe lời là đi. Phải có lý do tự nhiên."},{"who":"A","text":"{Goi} xin người đến Ngự hoa viên vào đúng buổi bẫy sập, đừng hỏi vì sao."},{"who":"me","text":"Đi mà không hỏi vì sao là lòng tin rất lớn. Hoàng thượng tin {goi} đến mức nào, {xung} chưa dám đoán."}]}},
{"id":"nr:td_ke_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, cổng cung của nàng ta vắng khách, chỉ có ngọn đèn nhỏ sáng sau tấm rèm xanh."},{"who":"A","text":"Mồi đã thả, mà {B} lại hay qua lại với người {xung} nghi đứng sau. Nếu nàng ta báo trước, bẫy sẽ hỏng."},{"who":"me","text":"Một lời báo trước là hỏng cả cuộc. Phải biết nàng ta gặp ai."},{"who":"A","text":"{Goi} giúp {xung} xem mấy hôm nay {B} gặp những ai."},{"who":"me","text":"Có thể nhờ người canh cửa, hoặc tự đến thăm dò lời. {Xung} sẽ nghĩ đường nào khéo hơn."}]}},
{"id":"nr:td_ke_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng Khôn Ninh cung vẫn mở, trên án nữ quan, một tập danh sách ra vào cung chờ chữ ký chấp thuận."},{"who":"A","text":"Người làm chứng của {xung} đã có, chỉ thiếu một lời cho phép vào cung khai. Trung cung nói được câu ấy."},{"who":"me","text":"Nhân chứng có rồi, chỉ cần một lời gật đầu."},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp {xung}, trước buổi triều hội đầu xuân."},{"who":"me","text":"Nhân chứng đã sẵn, chỉ còn một cái gật đầu của Trung cung. Xin thế nào để trước buổi triều hội Hoàng hậu thấy đáng gật?"}]}},
{"id":"nr:td_ke_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Từ Ninh cung, tiếng tụng kinh nhẹ vang, Thái hậu vẫn ngồi thẳng lưng, tay cầm tràng hạt nhìn ra ngoài sân."},{"who":"A","text":"Triều hội đầu xuân, kẻ kia đứng hàng đầu, mà Thái hậu xưa nay vẫn khen hắn. Nếu bà bênh, chứng cứ nào cũng nhẹ."},{"who":"me","text":"Một lời bênh của bà nặng hơn mọi chứng cứ."},{"who":"A","text":"{Goi} vào hầu, xin bà đừng nói gì trong buổi ấy."},{"who":"me","text":"Chỉ cần bà đứng ngoài trong buổi ấy là đủ. Chạm vào lòng bà ra sao để bà tự lùi một bước?"}]}},
{"id":"nr:td_song_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong tiểu viện vắng, nàng siết chặt lá thư báo tin từ biên ải, hơi thở nhẹ như sợ gió nghe thấy."},{"who":"A","text":"Chuyện tiểu đệ của {xung} còn sống đã lọt ra ngoài. {Xung} sợ người của {B} đã nghe."},{"who":"me","text":"Nhà kia sợ nhất điều gì, {goi} còn nhớ chứ?"},{"who":"A","text":"Nhà kia sợ nhất là con trai nhà bị hại lớn lên. {Goi} giúp {xung} biết tin ấy đã đến tai những ai."},{"who":"me","text":"Tin đi đến đâu thì nguy đến đó. {Xung} sẽ dò kín, hoặc nhờ người, hoặc tự để ý trong các buổi trà."}]}},
{"id":"nr:td_song_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, bản tấu của quan biên còn xếp dở, tên người lính trẻ nằm cuối dòng, nét chữ nhỏ như tơ."},{"who":"A","text":"Tin tiểu đệ của {xung} còn sống đã đến tai triều. Nếu Hoàng thượng nghe từ miệng nhà kia, người sẽ nghĩ nhà {xung} giấu tội."},{"who":"me","text":"Nghe từ người khác thì thành tội, nghe từ người nhà thì thành tình."},{"who":"A","text":"{Goi} kể trước với người, nói rằng tiểu đệ chỉ là một lính biên."},{"who":"me","text":"Lính biên nhỏ như hạt cát, mà nhà kia sẽ cố biến thành tảng đá. Kể sao để Hoàng thượng chỉ thấy hạt cát?"}]}},
{"id":"nr:td_song_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, một cung nữ đứng canh bên chiếc hộp thư đã khóa, ánh mắt thỉnh thoảng liếc về phía cổng."},{"who":"A","text":"Có kẻ đang săn thư của cung {xung} để đem bán. Một chữ lọt ra là tiểu đệ của {xung} mất mạng."},{"who":"me","text":"Thư mà thành món hàng, thì không thể tin đường nào nữa."},{"who":"A","text":"{Goi} cho thư của {xung} đi theo đường của cung {goi} một lần này thôi."},{"who":"me","text":"Thư thành món hàng, nên chỉ một lần đi sai đường là mất. Tiểu đệ ấy đang chờ tin, đường nào mới an ổn?"}]}},
{"id":"nr:td_song_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa Đông cung mở lúc hừng đông, tên gác cửa đứng khoanh tay, ống tay áo phồng lên như giấu thứ gì."},{"who":"A","text":"Thư của cung {xung} bị chặn ba lần, lần nào cũng ở cùng một cửa. Người gác cửa ấy hay nhận quà của {B}."},{"who":"me","text":"Ba lần cùng một cửa thì không phải ngẫu nhiên."},{"who":"A","text":"{Goi} giúp {xung} biết hắn đem thư đi bán cho ai."},{"who":"me","text":"Ống tay áo phồng kia giấu gì, {xung} muốn biết. Theo dấu hắn mà không để hắn hay, cần một người khéo chân."}]}},
{"id":"nr:td_song_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, trong ngự hoa viên, vài cung nữ thì thầm bên khóm hoa, hễ có người đến lại im bặt."},{"who":"A","text":"Có lời đồn sắp đến tai Hoàng thượng: con trai tội thần kết bè trong quân."},{"who":"me","text":"Lời đồn mà đến tai Hoàng thượng thì khó mà gỡ."},{"who":"A","text":"Nếu Hoàng thượng hỏi {goi} có biết gì không, xin đừng nói thêm một chữ. {Xung} chỉ xin sự im lặng ấy."},{"who":"me","text":"Lời đồn chưa đến tai Hoàng thượng thì còn kịp. Im lặng cũng là một cách che chở, nhưng che bằng cách nào?"}]}},
{"id":"nr:td_song_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phủ lão quan bộ Lễ treo đèn lồng cũ, trên án có tấm thiếp mời còn niêm, chữ ký đã mờ."},{"who":"A","text":"Lão quan bộ Lễ là đồng liêu cũ của cha {xung}, ông nhận ra tiểu đệ nhưng chưa nói."},{"who":"me","text":"Ông ấy chưa nói, nghĩa là lòng còn đắn đo."},{"who":"A","text":"{Xung} muốn gửi ông một lá thư, xin ông nhớ tình xưa mà im lặng."},{"who":"me","text":"Ông lão chưa nói, nghĩa là còn ngập ngừng. Lá thư nhắc tình xưa, ai mang đến thì ông mới mềm lòng?"}]}},
{"id":"nr:td_song_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nơi doanh trại biên ải, ngọn đèn dầu chao nghiêng bên chiếc giường tre, tiếng thở nặng của người lính vang lên trong đêm."},{"who":"A","text":"Tiểu đệ của {xung} trúng tên vào vai, quân y nói không sớm có thuốc tốt thì mất cánh tay."},{"who":"me","text":"Một cánh tay đối với người lính là cả cuộc đời."},{"who":"A","text":"Thuốc ấy chỉ Thái y viện có. {Goi} có quen thái y nào cắt giúp {xung} một hộp cao không?"},{"who":"me","text":"Vết tên ở vai không chờ ai. Cao thuốc ra đến biên ải kịp hay không, còn tùy tay người đưa."}]}},
{"id":"nr:td_song_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án Binh bộ, tờ lệnh điều quân còn thơm mùi mực mới, tên một đội nhỏ bị đặt lên tuyến đầu."},{"who":"A","text":"Có người đã ký lệnh đẩy đội của tiểu đệ {xung} lên tuyến đầu, và tên ấy dính đến nhà {B}."},{"who":"me","text":"Đẩy lên tuyến đầu mà không rõ lý do thì thật là mưu độc."},{"who":"A","text":"{Goi} giúp {xung} biết ai đã cầm bút."},{"who":"me","text":"Một chữ ký đẩy cả đội nhỏ ra tuyến đầu, kẻ cầm bút ắt để lại dấu. Dấu ấy {xung} phải lần từ đâu?"}]}},
{"id":"nr:td_song_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, tờ giấy trắng chờ điền họ tên mới, bên cạnh là quyển sổ hộ tịch cũ đã sờn gáy."},{"who":"A","text":"Hộ bộ sắp tra lại sổ hộ tịch. Tiểu đệ của {xung} cần một tờ hộ tịch mới, dưới một cái họ không ai nhớ."},{"who":"me","text":"Đổi họ là mất cả gốc rễ. Nhưng còn hơn mất mạng."},{"who":"A","text":"Nếu nhà {goi} có người quen ở huyện, {xung} chỉ cần một lời nhắn."},{"who":"me","text":"Một cái họ mới là một cuộc sống mới. Lời nhắn nhờ người quen ở huyện, trao vào tay ai thì mới êm?"}]}},
{"id":"nr:td_song_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân nhà dân, người lính trẻ vác củi giúp lão chủ, dáng đi vẫn còn nét quân nhân."},{"who":"A","text":"Hộ bộ sắp tra sổ hộ tịch, tiểu đệ của {xung} cần một chỗ đứng tên trong một nhà khác."},{"who":"me","text":"Một cái tên trong sổ nhà người ta cũng là một mái che."},{"who":"A","text":"{Goi} có thể cho tiểu đệ ghi tên làm gia nhân trong một nhà quen của {goi} không?"},{"who":"me","text":"Vác củi giúp lão chủ mà dáng quân nhân vẫn còn. Một cái tên trong sổ nhà lạ, tìm nhà nào cho tiểu đệ ấy nương thân?"}]}},
{"id":"nr:td_song_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, bảng đổi phiên các doanh biên đặt cạnh bản đồ kinh thành, tên người lính trẻ được khoanh nhẹ bằng bút son."},{"who":"A","text":"Các doanh biên đang đổi phiên, có thể xin cho tiểu đệ của {xung} về cấm quân ở kinh. Gần {xung}, cũng gần nhà kia."},{"who":"me","text":"Gần người nhà thì yên lòng, gần nhà kia thì cũng thêm hiểm nguy."},{"who":"A","text":"{Xung} muốn {goi} nói với Hoàng thượng một lời, để người tự quyết tiểu đệ của {xung} đứng ở đâu."},{"who":"me","text":"Gần kinh thì gần người thân, cũng gần nhà kia. Lời đến Hoàng thượng phải nhẹ, để người tự quyết chỗ đứng của tiểu đệ."}]}},
{"id":"nr:td_song_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Từ Ninh cung, bức họa tổ tiên treo cạnh cửa sổ, Thái hậu ngước nhìn như nhớ lại một thời đã xa."},{"who":"A","text":"Xin cho tiểu đệ về cấm quân là chuyện Binh bộ, nhưng Thái hậu thương con cháu nhà công thần cũ."},{"who":"me","text":"Công thần cũ thì còn có người nhớ. Nhất là khi người ấy là Thái hậu."},{"who":"A","text":"{Goi} vào hầu, nhắc bà rằng nhà {xung} từng có công."},{"who":"me","text":"Nhắc công cũ là nhắc lòng bà, chứ không đòi gì. Mở lời với Thái hậu thế nào để bà tự nhớ đến nhà {goi}?"}]}},
{"id":"nr:td_tha_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Khôn Ninh cung, con búp bê vải đặt trên khay lụa, kim châm đen ghim ở ngực, cả điện lặng như tờ."},{"who":"A","text":"Trung cung sắp hỏi chuyện con búp bê trù ếm. Cả cung chờ xem {xung} nói gì về con gái nhà đã hại nhà {xung}."},{"who":"me","text":"Ai cũng chờ nghe {goi} nói lời oán, nhưng lòng {goi} nghĩ gì?"},{"who":"A","text":"{Xung} chỉ muốn nói thật. {Goi} xin Hoàng hậu cho {xung} được nói sau cùng."},{"who":"me","text":"Ai cũng đợi nghe {goi} oán trách, mà {goi} lại chọn nói thật. Muốn được nói sau cùng, phải xin Hoàng hậu bằng lời nào?"}]}},
{"id":"nr:td_tha_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong kho cũ, rương đồ người đã khuất nằm phủ bụi, ổ khóa gỉ xanh còn nguyên dấu cạy."},{"who":"A","text":"Con búp bê trù ếm tìm thấy trong rương của người đã khuất, mà người mở rương là {B}."},{"who":"me","text":"Người mở rương lại là người tìm thấy, thật quá khéo."},{"who":"A","text":"{Xung} cần biết rương ấy đã nằm trong kho bao lâu, ai đã giữ chìa khóa."},{"who":"me","text":"Chiếc rương gỉ khóa có dấu cạy, mà {B} lại là người mở. Muốn lần ra ai giữ chìa, {xung} nên hỏi ai trước?"}]}},
{"id":"nr:td_tha_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, tờ sớ hặc tội đang chép dở, mực đen chưa ráo, cuối trang còn chừa chỗ ký tên."},{"who":"A","text":"Nhà {B} đang dâng sớ hặc nhà kia, và họ mời {xung} chung tay. {Xung} chưa trả lời."},{"who":"me","text":"Chung tay thì có thể bị cuốn vào vụ kiện. Chưa trả lời là phải."},{"who":"A","text":"{Goi} giúp {xung} biết trong tờ sớ ấy họ còn định kéo những ai xuống theo."},{"who":"me","text":"Biết trước danh sách thì mới biết nên đứng đâu. {Xung} sẽ dò bằng hai đường."}]}},
{"id":"nr:td_tha_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, tờ sớ chờ ký đang nằm bên đỉnh trầm, khói mỏng quấn quanh góc giấy."},{"who":"A","text":"Có một nhà mời {xung} chung tay dâng sớ. {Xung} không muốn chung tay, cũng không muốn bị coi là bênh nhà kia."},{"who":"me","text":"Đứng giữa mà vẫn muốn sạch, thật khó."},{"who":"A","text":"{Goi} khéo nói với Hoàng thượng rằng {xung} không dính vào tờ sớ nào."},{"who":"me","text":"Đứng ngoài tờ sớ mà không như chống ai, cần một câu thật nhẹ. Câu ấy nói ở nơi nào thì nhẹ nhất?"}]}},
{"id":"nr:td_tha_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phía sau cung, gian phòng nhỏ để trống từ lâu, bụi phủ mỏng trên chiếc án gỗ đơn sơ."},{"who":"A","text":"Con gái nhà kia nhắn muốn gặp {xung}. Gặp ở cung {xung} thì cả cung biết, gặp ở cung nàng ta thì {xung} không dám."},{"who":"me","text":"Chỗ gặp cũng quan trọng ngang chuyện sẽ nói."},{"who":"A","text":"{Goi} cho mượn một gian phòng sau cung {goi} trong một buổi tối."},{"who":"me","text":"Gian phòng bụi phủ, một buổi tối kín đáo là đủ. Cho mượn ở đâu thì không ai nghe tiếng bước?"}]}},
{"id":"nr:td_tha_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng nhỏ, cô gái nằm bên cửa sổ, sắc mặt tái nhợt, tay nắm chặt tấm chăn mỏng."},{"who":"A","text":"Con gái nhà kia muốn nói ra điều nàng giấu, nhưng nàng đã ốm mấy hôm vì sợ. Nếu nàng chết trước khi nói, không ai còn biết."},{"who":"me","text":"Nàng mà không còn, thì sự thật cũng chôn theo."},{"who":"A","text":"{Goi} mời giúp một thái y kín miệng xem bệnh cho nàng."},{"who":"me","text":"Nàng ốm vì sợ, nên thầy thuốc phải kín miệng. Ai bước vào phòng nàng mà không để ai dò ra?"}]}},
{"id":"nr:td_tha_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa cung, người đưa lời của nhà kia đứng chờ, tay cầm hộp sơn son đựng giấy tờ ruộng hương hỏa."},{"who":"A","text":"Người của nhà kia đến đưa lời: trả ruộng hương hỏa, thêm một rương bạc, đổi lấy tờ lời khai."},{"who":"me","text":"Một lời đề nghị hậu hĩnh. Nhưng {goi} đã nghĩ gì?"},{"who":"A","text":"{Xung} đã có câu trả lời. {Goi} giúp {xung} đưa nó ra tay người đưa lời, đừng để ai đọc trước."},{"who":"me","text":"Rương bạc hay ruộng hương hỏa, {goi} đều đã có câu trả lời riêng. Lá thư ấy phải đến tay người đưa lời mà không lọt qua mắt ai."}]}},
{"id":"nr:td_tha_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, bản đồ ruộng đất cũ mở sẵn, một khoảnh ruộng nhỏ được khoanh bằng bút son."},{"who":"A","text":"Nhà kia đòi đổi ruộng hương hỏa lấy tờ lời khai. {Xung} không bán."},{"who":"me","text":"Ruộng hương hỏa là phần của tổ tiên, sao bán được."},{"who":"A","text":"Nhưng nếu Hoàng thượng biết ruộng ấy vốn của nhà {xung}, người có thể trả lại mà không cần mặc cả. {Goi} nhắc người giúp."},{"who":"me","text":"Ruộng hương hỏa vốn là của nhà {goi}, trả về là phải đạo. Nhắc Hoàng thượng thế nào để không giống đòi lại?"}]}},
{"id":"nr:td_tha_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm giỗ cha mẹ, ngọn nến trắng đặt trước bàn thờ, hương khói quyện trong hơi lạnh của gió thu."},{"who":"A","text":"Đêm giỗ cha mẹ {xung}, con gái nhà kia xin đến thắp một nén hương. Mà {B} có tai mắt khắp nơi."},{"who":"me","text":"Thắp nén hương cũng phải e dè người dõi theo, thật bất công."},{"who":"A","text":"{Goi} cho người của {goi} sang canh cửa giúp {xung} một đêm."},{"who":"me","text":"Canh cửa đêm giỗ là việc nhỏ, nhưng người canh phải đáng tin. Ai là người ấy, {xung} phải chọn kỹ."}]}},
{"id":"nr:td_tha_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mâm trà bánh bày trước bàn thờ, hơi nóng vừa bốc lên, đĩa bánh còn nguyên chưa ai động đến."},{"who":"A","text":"Đêm giỗ, con gái nhà kia muốn thắp hương, mà nàng sợ có người bỏ thuốc vào trà. {Xung} không muốn có chuyện trong đêm ấy."},{"who":"me","text":"Đêm giỗ mà có chuyện thì mang tiếng cả hai nhà."},{"who":"A","text":"{Goi} nhờ thái y nghiệm trước trà bánh giúp {xung}."},{"who":"me","text":"Đĩa bánh còn nguyên chưa ai động đến, nên cũng chưa ai chịu tin. Nghiệm cho kín thì tìm ai bây giờ?"}]}},
{"id":"nr:td_tha_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong điện Hoàng thượng, tờ sớ tố cáo trải rộng trên án, hàng chữ nhắc đến hai chữ khi quân đỏ như vết máu."},{"who":"A","text":"Nhà kia tâu {xung} là con gái tội thần đổi tên vào cung, tội khi quân. {Xung} không chối thân thế."},{"who":"me","text":"Không chối thân thế, nhưng cũng không nhận tội."},{"who":"A","text":"{Xung} chỉ xin {goi} nói với Hoàng thượng: người vào cung là {xung}, chứ không phải tội của cha."},{"who":"me","text":"Họ có thể viết hai chữ khi quân đỏ như máu, nhưng người vào cung vẫn là {goi}. Lời ấy nói ở chỗ nào mới đến được Hoàng thượng?"}]}},
{"id":"nr:td_tha_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ tú nữ năm ấy mở trên án, trang giấy ố vàng, bên cạnh là tờ khai viết bằng nét chữ lạ."},{"who":"A","text":"Tờ sớ tâu {xung} đổi tên vào cung có kèm một tờ khai của thái giám giữ sổ tú nữ năm ấy."},{"who":"me","text":"Một tờ khai mà quyết định số phận. Phải xem ai là người viết."},{"who":"A","text":"{Xung} nghi {B} đã mua lời khai ấy, xin {goi} dò giúp xem bạc đi qua tay ai."},{"who":"me","text":"Tờ khai lạ nét chữ, lại do người giữ sổ viết ra. Lần theo đồng bạc, {xung} nên bắt đầu từ ai?"}]}},
{"id":"nr:ch_co_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, tờ danh sách cô mẫu giao nằm trên khay, một cái tên được khoanh tròn bằng bút son."},{"who":"A","text":"Cô mẫu muốn {xung} làm tai mắt cho Đức Thọ cung, mà trong danh sách có cả cung {goi}. {Xung} không muốn."},{"who":"me","text":"Làm tai mắt cho bề trên mà phải nhìn vào cung bạn, thật khó xử."},{"who":"A","text":"Xin {goi} theo {xung} đến thỉnh an cô mẫu một buổi, để {xung} có chuyện vô hại mà thưa."},{"who":"me","text":"Thỉnh an cô mẫu một buổi cho vô hại, nghe thì dễ. Nhưng đi cùng {goi}, cái tên khoanh son kia phải che thế nào?"}]}},
{"id":"nr:ch_co_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sổ tai mắt cô mẫu giao, chữ viết ngay ngắn, một cái tên bị chép đi chép lại như có người cố nhớ."},{"who":"A","text":"Trong danh sách tai mắt cô mẫu giao có người của cung {B}."},{"who":"me","text":"Người của {B} lại có tên trong sổ của cô mẫu. Chuyện này không đơn giản."},{"who":"A","text":"{Xung} cần biết người ấy đã báo những gì về Đức Thọ cung trước khi {xung} nhận việc."},{"who":"me","text":"Một cái tên bị chép đi chép lại, như có người cố nhớ. {Xung} muốn biết người của {B} ấy đã nói gì, và nghe được từ ai."}]}},
{"id":"nr:ch_co_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án Đức Thọ cung, quyển sổ mở dở, một trang bị xé đi, mép giấy còn lởm chởm như bị giật vội."},{"who":"A","text":"Một trang trong sổ của Đức Thọ cung biến mất, mấy tai mắt của cô mẫu bị lộ tên. {Xung} sẽ bị hỏi trước tiên."},{"who":"me","text":"Mất trang sổ thì kẻ cầm nó nắm trong tay nhiều người."},{"who":"A","text":"{Goi} giúp {xung} biết có phải người của {B} đã cầm trang sổ ấy không."},{"who":"me","text":"Trang giấy bị xé, mép còn lởm chởm, kẻ giật vội hẳn còn run. Dò từ phía nào thì ra người cầm?"}]}},
{"id":"nr:ch_co_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng sau Đức Thọ cung, nàng cung nữ run rẩy ngồi bên cửa, mắt đỏ hoe, tay nắm chặt vạt áo."},{"who":"A","text":"Một cung nữ tai mắt của cô mẫu bị lộ, người ta sắp đánh nàng để tra. Nàng chỉ làm theo lệnh."},{"who":"me","text":"Một người chỉ vâng lệnh mà phải chịu đòn thay. Thật tội."},{"who":"A","text":"{Goi} cho nàng ấy lánh sang chỗ {goi} ít hôm."},{"who":"me","text":"Nàng chỉ vâng lệnh mà phải chịu đòn, {xung} không nỡ đứng nhìn. Giấu nàng ở đâu cho khỏi bị tra tới?"}]}},
{"id":"nr:ch_co_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, hai phong thư niêm hai màu khác nhau đặt cạnh nhau, một đỏ của Đức Thọ cung, một vàng của Hoàng thượng."},{"who":"A","text":"Cùng một ngày, cô mẫu nhờ {xung} một việc, Hoàng thượng nhờ {xung} một việc, mà hai việc ngược nhau."},{"who":"me","text":"Hai phía kéo một người, thật là thế khó."},{"who":"A","text":"{Xung} không muốn Hoàng thượng nghĩ {xung} là người của Đức Thọ cung. {Goi} nói với người giúp: {Xung} vẫn ở bên người."},{"who":"me","text":"Phong đỏ, phong vàng nằm sát nhau như hai bàn tay kéo về hai phía. Lời đáp phải đến tai người cần nghe trước."}]}},
{"id":"nr:ch_co_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án Đức Thọ cung, tấm lệnh bài của Cửu môn đề đốc đặt cạnh chiếc hộp son, bên cạnh là tờ thiếp mời nhà ngoại."},{"who":"A","text":"Cô mẫu muốn chức Cửu môn đề đốc, người giữ các cửa kinh thành, về tay nhà ngoại, Hoàng thượng muốn người của người. {Xung} kẹt ở giữa."},{"who":"me","text":"Chức ấy giữ cả cửa kinh thành, ai cũng muốn nắm."},{"who":"A","text":"{Goi} thưa với cô mẫu rằng {xung} không đủ sức xoay việc triều."},{"who":"me","text":"Cửa kinh thành ai cũng muốn nắm, mà {goi} chỉ muốn rút tay. Từ chối thế nào để cô mẫu không thấy mình bị chê?"}]}},
{"id":"nr:ch_co_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn Đức Thọ cung, ngón tay cô mẫu gõ nhẹ lên tay vịn, giọng nói trầm như sương, ra lệnh mà chẳng cần lớn tiếng."},{"who":"A","text":"Cô mẫu bảo {xung} ra tay với {B}. {Xung} không làm. Nhưng nếu {xung} không làm, sẽ có người khác làm."},{"who":"me","text":"Từ chối chưa đủ, phải biết ai sẽ làm thay."},{"who":"A","text":"{Goi} giúp {xung} biết cô mẫu còn giao việc ấy cho ai."},{"who":"me","text":"Từ chối rồi, vẫn còn người khác cầm lấy việc ấy. Biết người đó là ai thì {xung} mới biết phòng ở đâu."}]}},
{"id":"nr:ch_co_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong ngự thư phòng, nghiên mực chưa khô, vài tờ tấu chờ chép lại, bên cạnh là chiếc ghế trống dành cho người hầu mực."},{"who":"A","text":"Cô mẫu giao cho {xung} một lệnh khó mà {xung} không muốn làm. Chỉ khi Hoàng thượng giao cho {xung} một việc ở bên người, cô mẫu mới không sai được {xung}."},{"who":"me","text":"Có việc ở bên Hoàng thượng thì không ai dám điều. Quả là một lối thoát."},{"who":"A","text":"Xin {goi} khéo tiến cử {xung} hầu người ở Ngự thư phòng ít lâu."},{"who":"me","text":"Chiếc ghế trống bên nghiên mực kia, nếu có tên {goi}, cô mẫu sẽ không sai được nữa. Tiến cử bằng cách nào cho khéo?"}]}},
{"id":"nr:ch_co_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cửa Đức Thọ cung đóng chặt, nàng đứng ngoài bậc thềm, tay nắm chặt vạt áo, ánh mắt nhìn vào hiên cung tĩnh lặng."},{"who":"A","text":"{Xung} đã từ chối cô mẫu. Đức Thọ cung sẽ coi {xung} như người dưng, hoặc tệ hơn."},{"who":"me","text":"Từ chối bề trên là cắt đứt một đường. Nhưng đây là điều {goi} chọn."},{"who":"A","text":"{Goi} vào hầu, xin nói đỡ một lời: {Xung} không phản bà, {xung} chỉ không làm được việc ấy."},{"who":"me","text":"Cửa cung đóng chặt, nghĩa là bà còn giận. Lời đỡ nên đến từ miệng nào thì bà mới chịu nghe?"}]}},
{"id":"nr:ch_co_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong cung của nàng, người hầu cũ do cô mẫu ban đứng nép bên cửa, nhìn quanh như người sắp phải lên đường."},{"who":"A","text":"{Xung} đã từ chối cô mẫu, người hầu cũ bà ban cho {xung} sắp bị gọi về. Nàng ấy biết nhiều chuyện của {xung}."},{"who":"me","text":"Người biết nhiều chuyện mà quay về thì thành mối nguy."},{"who":"A","text":"{Goi} nhận nàng ấy sang hầu cung {goi}, để nàng không phải về Đức Thọ cung."},{"who":"me","text":"Người biết nhiều chuyện thì đừng để về nơi nhiều tai. Cho nàng nương thân ở đâu thì yên ổn nhất?"}]}},
{"id":"nr:ch_co_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thọ yến Đức Thọ cung sắp bày, sơ đồ chỗ ngồi trải trên án, tên nàng nằm sát bên cô mẫu, nét chữ đậm hơn các tên khác."},{"who":"A","text":"Thọ yến Đức Thọ cung, chỗ của {xung} xếp ngay cạnh cô mẫu. Ai nhìn vào cũng thấy {xung} là quân cờ."},{"who":"me","text":"Ngồi cạnh bề trên là vinh, nhưng cũng là bị đóng dấu."},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp, cho {xung} ngồi chỗ khác."},{"who":"me","text":"Chỗ ngồi sát cô mẫu như dấu son đóng lên người. Muốn đổi chỗ mà không mang tiếng chê tiệc, phải đi qua cửa nào?"}]}},
{"id":"nr:ch_co_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa tiệc thọ, chén ngọc chạm nhau lanh canh, người ngồi sát bên nàng nghiêng đầu như đang lắng nghe chuyện của kẻ khác."},{"who":"A","text":"Tin về tờ sớ đã lọt ra từ thọ yến, mà người ngồi gần nhất là người của {B}."},{"who":"me","text":"Tin lọt ra ở bàn tiệc, nghĩa là có người nghe được mà không ai hay."},{"who":"A","text":"{Goi} giúp {xung} biết tin ấy đã truyền qua những ai."},{"who":"me","text":"Chén ngọc chạm nhau lanh canh, mà tin cứ thế lọt ra. Lần ngược từ bàn tiệc, {xung} nên bắt đầu từ ai?"}]}},
{"id":"nr:ch_benh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án, hai toa thuốc nằm cạnh nhau, một của Thái y viện, một của lương y ngoài cung, nét chữ khác nhau, vị thuốc cũng khác."},{"who":"A","text":"Thái y viện kê một phương, lương y ngoài cung kê một phương khác. Cô mẫu chỉ uống được một."},{"who":"me","text":"Hai phương khác nhau, mà chỉ một người đúng. Chọn sai thì hại mạng."},{"who":"A","text":"{Xung} cần một vị thái y kín miệng xem giúp phương nào đúng, mà không để viện biết {xung} hỏi."},{"who":"me","text":"Hai toa thuốc, một mạng người, mà cả viện đang nhìn. Nhờ ai xem giúp mà không ai hay, đó là chỗ {xung} phải cân."}]}},
{"id":"nr:ch_benh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, chén thuốc của viện còn nguyên trên khay, hơi nóng đã tan, cô mẫu quay mặt về phía cửa sổ."},{"who":"A","text":"Cô mẫu không chịu uống thuốc của Thái y viện, chỉ tin phương của lương y ngoài cung. {Xung} khuyên không được."},{"who":"me","text":"Bề trên cứng lòng thì lời con cháu khó vào."},{"who":"A","text":"{Goi} vào hầu, thưa với bà một lời. Có khi bà nghe người ngoài hơn nghe cháu."},{"who":"me","text":"Cô mẫu quay mặt về cửa sổ, không chịu nhìn chén thuốc. Lời khuyên nào mới lọt vào lòng bà?"}]}},
{"id":"nr:ch_benh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung vắng bớt khách, bậc cửa lặng ngắt, ngược lại cửa cung {B} người ra kẻ vào tấp nập."},{"who":"A","text":"Cô mẫu vừa lâm bệnh, đã có người đổi chỗ dựa. {Xung} muốn biết những ai đang lui tới cung {B} nhiều hơn trước."},{"who":"me","text":"Người ta đổi hướng gió rất nhanh. Phải biết ai đã đổi."},{"who":"A","text":"Nếu {goi} có tai mắt, xin giúp {xung} một lần."},{"who":"me","text":"Bậc cửa Đức Thọ cung vắng lạnh, cửa cung {B} thì nườm nượp. Muốn biết ai đổi hướng gió, {xung} nên bắt đầu từ đâu?"}]}},
{"id":"nr:ch_benh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án Hoàng thượng, tờ tấu xin giao việc lục cung cho người khác nằm dưới cùng chồng giấy, mép đã quăn."},{"who":"A","text":"Cô mẫu lâm bệnh, có người đã xin Hoàng thượng giao việc lục cung cho kẻ khác. {Xung} không xin quyền, chỉ xin người đợi cô mẫu khỏi."},{"who":"me","text":"Đợi thì còn có lòng. Nhưng chờ đợi lại khó trong lúc người ta đang tranh giành."},{"who":"A","text":"{Goi} nói giúp {xung} một lời."},{"who":"me","text":"Chỉ xin hoãn, chẳng xin quyền. Lời ấy tâu lúc nào, qua miệng ai, Hoàng thượng mới coi là lòng thành?"}]}},
{"id":"nr:ch_benh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc gian phòng, mảnh bã thuốc sẫm màu được gói trong tờ giấy bản, mùi vị lạ vẫn còn vương lại."},{"who":"A","text":"Chén thuốc của cô mẫu có vị lạ. {Xung} đã giữ lại chút bã."},{"who":"me","text":"Giữ bã thuốc là có lòng. Nhưng không ai tin nếu không có người nghiệm."},{"who":"A","text":"Để trong cung {xung} thì người ta sẽ nói {xung} bày chuyện. {Goi} cất giùm, đến khi có người nghiệm."},{"who":"me","text":"Gói bã thuốc nhỏ như vậy mà giữ cả một lời oan. Gửi nó ở nơi nào thì không ai tìm ra?"}]}},
{"id":"nr:ch_benh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong bếp thuốc, ba cung nữ đứng im bên lò sắc, ai cũng cúi đầu tránh ánh mắt của người đối diện."},{"who":"A","text":"Chén thuốc có vị lạ đi qua tay ba người, một trong số đó hay đến cung {B}."},{"who":"me","text":"Ba người bưng thuốc, một người có dây dưa. Đúng là đáng ngờ."},{"who":"A","text":"{Goi} giúp {xung} biết người ấy đã gặp ai trước khi bưng thuốc."},{"who":"me","text":"Ba người cúi đầu bên lò sắc, ai cũng tránh ánh mắt. Hỏi được ai trong số ấy mà không đánh động hai người còn lại?"}]}},
{"id":"nr:ch_benh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên giường bệnh, cô mẫu thở nhẹ, người đã kiệt sức, còn nàng ngồi tựa thành giường, mắt thâm quầng."},{"who":"A","text":"Cô mẫu không cho {xung} rời giường bệnh, đã bảy đêm {xung} không chợp mắt. {Xung} không dám xin ai thay."},{"who":"me","text":"Bảy đêm không ngủ, lưng còn thẳng đã là phi thường."},{"who":"A","text":"Chỉ có {goi} là cô mẫu không chê. Một đêm thôi."},{"who":"me","text":"Bảy đêm thức trắng mà {goi} chưa than một tiếng. Muốn thay một đêm, phải xin bà bằng lời nào?"}]}},
{"id":"nr:ch_benh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đêm khuya, cô mẫu trở mình khẽ rên, bàn tay xoa lưng vẫn không giảm cơn đau."},{"who":"A","text":"Cô mẫu đau lưng, mỗi đêm thức giấc mấy lần, ngự y chỉ kê thuốc uống."},{"who":"me","text":"Thuốc uống không giảm đau thì phải đổi phương."},{"who":"A","text":"{Xung} nghe nói có vị thái y giỏi châm cứu chưa từng được gọi. Nếu {goi} quen ông ấy, xin mời giúp."},{"who":"me","text":"Mỗi đêm trở mình mấy lần, nghe mà xót. Vị thái y giỏi châm cứu kia, mời ông thế nào để viện không phật ý?"}]}},
{"id":"nr:ch_benh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Thái y viện, danh sách vị thuốc dài dằng dặc, một vị bị gạch đỏ, ghi chú nhỏ bên lề: chỉ có ở hiệu phương nam."},{"who":"A","text":"Bệnh của cô mẫu trở nặng, Thái y viện nói còn thiếu một vị thuốc chỉ có ở hiệu thuốc phương nam."},{"who":"me","text":"Thiếu một vị mà cả toa thuốc thành vô dụng."},{"who":"A","text":"{Xung} có bạc. {Xung} chỉ cần người mang được thư ra ngoài, mà không qua sổ của Nội vụ phủ."},{"who":"me","text":"Vị thuốc chỉ có ở phương nam, mà đường ra ngoài lại qua sổ Nội vụ phủ. Ai đi được mà không bị ghi tên?"}]}},
{"id":"nr:ch_benh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Khôn Ninh cung, con dấu của Trung cung nằm cạnh hộp son, tờ phiếu lĩnh thuốc chờ đóng ấn."},{"who":"A","text":"Vị thuốc cứu mạng phải qua sổ Nội vụ phủ, mà Trung cung giữ con dấu."},{"who":"me","text":"Chỉ một cái dấu thôi mà nặng như núi."},{"who":"A","text":"{Xung} cần Hoàng hậu đóng dấu thật sớm, xin {goi} vào Khôn Ninh cung thưa giúp."},{"who":"me","text":"Một con dấu đóng sớm hay muộn một ngày là chuyện sống chết. Lời nhờ ấy đến Khôn Ninh cung bằng cửa nào cho gấp?"}]}},
{"id":"nr:ch_benh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm cuối thu, Đức Thọ cung ngập mùi thuốc, cô mẫu thều thào gọi tên Hoàng thượng, tay run bắt lấy tấm chăn."},{"who":"A","text":"Thái y viện nói bệnh cô mẫu đã đến hồi nguy kịch. Cô mẫu cứ hỏi đến Hoàng thượng, mà {xung} không dám tự đi mời."},{"who":"me","text":"Khi người sắp ra đi thì chỉ mong gặp người mình thương."},{"who":"A","text":"Nếu {goi} gặp được người, xin mời người đến Đức Thọ cung, dù chỉ một khắc."},{"who":"me","text":"Cô mẫu thều thào gọi tên Hoàng thượng, lòng {xung} cũng nôn nao. Mời được người đến đúng lúc, phải nhờ ai?"}]}},
{"id":"nr:ch_benh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ bên Đức Thọ cung, hai tiểu công chúa ngồi bên nhau, ôm chiếc gối thêu, mắt nhìn ra cửa chờ người."},{"who":"A","text":"Bệnh cô mẫu đã đến hồi nguy kịch, các tiểu công chúa cô mẫu nuôi không ai trông. {Xung} không thể rời giường bệnh."},{"who":"me","text":"Trẻ nhỏ không hiểu chuyện, cần có người ở bên cho yên lòng."},{"who":"A","text":"{Goi} trông giúp các tiểu công chúa một đêm."},{"who":"me","text":"Hai đứa trẻ nhìn ra cửa chờ người, nhìn mà thương. Đêm nay các cháu nên ngủ ở nơi nào cho yên lòng?"}]}},
{"id":"nr:ch_ho_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng thỉnh an, hành lang Khôn Ninh cung thoảng khói trầm, {A} đứng lặng bên bức bình phong, tay nắm chặt khăn lụa."},{"who":"A","text":"{Goi}, ở Đức Thọ cung cháu nào được gọi vào trước là cả cung đều nhìn. Cô mẫu lại hay theo thứ tự thỉnh an ở Khôn Ninh cung."},{"who":"me","text":"Chuyện thứ tự thì Hoàng hậu là người xếp. Sao {goi} không tự mình thưa với bà?"},{"who":"A","text":"{Xung} không dám. Người cháu kia vốn được ưu ái, {xung} sợ vừa mở lời đã thành kẻ tranh giành. Xin {goi} thưa giúp, cho {xung} được đứng theo ngôi."},{"who":"me","text":"Đã vậy, {xung} sẽ cân nhắc nên thưa thẳng với Hoàng hậu, hay nhờ người quen việc trong cung hỏi giúp."}]}},
{"id":"nr:ch_ho_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, hương sen thoảng qua rèm, {A} ngồi nép dưới cửa sổ, ngón tay vân vê vạt áo."},{"who":"A","text":"{Goi}, người cháu kia đã được gọi vào trước ba lần liền. {Xung} không tranh, chỉ sợ cô mẫu quên mất {xung}."},{"who":"me","text":"Thái hậu thương cả hai cháu, sao {goi} lại nghĩ bà quên?"},{"who":"A","text":"Lòng người ai chẳng đổi theo người ở gần. {Goi} vào hầu, chỉ cần nhắc tên {xung} một câu là đủ."},{"who":"me","text":"Chỉ sợ bà quên mà thôi, nghe {goi} nói mà {xung} thấy chạnh lòng. Một câu nhắc tên, nhắc thế nào cho bà thấy lòng thành?"}]}},
{"id":"nr:ch_ho_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước thềm cung, {A} ôm một cuộn chỉ ngũ sắc, mắt thâm quầng như người thức mấy đêm liền."},{"who":"A","text":"{Goi}, lễ mừng thọ cô mẫu sắp đến mà người cháu kia đã đặt xong một bức bình phong thêu. {Xung} không muốn thua."},{"who":"me","text":"Thêu bình phong cần cả một xưởng người. {Goi} định lấy ai ra để thêu cho kịp?"},{"who":"A","text":"Nếu cung {goi} có cung nữ thêu giỏi, xin cho {xung} mượn mười hôm. Mười hôm thôi, {xung} nhớ ơn suốt đời."},{"who":"me","text":"Lòng hiếu thảo của {goi} {xung} hiểu. Để {xung} xem là cho mượn người, hay mua giùm một tấm thêu sẵn."}]}},
{"id":"nr:ch_ho_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn đổ xuống kho cung, {A} đứng trước hòm quà mừng thọ, ngón tay lần theo một đường vải bị xé rách."},{"who":"A","text":"{Goi}, quà mừng thọ của {xung} để trong kho mà mới đây đã bị xé mất một góc. Chìa khóa kho chỉ ba người giữ."},{"who":"me","text":"Ba người giữ chìa thì kẻ làm chuyện này không khó tìm. {Goi} nghi ai?"},{"who":"A","text":"Một trong ba người ấy hay lui tới cung {B}. {Xung} chỉ muốn biết người ấy đã vào kho lúc nào."},{"who":"me","text":"Góc quà bị xé, chìa khóa chỉ ba người giữ, vết xé ấy còn mới. {Xung} muốn truy ra mà không để kẻ kia hay."}]}},
{"id":"nr:ch_ho_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua hành lang Đức Thọ cung, {A} tìm đến, môi tái đi như vừa nghe một lời nặng nề."},{"who":"A","text":"{Goi}, có người gièm với cô mẫu rằng {xung} mong bà sớm khuất để được ngồi ghế trên. Lời ấy độc lắm."},{"who":"me","text":"Chuyện hiếu đạo mà bị đem ra gièm, ai nghe cũng đau lòng. Thái hậu đã nói gì chưa?"},{"who":"A","text":"Bà chưa nói, nhưng mắt bà đã lạnh. {Goi} đến Đức Thọ cung, xin nói đỡ cho {xung} một câu."},{"who":"me","text":"Mắt Thái hậu đã lạnh thì lời đỡ nào cũng phải mang theo lòng thành. {Xung} nhận lời; chỉ còn cách đến trước mặt bà."}]}},
{"id":"nr:ch_ho_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, đèn trong thiên điện chập chờn, {A} ngồi một mình bên ấm trà nguội, nghe gió lay cửa."},{"who":"A","text":"{Goi}, lời gièm đến tai cô mẫu qua một ma ma già đã hầu bà mười năm. Ma ma ấy hay nhận quà của {B}."},{"who":"me","text":"Mười năm hầu hạ thì lời bà nói, Thái hậu hẳn tin. Bà ma ma ấy đã gièm những gì, {goi} nghe được lời nào chưa?"},{"who":"A","text":"Muốn biết bà ta đã nói những gì với cô mẫu. Chỉ cần biết thế, {xung} mới biết nên gỡ từ đâu."},{"who":"me","text":"Bà ma ma ấy nhận quà của {B}, mà lời gièm lại chạy qua miệng bà. Gỡ từ đầu dây nào mới khỏi động đến bà?"}]}},
{"id":"nr:ch_ho_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng nhỏ, {A} ngồi bên cửa sổ, bút chưa dứt đã đặt xuống, phong thư đợi sẵn trên án."},{"who":"A","text":"{Goi}, các trưởng bối họ ngoại sắp họp ở phủ Quốc cữu để chọn một người cháu trong cung. {Xung} không ra khỏi cung được."},{"who":"me","text":"Cổng cung đóng chặt, mà việc họ ngoại thì không đợi ai. {Goi} muốn nhắn gì?"},{"who":"A","text":"Một lá thư gửi phụ thân, phải đến tay ông trước buổi họp. Xin {goi} giúp {xung} gửi đi."},{"who":"me","text":"Thư ra khỏi cung phải qua tay người kín miệng. {Xung} sẽ xem nên dùng người trong cung, hay người nhà."}]}},
{"id":"nr:ch_ho_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, bên hồ sen sau cung, {A} khẽ vuốt cánh hoa héo, ánh mắt xa xăm hướng về phía phủ Quốc cữu."},{"who":"A","text":"{Goi}, các trưởng bối họ ngoại sẽ chọn người cháu được Hoàng thượng thương hơn. {Xung} không xin ân sủng."},{"who":"me","text":"Không xin ân sủng, vậy {goi} mong điều gì?"},{"who":"A","text":"Chỉ cần để ngài nhắc tên {xung} một lần trước mặt người nhà họ ngoại, thế thôi."},{"who":"me","text":"Họ ngoại chọn cháu qua một cái tên nghe được từ miệng Hoàng thượng. Tên ấy rơi nhẹ hay rơi nặng, còn tùy ai nhắc."}]}},
{"id":"nr:ch_ho_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân, gió cuốn lá vàng xoay tròn, {A} cầm một mảnh giấy ghi vội mấy dòng tin truyền từ ngoài triều."},{"who":"A","text":"{Goi}, Ngự sử đài hặc họ ngoại chuyên quyền, nêu tên cả phủ Quốc cữu lẫn nhà người cháu kia."},{"who":"me","text":"Tờ sớ ấy đụng đến cả hai nhà. {Goi} đang lo điều gì?"},{"who":"A","text":"{Xung} cần biết tờ sớ nói những gì, để biết nên đứng chung hay đứng riêng. Từ trong cung, {xung} không với tới được."},{"who":"me","text":"Bản sớ nằm ngoài tầm tay {goi}, nghe mà {xung} cũng bất an. Ai là người hỏi được mà không để lộ?"}]}},
{"id":"nr:ch_ho_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối buổi chiều, {A} đứng bên ngưỡng cửa ngự thư phòng, bàn tay nắm chặt tờ sớ chép lại."},{"who":"A","text":"{Goi}, tờ sớ hặc họ ngoại nêu tên cả nhà {xung} lẫn nhà người cháu kia. {Xung} không xin Hoàng thượng bỏ qua."},{"who":"me","text":"Vậy {goi} xin điều gì, thưa {A}?"},{"who":"A","text":"Chỉ xin ngài xét từng nhà một, đừng phạt chung. {Goi} nói giúp {xung}."},{"who":"me","text":"Lời này nói không khéo thì thành bênh vực họ ngoại. {Xung} sẽ cân nhắc nên nói thẳng, hay nhờ quan Ngự sử đài."}]}},
{"id":"nr:ch_ho_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên Đức Thọ cung, mưa nhỏ rơi tí tách, {A} đứng trước chiếc ghế bên cạnh ngai của Thái hậu mà không dám nhìn."},{"who":"A","text":"{Goi}, cô mẫu muốn {xung} ngồi chiếc ghế bên cạnh bà. {Xung} không muốn vì chiếc ghế ấy mà bị người cháu kia oán ghét."},{"who":"me","text":"Ghế ấy là phúc phần, cũng là mối họa. {Goi} muốn {xung} làm gì?"},{"who":"A","text":"Thưa với cô mẫu giúp {xung}, để bà đừng ép. {Xung} không dám cãi lời bà."},{"who":"me","text":"{Goi} từ chối chiếc ghế ấy là biết giữ mình, mà bà vốn thương {goi}. Lời từ chối, đưa thế nào để bà vẫn thấy lòng hiếu?"}]}},
{"id":"nr:ch_ho_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước yến tiệc lục cung, trong điện Khôn Ninh, {A} chỉnh lại vạt áo, ánh mắt lướt qua dãy ghế đã xếp sẵn."},{"who":"A","text":"{Goi}, chiếc ghế bên Thái hậu là chuyện của Đức Thọ cung, nhưng ở yến tiệc lục cung thì Trung cung xếp chỗ."},{"who":"me","text":"Đã vậy thì {goi} muốn xin điều gì?"},{"who":"A","text":"Xin xếp {xung} ngồi sau người cháu kia. {Xung} không muốn bị đẩy lên trước, rồi bị ghen ghét."},{"who":"me","text":"Chỗ ngồi sau người cháu kia cũng là một cách tự giữ. {Xung} nhận lời đưa việc này đến Trung cung, chỉ còn chọn lối vào."}]}},
{"id":"nr:ch_bi_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, ánh nến trong thiên điện lung lay, {A} đặt lên án một mảnh giấy cũ, đầu ngón tay run nhẹ."},{"who":"A","text":"{Goi}, bản sao lá thư cũ của cô mẫu đã đến tay Hoàng thượng một lần. Kẻ dâng thư chỉ là người bị sai đi."},{"who":"me","text":"Một lá thư năm xưa mà còn bay đến tận ngự án. {Goi} nghi ai?"},{"who":"A","text":"{Xung} nghi người của {B} đã đem thư vào cung. {Xung} cần biết điều ấy trước khi có bản thứ hai."},{"who":"me","text":"Truy đường thư phải thật kín. {Xung} sẽ xem nên sai người dò, hay tự hỏi những người gác cửa."}]}},
{"id":"nr:ch_bi_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hành lang vắng, {A} đi lại lặng lẽ, mắt không rời cánh cửa ngự thư phòng đóng kín."},{"who":"A","text":"{Goi}, bản sao lá thư đã đến tay Hoàng thượng một lần mà ngài chưa nói gì. {Xung} không biết ngài nghĩ sao về cô mẫu."},{"who":"me","text":"Im lặng của bậc đế vương còn đáng sợ hơn lời trách. {Goi} thấy Hoàng thượng im lặng vì giận, hay vì đang cân nhắc?"},{"who":"A","text":"Ngài còn giận hay không. {Goi} hầu ngài, dò giúp {xung} một lời."},{"who":"me","text":"Tờ thư đã đến tay Hoàng thượng mà người chưa nói gì, {xung} nghe cũng nặng lòng. Dò ý bậc chí tôn, đi lối nào mới khỏi động?"}]}},
{"id":"nr:ch_bi_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, {A} ngồi bên án thư, trước mặt là một phong thư chưa dán, mực còn ướt."},{"who":"A","text":"{Goi}, có một người cháu nhà họ Lâm nay làm ở Hàn lâm viện, vừa gửi vào cung một lời hăm dọa."},{"who":"me","text":"Hăm dọa bằng chuyện gì? Và {goi} định đáp thế nào?"},{"who":"A","text":"{Xung} muốn viết cho hắn trước, nói rằng còn có đường khác. Xin {goi} giúp {xung} đưa thư ra."},{"who":"me","text":"Lời hăm dọa từ Hàn lâm viện đến cung, giấy chưa khô mực. Thư đáp phải đi thật kín, qua tay ai {goi} tin?"}]}},
{"id":"nr:ch_bi_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới bóng cây ngô đồng, {A} đứng đợi, tay nắm chặt cánh cửa nhỏ khép hờ."},{"who":"A","text":"{Goi}, Lâm Khải ở Hàn lâm viện gửi lời hăm dọa, mà người đưa lời vào cung lại là người quen của {B}."},{"who":"me","text":"Hai bên quen nhau thì không phải chuyện nhỏ. Họ quen nhau từ bao giờ, {goi} có hay không?"},{"who":"A","text":"Biết hai bên đã gặp nhau mấy lần. {Xung} cần rõ điều ấy trước khi đáp lời hắn."},{"who":"me","text":"Người đưa lời lại quen với {B}, chuyện ấy không phải ngẫu nhiên. Muốn rõ họ đã gặp nhau mấy lần, dò theo lối nào?"}]}},
{"id":"nr:ch_bi_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong điện Đức Thọ, trầm hương lượn lờ, {A} đứng trước cửa phòng Thái hậu, bàn tay run nhẹ."},{"who":"A","text":"{Goi}, cô mẫu gọi {xung} đến hỏi chuyện chiếc hộp thư, mà {xung} chưa biết nên nói đến đâu."},{"who":"me","text":"Hỏi chuyện hộp thư thì lời nào cũng nặng. {Goi} muốn {xung} làm gì?"},{"who":"A","text":"{Goi} đi cùng {xung} một buổi. Có người thứ ba ngồi đó, cô mẫu sẽ hỏi nhẹ hơn."},{"who":"me","text":"Có người thứ ba ngồi cạnh, lời hỏi của bà hẳn nhẹ đi. {Xung} sẽ đi cùng {goi}, nếu {goi} thấy nên đến ngay hôm nay."}]}},
{"id":"nr:ch_bi_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tối muộn, trong gian phòng nhỏ khuất sau cung {A}, một bà lão ngồi nép bên ngọn đèn dầu."},{"who":"A","text":"{Goi}, cô mẫu hỏi chuyện hộp thư, mà Đàm ma ma, người làm chứng năm xưa, lại đang ở cung {xung}."},{"who":"me","text":"Nếu cô mẫu gọi ma ma đi thì sao?"},{"who":"A","text":"Nếu bà gọi, {xung} không giữ được. Xin {goi} cho Đàm ma ma lánh sang cung {goi} ít hôm."},{"who":"me","text":"Đàm ma ma là người cuối còn nhớ chuyện năm xưa, bị gọi đi thì {xung} cũng không đành. Che chở bà thế nào cho kín?"}]}},
{"id":"nr:ch_bi_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên rương gỗ đã mở trống, {A} cúi nhìn tấm lót nhung còn hằn dấu một chiếc hộp gấm."},{"who":"A","text":"{Goi}, chiếc hộp gấm đựng bản sao thư đã biến mất khỏi cung {xung}. Ai cầm nó, người ấy cầm Đức Thọ cung trong tay."},{"who":"me","text":"Hộp ấy mà lọt ra ngoài thì nguy lắm. {Goi} nghi ai?"},{"who":"A","text":"{Xung} nghi người của {B}. Xin {goi} giúp {xung} dò trước khi nó ra khỏi hậu cung."},{"who":"me","text":"Hộp gấm biến khỏi cung trong đêm, cửa ngõ còn chưa kịp đóng. Muốn chặn nó, nên canh từ đâu?"}]}},
{"id":"nr:ch_bi_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tối, trong sảnh nhỏ, {A} đứng nhìn rương trống, bàn tay xoắn chặt đuôi khăn."},{"who":"A","text":"{Goi}, chiếc hộp gấm biến mất khỏi cung {xung}. Muốn khám các cung khác phải có lệnh của Trung cung."},{"who":"me","text":"Khám cung là việc lớn, Hoàng hậu có chịu cho không?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu, xin bà cho khám kín trước khi hộp ra khỏi hậu cung."},{"who":"me","text":"Lệnh khám cung chỉ Trung cung ban được. {Goi} thấy nên thưa thế nào để bà gật đầu mà không hỏi vào trong hộp?"}]}},
{"id":"nr:ch_bi_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn trên mái ngói, {A} bước vào, mắt hoe đỏ, trong tay là chiếc khăn đã nhàu."},{"who":"A","text":"{Goi}, Hoàng thượng đã bắt đầu hỏi về chuyện năm xưa. Nếu ngài hỏi đến {goi}, xin chỉ nói điều tận mắt thấy, đừng đoán thêm."},{"who":"me","text":"Chỉ nói điều mình thấy, {xung} hiểu. Nhưng vì sao {goi} lo đến vậy?"},{"who":"A","text":"Một chữ đoán sai là cô mẫu của {xung} không còn đường lui."},{"who":"me","text":"Điều tận mắt thấy thì nói, điều mình ngờ thì giữ lại. {Xung} ghi nhớ lời dặn, chỉ lo lúc Hoàng thượng hỏi, lời mình ra sao."}]}},
{"id":"nr:ch_bi_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, {A} đứng im, ánh mắt dán vào hộp gấm đặt trên bàn nhỏ."},{"who":"A","text":"{Goi}, lá thư cũ có thể bảo vệ cô mẫu, cũng có thể hại bà. {Xung} muốn hỏi chính cô mẫu muốn {xung} làm gì."},{"who":"me","text":"Vậy sao {goi} chưa hỏi?"},{"who":"A","text":"{Xung} không dám mở lời. {Goi} vào hầu bà, mở lời giúp {xung}."},{"who":"me","text":"Hỏi cô mẫu của {goi} muốn gì là chạm vào nỗi đau cũ, {xung} hiểu vì sao {goi} ngại. Mở lời với bà, bắt đầu từ đâu?"}]}},
{"id":"nr:ch_bi_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước tiết Thanh minh, trong cung {A}, gió mang theo mùi hương khói từ chùa xa, {A} cầm một bao giấy cuộn kín."},{"who":"A","text":"{Goi}, bản sao cuối của lá thư đang ở trong tay {xung}. Cung {xung} sẽ bị soát nếu có biến."},{"who":"me","text":"Vậy {goi} muốn gửi lại ở đâu?"},{"who":"A","text":"Xin {goi} giữ giùm ít hôm, đến khi {xung} quyết đốt hay dâng."},{"who":"me","text":"Bản sao cuối cùng nằm trong tay {goi}, cửa cung đã sắp có người soát. Giữ nó ở đâu cho yên?"}]}},
{"id":"nr:ch_bi_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm Thanh minh sắp đến, {A} đứng bên cửa sổ nhìn về phía cửa Ngự sử đài, bóng người lờ mờ trong sương."},{"who":"A","text":"{Goi}, người của {B} hay chờ ở cửa Ngự sử đài. {Xung} cần biết họ chờ Lâm Khải hay chờ một người khác."},{"who":"me","text":"Chờ người nào thì tính đường nào, khác nhau nhiều. Họ đứng đó từ bao giờ, {goi} có thấy ai ra vào không?"},{"who":"A","text":"Biết họ chờ ai, và đã gặp được ai. {Xung} cần biết trước tiết Thanh minh."},{"who":"me","text":"Người của {B} đứng đợi ở cửa Ngự sử đài, chờ ai thì {xung} muốn biết trước tiết Thanh minh. Dò bằng cách nào mới kín?"}]}},
{"id":"nr:thd_tho_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ngọn đèn thư phòng, {A} cầm tờ thơ chép tay, mực còn thơm, đầu mày nhíu lại."},{"who":"A","text":"{Goi}, Hàn lâm viện mở kỳ Xuân thí, mà người giữ danh sách dự thí lại là chú của {B}. Tên {xung} có thể biến mất trước khi ai đọc đến thơ."},{"who":"me","text":"Một bài thơ hay mà không đến được tay người chấm thì uổng công. Vị học sĩ nào {goi} muốn đọc thơ của mình?"},{"who":"A","text":"Thơ của {xung} phải đến tay một vị học sĩ khác. Ngoài cung, {xung} không có ai để nhờ."},{"who":"me","text":"Danh sách dự thí nằm trong tay chú của {B}, tên {goi} có thể rơi mất. Thơ phải đến một vị học sĩ khác, bằng đôi tay nào?"}]}},
{"id":"nr:thd_tho_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa sổ ngự hoa viên, {A} đứng nhìn từng cánh hoa rơi, trong tay là bài thơ còn dang dở."},{"who":"A","text":"{Goi}, danh sách dự thí do chú của một phi tần khác giữ. {Xung} chỉ mong Hoàng thượng nói một câu: thơ phi tần ai cũng được dự."},{"who":"me","text":"Chỉ một câu thôi, mà phải đợi đúng lúc Hoàng thượng vui. {Goi} nghĩ lúc nào là hợp?"},{"who":"A","text":"Khi {goi} hầu ngài trò chuyện, khẽ nhắc giúp {xung}. Đừng để ngài nghĩ {xung} đang xin điều gì cho riêng mình."},{"who":"me","text":"Lời nhắc ấy nhẹ mà nặng. {Xung} sẽ tìm dịp tâu thẳng, hoặc nhờ thái giám Ngự thư phòng nhắc thay."}]}},
{"id":"nr:thd_tho_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư trống, {A} lật hết ngăn kéo, chỉ còn lại một tờ giấy lót vàng úa."},{"who":"A","text":"{Goi}, tập thơ nháp {xung} chép từ thuở ở quê đã biến mất khỏi án thư. Không có nó, {xung} không chứng được bài nào do {xung} viết."},{"who":"me","text":"Một tập thơ nháp mà đáng giá thế sao? Đêm nào nó mất?"},{"who":"A","text":"Đêm vừa rồi. {Goi} giúp {xung} hỏi xem đêm ấy người của {B} có vào phòng không."},{"who":"me","text":"Tập thơ viết từ thuở ở quê mà mất, {xung} nghe cũng xót. Hỏi người trực đêm thế nào để họ khỏi giấu?"}]}},
{"id":"nr:thd_tho_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên song cửa, {A} ngồi hồi lâu, tay giữ chồng thư cũ buộc dây gai, nét chữ của cha nghiêng nghiêng."},{"who":"A","text":"{Goi}, tập thơ nháp mất rồi, còn lại mấy bức thư của cha có chép thơ {xung}. {Xung} sợ chúng cũng mất."},{"who":"me","text":"Thư của cha là thứ không thể mua lại được. {Goi} muốn giữ ở đâu?"},{"who":"A","text":"Xin {goi} cất giùm mấy bức thư ấy đến ngày yết bảng. Đến lúc ấy {xung} sẽ lấy lại."},{"who":"me","text":"Thư của cha có chép thơ {goi}, mỗi nét còn nguyên mực cũ. Giữ ở nơi nào mới yên đến ngày yết bảng?"}]}},
{"id":"nr:thd_tho_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều xuân ở Ngự hoa viên, nén hương đã cắm sẵn trên án, {A} đứng bên bàn thi, ngón tay lạnh buốt."},{"who":"A","text":"{Goi}, vòng thi ở Ngự hoa viên, một nén hương một bài. Hoàng thượng ngồi trên, chưa chắc nghe hết."},{"who":"me","text":"Nếu Hoàng thượng không nghe thì bài hay cũng thành uổng. {Goi} muốn gì?"},{"who":"A","text":"Nếu {goi} ngồi gần ngài, khi đến bài của {xung}, xin khẽ nhắc ngài lắng tai."},{"who":"me","text":"Nhắc nhẹ mà không thiên vị, {xung} sẽ cố. Chỉ lo thái giám hầu giá nhắc sai bài thì thành trò cười."}]}},
{"id":"nr:thd_tho_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, bên án thi, {A} nhìn nghiên mực đen bóng, cung nữ đứng cạnh run run bàn tay."},{"who":"A","text":"{Goi}, vòng thi ở Ngự hoa viên, mỗi người được đem theo một người mài mực. Người của {xung} run tay."},{"who":"me","text":"Mực loãng một chút là chữ đã mất vẻ. {Goi} muốn nhờ gì?"},{"who":"A","text":"Cho {xung} mượn cung nữ mài mực khéo nhất cung {goi} một buổi. Chỉ một buổi."},{"who":"me","text":"Tay run thì mực loang, mà vòng thi chỉ có một buổi. Người mài mực nào mới làm {goi} yên lòng?"}]}},
{"id":"nr:thd_tho_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Khôn Ninh cung, {A} cầm mấy trang chép tay đề ngày cũ, ánh mắt như người sắp nghe lời tuyên án."},{"who":"A","text":"{Goi}, người ta tố {xung} đạo thơ, chứng là mấy trang chép tay đề ngày ba năm trước. Trung cung sẽ hỏi chuyện này."},{"who":"me","text":"Giấy ba năm trước mà nét mực lại còn mới? {Goi} định thế nào?"},{"who":"A","text":"{Xung} chỉ xin {goi} thưa với Hoàng hậu cho người soi lại giấy và mực của mấy trang ấy."},{"who":"me","text":"Giấy mực không biết nói dối, nhưng lời thưa phải khéo, kẻo Hoàng hậu ngỡ {xung} bênh người bị tố. {Xung} nhận lời; chọn lối thưa là việc kế tiếp."}]}},
{"id":"nr:thd_tho_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm muộn, {A} soi tờ giấy dưới ngọn đèn, thấy dấu nước của Nội vụ phủ hằn lên mặt giấy."},{"who":"A","text":"{Goi}, mấy trang chép tay đề ngày ba năm trước, giấy lại là giấy mới của Nội vụ phủ năm nay."},{"who":"me","text":"Giấy mới mà đề ngày cũ, rõ là có người sửa. {Goi} nghi ai?"},{"who":"A","text":"{Xung} cần biết ai đã xin loại giấy ấy, mà {xung} nghi người của {B}."},{"who":"me","text":"Giấy mới của năm nay mà đề ngày ba năm trước, chỉ một sổ phát giấy là rõ. Tra sổ ấy bằng cách nào?"}]}},
{"id":"nr:thd_tho_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên bàn học, {A} mở một hộp gỗ nhỏ trống rỗng, nét mặt thoáng vẻ bất lực."},{"who":"A","text":"{Goi}, Hàn lâm viện cho {xung} nộp chứng qua tay thái giám Ngự thư phòng. Thư của cha {xung} còn nằm ở quê."},{"who":"me","text":"Từ kinh về quê và trở lại thì xa lắm. Còn kịp ngày yết bảng không?"},{"who":"A","text":"Chỉ khi có người đi ngay. {Xung} cần một người ra ngoài, mang thư về kịp."},{"who":"me","text":"Việc này không thể chậm. {Xung} sẽ bỏ bạc nhờ thái giám, hoặc nhờ người nhà về quê lấy giúp."}]}},
{"id":"nr:thd_tho_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên Hàn lâm viện, {A} nhìn tập chứng cứ dày cộp bó trong lụa vàng, bàn tay nắm lại."},{"who":"A","text":"{Goi}, chứng cứ thơ là của {xung} chỉ đến tay Hàn lâm viện, mà ở đó có chú của {B}."},{"who":"me","text":"Chứng cứ đến tay người nhà địch thì khó giữ nguyên vẹn. {Goi} muốn gì?"},{"who":"A","text":"Xin Hoàng thượng tự đọc tập chứng. {Goi} xin ngài giúp {xung}."},{"who":"me","text":"Chứng cứ đã nằm gần tay nhà đối địch, nghĩ đến mà {xung} bồn chồn. Làm sao để chính Hoàng thượng cầm được tập chứng ấy?"}]}},
{"id":"nr:thd_tho_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hôm trước ngày yết bảng, {A} đứng bên cổng cung, nhìn xe ngựa qua lại, lòng nặng trĩu."},{"who":"A","text":"{Goi}, bảng Xuân thí sắp dán. {Xung} nghe nói {B} đã sai người đến nhà các học sĩ chấm thơ."},{"who":"me","text":"Nếu là thật thì bảng đã nghiêng về một phía. {Goi} nghe tin ấy từ đâu?"},{"who":"A","text":"Biết nàng ta đã đến những nhà nào. {Goi} giúp {xung} dò kịp trước khi bảng dán."},{"who":"me","text":"Bảng sắp dán mà người của {B} đã ghé các nhà học sĩ, bước chân còn mới. Muốn biết nàng ấy ghé nhà nào, hỏi từ ai?"}]}},
{"id":"nr:thd_tho_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều ngày yết bảng, Đức Thọ cung ngát hương hoa lan, {A} ôm tập thơ chép tay, đứng trước hiên mà chưa dám bước vào."},{"who":"A","text":"{Goi}, ngày yết bảng, ai đứng đầu tập Ngự tuyển thì Thái hậu ban một chiếc trâm. Nếu bà hỏi đến bài của {xung}, bảng khó bị sửa."},{"who":"me","text":"Thái hậu hỏi thì bảng ắt phải cân nhắc lại. {Goi} muốn {xung} làm gì?"},{"who":"A","text":"{Goi} vào hầu, đọc cho bà nghe một bài thơ của {xung}. Chỉ một bài thôi."},{"who":"me","text":"Chiếc trâm của bà đâu chỉ là món trang sức. Đọc thơ {goi} trước mặt bà, đưa vào lúc nào mới tự nhiên?"}]}},
{"id":"nr:thd_sach_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn, {A} mở một bọc vải, bên trong là quyển hạ bộ sách của cha, bìa đã sờn mép."},{"who":"A","text":"{Goi}, cha gửi vào cung quyển hạ của bộ sách, có tên từng người nhận bạc đê điều. Giữ trong cung {xung} thì {B} sớm muộn sẽ biết."},{"who":"me","text":"Đây là thứ có thể làm nên chuyện lớn. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cất giùm {xung}, đến khi {xung} quyết in hay giấu."},{"who":"me","text":"Quyển hạ nặng như một món nợ, giữ lấy thì lòng cũng thấp thỏm. {Xung} nhận lời; cất nó ở đâu cho khuất mắt {B}?"}]}},
{"id":"nr:thd_sach_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều gió thu, {A} ngồi bên bàn nhỏ, ngón tay lướt qua con dấu của cha trên phong thư chưa viết."},{"who":"A","text":"{Goi}, sĩ tử ngoài kinh đòi in quyển hạ, mà cha {xung} còn đắn đo. {Xung} muốn gửi cha một lá thư, khuyên ông chờ đến sau mùa lũ."},{"who":"me","text":"Chờ đến sau mùa lũ để làm gì?"},{"who":"A","text":"Để chuyện đê điều lắng xuống, sách mới khỏi làm hại ông. Xin {goi} giúp {xung} gửi thư về."},{"who":"me","text":"Mùa lũ chưa tới mà sĩ tử đã giục in sách. Thư khuyên cha chờ phải về tới tận nơi, nên nhờ ai?"}]}},
{"id":"nr:thd_sach_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng vắng, {A} đặt tờ sớ chép lại lên án, tay nắm chặt cạnh bàn."},{"who":"A","text":"{Goi}, ngoài triều có sớ chê sách của cha {xung} là lời thầy đồ vu khống. Trong cung, {B} đã bắt đầu ra tay với {xung}."},{"who":"me","text":"Ngoài triều và trong cung cùng lúc, thật khó đỡ. Nàng ấy đã ra tay với {goi} thế nào rồi?"},{"who":"A","text":"Biết nàng ta định làm gì tiếp. {Goi} giúp {xung} dò trước một bước."},{"who":"me","text":"Ngoài triều chê, trong cung ra tay, hai mũi cùng đánh một lúc. Bước kế tiếp của nàng ấy, nên dò từ chỗ nào trước?"}]}},
{"id":"nr:thd_sach_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm yên, {A} ngồi đọc lại tờ sớ chê sách, thấy tên cha mình bị bôi mực đậm."},{"who":"A","text":"{Goi}, ngoài triều có sớ chê sách của cha {xung} là lời vu khống. Hoàng thượng chưa đọc sách, chỉ đọc sớ."},{"who":"me","text":"Chưa đọc sách mà đã đọc lời chê, thật bất công. {Goi} muốn gì?"},{"who":"A","text":"Xin ngài đọc một chương sách trước khi tin tờ sớ. Chỉ một chương thôi."},{"who":"me","text":"Một chương sách có thể đổi cái nhìn của Hoàng thượng. {Xung} nhận lời đưa sách tới, chỉ còn chọn lúc người còn chịu đọc."}]}},
{"id":"nr:thd_sach_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin từ quê vừa đến, {A} cầm mảnh giấy dọa mà người nhà đã chép lại, đôi mắt đỏ hoe."},{"who":"A","text":"{Goi}, trường làng của cha {xung} bị đốt một góc, trước cổng có giấy dọa. Cha không chịu rời làng."},{"who":"me","text":"Cha {goi} thật cứng lòng. {Goi} muốn làm gì?"},{"who":"A","text":"{Xung} cần người mang bạc và thư về, nhờ người trong làng canh cha mấy phiên chợ."},{"who":"me","text":"Trường làng cháy một góc, giấy dọa dán trước cổng, nghe mà {xung} nhói lòng. Thư và bạc về làng, cho ai mang?"}]}},
{"id":"nr:thd_sach_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sân, {A} đứng im nhìn mảnh giấy dọa đã được dán lại, góc giấy còn vết keo khô."},{"who":"A","text":"{Goi}, kẻ dán giấy dọa cha {xung} hẹn quay lại vào phiên chợ tới. {Xung} nghi kẻ ấy là gia nhân nhà {B}."},{"who":"me","text":"Nếu đúng thì chỗ này không còn là chuyện làng quê. Hắn có để lại dấu gì trước cổng trường không?"},{"who":"A","text":"Muốn biết mặt hắn. {Goi} giúp {xung} biết hắn là ai."},{"who":"me","text":"Kẻ dán giấy hẹn quay lại phiên chợ tới, vậy còn kịp đón hắn. Đón thế nào mà hắn không hay?"}]}},
{"id":"nr:thd_sach_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư, bản thảo xếp thành chồng cao, {A} cầm bút, vai mỏi đến không nhấc nổi."},{"who":"A","text":"{Goi}, kinh diên mùa thu là dịp dâng trọn bộ sách lên ngự lãm. Bản dâng phải chép sạch, đóng bìa đúng phép."},{"who":"me","text":"Chép sạch cả bộ cũng mất nhiều ngày. {Goi} một mình sao kịp?"},{"who":"A","text":"{Xung} chỉ có hai bàn tay. Nếu bên {goi} có người biết chữ, xin cho {xung} mượn mấy hôm."},{"who":"me","text":"Chỉ có hai bàn tay mà cả bộ sách phải chép sạch, kịp sao nổi? Mấy hôm tới, {goi} cần ai ở bên?"}]}},
{"id":"nr:thd_sach_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cửa Nội vụ phủ, {A} cầm tờ phiếu xin gấm bìa bị trả về, môi mím chặt."},{"who":"A","text":"{Goi}, bản dâng phải đóng bìa đúng phép, mà Nội vụ phủ không chịu cấp gấm bìa cho sách của thầy đồ quê."},{"who":"me","text":"Họ chê sách của cha {goi} vì xuất thân sao?"},{"who":"A","text":"Đúng vậy. {Goi} thưa với Hoàng hậu giúp {xung}, xin một tấm gấm bìa theo lệ."},{"who":"me","text":"Gấm bìa theo lệ chẳng phải ân huệ, chỉ là cái lẽ. {Xung} nhận lời xin giúp, chỉ còn cân lối vào cửa Nội vụ phủ."}]}},
{"id":"nr:thd_sach_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, {A} giơ trang sách lên ánh sáng, chỉ vào một câu bị cắt đôi."},{"who":"A","text":"{Goi}, người ta cắt nửa câu trong sách của cha {xung}, đọc thành lời chê vua. Câu đầy đủ là lời khen ngài."},{"who":"me","text":"Cắt câu để vu oan, thật độc địa. {Goi} muốn gì?"},{"who":"A","text":"Lúc {goi} hầu ngài, xin đọc cho ngài nghe trọn câu ấy, một lần thôi."},{"who":"me","text":"Nửa câu bị cắt vẫn còn nửa lời khen. Đọc trọn câu ấy cho Hoàng thượng, đọc bằng giọng ai thì người tin?"}]}},
{"id":"nr:thd_sach_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa sổ, {A} cầm trang sách nhàu, vết gấp cắt ngang câu chữ."},{"who":"A","text":"{Goi}, người cắt nửa câu sách là một vị Ngự sử, học trò của phủ kia. {Xung} cần bản in gốc của cha để chứng câu ấy còn nửa sau."},{"who":"me","text":"Có bản in gốc thì không ai chối cãi được. Nó ở đâu?"},{"who":"A","text":"Ở nhà in. {Goi} giúp {xung} lấy một bản từ nhà in."},{"who":"me","text":"Kẻ cắt câu là Ngự sử, học trò của phủ kia, nghe mà {xung} rợn người. Bản in gốc lấy ra bằng đường nào?"}]}},
{"id":"nr:thd_sach_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngày trước phiên xét án, {A} đứng bên hiên, nhìn về hướng Cần Chánh điện, môi tái nhợt."},{"who":"A","text":"{Goi}, ngày xét án, cha {xung} phải quỳ dưới thềm Cần Chánh điện. Trước ngày ấy {xung} chỉ được nói một lời với Hoàng thượng."},{"who":"me","text":"Một lời với Hoàng thượng thì phải nói sao cho đáng. {Goi} muốn gì?"},{"who":"A","text":"Nếu Thái hậu nhắc trước rằng thầy đồ già ấy vô hại, lời của {xung} sẽ nặng hơn."},{"who":"me","text":"Chỉ một lời được nói trước Hoàng thượng, nên phải có người dọn đường. {Xung} nhận lời; Thái hậu nên được nhắc theo lối nào?"}]}},
{"id":"nr:thd_sach_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước ngày xét án, {A} đi lại trong thiên điện, ánh mắt như người đã thức nhiều đêm."},{"who":"A","text":"{Goi}, ngày xét án cha {xung} sẽ quỳ dưới thềm, mà {B} đã sai người gặp quan đứng hầu án."},{"who":"me","text":"Họ gặp nhau tức là có điều muốn bàn. Ai đã thấy họ gặp, {goi} nghe từ miệng ai?"},{"who":"A","text":"Biết họ đã hứa với nhau những gì. {Goi} giúp {xung} dò trước phiên xét."},{"who":"me","text":"Quan hầu án đã được {B} gặp trước phiên xét. Muốn biết họ hứa những gì, {goi} thấy nên hỏi ai?"}]}},
{"id":"nr:thd_tro_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa sáng sớm, {A} bước vội qua cổng cung, trên tay là tờ đề thi nhàu nát từ chợ sách chuyền vào."},{"who":"A","text":"{Goi}, đề thi Hương được rao ở chợ sách trước ngày thi. Có kẻ trong bộ Lễ chép đề ra ngoài, học trò của cha {xung} là người đầu tiên thấy."},{"who":"me","text":"Đề thi lọt ra thì cả khoa thi hóa hư. {Goi} nghi ai?"},{"who":"A","text":"{Xung} muốn biết kẻ ấy có quen nhà {B} không, trước kỳ thi tới. {Goi} giúp {xung} dò."},{"who":"me","text":"Chợ sách đông người, lời nào cũng dễ lộ. Việc này {xung} phải lo cho khéo."}]}},
{"id":"nr:thd_tro_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian thư phòng nhỏ, {A} xoay xoay tờ đề thi cũ, mực đã nhòe một góc."},{"who":"A","text":"{Goi}, đề thi rao ở chợ sách, mà người bán chỉ là tay buôn. Kẻ chép đề phải ngồi trong bộ Lễ."},{"who":"me","text":"Muốn tìm kẻ chép thì phải có chứng. Ngoài cung, {goi} đã có người nào đáng tin để đi mua tờ đề ấy chưa?"},{"who":"A","text":"{Xung} cần một người ngoài cung mua một tờ đề ấy làm chứng. Trong cung, {xung} không với tới."},{"who":"me","text":"Một tờ giấy mà đổi được cả một vụ. {Xung} sẽ nghĩ kỹ xem ai đi mua thì khỏi bị nghi."}]}},
{"id":"nr:thd_tro_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hoàng hôn buông, {A} ngồi bên án, trên giấy ghi mấy cái tên chi chít, nét bút đè nặng."},{"who":"A","text":"{Goi}, đề bị bán không chỉ một khoa. Khoa trước có một người đỗ Tiến sĩ, là biểu huynh của một phi tần trong cung."},{"who":"me","text":"Nếu khoa trước cũng bị bán đề thì bảng vàng ấy đáng ngờ. Điều đầu tiên {goi} cần biết là gì?"},{"who":"A","text":"Bảng vàng năm ấy ai chấm. {Xung} không thể tự hỏi mà không bị để ý."},{"who":"me","text":"Bảng vàng khoa trước mà đã có tay mua bán thì không chỉ một người oan. Muốn biết ai cầm bút chấm khoa ấy, nhờ lối nào?"}]}},
{"id":"nr:thd_tro_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong điện, {A} đứng trước bài văn chép tay của một vị Tiến sĩ, ngón tay lần theo từng dòng chữ."},{"who":"A","text":"{Goi}, biểu huynh của {B} đỗ khoa trước nhờ đề bán. Muốn lật bảng vàng phải có ý Hoàng thượng."},{"who":"me","text":"Ý Hoàng thượng không thể ép. {Goi} muốn gì?"},{"who":"A","text":"{Goi} khéo hỏi ngài có nhớ bài văn của vị Tiến sĩ ấy không. Chỉ cần ngài chợt nghĩ lại."},{"who":"me","text":"Gợi một câu mà không để lộ ý. Việc này {xung} phải cân nhắc, hỏi thẳng hay nhờ quan Hàn lâm đọc lại bài văn."}]}},
{"id":"nr:thd_tro_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trong sân cung, {A} đứng bên cổng hậu, nghe tiếng chân nha dịch dội xa xa ngoài phố."},{"who":"A","text":"{Goi}, học trò của cha {xung} bị vu đánh người ở tửu lâu, phủ Thuận Thiên phát trát bắt. Vào ngục thì một học trò nghèo có thể chết trước khi được xét."},{"who":"me","text":"Cậu ấy giờ đang ở đâu?"},{"who":"A","text":"Cậu ấy đang trốn. {Goi} có chỗ nào cho cậu ấy trú mấy hôm không?"},{"who":"me","text":"Nhận một người bị truy vào cung là việc dễ gây tiếng. {Xung} đang nghĩ cho cậu ấy trú ở nhà mình, hay lo một chỗ ngoài kinh."}]}},
{"id":"nr:thd_tro_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước điện Cần Chánh, {A} cầm tờ trát bắt người có dấu đỏ phủ Thuận Thiên, nét mặt tái đi."},{"who":"A","text":"{Goi}, học trò của cha {xung} bị phủ Thuận Thiên truy bắt vì một vụ đánh người cậu ấy không làm."},{"who":"me","text":"Cậu ấy không làm mà bị bắt, thật oan. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin Hoàng thượng cho phủ Thuận Thiên xét kỹ trước khi giam người."},{"who":"me","text":"Cậu ấy không làm mà đã bị bắt, cửa ngục chưa kịp khép. Lời xin xét kỹ nên tới tai ai trước?"}]}},
{"id":"nr:thd_tro_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Ngọ Môn, {A} giữ trong tay lá đơn kêu oan dày chữ ký, trang giấy đã nhàu vì nắm chặt."},{"who":"A","text":"{Goi}, sĩ tử khắp kinh ký hơn trăm tên vào một lá đơn kêu oan, mà đơn không qua được cửa bộ Lễ."},{"who":"me","text":"Đơn bị chặn thì chỉ còn đường khác. {Goi} muốn gì?"},{"who":"A","text":"Con đường còn lại là qua hậu cung. {Xung} không dám tự dâng. Nếu có dịp hầu ngài, xin {goi} cho lá đơn ấy đến được ngự án."},{"who":"me","text":"Hơn trăm sĩ tử ký tên mà đơn không đến được ngự án, {xung} cũng nặng lòng. Đưa lên Hoàng thượng bằng lối nào?"}]}},
{"id":"nr:thd_tro_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên Đức Thọ cung, {A} giữ lá đơn gấp làm tư trong tay áo, ánh mắt hướng về phía Ngọ Môn."},{"who":"A","text":"{Goi}, lá đơn trăm chữ ký bị chặn trước Ngọ Môn. Thái hậu thương sĩ tử nghèo, bà từng ban gạo cho trường thi."},{"who":"me","text":"Thái hậu từng ban gạo thì chắc nghe được. {Goi} muốn gì?"},{"who":"A","text":"{Goi} vào hầu, xin bà nghe chuyện lá đơn."},{"who":"me","text":"Thái hậu từng ban gạo cho trường thi, bà hẳn thương sĩ tử. {Xung} nhận lời; chỉ cần chọn cách kể cho bà dễ nghe."}]}},
{"id":"nr:thd_tro_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm mưa, {A} ngồi bên cửa sổ, nghe nước nhỏ từng giọt, trước mặt là lá thư báo tin thư lại bộ Lễ mất."},{"who":"A","text":"{Goi}, một thư lại bộ Lễ treo cổ trong đêm, ai cũng nói là tự vẫn. {Xung} không tin."},{"who":"me","text":"Vì sao {goi} không tin?"},{"who":"A","text":"Nhà ngoại của {B} đang chạy khắp các cửa quan. {Goi} giúp {xung} biết đêm ấy ai đã đến gặp ông."},{"who":"me","text":"Thư lại tự vẫn mà nhà ngoại của {B} chạy khắp các cửa quan, chuyện ấy nghe không xuôi. Đêm ấy ai gặp ông, hỏi từ đâu?"}]}},
{"id":"nr:thd_tro_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian phòng nhỏ, {A} ngồi canh bên chiếc giường gỗ, nơi một đứa bé gái đang ngủ co ro."},{"who":"A","text":"{Goi}, thư lại treo cổ còn một đứa con gái nhỏ, nhà kia đang tìm nó. {Xung} không có chỗ giấu."},{"who":"me","text":"Đứa bé biết điều gì không?"},{"who":"A","text":"Nó còn nhỏ, chỉ biết khóc. {Goi} nhận đứa bé làm cung nữ nhỏ ít lâu."},{"who":"me","text":"Đứa bé chỉ biết khóc mà đã có người đi tìm, nghe mà thương. Che chở nó, đặt nó ở đâu cho yên?"}]}},
{"id":"nr:thd_tro_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều trước kỳ thi lại, {A} đứng trước cổng điện, bóng nắng dài chạy qua những bậc đá."},{"who":"A","text":"{Goi}, Hoàng thượng cho thi lại ngay trong điện, học trò của cha {xung} cũng được gọi. Cậu ấy chỉ sợ đề bị lái về phía có lợi cho người khác."},{"who":"me","text":"Đề thi do ai ra thì ai cũng có thể nghi. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin ngài tự ra đề, đừng để ai khác cầm bút."},{"who":"me","text":"Đề thi bị lái đi thì đời một học trò đổi theo. Lời xin Hoàng thượng tự ra đề, {goi} muốn đưa tới lúc nào?"}]}},
{"id":"nr:thd_tro_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên cửa điện, {A} nhìn danh sách quan coi thi dán trên bảng, đầu mày nhíu chặt."},{"who":"A","text":"{Goi}, kỳ thi lại trong điện, quan coi thi lại là người nhà {B}. {Xung} lo cậu ấy bị chèn ép."},{"who":"me","text":"Quan coi thi mà có tư tâm thì thi gì cũng hỏng. Vị Tiến sĩ bị nghi ấy là ai, {goi} biết chăng?"},{"who":"A","text":"Họ đã gặp vị Tiến sĩ bị nghi trước ngày thi chưa. {Goi} giúp {xung} biết."},{"who":"me","text":"Quan coi thi là người nhà {B}, bước vào điện cậu ấy đã thấp hơn một bậc. Muốn biết họ gặp Tiến sĩ kia chưa, dò ai?"}]}},
{"id":"nr:thd_hoc_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giờ ngọ, trong cung {A}, một cậu bé ngồi thu lu bên chân ghế, tay nắm vạt áo, nhìn mọi người bằng đôi mắt sợ sệt."},{"who":"A","text":"{Goi}, một hoàng tự nhỏ trốn học sang chơi ở cung {goi}. Đưa về ngay thì cậu bé bị phạt, mà để mãi thì {xung} mang tiếng không dạy nổi."},{"who":"me","text":"Cậu bé trốn học vì sao?"},{"who":"A","text":"Có lẽ là sợ. {Goi} giữ cậu bé lại nửa buổi, để {xung} đến dỗ."},{"who":"me","text":"Cậu bé trốn học vì sợ, {xung} nghe mà mủi lòng. Giữ lại mà không thành tiếng, nên nhờ người nào trông?"}]}},
{"id":"nr:thd_hoc_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hành lang Thượng thư phòng, {A} cúi xuống nhìn cậu bé ngồi co ro, tay cậu còn nắm quyển sách đã nhàu."},{"who":"A","text":"{Goi}, hoàng tự nhỏ trốn học vì có người dọa cậu bé ở Thượng thư phòng. {Xung} nghi là thư đồng của {B}."},{"who":"me","text":"Trẻ nhỏ bị dọa thì không dám nói. Cậu bé đã hé với {goi} lời nào chưa?"},{"who":"A","text":"Biết đứa thư đồng ấy đã nói gì với cậu bé. {Goi} giúp {xung}."},{"who":"me","text":"Thư đồng của {B} đã nói gì mà cậu bé phải trốn? Muốn nghe lời thật, nên hỏi cậu lúc nào?"}]}},
{"id":"nr:thd_hoc_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên hiên Thượng thư phòng, {A} đứng lặng nhìn mấy phi tần đang thì thầm với nhau, ánh mắt họ liếc về phía mình."},{"who":"A","text":"{Goi}, {B} tin rằng {xung} thiên vị mấy thư đồng con nhà quan. Một người mẹ trong cung có thể làm nhiều hơn một lời than."},{"who":"me","text":"Lời than của một người mẹ có thể thành tấm bia đứng trước Hoàng thượng. Nàng ấy đã than với ai, {goi} nghe được gì chưa?"},{"who":"A","text":"Biết nàng ta đã nói gì với ai. {Goi} giúp {xung} dò."},{"who":"me","text":"Lời than của một người mẹ nặng hơn trăm lời của thầy. {Xung} nhận lời dò, chỉ cần chọn người nghe được điều ấy."}]}},
{"id":"nr:thd_hoc_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, {A} bước ra khỏi Thượng thư phòng, tay còn vương phấn trắng, giọng khàn đi vì mệt."},{"who":"A","text":"{Goi}, một người mẹ trong cung đã kêu với Hoàng thượng rằng {xung} thiên vị. {Xung} không cãi."},{"who":"me","text":"Không cãi nghĩa là {goi} tin vào sự thật. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin ngài một lần đến dự giờ, để ngài tự thấy {xung} dạy thế nào."},{"who":"me","text":"{Goi} không cãi mà chỉ mời Hoàng thượng tự đến thấy, như vậy mới ngay thẳng. Lời mời nên đưa ra bằng đường nào?"}]}},
{"id":"nr:thd_hoc_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hôm trước kỳ khảo hạch, {A} ngồi bên cậu bé nhút nhát, kiên nhẫn chỉ vào từng chữ trên trang sách."},{"who":"A","text":"{Goi}, kỳ khảo hạch này Hoàng thượng sẽ đến khảo bài các hoàng tự nhỏ. Có một đứa trẻ học rất giỏi mà nhút nhát, đứng trước ngài là quên hết chữ {xung} dạy."},{"who":"me","text":"Một đứa trẻ giỏi mà vì sợ mà mất hết, thật tiếc. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin ngài hỏi cậu bé sau cùng, khi cậu đã bớt sợ."},{"who":"me","text":"Đứa trẻ giỏi mà run trước thiên nhan, nghĩ mà tiếc. Xin đổi thứ tự hỏi bài, nên nói với ai?"}]}},
{"id":"nr:thd_hoc_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước khi mở kỳ khảo hạch, {A} đứng bên án, lật từng trang bài giảng đã đánh dấu bằng chỉ đỏ."},{"who":"A","text":"{Goi}, các Đại học sĩ sẽ ngồi nghe kỳ khảo hạch. {Xung} cần biết họ sẽ hỏi sách nào, để bọn trẻ khỏi bị hỏi điều chưa học."},{"who":"me","text":"Biết trước đề là điều khó. {Goi} nghĩ ai biết được?"},{"who":"A","text":"Nếu nhà {goi} quen một vị Đại học sĩ, xin {goi} nhờ hỏi giúp {xung}."},{"who":"me","text":"Hỏi trước sách của Đại học sĩ dễ bị coi là gian, mà bọn trẻ thì vô tội. {Goi} thấy ai hỏi khéo được?"}]}},
{"id":"nr:thd_hoc_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tà, bên cổng Khôn Ninh cung, {A} đứng ngập ngừng, nghe tiếng khóc của một người mẹ vọng ra từ trong điện."},{"who":"A","text":"{Goi}, một đứa trẻ bị phạt trong giờ {xung} dạy, mẹ nó đã đến Khôn Ninh cung kêu. Phép phạt của thầy là phép, nhưng ra khỏi cửa lớp thì là chuyện khác."},{"who":"me","text":"Phạt trong lớp thì thầy có quyền. Nhưng người mẹ nghe sao?"},{"who":"A","text":"Người mẹ chỉ nghe con khóc. {Goi} thưa với Hoàng hậu giúp {xung} một lời."},{"who":"me","text":"Phạt trong lớp là phép, ra khỏi cửa lớp là chuyện khác. Lời đỡ cho người thầy, nên đến tai Hoàng hậu thế nào?"}]}},
{"id":"nr:thd_hoc_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trong phòng nhỏ, {A} ngồi bên cậu bé đang nằm, đầu gối cậu tím bầm dưới ánh nến."},{"who":"A","text":"{Goi}, đứa trẻ bị phạt quỳ, đầu gối sưng tím, mẹ nó nói {xung} đánh con bà."},{"who":"me","text":"Chuyện phạt quỳ mà hóa thành đánh người. {Goi} muốn gì?"},{"who":"A","text":"{Xung} cần một thái y xem vết thương và ghi đúng là do quỳ. {Goi} mời giúp."},{"who":"me","text":"Đầu gối sưng tím ai cũng thấy, nên cần một lời ghi cho đúng. {Xung} nhận lời; thầy thuốc nào mới đáng tin?"}]}},
{"id":"nr:thd_hoc_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, {A} đứng bên cửa Thượng thư phòng, tay giữ quyển Mạnh Tử đã sờn gáy, vẻ mặt đầy lo âu."},{"who":"A","text":"{Goi}, {xung} dạy bọn trẻ một câu của Mạnh Tử, nay câu ấy bị đọc lại trước mặt Hoàng thượng như một lời ngông."},{"who":"me","text":"Một câu kinh điển mà bị hiểu ngược, thật oan. {Goi} muốn gì?"},{"who":"A","text":"Nếu nhà {goi} quen một bậc đại nho, một bài giải của bậc thầy ngoài cung sẽ gỡ được chuyện này."},{"who":"me","text":"Một câu kinh Mạnh Tử bị đọc ngược trước Hoàng thượng, {xung} nghe mà ức. Bài giải của bậc đại nho nên đến bằng đường nào?"}]}},
{"id":"nr:thd_hoc_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều trong Thượng thư phòng, {A} nhìn đàn trẻ đang chép bài, trong lòng vẫn nghĩ về lời kể bị thêu dệt."},{"who":"A","text":"{Goi}, câu Mạnh Tử trong lớp được đọc lại trước Hoàng thượng, mà người kể lại là {B}. {Xung} muốn biết nàng ta nghe câu ấy từ đứa trẻ nào."},{"who":"me","text":"Trẻ con không biết giữ lời. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} biết đứa trẻ nào đã kể."},{"who":"me","text":"Câu ấy đi từ miệng đứa trẻ nào đến tai {B}? Hỏi trẻ nhỏ phải thật nhẹ tay, {goi} muốn bắt đầu từ chỗ nào?"}]}},
{"id":"nr:thd_hoc_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm học, trong sân Thượng thư phòng, {A} nhìn đàn trẻ nô đùa dưới tuyết, nét mặt vừa vui vừa nặng lòng."},{"who":"A","text":"{Goi}, năm học khép lại, Hoàng thượng muốn nghe {xung} nói đứa trẻ nào gánh được việc lớn. Một câu của {xung} có thể định chỗ đứng của từng đứa."},{"who":"me","text":"Sức nặng của một câu như vậy thật đáng sợ. {Goi} muốn gì?"},{"who":"A","text":"Thái hậu thương các hoàng tôn. {Goi} xin bà hỏi trước, để lời {xung} khỏi thành của riêng {xung}."},{"who":"me","text":"Một câu của {goi} định chỗ đứng cho từng hoàng tôn, nên Thái hậu hỏi trước thì nhẹ gánh. Kể chuyện lớp học cho bà thế nào?"}]}},
{"id":"nr:thd_hoc_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm cuối năm, {A} ngồi bên án, tờ nhận xét đã viết nửa chừng, mực khô mà bút còn chần chừ."},{"who":"A","text":"{Goi}, Hoàng thượng muốn nghe {xung} nói đứa trẻ nào gánh được việc lớn. {Xung} muốn nói thật, nhưng sợ lời thật làm nhiều người oán."},{"who":"me","text":"Nói thật thì mất lòng, nói khéo thì mất sự thật. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin ngài cho {xung} viết, đừng bắt nói trước mọi người."},{"who":"me","text":"Viết thì bớt chạm mặt người, mà vẫn giữ được lời thật. {Xung} nhận lời; chỉ còn chọn lối xin giấy bút."}]}},
{"id":"nr:cnv_chu_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, {A} nép bên cửa phòng thuốc, hai tay nâng một gói giấy nhỏ, mùi xạ hương thoảng ra."},{"who":"A","text":"{Goi}, {xung} tìm thấy trong cung chủ của {xung} một gói xạ hương. Ở Thái y viện, mỗi lạng xạ hương xuất kho đều ghi tên cung nhận."},{"who":"me","text":"Xạ hương là thứ không thể để bừa. Gói ấy {goi} tìm thấy ở đâu trong cung?"},{"who":"A","text":"Gói ấy từ đâu ra. {Goi} có quen thái y nào, xin hỏi giúp {xung}."},{"who":"me","text":"Mỗi lạng xạ hương xuất kho đều có tên cung nhận, hỏi vụng một câu là lộ. Gói ấy, hỏi nguồn bằng đường nào?"}]}},
{"id":"nr:cnv_chu_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn, {A} trải trước mặt một tờ sổ rách mép, bàn tay không giấu nổi lo lắng."},{"who":"A","text":"{Goi}, ở Thái y viện, sổ xuất xạ hương đã bị xé mất một trang. {Xung} nghi người của {B} đã vào kho trước."},{"who":"me","text":"Một trang sổ mất là có kẻ muốn xóa dấu. Trang bị xé vào ngày nào, {goi} có nhớ không?"},{"who":"A","text":"Biết hôm ấy ai trực kho. Xin {goi} giúp {xung}."},{"who":"me","text":"Hỏi phiên trực mà không làm kinh động. {Xung} đang tính cử người hỏi, hay tự hỏi các thái giám giữ kho thuốc."}]}},
{"id":"nr:cnv_chu_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới bóng hành lang, {A} đứng cúi đầu, ánh mắt liếc về phía cổng sân, như sợ có người theo dõi."},{"who":"A","text":"{Goi}, người của {B} đang dò khắp nơi: ai trực đêm ấy, ai dọn phòng. {Xung} giữ kín được lời của {xung}, nhưng không giữ được miệng người khác."},{"who":"me","text":"Họ đã dò đến ai rồi?"},{"who":"A","text":"{Xung} chưa biết hết. {Goi} giúp {xung} biết họ đã hỏi những ai."},{"who":"me","text":"Người của {B} dò khắp nơi, nghe tin mà {xung} lạnh gáy. Trước hết, nên theo dấu họ từ phía nào?"}]}},
{"id":"nr:cnv_chu_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm vắng, {A} ngồi sau bức bình phong cùng một cung nữ trẻ, nàng ấy run lẩy bẩy, mắt thâm quầng."},{"who":"A","text":"{Goi}, người dò hỏi đã tìm đến cung nữ trực đêm hôm ấy, nàng ấy sợ đến mất ngủ. Nàng chỉ thấy một bóng người."},{"who":"me","text":"Chỉ một bóng người mà đã bị truy đến vậy. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cho nàng ấy sang làm việc ở chỗ khác ít hôm, cho khuất tầm mắt kẻ kia."},{"who":"me","text":"Nàng ấy chỉ thấy một bóng người mà đã mất ngủ. Có chỗ nào khuất mắt kẻ kia, {goi} nghĩ ra chưa?"}]}},
{"id":"nr:cnv_chu_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, bên hiên sau, {A} nắm chặt vạt áo, nhìn quanh như sợ bóng lá cũng biết nghe lén."},{"who":"A","text":"{Goi}, có người đem một chuyện riêng kể với {xung}, rồi chờ xem chuyện ấy có lọt ra không. {Xung} sợ người khác nói ra mà {xung} mang tiếng."},{"who":"me","text":"Đó là phép thử. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cho {xung} một việc ở xa chỗ đông người ít hôm."},{"who":"me","text":"Phép thử đã bày, tránh đi một thời gian là hợp lẽ. {Xung} nhận lời cho {goi} việc xa người; nơi nào ít tai mắt hơn?"}]}},
{"id":"nr:cnv_chu_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên hành lang vắng, {A} đứng lặng nghe tiếng gió rít qua kẽ cửa, nét mặt đầy ngờ vực."},{"who":"A","text":"{Goi}, phép thử đã bày, mà {B} đã biết chuyện trước cả {xung}. Có kẻ đứng ngoài cửa đêm ấy."},{"who":"me","text":"Kẻ ấy là người đã nghe lén. {Goi} muốn gì?"},{"who":"A","text":"Biết kẻ ấy là ai. {Goi} giúp {xung} hỏi ra."},{"who":"me","text":"Có kẻ đứng ngoài cửa đêm ấy, hành lang hẳn còn người nhớ. Hỏi từ ai trước?"}]}},
{"id":"nr:cnv_chu_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa buổi chiều, {A} ôm một chiếc hộp gỗ nhỏ bọc vải, nhìn ra sân như đợi người đến khám."},{"who":"A","text":"{Goi}, Nội vụ phủ sắp đến khám cung chủ của {xung}. Có một chiếc hộp nhỏ không được để ai thấy."},{"who":"me","text":"Hộp ấy đựng gì mà phải giấu?"},{"who":"A","text":"{Xung} không dám nói. {Goi} giữ giùm {xung} đến khi người khám đi khỏi."},{"who":"me","text":"Chiếc hộp nhỏ mà {goi} không dám nói tên, nghĩ cũng biết nặng thế nào. Nhận giữ rồi, cất ở đâu cho yên?"}]}},
{"id":"nr:cnv_chu_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước ngày khám cung, {A} đứng trước cửa phòng Trung cung, tay nắm chặt tờ đơn xin hoãn."},{"who":"A","text":"{Goi}, Nội vụ phủ sắp khám theo ý Trung cung. {Xung} không xin bỏ việc khám, chỉ xin khám vào ban ngày, có nữ quan đứng xem."},{"who":"me","text":"Khám ban ngày thì cũng đỡ lo. Nhưng Hoàng hậu có chịu không?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp, xin bà cho khám đúng phép."},{"who":"me","text":"Khám ban ngày, có nữ quan đứng xem, vậy là còn giữ được thể diện. {Goi} thấy lời xin nên mềm đến đâu?"}]}},
{"id":"nr:cnv_chu_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Khôn Ninh cung, {A} quỳ chờ gọi, bàn tay run run nắm vạt áo."},{"who":"A","text":"{Goi}, Trung cung đòi {xung} khai. Nói thật thì nỗi khổ chủ của {xung} từng chịu sẽ bị phơi ra hết, giữ kín thì {xung} phải gánh tội."},{"who":"me","text":"Khai hay không khai đều khổ. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp: {Xung} chỉ là người dọn phòng, không biết gì hơn."},{"who":"me","text":"Nỗi khổ của chủ không phải thứ để đem phơi. Lời thưa lên Hoàng hậu, nên để miệng ai nói?"}]}},
{"id":"nr:cnv_chu_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn đêm, {A} đứng trước cửa phòng thuốc, nhìn một vị thái y thu xếp hòm thuốc, như sắp đi xa."},{"who":"A","text":"{Goi}, Ôn thái y muốn rời kinh, mà chỉ ông nói được gói thuốc kia dùng để làm gì. {Xung} cần ông ở lại thêm mấy hôm."},{"who":"me","text":"Ông ấy đi rồi thì mất hết manh mối. {Goi} muốn gì?"},{"who":"A","text":"{Goi} có cách nào giữ ông lại không?"},{"who":"me","text":"Ôn thái y đi thì manh mối đi theo. {Xung} nhận lời giữ ông thêm mấy hôm, chỉ cần chọn lối mời cho khỏi ép."}]}},
{"id":"nr:cnv_chu_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối ngày, bên cửa ngục Thận hình ty, {A} đứng giữa gió lạnh, đôi mắt đỏ hoe nhìn về cánh cổng sắt."},{"who":"A","text":"{Goi}, {xung} sắp bị giải đến Thận hình ty. {B} đã khai tên {xung} trước, mà ở đó roi vọt chẳng cần biết ai có tội."},{"who":"me","text":"Khai tên trước, cũng là một đòn. {Goi} xin gì?"},{"who":"A","text":"{Xung} không xin thoát. {Xung} chỉ xin {goi} cho người nói với viên quản sự một câu, để tay roi nhẹ hơn."},{"who":"me","text":"Roi vọt ở Thận hình ty chẳng nể ai, {xung} nghe mà đau thay. Một câu nhờ viên quản sự, đưa vào lối nào?"}]}},
{"id":"nr:cnv_chu_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trong phòng nhỏ lạnh, {A} nằm nghiêng bên giường tre, lưng áo còn dính máu khô, giọng khàn khàn."},{"who":"A","text":"{Goi}, sau đêm tra hỏi, lưng {xung} rách thịt, Thận hình ty không cho thuốc. {Xung} không dám xin gì hơn."},{"who":"me","text":"Chuyện đã đến vậy, {goi} cần gì?"},{"who":"A","text":"Xin {goi} cho {xung} một lọ thuốc trị thương."},{"who":"me","text":"Lưng rách thịt mà không một lọ thuốc, nằm đêm ắt chẳng yên. Thuốc ấy đến tay nàng bằng đường nào mà khỏi ghi tên?"}]}},
{"id":"nr:cnv_ban_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước hiệu cầm đồ ngoài cửa cung, {A} đứng khuất sau bóng liễu, mắt dõi nhìn mấy cái hộp trang sức bày sau quầy."},{"who":"A","text":"{Goi}, chiếc vòng ngọc thật vẫn chưa về chỗ cũ. Nó đi đâu, qua tay ai, là biết {B} có dính vào vụ vu Xuân Đào không."},{"who":"me","text":"Một chiếc vòng mà mang cả một vụ án. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} hỏi ở mấy hiệu cầm đồ ngoài cửa cung."},{"who":"me","text":"Chiếc vòng đi qua tay ai, ấy là điều đáng biết. {Xung} nhận lời; hiệu cầm đồ nào ngoài cửa cung nên hỏi trước?"}]}},
{"id":"nr:cnv_ban_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng nhỏ, {A} đặt lên bàn một cuốn sổ nhỏ, ghi tên chiếc vòng ngọc bằng nét mực đỏ."},{"who":"A","text":"{Goi}, chiếc vòng ngọc thật nằm trong sổ của Trung cung là đồ ngự ban. Mất đồ ngự ban thì Hoàng hậu phải cho tra."},{"who":"me","text":"Đồ ngự ban mất thì thật là việc lớn. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp {xung}, xin bà cho tra lại."},{"who":"me","text":"Đồ ngự ban đã ghi trong sổ Trung cung, mất thì ai chịu? Xin tra lại, {goi} muốn thưa bằng lời nào?"}]}},
{"id":"nr:cnv_ban_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều xuống, bên cửa sau phòng hầu, {A} dắt tay Thu Cúc, nàng run lẩy bẩy như chim non gặp mưa."},{"who":"A","text":"{Goi}, Thu Cúc muốn khai ai đã sai nàng vu người, nhưng nàng sợ bị bịt miệng. {Xung} hứa với nàng sẽ tìm chỗ nương."},{"who":"me","text":"Một người đã dám khai thì phải bảo vệ. {Goi} muốn gì?"},{"who":"A","text":"{Goi} che chở cho Thu Cúc ít hôm. Chỉ ít hôm thôi."},{"who":"me","text":"Thu Cúc dám khai là đã tự bước ra khỏi bóng tối, nghĩ mà thương. Nàng nương nhờ nơi nào thì yên?"}]}},
{"id":"nr:cnv_ban_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa sau Nội vụ phủ, {A} đứng khuất sau cột đá, nhìn những chiếc xe chở hàng ra vào lúc nhá nhem."},{"who":"A","text":"{Goi}, đường bạc từ cửa sau Nội vụ phủ dẫn về cung {B}. {Xung} cần biết thái giám nào đã cầm bạc đi qua cửa ấy."},{"who":"me","text":"Bạc đi qua cửa sau thì tất phải có người dẫn. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} biết mặt người ấy."},{"who":"me","text":"Bạc đi qua cửa sau Nội vụ phủ mà bàn tay cầm không mang tên. Muốn biết mặt kẻ ấy, canh từ đâu?"}]}},
{"id":"nr:cnv_ban_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong khố Tân Giả, {A} quỳ bên Xuân Đào đang sốt li bì, nước mắt rơi xuống tấm chiếu rách."},{"who":"A","text":"{Goi}, Xuân Đào bị đánh rồi đày xuống Tân Giả khố, vết thương làm mủ, sốt li bì. Không có thuốc sớm thì nàng khó qua khỏi."},{"who":"me","text":"Nàng ấy còn tỉnh không?"},{"who":"A","text":"Nàng chỉ còn thều thào. {Xung} không có đường đến Thái y viện. {Goi} cứu nàng một lần."},{"who":"me","text":"Mạng người trước mắt, một đêm cũng không thể phí. {Xung} nhận lời cứu Xuân Đào; thuốc xuống Tân Giả khố đi bằng tay nào?"}]}},
{"id":"nr:cnv_ban_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm lạnh, bên cổng Tân Giả khố, {A} quỳ dưới nền đá, tay nâng một chiếc khăn ướt vẫn còn ấm hơi sốt."},{"who":"A","text":"{Goi}, Xuân Đào sốt li bì ở Tân Giả khố, mà ở đó không ai trông. Nếu được về một chỗ có người chăm, nàng còn sống."},{"who":"me","text":"Ở đó không ai trông, thì nàng khó qua đêm. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin cho nàng sang chỗ {goi} mấy hôm."},{"who":"me","text":"Sốt li bì mà không ai trông, nghe mà {xung} đau lòng. Đưa nàng về nơi có người chăm, thì đưa đi đâu?"}]}},
{"id":"nr:cnv_ban_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa Trung cung, {A} đứng bên Xuân Đào đang gầy guộc, hai người nắm tay nhau, nét mặt đều lo."},{"who":"A","text":"{Goi}, Xuân Đào muốn đứng ra làm chứng chuyện vòng ngọc. Một người bị đày, không ai cho nói, còn lời của {xung} thì chẳng ai nghe."},{"who":"me","text":"Nàng ấy muốn nói điều gì?"},{"who":"A","text":"Muốn nói sự thật. {Goi} thưa với Hoàng hậu giúp, cho nàng được khai trước Trung cung."},{"who":"me","text":"Một người bị đày mà dám đứng ra làm chứng, lời kẻ yếu cũng có chỗ đứng. Mở lời với Hoàng hậu, bắt đầu thế nào?"}]}},
{"id":"nr:cnv_ban_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước phiên làm chứng, {A} đứng canh trước cửa phòng nhỏ của Xuân Đào, nghe tiếng bước chân lạ ngoài hành lang."},{"who":"A","text":"{Goi}, phiên làm chứng sắp mở, mà người của {B} đã đến dọa Xuân Đào hai lần."},{"who":"me","text":"Dọa hai lần rồi, e còn lần ba. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} biết họ còn định dọa những ai."},{"who":"me","text":"Dọa hai lần rồi, lần thứ ba sẽ nhắm ai? Muốn biết trước, nên canh chỗ nào?"}]}},
{"id":"nr:cnv_ban_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, {A} đứng trước cổng cung, tay cầm một bọc quần áo nhỏ, bên cạnh là Xuân Đào xanh xao."},{"who":"A","text":"{Goi}, bàn phân xử đã bày, Xuân Đào hay Thu Cúc, một người sẽ phải đi. Dù thế nào, Xuân Đào cũng không còn ở lại được."},{"who":"me","text":"Nàng ấy không còn chỗ nào để về sao?"},{"who":"A","text":"Không. {Goi} cho nàng về hầu cung {goi}, {xung} xin chịu mọi tiếng."},{"who":"me","text":"Xuân Đào chẳng còn nơi nào để về, mà {goi} lại xin gánh mọi tiếng vì nàng, {xung} nghe mà nể. Nhận nàng ở đâu thì yên?"}]}},
{"id":"nr:cnv_ban_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong điện nhỏ, {A} đứng lặng bên án chứa nửa bộ chứng cứ, ánh mắt tìm kiếm một mảnh còn thiếu."},{"who":"A","text":"{Goi}, bàn phân xử đã bày, mà chứng cứ chỉ đủ một nửa. Nếu Trung cung cho thêm ít lâu, {xung} tìm được nửa kia."},{"who":"me","text":"Nửa kia ở đâu, {goi} có biết không?"},{"who":"A","text":"{Xung} biết, chỉ cần thêm thời gian. {Goi} thưa với Hoàng hậu giúp."},{"who":"me","text":"Chứng cứ mới đủ một nửa, thêm chút thời gian là thêm nửa còn lại. {Xung} nhận lời xin hoãn, chỉ chọn lối thưa lên Trung cung."}]}},
{"id":"nr:cnv_ban_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya, bên bàn quản sự Nội vụ phủ, {A} kín đáo giở một cuốn sổ ghi dày, mắt dò từng dòng chữ."},{"who":"A","text":"{Goi}, sổ ghi đồ lén đưa ra cửa sau đã đến bàn quản sự Nội vụ phủ. Trong sổ có tên mấy thái giám của chính Nội vụ phủ."},{"who":"me","text":"Nếu sổ bị chôn thì {B} thoát tội. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} chép lại một trang trước khi sổ bị chôn."},{"who":"me","text":"Sổ đã nằm trên bàn quản sự, một trang chép lại cũng đủ làm chứng. Chép bằng tay ai?"}]}},
{"id":"nr:cnv_ban_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước điện Khôn Ninh, {A} ôm một tờ giấy ghi tóm tắt mấy cái tên thái giám, vẻ mặt đầy quyết tâm."},{"who":"A","text":"{Goi}, sổ ghi đồ lén đưa ra cửa sau có tên mấy thái giám Nội vụ phủ. Nếu sổ đến tay Trung cung, không ai chôn được."},{"who":"me","text":"Vậy cần một người đến lấy sổ. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin Hoàng hậu cho người đến lấy sổ."},{"who":"me","text":"Sổ vào tay Trung cung thì không ai chôn nổi, nhưng người đi lấy phải là người Hoàng hậu tin. {Goi} nghĩ là ai?"}]}},
{"id":"nr:cnv_mat_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, bên hành lang hậu viện, {A} đứng nép sau cột sơn đỏ, tay siết chặt vạt áo."},{"who":"A","text":"{Goi}, Hoàng thượng nhìn {xung} một lần ở hành lang, từ đó lòng người trong cung chủ của {xung} đổi khác. {Xung} không dám mong gì."},{"who":"me","text":"Một ánh nhìn mà đổi cả lòng người. {Goi} muốn gì?"},{"who":"A","text":"{Goi} tìm cho {xung} một việc khuất mắt ít lâu."},{"who":"me","text":"Một ánh nhìn mà đổi cả lòng người, thương {goi} vô cớ mang lấy. Việc khuất mắt ít lâu, nên là nơi nào?"}]}},
{"id":"nr:cnv_mat_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên, {A} đứng một mình, nghe tiếng thì thầm từ dãy phòng hầu vọng ra, đầu cúi gằm."},{"who":"A","text":"{Goi}, từ khi Hoàng thượng nhìn {xung} ở hành lang, có người kể chuyện ấy khắp nơi, thêm thắt đủ điều. {Xung} nghi là người của {B}."},{"who":"me","text":"Lời đồn mà có người dệt thì khó dứt. Lời ấy {goi} nghe lần đầu từ ai?"},{"who":"A","text":"Biết ai đã kể. {Goi} giúp {xung}."},{"who":"me","text":"Lời đồn có người dệt thì phải có người kể đầu tiên. {Xung} nhận lời tìm ra; hỏi ở chỗ nào hay ngồi lê?"}]}},
{"id":"nr:cnv_mat_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa đường cung, {A} đứng giữa ánh đèn lồng chập chờn, vạt áo lay trong gió, mắt nhìn quanh đầy lo sợ."},{"who":"A","text":"{Goi}, Hoàng thượng đã mấy lần gọi {xung} giữa đường. {Xung} không dám trái ý ngài, cũng không dám để người ta thấy."},{"who":"me","text":"Bên nào cũng khó. {Goi} muốn gì?"},{"who":"A","text":"{Goi} khéo nói với ngài, đừng để {xung} đứng giữa hai bên."},{"who":"me","text":"Hoàng thượng gọi giữa đường, người thì nhìn, {goi} đứng giữa hai bên. Lời nói đỡ nên đến tai người lúc nào?"}]}},
{"id":"nr:cnv_mat_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, {A} đứng trước cửa Khôn Ninh cung, gói đồ nhỏ trên tay, mắt nhìn xuống nền đá."},{"who":"A","text":"{Goi}, Hoàng thượng gọi {xung} giữa đường ba lần, người ta bắt đầu nói {xung} cố ý đứng chờ."},{"who":"me","text":"Lời đồn đã thành hình rồi. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp, xin cho {xung} đổi sang đường đi khác."},{"who":"me","text":"Ba lần giữa đường đã thành cố ý chờ trong miệng người. Xin đổi đường đi, {goi} muốn nhờ ai thưa?"}]}},
{"id":"nr:cnv_mat_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn nhỏ, {A} mở trước mặt một tờ giấy ghi tên mình trong sổ Kính sự phòng, ngón tay lạnh buốt."},{"who":"A","text":"{Goi}, tên {xung} đã vào sổ Kính sự phòng, mà {xung} chưa từng xin. {Xung} nghi {B} đã đưa tên lên."},{"who":"me","text":"Tên vào sổ mà không xin, tức là có người đẩy tay. {Goi} muốn gì?"},{"who":"A","text":"Biết là ai, và người ấy muốn gì. {Goi} giúp {xung}."},{"who":"me","text":"Tên vào sổ Kính sự phòng mà {goi} chưa từng xin, nghe mà {xung} chột dạ. Hỏi ở đó phải dè dặt, dò từ đâu?"}]}},
{"id":"nr:cnv_mat_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm vắng, {A} ngồi sát bên cửa sổ, ngoài hiên có bóng người đứng im như tượng đá."},{"who":"A","text":"{Goi}, tên {xung} đã vào sổ Kính sự phòng, từ đó có người ngày đêm đứng ngoài phòng {xung}."},{"who":"me","text":"Bị canh như vậy thì ai mà ngủ yên. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cho {xung} sang ngủ ở chỗ khác mấy đêm."},{"who":"me","text":"Người đứng ngoài phòng ngày đêm không rời, giấc ngủ cũng thành tội. {Goi} nên ngủ ở nơi nào khuất mắt họ?"}]}},
{"id":"nr:cnv_mat_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều ngày thị tẩm, {A} đứng giữa phòng nhỏ, hai tay run run chỉnh lại tà áo mới, mắt không rời cánh cửa."},{"who":"A","text":"{Goi}, đêm hầu giá đầu tiên đã định, mà {xung} không biết một phép nào. Sai một bước là mang tội."},{"who":"me","text":"Nàng còn mấy ngày để học?"},{"who":"A","text":"Chỉ vài hôm. {Goi} cho {xung} một vị ma ma biết lễ, chỉ bảo {xung} trước đêm ấy."},{"who":"me","text":"Sai một bước là mang tội, mà chỉ còn vài hôm. {Xung} nhận lời tìm người dạy phép; ma ma nào kín miệng thì nhờ?"}]}},
{"id":"nr:cnv_mat_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước hầu giá, {A} nằm co trên giường, hai má đỏ bừng, tay nắm chặt tấm chăn mỏng."},{"who":"A","text":"{Goi}, đêm hầu giá đã định, mà mấy hôm nay {xung} sốt nhẹ. Hầu giá mà sốt là tội, khai bệnh thì mất dịp."},{"who":"me","text":"Khai bệnh thì mất cơ duyên, im lặng thì mang tội. {Goi} muốn gì?"},{"who":"A","text":"{Goi} xin giúp {xung} một thang thuốc hạ sốt."},{"who":"me","text":"Sốt nhẹ mà phải giấu, nghe mà {xung} thương. Thang thuốc hạ sốt, nhờ tay ai để khỏi lộ?"}]}},
{"id":"nr:cnv_mat_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng sớm, trong gian phòng chung, {A} ngồi trên giường, tay cầm một chiếc áo rách toạc, không dám nhìn ai."},{"who":"A","text":"{Goi}, từ đêm được gọi hầu giá, các cung nữ cùng phòng không ai nói với {xung} một câu, có người còn xé áo của {xung}."},{"who":"me","text":"Ghen ghét đến mức đó sao?"},{"who":"A","text":"{Xung} vẫn là kẻ hầu, chỉ xin được ở yên. {Goi} thưa với Hoàng hậu giúp, cho {xung} đổi sang phòng khác."},{"who":"me","text":"Ở chung mà không ai nói với {goi} một lời, đêm hẳn dài lắm. Xin đổi phòng, {goi} muốn đưa tới tai ai trước?"}]}},
{"id":"nr:cnv_mat_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa tiết đông, {A} co ro trong tấm áo mỏng, đứng trước cửa Nội vụ phủ, hai bàn tay tím tái."},{"who":"A","text":"{Goi}, từ đêm được gọi hầu giá, phần áo mùa đông của {xung} bị Nội vụ phủ cắt mất một nửa. {Xung} nghi người của {B} đã nói với Nội vụ phủ."},{"who":"me","text":"Cắt áo của người ta giữa mùa đông, thật tàn nhẫn. {Goi} muốn gì?"},{"who":"A","text":"{Goi} dò xem ai đã ký phiếu cắt."},{"who":"me","text":"Áo mùa đông bị cắt mất một nửa, gió lạnh tới đâu {goi} biết tới đó. Tay nào ký phiếu cắt, tra từ đâu?"}]}},
{"id":"nr:cnv_mat_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm tối, {A} ôm một gói vải nhỏ run rẩy trước cửa Đức Thọ cung, mắt đỏ như người đã khóc rất lâu."},{"who":"A","text":"{Goi}, người ta tìm thấy một gói bùa trong gối của {xung}, đồn {xung} quyến rũ Hoàng thượng bằng bùa ngải. Thái hậu ghét nhất chuyện ấy."},{"who":"me","text":"Bùa ngải trong cung là tội nặng. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa trước với Thái hậu, trước khi lời đồn đến tai bà."},{"who":"me","text":"Gói bùa trong gối mà đến tai Thái hậu thì thành tội nặng. {Xung} nhận lời thưa trước; chọn cách nào để bà nghe được lòng thật?"}]}},
{"id":"nr:cnv_mat_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn, {A} đặt gói bùa nhỏ lên bàn, mùi thuốc lạ thoang thoảng bốc lên."},{"who":"A","text":"{Goi}, gói bùa tìm thấy trong gối của {xung} có mùi thuốc lạ. Nếu biết trong đó có gì, sẽ biết nó từ đâu ra."},{"who":"me","text":"Mùi thuốc lạ ấy ai mà phân được. {Goi} muốn gì?"},{"who":"A","text":"{Goi} nhờ một thái y nghiệm giúp."},{"who":"me","text":"Mùi thuốc lạ ấy là manh mối duy nhất. {Goi} muốn biết nó là gì, mà không để ai ghi tên mình?"}]}},
{"id":"nr:cnv_ma_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giữa kho áo xếp cao như núi, {A} đứng thở dốc, tay áo xắn lên, trán lấm tấm mồ hôi."},{"who":"A","text":"{Goi}, Lưu ma ma giao {xung} việc thật đầu tiên: xếp lại cả kho áo cho kịp kỳ phát áo mùa. Một mình {xung} không kịp."},{"who":"me","text":"Còn mấy hôm nữa thì phát áo?"},{"who":"A","text":"Chỉ còn vài hôm. {Goi} cho người sang phụ {xung} một tay, {xung} không quên ơn."},{"who":"me","text":"Việc thật đầu tiên mà kho áo bừa bộn, {goi} lo cũng phải. {Xung} sẵn lòng giúp; ai là người đỡ tay nhanh nhất?"}]}},
{"id":"nr:cnv_ma_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm tối, {A} đứng trước cửa kho áo, nhìn những tấm áo bị xô lệch khắp nơi, mặt tái đi."},{"who":"A","text":"{Goi}, việc xếp kho áo Lưu ma ma giao bị ai đó làm rối hai lần trong đêm, mà cửa kho chỉ người của {B} đi ngang."},{"who":"me","text":"Làm rối hai lần thì ắt là cố ý. Hai lần ấy, đồ bị xáo trộn ra sao?"},{"who":"A","text":"Ai đã vào kho. {Goi} giúp {xung} biết."},{"who":"me","text":"Rối hai lần trong một đêm thì không phải tình cờ. Muốn bắt gặp kẻ vào kho, canh bằng cách nào?"}]}},
{"id":"nr:cnv_ma_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên bàn quản sự Nội vụ phủ, {A} lật từng trang sổ ba năm, ánh nến đổ bóng dài lên nét mực."},{"who":"A","text":"{Goi}, sổ ba năm của Nội vụ phủ hụt gần ba trăm lạng bạc gấm vóc, mà dấu ấn trên phiếu xuất là của Phùng cô cô."},{"who":"me","text":"Dấu ấn có thể bị mượn. {Goi} muốn gì?"},{"who":"A","text":"{Xung} cần thêm chứng cứ trước kỳ khóa sổ. {Goi} giúp {xung} xem hàng có đi qua tay {B} không."},{"who":"me","text":"Gần ba trăm lạng gấm vóc không tự biến mất. {Xung} nhận lời lần theo; theo dấu bằng tay nào cho kín?"}]}},
{"id":"nr:cnv_ma_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều tối, {A} đứng trước điện Trung cung, hai tay nâng một tờ sổ chép tóm, mắt nhìn lên cánh cửa đóng kín."},{"who":"A","text":"{Goi}, muốn lật sổ ba năm của Nội vụ phủ phải có lệnh Trung cung. Lưu ma ma không dám xin."},{"who":"me","text":"Lệnh Trung cung không dễ có. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp, xin bà cho soát sổ trước kỳ khóa."},{"who":"me","text":"Lệnh Trung cung là chiếc chìa mở sổ, Lưu ma ma không dám xin. Ai nên thưa thay bà?"}]}},
{"id":"nr:cnv_ma_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng Thận hình ty, {A} quỳ lặng, đôi vai gầy run lên trong gió, nhìn về phía cánh cửa sắt."},{"who":"A","text":"{Goi}, Phùng cô cô tố ngược Lưu ma ma, Thận hình ty đã giải ma ma đi chờ ngày tra. Ma ma đã già, {xung} chỉ sợ ma ma không qua nổi một trận roi."},{"who":"me","text":"Một trận roi với người già thì đáng sợ. {Goi} muốn gì?"},{"who":"A","text":"{Goi} thưa với Hoàng hậu giúp, cho ma ma được hỏi mà không bị đánh."},{"who":"me","text":"Người già chịu một trận roi, nghĩ mà xót. Xin Hoàng hậu nương tay, dùng lời nào cho mềm?"}]}},
{"id":"nr:cnv_ma_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, {A} đứng dưới mái hiên nhìn về cung của Phùng cô cô, nơi đèn vẫn sáng trắng."},{"who":"A","text":"{Goi}, Phùng cô cô tố Lưu ma ma mượn dấu, mà người làm chứng cho bà ta lại là cung nữ của {B}."},{"who":"me","text":"Chứng nhân của người bên kia thì lời nói khó tin. Cung nữ ấy ở phòng nào, {goi} có biết không?"},{"who":"A","text":"Biết cung nữ ấy được hứa gì. {Goi} giúp {xung}."},{"who":"me","text":"Chứng nhân là cung nữ của {B}, lời hứa hẳn nặng hơn lời khai. Dò nàng ấy bằng cách nào mà không động?"}]}},
{"id":"nr:cnv_ma_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều trước phiên xử án, {A} đứng ở sân Đức Thọ cung, nhìn tấm rèm lay động, nét mặt đầy hy vọng."},{"who":"A","text":"{Goi}, buổi xử án sau cùng sắp đến. Muốn cứu Lưu ma ma phải có một lời của người trên. Ma ma từng hầu ở Đức Thọ cung mười năm."},{"who":"me","text":"Mười năm hầu hạ thì Thái hậu hẳn còn nhớ. {Goi} muốn gì?"},{"who":"A","text":"{Goi} hầu Thái hậu, xin nhắc giúp bà còn nhớ người cũ."},{"who":"me","text":"Mười năm hầu ở Đức Thọ cung, Thái hậu hẳn còn nhớ ma ma. {Xung} nhận lời nhắc, chỉ chọn lối cho nhẹ."}]}},
{"id":"nr:cnv_ma_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước phiên xử án, {A} đứng bên cửa rương gỗ khóa kín của Phùng cô cô, nhìn qua khe cửa sổ, ánh mắt nặng trĩu."},{"who":"A","text":"{Goi}, sổ gốc nằm trong rương riêng của Phùng cô cô, mà người giữ chìa là người của {B}."},{"who":"me","text":"Chìa nằm trong tay người của {B} thì khó lấy. {Goi} muốn gì?"},{"who":"A","text":"{Goi} giúp {xung} biết chìa ấy cất ở đâu."},{"who":"me","text":"Chìa nằm trong tay người của {B}, muốn biết nơi cất thì hỏi ai? {Goi} đã thấy ai ra vào chỗ ấy chưa?"}]}},
{"id":"nr:cnv_ma_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sáng trước kỳ sát hạch, {A} đứng trước bảng danh sách người chấm ở Nội vụ phủ, nét mặt đầy lo âu."},{"who":"A","text":"{Goi}, kỳ sát hạch của Nội vụ phủ, Lưu ma ma ngồi ghế chấm. {Xung} nghe nói có người muốn gài người chấm thay ma ma để đánh trượt {xung}."},{"who":"me","text":"Đánh trượt một cung nữ cũng là cách đuổi người. Tin gài người chấm ấy {goi} nghe từ đâu?"},{"who":"A","text":"Biết {B} có nhúng tay không. {Goi} giúp {xung} dò."},{"who":"me","text":"Muốn gài người đánh trượt {goi}, nghe mà {xung} giận. Biết {B} có nhúng tay không, nên dò từ phía nào?"}]}},
{"id":"nr:cnv_ma_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước ngày sát hạch, {A} đứng bên hiên phòng Lưu ma ma, nhìn bóng bà ngồi một mình bên cửa sổ, nét mặt đầy xót xa."},{"who":"A","text":"{Goi}, kỳ sát hạch sắp đến, mà Lưu ma ma bị Phùng cô cô gây khó, không ai dám ngồi cạnh bà."},{"who":"me","text":"Ngồi một mình thì buổi chấm ấy bà chịu thiệt. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cho một ma ma của cung {goi} ngồi cùng bà trong buổi chấm."},{"who":"me","text":"Không ai dám ngồi cạnh Lưu ma ma trong buổi chấm, chiếc ghế bên ấy trống lạnh. Ai ngồi cùng bà thì không bị bắt bẻ?"}]}},
{"id":"nr:cnv_ma_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm lạnh, {A} đứng trước gian phòng chung của Lưu ma ma, nghe tiếng ho khàn vọng ra, tay nắm chặt cánh cửa gỗ."},{"who":"A","text":"{Goi}, Lưu ma ma ngã bệnh, mà một cung nữ già không được Thái y viện ghé đến. {Xung} không có bạc mời thầy."},{"who":"me","text":"Bệnh người già không thể để lâu. {Goi} muốn gì?"},{"who":"A","text":"Nếu {goi} quen một vị thái y, xin mời đến xem cho ma ma."},{"who":"me","text":"Người già bệnh không để lâu được. {Xung} nhận lời mời thầy; thầy ấy là ai, đưa tới bằng cách nào?"}]}},
{"id":"nr:cnv_ma_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm đông, {A} ngồi bên giường lạnh của Lưu ma ma, kéo tấm chăn mỏng lên vai bà, đôi mắt đỏ hoe."},{"who":"A","text":"{Goi}, Lưu ma ma bệnh nặng, ở chỗ chung không ai trông, đêm lạnh. {Xung} chỉ xin cho ma ma một chỗ ấm."},{"who":"me","text":"Một chỗ ấm cũng đủ cứu một người. {Goi} muốn gì?"},{"who":"A","text":"{Goi} cho ma ma sang chỗ {goi} dưỡng bệnh ít hôm."},{"who":"me","text":"Đêm đông mà thiếu chỗ ấm, nghe mà {xung} lạnh theo. Bà nên về nơi nào để khỏi lời ra tiếng vào?"}]}},
{"id":"nr:gd_tl_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng giáp sắt khẽ chạm nhau ngoài hiên, người thị vệ đứng nghiêm, tay còn nắm chặt chuôi đao như chưa quen rời cổng."},{"who":"A","text":"{Goi}, Thống lĩnh mới về nhậm chức, chưa ai biết người ưa điều gì, ghét điều gì. Vậy mà người của {B} đã kịp mang lễ đến chào."},{"who":"me","text":"Lễ đến trước người, tin cũng sẽ đến trước người. Bên ấy đã nói gì với Thống lĩnh, {goi} muốn biết điều gì nhất?"},{"who":"A","text":"Chỉ cần biết bên ấy đã thưa những lời nào. {Goi} có người qua lại các cung, xin dò giúp {xung} một chút."},{"who":"me","text":"Chuyện này không thể hỏi thẳng. {Xung} sẽ cân xem nên sai người thân tín hay nhờ một lời rỉ tai nơi bếp trà."}]}},
{"id":"nr:gd_tl_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trời vừa sáng, sương còn đọng trên mái ngói cổng cung, người thị vệ cúi đầu cung kính chờ ngoài bậc thềm."},{"who":"A","text":"{Goi}, Thống lĩnh mới là người Trung cung tiến cử. Người ấy chỉ nghe lời Hoàng hậu."},{"who":"me","text":"Vậy ra một lời của Hoàng hậu có thể đổi cả vận ca trực. {Goi} muốn nhờ {xung} nói điều gì?"},{"who":"A","text":"Nếu Hoàng hậu có dịp nghe rằng {xung} giữ cổng cung của {goi} chưa sai một khắc, Thống lĩnh sẽ để mắt đến {xung}."},{"who":"me","text":"Giữ cổng trọn một mùa mà chẳng ai hay, nghe mà chạnh lòng. Chỉ chưa rõ lời ấy nên lọt vào tai Hoàng hậu từ đâu."}]}},
{"id":"nr:gd_tl_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giờ Mão, sổ ca trực bị đem ra Nội vụ phủ, người thị vệ đứng dưới hiên, cổ áo còn ướt sương đêm."},{"who":"A","text":"{Goi}, có đồng liêu đem chuyện ca trực của {xung} kêu lên Nội vụ phủ, bảo đêm ấy {xung} đến muộn."},{"who":"me","text":"Cổng cung mở đóng theo từng khắc, một lời vu như vậy không nhẹ chút nào. Đêm ấy {goi} có đứng đủ giờ không?"},{"who":"A","text":"Thưa, đêm ấy {xung} đứng đủ giờ. {Xung} không cần ai bênh, chỉ xin {goi} nói một câu rằng đêm ấy {xung} có mặt đúng lúc."},{"who":"me","text":"{Xung} nhận lời nói giúp {goi}. Chỉ còn phải chọn nói trước mặt ai, để câu ấy tới Nội vụ phủ mà không thành chuyện lớn."}]}},
{"id":"nr:gd_tl_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua dãy phòng trực, cuốn sổ ca đặt trên bàn gỗ lật khẽ từng trang, người thị vệ nhìn mãi một dòng chữ."},{"who":"A","text":"{Goi}, có đồng liêu ghen vì {xung} được đổi lên ca ngày, mấy lần gài người lạ vào ca trực của {xung}. Bạc gài người ấy lại là bạc của {B}."},{"who":"me","text":"Người lạ đứng giữa ca trực thì chỉ cần một đêm sơ suất là có chuyện. {Goi} muốn biết điều gì trước?"},{"who":"A","text":"{Xung} cần biết kẻ được gài là ai, trước khi có chuyện xảy ra. Chỉ mong {goi} thương mà dò giúp."},{"who":"me","text":"Phải biết mặt kẻ ấy trước mới liệu được đường. {Xung} sẽ chọn lối dò nào ít để lộ nhất."}]}},
{"id":"nr:gd_tl_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc hộp cơm nhỏ đặt trên bàn, nắp mở hé, bên dưới lớp cơm là một gói bạc bọc kỹ bằng vải thô."},{"who":"A","text":"{Goi}, có người nhét gói bạc này vào hộp cơm của {xung}, nhờ đêm ấy mở cửa hông. {Xung} ngờ đó là người của {B}."},{"who":"me","text":"Chưa động đến đồng nào mà đã giữ vật nặng thế này, {goi} nhẫn nại thật. Vì sao không bỏ ngay?"},{"who":"A","text":"Bỏ đi thì mất chứng cớ, giữ lại thì sợ mang họa. Xin {goi} giữ hộ gói bạc, để sau này còn có vật làm chứng."},{"who":"me","text":"Một gói bạc mà thành chứng cứ hay thành tội, đều do nơi cất. {Xung} sẽ nghĩ kỹ nơi nào khuất mà an toàn."}]}},
{"id":"nr:gd_tl_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới hiên cổng, người thị vệ đưa mắt nhìn ra phố xa, nơi cửa cung đóng chặt chẳng cho ai bước qua một bước."},{"who":"A","text":"{Goi}, kẻ đưa bạc đêm ấy xưng là quản gia một phủ ngoài thành. {Xung} muốn biết phủ ấy có thật hay không."},{"who":"me","text":"Thị vệ không được rời cửa cung, nên {goi} chẳng thể tự mình đi hỏi. {Goi} lo điều gì nhất?"},{"who":"A","text":"Lo kẻ ấy dựng ra một cái tên không có thật. Xin {goi} cho người nhà hỏi thăm phủ ấy giúp {xung}."},{"who":"me","text":"Phủ ấy có thật hay không, chỉ người ở ngoài cổng cung hỏi được. {Xung} quen ai đủ kín miệng để nhờ chuyến này?"}]}},
{"id":"nr:gd_tl_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cờ săn thu đã dựng sẵn ngoài sân, tiếng ngựa hí vang từ chuồng xa, người thị vệ đứng thẳng như cây thương."},{"who":"A","text":"{Goi}, đợt săn thu này Hoàng thượng chọn người hộ giá theo lời Thống lĩnh. {Xung} không dám xin gì hơn."},{"who":"me","text":"Người hộ giá được cất nhắc trước mắt thánh thượng, ai chẳng mong. {Goi} chỉ mong điều gì?"},{"who":"A","text":"Chỉ mong khi thánh giá hỏi ai cưỡi ngựa vững, {goi} nhắc tên {xung}. Chỉ một lời thôi."},{"who":"me","text":"Một lời nhắc tên mà đổi cả vận số một người. {Xung} sẽ chọn lúc nào hợp để nhắc cho nhẹ nhàng."}]}},
{"id":"nr:gd_tl_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vết sẹo cũ ở vai thấp thoáng sau cổ áo, người thị vệ khẽ nhăn mày mỗi lần giơ tay, rồi vội che đi."},{"who":"A","text":"{Goi}, mùa săn năm ngoái {xung} ngã ngựa, vết thương ở vai trở trời lại đau. Thái y viện ghi tên ai đau thì không được hộ giá."},{"who":"me","text":"Vậy là đau mà không dám nói ra. Vai ấy giờ còn nhức nhiều không?"},{"who":"A","text":"Còn nhức mỗi khi trở trời. Xin {goi} cho thái y quen xem giúp {xung}, đừng ghi vào sổ."},{"who":"me","text":"Đau giấu đi thì sớm muộn cũng lộ, mà khai ra lại mất việc. {Xung} sẽ tìm cách để vết thương được xem kín đáo."}]}},
{"id":"nr:gd_tl_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sân khảo võ chưa mở, người thị vệ đứng bên giá binh khí, tay siết chặt chuôi đao, mắt dõi về phía phòng ra đề."},{"who":"A","text":"{Goi}, kỳ khảo võ năm nay, nghe nói người được {B} nâng đỡ đã biết trước đề."},{"who":"me","text":"Nếu đề đã lộ thì mọi công luyện tập đều thành vô nghĩa. {Goi} nghĩ sao về chuyện ấy?"},{"who":"A","text":"{Xung} không muốn thắng bằng mánh. Chỉ muốn biết ai đã để lộ đề ra ngoài, xin {goi} giúp một tay."},{"who":"me","text":"Biết kẻ để lộ thì mới có đường đòi công bằng. {Xung} sẽ dò theo đường kín, không để ai hay biết."}]}},
{"id":"nr:gd_tl_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bảng danh sách khảo võ treo dưới mái hiên, người thị vệ đứng nhìn một khoảng trống nơi tên mình đã bị gạch bỏ."},{"who":"A","text":"{Goi}, danh sách khảo võ năm nay do Nội vụ phủ lập, mà tên {xung} bị gạch vì một lần vắng ca."},{"who":"me","text":"Một lần vắng ca mà mất cả cơ hội dự khảo, nghe thật oan. Vì sao lần ấy {goi} vắng?"},{"who":"A","text":"Lần ấy {xung} theo lệnh Trung cung đi đón nữ quan. Xin {goi} thưa với Hoàng hậu, cho tên {xung} được ghi lại."},{"who":"me","text":"Việc theo lệnh Trung cung mà bị tính là lỗi, thật chẳng công bằng. {Xung} sẽ nghĩ cách thưa cho khéo."}]}},
{"id":"nr:gd_tl_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiều muộn, người thị vệ cầm một lá thư tiến cử đã nhàu mép, nét chữ của Thống lĩnh vẫn còn rõ trên giấy."},{"who":"A","text":"{Goi}, Thống lĩnh đã viết thư tiến cử {xung}, nhưng lá thư nằm ở Binh bộ đã nửa tháng, chưa thấy hồi âm."},{"who":"me","text":"Nửa tháng mà chẳng có tin, e rằng đã bị giữ lại giữa đường. {Goi} muốn nhờ {xung} điều gì?"},{"who":"A","text":"Xin {goi} hỏi giúp lá thư ấy đang ở tay ai. {Xung} không có đường nào ra ngoài cung để hỏi."},{"who":"me","text":"Thư đã đi mà không đến thì ắt có người giữ. {Xung} sẽ lần theo đường thư để biết nó dừng ở đâu."}]}},
{"id":"nr:gd_tl_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đèn nến trong điện sáng suốt đêm, người thị vệ đứng nép dưới hiên, mắt nhìn về phía chỗ ngự thư phòng."},{"who":"A","text":"{Goi}, Hoàng thượng sắp chọn người làm Phó thống lĩnh. Thư tiến cử chỉ là giấy, lời của người được tin mới nặng."},{"who":"me","text":"Một lời đúng lúc có sức nặng hơn cả trăm thư tiến cử. {Goi} xin {xung} nói điều gì?"},{"who":"A","text":"Nếu Hoàng thượng hỏi thị vệ nào giữ cổng cẩn thận, xin {goi} nói thật tên {xung}. Chỉ cần thật thôi."},{"who":"me","text":"Chỉ cần nói thật mà {goi} cũng phải chờ đúng lúc, nghe thật xót. {Xung} đang nhẩm xem lúc nào Hoàng thượng mới hỏi đến chuyện cổng cung."}]}},
{"id":"nr:gd_tinh_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bóng hòe in dài trên nền gạch lạnh, người thị vệ cầm chặt một nhành hòe khô vừa nhặt, nghĩ mãi về một lời hẹn."},{"who":"A","text":"{Goi}, cung nữ ấy hẹn {xung} dưới cây hòe một đêm, mà ca trực của {xung} lại trùng đúng đêm ấy."},{"who":"me","text":"Lời hẹn mà không đến, nàng ấy sẽ nghĩ gì? {Goi} lo điều gì nhất?"},{"who":"A","text":"{Xung} không dám bỏ cổng. Xin {goi} gọi nàng sang cung {goi} một lát, để nàng nhắn lại cho {xung} một lời."},{"who":"me","text":"Một lời nhắn nhỏ mà nặng lòng người. {Xung} sẽ tìm một cớ thật hợp lẽ, không để ai nghi ngờ."}]}},
{"id":"nr:gd_tinh_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm xuống, ngọn đèn lồng dưới cây hòe lung lay, người thị vệ nhìn quanh, giọng hạ thấp hẳn."},{"who":"A","text":"{Goi}, đúng đêm hẹn ấy có kẻ xin đổi ca để đứng đúng cổng gần cây hòe, mà kẻ ấy là người {B} cài vào."},{"who":"me","text":"Trùng hợp đến thế thì hẳn có người đã nghe lời hẹn. Trong những người từng nghe lời hẹn ấy, {goi} đã ngờ ai chưa?"},{"who":"A","text":"{Xung} sợ {B} đã biết lời hẹn. Xin {goi} dò giúp ai đã kể chuyện ấy cho {B}."},{"who":"me","text":"Lời hẹn kín mà còn lọt ra ngoài, thì kẻ nghe đã ở rất gần. {Xung} sẽ dò theo từng người từng lối."}]}},
{"id":"nr:gd_tinh_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ nhỏ nằm trong tay áo của tên thái giám, người thị vệ nhìn theo bước chân hắn đến khi khuất sau cột hiên."},{"who":"A","text":"{Goi}, có một thái giám cứ ghi giờ {xung} đổi ca vào một cuốn sổ nhỏ. Mỗi lần ghi đều liếc nhìn quanh."},{"who":"me","text":"Ghi giờ đổi ca của một thị vệ thì có ích gì? {Goi} đoán hắn làm việc cho ai?"},{"who":"A","text":"{Xung} cần biết hắn ghi cho {B} hay cho ai khác xem. Chỉ vậy thôi."},{"who":"me","text":"Biết hắn ghi cho ai thì mới biết ai đang rình. {Xung} sẽ chọn đường dò nào kín đáo nhất."}]}},
{"id":"nr:gd_tinh_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cửa cung, người thị vệ đứng nghiêm, nét mặt căng như dây cung, trong tay là mảnh giấy ghi sổ trực."},{"who":"A","text":"{Goi}, thái giám ghi sổ kia đã trình Trung cung rằng {xung} hay đứng lâu trước một cửa cung. Cửa ấy là cửa cung {goi}."},{"who":"me","text":"Vậy ra {goi} đứng đó theo lệnh, mà người ta lại báo thành lỗi. Ai giao {goi} trực chỗ ấy?"},{"who":"A","text":"Chính cung {goi} xin người trực. Xin {goi} thưa với Hoàng hậu rằng cung {goi} xin người đứng đó."},{"who":"me","text":"Một câu nói rõ nguồn gốc là đủ gỡ cả hiểu lầm. {Xung} sẽ nghĩ cách thưa cho Hoàng hậu nghe mà không phật lòng."}]}},
{"id":"nr:gd_tinh_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư gấp tư nằm trong lòng bàn tay người thị vệ, nét chữ vụng về mà nắn nót từng nét."},{"who":"A","text":"{Goi}, nhà cung nữ ấy ở ngoài thành. {Xung} viết được thư, mà không gửi được."},{"who":"me","text":"Một lá thư nhỏ mà vượt cả tường cung cũng khó. {Goi} muốn nhờ {xung} điều gì?"},{"who":"A","text":"Xin {goi} cho lá thư đi chung với thư nhà của {goi}."},{"who":"me","text":"Một lá thư nhỏ mà mang theo cả lòng hai người. Trao nhầm tay người đưa, nó sẽ rơi vào mắt kẻ không nên đọc."}]}},
{"id":"nr:gd_tinh_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tro thư còn vương trên nền, người thị vệ nhìn đống tàn đen với ánh mắt buồn bã, không nói gì suốt một lúc."},{"who":"A","text":"{Goi}, cung nữ ấy sợ đến mức đốt cả thư của {xung}, vì chủ của nàng hay lục rương."},{"who":"me","text":"Đốt thư thì cũng như đốt một phần lòng. Nàng ấy sống như vậy đã lâu chưa?"},{"who":"A","text":"Đã lâu rồi. Nếu {goi} xin nàng sang hầu cung {goi} một mùa, nàng không phải sợ mỗi lần có thư."},{"who":"me","text":"Đốt thư mà vẫn phải cười như chẳng có gì, nàng chịu thế đã quá lâu. {Xung} muốn xin nàng về, chỉ chưa rõ nên xin ai gật đầu."}]}},
{"id":"nr:gd_tinh_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ lệnh đổi ca nằm trên bàn, mực đã khô, chỉ còn thiếu dấu đóng, người thị vệ nhìn nó như nhìn một bản án."},{"who":"A","text":"{Goi}, lệnh đổi {xung} ra canh lăng tẩm đã viết xong, chỉ còn chờ đóng dấu."},{"who":"me","text":"Canh lăng tẩm là nơi xa vắng, rời cung là rời hết quen thuộc. Còn đường nào gỡ được không?"},{"who":"A","text":"Nếu {goi} xin giữ lại một thị vệ quen việc ở cửa cung {goi}, lệnh ấy còn có thể sửa."},{"who":"me","text":"Rời cửa cung quen mắt để ra lăng tẩm vắng, nghĩ đã thấy lạnh. Lệnh chưa đóng dấu thì còn kịp, nhưng kịp bằng lời của ai?"}]}},
{"id":"nr:gd_tinh_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Giờ Thân, nắng xiên qua cổng tây, người thị vệ đứng sát tường, mắt không rời con đường ngự giá thường qua."},{"who":"A","text":"{Goi}, Hoàng thượng hay đi qua cổng tây vào giờ Thân. Nếu người hỏi vì sao cổng ấy đổi người, lệnh đổi ca của {xung} sẽ phải tâu lại."},{"who":"me","text":"Một câu hỏi từ thánh giá có thể lật cả lệnh đã định. {Goi} xin {xung} nói điều gì?"},{"who":"A","text":"Khi {goi} đi cùng thánh giá, xin nhắc rằng thị vệ cũ đứng đó vẫn vững."},{"who":"me","text":"Một câu nhắc nhẹ mà phải đúng lúc đúng nơi. {Xung} sẽ chọn dịp nào để thánh giá nghe vào lòng."}]}},
{"id":"nr:gd_tinh_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lời đồn lan nhanh như gió thoảng qua dãy hành lang, người thị vệ cúi đầu nghe tiếng thì thầm sau mỗi cánh cửa."},{"who":"A","text":"{Goi}, {B} đang đồn khắp nơi rằng {xung} tư tình với người trong cung. Nếu lời đồn chạm đến tên nàng, nàng sẽ bị đuổi ra Tân Giả khố."},{"who":"me","text":"Một lời đồn nhẹ như khói mà đủ hủy cả đời người con gái. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Chỉ xin {goi} chặn lời ấy ở cung {goi}. Đừng để nó đi xa hơn nữa."},{"who":"me","text":"Lời đồn như khói, chặn ở cung này mà hở một khe thì khói lại thoát ra. {Xung} đang nhớ xem trong cung ai hay buôn chuyện nhất."}]}},
{"id":"nr:gd_tinh_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm từ Đức Thọ cung bay ra tận cổng, người thị vệ đứng xa, nhìn mái cung với vẻ lo lắng."},{"who":"A","text":"{Goi}, Thái hậu ghét nhất chuyện tư tình trong cung. Nếu lời đồn đến Đức Thọ cung trước, nàng không còn đường sống."},{"who":"me","text":"Đức Thọ cung là nơi lời đồn không được phép đến sớm. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} khi hầu Thái hậu, nói rằng lời đồn về {xung} chưa ai thấy tận mắt."},{"who":"me","text":"Một câu nói nhẹ mà phải đặt đúng lúc Thái hậu còn chưa nghe điều gì khác. {Xung} sẽ chọn lúc hầu cho vừa."}]}},
{"id":"nr:gd_tinh_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây hòe cổ đứng im trong gió chiều, người thị vệ nhìn về phía cây hòe, tay siết chặt chuôi đao."},{"who":"A","text":"{Goi}, Thống lĩnh muốn gả cháu gái cho {xung}; nhận thì được thăng, từ thì mất đường."},{"who":"me","text":"Nhận hay từ đều có cái giá, mà lòng {goi} thì đã có người. {Goi} định tính thế nào?"},{"who":"A","text":"{Xung} chỉ xin {goi}, nếu có dịp, xin Thái hậu ban ân cho nàng ra cung sớm một năm, {xung} sẽ có lời đáp Thống lĩnh."},{"who":"me","text":"Một lời xin cho nàng ra cung sớm mà phải khéo đến thế. {Xung} đang nhớ xem Thái hậu thường vui nhất vào lúc nào."}]}},
{"id":"nr:gd_tinh_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng ủng nặng nề vang lên ở cổng phụ, người thị vệ khẽ liếc về phía hậu cung, ánh mắt đầy lo toan."},{"who":"A","text":"{Goi}, nếu {xung} từ hôn cháu gái Thống lĩnh, người đầu tiên bị trả thù là nàng."},{"who":"me","text":"Người yếu thế nhất thường là người chịu trận trước. {Goi} đã nghĩ cách bảo vệ nàng chưa?"},{"who":"A","text":"Xin {goi} nhận nàng vào hầu cung {goi}; ở đó Thống lĩnh không với tay tới."},{"who":"me","text":"Nàng ấy chưa làm gì sai mà đã phải trốn. {Xung} muốn nhận nàng vào cung, chỉ ngại Thống lĩnh nghe tin trước khi nàng kịp đến."}]}},
{"id":"nr:gd_kho_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới chân tường ngự khố, vệt giày in trên nền đất ẩm còn rõ từng đường chỉ, người thị vệ nhìn nó mà siết chặt tay."},{"who":"A","text":"{Goi}, dấu giày dưới chân tường ngự khố là cỡ giày người nội cung, không phải thị vệ, vậy mà {B} một mực bảo đó là dấu giày của {xung}."},{"who":"me","text":"Giày thị vệ và giày nội cung khác nhau thế nào, ai nhìn cũng phân được. Sao {B} lại cố nói vậy?"},{"who":"A","text":"{Xung} cũng không rõ. Chỉ mong biết đêm ấy cung nào có người đi khuya. {Goi} qua lại các cung, xin hỏi giúp."},{"who":"me","text":"Một vệt giày mà đẩy oan cho cả một người. Hỏi sao cho kín, {xung} còn phải cân nhắc."}]}},
{"id":"nr:gd_kho_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc chổi tre dựa góc tường ngự khố, đứa trẻ quét sân co người sau cột, chẳng dám ngẩng mặt nhìn ai."},{"who":"A","text":"{Goi}, tiểu thái giám quét sân ngự khố đã thấy dấu giày trước {xung}, mà nó không dám nói vì có kẻ dọa."},{"who":"me","text":"Một đứa trẻ giữ trong lòng cả một sự thật nặng như vậy. Nó sợ ai đến mức không dám mở lời?"},{"who":"A","text":"Nó sợ kẻ đã dọa nó. Xin {goi} cho nó về hầu cung {goi} ít hôm, để nó dám nói thật."},{"who":"me","text":"Đứa nhỏ run đến thế mà vẫn giữ trong lòng một sự thật. {Xung} muốn đón nó về, nhưng đón sao để kẻ dọa nó không hay?"}]}},
{"id":"nr:gd_kho_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nửa chiếc chìa khóa đồng nằm trên lòng bàn tay người thị vệ, mép gãy còn sắc, ánh đồng mờ mờ dưới ánh đèn."},{"who":"A","text":"{Goi}, {xung} nhặt được nửa chiếc chìa khóa đồng này gần cửa khố. Để ở chỗ {xung} thì sớm muộn cũng bị {B} sai người khám mất."},{"who":"me","text":"Nửa chiếc chìa mà cũng đủ làm chứng. {Goi} muốn nhờ {xung} điều gì?"},{"who":"A","text":"Xin {goi} cất giữ giúp, đợi ngày trình án."},{"who":"me","text":"Giữ vật chứng cũng là giữ một phần mạng người. {Xung} sẽ chọn nơi nào chẳng ai dám động tới."}]}},
{"id":"nr:gd_kho_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách người canh ngự khố được viết nắn nót trên giấy, tên người thị vệ đứng đầu, mực đen đậm hơn mọi dòng."},{"who":"A","text":"{Goi}, Trung cung sắp gọi những người canh ngự khố lên hỏi, {xung} đứng đầu danh sách chỉ vì đêm ấy trực gần cửa."},{"who":"me","text":"Đứng gần cửa thì nghi ngờ rơi vào trước, thật bất công. {Goi} mong điều gì?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu cho hỏi cả người nội cung, đừng chỉ hỏi thị vệ."},{"who":"me","text":"Đứng gần cửa mà bị ngờ trước, ai nghe cũng thấy bất công. {Goi} muốn Hoàng hậu hỏi rộng ra, vậy lời thưa nên đến vào lúc nào?"}]}},
{"id":"nr:gd_kho_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước buổi thẩm vấn, người thị vệ đứng ngoài hiên Thận Hình ti, bóng đổ dài lên bức tường lạnh."},{"who":"A","text":"{Goi}, Thận Hình ti sắp đòi {xung} lên hỏi. Đêm mất đồ, {xung} đứng canh cửa cung {goi} suốt đêm."},{"who":"me","text":"Đêm ấy cửa cung chẳng hề mở, chỉ cần một lời chứng là đủ sao?"},{"who":"A","text":"Chỉ cần một lời của {goi}, roi vọt sẽ dừng. {Xung} không dám xin gì khác."},{"who":"me","text":"Một lời thật mà cứu được cả một người, {xung} không thể đứng ngoài. Còn phải chọn cách nói cho vừa."}]}},
{"id":"nr:gd_kho_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc áo thị vệ rách toạc sau lưng, vải dính máu khô, người thị vệ đứng nghiêng người để che vết thương."},{"who":"A","text":"{Goi}, sau buổi tra, lưng {xung} rách mấy chỗ, mà Thái y viện không chữa cho người đang mang án."},{"who":"me","text":"Mang án chưa kết mà đã bị bỏ mặc, thật khắc nghiệt. Vết thương còn đau lắm không?"},{"who":"A","text":"Đau, nhưng {xung} còn phải đứng vững ở buổi xét sau. Xin {goi} cho {xung} chút thuốc trị thương."},{"who":"me","text":"Một chút thuốc đủ giữ người ấy đứng vững. {Xung} sẽ chọn cách đưa thuốc sao cho không ai hay."}]}},
{"id":"nr:gd_kho_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hiệu cầm đồ ngoài cửa Tây Hoa đèn còn sáng, chiếc như ý ngọc nằm giữa quầy, người thị vệ chỉ nghe kể lại mà lòng nặng trĩu."},{"who":"A","text":"{Goi}, chiếc như ý ngọc mất ở ngự khố vừa thấy bày ở một hiệu cầm đồ ngoài cửa Tây Hoa. {Xung} không được ra cung."},{"who":"me","text":"Ngọc ấy mà lộ ra ngoài thì đường truy tìm sáng hơn nhiều. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} cho người ra hỏi ai đã đem nó đến."},{"who":"me","text":"Ngọc đã lộ ngoài cửa Tây Hoa, giờ chỉ thiếu một đôi chân đi hỏi. {Xung} đang nghĩ đến một người vừa kín miệng vừa nhanh chân."}]}},
{"id":"nr:gd_kho_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng rao hàng ngoài phố vọng vào tận hiên, người thị vệ đứng im, lắng nghe như thể có thể nghe thấy giọng người xa lạ ấy."},{"who":"A","text":"{Goi}, chủ hiệu cầm đồ khai người đem như ý đến mặc áo thái giám, nói giọng phương bắc. Người của {B} có một kẻ như thế."},{"who":"me","text":"Giọng phương bắc lẫn trong cung thì không nhiều. {Goi} muốn biết điều gì?"},{"who":"A","text":"Xin {goi} dò giúp {xung} kẻ ấy hầu ở cung nào."},{"who":"me","text":"Giọng phương bắc, áo thái giám, người của {B}, chừng ấy cũng gần chỉ ra một gương mặt. Hỏi gấp thì kẻ ấy sẽ biết mình đã bị để mắt."}]}},
{"id":"nr:gd_kho_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hồ sơ vụ án ngự khố trải trên bàn, mọi dấu vết đều gom về một cái tên, người thị vệ nhìn nó mà chẳng dám mở lời."},{"who":"A","text":"{Goi}, mọi dấu vết đều dẫn về một viên quan Nội vụ phủ, mà người ấy có chỗ dựa trong triều."},{"who":"me","text":"Có chỗ dựa thì đụng vào cũng như đụng vào cả một cây lớn. {Goi} lo điều gì nhất?"},{"who":"A","text":"{Xung} cần biết chỗ dựa ấy là ai trước khi dám trình án."},{"who":"me","text":"Đụng vào cây lớn mà chưa biết rễ nó ở đâu, {xung} thấy gai người. Trước hết phải tìm một người trong triều chịu nói thật."}]}},
{"id":"nr:gd_kho_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng chuông chùa vọng về từ Đức Thọ cung, người thị vệ nhìn về phía ấy với vẻ e dè như đang đứng trước một cánh cửa đóng."},{"who":"A","text":"{Goi}, viên quan Nội vụ phủ kia là họ hàng xa bên ngoại Thái hậu."},{"who":"me","text":"Họ hàng của Thái hậu mà dính vào án thì ắt khó nói. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu Thái hậu biết trước vụ án, người sẽ không nổi giận với kẻ trình án. Xin {goi} khéo thưa trước, để {xung} còn đường đi."},{"who":"me","text":"Một lời thưa trước đúng lúc có thể mở cả đường sống. {Xung} sẽ cân nhắc kỹ thời điểm và cách nói."}]}},
{"id":"nr:gd_kho_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hồ sơ án ngự khố đã buộc gọn bằng dây đỏ, người thị vệ đặt nó lên bàn, tay vẫn còn chưa nỡ buông."},{"who":"A","text":"{Goi}, hồ sơ án đã đủ, nhưng Thống lĩnh không dám trình vì dính đến người trên."},{"who":"me","text":"Án đủ mà không ai dám trình thì cũng như chưa từng có. {Goi} mong điều gì?"},{"who":"A","text":"{Xung} chỉ xin {goi}: nếu Hoàng thượng tự hỏi đến vụ ngự khố, án sẽ không bị dìm."},{"who":"me","text":"Án đủ mà nằm im, thế là tội của kẻ sợ. {Xung} sẽ giúp {goi}, chỉ cần tìm một dịp để Hoàng thượng tự mở lời hỏi."}]}},
{"id":"nr:gd_kho_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ đồ của Trung cung nằm trên án trong gian phòng, bìa đã sờn, người thị vệ đứng cách xa, chẳng dám đến gần."},{"who":"A","text":"{Goi}, án ngự khố có dính đến sổ đồ của Trung cung."},{"who":"me","text":"Sổ đồ ấy mà đem ra đối chiếu thì nhiều người sẽ không yên. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"Nếu Hoàng hậu cho đem sổ ra đối chiếu ngay buổi trình, người trên không kịp dìm án của {xung}. Xin {goi} thưa với Hoàng hậu một lời."},{"who":"me","text":"Một lời thưa hợp lẽ có thể đổi cả buổi trình. {Xung} sẽ cân nhắc xem nên nói thế nào cho Hoàng hậu thuận tai."}]}},
{"id":"nr:ty_thu_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn y thư mở sẵn trên án, một trang mép đã ố vàng, người thái y nhìn mãi một tên vị thuốc lạ."},{"who":"A","text":"{Goi}, y thư chép một vị thuốc tên lạ, {xung} đoán là cây cỏ mọc ở phương nam."},{"who":"me","text":"Tên lạ trong y thư mà không ai biết thì thật khó chữa bệnh. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"Xin {goi} viết thư về nhà, hỏi giúp người quê gọi nó là gì."},{"who":"me","text":"Một tên thuốc nơi quê nhà mà giữ được bao người bệnh, {xung} nghe mà nôn nóng. Thư viết sao để người quê đọc là hiểu ngay?"}]}},
{"id":"nr:ty_thu_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngọn đèn trong phòng thuốc cháy nhỏ, người thái y ngồi một mình, bên cạnh cuốn y thư nay đã mở nhiều lần."},{"who":"A","text":"{Goi}, đã ba lần người của {B} đến hỏi mượn cuốn y thư của {xung}, lần nào cũng đúng lúc {xung} vừa đọc ra một vị."},{"who":"me","text":"Ba lần đều trùng thì không phải ngẫu nhiên. {Goi} nghĩ sao?"},{"who":"A","text":"{Xung} ngờ có kẻ trong cung báo tin. Xin {goi} dò giúp kẻ báo tin ấy."},{"who":"me","text":"Biết ai ngồi sau lưng mình là việc cần làm trước nhất. {Xung} sẽ chọn đường dò nào ít để lộ."}]}},
{"id":"nr:ty_thu_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nồi thuốc vừa sắc xong còn tỏa hơi nóng, mùi đắng thấm cả căn phòng, người thái y đứng bên, hai tay đặt khẽ lên thành sứ."},{"who":"A","text":"{Goi}, phương thuốc đã sắc xong, cần người bệnh chịu uống thử."},{"who":"me","text":"Phương mới thì phải có người dám thử. {Goi} đã nghĩ đến ai chưa?"},{"who":"A","text":"Trong cung {goi} có một cung nhân ho đã lâu, Thái y viện bỏ không chữa. Xin cho {xung} được xem bệnh cho người ấy."},{"who":"me","text":"Người ho đã lâu mà chẳng ai chịu nhìn đến, {xung} nghĩ mà thương. Chỉ không biết đưa nàng vào cung có kẻ nào để ý mà đồn đi."}]}},
{"id":"nr:ty_thu_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phép trong cung đóng trên tờ giấy treo cạnh cửa Thái y viện, người thái y đứng đọc, mày chau lại."},{"who":"A","text":"{Goi}, phép trong cung, thuốc lạ muốn thử cho cung nhân phải có lời của Trung cung."},{"who":"me","text":"Không có lời của Trung cung thì dù thuốc có hay cũng không dám dùng. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"{Xung} không dám tự xin. Xin {goi} thưa với Hoàng hậu rằng chính cung {goi} muốn thử phương thuốc ấy."},{"who":"me","text":"Nếu lời ấy từ cung mình thì nhẹ nhàng hơn nhiều. {Xung} sẽ cân nhắc xem nên thưa theo lối nào."}]}},
{"id":"nr:ty_thu_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hương trầm trong Đức Thọ cung quyện với mùi thuốc, người thái y đứng ngoài, nhìn vào bên trong với ánh mắt lo lắng."},{"who":"A","text":"{Goi}, Thái hậu tin Thái y viện. Viện phán gọi thang thuốc của {xung} là tà thuật."},{"who":"me","text":"Nếu Thái hậu nghe lời viện phán thì thang thuốc ấy khó có đường sống. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} kể với Thái hậu rằng thang thuốc của {xung} đã giúp người khỏi bệnh, viện phán sẽ không dám gọi đó là tà thuật nữa."},{"who":"me","text":"Người khỏi bệnh là bằng chứng sống, ai cãi nổi. Chỉ là lời kể trước Thái hậu phải dịu mà thật, {xung} cần nhắc lại từng câu cho kỹ."}]}},
{"id":"nr:ty_thu_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin đồn lan qua Thái y viện nhanh như khói, người thái y đứng giữa sân, nghe mọi người thì thầm mà không ai dám nhìn thẳng."},{"who":"A","text":"{Goi}, lời gọi phương thuốc của {xung} là tà thuật do người của {B} tung ra, rồi mới lan khắp Thái y viện."},{"who":"me","text":"Một lời tung ra có chủ ý thì phải có kẻ cầm đầu. Trong Thái y viện, {goi} ngờ lời ấy lọt vào tai vị nào đầu tiên?"},{"who":"A","text":"{Xung} cần biết lời ấy đến tai vị viện phán nào trước tiên."},{"who":"me","text":"Lần ra đầu mối thì mới gỡ được cả mớ. {Xung} sẽ dò theo từng người từng bước."}]}},
{"id":"nr:ty_thu_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài thành, khói bếp thuốc bốc lên không ngớt, người thái y đứng nơi cửa cung, mặt mày mệt mỏi vì thiếu ngủ."},{"who":"A","text":"{Goi}, dịch ngoài thành mỗi ngày một rộng. Phương thuốc cứu được người, nhưng phải có chỉ dụ mở kho dược liệu."},{"who":"me","text":"Phương thuốc có mà kho thuốc đóng thì cũng bằng không. {Goi} xin {xung} điều gì?"},{"who":"A","text":"{Goi} được gần thánh giá, xin tâu giúp {xung} một lời."},{"who":"me","text":"Một lời tâu cứu được cả muôn người. {Xung} sẽ chọn lúc thích hợp để nhắc đến dịch cho Hoàng thượng nghe."}]}},
{"id":"nr:ty_thu_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa lạnh phủ đầy ngoài thành, đứa trẻ mồ côi ngồi co ro bên mái hiên một túp lều tạm, mắt nhìn người đi qua."},{"who":"A","text":"{Goi}, trong đám người bệnh ngoài thành có đứa con mồ côi của một cung nữ cũ. {Xung} không mang nó vào cung được."},{"who":"me","text":"Con của một cung nữ cũ mà phải chịu cảnh ấy, thật đáng thương. {Goi} mong điều gì?"},{"who":"A","text":"Xin {goi} sai người nhà nhận nuôi nó qua mùa dịch."},{"who":"me","text":"Đứa trẻ mồ côi chẳng có tội gì mà phải đứng ngoài cửa cung giữa mùa dịch. Người nhà đáng tin của {xung}, rốt cuộc là ai?"}]}},
{"id":"nr:ty_thu_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trang bản nháp viết tay còn nguyên dấu ngày tháng, nét mực đậm nhạt khác nhau, người thái y cầm nó như cầm chứng cứ cuối cùng."},{"who":"A","text":"{Goi}, có đồng liêu đang trình phương thuốc của {xung} lên viện phán như của hắn."},{"who":"me","text":"Cướp công như thế thì thật quá đáng. {Goi} có gì làm bằng không?"},{"who":"A","text":"Bản nháp viết tay của {xung} có ghi ngày tháng. Xin {goi} đem bản nháp đến viện phán; lời của {goi}, viện phán không dám bỏ qua."},{"who":"me","text":"Bản nháp có ngày tháng, kẻ cướp công chối sao được. Chỉ lo giữa đường nó bị chặn, nên người mang đi phải thật vững."}]}},
{"id":"nr:ty_thu_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bát thuốc đắng còn vương trên bàn trà của Đức Thọ cung, người thái y khẽ cúi đầu, giọng nhỏ như tiếng thở."},{"who":"A","text":"{Goi}, Thái hậu từng uống thang thuốc ấy khi trở trời, người còn nhớ vị đắng lạ."},{"who":"me","text":"Người còn nhớ vị đắng ấy thì có lẽ cũng nhớ ai bốc thuốc. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} kể với Thái hậu ai là người bốc thang, Thái y viện không ai dám nhận công của {xung} nữa."},{"who":"me","text":"Thái hậu đã nhớ vị thuốc, chỉ cần nhắc người nhớ thêm người bốc thuốc. {Xung} sẽ chọn lúc người vui lòng nhất."}]}},
{"id":"nr:ty_thu_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ba quyển y thư xếp ngay ngắn trên án, bìa vải còn mới, người thái y đặt tay lên sách như đặt lên một bảo vật."},{"who":"A","text":"{Goi}, y thư đã chép lại đủ ba quyển. Dâng qua viện phán thì sách sẽ đổi tên người soạn."},{"who":"me","text":"Công sức cả đời mà bị đổi tên thì còn đau hơn cả mất sách. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} đặt sách lên án thư của Hoàng thượng, với đúng tên người đã soạn."},{"who":"me","text":"Sách đến tay thánh thượng với đúng tên người soạn là tâm nguyện lớn nhất. {Xung} sẽ chọn lúc nào để dâng cho khéo."}]}},
{"id":"nr:ty_thu_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ giấy trắng còn để trống đầu quyển sách, người thái y nhìn nó như nhìn một ô cửa chưa mở."},{"who":"A","text":"{Goi}, sách thuốc dâng lên phải có người viết lời tựa."},{"who":"me","text":"Một dòng lời tựa của người có địa vị thì sách mới có sức nặng. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu Trung cung ban một dòng tựa, viện phán không dám đổi tên người soạn. Xin {goi} xin Hoàng hậu một dòng ấy cho sách của {xung}."},{"who":"me","text":"Một dòng tựa của Hoàng hậu thì viện phán cũng phải nể. Có điều xin tựa là xin một ân, {xung} không muốn Trung cung nghĩ mình mượn thế."}]}},
{"id":"nr:ty_tra_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hành lang từ Ngự dược phòng dẫn ra cung bệnh nhân vắng người, người thái y đếm từng bước, đếm cả từng người đã đi qua."},{"who":"A","text":"{Goi}, thang thuốc đi từ Ngự dược phòng đến cung bệnh nhân qua bốn người. {Xung} biết ba, còn người thứ tư mặc áo thái giám của một cung khác."},{"who":"me","text":"Người thứ tư mà không ai biết thì thuốc tráo ở đâu cũng được. Hắn có gì khả nghi?"},{"who":"A","text":"Hôm ấy hắn đứng nói chuyện với {B}. Xin {goi} dò giúp hắn là người cung nào."},{"who":"me","text":"Áo thái giám của cung khác mà đứng nói chuyện với {B}, đáng nhớ lắm. Dò hắn phải kín, kẻo hắn biến mất trước khi mình đoán ra."}]}},
{"id":"nr:ty_tra_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ nhận thuốc của Ngự dược phòng cất trong tủ khóa, người thái y đứng nhìn khóa ấy với ánh mắt thấp thỏm."},{"who":"A","text":"{Goi}, sổ nhận thuốc của Ngự dược phòng phải có dấu Trung cung mới được mở."},{"who":"me","text":"Có dấu Trung cung thì mới mở được sổ, đó là phép. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"Nếu Hoàng hậu cho mở sổ, {xung} sẽ biết bốn người ký nhận là ai. Xin {goi} thưa giúp {xung} một câu."},{"who":"me","text":"Mở được sổ là biết bốn người ký nhận. Chỉ không rõ Hoàng hậu có đang để tâm đến vụ tráo thuốc này hay không."}]}},
{"id":"nr:ty_tra_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mảnh giấy nhàu nằm trong lòng bàn tay người thái y, vài chữ vội vàng, nét mực còn chưa khô hẳn."},{"who":"A","text":"{Goi}, đêm qua có kẻ để lại mảnh giấy trước cửa phòng {xung}: im miệng thì sống. {Xung} không sợ cho thân mình."},{"who":"me","text":"Bị dọa mà vẫn còn lo cho người khác, {goi} thật có lòng. {Goi} sợ cho ai?"},{"who":"A","text":"{Xung} chỉ sợ cho đứa học trò nhỏ ở Ngự dược phòng. Xin {goi} cho nó về hầu thuốc trong cung {goi} ít lâu."},{"who":"me","text":"Mảnh giấy dọa kia {goi} không sợ, chỉ sợ cho đứa nhỏ. {Xung} hiểu rồi, giờ phải đón nó về cho khéo, đừng để ai kịp ngờ."}]}},
{"id":"nr:ty_tra_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nét chữ trên mảnh giấy dọa đen và đậm, người thái y soi dưới ánh đèn, ngón tay khẽ lướt qua từng nét như quen thuộc."},{"who":"A","text":"{Goi}, mảnh giấy dọa {xung} viết bằng thứ mực Thái y viện dùng để kê đơn, mà kẻ đặt nó trước cửa là người bên {B}."},{"who":"me","text":"Mực kê đơn thì không phải ai cũng có. Hắn lấy mực ấy từ tay ai, {goi} đã ngờ ai chưa?"},{"who":"A","text":"Xin {goi} dò giúp kẻ ấy đã lấy mực từ tay ai."},{"who":"me","text":"Lần ra thứ mực là lần ra được kẻ viết. {Xung} sẽ chọn đường hỏi nào ít đánh động."}]}},
{"id":"nr:ty_tra_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Người bệnh nằm thở khó trên giường, mùi thuốc giải còn thiếu một vị, người thái y đứng bên, mồ hôi rịn trên trán."},{"who":"A","text":"{Goi}, bệnh nhân trở nặng vì thuốc bị tráo. {Xung} có phương giải, nhưng thiếu một vị sâm núi mà Ngự dược phòng không chịu cấp cho thái y."},{"who":"me","text":"Thiếu một vị thuốc mà có thể mất một mạng người. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu cung {goi} đứng tên xin lĩnh, Ngự dược phòng không dám từ chối."},{"who":"me","text":"Chỉ thiếu một vị sâm núi mà thuốc giải chưa thành. Đứng tên cung {xung} xin lĩnh thì dễ, nhưng trễ một canh là mất cả người bệnh."}]}},
{"id":"nr:ty_tra_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bóng đêm phủ kín hành lang dẫn vào Đức Thọ cung, người thái y đứng chờ ngoài cổng, hơi thở gấp gáp."},{"who":"A","text":"{Goi}, bệnh nhân là một ma ma hầu Thái hậu đã lâu."},{"who":"me","text":"Người hầu Thái hậu lâu năm mà gặp họa thì nặng lòng người lắm. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"Nếu Thái hậu cho {xung} vào thẳng Đức Thọ cung, không qua Ngự dược phòng, kẻ tráo thuốc hết đường ra tay. Xin {goi} thưa với Thái hậu."},{"who":"me","text":"Đường thẳng đến Thái hậu là đường kín nhất. {Xung} sẽ chọn lúc nào thưa cho khéo."}]}},
{"id":"nr:ty_tra_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ ghi đơn dày cộp đặt trên bàn thư lại, một trang có nét bút mới hơn các trang khác, người thái y chỉ vào đó, ngón tay hơi run."},{"who":"A","text":"{Goi}, người của {B} đem sổ ghi đơn của Ngự dược phòng lên viện phán đòi xét {xung}, mà sổ ấy đã bị sửa một nét."},{"who":"me","text":"Sửa một nét mà đổi cả nghĩa, thật là thủ đoạn. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"Xin {goi} mượn sổ ấy một đêm, để {xung} đối lại nét bút cũ."},{"who":"me","text":"Một nét bút bị sửa mà {goi} phải chịu xét, {xung} nghe mà giận thay. Mượn sổ một đêm thì cần một cớ cho thật vẹn."}]}},
{"id":"nr:ty_tra_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản xét dâng lên viện phán còn nằm trong tập sớ, người thái y đứng chờ ngoài điện, nhìn về phía án thư xa xa."},{"who":"A","text":"{Goi}, viện phán sẽ dâng Hoàng thượng bản xét {xung}. Hoàng thượng đọc sớ thì hay hỏi một người thân cận."},{"who":"me","text":"Nếu thánh thượng hỏi {goi} thì lời của {goi} sẽ có sức nặng. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} được hỏi, xin nói rằng thang thuốc của {xung} đã giữ người bệnh qua đêm ấy."},{"who":"me","text":"Hoàng thượng mà hỏi đến, phải đáp sao cho thật mà không giống đã soạn sẵn. Ý ấy {xung} còn đang nghĩ lại từng chữ."}]}},
{"id":"nr:ty_tra_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói bã thuốc nhỏ được bọc trong lớp giấy dầu, người thái y ôm sát vào lòng như ôm một báu vật."},{"who":"A","text":"{Goi}, bã thuốc của thang bị tráo, {xung} còn giữ được một gói. Người của {B} đã lục phòng {xung} hai lần."},{"who":"me","text":"Bị lục hai lần mà vẫn giữ được, {goi} khéo thật. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} cất gói bã ấy ở nơi không ai dám lục."},{"who":"me","text":"Một gói bã nhỏ mà là cả chứng cứ. {Xung} sẽ chọn nơi nào kín đáo nhất."}]}},
{"id":"nr:ty_tra_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gói bã thuốc đặt trên bàn, người thái y nhìn nó như nhìn một lời chưa nói ra, sắc mặt đầy lo âu."},{"who":"A","text":"{Goi}, gói bã thuốc phải có người nghiệm trước buổi xét, mà Thái y viện không ai chịu nghiệm thuốc của đồng liêu."},{"who":"me","text":"Không ai dám nghiệm thì chứng cứ ấy cũng như vô dụng. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} mời một thái y ngoài viện vào cung {goi}, nghiệm kín giúp {xung}."},{"who":"me","text":"Nghiệm bã thuốc trước buổi xét thì còn đường nói. Một thái y ngoài viện, {goi} đã có người nào trong lòng chưa?"}]}},
{"id":"nr:ty_tra_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Khôn Ninh cung hôm nay đông người, người thái y đứng lẫn trong hàng quan chờ, tay nắm chặt tay áo."},{"who":"A","text":"{Goi}, Hoàng hậu sắp xét vụ tráo thuốc. {Xung} chỉ là một thái y, lời của {xung} nhẹ."},{"who":"me","text":"Lời nhẹ thì dễ bị gạt đi. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} có mặt và hỏi một câu về bã thuốc hôm ấy, Hoàng hậu sẽ phải cho người nghiệm."},{"who":"me","text":"Lời nhẹ mà câu hỏi đúng chỗ thì hóa nặng. {Xung} cần một câu để Hoàng hậu thấy là chính người muốn hỏi, không phải bị ép."}]}},
{"id":"nr:ty_tra_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi xét sắp đến, phòng thái y im lìm như ngày trước bão, người thái y ngồi bất động, nhìn ra cửa sổ xa xăm."},{"who":"A","text":"{Goi}, ở buổi xét sắp tới, người của {B} sẽ đứng ra làm chứng chống {xung}. Lời khai ấy đã có người dạy trước."},{"who":"me","text":"Lời khai đã được dạy thì dù là thật cũng thành giả. Trong đám người của {B}, {goi} ngờ ai đã đứng ra dạy lời?"},{"who":"A","text":"Xin {goi} dò giúp kẻ làm chứng đã gặp ai."},{"who":"me","text":"Biết kẻ làm chứng gặp ai thì biết kẻ dạy lời. {Xung} sẽ chọn lối dò sao cho không bị phát hiện."}]}},
{"id":"nr:vg_dat_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió đồng phương xa mang mùi lúa khô, người ấy mặc áo đi đường, tay cầm lá thư còn chưa niêm, mắt đầy lo toan."},{"who":"A","text":"{Goi}, đất phong của {xung} mất mùa, dân đói mà quan địa phương vẫn tâu được mùa."},{"who":"me","text":"Dân đói mà quan còn tâu được mùa, thật là điều đáng giận. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"{Xung} cần một lá thư đến Hộ bộ không qua tay viên quan ấy. Xin {goi} cho lá thư đi theo đường thư nhà của {goi}."},{"who":"me","text":"Dân đói mà quan vẫn tâu được mùa, nghe mà nghẹn. Lá thư đi Hộ bộ, nhờ ai mang thì mới không lọt vào tay viên quan ấy?"}]}},
{"id":"nr:vg_dat_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ nộp lúa của đất phong mở ra, hàng chữ đậm nét đỏ, người ấy ngồi bên án, ngón tay lướt qua từng dòng trong lo âu."},{"who":"A","text":"{Goi}, năm nay mất mùa, mà chiếu ban đất ghi rõ đất phong phải nộp lúa vào kho triều. {Xung} không xin miễn, chỉ xin hoãn."},{"who":"me","text":"Chỉ xin hoãn mà không xin miễn, {goi} thật biết giữ lễ. {Goi} nhờ {xung} gì?"},{"who":"A","text":"Xin {goi} khi Hoàng thượng hỏi chuyện mùa màng, nói rằng phương nam năm nay mưa dầm."},{"who":"me","text":"Xin hoãn mà không xin miễn, giữ lễ như thế thì đáng được nghe. {Xung} chỉ chờ một dịp Hoàng thượng nhắc đến mùa màng."}]}},
{"id":"nr:vg_dat_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thư của nơi đất phong vừa đến, mùi giấy ẩm còn vương, người ấy ngồi lặng bên án, mắt dõi về hướng cung nữ ở xa."},{"who":"A","text":"{Goi}, viên tri phủ ở đất phong có con gái làm cung nữ trong cung, và nghe nói {B} đã bỏ bạc nhờ nàng dò việc của {xung}."},{"who":"me","text":"Con gái quan địa phương lại ở trong cung, đường dây ấy thật khéo. {Goi} muốn biết điều gì?"},{"who":"A","text":"{Xung} muốn biết nàng đã kể những gì."},{"who":"me","text":"Nàng cung nữ ấy hẳn đã kể ra những chuyện nhỏ, mà chuyện nhỏ góp lại cũng thành lưới. Hỏi nàng thì phải làm sao cho nàng đừng sợ."}]}},
{"id":"nr:vg_dat_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Công văn của viên tri phủ đặt trên án, nét chữ ngạo nghễ, người ấy đọc đi đọc lại mà mày càng nhíu chặt."},{"who":"A","text":"{Goi}, viên tri phủ chống lệnh của {xung}, cậy có thư của người trong triều."},{"who":"me","text":"Cậy thư để chống lệnh thì thư ấy phải có sức nặng. {Goi} cần gì?"},{"who":"A","text":"{Xung} cần chép được lá thư ấy. Nếu nhà {goi} có người làm ở bộ Lại, xin hỏi giúp."},{"who":"me","text":"Bộ Lại thì {xung} chưa quen ai, nhưng nhà {xung} có lẽ có người. Lá thư ấy, {goi} cần chép nguyên văn hay chỉ cần biết ai ký?"}]}},
{"id":"nr:vg_dat_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấu chương gièm pha còn nằm trên án, mực đen chưa ráo, người ấy nhìn mà tay siết chặt tay vịn ghế."},{"who":"A","text":"{Goi}, có tấu chương nói {xung} tự ý thu thuế riêng. Đó là lúa cứu đói, có sổ ghi rõ."},{"who":"me","text":"Lúa cứu đói mà bị đổ là thu riêng, thật oan. {Goi} xin {xung} điều gì?"},{"who":"A","text":"{Xung} không thể tự vào cung tâu; xin {goi}, nếu Hoàng thượng nhắc đến, nói giúp rằng sổ lúa ấy vẫn còn, ai muốn xem cứ xem."},{"who":"me","text":"Sổ lúa còn nguyên, ai muốn xem cứ xem. Đến lúc Hoàng thượng nhắc, lời của {xung} thốt ra phải thật bình tĩnh."}]}},
{"id":"nr:vg_dat_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Viên ngự sử vừa rời phủ, hộp lễ còn đặt trên bàn, người ấy nhìn theo bóng xe xa dần mà trầm ngâm."},{"who":"A","text":"{Goi}, tấu chương gièm {xung} do một viên ngự sử dâng, mà viên ngự sử ấy vừa nhận lễ của {B}."},{"who":"me","text":"Nhận lễ rồi mới dâng tấu thì chẳng phải ngẫu nhiên. {Goi} có ngờ ai trong cung đã đưa tin ra cho {B} chưa?"},{"who":"A","text":"Xin {goi} dò giúp ai trong cung đã đưa tin cho {B}."},{"who":"me","text":"Ngăn không được lời tấu thì ít nhất cũng phải biết ai đã mở đường. {Xung} sẽ dò theo từng cửa cung."}]}},
{"id":"nr:vg_dat_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ thuế đất phong còn thiếu ba phần, người ấy nhìn con số đỏ mà thở dài thật khẽ, không nói thành lời."},{"who":"A","text":"{Goi}, thuế năm nay của đất phong thiếu ba phần. Đất ấy là đất tiên đế ban."},{"who":"me","text":"Đất tiên đế ban mà thiếu thuế thì tội càng nặng. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu Thái hậu mở lời xin hoãn thuế một năm, Hộ bộ sẽ không dám đòi gắt. Xin {goi} thưa giúp {xung}."},{"who":"me","text":"Thiếu thuế mà lại là đất tiên đế ban, Thái hậu nghe cũng nặng lòng. Kể mất mùa sao cho người thương dân, đừng thấy mình bị xin xỏ."}]}},
{"id":"nr:vg_dat_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Xấp gấm đất phong trải trên án, màu sắc rực rỡ dưới nắng, người ấy vuốt nhẹ lên mặt vải như muốn dâng tặng."},{"who":"A","text":"{Goi}, phần thuế thiếu có thể bù bằng gấm của đất phong, nếu Trung cung chịu nhận gấm thay lúa cho đợt may áo sắp tới."},{"who":"me","text":"Gấm thay lúa là cách hay, nhưng phải có lời của Trung cung. {Goi} nhờ {xung} gì?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu việc ấy giúp {xung}."},{"who":"me","text":"Gấm thay lúa là một lối thoát hiền hòa. Chưa rõ Hoàng hậu đang cần gấm cho việc may áo, hay đã đủ cả rồi."}]}},
{"id":"nr:vg_dat_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đường vào Đức Thọ cung lát đá xanh, người ấy xa kinh lâu năm, đứng nhìn mái cung như nhìn một nơi lạ."},{"who":"A","text":"{Goi}, Thái hậu triệu {xung} vào cung hỏi chuyện đất phong. {Xung} xa kinh lâu, không biết bây giờ Thái hậu ưa nghe điều gì, kiêng điều gì."},{"who":"me","text":"Xa kinh lâu thì quen thói cũ mà không biết thói mới. {Goi} muốn nhờ {xung} gì?"},{"who":"A","text":"{Goi} hay đến Đức Thọ cung, xin chỉ cho {xung} một hai điều."},{"who":"me","text":"Một hai điều về Thái hậu là đủ cho người xa kinh đỡ lạc. {Xung} đang nhớ xem lần gần nhất người cau mày là vì chuyện gì."}]}},
{"id":"nr:vg_dat_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tin buổi triệu kiến vừa truyền ra, người ấy thu xếp áo mũ, ánh mắt thoáng lo, biết sau buổi này còn một lần hỏi lại."},{"who":"A","text":"{Goi}, sau buổi Thái hậu hỏi chuyện {xung}, Hoàng thượng thế nào cũng hỏi lại."},{"who":"me","text":"Lời Thái hậu qua nhiều miệng thì dễ lệch đi. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi}, nếu Hoàng thượng hỏi, kể lại đúng lời Thái hậu, đừng để kẻ khác kể lệch đi."},{"who":"me","text":"Kể đúng từng chữ đã đành, giữ cho đúng cả giọng người mới là điều {xung} lo. Đêm nay phải nhớ lại từng câu cho kỹ."}]}},
{"id":"nr:vg_dat_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản biểu xin miễn thuế đã được viết lại nhiều lần, giấy mỏng nhàu, người ấy đặt nó xuống án với nét mặt kiên quyết."},{"who":"A","text":"{Goi}, biểu xin miễn thuế cho dân đất phong đã ba lần bị Nội các giữ lại. Lần này {xung} gửi thẳng vào cung."},{"who":"me","text":"Ba lần bị giữ lại thì chắc không phải chuyện nhỏ. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} để biểu ấy nằm trên án khi Hoàng thượng đến cung {goi}."},{"who":"me","text":"Một tờ biểu nằm trên án, thánh thượng bước vào là thấy. Chỉ cần nó trông như vô tình, đừng như được bày sẵn."}]}},
{"id":"nr:vg_dat_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ánh đèn dầu chiếu lên bản biểu, những dòng chữ nhắc đến dân đói, người ấy nhìn đoạn cuối mà lòng nặng như đá."},{"who":"A","text":"{Goi}, biểu miễn thuế mà có lời của Thái hậu thì Nội các không dám giữ, mà Thái hậu vốn thương dân đói."},{"who":"me","text":"Thái hậu thương dân thì một đoạn biểu cũng đủ chạm lòng. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} khi hầu Thái hậu, đọc cho người nghe một đoạn biểu của {xung}."},{"who":"me","text":"Lời biểu vì dân mà đến tai Thái hậu thì không ai cản được. {Xung} sẽ chọn đoạn nào cho thấm."}]}},
{"id":"nr:vg_bien_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió biên ải thổi mạnh, cờ quân phất liên hồi, người ấy đứng trên tường thành nhìn xuống đoàn xe trống rỗng."},{"who":"A","text":"{Goi}, quân lương ra biên đã chậm hai tháng. Lương đi qua kho Nội vụ phủ, mà người giữ kho mới vừa nhận lễ của {B}."},{"who":"me","text":"Chậm hai tháng mà không ai trả lời, thật đáng ngờ. {Goi} cần biết gì?"},{"who":"A","text":"{Xung} cần biết lương đang nằm ở kho nào."},{"who":"me","text":"Người giữ kho vừa nhận lễ, hỏi hắn thì uổng lời. {Xung} đang tìm xem ai trong Nội vụ phủ chịu mở sổ."}]}},
{"id":"nr:vg_bien_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nồi cháo loãng bốc hơi nhẹ giữa doanh trại, người ấy nhìn quân sĩ ngồi quanh mà siết chặt chuôi kiếm."},{"who":"A","text":"{Goi}, quân lương chậm, quân của {xung} ăn cháo loãng đã nửa tháng. Chỉ một chỉ dụ giục kho là lương lên đường ngay."},{"who":"me","text":"Cháo loãng mà vẫn giữ thành, quân ấy trung nghĩa thật. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} khi hầu Hoàng thượng, nhắc rằng mùa đông ngoài biên đến sớm."},{"who":"me","text":"Quân ăn cháo loãng nửa tháng mà vẫn giữ thành, lòng {xung} nặng trĩu. Một câu về mùa đông biên ải, nói sao cho nhẹ mà thấm?"}]}},
{"id":"nr:vg_bien_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Thư nhà từ kinh đến doanh trại, người ấy cầm trên tay mà chưa dám đọc hết, vì biết trong ấy có tin của mẹ phó tướng."},{"who":"A","text":"{Goi}, phó tướng của {xung} có mẹ già ở kinh, bệnh nặng mà không ai lo. Lòng tướng ở biên phần nhiều nằm ở quê nhà."},{"who":"me","text":"Tướng lo mẹ thì lòng đâu yên mà giữ thành. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} sai người đến thăm bà cụ một lần."},{"who":"me","text":"Bà cụ bệnh nặng, phó tướng nơi xa hẳn đứng ngồi không yên. Người đi thăm bà, {xung} muốn một người biết nói lời ấm."}]}},
{"id":"nr:vg_bien_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cổng doanh vừa khép sau lưng người đưa thư, người ấy đứng nhìn theo bóng ngựa xa dần, lòng đầy nghi ngại."},{"who":"A","text":"{Goi}, phó tướng của {xung} nhận thư riêng từ kinh, mà người đưa thư lại do {B} bỏ bạc thuê."},{"who":"me","text":"Thư riêng đến doanh mà do kẻ kia thuê thì chẳng lành. Trong thư riêng ấy, {goi} đoán {B} đã hứa điều gì với phó tướng?"},{"who":"A","text":"Xin {goi} dò giúp {B} đã hứa với phó tướng những gì."},{"who":"me","text":"Biết lời hứa của {B} thì biết lòng phó tướng đang nghiêng về đâu. {Xung} sẽ dò theo từng đường."}]}},
{"id":"nr:vg_bien_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp lễ của sứ giặc xếp thành hàng trong điện, vải gấm bọc ngoài đủ màu, người ấy đứng xa nhìn mà ánh mắt đầy cảnh giác."},{"who":"A","text":"{Goi}, sứ giặc vào kinh lần này mang lễ vật cho hậu cung. Nếu trong lễ có thư riêng gửi cho {B} hay cho ai khác, {xung} cần biết trước khi sứ giặc lên điện."},{"who":"me","text":"Thư riêng trong lễ vật thì là đường dây ngầm đáng sợ. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} để ý giúp một hộp có dấu lạ."},{"who":"me","text":"Dấu lạ trên hộp lễ chỉ kẻ để tâm mới thấy. {Xung} phải nhớ kỹ từng hộp được bày, đừng để ai nhận ra mình đang nhìn."}]}},
{"id":"nr:vg_bien_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sứ giặc quỳ trước điện Đức Thọ, tờ cầu hòa mở rộng, người ấy đứng ngoài, nhìn vào mà lòng như lửa đốt."},{"who":"A","text":"{Goi}, sứ giặc xin vào bái kiến Thái hậu, mang theo lời cầu hòa. Thái hậu mềm lòng thì triều đình sẽ lép vế."},{"who":"me","text":"Lời cầu hòa nghe thì dễ, mà hậu quả thì khó lường. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} ngồi hầu buổi ấy, nhắc khẽ Thái hậu rằng quân của {xung} vẫn đang giữ thành."},{"who":"me","text":"Lời cầu hòa mềm tai, nghe lâu dễ thành thật. Nhắc Thái hậu chuyện quân giữ thành, phải nhắc như người thương lính chứ không phải người cản."}]}},
{"id":"nr:vg_bien_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trận đầu sắp đến, trong vương phủ yên ắng, tiểu thái giám ngồi nơi bậc cửa, mắt không rời bóng người sắp ra trận."},{"who":"A","text":"{Goi}, {xung} có một tiểu thái giám theo hầu vương phủ từ nhỏ, không thể mang ra trận."},{"who":"me","text":"Theo hầu từ nhỏ thì tình nghĩa đã sâu. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {xung} không về, xin {goi} cho nó một chỗ làm trong cung {goi}."},{"who":"me","text":"Đứa nhỏ theo hầu từ bé, {goi} lo cho nó hơn lo cho mình. {Xung} muốn nhận, chỉ chưa rõ nên cho nó việc gì để khỏi ai gièm."}]}},
{"id":"nr:vg_bien_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vết thương ở tay quấn vội bằng vải, người ấy đứng dưới ánh đuốc doanh trại, nụ cười gượng gạo che giấu cơn đau."},{"who":"A","text":"{Goi}, trận đầu {xung} bị thương ở tay, giấu không cho ai biết, sợ Hoàng thượng gọi về."},{"who":"me","text":"Giấu vết thương thì lâu ngày thành họa. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} gửi giúp một hộp thuốc theo đường thư nhà, đừng ghi tên người dùng."},{"who":"me","text":"Giấu vết thương vì sợ bị gọi về, {goi} cứng đầu mà cũng đáng thương. Hộp thuốc gửi đi không tên, cần người đưa thật kín miệng."}]}},
{"id":"nr:vg_bien_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nửa chiếc hổ phù đặt trong hộp gỗ, ánh đồng lạnh lẽo, người ấy nhìn nó lâu rồi mới đẩy hộp ra phía trước."},{"who":"A","text":"{Goi}, trong kinh đồn {xung} giữ binh quyền không chịu nộp. {Xung} xin dâng lại một nửa hổ phù."},{"who":"me","text":"Dâng hổ phù là dâng cả quyền lực. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} nói với Hoàng thượng rằng lời xin ấy là thật lòng, trước khi Nội các kịp bàn."},{"who":"me","text":"Dâng một nửa hổ phù mà bị đồn giữ quyền, {goi} thật chịu thiệt. Lời thật nói trễ một ngày sẽ thành lời chữa cháy."}]}},
{"id":"nr:vg_bien_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bức thư mang ấn giả được trải ra dưới ánh đèn, dấu son đỏ in lệch một nét nhỏ, người ấy nhìn mà gằn giọng."},{"who":"A","text":"{Goi}, lời đồn {xung} mưu phản đi ra từ một bức thư mang ấn giả. Người khắc ấn ấy từng nhận bạc của {B}."},{"who":"me","text":"Ấn giả mà đủ gieo cả tội phản, thật đáng sợ. {Goi} muốn biết điều gì?"},{"who":"A","text":"Xin {goi} dò giúp hắn đang ở đâu."},{"who":"me","text":"Thợ khắc ấn đã nhận bạc thì hẳn không còn ở chỗ cũ. Muốn tìm hắn phải lần theo người cuối cùng từng thấy hắn."}]}},
{"id":"nr:vg_bien_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiệc mừng chưa mở, bàn tiệc đã bày thành hàng dài, người ấy đứng nhìn chỗ ngồi thượng tọa, ánh mắt trầm tư."},{"who":"A","text":"{Goi}, {xung} về kinh, Hoàng hậu sẽ mở tiệc mừng. Ai được ngồi gần ai trong tiệc, cả kinh thành sẽ đọc ra ý Hoàng thượng."},{"who":"me","text":"Một chỗ ngồi mà nói lên cả thánh ý. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} xin cho {xung} ngồi gần thượng tọa, cả kinh thành sẽ biết {xung} không bị ngờ."},{"who":"me","text":"Một chỗ ngồi trong tiệc mà cả kinh thành đọc ra thánh ý. Mở lời với Hoàng hậu, cần giọng nào để không giống đang cầu thể diện?"}]}},
{"id":"nr:vg_bien_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chén rượu đầu đặt trên khay ngọc ở Đức Thọ cung, hơi rượu thoảng thơm, người ấy nhìn chén ấy với ánh mắt trang nghiêm."},{"who":"A","text":"{Goi}, lễ mừng ở Đức Thọ cung có một chỗ dâng rượu; ai được dâng thì cả triều hiểu người ấy được tin."},{"who":"me","text":"Một chén rượu mà nói lên cả lòng tin. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} xin Thái hậu cho {xung} được dâng chén đầu."},{"who":"me","text":"Chén rượu đầu nặng như một lời bảo chứng. Xin Thái hậu đúng lúc người đang vui là hơn cả, mà chưa rõ lúc ấy là khi nào."}]}},
{"id":"nr:ns_tho_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản phổ cũ mở trên giá nhạc, nét mực xưa nhạt dần, người nhạc sư ngồi trước đàn, ngón tay khẽ chạm dây mà không gảy."},{"who":"A","text":"{Goi}, bản phổ cũ của khúc mừng thọ do tiên đế soạn, có một bản cất trong Đức Thọ cung. {Xung} không dám xin mượn."},{"who":"me","text":"Phổ của tiên đế thì quý, giữ trong cung Thái hậu càng không dễ mượn. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} khi hầu Thái hậu, xin cho chép lại một trang cuối."},{"who":"me","text":"Một trang cuối mà thiếu thì cả khúc mừng thọ đứt giữa chừng. {Xung} lo Thái hậu nghe lời xin ấy thành chuyện đòi của tiên đế để lại."}]}},
{"id":"nr:ns_tho_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Kho phổ nhạc phường im lìm, kệ gỗ xếp đầy bản chép tay, người nhạc sư dừng lại trước chỗ trống nơi một trang đã bị xé."},{"who":"A","text":"{Goi}, trang cuối bản phổ cũ trong nhạc phường đã bị xé, mà hôm ấy người giữ chìa khóa kho phổ vừa nhận lễ của {B}."},{"who":"me","text":"Xé một trang mà mất cả khúc nhạc, thật ác ý. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} dò giúp {xung} trang ấy đã vào tay ai."},{"who":"me","text":"Trang phổ bị xé, người giữ chìa vừa nhận lễ, chuyện nghe đã rõ một nửa. Phần còn lại phải lần theo từng bàn tay."}]}},
{"id":"nr:ns_tho_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây tỳ bà nằm trên bàn, dây đàn đứt rũ xuống, người nhạc sư nhìn nó mà đau như nhìn một người bạn bị thương."},{"who":"A","text":"{Goi}, cây tỳ bà của {xung} bị cắt dây trong đêm. Thợ đàn giỏi nhất ở ngoài cung, mà nhạc phường không được gọi người ngoài vào."},{"who":"me","text":"Dây đàn mà bị cắt thì chẳng phải ngẫu nhiên. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} lấy cớ sửa đồ của cung {goi} mà gọi ông ấy vào."},{"who":"me","text":"Dây đàn đứt giữa đêm, nghe mà xót cho cây tỳ bà. Cớ sửa đồ của cung {xung} nghe hợp lẽ, chỉ không rõ ông thợ có chịu vào cung không."}]}},
{"id":"nr:ns_tho_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mép dây đàn đứt phẳng lì như bị cắt bằng kéo sắc, người nhạc sư đưa lên soi dưới ánh đèn mà thở nhẹ."},{"who":"A","text":"{Goi}, dây tỳ bà của {xung} bị cắt bằng thứ kéo của thợ may Thượng y cục, mà {B} có người quen ở đó."},{"who":"me","text":"Kéo của Thượng y cục thì chỉ có người trong đó mới mượn được. {Goi} muốn biết điều gì?"},{"who":"A","text":"Xin {goi} dò giúp đêm ấy ai đã mượn kéo."},{"who":"me","text":"Kéo của Thượng y cục lại ở trong tay người quen của {B}, trùng hợp đến lạ. Đêm ấy kéo vào tay ai, hẳn còn người nhớ."}]}},
{"id":"nr:ns_tho_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng tiêu vọng từ xa trong màn chiều, mỏng như sợi khói, người nhạc sư dừng bước lắng nghe, mắt nhìn về phía cửa nhạc phường."},{"who":"A","text":"{Goi}, người thổi tiêu giỏi nhất của nhạc phường bị phạt đuổi vì một lần lỡ nhịp trước mặt quản sự. Hắn chưa đi xa."},{"who":"me","text":"Một nhạc công giỏi bị đuổi vì lỡ nhịp một lần, thật tiếc. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu {goi} cho hắn tạm hầu nhạc trong cung {goi} ít hôm, {xung} còn kịp gọi hắn về."},{"who":"me","text":"Tiếng tiêu hay mà phải đi chỉ vì một lần lỡ nhịp, thật phí. Hắn chưa đi xa thì còn kịp, chỉ cần một chỗ cho hắn đặt chân."}]}},
{"id":"nr:ns_tho_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách nhạc công tiệc thọ ghi tên đầy đủ, chỉ thiếu một người, người nhạc sư đứng nhìn chỗ trống mà lòng nặng nề."},{"who":"A","text":"{Goi}, quản sự nhạc phường đuổi người thổi tiêu mà không trình Trung cung, trong khi nhạc công tiệc thọ do Hoàng hậu định."},{"who":"me","text":"Tự ý đuổi người của Hoàng hậu định thì phạm lệ. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu, giữ hắn lại cho {xung} đến hết tiệc."},{"who":"me","text":"Nhạc công do Hoàng hậu định, quản sự đuổi mà không thưa là phạm lệ rõ ràng. Lời thưa phải đúng phép, kẻo lại thành đi tố người."}]}},
{"id":"nr:ns_tho_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Điện tập nhạc yên tĩnh, người nhạc sư đứng ở góc xa, nhìn về phía chỗ Thái hậu sẽ ngồi mà không thấy được gương mặt người."},{"who":"A","text":"{Goi}, Thái hậu sẽ nghe tập một lần trước tiệc thọ. {Xung} đứng xa, không thấy được sắc mặt người."},{"who":"me","text":"Không thấy sắc mặt thì khó biết khúc nhạc có vừa lòng người hay không. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} ngồi hầu bên Thái hậu buổi ấy, nếu người nhíu mày thì ra hiệu cho {xung}."},{"who":"me","text":"Một cái nhíu mày chỉ thoáng qua, nhìn không tinh là lỡ. Dấu hiệu nào {goi} nhìn ra ngay mà Thái hậu chẳng hay?"}]}},
{"id":"nr:ns_tho_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi tập sắp bắt đầu, nhạc công đã vào chỗ, người nhạc sư đứng giữa sân, nhìn về phía ngự lộ chờ bóng xe thánh giá."},{"who":"A","text":"{Goi}, Hoàng thượng có thể ghé buổi tập. Nếu người khen một câu trước mặt Thái hậu, buổi tập sẽ êm."},{"who":"me","text":"Lời khen của thánh thượng có sức nặng hơn nhiều lời khác. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} mời Hoàng thượng ghé qua, nói rằng khúc của {xung} soạn theo ý tiên đế."},{"who":"me","text":"Hoàng thượng khen một câu là buổi tập êm cả. Nhắc ý tiên đế cho đúng, mời sao để người muốn ghé chứ không thấy bị gọi?"}]}},
{"id":"nr:ns_tho_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm khuya vọng lại tiếng đàn từ vài cung xa, người nhạc sư đứng bên cửa sổ, tai căng ra nghe từng nốt như tìm kiếm điều gì."},{"who":"A","text":"{Goi}, có kẻ đã chép trộm khúc mừng thọ, định dâng trước {xung}, mà bạc mua chuộc là của {B}. Bản chép ấy đang giấu ở một cung trong hậu cung."},{"who":"me","text":"Chép trộm khúc nhạc mà dâng trước thì mất cả công soạn. {Goi} muốn biết điều gì?"},{"who":"A","text":"Xin {goi} dò giúp là cung nào."},{"who":"me","text":"Bản chép trộm nằm ở một cung nào đó, hậu cung rộng thế, tìm từ đâu mới không đánh động?"}]}},
{"id":"nr:ns_tho_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hộp lễ vật tiệc thọ xếp đầy một gian, mỗi hộp buộc một dải lụa, người nhạc sư đứng cạnh nữ quan xếp lễ vật mà chờ."},{"who":"A","text":"{Goi}, bản chép trộm muốn dâng trước phải qua tay nữ quan xếp lễ vật của Trung cung."},{"who":"me","text":"Qua tay nữ quan thì còn một cửa để chặn. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Nếu Hoàng hậu ra lệnh mọi khúc dâng thọ phải ghi tên người soạn, bản chép kia không dám trình. Xin {goi} thưa giúp {xung} một lời trước tiệc."},{"who":"me","text":"Ghi tên người soạn lên mọi khúc thì kẻ chép trộm đành đứng ngoài. Lời thưa trước tiệc phải đến lúc nào để Hoàng hậu thấy đó là ý hay của chính người?"}]}},
{"id":"nr:ns_tho_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách các khúc nhạc tiệc thọ trải trên án, khúc của người ấy nằm ở cuối, người nhạc sư nhìn dòng ấy mà chau mày."},{"who":"A","text":"{Goi}, thứ tự các khúc trong tiệc thọ do Trung cung định. Khúc của {xung} đang xếp cuối, lúc Thái hậu đã mỏi."},{"who":"me","text":"Khúc xếp cuối thì khó vào lòng người đã mỏi. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} nói với Hoàng hậu một câu, cho khúc ấy lên trước."},{"who":"me","text":"Khúc xếp cuối mà Thái hậu đã mỏi thì uổng công soạn. Muốn Hoàng hậu đổi thứ tự, phải cho người thấy cái lợi của cả tiệc, không phải của riêng {goi}."}]}},
{"id":"nr:ns_tho_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Người hát chính đứng bên cửa, tay đưa lên cổ, giọng khàn đặc không thành tiếng, người nhạc sư nhìn mà lòng như lửa đốt."},{"who":"A","text":"{Goi}, tiệc thọ sắp đến mà người hát chính của {xung} bỗng khản đặc giọng, Thái y viện bảo phải nghỉ lâu."},{"who":"me","text":"Tiệc sắp đến mà mất giọng chính thì đáng lo. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} mời một thái y quen cho nàng một thang thuốc thật sớm."},{"who":"me","text":"Người hát chính khản giọng giữa lúc này, thật xót. Một vị thái y quen thì {xung} chưa có sẵn, {goi} có nghĩ đến ai không?"}]}},
{"id":"nr:st_uoc_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Quán dịch dột nát, mưa nhỏ giọt xuống chậu đồng đặt giữa phòng, vị sứ giả ngồi im, nhìn nước rơi mà nghĩ ngợi."},{"who":"A","text":"{Goi}, Lễ bộ xếp sứ đoàn của {xung} ở một quán dịch dột nát, như muốn nói hai nước không ngang hàng."},{"who":"me","text":"Xếp chỗ ở như thế là cố ý hạ thấp một sứ đoàn. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} gửi một lời ra ngoài, để Lễ bộ biết trong cung có người hỏi đến sứ đoàn."},{"who":"me","text":"Quán dột mà sứ đoàn vẫn phải ở, nghe như bị tát nhẹ. Gửi lời ra ngoài phải khéo để Lễ bộ thấy mình bị nhắc, chứ không bị chê."}]}},
{"id":"nr:st_uoc_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua cửa quán dịch, tấm chăn mỏng chẳng đủ ấm, vị sứ giả khoác áo ngoài, hơi thở thành khói trắng."},{"who":"A","text":"{Goi}, quán dịch thiếu cả chăn ấm, mà đồ dùng của sứ đoàn do Nội vụ phủ cấp theo lệnh Trung cung."},{"who":"me","text":"Thiếu cả chăn ấm thì thật chẳng phải lễ đãi khách. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu, cấp cho sứ đoàn của {xung} đúng lệ khách quý."},{"who":"me","text":"Thiếu chăn ấm giữa tiết lạnh, khách quý nào lại chịu như thế. Thưa với Hoàng hậu, {xung} muốn nói như một việc giữ thể diện, không phải than phiền."}]}},
{"id":"nr:st_uoc_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Buổi bàn điều khoản đầu sắp đến, bản điều khoản đặt trên án, vị sứ giả nhìn nó nhiều lần mà chưa dám viết thêm chữ nào."},{"who":"A","text":"{Goi}, trước buổi bàn điều khoản đầu, {xung} cần biết Hoàng thượng định nhượng đến đâu. Chỉ một chữ thôi: được hay không."},{"who":"me","text":"Biết ý thánh thượng trước thì mới có đường bàn. {Goi} xin {xung} điều gì?"},{"who":"A","text":"{Goi} gần thánh giá, xin để ý giúp một câu."},{"who":"me","text":"Chỉ một chữ được hay không mà nặng cả buổi bàn. Gần thánh giá, {xung} phải để ý một cái gật, một cái nhíu hơn là một câu nói."}]}},
{"id":"nr:st_uoc_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trước buổi bàn, đèn trong phòng Lễ bộ sáng muộn, vị sứ giả đứng ngoài hiên, nhìn bóng người qua lại trên cửa giấy."},{"who":"A","text":"{Goi}, đêm trước buổi bàn, người của {B} đã gặp riêng viên quan Lễ bộ. {Xung} cần biết bên ấy đã nói gì khiến Lễ bộ đổi giọng về điều khoản đầu."},{"who":"me","text":"Đổi giọng chỉ sau một đêm thì chắc đã có lời hứa. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} dò giúp buổi gặp đêm ấy."},{"who":"me","text":"Lễ bộ đổi giọng chỉ sau một đêm, nghe đã có mùi lời hứa. Buổi gặp riêng ấy ai ngồi gần nhất mà nghe được, {xung} cần đoán cho đúng."}]}},
{"id":"nr:st_uoc_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm gấm dệt kiểu bên ấy trải trên án, hoa văn tinh xảo lấp lánh dưới ánh đèn, vị sứ giả vuốt nhẹ mặt vải với vẻ trân trọng."},{"who":"A","text":"{Goi}, quà sứ đoàn dâng Thái hậu là một tấm gấm dệt kiểu bên ấy. Người trong cung bảo Thái hậu không ưa đồ lạ."},{"who":"me","text":"Đồ lạ mà dâng nhầm thì mất cả thể diện. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} khi dâng quà, nói giúp {xung} ý nghĩa của hoa văn."},{"who":"me","text":"Một tấm gấm dệt kiểu lạ mà Thái hậu lại không ưa đồ lạ. Hoa văn nào trên đó kể được chuyện thân quen với người, {xung} cần nhìn lại."}]}},
{"id":"nr:st_uoc_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nữ quan Trung cung đứng cạnh tấm gấm, mắt dò xét từng đường chỉ, vị sứ giả đứng chờ, hơi thở nén lại."},{"who":"A","text":"{Goi}, lễ vật dâng Thái hậu phải qua Trung cung xem trước. Nếu Hoàng hậu gật đầu, tấm gấm sẽ không bị trả."},{"who":"me","text":"Qua tay Trung cung xem trước thì phải khéo nói ý. {Goi} xin {xung} điều gì?"},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu rằng gấm của {xung} dệt hình hạc, là ý chúc thọ."},{"who":"me","text":"Hình hạc là chúc thọ, nói ra ai nghe cũng thuận tai. Chỉ còn đợi Hoàng hậu xem tấm gấm, mà vẻ mặt người ra sao thì chưa ai biết."}]}},
{"id":"nr:st_uoc_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm trong quán dịch, ngọn đèn chong gần tàn; vị sứ giả đứng khuất sau bình phong, tay nắm một lá thư gấp nhỏ."},{"who":"A","text":"Ngày đêm có thị vệ đứng quanh quán dịch, {xung} không sao gửi nổi một chữ về nước. Lá thư này không thể qua tay họ."},{"who":"me","text":"Thư gì mà phải tránh cả người giữ cửa? Chữ của sứ thần vốn chẳng có điều gì phải giấu."},{"who":"A","text":"Chỉ là lời báo bình an và vài việc riêng, nhưng qua tay họ lại thành việc nước. Xin {goi} cho thư đi cùng đồ ban thưởng của cung {goi}."},{"who":"me","text":"Đồ ban thưởng có niêm phong, kẻ canh không dám khám. {Xung} hiểu rồi, chỉ còn nghĩ xem nên mượn đường nào."}]}},
{"id":"nr:st_uoc_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió thổi lạnh qua hành lang quán dịch; vị sứ giả đếm từng bước chân của đội thị vệ đổi ca dưới mái hiên."},{"who":"A","text":"Đêm nào thị vệ quanh quán dịch cũng đổi người, chỉ riêng một kẻ là không đổi. Hắn là người của {B}."},{"who":"me","text":"Một người đứng suốt đêm trước cửa nhà khách. Ngươi nghĩ hắn canh sứ đoàn, hay canh điều gì khác?"},{"who":"A","text":"{Xung} nghĩ hắn nghe ngóng. Sứ đoàn nói gì trong phòng, hôm sau {B} đã biết trước, mà {xung} chưa tìm ra kẽ hở."},{"who":"me","text":"Vậy điều đáng biết là hắn mang tin ấy vào cung rồi trao cho ai."},{"who":"A","text":"Chính thế. Xin {goi} dò giúp, vì chỉ người trong cung mới lần ra được đường tin đi."}]}},
{"id":"nr:st_uoc_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong gian khách sảnh của quán dịch, một cây đàn lạ nước ngoài dựng cạnh cửa sổ, dây đàn còn quấn khăn lụa."},{"who":"A","text":"Buổi hội đàm đang căng như dây đàn. Giá như trước giờ bàn việc, Hoàng thượng được nghe một khúc nhạc của bản quốc ở hậu cung."},{"who":"me","text":"Một khúc nhạc mà làm mềm được lời bàn của hai nước ư?"},{"who":"A","text":"Người nghe nhạc quê người, lòng sẽ chậm lại một nhịp, lời nặng cũng thành lời nhẹ. {Xung} chỉ xin dâng bản nhạc, không xin gì khác."},{"who":"me","text":"Nhạc có hồn thì không cần lời giải thích. Chỉ không biết nên để ai gảy khúc ấy trước mặt Hoàng thượng."}]}},
{"id":"nr:st_uoc_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một tấm thảm hoa lạ của bản quốc được trải ra trên bàn, vị sứ giả cẩn thận vuốt phẳng từng nếp gấp."},{"who":"A","text":"Năm xưa khi tiên đế còn tại vị, Thái hậu đã từng đích thân tiếp sứ bản quốc. {Xung} còn nhớ ngày ấy người ban cho cả đoàn một chén rượu quý."},{"who":"me","text":"Chuyện đã nhiều năm, không ngờ {goi} vẫn nhớ rõ chén rượu ấy."},{"who":"A","text":"Người nước {xung} giữ ơn lâu lắm. Một lời của Thái hậu về mối giao hảo cũ sẽ làm Hoàng thượng nhớ lại những ngày hai nước còn thân."},{"who":"me","text":"Nhắc chuyện cũ trước mặt Thái hậu cũng cần khéo, kẻo người tưởng {xung} thay sứ thần cầu xin điều gì."},{"who":"A","text":"Xin {goi} cứ gợi như chuyện nhà, đừng nói đó là lời nhờ."}]}},
{"id":"nr:st_uoc_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư của quán dịch, tờ quốc ước đã đề đủ chữ, chỉ còn chỗ trống dành cho dấu ấn chưa đóng."},{"who":"A","text":"Việc đóng ấn bị hoãn, vì Khâm thiên giám bảo ngày này chưa tốt. Ngày tốt kế tiếp còn xa mà sứ đoàn không thể ở lâu."},{"who":"me","text":"Chờ một ngày tốt thì đành chờ. Nhưng điều khiến {goi} lo, là những ngày chờ ấy hay lòng người đổi thay?"},{"who":"A","text":"Cả hai. Nghe nói trong kinh đã có kẻ bàn ra tán vào, mà nước {xung} không có người để đỡ lời."},{"who":"me","text":"Vậy việc cần hỏi là Khâm thiên giám có thể chọn ngày nào sớm hơn không."},{"who":"A","text":"Xin {goi} hỏi giúp. Chỉ cần một ngày sớm hơn, sứ đoàn cũng đã ghi nhớ ơn này."}]}},
{"id":"nr:st_uoc_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiếng chuông canh vang từ xa; vị sứ giả đứng bên cửa sổ quán dịch, nhìn ra những mái ngói phủ sương."},{"who":"A","text":"Khâm thiên giám chỉ dâng ngày, người định đoạt vẫn là Hoàng thượng. Nếu Hoàng thượng muốn xong sớm, tự khắc ngày tốt sẽ có."},{"who":"me","text":"{Goi} muốn {xung} nói với Hoàng thượng điều gì, và nói bằng cách nào cho khỏi như đang cầu xin?"},{"who":"A","text":"Rằng sứ đoàn đã ở lâu, mà xong sớm là phúc cho hai nước. Đó không phải lời xin, đó là lẽ phải."},{"who":"me","text":"Lời ấy nhẹ mà có sức. {Xung} chỉ còn lo chọn lúc nào Hoàng thượng thuận lòng nghe."}]}},
{"id":"nr:hs_hoa_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tại họa viện, sáng sớm ánh nắng rọi qua song cửa, vị họa sư đang pha màu mà tay còn run."},{"who":"A","text":"Bức chân dung đầu tiên sẽ được Hoàng thượng xem trước. Bức đầu được khen thì cả bộ tranh cũng được khen theo."},{"who":"me","text":"Nghe {goi} nói, ngồi đầu như đứng ở bậc cửa. Bức ấy sai một nét, mọi bức sau đều lỡ theo."},{"who":"A","text":"Vì thế {xung} mới xin được vẽ {goi} đầu tiên, và sẽ dốc hết sức. Chỉ cần Hoàng hậu gật đầu cho {goi} ngồi trước."},{"who":"me","text":"{Goi} đã nghĩ kỹ vậy, {xung} không nỡ chối. Còn phải cân xem nên thưa với Hoàng hậu thế nào."}]}},
{"id":"nr:hs_hoa_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi chu sa hãy còn nồng trong họa viện; hàng ghế ngồi vẽ đã được ai đó xếp lại từ trước khi trời sáng."},{"who":"A","text":"Họa sư vẽ cùng {xung} hôm nào cũng đến sớm, xếp các cung ngồi theo ý riêng. Người đứng sau hắn là {B}."},{"who":"me","text":"Một kẻ vẽ mà lại xếp chỗ ngồi? Việc ấy không thuộc phận sự của hắn."},{"who":"A","text":"Chính vì thế mới đáng ngờ. {Xung} cần biết hắn nhận lời của cung nào, để biết bức tranh của mình được vẽ trong tay ai."},{"who":"me","text":"Phải rồi. Màu vẽ còn có thể sửa, chỗ ngồi đã xếp thì khó lật ngược. {Xung} sẽ dò trước đã."}]}},
{"id":"nr:hs_hoa_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn của họa sư có một hộp bạc nhỏ đóng kín; chiếc khóa đồng còn khắc một dấu triện lạ."},{"who":"A","text":"Có người gửi cho {xung} hai thỏi bạc, kèm lời dặn vẽ một vị quý nhân đẹp hơn người thật. {Xung} nghe hộp ấy đã đi qua tay người của {B}."},{"who":"me","text":"Bạc mà gửi kèm lời dặn, thì chẳng còn là quà. Dấu trên hộp nói gì?"},{"who":"A","text":"Là dấu của một cung trong hậu cung, mà {xung} không dám đoán bừa. Sai một chữ là mang tội vu cho cả cung ấy."},{"who":"me","text":"Phải chỉ cho đúng cung nào trước, rồi mới tính chuyện trả lại hay giữ lại."},{"who":"A","text":"Xin {goi} nhìn dấu ấy giúp. Người trong cung nhìn một cái là nhận ra."}]}},
{"id":"nr:hs_hoa_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai thỏi bạc nằm trên khăn lụa trắng giữa họa viện, họa sư chắp tay đứng cách xa ba bước như sợ chạm vào."},{"who":"A","text":"Phép họa viện, họa sư mà nhận quà của hậu cung là có tội. {Xung} nào dám giữ hai thỏi bạc này một đêm."},{"who":"me","text":"{Goi} muốn tự mang đến Trung cung ư? Nhưng người gửi có thể đổi lời trước khi {goi} đến."},{"who":"A","text":"Vì thế {xung} mới muốn đi ngay, và mong có người đứng bên làm chứng rằng bạc chưa hề bị động tới."},{"who":"me","text":"Lời một kẻ hầu dễ bị coi nhẹ, lời của người có phẩm cấp thì khác. {Xung} hiểu vì sao {goi} tìm đến."}]}},
{"id":"nr:hs_hoa_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Gió lùa qua cửa họa viện chưa khép, bức họa mới vẽ còn căng trên giá, mực chưa ráo."},{"who":"A","text":"Bức họa sắp trình đang để ở họa viện, mà cửa họa viện ai cũng vào được. {Xung} đêm nào cũng không ngủ yên."},{"who":"me","text":"Bức tranh đáng giá hơn {xung} tưởng, nếu khiến {goi} thức trắng như thế."},{"who":"A","text":"Nó là công sức cả tháng của {xung}. Nếu có kẻ bôi một nét, đổi một màu, thì không còn phân biệt được ai đúng ai sai."},{"who":"me","text":"Muốn giữ một thứ cho kín, phải đặt ở nơi có người canh suốt đêm. {Xung} đang nghĩ nơi ấy ở đâu."}]}},
{"id":"nr:hs_hoa_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hũ son ở góc họa viện còn nguyên nắp, nhưng quanh miệng hũ có vệt đỏ lem lên ngón tay ai đó."},{"who":"A","text":"Bức họa bị tráo, mà bức tráo lại vẽ bằng son của họa viện. Kẻ giữ chìa hũ son mấy hôm nay hay qua lại với {B}."},{"who":"me","text":"Son thì ai cũng dùng được, chỉ chìa là thuộc về một người. Hôm trước hũ ấy mở cho ai thì {goi} đã hỏi chưa?"},{"who":"A","text":"{Xung} không dám hỏi thẳng, vì kẻ ấy sẽ biết mình nghi. Mong {goi} dò giúp, để rõ ngày nào hũ son được mở."},{"who":"me","text":"Chuyện nhỏ thế này lại là đầu mối của chuyện lớn. {Xung} sẽ nghĩ cách dò cho kín."}]}},
{"id":"nr:hs_hoa_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngày xem tranh đã gần kề; trong họa viện, bức chân dung được lau khung thật kỹ, tựa như sắp ra mắt người."},{"who":"A","text":"Hôm Hoàng thượng xem tranh, người sẽ hỏi ý một hai phi tần. {Xung} không xin lời khen, chỉ xin {goi} nói thật."},{"who":"me","text":"Nói thật bức ấy vẽ có giống người không. {Goi} dám nhờ một lời không ngọt như thế?"},{"who":"A","text":"Lời khen quá đáng sẽ hại tranh, lời thật dù chê vẫn có ích cho {xung}. Nét nào chưa giống, {xung} còn kịp sửa."},{"who":"me","text":"Một họa sư biết sợ lời khen quá lời, nét vẽ chắc chắn cũng thật. {Xung} sẽ nhìn bức tranh kỹ trước ngày ấy."}]}},
{"id":"nr:hs_hoa_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tại họa viện, những cuộn tranh cũ của đời tiên đế được mở ra, giấy đã ngả màu mà nét mực vẫn sắc."},{"who":"A","text":"Thái hậu sẽ xem tranh cùng Hoàng thượng. Người ưa nét vẽ cũ, chê lối mới, mà tranh của {xung} thì không hẳn là lối cũ."},{"who":"me","text":"Vậy {goi} muốn Thái hậu biết rằng nét xưa vẫn còn trong tay {goi}."},{"who":"A","text":"Thật ra {xung} học vẽ từ bản của họa sư đời tiên đế. Chỉ cần Thái hậu biết trước điều ấy, người sẽ nhìn tranh bằng con mắt khác."},{"who":"me","text":"Một câu kể chuyện thầy dạy mà đổi được cách nhìn. Đáng để thử khi hầu Thái hậu."},{"who":"A","text":"Xin {goi} thưa giúp, vì {xung} không có phận để gặp Thái hậu trước buổi ấy."}]}},
{"id":"nr:hs_hoa_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mưa phùn ngoài hiên họa viện, tờ chiếu của Trung cung gọi hỏi đặt trên bàn, một góc đã ướt nhòe."},{"who":"A","text":"Có người vu cho {xung} vẽ phi tần quá kỹ, có ý bất kính. Trung cung đang xét, mà {xung} oan."},{"who":"me","text":"Vẽ cho thật là việc của họa sư. Nhưng ai ngồi bên cạnh lúc {goi} vẽ?"},{"who":"A","text":"Cung nữ đứng hầu suốt buổi, phép họa viện xưa nay vẫn thế. Chỉ cần Hoàng hậu nghe một câu ấy thì tội vu tự tan."},{"who":"me","text":"Một lời nói đúng phép thì không cần cao giọng. {Xung} sẽ tìm lúc thưa với Hoàng hậu."}]}},
{"id":"nr:hs_hoa_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên giá gỗ của họa sư, hộc đựng bản phác bỗng trống đi một ngăn, giấy dùng nháp rải lả tả dưới sàn."},{"who":"A","text":"Lời vu {xung} vẽ phi tần quá kỹ, do {B} đem kể với nữ quan. Hắn còn giữ một bản phác của {xung}, định đem làm chứng."},{"who":"me","text":"Một bản phác nháp, ngay cả {goi} cũng không nhớ là bức nào?"},{"who":"A","text":"Nét phác dở dang, ai lấy ra mà chẳng nói được điều mình muốn. {Xung} cần biết nó đang cất ở đâu."},{"who":"me","text":"Giữ được bản phác thì chặn được lời vu. {Xung} sẽ lần theo chỗ cất của hắn."}]}},
{"id":"nr:hs_hoa_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Đức Thọ cung, giá vẽ đã dựng sẵn bên cửa sổ, chiếc ghế mây đặt trống dành cho người chưa chịu ngồi."},{"who":"A","text":"Bức cuối là chân dung Thái hậu, mà người chưa chịu ngồi cho {xung}. Cả bộ tranh dang dở chỉ vì thiếu bức này."},{"who":"me","text":"Thái hậu là bậc đã quen được người ta nhìn, không quen bị người ta vẽ. Ngươi nghĩ vì sao người chần chừ?"},{"who":"A","text":"Chắc người ngại ngồi lâu. {Xung} chỉ xin nửa canh giờ, đủ phác dáng và nét mắt."},{"who":"me","text":"Nửa canh giờ thì không nhiều với bà. Lời khuyên cần đặt cho khéo."}]}},
{"id":"nr:hs_hoa_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc khay lụa phủ lên bức tranh Thái hậu mới phác một nửa; nét mực trên khuôn mặt vẫn còn bỏ trống."},{"who":"A","text":"Bức chân dung Thái hậu phải xong trước lễ cúng tiên đế. Nếu Hoàng thượng truyền một lời, Thái hậu sẽ chịu ngồi."},{"who":"me","text":"Một lời của Hoàng thượng dễ nặng hơn lời của họa sư. Ngươi muốn ta nói với người điều gì?"},{"who":"A","text":"Rằng đây là lòng hiếu, không phải việc riêng của {xung}. Bức tranh ấy dâng lên tiên đế, không để khoe tài."},{"who":"me","text":"Nói bằng chữ hiếu thì không ai dám từ chối. Chỉ cần chọn đúng lúc để thưa."},{"who":"A","text":"Đa tạ {goi}. {Xung} chỉ sợ trễ ngày lễ."}]}},
{"id":"nr:tq_an_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong lối đi hẹp sau Nội vụ phủ, vị Tổng quản cúi đầu giấu chiếc ấn ngọc vào tay áo, ánh mắt không dám ngước lên."},{"who":"A","text":"Phó tổng quản đang đi lấy lòng từng cung để chờ ngày thay {xung}, mà kẻ đỡ lưng cho hắn là {B}."},{"who":"me","text":"Hắn bước vào cung nào, tay mang món gì, đều là dấu vết. Các cung ấy hẳn đã nhận lễ?"},{"who":"A","text":"{Xung} chưa biết, vì hắn đi lại rất kín. Chỉ cần rõ hắn đã tới cung nào, mang theo quà gì, {xung} mới liệu được đường lui."},{"who":"me","text":"Quà nhẹ hay nặng cũng nói lên người nhận. Việc này không khó nếu có người để ý đúng chỗ."}]}},
{"id":"nr:tq_an_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn bản kê việc làm còn nằm trên án ngự thư phòng, những chỗ bị khoanh mực đỏ đập vào mắt người nhìn."},{"who":"A","text":"Phó tổng quản đã dâng Hoàng thượng một bản kê việc làm của {xung}, chỗ nào cũng có lỗi. {Xung} không dám cãi nửa lời."},{"who":"me","text":"Bản kê chép lỗi mà không chép công, cũng khó gọi là công bằng. Ai nhìn vào cũng thấy một phía."},{"who":"A","text":"Chỉ mong nếu Hoàng thượng hỏi, {goi} nói được rằng cung {goi} chưa từng thiếu một ngọn đèn."},{"who":"me","text":"Một ngọn đèn mà nhắc đúng chỗ, còn đáng hơn trăm lời biện bạch."}]}},
{"id":"nr:tq_an_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn sổ chi của Nội vụ phủ mở sẵn ở trang có một dòng bỏ trống, ngón tay vị Tổng quản chạm vào mà run."},{"who":"A","text":"Sổ chi của Nội vụ phủ hụt một khoản, mà khoản ấy là bạc Trung cung sai lấy để sửa Phật đường."},{"who":"me","text":"Bạc của Trung cung mà ghi không rõ ai nhận, đúng là rắc rối. {Goi} đã hỏi người giữ sổ chưa?"},{"who":"A","text":"Hỏi rồi, chỉ đáp rằng không dám nói. {Xung} cũng không dám hỏi Hoàng hậu, vì sợ chạm vào điều người không muốn nhắc."},{"who":"me","text":"Vậy phải có người khéo hỏi một câu: Hoàng hậu có nhớ đã sai lấy khoản ấy không."},{"who":"A","text":"Chỉ cần một câu thôi, {goi} ạ. Sổ sách sẽ tự rõ."}]}},
{"id":"nr:tq_an_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới ánh đèn Nội vụ phủ, một tờ biên nhận khoản chi đã bị xé mất mép, chữ ký chỉ còn nửa dòng."},{"who":"A","text":"Kẻ rút khoản bạc Phật đường mà ghi tên Trung cung là người của {B}. {Xung} biết rõ nét chữ ấy."},{"who":"me","text":"Mượn danh Trung cung để rút bạc thì to gan thật. Bạc ấy đã đi đâu, {goi} có đầu mối chưa?"},{"who":"A","text":"Chưa. Hắn rút xong là bặt tăm, sổ chỉ còn nửa dòng. {Xung} chỉ biết đây là việc có sắp đặt."},{"who":"me","text":"Sắp đặt thì phải có đường đi của bạc. Lần theo đường ấy sẽ ra người."}]}},
{"id":"nr:tq_an_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một phong thiếp mời son đỏ đặt trên bàn Tổng quản, góc thiếp bị bóp nhàu vì cầm quá lâu."},{"who":"A","text":"Có một vị quý nhân sai người hỏi {xung} đứng về đâu, lại giục trả lời sớm. {Xung} chỉ muốn giữ thế đứng giữa."},{"who":"me","text":"Đứng giữa hai bên mà không ai phật lòng thì khó lắm. {Goi} đã tìm được cớ nào chưa?"},{"who":"A","text":"Cớ thật thì có, chỉ thiếu người trao cho. Nếu {goi} giao cho {xung} một việc của cung {goi}, {xung} sẽ có lý do chính đáng để từ chối."},{"who":"me","text":"Bận việc của cung khác là cớ khó bắt bẻ, lại không phải nói một chữ nặng lời."}]}},
{"id":"nr:tq_an_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cánh cửa phòng Tổng quản khép hờ, ngoài hiên có bóng một cung nữ lạ đứng quá lâu mà không bước vào."},{"who":"A","text":"{B} đang ép {xung} đứng về phía nàng ta, giục trả lời gấp. Nàng ta chắc đã nắm điều gì của {xung}, nên mới dám gấp thế."},{"who":"me","text":"Người chưa có lợi thế thì không giục. Vậy trước tiên cần biết điều bị nắm là gì."},{"who":"A","text":"Phải. Biết nàng ta nắm điều gì, {xung} mới biết nên nhượng hay nên chống. Xin {goi} dò giúp."},{"who":"me","text":"Chuyện này người trong cung dò dễ hơn người ngoài. Lời bàn trong cung nàng ta sẽ cho thấy."}]}},
{"id":"nr:tq_an_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi khói còn vương trong kho đèn; những cây nến cháy dở nằm lẫn trong tro, bốc lên mùi sáp khét."},{"who":"A","text":"Kho đèn cháy, Hoàng thượng hỏi tội {xung}. Lửa bắt từ một cây nến không ai thắp."},{"who":"me","text":"Nến không ai thắp mà cháy, ắt là đã có tay đặt. {Goi} tin như vậy?"},{"who":"A","text":"Tin lắm. Nhưng {xung} không xin tha. Chỉ xin {goi} xin Hoàng thượng cho tra cây nến ấy trước khi xử."},{"who":"me","text":"Tra rồi mới xử, đó là lẽ công bằng. Xin cũng không phải xin ơn, chỉ xin điều đáng có."},{"who":"A","text":"Chính thế. {Xung} chỉ cần một cơ hội để cây nến tự nói."}]}},
{"id":"nr:tq_an_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên thùng gỗ cháy xém, vị Tổng quản nhặt từ tro lên một mảnh sáp còn nguyên dấu ấn nhỏ của Nội vụ phủ."},{"who":"A","text":"Cây nến không ai thắp là nến của cung {B}, có dấu Nội vụ phủ phát cho cung ấy."},{"who":"me","text":"Dấu ấn chứng cho nơi phát nến, không chứng cho ai châm lửa."},{"who":"A","text":"Vì thế {xung} cần người thấy tận mắt hộp nến còn lại. Nếu hộp ấy đủ số, cây nến cháy kia đâu phải của cung ấy."},{"who":"me","text":"Đếm nến nghe nhỏ nhặt, nhưng thật ra là đếm lẽ phải. Nến còn thiếu hay đủ sẽ nói thay lời."}]}},
{"id":"nr:tq_an_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước điện Đức Thọ, hương trầm lan ra theo gió; vị Tổng quản quỳ rất lâu, đầu gối tê dại mà vẫn không dám đổi thế."},{"who":"A","text":"Thái hậu vốn trọng người làm lâu năm. Chỉ cần người nhắc một câu {xung} là người cũ, không ai dám đẩy {xung} xuống."},{"who":"me","text":"Người làm lâu năm cũng là người biết nhiều chuyện. Thái hậu hiểu rõ điều ấy."},{"who":"A","text":"Vì thế {xung} chỉ xin một lời nhắc tên, không xin gì thêm. Xin {goi}, khi hầu Thái hậu, nhắc đến {xung}."},{"who":"me","text":"Tên một người bền bỉ, nhắc ra nhẹ như sương, nhưng đọng lại lâu."}]}},
{"id":"nr:tq_an_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sau tiệc đêm, một tờ chỉ của Thái hậu nằm gọn trong hộp gấm; vị Tổng quản ôm hộp mà không dám mở ra."},{"who":"A","text":"Thái hậu đã mở lời che chở, nhưng nơi xét việc kẻ hầu trong cung vẫn là Trung cung. {Xung} sợ lời che chở ấy chưa đủ."},{"who":"me","text":"Hai nơi cùng giữ phép trong cung mà không cùng một lời. {Goi} lo Trung cung xét gắt?"},{"who":"A","text":"Lo lắm. Xin {goi} thưa với Hoàng hậu rằng Thái hậu đã nhắc tên {xung}, để Trung cung biết ý Thái hậu."},{"who":"me","text":"Đem lời Thái hậu đến trước Hoàng hậu, phải nói sao cho vừa lòng cả hai bên."},{"who":"A","text":"{Goi} khéo hơn {xung} nhiều. {Xung} chỉ biết chờ."}]}},
{"id":"nr:tq_an_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối hành lang sau cung, một tiểu thái giám ôm khay trà đi ngang, dáng vẻ lanh lợi khiến vị Tổng quản đứng nhìn không rời."},{"who":"A","text":"{Xung} cần một đứa nối tay. Đứa {xung} chọn đang hầu ở cung khác, chủ của nó không chịu thả."},{"who":"me","text":"Nó là đứa nào mà {goi} cố giữ đến thế?"},{"who":"A","text":"Một đứa nhanh tay, kín miệng, nhìn việc biết trước ba bước. Hiếm lắm mới gặp. {Xung} muốn dạy nó việc trước khi tuổi mình đã quá."},{"who":"me","text":"Chọn người nối nghiệp cũng là cách giữ nghiệp. Chỉ khó mở lời với chủ cũ của nó."}]}},
{"id":"nr:tq_an_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chùm chìa khóa kho đèn treo trên vách, vị Tổng quản nhìn nó rất lâu rồi lại quay mặt đi."},{"who":"A","text":"Đứa {xung} chọn nối tay đã bị {B} mua chuộc, mà nó chưa dám nói. {Xung} nhận ra từ ánh mắt của nó mỗi khi bị gọi."},{"who":"me","text":"Vậy nó vẫn còn do dự. {Goi} đã giao gì cho nó chưa?"},{"who":"A","text":"Chưa. Chìa khóa kho vẫn trong tay {xung}. Nhưng {xung} cần biết nó đã nhận những gì trước khi giao."},{"who":"me","text":"Giao chìa là giao cả đời mình. Nên biết cho tường rồi hãy giao."}]}},
{"id":"nr:tq_que_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bên song cửa phòng trực, một lá thư quê mới nhận đã ố vàng, chữ viết run run của người mẹ già hiện lên mờ nhạt."},{"who":"A","text":"Mẹ già của {xung} ở quê đã yếu lắm. Thái giám xin về quê phải có chỉ của Hoàng thượng."},{"who":"me","text":"Bà ấy có nhắc đến {goi} trong thư không?"},{"who":"A","text":"Chỉ viết một câu: bà còn sống đến khi gặp con thì mãn nguyện. {Xung} đọc đi đọc lại câu ấy suốt đêm."},{"who":"me","text":"Một câu như thế còn nặng hơn mọi bản tấu. Phải chọn lúc Hoàng thượng vui lòng mà nhắc."}]}},
{"id":"nr:tq_que_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chồng đơn xin của đám thái giám xếp dày trên bàn nữ quan Trung cung; có một tờ để dưới cùng đã nhàu nát."},{"who":"A","text":"Đơn xin về quê của thái giám phải qua tay Trung cung trước khi lên ngự án. Đơn của {xung} nằm ở đó đã một tháng."},{"who":"me","text":"Một tháng chưa ai nhìn đến. Chắc không phải vì Hoàng hậu quên."},{"who":"A","text":"{Xung} không dám đoán. Chỉ mong có người thưa với Hoàng hậu, cho đơn ấy được trình lên."},{"who":"me","text":"Đơn nằm dưới đáy chồng, chỉ cần một bàn tay nhấc lên là đủ."},{"who":"A","text":"Mẹ {xung} chờ không được lâu nữa, {goi} ạ."}]}},
{"id":"nr:tq_que_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trạm dịch ngoài thành, gói bạc nhỏ buộc chặt bằng dây đỏ được vị Tổng quản ôm trước ngực như báu vật."},{"who":"A","text":"{Xung} dành dụm được ít bạc gửi về quê, mà hai lần đều mất ở trạm."},{"who":"me","text":"Hai lần đều mất, chắc không phải do rủi. {Goi} đã nhờ người đáng tin đi cùng chưa?"},{"who":"A","text":"Thái giám trong cung nào có ai để nhờ. Nếu gói bạc đi theo người nhà của {goi} lúc ra về thì mẹ {xung} mới nhận được."},{"who":"me","text":"Người nhà {xung} ra về, mang theo một gói bạc cũng chẳng nặng gì. Chỉ cần dặn cho kín."}]}},
{"id":"nr:tq_que_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai tờ biên nhận mất bạc bị vo tròn trong ngăn kéo, góc giấy còn in dấu trạm dịch ngoài thành."},{"who":"A","text":"Hai lần bạc của {xung} mất ở trạm, lần nào kẻ giữ trạm cũng là người do bên {B} gửi gắm."},{"who":"me","text":"Hai lần trùng một người thì chẳng còn là trùng hợp. Nhưng {B} làm thế để được gì?"},{"who":"A","text":"Có thể là để lấy bạc, cũng có thể là để {xung} biết ai nắm đường tin của mình. {Xung} cần biết hắn đem bạc đi đâu."},{"who":"me","text":"Bạc đi đâu thì tin cũng đi đó. Lần ra một đầu mối, cả sợi dây sẽ lộ."}]}},
{"id":"nr:tq_que_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới bóng cổng Thần Vũ, một nhóm người quê mặc áo vải, tay xách bọc nhỏ, ngồi chờ từ sáng chưa ai gọi."},{"who":"A","text":"Họ hàng ở quê kéo lên kinh đòi {xung} lo việc, đứng chờ ngay ở cửa Thần Vũ."},{"who":"me","text":"Họ đi bộ cả quãng đường xa chỉ để tìm {goi}?"},{"who":"A","text":"Từ tận quê lên. Nhưng thái giám dính chuyện nhà ở cửa cung là có tội. {Xung} không dám ra gặp, mà cũng không nỡ để họ đói rét."},{"who":"me","text":"Cần một chỗ trọ và một lời nhắn khuyên họ về, trước khi lính gác để ý."},{"who":"A","text":"Xin {goi} sai người ra lo giúp. Công ơn ấy {xung} không dám quên."}]}},
{"id":"nr:tq_que_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ báo của thị vệ cửa Thần Vũ nằm trên án nữ quan Trung cung, mép giấy còn thấm dấu tay mồ hôi."},{"who":"A","text":"Thị vệ cửa Thần Vũ đã báo chuyện họ hàng {xung} lên Trung cung. Nếu Hoàng hậu xét, {xung} mất chức."},{"who":"me","text":"Họ hàng đến tìm thì có tội gì, trừ khi {goi} ra đón."},{"who":"A","text":"{Xung} không hề ra. Họ chỉ đến hỏi thăm, rồi đã được khuyên về."},{"who":"me","text":"Vậy thì sự thật không có gì đáng giấu. Cần có người nói đúng điều ấy trước mặt Hoàng hậu."}]}},
{"id":"nr:tq_que_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một chiếc khăn tay cũ bạc màu được vị Tổng quản mở ra, bên trong là bông hoa khô đã nát vụn từ lâu."},{"who":"A","text":"Ngày {xung} vào cung, có một người cũ trong làng đã hứa đợi. Bao năm nay chẳng có tin tức."},{"who":"me","text":"Người ấy còn nhớ {goi}, hay {goi} chỉ muốn biết người ấy còn sống?"},{"who":"A","text":"Chỉ muốn biết còn sống hay không, {goi} ạ. Nếu sống, {xung} yên lòng; nếu không, {xung} cũng thôi đợi."},{"who":"me","text":"Chờ tin bao nhiêu năm, nay chỉ xin một lời hỏi thăm. Không khó, chỉ cần có người đi."}]}},
{"id":"nr:tq_que_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong sân giặt sau cung, một bóng phụ nữ lớn tuổi đang cúi mình bên chậu gỗ, bàn tay nứt nẻ dưới nước lạnh."},{"who":"A","text":"Người cũ ấy còn sống, góa chồng, đang làm thuê ở kinh. {Xung} không được phép gặp."},{"who":"me","text":"Một người đợi bao năm, nay ở ngay trong kinh mà không dám nhìn mặt nhau."},{"who":"A","text":"Chỉ cần bà có chỗ nương thân, {xung} cũng đủ yên lòng. Xin {goi} nhận bà vào làm việc giặt giũ ở cung {goi}."},{"who":"me","text":"Một chỗ làm yên ổn là ơn lớn với kẻ góa bụa. Việc này không thể trả lời qua loa."}]}},
{"id":"nr:tq_que_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phòng trực, tờ thư nhà chưa đọc lại được nửa đã bị vị Tổng quản úp xuống, trán lấm tấm mồ hôi."},{"who":"A","text":"Bên {B} đang đồn {xung} ăn bớt bạc của cung để gửi về quê."},{"who":"me","text":"Lời đồn nặng như thế, hẳn có chỗ bám vào. Họ biết số bạc {goi} gửi?"},{"who":"A","text":"Biết rõ đến từng lần, nghĩa là có kẻ từng đọc thư nhà của {xung}. Thư gửi đi kín, vậy mà vẫn lọt."},{"who":"me","text":"Kẻ đọc thư ắt phải nằm trên đường thư đi. Thư qua tay những ai, tìm ra thì thấy."},{"who":"A","text":"Xin {goi} dò giúp. {Xung} thật sự bó tay."}]}},
{"id":"nr:tq_que_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tấm sổ thu chi của cung được xếp ngay ngắn trên án, nhưng nét mực cuối trang vẫn chưa được đối chiếu."},{"who":"A","text":"Thái hậu ghét nhất kẻ ăn bớt bạc cung. Nếu lời đồn đến Đức Thọ cung trước khi sổ được đối, {xung} hết đường."},{"who":"me","text":"Lời đồn chạy nhanh hơn sổ sách. {Goi} sợ nó đến tai Thái hậu trước."},{"who":"A","text":"Phải. Mong {goi} khi hầu Thái hậu, thưa rằng sổ chưa đối thì chưa nên tin lời đồn."},{"who":"me","text":"Một câu nói đúng lúc chặn được cả cơn bão. Chỉ cần sổ sách thật sự sạch."}]}},
{"id":"nr:tq_que_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một bức thư báo lũ nhàu nát, nét mực nhòe nước; vị Tổng quản ngồi bất động, mắt nhìn vào khoảng không."},{"who":"A","text":"Mộ tổ nhà {xung} bị lở sau mùa lũ. Thái giám không được tự ý về sửa mộ, trừ khi có ân ban."},{"who":"me","text":"Mộ tổ lở mà không về được, lòng {goi} chắc nặng lắm."},{"who":"A","text":"Nặng như đá. {Xung} chỉ xin Thái hậu cho một lần ân ấy, rồi cam chịu mọi điều còn lại."},{"who":"me","text":"Chữ hiếu nghe nhẹ trên môi, mà đặt lên vai mới biết sức nặng. Phải tìm lời xin cho vẹn."}]}},
{"id":"nr:tq_que_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một mảnh giấy vẽ sơ đồ nấm mồ họ tộc được trải ra, góc giấy ép bởi hai hòn sỏi mang lên từ quê."},{"who":"A","text":"Thợ ở làng không dám sửa mộ khi chưa có người nhà đứng ra, mà {xung} không về được."},{"who":"me","text":"Một nấm mồ cần cả người sống đứng tên mới được động đến."},{"who":"A","text":"Xin {goi} cho người nhà của {goi} về làng một chuyến, đứng tên cho thợ làm. Chỉ cần có tên là xong."},{"who":"me","text":"Chỉ có tên thôi mà gánh cả chữ hiếu. Phải xem trong nhà ai đi được."}]}},
{"id":"nr:ksp_so_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn Kính sự phòng, khay thẻ bài xếp thẳng hàng; một tấm thẻ cũ nằm lệch ra ngoài, như vừa bị ai đặt nhầm chỗ."},{"who":"A","text":"Đêm qua, tấm thẻ bài Hoàng thượng lật trúng lại là thẻ đã cất đi từ tháng trước. {Xung} không dám tâu là mình sai."},{"who":"me","text":"Thẻ đã cất mà vẫn treo lên khay, nghe ra không phải lỗi nhỏ. Hoàng thượng đã hỏi gì chưa?"},{"who":"A","text":"Chưa, nhưng sớm muộn cũng hỏi. Nếu người hỏi đến, xin {goi} nói rằng hôm trước {goi} còn thấy thẻ ấy treo ở đó."},{"who":"me","text":"Một lời nói đúng với điều mình đã thấy thì không phải dối. Nhưng cũng phải cẩn thận kẻo thành bao che."}]}},
{"id":"nr:ksp_so_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong Kính sự phòng, khay thẻ bài phủ một lớp bụi mỏng, chỉ riêng tấm thẻ bị treo lại là sạch bóng."},{"who":"A","text":"Thẻ bài đã cất bị treo lại vào đúng đêm {xung} đi vắng, mà đêm ấy người của {B} có ghé Kính sự phòng."},{"who":"me","text":"Trùng một đêm, trùng một nơi. Chưa chắc đã phải do hắn."},{"who":"A","text":"Vì thế {xung} mới không dám nói bừa. Chỉ cần biết kẻ ấy đã chạm vào khay thẻ chưa, {xung} sẽ rõ có phải hắn không."},{"who":"me","text":"Chạm vào khay thì để lại dấu. Muốn biết, phải hỏi cho đúng người trực đêm ấy."}]}},
{"id":"nr:ksp_so_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc hộp ngọc khảm xà cừ đặt bên cửa sổ Kính sự phòng, nắp hộp còn nguyên dải lụa buộc."},{"who":"A","text":"{B} sai người đưa {xung} một hộp ngọc, nhờ dời tên lên đầu sổ. {Xung} không nhận."},{"who":"me","text":"Không nhận thì phải trả. Mà trả thẳng thì nàng ta mất mặt, ắt trả thù."},{"who":"A","text":"Chính vậy, {goi} ạ. Xin {goi} cho cung nữ của {goi} mang trả hộ, kèm một lời khéo, để người ấy khỏi mất mặt."},{"who":"me","text":"Trả hộp ngọc mà không làm ai mất thể diện, đó là nghệ thuật. Chỉ nghĩ đã thấy khó."},{"who":"A","text":"Cũng vì khó mà {xung} mới cầu đến {goi}."}]}},
{"id":"nr:ksp_so_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuốn phép tắc Kính sự phòng đặt mở trên án, dòng chữ về việc tâu Trung cung được ai đó gạch dưới bằng mực đỏ."},{"who":"A","text":"Phép Kính sự phòng, kẻ nào được đưa quà xin dời tên là phải tâu Trung cung. {Xung} muốn tâu, mà sợ Hoàng hậu không tin lời kẻ hầu."},{"who":"me","text":"Phép đã đặt ra thì Hoàng hậu không thể trách người tuân phép."},{"who":"A","text":"Chỉ sợ người nghĩ {xung} bịa chuyện vu cung khác. Có người đi cùng, lời nói sẽ có sức."},{"who":"me","text":"Có người bên cạnh, lời của kẻ hầu cũng thành lời chứng. {Xung} hiểu ý {goi}."}]}},
{"id":"nr:ksp_so_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Đêm mưa trút xuống sân Kính sự phòng, trang sổ ghi muộn nằm giữa quyển sổ, nét mực sậm hơn các dòng khác."},{"who":"A","text":"Hoàng hậu sắp xem sổ Kính sự phòng. Trong sổ có một dòng {xung} ghi muộn, nét mực khác màu."},{"who":"me","text":"Khác màu mực thì ai nhìn cũng thấy. Vì sao {goi} ghi muộn?"},{"who":"A","text":"Đêm ấy mưa to, sổ phải mang vào sau, {xung} chép lúc đèn đã tàn. Chỉ cần có người nhắc trước mặt Hoàng hậu."},{"who":"me","text":"Sự thật nằm ngay trong cơn mưa, chỉ cần có người nhắc đúng lúc."}]}},
{"id":"nr:ksp_so_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ giấy lót trong bìa sổ bị gấp lại một góc, như từng có ai mở ra xem lén rồi vội vàng đóng lại."},{"who":"A","text":"Dòng ghi muộn trong sổ đã bị ai đó chỉ cho Hoàng hậu xem trước. Tuần trước chỉ có người của {B} mượn sổ."},{"who":"me","text":"Một người mượn sổ thì chẳng nói được gì, trừ khi hắn mang theo ý khác."},{"who":"A","text":"Phải biết hắn đã nói gì, với ai, trước khi sổ đến tay Hoàng hậu. {Xung} cần biết đường đi của lời ấy."},{"who":"me","text":"Lời đi bằng miệng người, muốn lần phải hỏi người nghe. Việc này hợp với người trong cung."}]}},
{"id":"nr:ksp_so_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên bàn tiểu thái giám mới đến có một tờ giấy chép nhỏ, nét chữ ngay ngắn, mực còn tươi."},{"who":"A","text":"Có kẻ chép sổ Kính sự phòng mang ra ngoài. Ai được lật thẻ đêm nào cũng lọt ra cả."},{"who":"me","text":"Tin ấy tuyệt mật, mà đã lọt đến tai người ngoài. {Goi} nghi ai?"},{"who":"A","text":"Một tiểu thái giám mới đến, chưa đầy một tháng. Hắn hay lui tới nơi nào, có phải cung của {B} không, {xung} chưa dám nói."},{"who":"me","text":"Dò cho đúng người rồi mới nói, kẻo oan một đứa trẻ."}]}},
{"id":"nr:ksp_so_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hơi thở đứt quãng, tiểu thái giám nấp sau cánh cửa phụ Kính sự phòng, hai tay ôm chặt tờ giấy đã nhàu."},{"who":"A","text":"Tiểu thái giám chép sổ đã chịu khai ra người sai khiến. Giờ ngày đêm hắn sợ bị trả thù."},{"who":"me","text":"Đứa trẻ ấy biết quá nhiều nên không còn chỗ nào yên thân."},{"who":"A","text":"Xin {goi} giữ hắn trong cung {goi}, chờ ngày {xung} đưa hắn ra làm chứng. Ở bên ngoài thì hắn không sống nổi."},{"who":"me","text":"Giữ một người làm chứng cũng là gánh một phần hiểm nguy. {Xung} phải cân nhắc."}]}},
{"id":"nr:ksp_so_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mùi thuốc thoang thoảng trong Kính sự phòng; trang sổ ghi ngày thai của một vị chủ cung bị gạch đi viết lại hai lần."},{"who":"A","text":"Một vị chủ cung báo có thai, mà ngày ghi trong sổ của {xung} lệch với lời thái y. Một bên sai thì một mạng người khó yên."},{"who":"me","text":"Sổ ghi ngày, thái y xem mạch, hai lời không khớp thì phải có một bên nhầm."},{"who":"A","text":"Phải biết bên nào nhầm trước khi ghi sổ. Xin {goi} mời một thái y quen bắt mạch kín cho vị chủ cung ấy."},{"who":"me","text":"Bắt mạch kín để không làm kinh động ai. Việc này có thể làm được nếu chọn đúng người."},{"who":"A","text":"Chỉ cần mạch án rõ, {xung} mới biết nên ghi thế nào."}]}},
{"id":"nr:ksp_so_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Con dấu của Trung cung nằm trên bàn bên hộp son, sổ của Kính sự phòng chờ đóng dấu từ hôm trước."},{"who":"A","text":"Ngày ghi trong sổ phải được Trung cung đóng dấu. Nếu Hoàng hậu cho Thái y viện nghiệm lại mạch trước khi đóng dấu, sổ của {xung} sẽ không lệch."},{"who":"me","text":"Đóng dấu rồi thì sai cũng thành đúng, khó sửa. Nên nghiệm lại trước là lẽ phải."},{"who":"A","text":"Chỉ cần Hoàng hậu gật đầu một cái. Xin {goi} thưa giúp một câu."},{"who":"me","text":"Một câu đủ giữ cả cuốn sổ. {Xung} sẽ tìm lúc thích hợp thưa với Hoàng hậu."}]}},
{"id":"nr:ksp_so_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cuối năm, cuốn sổ Kính sự phòng được bọc lụa vàng chuẩn bị dâng ngự thư phòng, bìa sổ lau sạch không một vết."},{"who":"A","text":"Cuối năm sổ được trình Hoàng thượng. Sổ khớp từng ngày, nhưng đã có người nói trước với Hoàng thượng rằng sổ lệch."},{"who":"me","text":"Lời nói đến trước, sổ đến sau. Hoàng thượng khó mà không nghi."},{"who":"A","text":"Xin {goi} khi hầu, nói rằng {goi} tin sổ của {xung} ghi đúng. Người nghe lời {goi} thì sẽ nhìn sổ bằng mắt khác."},{"who":"me","text":"Tin hay không tin là chuyện của lòng người. {Xung} chỉ nói được điều mình thấy."}]}},
{"id":"nr:ksp_so_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới đèn cung, một tờ chép sổ nhàu nát hiện ra từ ngăn tủ lạ; từng hàng chữ trên đó nét nghiêng khác thường."},{"who":"A","text":"Người nói trước với Hoàng thượng rằng sổ lệch là {B}. Nàng ta có trong tay một tờ chép sổ."},{"who":"me","text":"Tờ chép ấy lấy từ đâu thì sẽ biết nàng ta biết điều gì."},{"who":"A","text":"{Xung} cần biết tờ ấy chép từ trang nào. Nếu là trang mới sửa thì có người trong Kính sự phòng đã làm lộ."},{"who":"me","text":"Một tờ giấy mà đáng nghi đến thế. Phải xem nó từ trang nào ra, và ai đã chép."}]}},
{"id":"nr:eun_len_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Ngoài cửa Ngự thiện phòng, mùi hành phi thơm lẫn khói bếp, một tiểu thái giám đứng nép bên cửa tay nắm chặt vạt áo."},{"who":"A","text":"Có một lão thái giám ở Ngự thiện phòng chịu nhận {xung} làm đồ đệ. Chỉ còn ngại {xung} không có ai bảo lãnh."},{"who":"me","text":"Lão ấy nhận trò thì thích gì ở trò?"},{"who":"A","text":"Chắc lão muốn người thật thà chịu khó. {Xung} không dám tự khen, mà người ngoài thì ai chịu nói giúp một tiểu thái giám vô danh."},{"who":"me","text":"Một lời tốt từ người có tiếng nói nặng bằng cả mâm lễ. Chỉ cần lời ấy thật."}]}},
{"id":"nr:eun_len_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong góc bếp, một cái nồi đồng bị hỏng nằm lăn, cả đám thái giám đang xì xào nhìn về phía tiểu thái giám đứng cúi mặt."},{"who":"A","text":"Có kẻ nói với lão thái giám Ngự thiện phòng rằng {xung} trộm đồ, mà lời ấy đi ra từ miệng {B}."},{"who":"me","text":"{Goi} có từng gây hiềm khích với {B} chưa mà nàng ta nhắm vào {goi}?"},{"who":"A","text":"Chưa một lần. {Xung} chỉ là tiểu thái giám vô danh, vậy mà bị vu. Xin {goi} dò giúp vì sao {B} muốn hại {xung}."},{"who":"me","text":"Người ta không vu một kẻ vô danh vô cớ. Phía sau chắc có việc lớn hơn."}]}},
{"id":"nr:eun_len_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Căn phòng chung của đám thái giám chất đầy xô nước và giỏ củi, một tiểu thái giám xách nặng đến mức vai nghiêng hẳn."},{"who":"A","text":"Bọn thái giám cùng phòng đổ hết việc nặng cho {xung}, rồi kể với quản sự rằng {xung} lười. Nghe nói chúng nghe theo {B}."},{"who":"me","text":"Một đám đông hùa nhau thường có một kẻ đứng đầu. {Goi} có đoán được là ai?"},{"who":"A","text":"Không rõ. Biết ai cầm đầu thì {xung} mới biết nên tránh đường nào, đừng đụng nhầm kẻ không đáng đụng."},{"who":"me","text":"Tránh được đúng người còn hơn chịu đòn mà không biết ai đánh."}]}},
{"id":"nr:eun_len_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách kẻ lười bị gạch mực đỏ nằm trên bàn quản sự phòng thái giám, tên một tiểu thái giám vừa được viết thêm vào cuối trang."},{"who":"A","text":"Quản sự phòng thái giám sắp trình Trung cung danh sách kẻ lười để đuổi ra ngoài. Tên {xung} có trong đó, vì lời bọn cùng phòng."},{"who":"me","text":"Đuổi ra ngoài là hết đường sống. {Goi} làm việc có sai điều gì không?"},{"who":"A","text":"Chưa từng sai. {Xung} thức khuya dậy sớm, chỉ vì bị vu mà mang tội. Xin {goi} thưa với Hoàng hậu một lời."},{"who":"me","text":"Một lời thưa đúng với sự thật thì không sợ nặng. Danh sách chưa trình, còn kịp."}]}},
{"id":"nr:eun_len_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới mái hiên phòng thái giám, một bóng người lạ đứng khuất, ánh mắt dán vào cánh cửa mỗi lần tiểu thái giám bước qua."},{"who":"A","text":"Mấy hôm nay có kẻ cứ dò hỏi {xung} chuyện trong cung mà {xung} hầu. {Xung} chưa nói một lời."},{"who":"me","text":"Dò hỏi như thế, kẻ ấy hẳn đã biết {goi} hầu cung nào. Hắn hỏi chuyện gì?"},{"who":"A","text":"Hỏi ai đến, ai đi, giờ nào nghỉ. Nghe cứ như đang vẽ lại cả một ngày của cung ấy. {Xung} sợ hắn do {B} sai đến."},{"who":"me","text":"Nếu là thật thì không chỉ là tò mò mà là rình rập. Phải biết rõ ai đứng sau hắn."}]}},
{"id":"nr:eun_len_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc chăn mỏng ở góc phòng thái giám run lên từng nhịp, một đứa nhỏ nằm co ro bên trong, không dám ló đầu ra."},{"who":"A","text":"Kẻ dò hỏi đã dọa đánh tiểu thái giám ngủ cùng phòng với {xung}, nếu {xung} không chịu nói."},{"who":"me","text":"Hắn đánh một đứa trẻ để ép người khác mở miệng. Thật đáng giận."},{"who":"A","text":"Nó không có tội, chỉ vì ở gần {xung} mà bị liên lụy. Xin {goi} cho nó sang làm việc ở cung {goi} ít lâu."},{"who":"me","text":"Đưa đứa nhỏ ra khỏi tầm tay kẻ ép buộc, đó là việc nhân từ. {Xung} sẽ nghĩ cách."}]}},
{"id":"nr:eun_len_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Dưới nệm cói trong phòng thái giám, một chiếc túi vải nhỏ được giấu kỹ; tiểu thái giám sờ vào đó thêm một lần nữa mới yên tâm."},{"who":"A","text":"{Xung} để dành được ít bạc đầu tiên, mà phòng thái giám không có chỗ nào khóa được."},{"who":"me","text":"Số bạc ấy, {goi} đã phải dành dụm bao lâu?"},{"who":"A","text":"Gần cả năm trời, từng đồng từng hào. Nếu mất thì {xung} chẳng còn gì. Xin {goi} giữ hộ, đến ngày {xung} cần."},{"who":"me","text":"Nhận giữ bạc của kẻ khác là nhận một lời hứa. Nhỏ thôi, nhưng đáng để nghĩ."}]}},
{"id":"nr:eun_len_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc túi vải rỗng treo trên vách phòng thái giám, nút buộc đã bị ai đó cởi ra mà không buộc lại như cũ."},{"who":"A","text":"Bạc {xung} để dành bị mất hai lần, lần nào cũng vào hôm {B} ghé phòng thái giám."},{"who":"me","text":"Hai lần trùng một ngày thì cũng là điều đáng ngờ. Nhưng nàng ta ghé phòng thái giám làm gì?"},{"who":"A","text":"Nói là tìm người dạy việc, nhưng đứng nhìn quanh lâu hơn cần. {Xung} muốn biết kẻ nhặt túi bạc ấy là ai."},{"who":"me","text":"Phòng chỉ có chừng ấy người, tìm ra không khó nếu biết nhìn."}]}},
{"id":"nr:eun_len_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước thềm Nội vụ phủ, tờ danh sách đồ lễ Vạn thọ dài đến chạm đất, tiểu thái giám cầm bút mà tay vẫn còn run."},{"who":"A","text":"{Xung} được giao mua sắm đồ cho lễ Vạn thọ, phải ra cung cùng quan Nội vụ phủ. Quan ấy quen ăn bớt."},{"who":"me","text":"Giá thật giá giả khó phân khi người đi cùng đã quen tay. {Goi} định xử trí thế nào?"},{"who":"A","text":"{Xung} không dám nói thẳng, mà cũng không muốn để hỏng việc lớn. Xin {goi} cho {xung} một người của cung {goi} đi cùng, để có người làm chứng giá thật."},{"who":"me","text":"Có người làm chứng thì quan ấy cũng phải e dè. Chỉ cần chọn đúng người đi."}]}},
{"id":"nr:eun_len_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản báo giá đồ lễ được chép sạch sẽ trên giấy hoa tiên, nhưng con số cuối cùng lại cao hơn hẳn giá chợ."},{"who":"A","text":"{B} là kẻ đứng giữa, báo giá khống để quan Nội vụ phủ ăn bớt, nên chẳng ai dám nói."},{"who":"me","text":"Giá khống thì phần chênh phải chảy đi đâu đó. {Goi} thử tính chưa?"},{"who":"A","text":"Tính được rằng phần chênh không nhỏ. {Xung} cần biết nó qua tay {B} rồi đi về đâu."},{"who":"me","text":"Tiền đi đâu thì quyền đi đó. Lần ra chỗ ấy là lần ra gốc."}]}},
{"id":"nr:eun_len_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ danh sách quản sự phòng được kẹp trong cặp gỗ, một dòng cuối còn bỏ trống như chờ ai đó điền tên vào."},{"who":"A","text":"Tổng quản sắp chọn người lên làm quản sự một phòng. Chỉ cần một vị chủ cung nhắc đến tên, {xung} sẽ có tên trong danh sách."},{"who":"me","text":"Một bậc thang đáng giá như vậy mà chỉ cần một lời. {Goi} đã dốc hết sức chưa?"},{"who":"A","text":"Chỉ còn thiếu một lời. Sức {xung} đã bỏ ra nhiều năm, chỉ chưa ai nhìn thấy."},{"who":"me","text":"Công sức nhiều năm cần một người nhắc đến mới thành bậc thang. Đáng để nói giúp một lời."}]}},
{"id":"nr:eun_len_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chiếc chén trà men xanh năm xưa vẫn còn trên khay cũ, tiểu thái giám nhìn nó mà lòng như bồi hồi."},{"who":"A","text":"Danh sách quản sự cuối cùng phải dâng Hoàng thượng xem. Nếu người thấy tên {xung} mà nhớ ra kẻ hầu trà hôm nọ, tên ấy sẽ không bị gạch."},{"who":"me","text":"Hôm nọ {goi} hầu trà thế nào mà đáng nhớ?"},{"who":"A","text":"Không có gì đặc biệt, chỉ là {xung} không làm đổ một giọt. Nhưng biết đâu Hoàng thượng còn nhớ."},{"who":"me","text":"Chén trà không đổ cũng là một cái tên. Xin nhắc lại cho người nhớ."}]}},
{"id":"nr:off_ghe_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong phủ quan, tiệc rượu tan từ lâu mà đèn lồng vẫn còn sáng; vị quan đứng bên cửa sổ nhìn con đường dẫn sang phủ bên cạnh."},{"who":"A","text":"Có người trong bộ của {xung} ngày ngày đến phủ {B} ăn tiệc. Nếu phủ ấy có người nhà trong hậu cung, chuyện thăng giáng của bộ {xung} ắt lọt vào đây."},{"who":"me","text":"Tiệc rượu thì bàn chuyện triều, rượu cạn lời thật cũng lộ. {Goi} nghi ngờ ai?"},{"who":"A","text":"Chưa dám nghi ai, chỉ cần biết trong cung ai hay kể chuyện ấy. Xin {goi} để ý giúp."},{"who":"me","text":"Trong cung lời đi nhanh hơn gió, chỉ cần lắng tai đúng chỗ."}]}},
{"id":"nr:off_ghe_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản sớ xin chia bộ đặt trên án thư ngự, mép sớ còn ẩm mực, người đứng cạnh vị quan không dám thở mạnh."},{"who":"A","text":"Trong triều có người dâng sớ xin chia bộ của {xung} làm hai, Hoàng thượng chưa phê."},{"who":"me","text":"Chia bộ nghĩa là chia quyền. {Goi} đoán ai muốn thế?"},{"who":"A","text":"Người nào có lợi từ việc ấy thì {goi} đoán được. Điều {xung} lo là Hoàng thượng nghe theo sự xúi giục."},{"who":"me","text":"Một lời đúng đắn trước mặt Hoàng thượng đủ chặn cả bản sớ. Phải nói rằng việc trong bộ đang trôi chảy."},{"who":"A","text":"Chính thế. Chia ra chỉ thêm rối thôi, {goi} ạ."}]}},
{"id":"nr:off_ghe_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước án Nội các, tờ văn thư của vị quan nằm chờ mãi một nét chữ ký, giấy đã hơi cong vì ẩm."},{"who":"A","text":"Việc trong bộ đang kẹt lại, chỉ vì thiếu một chữ ký của Nội các. Người giữ ấn ở Nội các có mẹ là ma ma cũ trong cung."},{"who":"me","text":"Chữ ký thiếu một nét mà cả bộ đứng yên. Ma ma ấy có chịu nói giúp không?"},{"who":"A","text":"Bà vốn trọng người trong cung. Nếu {goi} cho gọi bà đến hầu chuyện một buổi, {xung} sẽ có đường nói."},{"who":"me","text":"Một buổi trà mà thông được cả con đường. Việc này đáng thử."}]}},
{"id":"nr:off_ghe_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ văn thư của vị quan bị chặn ở Nội các đã ba ngày, trên mặt giấy có một vết ngón tay lạ in nhẹ."},{"who":"A","text":"Chữ ký ở Nội các bị giữ là do {B} gửi lời. {Xung} cần biết hắn đã hứa gì với người giữ ấn."},{"who":"me","text":"Hứa gì thì mới giữ được một chữ ký ba ngày chứ."},{"who":"A","text":"Lễ vật hay lời hứa thăng chức, {xung} chưa rõ. Chỉ biết nếu không lần ra, văn thư cứ kẹt mãi."},{"who":"me","text":"Lần theo lễ vật là cách chắc nhất. Người ta nhận quà thì để lại dấu."}]}},
{"id":"nr:off_ghe_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng phủ quan, mấy xấp sổ cũ buộc dây gai xếp chồng trên tủ, giấy đã sờn mép vì lật nhiều."},{"who":"A","text":"Ngự sử sắp xét sổ của bộ. Có mấy trang sổ cũ {xung} chưa kịp đối chiếu, để ở phủ thì sợ bị lấy."},{"who":"me","text":"Sổ để trong phủ mình mà còn sợ mất. Vậy là {goi} đã nghi trong nhà có kẻ khác lòng."},{"who":"A","text":"Chưa dám nói chắc. Nhưng cẩn tắc vô áy náy, xin {goi} cho người nhà của {goi} giữ giúp ít hôm."},{"who":"me","text":"Giữ sổ của một vị quan là giữ cả một phần danh tiết. Việc này không nhỏ."}]}},
{"id":"nr:off_ghe_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản báo của ngự sử đặt trên bàn, những trang bị khoanh tròn đều là trang chưa đối, không sót một trang nào."},{"who":"A","text":"Ngự sử biết trước trang sổ nào chưa đối, nghĩa là trong bộ của {xung} có người báo. Người ấy hay lui tới phủ {B}."},{"who":"me","text":"Biết đúng trang nào chưa đối thì không phải đoán mò, phải có người chỉ."},{"who":"A","text":"{Xung} nghĩ mãi mà không ra là ai. Xin {goi} dò giúp, để {xung} khỏi nghi oan người ngay."},{"who":"me","text":"Tránh oan cho người ngay cũng là giữ phúc cho mình. Phải dò thật kín."}]}},
{"id":"nr:off_ghe_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chầu sớm vừa tan, vị quan đứng nán lại ngoài điện, mắt dõi về phía cửa ngự thư phòng vẫn đóng im ỉm."},{"who":"A","text":"Dạo này Hoàng thượng hỏi chuyện bộ của {xung} toàn qua người khác. {Xung} không dám xin vào gặp riêng."},{"who":"me","text":"Người ta bớt hỏi thẳng, tức là bớt tin. {Goi} cảm thấy điều ấy từ bao giờ?"},{"who":"A","text":"Từ hôm có tin đồn kia lan ra. {Xung} chỉ mong Hoàng thượng biết {xung} vẫn ngày ngày chờ được gọi vào tâu."},{"who":"me","text":"Nhắc một câu cho người nhớ có người đang chờ. Không xin gì, chỉ xin được nhớ."},{"who":"A","text":"Đúng thế. Được nhớ là đủ."}]}},
{"id":"nr:off_ghe_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ biểu đầu năm được cất trong hộp gỗ đàn, nét chữ còn nguyên, ấn đỏ vẫn tươi như mới đóng hôm qua."},{"who":"A","text":"Thái hậu từng khen tờ biểu đầu năm của {xung}. Nếu người nhắc lại một câu trước mặt Hoàng thượng, lòng nghi sẽ nhạt."},{"who":"me","text":"Lời khen của Thái hậu là sự bảo chứng cho cả bài văn. Hoàng thượng không thể không nể."},{"who":"A","text":"Chỉ cần gợi lại thôi, {xung} không dám xin Thái hậu nói thêm lời nào. Xin {goi} khi hầu Thái hậu, nhắc nhẹ tờ biểu ấy."},{"who":"me","text":"Nhắc một bài văn đã được khen, như nhắc một món nợ ân. Không khó chút nào."}]}},
{"id":"nr:off_ghe_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong thư phòng, hai bức thư của môn sinh cũ đặt cạnh nhau, một thư lễ phép từ năm trước, một thư lạnh nhạt vừa mới đến."},{"who":"A","text":"Một môn sinh của {xung} đỗ đạt mà không chịu nhận thầy, đi lại với phủ khác. Nhà hắn có cô con gái út làm cung nữ trong cung."},{"who":"me","text":"Đỗ đạt rồi quên thầy cũng chẳng hiếm. Nhưng {goi} muốn làm gì với cô con gái?"},{"who":"A","text":"Xin {goi} nhận nàng về hầu cung {goi}, để môn sinh ấy biết nhà ai còn nhớ ơn. Không phải ép buộc, chỉ là một lẽ."},{"who":"me","text":"Ơn nghĩa không thể cưỡng cầu, nhưng có thể gợi nhớ. Việc này cũng cần hỏi ý nàng."}]}},
{"id":"nr:off_ghe_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Vị quan cầm một tờ giấy nháp đã vo viên, nét chữ của môn sinh cũ vẫn còn nhận ra dù đã bị gạch xóa nhiều chỗ."},{"who":"A","text":"Môn sinh phản thầy kia giờ đang viết sớ cho {B}. {Xung} cần biết hắn sắp viết gì, để kịp liệu đường."},{"who":"me","text":"Một bản sớ viết cho người khác lại cầm trong tay thầy cũ. Chắc nhiều điều khó nói."},{"who":"A","text":"Hắn biết rõ sở đoản của {xung}, nên sớ ấy không dễ đỡ. Nếu biết trước, {xung} còn kịp chuẩn bị."},{"who":"me","text":"Biết trước một lời buộc tội còn hơn nghe nó trước mặt triều. Phải dò cho kịp thời."}]}},
{"id":"nr:off_ghe_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước buổi chầu lớn, bộ triều phục của vị quan đã được là phẳng treo ngay ngắn, nhưng người mặc thì chưa hề chợp mắt."},{"who":"A","text":"Buổi chầu lớn sắp tới, phe kia sẽ dâng sớ nhắm vào {xung}. Nếu Thái hậu cho gọi phu nhân của {xung} vào hầu trước đó, cả triều sẽ hiểu nhà {xung} chưa mất chỗ dựa."},{"who":"me","text":"Một buổi hầu chuyện trước thềm chầu cũng là một lời tuyên bố ngầm."},{"who":"A","text":"Chính thế. Xin {goi} xin giúp một lời, để Thái hậu cho gọi phu nhân của {xung}."},{"who":"me","text":"Chuyện nhà quan lại thành chuyện triều đình. Muốn xin thì phải xin thật nhã."}]}},
{"id":"nr:off_ghe_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bản sớ nháp chép tay nằm lẫn trong xấp giấy của phủ {B}, từng hàng chữ dày đặc như đang kể một bản án."},{"who":"A","text":"Sớ nhắm vào {xung} ở buổi chầu lớn sẽ do {B} đứng tên. {Xung} cần biết trong sớ kể những tội gì."},{"who":"me","text":"Biết từng tội thì mới đáp từng điều. Còn không thì ra điện cũng như đi mò trong đêm."},{"who":"A","text":"Chính vậy. Không cần cả bản sớ, chỉ cần biết mấy điều chính. Xin {goi} giúp {xung} nghe ngóng."},{"who":"me","text":"Nghe ngóng thôi mà quyết định cả buổi chầu. Phải làm thật khéo."}]}},
{"id":"nr:off_dan_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mấy tờ sổ ba năm trước được trải ra, một dòng ghi sai nằm giữa trang như vết mực đổ không lau được."},{"who":"A","text":"Ngự sử đang tra sổ sách nhà {xung} ba năm trước. Có một khoản ghi nhầm do thư lại cũ, mà người ấy đã về quê."},{"who":"me","text":"Chỉ một khoản ghi nhầm mà sắp thành tội. Thư lại ấy chắc nhớ rõ chuyện cũ."},{"who":"A","text":"Nếu tìm được ông ta, nhờ ông xác nhận một câu là rõ. Nhưng quê ông xa, {xung} không có người để sai."},{"who":"me","text":"Đường xa không đáng sợ bằng việc người ta quên mất. Phải tìm cho kịp."}]}},
{"id":"nr:off_dan_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ biên bản tra sổ của ngự sử đặt giữa án, những trang bị khoanh vòng đều trùng đúng chỗ sai sót."},{"who":"A","text":"Ngự sử tra đúng khoản ghi nhầm, như đã có người chỉ chỗ, mà người chỉ chỗ ăn lương của phủ {B}."},{"who":"me","text":"Chỉ đúng chỗ sai, tức là biết sổ rõ như lòng bàn tay. Chắc đã từng xem lén."},{"who":"A","text":"{Xung} cũng nghĩ thế. Xin {goi} dò giúp {xung} hắn đã đưa ngự sử những trang nào."},{"who":"me","text":"Những trang đưa đi cho thấy hắn muốn buộc tội điều gì. Dò ra thì biết đối sách."}]}},
{"id":"nr:off_dan_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Mấy tờ thiếp mời tiệc nhà quan bị trả về nguyên niêm, không một lời hồi âm, vị quan lặng lẽ ngồi nhìn chúng chồng cao dần."},{"who":"A","text":"Mấy nhà vẫn đi lại với {xung} giờ đều im lặng. {Xung} muốn biết ai đã nhận lời của {B}."},{"who":"me","text":"Im lặng thì không nói được là thân hay sợ. {Goi} nghĩ nhà nào đã đổi lòng?"},{"who":"A","text":"Chưa biết. Phu nhân các nhà ấy hay vào cung thỉnh an. Xin {goi} để ý xem ai đi lại với cung nào."},{"who":"me","text":"Lúc thỉnh an người ta để lộ ý. Chỉ cần nhìn xem họ ghé cung nào, lâu hay mau."}]}},
{"id":"nr:off_dan_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Danh sách quà ban dịp lễ của các năm trước được vị quan lật ra, năm nay trang giấy vẫn trống như chờ ai điền vào."},{"who":"A","text":"Các nhà đồng minh im lặng vì sợ. Nếu Thái hậu vẫn ban cho nhà {xung} món quà dịp lễ như mọi năm, họ sẽ hiểu chưa có gì đổi."},{"who":"me","text":"Một món quà nhỏ làm yên cả những nhà đang e dè. Thái hậu hiểu điều ấy."},{"who":"A","text":"Chỉ sợ năm nay người không nhớ. Xin {goi} nhắc Thái hậu món quà ấy."},{"who":"me","text":"Nhắc một thói quen cũ không phải xin ơn, chỉ gợi lại lẽ thường."}]}},
{"id":"nr:off_dan_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Lá thư có chữ ký của vị quan nằm trên án ngự sử, chữ ký giống đến mức chính người cũng phải nhìn lâu mới nhận ra là giả."},{"who":"A","text":"{B} trình lên một lá thư có chữ ký của {xung}. Chữ ký ấy giả. Chữ thật của {xung} có trong tờ biểu mừng thọ năm trước dâng vào cung."},{"who":"me","text":"Có chữ thật để đối chiếu thì giả sẽ lộ. Tờ biểu ấy nay ở đâu?"},{"who":"A","text":"Cất ở Nội vụ phủ, trong kho thư. {Xung} không có quyền vào xem. Xin {goi} tìm giúp tờ biểu ấy."},{"who":"me","text":"Kho thư của Nội vụ phủ hẳn không để người ngoài đụng vào. Phải có người cầm đúng chìa."}]}},
{"id":"nr:off_dan_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hai lá thư được trải cạnh nhau dưới ánh nến trong ngự thư phòng, một lá nét chữ thanh nhã, một lá giống đến kỳ lạ."},{"who":"A","text":"Chữ ký giả cần người tinh mắt xem, mà Hoàng thượng viết chữ đẹp, nhìn nét là biết."},{"who":"me","text":"Người am nét chữ thì nhìn là thấy hồn chữ. Khác nhau ở chỗ nào, chỉ cần một ánh nhìn."},{"who":"A","text":"Xin {goi} khi hầu, xin Hoàng thượng tự xem nét chữ thật của {xung} đặt cạnh chữ giả. {Xung} không cần biện bạch."},{"who":"me","text":"Để nét chữ tự kể lại sự thật, không cần ai nói thay. Cách ấy nhã mà chắc."}]}},
{"id":"nr:off_dan_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trong vườn hoa hậu cung, đám cung nhân quây quần rỉ tai, thấy bóng người lạ liền im bặt rồi tản đi nhanh."},{"who":"A","text":"Trong hậu cung đang có người đem chuyện đàn hặc nhà {xung} ra bàn, như nhà đã có tội."},{"who":"me","text":"Án chưa xét mà người đã kết tội. Lời đồn thường nhanh chân hơn công lý."},{"who":"A","text":"Xin {goi} thưa với Hoàng hậu một câu: án chưa xét, chưa ai có tội."},{"who":"me","text":"Một câu nói đúng ở chỗ đúng đủ làm lời đồn ngừng. {Xung} sẽ tìm dịp thưa."}]}},
{"id":"nr:off_dan_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tiệc nhà phủ {B} vừa tan, chén đĩa còn ngổn ngang mà tin đồn đã tới tận cung môn."},{"who":"A","text":"Lời bàn nhà {xung} có tội lan khắp hậu cung ngay sau khi phủ {B} mở tiệc."},{"who":"me","text":"Tiệc mới tan mà tin đã đi khắp cung. Người ta chuẩn bị trước cả."},{"who":"A","text":"Xin {goi} dò giúp lời ấy đi ra từ cung nào, để biết ai đang thổi lửa."},{"who":"me","text":"Lửa có nguồn thì có người đốt. Tìm đúng người thì lửa tắt."}]}},
{"id":"nr:off_dan_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ sớ hặc đóng dấu Ngự sử đài nằm giữa án, một dòng bị khoanh đỏ ghi rằng hôm ấy vị quan không có mặt ở kinh."},{"who":"A","text":"Sớ hặc của {B} nói hôm ấy {xung} ở phủ huyện, không ở kinh. Nhưng hôm ấy {xung} có vào cung chầu."},{"who":"me","text":"Nếu hôm ấy có vào chầu, sổ ra vào cửa cung sẽ ghi rõ."},{"who":"A","text":"Chính thế. Nếu tên {xung} có trong sổ ấy, sớ kia là sai. Xin {goi} hỏi giúp sổ ra vào cửa cung hôm ấy."},{"who":"me","text":"Một dòng ghi nhận ở cửa cung lật được cả bản sớ hặc. Chuyện nhỏ mà quan trọng."}]}},
{"id":"nr:off_dan_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một lá thư sắp gửi đi cho quan nhỏ nơi xa nằm trên án, mực chưa khô, góc thư viết đi viết lại tên một huyện lạ."},{"who":"A","text":"Đại Lý tự cần người làm chứng hôm {xung} vào chầu. Người ấy là một quan nhỏ ở Lễ bộ, nay đã đổi ra ngoài tỉnh."},{"who":"me","text":"Quan ấy còn nhớ rõ hôm đó không?"},{"who":"A","text":"Chắc còn nhớ, vì hôm ấy ông đứng ngay cạnh {xung}. Nhưng thư của {xung} gửi đi e không tới."},{"who":"me","text":"Thư của người đang bị hặc thường bị giữ lại. Cần một người ngoài sự nghi ngờ viết thay."}]}},
{"id":"nr:off_dan_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trên án thư, bản tạ tội của vị quan đã được chép sạch, từng hàng chữ ngay ngắn như lời trần tình của một người ngay thẳng."},{"who":"A","text":"Chẳng còn bao lâu nữa Hoàng thượng sẽ định đoạt. {Xung} đã viết một bản tạ tội, nhận phần lỗi của {xung}, chối phần lỗi không phải của {xung}."},{"who":"me","text":"Nhận phần thật, chối phần oan. Đó là cách của người trung thực."},{"who":"A","text":"Chỉ sợ Hoàng thượng chỉ đọc dòng đầu mà bỏ qua phần sau. Xin {goi} khuyên người đọc hết bản ấy."},{"who":"me","text":"Đọc hết mới hiểu hết. Một bản tạ tội viết thật lòng sẽ không sợ bị đọc kỹ."}]}},
{"id":"nr:off_dan_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Bàn thờ gia tiên nhà quan thắp đủ đèn, phu nhân ngồi một mình bên cạnh, tay vân vê vạt áo lễ phục vẫn chưa kịp thay."},{"who":"A","text":"Nếu nhà {xung} bị phạt bổng, phu nhân sẽ mất chỗ trong lễ mừng thọ của Trung cung. Người ngoài nhìn chỗ ngồi để đoán việc nhà."},{"who":"me","text":"Một chỗ ngồi mà nói lên cả thế nhà. Nếu mất chỗ, nhà mất mặt."},{"who":"A","text":"{Xung} không sợ bị phạt, chỉ sợ phu nhân bị coi thường. Xin {goi} thưa với Hoàng hậu, giữ chỗ ấy cho phu nhân."},{"who":"me","text":"Giữ thể diện cho người đàn bà trong nhà là giữ tôn nghiêm của cả nhà. {Xung} thấu hiểu."}]}},
{"id":"nr:off_thong_5#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng chùa Hộ Quốc, lá số của đôi trẻ được gói trong khăn đỏ, vị quan cầm trên tay mà ngần ngừ không dám đưa."},{"who":"A","text":"Lá số của con {xung} đang nằm ở chùa Hộ Quốc. Nhà kia nhờ sư trụ trì xem tuổi rồi bảo tuổi hai trẻ xung khắc."},{"who":"me","text":"Một lời nói ra từ cửa Phật thì khó đổi. Nhưng {goi} nghĩ sư xem đúng không?"},{"who":"A","text":"{Xung} không dám nghi sư, chỉ nghĩ có thể xem lại. Nếu trong cung có người đến lễ chùa ấy, lời xin xem lại sẽ được nghe."},{"who":"me","text":"Đi lễ chùa vốn là việc thường của người trong cung. Xin xem lại lá số cũng không khó nói."}]}},
{"id":"nr:off_thong_5#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Sổ cúng dường của chùa Hộ Quốc mở ra trên án thờ, một dòng mực mới được thêm vào cạnh dòng ghi ngày xem tuổi."},{"who":"A","text":"Sư trụ trì chùa Hộ Quốc vừa nhận cúng dường của phủ {B}, ngay hôm trước khi sư bảo tuổi hai trẻ xung khắc."},{"who":"me","text":"Trùng hôm thì cũng đáng ngờ. Nhưng Phật môn nhận cúng dường là chuyện thường."},{"who":"A","text":"Chính vì thường mà người ta dễ bỏ qua. Xin {goi} dò giúp {xung} bên ấy đã nhờ sư nói gì."},{"who":"me","text":"Lời nhờ không ghi trong sổ, nhưng người ngoài đi lại sẽ thấy."}]}},
{"id":"nr:off_thong_6#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Hòm sính lễ sơn son đặt giữa gian chính, nắp hòm chưa đóng, bên trong còn một khoảng trống chờ lấp."},{"who":"A","text":"Nhà có người trong cung kết thông gia, sính lễ phải được Trung cung gật đầu."},{"who":"me","text":"Trung cung gật đầu mới thành lễ. Có điều gì khiến {goi} lo?"},{"who":"A","text":"Lễ của {xung} không biết đã đủ hay chưa, sợ bị chê là thiếu. Xin {goi} thưa trước với Hoàng hậu."},{"who":"me","text":"Thưa trước thì sửa được trước. Một bước lo xa như vậy rất hợp lý."}]}},
{"id":"nr:off_thong_6#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một tấm lụa ban của Đức Thọ cung được vị quan nhắc tới, ánh mắt thoáng sáng lên như vừa nhớ ra điều gì hay."},{"who":"A","text":"Sính lễ mà có một món ban từ Đức Thọ cung thì không ai dám chê. Thái hậu vốn thương nhà gái."},{"who":"me","text":"Chỉ một món nhỏ mà nâng cả lễ lên. Thái hậu hiểu rõ điều ấy."},{"who":"A","text":"Xin {goi} khi hầu Thái hậu, kể chuyện hai trẻ, xin người ban cho nhà {xung} một món nhỏ."},{"who":"me","text":"Chuyện đôi trẻ nghe vào lòng người đã từng trải. Kể thật là đủ."}]}},
{"id":"nr:off_thong_7#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng nhà gái, một bà mối áo nâu cầm quạt cói bước vào, cười nói rôm rả như đã quen đường từ lâu."},{"who":"A","text":"{B} đang chen ngang, sai bà mối đến nhà gái mỗi tuần. {Xung} cần biết ai trong cung đứng sau."},{"who":"me","text":"Mỗi tuần một lần thì không phải chuyện tình cờ. Bà mối ấy kể gì với nhà gái?"},{"who":"A","text":"{Xung} chỉ biết bà ấy khen ngợi nhà kia hết lời. Còn ai đứng sau thì chưa lộ."},{"who":"me","text":"Bà mối chỉ là người đi trước, người sai bà mới là gốc. Phải theo dấu từ người ấy."}]}},
{"id":"nr:off_thong_7#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Nhà gái mở cửa, hương trà thơm thoảng ra tận sân; bà mối ngồi bên án, miệng nói không ngớt về nhà khác."},{"who":"A","text":"Bà mối nhà chen ngang là người làng của nhà gái. Nếu nhà gái nghe một lời từ người quen của {goi}, bà mối hết đất nói."},{"who":"me","text":"Người làng nói với người làng thì dễ nghe. Một lời của người quen sẽ nặng hơn lời bà mối."},{"who":"A","text":"Xin {goi} nhờ người nhà sang thăm nhà gái một buổi, giúp {xung}."},{"who":"me","text":"Đi thăm một buổi, nói chuyện thân tình là xong. Không cần phô trương."}]}},
{"id":"nr:off_thong_8#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Tờ thiếp báo tin hôn sự của hai nhà quan lớn nằm trên án, mực son chưa ráo mà người trong triều đã bắt đầu bàn tán."},{"who":"A","text":"Hai nhà quan lớn kết thông gia, Hoàng thượng ắt phải hỏi. Nếu người nghe ai đó nói đây là chuyện hai trẻ hợp nhau, không phải chuyện phe, người sẽ chuẩn dễ hơn."},{"who":"me","text":"Thông gia giữa hai nhà lớn, ai cũng nghĩ đến phe phái. {Goi} muốn người nhìn bằng con mắt khác."},{"who":"A","text":"{Xung} chỉ xin {goi} một lời ấy: hai trẻ hợp nhau, vậy thôi."},{"who":"me","text":"Một lời nhẹ mà gỡ được cả nghi kỵ. Đáng để nói."}]}},
{"id":"nr:off_thong_8#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Cây trâm bạc làm lễ ra mắt được đặt trên khay lụa trước mặt vị quan, ánh bạc phản chiếu lên khuôn mặt đầy lo lắng."},{"who":"A","text":"Hoàng thượng hay hỏi ý Thái hậu về việc thông gia của các nhà quan lớn. Nếu Thái hậu nói trước một câu mối ấy hợp, người sẽ chuẩn."},{"who":"me","text":"Thái hậu nói trước thì Hoàng thượng chỉ cần gật đầu. Đúng là con đường ngắn nhất."},{"who":"A","text":"Xin {goi} thưa giúp {xung} khi hầu Thái hậu."},{"who":"me","text":"Thưa một câu nhẹ, mà quyết cả một mối duyên. {Xung} sẽ cân nhắc lời cho vừa."}]}},
{"id":"nr:off_thong_9#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Chợ kinh sáng sớm ồn ã, một người hầu phủ {B} đứng giữa đám đông thì thầm điều gì đó, ánh mắt liếc về phía ngõ nhà gái."},{"who":"A","text":"Người của {B} đồn khắp kinh rằng nhà gái có người mắc bệnh lao, để phá đám cưới."},{"who":"me","text":"Lời đồn ác độc như vậy chắc chắn không phải tự nhiên nảy ra. Nó đi ra từ đâu?"},{"who":"A","text":"Từ một cung trong hậu cung. Còn cung nào, {xung} chưa tìm ra. Xin {goi} dò giúp {xung} cung ấy."},{"who":"me","text":"Đi từ cung ra chợ, đi từ chợ về nhà gái. Lần ngược lại thì sẽ ra."}]}},
{"id":"nr:off_thong_9#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Trước cổng nhà gái, tấm biển đề tên họ được lau sạch bóng, người nhà đứng nhìn nhau như muốn chứng tỏ gia đình không có bệnh."},{"who":"A","text":"Nhà gái muốn mời thái y trong cung đến bắt mạch cả nhà, để lời đồn bệnh lao tự tan. Thái y không ra cung khi chưa có lệnh."},{"who":"me","text":"Muốn chặn lời đồn phải có bằng chứng thật. Một thái y quen mặt thì ai cũng tin."},{"who":"A","text":"Xin {goi} xin giúp {xung} một thái y quen ra một buổi. Chỉ cần bắt mạch, lời đồn tự lặng."},{"who":"me","text":"Bắt mạch cho cả nhà trước mắt mọi người, đó là cách chắc nhất. Đáng để xin."}]}},
{"id":"nr:off_thong_10#0","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Phòng tân hôn đã treo đủ lụa đỏ, trên bàn trống một chỗ chưa có quà từ cung, người nhà chú rể lặng lẽ dọn dẹp lại."},{"who":"A","text":"Ngày cưới, nếu trong cung có món quà mừng, cả kinh thành sẽ coi trọng mối thông gia. {Xung} không dám xin Hoàng thượng."},{"who":"me","text":"Một món quà đứng tên một cung cũng đủ gây tiếng vang. {Goi} chỉ xin món nhỏ."},{"who":"A","text":"Chỉ xin {goi} gửi một món quà nhỏ, đứng tên cung {goi}."},{"who":"me","text":"Quà không cần lớn, chỉ cần đúng ngày. Tặng gì cho xứng, {xung} còn phải nghĩ."}]}},
{"id":"nr:off_thong_10#1","dlg":{"L":"A","R":"me","lines":[{"who":"nar","text":"Một dải lụa đỏ viết chữ Hỷ còn để trắng giữa gian chính; hai nhà đứng chờ, ánh mắt đều hướng ra cửa như đợi ai tới."},{"who":"A","text":"Ngày cưới mà có một chữ của Hoàng thượng ban thì hai nhà mới thật yên. {Xung} không dám xin."},{"who":"me","text":"Một chữ vua ban hơn cả trăm lời chúc. Chỉ cần khéo nói đúng lúc."},{"who":"A","text":"Xin {goi} khi Hoàng thượng vui, khéo nói ngày ấy là ngày lành."},{"who":"me","text":"Nói một câu cho người mỉm cười, còn lại để ý trời. Việc này không khó."}]}}
];
